[84001] = { ["id"] = 84001, ["name"] = "Cart Blanche", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "Our mining team is making great progress. All our carts have already been loaded with ore samples and sent back to camp. There's a problem though... None of the carts made it to camp due to trouble on the tracks! Please repair the tracks and collect any lost ore if you can so we can get those samples to camp.", ["objectivesText"] = "Repair 2 Mine Tracks, clear 5 Crashed Mine Carts, and collect 12 Ore Samples . Progress: Are the mine carts getting through now?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 226853 }, ["rewardCurrencies"] = { { ["id"] = 3090, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 232730, ["x"] = 0.485, ["y"] = 0.529 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 232730, ["x"] = 0.485, ["y"] = 0.529 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.529 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 84725 }, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2127, ["db2PoiUiMapID"] = 2369 },
