[84140] = { ["id"] = 84140, ["name"] = "Can-Do Caddy", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84140, 84141, 84142 }, ["description"] = "So, my \"company\" was subcontracted to provide services for the golf course here. Only, it turns out the materials we used in our patented, explosive-proof grass has drawn a swarm of coursehares . Which is inconvenient 'cause they're the only type of rodents that can eat the grass. I need a can-do caddy I can sub-subcontract out the elimination of this threat to my business. So tell me, can you?", ["objectivesText"] = "Eliminate 9 Coursehares .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228158, ["x"] = 0.652, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228158, ["x"] = 0.652, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83176 }, ["questLines"] = { { ["id"] = 5662, ["name"] = "Fore!", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[84141] = { ["id"] = 84141, ["name"] = "Scam Cans", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84140, 84141, 84142 }, ["description"] = "Look, I run a clean business here... when I'm paid to. But, I've gotta swathe of cheatin' no gooders tryin' to plant scam cans in the holes. The things cause the balls of cheaters to get drawn into 'em, cheapenin' the game. Can't have that. Get out there, find the scam cans , and get them gone.", ["objectivesText"] = "Extract 4 Scam Cans . Progress: Yeah, gotta watch out for them explodin' balls. They make for a great sport but hazard pay is a real thing.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228158, ["x"] = 0.652, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228158, ["x"] = 0.652, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83176 }, ["questLines"] = { { ["id"] = 5662, ["name"] = "Fore!", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[84142] = { ["id"] = 84142, ["name"] = "The Hole Deal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84140, 84141, 84142 }, ["description"] = "Okay, well now that's settled, how about you get a free go, eh? Here at... < Ripsnoodle pauses to look at notes he digs out of his pocket.> Emerald Hills Golf Course, we pride ourselves on everyone gettin' a hole-in-one! Especially since our boomballs explode after the first swing. So make 'em count. Go take a few balls out and give the course a whack.", ["objectivesText"] = "Sink 4 Boomballs into the four golf holes. Progress: The other day I saw this warlock trying to have their imp nudge a ball into the hole. Man that imp was NOT happy when it got resummoned after the explosion. The things people sell their soul over...", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 232742, 232749, 232751, 232760 }, ["rewardCurrencies"] = { { ["id"] = 3118, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228158, ["x"] = 0.652, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228158, ["x"] = 0.652, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 84140, 84141 }, ["questLines"] = { { ["id"] = 5662, ["name"] = "Fore!", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[84143] = { ["id"] = 84143, ["name"] = "Lost and Busy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84143 }, ["series"] = { 84144, 84363, 84393 }, ["description"] = "Thank the Light, an adventurer! Please, you must help me. Event coordination is a harrowing profession in the best of circumstances. I am drowning in crises! There was a small tuskarr child in need of assistance, but I have my hands full here. I last saw her headed to Leeroy's Chicken.", ["objectivesText"] = "Find Maru near Leeroy's Chicken.", ["rewardGold"] = 31500, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226684, ["x"] = 0.632, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 4063 }, ["db2QuestSortName"] = "Nightborne" },
[84144] = { ["id"] = 84144, ["name"] = "Tat Big Meanie", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84144 }, ["series"] = { 84143, 84363, 84393 }, ["description"] = "Tat big meanie stole my brovver's sleufing fingy! We need to find who it was and make them give it back! I fink it was lost past da potty over there. Here, my unco has this old bird idol that can look for clues! You can borrow it 'cause you look helpy.", ["objectivesText"] = "Use the Idol of Ohn'ahra to search for clues near the outhouses. Progress: Did you find any clues? We gotta find tat meanie!", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 207730, 225252, 227363, 227364, 227443 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 5 }, { ["id"] = 3100, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226684, ["x"] = 0.632, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226684, ["x"] = 0.632, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 84143 }, ["db2LabelIDs"] = { 4063 }, ["db2QuestSortName"] = "Nightborne" },
[84214] = { ["id"] = 84214, ["name"] = "The Job", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84214, 84215, 84216, 84217, 84218 }, ["series"] = { 84215 }, ["description"] = "Want money? Good at smashing stuff? Not afraid of a little morally grey wealth acquisition? Well then Entrepreneur Inc. has a gig for you! Come on down to our headquarters in the Heap and speak with Skedgit Cinderbangs for more details.", ["objectivesText"] = "Speak with Skedgit Cinderbangs in The Heap.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 25784, 25785, 32865, 32866, 32867, 32868, 33457, 33458, 33459, 33460, 33461, 33462, 35844, 35846, 35848, 59044, 59045, 59046, 59096, 59097, 59098, 90347, 90348, 90349, 90350, 90351, 90352, 90353, 90354, 90355, 118075, 118076, 118077, 118078, 131452, 131512, 208128, 208129, 225947, 233289, 233298 }, ["starts"] = { { ["x"] = 0.427, ["y"] = 0.528, ["mapID"] = 2346, ["objectID"] = 456747 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228286, ["x"] = 0.43, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83176 }, ["nextQuests"] = { 84215 }, ["questLines"] = { { ["id"] = 5663, ["name"] = "The Highst", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346, ["db2QuestHubAreaPoiID"] = 8189 },
[84215] = { ["id"] = 84215, ["name"] = "The Crew", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84214, 84215, 84216, 84217, 84218 }, ["series"] = { 84214 }, ["description"] = "You are hired! Okay, this heist I got planned is gonna make us a lot of money, but requires a crew and a bunch of planning. I'll take care of the planning, you get the crew. We need Goldmine. Outside of Venture Co., he's one of the fastest drivers out there. Because he's outside of Venture Co., he can't be traced back to me. We also need a face that no bruiser can say no to. We need Handsome Crog . Oh, and I need my cousin Ripsnoodle . He's not the best mage, but he's family... and my boss.", ["objectivesText"] = "Gather the crew. Progress: Okay, I know some of them may not come willingly. So, we got to tell them we're gonna get lotsa money outta this heist. Like... lots of money. Because there is. Lotsa of money. I swear.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 59086, 59087, 59088, 59089, 61484, 61495, 61500, 128658, 131445, 155052, 155058, 155063, 155066, 155071, 155073, 155077, 155080, 204378 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228286, ["x"] = 0.43, ["y"] = 0.824 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228286, ["x"] = 0.43, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 84214 }, ["questLines"] = { { ["id"] = 5663, ["name"] = "The Highst", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[84216] = { ["id"] = 84216, ["name"] = "The Play", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84214, 84215, 84216, 84217, 84218 }, ["description"] = "I'm gonna go over the details of the plan. However, here is the too-long-didn't-listen version: We meet in front of the Airship Station in Bilgewater's district. Handsome Crog helps get us past the guards to the airship supply balloon there. We steal that balloon and use it to board the airship over the arena where the safe with all that loot is. Ready?", ["objectivesText"] = "Steal an Airship Supply Balloon.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 56649, 56650, 56651, 56664, 56665, 56666, 131302, 131534, 156958, 166846, 166970, 166971, 189544, 190189, 190343, 190344, 190345, 190348, 190349, 190351, 190352, 190353, 190355, 190356, 190358, 190359, 190360, 190363, 190364, 190366, 190367, 190368, 190371, 190372, 190605, 190633, 190634, 192422, 192423, 192424, 192428, 192430, 192449, 192450, 192451, 235502, 246697 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228286, ["x"] = 0.43, ["y"] = 0.824 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228333, ["x"] = 0.51, ["y"] = 0.37 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 84215 }, ["questLines"] = { { ["id"] = 5663, ["name"] = "The Highst", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[84217] = { ["id"] = 84217, ["name"] = "The Highst", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84214, 84215, 84216, 84217, 84218 }, ["description"] = "Okay, we got this. Me, you, and loudmouth here are going to hop this service balloon and get up to that airship over the arena. That is where they are keeping the loot. Once we get aboard, fighting space will be tight. I got us some uniforms so we'll look like people who work there but try not to start anything. Ready?", ["objectivesText"] = "Reach the Safe.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228333, ["x"] = 0.51, ["y"] = 0.37 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228341, ["x"] = 0.615, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 84215 }, ["questLines"] = { { ["id"] = 5663, ["name"] = "The Highst", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[84218] = { ["id"] = 84218, ["name"] = "The Getaway", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84214, 84215, 84216, 84217, 84218 }, ["description"] = "Okay... um... I \"may\" have lied about the loot. You can be mad at me all you want but we need to get away now. Get in the car! We have to gun it!", ["objectivesText"] = "Escape in the Getaway Car.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 232734, 232735 }, ["rewardChoices"] = { 232734, 232735 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 25 }, { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3118, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228341, ["x"] = 0.615, ["y"] = 0.324 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228286, ["x"] = 0.43, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 84217 }, ["questLines"] = { { ["id"] = 5663, ["name"] = "The Highst", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[84220] = { ["id"] = 84220, ["name"] = "Passage to the Ringing Deeps", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 84220 }, ["starts"] = { { ["npcID"] = 228304, ["x"] = 0.376, ["y"] = 0.726, ["mapID"] = 2248 } }, ["ends"] = { { ["npcID"] = 228304, ["x"] = 0.376, ["y"] = 0.726, ["mapID"] = 2248 } }, ["coords"] = { ["x"] = 0.376, ["y"] = 0.726, ["source"] = "quest_giver", ["mapID"] = 2248 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78546 } },
[84221] = { ["id"] = 84221, ["name"] = "Paperwork Makes the Mine Go Under", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "Name is Marty. Marty Zoomcart . Marty Zoomcart , public defender, and agent assigned to the Gallagio's case for State of Undermine . What a mouthful... Just call me Marty. So the deed holder, Rosebud Gallywix, is dead? And no one knows whodunnit. And some nobody, you, has the deed? Frankly, it's a common occurrence. Plenty of precedent. Just no time... Here's the skinny: if we don't attach some new legal owners to the deed, it's getting put up on the auction house like a pair of decade-old pants.", ["objectivesText"] = "Establish a plan to keep the Gallagio out of the auction house. Progress: I don't usually like to get wrapped up in big business. But the Gallagio, you know, it's an important establishment for the people of Undermine .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232764, 232765 }, ["rewardChoices"] = { 232764, 232765 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 25 }, { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3118, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228369, ["x"] = 0.388667, ["y"] = 0.332667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228369, ["x"] = 0.388667, ["y"] = 0.332667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.388667, ["y"] = 0.332667 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83569 }, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[84222] = { ["id"] = 84222, ["name"] = "Secure the Perimeter", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "A veritable menagerie of dangerous creatures have attacked us since we set up our encampment. While my troops can manage most threats, some of the more powerful creatures may require your expertise. Scour the island and eliminate any powerful entities that might jeopardize our operations here.", ["objectivesText"] = "Eliminate 2 rare enemies on the Siren Isle . Progress: How goes the hunt? Is our encampment safe for now?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3090, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 227796, ["x"] = 0.695, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 227796, ["x"] = 0.695, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 84725 }, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 2127, ["db2PoiUiMapID"] = 2369 },
[84223] = { ["id"] = 84223, ["name"] = "Survivor's Guilt", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83031, 83499, 83502, 83539, 83553, 83554, 83555, 83556, 83641, 83643, 84223 }, ["description"] = "We have all suffered from Xal'atath's deeds, some more than others. I am glad to be alive, even if I now feel as old as I look. <Khadgar tries to laugh but coughs instead. He waves off your worry.> Don't worry about me. But Aethas... I've heard he went back to Dalaran's crash site. And that he hasn't slept or eaten since we arrived. He wants my help, but I haven't been able to bring myself to visit the crash site. Will you go in my stead?", ["objectivesText"] = "Find Aethas Sunreaver in the Tranquil Strand.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 227436, ["x"] = 0.315, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 225355, ["x"] = 0.295, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.315, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 83503, 84701 }, ["questLines"] = { { ["id"] = 5664, ["name"] = "Arcane Desolation", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5664, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[84224] = { ["id"] = 84224, ["name"] = "To Delves!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 81595, 81596, 83500, 84224 }, ["description"] = "There's more tae do in delves, <name>! Meet me in Dornogal. There's loads to discuss!", ["objectivesText"] = "Meet Brann Bronzebeard within Dornogal.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 224784, 229129, 229354, 229371, 232049, 232371, 235502, 239118, 244865, 250116, 254677, 268490 }, ["starts"] = { { ["x"] = 0.474, ["y"] = 0.444, ["mapID"] = 2339 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5633, ["name"] = "Delves - Season 1", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[84225] = { ["id"] = 84225, ["name"] = "Eggstinction", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "We should really get outta here, but... Do you see those eggs over there? If those monsters hatch them all, this place will be swarming with crabs when the storm clears. Ugh, there's just too many to destroy by hand. We're gonna need some help! Suzie's got a lot of helpful items back at the camp... or maybe my broiler will work? I dunno, champ. Grab somethin' to get rid of those eggs!", ["objectivesText"] = "Eliminate 12 Egg Tenders and 12 Spawning Clutches. Progress: Did you get rid of the eggs?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3090, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 231937, ["x"] = 0.635, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 227814, ["x"] = 0.691, ["y"] = 0.475 }, { ["mapID"] = 2369, ["npcID"] = 231937, ["x"] = 0.635, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 84725 }, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 2127, ["db2PoiUiMapID"] = 2369 },
[84236] = { ["id"] = 84236, ["name"] = "The Great Detective", ["level"] = 10, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84236 }, ["series"] = { 84237 }, ["description"] = "Adventurer, thank the Light you are here. We have a missing guest. There was a detective who was investigating the case, but I have not heard back. Could you please check in with him?", ["objectivesText"] = "Speak with Detective Jones.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226796, ["x"] = 0.6265, ["y"] = 0.5125 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 83831 }, ["db2LabelIDs"] = { 4063 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71, ["db2QuestSortName"] = "Nightborne" },
[84237] = { ["id"] = 84237, ["name"] = "The \"Great\" Detective", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84237 }, ["series"] = { 84236 }, ["description"] = "The missing guest? Yes, some Herrkrop fellow. Not to worry, I've already solved the case. He probably just got lost. Relax, <class>. Enjoy the festivities! Our missing guest will show up soon enough. If you don't believe me, go... I don't know... solve it yourself. Interrogate someone or other.", ["objectivesText"] = "Solve the mystery of Herrkrop's disappearance. Progress: Have you any luck in finding our missing guest?", ["rewardGold"] = 312800, ["rewardXP"] = 1415, ["rewardItems"] = { 206696, 207730, 208092, 227551 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 5 }, { ["id"] = 3100, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226796, ["x"] = 0.6265, ["y"] = 0.5125 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232405, ["x"] = 0.63, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.6265, ["y"] = 0.5125 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 84236 }, ["db2LabelIDs"] = { 4061, 4063 }, ["db2QuestSortName"] = "Nightborne" },
[84241] = { ["id"] = 84241, ["name"] = "Shoreline Stand", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "This storm will not drive me from my sacred duty. This cave must be defended at all costs! This new crystal may still be shrouded in mystery, but we will never understand its secrets or its relation to Beledar if we allow it to fall into the grasp of these wretches who crawl from the ocean's abyss. Stand with me, <name>. Together, we shall defend this shoreline to our final breath.", ["objectivesText"] = "Eliminate 15 Brinebound Wraith and Tide-Champion Korval . Progress: Is the crystal safe?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3090, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 232297, ["x"] = 0.4364, ["y"] = 0.2404 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 232297, ["x"] = 0.4364, ["y"] = 0.2404 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.4364, ["y"] = 0.2404 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 84725 }, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2127, ["db2PoiUiMapID"] = 2369 },
[84242] = { ["id"] = 84242, ["name"] = "Diving into the Heaps", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "Our first marks are the dynamite duo of gaming: Kayjay and Fantastic Davey. Been a few years since I was hustling macaroons in the electro-billiards halls. I wasn't bad, but those two cleaned the house out whenever they showed. They don't just win games either. They make them! Real artist-types, you know? But with great gaming, comes great debt. And it's usually to Venture Co. Meet me at the Heaps. If Rosebud's death means they're outta work, I'd bet money Venture scooped 'em up again.", ["objectivesText"] = "Meet Marty Zoomcart at Venturewood in The Heaps.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228369, ["x"] = 0.388667, ["y"] = 0.332667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226277, ["x"] = 0.5145, ["y"] = 0.714 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.388667, ["y"] = 0.332667 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 84221 }, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[84244] = { ["id"] = 84244, ["name"] = "Blackwater Beach Blast", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "You've done good work with Jojo. Real good. I'll stick around, seal the deal, then meet you over at Blackwater Marina for the final signature. Had my radio turned to WGOB 101.1 FM while dropping off the fifteen landfill-scented individuals earlier. DJ B. B. Rev announced there would be a battle of the bands at the marina today. Wouldn't you know it, Rosebud's Chief Executive of Entertainment is playing! The band you're looking for is the Cellar Gnomes.", ["objectivesText"] = "Meet Marty Zoomcart at Blackwater Marina.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231812, ["x"] = 0.368, ["y"] = 0.878 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226894, ["x"] = 0.565, ["y"] = 0.3975 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.878 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83542 }, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[84246] = { ["id"] = 84246, ["name"] = "Witnessing Brilliance", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 84246 }, ["description"] = "The time has finally come and the moment could not be more exhilarating. It's time to get to work. Join me outside, let's observe the fruits of our labor.", ["objectivesText"] = "Witness Siesbarg's Ascension.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 218171, ["x"] = 0.451333, ["y"] = 0.136 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 218171, ["x"] = 0.451333, ["y"] = 0.136 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.451333, ["y"] = 0.136 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 83721 } },
[84248] = { ["id"] = 84248, ["name"] = "A Ritual of Runes", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "I went to investigate a cave nearby, and I came across some Bloodwake vrykul that were conjuring something... something that activated my threat mitigation protocols. I calculate that if they complete their ritual, it would be disastrous for the island. <name>, please assess the cave and stop their ritual before something terrible occurs!", ["objectivesText"] = "Destroy 5 Summoning Runes and eliminate Inhyldir the Cursed . Progress: Did you disrupt the ritual?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 3090, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 233139, ["x"] = 0.515, ["y"] = 0.483 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 233139, ["x"] = 0.515, ["y"] = 0.483 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.483 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 84725 }, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2127, ["db2PoiUiMapID"] = 2369 },
[84249] = { ["id"] = 84249, ["name"] = "A Vat in the Pan", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "Our next mark is Jojo Gobdre, in the Vatworks. She was a big time chef. The real deal. And running cuisine at the Gallagio woulda meant franchise opportunities. Is there a reason she'd want Rosebud dead? Either way, we need a lead on where she's cooking these days. Luckily, I got an ol' pal who should have info. He's a little bit of a big shot for Steamwheedle, but we should be able to find him on his rooftop hideaway. We'll meet there. Come hungry.", ["objectivesText"] = "Meet Marty Zoomcart in The Vatworks.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 232823, ["x"] = 0.5645, ["y"] = 0.655 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226932, ["x"] = 0.328, ["y"] = 0.802 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.5645, ["y"] = 0.655 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83527, 83528 }, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[84252] = { ["id"] = 84252, ["name"] = "Peak Precision", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "Flying? It ain't for me. Sally Boltwrench wanted me to activate a bunch of survey machines to monitor the wind currents, but it's too rough up there and the heights give me the heebie jeebies. An' I get sick every time I try. Use the Go-Pack to activate the machines for me. I'll owe ya one!", ["objectivesText"] = "Activate 6 Survey Machines using the Experimental Go-Pack to help reach them. Progress: Did you switch those machines on?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 230728, 230795 }, ["rewardCurrencies"] = { { ["id"] = 3090, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 232255, ["x"] = 0.422667, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 227814, ["x"] = 0.691, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.422667, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 84725 }, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2127, ["db2PoiUiMapID"] = 2369 },
[84254] = { ["id"] = 84254, ["name"] = "Meet and Greet", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84254 }, ["series"] = { 82672 }, ["description"] = "Greetings, salutations, and happy anniversary! I am Yllana , the conductor of this symphony of celebration. I trust you are itching for fun and entertainment? Well do not fret, for there is much to do and plenty of time to do it. I've marked your map with the locations of my gleeful greeters who will tell you all about the activities in store for you. Once you've talked to them, return to me for a gift that will maximize your merriment. After all, what's a celebration without presents?", ["objectivesText"] = "Talk to the activity greeters. Progress: It's easy to get distracted. Have you spoken with the activity greeters I told you about?", ["rewardGold"] = 29200, ["rewardXP"] = 175, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 5 }, { ["id"] = 3100, ["amount"] = 3 } }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 223877, ["x"] = 0.628, ["y"] = 0.506 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 223877, ["x"] = 0.628, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 4063 }, ["db2QuestSortName"] = "Nightborne" },
[84260] = { ["id"] = 84260, ["name"] = "Crafting to Order", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84260 }, ["description"] = "Hello, greetings, and welcome to the Crafter's Enclave. According to Market Reeve Vokgret, we are now operating with the Artisan's Consortium to accommodate the needs of both the earthen and the outlanders. Please speak to Ardran or Pordaz to view and place crafting orders.", ["objectivesText"] = "Talk to Ardran in the Crafter's Enclave. Progress: Have you talked to Ardran?", ["rewardGold"] = 30900, ["rewardXP"] = 1155, ["rewardItems"] = { 210796, 210799, 210802, 210805, 210808, 210814, 210930, 210933, 210936, 212664, 212667, 213611, 218336, 218337, 219150, 219946, 219949, 224828, 227890, 228338, 228916, 228917, 228919, 228931, 228932, 228933 }, ["rewardChoices"] = { 228916, 228917, 228933 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219108, ["x"] = 0.592, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219108, ["x"] = 0.592, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard" },
[84274] = { ["id"] = 84274, ["name"] = "Crafting Orders: Blacksmithing", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84274 }, ["description"] = "So you are a blacksmith? You should have mentioned that earlier! Let me send you to Darean , a blacksmith of great renown, who has her shop within the Forgegrounds. I will mark it on your map. Darean has her very own Blacksmith's table", ["objectivesText"] = "Find Darean in the Forgegrounds and use her blacksmith's table . Progress: Please make use of my blacksmith's table if you need it.", ["rewardGold"] = 29200, ["rewardXP"] = 1155, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219108, ["x"] = 0.592, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223644, ["x"] = 0.492, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 84260 } },
[84279] = { ["id"] = 84279, ["name"] = "Crafting Orders: Jewelcrafting", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84279 }, ["description"] = "So you are a jewelcrafter? You should have mentioned that earlier! Let me send you to Makir , a jewelcrafter of great renown, who has a shop on the southern part of the Forgegrounds. I will mark it on your map. Makir has his very own jeweler's bench", ["objectivesText"] = "Find Makir in the Forgegrounds and use his jeweler's bench . Progress: Please make use of my jeweler's bench if you need it.", ["rewardGold"] = 29200, ["rewardXP"] = 1155, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219108, ["x"] = 0.592, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219087, ["x"] = 0.495, ["y"] = 0.71 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 84260 } },
[84280] = { ["id"] = 84280, ["name"] = "Crafting Orders: Leatherworking", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84280 }, ["description"] = "So you are a leatherworker? You should have mentioned that earlier! Let me send you to Marbb , a leatherworker of great renown, who has her shop on the eastern side of the Forgegrounds. I will mark it on your map. Marbb", ["objectivesText"] = "Find Marbb in the Forgegrounds and use her leatherworker's bench. Progress: Welcome! Please make use of my bench if you need it.", ["rewardGold"] = 30900, ["rewardXP"] = 1155, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219108, ["x"] = 0.592, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219080, ["x"] = 0.545, ["y"] = 0.585 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 84260 } },
[84281] = { ["id"] = 84281, ["name"] = "Crafting Orders: Tailoring", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84281 }, ["description"] = "So you are a tailor? You should have mentioned that earlier! Let me send you to Kotag , a tailor of great renown, who has their shop on the eastern side of the Forgegrounds. I will mark it on your map. Kotag", ["objectivesText"] = "Find Kotag in the Forgegrounds and use their tailoring table. Progress: Please! Take a \"measure\" of my table.", ["rewardGold"] = 29200, ["rewardXP"] = 1155, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219108, ["x"] = 0.592, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219094, ["x"] = 0.547, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 84260 } },
[84285] = { ["id"] = 84285, ["name"] = "Crafting Orders: Engineering", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84285 }, ["objectivesText"] = "Find Arhdas in the Forgegrounds and use his engineering table. Progress: My tools and bench are at your disposal.", ["rewardGold"] = 29200, ["rewardXP"] = 1155, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219108, ["x"] = 0.592, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219099, ["x"] = 0.49, ["y"] = 0.56 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 84260 } },
[84286] = { ["id"] = 84286, ["name"] = "The Finer Things", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14980, ["storyline"] = { 84286 }, ["objectivesText"] = "Progress: Fetch me the insignias from our Queen's guests and comrades. These have many uses within the city, and in exchange I will make you even deadlier to our foes within.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3056, ["amount"] = 75 } }, ["starts"] = { { ["npcID"] = 225184, ["zoneID"] = 14980 } }, ["ends"] = { { ["npcID"] = 225184, ["zoneID"] = 14980 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14980 } }, ["questGiverID"] = 225184, ["questType"] = "standard" },
[84287] = { ["id"] = 84287, ["name"] = "Crafting Orders: Inscription", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84287 }, ["description"] = "So you are an inscriber? I know one of the best inscribers in Dornogal . You should look for Brrigan on the southern edge of the Forgegrounds. Brrigan", ["objectivesText"] = "Find Brrigan in the Forgegrounds and use her drafting table. Progress: You are more than welcome to use my drafting table. Inscription is a rather new technique for us. There is much we can learn from your work.", ["rewardGold"] = 30900, ["rewardXP"] = 1155, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219108, ["x"] = 0.592, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219090, ["x"] = 0.486, ["y"] = 0.71 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 84260 } },
[84288] = { ["id"] = 84288, ["name"] = "Crafting Orders: Alchemy", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84288 }, ["description"] = "So you are an alchemist? I see. You should visit Tarig . She's an alchemist like you. Tarig", ["objectivesText"] = "Find Tarig in the Forgegrounds and use her alchemist's lab bench . Progress: I would never miss an opportunity to share my expertise--or my lab bench!", ["rewardGold"] = 30900, ["rewardXP"] = 1155, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219108, ["x"] = 0.592, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219092, ["x"] = 0.472, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 84260 } },
[84296] = { ["id"] = 84296, ["name"] = "The Trail's Gone Cold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84296 }, ["series"] = { 84278 }, ["description"] = "I've tracked the scent of Scrapes as far as here, but this cold air smothers our lead. I found a couple scraps of notes. Nothing useful yet, but he seems to have left a paper trail in his hurry. Look for clues that may indicate where our villain's lair is hidden. I will mark what I found on your map. Take Spirit's whistle . Call upon us when you are in need of assistance.", ["objectivesText"] = "Find Scrapes' hideout. Progress: How goes the hunt?", ["rewardGold"] = 315900, ["rewardXP"] = 1415, ["rewardItems"] = { 208092, 227664, 227665, 227671, 227672 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 5 }, { ["id"] = 3100, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226952, ["x"] = 0.61, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232405, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232406, ["x"] = 0.63, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.61, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 84278 }, ["db2LabelIDs"] = { 4061, 4063 }, ["db2QuestSortName"] = "Nightborne" },
[84298] = { ["id"] = 84298, ["name"] = "HELP WANTED: Kaja'Curiosity", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 862, ["storyline"] = { 84298, 84300, 84301, 84302, 84303, 84304, 84439 }, ["description"] = "<This listing is new, posted by the Bilgewater Cartel.> Do you like kaja'mite? Are ya ready to get your intellectual fix under some tropical sun? Want to develop cutting-edge tools that will only explode when we tell them to? Hop on a rocket drill to the Kaja'Coast! No prior experience required. Combat capabilities extremely welcome. Contractors are liable for their own safety. Compensation and working hours negotiable on-site. Please seek Jazz Mokkitz on the Kaja'Coast for more information.", ["objectivesText"] = "Speak with Jazz Mokkitz on the Kaja'Coast. Progress: Research takes guts, sure, but I would like to keep mine intact.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["x"] = 0.427, ["y"] = 0.528, ["mapID"] = 2346, ["objectID"] = 456747 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 228566, ["x"] = 0.216, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.216, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83130 }, ["questLines"] = { { ["id"] = 5669, ["name"] = "Kaja'Curiosity", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["db2QuestHubAreaPoiID"] = 8189, ["startItems"] = { 227702 } },
[84299] = { ["id"] = 84299, ["name"] = "Pirate Plunder", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "We got a good thing here, but these pirates are bad for business! They're stealin' all the special gems, an' they even made off with our Kaja'Cola stash ! Get rid of these pirate losers and recover any of the stuff they took from us!", ["objectivesText"] = "Bilge Rat forces disrupted Progress: Ya better be tellin' me them pirates is all gone!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 227453, 227670 }, ["rewardCurrencies"] = { { ["id"] = 3090, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 227818, ["x"] = 0.694, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 227818, ["x"] = 0.694, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 84725 }, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 2127, ["db2PoiUiMapID"] = 2369 },
[84300] = { ["id"] = 84300, ["name"] = "Refine, Repair, Repeat", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 862, ["storyline"] = { 84298, 84300, 84301, 84302, 84303, 84304, 84439 }, ["description"] = "<Jazz holds up a well-polished crystal of kaja'mite.> Most materials aren't ready to use straight outta the ground--kaja'mite included. I've got a few refined crystals to tinker with, but I'll need more. I rigged up some refiners on the slope, but halfway through the cycle elementals started beatin' on 'em pretty hard. Could you see if you could get 'em goin' again? You look like you could handle those angry rocks, and my wife likes it when I come home without injuries.", ["objectivesText"] = "Repair 6 broken Kaja'mite Refiners on the Kaja Coast.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 228566, ["x"] = 0.216, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 228566, ["x"] = 0.216, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.216, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["sourceQuests"] = { 84298 }, ["questLines"] = { { ["id"] = 5669, ["name"] = "Kaja'Curiosity", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862 },
[84301] = { ["id"] = 84301, ["name"] = "Mineral Madness", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 862, ["storyline"] = { 84298, 84300, 84301, 84302, 84303, 84304, 84439 }, ["description"] = "With all these elementals wreakin' havoc, it's impossible to work out here! How are we supposed to gather raw material when they're swingin' at us with the stuff? <Jazz stops, eyes lighting up.> <name>, those elementals ARE our raw material. Smashin' 'em up is our best bet--though, you'll have to do that for me. Now, keep it movin'! Time is money, and I ain't one to waste perfectly good research funding.", ["objectivesText"] = "Clear out aggressive Kaja'mite elementals and collect 12 Raw Kaja'mite Chunks from them. Progress: Who knew this place was so elementally active? No wonder the Darkfuse needed all hands on deck out here.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 227708 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 228566, ["x"] = 0.216, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 228566, ["x"] = 0.216, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.216, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["sourceQuests"] = { 84298 }, ["questLines"] = { { ["id"] = 5669, ["name"] = "Kaja'Curiosity", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862 },
[84302] = { ["id"] = 84302, ["name"] = "Creative Iteration", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 862, ["storyline"] = { 84298, 84300, 84301, 84302, 84303, 84304, 84439 }, ["description"] = "Alright, <name>, time for this to get serious. You got the crystals, and I've got our parts to work with! Kaja'mite is good for containin' volatile energy. I think we can do better than Darkfuse weaponry, but first, we need a proof of concept. I've got this old, glitchy, junk shrink ray. The kaja'mite should stabilize it. If it does, we've got a potential breakthrough! I need an extra set of hands to tinker on this thing. Just follow my instructions and you'll stay in one piece. Probably.", ["objectivesText"] = "Help Jazz tinker with his shrink ray and kaja'mite.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 228566, ["x"] = 0.216, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 228566, ["x"] = 0.216, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.216, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["sourceQuests"] = { 84300, 84301 }, ["questLines"] = { { ["id"] = 5669, ["name"] = "Kaja'Curiosity", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862 },
[84303] = { ["id"] = 84303, ["name"] = "Experimental Application", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 862, ["storyline"] = { 84298, 84300, 84301, 84302, 84303, 84304, 84439 }, ["description"] = "<Jazz shoves the shrink ray into your hands.> Only thing left to do is test the prototype, <name>. Try using it on the elementals! If it can work on those, it'll work on anything, probably. Don't expect the effects to last, though. It's only a first iteration! And keep contained to the mines. Just in case we need to bury any problems. Oh, don't give me that look. I built this originally to make spiders easier for my wife to handle. I promise, there's at least ONE functional failsafe.", ["objectivesText"] = "Test the Kaja'Containment Device on 8 Kaja'mite Crawlers in the Lucky Break Mines.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 228948 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 228566, ["x"] = 0.216, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 228566, ["x"] = 0.216, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.216, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["sourceQuests"] = { 84300 }, ["questLines"] = { { ["id"] = 5669, ["name"] = "Kaja'Curiosity", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862 },
[84304] = { ["id"] = 84304, ["name"] = "A Gem-Splitting Headache", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 862, ["storyline"] = { 84298, 84300, 84301, 84302, 84303, 84304, 84439 }, ["description"] = "Hey, <name>, I'm not usually one for revenge, but I've got an idea. That big guy who tossed us around ran up this way. I'll bet you good money it's in the mines somewhere, and I bet we could get a giant sample off its body. That'd set me up real nice for future tinkering. Besides, taking it out means it won't come back, and I'd like to finish this gig intact. I've got bills to pay, and kids to feed! Try the shrink ray on that hunk o' rock. Show it who's boss! For science, of course.", ["objectivesText"] = "Use the prototype to weaken & kill the Raging Kaja'mite Gemsplitter . Progress: Good to see you in one piece. How'd it go?", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 228549, 228948, 232762, 232763 }, ["rewardChoices"] = { 232762, 232763 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 228566, ["x"] = 0.216, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 228566, ["x"] = 0.216, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.216, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["sourceQuests"] = { 84302 }, ["questLines"] = { { ["id"] = 5669, ["name"] = "Kaja'Curiosity", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862 },
