[84334] = { ["id"] = 84334, ["name"] = "Warn the Detective", ["level"] = 10, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84334 }, ["description"] = "Welcome back, <name>. I saw the detective headed west. Hurry up and warn him before the shapeshifter comes for him too!", ["objectivesText"] = "Warn Detective Jones about the shapeshifter.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232405, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232406, ["x"] = 0.63, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226796, ["x"] = 0.6265, ["y"] = 0.5125 }, { ["mapID"] = 71, ["npcID"] = 228661, ["x"] = 0.61, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 84296 }, ["db2LabelIDs"] = { 4063 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71, ["db2QuestSortName"] = "Nightborne" },
[84336] = { ["id"] = 84336, ["name"] = "Spot the Difference", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84336 }, ["description"] = "Look, I'm the real detective. You believe me, right? I know--ask me anything. The good people here will be able to corroborate my story and we'll prove that I'm me.", ["objectivesText"] = "Solve the case of the shapeshifting demon. Progress: This is preposterous...", ["rewardGold"] = 676600, ["rewardXP"] = 1770, ["rewardItems"] = { 207730 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 10 }, { ["id"] = 3100, ["amount"] = 5 }, { ["id"] = 3100, ["amount"] = 8 } }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226796, ["x"] = 0.6265, ["y"] = 0.5125 }, { ["mapID"] = 71, ["npcID"] = 228661, ["x"] = 0.61, ["y"] = 0.506 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232405, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232406, ["x"] = 0.63, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.6265, ["y"] = 0.5125 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 84334 }, ["db2LabelIDs"] = { 4061, 4063 }, ["db2QuestSortName"] = "Nightborne" },
[84352] = { ["id"] = 84352, ["name"] = "No More Walkin' Here", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84352, 86618, 87581 }, ["description"] = "We gotta do something about how long it's taking to get you around. Luckily, I know just the gal. Go meet Nanny Talullah at the Caddy Shack and see if she'll lend you some wheels.", ["objectivesText"] = "Meet Nanny Talullah on the third floor at the Caddy Shack.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225531, ["x"] = 0.426, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 227210, ["x"] = 0.374667, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83167 }, ["questLines"] = { { ["id"] = 5772, ["name"] = "Shipping? Handled.", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346, ["db2QuestHubAreaPoiID"] = 8189 },
[84363] = { ["id"] = 84363, ["name"] = "Tweasure Hunt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84363 }, ["series"] = { 84143, 84144, 84393 }, ["description"] = "I know! We could use da stick to look for tweasures! You and Enzo go check da other ruins. Find somefing really cool! I'll meet you back at da parties.", ["objectivesText"] = "Use the Torch of Pyrreth to search for treasure around the ruins of Tanaris. Progress: Did you find any tweasure?", ["rewardGold"] = 292100, ["rewardXP"] = 1415, ["rewardItems"] = { 227775, 227777, 227785, 227790 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 5 }, { ["id"] = 3100, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 229062, ["x"] = 0.362, ["y"] = 0.785 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226684, ["x"] = 0.632, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.785 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 84393 }, ["db2LabelIDs"] = { 4063 }, ["db2QuestSortName"] = "Nightborne" },
[84365] = { ["id"] = 84365, ["name"] = "Something on the Horizon", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 84365 }, ["series"] = { 79197, 79333, 84367 }, ["description"] = "Brann's scouts have reported sightings of reinforcements approaching the shores of Khaz Algar. He's put out the call for adventurers to join him in Dornogal.", ["objectivesText"] = "Speak to Brann Bronzebeard in Dornogal.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["x"] = 0.474, ["y"] = 0.444, ["mapID"] = 2339, ["npcID"] = 206017 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 206017, ["questType"] = "standard" },
[84367] = { ["id"] = 84367, ["name"] = "A Time to Come Together", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 84367 }, ["series"] = { 79197, 79333, 84365 }, ["description"] = "We ought tae be getting a whole fleet o' reinforcements soon. Just in time, I hear Alleria and Anduin are back in Dornogal. If I know Moira, she'll already be workin' with 'em tae figure out our next move. She knows how tae lead like a gryphon knows how tae fly. Best go find her before she comes looking for ye.", ["objectivesText"] = "Speak to Moira Thaurissan in Dornogal.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 216149, ["x"] = 0.36, ["y"] = 0.804 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard" },
[84370] = { ["id"] = 84370, ["name"] = "The Key to Success", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15329, ["mapID"] = 2339, ["storyline"] = { 84370 }, ["description"] = "<A Cipher Key? Elise Starseeker might know what to do with this.>", ["objectivesText"] = "Bring the Archaic Cipher Key to Elise Starseeker in Dornogal. Progress: This map makes no sense... Champion! Good tidings I hope?", ["rewardGold"] = 234000, ["rewardXP"] = 4760, ["rewardItems"] = { 131744, 227794, 245589 }, ["rewardCurrencies"] = { { ["id"] = 2803, ["amount"] = 1500 }, { ["id"] = 2815, ["amount"] = 300 }, { ["id"] = 2815, ["amount"] = 500 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 228605, ["x"] = 0.48, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["startItems"] = { 227794 } },
[84371] = { ["id"] = 84371, ["name"] = "Lorewalking: The Blade and the High Priest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 40710, 53761, 53762, 53763, 54058, 54114, 54118, 54126, 84371, 84779, 84782, 84784, 84789, 85871 }, ["description"] = "Xal'atath, the Harbinger of Void, is a cunning and dangerous foe. She has been careful to make her presence known only to a precious few. We first learned of her during the Legion's third invasion of Azeroth, but whispers say she has been around since long, long before that. This is a story of power, darkness, and deceit. Join me and I will tell you the tale of Xal'atath's mysterious past.", ["objectivesText"] = "Follow Cho's guidance to learn the story of Xal'alath's past.", ["rewardGold"] = 29700, ["rewardXP"] = 175, ["rewardItems"] = { 142536, 229361, 242386, 244888, 245567, 245631 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3107, ["amount"] = 3 }, { ["id"] = 3284, ["amount"] = 3 } }, ["starts"] = { { ["x"] = 0.642, ["y"] = 0.161, ["mapID"] = 84, ["npcID"] = 232441 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 231891, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questGiverID"] = 232441, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5673, ["name"] = "Lorewalking: Xal'atath", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 266, ["title"] = "Lorewalking: Xal'atath", ["questLineID"] = 5673, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[84376] = { ["id"] = 84376, ["name"] = "Property Devalued", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84376, 84378, 84379, 84380, 84381, 86408 }, ["series"] = { 84378 }, ["description"] = "<You come across a wanted poster that has been nailed on top of a for rent sign .> WANTED: Seeking able-bodied adventurer to work as security for local apartment complex. Must be capable of not dying. REWARD: Free room and board in exchange for services rendered. Interested parties should inquire upstairs at the nearby Barrelbottom Apartments for further details.", ["objectivesText"] = "Visit Barrelbottom Apartments and inquire about a room to rent. Progress: That Moz is driving me crazy! Maybe you can talk some sense into him.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["x"] = 0.418, ["y"] = 0.659, ["mapID"] = 2346, ["objectID"] = 461478 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228857, ["x"] = 0.395, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["nextQuests"] = { 84378, 84379, 84380 }, ["questLines"] = { { ["id"] = 5685, ["name"] = "Property Devalued", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[84378] = { ["id"] = 84378, ["name"] = "Renter's Insurance", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84376, 84378, 84379, 84380, 84381, 86408 }, ["series"] = { 84376 }, ["description"] = "It's bad enough that the old skinflint landlord is letting this place slowly fall apart, but now we got even bigger problems. Recently, those would-be gangsters up the road, the Underriders, went from petty theft and noise complaints to being a heavily armed menace. They've started trashing the place, and even attackin' us directly! What's worse, anyone who can't afford to move out are evicted for the damage those thugs caused instead. You keep us safe, you can crash here free of charge.", ["objectivesText"] = "Kill 12 Underrider biker gang members. Progress: I can't keep up with all these repairs. Someone needs to do something about those bikers!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228857, ["x"] = 0.395, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228857, ["x"] = 0.395, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 84376 }, ["questLines"] = { { ["id"] = 5685, ["name"] = "Property Devalued", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[84379] = { ["id"] = 84379, ["name"] = "Tenant Trouble", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84376, 84378, 84379, 84380, 84381, 86408 }, ["description"] = "<Gabi waves you over urgently. The small goblin wrings her hands together nervously trying to find the words to explain her concern.> Some goblins aren't moving out--they're being kidnapped. I know it. My friends wouldn't have moved. They wouldn't. <Gabi looks up at you imploringly with misty eyes.> Please help, <class>. Please?", ["objectivesText"] = "Rescue 8 Captured Tenants.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228860, ["x"] = 0.394667, ["y"] = 0.684667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228857, ["x"] = 0.395, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.394667, ["y"] = 0.684667 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 84376 }, ["questLines"] = { { ["id"] = 5685, ["name"] = "Property Devalued", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[84380] = { ["id"] = 84380, ["name"] = "Weapons Cash", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84376, 84378, 84379, 84380, 84381, 86408 }, ["description"] = "<Inside the weapons crate you find a crumpled note written to the Underriders.> Good to see you're putting your new toys to good use. These little squatters are leaving in droves thanks to you guys! Keep up the good work and there's more where this came from. Just try not to burn the whole place down. Can't rent out an empty lot, haha! Signed, M.B.B.", ["objectivesText"] = "Destroy Underrider equipment throughout the compound. Progress: Find something?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229392 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.447, ["y"] = 0.661, ["mapID"] = 2346, ["objectID"] = 461492 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228857, ["x"] = 0.395, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 84376 }, ["questLines"] = { { ["id"] = 5685, ["name"] = "Property Devalued", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[84381] = { ["id"] = 84381, ["name"] = "Renegotiations", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84376, 84378, 84379, 84380, 84381, 86408 }, ["series"] = { 86408 }, ["description"] = "That settles it! I think we both know who's responsible for this mess. It's that bastard landlord, Moz Barrelbottom ! Soon as the Underriders were dealt with, he sent his goon Jarvis on a rampage. Looks like if he can't scare us out, he's going to force us out! <Keara spits on the ground in disgust.> He won't scare us so easily. You're pretty tough, <name>. Moz's office is just across the street. Go show him he's messin' with the wrong goblins!", ["objectivesText"] = "Defeat Jarvis Bonebreaker and collect the Barrelbottom Deed from Moz Barrelbottom in his third floor office across the street. Progress: We'll be fine here. You just go deal with Moz!", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 229419, 235146, 235147, 235148, 235149 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228857, ["x"] = 0.395, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228857, ["x"] = 0.395, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 84378, 84379, 84380 }, ["questLines"] = { { ["id"] = 5685, ["name"] = "Property Devalued", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[84392] = { ["id"] = 84392, ["name"] = "Hungry in Hollow", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 84392 }, ["series"] = { 82843 }, ["description"] = "Hey. You looking for a great meal? Willing to wade through the mud to get it? Go see Dolena . She'll sort you out. Don't bother trying to convince her to leave that hollow, though. Believe me--we've all tried. Why someone would leave the safety of the light for that... She seems to do alright, though.", ["objectivesText"] = "Seek out Dolena in Growling Hollow", ["rewardGold"] = 29200, ["rewardXP"] = 1275, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 222683, ["x"] = 0.489333, ["y"] = 0.394667 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224741, ["x"] = 0.699, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.489333, ["y"] = 0.394667 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["nextQuests"] = { 82843 } },
