[84419] = { ["id"] = 84419, ["name"] = "To da Ruins!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84419 }, ["description"] = "You found my brovver's sleufing fingy! < Maru holds it up with reverence.> Da Stick of Reveawing! Dis fing can turn on da lights, melt stuff, and even unlock ANSHENT TWEASURE. And all you gotta do is hold it up! We wuz gonna try it on dis fing outside the Wuins of Uldum. Wanna come?", ["objectivesText"] = "Meet Maru and Enzo outside the Ruins of Uldum.", ["rewardGold"] = 31200, ["rewardXP"] = 175, ["rewardItems"] = { 30253, 30254, 30255, 94219 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226684, ["x"] = 0.632, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 229062, ["x"] = 0.362, ["y"] = 0.785 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 84144 }, ["db2LabelIDs"] = { 4063 }, ["db2QuestSortName"] = "Nightborne" },
