[84521] = { ["id"] = 84521, ["name"] = "Thoughtful Pursuits", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84521 }, ["description"] = "Maru has been such a good junior sleuth that it's time to reward her with a Thinking Cap of her own! I can't just hand one over to her, though, so I've buried the parts she'll need to make one herself. I've hidden the coordinates for each part in riddles. Figure out the riddles to find the hiding places! Would you escort her to make sure she doesn't run into trouble? You can use my Thinking Cap to help. Also, I'll give you a special clue book that will reveal riddles as you progress.", ["objectivesText"] = "Escort Maru through Benatauk 's puzzle. Progress: How's it coming along? Maru isn't giving you any trouble, is she?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 206696, 228617, 228618, 228619, 228620 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 5 }, { ["id"] = 3100, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226766, ["x"] = 0.632, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226766, ["x"] = 0.632, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 84363 }, ["db2LabelIDs"] = { 4063 }, ["db2QuestSortName"] = "Nightborne" },
[84542] = { ["id"] = 84542, ["name"] = "A Radiant Echo", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84542 }, ["description"] = "<Within your hand, you hold a small Azerite sphere. Its light is steady and bright, but the sound it emits is plaintive and longing. It tugs at you, ever so slightly.>", ["objectivesText"] = "Bring the Radiant Echo to a Worldsoul Memory, then release it.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 220520, 235897 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14771 } }, ["questType"] = "standard", ["startItems"] = { 228958 } },
