[84779] = { ["id"] = 84779, ["name"] = "Lorewalking: The Blade's Gambit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 84, ["storyline"] = { 40710, 53761, 53762, 53763, 54058, 54114, 54118, 54126, 84371, 84779, 84782, 84784, 84789, 85871 }, ["description"] = "Though now only a blade of little power, Xal'atath was not idle. In the aftermath of the Legion invasion, tensions between the Horde and the Alliance erupted into the Fourth War. Xal'atath took advantage of the many forces at play in the war in a gambit to restore her power...", ["objectivesText"] = "Listen to Lorewalker Cho to learn the story of Xal'alath during the Fourth War.", ["rewardGold"] = 34100, ["rewardXP"] = 175, ["rewardItems"] = { 142536, 164911, 242386, 244888, 245567, 245631 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3107, ["amount"] = 3 }, { ["id"] = 3284, ["amount"] = 3 } }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 231891, ["x"] = 0.642, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 231891, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 84371 }, ["questLines"] = { { ["id"] = 5673, ["name"] = "Lorewalking: Xal'atath", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 266, ["title"] = "Lorewalking: Xal'atath", ["questLineID"] = 5673, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[84781] = { ["id"] = 84781, ["name"] = "Master of Secrets", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 6757, ["mapID"] = 554, ["storyline"] = { 84781 }, ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 142223, 161081, 198622, 205162, 228967, 228995, 228996 }, ["starts"] = { { ["x"] = 0.431, ["y"] = 0.414, ["mapID"] = 554, ["npcID"] = 16445 } }, ["ends"] = { { ["x"] = 0.431, ["y"] = 0.414, ["mapID"] = 554, ["npcID"] = 16445 } }, ["coords"] = { ["mapID"] = 554, ["x"] = 0.431, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["questGiverID"] = 16445, ["questTurnInID"] = 16445, ["questType"] = "standard", ["sourceQuests"] = { 84780 }, ["db2LabelIDs"] = { 4063 } },
[84782] = { ["id"] = 84782, ["name"] = "Lorewalking: The Blade's Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 84, ["storyline"] = { 40710, 53761, 53762, 53763, 54058, 54114, 54118, 54126, 84371, 84779, 84782, 84784, 84789, 85871 }, ["description"] = "Many years ago, a stone tablet from Stormsong Valley made its way into my library. It took years to break the cipher and translate the fragments of runes etched into it. I will tell you what we have pieced together. A tale of yet more treachery...", ["objectivesText"] = "Listen to Cho to learn the story of Xal'alath in Ny'alotha.", ["rewardGold"] = 1230, ["rewardXP"] = 175, ["rewardItems"] = { 142536, 244888, 245567, 245631 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 231891, ["x"] = 0.642, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 231891, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 14771 } }, ["questTurnInID"] = 231891, ["questType"] = "standard", ["sourceQuests"] = { 84779 }, ["questLines"] = { { ["id"] = 5673, ["name"] = "Lorewalking: Xal'atath", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 266, ["title"] = "Lorewalking: Xal'atath", ["questLineID"] = 5673, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2801, ["db2PoiUiMapID"] = 2381 },
[84784] = { ["id"] = 84784, ["name"] = "Lorewalking: The Blade's Nemeses", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["mapID"] = 2383, ["storyline"] = { 40710, 53761, 53762, 53763, 54058, 54114, 54118, 54126, 84371, 84779, 84782, 84784, 84789, 85871 }, ["description"] = "Lord N'Zoth calls now upon his brethren to aid in Xal'atath's defeat. You have been chosen to make the way for them to arrive. You know what to do.", ["objectivesText"] = "Activate the 3 Ritual Obelisks to summon Yogg-Saron , C'Thun , and Y'Shaarj . Progress: Do not waste Lord N'Zoth's time.", ["rewardGold"] = 34100, ["rewardXP"] = 175, ["rewardItems"] = { 244888, 245567, 245631 }, ["starts"] = { { ["x"] = 0.525, ["y"] = 0.731, ["mapID"] = 2381, ["npcID"] = 230321 } }, ["ends"] = { { ["x"] = 0.525, ["y"] = 0.731, ["mapID"] = 2381, ["npcID"] = 230321 } }, ["coords"] = { ["mapID"] = 2381, ["x"] = 0.525, ["y"] = 0.731 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 230321, ["questTurnInID"] = 230321, ["questType"] = "standard", ["sourceQuests"] = { 84782 }, ["questLines"] = { { ["id"] = 5673, ["name"] = "Lorewalking: Xal'atath", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 266, ["title"] = "Lorewalking: Xal'atath", ["questLineID"] = 5673, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2801, ["db2PoiUiMapID"] = 2383 },
