[84789] = { ["id"] = 84789, ["name"] = "Lorewalking: The Blade's Downfall", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 40710, 53761, 53762, 53763, 54058, 54114, 54118, 54126, 84371, 84779, 84782, 84784, 84789, 85871 }, ["description"] = "They are ready. The Lords hold Xal'atath within the keep. You are the pebble to trigger the avalanche of their power. To end Xal'atath . Go. Join them.", ["objectivesText"] = "Confront Xal'atath .", ["rewardGold"] = 34100, ["rewardXP"] = 175, ["rewardItems"] = { 242386, 244846, 244888, 245567, 245631 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 25 }, { ["id"] = 3107, ["amount"] = 10 }, { ["id"] = 3284, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.525, ["y"] = 0.731, ["mapID"] = 2381, ["npcID"] = 230321 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 231891, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questGiverID"] = 230321, ["questType"] = "standard", ["sourceQuests"] = { 84784, 85871 }, ["questLines"] = { { ["id"] = 5673, ["name"] = "Lorewalking: Xal'atath", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 266, ["title"] = "Lorewalking: Xal'atath", ["questLineID"] = 5673, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
