[84820] = { ["id"] = 84820, ["name"] = "By Oath and Blood", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84740, 84741, 84759, 84760, 84761, 84762, 84765, 84820, 84915 }, ["series"] = { 84765 }, ["description"] = "After the Devouring, I didn't think I'd see Fennad again. At first, it was easier to stay angry at him for leaving than to grieve. Then it was easier to forget, to only focus on surviving the next day. Seeing him again brought everything back. Oath-breaker... He had forsaken his oath to come home, but family is the first oath we're born to. What would it make me if I abandoned him now? He's my brother--by oath and by blood. I won't leave him to the Sufaadi.", ["objectivesText"] = "Rescue Om'fennad .", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230233, ["x"] = 0.712, ["y"] = 0.5205 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230159, ["x"] = 0.7008, ["y"] = 0.5564 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.5205 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 84762 }, ["questLines"] = { { ["id"] = 5683, ["name"] = "Of Boughs and Bonds", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[84821] = { ["id"] = 84821, ["name"] = "Biological Quintainment", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79559, 79561, 79563, 79564, 80096, 80144, 84621, 84821 }, ["description"] = "Have earned spurs, now time use them! Slimes run off with joust dummies, but that just make for moving target. Better practice! Mount noble mole steed by gate, get eye with lance, ride down slime. Important skill for any knight, yes.", ["objectivesText"] = "Lance target dummy carrying slimes from mole-back. Progress: Watch out for big ones. Kick you good!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 218866, ["x"] = 0.668, ["y"] = 0.785 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 218866, ["x"] = 0.668, ["y"] = 0.785 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.785 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 84621 }, ["questLines"] = { { ["id"] = 5678, ["name"] = "The Verdigrease Knight", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[84822] = { ["id"] = 84822, ["name"] = "To Iskaara", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2024, ["storyline"] = { 84822, 86352, 86353, 86354, 86355, 86356, 86357, 86358, 86359 }, ["series"] = { 86353, 86354 }, ["description"] = "Let's get these kids back to Iskaara, eh? I'll meet you there.", ["objectivesText"] = "Meet Hemet Nesingwary in Iskaara.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 21100, 21746, 199473, 201705, 201709, 201712, 201713, 201714, 201717, 201718, 204379 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 234745, ["x"] = 0.188, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 235290, ["x"] = 0.136, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.188, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 86353, 86354 }, ["questLines"] = { { ["id"] = 5744, ["name"] = "Nesingwary Necessities", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5744, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[84826] = { ["id"] = 84826, ["name"] = "Eco-Dome: Rhovan", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84826, 84827, 84831, 84834, 84838, 84848, 84867, 84869, 84876, 84879, 84883, 84910, 85730, 86327, 86332 }, ["description"] = "I will not make excuses for what we did. I will carry the responsibility of it for the rest of my existence. Alleria will come to understand why it was necessary. When she sees the power of the All-Devouring, she will understand. We will need at least two more Reshii Ribbons to bring enough of a force to bear against Dimensius. My friend Om'bera is a holder of a ribbon. She works in Eco-Dome: Rhovan on the next island. Let us gather her to our cause.", ["objectivesText"] = "Meet Locus-Walker at Eco-Dome: Rhovan.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230811, ["x"] = 0.47, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230288, ["x"] = 0.71, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 90517 }, ["questLines"] = { { ["id"] = 5717, ["name"] = "Desert Power", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5717, ["questLineOrder"] = 2 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5717, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[84827] = { ["id"] = 84827, ["name"] = "The Shattered Dome", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84826, 84827, 84831, 84834, 84838, 84848, 84867, 84869, 84876, 84879, 84883, 84910, 85730, 86327, 86332 }, ["description"] = "Eco-Dome: Rhovan was shattered by a falling chunk of void glass, destroying the structure and scattering its caretakers. They have returned to recover whatever equipment, flora, or fauna can be salvaged before the wastes claim them. Search the ruins to find any clues of Overseer Om'bera 's fate. We must have her Reshii Ribbon! Om'resh and I will search the impact crater.", ["objectivesText"] = "Search Eco-Dome: Rhovan for Om'bera . Progress: Could Om'bera still be somewhere within the wreckage?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229058, 229060 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230288, ["x"] = 0.71, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230288, ["x"] = 0.71, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 84826 }, ["questLines"] = { { ["id"] = 5717, ["name"] = "Desert Power", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5717, ["questLineOrder"] = 2 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5717, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[84831] = { ["id"] = 84831, ["name"] = "The Rhovan Infestation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84826, 84827, 84831, 84834, 84838, 84848, 84867, 84869, 84876, 84879, 84883, 84910, 85730, 86327, 86332 }, ["description"] = "When the meteor struck, Om'bera and I tried to salvage what we could. Without the dome's shield, we were soon beset upon by scavengers of the Great Dark Beyond. We fled and were separated. Such creatures are not of K'aresh , and hostile to the stable biomes we sought to achieve. We need to clear these invasive creatures to find our equipment, and Om'bera.", ["objectivesText"] = "Kill 10 invasive creatures in Eco-Dome: Rhovan. Progress: This was once a thriving eco-dome of the Trust. Our research worked toward the restoration of K'aresh .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230294, ["x"] = 0.71, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230294, ["x"] = 0.71, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 84826 }, ["questLines"] = { { ["id"] = 5717, ["name"] = "Desert Power", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5717, ["questLineOrder"] = 2 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5717, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[84834] = { ["id"] = 84834, ["name"] = "Tempest Clefts", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84826, 84827, 84831, 84834, 84838, 84848, 84867, 84869, 84876, 84879, 84883, 84910, 85730, 86327, 86332 }, ["series"] = { 86327 }, ["description"] = "The Wastelanders were once the oracles of the Worldsoul of K'aresh . They were so proud and strident about their oaths. Now they scavenge the ruins like animals. Even rats have their uses. Gather void cleft essences for me. I have an idea of how we might sway the fallen oracles to our cause.", ["objectivesText"] = "Bring 6 Void Cleft Essences to Xal'atath in the Tempest Fields. Progress: Many denizens of the Void are voracious consumers of energy. They greedily flock to pockets of coalesced energy like moths to a flame.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229994, 233018 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 233878, ["x"] = 0.64, ["y"] = 0.47 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 233878, ["x"] = 0.64, ["y"] = 0.47 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.47 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86327 }, ["questLines"] = { { ["id"] = 5717, ["name"] = "Desert Power", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5717, ["questLineOrder"] = 2 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5717, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
