[84838] = { ["id"] = 84838, ["name"] = "Enemies of Enemies", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84826, 84827, 84831, 84834, 84838, 84848, 84867, 84869, 84876, 84879, 84883, 84910, 85730, 86327, 86332 }, ["description"] = "The Wastelanders have made camp in the ruins of old K'aresh . A sanctuary from the ravenous beasts of the Void that stalk the wastes of K'aresh . A bulwark against outsiders. If a hostile entity were to enter their camp, you could defeat it--then they would respect you. Take the void energy you gathered into the ruined tower north of here. Be ready!", ["objectivesText"] = "Place the coalesced void energy in the Castigar. Progress: You are not welcome here, stranger.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 36888, 36937, 36938, 38213, 38672, 61600, 61604, 61606, 113145, 113146, 113147, 131572, 141348, 143488, 156952, 230772 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 233878, ["x"] = 0.64, ["y"] = 0.47 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230645, ["x"] = 0.612, ["y"] = 0.392 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.47 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 84834, 84869 }, ["questLines"] = { { ["id"] = 5717, ["name"] = "Desert Power", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5717, ["questLineOrder"] = 2 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5717, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[84848] = { ["id"] = 84848, ["name"] = "Before the Void", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84826, 84827, 84831, 84834, 84838, 84848, 84867, 84869, 84876, 84879, 84883, 84910, 85730, 86327, 86332 }, ["description"] = "You've impressed these Wastelanders with your violent prowess, my champion. Well done. Now let me do my work. I know what these former oracles want. They dream of hearing the Song of K'aresh once more. I must make them believe it is possible, then pull on that string of desire. Soon we will have our army, and another Reshii Ribbon. First, let's return the Tabiqa ritual dagger.", ["objectivesText"] = "Convince Soul-Scribe to join forces.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232599, 237860, 237866, 237872, 237881 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230634, ["x"] = 0.612, ["y"] = 0.392 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230292, ["x"] = 0.63, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.392 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 84838 }, ["questLines"] = { { ["id"] = 5717, ["name"] = "Desert Power", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5717, ["questLineOrder"] = 2 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5717, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
