[84915] = { ["id"] = 84915, ["name"] = "Clearing the Dunes", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84740, 84741, 84759, 84760, 84761, 84762, 84765, 84820, 84915 }, ["series"] = { 84740, 84741 }, ["description"] = "The deserts here were never safe, but there was still beauty--birdsong, herds of animals, and the desert would bloom from horizon to horizon after a storm. Now it's a wasteland. I barely took two steps off the docks before being chased by some monster. I need to get out there. If you could cull the worst of those creatures, I'd feel much safer.", ["objectivesText"] = "Slay 8 dune creatures. Progress: Is it safe yet?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230159, ["x"] = 0.7008, ["y"] = 0.5564 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230159, ["x"] = 0.7008, ["y"] = 0.5564 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.7008, ["y"] = 0.5564 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 84967 }, ["questLines"] = { { ["id"] = 5683, ["name"] = "Of Boughs and Bonds", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[84923] = { ["id"] = 84923, ["name"] = "A Bird's Tale", ["level"] = 10, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84923 }, ["series"] = { 84924 }, ["description"] = "I've heard that Reshad has a new story to tell involving his bird companion, Percy. Speak with him if you would like to discover the tale.", ["objectivesText"] = "Find Reshad near the stage.", ["rewardGold"] = 31500, ["rewardXP"] = 175, ["rewardItems"] = { 229411 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232406, ["x"] = 0.63, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 228273, ["x"] = 0.642, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 83831 }, ["db2LabelIDs"] = { 4018, 4063 }, ["db2QuestSortName"] = "Nightborne" },
[84924] = { ["id"] = 84924, ["name"] = "A Bird's Tail", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84924 }, ["series"] = { 84923 }, ["description"] = "I've told many tales in my days, but my companion Percy has a tale of his own to tell. Would you care to learn about it? I will give you a clue on where to start. From there, you must find the clues that Percy has left behind to discover his story. You can have this feather that Percy left behind as well. Look closely and you may find more clues. Perhaps a bird of your own may help you on your journey.", ["objectivesText"] = "Learn about Percy's adventures by finding his feathers. Progress: Have you discovered Percy's tale?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 110560, 207730, 229408, 229409, 229410, 229411, 229958, 231907 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 5 }, { ["id"] = 3100, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 228273, ["x"] = 0.642, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 228273, ["x"] = 0.642, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 84923 }, ["db2LabelIDs"] = { 4018, 4061, 4063 }, ["db2QuestSortName"] = "Nightborne" },
[84925] = { ["id"] = 84925, ["name"] = "Rallying All Rapscallions!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 84925 }, ["description"] = "Come one, come all, straight to Dornogal ! In addition to the usual selection of powerful equipment offered at the Contender's Gate, aspiring combatants and proven gladiators can purchase heraldry tokens which can be used to craft equipment certified for use in arenas and battlegrounds! Present this brochure to Hotharn to receive a few of these, on us! - Aisha", ["objectivesText"] = "Deliver the advertisement to Hotharn at the Contender's Gate in Dornogal .", ["rewardItems"] = { 229390, 229401, 230287 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219215, ["x"] = 0.555, ["y"] = 0.77 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.77 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["startItems"] = { 229401 } },
