[84932] = { ["id"] = 84932, ["name"] = "A Legacy of Destruction", ["level"] = 10, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84932 }, ["series"] = { 84933 }, ["description"] = "Adventurer! A dragon whelpling recently showed up in the pet playground and has been causing all sorts of chaos. Could you go talk to him and see if you can sort out the issue?", ["objectivesText"] = "Find the dragon whelpling at the pet playground.", ["rewardGold"] = 31200, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232406, ["x"] = 0.63, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 231029, ["x"] = 0.618, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 83831 }, ["db2LabelIDs"] = { 4018, 4063 }, ["db2QuestSortName"] = "Nightborne" },
[84933] = { ["id"] = 84933, ["name"] = "From Ashes to Wisdom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84933 }, ["series"] = { 84932 }, ["description"] = "I will become the great and powerful Deathwing! Cower before my strength! You there! Do you wish to join me, the next Deathwing, on an epic adventure?", ["objectivesText"] = "Show Voidfire the destruction of Deathwing. Progress: I want to get followers to do my bidding! Like a cult!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 134022, 231292, 231907 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 5 }, { ["id"] = 3100, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 231029, ["x"] = 0.618, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 231029, ["x"] = 0.618, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questTurnInID"] = 231029, ["questType"] = "standard", ["sourceQuests"] = { 84932 }, ["db2LabelIDs"] = { 4018, 4061, 4063 }, ["db2QuestSortName"] = "Nightborne" },
[84934] = { ["id"] = 84934, ["name"] = "A Dark Descent", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["storyline"] = { 84934 }, ["description"] = "I realize what I'm proposing is just this side of mad. The realm of death isn't the sort of place we're supposed to be able to just visit. But these visions that are plaguing my family... Mother's led to the destruction of Dalaran. What if Silvermoon is next? I can't afford to risk any complacency. And if there's anyone, living or otherwise, who might be able to speak to Silvermoon's defense... Well. Here goes nothing. See you on the other side? See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(84934)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(84934))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Venture forth into the Maw.", ["rewardXP"] = 1045, ["rewardItems"] = { 38734, 39033, 39060, 39098 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[84935] = { ["id"] = 84935, ["name"] = "Excising the Incursion", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 84935, 84936, 84937, 84938, 84939, 84942, 84943, 84944, 84945, 84946, 84947, 84949 }, ["description"] = "The Devouring Host must have somehow followed us here. I don't know what they could want with a place like this, but I can't imagine the Void is suddenly infused with benevolent purpose. We can't allow this incursion to get out of hand. Slay as many of them as you can manage. Enough to thin their numbers, at least.", ["objectivesText"] = "Slay aberrations of the Devouring Host in the Planes of Torment.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 231030, ["x"] = 0.25575, ["y"] = 0.2545 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 231030, ["x"] = 0.25575, ["y"] = 0.2545 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.25575, ["y"] = 0.2545 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 85214 }, ["questLines"] = { { ["id"] = 5706, ["name"] = "Paths Forward", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5706, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[84936] = { ["id"] = 84936, ["name"] = "To Cleanse Shadow's Stain", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 84935, 84936, 84937, 84938, 84939, 84942, 84943, 84944, 84945, 84946, 84947, 84949 }, ["description"] = "These monstrosities certainly wasted no time once they arrived. They are snatching up souls left and right and drowning them in void magics. Take my holy symbol. It should be potent enough to drive away the shadows that cling to any lingering souls.", ["objectivesText"] = "Use the Redeemer's Sigil to cleanse voidwarped souls in the Planes of Torment. Progress: Are the souls here just convenient targets? Or are they what drew the Host here to begin with?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 231791 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 231030, ["x"] = 0.25575, ["y"] = 0.2545 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 231030, ["x"] = 0.25575, ["y"] = 0.2545 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.25575, ["y"] = 0.2545 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 85214 }, ["questLines"] = { { ["id"] = 5706, ["name"] = "Paths Forward", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5706, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[84937] = { ["id"] = 84937, ["name"] = "Distant Echoes", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 84935, 84936, 84937, 84938, 84939, 84942, 84943, 84944, 84945, 84946, 84947, 84949 }, ["description"] = "Can you hear it? There's a strange sound echoing in the distance. Given where we are, I would assume it's a trick. Or worse, a trap. But it feels... I don't know how to describe it, but I feel calmer for hearing it. Like I'm in control. This is going to sound mad, but I think--I think we should follow it. I don't know where it could be coming from, but my instincts are telling me to trust it. We should follow its trail.", ["objectivesText"] = "Find the source of the strange melody. Progress: <Sylvanas eyes you up and down. She says nothing.>", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 231030, ["x"] = 0.25575, ["y"] = 0.2545 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 231033, ["x"] = 0.268286, ["y"] = 0.205429 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.25575, ["y"] = 0.2545 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 84935, 84936 }, ["questLines"] = { { ["id"] = 5706, ["name"] = "Paths Forward", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5706, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[84938] = { ["id"] = 84938, ["name"] = "Chaos Control", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 84935, 84936, 84937, 84938, 84939, 84942, 84943, 84944, 84945, 84946, 84947, 84949 }, ["description"] = "These are no mere embodiments of Void. They move with precision and purpose. They have taken up a defensive position within the Tremaculum. No doubt they intend to expand their presence and shore up their defenses, now that they have a foothold. All the better. It means they will all be gathered in one place. Break their ranks. Show no mercy.", ["objectivesText"] = "Stem the tide of the Devouring Host within the Tremaculum. Progress: I don't have to tell you how dangerous it would be to let outside forces meddle in the Maw for overlong. We need to excise them sooner rather than later.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 231033, ["x"] = 0.268286, ["y"] = 0.205429 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 231033, ["x"] = 0.268286, ["y"] = 0.205429 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.268286, ["y"] = 0.205429 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 84937 }, ["questLines"] = { { ["id"] = 5706, ["name"] = "Paths Forward", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5706, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[84939] = { ["id"] = 84939, ["name"] = "Mad Space", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 84935, 84936, 84937, 84938, 84939, 84942, 84943, 84944, 84945, 84946, 84947, 84949 }, ["description"] = "It doesn't matter how many of these void monstrosities we kill. We have to deal with the source, or they'll just keep coming. Traveling across the rift is not an easy feat in the best of times. If we can find the places where they've been able to tear through and close them, then we should be able to cut off their reinforcements. Lead the way. I'll be at your back the entire time.", ["objectivesText"] = "Collapse 5 Unstable Void Rifts . Progress: This place is swarming with servants of the Void. Stay on your guard.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 231030, ["x"] = 0.25575, ["y"] = 0.2545 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 231030, ["x"] = 0.25575, ["y"] = 0.2545 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.25575, ["y"] = 0.2545 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 84937 }, ["questLines"] = { { ["id"] = 5706, ["name"] = "Paths Forward", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5706, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[84940] = { ["id"] = 84940, ["name"] = "Friendly Competition", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 84719, 84720, 84721, 84722, 84723, 84724, 84725, 84726, 84727, 84728, 84940, 84941 }, ["description"] = "See, Ricket offered to dig it up, but the Arathi expedition lady didn't seem too keen on that. Gave 'er an earful. Could hear it from the airship. Yeesh. Bargus , the earthen \"ordinant\"--whatever that means-- proposed scanning the crystal to help us \"understand it better.\" I don't need to understand it. All I need's my cut. But I'm fine layin' low and doin' what they want. Go talk to Bargus at the earthen camp. See how they're comin' along an' if we can help.", ["objectivesText"] = "Seek out Bargus in the camp.", ["rewardGold"] = 30900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 230238, ["x"] = 0.6965, ["y"] = 0.494 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 230242, ["x"] = 0.6752, ["y"] = 0.4192 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.6965, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 84720 }, ["questLines"] = { { ["id"] = 5732, ["name"] = "A Song of Secrets", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 276, ["title"] = "Siren Isle", ["questLineID"] = 5732, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2127, ["db2PoiUiMapID"] = 2369 },
[84941] = { ["id"] = 84941, ["name"] = "Cave Barging", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 84719, 84720, 84721, 84722, 84723, 84724, 84725, 84726, 84727, 84728, 84940, 84941 }, ["description"] = "Unless it is a convergence of coincidence, whoever these large outlanders are, they appear to also be interested in the crystal's signal--and the location of its origin. We earthen do not often take stock in coincidences. Engage your defense protocols, <name>. These outlanders are not hospitable like your people.", ["objectivesText"] = "Find the source of the energy signature.", ["rewardGold"] = 309800, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 233501, ["x"] = 0.435, ["y"] = 0.2855 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 230271, ["x"] = 0.497333, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.2855 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 84727 }, ["questLines"] = { { ["id"] = 5732, ["name"] = "A Song of Secrets", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 276, ["title"] = "Siren Isle", ["questLineID"] = 5732, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2127, ["db2PoiUiMapID"] = 2369 },
[84942] = { ["id"] = 84942, ["name"] = "The Final Hazard", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 84935, 84936, 84937, 84938, 84939, 84942, 84943, 84944, 84945, 84946, 84947, 84949 }, ["description"] = "With their lesser rifts closed, the Devouring Host will be hard-pressed to muster any reinforcements. But if we don't deal with their leader, then they'll just open more. Above, in the parapets... There's no mistaking it. I can feel a force of Void drawing everything toward it, even all the way from down here. That's where we'll find our mark, without a doubt.", ["objectivesText"] = "Slay the Living Gateway atop the Tremaculum. Progress: All that's left to do is deal with their commander. I just really wish he'd picked a slightly lower vantage.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 231030, ["x"] = 0.25575, ["y"] = 0.2545 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 231033, ["x"] = 0.268286, ["y"] = 0.205429 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.25575, ["y"] = 0.2545 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 84938, 84939 }, ["questLines"] = { { ["id"] = 5706, ["name"] = "Paths Forward", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5706, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[84943] = { ["id"] = 84943, ["name"] = "The Long Vigil", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 11400, ["mapID"] = 1543, ["description"] = "If you and Arator desire something of me, it will have to wait. There are souls here that require my attention, assuming your bumbling hasn't driven them off. I've managed to track four souls that fell into the Maw without proper judgment. Correct your mistakes and help me to retrieve them, and perhaps I will find time for a chat.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["npcID"] = 231033, ["x"] = 0.268, ["y"] = 0.378, ["mapID"] = 1543 } }, ["ends"] = { { ["npcID"] = 231033, ["x"] = 0.268, ["y"] = 0.378, ["mapID"] = 1543 } }, ["coords"] = { ["x"] = 0.268, ["y"] = 0.378, ["source"] = "quest_giver", ["mapID"] = 1543 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 84942 }, ["questLines"] = { { ["id"] = 5706, ["name"] = "Paths Forward", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5706, ["questLineOrder"] = 2 } } },
[84944] = { ["id"] = 84944, ["name"] = "Preludes and Preparations", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 13476, ["mapID"] = 1543, ["storyline"] = { 84935, 84936, 84937, 84938, 84939, 84942, 84943, 84944, 84945, 84946, 84947, 84949 }, ["description"] = "As you are no doubt aware, ferrying souls beyond the bounds of the Maw is no easy task. This is not a place from whence souls are meant to ascend. Our resources are limited, but I have devised a way to ensure the relative safety of the souls I retrieve--though I will require materials. Fetch for me the reeds that grow in the silt of the Gorgoa River, soulthread from the cloaks of the wandering specters, the hide of a soul-eater... Ah. And mawrat teeth . We mustn't forget the mawrat teeth .", ["objectivesText"] = "Collect Gorgoa Reeds , Soulthreads , a Pristine Soul-Eater Hide , and 50 Mawrat Teeth . Progress: Have you gathered the reagents?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232427, 232428, 232429, 232513 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 231033, ["x"] = 0.268286, ["y"] = 0.205429 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 231030, ["x"] = 0.25575, ["y"] = 0.2545 }, { ["mapID"] = 1543, ["npcID"] = 238519, ["x"] = 0.305, ["y"] = 0.187 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.268286, ["y"] = 0.205429 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 84942 }, ["questLines"] = { { ["id"] = 5706, ["name"] = "Paths Forward", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5706, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[84945] = { ["id"] = 84945, ["name"] = "Repent of the Highborne", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 13476, ["mapID"] = 1543, ["storyline"] = { 84935, 84936, 84937, 84938, 84939, 84942, 84943, 84944, 84945, 84946, 84947, 84949 }, ["description"] = "The reagents are gathered, and the lingering souls have been put at ease for the moment. We do not have long. Stand back, while I send them to where they are meant to dwell.", ["objectivesText"] = "Observe the Ritual of Sending. Progress: <Sylvanas stands silently.>", ["rewardGold"] = 232300, ["rewardXP"] = 8825, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 231033, ["x"] = 0.268286, ["y"] = 0.205429 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 231033, ["x"] = 0.268286, ["y"] = 0.205429 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.268286, ["y"] = 0.205429 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 84943, 84944 }, ["questLines"] = { { ["id"] = 5706, ["name"] = "Paths Forward", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5706, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[84946] = { ["id"] = 84946, ["name"] = "Returning to Life", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 84935, 84936, 84937, 84938, 84939, 84942, 84943, 84944, 84945, 84946, 84947, 84949 }, ["description"] = "When I decided to come here, I have to admit that I wasn't sure what I would find. There's no disputing the terrible things that Sylvanas has done, and it's a burden that she will have to bear for the rest of her days. But seeing her, like this... Come. We've been here too long as it is. The weight of this place is starting to get to me.", ["objectivesText"] = "Return to K'aresh. Progress: Let's make haste. We don't belong here.", ["rewardGold"] = 232300, ["rewardXP"] = 8825, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 231030, ["x"] = 0.25575, ["y"] = 0.2545 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 233567, ["x"] = 0.606667, ["y"] = 0.924 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.25575, ["y"] = 0.2545 }, ["mapCandidates"] = { ["npc"] = { 1543, 2472 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 84945 }, ["questLines"] = { { ["id"] = 5706, ["name"] = "Paths Forward", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5706, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2472 },
[84947] = { ["id"] = 84947, ["name"] = "Determination", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 84935, 84936, 84937, 84938, 84939, 84942, 84943, 84944, 84945, 84946, 84947, 84949 }, ["description"] = "Hold a moment. Arator will be fine for a few moments longer. Let him travel alone for a moment. I wish to speak to you. Privately.", ["objectivesText"] = "Speak with Sylvanas. Progress: It would be unwise to linger here.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 233463, ["x"] = 0.262, ["y"] = 0.316 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 233463, ["x"] = 0.262, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.262, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 84945 }, ["questLines"] = { { ["id"] = 5706, ["name"] = "Paths Forward", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5706, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
