[84949] = { ["id"] = 84949, ["name"] = "The Eleventh Hour", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2472, ["storyline"] = { 84935, 84936, 84937, 84938, 84939, 84942, 84943, 84944, 84945, 84946, 84947, 84949 }, ["description"] = "It's high time we got back to Azeroth. I think we've done all we can do when it comes to mustering the Windrunners for whatever is to come.", ["objectivesText"] = "Return to Vereesa in Dornogal . Progress: We should get going. I've done enough dimension-traveling for one day, I think.", ["rewardGold"] = 929400, ["rewardXP"] = 17650, ["rewardItems"] = { 242715 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 233567, ["x"] = 0.606667, ["y"] = 0.924 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 233568, ["x"] = 0.399, ["y"] = 0.782 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.606667, ["y"] = 0.924 }, ["mapCandidates"] = { ["npc"] = { 2339, 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 84946, 84947 }, ["questLines"] = { { ["id"] = 5706, ["name"] = "Paths Forward", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5706, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
