[84956] = { ["id"] = 84956, ["name"] = "A Shadowy Invitation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2339, ["storyline"] = { 84956, 84957, 84958, 84959, 84960, 84961, 84963, 84964, 84965, 84967, 85003, 85039, 86835 }, ["description"] = "$p, I've received word from my mentor, Locus-Walker . He warns of a Shadowguard plot that requires our aid. I wonder if he has finally tracked down Xal'atath. Come to the Foundation Hall in Dornogal. We must speak immediately.", ["objectivesText"] = "Meet Locus-Walker at the Foundation Hall in Dornogal.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 235499 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 227758, ["x"] = 0.422, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 233603, ["x"] = 0.409333, ["y"] = 0.243333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5690, ["name"] = "A Shadowy Invitation", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5690, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[84957] = { ["id"] = 84957, ["name"] = "Return to the Veiled Market", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2339, ["storyline"] = { 84956, 84957, 84958, 84959, 84960, 84961, 84963, 84964, 84965, 84967, 85003, 85039, 86835 }, ["description"] = "I have been retained by the K'aresh Trust--a coalition of both broker and ethereal cartels who seek to reclaim K'aresh . The Trust is in desperate need of one of your skills, <name>. The Shadowguard assaults our city and threatens the work of the eco-dome project. Please accompany me.", ["objectivesText"] = "Accompany Locus-Walker and Alleria to Tazavesh.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 233603, ["x"] = 0.409333, ["y"] = 0.243333 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 233706, ["x"] = 0.595333, ["y"] = 0.833333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.409333, ["y"] = 0.243333 }, ["mapCandidates"] = { ["npc"] = { 2339, 2472 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 84956 }, ["questLines"] = { { ["id"] = 5690, ["name"] = "A Shadowy Invitation", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5690, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[84958] = { ["id"] = 84958, ["name"] = "Beasts Unbound", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 84956, 84957, 84958, 84959, 84960, 84961, 84963, 84964, 84965, 84967, 85003, 85039, 86835 }, ["description"] = "I am Ta'ka , supplier of rare creatures destined to repopulate my homeland. At least, I was until some of them escaped their translocation cages! This cannot stand! These creatures are vital. If you could assist me with capturing them, I'd be quite appreciative. Engage them in combat and subdue them. The capture device I've provided will automatically translocate them back to my care once they are on the verge of defeat.", ["objectivesText"] = "Defeat escaped creatures in Tazavesh to return them to Ta'ka . Progress: Have you finished capturing the escaped beasts?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 230954, ["x"] = 0.568, ["y"] = 0.733 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 230954, ["x"] = 0.568, ["y"] = 0.733 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.733 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 84957 }, ["questLines"] = { { ["id"] = 5690, ["name"] = "A Shadowy Invitation", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5690, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[84959] = { ["id"] = 84959, ["name"] = "Lost Lines of Defense", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 84956, 84957, 84958, 84959, 84960, 84961, 84963, 84964, 84965, 84967, 85003, 85039, 86835 }, ["description"] = "This is not a good day! Not at all. My whole shipment of barrier projectors was ransacked! Most of them are gone, and it seems whatever the culprits didn't take, they destroyed. These barrier projectors are essential for securing the wild places on K'aresh , and even the city of Tazavesh. Our efforts are in jeopardy! Please, if you can find any of my shipments it would help us get our efforts back on track.", ["objectivesText"] = "Collect 8 Stolen Barrier Projectors for Ba'ver . Progress: Have you located my barrier projectors?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235366, 237875, 237883, 237887, 237888 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 230955, ["x"] = 0.532, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 230955, ["x"] = 0.532, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 84957 }, ["questLines"] = { { ["id"] = 5690, ["name"] = "A Shadowy Invitation", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5690, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[84960] = { ["id"] = 84960, ["name"] = "The Darkness Among Us", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 84956, 84957, 84958, 84959, 84960, 84961, 84963, 84964, 84965, 84967, 85003, 85039, 86835 }, ["description"] = "Alleria, <name>... Have you sensed it? The Void lingers in all of this. Whoever is pulling the strings is cloaked in shadow, hiding from us. Come, let's seek them out and drag them into the light before they strike.", ["objectivesText"] = "Investigate the Void Presence and locate the culprits behind the many troubles in Tazavesh. Progress: We need to find the hidden Shadowguard, <name>.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 237890, 237893 }, ["rewardChoices"] = { 237890, 237893 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 233706, ["x"] = 0.595333, ["y"] = 0.833333 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 230604, ["x"] = 0.578857, ["y"] = 0.776286 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.595333, ["y"] = 0.833333 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 85003 }, ["questLines"] = { { ["id"] = 5690, ["name"] = "A Shadowy Invitation", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5690, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[84961] = { ["id"] = 84961, ["name"] = "Barriers to Entry", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 84956, 84957, 84958, 84959, 84960, 84961, 84963, 84964, 84965, 84967, 85003, 85039, 86835 }, ["description"] = "Those barrier projectors we recovered? We need them now. Place them at key points to reinforce the city shield and block more portals from forming. Move swiftly, <name>. This may be our only chance to stop the Shadowguard from flooding in.", ["objectivesText"] = "Place 8 Barrier Projectors around Tazavesh. Progress: Did you place the barrier projectors ? We need to slow down the invasion. Quickly!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 234596, ["x"] = 0.54, ["y"] = 0.634 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 234596, ["x"] = 0.54, ["y"] = 0.634 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.634 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questTurnInID"] = 234596, ["questType"] = "standard", ["sourceQuests"] = { 84960 }, ["questLines"] = { { ["id"] = 5690, ["name"] = "A Shadowy Invitation", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5690, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[84962] = { ["id"] = 84962, ["name"] = "Exigent Extermination", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84962, 85812, 85822, 85834, 85855, 85863, 85864, 86305, 86367, 86372, 86391, 86395, 86409, 86584, 86610, 86696, 86707, 86709, 86800, 86872 }, ["objectivesText"] = "Devourers culled", ["rewardXP"] = 11765, ["rewardItems"] = { 232601 }, ["starts"] = { { ["x"] = 0.659, ["y"] = 0.485, ["mapID"] = 2371 } }, ["ends"] = { { ["x"] = 0.659, ["y"] = 0.485, ["mapID"] = 2371 } }, ["coords"] = { ["mapID"] = 2371, ["x"] = 0.659, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15336 } }, ["questType"] = "world", ["questLines"] = { { ["id"] = 5737, ["name"] = "K'aresh - World Quests/Repeatables", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Devourers culled", ["amount"] = 12, ["type"] = 21, ["objectID"] = 4151, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[84963] = { ["id"] = 84963, ["name"] = "Sealing the Shadows", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 84956, 84957, 84958, 84959, 84960, 84961, 84963, 84964, 84965, 84967, 85003, 85039, 86835 }, ["series"] = { 84965 }, ["description"] = "No, no, no! The Shadowguard are ransacking the city and our defenses are crumbling! We even invested in new security golems after the city was last breached, but we haven't had time to activate them. Wait... I have an idea. The Shadowguard--some of them must have looted entropic cores that we can use to activate the golems. Please, you must take them down and retrieve those cores. We need to get those golems online to protect our investments! Uh, I mean, our city!", ["objectivesText"] = "Collect 5 Saturated Entropic Cores from Shadowguard within Tazavesh. Progress: Got those cores that Om'en wanted?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 233199, 238056, 238262 }, ["rewardChoices"] = { 238056, 238060, 238062, 238262 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 234601, ["x"] = 0.54, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 234601, ["x"] = 0.54, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questTurnInID"] = 234601, ["questType"] = "standard", ["sourceQuests"] = { 84960 }, ["questLines"] = { { ["id"] = 5690, ["name"] = "A Shadowy Invitation", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5690, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[84964] = { ["id"] = 84964, ["name"] = "Heroes Among Shadow", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 84956, 84957, 84958, 84959, 84960, 84961, 84963, 84964, 84965, 84967, 85003, 85039, 86835 }, ["description"] = "<name>! These people may not be my own, but we cannot stand by while the Shadowguard cut them down. You and I, we can make a difference! We need to get out there, rescue the civilians, and bring them to safety. The city may be in chaos, but we can still be the shield they need.", ["objectivesText"] = "Rescue 8 Tazavesh Civilians . Progress: The people are still out there, <name>!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 269973 }, ["rewardChoices"] = { 238188, 238191, 238194, 269973 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 234602, ["x"] = 0.493333, ["y"] = 0.646667 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 234602, ["x"] = 0.493333, ["y"] = 0.646667 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.493333, ["y"] = 0.646667 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questTurnInID"] = 234602, ["questType"] = "standard", ["sourceQuests"] = { 84960 }, ["questLines"] = { { ["id"] = 5690, ["name"] = "A Shadowy Invitation", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5690, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[84965] = { ["id"] = 84965, ["name"] = "Core Contributions", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 84956, 84957, 84958, 84959, 84960, 84961, 84963, 84964, 84965, 84967, 85003, 85039, 86835 }, ["series"] = { 84963 }, ["description"] = "The entropic cores we collected will be crucial in our defense. Use the entropic cores to activate the market guardians scattered around the city. Once reactivated, these golems will join our fight and help us push back the invaders. Time is of the essence, . The fate of Tazavesh rests in your hands.", ["objectivesText"] = "Activate 5 Market Guardians scattered around Tazavesh. Progress: Any of the guardians we activate should help stabilize the situation.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["npcID"] = 234483, ["x"] = 0.375, ["y"] = 0.399, ["mapID"] = 2472 } }, ["ends"] = { { ["npcID"] = 234483, ["x"] = 0.375, ["y"] = 0.399, ["mapID"] = 2472 } }, ["coords"] = { ["x"] = 0.375, ["y"] = 0.399, ["source"] = "quest_giver", ["mapID"] = 2472 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 84961, 84963, 84964 }, ["questLines"] = { { ["id"] = 5690, ["name"] = "A Shadowy Invitation", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5690, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[84966] = { ["id"] = 84966, ["name"] = "Break the Assault", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84966 }, ["objectivesText"] = "Shadowguard slain", ["rewardGold"] = 295000, ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.541, ["y"] = 0.637, ["mapID"] = 2472 } }, ["ends"] = { { ["x"] = 0.541, ["y"] = 0.637, ["mapID"] = 2472 } }, ["coords"] = { ["mapID"] = 2472, ["x"] = 0.541, ["y"] = 0.637 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 84960 }, ["db2Objectives"] = { { ["text"] = "Shadowguard slain", ["amount"] = 30, ["type"] = 21, ["objectID"] = 4213, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2472 },
[84967] = { ["id"] = 84967, ["name"] = "The Shadowguard Shattered", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 84956, 84957, 84958, 84959, 84960, 84961, 84963, 84964, 84965, 84967, 85003, 85039, 86835 }, ["description"] = "The commander of the Shadowguard, Shadowlord Al'zar , has assaulted this shelter of the Trust. I am preoccupied with assisting these injured brokers. I dare not leave, or their soul's energy will pour out. I must depend on you, <name>. Venture forth and eliminate Shadowlord Al'zar . His demise will cripple the Shadowguard's assault on Tazavesh. The fate of the city rests on your shoulders.", ["objectivesText"] = "Kill Shadowlord Al'zar in Tazavesh. Progress: Go. We will come as soon as we can.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 100 }, { ["id"] = 3129, ["amount"] = 2500 } }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 234620, ["x"] = 0.395333, ["y"] = 0.698333 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 234620, ["x"] = 0.395333, ["y"] = 0.698333 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.395333, ["y"] = 0.698333 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 86835 }, ["questLines"] = { { ["id"] = 5690, ["name"] = "A Shadowy Invitation", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[84971] = { ["id"] = 84971, ["name"] = "For Love of Grog", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84929, 84955, 84971, 84994, 84995, 85263, 85268, 85269, 85270, 85390, 85396, 85397, 85398, 85399, 85400, 85402, 85427, 85428, 85466, 85467, 85472, 85473, 85474, 85487, 85488, 85497, 85498, 85499, 85500, 85512, 85513, 85514, 85515, 85518, 85519, 85524, 85526, 85527, 85528, 85554, 85913, 85914, 85944, 85945, 85960, 85962, 86177, 86178, 86179, 86180, 86943, 86947, 86949, 86952 }, ["rewardXP"] = 11765, ["rewardItems"] = { 229407 }, ["starts"] = { { ["x"] = 0.446, ["y"] = 0.784, ["mapID"] = 2346 } }, ["ends"] = { { ["x"] = 0.446, ["y"] = 0.784, ["mapID"] = 2346 } }, ["coords"] = { ["mapID"] = 2346, ["x"] = 0.446, ["y"] = 0.784 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15347 } }, ["questType"] = "world", ["questLines"] = { { ["id"] = 5687, ["name"] = "Undermine - World Quests/Repeatables", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 1, ["amount"] = 30, ["objectID"] = 229407 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[84972] = { ["id"] = 84972, ["name"] = "Chipping the Void", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84972, 84973, 84974, 85018 }, ["description"] = "Greetings. I am Driruj . I think you could help with a project of mine. The nearby expanse of purple-hued crystal is ripe with potential. The void-infused glass could have many uses, from being a spell reagent to being melted down for crafts. I can't get near it myself, but someone like you will have no trouble at all! Bring me back some samples of the void glass so I can assess their worth to future buyers.", ["objectivesText"] = "Collect 6 Void Glass Samples from the Clefts of Unreality. Progress: I am preparing to move off world before what's left of K'aresh crumbles away. There are many potential uses, and therefore potential markets, for this newly created void glass. Potential equals profit, and profit means I can make a new life on a less volatile world.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229892 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231162, ["x"] = 0.766, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231162, ["x"] = 0.766, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.766, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 84967 }, ["questLines"] = { { ["id"] = 5906, ["name"] = "Avoiding the Void", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[84973] = { ["id"] = 84973, ["name"] = "Of Motes and Husks", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84972, 84973, 84974, 85018 }, ["description"] = "Regrettably, the void glass was too unstable. However, I have another idea. I believe I can stabilize the glass, but only at the moment of its creation. First, I need motes from the wyrms outside the eco-dome to power my device. While you're out there, hunt down some of those krolusks as well. Their husks can be ground down to make a pleasing beverage for which the folk in Shattrath will pay the highest of prices.", ["objectivesText"] = "Collect 4 Dune Wyrm essences and 6 Krolusk shells. Progress: Anything can be turned into profit, if you have the right market. It's all about knowing your buyers and finding that which they most desire. I still think the void glass will be the most lucrative for me, but it needs to be able to hold together more solidly.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229900, 229901 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231162, ["x"] = 0.766, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231162, ["x"] = 0.766, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.766, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 84972 }, ["questLines"] = { { ["id"] = 5906, ["name"] = "Avoiding the Void", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[84974] = { ["id"] = 84974, ["name"] = "Shards of Hope", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84972, 84973, 84974, 85018 }, ["description"] = "I still believe void-infused glass is my ticket out of here. The problem lies in the creation process itself. The motes you brought me can help stabilize the glass with the help of void energy. Lucky for us, there are numerous void surges on the edges of the glass crevasse. I have charged a device with the motes. All you need to do is channel void energy through it! Stand where a surge is about to happen and then collect the glass that's formed. Easy! Oh, it might tingle a bit...", ["objectivesText"] = "Collect 20 Void Shards. Progress: There are many potential uses, and therefore potential markets, for newly created void glass. If we can get this right, I should be set up comfortably in a new home by week's end! If you hold the device while standing in the void surges, the energy from the motes should help create more stable fragments.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229959, 236411 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231162, ["x"] = 0.766, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231162, ["x"] = 0.766, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.766, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 84973 }, ["questLines"] = { { ["id"] = 5906, ["name"] = "Avoiding the Void", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[84985] = { ["id"] = 84985, ["name"] = "Not Ready on Set", ["level"] = 10, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 84985 }, ["series"] = { 84912 }, ["description"] = "Oh <name>, I am glad to see you again. My superiors have informed me that I'm responsible not only for the guests here, but for everyone putting on celebrations! Now I'm hearing that Dapperdew in Ardenweald is trying to put on a new play and running into problems. Would you mind checking in on the situation? I can hardly manage this celebration, let alone whatever is happening in the Shadowlands.", ["objectivesText"] = "Find Dapperdew in Ardenweald.", ["rewardGold"] = 29200, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232406, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232407, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232408, ["x"] = 0.63, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 171743, ["x"] = 0.415, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71, 1565 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 83831 }, ["db2LabelIDs"] = { 4018, 4063 }, ["db2QuestSortName"] = "Nightborne" },
