[85001] = { ["id"] = 85001, ["name"] = "Blessings Be Upon You", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 84996, 84997, 84998, 85001, 85002, 92405 }, ["series"] = { 85002, 85011, 85151, 85155, 85804 }, ["description"] = "These innocents were simply trying to clean up the ruins, but the cultists are slaughtering them. We must come to their aid! Champion, I am certain that you and I can do this if we work together.", ["objectivesText"] = "Help Arator to rescue 8 Dalaran Custodians from the clutches of the Twilight's Blade. Progress: These poor souls are imperiled through no fault of their own!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 233312, ["x"] = 0.266, ["y"] = 0.424 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 233312, ["x"] = 0.266, ["y"] = 0.424 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.266, ["y"] = 0.424 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 84997 }, ["questLines"] = { { ["id"] = 5707, ["name"] = "Radiant Visions", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5707, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[85002] = { ["id"] = 85002, ["name"] = "Off to Tazavesh", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 84996, 84997, 84998, 85001, 85002, 92405 }, ["series"] = { 85001, 85011, 85151, 85155, 85804 }, ["description"] = "It's imperative we seek my mother's counsel. But before we can do that, we'll have to find her. Last I heard, she was out hunting in the Great Dark Beyond on a world known as K'aresh. Lucky for us, I thought ahead and asked Khadgar for a portal scroll to go directly there. I'll meet you on the other side.", ["objectivesText"] = "Regroup with Arator in Tazavesh, the Veiled Market, on K'aresh.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 233312, ["x"] = 0.266, ["y"] = 0.424 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 231266, ["x"] = 0.602, ["y"] = 0.915 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.266, ["y"] = 0.424 }, ["mapCandidates"] = { ["npc"] = { 2248, 2472 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 84998, 85001 }, ["questLines"] = { { ["id"] = 5707, ["name"] = "Radiant Visions", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5707, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2472 },
[85003] = { ["id"] = 85003, ["name"] = "Restoring Operational Efficiency", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 84956, 84957, 84958, 84959, 84960, 84961, 84963, 84964, 84965, 84967, 85003, 85039, 86835 }, ["description"] = "Locus-Walker was brought into the Trust to handle such a violent crisis of the Void. He says you are some kind of hero or champion. Good. We are in need of such a thing. Tazavesh is under threat from the Void. The Shadowguard! They threaten the work of the Trust and my reputation as an administrator.", ["objectivesText"] = "Help the brokers of Tazavesh by assisting with their issues.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 230604, ["x"] = 0.578857, ["y"] = 0.776286 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 230604, ["x"] = 0.578857, ["y"] = 0.776286 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.578857, ["y"] = 0.776286 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 84957 }, ["questLines"] = { { ["id"] = 5690, ["name"] = "A Shadowy Invitation", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5690, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[85005] = { ["id"] = 85005, ["name"] = "A Radiant Call", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14838, ["mapID"] = 2339, ["storyline"] = { 85005 }, ["description"] = "I have an urgent missive for $p from Mylton Wyldbraun , second in command of the Flame's Radiance! Hallowfall requires what strength we can muster and the Flame's Radiance seeks volunteers to join the fight against the remaining Sureki forces. Please report to Wyldbraun without delay.", ["objectivesText"] = "Meet Mylton Wyldbraun at the Flame's Radiance camp in Hallowfall .", ["rewardItems"] = { 233288 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 242126, ["x"] = 0.46, ["y"] = 0.494 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = { 2215, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 62, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[85006] = { ["id"] = 85006, ["name"] = "Those We Have Lost", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85006 }, ["description"] = "Ah, traveler! This was one of the first locations to show a response to our attempts to rejuvenate the land. We're actively studying why it happened at this location in particular. I have another experiment I wish to run, but I need some extra sources of power. The souls that litter the dunes are unfortunately lost, but we may let them serve one last time by using their energy.", ["objectivesText"] = "Collect Flickering Essence . Progress: How did the collecting go?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229969 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231314, ["x"] = 0.514, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231314, ["x"] = 0.514, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 84967 } },
[85007] = { ["id"] = 85007, ["name"] = "Extended Reach", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85007 }, ["description"] = "I'm very curious on why the influence of this restoration stopped where it did, as are my fellow colleagues. We set up some devices at the edge of the dunes to track the fluctuation in various energy types. They have probably sat out there long enough for an initial reading. Could you go gather that info for me?", ["objectivesText"] = "Gather readings from the Broker Pylons. Progress: Hopefully the devices were easy to find?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231314, ["x"] = 0.514, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231314, ["x"] = 0.514, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 84967 } },
[85008] = { ["id"] = 85008, ["name"] = "Machinations of Memory", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85008 }, ["description"] = "Well, the readings aren't anything to be concerned about... So we'll move on to the next step of my experiment. This console here is the central piece of our system to rejuvenate the area. I'm hoping that if we hook it up to a significant charge, it may stabilize the area even more. Could you help me set up the energy containers as I adjust the machine?", ["objectivesText"] = "Interact with the console. Progress: Yes?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231314, ["x"] = 0.514, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231314, ["x"] = 0.514, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 85006, 85007 } },
[85009] = { ["id"] = 85009, ["name"] = "Those We Have Yet to Save", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85009 }, ["description"] = "The fauna here seem to be the same in shape as what would have been found nearby when K'aresh was still intact, but they are acting rather oddly for their species. I wonder if we could give them one last push and fully bring them into being. Take the last of the energy. I have a device that should let you channel it into them.", ["objectivesText"] = "Recharge 6 Flickering Ephemera . Progress: Have you finished our experiment?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 230730, 245705, 245706 }, ["rewardChoices"] = { 245705, 245706 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 15 }, { ["id"] = 3008, ["amount"] = 15 }, { ["id"] = 3129, ["amount"] = 350 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231314, ["x"] = 0.514, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231314, ["x"] = 0.514, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 84967 } },
[85011] = { ["id"] = 85011, ["name"] = "Where in K'aresh is Alleria Windrunner?", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 85011, 85151, 85155, 85184, 85185, 85186, 85196, 85212, 85213, 85214, 85804 }, ["series"] = { 85001, 85002, 85151, 85155, 85804 }, ["description"] = "While you were on your way, I took the liberty to ask around. These brokers seem friendly enough, but be warned... part of the city is still under attack by a group of ethereals known as the Shadowguard. I managed to get a lead on a few traders who might have crossed paths with my mother recently. We should go before her trail runs cold.", ["objectivesText"] = "Discover the location of Alleria Windrunner by asking around Tazavesh, the Veiled Market. Progress: <Umbric looks at you with curiosity.>", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 231266, ["x"] = 0.602, ["y"] = 0.915 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 234263, ["x"] = 0.5145, ["y"] = 0.1955 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.915 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 85002 }, ["questLines"] = { { ["id"] = 5708, ["name"] = "A Meeting with Minn'da", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5708, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2472 },
[85018] = { ["id"] = 85018, ["name"] = "Packets of Promises", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84972, 84973, 84974, 85018 }, ["description"] = "I will not wait a moment longer. I have arranged for transport outside of the dome, and it will be arriving soon. Will you meet me outside? I have one last thing I would ask of you.", ["objectivesText"] = "Talk to Driruj . Progress: Driruj is a fool! He's likely to burn through his wrappings with his hot-headedness. He'll be back.", ["rewardGold"] = 232300, ["rewardXP"] = 8825, ["rewardItems"] = { 229905, 245721, 245722, 245723, 245724 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 15 }, { ["id"] = 3008, ["amount"] = 15 }, { ["id"] = 3129, ["amount"] = 350 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231162, ["x"] = 0.766, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231161, ["x"] = 0.765, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.766, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 84974 }, ["questLines"] = { { ["id"] = 5906, ["name"] = "Avoiding the Void", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[85019] = { ["id"] = 85019, ["name"] = "An Outcast's Request", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85019, 85020, 85021, 85022 }, ["description"] = "I felt it. Something happened in that dome. Something--no... someone... My friend, I do not know your name or where you came from, but this is it! It has to be! The ruined town of Sufaad to the southeast of here was where I resided as a Wastelander. Please go there and bring back my scepter, prayer book, and ceremonial bowl. There was no time to pack. I just ran, so the items could be anywhere within the town.", ["objectivesText"] = "Retrieve Outcast Hizfran 's belongings from North Sufaad. Progress: Once I have my belongings, I will be able to walk the path of the old ways. It is time to retake my true oath.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229893, 229895, 229902 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231422, ["x"] = 0.776, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231422, ["x"] = 0.776, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.776, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5970, ["name"] = "Priest of the Old Ways", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[85020] = { ["id"] = 85020, ["name"] = "The Blood of K'aresh", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85019, 85020, 85021, 85022 }, ["description"] = "In the old days, we used certain deep-mined salts in cleansing processes and rituals. As you can see around you, mining is no longer valid, as these fragile rocks are hanging on to each other. On the day of the Devouring of K'aresh , a never-before-seen mineral surfaced. The Blood of K'aresh is a blue mineral with some deposits to the west of here. Even though K'aresh is dying, I should follow the old traditions to the end. Please collect deposits from sand striders or veins and bring them to me.", ["objectivesText"] = "Collect 20 Blood of K'aresh deposits . Progress: Although the Blood of K'aresh may not have existed prior to the Devouring like other minerals, it came from within our world and thus should still be usable for the process.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229970 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231422, ["x"] = 0.776, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231422, ["x"] = 0.776, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.776, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 85019 }, ["questLines"] = { { ["id"] = 5970, ["name"] = "Priest of the Old Ways", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[85021] = { ["id"] = 85021, ["name"] = "Cleansing the Void", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85019, 85020, 85021, 85022 }, ["description"] = "Now that you have brought me all that I need, the ritual of return can begin. You see, stranger, the items you recovered were stowed in my hovel for over a hundred thousand years. The Void that surrounds us leaves its mark on everything it touches. While grinding the mineral removed the impurities of the Void, I still need to cleanse myself and the items. Please help me with the ritual. I do not foresee any distractions or issues. We are very close now.", ["objectivesText"] = "Help Outcast Hizfran with the ritual of return. Progress: Almost there, stranger... <name>. That is your name, is it not?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231422, ["x"] = 0.776, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231699, ["x"] = 0.778, ["y"] = 0.395 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.776, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 85020 }, ["questLines"] = { { ["id"] = 5970, ["name"] = "Priest of the Old Ways", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[85022] = { ["id"] = 85022, ["name"] = "Priest of the Old Ways", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85019, 85020, 85021, 85022 }, ["description"] = "<name>, I suspect that a living manifestation of the Void came out of myself and the items. I cannot, with good conscience, take on the mantle of a priest of the old ways while these manifestations are out there. I have a final request for you. Go find these creatures and slay them. Then, I will be able to reassume the mantle of priest.", ["objectivesText"] = "Slay 3 void manifestations. Progress: One step, <name>. One last step.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 245707, 245708, 245709, 245710 }, ["rewardCurrencies"] = { { ["id"] = 3129, ["amount"] = 350 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231699, ["x"] = 0.778, ["y"] = 0.395 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231774, ["x"] = 0.778, ["y"] = 0.392 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.778, ["y"] = 0.395 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 85021 }, ["questLines"] = { { ["id"] = 5970, ["name"] = "Priest of the Old Ways", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[85024] = { ["id"] = 85024, ["name"] = "Toy Trouble", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 85024 }, ["series"] = { 85025 }, ["description"] = "Adventurer, Maru is once again in need of your aid. She has an urgent matter that she would like to discuss with you.", ["objectivesText"] = "Speak with Maru .", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232405, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232406, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232407, ["x"] = 0.63, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226684, ["x"] = 0.632, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 84336 }, ["db2LabelIDs"] = { 4063 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71, ["db2QuestSortName"] = "Nightborne" },
[85025] = { ["id"] = 85025, ["name"] = "Operation Toy Rescue", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 85025 }, ["series"] = { 85024 }, ["description"] = "A sneaky thief has taken some of my friends' toys! You're a good sleufer now, right? Can you help my friend Yennu find his stolen toy? You'll find him on da Dragon Isles.", ["objectivesText"] = "Find the missing toys.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 228791, 228795, 229908, 229991 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 5 }, { ["id"] = 3100, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226684, ["x"] = 0.632, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226684, ["x"] = 0.632, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 85024 }, ["db2LabelIDs"] = { 4061, 4063 }, ["db2QuestSortName"] = "Nightborne" },
[85026] = { ["id"] = 85026, ["name"] = "Where Legends are Made", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 1637, ["mapID"] = 84, ["storyline"] = { 84423, 84424, 85026 }, ["series"] = { 84424 }, ["description"] = "There's so much to catch you up on <name>! Where do you want to start?", ["objectivesText"] = "Select a Timewalking Campaign from Chromie . Progress: Oooh, that one is my favorite!", ["rewardGold"] = 312800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 167032, ["x"] = 0.561, ["y"] = 0.174 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 167032, ["x"] = 0.561, ["y"] = 0.174 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.561, ["y"] = 0.174 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["sourceQuests"] = { 84424 }, ["questLines"] = { { ["id"] = 5676, ["name"] = "Adventure Awaits", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85 },
[85027] = { ["id"] = 85027, ["name"] = "Lorewalking: The Protectorate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 84, ["storyline"] = { 10339, 10384, 10385, 10406, 10408, 10437, 10439, 47203, 47217, 47218, 47219, 63855, 63895, 63976, 63977, 63979, 63980, 63982, 63983, 63984, 63985, 85027, 85028, 85029, 85035, 85036 }, ["description"] = "I have long been curious about the ethereals, who first came to Pandaria when the Mists parted. A mysterious group, they are reticent to speak of their history... but I am perhaps more persistent than most in my inquiries. So! Who are these strangers? What do we know of their history? We must piece it together, it seems. But our tale begins in Outland, where a hero joined a group of ethereals in Netherstorm to aid them with their cause.", ["objectivesText"] = "Follow Cho's guidance to learn about the ethereals.", ["rewardGold"] = 1024800, ["rewardXP"] = 2125, ["rewardItems"] = { 242386, 244888, 245567, 245631 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3107, ["amount"] = 3 }, { ["id"] = 3284, ["amount"] = 3 } }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 232441, ["x"] = 0.642, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 232441, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 14771 } }, ["questTurnInID"] = 232441, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5691, ["name"] = "Lorewalking: Ethereals", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 268, ["title"] = "Lorewalking: The Ethereals", ["questLineID"] = 5691, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[85028] = { ["id"] = 85028, ["name"] = "Lorewalking: The Brokers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 10565, ["mapID"] = 84, ["storyline"] = { 10339, 10384, 10385, 10406, 10408, 10437, 10439, 47203, 47217, 47218, 47219, 63855, 63895, 63976, 63977, 63979, 63980, 63982, 63983, 63984, 63985, 85027, 85028, 85029, 85035, 85036 }, ["description"] = "The ethereals are most fascinating indeed, but in my studies I have encountered another race of creatures who share many similarities with the ethereals. I feel we should speak of them as well--the brokers. They share a nomadic nature, a desire to collect rare and unusual antiquities, and a penchant for trade. Yet the brokers do not exist on Azeroth. Instead, they dwell in the Shadowlands... the land of death.", ["objectivesText"] = "Follow Cho's guidance to learn about the brokers.", ["rewardGold"] = 876300, ["rewardXP"] = 2125, ["rewardItems"] = { 242386, 244888, 245567, 245631 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3107, ["amount"] = 3 }, { ["id"] = 3284, ["amount"] = 3 } }, ["starts"] = { { ["x"] = 0.284, ["y"] = 0.472, ["mapID"] = 882, ["npcID"] = 231702 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 232441, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 10565 } }, ["questGiverID"] = 231702, ["questType"] = "standard", ["sourceQuests"] = { 85029 }, ["questLines"] = { { ["id"] = 5691, ["name"] = "Lorewalking: Ethereals", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 268, ["title"] = "Lorewalking: The Ethereals", ["questLineID"] = 5691, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[85029] = { ["id"] = 85029, ["name"] = "Lorewalking: Locus-Walker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 10339, 10384, 10385, 10406, 10408, 10437, 10439, 47203, 47217, 47218, 47219, 63855, 63895, 63976, 63977, 63979, 63980, 63982, 63983, 63984, 63985, 85027, 85028, 85029, 85035, 85036 }, ["description"] = "While the Protectorate of Outland may have stopped Dimensius and Salhadaar, the Ethereum remained. And as Salhadaar had wished, they chose to embrace the Void. Not just embrace it--become it. It twisted them into shadows of themselves, consumed with the pursuit of power. But there was one ethereal, Locus-Walker, that sought to harness the Void for more altruistic purposes. His history is entwined with an elf from our world--Alleria Windrunner.", ["objectivesText"] = "Follow Cho's guidance to learn about void ethereals.", ["rewardGold"] = 548280, ["rewardXP"] = 2125, ["rewardItems"] = { 242386, 244888, 245567, 245631 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3107, ["amount"] = 3 }, { ["id"] = 3284, ["amount"] = 3 } }, ["starts"] = { { ["x"] = 0.601, ["y"] = 0.317, ["mapID"] = 109, ["npcID"] = 231702 } }, ["ends"] = { { ["x"] = 0.601, ["y"] = 0.317, ["mapID"] = 109, ["npcID"] = 231702 } }, ["coords"] = { ["mapID"] = 109, ["x"] = 0.601, ["y"] = 0.317 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15969 } }, ["questGiverID"] = 231702, ["questTurnInID"] = 231702, ["questType"] = "standard", ["sourceQuests"] = { 85027 }, ["questLines"] = { { ["id"] = 5691, ["name"] = "Lorewalking: Ethereals", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 268, ["title"] = "Lorewalking: The Ethereals", ["questLineID"] = 5691, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[85032] = { ["id"] = 85032, ["name"] = "What Is Left of Home", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 84855, 84856, 84857, 84858, 84859, 84860, 84861, 84862, 84863, 84864, 84865, 84866, 85032, 85961, 86495, 86946, 90517 }, ["series"] = { 84855, 85961, 93979 }, ["description"] = "Dimensius threatens us once more. There is no one who knows his methods better than his former Harbinger, Xal'atath . I would not say we can trust her, but we can work with her. She fears the All-Devouring's wrath after her betrayal. We can't afford to turn away any potential ally. Think how many we will save from the Void Lord's hunger. Get your bearings in this city the four of us saved together. I will convince Alleria.", ["objectivesText"] = "Speak to citizens of Tazavesh and members of the Trust. Progress: There will be a day when K'aresh is restored.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 231128, ["x"] = 0.376, ["y"] = 0.745333 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 230700, ["x"] = 0.342, ["y"] = 0.108 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.376, ["y"] = 0.745333 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 84967 }, ["questLines"] = { { ["id"] = 5733, ["name"] = "Void Alliance", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5733, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[85035] = { ["id"] = 85035, ["name"] = "Locus-Walker, Telogrus Ranger", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 84, ["storyline"] = { 10339, 10384, 10385, 10406, 10408, 10437, 10439, 47203, 47217, 47218, 47219, 63855, 63895, 63976, 63977, 63979, 63980, 63982, 63983, 63984, 63985, 85027, 85028, 85029, 85035, 85036 }, ["description"] = "I apologize for interrupting your conversation, mortal. But it was your discussion that drew Ve'nari's attention. She hears much, after all--especially when her name is involved. I have been sent with an object for you to deliver to Locus-Walker . He is an ethereal that dwells within Telogrus Rift. I believe the \"void elves\" of your world also reside there. There is no need to travel. I will provide a portal to where you must go. Will you assist her in this task?", ["objectivesText"] = "Deliver Ve'nari's device to Locus-Walker in Telogrus Rift. Progress: Why have the Shadowguard come here, of all places?", ["rewardGold"] = 292100, ["rewardXP"] = 1415, ["rewardItems"] = { 231831 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 234111, ["x"] = 0.64, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 234111, ["x"] = 0.64, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 14771 } }, ["questTurnInID"] = 234111, ["questType"] = "standard", ["sourceQuests"] = { 85028 }, ["questLines"] = { { ["id"] = 5691, ["name"] = "Lorewalking: Ethereals", ["orderIndex"] = 24, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 268, ["title"] = "Lorewalking: The Ethereals", ["questLineID"] = 5691, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1865, ["db2PoiUiMapID"] = 971 },
[85036] = { ["id"] = 85036, ["name"] = "Veni Vidi Ve'nari", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 9415, ["mapID"] = 84, ["storyline"] = { 10339, 10384, 10385, 10406, 10408, 10437, 10439, 47203, 47217, 47218, 47219, 63855, 63895, 63976, 63977, 63979, 63980, 63982, 63983, 63984, 63985, 85027, 85028, 85029, 85035, 85036 }, ["description"] = "A broker sent you with this device? And they were sent to you by Ve'nari? This does not bode well.", ["objectivesText"] = "Witness the conversation with Locus-Walker . Progress: I have much to think about, my friend--and much to add to my studies!", ["rewardGold"] = 151900, ["rewardXP"] = 710, ["rewardItems"] = { 242386, 244843, 245567 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 25 }, { ["id"] = 3107, ["amount"] = 10 }, { ["id"] = 3284, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.275, ["y"] = 0.283, ["mapID"] = 971, ["npcID"] = 231706 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 232441, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9415 } }, ["questGiverID"] = 231706, ["questType"] = "standard", ["sourceQuests"] = { 85035 }, ["questLines"] = { { ["id"] = 5691, ["name"] = "Lorewalking: Ethereals", ["orderIndex"] = 25, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 268, ["title"] = "Lorewalking: The Ethereals", ["questLineID"] = 5691, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[85037] = { ["id"] = 85037, ["name"] = "That's a Wrap", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 83126, 83127, 83128, 83129, 84856, 84857, 84862, 84863, 84864, 84865, 84866, 84967, 85037, 85449, 85450, 86495, 86820, 86946, 90517, 91871, 93979 }, ["description"] = "The possibilities have begun to narrow. We are on the cusp of victory. Are you ready, my champion, to fulfill your oath against Dimensius? < Xal'atath chuckles.> Very well. I have some promises of my own to keep. Let us formalize our defense against Dimensius by the platform toward the manaforge.", ["objectivesText"] = "Speak to Xal'atath to assemble the Reshii Ribbons . Progress: What is Xal'atath 's game here? She had ample opportunity to trick us.", ["rewardGold"] = 929400, ["rewardXP"] = 17650, ["rewardCurrencies"] = { { ["id"] = 3129, ["amount"] = 2500 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231520, ["x"] = 0.442, ["y"] = 0.184 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231522, ["x"] = 0.428, ["y"] = 0.215 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.184 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 84906 }, ["questLines"] = { { ["id"] = 5696, ["name"] = "Shadows En Garde", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 19, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5696, ["questLineOrder"] = 3 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5696, ["questLineOrder"] = 3 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[85039] = { ["id"] = 85039, ["name"] = "Compromised Containment", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 84956, 84957, 84958, 84959, 84960, 84961, 84963, 84964, 84965, 84967, 85003, 85039, 86835 }, ["description"] = "Somehow, an artifact in the Menagerie has broken open, unleashing a swarm of furious arcane creatures. They're wreaking havoc, and havoc is bad for the project. I need someone capable of getting this situation under control with no questions asked. If you can get down there, clear your way through the creatures, and seal that artifact... I'll make it worth your while.", ["objectivesText"] = "Kill Arcane Creatures and seal the Unstable Artifact . Progress: Have you completed your assignment?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237891, 237894 }, ["rewardChoices"] = { 237891, 237894 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 231564, ["x"] = 0.565, ["y"] = 0.7255 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 231564, ["x"] = 0.565, ["y"] = 0.7255 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.7255 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 84957 }, ["questLines"] = { { ["id"] = 5690, ["name"] = "A Shadowy Invitation", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5690, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[85042] = { ["id"] = 85042, ["name"] = "The Final Toy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 85042 }, ["series"] = { 85043 }, ["description"] = "Maru discovered that one of her toys is now missing! Could this be related to the other missing toys that you previously helped her friends with?", ["objectivesText"] = "Speak with Maru .", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232405, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232406, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232407, ["x"] = 0.63, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226684, ["x"] = 0.632, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 85025 }, ["db2LabelIDs"] = { 4063 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71, ["db2QuestSortName"] = "Nightborne" },
