[85047] = { ["id"] = 85047, ["name"] = "A Pirate Predicament", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["series"] = { 85060 }, ["description"] = "I was recently made aware of a small group of Booty Bay Buccaneers who have landed and set up camp just outside the celebration area to the north. Pirates aren't inherently a problem, per se, but they do introduce an element of chaotic unpredictability. I know you're busy, but would you mind checking on them to see if they need any assistance?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["npcID"] = 232405, ["x"] = 0.63, ["y"] = 0.502, ["mapID"] = 71 }, { ["npcID"] = 232406, ["x"] = 0.63, ["y"] = 0.502, ["mapID"] = 71 }, { ["npcID"] = 232407, ["x"] = 0.63, ["y"] = 0.502, ["mapID"] = 71 }, { ["npcID"] = 232408, ["x"] = 0.63, ["y"] = 0.502, ["mapID"] = 71 } }, ["ends"] = { { ["npcID"] = 231413, ["x"] = 0.608, ["y"] = 0.448, ["mapID"] = 71 } }, ["coords"] = { ["x"] = 0.63, ["y"] = 0.502, ["source"] = "quest_giver", ["mapID"] = 71 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 84756, 85043 } },
[85051] = { ["id"] = 85051, ["name"] = "Beach Comber", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "There's a peculiar mechanical gnome scouring the beach nearby for valuable scrap metals. I am concerned for his safety but also intrigued. I just wonder what he's trying to find! Maybe he would be willing to share anything he finds in exchange for your assistance... Could you aid him in recovering any valuable items?", ["objectivesText"] = "Assist Kerchunk in his search for 24 Salvageable Scrap Progress: Have you found any Salvageable Scrap ? I'm looking for all I can find.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229967 }, ["rewardCurrencies"] = { { ["id"] = 3090, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 231783, ["x"] = 0.416, ["y"] = 0.683 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 231783, ["x"] = 0.416, ["y"] = 0.683 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.683 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 84725 }, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 15, ["flags"] = 0 } }, ["db2PoiMapID"] = 2127, ["db2PoiUiMapID"] = 2369 },
[85052] = { ["id"] = 85052, ["name"] = "A Lucrative Opportunity", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 85052, 85053, 85054, 85055 }, ["description"] = "Most fortuitous greetings, offworlder! I have been stuck for an eon at this post checking manifests one after another. This is not real trade. Real trade is done on the streets of Tazavesh! It just so happens that a contact of mine from your world was unloading waste cargo. I bought the whole supply. Expired storage contracts of some sort. However, I know better than to be trading without a permit. It would bring good fortune to my endeavor to have your help with this. Can I count on you, <race>?", ["objectivesText"] = "Seek out Cartel Boss Xy'eolm in Tazavesh on K'aresh .", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 231674, ["x"] = 0.48, ["y"] = 0.245 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 232008, ["x"] = 0.503, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.245 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 84967 }, ["questLines"] = { { ["id"] = 5695, ["name"] = "Lost and Found Storage", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2472, ["db2QuestHubAreaPoiID"] = 8385 },
[85053] = { ["id"] = 85053, ["name"] = "Obtaining Permits", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 85052, 85053, 85054, 85055 }, ["description"] = "There is a difference between securing a permit and securing permission to sell in Tazavesh. Xy'vez is a licensed dealer. He can buy and sell as he pleases in accordance with the authorities. However, I am glad he knows his place. If you are on my streets, you need my permission. Not everyone knows this. Cartel Ba likes to test the waters. I'll award your permission if you teach them a lesson.", ["objectivesText"] = "Obtain permission for Vaultkeeper Xy'vez in Tazavesh. Progress: Have you done what I asked?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 232008, ["x"] = 0.503, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 232008, ["x"] = 0.503, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 85052 }, ["questLines"] = { { ["id"] = 5695, ["name"] = "Lost and Found Storage", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2472 },
[85054] = { ["id"] = 85054, ["name"] = "Articles of Acquisition", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 85052, 85053, 85054, 85055 }, ["description"] = "Take this ledger to Xy'vez. Let him know I expect dinars upfront and on time. There are to be no discrepencies between my records and his, do you understand? You may head to the market to inform him. Knowing traders like him, he'll have already found a spot to set up shop. This venture has my blessing. Don't let it become unprofitable or we'll be seeing each other again, offworlder.", ["objectivesText"] = "Return to Vaultkeeper Xy'vez in the market of Tazavesh on K'aresh . Progress: Do we have good news, offworlder?", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 244847 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 232008, ["x"] = 0.503, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 232057, ["x"] = 0.448, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 85053 }, ["questLines"] = { { ["id"] = 5695, ["name"] = "Lost and Found Storage", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[85055] = { ["id"] = 85055, ["name"] = "Expired Goods", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 85052, 85053, 85054, 85055 }, ["description"] = "Now then, on to business. I hear tale that your world is full of heroes on adventure. And where there's adventurers, there's need for storing their treasures. Always. Thus, you have turned to our kin to keep them safely deposited between realms. Yet not one of you read the contract. We have since ceased such services and returned goods to their owners. You and I, <name>, are selling opportunities to purchase what remains. Blind of course. Help me prepare.", ["objectivesText"] = "Help Vaultkeeper Xy'vez prepare the void storage vaults for sale in Tazavesh on K'aresh . Progress: Always so much to prepare before a first sale.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 1604, 11122, 22589, 22726, 50818, 185824, 190005, 190006, 190007, 190008, 245725, 245726, 245727, 245728 }, ["rewardCurrencies"] = { { ["id"] = 3129, ["amount"] = 350 } }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 232057, ["x"] = 0.448, ["y"] = 0.356 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 232057, ["x"] = 0.448, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.356 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 85054 }, ["questLines"] = { { ["id"] = 5695, ["name"] = "Lost and Found Storage", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[85059] = { ["id"] = 85059, ["name"] = "A Piece of the Action", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 85059 }, ["description"] = "Game on table look like fun. But Skaggit no want Jack to play. Maybe you can? Sneak in and put a bet down. We see who wins!", ["objectivesText"] = "Contribute to an event on the Siren Isle Command Map. Progress: Did you put down a bet?", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3090, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 227817, ["x"] = 0.6948, ["y"] = 0.444 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 227817, ["x"] = 0.6948, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.6948, ["y"] = 0.444 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 84725 } },
[85060] = { ["id"] = 85060, ["name"] = "Pirate Foods and Superstitions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 85060 }, ["series"] = { 85047 }, ["description"] = "Our trusty cook, Cooktholomew, was lost at sea. Quite tragic that was, but now all the more tragic for us here! We don't dare set sail again without the lucky feast ol' Cooktholomew would prepare for us before each voyage. We've tried to make out his scribbles, but alas, we only managed to make the ink run. Me matey here swears he heard Cooktholomew say once he only brought copies out to sea. If that be true, the originals must be back in Booty Bay, somewhere near his bunk!", ["objectivesText"] = "Help the Booty Bay Buccaneers figure out how to recreate Cooktholomew's lucky feast. Progress: Cooktholomew and I have spun many a yarn talking about words and language. He was a lot deeper than most folk around here gave him credit for.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 229968, 231263 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 5 }, { ["id"] = 3100, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 231413, ["x"] = 0.608, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 105637, ["x"] = 0.4152, ["y"] = 0.704533 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 71, 210 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 85047 }, ["db2LabelIDs"] = { 4061, 4063 }, ["db2QuestSortName"] = "Nightborne" },
[85071] = { ["id"] = 85071, ["name"] = "Skyrocketing Sprint", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 85071 }, ["description"] = "Fly through the checkpoint rings marking the course. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(85071)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(85071))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Glide through the rings.", ["rewardXP"] = 9515, ["rewardItems"] = { 188134 }, ["starts"] = { { ["x"] = 0.39, ["y"] = 0.287, ["mapID"] = 2346, ["npcID"] = 231793 } }, ["ends"] = { { ["x"] = 0.39, ["y"] = 0.287, ["mapID"] = 2346, ["npcID"] = 231793 } }, ["coords"] = { ["mapID"] = 2346, ["x"] = 0.39, ["y"] = 0.287 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15347 } }, ["questGiverID"] = 231793, ["questTurnInID"] = 231793, ["questType"] = "standard" },
[85075] = { ["id"] = 85075, ["name"] = "To Stormsong", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["series"] = { 87340 }, ["description"] = "We have need of more species to help pollinate. I have studied your world, and I believe your bees in Stormsong Valley will be best. Not the fire ones though. Too dangerous. Bring back some bees and we can see if they are suitable. Take this communicator in case I need to contact you.", ["objectivesText"] = "Travel to Stormsong Valley in Kul Tiras to get some bees for Ve'nari . Progress: Where did you come from?", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 167744, 169614, 202046, 230030 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 942, 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 87340 }, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942 },
[85076] = { ["id"] = 85076, ["name"] = "Don't Bee Crazy", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 942, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["description"] = "Something is agitating the bees, and I suspect it's these honey-crazed maulers ! Take some down and see if it helps. Even if it doesn't, you're doing the world a favor. They are completely out of control!", ["objectivesText"] = "Slay 10 maulers in the Highland Flats and Mildenhall Meadery. Progress: The poor bees...", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["sourceQuests"] = { 85075 }, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942 },
[85077] = { ["id"] = 85077, ["name"] = "Sticky Fingers", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 942, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["description"] = "Stormsong has some of the biggest and best pollinators on Azeroth--when they aren't angry at least. If you are looking to take these, you'll need to try to calm them down. It looks like their honey is being stolen. Try to take some honey back from those honey... blob... things? Can't hurt right? Sorry. I'm more of a plant person than a bee person. They just come with the territory!", ["objectivesText"] = "Collect 7 Honey Globules at the Mildenhall Meadery. Progress: Did you get the honey?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 230053 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["sourceQuests"] = { 85075 }, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942 },
[85078] = { ["id"] = 85078, ["name"] = "Bee in the Bonnet", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 942, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["description"] = "While you were out, I scouted some of the smaller bee hives . They all look like they've suffered damage. We should investigate them. Maybe that's the cause of their aggression?", ["objectivesText"] = "Investigate 4 Bee Hives . Progress: What could have driven something to destroy so many hives?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["sourceQuests"] = { 85076, 85077 }, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942 },
[85079] = { ["id"] = 85079, ["name"] = "Such a Sleebee-head", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 942, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["description"] = "We need to deal with the hive guardians one way or another if we are going to investigate this place. I do hope we don't have to kill them.", ["objectivesText"] = "Tranquillize or slay 5 Hive Guardians . Progress: We should keep as many bees alive as possible.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 230210 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["sourceQuests"] = { 85076, 85077 }, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942 },
[85080] = { ["id"] = 85080, ["name"] = "An Un-Bee-lievable Solution", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 942, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["series"] = { 85081, 85082, 85249 }, ["description"] = "If we can save the smaller bees, they can join the queen's colony. I just wish we had some way of capturing or transporting them. Do you have any ideas? Perhaps that friend of yours has something? If you come across any of the larger bees... I worry they may be beyond saving. Do what you have to do.", ["objectivesText"] = "Collect the Anima Vacuum and use it to vacuum up 15 Honey Bees. Progress: Have you rescued the bees?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229424 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 85078, 85079 }, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942 },
[85081] = { ["id"] = 85081, ["name"] = "Beehemian Rhapsody", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 942, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["series"] = { 85080, 85082, 85249 }, ["description"] = "We need a way to lure out the queen so we can take her away from here. Oh! The honey you gathered earlier! Put that out to lure her, then catch her in this ventilated jar. You said you were after bees? I think she'd be a great fit.", ["objectivesText"] = "Place the Honey Pot and use it to lure out and rescue the Queen Bee. Progress: If we can get her to safety, and bring some of her hive, they can rebuild.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 230549 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["sourceQuests"] = { 85078, 85079 }, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942 },
[85082] = { ["id"] = 85082, ["name"] = "To K'aresh", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 942, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["series"] = { 85080, 85081, 85249 }, ["description"] = "We've secured the queen and apparently sent some bees to K'aresh. So... How do we get there?", ["objectivesText"] = "Return to the Oasis on K'aresh.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 942, 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 85080, 85081 }, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[85083] = { ["id"] = 85083, ["name"] = "Photogra-Bee", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 942, ["storyline"] = { 85075, 85076, 85077, 85078, 85079, 85080, 85081, 85082, 85083, 85084, 85249, 85255, 85256, 85257, 85258, 85259, 85260, 85261, 85262, 89348 }, ["series"] = { 85084, 85257 }, ["description"] = "The bees seem to be doing very well in this new environment. They are even starting to pollinate the plants here. We should document it. It's not science if you don't write it down. You'll find them mostly around the plants.", ["objectivesText"] = "Document 10 Honey Bees. Progress: Have you documented the bees?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 230729 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 231919, ["x"] = 0.725, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 85249 }, ["questLines"] = { { ["id"] = 5693, ["name"] = "The Bees Knees", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5693, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
