[85383] = { ["id"] = 85383, ["name"] = "Applied Mixology", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 85383, 85384, 85394 }, ["description"] = "Allow me to introduce myself, traveler. I am known as Ba'kril. As you know, my people do not imbibe as yours do. My proposal is simple: help me concoct a new energy drink and I shall allow you to use it free of charge. It will most certainly make you a hero amongst heroes. Is that not worth the risk? I have acquired various potent energy sources. Infuse them into the berry juice cocktail and let us see how potent we can make it.", ["objectivesText"] = "Concoct an energy drink infused with various power sources. Progress: On the soul of K'aresh , I make my oath to you, traveler. We will create the finest, most powerful infused concoction ever seen. With it, you will have the power of ten devourers! <Ba'kril grumbles something under his breath about Tazavesh's leadership.> Of course, there will be just a pinch of profit on the side for me.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 232351, ["x"] = 0.437, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 232351, ["x"] = 0.437, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.437, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 84967 }, ["questLines"] = { { ["id"] = 5699, ["name"] = "That Tazavesh Taste", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2472, ["db2QuestHubAreaPoiID"] = 8385 },
[85384] = { ["id"] = 85384, ["name"] = "Market Research", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 85383, 85384, 85394 }, ["description"] = "Since I never doubted our success, I took the liberty of making further preparations. I have arranged for a couple of volunteers. I want to see our new energy drink in action before you imbibe it, <name>. May I call you <name>? Of course I can. We're partners now. You will find the volunteers lounging on the high terraces of the city. Tazavesh has many such comfortable areas for visitors like yourself.", ["objectivesText"] = "Speak with the volunteers to test the new energy drink. Progress: We are both certain to profit from this venture, <name>, regardless of the outcome.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 232351, ["x"] = 0.437, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 232351, ["x"] = 0.437, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.437, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 85383 }, ["questLines"] = { { ["id"] = 5699, ["name"] = "That Tazavesh Taste", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2472, ["db2QuestHubAreaPoiID"] = 8385 },
