[85429] = { ["id"] = 85429, ["name"] = "Overwhelm Them", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 85429, 85430, 85431, 85432, 85433, 85434 }, ["description"] = "There's an audit coming up. My employer, Xy Imports, will be audited. Again. <Xy'nell visibly shakes, ducking his head.> I need this audit to go badly. It must be worse than the last. Can you help me? We have a shipment of small devourers that would cause a lot of trouble if they were to escape or go missing. Break open their crates. Business needs to be overwhelmed just like last time.", ["objectivesText"] = "Break 8 Xy Imports Crates on the docks in Tazavesh.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 232498, ["x"] = 0.505, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 232498, ["x"] = 0.505, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 84967 }, ["questLines"] = { { ["id"] = 5703, ["name"] = "On a Technicality", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2472, ["db2QuestHubAreaPoiID"] = 8385 },
[85430] = { ["id"] = 85430, ["name"] = "Mandatory Time Off", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 85429, 85430, 85431, 85432, 85433, 85434 }, ["description"] = "If my colleagues knew of my plan, they would be in danger of discharging their oaths as good employees. Besides that, they are far too excellent at their jobs. Take these. They're devices of my own creation. When placed near my colleagues, it will create an illusion of them working. They will be able to step away and rest. And the business will be under even more pressure without them.", ["objectivesText"] = "Place 7 Illusion Devices . Progress: I had to become good at illusions for this job. It was the only way to make it tolerable. Maybe now I can use those skills to help others for once.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 232498, ["x"] = 0.505, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 232498, ["x"] = 0.505, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 84967 }, ["questLines"] = { { ["id"] = 5703, ["name"] = "On a Technicality", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2472, ["db2QuestHubAreaPoiID"] = 8385 },
[85431] = { ["id"] = 85431, ["name"] = "Drain Their Resources", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 85429, 85430, 85431, 85432, 85433, 85434 }, ["description"] = "We've made good progress, but we need more disorganization. I've redirected a particularly large shipment of anima in the form of a devourer. Kill it and bring its anima core to me. The anima itself is not important--rather, the fact that it can be stolen. My boss will have more to answer for in the audit when his books are in disarray.", ["objectivesText"] = "Collect Overflowing Anima Core from Respleth the Hungerer outside Tazavesh. Progress: The Xy Imports associates transporting this anima are expecting a--ah--broker of sorts to relieve them of their charge. They will give you no trouble.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 232609 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 232498, ["x"] = 0.505, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 232498, ["x"] = 0.505, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 85429, 85430 }, ["questLines"] = { { ["id"] = 5703, ["name"] = "On a Technicality", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2472 },
[85432] = { ["id"] = 85432, ["name"] = "Confuse Their Contacts", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 85429, 85430, 85431, 85432, 85433, 85434 }, ["description"] = "When our imports are delayed or lost, the most direct impact is on Tazavesh businesses. Take this illusion pin. It will make you appear as a Xy Imports employee. Tell the businesses their shipments are delayed indefinitely. My boss cannot ignore downstream pressure forever.", ["objectivesText"] = "Speak with market vendors in Tazavesh. Progress: This is not the first time the market vendors have dealt with my boss's failings. I only hope it is the last.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 232644 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 232498, ["x"] = 0.505, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 232498, ["x"] = 0.505, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 85429, 85430 }, ["questLines"] = { { ["id"] = 5703, ["name"] = "On a Technicality", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2472 },
[85433] = { ["id"] = 85433, ["name"] = "Eyes on Us", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 85429, 85430, 85431, 85432, 85433, 85434 }, ["description"] = "I can hear Coordinator Xy'thir raging about the slide in business already. <Xy'nell shifts uncomfortably and ducks his head.> We're ready. Go to Port Authority Zo'rau . Tell them you represent an invested party and that the audit should be moved up. And there's one more thing I need you to do. Speak with me before you go.", ["objectivesText"] = "Speak with Port Authority Zo'rau in Tazavesh. Progress: This is more important than I can say, <name>. But I cannot break my oath. Deliver the pin to Zo'rau.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 22829, 22832, 38760, 38761, 38762, 53416, 53448, 65278, 65298, 65317, 66887, 66889, 66890, 71083, 130219, 130220, 130222, 131333, 133998, 143536, 153069, 153071, 153219, 153226, 181501, 181502, 181503, 181507, 181625, 181626, 181638, 181645, 181646, 181647, 181648, 181649, 181651, 181662, 181664, 181665, 181666, 181671, 181672, 181674, 181679, 181680, 181681, 181682, 181686, 181689, 181690, 181695, 184305, 184772, 184773, 184774, 184775, 184776, 190454, 190456, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192030, 192034, 192037, 193477, 195204, 195205, 197935, 197953, 197956, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243, 225571, 228445, 228446, 228447, 228448, 232639, 232740, 232748, 232750, 232761, 232772, 232777, 232780, 232785, 239125, 250769 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 232498, ["x"] = 0.505, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 232498, ["x"] = 0.505, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 85431, 85432 }, ["questLines"] = { { ["id"] = 5703, ["name"] = "On a Technicality", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2472 },
[85434] = { ["id"] = 85434, ["name"] = "On a Technicality", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 85429, 85430, 85431, 85432, 85433, 85434 }, ["description"] = "It's time. I cannot tell you what to expect, $p. I only hope this is the last day I must keep such a dreadful oath. <Xy'nell shakes his head.> Let us hurry. Port Authority Zo'rau has already begun questioning Coordinator Xy'thir .", ["objectivesText"] = "Confront Coordinator Xy'thir in Tazavesh. Progress: <Xy'nell is silent before Coordinator Xy'thir .>", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 245717, 245718, 245719, 245720 }, ["rewardCurrencies"] = { { ["id"] = 3129, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 232498, ["x"] = 0.505, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 233942, ["x"] = 0.515, ["y"] = 0.384 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 85433 }, ["questLines"] = { { ["id"] = 5703, ["name"] = "On a Technicality", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2472 },
[85438] = { ["id"] = 85438, ["name"] = "Or Else", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83417, 83418, 83419, 83420, 83421, 85438, 87008 }, ["description"] = "Am I glad I found you, <name>! My boss, Kraz Torquewrench, sent me to find you, and he don't take no for an answer, yanno? I thought I was gonna have to cash out and move futher underground, but here you are! Anyway, the boss's little girl is getting married, and he told me he wanted you, specifically, to help him \"finalize\" some \"details,\" with her intended and who's attendin'--if you get my meanin'.", ["objectivesText"] = "Speak with Kraz Torquewrench in Hovel Hill.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 52908, 52954, 131830 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 233235, ["x"] = 0.44, ["y"] = 0.496 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226518, ["x"] = 0.2595, ["y"] = 0.4265 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5642, ["name"] = "The Perfect Wedding", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346, ["db2QuestHubAreaPoiID"] = 8189 },
[85444] = { ["id"] = 85444, ["name"] = "Found Family", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "This crew trusted me. They're my family. We gotta see if any of them survived. I have other engineers who ain't here. They must have fled into the field. Razi , Keets , and Glizza are out there. Find 'em. Bring 'em home.", ["objectivesText"] = "Rescue Pamsy 's last engineers from the Writhing Fields. Progress: Don't leave those engineers out there to die.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 228214, ["x"] = 0.705, ["y"] = 0.885 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225598, ["x"] = 0.705, ["y"] = 0.886 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.885 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 83146 }, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[85449] = { ["id"] = 85449, ["name"] = "Phase Shift", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83126, 83127, 83128, 83129, 83130, 85449, 85450 }, ["description"] = "As soon as the ethereals attacked, phase resonance tore open rifts throughout the area. The rifts are gone, but the ethereals can return while the resonance remains. That is how they call more soldiers and communicate with their commanders. We need to destroy that resonance. It may earn us the ire of whoever is behind this attack, but I gladly invite them to stop us.", ["objectivesText"] = "Destroy 4 Phase Resonance in the Vatworks. Progress: We need to destroy that resonance if we are to stop this attack.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225669, ["x"] = 0.294667, ["y"] = 0.694 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225669, ["x"] = 0.294667, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.294667, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questTurnInID"] = 225669, ["questType"] = "standard", ["sourceQuests"] = { 83125 }, ["questLines"] = { { ["id"] = 5615, ["name"] = "Breaking the Shackles", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5615, ["questLineOrder"] = 3 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[85450] = { ["id"] = 85450, ["name"] = "Evacuation Plan", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83126, 83127, 83128, 83129, 83130, 85449, 85450 }, ["description"] = "We cannot let the ethereals find the Dark Heart before we do. Gazlowe needs to be informed. We must gather our forces and find the Dark Heart--quickly!", ["objectivesText"] = "Regroup with Gazlowe in Steamwheedle Laboratories. Progress: We need to get to the bottom of this.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 232660 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 229261, ["x"] = 0.27, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questGiverID"] = 232660, ["questType"] = "standard", ["sourceQuests"] = { 83126, 85449 }, ["questLines"] = { { ["id"] = 5615, ["name"] = "Breaking the Shackles", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5615, ["questLineOrder"] = 3 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[85451] = { ["id"] = 85451, ["name"] = "The Burning of Hammerfall", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15716, ["mapID"] = 14, ["storyline"] = { 84651, 84652, 84656, 84704, 84705, 84706, 84707, 84708, 84709, 84710, 84711, 84712, 84713, 84714, 84715, 84716, 84717, 85451, 91039 }, ["description"] = "The Syndicate has put Hammerfall to torch! And the cowards are using pyromancers to feed the flames. But we can save our huts if we get to them quickly. Fight through the Syndicate bandits to a building and then blow this horn. A Hammerfall shaman will come to put out the fire!", ["objectivesText"] = "Use the Hammerfall Horn at each main structure in Hammerfall to summon a shaman and put out the flames.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 231766 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.696, ["y"] = 0.41, ["mapID"] = 2372, ["npcID"] = 231768 } }, ["ends"] = { { ["x"] = 0.696, ["y"] = 0.41, ["mapID"] = 2372, ["npcID"] = 231768 } }, ["coords"] = { ["mapID"] = 2372, ["x"] = 0.696, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15716 } }, ["questGiverID"] = 231768, ["questTurnInID"] = 231768, ["questType"] = "standard", ["sourceQuests"] = { 84708 }, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 20, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2796, ["db2PoiUiMapID"] = 2372 },
