[85475] = { ["id"] = 85475, ["name"] = "Secret in the Sands", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 85475 }, ["series"] = { 85476 }, ["description"] = "Welcome back. Maru is looking for you again. She says only you have the skills to help her with this task. <The groans and complaints from the crowd intensify.> Oh, don't worry about me. I'll be here... As always...", ["objectivesText"] = "Speak with Maru .", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 232406, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232407, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232408, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232410, ["x"] = 0.63, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226684, ["x"] = 0.632, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 85195 }, ["db2LabelIDs"] = { 4063 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71, ["db2QuestSortName"] = "Nightborne" },
[85476] = { ["id"] = 85476, ["name"] = "Buried Tweasure", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 85476 }, ["series"] = { 85475 }, ["description"] = "Hello friend! You won't believe it, but I heard there's a hidden tweasure somewhere in Tanaris! I'm suuuper sneaky and managed to get a copy of the first riddle. And you're so good at solving them tat I want to give it to you!", ["objectivesText"] = "Find the buried treasure. Progress: Go find the tweasure!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 206696, 208092, 231808, 231819, 231820 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 5 }, { ["id"] = 3100, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226684, ["x"] = 0.632, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226684, ["x"] = 0.632, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 85475 }, ["db2LabelIDs"] = { 4061, 4063 }, ["db2QuestSortName"] = "Nightborne" },
[85477] = { ["id"] = 85477, ["name"] = "Lost and... Found?", ["level"] = 10, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 85477 }, ["description"] = "I am so overwhelmed. A group of folks were here a little while ago, all complai... I mean, submitting lost-item notices with great passion, but all at the same time. I tried to take down all the details, but in the stress of the moment, I fear they're all jumbled. I have this collection of items that have been found over the day, and I'm fairly sure these are the items those folks were talking about. Do you think you could use my notes and figure out which item belongs to each person?", ["objectivesText"] = "Deliver the lost items to their correct owners. Progress: How's it going? Have you found the owners of all the lost items?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 231761, 231762, 231763, 231764, 231765, 231810, 231907 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 5 }, { ["id"] = 3100, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232406, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232407, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232408, ["x"] = 0.63, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232405, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232406, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232407, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232408, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232410, ["x"] = 0.63, ["y"] = 0.502 } },