[85529] = { ["id"] = 85529, ["name"] = "Past Glory", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15716, ["mapID"] = 14, ["storyline"] = { 84638, 84639, 84640, 84641, 84643, 84645, 84649, 84650, 84656, 84657, 84658, 84659, 84710, 84717, 85529, 87299, 91039 }, ["description"] = "Marran's\"Red Dawn\" has left the city and peace has returned to Stromgarde. At least for now. Faerin left for the countryside. She said she wanted to check on Newstead and Refuge Point, but I think she wanted to get out of Stromgarde. She came here with such enthusiasm. I should not have tempered it so harshly. I feel in the end it was I who needed to learn a lesson. We should check in on her.", ["objectivesText"] = "Speak to Faerin at High Perch. Progress: <Faerin looks lost in thought as she again gazes at Thoradin's Wall.>", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 239137 }, ["starts"] = { { ["x"] = 0.216, ["y"] = 0.65, ["mapID"] = 2372, ["npcID"] = 232986 } }, ["ends"] = { { ["x"] = 0.216, ["y"] = 0.65, ["mapID"] = 2372, ["npcID"] = 232986 } }, ["coords"] = { ["mapID"] = 2372, ["x"] = 0.216, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15716 } }, ["questGiverID"] = 232986, ["questTurnInID"] = 232986, ["questType"] = "standard", ["sourceQuests"] = { 84717 }, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 31, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2796, ["db2PoiUiMapID"] = 2372 },
