[85553] = { ["id"] = 85553, ["name"] = "Side Gig: Feeling Crabby", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 85553 }, ["description"] = "Food's a critical resource for any crew that dares to sail the sea. So is gunpowder. Let's kill two crabs with one stone and get our hands on some of those bombshells out on the Kaja'Coast. Just don't get yourself blown up while you do it, yeah?", ["objectivesText"] = "Collect 15 Powdery Crab Meat from bombshell crabs on the Kaja'Coast. Progress: We'll need time to separate the powder from the crab, so get 'em here quick!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 219934, 233483, 235339, 245653 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 38 }, { ["id"] = 3171, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231064, ["x"] = 0.198, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231064, ["x"] = 0.198, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.198, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[85554] = { ["id"] = 85554, ["name"] = "Side Gig: It's Always Sunny Side Up", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84929, 84955, 84971, 84994, 84995, 85263, 85268, 85269, 85270, 85390, 85396, 85397, 85398, 85399, 85400, 85402, 85427, 85428, 85466, 85467, 85472, 85473, 85474, 85487, 85488, 85497, 85498, 85499, 85500, 85512, 85513, 85514, 85515, 85518, 85519, 85524, 85526, 85527, 85528, 85554, 85913, 85914, 85944, 85945, 85960, 85962, 86177, 86178, 86179, 86180, 86943, 86947, 86949, 86952 }, ["description"] = "Pterrordax eggs have been all the rage lately in the Undermine . And what good would the Blackwater name be if we couldn't import high-demand luxury goods? If you're interested in makin' some gold, head over to the Kaja'Coast and collect some for us. Oh, and make sure you don't take too many. Consumers these days love when we can label our goods \"ethical.\"", ["objectivesText"] = "Collect 8 Pterrordax Eggs on the Kaja'Coast.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232486, 232883, 233478, 233482, 234218, 235508, 245653 }, ["rewardCurrencies"] = { { ["id"] = 3118, ["amount"] = 100 }, { ["id"] = 3171, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231064, ["x"] = 0.198, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231064, ["x"] = 0.198, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.198, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5687, ["name"] = "Undermine - World Quests/Repeatables", ["orderIndex"] = 41, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[85562] = { ["id"] = 85562, ["name"] = "Tougher Than We Thought", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "Hah! I've never been feeling better! Now, we seize back what rightfully belongs to Blackwater, <name>. They've turned our prized headquarters into a smuggler's cove for that foul sludge. There are too many crates of Black Blood to deal with right now, but they can't move their cargo without fresh bodies. Let's cut them down.", ["objectivesText"] = "Reclaim the Port Authority from Darkfuse forces. Progress: There's blood to spill!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 226372 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 233296, ["x"] = 0.638, ["y"] = 0.175 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 233296, ["x"] = 0.638, ["y"] = 0.175 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.175 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questTurnInID"] = 233296, ["questType"] = "standard", ["sourceQuests"] = { 83200 }, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[85570] = { ["id"] = 85570, ["name"] = "The Tattered Journal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 85570 }, ["description"] = "<The journal almost falls apart in your hands as you leaf through it. What few pages that remain are filled with an erratic scrawling script. Perhaps Stellin Verasa would be interested in this journal back in camp.>", ["objectivesText"] = "Take the journal to Stellin Verasa back in the Siren Isle camp. Provided item:", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 232643, 233027 }, ["starts"] = { { ["x"] = 0.371, ["y"] = 0.772, ["mapID"] = 2375, ["objectID"] = 494923 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 229716, ["x"] = 0.708, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 15827 } }, ["questType"] = "standard" },
[85571] = { ["id"] = 85571, ["name"] = "Scattered To The Winds", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 85571 }, ["description"] = "My goodness! This journal is missing many of its pages! <Stellin flips through the journal, careful to not let any loose pages fall out.> This journal doesn't look very old... and it seems to be of human origin? Could this be the key to discovering what happened to the humans that came here? What a mystery! But less of a mystery if we could find the missing pages... Would you keep an eye out for them while you're out in the field?", ["objectivesText"] = "Collect 5 Journal pages around the isle. Progress: Have you found any more pages from the journal?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232643, 233027, 233831, 235543, 235544, 235545, 235546, 235547 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 229716, ["x"] = 0.708, ["y"] = 0.396 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 229716, ["x"] = 0.708, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 85570 } },
[85572] = { ["id"] = 85572, ["name"] = "A Group Effort", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 85572 }, ["description"] = "This is, um, quite the mess you've handed me. All these pages... what order do they go in? Aha! This journal seems to have belonged to a Kul Tiran that came here... <Stellin looks up, her eyes shining with excitement.> ...and it might hold the key to learning about their time on the isle. But the pages are hard to read... perhaps we should ask around to see if anyone can read them? Here, take a few pages. I'll keep trying to decipher the base journal while you go to camp and ask around.", ["objectivesText"] = "Ask Alta, Skitter, and Ricket if they can read the journal. Progress: <Stellin adjusts her glasses with a grimace.> This... seems like the author's signature. Had... is that a \"d\" or an \"l\" Had... do.. k--oh! Haddock? Or maybe that's an \"'e.\"", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 233027 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 229716, ["x"] = 0.708, ["y"] = 0.396 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 229716, ["x"] = 0.708, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 85571 } },
[85573] = { ["id"] = 85573, ["name"] = "Laid To Rest At Last", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 85573 }, ["description"] = "<Stellin listens as you explain what you've learned and nods gravely.> This poor fellow was part of a crew that sailed here aboard a ship called the Maiden's Whisper. They were almost wiped out by a storm, but then even the survivors disappeared! He was the last one and... didn't make it either in the end. Perhaps we can put his memory to rest? I spotted a graveyard out behind the Kul Tiran's base... perhaps setting the journal there amongst his crew's graves will bring his memory some peace.", ["objectivesText"] = "Bring the Tattered Kul Tiran Journal to the graveyard behind the Kul Tiran base in the Abandoned Mines. Progress: <name>, did you find the graveyard?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232694, 233027 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 229716, ["x"] = 0.708, ["y"] = 0.396 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 229716, ["x"] = 0.708, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 85572 } },
[85574] = { ["id"] = 85574, ["name"] = "Hazy Celebration Crate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 85574 }, ["description"] = "<This crate phases in and out of existence with dark, necromantic energy. Regardless, Alyx would likely appreciate the supplies returned.>", ["objectivesText"] = "Return the Hazy Celebration Crate to Alyx . Progress: Yes?", ["rewardItems"] = { 232263 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 5 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232410, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 2339, ["npcID"] = 234262, ["x"] = 0.505, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71, 2339 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 4061, 4063 }, ["db2QuestSortName"] = "Nightborne", ["startItems"] = { 232263 } },
[85589] = { ["id"] = 85589, ["name"] = "Ruffled Pages", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "Many of the wyvern on this isle have crafted their nests from folios, scrolls, and documents they scavenge from the isle's ruins. Because of this, their nests may hold the clues we need to understand the full history of this place. Our scouts have secured grappling holds for you to climb to their nests, but use any means you like to recover the paper the wyverns have used as nesting material. Our knowledge of the isle's history depends on it!", ["objectivesText"] = "Collect 15 Nesting Papers from the wyvern nests around the island. Progress: I really want to see what's on the papers the wyvern have taken!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232361 }, ["rewardCurrencies"] = { { ["id"] = 3090, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 229716, ["x"] = 0.708, ["y"] = 0.396 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 229716, ["x"] = 0.708, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 84725 }, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2127, ["db2PoiUiMapID"] = 2369 },
[85648] = { ["id"] = 85648, ["name"] = "Delver's Call: Earthcrawl Mines", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 85648 }, ["description"] = "HELP WANTED Troubles continue within Earthcrawl Mines. Fine pay to whoever can handle it.", ["objectivesText"] = "Complete the Earthcrawl Mines delve on any difficulty. Progress: Are you the one who grabbed the task for Earthcrawl Mines?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 232371 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.553, ["y"] = 0.559, ["mapID"] = 2248, ["objectID"] = 455716 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224566, ["x"] = 0.552, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard" },
[85649] = { ["id"] = 85649, ["name"] = "Delver's Call: The Waterworks", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 85649 }, ["description"] = "NOTICE The Waterworks have become unstable. Request aid in addressing issues.", ["objectivesText"] = "Complete the Waterworks delve on any difficulty.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 232371 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.466, ["y"] = 0.177, ["mapID"] = 2251, ["objectID"] = 487815 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213875, ["x"] = 0.449, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.449, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 15002 } }, ["questType"] = "standard" },
[85653] = { ["id"] = 85653, ["name"] = "Dipping a Toe", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 85653 }, ["description"] = "That ring of yours has caused quite a stir, hasn't it? And the history behind it... vrykul? Someone named Cyrce? I know you and Bargus unlocked more of the ring's potential by scouting the isle but... perhaps you should turn your attention to the sea? Take your ring into the water and see what happens. Bring whatever you find back to me. I'm a bit of a novice, but I might be able to piece whatever you find back together.", ["objectivesText"] = "Look for more citrines in the waters surrounding Siren Isle . Progress: Kobyss would give anyone thalassophobia. You're a brave soul looking for gems in that water.", ["rewardItems"] = { 229365, 232860, 232861, 232862 }, ["rewardCurrencies"] = { { ["id"] = 3090, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 231536, ["x"] = 0.712, ["y"] = 0.413333 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 231536, ["x"] = 0.712, ["y"] = 0.413333 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.413333 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 84726 }, ["db2PoiMapID"] = 2127, ["db2PoiUiMapID"] = 2369 },
[85654] = { ["id"] = 85654, ["name"] = "Juicing Up and Storming Out", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 85654 }, ["description"] = "Well, look. If it ain't <name>, the talk of the camp. <Didi grabs your hand and looks closely at your ring.> That ring on ya finger sure is peculiar, ya sure ya don't want a different one? <Didi looks up at you and winks.> I'm just yankin' ya chain, let's see what we can do with it! Ya get me enough of that magic metal lookin' stuff we've been finding, and I'll see about gettin' you suited up in the Pummeler over there. Your ring oughta give it the juice it needs to really wreak some havoc!", ["objectivesText"] = "Acquire enough Flame-Blessed Iron to test out the N.U.K.U.L.A.R Target Painter and TR-06 Pummeler . Progress: Ya got around to finding some of that iron an' wreakin' some havoc out there?", ["rewardItems"] = { 229365 }, ["rewardCurrencies"] = { { ["id"] = 3090, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 231997, ["x"] = 0.712, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 231997, ["x"] = 0.712, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 85653 }, ["db2PoiMapID"] = 2127, ["db2PoiUiMapID"] = 2369 },
[85655] = { ["id"] = 85655, ["name"] = "Unleashing Her Power", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 85655 }, ["description"] = "This ring that you and Bargus found has taken you all over the isle learning its history and finding its treasures. The ring has aided you in your exploration--and in battle. But, we have never truly pushed the ring to find its limitations. Perhaps some formal testing is in order. Perhaps we can unveil more of its potential if we invite a bit of danger. Go now and test the ring against any worthy opponents you can find. Come back to me with your observations.", ["objectivesText"] = "Equip Cyrce's Circlet and fight creatures on the Siren Isle to trigger its hidden ability while in combat. Progress: Have you engaged in combat testing with the ring? What were your findings?", ["rewardItems"] = { 88375, 199830, 229365 }, ["rewardCurrencies"] = { { ["id"] = 3090, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 228074, ["x"] = 0.711333, ["y"] = 0.441333 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 228074, ["x"] = 0.711333, ["y"] = 0.441333 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.711333, ["y"] = 0.441333 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 85654 }, ["db2PoiMapID"] = 2127, ["db2PoiUiMapID"] = 2369 },
[85656] = { ["id"] = 85656, ["name"] = "The Singing Bandit Catcher", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 85656 }, ["description"] = "Seems you've gotten the hang of that ring, eh? Maybe you can put it to good use for me. Our supplies here--especially our gold and flame-blessed iron --have been disappearing! <Tanmar leans in to whisper.> Normally I wouldn't suggest this--the Arathi are a trustworthy lot--but the number of incidents is building. and I'm wondering if there's a thief among us. See if you can find 'em. They being pretty brazen. I'm sure you can catch 'em in the act somewhere!", ["objectivesText"] = "Catch three thieves. Progress: Keep your hand on your pockets. There are thieves everywhere, it seems like.", ["rewardItems"] = { 229365, 232860, 232861, 232862 }, ["rewardCurrencies"] = { { ["id"] = 3090, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 231536, ["x"] = 0.712, ["y"] = 0.413333 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 231536, ["x"] = 0.712, ["y"] = 0.413333 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.413333 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 85655 }, ["db2PoiMapID"] = 2127, ["db2PoiUiMapID"] = 2369 },
[85657] = { ["id"] = 85657, ["name"] = "Cyrce Would Be So Proud", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 85657 }, ["description"] = "It ain't no secret the winds here are terrible. But! I don't think we've given that ring there a fair chance at fightin' 'em. I mean, that thing can let ya swim like a fish, make tornadoes outta nothin', and even shock the invisibility off of magical boxes! Surely it's got somethin' to say about a lil' nasty weather, right? Take my balloon up and see if you can keep it stable usin' that ring of yours. Maybe we can find the trick for stayin' in the sky!", ["objectivesText"] = "Fly in the Skypiercer to see if Cyrce's Circlet can protect you from the high winds. Progress: If that ring could help us outta storms, that'd be amazin'!", ["rewardItems"] = { 229365, 235041 }, ["rewardCurrencies"] = { { ["id"] = 3090, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 231997, ["x"] = 0.712, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 231997, ["x"] = 0.712, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 85656 }, ["db2PoiMapID"] = 2127, ["db2PoiUiMapID"] = 2369 },
[85664] = { ["id"] = 85664, ["name"] = "Delver's Call: Nightfall Sanctum", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 85664 }, ["description"] = "CALL FOR AID! The Order of Night may have a base set up in a location called Nightfall Sanctum. It is imperative that we stop any of their operations as soon as possible.", ["objectivesText"] = "Complete the Nightfall Sanctum delve on any difficulty.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 232371 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.726, ["y"] = 0.275, ["mapID"] = 2277, ["objectID"] = 487847 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214380, ["x"] = 0.432, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 15005 } }, ["questType"] = "standard" },
