[85678] = { ["id"] = 85678, ["name"] = "Repair Yourself", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 60168, 85678 }, ["description"] = "Your gear isn't looking too great from your last excursion. Speak to Quartermaster Richter to get it repaired.", ["objectivesText"] = "Speak with Quartermaster Richter , then select \"Repair All Items\" to repair your damaged gear. Progress: Speak with Quartermaster Richter and have her repair your equipment.", ["rewardGold"] = 1500, ["rewardXP"] = 150, ["starts"] = { { ["npcID"] = 156807, ["x"] = 0.522, ["y"] = 0.552, ["mapID"] = 1409 }, { ["npcID"] = 245394, ["x"] = 0.522, ["y"] = 0.556, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 156807, ["x"] = 0.522, ["y"] = 0.552, ["mapID"] = 1409 }, { ["npcID"] = 245394, ["x"] = 0.522, ["y"] = 0.556, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.522, ["y"] = 0.552, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 21, ["flags"] = 0 }, { ["id"] = 1072, ["name"] = "What Lurks Below", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409 },
