[85862] = { ["id"] = 85862, ["name"] = "A Prince's Duty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["mapID"] = 2418, ["storyline"] = { 12291, 12301, 12305, 12478, 85862, 85875, 85878, 85884, 85885 }, ["description"] = "It's a big day, lad. We've got a parade of the troops, a visiting contingent from Ironforge, and I hear word your father--er, King Terenas--will be here to oversee everything. It's days like today that you've been forged for, Arthas. Inspire your men. Prove yourself. Whip these troops into shape. No doubt Muradin has been itching for a brawl as well...", ["objectivesText"] = "Spar with the troops in Lordaeron Garrison. Progress: You are the best our kingdom has to offer, my son. Make us look good in front of our guests!", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.341, ["y"] = 0.841, ["mapID"] = 2418, ["npcID"] = 233752 } }, ["ends"] = { { ["x"] = 0.341, ["y"] = 0.841, ["mapID"] = 2418, ["npcID"] = 233752 } }, ["coords"] = { ["mapID"] = 2418, ["x"] = 0.341, ["y"] = 0.841 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 233752, ["questTurnInID"] = 233752, ["questType"] = "standard", ["sourceQuests"] = { 85884 }, ["questLines"] = { { ["id"] = 5718, ["name"] = "Lorewalking: Arthas", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 279, ["title"] = "Lorewalking: Arthas", ["questLineID"] = 5718, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2818, ["db2PoiUiMapID"] = 2418 },
