[85871] = { ["id"] = 85871, ["name"] = "Lorewalking: The Blade's Forces", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["mapID"] = 2383, ["storyline"] = { 40710, 53761, 53762, 53763, 54058, 54114, 54118, 54126, 84371, 84779, 84782, 84784, 84789, 85871 }, ["description"] = "Xal'atath brings with her an army of shadows and tricks. They are nothing to our evolved forms! You have been chosen--blessed with power by N'Zoth to serve as his champion. Go now and destroy them!", ["objectivesText"] = "Defeat Xal'atath's forces.", ["rewardGold"] = 29200, ["rewardXP"] = 175, ["rewardItems"] = { 244888, 245567, 245631 }, ["starts"] = { { ["x"] = 0.525, ["y"] = 0.731, ["mapID"] = 2381, ["npcID"] = 230321 } }, ["ends"] = { { ["x"] = 0.525, ["y"] = 0.731, ["mapID"] = 2381, ["npcID"] = 230321 } }, ["coords"] = { ["mapID"] = 2381, ["x"] = 0.525, ["y"] = 0.731 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 230321, ["questTurnInID"] = 230321, ["questType"] = "standard", ["sourceQuests"] = { 84782 }, ["questLines"] = { { ["id"] = 5673, ["name"] = "Lorewalking: Xal'atath", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 266, ["title"] = "Lorewalking: Xal'atath", ["questLineID"] = 5673, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2801, ["db2PoiUiMapID"] = 2383 },
[85873] = { ["id"] = 85873, ["name"] = "Another Shadowy Invitation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85873 }, ["description"] = "$p, do you like paperwork and forms as much as I do? Then let us dispense with the expedited entry to Tazavesh and experience once more the joy of jumping through bureaucratic hoops and paying bribes as is the tradition of all great broker stories. WARNING! COMPLETING THIS QUEST WILL REQUIRE YOU TO FINISH CHAPTER 1 OF THE 11.2 CAMPAIGN!", ["objectivesText"] = "Meet Locus-Walker in the Foundation Hall in Dornogal.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15336 } }, ["questType"] = "standard" },
