[85875] = { ["id"] = 85875, ["name"] = "Ascent of the Lich King", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 12291, 12301, 12305, 12478, 85862, 85875, 85878, 85884, 85885 }, ["description"] = "<Icecrown lies before you. Waiting. Frostmourne bids you... ... ascend.>", ["objectivesText"] = "Banish your memories. Progress: Arthas... my son.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["starts"] = { { ["x"] = 0.514, ["y"] = 0.794, ["mapID"] = 118 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 233811, ["x"] = 0.522, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["sourceQuests"] = { 85885 }, ["questLines"] = { { ["id"] = 5718, ["name"] = "Lorewalking: Arthas", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 279, ["title"] = "Lorewalking: Arthas", ["questLineID"] = 5718, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[85876] = { ["id"] = 85876, ["name"] = "Reading the Runes", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 85876 }, ["description"] = "My curiosity is still not terminated, <name>. I would like to know more about these vrykul and why they came to this land. < Bargus 's wiry brows knit together and his mustache bristles as he thinks.> The tablets you found were by far the best source of information on the vrykul and whoever this \"Cyrce\" is. Perhaps there are additional tablets we missed? I have my ordained duties here, but please examine them and report back to me.", ["objectivesText"] = "Examine various Rune-Carved Tablets within the Forgotten Tomb.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3090, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 230242, ["x"] = 0.6752, ["y"] = 0.4192 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 230242, ["x"] = 0.6752, ["y"] = 0.4192 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.6752, ["y"] = 0.4192 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 84726 } },
[85878] = { ["id"] = 85878, ["name"] = "O' Thanagor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 4820, ["mapID"] = 84, ["storyline"] = { 12291, 12301, 12305, 12478, 85862, 85875, 85878, 85884, 85885 }, ["description"] = "You are the Lich King. The whole of Azeroth is arrayed against you. Show them what it means to be king.", ["objectivesText"] = "Defeat the usurpers atop Icecrown Citadel.", ["rewardGold"] = 312800, ["rewardXP"] = 1415, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 236114, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 4820 } }, ["questType"] = "standard", ["sourceQuests"] = { 85875 }, ["questLines"] = { { ["id"] = 5718, ["name"] = "Lorewalking: Arthas", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 279, ["title"] = "Lorewalking: Arthas", ["questLineID"] = 5718, ["questLineOrder"] = 0 } } },
[85879] = { ["id"] = 85879, ["name"] = "Reduce, Reuse, Resell", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 85869, 85879, 86775 }, ["description"] = "The guys over at S.C.R.A.P. could use some extra hands this week. You want a piece of the pie, go find one of their reps named Carlo out in the field and see if he's got any work for you. But if you find a piece of pie in any of those trash piles, don't, uh... Don't actually eat it. I hope that kinda goes without sayin'.", ["objectivesText"] = "Complete 3 S.C.R.A.P. jobs in Undermine . Progress: What d'you need, instructions? Big trash piles. Shovel. Get at it.", ["rewardItems"] = { 234741, 236682 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 200 }, { ["id"] = 3118, ["amount"] = 1000 }, { ["id"] = 3169, ["amount"] = 2000 }, { ["id"] = 3171, ["amount"] = 2000 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231409, ["x"] = 0.436, ["y"] = 0.505 }, { ["mapID"] = 2346, ["npcID"] = 237659, ["x"] = 0.266, ["y"] = 0.374667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231409, ["x"] = 0.436, ["y"] = 0.505 }, { ["mapID"] = 2346, ["npcID"] = 237659, ["x"] = 0.266, ["y"] = 0.374667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 85463, 86934 }, ["questLines"] = { { ["id"] = 5900, ["name"] = "Undermine Repeatables", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346, ["db2QuestHubAreaPoiID"] = 8189 },
[85884] = { ["id"] = 85884, ["name"] = "Lorewalking: The Prince Who Would Be King", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 84, ["storyline"] = { 12291, 12301, 12305, 12478, 85862, 85875, 85878, 85884, 85885 }, ["description"] = "Before I can tell you the story of the Lich King, we must learn about who he was before he put on his crown. Before he pulled that cursed sword from the depths of Frostmourne Cavern. We must talk about the prince who was promised the world, and the people who championed his cause. We must start in Lordaeron, many years ago, on a day of pomp and circumstance.", ["objectivesText"] = "Hear the story of Prince Arthas Menethil.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 242386, 244888, 245567, 245631 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3107, ["amount"] = 3 }, { ["id"] = 3284, ["amount"] = 3 } }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 236114, ["x"] = 0.642, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 236114, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5718, ["name"] = "Lorewalking: Arthas", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 279, ["title"] = "Lorewalking: Arthas", ["questLineID"] = 5718, ["questLineOrder"] = 0 } } },
[85885] = { ["id"] = 85885, ["name"] = "Lorewalking: No King Rules Forever", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 84, ["storyline"] = { 12291, 12301, 12305, 12478, 85862, 85875, 85878, 85884, 85885 }, ["description"] = "What makes a king? Is it his crown? Is it the sharpness of his sword? The coldness of his heart? Perhaps the undying servitude of his people? Just as it is difficult to say when a sapling becomes a tree, or a mountain becomes a hill, so too is it difficult to know when exactly Arthas Menethil passed into memory, and the Lich King was born. Where do we draw the line between man and monster?", ["objectivesText"] = "Listen to the story of the Lich King.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 242386, 244858, 244888, 245567, 245631 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 25 }, { ["id"] = 3107, ["amount"] = 10 }, { ["id"] = 3284, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 236114, ["x"] = 0.642, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 236114, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 85884 }, ["questLines"] = { { ["id"] = 5718, ["name"] = "Lorewalking: Arthas", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 279, ["title"] = "Lorewalking: Arthas", ["questLineID"] = 5718, ["questLineOrder"] = 0 } } },
