[85941] = { ["id"] = 85941, ["name"] = "Attitude Adjustment", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "I'm not a violent gal by nature, but there are a lot of Darkfuse out there. They're already hassling the locals and they won't like you guys asking questions. You wanna keep your friends safe? You wanna put the locals in better spirits? It'd probably be best if there were a whole lot less Darkfuse. If you catch my meaning.", ["objectivesText"] = "Kill 12 Darkfuse at Tailgate Park. Progress: My meaning was, go kill a bunch of Darkfuse so they don't kill your friends. Can't a gal be subtle?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 229246, ["x"] = 0.452, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 229246, ["x"] = 0.452, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83109 }, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[85944] = { ["id"] = 85944, ["name"] = "Side Gig: Blood Type", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84929, 84955, 84971, 84994, 84995, 85263, 85268, 85269, 85270, 85390, 85396, 85397, 85398, 85399, 85400, 85402, 85427, 85428, 85466, 85467, 85472, 85473, 85474, 85487, 85488, 85497, 85498, 85499, 85500, 85512, 85513, 85514, 85515, 85518, 85519, 85524, 85526, 85527, 85528, 85554, 85913, 85914, 85944, 85945, 85960, 85962, 86177, 86178, 86179, 86180, 86943, 86947, 86949, 86952 }, ["description"] = "Darkfuse was up to all sorts of questionable research out in the Ringing Deeps and, well, everywhere, really. Anyway, they had to write some of it down. Nab whatever notes you can find and bring them back to me. Don't look at me like that. It's not intellectual dishonesty, it's industrial espionage!", ["objectivesText"] = "Collect 8 Darkfuse Research Notes in the Writhing Fields. Progress: Got the goods?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 219934, 232863, 233451, 233483, 233484, 233485, 233533, 233534, 233536, 233538, 233539, 233540, 233541, 235359, 236096, 234717 }, ["rewardCurrencies"] = { { ["id"] = 3173, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231062, ["x"] = 0.168, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231062, ["x"] = 0.168, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.168, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5687, ["name"] = "Undermine - World Quests/Repeatables", ["orderIndex"] = 44, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[85945] = { ["id"] = 85945, ["name"] = "Side Gig: Blood-B-Gone", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84929, 84955, 84971, 84994, 84995, 85263, 85268, 85269, 85270, 85390, 85396, 85397, 85398, 85399, 85400, 85402, 85427, 85428, 85466, 85467, 85472, 85473, 85474, 85487, 85488, 85497, 85498, 85499, 85500, 85512, 85513, 85514, 85515, 85518, 85519, 85524, 85526, 85527, 85528, 85554, 85913, 85914, 85944, 85945, 85960, 85962, 86177, 86178, 86179, 86180, 86943, 86947, 86949, 86952 }, ["description"] = "Do you have any idea how hard it is to get dried blood stains out of your laundry? Well, you might, I guess. Steamwheedle's finest are working on a new detergent specifically formulated to deal with this pressing issue! And while the blood fields in the Ringing Deeps might be bad for the environment, and you, they're the perfect place to field test our latest formulations. Just give the blood slimes out there a quick hose down and let us know what happens.", ["objectivesText"] = "Test Blood-B-Gone on 8 blood slimes in the Writhing Fields. Progress: We've got a market to corner here.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 219934, 232897, 233448, 233453, 233456, 233461, 233464, 233469, 233472, 233477, 233480, 233529, 233483 }, ["rewardCurrencies"] = { { ["id"] = 3118, ["amount"] = 100 }, { ["id"] = 3173, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231062, ["x"] = 0.168, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231062, ["x"] = 0.168, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.168, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5687, ["name"] = "Undermine - World Quests/Repeatables", ["orderIndex"] = 45, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[85946] = { ["id"] = 85946, ["name"] = "The Great Crab Breakout", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83323, 84788, 84791, 85715, 85717, 85732, 85733, 85758, 85759, 85769, 85771, 85773, 85797, 85826, 85854, 85861, 85874, 85888, 85946, 86311, 86313, 86314, 86315, 86317, 86318, 86319, 86320, 86321, 86410, 86412, 86418, 87569, 87588 }, ["objectivesText"] = "Arrived at Pleasant Heights Supermarket Crabs covered for Talk to Worker 1 Talk to Worker 2 Talk to Manager", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15347 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5643, ["name"] = "FF Task List", ["orderIndex"] = 25, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Arrived at Pleasant Heights", ["amount"] = 0, ["type"] = 19, ["objectID"] = 35570, ["orderIndex"] = 0 }, { ["text"] = "Supermarket Crabs covered for", ["amount"] = 3, ["type"] = 0, ["objectID"] = 234030, ["orderIndex"] = 1 }, { ["text"] = "Talk to Worker 1", ["amount"] = 1, ["type"] = 0, ["objectID"] = 238151, ["orderIndex"] = 2 }, { ["text"] = "Talk to Worker 2", ["amount"] = 1, ["type"] = 0, ["objectID"] = 238152, ["orderIndex"] = 3 }, { ["text"] = "Talk to Manager", ["amount"] = 1, ["type"] = 0, ["objectID"] = 238153, ["orderIndex"] = 4 } }, ["activities"] = { ["scenarios"] = { { ["id"] = 2933, ["name"] = "Shipping & Handling", ["areaID"] = 0 } } }, ["db2LabelIDs"] = { 4101 }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[85947] = { ["id"] = 85947, ["name"] = "An Original Journey Through Time", ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 1637, ["mapID"] = 71, ["storyline"] = { 85947 }, ["description"] = "Old warriors keep spinning tales about how things were so much tougher around Azeroth back in their day. I bet they would say you're not tough enough to last 10 minutes in their world. Think you're tough enough to find out? How 'bout you show me.", ["objectivesText"] = "Complete 5 Timewalking dungeons. Progress: You're not givin' up, are ya?", ["rewardGold"] = 1263600, ["rewardItems"] = { 232877 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 1 } }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 223884, ["x"] = 0.628, ["y"] = 0.502 }, { ["mapID"] = 84, ["npcID"] = 234555, ["x"] = 0.560667, ["y"] = 0.19 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 223884, ["x"] = 0.628, ["y"] = 0.502 }, { ["mapID"] = 84, ["npcID"] = 234555, ["x"] = 0.560667, ["y"] = 0.19 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71, 84 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 4063 } },
[85948] = { ["id"] = 85948, ["name"] = "A Burning Journey Through Time", ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 85948 }, ["description"] = "The blazing star shines upon the land, searing the earth and parching the landscape. This star is relentless, malevolent almost. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", ["objectivesText"] = "Complete 5 Timewalking dungeons.", ["rewardGold"] = 1123600, ["rewardItems"] = { 232877 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 98685, ["x"] = 0.545, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 98685, ["x"] = 0.545, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[85949] = { ["id"] = 85949, ["name"] = "A Frozen Journey Through Time", ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 4395, ["mapID"] = 125, ["storyline"] = { 85949 }, ["description"] = "The chill star shines upon the land with its cold light as even the spirits retreat to the shadows. This star is unlike any other in the skies, sapping warmth and life. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", ["objectivesText"] = "Complete 5 Timewalking dungeons.", ["rewardGold"] = 1251200, ["rewardItems"] = { 232877 }, ["rewardCurrencies"] = { { ["id"] = 3100, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.506, ["y"] = 0.464, ["mapID"] = 125, ["npcID"] = 98690 } }, ["ends"] = { { ["x"] = 0.506, ["y"] = 0.464, ["mapID"] = 125, ["npcID"] = 98690 } }, ["coords"] = { ["mapID"] = 125, ["x"] = 0.506, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questGiverID"] = 98690, ["questTurnInID"] = 98690, ["questType"] = "standard" },
[85953] = { ["id"] = 85953, ["name"] = "The Drag", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15946, ["storyline"] = { 85953 }, ["rewardGold"] = 210000, ["rewardXP"] = 2090, ["rewardItems"] = { 9706, 10702, 33235, 33241, 35814, 35815, 35816, 35817, 63824, 63825, 63826, 64596, 64606, 64615, 118927, 131672, 190454, 191462, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192030, 192034, 192037, 193477, 194705, 197935, 197953, 197956, 198407, 198451, 198489, 198622, 205423, 205682, 209837, 209839, 217242, 217243 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15946 } }, ["questType"] = "standard" },
[85960] = { ["id"] = 85960, ["name"] = "Side Gig: Lost in the Sauce", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84929, 84955, 84971, 84994, 84995, 85263, 85268, 85269, 85270, 85390, 85396, 85397, 85398, 85399, 85400, 85402, 85427, 85428, 85466, 85467, 85472, 85473, 85474, 85487, 85488, 85497, 85498, 85499, 85500, 85512, 85513, 85514, 85515, 85518, 85519, 85524, 85526, 85527, 85528, 85554, 85913, 85914, 85944, 85945, 85960, 85962, 86177, 86178, 86179, 86180, 86943, 86947, 86949, 86952 }, ["description"] = "Some of the workers forced by the Darkfuse to work the blood fields never made it home. We've got reports that they might be lost in whatever the \"Unseeming\" is. Apparently it's got something to do with the big blood puddles? Sounds like a job for someone more expendable--I mean experienced, than me.", ["objectivesText"] = "Rescue 8 Lost Goblins from the Unseeming in the Writhing Fields.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 219934, 233453, 233461, 233469, 233477, 233480, 233484, 236096, 245653 }, ["rewardCurrencies"] = { { ["id"] = 3169, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231063, ["x"] = 0.168, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231063, ["x"] = 0.168, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.168, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5687, ["name"] = "Undermine - World Quests/Repeatables", ["orderIndex"] = 46, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[85961] = { ["id"] = 85961, ["name"] = "Moving the Pawns", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 84855, 84856, 84857, 84858, 84859, 84860, 84861, 84862, 84863, 84864, 84865, 84866, 85032, 85961, 86495, 86946, 90517 }, ["series"] = { 84855, 85032, 93979 }, ["description"] = "There is a small island to the northwest of here, called Overlook Zo'Shuul. My scouts have been searching for a way into Manaforge Omega, where we must stop the return of the All-Devouring. If we are fortunate, the scouts have already found a safe pathway inside.", ["objectivesText"] = "Meet Locus-Walker at Overlook Zo'Shuul.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 230700, ["x"] = 0.342, ["y"] = 0.108 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230806, ["x"] = 0.482, ["y"] = 0.366 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.108 }, ["mapCandidates"] = { ["npc"] = { 2371, 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 85032 }, ["questLines"] = { { ["id"] = 5733, ["name"] = "Void Alliance", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5733, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[85962] = { ["id"] = 85962, ["name"] = "Side Gig: Unseemly Reagents", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84929, 84955, 84971, 84994, 84995, 85263, 85268, 85269, 85270, 85390, 85396, 85397, 85398, 85399, 85400, 85402, 85427, 85428, 85466, 85467, 85472, 85473, 85474, 85487, 85488, 85497, 85498, 85499, 85500, 85512, 85513, 85514, 85515, 85518, 85519, 85524, 85526, 85527, 85528, 85554, 85913, 85914, 85944, 85945, 85960, 85962, 86177, 86178, 86179, 86180, 86943, 86947, 86949, 86952 }, ["description"] = "There's all sorts of weirdness going on in the Ringing Deeps thanks to all that Black Blood still lying around. And where there's madness and mutation, there's opportunity! Get out there and see what sort of horrific but potentially lucrative reagents you can scrape up.", ["objectivesText"] = "Collect 10 Unseemly Growths in the Writhing Fields. Progress: Try not to go crazy until after delivery, ok?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 124640, 232486, 232907, 235363, 235373, 235467 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 31 }, { ["id"] = 3173, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231062, ["x"] = 0.168, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231062, ["x"] = 0.168, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.168, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5687, ["name"] = "Undermine - World Quests/Repeatables", ["orderIndex"] = 47, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[86151] = { ["id"] = 86151, ["name"] = "Faceless Mask of the Burned Bridge", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["storyline"] = { 86151 }, ["description"] = "The displaced warrior is always on uneasy footing, especially one who is removed from her home world. The void makes this unsteadiness a reality where one step can lead into the abyss or drain you to your core.", ["objectivesText"] = "Return the Faceless Mask of the Burned Bridge to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Burned Bridge on the altar.", ["rewardItems"] = { 232917 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 232917 } },
[86152] = { ["id"] = 86152, ["name"] = "Faceless Mask of the Daredevil", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["storyline"] = { 86152 }, ["description"] = "The hunter never sought to lead yet sought a challenge in life at every turn. He directed his allies with a deft hand and never shied from diving in to the melee himself. The prowess he showed made him as well as my other minions much more deadly. Return this mask to the altar of the Daredevil to challenge your own resolve in battle as your foes attacks cut even more deep.", ["objectivesText"] = "Return the Faceless Mask of the Daredevil to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Daredevil on the altar.", ["rewardItems"] = { 232918 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 232918 } },
[86153] = { ["id"] = 86153, ["name"] = "Faceless Mask of the Dark Imagination", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["storyline"] = { 86153 }, ["description"] = "These magi, twisting their magic to manipulate and conquer the world. Imagining greater power, they tread along the lines of the voids' domain. In these pursuits, these magi came to the realization that in the depths of one's imagination lie truly dark and terrible things.", ["objectivesText"] = "Return the Faceless Mask of the Dark Imagination to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Dark Imagination on the altar.", ["rewardItems"] = { 174080, 174081, 232919 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 232919 } },
[86154] = { ["id"] = 86154, ["name"] = "Faceless Mask of the Pained", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["storyline"] = { 86154 }, ["description"] = "Trading in secrets, trading in lies, operating on the fringes are all the Spymaster knows. His lost passions, lost loves are all gone, crushed under his own duty and loyalty to the crown. Nothing is left, nothing but the pain. Pain is an apt tutor and tool and one in which the void knows intimately. Return my mask if you dare to feel the many forms pain can take.", ["objectivesText"] = "Return the Faceless Mask of the Pained to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Pained on the altar.", ["rewardItems"] = { 232920 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 232920 } },
[86155] = { ["id"] = 86155, ["name"] = "Faceless Mask of the Long Night", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["storyline"] = { 86155 }, ["description"] = "The endurance needed to make it this far is extraordinary and the feat of a long experienced adventurer. Yet, the longest night is nigh and with it our ultimate conquest. Those that fight the coming of eternal twilight know only futility, for in the Longest Night they will be on the edge of sanity forever.", ["objectivesText"] = "Return the Faceless Mask of the Long Night to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Long Night on the altar.", ["rewardItems"] = { 232921 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 232921 } },
[86156] = { ["id"] = 86156, ["name"] = "Getting Involved", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 86156 }, ["description"] = "You. Do that again. Could be good stuff we ain't seen yet. Get those caves open an' see what's in there!", ["objectivesText"] = "Contribute 10 times to events on the Siren Isle Command Map and complete one event by slaying the target. Progress: Did you check out the cave? No? Get goin' then!", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3090, ["amount"] = 75 } }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 227817, ["x"] = 0.6948, ["y"] = 0.444 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 227817, ["x"] = 0.6948, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.6948, ["y"] = 0.444 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 85059 } },
[86174] = { ["id"] = 86174, ["name"] = "Special Assignment: Storm's a Brewin", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = { "emissary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 86174 }, ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235548 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10416 } }, ["questType"] = "standard" },
[86177] = { ["id"] = 86177, ["name"] = "Side Gig: The Tides Provide", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84929, 84955, 84971, 84994, 84995, 85263, 85268, 85269, 85270, 85390, 85396, 85397, 85398, 85399, 85400, 85402, 85427, 85428, 85466, 85467, 85472, 85473, 85474, 85487, 85488, 85497, 85498, 85499, 85500, 85512, 85513, 85514, 85515, 85518, 85519, 85524, 85526, 85527, 85528, 85554, 85913, 85914, 85944, 85945, 85960, 85962, 86177, 86178, 86179, 86180, 86943, 86947, 86949, 86952 }, ["description"] = "You look like the type who ain't shy to get your hands dirty. Up for a little treasure hunting? Word has it that a ship exploded not far off the Kaja'Coast. Go to shore and see what the tide's brought in. \"Finders keepers\" is one of the foundational tenets of goblin society, after all.", ["objectivesText"] = "Collect 5 Shiny Treasures along the Kaja'Coast. Progress: Gotta bring your own shovel. I never supply nothin', that's a liability waitin' to happen.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 219934, 233453, 233461, 233469, 233477, 233480, 233484, 233527, 233537, 235346 }, ["rewardCurrencies"] = { { ["id"] = 3118, ["amount"] = 100 }, { ["id"] = 3171, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231064, ["x"] = 0.198, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231064, ["x"] = 0.198, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.198, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5687, ["name"] = "Undermine - World Quests/Repeatables", ["orderIndex"] = 49, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[86178] = { ["id"] = 86178, ["name"] = "Side Gig: Cleanin' the Coast", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84929, 84955, 84971, 84994, 84995, 85263, 85268, 85269, 85270, 85390, 85396, 85397, 85398, 85399, 85400, 85402, 85427, 85428, 85466, 85467, 85472, 85473, 85474, 85487, 85488, 85497, 85498, 85499, 85500, 85512, 85513, 85514, 85515, 85518, 85519, 85524, 85526, 85527, 85528, 85554, 85913, 85914, 85944, 85945, 85960, 85962, 86177, 86178, 86179, 86180, 86943, 86947, 86949, 86952 }, ["description"] = "It's time for the Venture Company to earn a lil' good faith. We're lookin' to hire some efficient workers like yourself to clean up the Kaja'Coast. Could you help us kill some of the kaja'mentals that have gone... well, mental out there? We'll toss some competitive compensation your way.", ["objectivesText"] = "Kill 10 Agitated Kaja'mentals on the Kaja'Coast.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232485, 233478, 233480, 233533, 233534, 233536, 233538, 233539, 233540, 233541, 233542, 234217, 245653 }, ["rewardCurrencies"] = { { ["id"] = 3176, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231065, ["x"] = 0.196, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231065, ["x"] = 0.196, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.196, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5687, ["name"] = "Undermine - World Quests/Repeatables", ["orderIndex"] = 50, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[86179] = { ["id"] = 86179, ["name"] = "Side Gig: Lucky Break's Big Break", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84929, 84955, 84971, 84994, 84995, 85263, 85268, 85269, 85270, 85390, 85396, 85397, 85398, 85399, 85400, 85402, 85427, 85428, 85466, 85467, 85472, 85473, 85474, 85487, 85488, 85497, 85498, 85499, 85500, 85512, 85513, 85514, 85515, 85518, 85519, 85524, 85526, 85527, 85528, 85554, 85913, 85914, 85944, 85945, 85960, 85962, 86177, 86178, 86179, 86180, 86943, 86947, 86949, 86952 }, ["description"] = "You know the Lucky Break Mines over on the Kaja'Coast? Settin' those up was kind of a rush job. Darkfuse didn't exactly give Venture a whole lotta time to reinforce the place. Long story short, there's a good chance the mines might collapse if we don't fix 'em up. That wouldn't be good news for anyone, especially not my wallet. Could you head over and rig up some support beams in the mines? That should do the trick for now.", ["objectivesText"] = "Place 6 Support Beams in the Lucky Break Mines on the Kaja'Coast.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 219934, 232486, 233481, 233482, 233483, 233484, 235373, 235467, 236096 }, ["rewardCurrencies"] = { { ["id"] = 3176, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231065, ["x"] = 0.196, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231065, ["x"] = 0.196, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.196, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5687, ["name"] = "Undermine - World Quests/Repeatables", ["orderIndex"] = 51, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[86180] = { ["id"] = 86180, ["name"] = "Side Gig: Infested Waters", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84929, 84955, 84971, 84994, 84995, 85263, 85268, 85269, 85270, 85390, 85396, 85397, 85398, 85399, 85400, 85402, 85427, 85428, 85466, 85467, 85472, 85473, 85474, 85487, 85488, 85497, 85498, 85499, 85500, 85512, 85513, 85514, 85515, 85518, 85519, 85524, 85526, 85527, 85528, 85554, 85913, 85914, 85944, 85945, 85960, 85962, 86177, 86178, 86179, 86180, 86943, 86947, 86949, 86952 }, ["description"] = "So, my workers were supposed to be loadin' up some kaja'mite over in Zuldazar, but apparently the transport got upended and a shark swallowed the whole crate. I tried submittin' an insurance claim, but they ain't buyin' it. So we got no choice but to get that kaja'mite back ourselves. Down for a little shark huntin'?", ["objectivesText"] = "Retrieve the Swallowed Kaja'mite from the Kaja' Carrying Razormaw on the Kaja'Coast. Progress: You think the shark might end up bein' able to talk? I kinda want a talkin' shark.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 219934, 232486, 232883, 233450, 233452, 233453, 233458, 233461, 233466, 233468, 233469, 233474, 233477, 233481, 233485, 233530, 235508, 236096, 236773 }, ["rewardCurrencies"] = { { ["id"] = 3118, ["amount"] = 100 }, { ["id"] = 3176, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231065, ["x"] = 0.196, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231065, ["x"] = 0.196, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.196, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5687, ["name"] = "Undermine - World Quests/Repeatables", ["orderIndex"] = 48, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[86182] = { ["id"] = 86182, ["name"] = "Ghost Buster", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86182, 86183, 86184, 86185, 86186, 86187, 86188, 86189, 86190, 86191, 86192, 86194, 86195 }, ["series"] = { 86183, 86184 }, ["description"] = "I have been working on the Oasis console and I believe I am ready for the next step. It will involve destruction, so naturally I thought of you. I need you to use a phase conduit to shift into the Untethered Space of K'aresh and retrieve the essence of the ghostly slatebacks. I will explain more when you return.", ["objectivesText"] = "Collect 10 Slateback Essence in the Untethered Space of K'aresh. Progress: Well? Have you succeeded?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229395 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86359 }, ["questLines"] = { { ["id"] = 5705, ["name"] = "Roaming Free", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5705, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86183] = { ["id"] = 86183, ["name"] = "The Power of Gods", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86182, 86183, 86184, 86185, 86186, 86187, 86188, 86189, 86190, 86191, 86192, 86194, 86195 }, ["series"] = { 86182, 86184 }, ["description"] = "Today, we create life. Assuming my calculations are correct--which they are--we can use the essence you gathered along with the data we have collected to create new slatebacks.", ["objectivesText"] = "Help Ve'nari use her machine to create life in the Oasis. Progress: Has the experiment succeeded?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86182 }, ["questLines"] = { { ["id"] = 5705, ["name"] = "Roaming Free", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5705, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86184] = { ["id"] = 86184, ["name"] = "Diminishing Returns", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86182, 86183, 86184, 86185, 86186, 86187, 86188, 86189, 86190, 86191, 86192, 86194, 86195 }, ["series"] = { 86182, 86183 }, ["description"] = "The machine has its uses, but the slatebacks must start breeding so they can sustain themselves. Thus far, they have shown no inclination to do so. Take this device and use it to collect the slatebacks for testing. Om'talad will review the data.", ["objectivesText"] = "Shrink and collect 10 Slateback Roamers . Progress: Have you brought in the slatebacks as requested?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 232432 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86183 }, ["questLines"] = { { ["id"] = 5705, ["name"] = "Roaming Free", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5705, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86185] = { ["id"] = 86185, ["name"] = "Running Free", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86182, 86183, 86184, 86185, 86186, 86187, 86188, 86189, 86190, 86191, 86192, 86194, 86195 }, ["description"] = "Been talkin' to Ve'nari and Om'talad--trying to help the slatebacks get together. Apparently slatebacks used to display virility by engaging in races. Challenge the slateback alpha to a race. At worst, you'll both get some exercise. At best, it will increase the likelihood of a successful pairing.", ["objectivesText"] = "Race the Slateback Alpha . Progress: How's the race going?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86184 }, ["questLines"] = { { ["id"] = 5705, ["name"] = "Roaming Free", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5705, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86186] = { ["id"] = 86186, ["name"] = "The Super Sniffer", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86182, 86183, 86184, 86185, 86186, 86187, 86188, 86189, 86190, 86191, 86192, 86194, 86195 }, ["description"] = "It appears the slatebacks are not secreting the correct pheromones, resulting in them not breeding. We believe this is a side effect of the stasis. The technology was never tested for such an extreme length of time. Until now. Hemet tells me there are creatures called niffen in Azeroth that have expertise in this research. Bring me one from Azj-Kahet. You can use my portal to quickly get there.", ["objectivesText"] = "Travel to Mmarl in Azj-Kahet in Khaz Algar and find a willing niffen to help in the Oasis. Progress: I'm smellin' opportunity all over you!", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 234272, ["x"] = 0.775, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2255, 2371 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 86185 }, ["questLines"] = { { ["id"] = 5705, ["name"] = "Roaming Free", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5705, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[86187] = { ["id"] = 86187, ["name"] = "The Smallest Possible Effort", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2255, ["storyline"] = { 86182, 86183, 86184, 86185, 86186, 86187, 86188, 86189, 86190, 86191, 86192, 86194, 86195 }, ["description"] = "You're a shrewd negotiator, <name>. That's good fun! I'll start packing. You go get some bug bits for me, okay?", ["objectivesText"] = "Collect 50 Bug Bits in Rak-ush and the nearby area. Progress: How'd it go?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232990, 232992 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 234272, ["x"] = 0.775, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 234272, ["x"] = 0.775, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.775, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 86186 }, ["questLines"] = { { ["id"] = 5705, ["name"] = "Roaming Free", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5705, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[86188] = { ["id"] = 86188, ["name"] = "More-shrooms", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2255, ["storyline"] = { 86182, 86183, 86184, 86185, 86186, 86187, 86188, 86189, 86190, 86191, 86192, 86194, 86195 }, ["description"] = "Poor Gharrli needs to be set up while I'm away. The mushrooms you get will help with that. Get eight of them for now. We'll worry about the last one later!", ["objectivesText"] = "Collect 8 Rak-ush Mushrooms from Rak-ush and the nearby area. Progress: Got them mushrooms?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 233010 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 234272, ["x"] = 0.775, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 234272, ["x"] = 0.775, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.775, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 86186 }, ["questLines"] = { { ["id"] = 5705, ["name"] = "Roaming Free", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5705, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[86189] = { ["id"] = 86189, ["name"] = "Fungal Invasion", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2255, ["storyline"] = { 86182, 86183, 86184, 86185, 86186, 86187, 86188, 86189, 86190, 86191, 86192, 86194, 86195 }, ["series"] = { 86190, 86191 }, ["description"] = "I'm sending you somewhere a lil scary, but I'm sure you can handle anything that comes your way! Mind clearing up some of the creatures so it'll be easier for Gharrli to gets the ingredients in the future?", ["objectivesText"] = "Slay 10 monsters in Pillar-nest Vosh. Progress: Did ya get 'em?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 234272, ["x"] = 0.775, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 234272, ["x"] = 0.775, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.775, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 86187, 86188 }, ["questLines"] = { { ["id"] = 5705, ["name"] = "Roaming Free", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5705, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[86190] = { ["id"] = 86190, ["name"] = "One Mushroom to Rule Them All", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2255, ["storyline"] = { 86182, 86183, 86184, 86185, 86186, 86187, 86188, 86189, 86190, 86191, 86192, 86194, 86195 }, ["series"] = { 86189, 86191 }, ["description"] = "We've been working on a new scent to delight the locals, but we have one more ingredient we need. It's a rare mushroom from Pillar-nest Vosh. Get that, and Gharrli can finish the fragrance while I'm away!", ["objectivesText"] = "Collect a Voshsroom from Pillar-nest Vosh. Progress: Did you get that mushroom?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 233011 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 234272, ["x"] = 0.775, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 234272, ["x"] = 0.775, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.775, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 86187, 86188 }, ["questLines"] = { { ["id"] = 5705, ["name"] = "Roaming Free", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5705, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[86191] = { ["id"] = 86191, ["name"] = "Smell Ya Later", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2255, ["storyline"] = { 86182, 86183, 86184, 86185, 86186, 86187, 86188, 86189, 86190, 86191, 86192, 86194, 86195 }, ["series"] = { 86189, 86190 }, ["description"] = "Well. That's everything, I think. I'm ready for adventure!", ["objectivesText"] = "Meet Rhubarn and Ve'nari in the Oasis on K'aresh. Progress: This is a big sniff for me, <name>!", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 234272, ["x"] = 0.775, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.775, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2255, 2371 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 86189, 86190 }, ["questLines"] = { { ["id"] = 5705, ["name"] = "Roaming Free", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5705, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86192] = { ["id"] = 86192, ["name"] = "On a Bed of Bones They Lie", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86182, 86183, 86184, 86185, 86186, 86187, 86188, 86189, 86190, 86191, 86192, 86194, 86195 }, ["series"] = { 86194, 86195 }, ["description"] = "I was talking to Om'talad over there. Apparently, slatebacks used to gather bones for birthing nests, which is kinda funny on account of them being herbivores! Normally they get bones from dead animals, but we don't have any in the eco-domes. Can you gather some bones from creatures outside the Oasis for me? They'd appreciate it, and so would I!", ["objectivesText"] = "Collect 8 Creature Bones from around K'aresh and place them in a pile in the Oasis. Progress: Have you built the nests as requested?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 233016 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 234316, ["x"] = 0.76, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86194 }, ["questLines"] = { { ["id"] = 5705, ["name"] = "Roaming Free", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5705, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86193] = { ["id"] = 86193, ["name"] = "Life for Life", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85238, 85239, 85240, 85241, 86193 }, ["series"] = { 85241 }, ["description"] = "We're too late! The ritual is self-sustaining. It'll draw in more power until it overloads the machine. Tazavesh, the eco-domes--nothing will be safe if the failure cascades. If we remove the infusers, the energy should dissipate before it can cause any harm. It's too powerful though. It will tear you apart if you try to get close, and I'm not strong enough to do it alone... Unbind me. I'll wrap you in my energy. That should be enough to let you get close to the machine.", ["objectivesText"] = "Stop the machine.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 245737, 245738 }, ["rewardChoices"] = { 245737, 245738 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 15 }, { ["id"] = 3008, ["amount"] = 15 }, { ["id"] = 3129, ["amount"] = 350 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 233500, ["x"] = 0.586, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 233503, ["x"] = 0.595, ["y"] = 0.606 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 85241 }, ["questLines"] = { { ["id"] = 5715, ["name"] = "A Stranger's Gift", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86194] = { ["id"] = 86194, ["name"] = "The Scent of Love", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86182, 86183, 86184, 86185, 86186, 86187, 86188, 86189, 86190, 86191, 86192, 86194, 86195 }, ["series"] = { 86192, 86195 }, ["description"] = "I was out and about checking on these slatebacks of yours, and your broker friends are wrong! The slatebacks are giving off the smell of love, but it's just not strong enough to overpower all this dry air on K'aresh. Not yet anyway! I whipped up a batch of pheromones that should fix them right up! Take this sprayer and douse the slatebacks. That'll get things started!", ["objectivesText"] = "Douse 12 Slateback Roamers in pheromones. Progress: Have you got them smellin' better?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 233195 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 234316, ["x"] = 0.76, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 234316, ["x"] = 0.76, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86191 }, ["questLines"] = { { ["id"] = 5705, ["name"] = "Roaming Free", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5705, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86195] = { ["id"] = 86195, ["name"] = "Slateback Soccer", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86182, 86183, 86184, 86185, 86186, 86187, 86188, 86189, 86190, 86191, 86192, 86194, 86195 }, ["series"] = { 86192, 86194 }, ["description"] = "Oh my. I never thought I would see the day. A newly born slateback! I have been running standard non-invasive medical tests. However, I also need a test of its coordination. I have been noticing it chasing this ball around. Perhaps you could throw it and observe the results?", ["objectivesText"] = "Catch a ball 10 times while playing with your Slateback Cub. Progress: Has the cub responded to the ball?", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 229420 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86192 }, ["questLines"] = { { ["id"] = 5705, ["name"] = "Roaming Free", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5705, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86196] = { ["id"] = 86196, ["name"] = "Give Me Fuel", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86196, 86200, 86201 }, ["description"] = "Thank you for coming, <name>. There are many dangers we face when attempting to terraform K'aresh , not the least of which is attracting creatures that see the domes as convenient energy sources. Eco-Dome: Springhost is plagued with them. I have a plan to remedy this, but I could use your help preparing.", ["objectivesText"] = "Gather Firebud Pollen for Om'vek. Progress: Have you gathered enough pollen for me?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 233009 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 234216, ["x"] = 0.498, ["y"] = 0.574 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 234216, ["x"] = 0.498, ["y"] = 0.574 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.574 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 84967 }, ["questLines"] = { { ["id"] = 5735, ["name"] = "Anyway, Here's Firewall", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86200] = { ["id"] = 86200, ["name"] = "Give Me Fire", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86196, 86200, 86201 }, ["description"] = "Now we need to process this firebud pollen into fuel. And with this fuel, the downfall of these pests will be assured.", ["objectivesText"] = "Process the Firebud Pollen into fuel. Progress: Just place the firebud pollen into the containers on the console, and we'll get it refined into something we can use.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 234216, ["x"] = 0.498, ["y"] = 0.574 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 234216, ["x"] = 0.498, ["y"] = 0.574 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.574 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86196 }, ["questLines"] = { { ["id"] = 5735, ["name"] = "Anyway, Here's Firewall", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86201] = { ["id"] = 86201, ["name"] = "Watch Me Make These Bugs Expire", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86196, 86200, 86201 }, ["description"] = "Now that we've processed this firebud pollen, we can bring some flame to bear against our pests in Eco-Dome: Springhost.", ["objectivesText"] = "Use the flamethrower to force the glutted creepers off of the dome, then destroy them. Progress: Have you cleansed the eco-dome with the flame I've provided?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 233028, 245711, 245712 }, ["rewardChoices"] = { 245711, 245712 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 15 }, { ["id"] = 3008, ["amount"] = 15 }, { ["id"] = 3129, ["amount"] = 350 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 234216, ["x"] = 0.498, ["y"] = 0.574 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 234216, ["x"] = 0.498, ["y"] = 0.574 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.574 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86200 }, ["questLines"] = { { ["id"] = 5735, ["name"] = "Anyway, Here's Firewall", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86203] = { ["id"] = 86203, ["name"] = "Operation: Floodgate", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 86203 }, ["description"] = "My sources report that Darkfuse forces have infiltrated the Waterworks down in the Ringing Deeps. They have seized the power generators there and are rerouting the electricity somewhere else. We do not know their directive, but I am not keen to find out. Dismantle their operation and I will see that you are adequately rewarded.", ["objectivesText"] = "Biergoth wants you to confront Geezle Gigazap within Operation: Floodgate. Progress: Have you ended the operation?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 2815, 2899, 2902, 3056, 237014 }, ["rewardChoices"] = { 2815, 2899, 2902, 3056, 237014 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 225 }, { ["id"] = 2897, ["amount"] = 1500 }, { ["id"] = 2899, ["amount"] = 1500 }, { ["id"] = 2902, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.483333 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "dungeon" },
[86204] = { ["id"] = 86204, ["name"] = "Liberation of Undermine: The House Loses", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 85190, 85191, 85192, 86204, 87297, 87321 }, ["description"] = "Gallywix has been a stain on Undermine since he forgot where he came from. Gallywix's always been steppin' on the little guy--greed and always looking for the \"next best thing\" is just makin' him step even harder. Seeking power just for its own sake? Forget that! The power lies with the people. Let's bring Gallywix some swift justice, <name>.", ["objectivesText"] = "Defeat Chrome King Gallywix in the Liberation of Undermine .", ["rewardGold"] = 20496000, ["rewardXP"] = 20380, ["rewardItems"] = { 230936, 236954 }, ["rewardCurrencies"] = { { ["id"] = 3118, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 233482, ["x"] = 0.435, ["y"] = 0.509 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 238006, ["x"] = 0.275, ["y"] = 0.71 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.509 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "raid", ["sourceQuests"] = { 85780 }, ["questLines"] = { { ["id"] = 5694, ["name"] = "Homecoming", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5694, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346, ["db2QuestHubAreaPoiID"] = 8189 },
[86261] = { ["id"] = 86261, ["name"] = "Homeward Bound to Safer Shores", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 86261 }, ["description"] = "<Upon seeing you walk into camp this dirty, matted dog perks up. His tail wags when he sees the familiar face of the person who found his favorite toy. The faded tag around its neck reads: \"The Duke.\" He seems to have been here since the Kul Tirans disappeared and has somehow survived the isle's many perils. \"The Duke\" looks at you longingly and nuzzles your hand, seeking affection.>", ["objectivesText"] = "Pet the goodest boy. Progress: <The dog looks at you with hope gleaming in its old eyes.>", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 233027, 233056 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 234357, ["x"] = 0.6832, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 234357, ["x"] = 0.6832, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.6832, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 86240 } },
[86271] = { ["id"] = 86271, ["name"] = "Sanity's Rest", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 86271, 86272, 86273, 86274, 86275, 86276, 86277, 86575, 86697 }, ["series"] = { 86272 }, ["description"] = "Looks like another one down the hatch, huh? I'm tellin' ya, these Black Blood dig sites are chewin' up workers faster than I can hire 'em! Every day, one of my guys goes down with the shakes, sproutin' nonsense about seein' tentacles in the dirt... Take 'em to see my guy, Stitchoaf , in the cave over there. He's brewin' up some kinda \"cure.\" See if he can't help this poor guy out.", ["objectivesText"] = "Carry the Incapacitated Worker inside the cave in the Ringing Deeps . Progress: I'm already short. I mean, short-handed!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 233420, ["x"] = 0.684, ["y"] = 0.964 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 234293, ["x"] = 0.675, ["y"] = 0.968 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.684, ["y"] = 0.964 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 83139 }, ["questLines"] = { { ["id"] = 5736, ["name"] = "Sanity's Rest", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[86272] = { ["id"] = 86272, ["name"] = "Counteracting the Black Blood", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 86271, 86272, 86273, 86274, 86275, 86276, 86277, 86575, 86697 }, ["series"] = { 86271 }, ["description"] = "Black Blood? Nasty stuff. Glad I got this mask here. Nobody should be workin' in that mess. It gets inside ya, messes with ya head. Some folks get dizzy, seein' things that ain't there. Some even sproutin' strange scales. Makes me itch thinkin' about it. An' there ain't no cure. Best we can do is ease the pain an' maybe help the symptoms a bit. I got a \"cure\" brewin'. It's just soup, but they don't know that. It's almost \"done,\" but it could use some flavor.", ["objectivesText"] = "Help Stitchoaf ease the goblin's symptoms in the Ringing Deeps . Progress: I got the pot simmerin'. All it needs is a few finishing touches.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 234293, ["x"] = 0.675, ["y"] = 0.968 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 234293, ["x"] = 0.675, ["y"] = 0.968 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.675, ["y"] = 0.968 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 86271 }, ["questLines"] = { { ["id"] = 5736, ["name"] = "Sanity's Rest", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[86273] = { ["id"] = 86273, ["name"] = "Visit to the Shop", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 86271, 86272, 86273, 86274, 86275, 86276, 86277, 86575, 86697 }, ["description"] = "That's all we can do for now. But if you really wanna help us fix all this, you ought to talk to our local engineer--uh, Tricksy... or maybe Trixxy. She's got her workshop set up further down in the cave, and Benny's got her tinkerin' away day and night on some kind of... \"permanent solution.\" Odd, but she's sharp as a blade. If anyone's got a chance at makin' people safe down here, it's her.", ["objectivesText"] = "Find Trixxie Boltcrank 's workshop further in the depths of Sanity's Rest in the Ringing Deeps .", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 234293, ["x"] = 0.675, ["y"] = 0.968 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 234294, ["x"] = 0.672, ["y"] = 0.98 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.675, ["y"] = 0.968 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 86272 }, ["questLines"] = { { ["id"] = 5736, ["name"] = "Sanity's Rest", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[86274] = { ["id"] = 86274, ["name"] = "Automation Solution", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 86271, 86272, 86273, 86274, 86275, 86276, 86277, 86575, 86697 }, ["description"] = "As you have probably figured out, Black Blood exposure is bad for your health. And that's a problem for our operation. We can't keep replacin' our workers. It's expensive, and it ain't ethical. So! What's the solution? Replacin' our workers with my fully-automated bots. These beauties don't get affected by Black Blood exposure. They just dig and haul--precision, efficiency, an' no more sick workers! I just need more scrap to patch 'em up. You in?", ["objectivesText"] = "Collect metal scrap lying around the cave in the Ringing Deeps . Progress: Time is... you know what it is.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 233015 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 234294, ["x"] = 0.672, ["y"] = 0.98 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 234294, ["x"] = 0.672, ["y"] = 0.98 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.98 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 86273 }, ["questLines"] = { { ["id"] = 5736, ["name"] = "Sanity's Rest", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[86275] = { ["id"] = 86275, ["name"] = "Bug Exterminator Needed", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 86271, 86272, 86273, 86274, 86275, 86276, 86277, 86575, 86697 }, ["description"] = "Well, if ya really wanna help... We're safe in this cave from the Black Blood--or we were until it was crawlin' with nasty bloodfeasters . The ugly little creeps always had a taste for blood--but now they're gonzo for Black Blood! I got a hunch they're spreadin' Black Blood poisonin' when they bite us. I can't work like this. Each time I see one in a scrap pile, I wanna scream. They're gross, an' I don't wanna get bit an' start seein' things. Stomp 'em flat so we can keep safe an' keep workin'!", ["objectivesText"] = "Kill Bloodfeasters inside the cave in the Ringing Deeps . Progress: <Humming a catchy tune.> Ahh! Oh, I thought you were another bloodfeaster .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 234294, ["x"] = 0.672, ["y"] = 0.98 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 234294, ["x"] = 0.672, ["y"] = 0.98 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.98 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 86273 }, ["questLines"] = { { ["id"] = 5736, ["name"] = "Sanity's Rest", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[86276] = { ["id"] = 86276, ["name"] = "Out in the Fields", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 86271, 86272, 86273, 86274, 86275, 86276, 86277, 86575, 86697 }, ["description"] = "If Trixxie has those bots ready, then all we gotta do is mark where they needa work. Head out, fire a flare, and deploy those tin cans--an' see if they actually, yanno, work. Watch for glitchy servos, smokin' coolant vents... You know the drill. If they start doin' their work? Great. If not, well... I might be callin' some workers back in to clean up.", ["objectivesText"] = "Deploy goblin bots in the Writhing Fields in the Ringing Deeps . Progress: The longer it takes us to deploy those bots, the longer my workers gotta be in that Black Blood sludge. And the longer I have to pay 'em!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 233420, ["x"] = 0.684, ["y"] = 0.964 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 233420, ["x"] = 0.684, ["y"] = 0.964 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.684, ["y"] = 0.964 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 86575 }, ["questLines"] = { { ["id"] = 5736, ["name"] = "Sanity's Rest", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[86277] = { ["id"] = 86277, ["name"] = "\"Worm\" Food No More", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 86271, 86272, 86273, 86274, 86275, 86276, 86277, 86575, 86697 }, ["description"] = "We've got the bots workin' the fields, but there are still flesh-an'-blood workers out there. They need to be able to get back here safely, an' they can't do that with a giant, slobberin' \"worm\" doggin' their steps 'cause it's got a taste for goblin meat. So, here's the job: I don't want that thing scared off, I want it gone. Go out there, track down that overgrown \"earthworm\", and make sure it dies. Don't hold back--I want guts everywhere. Payback for all the goblins it's had for lunch.", ["objectivesText"] = "Kill the Maddened Eyestalk in the Writhing Fields in the Ringing Deeps .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235619, 235620, 235621, 235622 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 233420, ["x"] = 0.684, ["y"] = 0.964 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 233420, ["x"] = 0.684, ["y"] = 0.964 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.684, ["y"] = 0.964 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 86575 }, ["questLines"] = { { ["id"] = 5736, ["name"] = "Sanity's Rest", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[86297] = { ["id"] = 86297, ["name"] = "Morale Reflects Leadership", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "Undermine swallows everything that's good. Now it got Laslo. We need to find who's in charge now and figure out how to keep 'em safe. I think I know where to start askin'.", ["objectivesText"] = "Find the goblin in charge of the Bilgewater Cartel in Undermine . Progress: This ain't no place for good goblins.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 229223, ["x"] = 0.455, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 229223, ["x"] = 0.455, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83109 }, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
