[86327] = { ["id"] = 86327, ["name"] = "The Tempest Fields", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84826, 84827, 84831, 84834, 84838, 84848, 84867, 84869, 84876, 84879, 84883, 84910, 85730, 86327, 86332 }, ["series"] = { 84834 }, ["description"] = "Those Wastelanders have that broker's ribbon. We must get it back or you will never be able to reach Dimensius. They are deliciously bloodthirsty. I think we should lure them to our cause. We need an army for the coming battle, and they have the numbers for that. The void glass lies between their camp and us. That might provide a means to manipulate--speak with the Wastelanders.", ["objectivesText"] = "Meet Xal'atath in the Tempest Fields.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230602, ["x"] = 0.684, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 233878, ["x"] = 0.64, ["y"] = 0.47 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.684, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 85730 }, ["questLines"] = { { ["id"] = 5717, ["name"] = "Desert Power", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5717, ["questLineOrder"] = 2 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5717, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86332] = { ["id"] = 86332, ["name"] = "Distribution of Power", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84826, 84827, 84831, 84834, 84838, 84848, 84867, 84869, 84876, 84879, 84883, 84910, 85730, 86327, 86332 }, ["description"] = "My people need energy to live. We can harvest it from the pylons that were set out to collect it or hunt the energy scavengers that have siphoned off what is ours. Let's gather today's meager bounty of energy and then distribute it to my people. If we are to go to war together, it will help us both to know the character of your allies.", ["objectivesText"] = "Collect and distribute harvested energy in and around the Wastelander Camp. Progress: In the wastes of Merciless K'aresh , survival is all-important. We take what we need to ensure our future.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235051 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 234190, ["x"] = 0.61, ["y"] = 0.4 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230292, ["x"] = 0.63, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.61, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 84848 }, ["questLines"] = { { ["id"] = 5717, ["name"] = "Desert Power", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5717, ["questLineOrder"] = 2 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5717, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
