[86342] = { ["id"] = 86342, ["name"] = "Soaring over K'aresh", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 85459, 85460, 85461, 85462, 85465, 85470, 85481, 85710, 85721, 86342, 88659, 88975, 88980, 88981, 89056, 89057, 89065, 89192, 89195, 89197, 89198, 89209, 89210, 89212, 89213, 89221, 89238, 89240, 89242, 89254, 89297 }, ["description"] = "We've been taking the k'arrocs out for flights outside of the Oasis. Perhaps you might be interested in riding one?", ["objectivesText"] = "Complete the \"Oasis Overdrive\" race.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 5 }, { ["id"] = 3284, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5704, ["name"] = "Eco-Dome Repeatables", ["orderIndex"] = 20, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86348] = { ["id"] = 86348, ["name"] = "Fox Bane", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86348, 86350, 86351, 86360, 86361, 86362, 86392 }, ["description"] = "You have done well with the slatebacks. Will you do as well with the thorntails? If we are to improve their numbers, we will need some of their astral essence to produce new ones. Procure it for me.", ["objectivesText"] = "Collect 10 Thorntail Essences while Phase Diving in Untethered Space on K'aresh. Progress: Do you have the essences?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237896 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86195 }, ["questLines"] = { { ["id"] = 5742, ["name"] = "Fox-strut", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5742, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86349] = { ["id"] = 86349, ["name"] = "Lapbug Essence Hunter", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86349, 87291, 87292, 87293, 87294 }, ["description"] = "Thorntails are known to hunt smaller creatures. If we are to increase their numbers, we should also increase the numbers of the lapbug population to compensate. Gather some of their astral essence. You can use a phase conduit to get into Untethered Space.", ["objectivesText"] = "Collect 10 Lapbug Essence in Untethered Space on K'aresh. Progress: How fare your efforts?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229393 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86195 }, ["questLines"] = { { ["id"] = 5779, ["name"] = "Lil' Lapbugs", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5779, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86350] = { ["id"] = 86350, ["name"] = "Eau de Foxy", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86348, 86350, 86351, 86360, 86361, 86362, 86392 }, ["series"] = { 86351, 86362 }, ["description"] = "It's my favorite <race>! I've been sniffing around the Oasis and I've whipped up a batch of pheromones for those thorntails out there. Can you give them a good dose for me? Let Om'talad know when you're done--he was lookin' to do some testing too!", ["objectivesText"] = "Douse 8 Regal Thorntails in pheromones. Progress: Did you apply the pheromones?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 233487 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 234316, ["x"] = 0.76, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86348 }, ["questLines"] = { { ["id"] = 5742, ["name"] = "Fox-strut", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5742, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86351] = { ["id"] = 86351, ["name"] = "Strike a Pose", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86348, 86350, 86351, 86360, 86361, 86362, 86392 }, ["series"] = { 86350, 86362 }, ["description"] = "We are running low on food for the thorntails. It is odd. They should be hunting for a larger portion of their food. Can you take some pictures of them for documentation purposes? Perhaps it will shed some light on the issue.", ["objectivesText"] = "Document 10 Regal Thorntails. Progress: Have you taken the photos?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 233488 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86362 }, ["questLines"] = { { ["id"] = 5742, ["name"] = "Fox-strut", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5742, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86352] = { ["id"] = 86352, ["name"] = "Hunting for a Good Author", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 84822, 86352, 86353, 86354, 86355, 86356, 86357, 86358, 86359 }, ["description"] = "I am growing concerned that we may be in danger of overbalancing the ecosystem. We require a consultant. Have you read \"The Green Hills of Stranglethorn?\" I enjoyed it a great deal. The author appears to have turned from hunter to conservationist. Do not ask how I acquired this information. However, these are precisely the two skills I need. Retrieve him. Last I heard, he was in the Azure Span on the Dragon Isles. Use the portal to travel there.", ["objectivesText"] = "Look for Hemet Nesingwary in the Azure Span on the Dragon Isles.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 234745, ["x"] = 0.188, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2024, 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 85262 }, ["questLines"] = { { ["id"] = 5744, ["name"] = "Nesingwary Necessities", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5744, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[86353] = { ["id"] = 86353, ["name"] = "Protecting the Young", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2024, ["storyline"] = { 84822, 86352, 86353, 86354, 86355, 86356, 86357, 86358, 86359 }, ["series"] = { 84822, 86354 }, ["description"] = "These gnolls have kidnapped children from Iskaara. I was going to sneak in and rescue them, but I could use some help. Let's split up. Two sets of eyes are better than one. If you spot any kids, tell 'em to gather at this spot. Tell them Hemet sent you. They know me.", ["objectivesText"] = "Rescue 6 Tuskarr Children in the Brakenhide Brambles. Progress: We have to rescue those children! Who knows what the gnolls will do to them?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 234745, ["x"] = 0.188, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 234745, ["x"] = 0.188, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.188, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 86352 }, ["questLines"] = { { ["id"] = 5744, ["name"] = "Nesingwary Necessities", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5744, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[86354] = { ["id"] = 86354, ["name"] = "A Percussive Antidote", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 13646, ["mapID"] = 2024, ["series"] = { 86353, 84822 }, ["description"] = "These gnolls have been corrupting the land--growing too big and throwing off the ecosystem. We need to stop them, and let this land recover from all that decay.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 234745, ["x"] = 0.188, ["y"] = 0.398, ["mapID"] = 2024 } }, ["ends"] = { { ["npcID"] = 234745, ["x"] = 0.188, ["y"] = 0.398, ["mapID"] = 2024 } }, ["coords"] = { ["x"] = 0.188, ["y"] = 0.398, ["source"] = "quest_giver", ["mapID"] = 2024 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 86352 }, ["questLines"] = { { ["id"] = 5744, ["name"] = "Nesingwary Necessities", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5744, ["questLineOrder"] = 2 } } },
[86355] = { ["id"] = 86355, ["name"] = "Using the Whole Animal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2024, ["storyline"] = { 84822, 86352, 86353, 86354, 86355, 86356, 86357, 86358, 86359 }, ["description"] = "K'aresh, eh? Sounds a bit like Netherstorm. I've been staying with the tuskarr for a while an' learning what I can from 'em. I was supposed to gather meat for the evening meal. If you can do that, I can start packing.", ["objectivesText"] = "Collect 20 Bruffalon Meat nearby in the Azure Span. Progress: Make sure you harvest the whole animal. It'll go faster.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 234036, 234457 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 235290, ["x"] = 0.136, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 235290, ["x"] = 0.136, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.136, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 84822 }, ["questLines"] = { { ["id"] = 5744, ["name"] = "Nesingwary Necessities", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5744, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[86356] = { ["id"] = 86356, ["name"] = "Sustainable Harvesting", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2024, ["storyline"] = { 84822, 86352, 86353, 86354, 86355, 86356, 86357, 86358, 86359 }, ["description"] = "I'd like to repay the tuskarr's kindness for hosting me. They have some repairs that need doing. Can ye gather some wood for them? They can handle the repairs themselves--they just need a bit of help gatherin' the materials.", ["objectivesText"] = "Collect 12 Chopped Wood nearby in the Azure Span. Progress: Did ye get the wood?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 234452 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 235290, ["x"] = 0.136, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 235290, ["x"] = 0.136, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.136, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 84822 }, ["questLines"] = { { ["id"] = 5744, ["name"] = "Nesingwary Necessities", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5744, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[86357] = { ["id"] = 86357, ["name"] = "Time for Noms", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2024, ["storyline"] = { 84822, 86352, 86353, 86354, 86355, 86356, 86357, 86358, 86359 }, ["series"] = { 86358, 86359 }, ["description"] = "The local ottuks have a symbiotic relationship with the tuskarr, and it's feeding time. Can ye put out some of the meat ye gathered for them?", ["objectivesText"] = "Place a Pile of Meat for the local ottuks just outside Iskaara. Progress: Have ye fed those ottuks yet?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 235290, ["x"] = 0.136, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 235290, ["x"] = 0.136, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.136, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 86355, 86356 }, ["questLines"] = { { ["id"] = 5744, ["name"] = "Nesingwary Necessities", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5744, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[86358] = { ["id"] = 86358, ["name"] = "Any Old Excuse", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2024, ["storyline"] = { 84822, 86352, 86353, 86354, 86355, 86356, 86357, 86358, 86359 }, ["series"] = { 86357, 86359 }, ["description"] = "This'll be the hardest task for ye yet. The ottuk pups have to get acclimatized to touch. I... I need ye to go pet them. Hard work, but it has to be done.", ["objectivesText"] = "Pet 5 Ottuk Pups outside of Iskarra. Progress: What do you think of the wee li'l pups?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 235290, ["x"] = 0.136, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 235290, ["x"] = 0.136, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.136, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 86355, 86356 }, ["questLines"] = { { ["id"] = 5744, ["name"] = "Nesingwary Necessities", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5744, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[86359] = { ["id"] = 86359, ["name"] = "Return to K'aresh", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2024, ["storyline"] = { 84822, 86352, 86353, 86354, 86355, 86356, 86357, 86358, 86359 }, ["series"] = { 86357, 86358 }, ["description"] = "Right then. I'm ready to go. How do we get there?", ["objectivesText"] = "Return to the Oasis on K'aresh.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 235290, ["x"] = 0.136, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.136, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 2024, 2371 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 86357, 86358 }, ["questLines"] = { { ["id"] = 5744, ["name"] = "Nesingwary Necessities", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5744, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86360] = { ["id"] = 86360, ["name"] = "Fantastic Ms. Fox", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86348, 86350, 86351, 86360, 86361, 86362, 86392 }, ["description"] = "The thorntails aren't hunting like they're supposed tae? Ve'nari said that lapbugs aren't their normal prey. We'll need to teach the matriarch how to hunt them ourselves!", ["objectivesText"] = "Teach the Thorntail Matriarch to hunt Lapbug Skitterers 10 times. Progress: Is she hunting properly?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86351 }, ["questLines"] = { { ["id"] = 5742, ["name"] = "Fox-strut", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5742, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86361] = { ["id"] = 86361, ["name"] = "Are You Kitting Me?", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86348, 86350, 86351, 86360, 86361, 86362, 86392 }, ["description"] = "We need to ensure that the thorntail kits' reflexes are sharp so they are effective hunters when they grow up. Please take this ball and have a kit chase it. For scientific purposes, of course.", ["objectivesText"] = "Catch a ball 10 times while playing with your Thorntail Kit. Progress: Has a kit been sufficiently trained?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 229420 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86360 }, ["questLines"] = { { ["id"] = 5742, ["name"] = "Fox-strut", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5742, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86362] = { ["id"] = 86362, ["name"] = "What Does the Fox Dream?", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86348, 86350, 86351, 86360, 86361, 86362, 86392 }, ["series"] = { 86350, 86351 }, ["description"] = "I'd like to get some medical data on how the thorntails are doing. Please gather some blood samples for me. Use these to tranquilize the creatures. There should be more than enough blood for sampling on the darts when you retrieve them.", ["objectivesText"] = "Collect 5 Blood Samples. Progress: Have you gathered the samples we need?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 233552 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86350 }, ["questLines"] = { { ["id"] = 5742, ["name"] = "Fox-strut", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5742, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86363] = { ["id"] = 86363, ["name"] = "The Better Part of Valorstones", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 86363 }, ["description"] = "It's been many months since we arrived in Dornogal and there's still more to learn of Valorstones . It turns out they can be found beyond Azeroth! This discovery opens up entirely new avenues of research. With new research comes a need for new supplies. Bring me some, and we'll help upgrade your gear to new heights.", ["objectivesText"] = "Collect 50 Valorstones while adventuring in Khaz Algar, Undermine, and K'aresh, then return to Cuzolth and upgrade a piece of Season 3 equipment. Progress: There's no need to hurry. But if you wouldn't mind hurrying anyway...", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219226, ["x"] = 0.518, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219226, ["x"] = 0.518, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[86364] = { ["id"] = 86364, ["name"] = "Crests from the Ether", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 86364 }, ["description"] = "Wonderful. Valorstones are capable of upgrading lower-level equipment on their own. That being said, Valorstones can only do so much. More powerful equipment will also require Ethereal Crests to upgrade to their full potential. These crests are rewarded through many different activities. Ethereal Crests have four tiers, and more dangerous tasks reward you with higher-tier crests. Bring me fifteen Weathered Ethereal Crests, and we can help you upgrade some gear further.", ["objectivesText"] = "Acquire 15 Weathered Ethereal Crests by defeating unique creatures, conquering raids, completing world activities, or by looting caches. Then return to Vaskarn in Dornogal. Progress: If you're having a hard time finding Weathered Ethereal Crests, you can search for hidden treasures around Khaz Algar, Undermine, or K'aresh. There's no shortage of those treasures!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 236953 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219226, ["x"] = 0.518, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219226, ["x"] = 0.518, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 86363 }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[86365] = { ["id"] = 86365, ["name"] = "Crest Transmutation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 86365 }, ["description"] = "My friend, these Crests are magnificent. It looks like they can be transmuted into different tiers! If you find yourself no longer in need of a lower-tier Crest, then I can transmute them to be more powerful. I can also transmute Crests into a weaker tier. Let's practice the transmutation process. Here's a few Carved Ethereal Crests. Speak to me and I can transform them into Weathered Ethereal Crests for you.", ["objectivesText"] = "Bring 15 Carved Ethereal Crests to Vaskarn in Dornogal, then trade them for a Pouch of Weathered Ethereal Crests. Progress: If you lose those Carved Ethereal Crests, you can find more from powerful creatures around K'aresh. I've heard there's quite a variety of them!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 236953 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219226, ["x"] = 0.518, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219226, ["x"] = 0.518, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 86363 }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
