[86392] = { ["id"] = 86392, ["name"] = "Foxy Footwork", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86348, 86350, 86351, 86360, 86361, 86362, 86392 }, ["description"] = "Your efforts in teaching the matriarch to hunt have been too effective, it seems. Several broker guards have been attacked recently. Since you caused this issue, I need you to solve it. Best the thorntail matriarch in a fight. The rest of the thorntails will back down once their leader is humbled.", ["objectivesText"] = "Challenge and defeat the Thorntail Matriarch . Progress: Have you made a suitable display of dominance?", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86361 }, ["questLines"] = { { ["id"] = 5742, ["name"] = "Fox-strut", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5742, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
