[86408] = { ["id"] = 86408, ["name"] = "My Hole in the Wall", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84376, 84378, 84379, 84380, 84381, 86408 }, ["series"] = { 84381 }, ["description"] = "Never thought when I was lookin' for security I'd get some kinda bona fide hero. I can see why rumors about you spread so quickly. You like helpin' people, don'tcha? Look I don't wanna get all sappy or nothin'. It's just... What you did for everyone... < Mama Keara shakes her head and regains her composure.> Anyways. A deal's a deal. Sign your name on the apartment log over there and you'll be an official Barrelbottom resident. I'd say you've definitely earned it.", ["objectivesText"] = "Inspect the Barrelbottom Apartment Log.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 245306 }, ["rewardCurrencies"] = { { ["id"] = 3118, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228857, ["x"] = 0.395, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228857, ["x"] = 0.395, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questTurnInID"] = 228857, ["questType"] = "standard", ["sourceQuests"] = { 84381 }, ["questLines"] = { { ["id"] = 5685, ["name"] = "Property Devalued", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
