[86417] = { ["id"] = 86417, ["name"] = "Ready Check", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "We've done what we can here, <name>. Now we just have to hope it'll be enough. Maybe Gazlowe's got a plan. Maybe now we're ready to face down Gallywix. Let's formulate our next steps. I enjoy a bit of formulation from time to time.", ["objectivesText"] = "Check in with Grimla about what to do next.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225876, ["x"] = 0.565, ["y"] = 0.6755 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 230268, ["x"] = 0.564, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.6755 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83204, 83205 }, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
