[86470] = { ["id"] = 86470, ["name"] = "Fearin's Version", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15716, ["mapID"] = 14, ["storyline"] = { 86470 }, ["description"] = "I need someone to deliver these requests to people around the city. We've been shorthanded and I haven't gotten around to distributing this bunch. As my newest deputy, this responsibility is now yours! Most of these are simple and straightforward. Requests for supplies and such for the Stromic army. Joseph is another matter. He's been inciting the populace with inflammatory rhetoric. He needs to stop or we will have to arrest him. We can't afford another riot breaking out right now.", ["objectivesText"] = "Deliver Brewston's requests to people in Stromgarde.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15716 } }, ["questType"] = "standard" },
