[86482] = { ["id"] = 86482, ["name"] = "A Lifeline", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 86482 }, ["description"] = "<The snapdragon barely moves as you approach. It is clearly weak and seems much smaller than it should be. Perhaps Zexel Fingersnap has something for sale that could help get it back up on its feet?>", ["objectivesText"] = "Talk to Zexel Fingersnap. Progress: <The small snapdragon looks wearily at you with dull eyes.>", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 168970, 232466, 233489, 233493, 233494, 233495, 233497, 233498, 233499, 233500, 233501, 234426 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 235216, ["x"] = 0.708, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 235216, ["x"] = 0.708, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 84726 } },
[86483] = { ["id"] = 86483, ["name"] = "Snap To It", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 86483 }, ["description"] = "<The snapdragon seems to recognize you as you approach, its ear fins wiggling with anticipation. Not only has it grown bigger overnight, but its scales have changed to a seaweed-green color similar to the Kaja'cola-braised meat you fed it. Between it's talons lie morsels of meaty rations it has stolen from nearby invading forces. The snapdragon looks at you expectantly. Perhaps you can bring it more meaty rations by slaying the invading forces on the island.>", ["objectivesText"] = "Find 5 Meaty Rations from the invading forces: Pirates, Naga or Vrykul. Progress: <The snapdragon paws the ground and then looks at you expectantly. Its eyes glitter with intelligence.>", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 6256, 6529, 19022, 81805, 81806, 81807, 81808, 81809, 81810, 81811, 81812, 81813, 152668, 162297, 166846, 168970, 224807, 233489, 233493, 233494, 233495, 233497, 233498, 233499, 233500, 233501, 234443, 242241 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 235237, ["x"] = 0.708, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 235237, ["x"] = 0.708, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 86482 } },
[86484] = { ["id"] = 86484, ["name"] = "Temper Like A Tempest", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 86484 }, ["description"] = "<The snapdragon seems to recognize you as you approach, its ear fins wiggling with anticipation. Not only has it grown bigger overnight, but its scales have changed color from the meat you fed it yesterday. Between it's talons lie the remains of a sea creature from the last Seafury Tempest. The snapdragon looks at you expectantly. Perhaps by venturing into the Seafury Tempest and slaying creatures there you can bring it more meat.>", ["objectivesText"] = "Speak to Suzie Boltwrench to enter the Seafury Tempest and slay creatures to obtain Storm-infused Mystery Meat. Progress: <The snapdragon paws the ground, then looks at you expectantly. Its eyes glitter with intelligence and hunger.>", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 168970, 233489, 233493, 233494, 233495, 233497, 233498, 233499, 233500, 233501, 234592 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 235243, ["x"] = 0.708, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 235243, ["x"] = 0.708, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 86483 } },
[86485] = { ["id"] = 86485, ["name"] = "A Loyal Friend", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 86485 }, ["description"] = "<The snapdragon seems to recognize you as you approach, its ear fins wiggling with anticipation. Its massive, lithe body unfurls as it stands before you as a fully grown adult. It stares you down, clacking it's massive jaw gently as if it's deciding something. It seems to wait for you to make the first move.>", ["objectivesText"] = "Speak to the snapdragon. Progress: <The snapdragon hisses and wiggles it's ear fins, looking impressed.>", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 168970, 233489, 233493, 233494, 233495, 233497, 233498, 233499, 233500, 233501 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 235250, ["x"] = 0.708, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 235250, ["x"] = 0.708, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 86484 } },
[86486] = { ["id"] = 86486, ["name"] = "Hungry, Hungry Snapdragon", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 86486 }, ["description"] = "<The snapdragon seems to recognize you as you approach. Its ear fins wiggle with anticipation. It is hungry again and looks at you expectantly. It seems to want meat and doesn't seem to care where it comes from.>", ["objectivesText"] = "Collect 8 Mystery Meat Snacks by killing creatures around the Siren Isle . Progress: <The snapdragon stirs as you approach, its unnaturally-intelligent eyes scanning you. Clearly it hopes you have brought it a meal.>", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 168970, 233489, 233493, 233494, 233495, 233497, 233498, 233499, 233500, 233501, 235368 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 235237, ["x"] = 0.708, ["y"] = 0.485 }, { ["mapID"] = 2369, ["npcID"] = 235243, ["x"] = 0.708, ["y"] = 0.485 }, { ["mapID"] = 2369, ["npcID"] = 235250, ["x"] = 0.708, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 235237, ["x"] = 0.708, ["y"] = 0.485 }, { ["mapID"] = 2369, ["npcID"] = 235243, ["x"] = 0.708, ["y"] = 0.485 }, { ["mapID"] = 2369, ["npcID"] = 235250, ["x"] = 0.708, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 86482 } },
[86491] = { ["id"] = 86491, ["name"] = "Dastardly Duos! It's on!", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 86491 }, ["series"] = { 86503 }, ["description"] = "Hello, fight fans. The world's meanest villains are teamed up and back for revenge! They have returned, this time as Dastardly Duos! Meet me in Dornogal, at the foot of Contender's Gate and sign up to face the Dastardly Duos. Beat down these bosses one more time. Relive the dream! - Vinnie Sweets", ["objectivesText"] = "Speak with Vinnie Sweets in Dornogal near Contender's Gate.", ["rewardGold"] = 31200, ["rewardXP"] = 17650, ["rewardItems"] = { 234449, 238259, 239440 }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 234296, ["x"] = 0.528, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["startItems"] = { 234449 } },
