[86495] = { ["id"] = 86495, ["name"] = "The Reshii Ribbon", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 83126, 83127, 83128, 83129, 84856, 84857, 84862, 84863, 84864, 84865, 84866, 84967, 85037, 85449, 85450, 86495, 86820, 86946, 90517, 91871, 93979 }, ["series"] = { 84856 }, ["description"] = "During the Devouring War, I witnessed the horrific results of the All-Devouring's presence. A mortal being cannot approach him at the manaforge. He is the entropy of the end, and you are just flesh. Xal'atath knows rituals from across the Great Dark Beyond. With the power of the Reshii Ribbons, she was able to transform the K'areshi so they could withstand Dimensius. Alleria will not like this plan. You must convince her!", ["objectivesText"] = "Convince Alleria to let Xal'atath perform the ritual of transformation on you. Progress: Every moment spent debating or arguing is a moment closer to Dimensius emerging.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 234106, ["x"] = 0.482, ["y"] = 0.366 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 233946, ["x"] = 0.482, ["y"] = 0.366 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.366 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 84855 }, ["questLines"] = { { ["id"] = 5733, ["name"] = "Void Alliance", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86496] = { ["id"] = 86496, ["name"] = "An Ordered Design", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["requiredRaces"] = { 3, 34, 85 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 86496 }, ["description"] = "< Bargus holds up a tiny splinter of golden crystal.> Much like the radiant remnants found by the Arathi within Hallowfall, the Siren Crystal appears to be effecting the surrounding geological matrix of the island. Unlike our goblin compatriots, I don't recommend harvesting the larger shards we've seen around the isle, lest we disturb the fragile caverns beneath us or offend the Arathi. But these tiny splinters are worth investigating. Bring me a sizable portion. For... experimental purposes.", ["objectivesText"] = "Collect 50 crystal-splintered rubble . The crystal-splintered rubble can only be looted from creatures on the Siren Isle during the Seafury Tempest. Progress: Have you found more splinters of the Siren Crystal? I think I may be able to create something useful with them.", ["rewardItems"] = { 234456 }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 230242, ["x"] = 0.6752, ["y"] = 0.4192 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 230242, ["x"] = 0.6752, ["y"] = 0.4192 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.6752, ["y"] = 0.4192 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 84730 } },
[86503] = { ["id"] = 86503, ["name"] = "Who are the Dastardly Duos?", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16092, ["mapID"] = 2248, ["storyline"] = { 86503 }, ["series"] = { 86491 }, ["description"] = "Great question! Here's how to find out: Talk to Xyggie Marou and sign up to fight the Dastardly Duos . And because you're new to this, let me give you a list of \"Dastardly\" tasks to do while you're in there! Good luck! Maybe I'll see you on the other side.", ["objectivesText"] = "Beat the Dastardly Duos while finishing Vinnie's \"Dastardly\" tasks, then speak with Vinnie Sweets . Progress: Speak with Xyggie Marou , do my tasks, and beat those Dastardly Duos !", ["rewardGold"] = 34100, ["rewardXP"] = 17650, ["rewardItems"] = { 238259, 239440 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 234296, ["x"] = 0.528, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 234296, ["x"] = 0.528, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 86491 } },
[86509] = { ["id"] = 86509, ["name"] = "Friend or Fiend", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86509, 86510, 86511, 86512, 86513, 86514, 86515, 86516, 86517, 86518, 86519, 86520, 86521, 86522, 90571, 95276 }, ["series"] = { 86510, 90571 }, ["description"] = "Despite that spirited display, I'm inclined to help you. After all, what's a little violence between friends? And since we're friends, I'll let you in on a secret: shutting down the storm is only possible from inside the Nexus-Points. Of course you can't just walk in--you need the Mantle of Predation. < Decimus seems to savor the words.> Do I have your attention? Let's shake the dust off and discuss this somewhere... civilized. Meet me at my estate.", ["objectivesText"] = "Travel to the Howling Ridge.", ["rewardGold"] = 33500, ["rewardXP"] = 1605, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3389, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 240691, ["x"] = 0.41, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235697, ["x"] = 0.512, ["y"] = 0.703 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86545 }, ["questLines"] = { { ["id"] = 5730, ["name"] = "Dawn of Reckoning", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5730, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86510] = { ["id"] = 86510, ["name"] = "Domus Penumbra", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86509, 86510, 86511, 86512, 86513, 86514, 86515, 86516, 86517, 86518, 86519, 86520, 86521, 86522, 90571, 95276 }, ["series"] = { 86509, 90571 }, ["description"] = "It seems we all wish to stop the Voidstorm . Common ground--a rare thing here. I'll even tell you how to do it, and all I ask in return is for you to let me enjoy the show. But you must be tired. Show yourself around, and help yourself to the amenities. Then we will continue our discussion. Don't take too long. There is much to see, and the storm rages on.", ["objectivesText"] = "Establish your base at the Howling Ridge.", ["rewardGold"] = 154900, ["rewardXP"] = 6425, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235697, ["x"] = 0.512, ["y"] = 0.703 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235697, ["x"] = 0.512, ["y"] = 0.703 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.703 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86509 }, ["questLines"] = { { ["id"] = 5730, ["name"] = "Dawn of Reckoning", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5730, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86511] = { ["id"] = 86511, ["name"] = "Edge of the Abyss", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86509, 86510, 86511, 86512, 86513, 86514, 86515, 86516, 86517, 86518, 86519, 86520, 86521, 86522, 90571, 95276 }, ["description"] = "I don't trust Decimus any more than the rest of the beasts here. I do trust that they only serve themself. Seems having Xal'atath as a master isn't to their taste. We can turn one foe against another. Even Lothraxion would agree if he weren't so stubborn. If this Mantle of Predation will let us stop the storm, then it's our best shot. A troop of ren'dorei have been scouting the Obscurion Citadel. We'll meet with them and see what they've learned.", ["objectivesText"] = "Meet the ren'dorei scouts near the Obscurion Citadel. Progress: I've avoided this place until now. The howls and the stench are carried on the wind like a warning.", ["rewardGold"] = 34100, ["rewardXP"] = 1605, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3389, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 238296, ["x"] = 0.51, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235471, ["x"] = 0.528, ["y"] = 0.736 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 90571 }, ["questLines"] = { { ["id"] = 5730, ["name"] = "Dawn of Reckoning", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5730, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86512] = { ["id"] = 86512, ["name"] = "The Harvest", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86509, 86510, 86511, 86512, 86513, 86514, 86515, 86516, 86517, 86518, 86519, 86520, 86521, 86522, 90571, 95276 }, ["description"] = "Two sigils--you'll need both to open Terminas's vault and claim the Mantle. The first belongs to Torentia, petty ruler of this sad trench. Too ambitious for Terminas to bring her into his inner circle, too cowardly to strike out on her own. So here she cowers behind an unbreakable shield of Void. She's terrified of losing her already meager holdings. What a pity. Slaughter your way through the trench. The potential emergence of a new apex predator is something she won't ignore.", ["objectivesText"] = "Slay foes to attract Torentia's attention. Progress: Do you feel the hunger of this place? No wonder the Void came here.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 65670, 65692, 65710, 128942, 131689, 180648, 190743, 190746, 190750, 190752, 198606, 219314, 221154, 228741, 245345, 246951, 263462, 264659 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235633, ["x"] = 0.542, ["y"] = 0.742 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 236945, ["x"] = 0.555, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86511 }, ["questLines"] = { { ["id"] = 5730, ["name"] = "Dawn of Reckoning", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5730, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86513] = { ["id"] = 86513, ["name"] = "Face the Tide", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86509, 86510, 86511, 86512, 86513, 86514, 86515, 86516, 86517, 86518, 86519, 86520, 86521, 86522, 90571, 95276 }, ["description"] = "I expected an army, but this is chaos--beasts pouring from the Void, gorging themselves, taking captives for sport. Our mission is to claim the Mantle, but we can't ignore this. Sooner or later, these forces will be loosed against Silvermoon. Any blows we strike now will save lives down there, $p. Starve their forces, stem the flow of beasts from the Void, and free every captive they've abducted.", ["objectivesText"] = "Disrupt Obscurion Citadel forces. Progress: Even if we fail--Light forfend--at least we'll have struck a blow.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 262351 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235469, ["x"] = 0.526, ["y"] = 0.711 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 236944, ["x"] = 0.556, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.711 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86511 }, ["questLines"] = { { ["id"] = 5730, ["name"] = "Dawn of Reckoning", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5730, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86514] = { ["id"] = 86514, ["name"] = "Lady of the Pit", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86509, 86510, 86511, 86512, 86513, 86514, 86515, 86516, 86517, 86518, 86519, 86520, 86521, 86522, 90571, 95276 }, ["description"] = "For all their power, these domanaar still behave like beasts. That's good for us. Wolves try to avoid each other, but if one threatens another's territory, they'll fight to the death. By now, I think you've more than proven that you're a threat. Torentia can't back down if you challenge her--it would go against her nature. So take the fight to her, slay her, and claim her sigil.", ["objectivesText"] = "Challenge Torentia and claim her sigil to access the vault. Progress: Have you claimed Torentia's sigil ?", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardItems"] = { 238779, 260860, 260861, 260862, 260863 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3389, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 236945, ["x"] = 0.555, ["y"] = 0.728 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235502, ["x"] = 0.608, ["y"] = 0.736 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86512, 86513 }, ["questLines"] = { { ["id"] = 5730, ["name"] = "Dawn of Reckoning", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5730, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86515] = { ["id"] = 86515, ["name"] = "Hollow Hunger", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86509, 86510, 86511, 86512, 86513, 86514, 86515, 86516, 86517, 86518, 86519, 86520, 86521, 86522, 90571, 95276 }, ["description"] = "Alleria's judgement is clouded. She's spent too much time steeped in Void. I've prosecuted campaigns across the cosmos. Casualties are inevitable. I could not command if the loss of every soldier broke my will. We have the information we need: the location of the sigil bearer. The fiends whisper of a domanaar named Severum. Slay him and take his sigil, then we can be rid of this place.", ["objectivesText"] = "Slay Severum and claim his sigil. Progress: Would that we could put every voidspawn to the sword.", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardItems"] = { 236752, 260864, 260865, 260866, 260867 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3389, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235504, ["x"] = 0.605, ["y"] = 0.75 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235504, ["x"] = 0.605, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86514 }, ["questLines"] = { { ["id"] = 5730, ["name"] = "Dawn of Reckoning", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5730, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86516] = { ["id"] = 86516, ["name"] = "All Become Prey", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86509, 86510, 86511, 86512, 86513, 86514, 86515, 86516, 86517, 86518, 86519, 86520, 86521, 86522, 90571, 95276 }, ["description"] = "Lothraxion's acting like we have an army, but a single ultradon will tear through us if we're caught off guard. We need to be smarter. I've watched the beasts of this world: studied them, tracked them, killed them. They prey on weakness, and cull their own kind at the first sign of frailty. Harvest carrion essence from the carcasses around the citadel. Use it to mark ultradons. Other beasts will pounce, thinking they're wounded or dying. Let them tear each other apart, then clean up what's left.", ["objectivesText"] = "Slay Slavering Ultradons by marking them with Carrion Essence . Progress: These creatures operate on base instinct. We can exploit that.", ["rewardGold"] = 335000, ["rewardXP"] = 12845, ["rewardItems"] = { 237807, 267082 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235502, ["x"] = 0.608, ["y"] = 0.736 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235502, ["x"] = 0.608, ["y"] = 0.736 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.736 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86514 }, ["questLines"] = { { ["id"] = 5730, ["name"] = "Dawn of Reckoning", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5730, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86517] = { ["id"] = 86517, ["name"] = "Vanished in the Void", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86509, 86510, 86511, 86512, 86513, 86514, 86515, 86516, 86517, 86518, 86519, 86520, 86521, 86522, 90571, 95276 }, ["description"] = "\"Acceptable losses.\" I hope I never find it that easy to dismiss the deaths of friends and comrades. What use is the Light if it leaves us as callous as our enemies? Sideras was nearly killed. Luckily, he escaped through a rift. Riftblade Maella led the others in a fighting retreat. Find her. Hopefully they stuck together. I can't leave Sideras--not until he's stable.", ["objectivesText"] = "Find the missing void elves. Progress: Lothraxion should know better than this.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 240831 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235503, ["x"] = 0.606, ["y"] = 0.75 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235503, ["x"] = 0.606, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.606, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86514 }, ["questLines"] = { { ["id"] = 5730, ["name"] = "Dawn of Reckoning", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5730, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86518] = { ["id"] = 86518, ["name"] = "The Mantle of Predation", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86509, 86510, 86511, 86512, 86513, 86514, 86515, 86516, 86517, 86518, 86519, 86520, 86521, 86522, 90571, 95276 }, ["series"] = { 86519, 86520, 86521, 86522 }, ["description"] = "Let's move quickly. We need to steal the Mantle before Terminas returns and before Lothraxion does something rash. I understand this place grates on him, but he should know to trust my instincts. I thought we'd fought together long enough to earn that. Let's end this. Ready when you are.", ["objectivesText"] = "Steal the Mantle of Predation.", ["rewardGold"] = 170800, ["rewardXP"] = 6425, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235502, ["x"] = 0.608, ["y"] = 0.736 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235715, ["x"] = 0.602, ["y"] = 0.762 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.736 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86515, 86516, 86517 }, ["questLines"] = { { ["id"] = 5730, ["name"] = "Dawn of Reckoning", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5730, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86519] = { ["id"] = 86519, ["name"] = "Abyssus, Abyssum", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86509, 86510, 86511, 86512, 86513, 86514, 86515, 86516, 86517, 86518, 86519, 86520, 86521, 86522, 90571, 95276 }, ["series"] = { 86518, 86520, 86521, 86522 }, ["description"] = "I don't see Decimus. For all their glee at handing us over, I'd expect they'd want to watch the fight. What could be more important to a domanaar than enjoying a battle? <Alleria nocks another arrow.> Answers can wait. Right now we need to survive.", ["objectivesText"] = "Conquer Terminas's arena.", ["rewardGold"] = 619600, ["rewardXP"] = 16055, ["rewardItems"] = { 256198, 256206, 256214, 256222 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3389, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235715, ["x"] = 0.602, ["y"] = 0.762 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 239574, ["x"] = 0.6, ["y"] = 0.76 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.762 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86518 }, ["questLines"] = { { ["id"] = 5730, ["name"] = "Dawn of Reckoning", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5730, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86520] = { ["id"] = 86520, ["name"] = "Hunt the Light", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86509, 86510, 86511, 86512, 86513, 86514, 86515, 86516, 86517, 86518, 86519, 86520, 86521, 86522, 90571, 95276 }, ["series"] = { 86518, 86519, 86521, 86522 }, ["description"] = "There's no time. Lothraxion already has the lead. Get to Nexus-Point Xenas, $p. We'll meet you there.", ["objectivesText"] = "Meet Alleria Windrunner at Nexus-Point Xenas.", ["rewardGold"] = 34100, ["rewardXP"] = 1605, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3389, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 239574, ["x"] = 0.6, ["y"] = 0.76 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235763, ["x"] = 0.64, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.76 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86519 }, ["questLines"] = { { ["id"] = 5730, ["name"] = "Dawn of Reckoning", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5730, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86521] = { ["id"] = 86521, ["name"] = "Nexus-Point Xenas: Eclipse", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86509, 86510, 86511, 86512, 86513, 86514, 86515, 86516, 86517, 86518, 86519, 86520, 86521, 86522, 90571, 95276 }, ["series"] = { 86518, 86519, 86520, 86522 }, ["description"] = "If he destroys the Nexus-Point, everyone we're fighting for could perish. I'll try to talk him down, but if I can't, if I have to... <Alleria's face clouds.> No hesitation. We end this, one way or another.", ["objectivesText"] = "Enter Nexus-Point Xenas and stop Lothraxion. Progress: We've come too far to let anything stop us.", ["rewardGold"] = 1366400, ["rewardXP"] = 25690, ["rewardItems"] = { 251093, 251206, 251217, 262606 }, ["rewardChoices"] = { 251093, 251206, 251217 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3389, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235763, ["x"] = 0.64, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235765, ["x"] = 0.458, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 86520 }, ["questLines"] = { { ["id"] = 5730, ["name"] = "Dawn of Reckoning", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5730, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86522] = { ["id"] = 86522, ["name"] = "Daylight is Breaking", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86509, 86510, 86511, 86512, 86513, 86514, 86515, 86516, 86517, 86518, 86519, 86520, 86521, 86522, 90571, 95276 }, ["series"] = { 86518, 86519, 86520, 86521 }, ["description"] = "Turalyon is busying himself with the troops. We'll need to let him know what they'll face here, tell him about Lothraxion... <Alleria shakes her head.> Thank you, $p. Even when my thoughts feel clouded, you never seem to waver. Go, give Lor'themar my report. Arator and I will brief Turalyon.", ["objectivesText"] = "Report to Lor'themar Theron in the Sanctum of Light in Silvermoon City.", ["rewardGold"] = 83700, ["rewardXP"] = 3210, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3389, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235765, ["x"] = 0.458, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2393, 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86521 }, ["questLines"] = { { ["id"] = 5730, ["name"] = "Dawn of Reckoning", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5730, ["questLineOrder"] = 15 } }, ["db2PoiUiMapID"] = 2393 },
[86528] = { ["id"] = 86528, ["name"] = "A Cracked Holokey", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86528, 86530, 86531, 86536, 86537, 86538, 86539, 86540, 86541, 86542, 86544, 86545, 88768, 89249 }, ["description"] = "<A unique-looking ethereal device rests upon the cold ground. It bears a crack down the middle from damage in a scuffle. Perhaps Alleria will know what it is.>", ["objectivesText"] = "Bring the Cracked Holokey to Alleria deeper in the Ethereum Refinery.", ["rewardGold"] = 319000, ["rewardXP"] = 12845, ["rewardItems"] = { 241000 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["x"] = 0.357, ["y"] = 0.792, ["mapID"] = 2405, ["objectID"] = 504349 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235717, ["x"] = 0.362, ["y"] = 0.804 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.804 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86536 }, ["questLines"] = { { ["id"] = 5729, ["name"] = "The Night's Veil", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5729, ["questLineOrder"] = 14 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405, ["startItems"] = { 241000 } },
[86530] = { ["id"] = 86530, ["name"] = "First, The Shells", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86528, 86530, 86531, 86536, 86537, 86538, 86539, 86540, 86541, 86542, 86544, 86545, 88768, 89249 }, ["description"] = "Ages ago, on a dismal world of swamp, I led the Army of the Light to a demon-infested manaforge obscured by vines and fog. My soldiers left that world in a haze of flame and smoke, the scent of burning mana and victory in the air. We will do now as we did then. We'll begin by collecting the empty canisters they use to hold and transport fuel. The ethereals, and especially their automatons, will have them.", ["objectivesText"] = "Collect 5 Empty Manacells from mechs and ethereals at the Ethereum Refinery. Progress: Just as before.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 237380, 260848, 262375, 262376, 262672, 262674, 262675, 262678, 262733, 262737, 264657 }, ["rewardChoices"] = { 260848, 262375, 262376, 262672, 262674, 262675, 262678, 262733, 262737 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235394, ["x"] = 0.366, ["y"] = 0.73 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235713, ["x"] = 0.362, ["y"] = 0.805 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.73 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86536 }, ["questLines"] = { { ["id"] = 5729, ["name"] = "The Night's Veil", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5729, ["questLineOrder"] = 14 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86531] = { ["id"] = 86531, ["name"] = "Work Disruption", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86528, 86530, 86531, 86536, 86537, 86538, 86539, 86540, 86541, 86542, 86544, 86545, 88768, 89249 }, ["description"] = "The Shadowguard may once have defied Xal'atath, but they're part of her army now. Whatever they're doing with the energies gathered here must be stopped. Put down their soldiers, harvesters, and machines. I'll do the same, and meet you deeper within.", ["objectivesText"] = "Slay Shadowguard and disrupt the Manaforge at the Ethereum Refinery. Progress: What does she have planned...", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 263240 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235389, ["x"] = 0.366, ["y"] = 0.73 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235717, ["x"] = 0.362, ["y"] = 0.804 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.73 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86536 }, ["questLines"] = { { ["id"] = 5729, ["name"] = "The Night's Veil", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5729, ["questLineOrder"] = 14 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86535] = { ["id"] = 86535, ["name"] = "Test Run", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 86535 }, ["description"] = "Hey, you lookin' to make a few coins? We made a deal with the earthen to build a teleporter up in Dornogal. We get all the tourism traffic we want, and they get their pick of the finest cracked, chipped, or otherwise unsellable gemstones Undermine 's jewelers can offer. I just got this end of things workin', but I haven't tested it out yet. You wanna try? If you come out the other side, my coworker Kenzi will compensate ya. We'll say this constitutes a verbal waiver, yeah?", ["objectivesText"] = "Use the teleporter to travel from Undermine to Dornogal. Progress: Look at this teleporter. Ain't she gorgeous?", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 211397 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 235402, ["x"] = 0.275, ["y"] = 0.541 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 235403, ["x"] = 0.524667, ["y"] = 0.506667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.275, ["y"] = 0.541 }, ["mapCandidates"] = { ["npc"] = { 2339, 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83151 }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[86536] = { ["id"] = 86536, ["name"] = "Reliable Enemies", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86528, 86530, 86531, 86536, 86537, 86538, 86539, 86540, 86541, 86542, 86544, 86545, 88768, 89249 }, ["description"] = "The ren'dorei scouts report a familiar enemy upon this world: ethereals. Wretched scavengers and bandits that plague every corner of the Great Dark Beyond. The Shadowguard are the worst of them. We'll handle them. This... thing we've taken prisoner must know what they're doing here, and much else. Press the Void's secrets from it. See that it is convinced to share what it knows, or I will employ my own methods.", ["objectivesText"] = "Interrogate Decimus. Progress: Lothraxion has a plan. I trust him.", ["rewardGold"] = 85400, ["rewardXP"] = 3210, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235606, ["x"] = 0.354, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235389, ["x"] = 0.366, ["y"] = 0.73 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.354, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86565 }, ["questLines"] = { { ["id"] = 5729, ["name"] = "The Night's Veil", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5729, ["questLineOrder"] = 14 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86537] = { ["id"] = 86537, ["name"] = "Network Insecurity", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86528, 86530, 86531, 86536, 86537, 86538, 86539, 86540, 86541, 86542, 86544, 86545, 88768, 89249 }, ["description"] = "Judging by the design and the strength of this holokey's energy, it must be used to encrypt important communications. Let us try this lead. See if it's compatible with any of the consoles you find around the refinery. Given the damage it's taken, we'll have to piece together whatever scraps of information we can.", ["objectivesText"] = "Use the Holokey on consoles around the Ethereum Refinery. Progress: What have you found?", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 237745, 262669, 262670, 262671, 262673, 262677, 262730, 262735, 262738, 262739, 268921 }, ["rewardChoices"] = { 262669, 262670, 262671, 262673, 262677, 262730, 262735, 262738, 262739, 268921 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235717, ["x"] = 0.362, ["y"] = 0.804 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235717, ["x"] = 0.362, ["y"] = 0.804 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.804 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86528, 86530, 86531 }, ["questLines"] = { { ["id"] = 5729, ["name"] = "The Night's Veil", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5729, ["questLineOrder"] = 14 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86538] = { ["id"] = 86538, ["name"] = "Second, The Fuel", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86528, 86530, 86531, 86536, 86537, 86538, 86539, 86540, 86541, 86542, 86544, 86545, 88768, 89249 }, ["description"] = "Ethereals seek corners of the cosmos to drain of potent nether. Arcane, Void, fel--to them, it matters only the yield. And we have a rich vein to work with. Now, slay those who possess that energy: wild arcane elementals from their pipes, or their ethereal harvesters flush with energy. We have need of it.", ["objectivesText"] = "Collect 50 Arcane Remnants in the Ethereum Refinery. Progress: Go. Collect the catalyst.", ["rewardGold"] = 335000, ["rewardXP"] = 12845, ["rewardItems"] = { 237744 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235713, ["x"] = 0.362, ["y"] = 0.805 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235713, ["x"] = 0.362, ["y"] = 0.805 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.805 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86528, 86530, 86531 }, ["questLines"] = { { ["id"] = 5729, ["name"] = "The Night's Veil", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5729, ["questLineOrder"] = 14 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86539] = { ["id"] = 86539, ["name"] = "A Naaru!", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86528, 86530, 86531, 86536, 86537, 86538, 86539, 86540, 86541, 86542, 86544, 86545, 88768, 89249 }, ["description"] = "I refuse to let another naaru fall to darkness. Before our departure, the scouts reported they had found a Nexus-Point connected to this forge. If the Void's forces possess a naaru, it might be where they're keeping it. I will prepare the manacells as we conduct the search. Come.", ["objectivesText"] = "Find Lothraxion at the overlook to Nexus-Point Mid'Ar.", ["rewardGold"] = 77400, ["rewardXP"] = 3210, ["rewardItems"] = { 31746, 151565, 151568, 151704 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235713, ["x"] = 0.362, ["y"] = 0.805 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235648, ["x"] = 0.394, ["y"] = 0.822 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.805 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86537, 86538 }, ["questLines"] = { { ["id"] = 5729, ["name"] = "The Night's Veil", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5729, ["questLineOrder"] = 14 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86540] = { ["id"] = 86540, ["name"] = "Third, Blow It Up", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86528, 86530, 86531, 86536, 86537, 86538, 86539, 86540, 86541, 86542, 86544, 86545, 88768, 89249 }, ["description"] = "The manacells have been prepared. Set them near the pylon and its supporting machinery. When it's done, I will command Alleria to ignite them from afar. But we cannot proceed until the naaru has been brought to safety. Go now and I will make certain of her freedom.", ["objectivesText"] = "Place 5 Overcharged Manacells at Nexus-Point Mid'Ar. Progress: What are you doing here? Place the manacells, now!", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 264340 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235648, ["x"] = 0.394, ["y"] = 0.822 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235649, ["x"] = 0.38, ["y"] = 0.832 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.822 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86539 }, ["questLines"] = { { ["id"] = 5729, ["name"] = "The Night's Veil", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5729, ["questLineOrder"] = 14 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86541] = { ["id"] = 86541, ["name"] = "Just In Case...", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86528, 86530, 86531, 86536, 86537, 86538, 86539, 86540, 86541, 86542, 86544, 86545, 88768, 89249 }, ["description"] = "Perhaps Lothraxion will be able to bring that shield down on his own. Or perhaps he is a pompous blowhard. The Devouring Host offers its trusted soldiers fragments of a relic that can override any ethereal device, including that shield. You'll need to carve quite a swath through their forces to recover enough shards. But what do I know? I am merely unworthy voidspawn.", ["objectivesText"] = "Collect 8 Fragmented Keystones from Devouring Host soldiers at Nexus-Point Mid'Ar. Progress: < Decimus glances sideways at you.>", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 237895, 242254, 267209 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235650, ["x"] = 0.394, ["y"] = 0.82 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235652, ["x"] = 0.378, ["y"] = 0.832 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.82 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86539 }, ["questLines"] = { { ["id"] = 5729, ["name"] = "The Night's Veil", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5729, ["questLineOrder"] = 14 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86542] = { ["id"] = 86542, ["name"] = "Flicker in the Dark", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86528, 86530, 86531, 86536, 86537, 86538, 86539, 86540, 86541, 86542, 86544, 86545, 88768, 89249 }, ["description"] = "We're dawdling! There's no time to waste! Get that shield down, now! T'era's anguish tears at my soul!", ["objectivesText"] = "Free and rescue T'era.", ["rewardGold"] = 619600, ["rewardXP"] = 16055, ["rewardItems"] = { 260832, 260833, 260834, 260835 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3389, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235649, ["x"] = 0.38, ["y"] = 0.832 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235664, ["x"] = 0.416, ["y"] = 0.767 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.832 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86540, 86541, 88768 }, ["questLines"] = { { ["id"] = 5729, ["name"] = "The Night's Veil", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5729, ["questLineOrder"] = 14 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86543] = { ["id"] = 86543, ["name"] = "Magisters' Terrace: Homecoming", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2393, ["storyline"] = { 86543, 86549, 86557, 86558, 86559, 86561, 86562, 86565, 89388, 92061 }, ["series"] = { 89388 }, ["description"] = "We know there's land inside the Voidstorm , through its massive portal. If we can reach it, we can take the fight to Xal'atath. I have found the key. It is a relic known as the Cynosure of Twilight. For ages, it has mystified us by revealing unreachable pathways to infinite unknowns. My research tells me I can use it to open a path to the storm. There's just one problem: it's in Magisters' Terrace. And I'm not exactly... in their good graces, at the moment.", ["objectivesText"] = "Meet Magister Umbric on the Isle of Quel'Danas, then complete the Magisters' Terrace dungeon.", ["rewardGold"] = 1366400, ["rewardXP"] = 25690, ["rewardItems"] = { 251103, 251104, 251108, 251115, 251118, 260312 }, ["rewardChoices"] = { 251103, 251104, 251108, 251115, 251118, 260312 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 235386, ["x"] = 0.452, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 235405, ["x"] = 0.352, ["y"] = 0.655 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 92061 }, ["questLines"] = { { ["id"] = 5728, ["name"] = "Into the Abyss", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5728, ["questLineOrder"] = 13 } }, ["db2PoiUiMapID"] = 2393 },
[86544] = { ["id"] = 86544, ["name"] = "Post-Mortem", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86528, 86530, 86531, 86536, 86537, 86538, 86539, 86540, 86541, 86542, 86544, 86545, 88768, 89249 }, ["description"] = "We all bear a heavy burden in this place. I feel myself slipping towards hopelessness. But we haven't failed until we refuse to stand back up. I know my mother will collect herself. But the others need to know this fight isn't over. Speak with Hieron. He and the other scouts should have information. We can start there.", ["objectivesText"] = "Check in with the inhabitants of Locus Point. Progress: Mother... Hang in there.", ["rewardGold"] = 170800, ["rewardXP"] = 6425, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235724, ["x"] = 0.416, ["y"] = 0.746 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235724, ["x"] = 0.416, ["y"] = 0.746 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.746 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 89249 }, ["questLines"] = { { ["id"] = 5729, ["name"] = "The Night's Veil", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5729, ["questLineOrder"] = 14 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86545] = { ["id"] = 86545, ["name"] = "The Light's Brand", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86528, 86530, 86531, 86536, 86537, 86538, 86539, 86540, 86541, 86542, 86544, 86545, 88768, 89249 }, ["description"] = "No! <name>, we have to stop them! Lothraxion's boiling temper risks everything! That he chooses now of all times, when my mother is out of commission... There's no time. We have to go!", ["objectivesText"] = "Intervene in the fight between Lothraxion and Decimus. Progress: I should have realized earlier... Join me, <name>. Let us reveal the truth.", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardItems"] = { 260854, 260855, 260856, 260857 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3389, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235724, ["x"] = 0.416, ["y"] = 0.746 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235726, ["x"] = 0.41, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.746 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86544 }, ["questLines"] = { { ["id"] = 5729, ["name"] = "The Night's Veil", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5729, ["questLineOrder"] = 14 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86549] = { ["id"] = 86549, ["name"] = "No Fear of the Dark", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2393, ["storyline"] = { 86543, 86549, 86557, 86558, 86559, 86561, 86562, 86565, 89388, 92061 }, ["description"] = "Against all odds, we made it. I can open a way into the storm, but it will be a tenuous connection. We can only get a small team through the portal. We have no idea what awaits us on the other side. We must be prepared. I can use the Cynosure to bind us to Magisters' Terrace. If we need a quick escape, I can bring us back there. Come--help me calibrate this spell.", ["objectivesText"] = "Help Magister Umbric apply the anchor spell and open a portal to Voidstorm .", ["rewardGold"] = 154900, ["rewardXP"] = 6425, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 235405, ["x"] = 0.352, ["y"] = 0.655 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235411, ["x"] = 0.342, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.655 }, ["mapCandidates"] = { ["npc"] = { 2393, 2405 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 86543 }, ["questLines"] = { { ["id"] = 5728, ["name"] = "Into the Abyss", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5728, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86555] = { ["id"] = 86555, ["name"] = "Undermine Benefactor", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 86555 }, ["rewardItems"] = { 231737 }, ["starts"] = { { ["npcID"] = 231409, ["x"] = 0.436, ["y"] = 0.508, ["mapID"] = 2346 } }, ["ends"] = { { ["npcID"] = 231409, ["x"] = 0.436, ["y"] = 0.508, ["mapID"] = 2346 } }, ["coords"] = { ["x"] = 0.436, ["y"] = 0.508, ["source"] = "quest_giver", ["mapID"] = 2346 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard" },
[86556] = { ["id"] = 86556, ["name"] = "A Shattered Journey Through Time", ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 1637, ["mapID"] = 84, ["storyline"] = { 86556 }, ["description"] = "The Destroyer's star shines upon the land with its piercing light as even the spirits retreat to the shadows. This star is unlike any other in the skies, laying bare the weaknesses of even the boldest heroes. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", ["objectivesText"] = "Complete 5 Timewalking dungeons.", ["rewardGold"] = 1301200, ["rewardItems"] = { 232877 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 101759, ["x"] = 0.762, ["y"] = 0.172 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 101759, ["x"] = 0.762, ["y"] = 0.172 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.172 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[86557] = { ["id"] = 86557, ["name"] = "A Matter of Strife and Death", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86543, 86549, 86557, 86558, 86559, 86561, 86562, 86565, 89388, 92061 }, ["description"] = "Ha! A distant realm, crawling with vicious evil monsters? Just like old times. Alleria, Turalyon, and I faced a thousand years of war with demons in the far-flung realms. It is as simple a solution now as it was then. Kill or be killed.", ["objectivesText"] = "Kill 12 monsters in The Ingress. Progress: I will not deny, I still thrive in the rush of battle. So long as it is of righteous cause.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 264508 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235486, ["x"] = 0.344, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235522, ["x"] = 0.368, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86549 }, ["questLines"] = { { ["id"] = 5728, ["name"] = "Into the Abyss", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5728, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86558] = { ["id"] = 86558, ["name"] = "Save a Piece of Mind", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86543, 86549, 86557, 86558, 86559, 86561, 86562, 86565, 89388, 92061 }, ["description"] = "The Void here. It is like nothing else. Surely you can feel it, too? The overwhelming power... We must do something to stabilize the area. I'm barely able to keep our escape route from imploding, and the rest of our scouts... I can only hope they can hold it together. The ren'dorei know what to do. They will place Shadestar Loci to protect this area, but will need your help activating them.", ["objectivesText"] = "Activate 3 Shadestar Loci around The Ingress. Progress: Be careful, <class>. Treachery threatens us from all sides.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 260836, 260837, 260838, 260839 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235411, ["x"] = 0.342, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235486, ["x"] = 0.344, ["y"] = 0.605 }, { ["mapID"] = 2405, ["npcID"] = 235522, ["x"] = 0.368, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86549 }, ["questLines"] = { { ["id"] = 5728, ["name"] = "Into the Abyss", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5728, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86559] = { ["id"] = 86559, ["name"] = "The Far, Far Frontier", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86543, 86549, 86557, 86558, 86559, 86561, 86562, 86565, 89388, 92061 }, ["description"] = "We have secured this location. Some void elves can make this into a proper camp. There must be some weakness we can exploit to stop the storm. We must bring my army here to mete out justice to Xal'atath's armies! Join me and young Arator. Let us see what we can gather from this place across the horizon.", ["objectivesText"] = "Survey Voidstorm with Lothraxion and Arator.", ["rewardGold"] = 34100, ["rewardXP"] = 1605, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3389, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235522, ["x"] = 0.368, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235530, ["x"] = 0.312, ["y"] = 0.544 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86557, 86558 }, ["questLines"] = { { ["id"] = 5728, ["name"] = "Into the Abyss", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5728, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86560] = { ["id"] = 86560, ["name"] = "A Shrouded Journey Through Time", ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 6757, ["mapID"] = 554, ["storyline"] = { 86560 }, ["description"] = "The shrouded star flickers upon the land with its intermittent light ushering in an eerie mist upon the land. This star and the mists bring deep shadows to the land hiding its secrets and dangers. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", ["objectivesText"] = "Complete 5 Timewalking dungeons. Progress: I foresee that you will follow the shrouded star, and walk the paths it reveals.", ["rewardGold"] = 1239200, ["rewardItems"] = { 232877 }, ["starts"] = { { ["mapID"] = 554, ["npcID"] = 118828, ["x"] = 0.43, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 554, ["npcID"] = 118828, ["x"] = 0.43, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 554, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 554 }, ["zone"] = { 6757 } }, ["questType"] = "standard" },
[86561] = { ["id"] = 86561, ["name"] = "A Strange, Different World", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86543, 86549, 86557, 86558, 86559, 86561, 86562, 86565, 89388, 92061 }, ["description"] = "I don't know the purpose of these towers, only that they are called Nexus-Points and they thrum with Void power. We must get more information. The domanaar use some kind of Void-infused metal on the beasts here to add them to armies of the Devouring Host. They call it shadowgrafting. It empowers them, but also influences their minds. <Alleria smiles wryly.> What power doesn't? I have a plan for it. With you here, I can finally act on it.", ["objectivesText"] = "Collect 12 Shadowgraft Fragments in Nexus-Point Antius. Progress: The metal on these creatures... it seems particularly conductive to magical energies. Interesting.", ["rewardGold"] = 335000, ["rewardXP"] = 12845, ["rewardItems"] = { 242390, 262472 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235532, ["x"] = 0.312, ["y"] = 0.544 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235535, ["x"] = 0.274, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86559 }, ["questLines"] = { { ["id"] = 5728, ["name"] = "Into the Abyss", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5728, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86562] = { ["id"] = 86562, ["name"] = "Dancing with Death", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86543, 86549, 86557, 86558, 86559, 86561, 86562, 86565, 89388, 92061 }, ["description"] = "We may be a small strike team, but we are strong. We have you, after all. There is no need to move with complete stealth. We must cut a path to the domanaar here. Take down the strongest enemies you can find. We will join you in the fray.", ["objectivesText"] = "Slay Voidgrasper , Vathan the Rebel, and Scytheryp the Slicer in Nexus-Point Antius. Progress: Have you found the greatest of the enemies here? I wonder just how powerful a creature can get, consuming Void for eternity...", ["rewardGold"] = 619600, ["rewardXP"] = 16055, ["rewardItems"] = { 260840, 260841, 260842, 260843 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3389, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235530, ["x"] = 0.312, ["y"] = 0.544 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235535, ["x"] = 0.274, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86559 }, ["questLines"] = { { ["id"] = 5728, ["name"] = "Into the Abyss", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5728, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86563] = { ["id"] = 86563, ["name"] = "A Savage Journey Through Time", ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 7333, ["storyline"] = { 86563 }, ["description"] = "The brutal star shines upon the land, threatening to trample underfoot all who stand in its path. This star is many things: primal, fierce, and noble. While its influence holds, new paths may open up to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", ["objectivesText"] = "Complete 5 Timewalking dungeons. Progress: I foresee that you will follow the brutal star and walk the paths it reveals.", ["rewardGold"] = 1168400, ["rewardItems"] = { 232877 }, ["starts"] = { { ["npcID"] = 151955, ["x"] = 0.37, ["y"] = 0.724, ["zoneID"] = 7332 }, { ["npcID"] = 151987, ["x"] = 0.428, ["y"] = 0.544, ["zoneID"] = 7333 } }, ["ends"] = { { ["npcID"] = 151955, ["x"] = 0.37, ["y"] = 0.724, ["zoneID"] = 7332 }, { ["npcID"] = 151987, ["x"] = 0.428, ["y"] = 0.544, ["zoneID"] = 7333 } }, ["coords"] = { ["x"] = 0.37, ["y"] = 0.724, ["source"] = "quest_giver", ["zoneID"] = 7332 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7333 } }, ["questType"] = "standard" },
[86564] = { ["id"] = 86564, ["name"] = "A Fel Journey Through Time", ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 86564 }, ["description"] = "A corrupting star shines upon the land, threatening all with burning oblivion. The star betrays those who seek the light, its red glow obscuring rather than revealing. While its influence holds, new paths may open up to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", ["objectivesText"] = "Complete 5 Timewalking dungeons. Progress: I foresee that you will follow the corrupting red star and walk the paths it reveals.", ["rewardGold"] = 1168400, ["rewardItems"] = { 232877 }, ["starts"] = { { ["x"] = 0.686, ["y"] = 0.492, ["mapID"] = 627, ["npcID"] = 180899 } }, ["ends"] = { { ["x"] = 0.686, ["y"] = 0.492, ["mapID"] = 627, ["npcID"] = 180899 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.686, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 180899, ["questTurnInID"] = 180899, ["questType"] = "standard" },
[86565] = { ["id"] = 86565, ["name"] = "No Prayer for the Wicked", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86543, 86549, 86557, 86558, 86559, 86561, 86562, 86565, 89388, 92061 }, ["description"] = "Alleria has a plan to use this shadowgrafting material to capture that domanaar for information. But what good is information given by evil? I've fought countless demons and every one of them was a liar. < Lothraxion scowls.> Let us follow her plan, for now. Do what she asks with this metal, then slay the domanaar's pet beast. Once we speak with this vile creature, I will decide how long it lives.", ["objectivesText"] = "Help modify the Shadowgraft Fragments, slay Sinewshredder in Nexus-Point Antius, and capture the leading domanaar.", ["rewardGold"] = 670000, ["rewardXP"] = 16055, ["rewardItems"] = { 260844, 260845, 260846, 260847 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3389, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235535, ["x"] = 0.274, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235606, ["x"] = 0.354, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.274, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86561, 86562 }, ["questLines"] = { { ["id"] = 5728, ["name"] = "Into the Abyss", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5728, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86575] = { ["id"] = 86575, ["name"] = "Rocket Roll", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 86271, 86272, 86273, 86274, 86275, 86276, 86277, 86575, 86697 }, ["description"] = "That scrap was just what I needed. An' now without those bloodfeasters givin' me the heebie jeebies, I can get these bots officially rolled out. While I finish up here, why don't you go tell Benny the good news? I'm sure he'll wanna deploy 'em right away!", ["objectivesText"] = "Return to Benny Gooserocket outside the cave in the Ringing Deeps .", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 234294, ["x"] = 0.672, ["y"] = 0.98 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 233420, ["x"] = 0.684, ["y"] = 0.964 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.98 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 86274, 86275 }, ["questLines"] = { { ["id"] = 5736, ["name"] = "Sanity's Rest", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[86584] = { ["id"] = 86584, ["name"] = "Overwhelm Them with Mandatory Time Off", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 84962, 85812, 85822, 85834, 85855, 85863, 85864, 86305, 86367, 86372, 86391, 86395, 86409, 86584, 86610, 86696, 86707, 86709, 86800, 86872 }, ["objectivesText"] = "Docks handled Crates broken Illusion Devices activated", ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.577, ["y"] = 0.336, ["mapID"] = 2472 } }, ["ends"] = { { ["x"] = 0.577, ["y"] = 0.336, ["mapID"] = 2472 } }, ["coords"] = { ["mapID"] = 2472, ["x"] = 0.577, ["y"] = 0.336 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15781 } }, ["questType"] = "world", ["questLines"] = { { ["id"] = 5737, ["name"] = "K'aresh - World Quests/Repeatables", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Docks handled", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Crates broken", ["amount"] = 10, ["type"] = 2, ["objectID"] = 476259, ["orderIndex"] = 1 }, { ["text"] = "Illusion Devices activated", ["amount"] = 17, ["type"] = 3, ["objectID"] = 239597, ["orderIndex"] = 2 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371, ["db2QuestHubAreaPoiID"] = 8385, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[86587] = { ["id"] = 86587, ["name"] = "To Maldraxxus", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86587, 86588, 86589, 86590, 86591, 86592, 86593, 86594, 86595, 86601, 86602, 86603, 86604, 86605, 86606, 86607, 86782, 86783 }, ["description"] = "Rays once soared through the skies of K'aresh. While their void-touched descendants are in the skies outside the Oasis, we have no surviving specimens that have not been void-touched. However, I know of a location where we can procure a similar creature that should inhabit the same part of the ecosystem: Maldraxxus in the Shadowlands. Take my portal, and find the creatures for me.", ["objectivesText"] = "Travel to Maldraxxus in the Shadowlands to get some rays for Ve'nari . Progress: Greetings.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 176140, 181648, 181687, 181692, 181732, 181733 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 235860, ["x"] = 0.69, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 1536, 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86392, 87294 }, ["questLines"] = { { ["id"] = 5763, ["name"] = "Rays of Sunshine", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5763, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[86588] = { ["id"] = 86588, ["name"] = "Ritualistic Murder", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 1536, ["storyline"] = { 86587, 86588, 86589, 86590, 86591, 86592, 86593, 86594, 86595, 86601, 86602, 86603, 86604, 86605, 86606, 86607, 86782, 86783 }, ["series"] = { 86589, 86590, 86591, 86592, 86593, 86782 }, ["description"] = "The local ritualists are causing problems for the necrorays. Specifically, plague problems. If you kill them, it should lessen the issues for the necrorays.", ["objectivesText"] = "Slay 13 Morbid Ritualists .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 235860, ["x"] = 0.69, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 235860, ["x"] = 0.69, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.69, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 86587 }, ["questLines"] = { { ["id"] = 5763, ["name"] = "Rays of Sunshine", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5763, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[86589] = { ["id"] = 86589, ["name"] = "A Plague a Day Keeps the Doctor Away", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 1536, ["storyline"] = { 86587, 86588, 86589, 86590, 86591, 86592, 86593, 86594, 86595, 86601, 86602, 86603, 86604, 86605, 86606, 86607, 86782, 86783 }, ["series"] = { 86588, 86590, 86591, 86592, 86593, 86782 }, ["description"] = "The ritualists have been testing a new plague out on our poor necrorays. This is abominable... That's my job! Bring me some samples of deceased rays and I should be able to concoct a cure for the ones that haven't perished.", ["objectivesText"] = "Collect 6 Plague Samples from dead Pestilential Necrorays. Progress: Do you have those samples for me?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 234815 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 235860, ["x"] = 0.69, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 235860, ["x"] = 0.69, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.69, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 86587 }, ["questLines"] = { { ["id"] = 5763, ["name"] = "Rays of Sunshine", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5763, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[86590] = { ["id"] = 86590, ["name"] = "I Don't Even Work Here", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 1536, ["storyline"] = { 86587, 86588, 86589, 86590, 86591, 86592, 86593, 86594, 86595, 86601, 86602, 86603, 86604, 86605, 86606, 86607, 86782, 86783 }, ["series"] = { 86588, 86589, 86591, 86592, 86593, 86782 }, ["description"] = "It's good you are here, apprentice! I came to gather the essences from the local rancor. They are wonderful for adding just that little extra spice to a plague. But now that you are here, I can have you gather them instead! What an excellent learning opportunity for you!", ["objectivesText"] = "Gather 15 Rancor Essences . Progress: Well? Have you gathered the essences?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 234944 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 235860, ["x"] = 0.69, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 235860, ["x"] = 0.69, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.69, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 86587 }, ["questLines"] = { { ["id"] = 5763, ["name"] = "Rays of Sunshine", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5763, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[86591] = { ["id"] = 86591, ["name"] = "A Poor Imitation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 1536, ["storyline"] = { 86587, 86588, 86589, 86590, 86591, 86592, 86593, 86594, 86595, 86601, 86602, 86603, 86604, 86605, 86606, 86607, 86782, 86783 }, ["series"] = { 86588, 86589, 86590, 86592, 86593, 86782 }, ["description"] = "This is Vorax's work. He was once my apprentice, just like you! He's trying to replicate my work? Flattering, but sloppy. I'll work on a solution for you, apprentice, while you work on a solution for him.", ["objectivesText"] = "Slay Grand Ritualist Vorax . Progress: Is the deed done?", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 235860, ["x"] = 0.69, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 235860, ["x"] = 0.69, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.69, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 86588, 86589, 86590 }, ["questLines"] = { { ["id"] = 5763, ["name"] = "Rays of Sunshine", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5763, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[86592] = { ["id"] = 86592, ["name"] = "Get Your Jabs", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 1536, ["storyline"] = { 86587, 86588, 86589, 86590, 86591, 86592, 86593, 86594, 86595, 86601, 86602, 86603, 86604, 86605, 86606, 86607, 86782, 86783 }, ["series"] = { 86588, 86589, 86590, 86591, 86593, 86782 }, ["description"] = "If these rays are to travel, we should inoculate them first. What a good opportunity for you to learn about administering anti-plague, apprentice! It's not something that happens here very often.", ["objectivesText"] = "Inoculate 5 Calmed Necrorays. Progress: Have you jabbed the necrorays?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 230030 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 235860, ["x"] = 0.69, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 235860, ["x"] = 0.69, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.69, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 86591 }, ["questLines"] = { { ["id"] = 5763, ["name"] = "Rays of Sunshine", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5763, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[86593] = { ["id"] = 86593, ["name"] = "To the Oasis", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 1536, ["storyline"] = { 86587, 86588, 86589, 86590, 86591, 86592, 86593, 86594, 86595, 86601, 86602, 86603, 86604, 86605, 86606, 86607, 86782, 86783 }, ["series"] = { 86588, 86589, 86590, 86591, 86592, 86782 }, ["description"] = "I suppose you will be heading back now? It has been a true joy to work with you, apprentice. I hope we will see each other soon. I'll have some new experiments for you to help me out with. Please do take care of the necrorays! I hope they enjoy their new home.", ["objectivesText"] = "Travel to the Oasis on K'aresh. Progress: Well?", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 56840, 56841, 56842, 56843, 230030 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 235860, ["x"] = 0.69, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.69, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1536, 2371 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 86592 }, ["questLines"] = { { ["id"] = 5763, ["name"] = "Rays of Sunshine", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5763, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86594] = { ["id"] = 86594, ["name"] = "A Cultured Palette", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86587, 86588, 86589, 86590, 86591, 86592, 86593, 86594, 86595, 86601, 86602, 86603, 86604, 86605, 86606, 86607, 86782, 86783 }, ["series"] = { 86595, 86783 }, ["description"] = "We're trying to figure out what these rays eat. I've gathered some options. Can ye put them out? I'll watch for responses.", ["objectivesText"] = "Place 3 Food Items. Progress: Feeding time. Get to it!", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 235370 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 236846, ["x"] = 0.484, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 236846, ["x"] = 0.484, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86782 }, ["questLines"] = { { ["id"] = 5763, ["name"] = "Rays of Sunshine", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5763, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86595] = { ["id"] = 86595, ["name"] = "Custodial Duties", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86587, 86588, 86589, 86590, 86591, 86592, 86593, 86594, 86595, 86601, 86602, 86603, 86604, 86605, 86606, 86607, 86782, 86783 }, ["series"] = { 86594, 86783 }, ["description"] = "Seems like these rays slough off some gunk as they move. It's congealin' and makin' a mess! Ve'nari sent over this vacuum device to help out. Can you clean things up while yer out and about?", ["objectivesText"] = "Clean 18 Congealed Lumps in the Atrium.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 235384 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 236846, ["x"] = 0.484, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 236846, ["x"] = 0.484, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86782 }, ["questLines"] = { { ["id"] = 5763, ["name"] = "Rays of Sunshine", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5763, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86601] = { ["id"] = 86601, ["name"] = "Triple Twenty", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86587, 86588, 86589, 86590, 86591, 86592, 86593, 86594, 86595, 86601, 86602, 86603, 86604, 86605, 86606, 86607, 86782, 86783 }, ["description"] = "Tag the necrorays with these darts. It'll monitor their location and health. It also injects a pain killer so the necrorays don't even notice it. These brokers have some incredible inventions!", ["objectivesText"] = "Tag 5 Curious Necrorays .", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 235411 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 236890, ["x"] = 0.49, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 236890, ["x"] = 0.49, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86783 }, ["questLines"] = { { ["id"] = 5763, ["name"] = "Rays of Sunshine", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5763, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86602] = { ["id"] = 86602, ["name"] = "Medical Checkup", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86587, 86588, 86589, 86590, 86591, 86592, 86593, 86594, 86595, 86601, 86602, 86603, 86604, 86605, 86606, 86607, 86782, 86783 }, ["description"] = "You said your friend de-plagued those necrorays, but we need to see if the other animals are picking up anything else from them. Can ye go and collect some samples so we can check for issues?", ["objectivesText"] = "Collect samples from animals in Eco-Dome: Primus. Progress: Did ye get them all?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 235408, 235409, 235410 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 236890, ["x"] = 0.49, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 236890, ["x"] = 0.49, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86783 }, ["questLines"] = { { ["id"] = 5763, ["name"] = "Rays of Sunshine", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5763, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86603] = { ["id"] = 86603, ["name"] = "Ray-ket Ball", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86587, 86588, 86589, 86590, 86591, 86592, 86593, 86594, 86595, 86601, 86602, 86603, 86604, 86605, 86606, 86607, 86782, 86783 }, ["description"] = "It seems one of the necrorays you brought back was pregnant, so I have been dealing with a newborn all day. Thank you. Perhaps you would not mind testing out its reflexes for me?", ["objectivesText"] = "Catch a ball 10 times while playing with your Necroray Pup. Progress: Have you finished playin--er, testing the pup's reflexes yet?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 229420 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86601, 86602 }, ["questLines"] = { { ["id"] = 5763, ["name"] = "Rays of Sunshine", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5763, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86604] = { ["id"] = 86604, ["name"] = "Dubious Intent", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86587, 86588, 86589, 86590, 86591, 86592, 86593, 86594, 86595, 86601, 86602, 86603, 86604, 86605, 86606, 86607, 86782, 86783 }, ["description"] = "The ooze that Hemet had you collect may be of use to us. Go and collect the ooze directly from the necrorays. You can use this tranquilizer dart to bring them within range for collection.", ["objectivesText"] = "Collect 7 Necroray Gunk . Progress: Have you gathered the ooze?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 235500, 235501 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86603 }, ["questLines"] = { { ["id"] = 5763, ["name"] = "Rays of Sunshine", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5763, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86605] = { ["id"] = 86605, ["name"] = "Booster Shots", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86587, 86588, 86589, 86590, 86591, 86592, 86593, 86594, 86595, 86601, 86602, 86603, 86604, 86605, 86606, 86607, 86782, 86783 }, ["description"] = "After some analysis of the samples you brought back, it appears the necrorays are suffering from a vitamin deficiency. Ve'nari contacted Marileth, who prepared something... and then re-prepared it after she requested he remove the plague from it. Please gather the necrorays so we can test the initial batches.", ["objectivesText"] = "Lasso 6 Tranquil Necrorays and bring them to the Hitching Post by Om'talad . Progress: Have you gathered the necrorays?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 235851 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86604 }, ["questLines"] = { { ["id"] = 5763, ["name"] = "Rays of Sunshine", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5763, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86606] = { ["id"] = 86606, ["name"] = "The Golden Ooze", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86587, 86588, 86589, 86590, 86591, 86592, 86593, 86594, 86595, 86601, 86602, 86603, 86604, 86605, 86606, 86607, 86782, 86783 }, ["description"] = "Our custodians have yet to do their daily cleanup of the necrorays' discharge. I have many buyers in Tazavesh lined up for this material. They need it urgently, so its collection falls to you. Take the vacuum device. Compensation will be provided.", ["objectivesText"] = "Clean 25 Congealed Lumps in the Oasis. Progress: Have you succeeded at your task?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 235384 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86605 }, ["questLines"] = { { ["id"] = 5763, ["name"] = "Rays of Sunshine", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5763, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86607] = { ["id"] = 86607, ["name"] = "The Freedom of Ray-cing", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86587, 86588, 86589, 86590, 86591, 86592, 86593, 86594, 86595, 86601, 86602, 86603, 86604, 86605, 86606, 86607, 86782, 86783 }, ["description"] = "Those necrorays responded really well to those treatments you gave 'em! So well in fact that one of 'em is needin' to burn off some energy. Would ye be able to wear it out?", ["objectivesText"] = "Challenge the Zooming Necroray to a race and reach the finish line. Progress: Have ye worn the thing out yet?", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 242371 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86606 }, ["questLines"] = { { ["id"] = 5763, ["name"] = "Rays of Sunshine", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5763, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86610] = { ["id"] = 86610, ["name"] = "Nor Void of Night", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 84962, 85812, 85822, 85834, 85855, 85863, 85864, 86305, 86367, 86372, 86391, 86395, 86409, 86584, 86610, 86696, 86707, 86709, 86800, 86872 }, ["objectivesText"] = "Check in with Katy Stampwhistle Hosaas' Rest mail delivered Overlook Zo'Shuul mail delivered Shan'dorah mail delivered The Oasis mail delivered", ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.59, ["y"] = 0.834, ["mapID"] = 2472 } }, ["ends"] = { { ["x"] = 0.59, ["y"] = 0.834, ["mapID"] = 2472 } }, ["coords"] = { ["mapID"] = 2472, ["x"] = 0.59, ["y"] = 0.834 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15781 } }, ["questType"] = "world", ["questLines"] = { { ["id"] = 5737, ["name"] = "K'aresh - World Quests/Repeatables", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Check in with Katy Stampwhistle", ["amount"] = 1, ["type"] = 3, ["objectID"] = 235886, ["orderIndex"] = 0 }, { ["text"] = "Hosaas' Rest mail delivered", ["amount"] = 0, ["type"] = 19, ["objectID"] = 35988, ["orderIndex"] = 1 }, { ["text"] = "Overlook Zo'Shuul mail delivered", ["amount"] = 0, ["type"] = 19, ["objectID"] = 35989, ["orderIndex"] = 2 }, { ["text"] = "Shan'dorah mail delivered", ["amount"] = 0, ["type"] = 19, ["objectID"] = 35990, ["orderIndex"] = 3 }, { ["text"] = "The Oasis mail delivered", ["amount"] = 0, ["type"] = 19, ["objectID"] = 35987, ["orderIndex"] = 4 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371, ["db2QuestHubAreaPoiID"] = 8385, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[86618] = { ["id"] = 86618, ["name"] = "License Not Required", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84352, 86618, 87581 }, ["description"] = "Alright. Before you go out and run somebody over let's make sure you know how to do it properly. We'll introduce you to the car, the D.R.I.V.E. service we offer, and how to drive it in style.", ["objectivesText"] = "Learn how to drive the G-99 Breakneck . Progress: Just put your foot on the pedal and the rest will come naturally.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 227210, ["x"] = 0.374667, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 227210, ["x"] = 0.374667, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.374667, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 84352 }, ["questLines"] = { { ["id"] = 5772, ["name"] = "Shipping? Handled.", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[86619] = { ["id"] = 86619, ["name"] = "Theater Troupe", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["storyline"] = { 86619 }, ["rewardItems"] = { 226263, 235151, 239128, 250763 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[86621] = { ["id"] = 86621, ["name"] = "The Wayward Magister", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86621, 86622, 86623, 86624, 86626, 86632, 86633, 86634, 86635, 86636, 86781, 90493, 90494, 90509, 90907 }, ["description"] = "Magister Umbric --he's second only to Mother in mastering the Void. If anyone can help us with that storm in the sky, he's the one who can make it happen... if he can forgive the others for not listening to him in the first place. At least Lor'themar saw reason. There's no way we can take the fight to Xal'atath without Umbric. The forces keeping the Voidstorm at bay will only hold out so long. Let's make haste.", ["objectivesText"] = "Accompany Arator to meet with Magister Umbric in Tranquillien. Progress: What's that you have there?", ["rewardGold"] = 31200, ["rewardXP"] = 1470, ["rewardItems"] = { 239496 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236716, ["x"] = 0.472, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236087, ["x"] = 0.476, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86745 }, ["questLines"] = { { ["id"] = 5720, ["name"] = "Shadowfall", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5720, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 2395 },
[86622] = { ["id"] = 86622, ["name"] = "Chance Meeting", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86621, 86622, 86623, 86624, 86626, 86632, 86633, 86634, 86635, 86636, 86781, 90493, 90494, 90509, 90907 }, ["description"] = "I've heard some odd rumors myself. Strange happenings to the south--but also to the east and west, and the north. Tranquillien is surrounded by enemies, it seems. Since you are so dead-set on your investigation, would you look into something for me? There is an important report I need from one of my scouts. Check in with them, while I check over the rest of town.", ["objectivesText"] = "Meet with Lord Antenorian 's scout near Tranquillien. Progress: Let's get to the bottom of this.", ["rewardGold"] = 322100, ["rewardXP"] = 11765, ["rewardItems"] = { 243221, 248049, 248050 }, ["rewardChoices"] = { 248049, 248050 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 245004, ["x"] = 0.472, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236100, ["x"] = 0.476, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 90907 }, ["questLines"] = { { ["id"] = 5720, ["name"] = "Shadowfall", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5720, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 2395 },
[86623] = { ["id"] = 86623, ["name"] = "Appeal to the Void", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86621, 86622, 86623, 86624, 86626, 86632, 86633, 86634, 86635, 86636, 86781, 90493, 90494, 90509, 90907 }, ["description"] = "Kasiea... whatever you've found, you've perished for it. I won't let her work be in vain. There's something to be found here, $p. There are a few locations listed. Let's travel to them and try some of these theorems. The formulae may be incomplete, but perhaps we can discover what she was looking for. It had to have been important.", ["objectivesText"] = "Assist Umbric with testing Void theorems outside of Tranquillien.", ["rewardGold"] = 328500, ["rewardXP"] = 11765, ["rewardItems"] = { 251883 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236087, ["x"] = 0.476, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236087, ["x"] = 0.476, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86621 }, ["questLines"] = { { ["id"] = 5720, ["name"] = "Shadowfall", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5720, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 2395 },
[86624] = { ["id"] = 86624, ["name"] = "Rational Explanation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86621, 86622, 86623, 86624, 86626, 86632, 86633, 86634, 86635, 86636, 86781, 90493, 90494, 90509, 90907 }, ["description"] = "Something just doesn't feel right about all of this. Umbric can look into the notebook, but I suspect there's something more going on here. It couldn't hurt to ask around Tranquillien and see if anyone's heard anything odd. I'll take the north side of town, and you take the south. And... use your discretion, my friend. We should avoid alarming anyone for now.", ["objectivesText"] = "Question the townsfolk of Tranquillien and take note of any clues. Progress: How goes your investigation?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 244194, 244195, 244197 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236100, ["x"] = 0.476, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236100, ["x"] = 0.476, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86621 }, ["questLines"] = { { ["id"] = 5720, ["name"] = "Shadowfall", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5720, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 2395 },
[86625] = { ["id"] = 86625, ["name"] = "The Clue in the Inn", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86625 }, ["description"] = "Call me paranoid, you'd be correct, but I have been chased out of enough towns that I have a system. I establish a safehouse. Somewhere easily defensible, with enough materials that I can finish any delicate tasks and prepare for departure. That is the situation we find ourselves in-- we will retreat to the top floor of the inn and assess our options from there. I had shared the location with Caliea, when she was still studying with me... hopefully it serves us better than it did her.", ["objectivesText"] = "Retreat to Umbric's safehouse on the top floor of the inn.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15968 } }, ["questType"] = "standard" },
[86626] = { ["id"] = 86626, ["name"] = "The Ransacked Lab", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86621, 86622, 86623, 86624, 86626, 86632, 86633, 86634, 86635, 86636, 86781, 90493, 90494, 90509, 90907 }, ["description"] = "My notes, my research... I never should have left it alone. I was just beginning to understand the Voidstorm! Everything I'd learned, torn from my hands by cultists... Were they watching the entire time? Waiting for me to turn my back? I cannot let this stop me. They can't have destroyed everything. Perhaps there's enough here to salvage.", ["objectivesText"] = "Scour Umbric's ransacked lab for any salvageable research.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 242143, ["x"] = 0.476, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236687, ["x"] = 0.474, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86622 }, ["questLines"] = { { ["id"] = 5720, ["name"] = "Shadowfall", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5720, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 2395 },
[86632] = { ["id"] = 86632, ["name"] = "The Battle for Tranquillien", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86621, 86622, 86623, 86624, 86626, 86632, 86633, 86634, 86635, 86636, 86781, 90493, 90494, 90509, 90907 }, ["description"] = "The Twilight's Blade? Attacking in broad daylight now that their cover's blown... we'll prove what a mistake that was. Slay the traitors and the creatures they've summoned. Destroy their effigies and their supplies. Make this retreat costly, <name>.", ["objectivesText"] = "Free Tranquillien from the grip of the Twilight's Blade. Progress: Let's hope there's enough left here to rebuild.", ["rewardGold"] = 683200, ["rewardXP"] = 14705, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3365, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236687, ["x"] = 0.474, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 243984, ["x"] = 0.49, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86626 }, ["questLines"] = { { ["id"] = 5720, ["name"] = "Shadowfall", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5720, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 2395 },
[86633] = { ["id"] = 86633, ["name"] = "Comprehend the Void", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86621, 86622, 86623, 86624, 86626, 86632, 86633, 86634, 86635, 86636, 86781, 90493, 90494, 90509, 90907 }, ["description"] = "Kasiea's notes may be lost forever, but we must try and improvise. I have one final ritual to try. If this doesn't work, then the answers lay in Deatholme, the Twilight's Blade's heart. But first...", ["objectivesText"] = "Meet Umbric at the ritual site in Windrunner Village. There, collect 4 Void Shards and return them to the Void nexus. Progress: I can't hold this indefinitely--a little speed would be appreciated!", ["rewardGold"] = 322100, ["rewardXP"] = 11765, ["rewardItems"] = { 248046, 250361 }, ["rewardChoices"] = { 248046, 250361 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236363, ["x"] = 0.37, ["y"] = 0.74 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 237240, ["x"] = 0.374, ["y"] = 0.746 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.74 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86634 }, ["questLines"] = { { ["id"] = 5720, ["name"] = "Shadowfall", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5720, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 2395 },
[86634] = { ["id"] = 86634, ["name"] = "The Past Keeps Watch", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86621, 86622, 86623, 86624, 86626, 86632, 86633, 86634, 86635, 86636, 86781, 90493, 90494, 90509, 90907 }, ["description"] = "I don't trust the quiet here. Let's shore up the defenses. Did you see those slumped-over arcane golems around the village? They may not look like much now, but a quick tune up will have them on their feet soon enough. They're good for standing guard, and also for ferreting out any hidden snakes in the weeds. Let's get to work. The sooner the golems are running, the better I'll feel about this town's safety.", ["objectivesText"] = "Activate 6 Decrepit Ranger Constructs on the borders of Windrunner Village. Progress: It's odd being here. This place is... well, I suppose it's technically my namesake.", ["rewardGold"] = 312800, ["rewardXP"] = 11765, ["rewardItems"] = { 248030, 248031, 248032, 248033 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236391, ["x"] = 0.372, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236391, ["x"] = 0.372, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.372, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86781 }, ["questLines"] = { { ["id"] = 5720, ["name"] = "Shadowfall", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5720, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 2395 },
[86635] = { ["id"] = 86635, ["name"] = "To Deatholme", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86621, 86622, 86623, 86624, 86626, 86632, 86633, 86634, 86635, 86636, 86781, 90493, 90494, 90509, 90907 }, ["description"] = "That coward Antenorian has doomed us all. I had hoped it wouldn't come to this, but... We need the rest of Kasiea's research--the missing pages that were stolen from her corpse. But the cult has retreated south, to the ruins of Deatholme. Fitting that such traitors would sequester themselves in such a vile place. But we must root them out.", ["objectivesText"] = "Meet with Magister Umbric in the Ruins of Deatholme. Progress: Watch your back. The ruins of Deatholme are still dangerous.", ["rewardGold"] = 34100, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 237240, ["x"] = 0.374, ["y"] = 0.746 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236730, ["x"] = 0.445, ["y"] = 0.851 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.374, ["y"] = 0.746 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86633 }, ["questLines"] = { { ["id"] = 5720, ["name"] = "Shadowfall", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5720, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 2395 },
[86636] = { ["id"] = 86636, ["name"] = "Void Walk With Me", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86621, 86622, 86623, 86624, 86626, 86632, 86633, 86634, 86635, 86636, 86781, 90493, 90494, 90509, 90907 }, ["description"] = "I did not expect this place to be so heavily guarded. This is far more complicated than one charismatic leader and a group of wayward pilgrims. Still... if we take out Antenorian, it should weaken them considerably. A cult is nothing without its leader. Valeera tracked the governor to that cavern. He's gone in. We'll make sure he never comes out.", ["objectivesText"] = "Complete the Deatholme Delve. Progress: Let's be done with this. The Twilight's Blade must fall.", ["rewardGold"] = 1366400, ["rewardXP"] = 23530, ["rewardItems"] = { 249630, 249634, 249638, 249642, 249646, 249650, 253153 }, ["rewardChoices"] = { 249630, 249634, 249638, 249642, 249646, 249650, 249654, 249658 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236730, ["x"] = 0.445, ["y"] = 0.851 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236730, ["x"] = 0.445, ["y"] = 0.851 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.851 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86635 }, ["questLines"] = { { ["id"] = 5720, ["name"] = "Shadowfall", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5720, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 2395 },
[86637] = { ["id"] = 86637, ["name"] = "Anything but Reprieve", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86637, 86638, 86639, 86640, 86641, 86642, 86643, 86644, 86646, 86647, 86648, 86649, 86650 }, ["description"] = "This is dire. The Twilight's Blade is much larger--much more powerful--than any of us could have guessed. I'm relieved Umbric is on the case, but we need to let Silvermoon know what's happened here.", ["objectivesText"] = "Contact Silvermoon.", ["rewardGold"] = 31900, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 242433, ["x"] = 0.446, ["y"] = 0.852 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236099, ["x"] = 0.529333, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.852 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86636 }, ["questLines"] = { { ["id"] = 5721, ["name"] = "Ripple Effects", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5721, ["questLineOrder"] = 3 } }, ["db2PoiUiMapID"] = 2395 },
[86638] = { ["id"] = 86638, ["name"] = "Choking Tendrils", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86637, 86638, 86639, 86640, 86641, 86642, 86643, 86644, 86646, 86647, 86648, 86649, 86650 }, ["description"] = "I haven't the expertise of Orweyna in these matters. But if the Lightbloom moved this quickly, I assume the rutaani are accelerating the spread here just as they were in Fairbreeze. The town is beyond saving, but we can at least try to contain the Lightbloom within its walls.", ["objectivesText"] = "Cull the Lightbloom in Suncrown Village. Progress: Fairbreeze was nothing compared to this. What... happened here?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236132, ["x"] = 0.526, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236568, ["x"] = 0.535, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86637 }, ["questLines"] = { { ["id"] = 5721, ["name"] = "Ripple Effects", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5721, ["questLineOrder"] = 3 } }, ["db2PoiUiMapID"] = 2395 },
[86639] = { ["id"] = 86639, ["name"] = "What's Left", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86637, 86638, 86639, 86640, 86641, 86642, 86643, 86644, 86646, 86647, 86648, 86649, 86650 }, ["description"] = "You see what we have to contend with here. Runestone Shan'dor is helping stop the spread further north, but if this Lightbloom surges again, I don't know if we can halt it. I've heard cries for help from survivors still trapped within. We have to find them, and direct them to safety!", ["objectivesText"] = "Find and aid survivors in Suncrown Village. Progress: By the Light... this is so much worse than I would have ever imagined.", ["rewardGold"] = 325300, ["rewardXP"] = 11765, ["rewardItems"] = { 237858, 237870, 237879, 237886, 248057, 248058 }, ["rewardChoices"] = { 248057, 248058 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236099, ["x"] = 0.529333, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236099, ["x"] = 0.529333, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.529333, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86637 }, ["questLines"] = { { ["id"] = 5721, ["name"] = "Ripple Effects", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5721, ["questLineOrder"] = 3 } }, ["db2PoiUiMapID"] = 2395 },
[86640] = { ["id"] = 86640, ["name"] = "Premonition", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86637, 86638, 86639, 86640, 86641, 86642, 86643, 86644, 86646, 86647, 86648, 86649, 86650 }, ["description"] = "I came as quickly as I could. This is... devastating. I have called in our Magisters to reinforce this runestone. They will keep an eye on the Lightbloom spread. I suspect Halduron Brightwing and the Farstriders have uncovered more than the villagers know. I can rely on him for anything. We shall rendezvous with him at the encampment to the north, and soon have some answers.", ["objectivesText"] = "Regroup with Lor'themar Theron at Scintilas Outpost.", ["rewardGold"] = 31900, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236572, ["x"] = 0.534667, ["y"] = 0.545333 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 241206, ["x"] = 0.592, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.534667, ["y"] = 0.545333 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86638, 86639 }, ["questLines"] = { { ["id"] = 5721, ["name"] = "Ripple Effects", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5721, ["questLineOrder"] = 3 } }, ["db2PoiUiMapID"] = 2395 },
[86641] = { ["id"] = 86641, ["name"] = "Old Scars", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86637, 86638, 86639, 86640, 86641, 86642, 86643, 86644, 86646, 86647, 86648, 86649, 86650 }, ["description"] = "Of course the Amani would use this moment to encroach, the cowards. We are beset on all sides! This land belongs to the sin'dorei, and I will not see it taken by anyone. Not by raging plants, not by a cult, not by the Void, and never by the Amani! Whatever they are doing over there, it must be stopped. Do whatever you can to disrupt them and send them scurrying back to Zul'Aman where they belong.", ["objectivesText"] = "Disrupt the Amani lumber operation in Tor'Watha.", ["rewardGold"] = 319000, ["rewardXP"] = 11765, ["rewardItems"] = { 248019, 248020, 248021, 248022 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 241206, ["x"] = 0.592, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 241272, ["x"] = 0.644, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86640 }, ["questLines"] = { { ["id"] = 5721, ["name"] = "Ripple Effects", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5721, ["questLineOrder"] = 3 } }, ["db2PoiUiMapID"] = 2395 },
[86642] = { ["id"] = 86642, ["name"] = "A Foe Unseen", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86637, 86638, 86639, 86640, 86641, 86642, 86643, 86644, 86646, 86647, 86648, 86649, 86650 }, ["description"] = "I know Lor'themar is angry, but... this is strange, $p. They didn't attack Suncrown--the Lightbloom did. What are the Amani doing over there? There has to be some kind of explanation for this. It doesn't look like an invasion. Let's see what we can find out.", ["objectivesText"] = "Find information about what the trolls are doing in Tor'Watha.", ["rewardGold"] = 157900, ["rewardXP"] = 5885, ["rewardItems"] = { 244469 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236567, ["x"] = 0.59, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 241205, ["x"] = 0.645, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86640 }, ["questLines"] = { { ["id"] = 5721, ["name"] = "Ripple Effects", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5721, ["questLineOrder"] = 3 } }, ["db2PoiUiMapID"] = 2395 },
[86643] = { ["id"] = 86643, ["name"] = "Following the Root", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86637, 86638, 86639, 86640, 86641, 86642, 86643, 86644, 86646, 86647, 86648, 86649, 86650 }, ["description"] = "Lor'themar has a right to defend this land, but I don't think he's seeing clearly. The presence of Amani is too inciting. This doesn't add up. The trolls are going out of their way to craft Lightbloom weapons--to fight what? It isn't us. They didn't attack Suncrown. They could have, and they didn't. We need to find the truth. Let's head south. That hideout I discovered must have some answers.", ["objectivesText"] = "Meet Arator at Watha'nan Crypts in Eversong. Progress: There must be a reasonable answer for all of this.", ["rewardGold"] = 32200, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 241205, ["x"] = 0.645, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 241205, ["x"] = 0.645, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.645, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questTurnInID"] = 241205, ["questType"] = "standard", ["sourceQuests"] = { 86641, 86642 }, ["questLines"] = { { ["id"] = 5721, ["name"] = "Ripple Effects", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5721, ["questLineOrder"] = 3 } }, ["db2PoiUiMapID"] = 2579 },
[86644] = { ["id"] = 86644, ["name"] = "Gods Before Us", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2579, ["storyline"] = { 86637, 86638, 86639, 86640, 86641, 86642, 86643, 86644, 86646, 86647, 86648, 86649, 86650 }, ["description"] = "I suppose I shouldn't have expected a greeting with open arms, but I did not expect to be trapped in here. The Amani are clever. They must have made a way to escape. We have only to find it. Let's look around.", ["objectivesText"] = "Explore Watha'nan Crypts and pursue Zul'jan. Progress: There's a way out of here--I know it.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 244143, 244144, 252677 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 236610, ["mapID"] = 2579, ["x"] = 0.437506, ["y"] = 0.300725 } }, ["ends"] = { { ["npcID"] = 236610, ["mapID"] = 2579, ["x"] = 0.437506, ["y"] = 0.300725 } }, ["coords"] = { ["source"] = "quest_giver", ["mapID"] = 2579, ["x"] = 0.437506, ["y"] = 0.300725 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["sourceQuests"] = { 86643 }, ["questLines"] = { { ["id"] = 5721, ["name"] = "Ripple Effects", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5721, ["questLineOrder"] = 3 } }, ["db2PoiUiMapID"] = 2579 },
[86646] = { ["id"] = 86646, ["name"] = "An Impasse", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86637, 86638, 86639, 86640, 86641, 86642, 86643, 86644, 86646, 86647, 86648, 86649, 86650 }, ["description"] = "How deep does this crypt go? We need to find Zul'jan and explain to him that we fight a common enemy. Surely he'll see reason! Come on. They can't have gotten much farther in this maze.", ["objectivesText"] = "Pursue Vanatha and Zul'jan deeper into Watha'nan Crypts.", ["rewardGold"] = 683200, ["rewardXP"] = 14705, ["rewardItems"] = { 248080, 250470, 250471, 250472, 250473, 250474, 250475, 250476, 250477, 250478, 250479, 250480 }, ["rewardChoices"] = { 248080, 250470, 250471, 250472, 250473, 250474, 250475, 250476, 250477, 250478, 250479, 250480 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 } }, ["starts"] = { { ["npcID"] = 240662, ["mapID"] = 2579, ["x"] = 0.156591, ["y"] = 0.430779 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236737, ["x"] = 0.548, ["y"] = 0.682 }, { ["npcID"] = 240662, ["mapID"] = 2579, ["x"] = 0.156591, ["y"] = 0.430779 } }, ["coords"] = { ["source"] = "quest_giver", ["mapID"] = 2579, ["x"] = 0.156591, ["y"] = 0.430779 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86644 }, ["questLines"] = { { ["id"] = 5721, ["name"] = "Ripple Effects", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5721, ["questLineOrder"] = 3 } }, ["db2PoiUiMapID"] = 2395 },
[86647] = { ["id"] = 86647, ["name"] = "Beat of Blood", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86637, 86638, 86639, 86640, 86641, 86642, 86643, 86644, 86646, 86647, 86648, 86649, 86650 }, ["description"] = "None of this is necessary. We need to make them see reason! My father will know what to do. I know he'll see reason, once I explain what has happened here. There is no need for bloodshed! It's simple: if the Amani are set against the Twilight's Blade, we fight on the same side.", ["objectivesText"] = "Meet Arator at the Amani Pass.", ["rewardGold"] = 34100, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236737, ["x"] = 0.548, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236611, ["x"] = 0.582667, ["y"] = 0.814 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86646 }, ["questLines"] = { { ["id"] = 5721, ["name"] = "Ripple Effects", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5721, ["questLineOrder"] = 3 } }, ["db2PoiUiMapID"] = 2395 },
[86648] = { ["id"] = 86648, ["name"] = "Light Guide Us", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86637, 86638, 86639, 86640, 86641, 86642, 86643, 86644, 86646, 86647, 86648, 86649, 86650 }, ["description"] = "Our findings at Tor'Watha were correct. By the time Turalyon and I arrived here with troops, the Amani had already begun to take the pass. They seek to establish another path to acquire the lightwood from our land. The Amani have chosen war, as they always do. This, at least, is a threat I know how to handle. Arator is but a boy. He cannot grasp the magnitude of history between the sin'dorei and Amani--and I don't expect him to. Will you stand by the blood elves, and all that is right?", ["objectivesText"] = "Resolve the battle at the Amani Pass by helping the blood elves secure it, or try to dissuade the blood elves from fighting.", ["rewardGold"] = 938400, ["rewardXP"] = 17650, ["rewardItems"] = { 248027, 248028, 248029, 248053 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3365, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236612, ["x"] = 0.576, ["y"] = 0.814 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236612, ["x"] = 0.576, ["y"] = 0.814 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.814 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86647 }, ["questLines"] = { { ["id"] = 5721, ["name"] = "Ripple Effects", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5721, ["questLineOrder"] = 3 } }, ["db2PoiUiMapID"] = 2395 },
[86649] = { ["id"] = 86649, ["name"] = "Past Redemption", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86637, 86638, 86639, 86640, 86641, 86642, 86643, 86644, 86646, 86647, 86648, 86649, 86650 }, ["description"] = "These monsters deserve nothing more than swift retribution. For Silvermoon. For the sin'dorei. <Turalyon's eyes blaze with Light.> For Alleria. This will be finished!", ["objectivesText"] = "Finish the battle against the Amani at the Amani Pass.", ["rewardGold"] = 312800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 241654, ["x"] = 0.602, ["y"] = 0.814 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 237433, ["x"] = 0.605, ["y"] = 0.814 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.814 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86648 }, ["questLines"] = { { ["id"] = 5721, ["name"] = "Ripple Effects", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5721, ["questLineOrder"] = 3 } }, ["db2PoiUiMapID"] = 2395 },
[86650] = { ["id"] = 86650, ["name"] = "Fractured", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86637, 86638, 86639, 86640, 86641, 86642, 86643, 86644, 86646, 86647, 86648, 86649, 86650 }, ["description"] = "Lady Liadrin will remain here. The rest of us shall return to Silvermoon and debrief. <Lor'themar looks at the devastated Turalyon.> We still have many battles ahead, it seems.", ["objectivesText"] = "Return to Silvermoon City. Progress: There is much to do.", ["rewardGold"] = 938400, ["rewardXP"] = 17650, ["rewardItems"] = { 244538 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 237433, ["x"] = 0.605, ["y"] = 0.814 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.814 }, ["mapCandidates"] = { ["npc"] = { 2393, 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86649 }, ["questLines"] = { { ["id"] = 5721, ["name"] = "Ripple Effects", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5721, ["questLineOrder"] = 3 } }, ["db2PoiUiMapID"] = 2393 },
[86652] = { ["id"] = 86652, ["name"] = "Left in the Shadows", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86652, 86708, 86710, 86711, 86712, 86715, 86716, 86717, 86718, 86719, 86720, 86721, 86722, 86723, 86868, 90749 }, ["description"] = "De loa have not spoken to us in many years... not since I was a young child. And dey have shown no sign of wanting to help us now. No. It is up to us alone. We must find a way to rally de other tribes and fight de Twilight's Blade as one. I will speak to de tribal representatives and help de refugees where I can--dey are our priority. Come, you might learn somethin' about de Amani.", ["objectivesText"] = "Join Zul'jarra and Liadrin as they check on Atal'Aman refugees. Progress: Ancestors willing, we will find our opportunity to strike back soon.", ["rewardGold"] = 256200, ["rewardXP"] = 9130, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3354, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 236659, ["x"] = 0.451333, ["y"] = 0.664667 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 236126, ["x"] = 0.438, ["y"] = 0.684 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.451333, ["y"] = 0.664667 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86723 }, ["questLines"] = { { ["id"] = 5722, ["name"] = "Dis Was Our Land", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5722, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 2437, ["db2QuestHubAreaPoiID"] = 8504 },
[86653] = { ["id"] = 86653, ["name"] = "The Path of the Amani", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86653, 86654, 86655, 86656, 86657, 86658, 86659, 86660, 86661, 86663, 86664, 86665, 86666, 86808, 86809, 89334, 90772, 92084 }, ["description"] = "Kinduru is my uncle, and I trust him... But dis \"path of de hash'ey\"... Things are not what dey were decades ago. The loa are gone--they not gonna hear us. < Zul'jarra lets out a low growl only you and Liadrin hear.> No. We're running out of options. If dis is de time for old myths and dreams, so be it. We meet at the foot of the mountains, Akil'zon's Reach, where de old hash'ey shrines are.", ["objectivesText"] = "Meet Zul'jarra outside Akil'zon's Reach.", ["rewardGold"] = 31900, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3354, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 236126, ["x"] = 0.438, ["y"] = 0.684 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 236140, ["x"] = 0.516, ["y"] = 0.708 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.684 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86723 }, ["questLines"] = { { ["id"] = 5723, ["name"] = "Path of de Hash'ey", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5723, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 2437, ["db2QuestHubAreaPoiID"] = 8504 },
[86654] = { ["id"] = 86654, ["name"] = "Gnarldin Bashing", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86653, 86654, 86655, 86656, 86657, 86658, 86659, 86660, 86661, 86663, 86664, 86665, 86666, 86808, 86809, 89334, 90772, 92084 }, ["description"] = "Zul'jarra regards the gnarldin as a fierce, nomadic people that normally keep to themselves. It is clear by their clothing and weapons that they have a primitive but unique culture. If the circumstances were different, I would advocate for diplomacy. But they are between us and our mission. They cannot block our path or continue to damage the shrines or the nests of the eagles that roost here. We will eliminate only those that are in our way. The Amani can choose what to do with them later.", ["objectivesText"] = "Slay 12 gnarldin in Akil'zon's Reach. Progress: The gnarldin seem ready to fight us. Let's give them what they want, shall we?", ["rewardGold"] = 319000, ["rewardXP"] = 12170, ["rewardItems"] = { 264255 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3354, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 236143, ["x"] = 0.516, ["y"] = 0.708 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 236146, ["x"] = 0.52, ["y"] = 0.76 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.708 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86653 }, ["questLines"] = { { ["id"] = 5723, ["name"] = "Path of de Hash'ey", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5723, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 2437 },
[86655] = { ["id"] = 86655, ["name"] = "De Ancient Path", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86653, 86654, 86655, 86656, 86657, 86658, 86659, 86660, 86661, 86663, 86664, 86665, 86666, 86808, 86809, 89334, 90772, 92084 }, ["description"] = "My uncle, de loa speaker, spoke of de hash'ey when I was a child. But when de loa remained silent so many years... I do not think he would admit it, but he lost a little faith too. I remember some of his lessons. A chieftain must light de shrines on de way to de temple. De hash'ura must as well. Why? I do not remember. But if it is de only way to get de loa's favor? Come. Let us get dis out of de way.", ["objectivesText"] = "Light the 4 Hash'ey Shrines in Akil'zon's Reach. Progress: I hope we are doing dis right.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 248567, 248568, 248569, 248570 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 236140, ["x"] = 0.516, ["y"] = 0.708 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 236147, ["x"] = 0.518, ["y"] = 0.76 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.708 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86653 }, ["questLines"] = { { ["id"] = 5723, ["name"] = "Path of de Hash'ey", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5723, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 2437 },
[86656] = { ["id"] = 86656, ["name"] = "Brutal Feast", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86653, 86654, 86655, 86656, 86657, 86658, 86659, 86660, 86661, 86663, 86664, 86665, 86666, 86808, 86809, 89334, 90772, 92084 }, ["description"] = "< Zul'jarra 's brow furrows and her lip curls as she looks toward the temple.> When we lit de last shrine, some of de eagles returned to de temple. It could be a sign. < Zul'jarra scoffs.> Or de eagles are movin' in after de gnarldin started movin' out. When we get to the temple, all we gonna find is silence. Just like always. But we still gonna try. We should go now and present an offerin'.", ["objectivesText"] = "Reach the Temple of Akil'zon and seek Akil'zon's attention.", ["rewardGold"] = 170800, ["rewardXP"] = 6085, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 236147, ["x"] = 0.518, ["y"] = 0.76 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 244422, ["x"] = 0.524, ["y"] = 0.81 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.76 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86654, 86655, 89334 }, ["questLines"] = { { ["id"] = 5723, ["name"] = "Path of de Hash'ey", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5723, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 2437 },
[86657] = { ["id"] = 86657, ["name"] = "Shadebasin Watch", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86653, 86654, 86655, 86656, 86657, 86658, 86659, 86660, 86661, 86663, 86664, 86665, 86666, 86808, 86809, 89334, 90772, 92084 }, ["description"] = "< Zul'jarra smiles slightly as Akil'zon's blessing buffets her.> Kinduru's stories were real. We have de blessin' of Akil'zon, and de path of the hash'ey stretches out before us. We must follow Akil'zon's advice and seek out Halazzi next. As Akil'zon is de loa of de rulin' tribe--de Amani--and my family, Halazzi is de loa of the Witherbark and their leaders. If their loa speakers are gone, then maybe Kul'amara will know how to approach him.", ["objectivesText"] = "Speak with Kul'amara the Fierce at Shadebasin Watch. Progress: I thought de Witherbark were strong enough to handle de Vilebranch on their own. I should have come here before now.", ["rewardGold"] = 30900, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3354, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 236141, ["x"] = 0.522, ["y"] = 0.81 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 244438, ["x"] = 0.44, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.81 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86809 }, ["questLines"] = { { ["id"] = 5723, ["name"] = "Path of de Hash'ey", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5723, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 2437 },
[86658] = { ["id"] = 86658, ["name"] = "The Crypt in the Mist", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86653, 86654, 86655, 86656, 86657, 86658, 86659, 86660, 86661, 86663, 86664, 86665, 86666, 86808, 86809, 89334, 90772, 92084 }, ["description"] = "< Zul'jarra growls through her gritted tusks.> Now it's not as surprisin' dat Malacrass's tribe, de Vilebranch, fell to the lure of hex magic. But dat is their choice and a path dey chose long ago--a path away from us. I won't let dem live long enough to regret it. What de Vilebranch have done to de Witherbark has gone too long without an Amani response. De mist is not in our way. We can use it to our advantage. We will take a life for all de lives dey took. And make sure dey stay dead.", ["objectivesText"] = "Slay 8 Vilebranch trolls and Ritualist Zongha in Numazon Crypt. Progress: Finding Halazzi can wait. The Vilebranch are preyin' on my people. It's about time some predators hunted dem.", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 248571, 248572, 248573, 248574 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3354, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 244438, ["x"] = 0.44, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 244588, ["x"] = 0.368, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86657 }, ["questLines"] = { { ["id"] = 5723, ["name"] = "Path of de Hash'ey", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5723, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 2437 },
[86659] = { ["id"] = 86659, ["name"] = "Breaching the Mist", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86653, 86654, 86655, 86656, 86657, 86658, 86659, 86660, 86661, 86663, 86664, 86665, 86666, 86808, 86809, 89334, 90772, 92084 }, ["description"] = "The Vilebranch seemed to be just as confused by the mist as the Witherbark. Whatever has caused de mist, dealin' with de Vilebranch changed nothing. And now we must find de hash'ey shrines in de dark. < Zul'jarra moves her hand in front of her face, testing her range of visibility, and frowns.> We must light de shrines. Try not to get separated. Dis will try my patience. But I'm sure if we use our heads, we will find de path.", ["objectivesText"] = "Light the Hash'ey Shrines around the Temple of Halazzi.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 248575, 248576 }, ["rewardChoices"] = { 248575, 248576 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 244588, ["x"] = 0.368, ["y"] = 0.35 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 236155, ["x"] = 0.324, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86658, 86660 }, ["questLines"] = { { ["id"] = 5723, ["name"] = "Path of de Hash'ey", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5723, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 2437 },
[86660] = { ["id"] = 86660, ["name"] = "Rescue from the Shadows", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86653, 86654, 86655, 86656, 86657, 86658, 86659, 86660, 86661, 86663, 86664, 86665, 86666, 86808, 86809, 89334, 90772, 92084 }, ["description"] = "Kul'amara has told me dat a shadowy mist has fallen over Numazon. She believes de Vilebranch are behind it, usin' their magic to hide de crimes dey commit against de Witherbark. She believes dey are hidin' in de Numazon crypts. De hash'ey shrines are near there as well. We must find our way to Numazon and rescue de Witherbark captives. If we find de hash'ey shrines along de way, so be it. If Halazzi will not stand with us, den maybe de Witherbark will.", ["objectivesText"] = "Rescue 8 Witherbark captives in Numazon. Progress: Keep on de lookout for more Witherbark captives!", ["rewardGold"] = 319000, ["rewardXP"] = 12170, ["rewardItems"] = { 253469 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3354, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 244438, ["x"] = 0.44, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 244588, ["x"] = 0.368, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86657 }, ["questLines"] = { { ["id"] = 5723, ["name"] = "Path of de Hash'ey", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5723, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 2437 },
[86661] = { ["id"] = 86661, ["name"] = "Coals of a Dead Loa", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86653, 86654, 86655, 86656, 86657, 86658, 86659, 86660, 86661, 86663, 86664, 86665, 86666, 86808, 86809, 89334, 90772, 92084 }, ["description"] = "By helpin' de Witherbark, we helped ourselves--and passed Halazzi's trial. There is a lesson in that. Now dat Halazzi has returned, we should go back and let Vun'zarah know. I hope dis will improve de relationship between our tribes. And maybe he knows where we can find out how to resurrect Jan'alai.", ["objectivesText"] = "Travel to Witherbark Bluffs and speak with Vun'zarah, leader of the Witherbark Tribe. Progress: We have come dis far. We must try to resurrect de dead loa.", ["rewardGold"] = 34100, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3354, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 236155, ["x"] = 0.324, ["y"] = 0.316 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 244592, ["x"] = 0.384667, ["y"] = 0.224667 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.324, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 92084 }, ["questLines"] = { { ["id"] = 5723, ["name"] = "Path of de Hash'ey", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5723, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 2437 },
[86663] = { ["id"] = 86663, ["name"] = "Embers to a Flame", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86653, 86654, 86655, 86656, 86657, 86658, 86659, 86660, 86661, 86663, 86664, 86665, 86666, 86808, 86809, 89334, 90772, 92084 }, ["description"] = "The loa speaker talks of fire in de heart--in all hearts. Jan'alai is de loa of birth, death, and rebirth. Maybe de loa speaker is askin' for sacrifice. < Zul'jarra smiles deviously.> Hey, Liadrin. How much fire you think is in an elf's heart, eh? <Liadrin gives her a sour look.> Heh. Whatever de loa speaker wants, it is either part of resurrectin' de loa or part of de trial. Lets see what he has do say.", ["objectivesText"] = "Slay Amazards to empower the Ember of Jan'alai. Progress: This loa speaker's holding onto his faith a bit like Kinduru. But Kinduru knows how to speak clearly what he means. Usually.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 264715 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3354, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 236162, ["x"] = 0.55, ["y"] = 0.184 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 236162, ["x"] = 0.55, ["y"] = 0.184 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.184 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86808 }, ["questLines"] = { { ["id"] = 5723, ["name"] = "Path of de Hash'ey", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5723, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 2437 },
[86664] = { ["id"] = 86664, ["name"] = "Seer or Sear", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86653, 86654, 86655, 86656, 86657, 86658, 86659, 86660, 86661, 86663, 86664, 86665, 86666, 86808, 86809, 89334, 90772, 92084 }, ["description"] = "Dis old, crazy loa speaker is too busy dancin' to tell us what to do next. But I think I know. We could not light de shrines on de way to de temple. But now dat Jan'alai's presence is here... Maybe now we can. I will take de ember to de hash'ey shrines. Den maybe de trial will start. I jumped from de top of de temple of Akil'zon. I found my way through de mists of Halazzi. I am ready for Jan'alai's fire. We can only hope dey will receive us after what my grandfather has done.", ["objectivesText"] = "Assist Zul'jarra in lighting Hash'ey Shrines of Jan'alai. Progress: No stoppin' de trial now. We must do what needs to be done.", ["rewardGold"] = 619600, ["rewardXP"] = 15215, ["rewardItems"] = { 248577, 248578 }, ["rewardChoices"] = { 248577, 248578 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3354, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 236162, ["x"] = 0.55, ["y"] = 0.184 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 236162, ["x"] = 0.55, ["y"] = 0.184 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.184 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86663 }, ["questLines"] = { { ["id"] = 5723, ["name"] = "Path of de Hash'ey", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5723, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 2437 },
[86665] = { ["id"] = 86665, ["name"] = "Face in the Fire", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86653, 86654, 86655, 86656, 86657, 86658, 86659, 86660, 86661, 86663, 86664, 86665, 86666, 86808, 86809, 89334, 90772, 92084 }, ["description"] = "First my grandfather, then my brother. Jan'alai knew my shame at my grandfather's rage. And de rage I feel when Zul'jan disrespects me. I know I put fuel on his fire by respondin' de way I do. Maybe dat needs to change. I have left my doubt of de loa behind me. I can leave those thoughts behind too, and continue de path of de hash'ey. Stoke de coal, <name>. I am ready for de final trial, whatever it may be.", ["objectivesText"] = "Slay the last Fire Manifestation in the Temple of Jan'alai. Progress: Let's get dis over with.", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3354, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 236162, ["x"] = 0.55, ["y"] = 0.184 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 236162, ["x"] = 0.55, ["y"] = 0.184 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.184 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86664 }, ["questLines"] = { { ["id"] = 5723, ["name"] = "Path of de Hash'ey", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5723, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 2437 },
[86666] = { ["id"] = 86666, ["name"] = "In the Shadow of Rebirth", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86653, 86654, 86655, 86656, 86657, 86658, 86659, 86660, 86661, 86663, 86664, 86665, 86666, 86808, 86809, 89334, 90772, 92084 }, ["description"] = "Jan'alai's trial has made me realize... I need to make things right between me and my brother. He acts out at me, but it's because I put him down. I do not think about how hard it must be to be my brother. We should also check on how our preparations are goin' and if my troops are gettin' de food and rest dey need. Nalorakk's not gonna go anywhere. He can wait a few hours.", ["objectivesText"] = "Meet Zul'jarra in Amani'Zar Village.", ["rewardGold"] = 31900, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3354, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 236162, ["x"] = 0.55, ["y"] = 0.184 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 240186, ["x"] = 0.438, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.184 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 90772 }, ["questLines"] = { { ["id"] = 5723, ["name"] = "Path of de Hash'ey", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5723, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 2437 },
[86681] = { ["id"] = 86681, ["name"] = "Den of Nalorakk: A Taste of Vengeance", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86681, 86682, 91958 }, ["description"] = "Zul'jan has taken de troops without my orders--again! And de number of casualties... for what? For wood? I want to take his tusks and... < Zul'jarra growls but seems to center herself.> Kinduru will need help with de soldiers' death rites. Help him prepare de herb mixture and pour it onto de fires. My brother and I need to... talk.", ["objectivesText"] = "Assist Elder Kinduru with the death rites. Progress: There are so few of us left. What was my brother thinking?", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 264479, 264480, 264481 }, ["rewardChoices"] = { 264479, 264480, 264481 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3354, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 240186, ["x"] = 0.438, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 240186, ["x"] = 0.438, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86666 }, ["questLines"] = { { ["id"] = 5938, ["name"] = "Where War Slumbers", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5938, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 2437, ["db2QuestHubAreaPoiID"] = 8504 },
[86682] = { ["id"] = 86682, ["name"] = "Den of Nalorakk: Waking de Bear", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86681, 86682, 91958 }, ["description"] = "We must set aside what Zul'jan has done and focus on de final hash'ey trial: facin' Nalorakk, de Loa of War. De Revantusk were once beloved of Nalorakk. Legend has it dat his loa speaker was so devoted, she followed him into his temple and his den with de most faithful of de Revantusk's warriors. But now de temple is sealed. We cannot speak to de loa speaker, but maybe Lilaju knows how to get Nalorakk's attention. She keeps watch for de Twilight's Blade at Torntusk Overlook with her guards.", ["objectivesText"] = "Travel to Torntusk Overlook and speak with Lilaju, the Revantusk leader. Progress: Lilaju is de only person who can help us now.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3354, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 240186, ["x"] = 0.438, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 240215, ["x"] = 0.322, ["y"] = 0.821333 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86681 }, ["questLines"] = { { ["id"] = 5938, ["name"] = "Where War Slumbers", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5938, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 2437, ["db2QuestHubAreaPoiID"] = 8504 },
[86683] = { ["id"] = 86683, ["name"] = "Hash'ey Away", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86683, 86684, 86685, 86686, 86687, 86692, 86693, 91001, 91062 }, ["description"] = "We've done it, <name>. De loa are at our side once again. Am I hash'ey? I do not know. But I do know I would not have gotten dis far without my hash'ura. Come. We will return to Amani'Zar and tell Kinduru and Zul'jan de good news.", ["objectivesText"] = "Meet Zul'jarra at Amani'Zar Village.", ["rewardGold"] = 31200, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3354, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 240215, ["x"] = 0.322, ["y"] = 0.821333 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 240216, ["x"] = 0.436, ["y"] = 0.688 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.322, ["y"] = 0.821333 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91958 }, ["questLines"] = { { ["id"] = 5724, ["name"] = "De Amani Never Die", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5724, ["questLineOrder"] = 7 } }, ["db2PoiUiMapID"] = 2437 },
[86684] = { ["id"] = 86684, ["name"] = "The Blade's Edge", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86683, 86684, 86685, 86686, 86687, 86692, 86693, 91001, 91062 }, ["description"] = "With de other tribes and de loa's help, we can take de fight to de Twilight's Blade and take dem down. Blood for blood!", ["objectivesText"] = "Meet Zul'jarra and Liadrin at Broken Throne to fight the Twilight's Blade.", ["rewardGold"] = 33500, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3354, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 240216, ["x"] = 0.436, ["y"] = 0.688 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 240033, ["x"] = 0.284, ["y"] = 0.774 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86683 }, ["questLines"] = { { ["id"] = 5724, ["name"] = "De Amani Never Die", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5724, ["questLineOrder"] = 7 } }, ["db2PoiUiMapID"] = 2437, ["db2QuestHubAreaPoiID"] = 8504 },
[86685] = { ["id"] = 86685, ["name"] = "Chip and Shatter", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86683, 86684, 86685, 86686, 86687, 86692, 86693, 91001, 91062 }, ["description"] = "< Zul'jarra shakes her head back and forth and jumps in place, shaking out her muscles. She stops and turns to you, grinning broadly.> Heh. Do you feel it, my hash'ura? De electricity in de air? De smell of blood and fire? My soul is leapin' to join de fight. You ready to chop de enemy down, bathe in dey blood, and make dem pay for what dey done? Me too.", ["objectivesText"] = "Slay the Twilight's Blade at Broken Throne.", ["rewardGold"] = 335000, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3354, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 240033, ["x"] = 0.284, ["y"] = 0.774 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 245270, ["x"] = 0.256, ["y"] = 0.776 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.774 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86684 }, ["questLines"] = { { ["id"] = 5724, ["name"] = "De Amani Never Die", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5724, ["questLineOrder"] = 7 } }, ["db2PoiUiMapID"] = 2437 },
[86686] = { ["id"] = 86686, ["name"] = "Light Indiscriminate", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86683, 86684, 86685, 86686, 86687, 86692, 86693, 91001, 91062 }, ["description"] = "Though the dead litter this field, I still see plenty of Amani clinging to life. Help me heal the injured. We'll ensure their reputation for survival continues on after this day.", ["objectivesText"] = "Heal 10 Injured Amani Warriors. Progress: Every warrior healed is another sword at our side!", ["rewardGold"] = 312800, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3354, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 240039, ["x"] = 0.284, ["y"] = 0.774 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 245271, ["x"] = 0.256, ["y"] = 0.776 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.774 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86684 }, ["questLines"] = { { ["id"] = 5724, ["name"] = "De Amani Never Die", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5724, ["questLineOrder"] = 7 } }, ["db2PoiUiMapID"] = 2437 },
[86687] = { ["id"] = 86687, ["name"] = "Conduit Crisis", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86683, 86684, 86685, 86686, 86687, 86692, 86693, 91001, 91062 }, ["description"] = "With de loa at our side, we can finally break de Twilight's Blade and return to Amani'Zar with Mor'duun's head. De loa are already attackin' de main source of Mor'duun's power: summoned spheres of pure void energy. Go to de loa and offer your assistance. When de orbs are destroyed, we can move forward and strike at Mor'duun!", ["objectivesText"] = "Destroy the 12 Void Conduits hindering Nalorakk, Akil'zon, Halazzi, and Jan'alai in Broken Throne. Progress: Don't be afraid. If you assist dem, de loa will grant you their strength.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 248579, 248580, 248581, 248582 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 240033, ["x"] = 0.284, ["y"] = 0.774 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 245270, ["x"] = 0.256, ["y"] = 0.776 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.774 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86684 }, ["questLines"] = { { ["id"] = 5724, ["name"] = "De Amani Never Die", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5724, ["questLineOrder"] = 7 } }, ["db2PoiUiMapID"] = 2437 },
[86692] = { ["id"] = 86692, ["name"] = "Blade Shattered", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86683, 86684, 86685, 86686, 86687, 86692, 86693, 91001, 91062 }, ["description"] = "It ends here. De path of the hash'ey, my path, has led me here. Let dis fight bring a new age for my people. Come. It is time.", ["objectivesText"] = "Slay Mor'duun, High Inquisitor of the Twilight's Blade.", ["rewardGold"] = 1024800, ["rewardXP"] = 18255, ["rewardItems"] = { 65487, 248583 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3354, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 240034, ["x"] = 0.225, ["y"] = 0.774 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 240037, ["x"] = 0.215, ["y"] = 0.774 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.225, ["y"] = 0.774 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91001 }, ["questLines"] = { { ["id"] = 5724, ["name"] = "De Amani Never Die", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5724, ["questLineOrder"] = 7 } }, ["db2PoiUiMapID"] = 2437 },
[86693] = { ["id"] = 86693, ["name"] = "De Legend of de Hash'ey", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86683, 86684, 86685, 86686, 86687, 86692, 86693, 91001, 91062 }, ["description"] = "Mor'duun is slain. De Twilight's Blade will continue to plague our lands, but of dem only Mor'duun's \"fodder\" is left. Dey will be easy prey for us. And now I will say somethin' my uncle would be proud of. Let us follow de teachin' of Nalorakk, de Loa of War. De battle is over. It is time to rest--I can tell by your eyes both my hash'ura need it too. Let us leave dis place. We can speak again back in Amani'Zar.", ["objectivesText"] = "Speak with Zul'jarra in Amani'Zar Village.", ["rewardGold"] = 32800, ["rewardXP"] = 1520, ["rewardItems"] = { 255648 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3354, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 240037, ["x"] = 0.215, ["y"] = 0.774 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 249653, ["x"] = 0.456, ["y"] = 0.655 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.215, ["y"] = 0.774 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86692 }, ["questLines"] = { { ["id"] = 5724, ["name"] = "De Amani Never Die", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5724, ["questLineOrder"] = 7 } }, ["db2PoiUiMapID"] = 2437 },
