[86697] = { ["id"] = 86697, ["name"] = "The Cleanup Crew", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 86271, 86272, 86273, 86274, 86275, 86276, 86277, 86575, 86697 }, ["description"] = "Even if we got bots out there an' not workers, there are still gonna be monsters out there gettin' in their hair, er, wirin'. Get out there an' thin out the wildlife. That'll keep our bots from gettin' damaged and voidin' whatever warranty they got left. The longer they can stay out there, the longer we can stay right here!", ["objectivesText"] = "Kill enemies in the Writhing Fields in the Ringing Deeps . Progress: Got any good news, kid?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3118, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 233420, ["x"] = 0.684, ["y"] = 0.964 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 233420, ["x"] = 0.684, ["y"] = 0.964 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.684, ["y"] = 0.964 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 86575 }, ["questLines"] = { { ["id"] = 5736, ["name"] = "Sanity's Rest", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
