[86706] = { ["id"] = 86706, ["name"] = "Seeking Knowledge of the Past", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 86706, 87328, 87329, 87332, 87335, 87336 }, ["description"] = "Greetings, <race>. I must seek your aid. Soridormi and our kin have journeyed to Khaz Algar to help in this fight against the Void's new master. We think that we can provide insight and valuable information about past attacks by the Void. Seek her out near the southern edge of the Coreway.", ["objectivesText"] = "Seek out Soridormi near the Coreway in Dornogol on the Isle of Dorn .", ["rewardGold"] = 30900, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 238129, ["x"] = 0.424667, ["y"] = 0.285333 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 236382, ["x"] = 0.345, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.424667, ["y"] = 0.285333 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["nextQuests"] = { 87328 }, ["questLines"] = { { ["id"] = 5768, ["name"] = "Horrific Visions Revisited", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
