[86708] = { ["id"] = 86708, ["name"] = "The Gates of Zul'Aman", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2395, ["storyline"] = { 86652, 86708, 86710, 86711, 86712, 86715, 86716, 86717, 86718, 86719, 86720, 86721, 86722, 86723, 86868, 90749 }, ["description"] = "After the Amani surrender, we demanded Zul'jan relinquish our lightwood and return to their lands. Even so, Zul'jan still lingers at the gates of Zul'Aman with his troops. Lady Liadrin and her Blood Knights hold the pass, and Liadrin is trying to remedy the situation with diplomacy, but she reports that aggression may begin anew. She requests your assistance in this precarious matter.", ["objectivesText"] = "Meet Lady Liadrin at the Amani Pass.", ["rewardGold"] = 156400, ["rewardXP"] = 6085, ["starts"] = { { ["npcID"] = 240523, ["mapID"] = 2393, ["x"] = 0.455998, ["y"] = 0.703362 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236436, ["x"] = 0.602, ["y"] = 0.814 }, { ["npcID"] = 240523, ["mapID"] = 2393, ["x"] = 0.455998, ["y"] = 0.703362 } }, ["coords"] = { ["source"] = "quest_giver", ["mapID"] = 2393, ["x"] = 0.455998, ["y"] = 0.703362 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86735, 86736 }, ["questLines"] = { { ["id"] = 5722, ["name"] = "Dis Was Our Land", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5722, ["questLineOrder"] = 4 } }, ["db2AdventureMapPoiID"] = 194, ["db2PoiUiMapID"] = 2395 },
