[86710] = { ["id"] = 86710, ["name"] = "The Line Must Be Drawn Here", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2395, ["storyline"] = { 86652, 86708, 86710, 86711, 86712, 86715, 86716, 86717, 86718, 86719, 86720, 86721, 86722, 86723, 86868, 90749 }, ["description"] = "I had hoped that Zul'jan would leave the lightwood and return swiftly to his lands after our confrontation with him. But dealing with the Amani has never been a simple matter. Diplomacy is the only way to avoid more bloodshed, but Zul'jan is finished listening to me. Perhaps he will listen to you?", ["objectivesText"] = "Speak to Zul'jan and defuse the situation. Progress: An outsider's view may help him see reason.", ["rewardGold"] = 670000, ["rewardXP"] = 15215, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236436, ["x"] = 0.602, ["y"] = 0.814 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236436, ["x"] = 0.602, ["y"] = 0.814 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.814 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86708 }, ["questLines"] = { { ["id"] = 5722, ["name"] = "Dis Was Our Land", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5722, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 2395 },
[86711] = { ["id"] = 86711, ["name"] = "Amani Clarion Call", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2536, ["storyline"] = { 86652, 86708, 86710, 86711, 86712, 86715, 86716, 86717, 86718, 86719, 86720, 86721, 86722, 86723, 86868, 90749 }, ["description"] = "If you want to survive here in Atal'Aman, find and beat de city's battle drums. Dat will rally our remainin' soldiers forward to join de fight. It will also bring all de tribes of Zul'Aman --de Witherbark, de Revantusk, and de Shadowpine--to our aid and tell our civilians to retreat to de Altar of Malacrass if we need to evacuate. Use the drums to spread de word. Find me at de Altar of Malacrass when you are done.", ["objectivesText"] = "Sound the Amani War Drums in Atal'Aman.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 264334 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2536, ["npcID"] = 236468, ["x"] = 0.055, ["y"] = 0.475 } }, ["ends"] = { { ["mapID"] = 2536, ["npcID"] = 236559, ["x"] = 0.461, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 2536, ["source"] = "quest_giver", ["x"] = 0.055, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 2536 }, ["zone"] = { 16194 } }, ["questType"] = "standard", ["sourceQuests"] = { 90749 }, ["questLines"] = { { ["id"] = 5722, ["name"] = "Dis Was Our Land", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5722, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 2437 },
[86712] = { ["id"] = 86712, ["name"] = "The Amani Stand Strong", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2536, ["storyline"] = { 86652, 86708, 86710, 86711, 86712, 86715, 86716, 86717, 86718, 86719, 86720, 86721, 86722, 86723, 86868, 90749 }, ["description"] = "Zul'jarra doesn't think de lightwood is worth de risks I am taking. We will prove her wrong. I have seen too many warriors discouraged because their weapons don't work against de Twilight's Blade. Don't just tell them to retreat. Give them de lightwood weapons . Nothing stirs Amani blood like an effective axe in their hands. Let dem fight their way back to de Altar of Malacrass.", ["objectivesText"] = "Give 8 Lightwood Weapons to Demoralized Defenders .", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 237501, 264257 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2536, ["npcID"] = 236540, ["x"] = 0.225, ["y"] = 0.7955 } }, ["ends"] = { { ["mapID"] = 2536, ["npcID"] = 236588, ["x"] = 0.488, ["y"] = 0.465 } }, ["coords"] = { ["mapID"] = 2536, ["source"] = "quest_giver", ["x"] = 0.225, ["y"] = 0.7955 }, ["mapCandidates"] = { ["npc"] = { 2536 }, ["zone"] = { 16194 } }, ["questType"] = "standard", ["sourceQuests"] = { 86717, 86719 }, ["questLines"] = { { ["id"] = 5722, ["name"] = "Dis Was Our Land", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5722, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 2437 },
[86715] = { ["id"] = 86715, ["name"] = "Rituals Cut Short", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2536, ["storyline"] = { 86652, 86708, 86710, 86711, 86712, 86715, 86716, 86717, 86718, 86719, 86720, 86721, 86722, 86723, 86868, 90749 }, ["description"] = "In our reconnaissance flight around the city, Zul'jarra and I got a look at the Twilight's offensive. They're summoning more Twilight's Blade directly into Atal'Aman. We can counter them by disrupting their dark summoning rituals. That will stop the flow of their cultists into the city and give the Amani time to strategize. Kill the ritualists, and any trollbreakers already portaled into the area.", ["objectivesText"] = "Destroy 6 Twilight Ritualists and 6 Twilight Trollbreakers in Firewing Terrace. Progress: We cannot allow the Twilight's Blade to bring even more troops into Atal'Aman.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2536, ["npcID"] = 236542, ["x"] = 0.23, ["y"] = 0.795 } }, ["ends"] = { { ["mapID"] = 2536, ["npcID"] = 236586, ["x"] = 0.473333, ["y"] = 0.468 } }, ["coords"] = { ["mapID"] = 2536, ["source"] = "quest_giver", ["x"] = 0.23, ["y"] = 0.795 }, ["mapCandidates"] = { ["npc"] = { 2536 }, ["zone"] = { 16194 } }, ["questType"] = "standard", ["sourceQuests"] = { 86716, 86721 }, ["questLines"] = { { ["id"] = 5722, ["name"] = "Dis Was Our Land", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5722, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 2437 },
[86716] = { ["id"] = 86716, ["name"] = "Armed by Light", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2536, ["storyline"] = { 86652, 86708, 86710, 86711, 86712, 86715, 86716, 86717, 86718, 86719, 86720, 86721, 86722, 86723, 86868, 90749 }, ["description"] = "You might be good at killing, <class>, but so are we Amani. And even more de better our weapons! I took an army into Eversong to reclaim de lightwood forests for de Amani. It was against my sister's orders, yes, but lightwood gives us an advantage. Take back de weapons being stolen by the de Twilight's Blade, and I'll show you why it was worth de effort.", ["objectivesText"] = "Recover 8 stolen Lightwood Weapons . Progress: These weapons are the difference between my people living or dying.", ["rewardGold"] = 309800, ["rewardXP"] = 12170, ["rewardItems"] = { 237767, 248555, 248556, 248557, 248558, 248559, 248560, 248561, 248562 }, ["rewardChoices"] = { 248555, 248556, 248557, 248558, 248559, 248560, 248561, 248562 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2536, ["npcID"] = 236522, ["x"] = 0.1655, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 2536, ["npcID"] = 236540, ["x"] = 0.225, ["y"] = 0.7955 } }, ["coords"] = { ["mapID"] = 2536, ["source"] = "quest_giver", ["x"] = 0.1655, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 2536 }, ["zone"] = { 16194 } }, ["questType"] = "standard", ["sourceQuests"] = { 86717, 86719 }, ["questLines"] = { { ["id"] = 5722, ["name"] = "Dis Was Our Land", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5722, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 2536 },
[86717] = { ["id"] = 86717, ["name"] = "Show Us Your Worth", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2536, ["storyline"] = { 86652, 86708, 86710, 86711, 86712, 86715, 86716, 86717, 86718, 86719, 86720, 86721, 86722, 86723, 86868, 90749 }, ["description"] = "De Twilight's Blade's general, Mor'duun, has got us by de throat. We're not winnin', and we are too few. We've got to evacuate before there's no one left--and hope de other tribes meet us at Amani'Zar. In de meantime, I'm glad to use you while we rally de people of Zul'Aman . De civilians' lives are my priority. Go to Swiftclaw Terrace and evacuate de people there. Tear through de Twilight's Blade as you go. Find your way to Zul'jan when you're done.", ["objectivesText"] = "Rescue Amani civilians and destroy the Twilight's Blade presence at Swiftclaw Terrace in Atal'Aman. Progress: Separate their limbs from their bodies. Tear down their banners and shelters too!", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2536, ["npcID"] = 236559, ["x"] = 0.461, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 2536, ["npcID"] = 236522, ["x"] = 0.1655, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 2536, ["source"] = "quest_giver", ["x"] = 0.461, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 2536 }, ["zone"] = { 16194 } }, ["questType"] = "standard", ["sourceQuests"] = { 86711, 86868 }, ["questLines"] = { { ["id"] = 5722, ["name"] = "Dis Was Our Land", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5722, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 2536 },
[86718] = { ["id"] = 86718, ["name"] = "Twilight Bled", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2536, ["storyline"] = { 86652, 86708, 86710, 86711, 86712, 86715, 86716, 86717, 86718, 86719, 86720, 86721, 86722, 86723, 86868, 90749 }, ["description"] = "Mor'duun may be de leader of de Twilight's Blade in Zul'Aman , but dat ogre can't be everywhere. De elf found his military commander--a hulkin' pile of armor and flesh named Benvis Bladesplatter. He's paradin' 'round like he's already won just because dey seized Firewing Terrace. Make him pay for his arrogance.", ["objectivesText"] = "Kill Benvis Bladesplatter at Firewing Terrace. Progress: Have you ended him yet?", ["rewardGold"] = 309800, ["rewardXP"] = 12170, ["rewardItems"] = { 260468, 260469, 260470, 260471 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2536, ["npcID"] = 236541, ["x"] = 0.226667, ["y"] = 0.795333 } }, ["ends"] = { { ["mapID"] = 2536, ["npcID"] = 236587, ["x"] = 0.475, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 2536, ["source"] = "quest_giver", ["x"] = 0.226667, ["y"] = 0.795333 }, ["mapCandidates"] = { ["npc"] = { 2536 }, ["zone"] = { 16194 } }, ["questType"] = "standard", ["sourceQuests"] = { 86716, 86721 }, ["questLines"] = { { ["id"] = 5722, ["name"] = "Dis Was Our Land", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5722, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 2437 },
[86719] = { ["id"] = 86719, ["name"] = "Important Amani", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2536, ["storyline"] = { 86652, 86708, 86710, 86711, 86712, 86715, 86716, 86717, 86718, 86719, 86720, 86721, 86722, 86723, 86868, 90749 }, ["description"] = "De drums have sounded. But de elders have not come. We cannot lose them. They are our link to our culture--our sages and our best minds. Torundo helped devise de lightwood weapons. And Doru is our provisioner. We will need both if de battle goes on. Go find Doru in de market and Torundo in de tribute hall. De last one is de old loa speaker--our uncle, Kinduru. He may need... special persuasion to leave. I will go to Talonstrike Terrace to speak to him. Meet me there after you find de others.", ["objectivesText"] = "Find the Amani elders: Torundo the Grizzled , Doru, and Kinduru. Progress: Do whatever is necessary to get Kinduru to leave. He's our uncle. We can't leave him here.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 237768 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2536, ["npcID"] = 236558, ["x"] = 0.461, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 2536, ["npcID"] = 236522, ["x"] = 0.1655, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 2536, ["source"] = "quest_giver", ["x"] = 0.461, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 2536 }, ["zone"] = { 16194 } }, ["questType"] = "standard", ["sourceQuests"] = { 86711, 86868 }, ["questLines"] = { { ["id"] = 5722, ["name"] = "Dis Was Our Land", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5722, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 2536 },
[86720] = { ["id"] = 86720, ["name"] = "Break the Blade", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2536, ["storyline"] = { 86652, 86708, 86710, 86711, 86712, 86715, 86716, 86717, 86718, 86719, 86720, 86721, 86722, 86723, 86868, 90749 }, ["description"] = "Zul'jan's ballista is ready. And it had better work after what he has done. We lost de army we needed to defend de city, but we can fend off Mor'duun long enough to let our people escape. Help my brother man de ballista. Focus on de shadow warders and de pylon. Liadrin and I will distract Mor'duun. I will kill him if I can, but even then we can't stay here. There's too much void energy. And too much destruction. Atal'Aman is truly lost.", ["objectivesText"] = "Use the Lightwood Ballista to destroy the Empowering Shadows and the Scrying Focus to bring down Mord'uun's barrier.", ["rewardGold"] = 957000, ["rewardXP"] = 18255, ["rewardItems"] = { 248563, 248564, 248565, 248566 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3354, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2536, ["npcID"] = 236587, ["x"] = 0.475, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 2536, ["npcID"] = 236601, ["x"] = 0.478, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 2536, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 2536 }, ["zone"] = { 16194 } }, ["questType"] = "standard", ["sourceQuests"] = { 86712, 86715, 86718 }, ["questLines"] = { { ["id"] = 5722, ["name"] = "Dis Was Our Land", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5722, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 2437 },
[86721] = { ["id"] = 86721, ["name"] = "Everything We Worked For", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2536, ["storyline"] = { 86652, 86708, 86710, 86711, 86712, 86715, 86716, 86717, 86718, 86719, 86720, 86721, 86722, 86723, 86868, 90749 }, ["description"] = "My blood is boiling! While waiting for Kinduru, de Twilight's Blade was destroying what little stores of lightwood we had left at Ragemaw Terrace! But if we act quickly, we can save enough to arm de lightwood ballista--and take a shot at Mor'duun. And without de ballista, we cannot claim victory!", ["objectivesText"] = "Extinguish fires on the Lightwood Piles at Ragemaw Terrace. Progress: Don't let de lightwood burn!", ["rewardGold"] = 309800, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2536, ["npcID"] = 236522, ["x"] = 0.1655, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 2536, ["npcID"] = 236540, ["x"] = 0.225, ["y"] = 0.7955 } }, ["coords"] = { ["mapID"] = 2536, ["source"] = "quest_giver", ["x"] = 0.1655, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 2536 }, ["zone"] = { 16194 } }, ["questType"] = "standard", ["sourceQuests"] = { 86717, 86719 }, ["questLines"] = { { ["id"] = 5722, ["name"] = "Dis Was Our Land", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5722, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 2437 },
[86722] = { ["id"] = 86722, ["name"] = "Heart of the Amani", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2536, ["storyline"] = { 86652, 86708, 86710, 86711, 86712, 86715, 86716, 86717, 86718, 86719, 86720, 86721, 86722, 86723, 86868, 90749 }, ["description"] = "You and your elf friend amuse me. And you've more than proved yourself in battle. Our people are headin' to Amani'Zar. We hope dat de other tribes rallied there instead of Atal'Aman. Their representatives will give us council, and then we will mount an attack on de Twilight's Blade. If you still wish to fight with de Amani, meet me on de northwest side of de village. Zul'jan will have gone ahead to speak of his deeds--and yours--but do not enter de village without me. Amani kill strangers on sight.", ["objectivesText"] = "Meet Zul'jarra at the entrance to Amani'Zar Village.", ["rewardGold"] = 162600, ["rewardXP"] = 6085, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2536, ["npcID"] = 236601, ["x"] = 0.478, ["y"] = 0.475 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 236602, ["x"] = 0.426, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 2536, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 2437, 2536 }, ["zone"] = { 16194 } }, ["questType"] = "standard", ["sourceQuests"] = { 86720 }, ["questLines"] = { { ["id"] = 5722, ["name"] = "Dis Was Our Land", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5722, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 2437 },
[86723] = { ["id"] = 86723, ["name"] = "Isolation", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86652, 86708, 86710, 86711, 86712, 86715, 86716, 86717, 86718, 86719, 86720, 86721, 86722, 86723, 86868, 90749 }, ["description"] = "We will speak to Torundo, my war advisor. And if de representatives of de tribes are here, we will have a council meetin' in de Zari Lodge. Together, we must agree on a way to defeat de Twilight's Blade. Explore de village if you want. But keep your weapons where dey can be seen. You are here by my invitation and my word is law, but I can only run so fast if one of my people thinks you looked at dem in de wrong way. < Zul'jarra smiles a tusky grin as if proud of her people's short fuse.>", ["objectivesText"] = "Meet Zul'jarra and Liadrin to assess the situation with the other troll tribes. Progress: I need de advise of my advisor, Torundo. And we must see why de other tribes did not heed de drums. Dey may think I am desperate to ask for your help. But dey also would dare not challenge me.", ["rewardGold"] = 159500, ["rewardXP"] = 6085, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 236602, ["x"] = 0.426, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 236659, ["x"] = 0.451333, ["y"] = 0.664667 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86722 }, ["questLines"] = { { ["id"] = 5722, ["name"] = "Dis Was Our Land", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5722, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 2437 },
[86728] = { ["id"] = 86728, ["name"] = "Operation: Floodgate: Disposing of the Garbage", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 86728 }, ["description"] = "Hey, pal. I've heard murmurs of a real piece of work trying to siphon off energy at the Waterworks in the Ringing Deeps. Stealing from our stone friends ain't good for business, and it certainly ain't something we're willing to let continue. I know you've made a name for yourself for disposing of the trash, and bad business folks are certainly as trashy as they come. Do me a favor, will ya? Weapons are optional, but attitude is required... if you catch my drift.", ["objectivesText"] = "Defeat Geezle Gigazap in Operation: Floodgate. Progress: Yo, you take care of that \"thing\" for me?", ["rewardGold"] = 1239200, ["rewardXP"] = 23530, ["rewardCurrencies"] = { { ["id"] = 3118, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231045, ["x"] = 0.434, ["y"] = 0.514667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231045, ["x"] = 0.434, ["y"] = 0.514667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.514667 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346, ["db2QuestHubAreaPoiID"] = 8189, ["db2QuestInfoID"] = 81, ["db2QuestInfoName"] = "Dungeon" },
[86731] = { ["id"] = 86731, ["name"] = "An Original Path Through Time", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 86731 }, ["description"] = "Ever since your city fell out of the sky, I have learned more of this world's history and the challenges that heroes like yourself have faced. Learning from the past is how we ensure our future. Walk through time to the humble beginnings, defeat those threats once more, and bring those lessons forward.", ["objectivesText"] = "Complete 5 Timewalking dungeons.", ["rewardItems"] = { 212446, 220305, 226194, 233014 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard" },
[86733] = { ["id"] = 86733, ["name"] = "Silvermoon Negotiations", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2424, ["storyline"] = { 86733, 86734, 86735, 86736, 86737 }, ["description"] = "It would be an understatement to say things between Silvermoon and the Alliance are often tense and uneasy. I thank you for setting aside any prejudices you might have had and lending your strength to the defense of Silvermoon and the Sunwell. We have Xal'atath's forces held for now, but this is far from over. I would include you in our next steps. Meet me at the Sanctum of Light .", ["objectivesText"] = "Journey to Silvermoon City.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 248075, 248076 }, ["rewardChoices"] = { 248075, 248063, 248067, 248070 }, ["starts"] = { { ["mapID"] = 2424, ["npcID"] = 236779, ["x"] = 0.525, ["y"] = 0.882 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2424, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.882 }, ["mapCandidates"] = { ["npc"] = { 2393, 2424 }, ["zone"] = { 16215 } }, ["questType"] = "standard", ["sourceQuests"] = { 86852 }, ["questLines"] = { { ["id"] = 5719, ["name"] = "Whispers in the Twilight", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6130, ["name"] = "Eversong Intro", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5719, ["questLineOrder"] = 1 }, { ["id"] = 336, ["title"] = "Eversong Intro Skip", ["questLineID"] = 6130, ["questLineOrder"] = 0 }, { ["id"] = 335, ["title"] = "Midnight Expansion Intro Skip", ["questLineID"] = 6130, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 2393 },
[86734] = { ["id"] = 86734, ["name"] = "Diplomacy", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 86733, 86734, 86735, 86736, 86737 }, ["description"] = "We shall all weigh in on the situation. <Lor'themar glances at Umbric and Rommath.> As you can see, there are many tensions at play. Please give us a moment to discuss.", ["objectivesText"] = "Listen to the discussion. Progress: We have much to discuss.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 53265, 53267, 53292, 131398 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 86733 }, ["questLines"] = { { ["id"] = 5719, ["name"] = "Whispers in the Twilight", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6130, ["name"] = "Eversong Intro", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5719, ["questLineOrder"] = 1 }, { ["id"] = 336, ["title"] = "Eversong Intro Skip", ["questLineID"] = 6130, ["questLineOrder"] = 0 }, { ["id"] = 335, ["title"] = "Midnight Expansion Intro Skip", ["questLineID"] = 6130, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 2393 },
[86735] = { ["id"] = 86735, ["name"] = "Paved in Ash", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 86733, 86734, 86735, 86737 }, ["description"] = "Now that the matter is settled, you should acquaint yourself with Silvermoon. There are a few key civilians I'd like informed about your presence here--you should check in with them. Show them my signet ring--they'll know you've my permission to be here. But please take care where you go, and stay in the outer city to avoid any issues.", ["objectivesText"] = "Show Lor'themar's Signet around the city. Progress: Have you spoken to everyone yet?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 248042, 248043, 248044, 248045, 250352, 263231 }, ["rewardCurrencies"] = { { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 86734 }, ["questLines"] = { { ["id"] = 5719, ["name"] = "Whispers in the Twilight", ["orderIndex"] = 2, ["flags"] = 1 }, { ["id"] = 6130, ["name"] = "Eversong Intro", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5719, ["questLineOrder"] = 1 }, { ["id"] = 336, ["title"] = "Eversong Intro Skip", ["questLineID"] = 6130, ["questLineOrder"] = 0 }, { ["id"] = 335, ["title"] = "Midnight Expansion Intro Skip", ["questLineID"] = 6130, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 2393 },
[86736] = { ["id"] = 86736, ["name"] = "Paved in Ash", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 86733, 86734, 86736, 86737 }, ["description"] = "I've more to review with Turalyon, but in the meantime, the rest of the city should be informed that we will have some temporary guests in the outer perimeter. I'd like you to check in with a few key civilians and deliver the news. While you're out there, take the chance to familiarize yourself with Silvermoon. We've made impressive strides rebuilding it since you've last visited.", ["objectivesText"] = "Check in with civilians around the city. Progress: Have you met with everyone?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 248042, 248043, 248044, 248045, 250352, 263231 }, ["rewardCurrencies"] = { { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 86734 }, ["questLines"] = { { ["id"] = 5719, ["name"] = "Whispers in the Twilight", ["orderIndex"] = 3, ["flags"] = 1 }, { ["id"] = 6130, ["name"] = "Eversong Intro", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5719, ["questLineOrder"] = 1 }, { ["id"] = 336, ["title"] = "Eversong Intro Skip", ["questLineID"] = 6130, ["questLineOrder"] = 0 }, { ["id"] = 335, ["title"] = "Midnight Expansion Intro Skip", ["questLineID"] = 6130, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 2393 },
[86737] = { ["id"] = 86737, ["name"] = "Fair Breeze, Light Bloom", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 86733, 86734, 86735, 86736, 86737 }, ["series"] = { 86738 }, ["description"] = "In recent years, small pockets of wild growth we call \"Lightbloom\" have blossomed throughout Eversong. A curiosity for our local botanists, for the most part. However, the Magistrix in Fairbreeze is asking for help with the local Lightbloom. Every capable hand I have is focused on holding back the Voidstorm--but if the Magistrix cannot handle the matter herself, it requires swift attention. I'd like you to see to the issue. Magister Rommath can provide you with an arcane projector to keep in touch.", ["objectivesText"] = "Journey to Fairbreeze Village.", ["rewardGold"] = 31900, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236739, ["x"] = 0.466, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 2393, 2395 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 86735 }, ["questLines"] = { { ["id"] = 5719, ["name"] = "Whispers in the Twilight", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 6130, ["name"] = "Eversong Intro", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5719, ["questLineOrder"] = 1 }, { ["id"] = 336, ["title"] = "Eversong Intro Skip", ["questLineID"] = 6130, ["questLineOrder"] = 0 }, { ["id"] = 335, ["title"] = "Midnight Expansion Intro Skip", ["questLineID"] = 6130, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 2395 },
[86738] = { ["id"] = 86738, ["name"] = "Sharpmaw", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86733, 86734, 86735, 86736, 86737, 86738, 86739, 86740, 86741, 86742, 86743, 86744, 86745, 94871, 94993, 95008 }, ["series"] = { 86737 }, ["description"] = "These beasts roaming the village are nuisances, but we have a bigger problem. There's a feral lynx prowling nearby that we call Sharpmaw . She used to keep her distance from the village, but the current situation has made her more bold. We've plenty of little ones around here, and more than once the guards have caught that beast eyeing them like they were a snack waiting to be snatched. Stop her before she starts attacking my people in earnest!", ["objectivesText"] = "Slay Sharpmaw .", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 248023, 248024, 248025, 248026 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236739, ["x"] = 0.466, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236739, ["x"] = 0.466, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86737 }, ["questLines"] = { { ["id"] = 5719, ["name"] = "Whispers in the Twilight", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5719, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 2395 },
[86739] = { ["id"] = 86739, ["name"] = "Fairbreeze Favors", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86733, 86734, 86735, 86736, 86737, 86738, 86739, 86740, 86741, 86742, 86743, 86744, 86745, 94871, 94993, 95008 }, ["description"] = "This is the oddest situation I've ever been in--our village is being overrun! I like to keep things neat and tidy around here, but these animals... they've come in from the wilds like they own the town. They're attacking our sweet pets, overturning our belongings, and causing havoc. No sooner have I solved one problem than another is rearing its head. I'm only one elf--I can't stop all of this on my own! Lend a hand, won't you? This... elf... troll... person hasn't lifted a finger.", ["objectivesText"] = "Help restore order in Fairbreeze Village. Progress: The sooner the village is returned to peace, the sooner I can breathe.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 264248 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236739, ["x"] = 0.466, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236739, ["x"] = 0.466, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86737 }, ["questLines"] = { { ["id"] = 5719, ["name"] = "Whispers in the Twilight", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5719, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 2395 },
[86740] = { ["id"] = 86740, ["name"] = "Displaced Denizens", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86733, 86734, 86735, 86736, 86737, 86738, 86739, 86740, 86741, 86742, 86743, 86744, 86745, 94871, 94993, 95008 }, ["description"] = "The wildlife here seems to have been upset by something. Perhaps this is why the world's song bade me here: to discover why and correct it. Study the displaced wildlife. Bring me your findings. If there is anything unusual, I wish to know of it. I will speak with the Magistrix. Perhaps together we can uncover this mystery.", ["objectivesText"] = "Study 3 disturbances caused by displaced wildlife and 3 unusual plants in Fairbreeze Village. Progress: Perhaps we can solve this problem together.", ["rewardGold"] = 312800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236743, ["x"] = 0.466, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236743, ["x"] = 0.466, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86737 }, ["questLines"] = { { ["id"] = 5719, ["name"] = "Whispers in the Twilight", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5719, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 2395 },
[86741] = { ["id"] = 86741, ["name"] = "Lightbloom Looming", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86733, 86734, 86735, 86736, 86737, 86738, 86739, 86740, 86741, 86742, 86743, 86744, 86745, 94871, 94993, 95008 }, ["description"] = "The wildlife seems to have been displaced from the south. It is there we will surely find answers. Come--I will use my magic to illuminate the path and we will follow the trail.", ["objectivesText"] = "Follow the trail of the displaced wildlife.", ["rewardGold"] = 319000, ["rewardXP"] = 11765, ["rewardItems"] = { 245992, 248018, 248054, 248055, 248056 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236743, ["x"] = 0.466, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236903, ["x"] = 0.4305, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86738, 86739, 86740 }, ["questLines"] = { { ["id"] = 5719, ["name"] = "Whispers in the Twilight", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5719, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 2395 },
[86742] = { ["id"] = 86742, ["name"] = "Curious Cultivation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86733, 86734, 86735, 86736, 86737, 86738, 86739, 86740, 86741, 86742, 86743, 86744, 86745, 94871, 94993, 95008 }, ["description"] = "This place is unlike anything I have seen before. The plant growth is unique. $p, let us examine the Lightbloom more closely. Perhaps we can uncover the secrets of this place together.", ["objectivesText"] = "Examine 3 Lightbloom Plant Growths in Lightbloom Ath'Ran. Progress: This makes no sense.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 248047, 248048, 253386 }, ["rewardChoices"] = { 248047, 248048 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236903, ["x"] = 0.4305, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236903, ["x"] = 0.4305, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.4305, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86741 }, ["questLines"] = { { ["id"] = 5719, ["name"] = "Whispers in the Twilight", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5719, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 2395 },
[86743] = { ["id"] = 86743, ["name"] = "Trimming the Lightbloom", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86733, 86734, 86735, 86736, 86737, 86738, 86739, 86740, 86741, 86742, 86743, 86744, 86745, 94871, 94993, 95008 }, ["description"] = "The creatures of this Lightbloom see us as the intruders. They threaten the surrounding wildlife and inhabitants who are naturally here. We should reduce their numbers and end this threat.", ["objectivesText"] = "Kill Lightbloom creatures in Lightbloom Ath'ran. Progress: These creatures are so odd... as if they are driven.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236903, ["x"] = 0.4305, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236903, ["x"] = 0.4305, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.4305, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86741 }, ["questLines"] = { { ["id"] = 5719, ["name"] = "Whispers in the Twilight", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5719, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 2395 },
[86744] = { ["id"] = 86744, ["name"] = "Seeking Truth", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86733, 86734, 86735, 86736, 86737, 86738, 86739, 86740, 86741, 86742, 86743, 86744, 86745, 94871, 94993, 95008 }, ["description"] = "I will channel on this strange seed we have collected, and see if I can discover what has happened here. This may upset the rutaani. Make sure I am not interrupted. This is why I was called here--I know now. But I must discover what needs to be done.", ["objectivesText"] = "Defend Orweyna . Progress: Ah... perhaps we have some answers.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 248038, 248039, 248040, 248041 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3365, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236903, ["x"] = 0.4305, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236903, ["x"] = 0.4305, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.4305, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86742, 86743 }, ["questLines"] = { { ["id"] = 5719, ["name"] = "Whispers in the Twilight", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5719, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 2395 },
[86745] = { ["id"] = 86745, ["name"] = "Silvermoon Must Know", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86733, 86734, 86735, 86736, 86737, 86738, 86739, 86740, 86741, 86742, 86743, 86744, 86745, 94871, 94993, 95008 }, ["description"] = "This growth--Lor'themar needs to know about this. I worry what will happen should it get out of control. And the Light's influence... my father should know, too.", ["objectivesText"] = "Contact Silvermoon. Progress: We must contact Silvermoon to give them an update.", ["rewardGold"] = 319000, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236716, ["x"] = 0.472, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236716, ["x"] = 0.472, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86744 }, ["questLines"] = { { ["id"] = 5719, ["name"] = "Whispers in the Twilight", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5719, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 2395 },
[86769] = { ["id"] = 86769, ["name"] = "Last Bastion of the Light", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16182, ["mapID"] = 2432, ["storyline"] = { 86769, 86770, 86780, 86805, 86806, 86807, 86811, 86834, 86848, 86849, 86850, 86852, 88719, 89012, 89271, 91274, 91281 }, ["series"] = { 86770, 88719, 91281 }, ["description"] = "Your arrival has reignited hope. We have pushed Xal'atath's forces away from the Sunwell, yet they still infest the Isle of Quel'Danas , and appear to be massing for another attack as they prey upon the sin'dorei. We must join up with the Vanguard of Light.", ["objectivesText"] = "Follow Lady Liadrin to Parhelion Plaza.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 239151 }, ["starts"] = { { ["mapID"] = 2432, ["npcID"] = 236692, ["x"] = 0.485333, ["y"] = 0.384667 } }, ["ends"] = { { ["mapID"] = 2432, ["npcID"] = 236693, ["x"] = 0.476667, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 2432, ["source"] = "quest_giver", ["x"] = 0.485333, ["y"] = 0.384667 }, ["mapCandidates"] = { ["npc"] = { 2432 }, ["zone"] = { 16182 } }, ["questType"] = "standard", ["sourceQuests"] = { 88719 }, ["questLines"] = { { ["id"] = 5811, ["name"] = "The Light's Summons", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 335, ["title"] = "Midnight Expansion Intro Skip", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 352, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2858, ["db2PoiUiMapID"] = 2432 },
[86770] = { ["id"] = 86770, ["name"] = "Champions of Quel'Danas", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16182, ["mapID"] = 2432, ["storyline"] = { 86769, 86770, 86780, 86805, 86806, 86807, 86811, 86834, 86848, 86849, 86850, 86852, 88719, 89012, 89271, 91274, 91281 }, ["series"] = { 86769, 88719, 91281 }, ["description"] = "Lor'themar has formed a rally point at Sunstrider Rise, while the civilians there are evacuated to Silvermoon, but the forces of the Vanguard of Light are scattered throughout the battlefield. We need to fight as one to defeat this host. Together, we can defeat Xal'atath and save the Sunwell.", ["objectivesText"] = "Rally Faerin Lothar , Lothraxion , and Alonsus Faol at Light's Spire. Progress: You have gathered help?", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2432, ["npcID"] = 236693, ["x"] = 0.476667, ["y"] = 0.404 } }, ["ends"] = { { ["mapID"] = 2432, ["npcID"] = 236896, ["x"] = 0.355, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 2432, ["source"] = "quest_giver", ["x"] = 0.476667, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 2432 }, ["zone"] = { 16211 } }, ["questType"] = "standard", ["sourceQuests"] = { 86769 }, ["questLines"] = { { ["id"] = 5811, ["name"] = "The Light's Summons", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 335, ["title"] = "Midnight Expansion Intro Skip", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 352, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2858, ["db2PoiUiMapID"] = 2432 },
[86775] = { ["id"] = 86775, ["name"] = "Urge to Surge", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 85869, 85879, 86775 }, ["description"] = "Occasionally we get more jobs than we can handle. You know what that means-- big money. Help out during some Surge Pricing and we'll see to it that you're thanked for your help.", ["objectivesText"] = "Complete a Surge Pricing event at least once. Progress: Keep an ear out for when we call for help. Usually it happens within the hour.", ["rewardItems"] = { 212316, 234741, 236682, 236756, 236757, 236758, 238208, 250764 }, ["rewardCurrencies"] = { { ["id"] = 3118, ["amount"] = 1000 }, { ["id"] = 3169, ["amount"] = 2000 }, { ["id"] = 3171, ["amount"] = 2000 }, { ["id"] = 3173, ["amount"] = 2000 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231409, ["x"] = 0.436, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231409, ["x"] = 0.436, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5900, ["name"] = "Undermine Repeatables", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346, ["db2QuestHubAreaPoiID"] = 8189 },
[86780] = { ["id"] = 86780, ["name"] = "Where Heroes Hold", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16182, ["mapID"] = 2432, ["storyline"] = { 86769, 86770, 86780, 86805, 86806, 86807, 86811, 86834, 86848, 86849, 86850, 86852, 88719, 89012, 89271, 91274, 91281 }, ["description"] = "We have stopped the Devouring Host's initial attack. This battle will not be won if we go on the defensive, not even to safeguard the innocents of Quel'Danas. Focus on culling the Voidfront. Without their invading force, the Devouring Host cannot maintain a foothold! We will rally at Sunstrider Rise when ready.", ["objectivesText"] = "Hinder the Voidfront forces along the walls of Parhelion Plaza. Progress: Have you thwarted the enemy?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 251076, 251116 }, ["rewardChoices"] = { 251076, 251116 }, ["starts"] = { { ["mapID"] = 2432, ["npcID"] = 236906, ["x"] = 0.46, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 2432, ["npcID"] = 236954, ["x"] = 0.354, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2432, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 2432 }, ["zone"] = { 16182 } }, ["questType"] = "standard", ["sourceQuests"] = { 86769 }, ["questLines"] = { { ["id"] = 5811, ["name"] = "The Light's Summons", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 335, ["title"] = "Midnight Expansion Intro Skip", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 352, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2858, ["db2PoiUiMapID"] = 2565 },
[86781] = { ["id"] = 86781, ["name"] = "Face the Past", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86621, 86622, 86623, 86624, 86626, 86632, 86633, 86634, 86635, 86636, 86781, 90493, 90494, 90509, 90907 }, ["description"] = "<Umbric scans the Eversong map with grave intent.> Tranquillien was marked, as are a number of other locations. <Umbric stops, voice tightening.> Windrunner Village. It's marked. The Twilight's Blade retreated to their base in Deatholme, but my home may be in peril. We must make sure my people in Windrunner Village are safe before pursuing them.", ["objectivesText"] = "Regroup in Windrunner Village.", ["rewardGold"] = 31500, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 242143, ["x"] = 0.476, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236363, ["x"] = 0.37, ["y"] = 0.74 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 90494 }, ["questLines"] = { { ["id"] = 5720, ["name"] = "Shadowfall", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5720, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 2395 },
[86782] = { ["id"] = 86782, ["name"] = "Atrium Hospital", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86587, 86588, 86589, 86590, 86591, 86592, 86593, 86594, 86595, 86601, 86602, 86603, 86604, 86605, 86606, 86607, 86782, 86783 }, ["series"] = { 86588, 86589, 86590, 86591, 86592, 86593 }, ["description"] = "The necrorays have been installed in the Atrium, and Hemet is seeing to them. He has requested your presence.", ["objectivesText"] = "Meet Hemet Nesingwary in the Atrium.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 236846, ["x"] = 0.484, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86593 }, ["questLines"] = { { ["id"] = 5763, ["name"] = "Rays of Sunshine", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5763, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
