[86786] = { ["id"] = 86786, ["name"] = "The Void Hunter", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86786, 89323, 89324, 89325, 89326, 89327, 90972, 91044, 94933 }, ["description"] = "The Void espouses all truths, <name>. And in none of them do I defeat Ramon'ta without some help. And here you are. My quarry is a cosmic worm known as Ramon'ta the Insatiable . It started out small enough, but with each void entity it feasts upon, it grows, and its power grows along with it. If we can defeat it, I can claim its power. Will you help me?", ["objectivesText"] = "Help Leona defeat the empowered cosmic worm and claim its power. Progress: Wrap this up quickly, <class>. I have more important matters to attend to.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 239074 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 240842, ["x"] = 0.660667, ["y"] = 0.356667 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 236907, ["x"] = 0.6, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.660667, ["y"] = 0.356667 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 90972 }, ["questLines"] = { { ["id"] = 5770, ["name"] = "In Search of Darkness", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86800] = { ["id"] = 86800, ["name"] = "Swipe 'Em", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 84962, 85812, 85822, 85834, 85855, 85863, 85864, 86305, 86367, 86372, 86391, 86395, 86409, 86584, 86610, 86696, 86707, 86709, 86800, 86872 }, ["rewardXP"] = 11765, ["rewardItems"] = { 235413 }, ["starts"] = { { ["x"] = 0.538, ["y"] = 0.494, ["mapID"] = 2371 } }, ["ends"] = { { ["x"] = 0.538, ["y"] = 0.494, ["mapID"] = 2371 } }, ["coords"] = { ["mapID"] = 2371, ["x"] = 0.538, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15336 } }, ["questType"] = "world", ["questLines"] = { { ["id"] = 5737, ["name"] = "K'aresh - World Quests/Repeatables", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 1, ["amount"] = 40, ["objectID"] = 235413 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[86801] = { ["id"] = 86801, ["name"] = "Faceless Mask of Multitudes", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["storyline"] = { 86801 }, ["description"] = "By our multitudes will the world drown and feed the hunger of our gods. Only by bathing in the blood of our foes may one rise to the exaltation of our masters and unleash their never ending multitudes for themself.", ["objectivesText"] = "Return the Faceless Mask of Multitudes to the altar within a Horrific Vision. Progress: Place the Faceless Mask of Multitudes on the altar.", ["rewardItems"] = { 235414 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 235414 } },
[86805] = { ["id"] = 86805, ["name"] = "The Hour of Need", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16182, ["mapID"] = 2432, ["storyline"] = { 86769, 86770, 86780, 86805, 86806, 86807, 86811, 86834, 86848, 86849, 86850, 86852, 88719, 89012, 89271, 91274, 91281 }, ["series"] = { 86806, 89012 }, ["description"] = "Turalyon is thinking like a battlefield captain and not like a leader! My people, the sin'dorei, have suffered much in these past few wars. How many must die in the name of his victory? Please, <name>. Rescue any citizens you can and help guide them safely to the boats at the Silver Landing. Every life saved is a victory for the blood elves.", ["objectivesText"] = "Rescue $10oa citizens, then head to the Silver Landing. Progress: The ships still have space for more! Rescue as many as you can.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 248239, 268326, 268327 }, ["rewardChoices"] = { 268326, 268327 }, ["starts"] = { { ["mapID"] = 2432, ["npcID"] = 236896, ["x"] = 0.355, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 2432, ["npcID"] = 236961, ["x"] = 0.412, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 2432, ["source"] = "quest_giver", ["x"] = 0.355, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 2432 }, ["zone"] = { 16182 } }, ["questType"] = "standard", ["sourceQuests"] = { 86770, 86780, 89271 }, ["questLines"] = { { ["id"] = 5811, ["name"] = "The Light's Summons", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 335, ["title"] = "Midnight Expansion Intro Skip", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 352, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2858, ["db2PoiUiMapID"] = 2432 },
[86806] = { ["id"] = 86806, ["name"] = "Luminous Wings", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16182, ["mapID"] = 2432, ["storyline"] = { 86769, 86770, 86780, 86805, 86806, 86807, 86811, 86834, 86848, 86849, 86850, 86852, 88719, 89012, 89271, 91274, 91281 }, ["series"] = { 86805, 89012 }, ["description"] = "No! Xal'atath's Host has opened portals above the strait. Void creatures spill out and descend upon the refugee's ships. We have to safeguard the civilians! Those dragonhawks have been empowered by the Light. They should give you enough power to defeat the Void beasts and rescue the fleeing civilians.", ["objectivesText"] = "Take flight on the Empowered Dragonhawk , destroy 16 Devouring Host, and rescue 3 civilians in need. Progress: The ships full of sin'dorei refugees are still in danger.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2432, ["npcID"] = 236961, ["x"] = 0.412, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 2432, ["npcID"] = 236961, ["x"] = 0.412, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 2432, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 2432 }, ["zone"] = { 16182 } }, ["questType"] = "standard", ["sourceQuests"] = { 86805, 89012 }, ["questLines"] = { { ["id"] = 5811, ["name"] = "The Light's Summons", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 335, ["title"] = "Midnight Expansion Intro Skip", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 352, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2858, ["db2PoiUiMapID"] = 2432 },
[86807] = { ["id"] = 86807, ["name"] = "The Gate", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16182, ["mapID"] = 2432, ["storyline"] = { 86769, 86770, 86780, 86805, 86806, 86807, 86811, 86834, 86848, 86849, 86850, 86852, 88719, 89012, 89271, 91274, 91281 }, ["description"] = "The High Exarch commanded us to assemble with his Vanguard of Light and attack the Devouring Host. I do not regret my delay of that order, but he will have noticed my absence. We should make haste and assemble with the others.", ["objectivesText"] = "Assemble with the Vanguard of Light. Progress: We shouldn't delay any longer.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2432, ["npcID"] = 243091, ["x"] = 0.412, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 2565, ["npcID"] = 236974, ["x"] = 0.491667, ["y"] = 0.225333 } }, ["coords"] = { ["mapID"] = 2432, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 2432, 2565 }, ["zone"] = { 16182 } }, ["questType"] = "standard", ["sourceQuests"] = { 86806 }, ["questLines"] = { { ["id"] = 5811, ["name"] = "The Light's Summons", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 335, ["title"] = "Midnight Expansion Intro Skip", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 352, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2858, ["db2PoiUiMapID"] = 2565 },
[86808] = { ["id"] = 86808, ["name"] = "The Riddled Speaker", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86653, 86654, 86655, 86656, 86657, 86658, 86659, 86660, 86661, 86663, 86664, 86665, 86666, 86808, 86809, 89334, 90772, 92084 }, ["description"] = "Chief Vun'zarah knew little of Jan'alai, but he did know about their loa speaker. If dey are still at de temple, then there is hope we can resurrect de loa. < Zul'jarra 's hand tightens on her axe.> Makin' Akil'zon flee, woundin' Halazzi, sendin' Nalorakk into a rage, and killin' Jan'alai... My grandfather and Malacrass have so much to pay for.", ["objectivesText"] = "Meet Zul'jarra and Liadrin at the Temple of Jan'alai.", ["rewardGold"] = 32200, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3354, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 244592, ["x"] = 0.384667, ["y"] = 0.224667 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 236162, ["x"] = 0.55, ["y"] = 0.184 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.384667, ["y"] = 0.224667 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86661 }, ["questLines"] = { { ["id"] = 5723, ["name"] = "Path of de Hash'ey", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5723, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 2437 },
[86809] = { ["id"] = 86809, ["name"] = "Test of Conviction", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86653, 86654, 86655, 86656, 86657, 86658, 86659, 86660, 86661, 86663, 86664, 86665, 86666, 86808, 86809, 89334, 90772, 92084 }, ["description"] = "We got her attention. But now what? I know there is a trial. But Akil'zon is not givin' any hints on what it is. Think. Think. What did Kinduru teach me as a child? She is de loa of victory. But also of oaths and conviction. If only we had made it to de top when I was a child, and I hadn't fallen...", ["objectivesText"] = "Prove yourself to Akil'zon with Zul'jarra .", ["rewardGold"] = 164200, ["rewardXP"] = 6085, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 244422, ["x"] = 0.524, ["y"] = 0.81 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 236141, ["x"] = 0.522, ["y"] = 0.81 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.524, ["y"] = 0.81 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86656 }, ["questLines"] = { { ["id"] = 5723, ["name"] = "Path of de Hash'ey", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5723, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 2437 },
[86810] = { ["id"] = 86810, ["name"] = "Harvesting the Void", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86810 }, ["description"] = "To effectively counteract the void anomalies present here, we must obtain viable samples of the anomalies. Search the area for containment vessels that hold developing anomalies, as well as the Unstable Oozelings created from the contamination. Use the collection device to make this process easier. Only living Oozelings will provide viable samples.", ["objectivesText"] = "Collect 20 Anomaly Samples. Progress: Have you collected the necessary samples?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 246951 }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 248114, ["x"] = 0.265333, ["y"] = 0.676667 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 248114, ["x"] = 0.265333, ["y"] = 0.676667 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.265333, ["y"] = 0.676667 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[86811] = { ["id"] = 86811, ["name"] = "Ethereal Eradication", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16182, ["mapID"] = 2432, ["storyline"] = { 86769, 86770, 86780, 86805, 86806, 86807, 86811, 86834, 86848, 86849, 86850, 86852, 88719, 89012, 89271, 91274, 91281 }, ["series"] = { 86834 }, ["description"] = "<name>! I have a mission for you. There is a contingent of Shadowguard ethereals to the northeast. They appear to be looting the buildings, but that could change in a moment. The Vanguard cannot afford to be flanked as we advance. Take out their leader and decimate their forces while we engage the Host.", ["objectivesText"] = "Eliminate Norkonahl the Looter and 12 Shadowguard intruders. Progress: Have you completed the mission?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 30311, 30313, 30316, 30317, 30318, 128820, 145283, 238807, 238842, 238843, 238844, 238845, 238846, 238890 }, ["starts"] = { { ["mapID"] = 2432, ["npcID"] = 236978, ["x"] = 0.454, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 2432, ["npcID"] = 236978, ["x"] = 0.454, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 2432, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 2432 }, ["zone"] = { 16182 } }, ["questType"] = "standard", ["sourceQuests"] = { 86834, 91274 }, ["questLines"] = { { ["id"] = 5811, ["name"] = "The Light's Summons", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 335, ["title"] = "Midnight Expansion Intro Skip", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 352, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2858, ["db2PoiUiMapID"] = 2432 },
[86820] = { ["id"] = 86820, ["name"] = "Manaforge Omega: Dimensius Looms", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16178, ["mapID"] = 2371, ["storyline"] = { 83126, 83127, 83128, 83129, 84856, 84857, 84862, 84863, 84864, 84865, 84866, 84967, 85037, 85449, 85450, 86495, 86820, 86946, 90517, 91871, 93979 }, ["description"] = "This is it, $p. We must defeat this Void Lord... no matter what it takes.", ["objectivesText"] = "Defeat Dimensius in the Manaforge Omega raid.", ["rewardGold"] = 18588000, ["rewardXP"] = 23530, ["rewardItems"] = { 231769, 260582 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231522, ["x"] = 0.428, ["y"] = 0.215 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231522, ["x"] = 0.428, ["y"] = 0.215 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.215 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questTurnInID"] = 231522, ["questType"] = "raid", ["sourceQuests"] = { 85037 }, ["questLines"] = { { ["id"] = 5734, ["name"] = "The Light of K'aresh", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 20, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5734, ["questLineOrder"] = 5 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5734, ["questLineOrder"] = 5 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2810, ["db2PoiUiMapID"] = 2470 },
[86821] = { ["id"] = 86821, ["name"] = "Phase Diving: Unmoored and Unwell", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86821 }, ["objectivesText"] = "Enter Phase Diving Unmoored Phased Diver stabilized", ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.788, ["y"] = 0.324, ["mapID"] = 2371 } }, ["ends"] = { { ["x"] = 0.788, ["y"] = 0.324, ["mapID"] = 2371 } }, ["coords"] = { ["mapID"] = 2371, ["x"] = 0.788, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15336 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Enter Phase Diving", ["amount"] = 1, ["type"] = 0, ["objectID"] = 238335, ["orderIndex"] = 0 }, { ["text"] = "Unmoored Phased Diver stabilized", ["amount"] = 8, ["type"] = 0, ["objectID"] = 237208, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[86822] = { ["id"] = 86822, ["name"] = "One Final Relic", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15716, ["mapID"] = 14, ["storyline"] = { 86822, 86823, 86824, 86825, 86826, 86827, 86828, 86829, 86830, 86831, 86832, 86833, 86903, 91391, 91726, 91787, 91842 }, ["description"] = "$p, I've asked the Sons of Lothar to meet us in the Burning Steppes near Blackrock Mountain. There's one more item we must recover there. We can depart as soon as you are ready.", ["objectivesText"] = "Travel to the Burning Steppes and meet with the Sons of Lothar. Progress: Good trip?", ["rewardGold"] = 30900, ["rewardXP"] = 1520, ["rewardItems"] = { 44689 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 240747, ["x"] = 0.6885, ["y"] = 0.3385 } }, ["ends"] = { { ["mapID"] = 36, ["npcID"] = 242120, ["x"] = 0.3228, ["y"] = 0.4192 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.6885, ["y"] = 0.3385 }, ["mapCandidates"] = { ["npc"] = { 14, 36 }, ["zone"] = { 45 } }, ["questType"] = "standard", ["sourceQuests"] = { 89338 }, ["questLines"] = { { ["id"] = 5751, ["name"] = "Regrets of the Past", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5751, ["questLineOrder"] = 12 } }, ["db2PoiUiMapID"] = 36 },
[86823] = { ["id"] = 86823, ["name"] = "The Dark Horde", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 46, ["mapID"] = 36, ["storyline"] = { 86822, 86823, 86824, 86825, 86826, 86827, 86828, 86829, 86830, 86831, 86832, 86833, 86903, 91391, 91726, 91787, 91842 }, ["description"] = "I once served under Blackhand, long ago. His son Rend was a sniveling fool: a coward who bolstered himself in that Spire after Doomhammer was defeated. He made deals with dragons, called himself Warchief, and proclaimed his Dark Horde the \"true\" Horde. Pah! This Dark Horde embraces the ideals of a past long gone. Rend died years ago, but there are still orcs and ogres here who cling to the rotting husk that remains. If they haven't seen the truth by now, there is little hope for them but death.", ["objectivesText"] = "Kill 12 soldiers of the Dark Horde.", ["rewardGold"] = 309800, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 36, ["npcID"] = 237224, ["x"] = 0.335, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 36, ["npcID"] = 237224, ["x"] = 0.335, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 36, ["source"] = "quest_giver", ["x"] = 0.335, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 36 }, ["zone"] = { 46 } }, ["questType"] = "standard", ["sourceQuests"] = { 86822 }, ["questLines"] = { { ["id"] = 5751, ["name"] = "Regrets of the Past", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5751, ["questLineOrder"] = 12 } }, ["db2PoiUiMapID"] = 36 },
[86824] = { ["id"] = 86824, ["name"] = "None Left Standing", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 46, ["mapID"] = 36, ["storyline"] = { 86822, 86823, 86824, 86825, 86826, 86827, 86828, 86829, 86830, 86831, 86832, 86833, 86903, 91391, 91726, 91787, 91842 }, ["description"] = "The one thing worse than seeing this Dark Horde here is their banners. It showcases their pride in this accursed mountain as a place of greatness--as a place for their horde to rise. In reality, this banner is little more than a defiled perversion of the ancestral Blackrock sigil. Burn down every one you find.", ["objectivesText"] = "Burn 6 Dark Horde Banners. Progress: Got those banners dealt with, <name>?", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 239130 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 36, ["npcID"] = 237224, ["x"] = 0.335, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 36, ["npcID"] = 237224, ["x"] = 0.335, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 36, ["source"] = "quest_giver", ["x"] = 0.335, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 36 }, ["zone"] = { 46 } }, ["questType"] = "standard", ["sourceQuests"] = { 86822 }, ["questLines"] = { { ["id"] = 5751, ["name"] = "Regrets of the Past", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5751, ["questLineOrder"] = 12 } }, ["db2PoiUiMapID"] = 36 },
[86825] = { ["id"] = 86825, ["name"] = "Faithful Servant, Faithless Cause", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 46, ["mapID"] = 36, ["storyline"] = { 86822, 86823, 86824, 86825, 86826, 86827, 86828, 86829, 86830, 86831, 86832, 86833, 86903, 91391, 91726, 91787, 91842 }, ["description"] = "One of their lieutenants, Mar'kag , appears to be the one barking orders. His father, High Overlord Omokk, followed under Rend Blackhand's banner. Cruel, vicious... no surprise that his son follows in his footsteps. Taking Mar'kag down will spread chaos among the cowardly remnants of this Dark Horde and perhaps help them realize they are not as strong as they think. Faol also has us here to look for relic fragments. If Mar'kag has anything of note, bring it back.", ["objectivesText"] = "Defeat Mar'kag . Progress: Did you put a stop to Mar'kag , <name>?", ["rewardGold"] = 638000, ["rewardXP"] = 15215, ["rewardItems"] = { 246704, 251829, 251830, 251831, 251832 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3365, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 36, ["npcID"] = 237224, ["x"] = 0.335, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 36, ["npcID"] = 237224, ["x"] = 0.335, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 36, ["source"] = "quest_giver", ["x"] = 0.335, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 36 }, ["zone"] = { 46 } }, ["questType"] = "standard", ["sourceQuests"] = { 86822 }, ["questLines"] = { { ["id"] = 5751, ["name"] = "Regrets of the Past", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5751, ["questLineOrder"] = 12 } }, ["db2PoiUiMapID"] = 36 },
[86826] = { ["id"] = 86826, ["name"] = "Nagosh the Scarred", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 46, ["mapID"] = 36, ["storyline"] = { 86822, 86823, 86824, 86825, 86826, 86827, 86828, 86829, 86830, 86831, 86832, 86833, 86903, 91391, 91726, 91787, 91842 }, ["description"] = "The Dark Horde may strut around inside the mountain, but an orc called Nagosh is the one rulin' this roost. He barks orders, then charges straight into a fight. Rock-heads in command like that one are what gets everyone on all sides killed. I'd bet anything that numbskull claimed Faol's shiny relic. Keep an eye out. He may jump ye in the middle of a fight.", ["objectivesText"] = "Defeat Nagosh the Scarred . Progress: Did ye put a stop to Nagosh?", ["rewardGold"] = 638000, ["rewardXP"] = 15215, ["rewardItems"] = { 246699, 251826, 251828 }, ["rewardChoices"] = { 251826, 251828 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3365, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 36, ["npcID"] = 237268, ["x"] = 0.212, ["y"] = 0.396 } }, ["ends"] = { { ["mapID"] = 36, ["npcID"] = 237268, ["x"] = 0.212, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 36, ["source"] = "quest_giver", ["x"] = 0.212, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 36 }, ["zone"] = { 46 } }, ["questType"] = "standard", ["sourceQuests"] = { 91391 }, ["questLines"] = { { ["id"] = 5751, ["name"] = "Regrets of the Past", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5751, ["questLineOrder"] = 12 } }, ["db2PoiUiMapID"] = 36 },
[86827] = { ["id"] = 86827, ["name"] = "Due Recognition", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 46, ["mapID"] = 36, ["storyline"] = { 86822, 86823, 86824, 86825, 86826, 86827, 86828, 86829, 86830, 86831, 86832, 86833, 86903, 91391, 91726, 91787, 91842 }, ["description"] = "Blackrock Mountain is where most of the Dark Horde has holed up. All their unit commanders adorn themselves with badges, struttin' around like they won the Second War. Shameful! But it gives me an idea. Defeat them and take their badges. Can't have new leaders that way--these blowhards like the pomp of command. Who wants the stress of leadership with no fancy badge to wear? Head on in there with Arator and keep 'em busy. Sky'reen an' I will support ye from the air.", ["objectivesText"] = "Retrieve Stone Guard Badges from the Dark Horde in Blackrock Mountain. Progress: Did ye get their badges, <name>?", ["rewardGold"] = 319000, ["rewardXP"] = 12170, ["rewardItems"] = { 247218 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 36, ["npcID"] = 237268, ["x"] = 0.212, ["y"] = 0.396 } }, ["ends"] = { { ["mapID"] = 36, ["npcID"] = 237268, ["x"] = 0.212, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 36, ["source"] = "quest_giver", ["x"] = 0.212, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 36 }, ["zone"] = { 46 } }, ["questType"] = "standard", ["sourceQuests"] = { 91391 }, ["questLines"] = { { ["id"] = 5751, ["name"] = "Regrets of the Past", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5751, ["questLineOrder"] = 12 } }, ["db2PoiUiMapID"] = 36 },
[86828] = { ["id"] = 86828, ["name"] = "Not Just a Troll's Bane", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 46, ["mapID"] = 36, ["storyline"] = { 86822, 86823, 86824, 86825, 86826, 86827, 86828, 86829, 86830, 86831, 86832, 86833, 86903, 91391, 91726, 91787, 91842 }, ["description"] = "As much as I'd love to keep harassing these Dark Horde grunts, we've found the relic piece that Faol wanted us to. We best be getting on. Danath went looking for the last piece of the relic. You go find him, and I'll tell the mad bishop that his plan is nearly complete. Find me at Lothar's Statue when yer done.", ["objectivesText"] = "Find Danath Trollbane .", ["rewardGold"] = 30900, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 36, ["npcID"] = 237268, ["x"] = 0.212, ["y"] = 0.396 } }, ["ends"] = { { ["mapID"] = 36, ["npcID"] = 242120, ["x"] = 0.3228, ["y"] = 0.4192 } }, ["coords"] = { ["mapID"] = 36, ["source"] = "quest_giver", ["x"] = 0.212, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 36 }, ["zone"] = { 46 } }, ["questType"] = "standard", ["sourceQuests"] = { 86826, 86827, 91842 }, ["questLines"] = { { ["id"] = 5751, ["name"] = "Regrets of the Past", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5751, ["questLineOrder"] = 12 } }, ["db2PoiUiMapID"] = 36 },
[86829] = { ["id"] = 86829, ["name"] = "A Landmark Moment", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 46, ["mapID"] = 36, ["storyline"] = { 86822, 86823, 86824, 86825, 86826, 86827, 86828, 86829, 86830, 86831, 86832, 86833, 86903, 91391, 91726, 91787, 91842 }, ["description"] = "With their leader defeated and that third relic fragment found, we should regroup with the others back at Lothar's Statue, $p. I'll meet you there.", ["objectivesText"] = "Meet the Sons of Lothar at Lothar's Statue.", ["rewardGold"] = 319000, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 36, ["npcID"] = 242120, ["x"] = 0.3228, ["y"] = 0.4192 } }, ["ends"] = { { ["mapID"] = 36, ["npcID"] = 248263, ["x"] = 0.368, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 36, ["source"] = "quest_giver", ["x"] = 0.3228, ["y"] = 0.4192 }, ["mapCandidates"] = { ["npc"] = { 36 }, ["zone"] = { 46 } }, ["questType"] = "standard", ["sourceQuests"] = { 86830, 86831 }, ["questLines"] = { { ["id"] = 5751, ["name"] = "Regrets of the Past", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5751, ["questLineOrder"] = 12 } }, ["db2PoiUiMapID"] = 36 },
[86830] = { ["id"] = 86830, ["name"] = "A True Horde of Dark Horde", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 46, ["mapID"] = 36, ["storyline"] = { 86822, 86823, 86824, 86825, 86826, 86827, 86828, 86829, 86830, 86831, 86832, 86833, 86903, 91391, 91726, 91787, 91842 }, ["description"] = "The remaining Dark Horde forces are gathered here, $p. Many of them look to be untrained and new to the cause. Drive away the forces gathered here, and perhaps we can hope to see some peace in this region--for the first time in decades.", ["objectivesText"] = "Defeat 12 Dark Horde troops and 3 Dark Horde Sergeants. Progress: You've made a good start, <name>, with Arator 's help.", ["rewardGold"] = 319000, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 36, ["npcID"] = 242120, ["x"] = 0.3228, ["y"] = 0.4192 } }, ["ends"] = { { ["mapID"] = 36, ["npcID"] = 242120, ["x"] = 0.3228, ["y"] = 0.4192 } }, ["coords"] = { ["mapID"] = 36, ["source"] = "quest_giver", ["x"] = 0.3228, ["y"] = 0.4192 }, ["mapCandidates"] = { ["npc"] = { 36 }, ["zone"] = { 46 } }, ["questType"] = "standard", ["sourceQuests"] = { 86828 }, ["questLines"] = { { ["id"] = 5751, ["name"] = "Regrets of the Past", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5751, ["questLineOrder"] = 12 } }, ["db2PoiUiMapID"] = 36 },
[86831] = { ["id"] = 86831, ["name"] = "Warriors Without a Warlord", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 46, ["mapID"] = 36, ["storyline"] = { 86822, 86823, 86824, 86825, 86826, 86827, 86828, 86829, 86830, 86831, 86832, 86833, 86903, 91391, 91726, 91787, 91842 }, ["description"] = "Despite our work in the area, the Dark Horde continues to battle. Their leader is there, in Blackrock Stronghold, likely bolstering their spirits. Take them out. Once we do, I suspect this Dark Horde will come to nothing, with much less bloodshed. And Faol thinks there may be a fragment of the relic he's looking for in there. Recover that as well!", ["objectivesText"] = "Enter Blackrock Stronghold and take out the leader of the Dark Horde. Progress: Have you taken them out?", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 235625, 251822, 251823, 251824, 251825 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3365, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 36, ["npcID"] = 242120, ["x"] = 0.3228, ["y"] = 0.4192 } }, ["ends"] = { { ["mapID"] = 36, ["npcID"] = 242120, ["x"] = 0.3228, ["y"] = 0.4192 } }, ["coords"] = { ["mapID"] = 36, ["source"] = "quest_giver", ["x"] = 0.3228, ["y"] = 0.4192 }, ["mapCandidates"] = { ["npc"] = { 36 }, ["zone"] = { 46 } }, ["questType"] = "standard", ["sourceQuests"] = { 86828 }, ["questLines"] = { { ["id"] = 5751, ["name"] = "Regrets of the Past", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5751, ["questLineOrder"] = 12 } }, ["db2PoiUiMapID"] = 36 },
[86832] = { ["id"] = 86832, ["name"] = "A Worthy Forge", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 46, ["mapID"] = 36, ["storyline"] = { 86822, 86823, 86824, 86825, 86826, 86827, 86828, 86829, 86830, 86831, 86832, 86833, 86903, 91391, 91726, 91787, 91842 }, ["description"] = "Thank you for all your help, $p. It's strange to hold what remains of my father's shield and know that, prior to that day, he was such a defender of others. I feel I've only seen his aggressive side. I realize he means well, but I don't think... That is not the path for me. Regardless, let's return to Silvermoon and get these fragments we've gathered to a worthy forge.", ["objectivesText"] = "Return to Silvermoon. Progress: <name>, I can't thank you enough for taking this journey with Arator and I.", ["rewardGold"] = 31900, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 36, ["npcID"] = 237508, ["x"] = 0.366, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 237511, ["x"] = 0.439333, ["y"] = 0.656667 } }, ["coords"] = { ["mapID"] = 36, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 36, 2393 }, ["zone"] = { 46 } }, ["questType"] = "standard", ["sourceQuests"] = { 91726 }, ["questLines"] = { { ["id"] = 5751, ["name"] = "Regrets of the Past", ["orderIndex"] = 13, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5751, ["questLineOrder"] = 12 } }, ["db2PoiUiMapID"] = 2393 },
[86833] = { ["id"] = 86833, ["name"] = "A Bulwark Remade", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 46, ["mapID"] = 2393, ["storyline"] = { 86822, 86823, 86824, 86825, 86826, 86827, 86828, 86829, 86830, 86831, 86832, 86833, 86903, 91391, 91726, 91787, 91842 }, ["description"] = "$p, it is time to see what we can do with these fragments of Turalyon's shield. While it did break, it was exceptionally powerful in its day, and it could be a great help to Turalyon against the Void. Perhaps a moment of healing and letting go, as well.", ["objectivesText"] = "Help Arator reforge his father's shield. Progress: Thank you for helping me with this, <name>.", ["rewardGold"] = 322100, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 237511, ["x"] = 0.439333, ["y"] = 0.656667 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 237510, ["x"] = 0.405, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.439333, ["y"] = 0.656667 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 86832 }, ["questLines"] = { { ["id"] = 5751, ["name"] = "Regrets of the Past", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5751, ["questLineOrder"] = 12 } }, ["db2PoiUiMapID"] = 2393 },
[86834] = { ["id"] = 86834, ["name"] = "Voidborn Banishing", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16182, ["mapID"] = 2565, ["storyline"] = { 86769, 86770, 86780, 86805, 86806, 86807, 86811, 86834, 86848, 86849, 86850, 86852, 88719, 89012, 89271, 91274, 91281 }, ["series"] = { 86811 }, ["description"] = "The Devouring Host are composed of horrors from the depths of the Void, but they are still an army, with soldiers and leaders. Amongst that sea of void walkers, I notice there are singular creatures. Whether commander or mascot to the Host, removing them from the battlefield will help to break their lines.", ["objectivesText"] = "Slay Latrunculon , Blightclaw , and The Wasting . Progress: We need to defeat all of the void commanders.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 251241, 251242 }, ["rewardChoices"] = { 251241, 251242 }, ["starts"] = { { ["mapID"] = 2565, ["npcID"] = 236964, ["x"] = 0.4948, ["y"] = 0.2176 } }, ["ends"] = { { ["mapID"] = 2432, ["npcID"] = 236978, ["x"] = 0.454, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 2565, ["source"] = "quest_giver", ["x"] = 0.4948, ["y"] = 0.2176 }, ["mapCandidates"] = { ["npc"] = { 2432, 2565 }, ["zone"] = { 16211 } }, ["questType"] = "standard", ["sourceQuests"] = { 86807 }, ["questLines"] = { { ["id"] = 5811, ["name"] = "The Light's Summons", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 335, ["title"] = "Midnight Expansion Intro Skip", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 352, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2858, ["db2PoiUiMapID"] = 2432 },
[86835] = { ["id"] = 86835, ["name"] = "Regroup!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 84956, 84957, 84958, 84959, 84960, 84961, 84963, 84964, 84965, 84967, 85003, 85039, 86835 }, ["description"] = "We've stabilized most of the city and saved as many as we could, but our job isn't over. Locus-Walker must still be out there looking for the enemy commander. We've already searched over most of the city, so he must be in the one place we've not yet looked. Come, <name>. Meet me at Myza's Oasis.", ["objectivesText"] = "Locate Locus-Walker within Tazavesh.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 90330, 90332, 90333, 90334, 90335, 90337, 143488 }, ["starts"] = { { ["npcID"] = 234483 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 234620, ["x"] = 0.395333, ["y"] = 0.698333 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.395333, ["y"] = 0.698333 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questGiverID"] = 234483, ["questType"] = "standard", ["sourceQuests"] = { 84965 }, ["questLines"] = { { ["id"] = 5690, ["name"] = "A Shadowy Invitation", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5690, ["questLineOrder"] = 0 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5690, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[86836] = { ["id"] = 86836, ["name"] = "The Hunter Awaits", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86836, 86851, 86855, 86856, 86857, 86858, 86859, 86860, 86861, 86862, 86864, 86865, 86866, 86867, 86874, 86877, 86880, 86881, 86882, 86890, 94677 }, ["description"] = "I have warned Orweyna of the dangers and madness that lay within the Rift of Aln, but she believes it is her only path forward. I envy her faith. Someone can help show her the way: the Shul'ka. The Hunters of Shadows. They have sacrificed everything to protect the haranir from the effects of the rift. I will let one know that you need help. You will find him in the Vale of Mists.", ["objectivesText"] = "Find Orweyna and the Shul'ka in the Vale of Mists.", ["rewardGold"] = 34100, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3370, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 241045, ["x"] = 0.542, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237236, ["x"] = 0.62, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86864 }, ["questLines"] = { { ["id"] = 5726, ["name"] = "Call of the Goddess", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5726, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86837] = { ["id"] = 86837, ["name"] = "Meet at the Sunwell", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 86837, 86838, 86839, 86840, 86841, 86842, 86843, 86844, 86845, 86846, 86902, 89193, 89338, 91000, 92136 }, ["series"] = { 89193 }, ["description"] = "I have been tasked with bolstering the Vanguard of Light that empower the Sunwell. I need your help, though not just for that simple task. Our mutual friend, Arator , is... stuck. Stuck in his grief and anger over that tragic conflict between him and his father. I'm just an old priest that's been raised from the dead, but I've found that a quest is just the thing to set a young paladin back on the right path. Would you help?", ["objectivesText"] = "Ask Arator to meet Faol at the Sunwell.", ["rewardGold"] = 34100, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 237565, ["x"] = 0.456, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 2424, ["npcID"] = 240240, ["x"] = 0.528, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 2393, 2424 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 89193 }, ["questLines"] = { { ["id"] = 5750, ["name"] = "The Path of Light", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5750, ["questLineOrder"] = 11 } }, ["db2PoiUiMapID"] = 2424 },
[86838] = { ["id"] = 86838, ["name"] = "Renewal for the Weary", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2424, ["storyline"] = { 86837, 86838, 86839, 86840, 86841, 86842, 86843, 86844, 86845, 86846, 86902, 89193, 89338, 91000, 92136 }, ["description"] = "The Vanguard of Light are maintaining a difficult ritual at the Sunwell. It requires focus, discipline, and is quite exhausting. Take my staff. I've had it since I was Archbishop in Stormwind. It is meaningful to me and my faith. The Light responds to meaning and intention. It should renew the Vanguard's spirits so they can maintain the ritual a while longer. I can't approach any closer to the Sunwell, so you will have to do this for me.", ["objectivesText"] = "Restore the Light to 10 weary channelers.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 18608, 237811, 251274, 251275, 251276, 251277 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2424, ["npcID"] = 240240, ["x"] = 0.528, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 2424, ["npcID"] = 240240, ["x"] = 0.528, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 2424, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 2424 }, ["zone"] = { 16215 } }, ["questType"] = "standard", ["sourceQuests"] = { 89193 }, ["questLines"] = { { ["id"] = 5750, ["name"] = "The Path of Light", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5750, ["questLineOrder"] = 11 } }, ["db2PoiUiMapID"] = 2424 },
[86839] = { ["id"] = 86839, ["name"] = "Relics of Light's Hope", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2424, ["storyline"] = { 86837, 86838, 86839, 86840, 86841, 86842, 86843, 86844, 86845, 86846, 86902, 89193, 89338, 91000, 92136 }, ["description"] = "The holy power in my staff has been spent. Forty years of fervent prayers drained away in a few minutes. It was for a good cause, and my staff will recover in time. There are other relics, like my staff, that were important to paladins and priests. Light's Hope Chapel has many such relics stored there. Arator trained there as well. Perhaps the solution to his pain could also be found within.", ["objectivesText"] = "Meet Lord Maxwell Tyrosus at Light's Hope Chapel.", ["rewardGold"] = 170800, ["rewardXP"] = 6085, ["rewardItems"] = { 61379 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2424, ["npcID"] = 240240, ["x"] = 0.528, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 237594, ["x"] = 0.738, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2424, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 23, 2424 }, ["zone"] = { 16215 } }, ["questType"] = "standard", ["sourceQuests"] = { 86838 }, ["questLines"] = { { ["id"] = 5750, ["name"] = "The Path of Light", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5750, ["questLineOrder"] = 11 } }, ["db2PoiUiMapID"] = 23 },
[86840] = { ["id"] = 86840, ["name"] = "Flickering Hope", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 139, ["mapID"] = 23, ["storyline"] = { 86837, 86838, 86839, 86840, 86841, 86842, 86843, 86844, 86845, 86846, 86902, 89193, 89338, 91000, 92136 }, ["description"] = "Normally, $p, paladins from Light's Hope hold back the Scourge in the immediate area around the chapel, but they've all been called to fight the Void. As a result, Scourge forces have greatly increased their numbers around the chapel. We've managed to hold the line so far, but only with the help of Darion and the Ebon Blade. Give us some room to breathe--defeat as many of them as you can.", ["objectivesText"] = "Kill Scourge forces around Light's Hope Chapel. Progress: We can't hold back the undead forever, <name>.", ["rewardGold"] = 312800, ["rewardXP"] = 12170, ["rewardItems"] = { 206350, 251719, 251720, 251721, 251722 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 237594, ["x"] = 0.738, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 237594, ["x"] = 0.738, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.738, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 139 } }, ["questType"] = "standard", ["sourceQuests"] = { 86839 }, ["questLines"] = { { ["id"] = 5750, ["name"] = "The Path of Light", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5750, ["questLineOrder"] = 11 } }, ["db2PoiUiMapID"] = 23 },
[86841] = { ["id"] = 86841, ["name"] = "Relics of Paladins Past", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 139, ["mapID"] = 23, ["storyline"] = { 86837, 86838, 86839, 86840, 86841, 86842, 86843, 86844, 86845, 86846, 86902, 89193, 89338, 91000, 92136 }, ["description"] = "Alonsus tells me you're looking for relics of holy power, to sustain those performing the ritual holding the Void at bay. Now that you've beaten back the Scourge, you and Arator are certainly welcome to enter the Sanctum of Light and use what we have for the cause.", ["objectivesText"] = "Gather 5 relics from the Sanctum of Light. Progress: Countless great heroes are interred under the chapel, <name>. Hopefully their relics can be of aid to those at the Sunwell.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 237513, 237518, 237519, 237573, 237574 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 237594, ["x"] = 0.738, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 237594, ["x"] = 0.738, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.738, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 139 } }, ["questType"] = "standard", ["sourceQuests"] = { 86840 }, ["questLines"] = { { ["id"] = 5750, ["name"] = "The Path of Light", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5750, ["questLineOrder"] = 11 } }, ["db2PoiUiMapID"] = 23 },
[86842] = { ["id"] = 86842, ["name"] = "Scarlet Power", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 139, ["mapID"] = 23, ["storyline"] = { 86837, 86838, 86839, 86840, 86841, 86842, 86843, 86844, 86845, 86846, 86902, 89193, 89338, 91000, 92136 }, ["description"] = "These artifacts will help sustain the Vanguard, but they are not enough. I know of a place nearby that would have the rest we need, but... given Arator 's state of mind, I'm hesitant to go there. Hmph... No sense in avoiding it. We must all face up to the fact that Scarlet Crusade calls upon the power of the Light, and has for decades.", ["objectivesText"] = "Meet Alonsus Faol at Scarlet Monastery. Progress: When it comes to reclaiming relics of the Light from the Scarlet Crusade, there's no better time than now, <name>.", ["rewardGold"] = 164200, ["rewardXP"] = 6085, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 237601, ["x"] = 0.738, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 237601, ["x"] = 0.738, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.738, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 139 } }, ["questTurnInID"] = 237601, ["questType"] = "standard", ["sourceQuests"] = { 86841 }, ["questLines"] = { { ["id"] = 5750, ["name"] = "The Path of Light", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5750, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2857, ["db2PoiUiMapID"] = 2438 },
[86843] = { ["id"] = 86843, ["name"] = "Light Miswielded", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 85, ["mapID"] = 2438, ["storyline"] = { 86837, 86838, 86839, 86840, 86841, 86842, 86843, 86844, 86845, 86846, 86902, 89193, 89338, 91000, 92136 }, ["description"] = "The Scarlet Crusade has been wielding the Light for its evil purposes for decades, $p. I'm disappointed to see how many forces they still have here. Still, the Light responds to them, just as it does to us. We're here to get their relics to help the Sunwell, but while we're here, let's cleanse this place of their dark influence.", ["objectivesText"] = "Defeat Scarlet Crusade members. Progress: Have you dealt with the Scarlet threat, <name>?", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 237602, ["mapID"] = 2438, ["x"] = 0.473153, ["y"] = 0.907505 } }, ["ends"] = { { ["npcID"] = 237602, ["mapID"] = 2438, ["x"] = 0.473153, ["y"] = 0.907505 } }, ["coords"] = { ["source"] = "quest_giver", ["mapID"] = 2438, ["x"] = 0.473153, ["y"] = 0.907505 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["sourceQuests"] = { 86842 }, ["questLines"] = { { ["id"] = 5750, ["name"] = "The Path of Light", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5750, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2857, ["db2PoiUiMapID"] = 2438 },
[86844] = { ["id"] = 86844, ["name"] = "Light Repurposed", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 85, ["mapID"] = 2438, ["storyline"] = { 86837, 86838, 86839, 86840, 86841, 86842, 86843, 86844, 86845, 86846, 86902, 89193, 89338, 91000, 92136 }, ["description"] = "Leaders of the Crusade have channeled the Light through their weapons every day for years. While their goals and actions are reprehensible to us, their weapons are no less useful than my own staff, especially in such a time of need. As you go through the Scarlet Halls, whenever you find a leader, defeat them and bring back their weapon. We will put it to a righteous use: to aid the Sunwell.", ["objectivesText"] = "Recover Meyer's Rod of Castigation , Aelyse's Gleaming Falchion , and Benthar's Scarlet Spire . Progress: What artifacts have you found here, <name>?", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 237576, 237579, 237761, 251724, 251725, 251726, 251727, 251728, 251729, 251730, 251731, 251732, 251733, 251734 }, ["rewardChoices"] = { 251724, 251725, 251726, 251727, 251728, 251729, 251730, 251731, 251732, 251733, 251734 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3365, ["amount"] = 100 } }, ["starts"] = { { ["npcID"] = 237602, ["mapID"] = 2438, ["x"] = 0.473153, ["y"] = 0.907505 } }, ["ends"] = { { ["npcID"] = 237602, ["mapID"] = 2438, ["x"] = 0.473153, ["y"] = 0.907505 } }, ["coords"] = { ["source"] = "quest_giver", ["mapID"] = 2438, ["x"] = 0.473153, ["y"] = 0.907505 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["sourceQuests"] = { 86842 }, ["questLines"] = { { ["id"] = 5750, ["name"] = "The Path of Light", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5750, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2857, ["db2PoiUiMapID"] = 2438 },
[86845] = { ["id"] = 86845, ["name"] = "The Sunwalker Path", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 85, ["mapID"] = 2424, ["storyline"] = { 86837, 86838, 86839, 86840, 86841, 86842, 86843, 86844, 86845, 86846, 86902, 89193, 89338, 91000, 92136 }, ["description"] = "I think I have failed Arator. In my attempt to steady him after the incident with his father, I may have shattered his faith with uncomfortable truths of the Light. I would like to consult with the wisest person I know, Sunwalker Dezco . I did not see him with the Vanguard. Tyrosus told me he may be in Hammerfall providing aid to the displaced.", ["objectivesText"] = "Meet with Sunwalker Dezco in Hammerfall. Progress: Welcome, <name>. There's plenty to do here if you're willing!", ["rewardGold"] = 170800, ["rewardXP"] = 6085, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2424, ["npcID"] = 251355, ["x"] = 0.525333, ["y"] = 0.556667 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 245186, ["x"] = 0.69, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 2424, ["source"] = "quest_giver", ["x"] = 0.525333, ["y"] = 0.556667 }, ["mapCandidates"] = { ["npc"] = { 14, 2424 }, ["zone"] = { 16215 } }, ["questType"] = "standard", ["sourceQuests"] = { 86902 }, ["questLines"] = { { ["id"] = 5750, ["name"] = "The Path of Light", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5750, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2796, ["db2PoiUiMapID"] = 2372 },
[86846] = { ["id"] = 86846, ["name"] = "Resupplying Our Suppliers", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 130, ["mapID"] = 14, ["storyline"] = { 86837, 86838, 86839, 86840, 86841, 86842, 86843, 86844, 86845, 86846, 86902, 89193, 89338, 91000, 92136 }, ["description"] = "$p, the people of Hammerfall were attacked not so long ago by saboteurs from a group called the Red Dawn. I am working to help them recover and rebuild from the attack with my fellow Sunwalkers: Malu and Nadura. One thing they have been doing is gathering supplies needed by Hammerfall's crafters from various sources. If you could deliver these supplies, it would be a great help.", ["objectivesText"] = "Aid the people of Hammerfall in their recovery. Progress: Have you distributed the supplies, <name>?", ["rewardGold"] = 309800, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 245186, ["x"] = 0.69, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 247299, ["x"] = 0.685, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.69, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 14 }, ["zone"] = { 45 } }, ["questType"] = "standard", ["sourceQuests"] = { 86845 }, ["questLines"] = { { ["id"] = 5750, ["name"] = "The Path of Light", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5750, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2796, ["db2PoiUiMapID"] = 2372 },
[86848] = { ["id"] = 86848, ["name"] = "Light's Arsenal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16182, ["mapID"] = 2432, ["storyline"] = { 86769, 86770, 86780, 86805, 86806, 86807, 86811, 86834, 86848, 86849, 86850, 86852, 88719, 89012, 89271, 91274, 91281 }, ["description"] = "The armory here stores legendary weapons and artifacts, blessed with the power of the Light due to their proximity to the Sunwell. While we are pinned down by the Host, the ethereals are looting these treasures. <name>, secure these holy artifacts. They are our best weapons against the Void. Use them to cut down these invaders if you have the need.", ["objectivesText"] = "Collect 7 Legendary Weapons. Progress: Have you secured our artifacts?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 238807, 238842, 238843, 238844, 238845, 238846, 238864, 238890, 238891, 251257 }, ["rewardChoices"] = { 251257 }, ["starts"] = { { ["mapID"] = 2432, ["npcID"] = 237253, ["x"] = 0.452, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 2432, ["npcID"] = 237253, ["x"] = 0.452, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 2432, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 2432 }, ["zone"] = { 16182 } }, ["questType"] = "standard", ["sourceQuests"] = { 86834, 91274 }, ["questLines"] = { { ["id"] = 5811, ["name"] = "The Light's Summons", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 335, ["title"] = "Midnight Expansion Intro Skip", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 352, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2858, ["db2PoiUiMapID"] = 2432 },
[86849] = { ["id"] = 86849, ["name"] = "Wrath Unleashed", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16182, ["mapID"] = 2432, ["storyline"] = { 86769, 86770, 86780, 86805, 86806, 86807, 86811, 86834, 86848, 86849, 86850, 86852, 88719, 89012, 89271, 91274, 91281 }, ["description"] = "<name>, the time has come! We push these fiends to Sun's Reach Harbor! We drive them back into their accursed void portal and drive them from these sacred shores! For the Light! For Azeroth!", ["objectivesText"] = "Join the charge of the Vanguard of Light. Progress: Don't stop until we drive them from these shores!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2432, ["npcID"] = 236978, ["x"] = 0.454, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 2432, ["npcID"] = 237277, ["x"] = 0.458, ["y"] = 0.115 } }, ["coords"] = { ["mapID"] = 2432, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 2432 }, ["zone"] = { 16182 } }, ["questType"] = "standard", ["sourceQuests"] = { 86811, 86848 }, ["questLines"] = { { ["id"] = 5811, ["name"] = "The Light's Summons", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 335, ["title"] = "Midnight Expansion Intro Skip", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 352, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2858, ["db2PoiUiMapID"] = 2432 },
[86850] = { ["id"] = 86850, ["name"] = "Broken Sun", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16182, ["mapID"] = 2432, ["storyline"] = { 86769, 86770, 86780, 86805, 86806, 86807, 86811, 86834, 86848, 86849, 86850, 86852, 88719, 89012, 89271, 91274, 91281 }, ["series"] = { 86852 }, ["description"] = "We need to fall back! This is not a battle that we can win. Not like this. But there is still hope! The Sunwell. It brought the Vanguard of Light here to defend it. It brought you, <name>. Fall back to the Sunwell chamber and defend it for as long as we can. I have faith the Light did not intend for us to lose this day.", ["objectivesText"] = "Meet Liadrin at the entrance to the Sunwell.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2432, ["npcID"] = 237277, ["x"] = 0.458, ["y"] = 0.115 } }, ["ends"] = { { ["mapID"] = 2432, ["npcID"] = 237278, ["x"] = 0.525429, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 2432, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.115 }, ["mapCandidates"] = { ["npc"] = { 2432 }, ["zone"] = { 16182 } }, ["questType"] = "standard", ["sourceQuests"] = { 86849 }, ["questLines"] = { { ["id"] = 5811, ["name"] = "The Light's Summons", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 335, ["title"] = "Midnight Expansion Intro Skip", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 352, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2858, ["db2PoiUiMapID"] = 2566 },
[86851] = { ["id"] = 86851, ["name"] = "The Foundation of Aln", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86836, 86851, 86855, 86856, 86857, 86858, 86859, 86860, 86861, 86862, 86864, 86865, 86866, 86867, 86874, 86877, 86880, 86881, 86882, 86890, 94677 }, ["description"] = "The presence of the goddess reverberates through everything in the Rift of Aln. The voice is too powerful for haranir to resist. In mere minutes, one of our flock would be lost forever. There are, however, ways to protect oneself for a short time. Kill the rejects that crawl up from the rift and gather the Alndust from which they are created. I can show Orweyna how to craft a short-term solution for entering the rift.", ["objectivesText"] = "Collect 6 alndust from Rift creatures in the Vale of Mists. Progress: I will let your young companion know what to do with the Alndust.", ["rewardGold"] = 335000, ["rewardXP"] = 12170, ["rewardItems"] = { 238417, 266259 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 237236, ["x"] = 0.62, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 241070, ["x"] = 0.619, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86836 }, ["questLines"] = { { ["id"] = 5726, ["name"] = "Call of the Goddess", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5726, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86852] = { ["id"] = 86852, ["name"] = "Light's Last Stand", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16182, ["mapID"] = 2432, ["storyline"] = { 86769, 86770, 86780, 86805, 86806, 86807, 86811, 86834, 86848, 86849, 86850, 86852, 88719, 89012, 89271, 91274, 91281 }, ["series"] = { 86850 }, ["description"] = "Our attempts to fight Xal'atath's Devouring Host have failed. Our only hope is to call upon the Light once more and trust that there was a reason it brought this Vanguard together. <name>, you and Arator need to protect the Sunwell from the Devouring Host. With so few of us left, we cannot spare any more defenders. Our faith in the Light will save us.", ["objectivesText"] = "Defend the Sunwell from the attacking forces.", ["rewardGold"] = 929400, ["rewardXP"] = 17650, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2432, ["npcID"] = 237278, ["x"] = 0.525429, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 2424, ["npcID"] = 241068, ["x"] = 0.525, ["y"] = 0.883 } }, ["coords"] = { ["mapID"] = 2432, ["source"] = "quest_giver", ["x"] = 0.525429, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 2424, 2432 }, ["zone"] = { 16182 } }, ["questType"] = "standard", ["sourceQuests"] = { 86850 }, ["questLines"] = { { ["id"] = 5811, ["name"] = "The Light's Summons", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 335, ["title"] = "Midnight Expansion Intro Skip", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 352, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 2424 },
[86853] = { ["id"] = 86853, ["name"] = "Sparks of War: Undermine", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14752, ["mapID"] = 2339, ["storyline"] = { 86853 }, ["description"] = "Investigate the Undermine! Reports are coming in about a growing conflict in the area, go and check it out.", ["objectivesText"] = "Collect 100 Sparks of War in Undermine, while in War Mode. Progress: Go off and complete your investigation.", ["rewardItems"] = { 219934 }, ["rewardCurrencies"] = { { ["id"] = 1792, ["amount"] = 500 }, { ["id"] = 1602, ["amount"] = 50 }, { ["id"] = 2123, ["amount"] = 1000 }, { ["id"] = 2815, ["amount"] = 40 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard" },
[86855] = { ["id"] = 86855, ["name"] = "Consequences of Our Duty", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86836, 86851, 86855, 86856, 86857, 86858, 86859, 86860, 86861, 86862, 86864, 86865, 86866, 86867, 86874, 86877, 86880, 86881, 86882, 86890, 94677 }, ["description"] = "You must see with your own eyes the effects that the Rift of Aln can have on any haranir. Even those who stand guard over the border are oft affected by its call. Take this. I use it as an emergency salve to help those who are stricken of the dangers of Aln. Patrol these lands and give aid to those who need it. Perhaps then you will understand the gravity of what you seek to do.", ["objectivesText"] = "Heal 5 Wounded Guardians in the Vale of Mists. Progress: I did not know that these castoffs from the rift could affect us so much...", ["rewardGold"] = 335000, ["rewardXP"] = 12170, ["rewardItems"] = { 243595, 256334, 256335 }, ["rewardChoices"] = { 256334, 256335 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 237236, ["x"] = 0.62, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 241070, ["x"] = 0.619, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86836 }, ["questLines"] = { { ["id"] = 5726, ["name"] = "Call of the Goddess", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5726, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86856] = { ["id"] = 86856, ["name"] = "Dampening the Call", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86836, 86851, 86855, 86856, 86857, 86858, 86859, 86860, 86861, 86862, 86864, 86865, 86866, 86867, 86874, 86877, 86880, 86881, 86882, 86890, 94677 }, ["description"] = "Amarakk told me how to prepare Alndust to create the salve. In small doses, Alndust can strengthen the mind against madness and terror. It offers clarity and peace, but only if expertly employed. I could use your help to set an anchor to this place, $p. The ritual is delicate, and failure could be disastrous.", ["objectivesText"] = "Help Orweyna create the Alndust Filter at the Vale of Mists. Progress: The process sounded simple enough--well within my abilities. But I appreciate your presence here to ground me.", ["rewardGold"] = 154900, ["rewardXP"] = 6085, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 241070, ["x"] = 0.619, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 241070, ["x"] = 0.619, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.619, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86851, 86855 }, ["questLines"] = { { ["id"] = 5726, ["name"] = "Call of the Goddess", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5726, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86857] = { ["id"] = 86857, ["name"] = "Descent into the Rift", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86836, 86851, 86855, 86856, 86857, 86858, 86859, 86860, 86861, 86862, 86864, 86865, 86866, 86867, 86874, 86877, 86880, 86881, 86882, 86890, 94677 }, ["description"] = "With this, I will be able to venture down into the Rift of Aln. I will not have long, so we should not dawdle. Let us find Amarakk and gain his help.", ["objectivesText"] = "Find the Wards of the Shul'ka in the Rift of Aln to find Amarakk .", ["rewardGold"] = 335000, ["rewardXP"] = 12170, ["rewardItems"] = { 246407 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 241070, ["x"] = 0.619, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237284, ["x"] = 0.619333, ["y"] = 0.567333 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.619, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86856 }, ["questLines"] = { { ["id"] = 5726, ["name"] = "Call of the Goddess", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5726, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86858] = { ["id"] = 86858, ["name"] = "The Madness Roots Deep", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86836, 86851, 86855, 86856, 86857, 86858, 86859, 86860, 86861, 86862, 86864, 86865, 86866, 86867, 86874, 86877, 86880, 86881, 86882, 86890, 94677 }, ["description"] = "I found you while I was in the middle of one of my duties. Someone has spent too long within the rift and has fallen prey to the call of the goddess. I must rescue him and send him back to where he belongs. Help me with this task, and I will help you.", ["objectivesText"] = "Defeat On'hiea in the Rift of Aln. Progress: We can save him!", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 256199, 256207, 256215, 256223 }, ["rewardChoices"] = { 256199, 256207, 256215, 256223 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 237284, ["x"] = 0.619333, ["y"] = 0.567333 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237284, ["x"] = 0.619333, ["y"] = 0.567333 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.619333, ["y"] = 0.567333 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86857 }, ["questLines"] = { { ["id"] = 5726, ["name"] = "Call of the Goddess", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5726, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86859] = { ["id"] = 86859, ["name"] = "Grinding Out a Solution", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86836, 86851, 86855, 86856, 86857, 86858, 86859, 86860, 86861, 86862, 86864, 86865, 86866, 86867, 86874, 86877, 86880, 86881, 86882, 86890, 94677 }, ["description"] = "I have been pondering what Hagar could have meant from the moment Orweyna mentioned an answer to your problems. There are no mystical fountains--no weapons. Everything in the rift is created from the same source: Alndust, the distillation of the influence of the goddess. If we hunt a large manifestation, you will have the power of creation in its purest form. We cannot defeat it without help. Search the rift and look for fungi large enough to cultivate. I can use them to give us an edge.", ["objectivesText"] = "Find 5 Alngrown Fungus in the Rift of Aln. Progress: Any advantage that we can have against the manifestation will give us a better chance to survive.", ["rewardGold"] = 309800, ["rewardXP"] = 12170, ["rewardItems"] = { 238651 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 237284, ["x"] = 0.619333, ["y"] = 0.567333 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237284, ["x"] = 0.619333, ["y"] = 0.567333 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.619333, ["y"] = 0.567333 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86858 }, ["questLines"] = { { ["id"] = 5726, ["name"] = "Call of the Goddess", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5726, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86860] = { ["id"] = 86860, ["name"] = "Before They Grow", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86836, 86851, 86855, 86856, 86857, 86858, 86859, 86860, 86861, 86862, 86864, 86865, 86866, 86867, 86874, 86877, 86880, 86881, 86882, 86890, 94677 }, ["description"] = "Within every creature that roams the Rift of Aln thrums a gathering of the foundation of the goddess's influence. This Alndust yearns to merge with others of its ilk. Part of my duties as the Shul'ka is to make sure to keep the number of large manifestations low so they do not overwhelm the Den. It is easiest to do that while they are small. Take this spear. You may use it to shatter the smaller creatures down to... trivial sizes.", ["objectivesText"] = "Use Amarakk's Influence to defeat Aln Mites and creatures in the Rift of Aln.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 239131 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 237284, ["x"] = 0.619333, ["y"] = 0.567333 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237284, ["x"] = 0.619333, ["y"] = 0.567333 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.619333, ["y"] = 0.567333 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86858 }, ["questLines"] = { { ["id"] = 5726, ["name"] = "Call of the Goddess", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5726, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86861] = { ["id"] = 86861, ["name"] = "Herding Manifestations", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86836, 86851, 86855, 86856, 86857, 86858, 86859, 86860, 86861, 86862, 86864, 86865, 86866, 86867, 86874, 86877, 86880, 86881, 86882, 86890, 94677 }, ["description"] = "We are preparing to fight a giant manifestation. Let me emphasize this again. We must fight just one. If we fight two at a time, we would have no chance of survival. Place these wards around the rift to draw the others away. They will not last long... but we will need every advantage we can gain.", ["objectivesText"] = "Place 3 Wards around the Rift of Aln. Progress: These wars are a creation of my own making. They attack the larger creatures toward them by mimicking their reaction to food.", ["rewardGold"] = 319000, ["rewardXP"] = 12170, ["rewardItems"] = { 252045 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 237284, ["x"] = 0.619333, ["y"] = 0.567333 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237284, ["x"] = 0.619333, ["y"] = 0.567333 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.619333, ["y"] = 0.567333 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86858 }, ["questLines"] = { { ["id"] = 5726, ["name"] = "Call of the Goddess", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5726, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86862] = { ["id"] = 86862, ["name"] = "The Greater They Aln", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86836, 86851, 86855, 86856, 86857, 86858, 86859, 86860, 86861, 86862, 86864, 86865, 86866, 86867, 86874, 86877, 86880, 86881, 86882, 86890, 94677 }, ["description"] = "We have one chance at this only. I pray we have prepared enough.", ["objectivesText"] = "Defeat the Aln Manifestation and gather its components in the Rift of Aln. Progress: The power of the Rift of Aln is beyond mortal comprehension. What we are doing is simply borrowing some of it for a brief moment.", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 238738, 252956, 259477 }, ["rewardChoices"] = { 252956, 259477 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3370, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 237284, ["x"] = 0.619333, ["y"] = 0.567333 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237284, ["x"] = 0.619333, ["y"] = 0.567333 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.619333, ["y"] = 0.567333 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86859, 86860, 86861 }, ["questLines"] = { { ["id"] = 5726, ["name"] = "Call of the Goddess", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5726, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86864] = { ["id"] = 86864, ["name"] = "Watch the Den", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86836, 86851, 86855, 86856, 86857, 86858, 86859, 86860, 86861, 86862, 86864, 86865, 86866, 86867, 86874, 86877, 86880, 86881, 86882, 86890, 94677 }, ["description"] = "Finally, we have a moment to breathe. This is where we feel closest to the goddess--we are below the Cradle where she used to rest. The elders will not allow us to use any of the Alndust they have gathered over the centuries. They see only what the goddess asked of us before, not what her world needs now. Alndust is rare, but there are ways to get it. Ask around. I will check... elsewhere.", ["objectivesText"] = "Speak to the Innkeeper, Renown Quartermaster, and the Flight Master at the Den. Progress: I hope that you will be able to rest here. You must know how to navigate this place.", ["rewardGold"] = 34100, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3370, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 237860, ["mapID"] = 2576, ["x"] = 0.44172, ["y"] = 0.526027 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237234, ["x"] = 0.596667, ["y"] = 0.562 }, { ["npcID"] = 237860, ["mapID"] = 2576, ["x"] = 0.44172, ["y"] = 0.526027 } }, ["coords"] = { ["source"] = "quest_giver", ["mapID"] = 2576, ["x"] = 0.44172, ["y"] = 0.526027 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86930 }, ["questLines"] = { { ["id"] = 5726, ["name"] = "Call of the Goddess", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5726, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86865] = { ["id"] = 86865, ["name"] = "In Search of the Problem", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86836, 86851, 86855, 86856, 86857, 86858, 86859, 86860, 86861, 86862, 86864, 86865, 86866, 86867, 86874, 86877, 86880, 86881, 86882, 86890, 94677 }, ["description"] = "We did what Hagar asked us to do. The next step will be to test this on something--or someone--afflicted with the Lightbloom. It may be difficult to find the Lightbloom in enough quantities in Harandar , but I believe we will find what we need at Har'alnor. I will meet you there!", ["objectivesText"] = "Meet Orweyna at Har'alnor.", ["rewardGold"] = 170800, ["rewardXP"] = 6085, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 237234, ["x"] = 0.596667, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237295, ["x"] = 0.317, ["y"] = 0.631 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.596667, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86862 }, ["questLines"] = { { ["id"] = 5726, ["name"] = "Call of the Goddess", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5726, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86866] = { ["id"] = 86866, ["name"] = "Can We Heal This?", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86836, 86851, 86855, 86856, 86857, 86858, 86859, 86860, 86861, 86862, 86864, 86865, 86866, 86867, 86874, 86877, 86880, 86881, 86882, 86890, 94677 }, ["description"] = "The rutaani have escaped their nearby villages to Har'alnor. The guards have told me that some of them have been afflicted with the Lightbloom, yet have not succumbed to its effects. This may be our best opportunity to test the Alndust's powers. Time is of the essence!", ["objectivesText"] = "Use the Greater Alndust on the Afflicted Rutaani at Har'alnor. Progress: This is it, <name>. The moment of truth. Do we have an answer for the problems on Azeroth?", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 252045, 254319 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 237325, ["x"] = 0.314, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237356, ["x"] = 0.319333, ["y"] = 0.715333 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.314, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86865 }, ["questLines"] = { { ["id"] = 5726, ["name"] = "Call of the Goddess", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5726, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86867] = { ["id"] = 86867, ["name"] = "Into the Lightbloom", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86836, 86851, 86855, 86856, 86857, 86858, 86859, 86860, 86861, 86862, 86864, 86865, 86866, 86867, 86874, 86877, 86880, 86881, 86882, 86890, 94677 }, ["description"] = "We've gathered the haranir we have available and distributed the Alndust. We have everything we need, but they need to be able to safely enter the area. Scouts have told us that the creatures spreading the Lightbloom are protected by a shield. We must stop them. We will also need to thin their numbers. Get on the petalwing, <name>, and let's clear the way.", ["objectivesText"] = "Ride on the Petalwing, destroy the shields protecting 4 Lightbloom Spreaders, and defeat Lightbloom creatures in the Blinding Bloom. Progress: We ride together!", ["rewardGold"] = 619600, ["rewardXP"] = 15215, ["rewardItems"] = { 253467 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3370, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 237356, ["x"] = 0.319333, ["y"] = 0.715333 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237356, ["x"] = 0.319333, ["y"] = 0.715333 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.319333, ["y"] = 0.715333 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86882 }, ["questLines"] = { { ["id"] = 5726, ["name"] = "Call of the Goddess", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5726, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86868] = { ["id"] = 86868, ["name"] = "Goodwill Tour", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2536, ["storyline"] = { 86652, 86708, 86710, 86711, 86712, 86715, 86716, 86717, 86718, 86719, 86720, 86721, 86722, 86723, 86868, 90749 }, ["description"] = "The situation here is far worse than I imagined. The Twilight's Blade and their leader, Mor'duun, have completely overrun this city. We will use this opportunity to show the Amani how efficient we are at eliminating forces of the Void. Perhaps that will help convince them to stall hostilities between our people... at least until the current threat has passed.", ["objectivesText"] = "Kill 10 Invading Shadows while traveling deeper into the city of Atal'Aman.", ["rewardGold"] = 325300, ["rewardXP"] = 12170, ["rewardItems"] = { 248551, 248552, 248553, 248554 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2536, ["npcID"] = 236485, ["x"] = 0.055, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 2536, ["npcID"] = 236570, ["x"] = 0.459, ["y"] = 0.484 } }, ["coords"] = { ["mapID"] = 2536, ["source"] = "quest_giver", ["x"] = 0.055, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 2536 }, ["zone"] = { 16194 } }, ["questType"] = "standard", ["sourceQuests"] = { 90749 }, ["questLines"] = { { ["id"] = 5722, ["name"] = "Dis Was Our Land", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5722, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 2437 },
[86869] = { ["id"] = 86869, ["name"] = "Phase Diving: Shan'dorah Saboteurs", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86869 }, ["objectivesText"] = "Enter Phase Diving Sabotage thwarted", ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.589, ["y"] = 0.287, ["mapID"] = 2371 } }, ["ends"] = { { ["x"] = 0.589, ["y"] = 0.287, ["mapID"] = 2371 } }, ["coords"] = { ["mapID"] = 2371, ["x"] = 0.589, ["y"] = 0.287 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15336 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Enter Phase Diving", ["amount"] = 1, ["type"] = 0, ["objectID"] = 238335, ["orderIndex"] = 0 }, { ["text"] = "Sabotage thwarted", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
