[86874] = { ["id"] = 86874, ["name"] = "Culling the Light", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86836, 86851, 86855, 86856, 86857, 86858, 86859, 86860, 86861, 86862, 86864, 86865, 86866, 86867, 86874, 86877, 86880, 86881, 86882, 86890, 94677 }, ["objectivesText"] = "Lightbloom curbed", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 237356, ["x"] = 0.319333, ["y"] = 0.715333 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237356, ["x"] = 0.319333, ["y"] = 0.715333 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.319333, ["y"] = 0.715333 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86867 }, ["questLines"] = { { ["id"] = 5726, ["name"] = "Call of the Goddess", ["orderIndex"] = 20, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5726, ["questLineOrder"] = 9 } }, ["db2Objectives"] = { { ["text"] = "Lightbloom curbed", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86877] = { ["id"] = 86877, ["name"] = "Righteous Pruning", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86836, 86851, 86855, 86856, 86857, 86858, 86859, 86860, 86861, 86862, 86864, 86865, 86866, 86867, 86874, 86877, 86880, 86881, 86882, 86890, 94677 }, ["description"] = "This is a threat that could destroy all of Harandar if left unchecked. That's why we will pull this out at the root. The ruutani who did not have the time to escape this place must be fully corrupted by now. Unfortunate, but it makes our plan of attack simple. Their leaders must be spreading the Lightbloom. We must strike them down.", ["objectivesText"] = "Kill 4 Lightblinded Sap Weavers in the Blinding Bloom. Progress: If these leaders are allowed to thrive, they will gather more forces to the Lightbloom. We can't allow that to happen.", ["rewardGold"] = 625600, ["rewardXP"] = 15215, ["rewardItems"] = { 256198, 256206, 256214, 256222 }, ["rewardChoices"] = { 256198, 256206, 256214, 256222 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3370, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 237356, ["x"] = 0.319333, ["y"] = 0.715333 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237356, ["x"] = 0.319333, ["y"] = 0.715333 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.319333, ["y"] = 0.715333 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86867 }, ["questLines"] = { { ["id"] = 5726, ["name"] = "Call of the Goddess", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5726, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86880] = { ["id"] = 86880, ["name"] = "Our Beloved, Returned", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86836, 86851, 86855, 86856, 86857, 86858, 86859, 86860, 86861, 86862, 86864, 86865, 86866, 86867, 86874, 86877, 86880, 86881, 86882, 86890, 94677 }, ["description"] = "The haranir had a presence by the roots of Shaladrassil, as a sign of goodwill with the cultures that live within our home. When the guards retreated, they left some of our treasured mementos and artifacts. Since the spread of the Lightbloom has been greater than I ever expected, I do not know when we'll be able to come back. Let's find those artifacts in the Blinding Bloom and bring them home.", ["objectivesText"] = "Recover 6 Haranir Artifacts in the Blinding Bloom. Progress: It would be good to bring some of these items back in our hands.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 238792 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 237356, ["x"] = 0.319333, ["y"] = 0.715333 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237356, ["x"] = 0.319333, ["y"] = 0.715333 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.319333, ["y"] = 0.715333 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86867 }, ["questLines"] = { { ["id"] = 5726, ["name"] = "Call of the Goddess", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5726, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86881] = { ["id"] = 86881, ["name"] = "At the Root", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86836, 86851, 86855, 86856, 86857, 86858, 86859, 86860, 86861, 86862, 86864, 86865, 86866, 86867, 86874, 86877, 86880, 86881, 86882, 86890, 94677 }, ["description"] = "The growths that help them spread the Lightbloom so quickly should be vulnerable after your attack from the air, but we still need to destroy them. Return to the Blinding Bloom and uproot the spreaders before they can recover from our attack.", ["objectivesText"] = "Destroy the Lightbloom Spreaders in the Blinding Bloom. Progress: We need to stop the spread of the Lightbloom, lest it take over all of Harandar .", ["rewardGold"] = 309800, ["rewardXP"] = 12170, ["rewardItems"] = { 35232, 35921, 35922, 35923, 35924, 38754, 38756, 39062, 39105, 61065, 61066, 61067, 65290, 65309, 65328, 65341, 65822, 65823, 65824, 84075, 84076, 84077, 84078, 84079, 131594, 182180, 184948, 184949, 184950, 184951, 184952, 184953, 184954, 184955, 184956, 186201, 186205, 186206, 187328, 187334, 187336, 187466, 209910, 249620, 249627, 251183, 251185, 251190, 251194, 251197, 251200, 256199, 256207, 256215, 256223, 263041, 263462, 263467, 264178 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 237356, ["x"] = 0.319333, ["y"] = 0.715333 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237356, ["x"] = 0.319333, ["y"] = 0.715333 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.319333, ["y"] = 0.715333 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86867 }, ["questLines"] = { { ["id"] = 5726, ["name"] = "Call of the Goddess", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5726, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86882] = { ["id"] = 86882, ["name"] = "Alndust in Right Hands", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86836, 86851, 86855, 86856, 86857, 86858, 86859, 86860, 86861, 86862, 86864, 86865, 86866, 86867, 86874, 86877, 86880, 86881, 86882, 86890, 94677 }, ["description"] = "We can now go to the roots of Shaladrassil and stop the Lightbloom spreading even further into Harandar . We have enough Alndust to inoculate any haranir who are willing to risk their lives to follow us into battle. Find them, $p, and give them the Alndust.", ["objectivesText"] = "Give Alndust to 5 haranir around Har'alnor and the Blinding Bloom. Progress: I know that my people are ready to step up to the challenge.", ["rewardGold"] = 309800, ["rewardXP"] = 12170, ["rewardItems"] = { 256197, 256205, 256213, 256221 }, ["rewardChoices"] = { 256197, 256205, 256213, 256221 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 237356, ["x"] = 0.319333, ["y"] = 0.715333 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237356, ["x"] = 0.319333, ["y"] = 0.715333 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.319333, ["y"] = 0.715333 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86866, 94677 }, ["questLines"] = { { ["id"] = 5726, ["name"] = "Call of the Goddess", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5726, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86883] = { ["id"] = 86883, ["name"] = "The Frenzied March", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86883, 86884, 86885, 86887, 86891, 86892, 86894, 86896, 86897, 86898 }, ["description"] = "Halduron's news is dire. If the Lightbloom is frenzying on the surface, then the danger has grown far more quickly than we were prepared to reckon with. We must make for Eversong at once. I will stand against any threat to Aln'hara's creation, be it here or in the world above... and I will do it alone, if I must.", ["objectivesText"] = "Return to Eversong Forest.", ["rewardGold"] = 34100, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3370, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 241742, ["x"] = 0.5, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 237361, ["x"] = 0.605333, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 2395, 2413 }, ["zone"] = { 15921 } }, ["questType"] = "standard", ["sourceQuests"] = { 86890 }, ["questLines"] = { { ["id"] = 5727, ["name"] = "Emergence", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5727, ["questLineOrder"] = 10 } }, ["db2PoiUiMapID"] = 2395 },
[86884] = { ["id"] = 86884, ["name"] = "Cull and Burn", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2395, ["storyline"] = { 86883, 86884, 86885, 86887, 86891, 86892, 86894, 86896, 86897, 86898 }, ["description"] = "Simply culling these creatures is not sufficient. If their bodies are left unattended, the Light will seep from their remains and spread through the soil to the surrounding foliage. We must take more drastic measures. Gather the bones of the creatures you slay. If we burn them, perhaps we can prevent their further spread through the roots of this forest.", ["objectivesText"] = "Collect 10 Corrupted Bones from Lightbloom-Infested wildlife. Progress: Do not delay. The longer we wait to cull this growth, the more of this forest the sin'dorei will lose.", ["rewardGold"] = 309800, ["rewardXP"] = 12170, ["rewardItems"] = { 238196, 256224, 256225 }, ["rewardChoices"] = { 256224, 256225 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 237361, ["x"] = 0.605333, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 237361, ["x"] = 0.605333, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.605333, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86883 }, ["questLines"] = { { ["id"] = 5727, ["name"] = "Emergence", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5727, ["questLineOrder"] = 10 } }, ["db2PoiUiMapID"] = 2395 },
[86885] = { ["id"] = 86885, ["name"] = "Stem the Tides", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2395, ["storyline"] = { 86883, 86884, 86885, 86887, 86891, 86892, 86894, 86896, 86897, 86898 }, ["description"] = "When the Farstriders first discovered the Lightbloom, we thought it to be merely an aesthetic change--a small quirk of the Sunwell's influence. Would that we knew then what we know now. These Light-frenzied rootways must lead all the way back to Harandar . If we don't close them, it won't matter how many of these damned things I bring down. Close the rootways and we might have a fighting chance.", ["objectivesText"] = "Burn 5 Lightfrenzy Portalways. Progress: What are you waiting for? Every moment that passes, more of those things filter through. Our odds are scant enough as it is.", ["rewardGold"] = 335000, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 237465, ["x"] = 0.6085, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 237465, ["x"] = 0.6085, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.6085, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86883 }, ["questLines"] = { { ["id"] = 5727, ["name"] = "Emergence", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5727, ["questLineOrder"] = 10 } }, ["db2PoiUiMapID"] = 2395 },
[86887] = { ["id"] = 86887, ["name"] = "Expeditious Retreat", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2395, ["storyline"] = { 86883, 86884, 86885, 86887, 86891, 86892, 86894, 86896, 86897, 86898 }, ["description"] = "I have a way to stop the Lightbloom from spreading further through the forest, but it isn't exactly a delicate touch. Normally, I'd never dream of resorting to a controlled burn in such a healthy portion of Eversong... but the frenzy is spreading too quickly, and we are running out of options. I've sounded the retreat to my Farstriders, but some of them haven't responded. I need you to find any rangers in particularly sticky situations, and lend your aid in securing their escape.", ["objectivesText"] = "Rescue 3 Beleaguered Farstriders. Progress: We're short on time, <name>. I can't execute my plan if we have Farstriders still in the field.", ["rewardGold"] = 312800, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 237465, ["x"] = 0.6085, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 241130, ["x"] = 0.586, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.6085, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86884, 86885 }, ["questLines"] = { { ["id"] = 5727, ["name"] = "Emergence", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5727, ["questLineOrder"] = 10 } }, ["db2PoiUiMapID"] = 2395 },
[86890] = { ["id"] = 86890, ["name"] = "Tell the People What You Have Seen", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86836, 86851, 86855, 86856, 86857, 86858, 86859, 86860, 86861, 86862, 86864, 86865, 86866, 86867, 86874, 86877, 86880, 86881, 86882, 86890, 94677 }, ["description"] = "We may have stemmed the malignant growth, but we have so many more questions than answers. How did this happen? How did this grow so much? How did Ruia not understand the extent of the calamity? $p, we must return to the Cradle immediately. The elders must know what happened today.", ["objectivesText"] = "Return to the Den to speak to the Elders. Progress: I only pray that they are more receptive to the truth this time around.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 256228, 256229 }, ["rewardChoices"] = { 256228, 256229 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3370, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 237356, ["x"] = 0.319333, ["y"] = 0.715333 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 241742, ["x"] = 0.5, ["y"] = 0.542 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.319333, ["y"] = 0.715333 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86877, 86880, 86881 }, ["questLines"] = { { ["id"] = 5726, ["name"] = "Call of the Goddess", ["orderIndex"] = 19, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5726, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86891] = { ["id"] = 86891, ["name"] = "A Last Resort", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86883, 86884, 86885, 86887, 86891, 86892, 86894, 86896, 86897, 86898 }, ["description"] = "With our ground forces pulled back, our position will be overwhelmed in a matter of minutes. It's time to execute our gambit. Rommath and the Magisters have provided us a mana gem that can be used to overload Lash'ra's runestones. Take it, and infuse the stones with the mana contained therein. That will set the stage for the Magisters' ritual: to detonate the runestones and burn the entirety of Lash'ra to the ground. We just have to hope the Lightbloom cannot survive in an inferno.", ["objectivesText"] = "Overload 3 Phoenixfire Runestones.", ["rewardGold"] = 335000, ["rewardXP"] = 12170, ["rewardItems"] = { 254878 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 237465, ["x"] = 0.6085, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 241130, ["x"] = 0.586, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.6085, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86884, 86885 }, ["questLines"] = { { ["id"] = 5727, ["name"] = "Emergence", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5727, ["questLineOrder"] = 10 } }, ["db2PoiUiMapID"] = 2395 },
[86892] = { ["id"] = 86892, ["name"] = "Survive", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86883, 86884, 86885, 86887, 86891, 86892, 86894, 86896, 86897, 86898 }, ["description"] = "Our retreat to safer ground has not gone unnoticed. The rutaani mark us at every turn, and now they mean to cross the river. We have to buy Rommath and the Magisters as much time as we can. If we fail here, the whole of Eversong could be lost. Stand tall. Do not falter. And do your best not to die.", ["objectivesText"] = "Survive the Lightbloom onslaught. Progress: We do not know when the frenzy will push past the lakeshore and encroach upon our position. Better to have Rommath start the ritual sooner rather than later.", ["rewardGold"] = 670000, ["rewardXP"] = 15215, ["rewardItems"] = { 256192, 256200, 256208, 256216 }, ["rewardChoices"] = { 256192, 256200, 256208, 256216 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3370, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 237361, ["x"] = 0.605333, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 237361, ["x"] = 0.605333, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.605333, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86887, 86891 }, ["questLines"] = { { ["id"] = 5727, ["name"] = "Emergence", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5727, ["questLineOrder"] = 10 } }, ["db2PoiUiMapID"] = 2395 },
[86894] = { ["id"] = 86894, ["name"] = "The Gift of Aln'hara", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86883, 86884, 86885, 86887, 86891, 86892, 86894, 86896, 86897, 86898 }, ["description"] = "Ruia has always been a zealous advocate, but this behavior is beyond the pale. The Lightbloom must be affecting him, driving him to these dangerous lengths. But we do not have to be like him. This forest need not fall to the bloom like Shaladrassil's roots did. The Hara'ti brought enough Alndust to bolster our allies against corruption, and prevent the frenzy from spreading further. Together, you and I shall spread Aln'hara's gift across the forest. This frenzy shall advance no further.", ["objectivesText"] = "Use the Alndust to combat the Lightbloom frenzy in Lightbloom Lash'ra. Progress: Alndust is no mere common reagent. We must be precious about its use. For my people, though, I will not hesitate to give all I have.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 237361, ["x"] = 0.605333, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 237361, ["x"] = 0.605333, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.605333, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86892 }, ["questLines"] = { { ["id"] = 5727, ["name"] = "Emergence", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5727, ["questLineOrder"] = 10 } }, ["db2PoiUiMapID"] = 2395 },
[86896] = { ["id"] = 86896, ["name"] = "Light Finds a Way", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86883, 86884, 86885, 86887, 86891, 86892, 86894, 86896, 86897, 86898 }, ["description"] = "I am an expert in the fauna of Eversong, and I can say with certainty that the vast majority of the wildlife here tend to be of fairly average size. But these Light-frenzied saptors are decidedly, unequivocally not. One bite from those thorny jaws could claim the lives of half a dozen Farstriders, if they are caught unawares. My rangers have their quivers full culling the chaff alongside the haranir. See to it that those towering tyrannosaptors don't catch them unawares.", ["objectivesText"] = "Slay 3 Lightfrenzy Tyrannosaptors in Lightbloom Lash'ra.", ["rewardGold"] = 309800, ["rewardXP"] = 12170, ["rewardItems"] = { 247234, 254878 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 241130, ["x"] = 0.586, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 237465, ["x"] = 0.6085, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86892 }, ["questLines"] = { { ["id"] = 5727, ["name"] = "Emergence", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5727, ["questLineOrder"] = 10 } }, ["db2PoiUiMapID"] = 2395 },
[86897] = { ["id"] = 86897, ["name"] = "Quelling the Frenzy", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2395, ["storyline"] = { 86883, 86884, 86885, 86887, 86891, 86892, 86894, 86896, 86897, 86898 }, ["description"] = "The day is nearly won. The sin'dorei cull every new sprout that blooms, and the Hara'ti ward the surrounding wilds against the frenzy's influence. All that yet remains is to remove this lightbound serpent's misguided head. Rootwarden Ruia has opposed our every action and shouted down our every word. But he is still a Rootwarden, and one with the power of a frenzying Lightbloom host at his beck and call. He is strong. But he does not walk with Aln'hara. It is time to end this.", ["objectivesText"] = "Confront Lightwarden Ruia .", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 252957, 259896 }, ["rewardChoices"] = { 252957, 259896 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3370, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 237361, ["x"] = 0.605333, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 241704, ["x"] = 0.584, ["y"] = 0.554 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.605333, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86894, 86896 }, ["questLines"] = { { ["id"] = 5727, ["name"] = "Emergence", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5727, ["questLineOrder"] = 10 } }, ["db2PoiUiMapID"] = 2395 },
[86898] = { ["id"] = 86898, ["name"] = "Rise of the Haranir", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2395, ["storyline"] = { 86883, 86884, 86885, 86887, 86891, 86892, 86894, 86896, 86897, 86898 }, ["description"] = "It is done. The frenzy is routed, the Rootwarden has fled, and the sin'dorei have reclaimed control of their forests. I can scarcely believe it, but... we succeeded, <name>. By Aln'hara's grace, we found a path forward. Now Halduron's people invite us to their den. I am not fond of your surface-cities, but... You have aided me so many times, my friend. It is time that the Hara'ti reached out hands of our own.", ["objectivesText"] = "Meet Orweyna and Halduron in the Gardens of Remembrance in Silvermoon City.", ["rewardGold"] = 154900, ["rewardXP"] = 6085, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3370, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 241704, ["x"] = 0.584, ["y"] = 0.554 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 255822, ["x"] = 0.365, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.554 }, ["mapCandidates"] = { ["npc"] = { 2393, 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86897 }, ["questLines"] = { { ["id"] = 5727, ["name"] = "Emergence", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5727, ["questLineOrder"] = 10 } }, ["db2PoiUiMapID"] = 2393 },
[86899] = { ["id"] = 86899, ["name"] = "The Root Cause", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2395, ["storyline"] = { 86899, 86900, 86901, 86907, 86910, 86911, 86912, 86913, 86914, 86929, 86930, 86942, 86944, 86956, 86973, 89034, 89402, 90094, 90095 }, ["series"] = { 86900, 89402 }, ["description"] = "The rutaani who attacked Silvermoon come from my homeland, Harandar . This Lightbloom infection is new, however. The time has come for me to return to my people. I will face their judgement, and explain my actions. If the Lightbloom has spread, I must warn my people of the danger. If you're willing to join me, I will take you and your insistent friend through the rootways to Harandar . Let me know when you are ready to go.", ["objectivesText"] = "Take the portal and meet Orweyna in Harandar .", ["rewardGold"] = 34100, ["rewardXP"] = 1520, ["rewardItems"] = { 35921, 35922, 35923, 35924 }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236704, ["x"] = 0.453333, ["y"] = 0.459333 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237480, ["x"] = 0.756, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.453333, ["y"] = 0.459333 }, ["mapCandidates"] = { ["npc"] = { 2395, 2413 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 89402 }, ["questLines"] = { { ["id"] = 5725, ["name"] = "Of Caves and Cradles", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5725, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86900] = { ["id"] = 86900, ["name"] = "To Har'athir", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86899, 86900, 86901, 86907, 86910, 86911, 86912, 86913, 86914, 86929, 86930, 86942, 86944, 86956, 86973, 89034, 89402, 90094, 90095 }, ["series"] = { 86899, 89402 }, ["description"] = "All of the world's roots grow toward our homeland. The ones above you are mighty, but new--born of a fledgling World Tree you call Amirdrassil. As far as World Trees go, it is a strange one. But its nature matters less than its reach. Any roots that seek to protect our world from harm are worth protecting. Let us follow the road down to Har'athir and check in with the Rootwarden. We will ask if he's noticed signs of Lightbloom yet.", ["objectivesText"] = "Follow Orweyna into Harandar .", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 256226, 256227 }, ["rewardChoices"] = { 256226, 256227 }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 237480, ["x"] = 0.756, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 239525, ["x"] = 0.7, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.756, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86899 }, ["questLines"] = { { ["id"] = 5725, ["name"] = "Of Caves and Cradles", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5725, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86901] = { ["id"] = 86901, ["name"] = "The Rift and the Den", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86899, 86900, 86901, 86907, 86910, 86911, 86912, 86913, 86914, 86929, 86930, 86942, 86944, 86956, 86973, 89034, 89402, 90094, 90095 }, ["series"] = { 86907, 86911, 86929, 90094 }, ["description"] = "As I suspected, the elders are quite upset with my actions. Now that I have seen the children and Ku'paal to safety, I am ready to face the Council. I will do what I can to make them see that the Lightbloom is a threat, and to enable your ability to move freely through Harandar . Petalvane will carry you safely to the Den. Let us make haste.", ["objectivesText"] = "Ride Petalvane to the Den.", ["rewardGold"] = 34100, ["rewardXP"] = 1520, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 237483, ["x"] = 0.7, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237345, ["x"] = 0.548, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86900 }, ["questLines"] = { { ["id"] = 5725, ["name"] = "Of Caves and Cradles", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5725, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86902] = { ["id"] = 86902, ["name"] = "Relinquishing Relics", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2424, ["storyline"] = { 86837, 86838, 86839, 86840, 86841, 86842, 86843, 86844, 86845, 86846, 86902, 89193, 89338, 91000, 92136 }, ["description"] = "My staff bought us time in the effort to hold back the Void, but these relics will be a more powerful aid. Let us hope it will be enough. Quickly, deliver these relics to our friends.", ["objectivesText"] = "Distribute relics to Taelia, Valunei , Salandria , and Mehlar. Progress: Did you get those relics out to everyone, <name>?", ["rewardGold"] = 335000, ["rewardXP"] = 12170, ["rewardItems"] = { 257240 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2424, ["npcID"] = 251355, ["x"] = 0.525333, ["y"] = 0.556667 } }, ["ends"] = { { ["mapID"] = 2424, ["npcID"] = 251355, ["x"] = 0.525333, ["y"] = 0.556667 } }, ["coords"] = { ["mapID"] = 2424, ["source"] = "quest_giver", ["x"] = 0.525333, ["y"] = 0.556667 }, ["mapCandidates"] = { ["npc"] = { 2424 }, ["zone"] = { 16215 } }, ["questType"] = "standard", ["sourceQuests"] = { 92136 }, ["questLines"] = { { ["id"] = 5750, ["name"] = "The Path of Light", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5750, ["questLineOrder"] = 11 } }, ["db2PoiUiMapID"] = 2424 },
[86903] = { ["id"] = 86903, ["name"] = "The Arcantina", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 86822, 86823, 86824, 86825, 86826, 86827, 86828, 86829, 86830, 86831, 86832, 86833, 86903, 91391, 91726, 91787, 91842 }, ["description"] = "$p, there's a place that we used during the Second War, when we missed our homes an' needed to remember Azeroth. Somethin' of a retreat an' a sanctuary for those who've seen too much fighting--too much pain. Over time, we've brought friends and allies there. In recent years, members o' the Horde have been invited as well. We call it the Arcantina. I believe Arator , and you, would benefit from some respite there. Use this key to make a portal.", ["objectivesText"] = "Visit the Arcantina. Progress: This really is quite the place, isn't it, <name>?", ["rewardGold"] = 670000, ["rewardXP"] = 15215, ["rewardItems"] = { 248131, 253629, 254838 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3365, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 253125, ["x"] = 0.405, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 253125, ["x"] = 0.405, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questTurnInID"] = 253125, ["questType"] = "standard", ["sourceQuests"] = { 86833 }, ["questLines"] = { { ["id"] = 5751, ["name"] = "Regrets of the Past", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5751, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 2195, ["db2PoiUiMapID"] = 2541 },
[86905] = { ["id"] = 86905, ["name"] = "No More Sick Days", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15524, ["mapID"] = 2351, ["storyline"] = { 86905 }, ["description"] = "When we started clearin' out this forest we expected some trouble from the local wildlife but we never expected to be set upon by diseased animals! My work crew keeps gettin' sick and takin' time off to recover. Obviously this is messin' with our bottom line, so perhaps you could clear out some of the creatures so we can start work again? When you're done see my assistant for payment.", ["objectivesText"] = "Clear out 8 diseased creatures .", ["rewardGold"] = 292100, ["rewardXP"] = 9515, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15524 } }, ["questType"] = "standard" },
[86907] = { ["id"] = 86907, ["name"] = "The Den of Echoes", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86899, 86900, 86901, 86907, 86910, 86911, 86912, 86913, 86914, 86929, 86930, 86942, 86944, 86956, 86973, 89034, 89402, 90094, 90095 }, ["series"] = { 86901, 86911, 86929, 90094 }, ["description"] = "Greetings, stranger. I am Elder Hagar . You have been granted permission to stay, as long as you pass through the trials of the Den of Echoes. Aln'hara will determine your fate, and you will learn about our people and customs. Let us meet at the caves.", ["objectivesText"] = "Meet Hagar at the Den of Echoes.", ["rewardGold"] = 34100, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3370, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 237332, ["mapID"] = 2576, ["x"] = 0.437733, ["y"] = 0.542712 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237567, ["x"] = 0.388, ["y"] = 0.468 }, { ["npcID"] = 237332, ["mapID"] = 2576, ["x"] = 0.437733, ["y"] = 0.542712 } }, ["coords"] = { ["source"] = "quest_giver", ["mapID"] = 2576, ["x"] = 0.437733, ["y"] = 0.542712 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15921 } }, ["questType"] = "standard", ["sourceQuests"] = { 86929 }, ["questLines"] = { { ["id"] = 5725, ["name"] = "Of Caves and Cradles", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5725, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86909] = { ["id"] = 86909, ["name"] = "Unrestful Spirits", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86909 }, ["rewardGold"] = 319000, ["rewardXP"] = 12170, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15355 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86910] = { ["id"] = 86910, ["name"] = "Koozat's Trample", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86899, 86900, 86901, 86907, 86910, 86911, 86912, 86913, 86914, 86929, 86930, 86942, 86944, 86956, 86973, 89034, 89402, 90094, 90095 }, ["description"] = "Koozat is usually very docile. This isn't like him at all. Please, find out what happened.", ["objectivesText"] = "Follow Orweyna . Progress: Koozat is not usually a violent creature.", ["rewardGold"] = 33500, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3370, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 237572, ["x"] = 0.348, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 240533, ["x"] = 0.356, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.348, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86914, 86956 }, ["questLines"] = { { ["id"] = 5725, ["name"] = "Of Caves and Cradles", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5725, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86911] = { ["id"] = 86911, ["name"] = "Echoes and Memories", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86899, 86900, 86901, 86907, 86910, 86911, 86912, 86913, 86914, 86929, 86930, 86942, 86944, 86956, 86973, 89034, 89402, 90094, 90095 }, ["series"] = { 86901, 86907, 86929, 90094 }, ["description"] = "The history of the haranir has been recorded for tens of thousands of years in the caves within. The memories of our people are painted on the stone, that we might never forget where we came from and what our purpose is. You are the first outsiders to ever witness the Den of Echoes. When you touch the paintings, our ancestors will share our stories and struggles. Zur'ashar Kassameh awaits you within. He will guide you and Halduron on your journeys. I wish you luck.", ["objectivesText"] = "Complete the first vision of the Den of Echoes. Progress: Our people have been here for tens of thousands of years, but it was not always so. Once, we lived on the surface as you do.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 239014, 246415 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 237567, ["x"] = 0.388, ["y"] = 0.468 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 239650, ["x"] = 0.36, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.468 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86907 }, ["questLines"] = { { ["id"] = 5725, ["name"] = "Of Caves and Cradles", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5725, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86912] = { ["id"] = 86912, ["name"] = "Down the Rootways", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86899, 86900, 86901, 86907, 86910, 86911, 86912, 86913, 86914, 86929, 86930, 86942, 86944, 86956, 86973, 89034, 89402, 90094, 90095 }, ["description"] = "You have gained a glimpse into our history. There is one trial yet remaining. If you survive, the goddess's blessing will be upon you, and the Council will not be able to deny your presence here. Descend now into the earth and follow in our ancestors' footsteps.", ["objectivesText"] = "Complete the Gulf of Memories delve and obtain the Fragment of Revelation from its treasure room. Progress: You have survived the Gulf of Memories. Welcome to Har'mara, friend.", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 249620, 249627, 251512 }, ["rewardChoices"] = { 249620, 249627 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 243884, ["x"] = 0.34, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 240839, ["x"] = 0.348, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90095 }, ["questLines"] = { { ["id"] = 5725, ["name"] = "Of Caves and Cradles", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5725, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86913] = { ["id"] = 86913, ["name"] = "A Hut in Har'mara", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86899, 86900, 86901, 86907, 86910, 86911, 86912, 86913, 86914, 86929, 86930, 86942, 86944, 86956, 86973, 89034, 89402, 90094, 90095 }, ["description"] = "The others have gathered downstairs. Come. Orweyna is eager to see that you are in one piece.", ["objectivesText"] = "Meet Orweyna in Har'mara.", ["rewardGold"] = 31900, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3370, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 240839, ["x"] = 0.348, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237786, ["x"] = 0.348, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.348, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86912 }, ["questLines"] = { { ["id"] = 5725, ["name"] = "Of Caves and Cradles", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5725, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86914] = { ["id"] = 86914, ["name"] = "Tending to Har'mara", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86899, 86900, 86901, 86907, 86910, 86911, 86912, 86913, 86914, 86929, 86930, 86942, 86944, 86956, 86973, 89034, 89402, 90094, 90095 }, ["description"] = "Har'mara has long been a refuge for those who have removed themselves from the conflicts that often arise between the rutaani and the fungarians. Here, they learn how to live with one another. They work, play, and live together--balanced. You have learned much about the past of the haranir, including our deepest shame. Now you will see our current work: harmony.", ["objectivesText"] = "Complete tasks in Har'mara. Progress: It is the natural state of the fungarians and the rutaani to spread themselves out. At times, this can lead to overgrowth and the crowding out of other species. Maintaining that balance is important, and is the duty the haranir fulfill as stewards of Harandar .", ["rewardGold"] = 319000, ["rewardXP"] = 12170, ["rewardItems"] = { 238024, 256174, 256175, 256177, 256180, 256184, 256186, 256188, 256190, 256231, 269982 }, ["rewardChoices"] = { 256174, 256175, 256177, 256180, 256184, 256186, 256188, 256190, 256231, 269982 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 237572, ["x"] = 0.348, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237572, ["x"] = 0.348, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.348, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86913 }, ["questLines"] = { { ["id"] = 5725, ["name"] = "Of Caves and Cradles", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id