[86930] = { ["id"] = 86930, ["name"] = "To Sow the Seed", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86899, 86900, 86901, 86907, 86910, 86911, 86912, 86913, 86914, 86929, 86930, 86942, 86944, 86956, 86973, 89034, 89402, 90094, 90095 }, ["description"] = "Eonka's seed from Rift of Aln is the clue we were looking for. The inhabitants and plants there seem immune to the Lightbloom! We must investigate the rift for ourselves. Let us return to the Den and plan our next moves.", ["objectivesText"] = "Return to the Den.", ["rewardGold"] = 335000, ["rewardXP"] = 12170, ["rewardItems"] = { 256195, 256203, 256211, 256219 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3370, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 237786, ["x"] = 0.348, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237786, ["x"] = 0.348, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.348, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questTurnInID"] = 237786, ["questType"] = "standard", ["sourceQuests"] = { 86944 }, ["questLines"] = { { ["id"] = 5725, ["name"] = "Of Caves and Cradles", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5725, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[86934] = { ["id"] = 86934, ["name"] = "Trash to Profit", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 86934, 86935 }, ["description"] = "Ey! I heard you've been cleanin' up some of the trash around Undermine . Good on ya. Any interest in takin' that more literally? It's a dirty job, but lots of gold to be made if you're good at it. If that sounds up your alley, go talk to the boss man Carlo back at Undermine Sanitation. Tell him I sent ya so I get my recruitment bonus!", ["objectivesText"] = "Talk to Carlo Greasegrind at Undermine Sanitation.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 237649, ["x"] = 0.428, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 237659, ["x"] = 0.266, ["y"] = 0.374667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5776, ["name"] = "Trashy Business", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346, ["db2QuestHubAreaPoiID"] = 8189 },
[86935] = { ["id"] = 86935, ["name"] = "On-the-Job Training", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 86934, 86935 }, ["description"] = "If you're lookin' for work, S.C.R.A.P. is always hirin'. That's short for \"Salvage, Cleanup, and Recl-Amation Patrol.\" We go around Undermine shovelin' up trash and pickin' out the good bits. Valuables get brought back here, cleaned up, and resold to whoever's buyin'. Find somethin' useful and my man Angelo will trade you for it. Go check out what he's got in stock, then find me out in the field and I'll show you the ropes. But I mean, it's trash shovelin', not rocket surgery.", ["objectivesText"] = "Check out Angelo Rustbin's wares inside Undermine Sanitation, then complete a S.C.R.A.P. job in Undermine . Progress: You might wanna invest in some eye protection. Or at least some really thick gloves. Maybe nose plugs.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 237659, ["x"] = 0.266, ["y"] = 0.374667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 237659, ["x"] = 0.266, ["y"] = 0.374667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.266, ["y"] = 0.374667 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 86934 }, ["questLines"] = { { ["id"] = 5776, ["name"] = "Trashy Business", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[86936] = { ["id"] = 86936, ["name"] = "Warped Wood", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15524, ["mapID"] = 2351, ["storyline"] = { 86936 }, ["description"] = "Our shredders were cuttin' down trees in this area to make room for new homes when they suddenly uprooted and started causin' all kinds of havoc! As if all these diseased animals weren't bad enough, those trees seem hell bent on preventing us from completing this job. If you could clear out a few it would really help speed up our construction efforts.", ["objectivesText"] = "Kill 3 Rotting Treants", ["rewardGold"] = 292100, ["rewardXP"] = 9515, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15524 } }, ["questType"] = "standard" },
[86937] = { ["id"] = 86937, ["name"] = "Healthy Home Certified", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15524, ["mapID"] = 2351, ["storyline"] = { 86937 }, ["description"] = "We think we've found the source for all this disease nonsense and wouldn't ya believe it -- a blasted satyr. I hate these guys, always showin' up in places I want to harvest for precious resources. Do us a favor and get rid of him? As always, see my assistant for payment.", ["objectivesText"] = "Kill the Xarn Felhoof", ["rewardGold"] = 468000, ["rewardXP"] = 11895, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15524 } }, ["questType"] = "standard" },
