[86942] = { ["id"] = 86942, ["name"] = "Culling the Spread", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86899, 86900, 86901, 86907, 86910, 86911, 86912, 86913, 86914, 86929, 86930, 86942, 86944, 86956, 86973, 89034, 89402, 90094, 90095 }, ["description"] = "Powdercap said that the visiting travelers were the first to show signs of the Lightbloom infection--right after you questioned them! Sadly, it seems Koozat has also fallen to the sickness. Take out the merchants and see to Koozat as well. He's far too dangerous a creature to be trampling around here.", ["objectivesText"] = "Slay the visiting rutaani merchants and Koozat . Progress: I raised Koozat since he was small enough to fit in my hands. The Lightbloom does not discriminate who it infects.", ["rewardGold"] = 638000, ["rewardXP"] = 15215, ["rewardItems"] = { 256194, 256202, 256210, 256218 }, ["rewardChoices"] = { 256194, 256202, 256210, 256218 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3370, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 240533, ["x"] = 0.356, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 240533, ["x"] = 0.356, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86910 }, ["questLines"] = { { ["id"] = 5725, ["name"] = "Of Caves and Cradles", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5725, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
