[86944] = { ["id"] = 86944, ["name"] = "Seeds of the Rift", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86899, 86900, 86901, 86907, 86910, 86911, 86912, 86913, 86914, 86929, 86930, 86942, 86944, 86956, 86973, 89034, 89402, 90094, 90095 }, ["description"] = "The situation is stabilizing, but let's make sure we're in the clear. I will see how Hagar is faring. Check on Eonka again and be sure that she's not showing any signs of Lightbloom. She is on an upper level in Hagar's Hut.", ["objectivesText"] = "Check on Eonka . Progress: Let us hope Eonka is unchanged.", ["rewardGold"] = 31900, ["rewardXP"] = 1520, ["rewardItems"] = { 258623 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3370, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 240533, ["x"] = 0.356, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237786, ["x"] = 0.348, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86942, 86973, 89034 }, ["questLines"] = { { ["id"] = 5725, ["name"] = "Of Caves and Cradles", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5725, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
