[86946] = { ["id"] = 86946, ["name"] = "Unwrapped and Unraveled", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 83126, 83127, 83128, 83129, 84856, 84857, 84862, 84863, 84864, 84865, 84866, 84967, 85037, 85449, 85450, 86495, 86820, 86946, 90517, 91871, 93979 }, ["description"] = "Seeing you two on the battlefield was beautiful. It really is wonderful watching you work. If only your so-called friends had trusted you with the truth of their actions so long ago. Locus-Walker hasn't tried to deceive you with his actions in the present, though his actions in the past that led us to this point... he has been less than forthcoming about. In all good conscience, I cannot continue hiding the truth from you or Alleria.", ["objectivesText"] = "Find Alleria before she confronts Locus-Walker.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 237705, ["x"] = 0.542, ["y"] = 0.454 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 242538, ["x"] = 0.47, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.454 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 84866 }, ["questLines"] = { { ["id"] = 5733, ["name"] = "Void Alliance", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrde