[86956] = { ["id"] = 86956, ["name"] = "The Traveling Flowers", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86899, 86900, 86901, 86907, 86910, 86911, 86912, 86913, 86914, 86929, 86930, 86942, 86944, 86956, 86973, 89034, 89402, 90094, 90095 }, ["description"] = "Orweyna mentioned that there are rutaani who are visiting from other villages. This is an opportunity for us to get to know what they're like when they're not Light-crazed. I will stay here to speak with Meeka. You should speak with the visiting rutaani to determine whether the Lightbloom has reached their homes.", ["objectivesText"] = "Talk to the visiting rutaani merchants. Progress: We must stop the spread of the Lightbloom! Determining its spread will help us fight it in the long run.", ["rewardGold"] = 251200, ["rewardXP"] = 9130, ["rewardItems"] = { 262614 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 237787, ["x"] = 0.348, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237787, ["x"] = 0.348, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.348, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86913 }, ["questLines"] = { { ["id"] = 5725, ["name"] = "Of Caves and Cradles", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5725, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
