[86960] = { ["id"] = 86960, ["name"] = "The Key to Good Health", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["storyline"] = { 86960 }, ["description"] = "I'm supposed to be the assigned health advisor for this job but somehow I'm the one who ended up getting sick! I have antidotes in this chest but I lost the key and I suspect one of the local wildlife ate it in the aftermath of being attacked. Be a pal and see if you can find it?", ["objectivesText"] = "Find a key to open the chest and retrieve the antidote.", ["rewardGold"] = 292100, ["rewardXP"] = 9515, ["rewardItems"] = { 235708, 235714 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[86961] = { ["id"] = 86961, ["name"] = "Diversified Investments", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 86961 }, ["description"] = "<The letter is simply addressed to \"The <class> who took down Gallywix.\" It takes you a frustrating amount of time to rip open the multiple layers of duct tape sealing the envelope shut.> Hey bud, You've been gettin' a reputation for yourself. Not afraid to roll up your sleeves and get down to business. Certain people really value that kind of thing. Let's talk shop. Meet me in my warehouse and maybe we can agree on a business partnership.", ["objectivesText"] = "Find your prospective \"business partner\" and speak to them.", ["starts"] = { { ["x"] = 0.433, ["y"] = 0.515, ["mapID"] = 2346, ["objectID"] = 509486 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231396, ["x"] = 0.305, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.305, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 86204 } },
