[86973] = { ["id"] = 86973, ["name"] = "Halting Harm in Har'mara", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86899, 86900, 86901, 86907, 86910, 86911, 86912, 86913, 86914, 86929, 86930, 86942, 86944, 86956, 86973, 89034, 89402, 90094, 90095 }, ["description"] = "Lightbloom-infected rutaani are attacking the village! Rizam and Teetem both succumbed to the infection. It looks like Eonka hasn't been affected, but we must handle the others. I will stay here and keep an eye on her. I need you to do what you can to protect Har'mara. Take out Rizam and Teetem as well.", ["objectivesText"] = "Slay 8 Lightbloom rutaani.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 245535 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 240533, ["x"] = 0.356, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 240533, ["x"] = 0.356, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86910 }, ["questLines"] = { { ["id"] = 5725, ["name"] = "Of Caves and Cradles", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5725, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
