[86997] = { ["id"] = 86997, ["name"] = "Spellbook Scuffle", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16173, ["mapID"] = 2395, ["storyline"] = { 86997, 86998, 87002, 94396 }, ["description"] = "You there! I've heard whispers of your so-called \"heroics,\" but I'm convinced they must be false. For if they were true, it would mean you would have achieved more than I, Tytalor Goldenblade --the finest, smartest, and most handsome mage at this academy. Therefore, I challenge you to prove your worth, if you are not a coward. The arcane tomes will make a fine warm-up for you... if you survive. Tear out their pages and prove you're not a complete fraud.", ["objectivesText"] = "Collect 9 Torn Spellbook Pages from Arcane Tomes in Sunstrider Isle. Progress: Well? Are the pages in your possession, or will you admit your deception?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 235808 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 237873, ["x"] = 0.394, ["y"] = 0.174 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 237904, ["x"] = 0.384, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.174 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 94396 }, ["questLines"] = { { ["id"] = 5781, ["name"] = "Aspiring Academic", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[86998] = { ["id"] = 86998, ["name"] = "Training Arc", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16173, ["mapID"] = 2395, ["storyline"] = { 86997, 86998, 87002, 94396 }, ["description"] = "Hah! You actually managed to defeat the spell books? I suppose even a blind squirrel finds a nut once in a while. Don't get too proud of yourself though! My followers ahead won't be so easily dismantled by your flailing. When you inevitably fail, I'll be sure to remember this as the moment your arrogance got the better of you.", ["objectivesText"] = "Best 6 mages in Sunstrider Isle. Progress: Ah! So you've come crawling back after failing to defeat even my least competent followers?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 237904, ["x"] = 0.384, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 237905, ["x"] = 0.379, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.384, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86997 }, ["questLines"] = { { ["id"] = 5781, ["name"] = "Aspiring Academic", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[87000] = { ["id"] = 87000, ["name"] = "No Wood Left Behind", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15524, ["mapID"] = 2351, ["storyline"] = { 87000 }, ["description"] = "When we were attacked by the local fauna we had to leave behind much of the wood we already harvested. While we are waitin' for you to take care of our little animal problem, we could be turnin' those logs into planks to get a head start on our buildin' efforts. If you can bring me back any I'd sure appreciate it pal.", ["objectivesText"] = "Collect 8 wood logs.", ["rewardGold"] = 292100, ["rewardXP"] = 9515, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15524 } }, ["questType"] = "standard" },
[87001] = { ["id"] = 87001, ["name"] = "Warrant: Shatterpulse", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87001 }, ["series"] = { 90124 }, ["description"] = "The horrifying monstrosity known as Shatterpulse lies hidden in a stasis cell at Shadowpoint. It is not kept as a prisoner, but as a weapon to be unleashed upon us when we are least prepared. Create a key to open Shatterpulse's stasis cell revealing this threat to everyone.", ["objectivesText"] = "Collect a Calculation Container , Marking Matrix and some Void Fused Resin to create a key. Progress: Combine the items to form the Stasis Cell Key.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235866, 235913, 235982, 235983, 236353 }, ["starts"] = { { ["x"] = 0.485, ["y"] = 0.586, ["mapID"] = 2472, ["npcID"] = 238265 } }, ["ends"] = { { ["x"] = 0.485, ["y"] = 0.586, ["mapID"] = 2472, ["npcID"] = 238265 } }, ["coords"] = { ["mapID"] = 2472, ["x"] = 0.485, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15336 } }, ["questGiverID"] = 238265, ["questTurnInID"] = 238265, ["questType"] = "standard", ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2472, ["startItems"] = { 235983 } },
[87002] = { ["id"] = 87002, ["name"] = "Academic Aspirations", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16173, ["mapID"] = 2395, ["storyline"] = { 86997, 86998, 87002, 94396 }, ["description"] = "How charming. You've actually made it this far thinking you've proven something. Let me make it clear--nothing you've done compares to my prowess. You've struggled through the simplest of challenges, but now you'll face me. Meet me at the top of this tower and I'll show you exactly how far beneath me you really are.", ["objectivesText"] = "Defeat Tytalor Goldenblade in Sunstrider Isle.", ["rewardGold"] = 683200, ["rewardXP"] = 14705, ["rewardItems"] = { 263324, 263325 }, ["rewardChoices"] = { 263324, 263325 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3365, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 237905, ["x"] = 0.379, ["y"] = 0.186 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 237907, ["x"] = 0.392, ["y"] = 0.172 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.379, ["y"] = 0.186 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86998 }, ["questLines"] = { { ["id"] = 5781, ["name"] = "Aspiring Academic", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[87008] = { ["id"] = 87008, ["name"] = "Ad-Hoc Wedding Planner", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83417, 83418, 83419, 83420, 83421, 85438, 87008 }, ["description"] = "Eeey, now that was a wedding worth talkin' about! You did okay. Everything went right and the only hitch was the one my little girl got. So we're good. I know the bride an' groom wanna say their thanks so go chat with them.", ["objectivesText"] = "Speak with Neenee and Vrizek . Progress: Ain't it great to see those two crazy kids hitched?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 245308 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226518, ["x"] = 0.2595, ["y"] = 0.4265 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226518, ["x"] = 0.2595, ["y"] = 0.4265 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.2595, ["y"] = 0.4265 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83421 }, ["questLines"] = { { ["id"] = 5642, ["name"] = "The Perfect Wedding", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[87010] = { ["id"] = 87010, ["name"] = "Calculation Container", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87010 }, ["description"] = "A Calculation Container is no easy feat to construct. I have not made one recently, as thieves have stolen the data rods I need to complete the task. If you can recover the rods, I could create one. Be warned! The rods are quite heavy and will take some effort to return them. I have been known to drop them quite easily.", ["objectivesText"] = "5 Weighty Variable Rod delivered to Engineer Om'loof Progress: Have you found what we need?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235866 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 238057, ["x"] = 0.48, ["y"] = 0.574 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 238057, ["x"] = 0.48, ["y"] = 0.574 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.574 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard" },
[87254] = { ["id"] = 87254, ["name"] = "Curse Cleanse", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["description"] = "Warlord Akutu could die at any moment, and you brought no pango liver? Bah! Each day I scream at Kulzi to tell me how to cure him. I say, \"you force me to use de forbidden liver ritual!\" But de loa says nothin'. Loa Speaker Sij'ta 's eyes seem angry but also afraid.> If he won't tell us what is wrong, then we will have to use de pango liver ritual. It is rumored to be a potent but forbidden ritual. Get de largest pango liver you can find. There is no time to waste.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 237953, ["x"] = 0.404, ["y"] = 0.494, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 237953, ["x"] = 0.404, ["y"] = 0.494, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.404, ["y"] = 0.494, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91206 }, ["questLines"] = { { ["id"] = 5778, ["name"] = "Healing the Spirit", ["orderIndex"] = 1, ["flags"] = 0 } } },
[87256] = { ["id"] = 87256, ["name"] = "Alternative Medicine", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 87254, 87256, 87267, 87268, 87317, 91206, 92531 }, ["description"] = "I can't leave de warlord's side. I swore an oath to Zul'jin himself to save de Amani warlords at any cost. If I leave, he is sure to die. He is already cold as death! If he weren't movin' and talkin', I'd swear he was already dead. There are things we can do without de loa's diagnosis. Bring me de bloodweed branches dat grow below de shrine. They're very important to de healin' rituals we can still do. Gather me a heap of dem.", ["objectivesText"] = "Collect Bloodweed Branches from shrubs below the Shrine of Kulzi. Progress: Dey must be pungent if dey gonna work.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 235912 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 237953, ["x"] = 0.404, ["y"] = 0.494 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 237953, ["x"] = 0.404, ["y"] = 0.494 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91206 }, ["questLines"] = { { ["id"] = 5778, ["name"] = "Healing the Spirit", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[87267] = { ["id"] = 87267, ["name"] = "Demands Unmet", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 87254, 87256, 87267, 87268, 87317, 91206, 92531 }, ["description"] = "Good, we have de branches. We will use them! Above us are de altars where we bring de injured to Kulzi for healin'... <Sij'ta looks very disoriented.> Wait. I already did this. I brought Akutu up there, an' laid him upon one of de altars. Dat is where he held my hand, made me swear to... What? Why can't I remember? You--you're here for a reason. Go get answers. If de loa appears, tell him he's gotta fix dis--or else!", ["objectivesText"] = "Confront Kulzi , the Loa of Medicine. Progress: Kulzi cannot keep ignorin' us!", ["rewardGold"] = 85400, ["rewardXP"] = 2940, ["rewardItems"] = { 246210 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3354, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 237953, ["x"] = 0.404, ["y"] = 0.494 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 237953, ["x"] = 0.404, ["y"] = 0.494 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 87254, 87256 }, ["questLines"] = { { ["id"] = 5778, ["name"] = "Healing the Spirit", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[87268] = { ["id"] = 87268, ["name"] = "Required Repentance", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 87254, 87256, 87267, 87268, 87317, 91206, 92531 }, ["description"] = "I remember dis staff. And I remember dat day. We are... dead, then. <Sij'ta seems to take in the realization with a sort of relief.> Akutu was near death from a battle in de city. He had some serious wounds. Kulzi said he could not heal dem. Akutu would not accept dis. He wanted me to use de staff--a hexlord staff--on Kulzi to force him to heal. And then... I think I broke it. Show de other spirits here dis staff. Maybe we can piece together what happened from their memories.", ["objectivesText"] = "Use the staff to aid Forgetful Ghosts in remembering what happened at the Shrine of Kulzi. Progress: Show dem de staff. See what dey remember.", ["rewardGold"] = 312800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 237953, ["x"] = 0.404, ["y"] = 0.494 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 237953, ["x"] = 0.404, ["y"] = 0.494 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 87267 }, ["questLines"] = { { ["id"] = 5778, ["name"] = "Healing the Spirit", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[87284] = { ["id"] = 87284, ["name"] = "A Radiant Echo", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 87284 }, ["description"] = "<Within your hand, you hold a small Azerite sphere. Its light is steady and bright, but the sound it emits is plaintive and longing. It tugs at you, ever so slightly.>", ["objectivesText"] = "Bring the Radiant Echo to a Worldsoul Memory, then release it.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235897 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14771 } }, ["questType"] = "standard", ["startItems"] = { 235896 } },
[87285] = { ["id"] = 87285, ["name"] = "Marking Matrix", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87285 }, ["description"] = "A Marking Matrix must be attuned to the frequency of the void energies wielded by the Shadowguard. You must obtain samples of that energy. My containment Trap is designed to capture Shadowguard and allow you to extract the void markings tied to their corrupted energies. With those markings I can create a matrix to help attune your creation to work on void powered constructs.", ["objectivesText"] = "8 Void Markings extracted from Shadowguard enemies. Progress: Have you finished the work?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 187684, 235898, 235913 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 238057, ["x"] = 0.48, ["y"] = 0.574 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 238057, ["x"] = 0.48, ["y"] = 0.574 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.574 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard" },
[87289] = { ["id"] = 87289, ["name"] = "Barreling Down", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Brewfest", ["expansion"] = 11, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 87289 }, ["description"] = "If it's ale ye be looking for, we've plenty to sample! Or at least we would if the dracthyr folk would hurry up and bring the rest of the barrels down here. Some o' the dracthyr folk have come to celebrate here with us and decided to help transport the ale. Rolling barrels? That's no way to treat a good brew! Mind lending a hand to bring those barrels over to Kharanos? And try not to break 'em!", ["objectivesText"] = "Deliver barrels to Kharanos. Progress: Careful with the barrels! Ye shouldn't jostle a good ale.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 37829 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 237987, ["x"] = 0.538, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 237987, ["x"] = 0.538, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 }, ["db2QuestSortName"] = "Epic" },
[87290] = { ["id"] = 87290, ["name"] = "The Oasis", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2472, ["storyline"] = { 87290, 87337, 87338, 87339, 87340 }, ["series"] = { 87337 }, ["description"] = "Hello again, <name>. Ve'nari asked me to find you. She asked that you meet her in the Oasis. I shall join you shortly. I have some errands to run here first.", ["objectivesText"] = "Travel to the Oasis in K'aresh.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 56840, 56841, 56842, 56843, 245611 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 238212, ["x"] = 0.395, ["y"] = 0.245 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 238209, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.245 }, ["mapCandidates"] = { ["npc"] = { 2371, 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 85037 }, ["questLines"] = { { ["id"] = 5780, ["name"] = "The Oasis", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5780, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[87291] = { ["id"] = 87291, ["name"] = "Salad Bar", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86349, 87291, 87292, 87293, 87294 }, ["series"] = { 87292 }, ["description"] = "Hemet, Om'talad, and I have been working together to see what we can do to help the lapbugs. It seems their original food source didn't make it through the collapse of K'aresh! Do you think you might be able to gather some prickleblooms and lustrous conkers, and put together a little platter for them?", ["objectivesText"] = "Collect 7 Chopped Oasis Plant cuttings and then place 3 Plant Platters . Progress: Have you fed the lapbugs?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 235914 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86351, 87292 }, ["questLines"] = { { ["id"] = 5779, ["name"] = "Lil' Lapbugs", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5779, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[87292] = { ["id"] = 87292, ["name"] = "Rooting for Trouble", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86349, 87291, 87292, 87293, 87294 }, ["series"] = { 87291 }, ["description"] = "Our bees have been marvelous at cultivating the local flora. Some of the plants have seen almost explosive growth. However, the lapbugs have become entangled in their roots. I've been untangling them all morning. Would you lend a hand?", ["objectivesText"] = "Detangle 10 Stuck Lapbugs . Progress: Have you gotten those lapbugs untangled?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86349 }, ["questLines"] = { { ["id"] = 5779, ["name"] = "Lil' Lapbugs", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5779, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[87293] = { ["id"] = 87293, ["name"] = "Shameless Hawking", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86349, 87291, 87292, 87293, 87294 }, ["series"] = { 87294 }, ["description"] = "Lapbugs were once a highly sought after pet here on K'aresh. I suspect we could use them to attract interested parties in Tazavesh, increasing both support and donations for the Oasis. I would like you to test this theory.", ["objectivesText"] = "Gather support for the Oasis in Tazavesh. Progress: Yes? I am busy.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 87291 }, ["questLines"] = { { ["id"] = 5779, ["name"] = "Lil' Lapbugs", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5779, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371, ["db2QuestHubAreaPoiID"] = 8385 },
[87294] = { ["id"] = 87294, ["name"] = "A Truth Universally Acknowledged", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 86349, 87291, 87292, 87293, 87294 }, ["series"] = { 87293 }, ["description"] = "I have an idea, <name>. Everyone seems to love the lapbugs, so I have enlarged them, given them hats, and placed them in picturesque locations. Take this camera and take some photos with the lapbugs. If I am correct, this will go a long way toward increasing support for our efforts.", ["objectivesText"] = "Take a S.E.L.F.I.E. with various lapbugs that are wearing hats. Progress: Have you gotten those photos? Do make sure your charming face is in them as well.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 236406 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 87293 }, ["questLines"] = { { ["id"] = 5779, ["name"] = "Lil' Lapbugs", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5779, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[87297] = { ["id"] = 87297, ["name"] = "Cashing the Check", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 85190, 85191, 85192, 86204, 87297, 87321 }, ["description"] = "We got one more thing to set straight. Come on. Grimla's waitin' for us back in the hotel lobby.", ["objectivesText"] = "Speak to Grimla Fizzlecrank in the Incontinental Hotel. Progress: Heya, boss.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 243321 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 234801, ["x"] = 0.392, ["y"] = 0.234 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 238002, ["x"] = 0.435, ["y"] = 0.511 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.234 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 85192 }, ["questLines"] = { { ["id"] = 5694, ["name"] = "Homecoming", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5694, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[87298] = { ["id"] = 87298, ["name"] = "Void Fused Resin", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87298 }, ["description"] = "Void-Fused Resin isn't my usual craft, but there is a way I could make it for you. Void energies continue to seep through the cracks in our shields contaminating the plants in the domes. If we eliminate the contaminated plants, they may provide the ingredients needed to create the resin. Destroy Void-Tainted Growths and bring me any Void Granules you find.", ["objectivesText"] = "35 Void Granules collected. Progress: Hurry, you need to finish this task!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235918, 235982 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 238069, ["x"] = 0.494, ["y"] = 0.544 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 238069, ["x"] = 0.494, ["y"] = 0.544 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard" },
[87299] = { ["id"] = 87299, ["name"] = "How Old Are These Things?", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15716, ["mapID"] = 14, ["storyline"] = { 84638, 84639, 84640, 84641, 84643, 84645, 84649, 84650, 84656, 84657, 84658, 84659, 84710, 84717, 85529, 87299, 91039 }, ["description"] = "Marran tried to declare herself the new ruler of Stromgarde. While some in the army are complicit in her coup, there are still a lot of us who are loyal to Lord Danath Trollbane. But when we broke ranks, Marran was ready for us. She has an army of soldiers I've never seen before. They call themselves the Red Dawn, but I think they're just the bandits wearing uniforms they took from our supplies! Help us take out her goons and collect any evidence that shows what they really are!", ["objectivesText"] = "Collect 20 Articles of Proof from Red Dawn troops within Stromgarde. Progress: Some of this stuff must be at least twenty years old...", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 7997, 23192, 231878, 231879, 231880, 231881, 231883, 231884 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.177, ["y"] = 0.603, ["mapID"] = 2372, ["npcID"] = 238012 } }, ["ends"] = { { ["x"] = 0.177, ["y"] = 0.603, ["mapID"] = 2372, ["npcID"] = 238012 } }, ["coords"] = { ["mapID"] = 2372, ["x"] = 0.177, ["y"] = 0.603 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15716 } }, ["questGiverID"] = 238012, ["questTurnInID"] = 238012, ["questType"] = "standard", ["sourceQuests"] = { 84657 }, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 25, ["flags"] = 1 }, { ["id"] = 5947, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2796, ["db2PoiUiMapID"] = 2372 },
[87301] = { ["id"] = 87301, ["name"] = "Untethered Battery", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87301 }, ["description"] = "Untethered batteries are difficult to create, as they require elusive energies that leak from void storage cells into Untethered Space. However, I know of an individual capable of harvesting this energy. If they can extract and store the energy and return it to me, we will have the necessary components to construct a battery. Speak to Myi Koo and collect the energy, we can then create a battery.", ["objectivesText"] = "Meet with Myi Koo, enter untethered space and collect 10 Untethered Energy Samples. Progress: Have you collected the required energy.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235499, 239249 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 238057, ["x"] = 0.48, ["y"] = 0.574 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 238057, ["x"] = 0.48, ["y"] = 0.574 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.574 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard" },
