[87308] = { ["id"] = 87308, ["name"] = "Twilight's Dawn", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = { "weekly", "repeatable", "meta" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 87308 }, ["description"] = "The remnants of the Twilight's Hammer are reforming under a new banner, crawling from their holes to pledge allegiance to the Twilight's Blade and their new mistress: Xal'atath. We cannot allow this to occur. Stamp them out. The only mercy those who tamper with the Void deserve is a swift death. <Rommath looks pointedly at Magister Umbric as he says this.>", ["objectivesText"] = "Complete world quests or defeat Twilight's Blade rares in the Twilight Highlands . Progress: There is much to do. Do not dawdle.", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 33250, 57851, 131253 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 50 }, { ["id"] = 3008, ["amount"] = 50 }, { ["id"] = 3319, ["amount"] = 40 } }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 237504, ["x"] = 0.498, ["y"] = 0.808 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 237504, ["x"] = 0.498, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.808 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 241, ["db2QuestInfoID"] = 284, ["db2QuestInfoName"] = "Meta Quest" },
[87317] = { ["id"] = 87317, ["name"] = "Denial Denied", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 87254, 87256, 87267, 87268, 87317, 91206, 92531 }, ["description"] = "So, I broke de staff. And everybody died. Maybe dis is my mistake. Sometimes it's too hard to say we made a mistake. And den we made even more mistakes. We in this deep, now. While you were talkin' to the others, I tried to get through to Akutu that we're dead. But he's not listenin'. All he does is blame others. Maybe I deserve it. Show Warlord Akutu de staff. Den take him to Kulzi. We need to try to talk to de loa. De pieces of dis puzzle are fallin' into place.", ["objectivesText"] = "Help Warlord Akutu face the truth and speak to Kulzi. Progress: Why aren't ya helpin me?!", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 237953, ["x"] = 0.404, ["y"] = 0.494 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 246525, ["x"] = 0.388, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 87268 }, ["questLines"] = { { ["id"] = 5778, ["name"] = "Healing the Spirit", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[87321] = { ["id"] = 87321, ["name"] = "Things Left Undone", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 85190, 85191, 85192, 86204, 87297, 87321 }, ["series"] = { 85190 }, ["description"] = "Hey pal, I can't thank you enough for what you've done for me... and for Undermine . <Marin glances over at Sprinkle before looking back at you.> I know you've been busy since Renzik and Gazlowe brought you here, and you keep doing what we've asked of you. But there's one more thing that needs doing. Meet up with Gazlowe at the hotel. I'm sure he'd appreciate you being there to help.", ["objectivesText"] = "Meet with Monte Gazlowe in the Incontinental Hotel in Undermine .", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 238006, ["x"] = 0.275, ["y"] = 0.71 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 232822, ["x"] = 0.425, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.275, ["y"] = 0.71 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 86204 }, ["questLines"] = { { ["id"] = 5694, ["name"] = "Homecoming", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5694, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[87324] = { ["id"] = 87324, ["name"] = "Pile of Voidbane Gems", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87324 }, ["description"] = "Voidbane Gems are dangerous business! The Shadowguard hide the gems in Untethered Space. You need to go in and find them. Be warned though, others may be looking for those gems as well! I marked the location of the stashes for you, but there's other gems laying around too. Grab what you can, and you'll have yourself a nice big pile of gems when you're done.", ["objectivesText"] = "20 Voidbane Gems collected. Progress: Hurry, grab those gems before someone else does.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235917, 236407, 236632 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 238181, ["x"] = 0.525, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 238181, ["x"] = 0.525, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard" },
[87327] = { ["id"] = 87327, ["name"] = "A Challenger's Resilience", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16395, ["mapID"] = 2112, ["storyline"] = { 87327 }, ["description"] = "Wow <name>, you've taken on some unbelievably scary dungeons AND lived to tell me about it! Come speak with me and I'll see about making your most challenging Keystones more Resilient.", ["objectivesText"] = "Meet with Lindormi to learn about Resilient Keystones . Progress: You have achieved much. Your deeds are Legendary.", ["rewardGold"] = 1239200, ["rewardXP"] = 23530, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 197711, ["x"] = 0.531, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 197711, ["x"] = 0.531, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.531, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 16395 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339, ["db2QuestInfoID"] = 282, ["db2QuestInfoName"] = "Important Quest" },
[87328] = { ["id"] = 87328, ["name"] = "Truly Horrific to Behold", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 86706, 87328, 87329, 87332, 87335, 87336 }, ["description"] = "<name>, we have much to discuss. The new threat of the Void is one that puts us all at risk. But this is not our first time. There are clues in our past encounters. So is the case for the Black Blood. In the past, N'Zoth used it to induce visions. Perhaps we can figure out how to counter its effects by returning to these moments. Come, help me set up the portal.", ["objectivesText"] = "Speak with Soridormi to assist with setting up the portal. Progress: Are you ready to revisit these Horrific Visions?", ["rewardGold"] = 170800, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 236382, ["x"] = 0.345, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 236382, ["x"] = 0.345, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.345, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 86706 }, ["questLines"] = { { ["id"] = 5768, ["name"] = "Horrific Visions Revisited", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[87329] = { ["id"] = 87329, ["name"] = "Into the Darkest Memories", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 86706, 87328, 87329, 87332, 87335, 87336 }, ["description"] = "Are you prepared? The path through the timeways has been opened to where we last entered the visions. Expect your sanity to be tested. You probably will not last long on this first attempt. The portal is ready for you, <name>. Journey forth.", ["objectivesText"] = "Interact with the Portal to Horrific Visions to rediscover the horrors of the Black Blood. Progress: We must build on our past knowledge. Did you find something new?", ["rewardGold"] = 683200, ["rewardCurrencies"] = { { ["id"] = 3149, ["amount"] = 20 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 236382, ["x"] = 0.345, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 236382, ["x"] = 0.345, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.345, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 87328 }, ["questLines"] = { { ["id"] = 5768, ["name"] = "Horrific Visions Revisited", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[87332] = { ["id"] = 87332, ["name"] = "A Collection of Variables", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 86706, 87328, 87329, 87332, 87335, 87336 }, ["description"] = "My assistant Augermu has been monitoring you and the timeways while you were in the past. He has a way for you to replicate gaining some of the boons adventurers used the first time they faced these visions. Give him some of the displaced corrupted mementos you gleaned from your experience for further analysis.", ["objectivesText"] = "Speak to Augermu to ask about what you can do with the Displaced Corrupted Mementos.", ["rewardGold"] = 30900, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 236382, ["x"] = 0.345, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 238136, ["x"] = 0.35, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.345, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 87329 }, ["questLines"] = { { ["id"] = 5768, ["name"] = "Horrific Visions Revisited", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[87335] = { ["id"] = 87335, ["name"] = "Echoing Lessons", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 86706, 87328, 87329, 87332, 87335, 87336 }, ["description"] = "We can use your displaced corrupted mementos to create Echoes of N'Zoth. I don't want to bore you with the details unless you want to hear. No? Oh well. < Augermu appears slightly disappointed.> The more echoes you have, the closer we can get you to a version of yourself that's more prepared for the visions. So, let's get started.", ["objectivesText"] = "Work with Augermu to create an Echo of N'Zoth and insert it into the Hourglass of Horrific Visions. Progress: Were you able to slot in the first Echo of N'Zoth?", ["rewardGold"] = 34100, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 238136, ["x"] = 0.35, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 238136, ["x"] = 0.35, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 87332 }, ["questLines"] = { { ["id"] = 5768, ["name"] = "Horrific Visions Revisited", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[87336] = { ["id"] = 87336, ["name"] = "Remembering Again and Again", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 86706, 87328, 87329, 87332, 87335, 87336 }, ["description"] = "Now that we have the hourglass calibrated to you, you can re-enter Horrific Visions whenever you like. No need for keys when traveling back in time! That said, we do face one limitation. The hourglass is still fragile, and I must harden it week to week to support additional Echoes of N'Zoth. Who knew that memories of an Old God were so dangerous...? Well, you should report back to Soridormi and get back to it!", ["objectivesText"] = "Report back to Soridormi .", ["rewardGold"] = 30900, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 238136, ["x"] = 0.35, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 236382, ["x"] = 0.345, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 87335 }, ["questLines"] = { { ["id"] = 5768, ["name"] = "Horrific Visions Revisited", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[87337] = { ["id"] = 87337, ["name"] = "Custodian Duties", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 87290, 87337, 87338, 87339, 87340 }, ["series"] = { 87290 }, ["description"] = "Ve'nari is very busy. While both her and Om'talad are away, I will give you your orders. We have many creatures here in the Oasis. They make messes. Go clean them up.", ["objectivesText"] = "Clean up the Oasis in K'aresh. Progress: I apologize for that.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 236416 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 238209, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 87290 }, ["questLines"] = { { ["id"] = 5780, ["name"] = "The Oasis", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5780, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[87338] = { ["id"] = 87338, ["name"] = "Day One Orientation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 87290, 87337, 87338, 87339, 87340 }, ["description"] = "We've taken some of the native species we saved out of stasis. We will need to recreate their habitats. There are two primary species here, as well as this console to monitor species in the Oasis. I recommend acquainting yourself with these creatures before we begin.", ["objectivesText"] = "Introduce yourself to the animals of the Oasis, and check their status on the console in the Oasis. Progress: Have you familiarized yourself with the animals?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 87337 }, ["questLines"] = { { ["id"] = 5780, ["name"] = "The Oasis", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5780, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[87339] = { ["id"] = 87339, ["name"] = "Ongoing Activities", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 87290, 87337, 87338, 87339, 87340 }, ["description"] = "While you will be on assignments that befit your skill set, there are also additional tasks that need to be done in the Oasis on a regular basis. While these are typically done by the custodians, if you are in the area I would not say no to your assistance with them. Now, and in the future.", ["objectivesText"] = "Perform various activities in the Oasis in K'aresh. Progress: Have you been hard at work?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 236641 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 87337 }, ["questLines"] = { { ["id"] = 5780, ["name"] = "The Oasis", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5780, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[87340] = { ["id"] = 87340, ["name"] = "Junk Mail", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 87290, 87337, 87338, 87339, 87340 }, ["series"] = { 85075 }, ["description"] = "One final item before we begin--a special task suited to your unique capabilities. No, not killing. Flying. The Oasis requires donations. Donations come from advertising. Take these stacks of fliers and distribute them around Tazavesh.", ["objectivesText"] = "Fly through the rings above Tazavesh to distribute fliers. Progress: Have you distributed the fliers?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 87338, 87339 }, ["questLines"] = { { ["id"] = 5780, ["name"] = "The Oasis", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5780, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[87341] = { ["id"] = 87341, ["name"] = "Barreling Down", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Brewfest", ["expansion"] = 11, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 87341 }, ["description"] = "If it's ale you're looking for, we've got plenty to sample! Or at least we would if the Dracthyr folk would hurry up and bring the rest of the barrels down here. Some of the Dracthyr have come to celebrate here with us and decided to help transport the ale. Rolling barrels? That's no way to treat a good brew! Mind lending a hand to bring those barrels over to Razor Hill? And try not to break them.", ["objectivesText"] = "Deliver barrels to Razor Hill. Progress: Careful with the barrels! You shouldn't jostle a good ale.", ["rewardGold"] = 338300, ["rewardXP"] = 1415, ["rewardItems"] = { 37829 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 238221, ["x"] = 0.425, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 238221, ["x"] = 0.425, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.425, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 } },
[87342] = { ["id"] = 87342, ["name"] = "Honor the Flame", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 87342 }, ["description"] = "The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, <name>?", ["objectivesText"] = "Honor the Midsummer Bonfire in the Isle of Dorn.", ["rewardGold"] = 154900, ["rewardXP"] = 100, ["rewardItems"] = { 23247 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 238236, ["x"] = 0.482, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 238236, ["x"] = 0.482, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questTurnInID"] = 238236, ["questType"] = "standard", ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[87343] = { ["id"] = 87343, ["name"] = "Warrant: Hollowbane", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87343 }, ["series"] = { 90123 }, ["description"] = "Shadowguard forces in Shadow Point have rallied around an enigmatic champion know as Hollowbane. Though the Hollowbane's existence is unconfirmed, we have located a travel portal supposedly used by the champion. Unlock the portal and expose Hollowbane so they may be confronted and eliminated.", ["objectivesText"] = "Combine an Umbral Facade , Energy Encapsulation and a Bag of Veilshards to create a portal key.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235917, 236688, 236957, 237354 }, ["starts"] = { { ["x"] = 0.485, ["y"] = 0.581, ["mapID"] = 2472, ["npcID"] = 238269 } }, ["ends"] = { { ["x"] = 0.485, ["y"] = 0.581, ["mapID"] = 2472, ["npcID"] = 238269 } }, ["coords"] = { ["mapID"] = 2472, ["x"] = 0.485, ["y"] = 0.581 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15336 } }, ["questGiverID"] = 238269, ["questTurnInID"] = 238269, ["questType"] = "standard", ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2472 },
[87344] = { ["id"] = 87344, ["name"] = "A Key Threat", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 87344 }, ["description"] = "Tazavesh is a city rife with turmoil, beset by countless dangers. We could always use your help. Check our warrant board, and see if you have what it takes to eliminate our most wanted threats.", ["objectivesText"] = "Complete a warrant and eliminate the threat to our city. Progress: Have you completed a warrant.", ["rewardGold"] = 929400, ["rewardXP"] = 17650, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 238255, ["x"] = 0.485, ["y"] = 0.5755 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 238255, ["x"] = 0.485, ["y"] = 0.5755 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.5755 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 84967 }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2472, ["db2QuestHubAreaPoiID"] = 8385 },
[87345] = { ["id"] = 87345, ["name"] = "Warrant: Xy'vox the Twisted", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87345 }, ["series"] = { 90122 }, ["description"] = "Xy'vox the Twisted the former constable of Tazavesh, hailed from a powerful cartel family. Unknown to most, the family's power was obtained from illegal crimes, all conveniently overlooked by Xy'vox. When the truth came out, Xy'vox went into hiding. I believe the constable never left town, instead hides here in plain sight, continuing criminal activities. Create a Refuge Dampener to reveal Xy'vox to all of Tazavesh.", ["objectivesText"] = "Collect a Tazavesh Facade , Ethereal Seal and a Zo'kita Fruit .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 236753, 236762, 236781, 236783, 236858, 237485, 245255 }, ["starts"] = { { ["x"] = 0.485, ["y"] = 0.584, ["mapID"] = 2472, ["npcID"] = 238271 } }, ["ends"] = { { ["x"] = 0.485, ["y"] = 0.584, ["mapID"] = 2472, ["npcID"] = 238271 } }, ["coords"] = { ["mapID"] = 2472, ["x"] = 0.485, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15336 } }, ["questGiverID"] = 238271, ["questTurnInID"] = 238271, ["questType"] = "standard", ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[87347] = { ["id"] = 87347, ["name"] = "Bubbling Brews", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Brewfest", ["expansion"] = 11, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 87347 }, ["description"] = "Drat! I might've made a mistake asking the dracthyr to help with these deliveries. They've been rolling barrels of brews and crashing 'em all over the place! Well, we shouldn't let the brew go to waste if we can help it! Take a barrel an' take to the skies! Try to collect and save as much of the brew as you can by collecting the bubbles.", ["objectivesText"] = "Collect brew bubbles in Dun Morogh. Progress: Have ye filled up the barrel?", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 37829 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 237987, ["x"] = 0.538, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 237987, ["x"] = 0.538, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 }, ["db2QuestSortName"] = "Epic" },
