[87355] = { ["id"] = 87355, ["name"] = "Honor the Flame", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 11, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 87355 }, ["description"] = "The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, <name>?", ["objectivesText"] = "Honor the Midsummer Bonfire in Hallowfall", ["rewardGold"] = 154900, ["rewardXP"] = 100, ["rewardItems"] = { 23247 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 238338, ["x"] = 0.424, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 238338, ["x"] = 0.424, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questTurnInID"] = 238338, ["questType"] = "standard", ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[87356] = { ["id"] = 87356, ["name"] = "Honor the Flame", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 11, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 87356 }, ["description"] = "The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, <name>?", ["objectivesText"] = "Honor the Midsummer Bonfire in Azj-Kahet", ["rewardGold"] = 154900, ["rewardXP"] = 100, ["rewardItems"] = { 23247 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 238339, ["x"] = 0.555, ["y"] = 0.434 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 238339, ["x"] = 0.555, ["y"] = 0.434 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.434 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questTurnInID"] = 238339, ["questType"] = "standard", ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[87357] = { ["id"] = 87357, ["name"] = "Honor the Flame", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 11, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 87357 }, ["description"] = "The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, <name>?", ["objectivesText"] = "Honor the Midsummer Bonfire in the Ringing Deeps", ["rewardGold"] = 154900, ["rewardXP"] = 100, ["rewardItems"] = { 23247 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 238340, ["x"] = 0.436, ["y"] = 0.326 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 238340, ["x"] = 0.436, ["y"] = 0.326 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.326 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questTurnInID"] = 238340, ["questType"] = "standard", ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[87358] = { ["id"] = 87358, ["name"] = "Umbral Facade", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87358 }, ["description"] = "The trick to creating a perfect Facade is to scan live Shadowguard with a nifty little device I will provide you. This device will allow you copy the very unique essence that is the core of their being, and store it for our use. You can locate shadowguard in both regular and untethered space. Regardless of how you find them, they won't take kindly to your presence, and they certainly won't want to be scanned.", ["objectivesText"] = "18 Shadowguard Essence scanned Progress: Did you finish those scans?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 236679, 236688 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 238181, ["x"] = 0.525, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 238181, ["x"] = 0.525, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard" },
[87363] = { ["id"] = 87363, ["name"] = "Tazavesh Facade", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 87363 }, ["description"] = "To create the perfect Tazavesh facade , you must scan live Shadowguard around Tazavesh with a device I will provide you. This device will mark the targets, allowing you to copy the unique essence that is the core of their being and store it for our use. This is dangerous business, as you will have to approach them directly and see if they're willing to be scanned!", ["objectivesText"] = "15 Shadowguard Essence scanned. Progress: Did you finish those scans?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 236762, 236766 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 238387, ["x"] = 0.468, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 238387, ["x"] = 0.468, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard" },
[87374] = { ["id"] = 87374, ["name"] = "C.H.E.T.T.ing In", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 87374 }, ["description"] = "Undermine with directions to The Incontinental's second floor.>", ["objectivesText"] = "Speak to C.H.E.T.T. on the second floor of The Incontinental to learn about C.H.E.T.T. Lists.", ["starts"] = { { ["x"] = 0.433, ["y"] = 0.505, ["mapID"] = 2346, ["npcID"] = 238029 } }, ["ends"] = { { ["x"] = 0.433, ["y"] = 0.505, ["mapID"] = 2346, ["npcID"] = 238029 } }, ["coords"] = { ["mapID"] = 2346, ["x"] = 0.433, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15347 } }, ["questGiverID"] = 238029, ["questTurnInID"] = 238029, ["questType"] = "standard", ["sourceQuests"] = { 83151 }, ["db2QuestHubAreaPoiID"] = 8189 },
[87376] = { ["id"] = 87376, ["name"] = "Ethereal Seal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 87376 }, ["description"] = "An Ethereal Seal grants unrestricted access and control over Ethereal assets without raising suspicion. Acquiring an authentic seal can be quite difficult. It is far easier to forge one using discarded cyphers instead. If you're not afraid to get your hands dirty, you can find discarded writs in the trash piles outside of town. Bring those to me, and I can create a seal for you.", ["objectivesText"] = "Collect 12 Discarded Shadow Writs . Progress: Did your find the Shadow Seals?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 235499, 236753, 236781, 236783 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 238486, ["x"] = 0.465, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 238486, ["x"] = 0.465, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard" },
[87380] = { ["id"] = 87380, ["name"] = "Zo'kita Fruit", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 87380 }, ["description"] = "You can have the fruit, but only if you do me a favor first. Something is watching us. You can't see it, but the smell of the fruit draws it to us. Hidden monsters lurking just beyond our sight. Gain access to the Untethered Space, hunt these creatures down, and bring me their hides. I want proof that these creatures actually exist!", ["objectivesText"] = "8 Untethered Hide collected Progress: Did you see them? Did you cut them to pieces?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 236858, 236859, 236962 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 238474, ["x"] = 0.524667, ["y"] = 0.575333 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 238474, ["x"] = 0.524667, ["y"] = 0.575333 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.524667, ["y"] = 0.575333 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard" },
[87388] = { ["id"] = 87388, ["name"] = "A Bigger Beast", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 87388, 87391, 87672, 88653, 88708, 88755 }, ["series"] = { 88653, 88755 }, ["description"] = "Return to Umbric? But we're on the brink of deeper understandings! Hypothesis: there exists an apex predator amongst these creatures that might hold immense power! And this predator's relationship with the Void could further our own understanding of the infinite darkness. Eradicate some of the smaller creatures and see if such a beast answers the call of violence!", ["objectivesText"] = "Slay 8 Vicious Karions in the Bladeburrows. Progress: There is a connection between these beasts and the Void... not so unlike the ren'dorei.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 236908, ["x"] = 0.412, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 236908, ["x"] = 0.412, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 88755 }, ["questLines"] = { { ["id"] = 6010, ["name"] = "The Void Peers Back", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[87391] = { ["id"] = 87391, ["name"] = "Sampling the Local Fare", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 87388, 87391, 87672, 88653, 88708, 88755 }, ["series"] = { 87672 }, ["description"] = "This place is a food chain of ferocity and far too many teeth. Our studies grow more dangerous by the minute, but if Matrean insists on staying, we may as well assist him. We're studying a link between the nature of these creatures and the Void's accumulation here. Dispatch some of the beasts below and bring samples of their tissue back to me. We can study them to learn more of their connection with the Void.", ["objectivesText"] = "Collect 30 Exotic Tissue Samples from creatures in the Bladeburrows. Progress: Can there even BE a ruler of such a chaotic animal kingdom?", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 235632 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 236930, ["x"] = 0.412, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 236930, ["x"] = 0.412, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 88755 }, ["questLines"] = { { ["id"] = 6010, ["name"] = "The Void Peers Back", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[87392] = { ["id"] = 87392, ["name"] = "Cargo Conspiracy", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 87392, 87393, 87394, 87395, 87396, 87397, 87398 }, ["description"] = "The Sunwell's radiance may shine, but its Light has not purged the filth that festers within this city. Smugglers scuttle through the streets like vermin, preying upon the desperate and enriching the spineless. Yet, there are whispers of something fouler still--trade in wares so vile that even the Venture Company would recoil. I require someone to spy on each shipping company and find out which cloaks a smuggling ring. Will you stand with me, or will you turn away as the rot spreads?", ["objectivesText"] = "Investigate shipping companies in Fairbreeze Village. Progress: So, what did our fine dockworkers have to say?", ["rewardGold"] = 170800, ["rewardXP"] = 5885, ["rewardItems"] = { 237722 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 238490, ["x"] = 0.468, ["y"] = 0.452 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 238490, ["x"] = 0.468, ["y"] = 0.452 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.452 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86735 }, ["questLines"] = { { ["id"] = 5805, ["name"] = "Port Detective", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[87393] = { ["id"] = 87393, ["name"] = "Warranted Search", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 87392, 87393, 87394, 87395, 87396, 87397, 87398 }, ["description"] = "Tideborne Freight, is it? A name far too polished, like an ornate blade designed to distract from the blood it has shed. Smuggling through the port... but I suspect this venture involves something far more perilous than we think. We must act with haste before they set sail and vanish into the mists. Keep your weapons honed and your senses sharper. Make them understand that crossing me was a grave miscalculation.", ["objectivesText"] = "\"Interrogate\" 12 Tideborne Freight sailors in Sunsail Anchorage. Progress: Back already? Let's hear it. What did you uncover about the Tideborne? And don't leave out any details", ["rewardGold"] = 312800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 238490, ["x"] = 0.468, ["y"] = 0.452 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 238505, ["x"] = 0.394, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.452 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 87392 }, ["questLines"] = { { ["id"] = 5805, ["name"] = "Port Detective", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[87394] = { ["id"] = 87394, ["name"] = "Supplier Surveillance", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 87392, 87393, 87394, 87395, 87396, 87397, 87398 }, ["description"] = "This note all but drips with guilt, but mere words alone will not bring down Tideborne Freight. I require undeniable proof--evidence so damning that not even their well-bribed magistrates can turn a blind eye. That is where you come in. Take this arcane recorder and make your way to the docks. Document their shipments, their crew--anything that reeks of smuggling. A single image can speak volumes, and I intend to make every word count.", ["objectivesText"] = "Record evidence in Sunsail Anchorage. Progress: You're back, and with the recordings, I hope.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 238490, ["x"] = 0.468, ["y"] = 0.452 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 238505, ["x"] = 0.394, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.452 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 87392 }, ["questLines"] = { { ["id"] = 5805, ["name"] = "Port Detective", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[87395] = { ["id"] = 87395, ["name"] = "Below the Brine", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 87392, 87393, 87394, 87395, 87396, 87397, 87398 }, ["description"] = "Discarding crates into the ocean? How utterly desperate. Whatever they seek to conceal must be damning--sufficient enough to unravel their entire operation, should we recover it. Take a deep breath and retrieve it before the current sweeps it away. Every thread we pull unravels their scheme further. Soon there will be nothing left but the ruin of their own making.", ["objectivesText"] = "Recover 12 Submerged Cargo Items in Sunsail Anchorage. Progress: So what did our friends at Tideborne Freight so desperately want to hide? Their scuttling cannot conceal their true intentions forever.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 239022, 242552 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 238505, ["x"] = 0.394, ["y"] = 0.45 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 239368, ["x"] = 0.358, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 87393, 87394 }, ["questLines"] = { { ["id"] = 5805, ["name"] = "Port Detective", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[87396] = { ["id"] = 87396, ["name"] = "Dead to Rights", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 87392, 87393, 87394, 87395, 87396, 87397, 87398 }, ["description"] = "Tideborne's decision to discard crates into the ocean was no mere error. It was a calculated delivery. Pursue them, and ensure the naga are reminded of the grave consequences they face when they dare to cross us.", ["objectivesText"] = "Defeat 10 Tideborne naga in Sunset Strand. Progress: Get after them!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 239368, ["x"] = 0.358, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 239368, ["x"] = 0.358, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.358, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 87395 }, ["questLines"] = { { ["id"] = 5805, ["name"] = "Port Detective", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[87397] = { ["id"] = 87397, ["name"] = "Cargo Collateral", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 87392, 87393, 87394, 87395, 87396, 87397, 87398 }, ["description"] = "If the naga manage to siphon the remaining arcane energy from those unstable arcana, they will gain the very power they seek. Destroy, incinerate, shatter them--do whatever is necessary. Ensure not a single shard remains for the naga or Tideborne to exploit. I do not wish to see even the faintest trace of arcane energy linger.", ["objectivesText"] = "Destroy 5 Smuggled Crates in Sunset Strand. Progress: I trust you gave that cargo a proper send-off.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 239368, ["x"] = 0.358, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 239368, ["x"] = 0.358, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.358, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 87395 }, ["questLines"] = { { ["id"] = 5805, ["name"] = "Port Detective", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[87398] = { ["id"] = 87398, ["name"] = "Smuggler Showdown", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 87392, 87393, 87394, 87395, 87396, 87397, 87398 }, ["description"] = "The naga acted out of desperation. Tideborne's crew, however, is driven by arrogance. They sit smugly aboard their ship, convinced of their invulnerability and counting their ill-gotten wealth. It is time we put an end to that. Captain Bloodwake shall be made to answer for every crate, every transaction, and every transgression. Are you prepared to extract the truth?", ["objectivesText"] = "Defeat Captain Dorynth Bloodwake in Sunsail Anchorage.", ["rewardGold"] = 683200, ["rewardXP"] = 14705, ["rewardItems"] = { 263447, 263480, 263481, 263482, 263484, 263485, 263486, 263487 }, ["rewardChoices"] = { 263447, 263480, 263481, 263482, 263484, 263485, 263486, 263487 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3365, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 239368, ["x"] = 0.358, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 244870, ["x"] = 0.378, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.358, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 87396, 87397 }, ["questLines"] = { { ["id"] = 5805, ["name"] = "Port Detective", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[87399] = { ["id"] = 87399, ["name"] = "Facing the Sun", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 87399, 87400, 87401, 87402 }, ["description"] = "This sanctum was studying the Lightbloom well before the incident at Fairbreeze. We had no reason to be concerned over their research up until that point. However, the last message we attempted to send never received a reply. And this doesn't look good now that we're here. We need to clear out some of the wildlife first, though. We cannot risk any contamination.", ["objectivesText"] = "Kill 8 encroaching wildlife. Progress: How goes the hunt?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 238083, ["x"] = 0.511333, ["y"] = 0.770667 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 238083, ["x"] = 0.511333, ["y"] = 0.770667 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.511333, ["y"] = 0.770667 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86745 }, ["questLines"] = { { ["id"] = 6018, ["name"] = "Blinding Sun", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[87400] = { ["id"] = 87400, ["name"] = "Scattered in Sunbeams", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 87399, 87400, 87401, 87402 }, ["description"] = "We've given the garden tenders some space to continue their work unimpeded. Hopefully they can keep this place pristine until Silvermoon has the chance to fix it up. But now we need to figure out where the missing scholars are. They were studying mana influence on plants in the gardens toward the back. Perhaps we'll find a sign of them there.", ["objectivesText"] = "Find signs of what happened to the Sanctum's researchers.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 238083, ["x"] = 0.511333, ["y"] = 0.770667 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 238083, ["x"] = 0.511333, ["y"] = 0.770667 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.511333, ["y"] = 0.770667 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 87399 }, ["questLines"] = { { ["id"] = 6018, ["name"] = "Blinding Sun", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[87401] = { ["id"] = 87401, ["name"] = "Gardener Mishap", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 87399, 87400, 87401, 87402 }, ["description"] = "The sanctum door seems to be locked. Probably from the inside. I believe an arcane construct is used for heavy lifting and general upkeep alongside the treants. The core of it should override the lock on the door and work as a master key. I doubt it will just let us take it, so be careful.", ["objectivesText"] = "Find a magical construct and retrieve its core. Progress: Yes?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 238677 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 238084, ["x"] = 0.505, ["y"] = 0.78 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 238084, ["x"] = 0.505, ["y"] = 0.78 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.78 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 87399 }, ["questLines"] = { { ["id"] = 6018, ["name"] = "Blinding Sun", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[87402] = { ["id"] = 87402, ["name"] = "The Light Provides", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 87399, 87400, 87401, 87402 }, ["description"] = "We need to get into the Sanctum. Now. Burn away the roots on that door! And be prepared--nothing good can be behind it.", ["objectivesText"] = "Open the door to the Sanctum of the Sun and deal with what lies beyond. Progress: We cannot wait.", ["rewardGold"] = 683200, ["rewardXP"] = 14705, ["rewardItems"] = { 246441, 263326, 263327, 263328, 263331 }, ["rewardChoices"] = { 263326, 263327, 263328, 263331 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3365, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 238084, ["x"] = 0.505, ["y"] = 0.78 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 238084, ["x"] = 0.505, ["y"] = 0.78 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.78 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 87400, 87401 }, ["questLines"] = { { ["id"] = 6018, ["name"] = "Blinding Sun", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[87404] = { ["id"] = 87404, ["name"] = "Energy Encapsulation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87404 }, ["description"] = "You need an Energy Encapsulation ? You must be planning to activate a portal or teleporter with it! I can construct what you require with ease, provided you supply the necessary energy. Visit the Harvesters nearby. They let us collect what we need, as long as we help keep the wyrms off the harvesters.", ["objectivesText"] = "10 Energy collected from Power Harvesters and Crackling Wyrms . Progress: Do you have the required energy?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235051, 236937 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 238057, ["x"] = 0.48, ["y"] = 0.574 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 238057, ["x"] = 0.48, ["y"] = 0.574 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.574 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard" },
[87405] = { ["id"] = 87405, ["name"] = "Warrant: Grubber", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87405 }, ["series"] = { 90126 }, ["description"] = "A massive worm has been spotted lurking in the Scrapdrift Sands east of town. The locals have nicknamed it Grubber. Tragically, we lost deputy Zo'wie when he went out to investigate. The creature pulled him under the sand. Devise a method to lure the worm into revealing itself, so it may be eliminated once and for all.", ["objectivesText"] = "Collect a Basket of Zo'kita Fruit , a Dozen Veilshards and some Flavorful Scraps .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 236962, 236966, 236967, 237352 }, ["starts"] = { { ["x"] = 0.485, ["y"] = 0.588, ["mapID"] = 2472, ["npcID"] = 238548 } }, ["ends"] = { { ["x"] = 0.485, ["y"] = 0.588, ["mapID"] = 2472, ["npcID"] = 238548 } }, ["coords"] = { ["mapID"] = 2472, ["x"] = 0.485, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15336 } }, ["questGiverID"] = 238548, ["questTurnInID"] = 238548, ["questType"] = "standard" },
[87406] = { ["id"] = 87406, ["name"] = "Inoperative Mega-Mecha Gorilla", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 87406 }, ["description"] = "<Despite your best efforts, the machine remains silent. Maybe a local expert could get it working.>", ["objectivesText"] = "Take the Inoperative Mega-Mecha Gorilla to Ditty Fuzeboy for repairs. Provided item:", ["rewardItems"] = { 232843, 234427, 234430, 234431, 234432, 234433, 234741, 236961 }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 236411, ["x"] = 0.354, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.354, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["startItems"] = { 236961 } },
[87408] = { ["id"] = 87408, ["name"] = "Being Spiritual", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 87408, 87409, 87410, 87411, 87412, 87413, 87414, 87415 }, ["series"] = { 87409 }, ["description"] = "We have perfected creating existing creatures, but I would like to go one step further. I would like to try this process with a creature that did not survive the Devouring. This world once had a creature called a k'arroc. Locate its essence and gather it for me.", ["objectivesText"] = "Collect 15 Flyer Essence in Untethered Space on K'aresh. Progress: Have you gathered the essences I needed?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229396 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86607 }, ["questLines"] = { { ["id"] = 5782, ["name"] = "Hard Kalroc", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5782, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[87409] = { ["id"] = 87409, ["name"] = "From Death, Life", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 87408, 87409, 87410, 87411, 87412, 87413, 87414, 87415 }, ["series"] = { 87408 }, ["description"] = "We have only to let the machine do its work now. I will let you do the honors. If it fails, I will place the blame on you... ... I jest, my friend. Mostly.", ["objectivesText"] = "Help Ve'nari use her machine to create life in the Oasis.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 87408 }, ["questLines"] = { { ["id"] = 5782, ["name"] = "Hard Kalroc", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5782, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[87410] = { ["id"] = 87410, ["name"] = "Percussive Negotiation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 87408, 87409, 87410, 87411, 87412, 87413, 87414, 87415 }, ["series"] = { 87411 }, ["description"] = "The k'arrocs are big and they're going to need tae stretch their wings sooner or later. Let's plan for it, eh? The Shadowguard have all sorts of void shielding going on. I bet you could get parts from them using your usual method of negotiatin' with enemies. Take the parts to Ve'nari when you're done.", ["objectivesText"] = "Collect 12 Void Shielding Parts in the Umbral Garrison. Progress: Did you get the parts?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237010 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 87409 }, ["questLines"] = { { ["id"] = 5782, ["name"] = "Hard Kalroc", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5782, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[87411] = { ["id"] = 87411, ["name"] = "Making Stuff to Look Tough", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 87408, 87409, 87410, 87411, 87412, 87413, 87414, 87415 }, ["series"] = { 87410 }, ["description"] = "I suppose we can construct the void shield Hemet imagined, but these parts are not ideal. Meet me outside the Oasis to the east and we shall see if we can craft a workable solution.", ["objectivesText"] = "Assist Ve'nari in crafting a Void Shield outside the Oasis. Progress: Come now. Let us begin building.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 237021 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 87410 }, ["questLines"] = { { ["id"] = 5782, ["name"] = "Hard Kalroc", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5782, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[87412] = { ["id"] = 87412, ["name"] = "K'arrocing Photos", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 87408, 87409, 87410, 87411, 87412, 87413, 87414, 87415 }, ["description"] = "We must keep our documentation updated. That means I require your services once more. Take this camera and gather more photos of the k'arrocs. You'll find them on the rocks around the area.", ["objectivesText"] = "Document 7 Domineering K'arrocs. Progress: Have you taken the photos I requested?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 237012 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 87411 }, ["questLines"] = { { ["id"] = 5782, ["name"] = "Hard Kalroc", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5782, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[87413] = { ["id"] = 87413, ["name"] = "Bird Bath", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 87408, 87409, 87410, 87411, 87412, 87413, 87414, 87415 }, ["description"] = "<name>--just the person I needed! The k'arrocs are gettin' so dirty that it's covering up their natural smell. There's not enough water here for them to bathe! Take this anima vacuum . It'll take that dirt straight off 'em, but you're gonna have to stick to the ones on the ground. Try looking on top of the rocks to the north!", ["objectivesText"] = "Wash 7 Domineering K'arrocs. Progress: Have you cleaned up those dirty birdies?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 237013 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 234316, ["x"] = 0.76, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 234316, ["x"] = 0.76, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 87412 }, ["questLines"] = { { ["id"] = 5782, ["name"] = "Hard Kalroc", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5782, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[87414] = { ["id"] = 87414, ["name"] = "Medical Maneuvers", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 87408, 87409, 87410, 87411, 87412, 87413, 87414, 87415 }, ["series"] = { 87415 }, ["description"] = "It would be good to get a solid medical checkup on the k'arrocs. Would you shrink them down and bring them to me?", ["objectivesText"] = "Shrink and collect 8 Domineering K'arrocs. Progress: Have you gathered the k'arrocs I asked for?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 237030, 238913 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 87413 }, ["questLines"] = { { ["id"] = 5782, ["name"] = "Hard Kalroc", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5782, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[87415] = { ["id"] = 87415, ["name"] = "The Skies of K'aresh", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 87408, 87409, 87410, 87411, 87412, 87413, 87414, 87415 }, ["series"] = { 87414 }, ["description"] = "The shielding device you helped with has been tested. It is ready for its first flight, if you will forgive the turn of phrase. Speak with Om'torid . They have a course picked out for you and the k'arroc to soar along.", ["objectivesText"] = "Test out the shield device by taking a k'arroc for a flight outside of the Oasis. Progress: How did the shield hold up?", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 87414 }, ["questLines"] = { { ["id"] = 5782, ["name"] = "Hard Kalroc", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5782, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[87417] = { ["id"] = 87417, ["name"] = "Worldsoul: Dungeons", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "The enemies of Khaz Algar rise up, unified in the suffering they inflict on those who do not believe in their causes. <Faerin pauses, then takes a quick glance at the table in front of her before returning her gaze to you.> Show these people the light, <name>. If they cannot see the error of their ways, please show them a merciful conclusion to their beliefs.", ["objectivesText"] = "Complete any Seasonal Dungeon at Normal difficulty or higher. Progress: How goes the mission?", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224701, 224784, 239118, 244865 }, ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[87419] = { ["id"] = 87419, ["name"] = "Worldsoul: Delves", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "These lands house many deep crevices, leaving shadows where our enemies believe they are safe. Explore these hidden places and leave our enemies no sanctuary.", ["objectivesText"] = "Complete a War Within Delve at any difficulty.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 229354, 239118, 244865 }, ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 15, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[87420] = { ["id"] = 87420, ["name"] = "Basket of Zo'kita Fruit", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 87420 }, ["description"] = "You need more Zo'kita Fruit than I'd ever dare to keep around here! Just one Zo'kita fruit is enough to drive my brother out of the market, and you're asking for a whole basket? Bold move, my friend! Visit Eco-dome: Primus, I secretly grow them there, hidden out of sight. Use my picking gear to locate them and take as many as you need.", ["objectivesText"] = "Collect 8 Freshly Picked Zo'kita Fruit. Progress: Did you get enough?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 236962, 236972, 237009 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 238474, ["x"] = 0.524667, ["y"] = 0.575333 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 238474, ["x"] = 0.524667, ["y"] = 0.575333 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.524667, ["y"] = 0.575333 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard" },
[87422] = { ["id"] = 87422, ["name"] = "Worldsoul: Undermine World Quests", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Undermine may be a place I do not understand, but they too are in need of aid. Our conflicts inflame their situation, it would do good to help them move forward. Go there and help them. See what you can do to bring these... cartels closer together, and to us.", ["objectivesText"] = "Complete World Quests in Undermine.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 239118, 244865 }, ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 50, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[87423] = { ["id"] = 87423, ["name"] = "Worldsoul: Undermine Explorer", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Undermine is held together by an intricate design of innovation, hard work, allegiance, and it seems like the sheer will of the goblins. Rather than cower in their sunless cave, the goblins have built a city that thrives on motion and activity. We can learn much from that. After not seeing new faces for years, they bring a new light to our lands. Go help them in whatever ways seem fitting.", ["objectivesText"] = "Complete various activities in Undermine.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 232523, 239118 }, ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 43, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[87424] = { ["id"] = 87424, ["name"] = "Worldsoul: World Bosses", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Hallowfall is not the only land beset by enemies. Great monsters threaten our allies. Wherever the shadows of our war have fallen, savage beasts and cunning fiends rise up. They murder Arathi, earthen, and the others who stand with us. Innocent farmers to great warriors. I know the Sacred Flame burns in you. You are our best hope to hunt these great evils.", ["objectivesText"] = "Defeat all available World Bosses in The War Within. Progress: I've seen monsters shifting in the distant darkness of Hallowfall. Things that haunt my nightmares.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 239118, 244865 }, ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 39, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[87425] = { ["id"] = 87425, ["name"] = "Large Sticky Voidmass", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87425 }, ["description"] = "Ah, yes, I've seen what you are describing! The sap from the corrupted plants is tainted with void energy. Collect several samples of the sap as you can, and I will combine it to make a Large Sticky Mass.", ["objectivesText"] = "Collect 5 Corrupted Sap . Progress: Have you found the sap?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 236964, 237019 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 238069, ["x"] = 0.494, ["y"] = 0.544 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 238069, ["x"] = 0.494, ["y"] = 0.544 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard" },
[87426] = { ["id"] = 87426, ["name"] = "Flavorful Scraps", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 87426 }, ["description"] = "Plenty of profit to be made scavenging these sands, but watch out for the monster. It's hungry, I've seen it drag scavengers under the sands! You can trick it, I fed it once. Tossed it some scraps. You need the tastiest garbage to lure it out. Collect what you can and I will help sort it to find the most flavorful scraps .", ["objectivesText"] = "Collect 24 Discarded Scraps Progress: Did you find anything tasty?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 236766, 236966, 237022 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 238591, ["x"] = 0.685, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 238591, ["x"] = 0.685, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard" },
[87455] = { ["id"] = 87455, ["name"] = "Trials and Tabulations", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 87455, 87456, 87457, 87458 }, ["description"] = "In hindsight, we should have gone drinking in neutral territory. Gidwin and I were here in Silvermoon on vacation when the Fourth War broke out. We escaped the city but left behind a... rather large bar tab. Gidwin's run off to the place we were staying to find an expensive item we'd left behind, but he's late. Would you go find him while I keep this debt collector busy? He should have been back by now.", ["objectivesText"] = "Find Gidwin Goldbraids in Silvermoon.", ["rewardGold"] = 31200, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 238730, ["x"] = 0.576, ["y"] = 0.688 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 238834, ["x"] = 0.334, ["y"] = 0.892 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 86735 }, ["questLines"] = { { ["id"] = 5784, ["name"] = "The Drinking Debt", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[87456] = { ["id"] = 87456, ["name"] = "Souvenirs Scattered", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 87455, 87456, 87457, 87458 }, ["description"] = "When Tarenar and I escaped the city before, we left some things behind. An open bar tab, sure. But we'd also bought souvenirs for some of our friends. Could you look around for them? They're somewhere in this mess.", ["objectivesText"] = "Find the souvenirs in Silvermoon. Progress: Have you found all the souvenirs? We got other things for the rest of our crew back in Suramar, but we didn't have time to mail these when we escaped.", ["rewardGold"] = 170800, ["rewardXP"] = 5885, ["rewardItems"] = { 237164, 237165, 237166 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 238732, ["x"] = 0.334, ["y"] = 0.892 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 238748, ["x"] = 0.334, ["y"] = 0.897 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.334, ["y"] = 0.892 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 87455 }, ["questLines"] = { { ["id"] = 5784, ["name"] = "The Drinking Debt", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[87457] = { ["id"] = 87457, ["name"] = "What We Do Best", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 87455, 87456, 87457, 87458 }, ["description"] = "That spider! It blasted me right as I walked in the door. I've been gooped by one spider too many, what with all the nerubians we've been punching lately! I saw something around its neck out of the corner of my eye. It's an artifact we found while fighting the Legion. It ought to fetch a good price. You just have to tear that spider's head off!", ["objectivesText"] = "Kill Squatter and collect the Antique Necklace in Silvermoon. Progress: This necklace was in a camp we cleared of demons. Must've been for a ritual, but we stopped them from cursing it.", ["rewardGold"] = 683200, ["rewardXP"] = 14705, ["rewardItems"] = { 237167 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3365, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 238732, ["x"] = 0.334, ["y"] = 0.892 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 238748, ["x"] = 0.334, ["y"] = 0.897 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.334, ["y"] = 0.892 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 87455 }, ["questLines"] = { { ["id"] = 5784, ["name"] = "The Drinking Debt", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[87458] = { ["id"] = 87458, ["name"] = "Debts Paid", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 87455, 87456, 87457, 87458 }, ["description"] = "That's everything, I think. Can't believe it's been so long since the Fourth War. We left in such a rush. Let's get that necklace to Tarenar. He's been waiting long enough.", ["objectivesText"] = "Return to Tarenar Sunstrike in Silvermoon.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 263437, 263438 }, ["rewardChoices"] = { 263437, 263438 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3365, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 238748, ["x"] = 0.334, ["y"] = 0.897 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 238730, ["x"] = 0.576, ["y"] = 0.688 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.334, ["y"] = 0.897 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 87456, 87457 }, ["questLines"] = { { ["id"] = 5784, ["name"] = "The Drinking Debt", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[87475] = { ["id"] = 87475, ["name"] = "Sureki Incursion: Hold the Wall", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 87475 }, ["description"] = "Flames! Those chitinous vermin are relentless! We've received reports from Auralia Steelstrike that a small force of nerubians are harassing the outer perimeter of the city. Regroup with our allies on the outskirts of Mereldar and join the fight!", ["objectivesText"] = "Assist the Flame's Radiance in pushing back the Sureki outside Mereldar. Progress: We must hold the line against these Sureki. Push them back!", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 239546 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 55 }, { ["id"] = 3283, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 }, { ["mapID"] = 2215, ["npcID"] = 241344, ["x"] = 0.405, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 4885 } },
[87477] = { ["id"] = 87477, ["name"] = "Sureki Incursion: Southern Swarm", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 87477 }, ["description"] = "The Sureki aren't known to give up their assaults so easily. Reports from our southern holdings have warned of a swarm stirring along the mountain range. I don't know whether they plan to hit Tenir's Ascent or Beledar's Bounty, but we cannot wait for them to make the first move. Join our allies and intercept the swarm!", ["objectivesText"] = "Assist the Flame's Radiance in pushing back the Sureki swarm in southern Hallowfall . Progress: The nerubians have brought every foul, multi-limbed horror from the depths in this swarm! We cannot allow our holdings to fall!", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 239546 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 55 }, { ["id"] = 3283, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 }, { ["mapID"] = 2215, ["npcID"] = 241340, ["x"] = 0.52, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 4885 } },
[87480] = { ["id"] = 87480, ["name"] = "Sureki Incursion: The Eastern Assault", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 87480 }, ["description"] = "There's no time to rest, <name>! Our earthen allies in eastern Hallowfall have spotted a Sureki battalion preparing to attack Dunelle's Kindness--they must be targeting the Dawntower! Flame's Radiance reinforcements are securing the town and Lothar's Landing as we speak. Head east and lend what aid you can!", ["objectivesText"] = "Assist the Flame's Radiance and disrupt the Sureki's eastern assault. Progress: We will hold this position. Go, help Dunelle's Kindness below!", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 239546 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 55 }, { ["id"] = 3283, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 }, { ["mapID"] = 2215, ["npcID"] = 241093, ["x"] = 0.764, ["y"] = 0.458 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 4885 } },
[87496] = { ["id"] = 87496, ["name"] = "Benefit Packages", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 87496 }, ["description"] = "Times are rough, so the cartels have been tryin' out this new business strategy called \"employee retention.\" Never heard of it before, but it sounds fancy. Anyway, I'm pretty sure it means givin' employees the privilege of buyin' stuff from the company stores after you work for 'em long enough. Go check out what the cartels got for sale. See if anything catches your eye before you start workin'.", ["objectivesText"] = "Visit each cartel's quartermaster in Undermine . Progress: You can find the sellers at each cartel's headquarters.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231049, ["x"] = 0.428, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231049, ["x"] = 0.428, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83096 } },
[87540] = { ["id"] = 87540, ["name"] = "Begin the Sky Assaults", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["storyline"] = { 87540 }, ["rewardGold"] = 2775, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[87546] = { ["id"] = 87546, ["name"] = "Warrant: Purple Peat", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 87546 }, ["series"] = { 90125 }, ["description"] = "In restoring the eco domes, much of the contaminated plant life was removed, allowing the soil to heal. However, one corrupted lasher escaped our notice. Nicknamed \"Purple Peat\" by the dome technicians, it continues to spread its roots and seeds into Eco-Dome: Primus. The plant hides safely in an old stasis cell outside the dome. Construct a device to remove the protective cell and expose the plant so it can be eliminated.", ["objectivesText"] = "Combine a Large Sticky Voidmass , Energy Encapsulation and a Untethered Battery create a create a key to unlock the stasis sphere.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 236937, 236964, 237485, 239249, 239276, 245255 }, ["starts"] = { { ["x"] = 0.485, ["y"] = 0.583, ["mapID"] = 2472, ["npcID"] = 238919 } }, ["ends"] = { { ["x"] = 0.485, ["y"] = 0.583, ["mapID"] = 2472, ["npcID"] = 238919 } }, ["coords"] = { ["mapID"] = 2472, ["x"] = 0.485, ["y"] = 0.583 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15336 } }, ["questGiverID"] = 238919, ["questTurnInID"] = 238919, ["questType"] = "standard", ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2472 },
[87547] = { ["id"] = 87547, ["name"] = "What's Your Specialty?", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 1519, ["mapID"] = 2022, ["storyline"] = { 87547, 87555, 87562 }, ["description"] = "The Dragon Isles is a dangerous and uncharted place. We'll need to get you prepared. You're strong enough now that you should choose a combat specialization. This will unlock a new array of abilities for you to face the dangers within the Dragon Isles. Go ahead and choose your combat specialization.", ["objectivesText"] = "Choose your combat specialization. Progress: Having trouble? You can find your combat specialization beside your spellbook.", ["rewardXP"] = 505, ["rewardItems"] = { 25470, 25474, 175165, 175166, 246462 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 238913, ["x"] = 0.82, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 238913, ["x"] = 0.82, ["y"] = 0.314 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.82, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 55991 }, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 57, ["flags"] = 0 }, { ["id"] = 5458, ["name"] = "The Dragon Isles", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6024, ["name"] = "Welcome to the Waking Shore", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5458, ["questLineOrder"] = 2 }, { ["id"] = 321, ["title"] = "Exile's Reach", ["questLineID"] = 6024, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[87548] = { ["id"] = 87548, ["name"] = "A Dozen Veilshards", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 87548 }, ["description"] = "Yes I know of Veilshards, a highly prized treasure, often the target of thieves! But rest assured, the upstanding citizen Om'sto , would not be involved in such crimes. To find Veilshards you need only look to the rats of this city, they are the craftiest of thieves! Follow a Thieving Scurrier to its nest, and you're bound to uncover a gem among it's stolen hoard. Bring back what you find, and we'll bundle them into a neat dozen for you.", ["objectivesText"] = "Collect 12 Stolen Veilshards Progress: Did follow the rats?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237266, 237352 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 238486, ["x"] = 0.465, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 238486, ["x"] = 0.465, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard" },
[87550] = { ["id"] = 87550, ["name"] = "Week 2: We're Really Taking Off", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2248, ["description"] = "It's Dastardly Duos' second week! Twice the brutality, twice the fun! Win a match this week for even more rewards!", ["rewardGold"] = 34100, ["rewardItems"] = { 239440 }, ["starts"] = { { ["npcID"] = 234296, ["x"] = 0.528, ["y"] = 0.516, ["mapID"] = 2248 } }, ["ends"] = { { ["npcID"] = 234296, ["x"] = 0.528, ["y"] = 0.516, ["mapID"] = 2248 } }, ["coords"] = { ["x"] = 0.528, ["y"] = 0.516, ["source"] = "quest_giver", ["mapID"] = 2248 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 86503 } },
[87551] = { ["id"] = 87551, ["name"] = "Week 3: Spread the Word", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 87551 }, ["description"] = "Hey, you wanna help out the organization? you know, spread the word? Next time you're in a match, throw your Dastardly Banner down in the arena. Show support! But be careful -- your opponents might take offense and come straight after you...", ["objectivesText"] = "Place your Dastardly Banner during a match, then win the match. Progress: Don't forget to use your banner inside the area. Your opponents will hate it, but the fans will love it!", ["rewardGold"] = 34100, ["rewardItems"] = { 239007, 239440 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 234296, ["x"] = 0.528, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 234296, ["x"] = 0.528, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 87550 } },
[87552] = { ["id"] = 87552, ["name"] = "Week 4: They've Heard of You", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 87552 }, ["description"] = "You're making a name for yourself, <race>. You keep the victories coming and I'll keep the tickets selling.", ["objectivesText"] = "Win a Dastardly Duos match, then speak with Vinnie Sweets .", ["rewardGold"] = 29200, ["rewardItems"] = { 239440 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 234296, ["x"] = 0.528, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 234296, ["x"] = 0.528, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 87551 } },
[87553] = { ["id"] = 87553, ["name"] = "Week 5: Another Amazing Week!", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 87553 }, ["description"] = "<Vinnie is busy counting money> What? Oh, hey <name>. Here to fill more seats-- I mean... here for another match? Great!", ["objectivesText"] = "Win a Dastardly Duos match, then speak with Vinnie Sweets . Progress: Speak with Xyggie Marou sign up for another match. Strike fear into your foes!", ["rewardGold"] = 34100, ["rewardItems"] = { 239440 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 234296, ["x"] = 0.528, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 234296, ["x"] = 0.528, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 87552 } },
[87554] = { ["id"] = 87554, ["name"] = "Week 6: It's the Finale!", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 87554 }, ["description"] = "This is it, the end of the event. Let's go out with a roar! Put on one last good show and we can count our money together!", ["objectivesText"] = "Win a Dastardly Duos match, then speak with Vinnie Sweets .", ["rewardGold"] = 29200, ["rewardItems"] = { 239440 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 234296, ["x"] = 0.528, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 234296, ["x"] = 0.528, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 87553 } },
[87555] = { ["id"] = 87555, ["name"] = "Home Is Where the Hearth Is", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 1519, ["mapID"] = 2022, ["storyline"] = { 87547, 87555, 87562 }, ["description"] = "Before you head off, you'll want to get yourself a Hearthstone . This little stone will return you to the inn where you last bound it to. It's not much of an \"inn\", but the explorer's have a tent set up. Test out that new mount of yours and ride over to Happy Hal. He'll get you sorted out with a Hearthstone .", ["objectivesText"] = "Ride your mount, then speak with Happy Hal to get a Hearthstone bound to the Wild Coast. Progress: Happy Hal nearby can get you set up with a Hearthstone .", ["rewardGold"] = 200, ["rewardXP"] = 505, ["rewardItems"] = { 6948 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 238913, ["x"] = 0.82, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 238913, ["x"] = 0.82, ["y"] = 0.314 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.82, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 87547 }, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 68, ["flags"] = 0 }, { ["id"] = 5458, ["name"] = "The Dragon Isles", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6024, ["name"] = "Welcome to the Waking Shore", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5458, ["questLineOrder"] = 2 }, { ["id"] = 321, ["title"] = "Exile's Reach", ["questLineID"] = 6024, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[87562] = { ["id"] = 87562, ["name"] = "Aiding the Dragon Isles", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 1519, ["mapID"] = 2022, ["storyline"] = { 87547, 87555, 87562 }, ["description"] = "It's time for us to part ways. I have pressing business further within the Dragon Isles in a place called the Azure Span. Toddy Whiskers of the Dragonscale Expedition could use your help. Safe travels, <name>. I look forward to our next meeting!", ["objectivesText"] = "Meet Toddy Whiskers to begin your adventure in the Dragon Isles.", ["rewardXP"] = 505, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 238913, ["x"] = 0.82, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189022, ["x"] = 0.82, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.82, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 87555 }, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 69, ["flags"] = 0 }, { ["id"] = 5458, ["name"] = "The Dragon Isles", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 6024, ["name"] = "Welcome to the Waking Shore", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5458, ["questLineOrder"] = 2 }, { ["id"] = 321, ["title"] = "Exile's Reach", ["questLineID"] = 6024, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[87569] = { ["id"] = 87569, ["name"] = "Legally Mandated Break", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83323, 84788, 84791, 85715, 85717, 85732, 85733, 85758, 85759, 85769, 85771, 85773, 85797, 85826, 85854, 85861, 85874, 85888, 85946, 86311, 86313, 86314, 86315, 86317, 86318, 86319, 86320, 86321, 86410, 86412, 86418, 87569, 87588 }, ["objectivesText"] = "Arrived at Shipping and Handling Garage Take your Legally Mandated Break", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15347 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5643, ["name"] = "FF Task List", ["orderIndex"] = 19, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Arrived at Shipping and Handling Garage", ["amount"] = 0, ["type"] = 19, ["objectID"] = 36572, ["orderIndex"] = 0 }, { ["text"] = "Take your Legally Mandated Break", ["amount"] = 1, ["type"] = 0, ["objectID"] = 239001, ["orderIndex"] = 1 } }, ["activities"] = { ["scenarios"] = { { ["id"] = 2940, ["name"] = "Shipping & Handling", ["areaID"] = 0 } } }, ["db2LabelIDs"] = { 4101 }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[87581] = { ["id"] = 87581, ["name"] = "No More Walkin' Here", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 84352, 86618, 87581 }, ["description"] = "We gotta do something about how long it's taking to get you around. Luckily, I know just the gal. Go meet Nanny Talullah at Shipping and Handling and see if she'll lend you some wheels.", ["objectivesText"] = "Meet Nanny Talullah on the third floor at Shipping and Handling.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 238946, ["x"] = 0.432, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 227210, ["x"] = 0.374667, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83167 }, ["questLines"] = { { ["id"] = 5772, ["name"] = "Shipping? Handled.", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[87582] = { ["id"] = 87582, ["name"] = "Delves: Site of Madness", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 87582 }, ["description"] = "Hey, pal. Some real weird stuff has been happening south of Gutterville. Some of my friends have gone missing, and their family's worried about them. How about you take that can-do attitude of yours down there and see if you can figure out what happened? <Paks scratches his chin before looking back at you.> I'm sure there will be some compensation to make it up to you too. Trust me.", ["objectivesText"] = "Complete the Excavation Site 9 delve on any difficulty. Progress: Yo, did you figure out what happened down there?", ["rewardGold"] = 1239200, ["rewardXP"] = 23530, ["rewardCurrencies"] = { { ["id"] = 3118, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231045, ["x"] = 0.434, ["y"] = 0.514667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231045, ["x"] = 0.434, ["y"] = 0.514667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.514667 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83096 }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346, ["db2QuestHubAreaPoiID"] = 8189, ["db2QuestInfoID"] = 288, ["db2QuestInfoName"] = "Delve" },
[87583] = { ["id"] = 87583, ["name"] = "Delves: The Sluice Contains the Juice", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 87583 }, ["description"] = "Buddy, pal, <class>. Some Darkfuse have taken root down in the sewers here in Undermine. They're shaking down hard-working goblins for cash, stealing their lunches, and sometimes even destroying their flamingo lawn ornaments! Those Darkfuse suffer from a real lack of decorum, let me tell you. I know you'll do the right thing and help us out, especially after such a tearjerker of a story.", ["objectivesText"] = "Complete the Sidestreet Sluice delve on any difficulty.", ["rewardGold"] = 1239200, ["rewardXP"] = 23530, ["rewardCurrencies"] = { { ["id"] = 3118, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 231045, ["x"] = 0.434, ["y"] = 0.514667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 231045, ["x"] = 0.434, ["y"] = 0.514667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.514667 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83096 }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346, ["db2QuestHubAreaPoiID"] = 8189, ["db2QuestInfoID"] = 288, ["db2QuestInfoName"] = "Delve" },
[87588] = { ["id"] = 87588, ["name"] = "Bash that Trash", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83323, 84788, 84791, 85715, 85717, 85732, 85733, 85758, 85759, 85769, 85771, 85773, 85797, 85826, 85854, 85861, 85874, 85888, 85946, 86311, 86313, 86314, 86315, 86317, 86318, 86319, 86320, 86321, 86410, 86412, 86418, 87569, 87588 }, ["objectivesText"] = "Arrived at The Heaps Trash Compacted Trash Compacted", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15347 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5643, ["name"] = "FF Task List", ["orderIndex"] = 17, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Arrived at The Heaps", ["amount"] = 0, ["type"] = 19, ["objectID"] = 36624, ["orderIndex"] = 0 }, { ["text"] = "Trash Compacted", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 1 }, { ["text"] = "Trash Compacted", ["amount"] = 10, ["type"] = 0, ["objectID"] = 239236, ["orderIndex"] = 2 } }, ["activities"] = { ["scenarios"] = { { ["id"] = 2941, ["name"] = "Shipping & Handling", ["areaID"] = 0 } } }, ["db2LabelIDs"] = { 4101 }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[87597] = { ["id"] = 87597, ["name"] = "A Bag of Veilshards", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 87597 }, ["description"] = "I myself could sell you Veilshards, but my own supply has been stolen. The vermin of this city will not hesitate to steal them when my back is turned. Follow any Thieving Scurrier to its nest, and you are sure to locate some stolen shards. To assist you, I will provide a device capable of tracking the thieving vermin. Recover enough Veilshards to satisfy both our needs.", ["objectivesText"] = "Collect 18 Om'sto's Veilshards Progress: Did you locate the veilshards?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237266, 237353, 237354, 237356 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 238486, ["x"] = 0.465, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 238486, ["x"] = 0.465, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard" },
[87672] = { ["id"] = 87672, ["name"] = "Void is in the Air", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 87388, 87391, 87672, 88653, 88708, 88755 }, ["series"] = { 87391 }, ["description"] = "We void elves all face the same risk... that should our resilience falter, madness awaits. <Kelia frowns in Matrean's direction.> The caves below are steeped in Void's vile touch. Void Surges erupt from the earth, creating a miasma of filth that fills the nesting grounds. <She hands you a magical device.> Take this. It will capture the surges of dark energy bursting from the soil. We will study them safely back at the Ingress.", ["objectivesText"] = "Capture 3 Void Surges in the Bladeburrows caves. Progress: The Voidstorm threatens our very existence. We cannot stay long.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 267614 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 236930, ["x"] = 0.412, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 236930, ["x"] = 0.412, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 87388, 87391 }, ["questLines"] = { { ["id"] = 6010, ["name"] = "The Void Peers Back", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[87759] = { ["id"] = 87759, ["name"] = "Encapsulated Void", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 87759 }, ["objectivesText"] = "Subdue Void Creatures or Kill Players Subdue Void Creatures", ["rewardXP"] = 13690, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16648 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 15, ["amount"] = 1, ["objectID"] = 0, ["text"] = "Subdue Void Creatures or Kill Players" }, { ["orderIndex"] = 1, ["type"] = 9, ["amount"] = 7, ["objectID"] = 466 }, { ["orderIndex"] = 2, ["type"] = 0, ["amount"] = 10, ["objectID"] = 239434, ["text"] = "Subdue Void Creatures" } }, ["db2LabelIDs"] = { 6047 }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444, ["db2QuestInfoID"] = 113, ["db2QuestInfoName"] = "PvP World Quest" },
[88652] = { ["id"] = 88652, ["name"] = "Faceless Mask of the Nemesis", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["storyline"] = { 88652 }, ["description"] = "There are those enemies that you will battle or come into conflict over and over. Thought defeated they return from the shadows to attack you again and again. This is is the heart of a true nemesis. And, these are the enemies that will live on forever no matter what you do.", ["objectivesText"] = "Return the Faceless Mask of the Nemesis to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Nemesis on the altar.", ["rewardItems"] = { 237434 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 237434 } },
[88653] = { ["id"] = 88653, ["name"] = "Yolks on You", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 87388, 87391, 87672, 88653, 88708, 88755 }, ["series"] = { 87388, 88755 }, ["description"] = "Our research has proven fruitful. I can feel the promise of power beckoning. Do you hear it, <name>? The apex predator calls to us. The beast must be nearby. We must gather tribute. Yes... we must offer it a gift of vitality! We must meet it bathed in the essence of the young... Some of the smaller creatures are nesting in the tunnels below. Break a few eggs and bathe in their juices. Then, perhaps, the beast will be drawn to the smell!", ["objectivesText"] = "Bathe yourself in bestial fluids by destroying 15 Blistercreep Eggs in the Bladeburrows caves. Progress: So much flesh and bone and meat. How can we resist?", ["rewardGold"] = 309800, ["rewardXP"] = 12845, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 236908, ["x"] = 0.412, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 236908, ["x"] = 0.412, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 87388, 87391 }, ["questLines"] = { { ["id"] = 6010, ["name"] = "The Void Peers Back", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[88655] = { ["id"] = 88655, ["name"] = "Outbound for Outland", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["description"] = "Snakes! Why'd it have to be snakes? Ve'nari says they used to have snake-like things on K'aresh before the Devouring. None of 'em survived. They still got worms, but that's nae what we're after. I know just the place--my ol' stomping grounds in Nagrand on Outland. Let's use this infernal contraption of a portal to get there.", ["objectivesText"] = "Regroup with Hemet Nesingwary at the Nesingwary Safari in Nagrand on Outland.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 107, ["npcID"] = 18180, ["x"] = 0.522, ["y"] = 0.314667 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 107, 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 87415 }, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 107 },
[88656] = { ["id"] = 88656, ["name"] = "Comfort Stones", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 107, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88657, 88658, 88660, 88661, 88662 }, ["description"] = "Right then. We're gonna need tae collect things tae make the snakes comfortable on K'aresh. Let's get 'em some bedding. Some of the most important things are rocks! Snakes can sun themselves atop a rock or hide under it. Those nearby earth elementals were always a pain in our side. See if you can get some rocks from 'em.", ["objectivesText"] = "Collect 20 Smooth Stones from Tortured Earth Spirits, Enraged Crushers, or Shattered Rumblers. Progress: It's nice to be helpin' these critters rather than hunting 'em. The angry elementals don't count!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237572 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 107, ["npcID"] = 18180, ["x"] = 0.522, ["y"] = 0.314667 } }, ["ends"] = { { ["mapID"] = 107, ["npcID"] = 18180, ["x"] = 0.522, ["y"] = 0.314667 } }, ["coords"] = { ["mapID"] = 107, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.314667 }, ["mapCandidates"] = { ["npc"] = { 107 }, ["zone"] = { 3518 } }, ["questType"] = "standard", ["sourceQuests"] = { 88655 }, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 107 },
[88657] = { ["id"] = 88657, ["name"] = "Zangarmoss", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 107, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88656, 88658, 88660, 88661, 88662 }, ["description"] = "Next up, we'll be needin' some moss for their beds. Sorry to say, but we need to go into the slimy marsh for 'em. The naga control that place. It grows on their mushroom trees. They're also fond o' munching on it or something foul. Fastest way to Zangarmarsh is through the pass to the north. If it were me, I'd look around the Darkcrest Shore.", ["objectivesText"] = "Collect 15 Marsh Moss in Zangarmarsh. Progress: How much you got? It's one o' the last things we need before we head back to K'aresh.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237757 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 107, ["npcID"] = 18180, ["x"] = 0.522, ["y"] = 0.314667 } }, ["ends"] = { { ["mapID"] = 107, ["npcID"] = 18180, ["x"] = 0.522, ["y"] = 0.314667 } }, ["coords"] = { ["mapID"] = 107, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.314667 }, ["mapCandidates"] = { ["npc"] = { 107 }, ["zone"] = { 3521 } }, ["questType"] = "standard", ["sourceQuests"] = { 88656, 88658 }, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 107 },
[88658] = { ["id"] = 88658, ["name"] = "Sneks and Things", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 107, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88656, 88657, 88660, 88661, 88662 }, ["description"] = "O' course, we also need some snakes. That's the whole point o' why we came out here in the first place. You can find the small ones we want down in the Telaari Basin to the south. Just rustle their dens an' they'll come slitherin' out. That's where the plants they like grow. Speaking of which, make sure to get some o' them fragrant plants while you're at it. Ye might not know this, but snakes have a keen sense o' smell.", ["objectivesText"] = "Collect 10 Nagrand Snakes and 20 Fragrant Dreaming Glory . Progress: How many do you have? I canna tell. Your pack always looks so full.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237601, 237604 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 107, ["npcID"] = 18180, ["x"] = 0.522, ["y"] = 0.314667 } }, ["ends"] = { { ["mapID"] = 107, ["npcID"] = 18180, ["x"] = 0.522, ["y"] = 0.314667 } }, ["coords"] = { ["mapID"] = 107, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.314667 }, ["mapCandidates"] = { ["npc"] = { 107 }, ["zone"] = { 3518 } }, ["questType"] = "standard", ["sourceQuests"] = { 88655 }, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 107 },
[88659] = { ["id"] = 88659, ["name"] = "More Cozy Beds", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 85459, 85460, 85461, 85462, 85465, 85470, 85481, 85710, 85721, 86342, 88659, 88975, 88980, 88981, 89056, 89057, 89065, 89192, 89195, 89197, 89198, 89209, 89210, 89212, 89213, 89221, 89238, 89240, 89242, 89254, 89297 }, ["description"] = "We need all sorts o' replacements for things--stones and moss for the beds, and more o' them stinky flowers. Remember, ye can get the stone from the earth elementals in Nagrand. The flowers are down in the Telaari Basin there in Nagrand as well. An' the moss is over at the Darkcrest Shore in Zangarmarsh. It'll be a good excuse for me tae go see the gang again. Meet ye on the other side o' the portal.", ["objectivesText"] = "Collect 10 Fragrant Dreaming Glory , 10 Marsh Moss , and 10 Smooth Stones in Nagrand and Zangarmarsh on Outland. Progress: Have ye got it all?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237572, 237604, 237757 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 5 }, { ["id"] = 3284, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5704, ["name"] = "Eco-Dome Repeatables", ["orderIndex"] = 24, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[88660] = { ["id"] = 88660, ["name"] = "Snakes on a Plane", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 107, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88656, 88657, 88658, 88661, 88662 }, ["description"] = "Last, but certainly not least, we need to get those two snakes off o' me plane! I dunno how long snakes normally live, but it seems like those two have been there forever. And they always look at me funny if I come near. Maybe you could go get 'em?", ["objectivesText"] = "Gather the two snakes off of the crashed plane at the Nesingwary Safari. Progress: You got 'em?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 107, ["npcID"] = 18180, ["x"] = 0.522, ["y"] = 0.314667 } }, ["ends"] = { { ["mapID"] = 107, ["npcID"] = 18180, ["x"] = 0.522, ["y"] = 0.314667 } }, ["coords"] = { ["mapID"] = 107, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.314667 }, ["mapCandidates"] = { ["npc"] = { 107 }, ["zone"] = { 3518 } }, ["questType"] = "standard", ["sourceQuests"] = { 88657 }, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 107 },
[88661] = { ["id"] = 88661, ["name"] = "To the Atrium", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 107, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88656, 88657, 88658, 88660, 88662 }, ["description"] = "We got what we're after. Time to head back. Before we can introduce the snakes to the ecology in the Oasis, we need to test 'em out. There are a few o' these place they call eco-domes where that's done on K'aresh. Ve'nari's portal will take us to one called the Atrium. I wish I could fly me plane there instead.", ["objectivesText"] = "Regroup with Hemet Nesingwary at the Atrium on K'aresh.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 107, ["npcID"] = 18180, ["x"] = 0.522, ["y"] = 0.314667 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 236846, ["x"] = 0.484, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 107, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.314667 }, ["mapCandidates"] = { ["npc"] = { 107, 2371 }, ["zone"] = { 3518 } }, ["questType"] = "standard", ["sourceQuests"] = { 88660 }, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[88662] = { ["id"] = 88662, ["name"] = "What's in a Name?", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88656, 88657, 88658, 88660, 88661 }, ["description"] = "Though they clearly don't like me, I think the two snakes from me crashed plane have taken a liking to you. Ye want to name 'em?", ["objectivesText"] = "Name the female and male snake . Progress: What have ye decided on?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 52921, 52938, 52941, 52966, 52970, 52972, 84105, 131844, 131846 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 236846, ["x"] = 0.484, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 236846, ["x"] = 0.484, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 88661 }, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[88663] = { ["id"] = 88663, ["name"] = "Scales and Measures", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88664, 88665 }, ["description"] = "Now to get some vital statistics. Ve'nari and her people have all sorts o' contraptions for doing things around here. This li'l robot is gonna use the thing the snakes are on to take some measurements. Just speak with it when you're ready. I can get readings for the rest o' the snakes while you're off doing other things.", ["objectivesText"] = "Speak with the Data Collection Drone to complete a data analysis of the named snakes. Progress: Let me know what that thing figures out an' we'll move on to other things. We gotta do some stuff before we can head back to the Oasis.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 236846, ["x"] = 0.484, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 236846, ["x"] = 0.484, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 88662 }, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[88664] = { ["id"] = 88664, ["name"] = "Nagrandification", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88663, 88665 }, ["description"] = "Remember all those stinky plants ye gathered up in Nagrand? Would ye mind replanting 'em? We don't have to plant 'em all right now. Just enough to test and ensure they'll take to the soil of K'aresh. We'll be needin' a lot more plants than this eventually.", ["objectivesText"] = "Plant 6 Fragrant Dreaming Glory. Progress: I'm gonna have to make certain to stay upwind o' those \"fragrant\" plants.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 236846, ["x"] = 0.484, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 236846, ["x"] = 0.484, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 88662 }, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[88665] = { ["id"] = 88665, ["name"] = "Follow Your Tongue", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88663, 88664 }, ["description"] = "Now it's time to move north into Eco-Dome: Primus. That's a mouthful. Take one o' the remaining stinky flowers an' lead the snakes there.", ["objectivesText"] = "Lead the Nagrand Snakes to Eco-Dome: Primus.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 236846, ["x"] = 0.484, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 236890, ["x"] = 0.49, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 88663, 88664 }, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[88666] = { ["id"] = 88666, ["name"] = "Mossy Beds", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88667, 88668 }, ["description"] = "I've put together the rocks an' the moss that ye collected in Nagrand. Now it's time to see if the snakes like 'em. I spread 'em out around the eco-dome so you could test 'em out for differences. While you're doing that, I'll make preparations for getting 'em all to the Oasis.", ["objectivesText"] = "Test 8 Mossy Snake Beds.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 236890, ["x"] = 0.49, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 236890, ["x"] = 0.49, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 88665 }, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[88667] = { ["id"] = 88667, ["name"] = "Water Snakes", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88666, 88668 }, ["description"] = "Oh no! Some o' the snakes are having trouble adapting. They aren't drinkin' as much as they should an' are dehydrated. Quick, <name>. Take this waterin' can and give 'em a good dousing.", ["objectivesText"] = "Use Hemet's Waterin' Can to water 10 Parched Snakes .", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 237898 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 236890, ["x"] = 0.49, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 236890, ["x"] = 0.49, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 88665 }, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[88668] = { ["id"] = 88668, ["name"] = "Ophidian Portation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88666, 88667 }, ["description"] = "Our tests are successful! Time to move to the Oasis. Ve'nari gave me these \"portation\" devices to quickly get the snakes o'er there. Why don't you take care o' Ember and Indigo, and I'll take care o' the rest? They've been giving me the side-eye ever since I moved 'em here.", ["objectivesText"] = "Use Ve'nari's Portation Tags on the two named snakes to transport them to the Oasis.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 236890, ["x"] = 0.49, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 88666, 88667 }, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[88669] = { ["id"] = 88669, ["name"] = "Nesting Time", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88670, 88671, 88672 }, ["description"] = "We need to set up a nice home for these two, especially since Ember's expectin'. I took a look around an' spotted a shady place under a tree not far from here. There's all sorts o' things to make 'em comfortable an' safe. Use Ve'nari's portation tags again to summon in everything ye need.", ["objectivesText"] = "Set up a home for the two named snakes. Progress: How'd it go? Did they like their new place?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 88668 }, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[88670] = { ["id"] = 88670, ["name"] = "Soothing Serpents", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88669, 88671, 88672 }, ["description"] = "Most o' the snakes did not like Ve'nari's teleport. Others were cloned by Om'talad, an' they don't like that either. They're clearly agitated an' I'm afraid they're gonna hurt themselves. I've got this flute. Don't ask. I can't even play the darned thing. Would ye take it out there an' soothe the snakes with some calming melodies?", ["objectivesText"] = "Use Hemet's Soothin' Flute to soothe 15 Agitated Snakes . Progress: I'm certain you're much better at playin' that thing than me.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 238216 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 88668 }, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[88671] = { ["id"] = 88671, ["name"] = "Eggstra Eggs", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88669, 88670, 88672 }, ["description"] = "I've been talkin' with the others about food for the snakes, an' we think we have a solution. The k'arrocs have been prospering a wee bit too much for the ecology o' the Oasis. If ye get some o' their eggs, that should be enough for now so we can feed the snakes.", ["objectivesText"] = "Collect 6 K'arroc Eggs . Progress: How goes the egg pilferin'?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 238242 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 88669, 88670 }, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[88672] = { ["id"] = 88672, ["name"] = "Snakelets!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 88655, 88656, 88657, 88658, 88660, 88661, 88662, 88663, 88664, 88665, 88666, 88667, 88668, 88669, 88670, 88671, 88672 }, ["series"] = { 88669, 88670, 88671 }, ["description"] = "Speaking o' eggs--I checked, an' Ember has laid her clutch. It's almost time to hatch us some babies! Meet me back at the nest an' we can welcome our first snakelets to K'aresh.", ["objectivesText"] = "Help with hatching the snakelets. Progress: What an excitin' time.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 88671 }, ["questLines"] = { { ["id"] = 5791, ["name"] = "Sneks for K'aresh", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 283, ["title"] = "Ecological Succession", ["questLineID"] = 5791, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
