[88696] = { ["id"] = 88696, ["name"] = "The Devouring Citadel", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16215, ["mapID"] = 2424, ["storyline"] = { 88696, 88697, 88698, 88699, 88700, 88701, 88702, 88703, 88704, 88705, 88706, 90777, 91417, 91426, 94957 }, ["description"] = "I must return to Silvermoon, but Turalyon has commanded all able-bodied champions of the Light to meet him at the muster point outside the Voidspire. The forces of the Devouring Host will fall, <class>. One way, or the other.", ["objectivesText"] = "Report to Turalyon at the Voidspire muster point: The Approach.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2424, ["npcID"] = 247414, ["x"] = 0.53, ["y"] = 0.585 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 239810, ["x"] = 0.454, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2424, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.585 }, ["mapCandidates"] = { ["npc"] = { 2405, 2424 }, ["zone"] = { 16215 } }, ["questType"] = "standard", ["sourceQuests"] = { 90777 }, ["questLines"] = { { ["id"] = 5792, ["name"] = "Foothold", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5792, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[88697] = { ["id"] = 88697, ["name"] = "Clarity of Purpose", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15458, ["mapID"] = 2405, ["storyline"] = { 88696, 88697, 88698, 88699, 88700, 88701, 88702, 88703, 88704, 88705, 88706, 90777, 91417, 91426, 94957 }, ["description"] = "The ethereals on the nearby plateau are forcing us to ground our heavier weapons. We'll need to neutralize their turrets before we can begin our assault on the Voidspire. Speak to Umbric and he'll help you gain a tactical understanding of the battlefield.", ["objectivesText"] = "Use Umbric's Void Scryer to observe the current tactical situation. Progress: Turalyon's focus is on the obstacle in front of him, but there's more to this fight than just armies and ramparts.", ["rewardGold"] = 256200, ["rewardXP"] = 10270, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 239810, ["x"] = 0.454, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 239828, ["x"] = 0.454, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 88696 }, ["questLines"] = { { ["id"] = 5792, ["name"] = "Foothold", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5792, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[88698] = { ["id"] = 88698, ["name"] = "Master of Mayhem", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15458, ["mapID"] = 2405, ["storyline"] = { 88696, 88697, 88698, 88699, 88700, 88701, 88702, 88703, 88704, 88705, 88706, 90777, 91417, 91426, 94957 }, ["description"] = "<name>, ethereals have been striking out from the Ethereum Overcroft, harassing our Vanguard forces where they find them. If you can bring the fight to them, it'll take the pressure off our muster. Can you do that for us?", ["objectivesText"] = "Wreak havoc across the Ethereum Overcroft.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 257164, 257165, 257166, 257167 }, ["rewardChoices"] = { 257164, 257165, 257166, 257167 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 239828, ["x"] = 0.454, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 239828, ["x"] = 0.454, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 88697 }, ["questLines"] = { { ["id"] = 5792, ["name"] = "Foothold", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5792, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[88699] = { ["id"] = 88699, ["name"] = "Powerless", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15458, ["mapID"] = 2405, ["storyline"] = { 88696, 88697, 88698, 88699, 88700, 88701, 88702, 88703, 88704, 88705, 88706, 90777, 91417, 91426, 94957 }, ["description"] = "Their very life force is being siphoned to power the ethereals' guns, <name>! This cannot be allowed to continue. Head into the Ethereum Overcroft and free my fellow void elves from the ethereals' clutches. With their freedom, the turrets will have no power, and Turalyon will be able to launch his warframes.", ["objectivesText"] = "Free the captured void elves to silence the Overcroft's turrets. Progress: We can't leave our people to be tortured like this.", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["rewardItems"] = { 257178, 257179, 257181, 257182 }, ["rewardChoices"] = { 257178, 257179, 257181, 257182 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3365, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 239828, ["x"] = 0.454, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 239828, ["x"] = 0.454, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 88697 }, ["questLines"] = { { ["id"] = 5792, ["name"] = "Foothold", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5792, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[88700] = { ["id"] = 88700, ["name"] = "Two Tons of Metal and Holy Fire", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15458, ["mapID"] = 2405, ["storyline"] = { 88696, 88697, 88698, 88699, 88700, 88701, 88702, 88703, 88704, 88705, 88706, 90777, 91417, 91426, 94957 }, ["description"] = "Finally, the might of our warframes can be brought to bear. With the Overcroft's air batteries silenced, our powerful warframes will be able to perform strafing runs along the spire ramparts, softening the opposition to our siege. If you'd like, you may have the honor of piloting one of these warframes for the glory of the Light!", ["objectivesText"] = "Piloting the Warframe, destroy defenders along the Voidspire ramparts. Progress: Soon, the Devouring Host will feel the wrath of the Light.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 257187, 257188, 257189, 257190, 262610 }, ["rewardChoices"] = { 257187, 257188, 257189, 257190 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 239810, ["x"] = 0.454, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 239810, ["x"] = 0.454, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 88698, 88699 }, ["questLines"] = { { ["id"] = 5792, ["name"] = "Foothold", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5792, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[88701] = { ["id"] = 88701, ["name"] = "The Memory Remains", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15458, ["mapID"] = 2405, ["storyline"] = { 88696, 88697, 88698, 88699, 88700, 88701, 88702, 88703, 88704, 88705, 88706, 90777, 91417, 91426, 94957 }, ["description"] = "Our Vanguard forces have been harrying the Devouring Host, probing for weaknesses and gathering intelligence. Unfortunately, nearly all of them have succumbed to the Host. We are too late to help those who have fallen, but perhaps we can gather something to remember them by. Will you do this, <name>? Recover mementos of the fallen so they can be returned to those they fought to protect.", ["objectivesText"] = "Recover Mementos from fallen Vanguard Scouts. Progress: Have you recovered them yet? I'm sure these keepsakes will be a source of comfort to their loved ones.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 237827, 257205, 257206, 257207, 257208 }, ["rewardChoices"] = { 257205, 257206, 257207, 257208 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 239827, ["x"] = 0.46, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 239827, ["x"] = 0.46, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questTurnInID"] = 239827, ["questType"] = "standard", ["sourceQuests"] = { 91417 }, ["questLines"] = { { ["id"] = 5792, ["name"] = "Foothold", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5792, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[88702] = { ["id"] = 88702, ["name"] = "Aegis of the Redeemer", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15458, ["mapID"] = 2405, ["storyline"] = { 88696, 88697, 88698, 88699, 88700, 88701, 88702, 88703, 88704, 88705, 88706, 90777, 91417, 91426, 94957 }, ["description"] = "We're more than just an army, <name>, even if my father doesn't see that. We're a fellowship, joined by a desire to protect those that matter to us, and those that don't have a protector of their own. And now, that protection extends to those wounded on the battlefield.", ["objectivesText"] = "Rescue the beleaguered Vanguard forces. Progress: The Devouring Host is aptly-named. Those that join it or fight with it are consumed--one way, or the other.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 257209, 257210, 257212, 257213 }, ["rewardChoices"] = { 257209, 257210, 257212, 257213 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 239827, ["x"] = 0.46, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 239827, ["x"] = 0.46, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questTurnInID"] = 239827, ["questType"] = "standard", ["sourceQuests"] = { 91417 }, ["questLines"] = { { ["id"] = 5792, ["name"] = "Foothold", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5792, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[88703] = { ["id"] = 88703, ["name"] = "The Night Before", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15458, ["mapID"] = 2405, ["storyline"] = { 88696, 88697, 88698, 88699, 88700, 88701, 88702, 88703, 88704, 88705, 88706, 90777, 91417, 91426, 94957 }, ["description"] = "Vicious voidbeasts have been snatching our officers, <name>. I've been told that you saw one from afar, through Umbric's void scryer. Those beasts are steeped in void energy, using their instinctual mastery of teleportation to strike at our most vulnerable before melting back into the shadows. Alleria has gone after them, and sent a request for another pair of eyes. You can find her at a campsite at the mouth of the gorge to the east. I'll mark it on your map.", ["objectivesText"] = "Meet Alleria at her campsite. Progress: I'm glad you could make it. It's easier to track with some support at your side.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 254884, ["x"] = 0.462, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 239826, ["x"] = 0.508667, ["y"] = 0.642 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 91426 }, ["questLines"] = { { ["id"] = 5792, ["name"] = "Foothold", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5792, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[88704] = { ["id"] = 88704, ["name"] = "The Patient Hunter", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15458, ["mapID"] = 2405, ["storyline"] = { 88696, 88697, 88698, 88699, 88700, 88701, 88702, 88703, 88704, 88705, 88706, 90777, 91417, 91426, 94957 }, ["description"] = "These void beasts are elusive, able to open temporary void portals that they can use to move short distances instantaneously. They may be beneath Turalyon's notice, but they're having devastating effects on the Vanguard's morale. Between the two of us, I'm confident we can outmaneuver them.", ["objectivesText"] = "Track down the void beasts in the gorge.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 257214, 257216, 257217, 257218 }, ["rewardChoices"] = { 257214, 257216, 257217, 257218 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 239826, ["x"] = 0.508667, ["y"] = 0.642 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 243886, ["x"] = 0.562, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.508667, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 88703 }, ["questLines"] = { { ["id"] = 5792, ["name"] = "Foothold", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5792, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[88705] = { ["id"] = 88705, ["name"] = "Killing Blow", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15458, ["mapID"] = 2405, ["storyline"] = { 88696, 88697, 88698, 88699, 88700, 88701, 88702, 88703, 88704, 88705, 88706, 90777, 91417, 91426, 94957 }, ["description"] = "I heard about these beasts, but I thought it was a rumor. Void creatures appearing out of void portals, kidnapping and eating our officers... sounds like a load of bunk. I never thought it'd happen to me. There was a big one that got me, but he ran off. Please, let's get out of here before it comes back!", ["objectivesText"] = "Escort Nadia safely from the cave.", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["rewardItems"] = { 35807, 35808, 35809, 35810, 35811, 35812, 257201, 257202, 257203, 257204 }, ["rewardChoices"] = { 257201, 257202, 257203, 257204 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3365, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 243886, ["x"] = 0.562, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 239826, ["x"] = 0.508667, ["y"] = 0.642 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 88704 }, ["questLines"] = { { ["id"] = 5792, ["name"] = "Foothold", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5792, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[88706] = { ["id"] = 88706, ["name"] = "Nothing Stands Forever", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15458, ["mapID"] = 2405, ["storyline"] = { 88696, 88697, 88698, 88699, 88700, 88701, 88702, 88703, 88704, 88705, 88706, 90777, 91417, 91426, 94957 }, ["description"] = "With the Patriarch defeated, these cunning creatures should no longer pose a serious threat. Return to Turalyon and report on our success. I will join you all shortly.", ["objectivesText"] = "Speak to Turalyon at the Voidspire muster point. Progress: My wife's hunting instinct is unmatched. If she chose that target, then it was surely a worthy one.", ["rewardGold"] = 1024800, ["rewardXP"] = 20540, ["rewardItems"] = { 257183, 257184, 257185, 257186, 264660 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3365, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 239826, ["x"] = 0.508667, ["y"] = 0.642 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 239810, ["x"] = 0.454, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.508667, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 88705 }, ["questLines"] = { { ["id"] = 5792, ["name"] = "Foothold", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5792, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[88707] = { ["id"] = 88707, ["name"] = "The Stage is Set", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15458, ["mapID"] = 2405, ["storyline"] = { 88707 }, ["description"] = "I know better than to question my wife when she's set on a target, but I trust that the target was chosen well. Our forces have acquitted themselves admirably, readying the battlefield for the main assault. Now listen, as the war council begins.", ["objectivesText"] = "Return to Turalyon.", ["rewardGold"] = 1024800, ["rewardXP"] = 20540, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 239810, ["x"] = 0.454, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard" },
[88708] = { ["id"] = 88708, ["name"] = "Violent Conclusions", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 87388, 87391, 87672, 88653, 88708, 88755 }, ["description"] = "Our research here is complete. Conclusion: the Void is attracted to this realm due to its violent nature! The Voidstorm is a melting pot of torment and savagery. The Void was drawn to this aura of endless suffering. This place is a dire threat to the ren'dorei. However, our mission here is important. Let us take our findings back to the others. Can you help me snap Matrean out of it?", ["objectivesText"] = "Convince Matrean to return to the Ingress. Progress: Was any of this worth it? Did we sin'dorei make a mistake marrying our fate to the Void?", ["rewardGold"] = 619600, ["rewardXP"] = 16055, ["rewardItems"] = { 243146 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3389, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 236930, ["x"] = 0.412, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 236930, ["x"] = 0.412, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 87672, 88653 }, ["questLines"] = { { ["id"] = 6010, ["name"] = "The Void Peers Back", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[88709] = { ["id"] = 88709, ["name"] = "The Voidspire", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16340, ["mapID"] = 2405, ["storyline"] = { 88709, 90690, 90724, 92520 }, ["series"] = { 90690 }, ["description"] = "At long last, we will ride to glory and dispense justice upon this vile creature who would levy the very Void itself against us. Today is the day Xal'atath's forces will face our judgement. Now is the hour we strike back! Come, let us make an end of this enemy.", ["objectivesText"] = "Assault the Voidspire.", ["rewardGold"] = 20496000, ["rewardXP"] = 27380, ["rewardItems"] = { 257172, 257173, 257174, 257175 }, ["rewardChoices"] = { 257172, 257173, 257174, 257175 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 75 }, { ["id"] = 3344, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 239810, ["x"] = 0.454, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 239810, ["x"] = 0.454, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 16340 } }, ["questTurnInID"] = 239810, ["questType"] = "raid", ["sourceQuests"] = { 90690 }, ["questLines"] = { { ["id"] = 5793, ["name"] = "The Voidspire", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5793, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2912, ["db2PoiUiMapID"] = 2530 },
[88710] = { ["id"] = 88710, ["name"] = "March on Quel'Danas", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16215, ["mapID"] = 2424, ["storyline"] = { 88710, 90748 }, ["series"] = { 90748, 90993 }, ["description"] = "Champion... friend... this is it. We must wrest the Darkwell from L'ura , or fall to the Void. We do not have the forces available for a second chance. Strike hard, and strike true. Watch your allies' flanks, and we will see this day won.", ["objectivesText"] = "March on Quel'Danas. Progress: How does one rebuild in the wake of so much destruction?", ["rewardGold"] = 20496000, ["rewardXP"] = 27380, ["rewardItems"] = { 257736 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3344, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 2424, ["npcID"] = 245061, ["x"] = 0.525333, ["y"] = 0.903333 } }, ["ends"] = { { ["mapID"] = 2424, ["npcID"] = 244557, ["x"] = 0.526, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 2424, ["source"] = "quest_giver", ["x"] = 0.525333, ["y"] = 0.903333 }, ["mapCandidates"] = { ["npc"] = { 2424 }, ["zone"] = { 16215 } }, ["questType"] = "raid", ["sourceQuests"] = { 90748 }, ["questLines"] = { { ["id"] = 5797, ["name"] = "March on Quel'Danas", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5797, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2913, ["db2PoiUiMapID"] = 2534 },
[88711] = { ["id"] = 88711, ["name"] = "Radiant Incursion: Toxins and Pheromones", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14752, ["mapID"] = 2215, ["storyline"] = { 88711 }, ["description"] = "Our allies in Azj-Kahet have identified a strategic location to strike at the Sureki. According to reports, our enemies are gathering toxins to fuel their war machines. Let's take this opportunity to cut off their supplies, and perhaps better our own understanding of their alchemy.", ["objectivesText"] = "Aid the Flame's Radiance in disrupting the Sureki forces in the Untamed Valley. Progress: Nerubian toxins are volatile, even for our most skill healers and medics.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 140192, 239546, 240215 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 55 }, { ["id"] = 3283, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 }, { ["mapID"] = 2255, ["npcID"] = 242591, ["x"] = 0.66, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2215, 2255 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 4885 } },
[88719] = { ["id"] = 88719, ["name"] = "A Voice from the Light", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16182, ["mapID"] = 84, ["storyline"] = { 86769, 86770, 86780, 86805, 86806, 86807, 86811, 86834, 86848, 86849, 86850, 86852, 88719, 89012, 89271, 91274, 91281 }, ["series"] = { 86769, 86770, 91281 }, ["description"] = "$p, you have been chosen. Xal'atath's army of the Void has descended upon the Sunwell. We have put our faith in the Light, and in turn, the Light has called upon the greatest champions of Azeroth. Answer this summons and stand against the Devouring Host! The fate of Quel'Danas and the world rests in your hands.", ["objectivesText"] = "Accept the summons and travel to Quel'Danas to aid the Vanguard of the Light.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 6948, 239151 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 241677, ["x"] = 0.532, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 2432, ["npcID"] = 236692, ["x"] = 0.485333, ["y"] = 0.384667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 84, 2432 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 91281 }, ["questLines"] = { { ["id"] = 5811, ["name"] = "The Light's Summons", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 335, ["title"] = "Midnight Expansion Intro Skip", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 352, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2858, ["db2PoiUiMapID"] = 2432 },
