[88755] = { ["id"] = 88755, ["name"] = "Scholarly Pursuits", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 87388, 87391, 87672, 88653, 88708, 88755 }, ["series"] = { 87388, 88653 }, ["description"] = "<name>... a favor. My research partner Matrean and I are studying the local wildlife and their relationship to the Void. I've concluded my findings, but Matrean--reckless and obsessive as ever--insists there is more to discover. Can you help convince him to return here?", ["objectivesText"] = "Meet with Kelia and Matrean in the Bladeburrows.", ["rewardGold"] = 31500, ["rewardXP"] = 1605, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3389, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 242700, ["x"] = 0.358, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 236908, ["x"] = 0.412, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.358, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86565 }, ["nextQuests"] = { 87388, 87391 }, ["questLines"] = { { ["id"] = 6010, ["name"] = "The Void Peers Back", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[88768] = { ["id"] = 88768, ["name"] = "Agents of Darkness", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86528, 86530, 86531, 86536, 86537, 86538, 86539, 86540, 86541, 86542, 86544, 86545, 88768, 89249 }, ["description"] = "When that shield goes down, Xal'atath's forces will be upon us in droves. If I'm going to detonate those manacells from afar, I'll need an opening. Thin the Devouring Host of their strongest, and the rest of Xal'atath's lackeys will be easier to fight off. We will make sure the shield goes down in the meantime. Good luck, <name>.", ["objectivesText"] = "Slay Nexus-King Salhadaar's lieutenants within Nexus-Point Mid'Ar. Progress: Have you taken them out?", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 263282 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235660, ["x"] = 0.394, ["y"] = 0.822 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235662, ["x"] = 0.38, ["y"] = 0.832 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.822 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86539 }, ["questLines"] = { { ["id"] = 5729, ["name"] = "The Night's Veil", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5729, ["questLineOrder"] = 14 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[88769] = { ["id"] = 88769, ["name"] = "The Battle of the Bridge", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 88769 }, ["series"] = { 90746 }, ["description"] = "Our elven allies have arrived. It is time to take the fight to the Darkwell. Xal'atath's forces hold the bridge and recently pushed into the harbor to reinforce their position. We must retake the harbor, launch our naval forces, and use a combined assault to take the bridge. Are you ready, <name>?", ["objectivesText"] = "Complete the Battle of the Bridge scenario.", ["rewardGold"] = 1024800, ["rewardXP"] = 20540, ["rewardItems"] = { 258122, 260233 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3365, ["amount"] = 1000 }, { ["id"] = 3391, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 240267, ["x"] = 0.456, ["y"] = 0.703333 } }, ["ends"] = { { ["mapID"] = 2424, ["npcID"] = 245061, ["x"] = 0.525333, ["y"] = 0.903333 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.703333 }, ["mapCandidates"] = { ["npc"] = { 2393, 2424 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 88942 } },
