[88803] = { ["id"] = 88803, ["name"] = "Timely Assistance", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["storyline"] = { 88803 }, ["description"] = "Hello, Champion. I have found a way that I may further assist you in the visions. Should you require it, you can call upon my assistance using this hourglass. I will form a construct that will assist you in the vision.", ["objectivesText"] = "Interact with the hourglass and gain Soridormi's assistance. Progress: I hope you find this useful.", ["starts"] = { { ["x"] = 0.519, ["y"] = 0.827, ["mapID"] = 2403, ["npcID"] = 238337 } }, ["ends"] = { { ["x"] = 0.519, ["y"] = 0.827, ["mapID"] = 2403, ["npcID"] = 238337 } }, ["coords"] = { ["mapID"] = 2403, ["x"] = 0.519, ["y"] = 0.827 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 238337, ["questTurnInID"] = 238337, ["questType"] = "standard", ["sourceQuests"] = { 87336 } },
