[88903] = { ["id"] = 88903, ["name"] = "Faceless Mask of Vengeance", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["storyline"] = { 88903 }, ["description"] = "Blood begets blood, and the weight of the fallen lingers in the air like a whispered curse. Those who stand witness to your wrath feel it creeping into their bones, driving them to strike harder, desperation masquerading as courage. Vengeance does not end violence. It only feeds the storm.", ["objectivesText"] = "Return the Faceless Mask of Vengeance to the altar within a Horrific Vision. Progress: Place the Faceless Mask of Vengeance on the altar.", ["rewardItems"] = { 238260 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 238260 } },
