[88916] = { ["id"] = 88916, ["name"] = "Radiant Incursion: Sureki's End", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14752, ["mapID"] = 2215, ["storyline"] = { 88916 }, ["description"] = "Credible intel has revealed the Sureki are regrouping for another assault. Now we take the fight to them! The Flame's Radiance have rallied at Faerin's Advance, and prepare to strike at the Sureki forces amassing in northern Azj-Kahet . Be warned, soldier. The Sureki in \"Arathi's End\" are greater in number and power. Should you require aid, our Sacredites in the field should be equipped with potions to assist you.", ["objectivesText"] = "Assist the Flame's Radiance and disrupt the Sureki forces at Arathi's End. Progress: We must not let them gather strength. Now is the time to strike!", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 239546 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 55 }, { ["id"] = 3283, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 }, { ["mapID"] = 2255, ["npcID"] = 241100, ["x"] = 0.606, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2215, 2255 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 4885 } },
[88919] = { ["id"] = 88919, ["name"] = "Into the Darkway", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10425, ["mapID"] = 2393, ["storyline"] = { 88919, 88922, 88928, 88929, 88930, 88942 }, ["description"] = "Ulen's imposter may have escaped, but I suspect I know what the cult has been doing. The Twilight's Blade must be redirecting Suramar's mana flow. Without it being sent to the correct places, our awareness dulls, our golems wilt, and our entire society risks a mana withdrawal. There is only one place they would be able to exert control over our ley lines like this, and that would be the Arcway. Go. Find them and crush them. We will meet in Silvermoon when you are done.", ["objectivesText"] = "Slay Twilight Imposter Gulkat in the Darkway Delve.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 }, { ["id"] = 3391, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 256046, ["mapID"] = 680, ["x"] = 0.705921, ["y"] = 0.74305 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 254654, ["x"] = 0.402, ["y"] = 0.328 }, { ["npcID"] = 256046, ["mapID"] = 680, ["x"] = 0.705921, ["y"] = 0.74305 } }, ["coords"] = { ["source"] = "quest_giver", ["mapID"] = 680, ["x"] = 0.705921, ["y"] = 0.74305 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 10425 } }, ["questType"] = "standard", ["sourceQuests"] = { 88929, 88930 }, ["questLines"] = { { ["id"] = 5795, ["name"] = "Gathering of the Elves", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5795, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 3003, ["db2PoiUiMapID"] = 2525 },
[88920] = { ["id"] = 88920, ["name"] = "The Kaldorei", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 88920, 88922, 88923, 88925, 88927, 88937, 88938, 88939, 88941 }, ["description"] = "We must retake the Darkwell and defeat L'ura before the world is torn asunder. We will need an army. No. Many armies. We need to reach out to the other elves. We should start with the kaldorei at Bel'ameth. Oculeth can teleport a small envoy there and we can present our request. Still... there has been much blood spilt among the elves. Vendettas that go far and strike deep. Hold on to hope, <name>. It is all we have left.", ["objectivesText"] = "Listen to Arator 's plan and then use Telemancer Oculeth's Portal to Bel'ameth . Progress: Are you ready to depart, Champion?", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 240267, ["x"] = 0.456, ["y"] = 0.703333 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 240334, ["x"] = 0.482, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.703333 }, ["mapCandidates"] = { ["npc"] = { 2239, 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 92520 }, ["questLines"] = { { ["id"] = 5795, ["name"] = "Gathering of the Elves", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5795, ["questLineOrder"] = 2 } } },
[88922] = { ["id"] = 88922, ["name"] = "The Quel'dorei", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 88919, 88920, 88922, 88923, 88925, 88927, 88928, 88929, 88930, 88937, 88938, 88939, 88941, 88942 }, ["description"] = "<name>, while the kaldorei are mustering, I could use your help as a witness as I ask another group for aid. We will need the quel'dorei for what is to come, no matter how much some of the sin'dorei will protest. Oculeth has agreed to open a portal for the two of us to reach my aunt, Vereesa Windrunner, where she awaits us in Eversong. The sin'dorei will not come with me. Will you?", ["objectivesText"] = "Take Oculeth's portal to Eversong Woods.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 251335, ["x"] = 0.482, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240296, ["x"] = 0.312, ["y"] = 0.912 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 2239, 2395 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["sourceQuests"] = { 88925, 88927, 88937 }, ["questLines"] = { { ["id"] = 5795, ["name"] = "Gathering of the Elves", ["orderIndex"] = 5, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5795, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239 },
[88923] = { ["id"] = 88923, ["name"] = "Children of the Stars", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 88920, 88922, 88923, 88925, 88927, 88937, 88938, 88939, 88941 }, ["description"] = "You have traveled far to ask my people to march to yet another war. Maiev's fervor is blunt but not misplaced. While Silvermoon is under threat, let us not forget how many of my people burned when the sin'dorei failed to aid us at Teldrassil. However, Bel'ameth stands tall thanks to their aid. Let each present their reasoning and I shall then make my decision.", ["objectivesText"] = "Have each envoy present their case to Shandris Feathermoon . Progress: Have you more to add?", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 }, { ["id"] = 3391, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 240334, ["x"] = 0.482, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 240334, ["x"] = 0.482, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["sourceQuests"] = { 88920 }, ["questLines"] = { { ["id"] = 5795, ["name"] = "Gathering of the Elves", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5795, ["questLineOrder"] = 2 } } },
[88925] = { ["id"] = 88925, ["name"] = "Awaken the Ancient of War", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 88920, 88922, 88923, 88925, 88927, 88937, 88938, 88939, 88941 }, ["description"] = "If we are to muster for war, then there is an ancient we must bring with us or they will never forgive us. They are a mentor to myself and nearly every sentinel who serves the kaldorei. They are skilled in war, tactics, and rallying our greatest forces. And they fell asleep again. If history is any lesson, they will only awaken with the aid of someone who has known war. Will you seek out their grove keeper to learn how to awaken them?", ["objectivesText"] = "Awaken the Ancient of War in Bel'ameth.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 251782, 252957, 264694, 264701, 264968, 265027 }, ["rewardChoices"] = { 251782, 252957, 264694, 264701, 264968, 265027 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 }, { ["id"] = 3391, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 240334, ["x"] = 0.482, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 240334, ["x"] = 0.482, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["sourceQuests"] = { 88923 }, ["questLines"] = { { ["id"] = 5795, ["name"] = "Gathering of the Elves", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5795, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239 },
[88926] = { ["id"] = 88926, ["name"] = "Return to Belanaar", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = true, ["expansion"] = 11, ["storyline"] = { 88926 }, ["description"] = "This has been most productive. I suspected the kaldorei might be our the most difficult to convince, but Shandris has turned a new leaf of leadership for her people. Let this be the first of many successful partnerships between our people. Now swiftly, . Let us return home and prepare our defense.", ["objectivesText"] = "Return to the docks in Bel'ameth with Lor'themar and Shandris.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[88927] = { ["id"] = 88927, ["name"] = "Awaken the Ancient Protector", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 88920, 88922, 88923, 88925, 88927, 88937, 88938, 88939, 88941 }, ["description"] = "The enemy we face is a vast host with many capabilities. We will need to match their strength and versatility on the battlefield. To that end, I ask that you seek out Elder Verdantbark --an ancient protector who has long kept our people safe in times of war. They are stubborn and may require you to entice them in some fashion, but their grove keeper will know best how to do so.", ["objectivesText"] = "Awaken the Ancient Protector in Bel'ameth.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 257234, 257237, 257238, 257249, 257250, 257251, 257252, 257256, 257269, 257271, 257289 }, ["rewardChoices"] = { 257234, 257237, 257238, 257249, 257250, 257251, 257252, 257256, 257269, 257271, 257289 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 }, { ["id"] = 3391, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 240334, ["x"] = 0.482, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 240334, ["x"] = 0.482, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["sourceQuests"] = { 88923 }, ["questLines"] = { { ["id"] = 5795, ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5795, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239 },
[88928] = { ["id"] = 88928, ["name"] = "The Shal'dorei", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 88919, 88922, 88928, 88929, 88930, 88942 }, ["series"] = { 88930 }, ["description"] = "Champion, your timing is fortuitous. I sent the call for the armies of Suramar to muster, but they have not arrived yet. My seneschal should have alerted me if anything went wrong, but I have heard nothing. I plan to go to Suramar to investigate what is amiss. Would you join me? I may have need of your skills.", ["objectivesText"] = "Use Oculeth's portal to travel to Suramar.", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["rewardItems"] = { 141324, 141325, 141326 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 }, { ["id"] = 3391, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 240255, ["x"] = 0.466, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 250958, ["x"] = 0.705, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 680, 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 88941 }, ["questLines"] = { { ["id"] = 5795, ["name"] = "Gathering of the Elves", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5795, ["questLineOrder"] = 2 } } },
[88929] = { ["id"] = 88929, ["name"] = "An Illusion!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 88919, 88922, 88928, 88929, 88930, 88942 }, ["description"] = "The mana of Suramar is carefully cultivated, regulated, and controlled. It does not just randomly \"stop.\" Someone or something must be interfering with it. As you investigate the mana drain, I want you to occasionally dispel illusions in the area. Focus on those gathered here. I suspect not everyone is what they appear to be.", ["objectivesText"] = "Dispel illusions in the Botanist's Garden that may be concealing sabotage or saboteurs. Progress: How many of my people have been taken by this evil?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 187591, 198607, 248920 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 }, { ["id"] = 3391, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 240302, ["x"] = 0.705, ["y"] = 0.742 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 240302, ["x"] = 0.705, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questTurnInID"] = 240302, ["questType"] = "standard", ["sourceQuests"] = { 88928 }, ["questLines"] = { { ["id"] = 5795, ["name"] = "Gathering of the Elves", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5795, ["questLineOrder"] = 2 } } },
[88930] = { ["id"] = 88930, ["name"] = "Drained Mana", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 88919, 88922, 88928, 88929, 88930, 88942 }, ["series"] = { 88928 }, ["description"] = "I have received no word from the High Arcanist Thalyssra for days! We have had many mana problems lately, so there is a chance her message spells were simply not able to be received.", ["objectivesText"] = "Investigate the Mana Drain at the Botanist's Terrace in Suramar. Progress: Have you found anything?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 264287, 264288 }, ["rewardChoices"] = { 264287, 264288 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 }, { ["id"] = 3391, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 250958, ["x"] = 0.705, ["y"] = 0.742 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 250958, ["x"] = 0.705, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questTurnInID"] = 250958, ["questType"] = "standard", ["sourceQuests"] = { 88928 }, ["questLines"] = { { ["id"] = 5795, ["name"] = "Gathering of the Elves", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5795, ["questLineOrder"] = 2 } } },
[88932] = { ["id"] = 88932, ["name"] = "With the Shal'dorei", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 88932 }, ["description"] = "Our reinforcements will be arriving shortly. Some will stay behind to defend Suramar. The rest will join us in Silvermoon. Thank you for joining me in this journey, . Hold on to the memory of this place in the battles to come. It will shield you from any doubt the void plants within you. Accompany me back to Silvermoon. We have many allies to find yet if we are to prevail against this force.", ["objectivesText"] = "Meet First Arcanist Thalyssra in the Sanctum of Light in Silvermoon City.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[88937] = { ["id"] = 88937, ["name"] = "Awaken the Ancient of Lore", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 88920, 88922, 88923, 88925, 88927, 88937, 88938, 88939, 88941 }, ["description"] = "While our forces gather, I would like you to have the honor of awakening our ancients. There is a particular ancient of lore we will need awakened. They are a master of magic, a teacher of our druids, and a force that has walked alongside us across many battlefields. Find their grove keeper to learn what is needed to wake the ancient.", ["objectivesText"] = "Awaken an Ancient of Lore in Bel'ameth. Progress: What stories does the ancient of lore have to tell, I wonder?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 257242, 257248, 257254, 257270, 257284, 257537, 257686, 257687, 257688 }, ["rewardChoices"] = { 257242, 257248, 257254, 257270, 257284, 257537, 257686, 257687, 257688 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 }, { ["id"] = 3391, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 240334, ["x"] = 0.482, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 240334, ["x"] = 0.482, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["sourceQuests"] = { 88923 }, ["questLines"] = { { ["id"] = 5795, ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5795, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239 },
[88938] = { ["id"] = 88938, ["name"] = "Symbols of the Past", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 88920, 88922, 88923, 88925, 88927, 88937, 88938, 88939, 88941 }, ["description"] = "Arator 's warning is poignant. There will be no small amount of grief or even threats when we return to Silvermoon. I suspect Aethas and his Sunreavers will bar our passage if we enter without preparations. To that end, I have saved some precious remnants of our shared history from before the demise of Dalaran. Would you please gather them for me, <name>?", ["objectivesText"] = "Gather the Relics of High King Anasterian Sunstrider. Progress: We were not able to preserve much from Dalaran before its fall. But every object recovered carries with it history, meaning, and lessons--lessons that any citizen of Quel'Thalas should understand on sight.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 251899, 251904, 257171, 264286 }, ["rewardChoices"] = { 257171, 264286 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 }, { ["id"] = 3391, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240295, ["x"] = 0.312, ["y"] = 0.912 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240295, ["x"] = 0.312, ["y"] = 0.912 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.912 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 88922 }, ["questLines"] = { { ["id"] = 5795, ["name"] = "Gathering of the Elves", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5795, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 2395 },
[88939] = { ["id"] = 88939, ["name"] = "Rest for the Restless", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 88920, 88922, 88923, 88925, 88927, 88937, 88938, 88939, 88941 }, ["description"] = "Before we are able to make amends with the living, we must lay the dead to rest. Years ago, I purged Dalaran of all elves allied with the Horde. I blamed them for the actions of the warchief at the time that resulted in the death of my husband. Now, years later, those ghosts still haunt me. Will you put them to rest and gather their remains? I'll perform some small atonement by bringing these remains to Silvermoon. They deserve to be returned home.", ["objectivesText"] = "Gather 10 Remains of the Fallen from the Purged of Dalaran. Progress: I have allowed them to torment my people for too long. I bear that guilt as well.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 43832, 43833, 43834, 43835, 57207, 57223, 57233, 84610, 84611, 84612, 84613, 84614, 258041 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 }, { ["id"] = 3391, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240295, ["x"] = 0.312, ["y"] = 0.912 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240295, ["x"] = 0.312, ["y"] = 0.912 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.912 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 88922 }, ["questLines"] = { { ["id"] = 5795, ["name"] = "Gathering of the Elves", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5795, ["questLineOrder"] = 2 } } },
[88941] = { ["id"] = 88941, ["name"] = "For Quel'Thalas", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 88920, 88922, 88923, 88925, 88927, 88937, 88938, 88939, 88941 }, ["description"] = "It is time for us to return to Silvermoon. I have no doubt we will be greeted as traitors and murderers. I do not care how we are seen. I care that Quel'Thalas survives. Will you join us, <name>? From what Arator has said, you have earned more than a measure of respect from Silvermoon. I would be honored if you would assist us in entering the city without incident.", ["objectivesText"] = "Confront the Sunreavers with Vereesa Windrunner at the gates of Silvermoon.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 251914, 257169, 257220 }, ["rewardChoices"] = { 257169, 257220 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 }, { ["id"] = 3391, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240295, ["x"] = 0.312, ["y"] = 0.912 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 240262, ["x"] = 0.458, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.912 }, ["mapCandidates"] = { ["npc"] = { 2393, 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 88938, 88939 }, ["questLines"] = { { ["id"] = 5795, ["name"] = "Gathering of the Elves", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5795, ["questLineOrder"] = 2 } } },
[88942] = { ["id"] = 88942, ["name"] = "The Elves are Going to War", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 88919, 88922, 88928, 88929, 88930, 88942 }, ["description"] = "We have learned much about the forces we will be facing in the battle to come. Suramar remembers the debt we owe the sin'dorei for their aid in our time of need. Now that our forces are assembled and our golems prepared, we are ready to defend this city as if it were our own. Come, <name>. Let us return to Lor'themar. It is time to discuss battle strategy.", ["objectivesText"] = "Return to the Sanctum of Light in Silvermoon City.", ["rewardGold"] = 1024800, ["rewardXP"] = 20540, ["rewardItems"] = { 246458, 248583, 251783, 251784, 251786, 251788, 251791, 259896 }, ["rewardChoices"] = { 248583, 251783, 251784, 251786, 251788, 251791, 259896 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3365, ["amount"] = 1000 }, { ["id"] = 3391, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 254654, ["x"] = 0.402, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 240266, ["x"] = 0.456, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 88919 }, ["questLines"] = { { ["id"] = 5795, ["name"] = "Gathering of the Elves", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5795, ["questLineOrder"] = 2 } } },
[88945] = { ["id"] = 88945, ["name"] = "Radiant Incursion: Rak-Zakaz", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14752, ["mapID"] = 2215, ["storyline"] = { 88945 }, ["description"] = "The nerubian allies you and Lady Faerin made in Azj-Kahet have proven resourceful... for now. According to their intel, Sureki sympathizers have begun to rally at Rak-Zakaz and aid their fallen queen's loyalists in their renewed assaults. Regroup with our forces at Faerin's Advance and cut off their reinforcements!", ["objectivesText"] = "Assist the Flame's Radiance and disrupt the Sureki forces at Rak-Zakaz. Progress: By disrupting operations at Rak-Zakaz, we cut off their reinforcements and discourage any sympathizers to their cause.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 239546 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 55 }, { ["id"] = 3283, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 }, { ["mapID"] = 2255, ["npcID"] = 241100, ["x"] = 0.606, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2215, 2255 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 4885 } },
[88947] = { ["id"] = 88947, ["name"] = "Undermined Delves", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 88947 }, ["description"] = "There's more tae do in delves, <name>! Meet me in Dornogal. There's loads to discuss!", ["objectivesText"] = "Meet Brann Bronzebeard within Dornogal.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["x"] = 0.476, ["y"] = 0.443, ["mapID"] = 2339, ["npcID"] = 206017 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 206017, ["questType"] = "standard", ["nextQuests"] = { 85242 } },
[88970] = { ["id"] = 88970, ["name"] = "LFGDungeons - 11.2 The War Within - Raid Finder - 1st", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["storyline"] = { 88970 }, ["rewardGold"] = 3098000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[88974] = { ["id"] = 88974, ["name"] = "Eco-Stability", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 88974, 88976 }, ["description"] = "Speakin' o' eggs, I checked an' Ember has laid her clutch. It's almost time ta hatch some babies! Meet me back at tha nest an' we can welcome our first snakelets ta K'aresh.", ["objectivesText"] = "Help with hatching the snakelets.", ["rewardGold"] = 929400, ["rewardXP"] = 17650, ["starts"] = { { ["x"] = 0.759, ["y"] = 0.342, ["mapID"] = 2371, ["npcID"] = 231820 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questGiverID"] = 231820, ["questType"] = "standard", ["sourceQuests"] = { 88672 }, ["questLines"] = { { ["id"] = 5803, ["name"] = "A Thriving Eco-System", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[88975] = { ["id"] = 88975, ["name"] = "Spooked Slitherin' Snakes", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 85459, 85460, 85461, 85462, 85465, 85470, 85481, 85710, 85721, 86342, 88659, 88975, 88980, 88981, 89056, 89057, 89065, 89192, 89195, 89197, 89198, 89209, 89210, 89212, 89213, 89221, 89238, 89240, 89242, 89254, 89297 }, ["description"] = "Somethin' has the snakes agitated again. Spooked even. How would ye feel about taking me flute back out there and calming 'em down?", ["objectivesText"] = "Use Hemet's Soothin' Flute to soothe 15 Agitated Snakes . Progress: Sweet music to me ears.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 238914 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 5 }, { ["id"] = 3284, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5704, ["name"] = "Eco-Dome Repeatables", ["orderIndex"] = 25, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[88976] = { ["id"] = 88976, ["name"] = "The Hope of K'aresh", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 88974, 88976 }, ["description"] = "It is finished. By all measurements, the eco-system in the Oasis is fully stable. While there will always be things we can help with, it would survive if we left it alone. Take some time and speak with everyone. Congratulate them. Good work should be properly acknowledged. Speak with me when you are done.", ["objectivesText"] = "Talk to your team in the Oasis.", ["rewardGold"] = 929400, ["rewardXP"] = 17650, ["rewardItems"] = { 242713 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5803, ["name"] = "A Thriving Eco-System", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[88977] = { ["id"] = 88977, ["name"] = "Reenact the Crime", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15993, ["mapID"] = 2395, ["storyline"] = { 88977, 88978, 88979, 90544, 94388 }, ["description"] = "Ah, you there! You appear to have the wisdom to assist me, unlike a certain bow-wielding simpleton who thinks sniffing dirt will solve our problem. We've accidentally misplaced a very important journal--the sort my mentor would transmogrify me to have lost! Please use my arcane timepiece to summon echoes of the past and investigate these moments. That should allow us to find my journal properly, without indulging Vardis's primitive methods.", ["objectivesText"] = "Use the Arcane Timepiece to investigate 3 Frozen Moments in the West Sanctum. Progress: Impossible. My magic has never failed me before... It seems we are at an impasse. To be thwarted by something so simple, yet so insidiously effective... is infuriating.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 238730 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240403, ["x"] = 0.41, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240420, ["x"] = 0.396, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 94388 }, ["questLines"] = { { ["id"] = 5804, ["name"] = "Theft Tracking", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[88978] = { ["id"] = 88978, ["name"] = "Tracking the Trail", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15993, ["mapID"] = 2395, ["storyline"] = { 88977, 88978, 88979, 90544, 94388 }, ["description"] = "While a certain wyrm-brained mage wastes time with his inept magic, we'll actually solve this case. The local wildlife has likely eaten the journal. Time to gut them and see if we can recover it. If the journal's inside, we'll find it... unlike someone who couldn't track his own insipid ego if it were carved into the ground.", ["objectivesText"] = "Gather 8 pieces of evidence in the West Sanctum. Progress: What do you mean none of them had the journal? How is this even possible? It defies logic! If the wildlife didn't take it, then where in the Twisting Nether could it have gone?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 240946 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240408, ["x"] = 0.41, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240421, ["x"] = 0.395, ["y"] = 0.391 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 94388 }, ["questLines"] = { { ["id"] = 5804, ["name"] = "Theft Tracking", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[88979] = { ["id"] = 88979, ["name"] = "Caught Red-Handed", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15993, ["mapID"] = 2395, ["storyline"] = { 88977, 88978, 88979, 90544, 94388 }, ["description"] = "A dog, of all creatures? This is the thief we've been chasing? And now we must save it from a lynx? Truly, this day has taken a most... irritating turn. No matter, we shall retrieve the journal... though I do wonder if this canine truly understands the gravity of its actions.", ["objectivesText"] = "Defeat the Hot-Headed Lynx in the West Sanctum. Progress: Did you manage to retrieve the journal?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 241192 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240422, ["x"] = 0.384667, ["y"] = 0.395333 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 242663, ["x"] = 0.396, ["y"] = 0.392 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.384667, ["y"] = 0.395333 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 88977, 88978 }, ["questLines"] = { { ["id"] = 5804, ["name"] = "Theft Tracking", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[88980] = { ["id"] = 88980, ["name"] = "Who You Gonna Call?", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 85459, 85460, 85461, 85462, 85465, 85470, 85481, 85710, 85721, 86342, 88659, 88975, 88980, 88981, 89056, 89057, 89065, 89192, 89195, 89197, 89198, 89209, 89210, 89212, 89213, 89221, 89238, 89240, 89242, 89254, 89297 }, ["description"] = "We could do with more slateback essence . I imagine that the opportunity to keep the sand of K'aresh safe would be right up your alley, yes? Just bring me back what you find after you are done.", ["objectivesText"] = "Collect 10 Slateback Essence in Untethered Space on K'aresh. Progress: You have the essence?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229395 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 5 }, { ["id"] = 3284, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5704, ["name"] = "Eco-Dome Repeatables", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[88981] = { ["id"] = 88981, ["name"] = "Nesting Upkeep", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 85459, 85460, 85461, 85462, 85465, 85470, 85481, 85710, 85721, 86342, 88659, 88975, 88980, 88981, 89056, 89057, 89065, 89192, 89195, 89197, 89198, 89209, 89210, 89212, 89213, 89221, 89238, 89240, 89242, 89254, 89297 }, ["description"] = "It's time to refresh Ember, Indigo, an' the snakelet's nest. Gotta keep our K'areshi snakes comfy. Don't worry 'bout carrying anything down there. Just like last time, we'll use one o' Ve'nari's portation tags for that.", ["objectivesText"] = "Refresh the nest of the two named snakes and their snakelets. Progress: Everything good with 'em? Aren't the snakelets just adorable?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 5 }, { ["id"] = 3284, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 235353, ["x"] = 0.758, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5704, ["name"] = "Eco-Dome Repeatables", ["orderIndex"] = 26, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[88982] = { ["id"] = 88982, ["name"] = "Prey Contract: Renegade Magister", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["storyline"] = { 88982 }, ["description"] = "A RENEGADE MAGISTER has been spotted in Voidstorm! Difficulty: Normal Affixes: 0 See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(88982)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(88982))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[88985] = { ["id"] = 88985, ["name"] = "Recuperating Returns", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 88985 }, ["description"] = "One of our lightwood loggin' outposts is late with their weapon shipments. Dey used to be punctual, but now we are lacking crucial supplies. Go check on de camp. Somethin' must be goin' on.", ["objectivesText"] = "Meet Woodcrafter Azai at Zeb'Alar Lumberyard.", ["rewardGold"] = 33500, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3354, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 241082, ["x"] = 0.456, ["y"] = 0.655 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 240521, ["x"] = 0.284, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.655 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86652 }, ["nextQuests"] = { 88986, 88987 } },
[88986] = { ["id"] = 88986, ["name"] = "Blind the Bandits", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 88986, 88987, 88988, 88989 }, ["description"] = "Dis elf showed up here seekin' revenge, thinkin' we were responsible for de death of his sister. But instead of killin' him, I'm gonna set de boy straight. De Amani got no business with some farm! He don't understand de Twilight's Blade is attackin' on both sides of de Zul'Aman border! I don't blame de child. He don't know dat de Twilight's Blade can hide demselves with their void powers. Take some lightwood splinters . Throw 'em on de shrouded Twilight's Blade. Show him who de real enemy is!", ["objectivesText"] = "Kill 8 Twilight's Blade cultists. Progress: Dat boy came here seekin' revenge on de first trolls he saw. Keep his restraints tight. Dat should help him sober up to de consequences of his childish recklessness.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 238962 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 240521, ["x"] = 0.284, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 241219, ["x"] = 0.284, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 88985 }, ["questLines"] = { { ["id"] = 6048, ["name"] = "Sawdust to Sawdust", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[88987] = { ["id"] = 88987, ["name"] = "Salvaged Sabotage", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 88986, 88987, 88988, 88989 }, ["description"] = "Rakani overreacted when de boy came crashin' into camp, but we all have been on edge. De Twilight's Blade had already snuck into our camp and sabotaged our work. It has already been challengin' to keep up with de demand for weapons. And our people need de weapons to defend themselves! If we can get de broken weapons back, we can maybe make up for what we lost. While you deal with dem, see if you can get any of our weapons back--whatever condition dey are in.", ["objectivesText"] = "Retrieve 6 Stolen Equipment . Progress: De chaos de elf caused is nothin' next to what we're facin' every day. We have to be extra cautious with de Twilight's Blade tryin' to sabotage our every move.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 238964 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 240521, ["x"] = 0.284, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 241219, ["x"] = 0.284, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 88985 }, ["questLines"] = { { ["id"] = 6048, ["name"] = "Sawdust to Sawdust", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[88988] = { ["id"] = 88988, ["name"] = "The Artisan's Apprentice", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 88986, 88987, 88988, 88989 }, ["description"] = "Looks like de boy has realized there is more in dis world than his family farm an' de big bad trolls of Zul'Aman . But I'm not done with him yet. He gonna learn hard work too. De boy needs to make up for de disruption he caused and de work we lost. It'll be a learnin' opportunity--for de both of you. You are goin' to make somethin' for us. Pay attention. One wrong move can destroy de lightwood. With de Twilight's Blade sabotagin' our equipment, our resources are too limited already.", ["objectivesText"] = "Follow Woodcrafter Azai 's instructions to craft a Lightwood Javelin. Progress: De lightwood is challengin' to work with, even for experienced woodcrafters. Be patient. Be precise. And do everything I say.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 239138 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 241219, ["x"] = 0.284, ["y"] = 0.274 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 241219, ["x"] = 0.284, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 88986, 88987 }, ["questLines"] = { { ["id"] = 6048, ["name"] = "Sawdust to Sawdust", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[88989] = { ["id"] = 88989, ["name"] = "Another One Bites the Sawdust", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 88986, 88987, 88988, 88989 }, ["description"] = "Dat boy is a fool. But he's a courageous fool. It's time to test dis weapon you crafted. He'll be goin' after their commander. He's killed many of my crafters, but revenge is not worth his life or dat of anyone else. Go after him before he gets himself killed. I did not go through all dis trouble just for him to die now, eh?", ["objectivesText"] = "Kill Covert Commander Tofir and rescue Kellor Sunshimmer. Progress: Dat commander killed some of our own. His troops most likely killed de boy's sister. But even though killin' him would make craftin' weapons and sendin' dem back to Amani'Zar easier, it's not worth dat boy's life.", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 241612, 264449, 264450, 264451, 264452, 264453, 264454, 264455, 264456, 264457, 264458, 264459 }, ["rewardChoices"] = { 264449, 264450, 264451, 264452, 264453, 264454, 264455, 264456, 264457, 264458, 264459 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3354, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 241219, ["x"] = 0.284, ["y"] = 0.274 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 241219, ["x"] = 0.284, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 88988 }, ["questLines"] = { { ["id"] = 6048, ["name"] = "Sawdust to Sawdust", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[88992] = { ["id"] = 88992, ["name"] = "Envisioned Mastery", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15958, ["mapID"] = 2444, ["storyline"] = { 88992 }, ["objectivesText"] = "Kill Shadowguards or Kill Players Kill Shadowguard Kill Shadowguard", ["rewardXP"] = 13690, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15958 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 15, ["amount"] = 1, ["objectID"] = 0, ["text"] = "Kill Shadowguards or Kill Players" }, { ["orderIndex"] = 1, ["type"] = 9, ["amount"] = 7, ["objectID"] = 466 }, { ["orderIndex"] = 2, ["type"] = 0, ["amount"] = 10, ["objectID"] = 240645, ["text"] = "Kill Shadowguard" }, { ["orderIndex"] = 3, ["type"] = 0, ["amount"] = 10, ["objectID"] = 240647, ["text"] = "Kill Shadowguard" } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444, ["db2QuestInfoID"] = 113, ["db2QuestInfoName"] = "PvP World Quest" },
[88993] = { ["id"] = 88993, ["name"] = "Wey'nan's Ward", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 88993, 88994, 88995, 88996, 88997, 88998, 88999 }, ["description"] = "To claim this relic, travel to the Vale of Secrets. Seek the Visionstone. Its surface bears sacred paintings, with a hand print aglow at the center. Press your hand upon it and let your spirit be known. Your body will falter into trance, and your soul will walk visions of the past. Be warned: these visions are no mere dreams, and the dangers within may strike true. Return to me with the wisdom you uncover.", ["objectivesText"] = "Travel to the indicated shrine in Harandar to meditate and experience the history of Wey'nan's Ward. Progress: Has your journey revealed the truth of Wey'nan's Ward? Share what you have uncovered.", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 263037, 263467, 268487, 269703, 279525 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3370, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 89268 }, ["questLines"] = { { ["id"] = 6015, ["name"] = "Legends Relics", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2LabelIDs"] = { 4794 }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[88994] = { ["id"] = 88994, ["name"] = "The Cauldron of Echoes", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 88993, 88994, 88995, 88996, 88997, 88998, 88999 }, ["description"] = "For untold eons, the Cauldron of Echoes has rested in shadow, its purpose obscured by time. When I first walked the path of the Zur'ashar, my master spoke of its significance--a relic tied to the very origins of our kind. Yet its secrets eluded even them... a mystery left unanswered. Now, it calls to us once more. Will you uncover what has been forgotten? The truth waits within, and I would be forever grateful for your discovery.", ["objectivesText"] = "Travel to the Glade of Walking Memories in Harandar to learn the history of the Cauldron of Echoes. Progress: Has your journey revealed the truth of the Cauldron of Echoes? Share what you have uncovered.", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 263315, 263467, 268487, 269703, 279525 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3370, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 89268 }, ["questLines"] = { { ["id"] = 6015, ["name"] = "Legends Relics", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2LabelIDs"] = { 4794 }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[88995] = { ["id"] = 88995, ["name"] = "Aln'hara's Bloom", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 88993, 88994, 88995, 88996, 88997, 88998, 88999 }, ["description"] = "When I was young in the path of a Zur'ashar, I heard a tale of a gift from Aln'hara: \"A sign of the goddess, felt in the stillness.\" Unfortunately, all those who were there to experience the event eventually passed on before we learned the secrets of our special paint. Would you walk the memory that surrounds the bloom and find out if this theory is true?", ["objectivesText"] = "Travel to Veilroot Clearing and uncover the truth behind Aln'hara's Bloom. Progress: Tell me what you witnessed, and we will ensure the memory is not lost again.", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 263196, 263467, 268487, 269703, 279525 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3370, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 89268 }, ["questLines"] = { { ["id"] = 6015, ["name"] = "Legends Relics", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2LabelIDs"] = { 4794 }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[88996] = { ["id"] = 88996, ["name"] = "The Echoless Flame", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 88993, 88994, 88995, 88996, 88997, 88998, 88999 }, ["description"] = "The Echoless Flame's fate is lost to time. Down through the ages, it was whispered that the lantern contained the power of Aln'hara herself. But now, it lies dormant--a shell without even a flicker left within. Perhaps you can uncover its secrets where others have failed? Retrace the steps of Obayo, the first of the Shul'ka, and bear witness to the glory of the relic and its true purpose.", ["objectivesText"] = "Travel to the Verdant Sepulcher in Harandar to learn the history of the Echoless Flame. Progress: Have you uncovered the secrets of the Echoless Flame?", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 263467, 264262, 268487, 269703, 279525 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3370, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 89268 }, ["questLines"] = { { ["id"] = 6015, ["name"] = "Legends Relics", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2LabelIDs"] = { 4794 }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[88997] = { ["id"] = 88997, ["name"] = "Russula's Outreach", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 88993, 88994, 88995, 88996, 88997, 88998, 88999 }, ["description"] = "A weather-worn spear haft, laced with pale mushroom threads, rests in silent vigil. The elders name it Russula's Outreach, yet no tale agrees on what that outreach was, or whom it spared. Was this weapon raised in fury, or lowered in mercy? The relic offers no answers here, only a lingering pull toward the old culling grounds. Follow that pull. Trace the footsteps lost to rot and rumor, and let the visions speak of what history forgot.", ["objectivesText"] = "Travel to the Verdant Sepulcher to learn the history of Russula's Outreach. Progress: Has your journey revealed the secrets of Russula's Outreach?", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 262906, 263467, 268487, 269703, 279525 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3370, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 89268 }, ["questLines"] = { { ["id"] = 6015, ["name"] = "Legends Relics", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2LabelIDs"] = { 4794 }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[88998] = { ["id"] = 88998, ["name"] = "Root of the World", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 88993, 88994, 88995, 88996, 88997, 88998, 88999 }, ["description"] = "The Root of the World is the first gift of the land to the haranir, or so it has been said. We have forgotten much about how the staff came to be in the possession of my people. But the root of the story, if you will permit, begins at a time not long after the haranir first came to Harandar . I trust that together, we can uncover its lost past. It is known that Ruilla the Huntress was a pivotal figure in the events that led to the creation of the staff. Go and see history through her eyes.", ["objectivesText"] = "Travel to the Vale of Secrets to learn the history of the Root of the World. Progress: Have you learned about the Root of the World? What truths have you uncovered?", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 263041, 263467, 279525 }, ["rewardCurrencies"] = { { ["id"] = 3370, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 89268 }, ["questLines"] = { { ["id"] = 6015, ["name"] = "Legends Relics", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2LabelIDs"] = { 4794 }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[88999] = { ["id"] = 88999, ["name"] = "Sky's Hope", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 88993, 88994, 88995, 88996, 88997, 88998, 88999 }, ["description"] = "Sky's Hope: the stone that legend says fell from the sky. Little is known about it besides it being considered a symbol of hope. But why? Following in the path of our ancient ancestor, Awe'ohna, might shed some light on the matter.", ["objectivesText"] = "Travel to the Shrouded Grove in Harandar to learn the history of Sky's Hope. Progress: Back so soon? What mysteries of Sky's Hope have been revealed?", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 253443, 263467, 279525 }, ["rewardCurrencies"] = { { ["id"] = 3370, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90743 }, ["questLines"] = { { ["id"] = 6015, ["name"] = "Legends Relics", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2LabelIDs"] = { 4794 }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[89012] = { ["id"] = 89012, ["name"] = "A Safe Path", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16182, ["mapID"] = 2432, ["storyline"] = { 86769, 86770, 86780, 86805, 86806, 86807, 86811, 86834, 86848, 86849, 86850, 86852, 88719, 89012, 89271, 91274, 91281 }, ["series"] = { 86805, 86806 }, ["description"] = "We must rescue the civilians and get them to the ships, yet the path to the docks is barred by a vile, hungering creature. If we are to save my people, then we need to clear an evacuation path. We cannot leave them to fend for themselves.", ["objectivesText"] = "Eliminate Gloomstress . Progress: Does the engulfing Void still bar the way?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["npcID"] = 237222, ["mapID"] = 2432, ["x"] = 0.354138, ["y"] = 0.4392 } }, ["ends"] = { { ["mapID"] = 2432, ["npcID"] = 236896, ["x"] = 0.355, ["y"] = 0.44 }, { ["mapID"] = 2432, ["npcID"] = 236961, ["x"] = 0.412, ["y"] = 0.568 }, { ["npcID"] = 237222, ["mapID"] = 2432, ["x"] = 0.354138, ["y"] = 0.4392 } }, ["coords"] = { ["source"] = "quest_giver", ["mapID"] = 2432, ["x"] = 0.354138, ["y"] = 0.4392 }, ["mapCandidates"] = { ["npc"] = { 2432 }, ["zone"] = { 16211 } }, ["questType"] = "standard", ["sourceQuests"] = { 86770, 86780, 89271 }, ["questLines"] = { { ["id"] = 5811, ["name"] = "The Light's Summons", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 335, ["title"] = "Midnight Expansion Intro Skip", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 352, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2858, ["db2PoiUiMapID"] = 2432 },
