[89032] = { ["id"] = 89032, ["name"] = "Renowned with The Singularity", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 89032 }, ["description"] = "You continue to show us that you are an integral member of our community. To honor that bond seek me out in Iskaara as I have prepared a pack of supplies to aid you.", ["objectivesText"] = "Speak with Murik in Iskaara.", ["rewardItems"] = { 259334 }, ["starts"] = { { ["x"] = 0.526, ["y"] = 0.729, ["mapID"] = 2405, ["npcID"] = 248328 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 248328, ["x"] = 0.525, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questGiverID"] = 248328, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2725, ["threshold"] = 7500 } } } },
[89034] = { ["id"] = 89034, ["name"] = "Burning Bitterblooms", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86899, 86900, 86901, 86907, 86910, 86911, 86912, 86913, 86914, 86929, 86930, 86942, 86944, 86956, 86973, 89034, 89402, 90094, 90095 }, ["description"] = "Lightbloom-infested rutaani are working to spread the contamination through the village. This plant showed significant signs of the disease. Destroy any of the plants they've come into contact with. We must contain this!", ["objectivesText"] = "Destroy 6 Lightbloom-Infected plants in Har'mara. Progress: The Lightbloom cannot be allowed to spread. The harmony of Har'mara is delicately balanced. We must keep it intact.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 256196, 256204, 256212, 256220 }, ["rewardChoices"] = { 256196, 256204, 256212, 256220 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 240630, ["x"] = 0.356, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 240630, ["x"] = 0.356, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86910 }, ["questLines"] = { { ["id"] = 5725, ["name"] = "Of Caves and Cradles", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5725, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[89035] = { ["id"] = 89035, ["name"] = "Renowned with the Hara'ti", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 89035 }, ["description"] = "The Hara'ti are stronger for what you have done. Go to Naynar . She will see that your deeds are remembered, and present you trophies appropriate for all you have done.", ["objectivesText"] = "Speak with Naynar in the Den.", ["rewardItems"] = { 256055 }, ["starts"] = { { ["x"] = 0.509, ["y"] = 0.507, ["mapID"] = 2413, ["npcID"] = 240407 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 240407, ["x"] = 0.51, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questGiverID"] = 240407, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2726, ["threshold"] = 7500 } } } },
