[89192] = { ["id"] = 89192, ["name"] = "A Hard Day's Work", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 85459, 85460, 85461, 85462, 85465, 85470, 85481, 85710, 85721, 86342, 88659, 88975, 88980, 88981, 89056, 89057, 89065, 89192, 89195, 89197, 89198, 89209, 89210, 89212, 89213, 89221, 89238, 89240, 89242, 89254, 89297 }, ["description"] = "We are running low on void shields . Your assistance is required to make a new one. Meet me outside the dome to the east. We shall craft it together.", ["objectivesText"] = "Assist Ve'nari in crafting a void shield outside the Oasis. Progress: Come now. Let us begin.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 237021 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 5 }, { ["id"] = 3284, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5704, ["name"] = "Eco-Dome Repeatables", ["orderIndex"] = 19, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
