[89194] = { ["id"] = 89194, ["name"] = "Shake your Bee-hind", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 89194 }, ["description"] = "<name>--just the <race> I wanted to see! I need you to go dance for m--I mean, bees. I shall just watch you leave now.", ["objectivesText"] = "Dance for the bees in the Oasis. Progress: <Alaenra appears to be silently dancing to a beat only she can hear.>", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 5 }, { ["id"] = 3284, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard" },
[89195] = { ["id"] = 89195, ["name"] = "Funny Buzzness", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 85459, 85460, 85461, 85462, 85465, 85470, 85481, 85710, 85721, 86342, 88659, 88975, 88980, 88981, 89056, 89057, 89065, 89192, 89195, 89197, 89198, 89209, 89210, 89212, 89213, 89221, 89238, 89240, 89242, 89254, 89297 }, ["description"] = "I seem to bee running low on bee puns at the moment, but I do need more bees from Stormsong Valley. Would you bee a dear and collect them for me?", ["objectivesText"] = "Vacuum up 20 Honey Bees to K'aresh while in Rosaline's Apiary in Stormsong Valley on Azeroth. Progress: <Alaenra appears to be making sucking noises while holding an imaginary vacuum.>", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 238904 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 5 }, { ["id"] = 3284, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5704, ["name"] = "Eco-Dome Repeatables", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[89197] = { ["id"] = 89197, ["name"] = "Ray Ranching", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 85459, 85460, 85461, 85462, 85465, 85470, 85481, 85710, 85721, 86342, 88659, 88975, 88980, 88981, 89056, 89057, 89065, 89192, 89195, 89197, 89198, 89209, 89210, 89212, 89213, 89221, 89238, 89240, 89242, 89254, 89297 }, ["description"] = "Ah, there you are. I need to perform medical checkups on the necrorays, and I could use some assistance in capturing them. Perhaps you could help?", ["objectivesText"] = "Lasso 6 Tranquil Necrorays and bring them to the Hitching Post by Om'talad . Progress: Have you captured the necrorays I require?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 238910 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 5 }, { ["id"] = 3284, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5704, ["name"] = "Eco-Dome Repeatables", ["orderIndex"] = 27, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[89198] = { ["id"] = 89198, ["name"] = "Dry Cleaning", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 85459, 85460, 85461, 85462, 85465, 85470, 85481, 85710, 85721, 86342, 88659, 88975, 88980, 88981, 89056, 89057, 89065, 89192, 89195, 89197, 89198, 89209, 89210, 89212, 89213, 89221, 89238, 89240, 89242, 89254, 89297 }, ["description"] = "Aw heck! The k'arrocs are acting all feisty again. Mind giving them a good clean so their natural aroma can rise to the top?", ["objectivesText"] = "Wash 10 Domineering K'arrocs.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 238909 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 5 }, { ["id"] = 3284, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 234316, ["x"] = 0.76, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 234316, ["x"] = 0.76, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5704, ["name"] = "Eco-Dome Repeatables", ["orderIndex"] = 23, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[89199] = { ["id"] = 89199, ["name"] = "A Small Task", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 89199, 89200, 89201, 89202, 89203, 89204, 89205, 89206, 89207, 89208, 90669 }, ["description"] = "You will forgive the lack of pleasantries, as this situation requires prompt remediation. All you need know is that I am Aradis, wardsmith of Silvermoon. We are an order of Magisters who maintain the city's defenses. I am recovering from a... minor battle injury, and require aid charging my wardbreaker staff. You will be compensated, and perhaps provided additional opportunities to aid me. I can furnish the details as you work, so long as you are not terribly slow.", ["objectivesText"] = "Collect the Depleted Wardbreaker , then charge it using 4 arcane reservoirs. Progress: Do handle the wardbreaker carefully. I will not tolerate seeing it damaged.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 239511, 246936, 249400, 254267, 254579, 264675 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 241393, ["x"] = 0.54, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 241405, ["x"] = 0.54, ["y"] = 0.336 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 90669 }, ["questLines"] = { { ["id"] = 5812, ["name"] = "Lesser Evil", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[89200] = { ["id"] = 89200, ["name"] = "Unraveling Wards", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 89199, 89200, 89201, 89202, 89203, 89204, 89205, 89206, 89207, 89208, 90669 }, ["description"] = "Dawnblaze is keeping the blackmail documents in her study. It is highly warded, naturally. The wards themselves are pitifully made. However, she is supplying additional power to them using arcane conduits placed throughout the city. I found the first link in the chain and brought it here to study. It is also warded, but weakly. I theorize that if the conduits are broken in sequence, then the shields on Dawnblaze's study will be vulnerable. Sabotage them, then recover the documents. Understood?", ["objectivesText"] = "Use the charged Wardbreaker to destroy the shields guarding 5 Warded Conduits.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 241405, ["x"] = 0.54, ["y"] = 0.336 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 241400, ["x"] = 0.372, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.336 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 89199 }, ["questLines"] = { { ["id"] = 5812, ["name"] = "Lesser Evil", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[89201] = { ["id"] = 89201, ["name"] = "Outschemed", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 89199, 89200, 89201, 89202, 89203, 89204, 89205, 89206, 89207, 89208, 90669 }, ["description"] = "The entrance to Dawnblaze's study is in the terrace just beneath us. Since my magic can project this close to her wards, that means the magic guarding this place has been weakened... as I predicted. Break the larger ward sealing the entrance and find the documents she forged to slander me. I will expect your expedient return to my office thereafter.", ["objectivesText"] = "Use the Wardbreaker to enter Magister Dawnblaze 's study, then find the Incriminating Documents . Progress: I will be taking those documents back.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 239608 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 241400, ["x"] = 0.372, ["y"] = 0.742 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 241398, ["x"] = 0.388, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.372, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 89200 }, ["questLines"] = { { ["id"] = 5812, ["name"] = "Lesser Evil", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[89202] = { ["id"] = 89202, ["name"] = "Stir the Nest", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 89199, 89200, 89201, 89202, 89203, 89204, 89205, 89206, 89207, 89208, 90669 }, ["description"] = "Aradis told you the blackmail was false? Of course. He is vying for my position. These receipts would ruin him. He is a warlock, and we have rules about fel magic. It is not banned, but it must be used discreetly. Aradis is not discreet. Magic misuse, unsanctioned demons, fel smuggling, bribery... His list of crimes is long. But you need not take my word for it. Aradis has earned many enemies in the city. If you can find him in the Row, a man named Jaeth could tell you all about our dear warlock.", ["objectivesText"] = "Question 8 Row Rats about Jaeth 's whereabouts.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 259992 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 241398, ["x"] = 0.388, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 241399, ["x"] = 0.518, ["y"] = 0.636 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 89201 }, ["questLines"] = { { ["id"] = 5812, ["name"] = "Lesser Evil", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[89203] = { ["id"] = 89203, ["name"] = "Mutual Benefit", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 89199, 89200, 89201, 89202, 89203, 89204, 89205, 89206, 89207, 89208, 90669 }, ["description"] = "< Jaeth waves a hand to cut you off as you explain.> All right, Dawnblaze sent you. That means there's a job. Not surprised she doesn't want to dirty her robes coming to the Row herself. The types who hire us never do. Everyone that high up in Silvermoon backstabs each other. When it's literal, they pay us to do it for them. They get whatever power they're chasing, and we get enough coin to live another week. Whose back is getting a knife this time?", ["objectivesText"] = "Show Jaeth the incriminating documents about Aradis. Progress: Come on. Spit out the details.", ["rewardGold"] = 335000, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 241399, ["x"] = 0.518, ["y"] = 0.636 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 241399, ["x"] = 0.518, ["y"] = 0.636 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.636 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 89202 }, ["questLines"] = { { ["id"] = 5812, ["name"] = "Lesser Evil", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[89204] = { ["id"] = 89204, ["name"] = "Five Finger Discount", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["description"] = "Aradis gave you his wardbreaker? What an idiot. Those get sold on the black market as skeleton keys. Expensive, but you have to attune them to the magic you're breaking, which isn't easy. Looks like yours is empty. We can fix that. If we pocket a few magic valuables around the city, my buddy upstairs can disenchant them and get that wardbreaker juiced with fel magic. Aradis won't have anywhere to hide then.", ["rewardGold"] = 683200, ["rewardXP"] = 14705, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3365, ["amount"] = 100 } }, ["starts"] = { { ["npcID"] = 241399, ["x"] = 0.518, ["y"] = 0.636, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 241401, ["x"] = 0.508, ["y"] = 0.61, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.518, ["y"] = 0.636, ["source"] = "quest_giver", ["mapID"] = 2393 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 89203 }, ["questLines"] = { { ["id"] = 5812, ["name"] = "Lesser Evil", ["orderIndex"] = 6, ["flags"] = 0 } } },
[89205] = { ["id"] = 89205, ["name"] = "Cutting a Key", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 89199, 89200, 89201, 89202, 89203, 89204, 89205, 89206, 89207, 89208, 90669 }, ["description"] = "I told Zanien here the whole story. He's been training warlocks for a long time--and if anyone hates sloppy ones, it's him. He's confident he can get the wardbreaker recharged. Follow his instructions and we should be good to head out afterward.", ["objectivesText"] = "Attune the Wardbreaker to fel magic. Progress: That staff should be able to break this ward now.", ["rewardGold"] = 34100, ["rewardXP"] = 1470, ["rewardItems"] = { 242253 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 241401, ["x"] = 0.508, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 241402, ["x"] = 0.542, ["y"] = 0.336 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 89204 }, ["questLines"] = { { ["id"] = 5812, ["name"] = "Lesser Evil", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[89206] = { ["id"] = 89206, ["name"] = "Break and Enter", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 89199, 89200, 89201, 89202, 89203, 89204, 89205, 89206, 89207, 89208, 90669 }, ["description"] = "Can you hear that? It sounds like it's coming from downstairs. Like someone's in pain. The last kidnapping from the Row was pretty recent. This could be where he's been keeping the people he took. My people. My friends. Even if Aradis doesn't show his face, we're not letting him keep them here. Bring this ward down. We're going in.", ["objectivesText"] = "Destroy the fel magic warding Aradis's private study. Progress: We're getting them out of here.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 241402, ["x"] = 0.542, ["y"] = 0.336 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 241403, ["x"] = 0.542, ["y"] = 0.336 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.336 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 89205 }, ["questLines"] = { { ["id"] = 5812, ["name"] = "Lesser Evil", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[89207] = { ["id"] = 89207, ["name"] = "Rats Can Bite", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 89199, 89200, 89201, 89202, 89203, 89204, 89205, 89206, 89207, 89208, 90669 }, ["description"] = "I know all of these people. They're workers, not fighters. Aradis went after the ones who couldn't fend him off. That's why he ran when he tried to take me and realized he picked the wrong target. After the trouble we've made, there's no way he doesn't know we're here. Be on guard. Once he shows his face, he's dead.", ["objectivesText"] = "Kill Magister Aradis .", ["rewardGold"] = 670000, ["rewardXP"] = 14705, ["rewardItems"] = { 263358, 263359, 263362, 263364 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3365, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 241403, ["x"] = 0.542, ["y"] = 0.336 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 241404, ["x"] = 0.53, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.336 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 89206 }, ["questLines"] = { { ["id"] = 5812, ["name"] = "Lesser Evil", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[89208] = { ["id"] = 89208, ["name"] = "What We're Owed", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 89199, 89200, 89201, 89202, 89203, 89204, 89205, 89206, 89207, 89208, 90669 }, ["description"] = "Everyone out here should be fine. Sarvi... I'll get her back to the Row. If we leave her here, the guards will just have the body tossed. I hope they do the same to Aradis, but I'm sure they won't. Come on. Let's go talk to Dawnblaze and get our payment. I remember where her office is.", ["objectivesText"] = "Inform Magister Dawnblaze that the job was completed. Progress: I see you recruited our dear assassin to the cause. Well done.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3365, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 241404, ["x"] = 0.53, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 241490, ["x"] = 0.373, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 89207 }, ["questLines"] = { { ["id"] = 5812, ["name"] = "Lesser Evil", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[89209] = { ["id"] = 89209, ["name"] = "Bu-zzz", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 85459, 85460, 85461, 85462, 85465, 85470, 85481, 85710, 85721, 86342, 88659, 88975, 88980, 88981, 89056, 89057, 89065, 89192, 89195, 89197, 89198, 89209, 89210, 89212, 89213, 89221, 89238, 89240, 89242, 89254, 89297 }, ["description"] = "These bees are absolute workhorses--workbees? They are worker bees so I suppose... ah, apologies for my distraction. Several of the bees have tired themselves out. Can you return them to the hive?", ["objectivesText"] = "Pickup 10 Overworked Honey Bees and return them to their hive. Progress: Goodness! They're terribly busy, aren't they?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 124640 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 5 }, { ["id"] = 3284, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5704, ["name"] = "Eco-Dome Repeatables", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[89210] = { ["id"] = 89210, ["name"] = "Photography is the Bee's Knees", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 85459, 85460, 85461, 85462, 85465, 85470, 85481, 85710, 85721, 86342, 88659, 88975, 88980, 88981, 89056, 89057, 89065, 89192, 89195, 89197, 89198, 89209, 89210, 89212, 89213, 89221, 89238, 89240, 89242, 89254, 89297 }, ["description"] = "All right, <name>. Take this camera and this film. You've done this before. It's time for documentation! I know you are practically buzzing to get out there, but it's time to bee focused.", ["objectivesText"] = "Document 15 Honey Bees and the Queen Bee . Progress: Photographing bees is marvelous when someone else does it.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 238903 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 5 }, { ["id"] = 3284, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5704, ["name"] = "Eco-Dome Repeatables", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[89212] = { ["id"] = 89212, ["name"] = "Royal Photographer", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 85459, 85460, 85461, 85462, 85465, 85470, 85481, 85710, 85721, 86342, 88659, 88975, 88980, 88981, 89056, 89057, 89065, 89192, 89195, 89197, 89198, 89209, 89210, 89212, 89213, 89221, 89238, 89240, 89242, 89254, 89297 }, ["description"] = "< Om'talad is intently taking several photos of himself.> Ah! <name>! We need to update our documentation of the thorntails. This camera I was... testing appears to be functioning correctly. Please go update our documentation.", ["objectivesText"] = "Document 10 Regal Thorntails. Progress: < Om'talad appears to be engrossed in some data from the console and is actively avoiding your gaze.>", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 238906 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 5 }, { ["id"] = 3284, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5704, ["name"] = "Eco-Dome Repeatables", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[89213] = { ["id"] = 89213, ["name"] = "Flights of Fancy", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 85459, 85460, 85461, 85462, 85465, 85470, 85481, 85710, 85721, 86342, 88659, 88975, 88980, 88981, 89056, 89057, 89065, 89192, 89195, 89197, 89198, 89209, 89210, 89212, 89213, 89221, 89238, 89240, 89242, 89254, 89297 }, ["description"] = "We are in need of new photos of the k'arrocs for our records. Please take some for us while you are out in the eco-dome.", ["objectivesText"] = "Document 7 Domineering K'arrocs.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 238908 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 5 }, { ["id"] = 3284, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5704, ["name"] = "Eco-Dome Repeatables", ["orderIndex"] = 21, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[89221] = { ["id"] = 89221, ["name"] = "Leafing Things on the Ground", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 85459, 85460, 85461, 85462, 85465, 85470, 85481, 85710, 85721, 86342, 88659, 88975, 88980, 88981, 89056, 89057, 89065, 89192, 89195, 89197, 89198, 89209, 89210, 89212, 89213, 89221, 89238, 89240, 89242, 89254, 89297 }, ["description"] = "I woke up today and thought to myself, \"That platter of food <name> put out for the lapbugs was excellent. I suspect the lapbugs would like it if <name> did that again.\" Why don't you make that happen, hmm?", ["objectivesText"] = "Collect 7 Chopped Oasis Plant cuttings and then place 3 Plant Platters . Progress: Have you fed the lapbugs yet?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 235914 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 5 }, { ["id"] = 3284, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 232385, ["x"] = 0.758, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5704, ["name"] = "Eco-Dome Repeatables", ["orderIndex"] = 16, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[89222] = { ["id"] = 89222, ["name"] = "Remnant of Azeroth", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 8717, ["mapID"] = 1161, ["storyline"] = { 89222 }, ["description"] = "Upon first glance it appears to be a crystallized shard of Azeroth's life blood. Peering into the shard reveals visions of war across familiar fronts, countless lives locked in battle. The sounds of thunderous storms and crashing waves begin to overwhelm you, before coming to an eerie halt. Kul Tiras calls out to you.", ["objectivesText"] = "Bring the Remnant of Azeroth to Churbro in Boralus.", ["rewardGold"] = 276200, ["rewardXP"] = 200, ["rewardItems"] = { 238790 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 200 }, { ["id"] = 1166, ["amount"] = 500 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 239840, ["x"] = 0.708, ["y"] = 0.167 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.167 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["startItems"] = { 238790 } },
[89223] = { ["id"] = 89223, ["name"] = "Remnant of Azeroth", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 8665, ["mapID"] = 1161, ["storyline"] = { 89223 }, ["description"] = "Upon first glance it appears to be a crystallized shard of Azeroth's life blood. Peering into the shard reveals visions of war across familiar fronts, countless lives locked in battle. The sounds of thunderous storms and crashing waves begin to overwhelm you, before coming to an eerie halt. Zandalar calls out to you.", ["objectivesText"] = "Bring the Remnant of Azeroth to Churbro in Dazar'alor.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 238791 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 500 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 239840, ["x"] = 0.708, ["y"] = 0.167 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.167 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["startItems"] = { 238791 } },
[89230] = { ["id"] = 89230, ["name"] = "A Lover Not a Fighter", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 89230, 89231, 89233 }, ["description"] = "De elders are plannin' a festival to give thanks to de loa. I wanna ask Namaji to accompany me but.... It is tradition that a suitor give a gift that proves their prowess as a warrior. But I am a poor fighter and de others laugh at me because of it. < Kagara hangs his head dejectedly.> Perhaps you can help me? I know Namaji has always wanted a threshadon tooth necklace . De gnarldin make dem, but only de strongest have one. Could you find one for me and deliver it to her on my behalf?", ["objectivesText"] = "Collect a Threshadon Tooth Necklace from the gnarldin at Akil'zon's Reach. Progress: Did you need somethin'?", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 249271 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 240976, ["x"] = 0.44, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 240975, ["x"] = 0.444, ["y"] = 0.656 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91062 }, ["questLines"] = { { ["id"] = 5981, ["name"] = "Between Two Trolls", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[89231] = { ["id"] = 89231, ["name"] = "A Fighter Not a Lover", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 89230, 89231, 89233 }, ["description"] = "You goin' to de loa festival? Young trolls like me are expected to ask someone dey like to go wit' dem. And to give a gift to show their worthiness. I wanna go wit' Namaji . I'm a great fighter, but I'm sure there are many other warriors dat wanna go wit' her! They'll gift her trophies and spoils. But I'll be different. I think she'd like a headdress, but I have no idea how to make one. Could you make a feathered headdress for me and give it to her? You can find feathers at Akil'zon's Reach.", ["objectivesText"] = "Collect 8 Eagle Feathers from Akil'zon's Reach and make an Amani Headdress . Progress: Another gift?", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 249231, 249236 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 240977, ["x"] = 0.438, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 240975, ["x"] = 0.444, ["y"] = 0.656 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91062 }, ["questLines"] = { { ["id"] = 5981, ["name"] = "Between Two Trolls", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[89233] = { ["id"] = 89233, ["name"] = "Love Triangle", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 89230, 89231, 89233 }, ["description"] = "It seems we have a problem: Kagara and Zak'kash both wanna go wit' me to de festival! Which one do I choose? I like both of dem well enough. Please <name>, you need to help me! What do you think?", ["objectivesText"] = "Help Namaji decide who to go to the festival with. Progress: Dey are both good choices...", ["rewardGold"] = 156400, ["rewardXP"] = 6085, ["rewardItems"] = { 264447, 264448 }, ["rewardChoices"] = { 264447, 264448 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3354, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 240975, ["x"] = 0.444, ["y"] = 0.656 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 240975, ["x"] = 0.444, ["y"] = 0.656 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.656 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 89230, 89231 }, ["questLines"] = { { ["id"] = 5981, ["name"] = "Between Two Trolls", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[89238] = { ["id"] = 89238, ["name"] = "Follow-up Appointment", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 85459, 85460, 85461, 85462, 85465, 85470, 85481, 85710, 85721, 86342, 88659, 88975, 88980, 88981, 89056, 89057, 89065, 89192, 89195, 89197, 89198, 89209, 89210, 89212, 89213, 89221, 89238, 89240, 89242, 89254, 89297 }, ["description"] = "There is much medical data to be gleaned in the evaluation of the k'arrocs. Please take the condenser disc to shrink them and then pick the little ones up for easy transport.", ["objectivesText"] = "Shrink and collect 8 Domineering K'arrocs.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 238913 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 5 }, { ["id"] = 3284, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5704, ["name"] = "Eco-Dome Repeatables", ["orderIndex"] = 22, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[89240] = { ["id"] = 89240, ["name"] = "Dream-Dream-Dream-Dream-Dreameringeding!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 85459, 85460, 85461, 85462, 85465, 85470, 85481, 85710, 85721, 86342, 88659, 88975, 88980, 88981, 89056, 89057, 89065, 89192, 89195, 89197, 89198, 89209, 89210, 89212, 89213, 89221, 89238, 89240, 89242, 89254, 89297 }, ["description"] = "We need to check how the thorntails are progressing. Would you be so kind as to gather more blood samples? As before, use the darts to put them to sleep and then retrieve the dart with the blood on it.", ["objectivesText"] = "Collect 5 Blood Samples from Regal Thorntails .", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 238912 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 5 }, { ["id"] = 3284, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5704, ["name"] = "Eco-Dome Repeatables", ["orderIndex"] = 15, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[89241] = { ["id"] = 89241, ["name"] = "Up and Up", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 89241 }, ["objectivesText"] = "Kill Ethereal or Players Kill Players Kill Ethereal Kill Ethereal Kill Ethereal", ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.726, ["y"] = 0.124, ["mapID"] = 2371 } }, ["ends"] = { { ["x"] = 0.726, ["y"] = 0.124, ["mapID"] = 2371 } }, ["coords"] = { ["mapID"] = 2371, ["x"] = 0.726, ["y"] = 0.124 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15336 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Kill Ethereal or Players", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Kill Players", ["amount"] = 7, ["type"] = 9, ["objectID"] = 459, ["orderIndex"] = 1 }, { ["text"] = "Kill Ethereal", ["amount"] = 10, ["type"] = 0, ["objectID"] = 243705, ["orderIndex"] = 2 }, { ["text"] = "Kill Ethereal", ["amount"] = 10, ["type"] = 0, ["objectID"] = 243703, ["orderIndex"] = 3 }, { ["text"] = "Kill Ethereal", ["amount"] = 10, ["type"] = 0, ["objectID"] = 243704, ["orderIndex"] = 4 } }, ["db2LabelIDs"] = { 3302 }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371, ["db2QuestInfoID"] = 113, ["db2QuestInfoName"] = "PvP World Quest" },
[89242] = { ["id"] = 89242, ["name"] = "I Want a Golden Ooze!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 85459, 85460, 85461, 85462, 85465, 85470, 85481, 85710, 85721, 86342, 88659, 88975, 88980, 88981, 89056, 89057, 89065, 89192, 89195, 89197, 89198, 89209, 89210, 89212, 89213, 89221, 89238, 89240, 89242, 89254, 89297 }, ["description"] = "It seems our custodians have been lax in their duties once again. Take the vacuum device. Clean up the lumps. I will cut you a percentage of the returns.", ["objectivesText"] = "Clean 25 Congealed Lumps in the Oasis. Progress: How go your efforts?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 238916 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 5 }, { ["id"] = 3284, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5704, ["name"] = "Eco-Dome Repeatables", ["orderIndex"] = 29, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[89249] = { ["id"] = 89249, ["name"] = "Overwhelmed", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86528, 86530, 86531, 86536, 86537, 86538, 86539, 86540, 86541, 86542, 86544, 86545, 88768, 89249 }, ["description"] = "We were too late. All of the strength between us wasn't enough. < Arator looks over his shoulder, wary. Then, he crouches and places his hand on Alleria's shoulder. She responds only with a ragged exhale.> Let's fall back. The ren'dorei have been exploring the wilds while we've been following Lothraxion. We might be able to find their encampment nearby.", ["objectivesText"] = "Reconvene with Arator at Locus Point.", ["rewardGold"] = 83700, ["rewardXP"] = 3210, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 241109, ["x"] = 0.416, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235724, ["x"] = 0.416, ["y"] = 0.746 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86542 }, ["questLines"] = { { ["id"] = 5729, ["name"] = "The Night's Veil", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5729, ["questLineOrder"] = 14 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[89250] = { ["id"] = 89250, ["name"] = "Burning Rubber", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 89250 }, ["description"] = "<Few things are as exhilarating as unbridled speed, and few things are as respected as the G-99 Breakneck in Nanny Talullah's garage. Mobber will certainly know how to tune your ride with the new part.>", ["objectivesText"] = "Speak with Mobber to tune your G-99 Breakneck.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 232523, 232983, 232984 }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 227216, ["x"] = 0.375, ["y"] = 0.469 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.375, ["y"] = 0.469 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard" },
[89254] = { ["id"] = 89254, ["name"] = "Shutterbug", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 85459, 85460, 85461, 85462, 85465, 85470, 85481, 85710, 85721, 86342, 88659, 88975, 88980, 88981, 89056, 89057, 89065, 89192, 89195, 89197, 89198, 89209, 89210, 89212, 89213, 89221, 89238, 89240, 89242, 89254, 89297 }, ["description"] = "The pictures with the lapbugs were a smash hit. We need more of them for marketing. Sorry, <name>. In this case, the lapbugs with hats are more in-demand than you. Do not be sad though. At least you're getting paid while also getting your face out there, yes? Now, get clicking.", ["objectivesText"] = "Take a S.E.L.F.I.E. with various lapbugs that are wearing hats. Progress: Consider making the shots more interesting with your own wardrobe changes.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 238933 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 5 }, { ["id"] = 3284, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5704, ["name"] = "Eco-Dome Repeatables", ["orderIndex"] = 18, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
