[89268] = { ["id"] = 89268, ["name"] = "Lost Legends", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 89268 }, ["description"] = "Among these walls lie relics, silent and forgotten, their stories obscured by time. The path to reclaiming our past is clear: take a relic to the sacred shrines and step into the echoes of its history. The visions will guide you, letting you walk the tale firsthand and breathe life into memory once more. If you would lend your spirit to this cause, choose a relic to reawaken its story.", ["objectivesText"] = "Select a relic to pursue.", ["rewardGold"] = 34100, ["rewardXP"] = 1520, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard" },
[89271] = { ["id"] = 89271, ["name"] = "My Son", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16182, ["mapID"] = 2432, ["storyline"] = { 86769, 86770, 86780, 86805, 86806, 86807, 86811, 86834, 86848, 86849, 86850, 86852, 88719, 89012, 89271, 91274, 91281 }, ["description"] = "One moment, <name>. I have a personal matter. I would like you to find my son, Arator . He is a member of the Silver Hand, an accomplished paladin. I know he must have been called. His faith is strong. The Light would want him here fighting against Xal'atath.", ["objectivesText"] = "Find Arator and bring him to Turalyon at Light's Spire. Progress: Have you found my son?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2432, ["npcID"] = 236906, ["x"] = 0.46, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 2432, ["npcID"] = 236954, ["x"] = 0.354, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2432, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 2432 }, ["zone"] = { 16182 } }, ["questType"] = "standard", ["sourceQuests"] = { 86769 }, ["questLines"] = { { ["id"] = 5811, ["name"] = "The Light's Summons", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 335, ["title"] = "Midnight Expansion Intro Skip", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 352, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2858, ["db2PoiUiMapID"] = 2565 },
