[89276] = { ["id"] = 89276, ["name"] = "Light Snacks", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "Classics are classic for a reason, darling. One simply cannot host a worthwhile soiree without a fine selection of mana for one's guests to indulge in. The Magisters could bring some, but mana is best when freshly siphoned. The mana wyrms in southern Eversong have a decadent brightness to them that I find particularly lovely. Be a dear and gather some for us.", ["objectivesText"] = "Siphon magical energy from 6 Scintillant Wyrms in the Tranquil Repose. Progress: Time is of the essence, dear.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 40 }, { ["id"] = 3379, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240834, ["x"] = 0.426, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240834, ["x"] = 0.426, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[89277] = { ["id"] = 89277, ["name"] = "Illuminate the Space", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "I share our dear Saltheril's love for vintage fixtures, but the lighting enchantment he is using is far too common for such an auspicious occasion. My Magisters can create a far more stunning enchantment. Simply gather some fibers from the Lightbloom for me and I can have them broken down into spell reagents. The effect will be marvelous.", ["objectivesText"] = "Gather 8 Luminous Fibers from creatures near Lightbloom Ath'Ran. Progress: We need only a small quantity. Our spellwork is quite efficient.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 239067, 242241 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 50 }, { ["id"] = 3379, ["amount"] = 60 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240834, ["x"] = 0.426, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240834, ["x"] = 0.426, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[89278] = { ["id"] = 89278, ["name"] = "Minding Our Duty", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "While the court does demand our consideration, we cannot forget duties. Our guests will enjoy themselves more freely if they are assured of the solidity of Eversong's defenses. The Magisters are tasked with maintaining the runestone wards throughout Eversong. Please survey them for us and let us know if any wards need our attention.", ["objectivesText"] = "Inspect the integrity of 4 Runestone wards around Eversong Woods .", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 40 }, { ["id"] = 3379, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240834, ["x"] = 0.426, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240834, ["x"] = 0.426, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
