[89289] = { ["id"] = 89289, ["name"] = "Favor of the Court", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "Ah, <name>, my favorite <class>! I am delighted to see you in attendance once more. You have quite the natural talent for these sorts of affairs. The nobles are pleased with your presence and your favor has been swaying their coffers. Let us not stop a good thing, shall we? Help me choose an ally of our representatives to invite to the Haven this week. I'm ever curious to see the drama you will stir up. As my personal guest of honor, your favor will be seen as an extension of my favor.", ["objectivesText"] = "Choose an ally of the Magisters, Blood Knights, Farstriders, or Shades of the Row to invite to Saltheril's Soiree this week. Your choice will determine which faction will offer \"Fortify the Runestones\" to your Warband this week. Progress: Be cautious, as always. The sin'dorei take great offense to many subtle things.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 238987, 259189, 268489, 269701 }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240832, ["x"] = 0.426, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240832, ["x"] = 0.426, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex