[89295] = { ["id"] = 89295, ["name"] = "The Flame Burns Eternal", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 89295 }, ["description"] = "These Sureki sure are a persistent bunch! We need to match their persistence with our blades. Can we count on your continued support in the battles ahead?", ["objectivesText"] = "Complete the Nightfall scenario. Progress: Ready yourself soldier, the battle is still to come.", ["rewardItems"] = { 239004 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 25 }, { ["id"] = 3108, ["amount"] = 15 }, { ["id"] = 3283, ["amount"] = 50 }, { ["id"] = 3283, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard" },
[89297] = { ["id"] = 89297, ["name"] = "Not as Cute When They Are Bigger and Angrier", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15792, ["mapID"] = 2371, ["storyline"] = { 85459, 85460, 85461, 85462, 85465, 85470, 85481, 85710, 85721, 86342, 88659, 88975, 88980, 88981, 89056, 89057, 89065, 89192, 89195, 89197, 89198, 89209, 89210, 89212, 89213, 89221, 89238, 89240, 89242, 89254, 89297 }, ["description"] = "It seems there are some who are looking to adopt lapbugs. Adoptions mean more revenue. Ultimately, this benefits the Oasis. Please acquire more essence for me.", ["objectivesText"] = "Collect 10 Lapbug Essence in Untethered Space on K'aresh. Progress: Have you performed the task?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 229393 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 5 }, { ["id"] = 3284, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 231820, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5704, ["name"] = "Eco-Dome Repeatables", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
