[89311] = { ["id"] = 89311, ["name"] = "Saltheril's Favor", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["rewardItems"] = { 238987 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 29, ["flags"] = 0 } } },
[89314] = { ["id"] = 89314, ["name"] = "Saltheril's Favor", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["rewardItems"] = { 238987 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 26, ["flags"] = 0 } } },
[89317] = { ["id"] = 89317, ["name"] = "Children's Week in Dornogal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Children's Week", ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 89317 }, ["description"] = "Oh, hello! You must be <name>. I can't thank you enough for stopping by to help with these little ones. Since we earthen don't have children of our own, I thought it would be fun to help some of our allies out for the week, but it turns out children are quite... energetic. I also don't have a good grasp of what children find \"fun\" yet. If you could take the kobold youngling with you that would be helpful. They seem to have somewhere they want to visit. Take this whistle to call them to you.", ["objectivesText"] = "Speak to the orphan, Skibbles.", ["rewardItems"] = { 221851, 232857, 241193, 241215, 242260, 242265 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 240696, ["x"] = 0.555, ["y"] = 0.271 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 241593, ["x"] = 0.554, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.271 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard" },
[89318] = { ["id"] = 89318, ["name"] = "Bold for a Kobold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Children's Week", ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 89318 }, ["description"] = "Big-Tall! Nice Talk-Rock tell Skibbles that she get to do whatever she want today! Well, me have big dream. One so big, me get in trouble for it. A lot. <Skibbles takes a deep breath.> Me want to be brave candle knight, like shiny humans with floaty boats! A-and me hear there is crystal that's brighter than any candle! <Skibbles pauses, seemingly anticipating rejection.> Would...would you take Skibbles to see candle knights with big kitties?", ["objectivesText"] = "Take Skibbles to Mereldar. Progress: Oh, hello <name>. I've had a wonderful time chatting with the orphanage patron here. After watching the children play, I am starting to see why my previous activities weren't as exciting for the younglings I am watching. They do not seem as interested in city tours but instead have an incredible capacity to pretend! Fascinating. Oh, I almost forgot--did you get a chance to take Skibbles to see the Lamplighters?", ["rewardGold"] = 31900, ["rewardXP"] = 175, ["rewardItems"] = { 219365, 219367, 219374, 219378, 221851, 232857, 239689, 241193, 241215, 242260, 242265 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 241593, ["x"] = 0.554, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 241631, ["x"] = 0.42, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 2215, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 89317 } },
[89319] = { ["id"] = 89319, ["name"] = "The Wondrous Weave", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Children's Week", ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 89319 }, ["description"] = "<Destien looks at his feet as you approach.> H-hello! I'm Destien. Earthen Matron Ullna told me about you, and said you are an adventurer! You must have seen all kinds of spooky and awesome things, right? T-there is one thing I would like to do, but I'm worried it will scare people. <Destien looks around nervously and lowers his voice.> I've heard there are good nerubians and that you've met them! I've always wanted to talk to one but they scare me. Would you come with me to meet them?", ["objectivesText"] = "Take Destien to the Weaver's Lair to meet the Widow. Progress: My goodness! The nerubians certainly have an interesting society. The younglings seem to be very different than the Arathi children, even though they're similar in their desire to play and get into trouble. < Ullna smiles fondly.>", ["rewardGold"] = 31900, ["rewardXP"] = 175, ["rewardItems"] = { 240196, 241215 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 241604, ["x"] = 0.556, ["y"] = 0.269 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 241649, ["x"] = 0.556, ["y"] = 0.436 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.269 }, ["mapCandidates"] = { ["npc"] = { 2255, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 89318 } },
[89320] = { ["id"] = 89320, ["name"] = "The Eager Engineer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Children's Week", ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2255, ["storyline"] = { 89320 }, ["description"] = "<Threadis looks up at you nervously. They hold up what appears to be a drawing of a goblin rocket, similar to the rocket drill going to Undermine. Perhaps they would like to ride the rocket drill to Undermine located in the Ringing Deeps?>", ["objectivesText"] = "Take Threadis to visit the rocket drill in the Ringing Deeps. Progress: My, this place is certainly different! It's almost the complete opposite of the Weaver's Lair. Not to mention all the colors... and smells. It has been fun to watch the goblin children at play, though. They have more in common with the Arathi, kobold, and nerubian children than I would have imagined! They're certainly a handful...", ["rewardGold"] = 31900, ["rewardXP"] = 175, ["rewardItems"] = { 221851, 232857, 240197, 241193, 241215, 242260, 242265 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 241603, ["x"] = 0.556, ["y"] = 0.436 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 242338, ["x"] = 0.347, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.436 }, ["mapCandidates"] = { ["npc"] = { 2255, 2346 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 89319 } },
[89321] = { ["id"] = 89321, ["name"] = "Recreation for Rooks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Children's Week", ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2255, ["storyline"] = { 89321 }, ["description"] = "Hey! You're <name>, ain't ya? My name's Kitzy! Man am I sure glad to see you. Look, I really wanna go back up to the surface to the stone city. The air is so clean and the sun is so bright! I also saw a giant blue bird fly overhead, except it had lots of legs! Ullna said it was called a...ruk? Rock? Somethin' like that. Anyway, I wanna see one! I ain't never seen anything so pretty before. Do you think I can pet one? <Kitzy gasps, her eyes shining in excitement.> Do you think I could RIDE one?", ["objectivesText"] = "Take Kitzy to Dornogal to see the Stormrooks. Progress: < Ullna notices you approach and beams excitedly.> <name>, look at all of these people! They're here asking about the children we've been watching. I can't believe it. This is so exciting! Let me know when Kitzy's ready to return. We have much to discuss.", ["rewardGold"] = 31900, ["rewardXP"] = 175, ["rewardItems"] = { 221851, 232857, 240198, 241193, 241215, 242260, 242265 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 241605, ["x"] = 0.556, ["y"] = 0.436 }, { ["mapID"] = 2339, ["npcID"] = 241732, ["x"] = 0.554, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 241732, ["x"] = 0.554, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.436 }, ["mapCandidates"] = { ["npc"] = { 2255, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 89320 } },
[89322] = { ["id"] = 89322, ["name"] = "A Brighter Tomorrow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Children's Week", ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 89322 }, ["description"] = "<name>, look at this! All of these people are here to discuss the children's futures. They expressed a desire to speak with you as well.", ["objectivesText"] = "Speak to the recently arrived benefactors. Progress: Have you had a chance to speak with the benefactors?", ["rewardItems"] = { 221851, 232857, 241193, 241215, 242242, 242260, 242265 }, ["rewardChoices"] = { 221851, 232857, 241193, 242260, 242265, 241215 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 241732, ["x"] = 0.554, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 241732, ["x"] = 0.554, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 89321 } },
[89323] = { ["id"] = 89323, ["name"] = "Wasted Lands", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86786, 89323, 89324, 89325, 89326, 89327, 90972, 91044, 94933 }, ["description"] = "Illidan taught us that if we are to fight threats that acknowledge no limits, we must be willing to do the same. With his rage he tamed the power of the fel, and so will I, with the void. A fragment from this world, touched by the All-Devouring, is held deep in the heart of North Sufaad. With the void essence Leona collected, and this fragment as a vessel, I will yoke the power of the void to my will. Combining the strength of the illidari and the secrets of the ren'dorei will make me unstoppable.", ["objectivesText"] = "Travel to North Sufaad. Progress: Travel to the location of the shard in North Sufaad.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 236907, ["x"] = 0.6, ["y"] = 0.296 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 242179, ["x"] = 0.79, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86786 }, ["questLines"] = { { ["id"] = 5770, ["name"] = "In Search of Darkness", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[89324] = { ["id"] = 89324, ["name"] = "A Piece of Something Greater", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86786, 89323, 89324, 89325, 89326, 89327, 90972, 91044, 94933 }, ["description"] = "Seek out the Relictors. They comb through these wastes like carrion feeders, sifting through proof of their people's weakness in a misguided attempt to find strength. <Adarus spits contemptuously onto the sand.> The only object of real value is here in front of us, and they keep it contained out of fear. I will not make that mistake. Go, find these Relictors, unburden them of their keys, and return.", ["objectivesText"] = "Retrieve the three keys. Progress: You've proved yourself useful so far, <class>. Continue to do so.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 239153, 239154, 239155 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 242179, ["x"] = 0.79, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 242179, ["x"] = 0.79, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.79, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 89323 }, ["questLines"] = { { ["id"] = 5770, ["name"] = "In Search of Darkness", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[89325] = { ["id"] = 89325, ["name"] = "The Void Confluence", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86786, 89323, 89324, 89325, 89326, 89327, 90972, 91044, 94933 }, ["description"] = "At last, <name>. With the promise of this fragment's power, and my mastery over the illidari ways, I will be ready to fight the shadowguard and any other threats the void throws at us. Leona spoke of a cave near Shan'dorah where the void energies suffusing K'aresh converge. Meet us there, and play a part in my ascension.", ["objectivesText"] = "Meet Adarus and Leona at the ritual site inside the cave at the Fracture of Laacuna.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 242179, ["x"] = 0.79, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 240842, ["x"] = 0.660667, ["y"] = 0.356667 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.79, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 89324 }, ["questLines"] = { { ["id"] = 5770, ["name"] = "In Search of Darkness", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[89326] = { ["id"] = 89326, ["name"] = "Distilled Darkness", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86786, 89323, 89324, 89325, 89326, 89327, 90972, 91044, 94933 }, ["description"] = "Adarus is preparing his mind and body for the ritual. Our task is to place the fragment at two points within this cavern, which will both align the crystal to the void energy in the area and attract any void entities that reside nearby. Defeat those entities and their essence will be absorbed into the fragment, empowering it further.", ["objectivesText"] = "Align the shard of K'aresh with the void energy in the cave. Progress: Move quickly, <name>. Time is of the essence.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 240842, ["x"] = 0.660667, ["y"] = 0.356667 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 240842, ["x"] = 0.660667, ["y"] = 0.356667 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.660667, ["y"] = 0.356667 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 16505 } }, ["questType"] = "standard", ["sourceQuests"] = { 89325 }, ["questLines"] = { { ["id"] = 5770, ["name"] = "In Search of Darkness", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[89327] = { ["id"] = 89327, ["name"] = "Chaos", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86786, 89323, 89324, 89325, 89326, 89327, 90972, 91044, 94933 }, ["description"] = "This is it, <name>. Place the K'areshi fragment above Adarus, and I will channel the void lure containing Ramon'ta's void essence into the shard. Adarus is powerful and determined, but we're attempting something both experimental and dangerous. I'll ask you to be vigilant.", ["objectivesText"] = "Assist Adarus and Leona with the ritual. Progress: When you're ready, <name>.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 38671, 42989, 43872, 43905, 43923, 43941, 43976, 87399, 130905 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 240842, ["x"] = 0.660667, ["y"] = 0.356667 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 240842, ["x"] = 0.660667, ["y"] = 0.356667 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.660667, ["y"] = 0.356667 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 16505 } }, ["questType"] = "standard", ["sourceQuests"] = { 89326 }, ["questLines"] = { { ["id"] = 5770, ["name"] = "In Search of Darkness", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[89331] = { ["id"] = 89331, ["name"] = "Flame Fortification", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 89331 }, ["description"] = "Sureki forces are gathering all over Hallowfall and Azj-Kahet--but we're certain they're just distractions. We think the main attack will come from the west. When the time comes we'll need all the help we can get to push them back and defend Mereldar. Can Flame's Radiance count on your support?", ["objectivesText"] = "Complete the Nightfall scenario. Progress: Be ready, the Sureki could attack at any moment!", ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 250 }, { ["id"] = 3283, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard" },
[89332] = { ["id"] = 89332, ["name"] = "Boot Camp", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 89332 }, ["description"] = "The Sureki gather across Hallowfall and Azj-Kahet while we prepare for their attack on Mereldar. They want to split our forces, but we cannot ignore their activities elsewhere. The Flame's Radiance forces are defending against their incursions in Hallowfall while we run incursions of our own into Azj-Kahet. Rendezvous with the Flame's Radiance in the field and assist their efforts.", ["objectivesText"] = "Complete a Radiant Incursion or Sureki Incursion.", ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 250 }, { ["id"] = 3283, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard" },
[89334] = { ["id"] = 89334, ["name"] = "Ahead of the Issue", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86653, 86654, 86655, 86656, 86657, 86658, 86659, 86660, 86661, 86663, 86664, 86665, 86666, 86808, 86809, 89334, 90772, 92084 }, ["description"] = "I do not know de loa Akil'zon, but she cannot be happy with de gnarldin defilin' de hash'ey shrines and makin' meals of her eagle kin. We gotta let dem know dis is a sacred place and dat we will not take kindly to their presence here. I may not know Akil'zon, but I know de giants. All dey understand is strength--de language of Zul'Aman . Our strongest message we can send is to take de heads of their fiercest warriors.", ["objectivesText"] = "Collect the heads of Brulagh the Crusher, Cragward Gaahl, and Pulverizer Helthra. Progress: Take their heads. How painful de method is between you and whatever force you worship.", ["rewardGold"] = 657000, ["rewardXP"] = 15215, ["rewardItems"] = { 239083, 243188, 243189, 260458, 260459, 260461 }, ["rewardChoices"] = { 260458, 260459, 260461 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3354, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 236140, ["x"] = 0.516, ["y"] = 0.708 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 236147, ["x"] = 0.518, ["y"] = 0.76 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.708 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86653 }, ["questLines"] = { { ["id"] = 5723, ["name"] = "Path of de Hash'ey", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5723, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 2437 },
[89338] = { ["id"] = 89338, ["name"] = "Gathering Plowshares", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 130, ["mapID"] = 14, ["storyline"] = { 86837, 86838, 86839, 86840, 86841, 86842, 86843, 86844, 86845, 86846, 86902, 89193, 89338, 91000, 92136 }, ["description"] = "$p, now that Hammerfall can expect peace with Stromgarde, there's a lot more use in being able to farm and craft than in fighting. So, we've been gathering old weapons from past skirmishes to make into tools for the people of Hammerfall. Would you and Arator be willing to give me a hand?", ["objectivesText"] = "Gather 4 Fallen Longswords and 4 Forgotten Skullcleavers . Progress: The weapons we gather will help reforge Hammerfall's future, <name>.", ["rewardGold"] = 312800, ["rewardXP"] = 12170, ["rewardItems"] = { 238515, 238516 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 247299, ["x"] = 0.685, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 247299, ["x"] = 0.685, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 14 }, ["zone"] = { 45 } }, ["questType"] = "standard", ["sourceQuests"] = { 86846, 91000 }, ["questLines"] = { { ["id"] = 5750, ["name"] = "The Path of Light", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5750, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2796, ["db2PoiUiMapID"] = 2372 },
[89343] = { ["id"] = 89343, ["name"] = "The Untethered Void", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 89343, 89344, 89345, 89380, 89561 }, ["series"] = { 89344, 89345, 89380 }, ["description"] = "The Reshii Wraps that the Harbinger gave you allow you to briefly transform into energy and fall into Untethered Space. This is a nightmare for all ethereals--a natural result of losing our wraps and radiating away our energy. We can control the process by properly attuning with the Phase Conduit, letting us visit this sub-realm and return intact. That is the theory. We have tested it with K'areshi Phase Divers, but not with one of your kind. Are you willing to risk the journey to Untethered Space?", ["objectivesText"] = "Interact with the Phase Conduit while wearing the Reshii Wraps. Progress: Untethered Space is beautiful to visit, but dangerous for those that are trapped there.", ["rewardGold"] = 309800, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 241624, ["x"] = 0.504, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 241624, ["x"] = 0.504, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.504, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 89380 }, ["questLines"] = { { ["id"] = 5903, ["name"] = "Diving Into Phase Diving", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[89344] = { ["id"] = 89344, ["name"] = "What Doesn't See You", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 89343, 89344, 89345, 89380, 89561 }, ["series"] = { 89343, 89345, 89380 }, ["description"] = "Untethered Space is an arcane phenomenon twisted by creatures of the Void that feed on its energy. Should we ethereals damage our wraps or the brokers their suits, our energy cannot remain intact for long. Then, we fall into this layer of reality, possibly never to return. The upside of this nightmare is that all the energy that falls out of phase is valuable. Use the Phase Conduit to enter Untethered Space, and fight the observers that scavenge phase energy there.", ["objectivesText"] = "Kill Untethered Observers and collect phase energy in Untethered Space on Overlook Zo'Shuul. Progress: Fascinating, isn't it?", ["rewardGold"] = 309800, ["rewardItems"] = { 235499, 244042 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 241624, ["x"] = 0.504, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 241624, ["x"] = 0.504, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.504, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 89343 }, ["questLines"] = { { ["id"] = 5903, ["name"] = "Diving Into Phase Diving", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[89345] = { ["id"] = 89345, ["name"] = "The Untethered Horror", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 89343, 89344, 89345, 89380, 89561 }, ["series"] = { 89343, 89344, 89380 }, ["description"] = "Void predators that have recently invaded Untethered Space are a mere annoyance compared to the ancient creatures that traveled here long ago. These primal predators feed on the energies of the remnants of old K'aresh , as well as the unfortunate K'areshi who have fallen into this state of being. There is one such creature we call Netherdeath that haunts this rock. We have only been able to drive it away. Perhaps you have the skill to end its reign of terror?", ["objectivesText"] = "Slay Netherdeath in Untethered Space. Progress: Have you rid Untethered Space of this predator?", ["rewardGold"] = 619600, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 241624, ["x"] = 0.504, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 241624, ["x"] = 0.504, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.504, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 89344 }, ["questLines"] = { { ["id"] = 5903, ["name"] = "Diving Into Phase Diving", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
