[89354] = { ["id"] = 89354, ["name"] = "Preparing for Battle", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 89354 }, ["description"] = "Void creatures have been multiplying throughout Slayer's Rise. Go help clear some out and return to me for a prize. There are turrets that are normally used in battle that can be used to make this task easier for you.", ["objectivesText"] = "Kill 20 Void Creatures in Slayer's Rise. Progress: This isn't enough! Go clear more of the void creatures.", ["rewardCurrencies"] = { { ["id"] = 1792, ["amount"] = 500 }, { ["id"] = 2123, ["amount"] = 150 }, { ["id"] = 3410, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 245976, ["x"] = 0.388, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 245976, ["x"] = 0.388, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "pvp", ["sourceQuests"] = { 86549 }, ["db2LabelIDs"] = { 2762 } },
