[89380] = { ["id"] = 89380, ["name"] = "Another World", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 89343, 89344, 89345, 89380, 89561 }, ["series"] = { 89343, 89344, 89345 }, ["description"] = "I represent a group within the Trust tasked with a dangerous but vital job--Phase Diving. I was at Overlook Zo'Shuul when the Harbinger transformed you into energy. It is similar to that, but more profitable. The Trust embarks on Phase Dives to help replenish our energy reserves. On K'aresh , energy is power--and now we must compete with the Shadowguard. We desperately need the help of someone like you. Meet me at Overlook Zo'Shuul if you are interested. We will, of course, compensate you.", ["objectivesText"] = "Find Shad'anis at Overlook Zo'Shuul on K'aresh .", ["rewardGold"] = 309800, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 241601, ["x"] = 0.748, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 241624, ["x"] = 0.504, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5903, ["name"] = "Diving Into Phase Diving", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[89383] = { ["id"] = 89383, ["name"] = "One Adventurous Hatchling", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89383, 89384, 89385, 89386 }, ["description"] = "One of my hatchlings was frightened off when that giant construct marched past the ranch. He bolted right through the fence and into the woods before I could stop him! He's small, fast, and probably hiding somewhere nearby. Please find him before something else does, and return him to me.", ["objectivesText"] = "Find the missing Hawkstrider Fledgling at Stillwhisper Pond. Progress: Did you find the hatchling?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 241553, ["x"] = 0.568, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 241553, ["x"] = 0.568, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86650 }, ["questLines"] = { { ["id"] = 5898, ["name"] = "One Adventurous Hatchling", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[89384] = { ["id"] = 89384, ["name"] = "A Hungry Flock", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89383, 89384, 89385, 89386 }, ["description"] = "Some think that raising hawkstriders is an easy task, but it most certainly is not. Hawkstrider appetites tend to be notoriously fussy! More often than not they'll turn their beaks up at anything I offer. But this time of year? Frog legs. They love the slimy little things. They can't get enough of them! There's a pond just down the hill just swarming with the leggy little morsels. Could you gather some for me, please?", ["objectivesText"] = "Gather frog legs from the Gloombelly Toads at Stillwhisper Pond. Progress: Have you found any frogs? The hawkstriders are hungry!", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 244214 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 241553, ["x"] = 0.568, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 241553, ["x"] = 0.568, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86650 }, ["questLines"] = { { ["id"] = 5898, ["name"] = "One Adventurous Hatchling", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[89385] = { ["id"] = 89385, ["name"] = "First Step Into Parenthood", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89383, 89384, 89385, 89386 }, ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 262510 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3365, ["amount"] = 250 } }, ["starts"] = { { ["npcID"] = 241553, ["x"] = 0.568, ["y"] = 0.356, ["mapID"] = 2395 } }, ["ends"] = { { ["npcID"] = 241553, ["x"] = 0.568, ["y"] = 0.356, ["mapID"] = 2395 } }, ["coords"] = { ["x"] = 0.568, ["y"] = 0.356, ["source"] = "quest_giver", ["mapID"] = 2395 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 89383, 89384, 89386 }, ["questLines"] = { { ["id"] = 5898, ["name"] = "One Adventurous Hatchling", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[89386] = { ["id"] = 89386, ["name"] = "A Roost-ed Development", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89383, 89384, 89385, 89386 }, ["description"] = "A comfortable hawkstrider is a happy hawkstrider. We don't expect them to stand all day. They need someplace cozy to roost! There's a plant called golden sunleaf that sprouts just beyond the ridge. It makes the softest bedding--the hawkstriders love it. Could you gather some for me?", ["objectivesText"] = "Collect Golden Sunleaf at Stillwhisper Pond. Progress: Did you find the golden sunleaf ?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 245531 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 241553, ["x"] = 0.568, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 241553, ["x"] = 0.568, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86650 }, ["questLines"] = { { ["id"] = 5898, ["name"] = "One Adventurous Hatchling", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[89388] = { ["id"] = 89388, ["name"] = "Voidstorm", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2393, ["storyline"] = { 86543, 86549, 86557, 86558, 86559, 86561, 86562, 86565, 89388, 92061 }, ["series"] = { 86543 }, ["description"] = "Magister Umbric has a plan to infiltrate the Voidstorm and take the fight to the Devouring Host directly. This will be no easy task, and he is assembling a small but powerful team to strike at the enemy's heart.", ["objectivesText"] = "Speak with Magister Umbric in the Sanctum of Light in Silvermoon.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["npcID"] = 240523, ["mapID"] = 2393, ["x"] = 0.455998, ["y"] = 0.703362 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 235386, ["x"] = 0.452, ["y"] = 0.702 }, { ["npcID"] = 240523, ["mapID"] = 2393, ["x"] = 0.455998, ["y"] = 0.703362 } }, ["coords"] = { ["source"] = "quest_giver", ["mapID"] = 2393, ["x"] = 0.455998, ["y"] = 0.703362 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5728, ["name"] = "Into the Abyss", ["orderIndex"] = 0, ["flags"] = 1 }, { ["id"] = 6131, ["name"] = "Midnight Scouting Map", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5728, ["questLineOrder"] = 13 } }, ["db2AdventureMapPoiID"] = 198, ["db2PoiUiMapID"] = 2393 },
