[89402] = { ["id"] = 89402, ["name"] = "Harandar", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2395, ["storyline"] = { 89193, 89388, 89402, 94871, 94957 }, ["series"] = { 86899, 86900 }, ["description"] = "With the Devouring Host occupying much of our attention and time, we leave our backs exposed to other threats that wait in the wings. This Lightbloom that has afflicted Eversong grows worse by the day. If it gets out of control, then we might find ourselves fighting a two-front conflict--or worse, having our home consumed completely while we busy ourselves with the Void. The strange woman who you found poking about the Lightbloom... You seem to be familiar with her. Seek her out. She may have answers.", ["objectivesText"] = "Speak with Orweyna in Fairbreeze Village.", ["rewardGold"] = 31200, ["rewardXP"] = 1520, ["starts"] = { { ["npcID"] = 240523, ["mapID"] = 2393, ["x"] = 0.455998, ["y"] = 0.703362 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236704, ["x"] = 0.453333, ["y"] = 0.459333 }, { ["npcID"] = 240523, ["mapID"] = 2393, ["x"] = 0.455998, ["y"] = 0.703362 } }, ["coords"] = { ["source"] = "quest_giver", ["mapID"] = 2393, ["x"] = 0.455998, ["y"] = 0.703362 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5725, ["name"] = "Of Caves and Cradles", ["orderIndex"] = 0, ["flags"] = 1 }, { ["id"] = 6131, ["name"] = "Midnight Scouting Map", ["orderIndex"] = 3, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5725, ["questLineOrder"] = 8 } }, ["db2AdventureMapPoiID"] = 196, ["db2PoiUiMapID"] = 2395 },
