[89440] = { ["id"] = 89440, ["name"] = "Protecting the Flank", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16178, ["mapID"] = 2371, ["storyline"] = { 89440 }, ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.555, ["y"] = 0.28, ["mapID"] = 2432 } }, ["ends"] = { { ["x"] = 0.555, ["y"] = 0.28, ["mapID"] = 2432 } }, ["coords"] = { ["mapID"] = 2432, ["x"] = 0.555, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16178 } }, ["questType"] = "standard", ["sourceQuests"] = { 86807 }, ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 20, ["objectID"] = 244094 }, { ["orderIndex"] = 1, ["type"] = 0, ["amount"] = 1, ["objectID"] = 244096 } }, ["db2PoiMapID"] = 2858, ["db2PoiUiMapID"] = 2432 },
