[89450] = { ["id"] = 89450, ["name"] = "Create a Neighborhood", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16105, ["mapID"] = 2352, ["storyline"] = { 89450 }, ["description"] = "You know what they say: it takes a neighborhood! Do they not say that? Well, they should. Gather signatures from like-minded settlers and found your own neighborhood!", ["objectivesText"] = "Gather charter signatures from players, then create your new neighborhood! Use the Neighborhood Charter quest item to open your charter.", ["rewardItems"] = { 239098 }, ["starts"] = { { ["x"] = 0.553, ["y"] = 0.576, ["mapID"] = 2351, ["npcID"] = 233063 } }, ["ends"] = { { ["mapID"] = 2352, ["npcID"] = 233063, ["x"] = 0.53, ["y"] = 0.4 }, { ["mapID"] = 2351, ["npcID"] = 233708, ["x"] = 0.552, ["y"] = 0.575 }, { ["mapID"] = 85, ["npcID"] = 254688, ["x"] = 0.584, ["y"] = 0.895 }, { ["mapID"] = 84, ["npcID"] = 256078, ["x"] = 0.474, ["y"] = 0.932 } }, ["coords"] = { ["mapID"] = 2352, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 84, 85, 2351, 2352 }, ["zone"] = { 16105 } }, ["questGiverID"] = 233063, ["questType"] = "standard" },
[89483] = { ["id"] = 89483, ["name"] = "Beginning of Abundance", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["storyline"] = { 89483 }, ["description"] = "The land is alive. With our relationship to the loa rekindled, the very ground beneath us responds in joy. Rich materials are providing themselves in quantities never witnessed before. One such place is in a cave in the north of Zul'Aman, just past Halazzi's domain. Meet me there if you wish to obtain great abundance!", ["objectivesText"] = "Meet Chel the Chip at the cave in Northern Zul'Aman.", ["rewardItems"] = { 238729 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[89490] = { ["id"] = 89490, ["name"] = "Warrant: Arcana-Monger So'zer", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 89490 }, ["series"] = { 90127 }, ["description"] = "Arcana-Monger So'zer is responsible for a spree of thefts throughout Tazavesh that have resulted in the loss of magic relics, wands, and several crates of highly toxic Zo'kita fruit. Informants suggest that So'zer may be compelled to reveal himself if presented with a highly prized arcane relic. Create an item tempting enough to trick this criminal into revealing themselves.", ["objectivesText"] = "Combine an Arcane Runed Sigil with a Charged Crystal and a Smuggler's Mark to create an Arcane Lure to reveal So'zer.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 239314, 239484, 239564, 239607 }, ["starts"] = { { ["x"] = 0.484, ["y"] = 0.59, ["mapID"] = 2472, ["npcID"] = 241951 } }, ["ends"] = { { ["x"] = 0.484, ["y"] = 0.59, ["mapID"] = 2472, ["npcID"] = 241951 } }, ["coords"] = { ["mapID"] = 2472, ["x"] = 0.484, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15336 } }, ["questGiverID"] = 241951, ["questTurnInID"] = 241951, ["questType"] = "standard", ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2472 },
[89492] = { ["id"] = 89492, ["name"] = "Worldsoul: Dastardly Duos in the Dome!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "That's right, the Dastardly Duos are here! Show your support! Talk to Xyggie Marou in Dornogal and sign up to fight a Dastardly Duos match. From there, wait until you're called and away you go! Show them what you got, hero!", ["objectivesText"] = "Beat the Dastardly Duos, then speak with Vinnie Sweets .", ["rewardGold"] = 683200, ["rewardXP"] = 17650, ["rewardItems"] = { 234449 }, ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 234296, ["x"] = 0.528, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questGiverID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 42, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
