[89501] = { ["id"] = 89501, ["name"] = "Charged Crystal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 89501 }, ["description"] = "An arcane charged crystal is not an item you will find in K'aresh , but there is a way we can make one! A small helper I know can help you harvest and store arcane energy . If you return that energy and an uncharged crystal to me, we can make a charged crystal . Gain Myi Koo's assistance, then travel through the ethereal portal to the Azure Vaults. Collect the energy and crystal.", ["objectivesText"] = "Meet with Myi Koo, enter the Archival Assault delve, and collect 6 Arcane Energy Samples and an Uncharged Crystal . Progress: Have you collected the crystal and the required energy?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 239446, 239607 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 238057, ["x"] = 0.48, ["y"] = 0.574 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 238057, ["x"] = 0.48, ["y"] = 0.574 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.574 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard" },
[89502] = { ["id"] = 89502, ["name"] = "Worldsoul: Nightfall", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 11, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "The remaining Sureki are rampaging around Hallowfall and Azj-Kahet, but we believe they are gathering forces west of the Veneration Grounds so that they can strike Mereldar directly! Please join Flame's Radiance in their defense and put down this Sureki threat! See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(89502)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(89502))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Complete the Nightfall scenario.", ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["coords"] = { ["mapID"] = 2339, ["x"] = 0.461, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 223875, ["questTurnInID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 53, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[89503] = { ["id"] = 89503, ["name"] = "Somber Siblings", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 89503, 89506, 89513, 89559, 89560, 89565 }, ["description"] = "Iz'ken left us many years ago, $p. Preparin' may be tense, but at least we won't have to do it alone. First, we need to collect de spores of de weepin' mushrooms. You can get dem from the mushrooms, or de boars. I'll be usin' dem to create incense for de ritual. Be careful, $p--de boars might be unhappy when we take their food.", ["objectivesText"] = "Collect 30 Weeping Spores from Weeping Caps or boars in the Solemn Valley. Progress: They're called weepin' spores, because when dey burn dey make your eyes water. De spores give our warriors a good excuse if dey are too cowardly to admit their feelings at de pyre.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 239447 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 247424, ["x"] = 0.458, ["y"] = 0.724 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 247424, ["x"] = 0.458, ["y"] = 0.724 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.724 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questTurnInID"] = 247424, ["questType"] = "standard", ["sourceQuests"] = { 89565 }, ["questLines"] = { { ["id"] = 5901, ["name"] = "Sorrowing Kin", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[89505] = { ["id"] = 89505, ["name"] = "Smuggler's Mark", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 89505 }, ["description"] = "An upstanding citizen such as Om'sto, would not have such an illegal item like a Smuggler's Mark . If I did acquire one...I would be inclined to give it to someone that I owe a debt to. If you did me a favor, and then I would be in your debt. Travel to North Sufaad, and fill my pack with items I lost there. You do this, and I may have what you need.", ["objectivesText"] = "Find enough lost items in North Sufaad to fill Om'sto's pack. Progress: Have you recovered all my items?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 239484, 239495, 239497, 239500, 239501, 239510 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 238486, ["x"] = 0.465, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 238486, ["x"] = 0.465, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard" },
[89506] = { ["id"] = 89506, ["name"] = "Strong Ties", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 89503, 89506, 89513, 89559, 89560, 89565 }, ["description"] = "Next we need to collect sinew from giants. De sinew makes sure de bonfire is not gonna fall apart, and de act of risking ya life against a powerful foe honors de fallen. I am a tested warrior, so do not worry for me. But please make sure Iz'ken does not come to harm from de giants.", ["objectivesText"] = "Collect 3 Resilient Sinew from mountain giants in the Solemn Valley. Progress: De sinew of mountain giants is a strong buildin' material. But we only use it for dis one purpose, because it's dangerous to get and there are not enough giants.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 239480 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 256867, ["mapID"] = 2437, ["x"] = 0.458697, ["y"] = 0.724357 } }, ["ends"] = { { ["npcID"] = 256867, ["mapID"] = 2437, ["x"] = 0.458697, ["y"] = 0.724357 } }, ["coords"] = { ["source"] = "quest_giver", ["mapID"] = 2437, ["x"] = 0.458697, ["y"] = 0.724357 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 89503 }, ["questLines"] = { { ["id"] = 5901, ["name"] = "Sorrowing Kin", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[89507] = { ["id"] = 89507, ["name"] = "Abundant Offerings", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "weekly", "meta", "repeatable" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2437, ["storyline"] = { 87350, 89507, 91302, 91457, 91475, 91930, 91932, 91933, 93890, 93931, 94361 }, ["description"] = "We have been called on yet again by de Loa of Abundance! Seek, harvest, and provide offerings at any of the abundance sites in Eversong, Zul'Aman, Harandar, or Voidstorm. I will provide you with the appropriate glory when the Harvest Lord has been satisfied.", ["objectivesText"] = "Earn 20,000 points in Abundance harvests.", ["rewardXP"] = 14705, ["rewardItems"] = { 263466, 268488, 269702, 279523 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 50 }, { ["id"] = 3310, ["amount"] = 75 }, { ["id"] = 3316, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 241928, ["x"] = 0.316, ["y"] = 0.262 }, { ["mapID"] = 2413, ["npcID"] = 248658, ["x"] = 0.66, ["y"] = 0.615 }, { ["mapID"] = 2405, ["npcID"] = 257632, ["x"] = 0.388, ["y"] = 0.532 }, { ["mapID"] = 2395, ["npcID"] = 257633, ["x"] = 0.568, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 241928, ["x"] = 0.316, ["y"] = 0.262 }, { ["mapID"] = 2413, ["npcID"] = 248658, ["x"] = 0.66, ["y"] = 0.615 }, { ["mapID"] = 2405, ["npcID"] = 257632, ["x"] = 0.388, ["y"] = 0.532 }, { ["mapID"] = 2395, ["npcID"] = 257633, ["x"] = 0.568, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.316, ["y"] = 0.262 }, ["mapCandidates"] = { ["npc"] = { 2395, 2405, 2413, 2437 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5810, ["name"] = "Abundance", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[89513] = { ["id"] = 89513, ["name"] = "Kindling Aplenty", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 89503, 89506, 89513, 89559, 89560, 89565 }, ["description"] = "Next, we need to collect de logs for our bonfire. Kan'sha, de large tree at de end of de valley, was infected with poison from a stray arrow long ago. She's quite tough. To survive, she sheds her branches regularly. In a way, Kan'sha has become a regular part of our rituals. Her strong wood burns warm and hot--like Amani blood. It is perfect for bonfires.", ["objectivesText"] = "Collect 4 Fallen Branches around Kan'sha in the Solemn Valley. Progress: Do not worry for Kan'sha. She has outlived generations of trolls, and de druids say she'll survive many more.", ["rewardGold"] = 309800, ["rewardXP"] = 12170, ["rewardItems"] = { 239483 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 256867, ["mapID"] = 2437, ["x"] = 0.458697, ["y"] = 0.724357 } }, ["ends"] = { { ["npcID"] = 256867, ["mapID"] = 2437, ["x"] = 0.458697, ["y"] = 0.724357 } }, ["coords"] = { ["source"] = "quest_giver", ["mapID"] = 2437, ["x"] = 0.458697, ["y"] = 0.724357 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["sourceQuests"] = { 89506 }, ["questLines"] = { { ["id"] = 5901, ["name"] = "Sorrowing Kin", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[89514] = { ["id"] = 89514, ["name"] = "Worldsoul: Horrific Visions Revisited", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15942, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "This Black Blood that has corrupted the nerubians is nasty stough. I hear that it is not the first time that the Old Gods have used this blood. A new visitor to Dorgogal, Soridormi of the Bronze Dragons, has found a way for you to revisit this past event. Seek her out to relive these Horrific Visions and learn what you can. Keep your eyes open <name>. Any info you can learn will surely aid us today.", ["objectivesText"] = "Defeat 5 bosses inside Horrific Visions Revisited.", ["rewardGold"] = 683200, ["rewardXP"] = 17650, ["rewardItems"] = { 244865 }, ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 15942 } }, ["questGiverID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 38, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[89515] = { ["id"] = 89515, ["name"] = "Renowned with Flame's Radiance", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15335, ["mapID"] = 2215, ["storyline"] = { 89515 }, ["description"] = "You continue to inspire us on the battlefield, <name>. Your heroic deeds have kept our people safe during these trying times, and we cannot thank you enough.", ["objectivesText"] = "Speak with Lars Bronsmaelt in Morgaen's Tears.", ["rewardItems"] = { 239489 }, ["starts"] = { { ["x"] = 0.283, ["y"] = 0.561, ["mapID"] = 2215, ["npcID"] = 240852 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 240852, ["x"] = 0.282, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questGiverID"] = 240852, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2689, ["threshold"] = 7500 } } } },
[89559] = { ["id"] = 89559, ["name"] = "Reasonless Worship", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 89503, 89506, 89513, 89559, 89560, 89565 }, ["description"] = "Ahead is an old shrine. Nobody knows anymore what we worshipped there or why, but it was a place my mother loved. It would honor her if we put a stone from it on de pyre with her.", ["objectivesText"] = "Collect a Weathered Shrine Piece . Progress: We both know dat de shrine is a place dat pleased our mother. I can't say she knew dat much about us.", ["rewardGold"] = 328500, ["rewardXP"] = 12170, ["rewardItems"] = { 239494 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 256867, ["mapID"] = 2437, ["x"] = 0.458697, ["y"] = 0.724357 } }, ["ends"] = { { ["npcID"] = 256867, ["mapID"] = 2437, ["x"] = 0.458697, ["y"] = 0.724357 } }, ["coords"] = { ["source"] = "quest_giver", ["mapID"] = 2437, ["x"] = 0.458697, ["y"] = 0.724357 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["sourceQuests"] = { 89513 }, ["questLines"] = { { ["id"] = 5901, ["name"] = "Sorrowing Kin", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[89560] = { ["id"] = 89560, ["name"] = "A Quiet Farewell", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 89503, 89506, 89513, 89559, 89560, 89565 }, ["description"] = "Now we set up de bonfire to burn de body. Destroying the body means it cannot be used by de Vilebranch for evil and makes sure de spirit finds rest. It still chills me how quiet she is now. The tribe should be gatherin' down at de Funerary Coast.", ["objectivesText"] = "Setup the bonfire for Chana and Iz'ken. Progress: It's time. We are ready.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 264654 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3354, ["amount"] = 250 } }, ["starts"] = { { ["npcID"] = 256867, ["mapID"] = 2437, ["x"] = 0.458697, ["y"] = 0.724357 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 242014, ["x"] = 0.457, ["y"] = 0.804 }, { ["npcID"] = 256867, ["mapID"] = 2437, ["x"] = 0.458697, ["y"] = 0.724357 } }, ["coords"] = { ["source"] = "quest_giver", ["mapID"] = 2437, ["x"] = 0.458697, ["y"] = 0.724357 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 89513, 89559 }, ["questLines"] = { { ["id"] = 5901, ["name"] = "Sorrowing Kin", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[89561] = { ["id"] = 89561, ["name"] = "Wrapped Up", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 89343, 89344, 89345, 89380, 89561 }, ["description"] = "Shad'anis has told me about you--a fleshling with the ability to travel to Untethered Space. How do you accomplish such a feat? Wait--let me deduce. It must be those wraps you wear as a cloak. They have been modified by a Reshii Ribbon. I have not seen such a thing since the Devouring War. Very nice. Classic. Do you want classic? Or do you want powerful? I can enhance your Reshii Wraps with modern technomancy techniques to better face the dangers of Untethered Space.", ["objectivesText"] = "Talk to Hashim about your Reshii Wraps. Progress: Enhancing the Reshii Wraps is paramount to your survival.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 21191, 21310 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 241588, ["x"] = 0.502, ["y"] = 0.364 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 241624, ["x"] = 0.504, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.364 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5903, ["name"] = "Diving Into Phase Diving", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[89565] = { ["id"] = 89565, ["name"] = "The Path of Mourning", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 89503, 89506, 89513, 89559, 89560, 89565 }, ["description"] = "Hash'ura, could I ask for your aid? My mother passed recently, and I'm de one responsible for performin' her death rituals. It's a lotta work for one person to do. Most would get help from their family, but I don't have any left. Can you help me?", ["objectivesText"] = "Meet Chana in the Solemn Valley.", ["rewardGold"] = 31500, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3354, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 242014, ["x"] = 0.457, ["y"] = 0.804 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 247424, ["x"] = 0.458, ["y"] = 0.724 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.457, ["y"] = 0.804 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86652 }, ["questLines"] = { { ["id"] = 5901, ["name"] = "Sorrowing Kin", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[89585] = { ["id"] = 89585, ["name"] = "Nightfall", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["storyline"] = { 89585 }, ["rewardGold"] = 606600, ["rewardXP"] = 1415, ["rewardItems"] = { 152105, 157826, 229371, 232049, 232371, 249783, 254267 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[90081] = { ["id"] = 90081, ["name"] = "Arcane Runed Sigil", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 90081 }, ["description"] = "An Arcane Runed Sigil is essential in proving an item's authenticity as a true masterpiece of Azure artisans. Of course, they can be affixed to any object, turning a flea market trinket into something that appears to be a priceless work of art. I could create something like that, and it might turn a great profit. If you travel to the Azure Vault and gather the parts I need, we can use them to craft a Sigil. Bring me enough parts for two, and I shall keep one as my fee for the service.", ["objectivesText"] = "Enter the Archival Assault delve and collect 24 Etched Fragments . Progress: Have you collected the parts?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 239564, 245740 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 238181, ["x"] = 0.525, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 238181, ["x"] = 0.525, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard" },
[90093] = { ["id"] = 90093, ["name"] = "Prey Contract: Murloc Shadowhunter", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["storyline"] = { 90093 }, ["description"] = "A MURLOC SHADOWHUNTER has been spotted in Zul Aman! Difficulty: Hard Affixes: Mark of the Prey Your target will occasionally mark you, decreasing your damage done and increasing damage taken. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(90093)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(90093))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[90094] = { ["id"] = 90094, ["name"] = "Echo of the Hunt", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86899, 86900, 86901, 86907, 86910, 86911, 86912, 86913, 86914, 86929, 86930, 86942, 86944, 86956, 86973, 89034, 89402, 90094, 90095 }, ["series"] = { 86901, 86907, 86911, 86929 }, ["description"] = "Haranir are fierce and ferocious--cunning and canny. In time, we became the most feared beasts upon the mountain. A great many wise and powerful beasts roamed the hills of our old mountain. But in time, we came to master them all. Today, you shall hunt as we once did.", ["objectivesText"] = "Complete the second trial at the Den of Echoes.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 239650, ["x"] = 0.36, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 239795, ["x"] = 0.346, ["y"] = 0.431 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.36, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86911 }, ["questLines"] = { { ["id"] = 5725, ["name"] = "Of Caves and Cradles", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5725, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90095] = { ["id"] = 90095, ["name"] = "Echo of the Call", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86899, 86900, 86901, 86907, 86910, 86911, 86912, 86913, 86914, 86929, 86930, 86942, 86944, 86956, 86973, 89034, 89402, 90094, 90095 }, ["description"] = "When the haranir began to grow restless, they looked to new sources of purpose. Some cast their gazes upward, toward the stars and the moon. Others, such as the Hara'ti , heard a call from deep within the world. The moment the first of the Hara'ti heard the Song echoing from the roots, we knew that we had found a new purpose. We would seek out the source of the Song, and discover the truth of it for ourselves. But it would be a difficult road. Strange stone monsters sought to block our path.", ["objectivesText"] = "Complete the third trial at the Den of Echoes.", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 256176, 256178, 256179, 256181, 256182, 256183, 256185, 256187, 256189, 256191, 256230 }, ["rewardChoices"] = { 256176, 256178, 256179, 256181, 256182, 256183, 256185, 256187, 256189, 256191, 256230 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3370, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 239795, ["x"] = 0.346, ["y"] = 0.431 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 243884, ["x"] = 0.34, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.431 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90094 }, ["questLines"] = { { ["id"] = 5725, ["name"] = "Of Caves and Cradles", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5725, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90115] = { ["id"] = 90115, ["name"] = "Infinite Research: Combat Studies, Groverunner", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily", "meta" }, ["sharable"] = false, ["expansion"] = 11, ["mapID"] = 619, ["storyline"] = { 90115 }, ["description"] = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma. This will be a study of your attunement to the forest, so focus on fighting opponents using the power of nature. And remember, this is for the greater good.", ["objectivesText"] = "Kill 100 enemies while Call of the Forest is your active artifact ability.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 246936, 249400, 254267, 254579, 264675 }, ["starts"] = { { ["x"] = 0.457, ["y"] = 0.685, ["mapID"] = 619, ["npcID"] = 241748 } }, ["ends"] = { { ["mapID"] = 619, ["npcID"] = 241748, ["x"] = 0.456, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 619, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 619 }, ["zone"] = {} }, ["questGiverID"] = 241748, ["questType"] = "standard" },
