[90467] = { ["id"] = 90467, ["name"] = "Tales of the Sky", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90467, 90468, 90469, 90470, 90474 }, ["description"] = "Wait a minute... You're no rutaani at all! Are you one of those \"outsiders\" that Saku and Orkon keep talking about? Oh! I just had a great idea. Did you know that the Goddess used to have a pet? Rumor has it that when the Goddess disappeared, Aln'sharan was SO sad that he flew up into the highest roots of Harandar , never to be seen again. But every so often, he goes looking for food... And his scales fall as skyglass! I wanna gather some. It's my dream to see Aln'sharan firsthand! Will you help me?", ["objectivesText"] = "Collect 6 Stray Skyshards in the Cascades of Harandar . Progress: Aln'sharan is a folk tale that we tell haranir children to explain the shards of glass that occasionally rain upon Harandar . Most grow out of searching for sky serpents. But Kuri 's heart has always been filled with whimsy.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 240484, 255826, 256424 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 242358, ["x"] = 0.67, ["y"] = 0.264 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 242689, ["x"] = 0.678, ["y"] = 0.273 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.264 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86930 }, ["questLines"] = { { ["id"] = 5909, ["name"] = "Legend of Aln'sharan", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90468] = { ["id"] = 90468, ["name"] = "Ugh, Chores!", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90467, 90468, 90469, 90470, 90474 }, ["description"] = "Okay, so I may have a DIFFERENT thing that I'm supposed to be doing in the Cascades, too. It's my turn to gather saptor fronds for stew. It's such a pain. Not only are saptor fronds horribly bitter, but the saptors are barely even fun to hunt! They don't even make your blood flow that fast before they die. But hey! You probably don't get to fight saptors as often as I do. Maybe while you're looking for skyglass, you could gather some up for me? You know... while you're in the area.", ["objectivesText"] = "Collect 8 Intact Saptor Fronds from the saptors of the Harandar Cascades. Progress: Oh, Kuri ...", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 240485 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 242358, ["x"] = 0.67, ["y"] = 0.264 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 242689, ["x"] = 0.678, ["y"] = 0.273 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.264 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86930 }, ["questLines"] = { { ["id"] = 5909, ["name"] = "Legend of Aln'sharan", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90469] = { ["id"] = 90469, ["name"] = "Carry On, Wayward Kuri", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90467, 90468, 90469, 90470, 90474 }, ["description"] = "Oh, that Kuri . She holds tightly to our ancient traditions and tales... perhaps too tightly. There is a difference between holding reverence for our ancient ways and chasing them into dangerous caves. I fear she might bite off more than she can chew in her search for Aln'sharan. Won't you go after her? She seems to trust you, now that she sees you as her co-conspirator in this quest. Please bring her home safely.", ["objectivesText"] = "Find Kuri in Dreth'amar Cavern. Progress: I'm certain Kuri will be fine. She's got her head in the roots, but she's made of tough stuff. But with Harandar as volatile as it has been of late, I would rather be safe than sorry.", ["rewardGold"] = 256200, ["rewardXP"] = 9130, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 242689, ["x"] = 0.678, ["y"] = 0.273 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 242691, ["x"] = 0.696, ["y"] = 0.266 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.678, ["y"] = 0.273 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90467, 90468 }, ["questLines"] = { { ["id"] = 5909, ["name"] = "Legend of Aln'sharan", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90470] = { ["id"] = 90470, ["name"] = "Skyglass Scavenging", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90467, 90468, 90469, 90470, 90474 }, ["description"] = "The adults find all sorts of stuff in the caves around here that we use back at the village. A lot of the critters that live in the caves like to gather skyglass, in particular. I guess they think it's shiny. That's good for us, though! It means we can go and get a bunch of skyglass. Go in there and make sure the coast is clear, and then I'll come in and gather up as much as I can carry! At this rate, we'll be able to summon Aln'sharan in no time.", ["objectivesText"] = "Gather as much Skyglass as Kuri can carry from Dreth'amar Cavern in Harandar . Progress: Come onnn! We've gotta hurry before mom gets TOO worried.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 242691, ["x"] = 0.696, ["y"] = 0.266 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 242691, ["x"] = 0.696, ["y"] = 0.266 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.696, ["y"] = 0.266 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90469 }, ["questLines"] = { { ["id"] = 5909, ["name"] = "Legend of Aln'sharan", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90474] = { ["id"] = 90474, ["name"] = "The Legend of Aln'sharan", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90467, 90468, 90469, 90470, 90474 }, ["description"] = "This is it! We have all the skyglass we can carry. The legends say that Aln'sharan cries crystal tears to mourn the missing Goddess. Maybe if we give the crystals back to him, he won't be so sad? Maybe then he'll appear for us! Meet me back at the village. I think I know the perfect place to make our offering.", ["objectivesText"] = "Return to Kuri in Har'kuai. Progress: Come on! We don't wanna miss our chance! Also all of this skyglass is heavy. Can't you carry some?!", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 255826, 256424 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3370, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 242691, ["x"] = 0.696, ["y"] = 0.266 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 242358, ["x"] = 0.67, ["y"] = 0.264 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.696, ["y"] = 0.266 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90470 }, ["questLines"] = { { ["id"] = 5909, ["name"] = "Legend of Aln'sharan", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90481] = { ["id"] = 90481, ["name"] = "I Have a Permit", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 90481, 90482, 90483, 90484, 90485, 90486, 90568, 93667 }, ["description"] = "These Witherbark youths are telling us we can't stay here. But I've been talking to one of their elders for months to be sure we'd have permission to set up camp and explore. I even have copies of all the letters! Can you find Elder Ren'zen in Witherbark Village and show him his letter of approval?", ["objectivesText"] = "Find Elder Ren'zen in Witherbark Village. Progress: Elder Ren'zen seemed so pleasant in his letters. Why all the hostility now?", ["rewardGold"] = 34100, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3354, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 242383, ["x"] = 0.462, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 242383, ["x"] = 0.462, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 93667 }, ["questLines"] = { { ["id"] = 5905, ["name"] = "Unlikely Friends", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[90482] = { ["id"] = 90482, ["name"] = "Cuisine Connection", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 90481, 90482, 90483, 90484, 90485, 90486, 90568, 93667 }, ["description"] = "Dis \"seeker\" has been askin' a lot of questions about de foods we eat. It sounds like these tortollans like to eat poisonous foods. De Witherbark do as well. There are many foods we eat that could kill us if not treated properly. Go collect zapgut eel stomachs and blisterskin kelp . I'd like to test dis turtle's tongue.", ["objectivesText"] = "Collect 6 Zapgut Eel Stomachs and 60 Blisterskin Kelp . Progress: We ingest some poisons to make ourselves resistant to potential threats. Some just taste good or provide a good thrill.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 241013, 241014 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 242394, ["x"] = 0.472, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 242394, ["x"] = 0.472, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 90481 }, ["questLines"] = { { ["id"] = 5905, ["name"] = "Unlikely Friends", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[90483] = { ["id"] = 90483, ["name"] = "A Witherbark Story", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 90481, 90482, 90483, 90484, 90485, 90486, 90568, 93667 }, ["description"] = "The Witherbark say they have a lot of stories to tell, but I've heard two and BOTH involved a sparring match! Please, can you ask the Witherbark here for stories? My old bones can't take another reenactment!", ["objectivesText"] = "\"Reenact\" 5 Witherbark stories in Camp Stonewash. Progress: What's wrong with a gentle story about falling asleep at an inopportune time? Tortollan folklore is full of those. Do trolls not sleep?", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 242391, ["x"] = 0.468667, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 242391, ["x"] = 0.468667, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.468667, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 90481 }, ["questLines"] = { { ["id"] = 5905, ["name"] = "Unlikely Friends", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[90484] = { ["id"] = 90484, ["name"] = "Sightseeing Stegadon", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 90481, 90482, 90483, 90484, 90485, 90486, 90568, 93667 }, ["description"] = "Wow, your armor is sooooo cool! < Trishe stares, slack-jawed.> Oh, have you seen my friend Steggy? She was here with me, but then there were all these pretty bugs and things, and she ran off after them, and I was too slow to follow her. < Trishe pouts.> I'm s'posed to watch Steggy. I'm response-able! And now you're response-able for finding her, okay?", ["objectivesText"] = "Find Steggy and defeat Hidegorger the Everburning in Zul'Aman . Progress: Have you seen how big the trolls are? Steggy is going to be bigger than the trolls, but she's still little like me. Steggy needs to eat so she can get bigger. Please find her so I can feed her!", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3354, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 242393, ["x"] = 0.472, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 242393, ["x"] = 0.472, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 90481 }, ["questLines"] = { { ["id"] = 5905, ["name"] = "Unlikely Friends", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[90485] = { ["id"] = 90485, ["name"] = "Afterthought Artifacts", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 90481, 90482, 90483, 90484, 90485, 90486, 90568, 93667 }, ["description"] = "This location is ideal for finding artifacts. Searching through the rubble at the bottom of that lake could reveal many treasures. If you have a moment, you're welcome to take a look around yourself. Bring me anything you find and we'll see if it's valuable.", ["objectivesText"] = "Find artifacts in the lake near Camp Stonewash in Zul'Aman . Progress: Found anything exciting yet?", ["rewardGold"] = 170800, ["rewardXP"] = 6085, ["rewardItems"] = { 241614, 241615, 251075, 251272 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 242391, ["x"] = 0.468667, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 242391, ["x"] = 0.468667, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.468667, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 90481 }, ["questLines"] = { { ["id"] = 5905, ["name"] = "Unlikely Friends", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[90486] = { ["id"] = 90486, ["name"] = "Dangerous Delicacies", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 90481, 90482, 90483, 90484, 90485, 90486, 90568, 93667 }, ["description"] = "A Witherbark troll could survive eatin' each of these ingredients raw, but dey would need aid. Together, de ingredients would be deadly. We're going to cook dem into one dish. Don't worry. I'll show you how to take out enough poison so it tastes good AND has paralytic effects.", ["objectivesText"] = "Cook Blistereel Boar in Camp Stonewash. Progress: What do you think this is going to taste like? Amaxi says it's absolutely arresting and could kill a stegodon!", ["rewardGold"] = 170800, ["rewardXP"] = 6085, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 242394, ["x"] = 0.472, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 242390, ["x"] = 0.471, ["y"] = 0.245 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 90482 }, ["questLines"] = { { ["id"] = 5905, ["name"] = "Unlikely Friends", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[90493] = { ["id"] = 90493, ["name"] = "The Heart of Tranquillien", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86621, 86622, 86623, 86624, 86626, 86632, 86633, 86634, 86635, 86636, 86781, 90493, 90494, 90509, 90907 }, ["description"] = "We can't let the Twilight's Blade get away with this. There are innocent citizens all over town who had nothing to do with this cult. You heard the governor: anyone who doesn't join will be executed. I won't stand for that. Go--aid any civilians you can find. Get them out of harm's way. If they're being attacked, take their attacker down. Tranquillien will not fall under my watch.", ["objectivesText"] = "Rescue 8 innocent Tranquillien Citizens.", ["rewardGold"] = 312800, ["rewardXP"] = 11765, ["rewardItems"] = { 253485, 253488 }, ["rewardChoices"] = { 253485, 253488 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236686, ["x"] = 0.476, ["y"] = 0.696 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 243984, ["x"] = 0.49, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.696 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86626 }, ["questLines"] = { { ["id"] = 5720, ["name"] = "Shadowfall", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5720, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 2395 },
[90494] = { ["id"] = 90494, ["name"] = "The Missing Magister", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86621, 86622, 86623, 86624, 86626, 86632, 86633, 86634, 86635, 86636, 86781, 90493, 90494, 90509, 90907 }, ["description"] = "Umbric went to chase down Antenorian when the fighting broke out, but nobody has seen him since. I trust him to hold his own, but between Kasiea's death and Antenorian's betrayal, I worry he may be so set on revenge that he won't see an attack if one happens. Can you find him for me? I'll stay here and make sure these civilians remain safe.", ["objectivesText"] = "Find Magister Umbric . Progress: I will not allow them to get away with this.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 239134, 243468, 243478, 248051, 248052 }, ["rewardChoices"] = { 248051, 248052 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 243984, ["x"] = 0.49, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 242143, ["x"] = 0.476, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86632, 90493, 90509 }, ["questLines"] = { { ["id"] = 5720, ["name"] = "Shadowfall", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5720, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 2395 },
[90509] = { ["id"] = 90509, ["name"] = "The Traitors of Tranquillien", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86621, 86622, 86623, 86624, 86626, 86632, 86633, 86634, 86635, 86636, 86781, 90493, 90494, 90509, 90907 }, ["description"] = "Some of the town's most respected citizens, traitors? How long has the Twilight's Blade been here? How many scouts have gone missing? Crimes gone unreported? Innocents recruited by those they thought they could trust? They must be stopped. Cut down the traitors. Show them that Tranquillien is no home for cultists.", ["objectivesText"] = "Slay Ranger Lethvalin , Matron Narsilla , and Guard Captain Leonic . Progress: We cannot allow these traitors to escape!", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 248065, 248069, 250355 }, ["rewardChoices"] = { 248065, 248069, 250355 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236686, ["x"] = 0.476, ["y"] = 0.696 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 243984, ["x"] = 0.49, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.696 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86626 }, ["questLines"] = { { ["id"] = 5720, ["name"] = "Shadowfall", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5720, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 2395 },
[90517] = { ["id"] = 90517, ["name"] = "My Part of the Deal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 83126, 83127, 83128, 83129, 84856, 84857, 84862, 84863, 84864, 84865, 84866, 84967, 85037, 85449, 85450, 86495, 86820, 86946, 90517, 91871, 93979 }, ["description"] = "The threat of the Shadowguard to Eco-Dome: Primus is over. My Reshii Ribbon is no longer needed to protect this asset. Take it. Use it wisely. Protect the greatest investment of all--our existence. Stay focused! The Harbinger has already driven off one member of your team. Once you get enough Reshii Ribbons, you still need to fight Dimensius. Find allies who will stand with us, in addition to artifacts.", ["objectivesText"] = "Take Ve'nari's Reshii Ribbon . Progress: The Reshii Ribbons are a means to get you and your allies to Dimensius. You will need at least two more if this plan is going to work.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3129, ["amount"] = 2500 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 242538, ["x"] = 0.47, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 242538, ["x"] = 0.47, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 86946 }, ["questLines"] = { { ["id"] = 5733, ["name"] = "Void Alliance", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 271, ["title"] = "The Knife's Edge", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 311, ["title"] = "LAURA TEST", ["questLineID"] = 5733, ["questLineOrder"] = 1 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[90533] = { ["id"] = 90533, ["name"] = "Go Get Orweyna!", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90533, 90534, 90535 }, ["description"] = "Hey! Champ! Look, I swear I'm glad to see ya. I'm just in a little bit of a diplomatic situation here. Can you go get Orweyna and bring her back here? See if she'll talk this beast into letting me go? I'm not an elekk plushie, for cryin' out loud.", ["objectivesText"] = "Go get Orweyna in the Den and find a way to free Gazlowe. Progress: Never try to take something from a beast like this without offering something better. I would hate to lose another friend that way.", ["rewardGold"] = 34100, ["rewardXP"] = 1520, ["rewardItems"] = { 241125 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3370, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 242593, ["x"] = 0.47, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 242592, ["x"] = 0.506, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86898 }, ["questLines"] = { { ["id"] = 5907, ["name"] = "A Goblin in Harandar", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90534] = { ["id"] = 90534, ["name"] = "The Home of the Haranir", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90533, 90534, 90535 }, ["description"] = "I am eager to show Monte my home, but I know it is very different from what he is used to. Come with us as he meets my people.", ["objectivesText"] = "Accompany Orweyna and Gazlowe around the Cradle and the Den.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 242592, ["x"] = 0.506, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 242592, ["x"] = 0.506, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questTurnInID"] = 242592, ["questType"] = "standard", ["sourceQuests"] = { 90533 }, ["questLines"] = { { ["id"] = 5907, ["name"] = "A Goblin in Harandar", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2576 },
[90535] = { ["id"] = 90535, ["name"] = "Leave Your Mark", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2576, ["storyline"] = { 90533, 90534, 90535 }, ["description"] = "One thing that is very important to the haranir is our past. Some may remove their ability to hear the Goddess, but we are all connected to who came before us. You and Gazlowe are a part of our history now. You have earned the right to leave your mark here in the Den, for as long as the Den remains. Go, touch the wall with your painted hand, and know that you touch the same stone as generations before you.", ["objectivesText"] = "Paint your mark on the wall of the Den. Progress: We are continually making ourselves new, even as we hold to what came before. I should remember this more often.", ["rewardGold"] = 309800, ["rewardXP"] = 12170, ["rewardItems"] = { 260427 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3370, ["amount"] = 250 } }, ["starts"] = { { ["npcID"] = 242882, ["mapID"] = 2576, ["x"] = 0.480098, ["y"] = 0.223462 } }, ["ends"] = { { ["npcID"] = 242882, ["mapID"] = 2576, ["x"] = 0.480098, ["y"] = 0.223462 } }, ["coords"] = { ["source"] = "quest_giver", ["mapID"] = 2576, ["x"] = 0.480098, ["y"] = 0.223462 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15921 } }, ["questType"] = "standard", ["sourceQuests"] = { 90534 }, ["questLines"] = { { ["id"] = 5907, ["name"] = "A Goblin in Harandar", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2576 },
[90536] = { ["id"] = 90536, ["name"] = "The Tale of Wey'nan's Ward", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90536 }, ["objectivesText"] = "Zaratti forces slain Follow Wey'nan's trail tall grass Wey'nan calmed Wey'nan's Ward crafted", ["rewardItems"] = { 241349, 241611 }, ["starts"] = { { ["x"] = 0.443, ["y"] = 0.383, ["mapID"] = 2413, ["npcID"] = 241117 } }, ["ends"] = { { ["x"] = 0.443, ["y"] = 0.383, ["mapID"] = 2413, ["npcID"] = 241117 } }, ["coords"] = { ["mapID"] = 2413, ["x"] = 0.443, ["y"] = 0.383 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15355 } }, ["questGiverID"] = 241117, ["questTurnInID"] = 241117, ["questType"] = "standard", ["sourceQuests"] = { 88993 }, ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 6, ["objectID"] = 240970, ["text"] = "Zaratti forces slain" }, { ["orderIndex"] = 1, ["type"] = 0, ["amount"] = 1, ["objectID"] = 241172, ["text"] = "Follow Wey'nan's trail" }, { ["orderIndex"] = 2, ["type"] = 19, ["amount"] = 0, ["objectID"] = 36978, ["text"] = "tall grass" }, { ["orderIndex"] = 3, ["type"] = 1, ["amount"] = 1, ["objectID"] = 241349 }, { ["orderIndex"] = 4, ["type"] = 0, ["amount"] = 1, ["objectID"] = 241560, ["text"] = "Wey'nan calmed" }, { ["orderIndex"] = 5, ["type"] = 1, ["amount"] = 1, ["objectID"] = 241611 }, { ["orderIndex"] = 6, ["type"] = 0, ["amount"] = 1, ["objectID"] = 241831, ["text"] = "Wey'nan's Ward crafted" } }, ["activities"] = { ["scenarios"] = { { ["id"] = 2982, ["name"] = "The Legend of Wey'nan's Ward", ["areaID"] = 0 } } }, ["db2LabelIDs"] = { 4797 } },
[90537] = { ["id"] = 90537, ["name"] = "Late Bloomers", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90537, 90540, 90569, 90601, 90602, 90963 }, ["series"] = { 90540 }, ["description"] = "It is good to see you again, <name>. Orweyna told me that you might be able to help me with something. A group of rutaani were due to arrive here earlier today, but they're late. They're coming up from Blooming Terrace with my mentor, Ru'gar, and I am worried they've had trouble on the road. Will you scout along the road from here down to the Terrace? I'll come up from there and we can meet on the way if we find nothing.", ["objectivesText"] = "Look for the missing company of rutaani and haranir. Progress: Quietly now. The enemy is close.", ["rewardGold"] = 170800, ["rewardXP"] = 6085, ["rewardItems"] = { 244337 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 242650, ["x"] = 0.368, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 243053, ["x"] = 0.49, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86930 }, ["questLines"] = { { ["id"] = 5935, ["name"] = "Late Bloomers", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90538] = { ["id"] = 90538, ["name"] = "Prey Contract: Zealous Crusader", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["storyline"] = { 90538 }, ["description"] = "A ZEALOUS CRUSADER has been spotted in Eversong! Difficulty: Hard Affixes: Grounded! Unable to use mounts while inside your active Prey Area. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(90538)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(90538))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[90540] = { ["id"] = 90540, ["name"] = "Rutaani Rescue", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90537, 90540, 90569, 90601, 90602, 90963 }, ["series"] = { 90537 }, ["description"] = "Over the hill north of here is a fungarian village, Fungal Cleft. I believe the missing rutaani have been taken there. The fate that awaits them is a brutal one if we do not get them back quickly. Usually, fungarians favor hosts that are already dead for their reproductive purposes. The ones here are strangely vicious, however. I have seen some mushroom-covered animals and rutaani who are still moving around! It is unnatural. Go to Fungal Cleft and see if you can rescue the missing travelers.", ["objectivesText"] = "Rescue 5 Captured Rutaani .", ["rewardGold"] = 309800, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 243053, ["x"] = 0.49, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 243053, ["x"] = 0.49, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90537 }, ["questLines"] = { { ["id"] = 5935, ["name"] = "Late Bloomers", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90544] = { ["id"] = 90544, ["name"] = "Thief at Bark", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15993, ["mapID"] = 2395, ["storyline"] = { 88977, 88978, 88979, 90544, 94388 }, ["description"] = "< Luma stands in front of you, ears perked, thankful for your help. She lets out a short bark, tail wagging once before trotting a few steps forward, then pausing. Glancing back, Luma waits expectantly. Her body language pleads, \"Come on, follow me!\">", ["objectivesText"] = "Follow Luma . Progress: < Luma appears to be waiting for your approval.>", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 262999 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3365, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 242688, ["x"] = 0.392667, ["y"] = 0.387333 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 242688, ["x"] = 0.392667, ["y"] = 0.387333 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.392667, ["y"] = 0.387333 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 88979 }, ["questLines"] = { { ["id"] = 5804, ["name"] = "Theft Tracking", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[90545] = { ["id"] = 90545, ["name"] = "A Reel Problem", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 90545 }, ["description"] = "An essential component of the Oasis ecosystem is the aquatic life within our small lake. It appears that artificial organisms known as Hyrobites are in the lake. Originally introduced to remove toxins in the water, their continued presence threatens the equilibrium of the water. Please remove these mechanical fish immediately!", ["objectivesText"] = "Catch 7 Hydrobites around the Oasis. Progress: Did you catch those fish?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 241352 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 60 }, { ["id"] = 3129, ["amount"] = 300 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 230736, ["x"] = 0.758, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard" },
[90546] = { ["id"] = 90546, ["name"] = "Missing Paladins", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 90546, 90549, 90555, 90556, 90570 }, ["description"] = "Some of our brothers and sisters in the Light were responding to a request for help by the Magisters at the Sanctum of the Moon. Apparently the Twilight's Blade has been seen lurking in the area. We expected to hear back from them awhile ago, but we've heard nothing. Given the strength of the party that went, Salandria and I wanted some additional backup before we looked into the issue. Care to lend a hand?", ["objectivesText"] = "Meet Taelia at the Sanctum of the Moon.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 242803, ["x"] = 0.532, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 242889, ["x"] = 0.44, ["y"] = 0.67 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 2393, 2395 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5908, ["name"] = "Paladin Rescue", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[90547] = { ["id"] = 90547, ["name"] = "Missing Paladins", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 90547, 90548, 90550, 90551, 90552, 90553, 90554, 90556 }, ["description"] = "Some of our brothers and sisters in the Light--including my friend Dawnheart--were responding to a request for help by the Magisters at the Sanctum of the Moon. Apparently the Twilight's Blade has been seen lurking in the area. We expected to hear back from them awhile ago, but we've heard nothing. Given the strength of the party that went, Taelia and I wanted some additional backup before we looked into the issue. Care to lend a hand?", ["objectivesText"] = "Meet Salandria at the Sanctum of the Moon.", ["rewardGold"] = 31200, ["rewardXP"] = 1370, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 242802, ["x"] = 0.532, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 242890, ["x"] = 0.44, ["y"] = 0.67 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 2393, 2395 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5908, ["name"] = "Paladin Rescue", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[90548] = { ["id"] = 90548, ["name"] = "Twilight Missive", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 90547, 90548, 90550, 90551, 90552, 90553, 90554, 90556 }, ["description"] = "We need to figure out what the Twilight's Blade is trying to do here. We also need to get rid of these cultists so the Magisters can get back to their work building runestones. Take out as many cultists as you can. See if any of them are carrying information we can use.", ["objectivesText"] = "Collect 6 missives. Progress: What'd you find?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 244844 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 242890, ["x"] = 0.44, ["y"] = 0.67 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 242890, ["x"] = 0.44, ["y"] = 0.67 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.67 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 90546, 90547 }, ["questLines"] = { { ["id"] = 5908, ["name"] = "Paladin Rescue", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[90549] = { ["id"] = 90549, ["name"] = "Signs of the Struggle", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 90546, 90549, 90555, 90556, 90570 }, ["description"] = "The Twilight's Blade are acting boldly in their takeover here. None of these Magisters have any information for us. We'll hold this end of the bridge and protect any Magisters who escape. You get in there and look for signs of the missing paladins. Were they taken? Did they put up a fight, or were they ambushed? Are they still armed? I have a bad feeling we are running out of time.", ["objectivesText"] = "Look for signs of the lost paladins. Progress: Have you found sign of the missing paladins?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 242889, ["x"] = 0.44, ["y"] = 0.67 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 242889, ["x"] = 0.44, ["y"] = 0.67 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.67 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 90546, 90547 }, ["questLines"] = { { ["id"] = 5908, ["name"] = "Paladin Rescue", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[90550] = { ["id"] = 90550, ["name"] = "A Somber Sun", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 90547, 90548, 90550, 90551, 90552, 90553, 90554, 90556 }, ["description"] = "<The corpse of this Blood Knight has been horribly mangled and tainted by Void magic. He put up a fight, but was unable to survive. Salandria will want to know of this.>", ["objectivesText"] = "Report the corpse to Salandria .", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 242811, ["x"] = 0.432, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 242890, ["x"] = 0.44, ["y"] = 0.67 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 90546, 90547 }, ["questLines"] = { { ["id"] = 5908, ["name"] = "Paladin Rescue", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[90551] = { ["id"] = 90551, ["name"] = "Captured Information", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 90547, 90548, 90550, 90551, 90552, 90553, 90554, 90556 }, ["description"] = "We need to find out where the paladins were taken. Easiest way to do that is ask... under a bit of duress. Find an isolated target, beat them down, and then drag them to the hollow on the other side of the Sanctum. Taelia and I will get the civilians to safety and meet you there.", ["objectivesText"] = "Capture and bring an isolated cultist to the Hollow Grove. Progress: Did you capture a cultist?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 242890, ["x"] = 0.44, ["y"] = 0.67 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 242893, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.67 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 90548, 90549, 90550 }, ["questLines"] = { { ["id"] = 5908, ["name"] = "Paladin Rescue", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[90552] = { ["id"] = 90552, ["name"] = "Interrogation", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 90547, 90548, 90550, 90551, 90552, 90553, 90554, 90556 }, ["description"] = "We need to know where Dawnheart and the others were taken. This one doesn't seem to want to talk... but we can fix that.", ["objectivesText"] = "Interrogate the captive cultist. Progress: Are you sure we don't need to use a little more force?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 242893, ["x"] = 0.416, ["y"] = 0.722 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 242893, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 90551 }, ["questLines"] = { { ["id"] = 5908, ["name"] = "Paladin Rescue", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[90553] = { ["id"] = 90553, ["name"] = "Executing the Blades", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 90547, 90548, 90550, 90551, 90552, 90553, 90554, 90556 }, ["description"] = "Those monsters will pay for what they have done! Take out any Twilight's Blade cultists you see. We'll scour them from Eversong for good!", ["objectivesText"] = "Kill 15 cultists. Progress: Show them no mercy!", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 242897, ["x"] = 0.444, ["y"] = 0.812 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 242897, ["x"] = 0.444, ["y"] = 0.812 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.812 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questTurnInID"] = 242897, ["questType"] = "standard", ["sourceQuests"] = { 90570 }, ["questLines"] = { { ["id"] = 5908, ["name"] = "Paladin Rescue", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
