[90555] = { ["id"] = 90555, ["name"] = "Blessing of Freedom", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 90546, 90549, 90555, 90556, 90570 }, ["description"] = "Our friends are being held in this area. I have no idea what state we'll find them in, but I pray they are at least alive. Help me find and free our missing paladins in the Ruins of Deatholme.", ["objectivesText"] = "Free paladins in the Ruins of Deatholme. Progress: Have <name> found everyone yet?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 242898, ["x"] = 0.444, ["y"] = 0.812 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 242898, ["x"] = 0.444, ["y"] = 0.812 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.812 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questTurnInID"] = 242898, ["questType"] = "standard", ["sourceQuests"] = { 90570 }, ["questLines"] = { { ["id"] = 5908, ["name"] = "Paladin Rescue", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[90556] = { ["id"] = 90556, ["name"] = "Cutting off the Head", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 90546, 90547, 90548, 90549, 90550, 90551, 90552, 90553, 90554, 90555, 90556, 90570 }, ["description"] = "We'll crush their leader! For justice and the Light!", ["objectivesText"] = "Slay Overseer Mognak . Progress: May their ilk never come around here again!", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["rewardItems"] = { 263374, 263375, 263376, 263378 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3365, ["amount"] = 250 } }, ["starts"] = { { ["npcID"] = 245944, ["mapID"] = 2395, ["x"] = 0.444284, ["y"] = 0.812254 } }, ["ends"] = { { ["npcID"] = 245944, ["mapID"] = 2395, ["x"] = 0.444284, ["y"] = 0.812254 } }, ["coords"] = { ["source"] = "quest_giver", ["mapID"] = 2395, ["x"] = 0.444284, ["y"] = 0.812254 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 90553, 90554, 90555 }, ["questLines"] = { { ["id"] = 5908, ["name"] = "Paladin Rescue", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[90568] = { ["id"] = 90568, ["name"] = "Unlikely Friends", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 90481, 90482, 90483, 90484, 90485, 90486, 90568, 93667 }, ["description"] = "This old Witherbark pot you found is quite interesting. I've made a series of notes on its construction and use, but now it's time we speak to Elder Ren'zen . The pot should be returned to him. And he can fill in the gaps in the pot's story! Let's speak with him in the village.", ["objectivesText"] = "Speak with Elder Ren'zen in Witherbark Village.", ["rewardGold"] = 30900, ["rewardXP"] = 1520, ["rewardItems"] = { 264182 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3354, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 242391, ["x"] = 0.468667, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 242464, ["x"] = 0.382, ["y"] = 0.21 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.468667, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 90483, 90484, 90485, 90486 }, ["questLines"] = { { ["id"] = 5905, ["name"] = "Unlikely Friends", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[90569] = { ["id"] = 90569, ["name"] = "Back in the Bag", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90537, 90540, 90569, 90601, 90602, 90963 }, ["description"] = "What a mess this is. The sack you found was supposed to be filled with seeds. They're part of an important cultivation project that Ru'gar was working on. It appears the fungarians made off with the seeds when they captured the rutaani. While you're looking for the rutaani, see if you can recover the seeds that were stolen.", ["objectivesText"] = "Collect 6 Stolen Seeds . Progress: I can't bear to think of what the fungarians will do to the seeds that Ru'gar has been carefully cultivating. He had been working with the rutaani on plants that were more hardy and produced greater yield. His work should not be lost.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 242226 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 243053, ["x"] = 0.49, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 243053, ["x"] = 0.49, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90537 }, ["questLines"] = { { ["id"] = 5935, ["name"] = "Late Bloomers", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90570] = { ["id"] = 90570, ["name"] = "To the Ruins of Deatholme", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 90546, 90549, 90555, 90556, 90570 }, ["description"] = "Thanks to our \"friend\" here, we know the missing paladins were taken to Deatholme. We have to find them before it's too late! Salandria and I will meet you there.", ["objectivesText"] = "Meet Taelia and Salandria at Deatholme.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 242894, ["x"] = 0.416, ["y"] = 0.722 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 242898, ["x"] = 0.444, ["y"] = 0.812 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 90552 }, ["questLines"] = { { ["id"] = 5908, ["name"] = "Paladin Rescue", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[90571] = { ["id"] = 90571, ["name"] = "The Lay of the Beast", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 86509, 86510, 86511, 86512, 86513, 86514, 86515, 86516, 86517, 86518, 86519, 86520, 86521, 86522, 90571, 95276 }, ["series"] = { 86509, 86510 }, ["description"] = "Your friend's scheme to blow up the Nexus-Point was adorable. You all looked so determined, I didn't have the heart to tell you how simple the solution really is. The Mantle of Predation will allow you to enter the Nexus-Points and weaken the storm. Alas, it's claiming the Mantle that will truly test you. Borrow my pet--see through his eyes. I'll show you who you'll steal the Mantle from.", ["objectivesText"] = "Use Decimus 's pet to scout the Voidspire. Progress: Go on. Ciphus won't mind.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 260858, 260859 }, ["rewardChoices"] = { 260858, 260859 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235697, ["x"] = 0.512, ["y"] = 0.703 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235697, ["x"] = 0.512, ["y"] = 0.703 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.703 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86510 }, ["questLines"] = { { ["id"] = 5730, ["name"] = "Dawn of Reckoning", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5730, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[90573] = { ["id"] = 90573, ["name"] = "Fortify the Runestones: Magisters", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "We placed a number of runestones throughout Eversong Woods , each one charged with protective arcane magic intended to ward off the Lightbloom. While highly effective, the runestones require an immense amount of power to function. They must be regularly fed with latent arcana lest they weaken. As Magisters, it is our duty to maintain the runestones--especially when the eyes of this Haven are upon us. Recharge their arcane power and defend them from those who would threaten us.", ["objectivesText"] = "Collect Latent Arcana from Saltheril's Soiree weekly quests and Misplaced Tomes, then use it to charge and defend a Runestone in Eversong Woods . Progress: We must ensure the runestones are charged and defended.", ["rewardGold"] = 341600, ["rewardXP"] = 14705, ["rewardItems"] = { 263465, 268489, 269701, 279522 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 200 }, { ["id"] = 3365, ["amount"] = 2000 }, { ["id"] = 3379, ["amount"] = 125 }, { ["id"] = 3379, ["amount"] = 150 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240834, ["x"] = 0.426, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240834, ["x"] = 0.426, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "group", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 38, ["flags"] = 0 } }, ["activities"] = { ["groupFinder"] = { { ["id"] = 1943, ["name"] = "Eversong", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 11, ["maxPlayers"] = 0 } } }, ["db2PoiUiMapID"] = 2395 },
[90574] = { ["id"] = 90574, ["name"] = "Fortify the Runestones: Blood Knights", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "The Magisters placed a number of runestones throughout Eversong Woods , each one charged with protective arcane magic intended to ward off the Lightbloom. Naturally, the runestones require an immense amount of power to function. They can be fed with latent arcana, but that power draws enemies seeking to claim it. As Blood Knights, it is our duty to defend the runestones--especially when the eyes of this Haven are upon us. Recharge their arcane power and defend them from those who would threaten us.", ["objectivesText"] = "Collect Latent Arcana from Saltheril's Soiree weekly quests and Coalesced Light, then use it to charge and defend a Runestone in Eversong Woods . Progress: Maintaining the safety of Eversong is of utmost importance.", ["rewardGold"] = 341600, ["rewardXP"] = 14705, ["rewardItems"] = { 263465, 268489, 269701, 279522 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 200 }, { ["id"] = 3365, ["amount"] = 2000 }, { ["id"] = 3379, ["amount"] = 125 }, { ["id"] = 3379, ["amount"] = 150 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240835, ["x"] = 0.424, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240835, ["x"] = 0.424, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "group", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 39, ["flags"] = 0 } }, ["activities"] = { ["groupFinder"] = { { ["id"] = 1943, ["name"] = "Eversong", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 11, ["maxPlayers"] = 0 } } }, ["db2PoiUiMapID"] = 2395 },
[90575] = { ["id"] = 90575, ["name"] = "Fortify the Runestones: Farstriders", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "The Magisters placed a handful of runestones across Eversong, each one charged with arcane magic that wards off the Lightbloom. As you might guess, the runestones require a huge amount of power to function. The Magisters feed them with latent arcana, but that kind of power draws a lot of attention. Bad attention. As Farstriders, it's our duty to defend Eversong from those kinds of threats--especially when the Haven is looking at us. Go recharge the runestones and fight off whatever tries to stop you.", ["objectivesText"] = "Collect Latent Arcana from Saltheril's Soiree weekly quests and Ranger's Caches, then use it to charge and defend a Runestone in Eversong Woods . Progress: We need to keep those runestones safe.", ["rewardGold"] = 341600, ["rewardXP"] = 14705, ["rewardItems"] = { 263465, 268489, 269701, 279522 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 200 }, { ["id"] = 3365, ["amount"] = 2000 }, { ["id"] = 3379, ["amount"] = 125 }, { ["id"] = 3379, ["amount"] = 150 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240836, ["x"] = 0.428, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240836, ["x"] = 0.428, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "group", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 40, ["flags"] = 0 } }, ["activities"] = { ["groupFinder"] = { { ["id"] = 1943, ["name"] = "Eversong", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 11, ["maxPlayers"] = 0 } } }, ["db2PoiUiMapID"] = 2395 },
[90576] = { ["id"] = 90576, ["name"] = "Fortify the Runestones: Shades of the Row", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "Have you seen the runestones out in Eversong? Huge rocks full of arcane magic that ward off the Lightbloom. I'm not the magic type, but I know an opportunity when I see one. Those runestones need a lot of power to work. If we help keep them charged, there are a lot of people who would owe us favors--and favors are even better than gold. Here's the plan: I help you get some latent arcana, you drop it into the runestones, beat up whatever tries to stop you, then we bask in the accolades. Deal?", ["objectivesText"] = "Collect Latent Arcana from Saltheril's Soiree weekly quests and Dead Drops , then use it to charge and defend a Runestone in Eversong Woods . Progress: Those runestones aren't going to charge themselves.", ["rewardGold"] = 341600, ["rewardXP"] = 14705, ["rewardItems"] = { 263465, 268489, 269701, 279522 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 200 }, { ["id"] = 3365, ["amount"] = 2000 }, { ["id"] = 3379, ["amount"] = 125 }, { ["id"] = 3379, ["amount"] = 150 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240837, ["x"] = 0.428, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240837, ["x"] = 0.428, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "group", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 41, ["flags"] = 0 } }, ["activities"] = { ["groupFinder"] = { { ["id"] = 1943, ["name"] = "Eversong", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 11, ["maxPlayers"] = 0 } } }, ["db2PoiUiMapID"] = 2395 },
[90601] = { ["id"] = 90601, ["name"] = "Gathering Glowshrooms", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90537, 90540, 90569, 90601, 90602, 90963 }, ["series"] = { 90963 }, ["description"] = "Ru'gar used to tell me about how he'd sneak into the nearby cave to harvest glowshrooms . They seemed to be integral to the development of the tla'tak seeds he was cultivating. Will you collect some of the mushrooms within? Oh, and Ru'gar mentioned that the mushrooms have strange properties when harvested. I'm not sure what he meant by that, but maybe stay on your toes.", ["objectivesText"] = "Collect 6 Glowshrooms . Progress: Ru'gar mentioned that the glowshrooms helped create a more robust harvest when they were mixed into the dirt he'd planted crops in. How he even figured that out, I'll never know. I would like to carry on Ru'gar's work. Since we're already here, we might as well gather what we can.", ["rewardGold"] = 338300, ["rewardXP"] = 12170, ["rewardItems"] = { 244429 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 245166, ["x"] = 0.496, ["y"] = 0.232 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 245166, ["x"] = 0.496, ["y"] = 0.232 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.232 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90963 }, ["questLines"] = { { ["id"] = 5935, ["name"] = "Late Bloomers", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90602] = { ["id"] = 90602, ["name"] = "Gomphusta", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90537, 90540, 90569, 90601, 90602, 90963 }, ["description"] = "I would ask one last thing of you. I've heard quite a few of the fungarians mention their leader, Gomphusta . It seems he's behind the uptick in their violence and the reason they're stealing the seeds. While you're in the cave, find him and take him out. Without Gomphusta pulling the strings, the other fungarians will be thrown into chaos and won't be able to organize ambushes as well.", ["objectivesText"] = "Kill Gomphusta . Progress: The fungarians aren't always this violent and aggressive. Gomphusta must be the force driving them. He seems to be the one infecting living creatures with spores. With him gone, the fungarians may return to a more balanced state.", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 246117, 246120, 263473 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3370, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 245166, ["x"] = 0.496, ["y"] = 0.232 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 245166, ["x"] = 0.496, ["y"] = 0.232 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.232 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90963 }, ["questLines"] = { { ["id"] = 5935, ["name"] = "Late Bloomers", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90615] = { ["id"] = 90615, ["name"] = "Be Grudge You", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90615, 90616, 90617, 90619, 90620, 90621, 90622, 91270, 91450, 92616, 92617, 92618 }, ["series"] = { 90616, 90617 }, ["description"] = "You look... different! Ever be to Grudge Pit? Grudge Pit is great place! Full of fighting and cheering and fungarians. Also decaying! Boletus is always look for strong creatures to be kill in Grudge Pit. Or for making others be kill. Are strong creature? Should go to Pit!", ["objectivesText"] = "Speak with Boletus at the Grudge Pit.", ["rewardGold"] = 31500, ["rewardXP"] = 1520, ["rewardItems"] = { 56891, 56892, 56893, 56894, 56895, 56896 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3370, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 254903, ["x"] = 0.702, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 243226, ["x"] = 0.718, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86930 }, ["nextQuests"] = { 90616 }, ["questLines"] = { { ["id"] = 5910, ["name"] = "The Grudge Pit", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90616] = { ["id"] = 90616, ["name"] = "You Strong?", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90615, 90616, 90617, 90619, 90620, 90621, 90622, 91270, 91450, 92616, 92617, 92618 }, ["series"] = { 90615, 90617 }, ["description"] = "You look strong. Should test yourself in our arena. See how you compare to strong fungarians.", ["objectivesText"] = "Kill enemies in the Grudge Pit. Progress: Many fungarians watch the fighting. Always so exciting!", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 74587, 74588, 74589, 74590, 89125, 141681, 157020, 264257 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 243226, ["x"] = 0.718, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 243226, ["x"] = 0.718, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90615 }, ["questLines"] = { { ["id"] = 5910, ["name"] = "The Grudge Pit", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90617] = { ["id"] = 90617, ["name"] = "A Few Fun Guys", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90615, 90616, 90617, 90619, 90620, 90621, 90622, 91270, 91450, 92616, 92617, 92618 }, ["series"] = { 90615, 90616 }, ["description"] = "You are very strong, $p. Will teach fungarians to fight? Much we could learn from you. Many fungarians watch battle. Ask if they want to be strong in Pit.", ["objectivesText"] = "Recruit 3 Fungarians.", ["rewardGold"] = 170800, ["rewardXP"] = 6085, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 243226, ["x"] = 0.718, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 243226, ["x"] = 0.718, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90616 }, ["questLines"] = { { ["id"] = 5910, ["name"] = "The Grudge Pit", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90619] = { ["id"] = 90619, ["name"] = "What Doesn't Kill Them", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90615, 90616, 90617, 90619, 90620, 90621, 90622, 91270, 91450, 92616, 92617, 92618 }, ["description"] = "Have team, now are ready to fight. Take your team to empty area. Practice fight, and see what can do.", ["objectivesText"] = "Spar with your teammates. Progress: We fighting you? You are strong. Fight together is good practice for be strong.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 243226, ["x"] = 0.718, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 246208, ["x"] = 0.72, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90617 }, ["questLines"] = { { ["id"] = 5910, ["name"] = "The Grudge Pit", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90620] = { ["id"] = 90620, ["name"] = "To the Ring", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90615, 90616, 90617, 90619, 90620, 90621, 90622, 91270, 91450, 92616, 92617, 92618 }, ["description"] = "TeamName? Not bad. I like! You and the TeamName head on down, and we say words. You fight Spore Storm. If beat, fight Cap Clash. If beat, fight Fungus Force. Always-winners are Glow Guard. You won't beat. No run out! Run out is big, big lose.", ["objectivesText"] = "Go fight with your team.", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 9588, 16659, 16660, 16661, 21396, 21399, 21411, 21417, 94219, 114708, 114709, 114710, 114711, 131216, 171828, 187140, 189544, 190189, 190341, 190342, 190343, 190345, 190346, 190347, 190349, 190350, 190351, 190352, 190353, 190354, 190357, 190359, 190360, 190361, 190362, 190365, 190368, 190369, 190370, 190605, 190632, 190633, 190634, 190635, 192422, 192423, 192424, 192428, 192430, 192449, 192450, 192451, 194384 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3370, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 243226, ["x"] = 0.718, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 247245, ["x"] = 0.718, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 91270 }, ["questLines"] = { { ["id"] = 5910, ["name"] = "The Grudge Pit", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
