[90622] = { ["id"] = 90622, ["name"] = "Not-Yet Defeated Champions", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90615, 90616, 90617, 90619, 90620, 90621, 90622, 91270, 91450, 92616, 92617, 92618 }, ["series"] = { 90621 }, ["description"] = "$p, the PHTeamname look stronger now! More ready. Hope they won't run again. Next fight is against Glow Guard. Glow Guard always never lose. Hope your training makes fight better, before TEAMNAME lose. Will be fun for watch!", ["objectivesText"] = "Enter the Grudge Pit and defeat the Glow Guard. Progress: The Grudge Pit is always looking for new champions, <name>. Until now, we've just been finding the old ones again.", ["rewardGold"] = 619600, ["rewardXP"] = 15215, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3370, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 243226, ["x"] = 0.718, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 243226, ["x"] = 0.718, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90621 }, ["questLines"] = { { ["id"] = 5910, ["name"] = "The Grudge Pit", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
