[90669] = { ["id"] = 90669, ["name"] = "Gold is Gold", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 89199, 89200, 89201, 89202, 89203, 89204, 89205, 89206, 89207, 89208, 90669 }, ["description"] = "Hey! You there. < Sarvi beckons you closer and lowers her voice.> You looking for work? A Magister gave me five gold to find an adventuring type to do some sort of job for him. He said if the person gets it done, I get five more. That'll feed me for months. You fit the bill. If you want to try to get paid too, he has a study over by the harbor. Real fancy place--you can't miss it. The guy's name is Aradis.", ["objectivesText"] = "Speak to Magister Aradis in his study near the Silvermoon Harbor.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 1359, 6078, 12293, 21100, 21746, 23444, 57389, 57390, 57391, 57400, 57401, 57402, 67414, 79868, 87399, 88417, 116980, 131196, 131876, 151482, 166846, 174506, 186201, 186205, 186206, 186680, 186688, 186690, 186691, 186692, 186693, 186705, 186706, 186707, 186708, 187328, 187334, 187336, 187466, 204195, 223907, 230905, 232766, 232767, 248798 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 243290, ["x"] = 0.545, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 241393, ["x"] = 0.54, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 86735 }, ["questLines"] = { { ["id"] = 5812, ["name"] = "Lesser Evil", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
