[90690] = { ["id"] = 90690, ["name"] = "Charge of the Vanguard", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 88709, 90690, 90724, 92520 }, ["series"] = { 88709 }, ["description"] = "Turalyon reports the Vanguard of the Light is prepared to march on Xal'atath's stronghold. Would that I could join you for the charge. I will keep my retainer of forces here to maintain the defense of the Sunwell and Silvermoon while you take the fight to our enemy. Muster in the Voidstorm, take the fight to the Voidspire, and bring an end to this great enemy. Good hunting.", ["objectivesText"] = "Meet with Turalyon in the Voidstorm.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 239810, ["x"] = 0.454, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 2393, 2405 }, ["zone"] = { 15969 } }, ["questType"] = "raid", ["sourceQuests"] = { 88706 }, ["nextQuests"] = { 88709 }, ["questLines"] = { { ["id"] = 5793, ["name"] = "The Voidspire", ["orderIndex"] = 0, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5793, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[90701] = { ["id"] = 90701, ["name"] = "Cowardly Cheery Bombs", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16092, ["mapID"] = 2248, ["storyline"] = { 90701 }, ["description"] = "Goblins love bombs, I get that. But does EVERYTHING have to blow up? Do me a favor: In the next Dastardly Duos match you enter, find a cheery bomb inside one of the wooden tree and planter props. After you find the bomb, but before it \"blows up\"... smack it for me. Don't worry, they're cowards.", ["objectivesText"] = "Find a Cheery Bomb , hidden inside a Dastardly prop. Smack it before it blows up. Progress: Those cheery bombs are asking for it, <name>. Find one in a Dastardly Duos match and smack it!", ["rewardGold"] = 341600, ["rewardItems"] = { 237384, 237774 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 234297, ["x"] = 0.526, ["y"] = 0.514 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 234297, ["x"] = 0.526, ["y"] = 0.514 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 86503 } },
[90705] = { ["id"] = 90705, ["name"] = "Lorewalking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 90705 }, ["description"] = "Are you curious about your world's history? Would you like to learn more? Lorewalker Cho has been traveling and gathering stories of important events and figures across Azeroth and beyond. If you pay him a visit in your capital city, he will gladly share a tale of the past with you! Or perhaps more than one tale. He does very much enjoy conversation! Tell him Assistant Lali sent you.", ["objectivesText"] = "Find Lorewalker Cho in Silvermoon, Dornogal, Stormwind, or Orgrimmar.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 242386, 244846, 244858, 244888, 245567, 245631 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 230246, ["x"] = 0.641, ["y"] = 0.163 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.641, ["y"] = 0.163 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[90718] = { ["id"] = 90718, ["name"] = "Request of the Arcantina", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 90718 }, ["description"] = "Ah, <name>! I hear you have a standing invitation to Archmage Khadgar 's... Arcantina? Can you go there for me and bring this missive to the Archmage? I need to source reagents for the sheer volume of telemancy spells I have been asked to conjure. Magister's Terrace has been an excellent source up until recent events but really I need the Kirin Tor to loan me some of their harder to find ingredients.", ["objectivesText"] = "Deliver Telemancer's Request to Archmage Khadgar at the Arcantina. Progress: Champion? Do you have something for me?", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["rewardItems"] = { 260165 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 240265, ["x"] = 0.474, ["y"] = 0.696 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 240265, ["x"] = 0.474, ["y"] = 0.696 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.696 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questTurnInID"] = 240265, ["questType"] = "standard", ["sourceQuests"] = { 92319, 92520 }, ["questLines"] = { { ["id"] = 5794, ["name"] = "Arcantina Reminders", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2195, ["db2PoiUiMapID"] = 2541 },
[90719] = { ["id"] = 90719, ["name"] = "Borrowing Corruption", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 90719 }, ["description"] = "Adventurer, I have made an amazing discovery. Analyzing the memories from the time I have discovered that I might be able to recreate the corruption effects that have been wielded in the past. Albeit in a much more controlled way. I will need you gather some black blood residue from defeating the bosses of the Corrupted or Lost areas of the map and a few more of the displaced corrupted mementos .", ["objectivesText"] = "Find Black Blood Residue and Displaced Corrupted Mementos from the bosses of the Corrupted and Lost areas of the Horrific Visions. Progress: Were you successful?", ["rewardGold"] = 683200, ["rewardItems"] = { 238403, 238407, 238678, 239078, 239084, 239088, 239093 }, ["rewardChoices"] = { 238403, 238678, 239078, 239084, 239088, 239093 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 238136, ["x"] = 0.35, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 238136, ["x"] = 0.35, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard" },
[90724] = { ["id"] = 90724, ["name"] = "The Broken Sky", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2405, ["storyline"] = { 88709, 90690, 90724, 92520 }, ["description"] = "All those people. Our army. Our heroes. Our leaders. Gone. We are exposed here. Umbric's tether saved us, but we need to ensure we survive this. Report to Lor'themar and tell him what transpired in the Voidspire. I will get Umbric to safety and learn what I can here.", ["objectivesText"] = "Report to Lor'themar in Silvermoon City.", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 }, { ["id"] = 3391, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 253603, ["x"] = 0.445, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 2393, 2405 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 88709 }, ["questLines"] = { { ["id"] = 5793, ["name"] = "The Voidspire", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5793, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 2393 },
[90729] = { ["id"] = 90729, ["name"] = "Win-Win Situation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 90663, 90729, 90747, 90769, 90770, 90773 }, ["description"] = "Not everything you recovered yesterday was mine, but let's be honest--we're going to keep it anyway! Xy'daz has been ripping people off for years. It's his turn to take a loss! Now, this can work in both our favors. You sell off half of the leftover goods for me, and I'll let you keep the rest!", ["objectivesText"] = "Sell 6 Shadowtrade Overstock. Progress: Did you sell the items?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 242529, 242667, 242708, 242733 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 238016, ["x"] = 0.575, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 238016, ["x"] = 0.575, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 90663 }, ["questLines"] = { { ["id"] = 5941, ["name"] = "Ba'eth's Request", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2472 },
[90731] = { ["id"] = 90731, ["name"] = "Enhancing Corruption", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 90731 }, ["description"] = "Welcome back adventurer. I have made a new discovery but I need to test it out. Hidden in the Lost areas of the Horrific Visions I believe is a rare black blood coagulate . This might be the key to increasing the power of the corruption effects... in a safe way. If you can go into these areas and find this item and also bring me back more displaced corrupted mementos I should be able to increase the potency of the corruption effects.", ["objectivesText"] = "Find Black Blood Coagulate and Displaced Corrupted Mementos from the bosses of the Lost areas of the Horrific Visions. Progress: Were you successful?", ["rewardGold"] = 683200, ["rewardItems"] = { 238405, 238680, 239080, 239086, 239090, 239095, 242648 }, ["rewardChoices"] = { 238405, 238680, 239080, 239086, 239090, 239095 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 238136, ["x"] = 0.35, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 238136, ["x"] = 0.35, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 90719 } },
[90733] = { ["id"] = 90733, ["name"] = "The Listener", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90733, 90734, 90735, 90736, 90737, 90738, 90739, 90740, 90741, 90742, 90743, 90744, 90745 }, ["description"] = "Now that you've learned about our legends, you've earned the notice of one of our elders. He wants to meet you. His name is Aksem , and he knows things that the rest of us have never learned. History that remains hidden, even in the paintings. Go and introduce yourself. He's expecting you.", ["objectivesText"] = "Speak to Aksem in the Den.", ["rewardGold"] = 315900, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 243759, ["x"] = 0.534, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 88998, 88999, 91053, 91054, 91456, 91511, 91512 }, ["questLines"] = { { ["id"] = 5929, ["name"] = "The Empty Cradle", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90734] = { ["id"] = 90734, ["name"] = "In the Name of the Goddess", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90733, 90734, 90735, 90736, 90737, 90738, 90739, 90740, 90741, 90742, 90743, 90744, 90745 }, ["description"] = "The high priest Aksem has asked for you again. He said you are not the only one on a quest for knowledge about the deep history of Harandar . Go to him. I believe he already has another guest who is also interested in learning this hidden history.", ["objectivesText"] = "Return to Aksem in the Den. Progress: Tea will calm your thoughts.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 243759, ["x"] = 0.534, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 88998, 88999, 91053, 91054, 91456, 91511, 91512 }, ["questLines"] = { { ["id"] = 5929, ["name"] = "The Empty Cradle", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90735] = { ["id"] = 90735, ["name"] = "The Stolen Staff", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90733, 90734, 90735, 90736, 90737, 90738, 90739, 90740, 90741, 90742, 90743, 90744, 90745 }, ["series"] = { 90738 }, ["description"] = "This time, I do not have a story for you. Instead, Aksem has asked that you meet with him to help recover the next of the relics. Go to speak with him, and he will tell you more of what you must do.", ["objectivesText"] = "Speak to Aksem in the Den.", ["rewardGold"] = 31200, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3370, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 243759, ["x"] = 0.534, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 88998, 88999, 91053, 91054, 91456, 91511, 91512 }, ["questLines"] = { { ["id"] = 5929, ["name"] = "The Empty Cradle", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90736] = { ["id"] = 90736, ["name"] = "That's Not Yours", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90733, 90734, 90735, 90736, 90737, 90738, 90739, 90740, 90741, 90742, 90743, 90744, 90745 }, ["description"] = "The rutaani in the Blossoming Terrace are crafty. They've trained their petalwings to search and grab anything shiny that rolls down from the Den. And, I suspect, sometimes they grab things that haven't naturally fallen. So we want to get those things back. That's where you come in. Go into the terrace, and don't hesitate to use force to send a message. That's a language we all understand.", ["objectivesText"] = "Retrieve 8 Stolen Belongings from the Blossoming Terrace. Progress: Have you found those missing things?", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 246221 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 243762, ["x"] = 0.588, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 243762, ["x"] = 0.588, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90738 }, ["questLines"] = { { ["id"] = 5929, ["name"] = "The Empty Cradle", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90737] = { ["id"] = 90737, ["name"] = "Nested Clues", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90733, 90734, 90735, 90736, 90737, 90738, 90739, 90740, 90741, 90742, 90743, 90744, 90745 }, ["description"] = "You're looking for a staff called the Root of the World. It's a powerful twist of woven roots, back from before the haranir traveled deep into the mountain. It's irreplaceable, as Aksem knows. So if a rutaani petalwing stole it, that's embarrassing. The only way for everyone to save face is to get it back. Search the nests of the bigger birds. They've been trained to look for more valuable items.", ["objectivesText"] = "Uncover clues about where the stolen rootstaff could be. Progress: Have you found where the staff might be?", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 243762, ["x"] = 0.588, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 243762, ["x"] = 0.588, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90738 }, ["questLines"] = { { ["id"] = 5929, ["name"] = "The Empty Cradle", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90738] = { ["id"] = 90738, ["name"] = "To the Blossoming Terrace", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90733, 90734, 90735, 90736, 90737, 90738, 90739, 90740, 90741, 90742, 90743, 90744, 90745 }, ["series"] = { 90735 }, ["description"] = "When the haranir first arrived in Harandar , they brought with them a staff formed of the roots of a great tree. That tree has since gone away, but the roots remain. It has been our duty to protect that staff and pass it on through the generations, but now it has been stolen. Your task is to find it and return it to Zur'Ashar Kassameh. Go into the mists below the Den and seek out the Shul'ka. They will guide you on your search.", ["objectivesText"] = "Meet Shul'ka Seila outside the Blossoming Terrace.", ["rewardGold"] = 31200, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3370, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 243759, ["x"] = 0.534, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 243762, ["x"] = 0.588, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.534, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90735 }, ["questLines"] = { { ["id"] = 5929, ["name"] = "The Empty Cradle", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90739] = { ["id"] = 90739, ["name"] = "The Root of Things", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90733, 90734, 90735, 90736, 90737, 90738, 90739, 90740, 90741, 90742, 90743, 90744, 90745 }, ["series"] = { 90740 }, ["description"] = "Looks like you didn't find any sign of the rootstaff among all the thiever's nests. That's a good thing, honestly. But there's more to this test than just recovering stolen goods. Yes, it's a test. You're seeking secret knowledge. That means something here doesn't add up, and the real answer is waiting to be found. So, come find me when you're ready to get that answer.", ["objectivesText"] = "Follow Shul'ka Seila and recover the missing staff.", ["rewardGold"] = 312800, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 243762, ["x"] = 0.588, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 243759, ["x"] = 0.534, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90736, 90737 }, ["questLines"] = { { ["id"] = 5929, ["name"] = "The Empty Cradle", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90740] = { ["id"] = 90740, ["name"] = "A Legend to Know", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90733, 90734, 90735, 90736, 90737, 90738, 90739, 90740, 90741, 90742, 90743, 90744, 90745 }, ["series"] = { 90739 }, ["description"] = "I am entrusted with many secrets, and the benefit of that is not having to explain myself often. You have recovered the Root of the World, as I asked. Now, take it to Zur'ashar Kassemeh, and learn more about it. There will be more for you, later.", ["objectivesText"] = "Return to Zur'ashar Kassameh .", ["rewardGold"] = 30900, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3370, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 243759, ["x"] = 0.534, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.534, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90739 }, ["questLines"] = { { ["id"] = 5929, ["name"] = "The Empty Cradle", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90741] = { ["id"] = 90741, ["name"] = "Once More Into the Rift", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90733, 90734, 90735, 90736, 90737, 90738, 90739, 90740, 90741, 90742, 90743, 90744, 90745 }, ["description"] = "Aksem has asked for you again. He says he's ready for you to undergo the final ritual for the knowledge he wants to teach you. I admit, I'm envious, but I do not envy the trials you'll need to undergo in order to prepare for this knowledge. Go speak to Aksem , and do as he says. Orweyna will be joining you.", ["objectivesText"] = "Speak to Aksem , then meet Orweyna in the Rift of Aln.", ["rewardGold"] = 34100, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3370, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 243795, ["x"] = 0.618, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90740 }, ["questLines"] = { { ["id"] = 5929, ["name"] = "The Empty Cradle", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90742] = { ["id"] = 90742, ["name"] = "Shrouded by Aln'hara", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90733, 90734, 90735, 90736, 90737, 90738, 90739, 90740, 90741, 90742, 90743, 90744, 90745 }, ["description"] = "As you know well by now, the creatures in the rift are infused with the essence of Aln'hara. What we need is that essence mixed with water. Aksem wants us to collect water here and then infuse the essence of Aln'hara into it. I can only imagine what it might be used for.", ["objectivesText"] = "Collect water and defeat creatures in the Rift of Aln. Progress: The voice is as strong as ever here.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 243795, ["x"] = 0.618, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 243795, ["x"] = 0.618, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90741 }, ["questLines"] = { { ["id"] = 5929, ["name"] = "The Empty Cradle", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90743] = { ["id"] = 90743, ["name"] = "Ritual Reinforcement", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90733, 90734, 90735, 90736, 90737, 90738, 90739, 90740, 90741, 90742, 90743, 90744, 90745 }, ["description"] = "You know the dangers of the Rift of Aln, but this is the best place to prepare for the kind of ritual Aksem wants to perform. Go about the rift and place offerings to prepare yourself.", ["objectivesText"] = "Place Ritual Offerings in the Rift of Aln.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 243794, ["x"] = 0.618, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 243794, ["x"] = 0.618, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90741 }, ["questLines"] = { { ["id"] = 5929, ["name"] = "The Empty Cradle", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90744] = { ["id"] = 90744, ["name"] = "The Dreamrift: Malformed Mystery", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90733, 90734, 90735, 90736, 90737, 90738, 90739, 90740, 90741, 90742, 90743, 90744, 90745 }, ["series"] = { 90745 }, ["description"] = "We have prepared ourselves as best we can for the next stage. Now, we must venture into the deepest part of the Rift of Aln. Into the Dreamrift. It's a place so dangerous that even the Shul'ka hesitate to go, but we must. Aksem needs us to collect the most powerful infusion of Aln there is. Are you ready?", ["objectivesText"] = "Defeat Chimaerus in the Dreamrift.", ["rewardGold"] = 1024800, ["rewardXP"] = 17650, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 500 }, { ["id"] = 3344, ["amount"] = 30 }, { ["id"] = 3370, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 243795, ["x"] = 0.618, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 243759, ["x"] = 0.534, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "raid", ["sourceQuests"] = { 90743 }, ["questLines"] = { { ["id"] = 5929, ["name"] = "The Empty Cradle", ["orderIndex"] = 11, ["flags"] = 0 } }, ["activities"] = { ["groupFinder"] = { { ["id"] = 1753, ["name"] = "Harandar", ["mapID"] = 2694, ["difficultyID"] = 0, ["expansion"] = 11, ["maxPlayers"] = 0 } } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90745] = { ["id"] = 90745, ["name"] = "The Empty Cradle", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90733, 90734, 90735, 90736, 90737, 90738, 90739, 90740, 90741, 90742, 90743, 90744, 90745 }, ["series"] = { 90744 }, ["description"] = "You have ventured far, fought deep, and learned many things about our history to be here. Now it's time to know the truth. Prepare yourself.", ["objectivesText"] = "Speak to Aksem in the Den.", ["rewardGold"] = 34100, ["rewardXP"] = 1520, ["rewardItems"] = { 260306 }, ["rewardCurrencies"] = { { ["id"] = 3370, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 243759, ["x"] = 0.534, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 243759, ["x"] = 0.534, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.534, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90744 }, ["questLines"] = { { ["id"] = 5929, ["name"] = "The Empty Cradle", ["orderIndex"] = 12, ["flags"] = 0 } } },
[90746] = { ["id"] = 90746, ["name"] = "The Elves Assemble", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = true, ["expansion"] = 11, ["storyline"] = { 90746 }, ["series"] = { 88769 }, ["description"] = "The time for preparations have passed. Xal'atath's forces are upon us. Join us, champion, as we must rebuff this assault and then press our attack on the Darkwell.", ["objectivesText"] = "Speak to Arator at the war table.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[90747] = { ["id"] = 90747, ["name"] = "The Wrong Bluecephalus", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 90663, 90729, 90747, 90769, 90770, 90773 }, ["description"] = "We may have gotten off on the wrong foot, but there's something you should know. That old slateback you used to haul all those imports? I thought it was just another worn-out nag, but it turns out it was the real treasure all along. A rare bluecephalus, worth a fortune! You might want to figure out where it went, and why Ba'eth isn't exactly rushing to share the profits!", ["objectivesText"] = "Speak with Ba'eth and others. Progress: Are you ready to help?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 242667, 242708, 242733 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 243291, ["x"] = 0.468, ["y"] = 0.365 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 243926, ["x"] = 0.485, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.365 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 90729 }, ["questLines"] = { { ["id"] = 5941, ["name"] = "Ba'eth's Request", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[90748] = { ["id"] = 90748, ["name"] = "Quel'Danas", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 88710, 90748 }, ["series"] = { 88710, 90993 }, ["description"] = "Champion, the time has come to see an end to the Darkwell. I do not know what awaits us beyond the gates of Quel'Danas, but we cannot tarry any longer. The Void continues to pour into the Darkwell, transforming it. Arator is at the head of our combined armies. He has asked you and your strongest allies join him at his side. It is time to end this and take back our well.", ["objectivesText"] = "Meet with Arator before the gates of Quel'Danas.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["rewardItems"] = { 257736 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 2424, ["npcID"] = 245061, ["x"] = 0.525333, ["y"] = 0.903333 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 2393, 2424 }, ["zone"] = { 15969 } }, ["questType"] = "raid", ["sourceQuests"] = { 88769 }, ["nextQuests"] = { 88710 }, ["questLines"] = { { ["id"] = 5797, ["name"] = "March on Quel'Danas", ["orderIndex"] = 0, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5797, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2913, ["db2PoiUiMapID"] = 2533 },
[90749] = { ["id"] = 90749, ["name"] = "Our Mutual Enemy", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2395, ["storyline"] = { 86652, 86708, 86710, 86711, 86712, 86715, 86716, 86717, 86718, 86719, 86720, 86721, 86722, 86723, 86868, 90749 }, ["description"] = "<Liadrin lowers her voice, speaking only to you.> We have two choices. We can either continue to talk to the Amani or fight our way inside. I would still prefer to negotiate passage with Zul'jarra, but if our diplomacy goes awry, be ready. For now, follow my lead.", ["objectivesText"] = "Follow Lady Liadrin into Zul'Aman .", ["rewardGold"] = 162600, ["rewardXP"] = 6085, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236436, ["x"] = 0.602, ["y"] = 0.814 } }, ["ends"] = { { ["mapID"] = 2536, ["npcID"] = 236485, ["x"] = 0.055, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.814 }, ["mapCandidates"] = { ["npc"] = { 2395, 2536 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86710 }, ["questLines"] = { { ["id"] = 5722, ["name"] = "Dis Was Our Land", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5722, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 2437 },
[90754] = { ["id"] = 90754, ["name"] = "Skyriding", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 7502, ["mapID"] = 371, ["storyline"] = { 80012, 80013, 80015, 80016, 80017, 80018, 90754 }, ["description"] = "This land is more vast than I remember. However, a good scholar is always prepared. To cover more ground, you will need a winged mount and the skill to ride it swiftly. I recall Lord Andestrasz helping us with this in the past, near the Timeless Isle in Pandaria. Let's send you back to that moment in time, so you can learn from him. Don't wander too far in distant lands, you're still needed back here. Return via the portal when you have finished your instructions.", ["objectivesText"] = "Take Moratari 's portal to Lord Andestrasz . Progress: All things come with practice.", ["rewardGold"] = 31200, ["rewardXP"] = 175, ["rewardItems"] = { 194034 }, ["starts"] = { { ["x"] = 0.721, ["y"] = 0.417, ["mapID"] = 627, ["npcID"] = 243948 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 218469, ["x"] = 0.652, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 7502 } }, ["questGiverID"] = 243948, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5546, ["name"] = "Introduction to Skyriding", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
[90755] = { ["id"] = 90755, ["name"] = "Time Flies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 90755 }, ["description"] = "That should suffice for now. Remember the basics and you will improve in time. Speaking of time, you had best be on your way. The portal there will take you back to Moratari .", ["objectivesText"] = "Return to Moratari .", ["rewardGold"] = 31200, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 218469, ["x"] = 0.652, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 218469, ["x"] = 0.652, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questTurnInID"] = 218469, ["questType"] = "standard", ["sourceQuests"] = { 80018 } },
[90759] = { ["id"] = 90759, ["name"] = "The Cult Within", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 4922, ["mapID"] = 84, ["storyline"] = { 90759, 90760, 90762, 90766, 90767, 90768 }, ["description"] = "<A missive written on shimmering vellum unfurls before you.> $p, Rumors suggest that Xal'atath's cult, the Twilight's Blade, has been recruiting in Alliance cities. Meet me in Stormwind to investigate these rumors. If the cult is there, then we must stamp it out at once. Magister Umbric", ["objectivesText"] = "Meet Magister Umbric in Stormwind.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 224148, 232856, 244911, 246628, 248218, 249438, 249468 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 246156, ["x"] = 0.718, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 246156, ["x"] = 0.718, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5930, ["name"] = "The Cult Within", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[90760] = { ["id"] = 90760, ["name"] = "Avoiding Blame", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 90759, 90760, 90762, 90766, 90767, 90768 }, ["description"] = "Apocalyptic threats have taken many forms in Azeroth's history, but today we face Xal'atath and her Twilight's Blade. I fear that people are falling into hopelessness as the Radiant Song cries a warning. The Twilight's Blade could use that despair to draw them into their ranks. My mages have identified this district as housing a peculiar amount of void energy. Investigate and stop any cultists you may find.", ["objectivesText"] = "Disperse 6 Suspicious Citizens in Stormwind. Progress: I understand the comfort the void can provide. But surrendering to it completely is not the peace many are led to believe.", ["rewardGold"] = 273848, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 246156, ["x"] = 0.718, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 246156, ["x"] = 0.718, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 90759 }, ["questLines"] = { { ["id"] = 5930, ["name"] = "The Cult Within", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[90761] = { ["id"] = 90761, ["name"] = "Avoiding Blame", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 90761, 90762, 90763, 90764, 90765, 90766, 90768 }, ["description"] = "The cult of twilight has long been dedicated to ending Azeroth. That they ally with Xal'atath is no surprise. If the Twilight's Blade are indoctrinating citizens, we must stop them. We cannot permit the weak to fall to the Void's dark designs. The Cleft of Shadow is home to many practitioners of unsavory magic. Identify and end any cultists you may find there.", ["objectivesText"] = "Disperse 6 Suspicious Citizens in Orgrimmar . Progress: <Rommath sneers at you.> The calm and comfort the Void offers is a lie. You would do well to abandon it.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 246158, ["x"] = 0.42, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 246158, ["x"] = 0.42, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["sourceQuests"] = { 90764 }, ["questLines"] = { { ["id"] = 5930, ["name"] = "The Cult Within", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85 },
[90762] = { ["id"] = 90762, ["name"] = "The Twilight Highlands", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 4922, ["mapID"] = 84, ["storyline"] = { 90759, 90760, 90761, 90762, 90763, 90764, 90765, 90766, 90767, 90768 }, ["description"] = "I've spoken with Grand Magister Rommath . Despite our differences, it seems we are aligned in purpose. We have both found evidence that Twilight's Blade cultists are convening in the Twilight Highlands . It's a place long scarred by the cult's misdeeds. And it's a suitable staging ground for an attack. Meet us there so we may continue our investigation.", ["objectivesText"] = "Meet Grand Magister Rommath in the Twilight Highlands .", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 246156, ["x"] = 0.718, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 237504, ["x"] = 0.498, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 84, 241 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 90760 }, ["questLines"] = { { ["id"] = 5930, ["name"] = "The Cult Within", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 241 },
[90763] = { ["id"] = 90763, ["name"] = "The Twilight Highlands", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 4922, ["mapID"] = 85, ["storyline"] = { 90761, 90762, 90763, 90764, 90765, 90766, 90768 }, ["description"] = "I've received word from Magister Umbric. He has found similar evidence that the Twilight's Blade are recruiting in Stormwind. The Void poses an existential threat to all of Azeroth. We must stop the cult at its source. We've agreed to meet in the cult's homeland, the Twilight Highlands . Find me there so we may continue our investigation.", ["objectivesText"] = "Meet Grand Magister Rommath in the Twilight Highlands .", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 246158, ["x"] = 0.42, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 237504, ["x"] = 0.498, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 85, 241 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["sourceQuests"] = { 90761 }, ["questLines"] = { { ["id"] = 5930, ["name"] = "The Cult Within", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 241 },
[90764] = { ["id"] = 90764, ["name"] = "The Cult Within", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 4922, ["mapID"] = 85, ["storyline"] = { 90761, 90762, 90763, 90764, 90765, 90766, 90768 }, ["description"] = "<A missive written on fine parchment unfurls before you.> $p, I have heard unsettling rumors that Xal'atath's cult, the Twilight's Blade, is recruiting within Horde cities. Meet me in Orgrimmar so we may root out this evil. We cannot suffer a single cultist within our walls. Grand Magister Rommath", ["objectivesText"] = "Meet Grand Magister Rommath in Orgrimmar.", ["rewardGold"] = 23635, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 246158, ["x"] = 0.42, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 246158, ["x"] = 0.42, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5930, ["name"] = "The Cult Within", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85 },
[90765] = { ["id"] = 90765, ["name"] = "Midnight Dress", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 90761, 90762, 90763, 90764, 90765, 90766, 90768 }, ["description"] = "Cult activity in the area has risen significantly. While we are gathering troops, you secure a cultist disguise and infiltrate their nearby training grounds. Find out anything you can about the Twilight's Blade and their goals. I will keep this area secure.", ["objectivesText"] = "Find a Twilight's Blade disguise and infiltrate the Twilight's Blade. Progress: You look lost, fledgling. Isn't there somewhere you should be?", ["rewardGold"] = 292100, ["rewardXP"] = 1415, ["rewardItems"] = { 246397, 246398, 246399, 246400, 249438 }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 237504, ["x"] = 0.498, ["y"] = 0.808 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 246021, ["x"] = 0.464, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.808 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard", ["sourceQuests"] = { 90762, 90763 }, ["questLines"] = { { ["id"] = 5930, ["name"] = "The Cult Within", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 241 },
[90766] = { ["id"] = 90766, ["name"] = "Xal'atath's Proven Faithful", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 90759, 90760, 90761, 90762, 90763, 90764, 90765, 90766, 90767, 90768 }, ["description"] = "It takes more than blistering desperation for the apocalypse to be part of the Cult of Twilight. We are Xal'atath's Twilight's Blade. Our purpose is greater than it has ever been before. And thus, we must become her strongest allies. Go and train with my associates in the field. Educate yourself on our rituals and rhetoric. Only then will I allow you to go through the initiation ceremony.", ["objectivesText"] = "Train to become a Twilight's Blade cultist.", ["rewardGold"] = 292100, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 246021, ["x"] = 0.464, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 246022, ["x"] = 0.521, ["y"] = 0.708 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard", ["sourceQuests"] = { 90765 }, ["questLines"] = { { ["id"] = 5930, ["name"] = "The Cult Within", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 241 },
[90767] = { ["id"] = 90767, ["name"] = "More Doom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 90759, 90760, 90762, 90766, 90767, 90768 }, ["description"] = "Having completed your training, you have earned full membership with the Twilight's Blade. <Harrowtongue pauses a moment, appearing self-satisfied.> As a member of the cult, you will now join your fellow acolytes in an initiation ceremony. They are in the basement of this building receiving instructions from our great leader, Mor'duun. Allow his words to fill you with zeal for the cause. The end is near!", ["objectivesText"] = "Sabotage the ritual. Progress: Have you discovered more about the cult's plans?", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 250465 }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 246022, ["x"] = 0.521, ["y"] = 0.708 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 246025, ["x"] = 0.524, ["y"] = 0.704 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.521, ["y"] = 0.708 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard", ["sourceQuests"] = { 90766 }, ["questLines"] = { { ["id"] = 5930, ["name"] = "The Cult Within", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 241 },
[90768] = { ["id"] = 90768, ["name"] = "Cult It Out", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 90759, 90760, 90761, 90762, 90763, 90764, 90765, 90766, 90767, 90768 }, ["description"] = "Mor'duun and his Twilight's Blade cultists are directly supporting the Harbinger's dark designs for our world. And that is all we need to know. Kill as many as you can, then meet us back at our base of operations. The cult and its leaders must be eliminated.", ["objectivesText"] = "Kill Gehl Harrowtongue and 12 Twilight's Blade cultists.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 37961, 38003, 38045, 38107, 59376, 59377, 59378, 59379, 62192, 62193, 62194, 131627, 198402, 199647, 199651, 199652, 199653, 199654, 200550, 200551, 224148, 232856, 244911, 246627, 246628, 248047, 248048, 248218, 249438, 249468 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 30 } }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 246025, ["x"] = 0.524, ["y"] = 0.704 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 237504, ["x"] = 0.498, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.524, ["y"] = 0.704 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard", ["sourceQuests"] = { 90767 }, ["questLines"] = { { ["id"] = 5930, ["name"] = "The Cult Within", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 241 },
[90769] = { ["id"] = 90769, ["name"] = "A Blue for You", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["description"] = "Why you want such a strange beast? I save many better items just for you. What about some soap? But, I not deny $p heart's desire.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 242733 }, ["starts"] = { { ["npcID"] = 243915, ["x"] = 0.488, ["y"] = 0.412, ["mapID"] = 2472 } }, ["ends"] = { { ["npcID"] = 243915, ["x"] = 0.488, ["y"] = 0.412, ["mapID"] = 2472 } }, ["coords"] = { ["x"] = 0.488, ["y"] = 0.412, ["source"] = "quest_giver", ["mapID"] = 2472 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 90770 }, ["questLines"] = { { ["id"] = 5941, ["name"] = "Ba'eth's Request", ["orderIndex"] = 5, ["flags"] = 0 } } },
[90770] = { ["id"] = 90770, ["name"] = "The Grift", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 90663, 90729, 90747, 90769, 90770, 90773 }, ["description"] = "Dey say you want the blue beast. Was a great bargain I stumbled upon. Da bazaar full of opportunities. Many more bargains to find in spots where treasures lie waiting. You know where to look? Go to dis special place and find treasures, I give the blue beast to you.", ["objectivesText"] = "Enter Untethered Space and recover the items Griftah requires. Progress: Did you find da treasures?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 723, 242371, 242667, 242708, 242733, 243049, 243050, 243053, 243054, 243055 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 243915, ["x"] = 0.486, ["y"] = 0.414667 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 243915, ["x"] = 0.486, ["y"] = 0.414667 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.486, ["y"] = 0.414667 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 90773 }, ["questLines"] = { { ["id"] = 5941, ["name"] = "Ba'eth's Request", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[90772] = { ["id"] = 90772, ["name"] = "The Flames Rise Higher", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86653, 86654, 86655, 86656, 86657, 86658, 86659, 86660, 86661, 86663, 86664, 86665, 86666, 86808, 86809, 89334, 90772, 92084 }, ["description"] = "De coal... it's white-hot now. And I feel like there is somethin' inside it? Brek said dis was de last trial. But Jan'alai is not here. What do we do now? < Zul'jarra looks at Brek and scowls.> Talk to Brek and see if he's got anything to say we can understand.", ["objectivesText"] = "Complete the ritual of Jan'alai. Progress: If I cannot commune with Jan'alai, de path of de hash'ey stops at dis temple.", ["rewardGold"] = 32800, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3354, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 236162, ["x"] = 0.55, ["y"] = 0.184 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 236162, ["x"] = 0.55, ["y"] = 0.184 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.184 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86665 }, ["questLines"] = { { ["id"] = 5723, ["name"] = "Path of de Hash'ey", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5723, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 2437 },
[90773] = { ["id"] = 90773, ["name"] = "Meat My Business", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 90663, 90729, 90747, 90769, 90770, 90773 }, ["description"] = "Since I am helping you, I'm sure you won't mind returning the favor. I have a constant need for fresh, untainted meat, which is quite hard to come by. The Oasis is off limits, but the wildlife roaming these sands? I've got a list of what I need. Bring me those items, and I'll tell you what you need to know.", ["objectivesText"] = "Collect 12 Dustback Flank , 5 Siltwing Tail , and 5 Swoopwing Eggs . Progress: You've collect all the meat?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 242667, 242708, 242733, 242794, 242796, 242797 }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 243926, ["x"] = 0.485, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 243926, ["x"] = 0.485, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 90747 }, ["questLines"] = { { ["id"] = 5941, ["name"] = "Ba'eth's Request", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[90776] = { ["id"] = 90776, ["name"] = "Ancient Curiosity: Combat", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15329, ["mapID"] = 2393, ["storyline"] = { 90776 }, ["description"] = "<You hold the curio and discover a shimmering glow emanating from it. This looks important. The Explorers' League would be interested in this.>", ["objectivesText"] = "Use and equip a Combat Curio to Brann Bronzebeard.", ["rewardXP"] = 9515, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15329 } }, ["questType"] = "standard", ["startItems"] = { 242849 } },
[90777] = { ["id"] = 90777, ["name"] = "Feeding the Flame", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 88696, 88697, 88698, 88699, 88700, 88701, 88702, 88703, 88704, 88705, 88706, 90777, 91417, 91426, 94957 }, ["description"] = "Champion, the Sunwell holds for now, but the Vanguard has begun to deploy the bulk of its forces to Voidstorm. Lady Liadrin has requested your assistance at the Sunwell.", ["objectivesText"] = "Speak to Liadrin at the Sunwell. Progress: It's heartening to see our commanders so eager to bring the fight to the enemy.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 2424, ["npcID"] = 247414, ["x"] = 0.53, ["y"] = 0.585 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 2393, 2424 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 86522 }, ["questLines"] = { { ["id"] = 5792, ["name"] = "Foothold", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5792, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 2424 },
