[90779] = { ["id"] = 90779, ["name"] = "Cracked Keystone", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["storyline"] = { 90779 }, ["description"] = "Fragmentary images of heroic deeds flash though your mind as you touch the stone, but they fade as fast as they arrive. Perhaps performing a suitably impressive task will stabilize the stone's magic once more?", ["objectivesText"] = "Complete any dungeon on Mythic 2 or higher difficulty.", ["rewardGold"] = 1239200, ["rewardXP"] = 19030, ["rewardItems"] = { 242919 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[90781] = { ["id"] = 90781, ["name"] = "Sparks of War: K'aresh", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2339, ["storyline"] = { 90781 }, ["description"] = "There's rumors about conflict rising in K'aresh - go off and find out more!", ["objectivesText"] = "Collect 100 Sparks of War in K'aresh , while in War Mode. Progress: Go off and finish what you started.", ["rewardItems"] = { 219934 }, ["rewardCurrencies"] = { { ["id"] = 2123, ["amount"] = 1000 }, { ["id"] = 1792, ["amount"] = 500 }, { ["id"] = 1602, ["amount"] = 50 }, { ["id"] = 2815, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard" },
[90782] = { ["id"] = 90782, ["name"] = "The Nethersent", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90782, 90866, 90872, 90873, 90874, 90875 }, ["description"] = "<The draenei first tries to speak to you in his native tongue, adapting after you fail to respond.> Men of Void take us to here. Come from sky. Fighting, killing. Want to go back. Help brothers and sisters. Show you.", ["objectivesText"] = "Free the draenei and meet with him at the base of Masters' Perch.", ["rewardGold"] = 85400, ["rewardXP"] = 3210, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 242233, ["x"] = 0.562, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 241620, ["x"] = 0.396, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86509 }, ["questLines"] = { { ["id"] = 5933, ["name"] = "The Nethersent", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[90818] = { ["id"] = 90818, ["name"] = "Murder Row: Loose Lips", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 90818, 90819, 90821, 90822, 90835, 90837 }, ["description"] = "It is not unexpected to sense some fel magic here. There are still warlocks in the city and old fel siphoning chambers. But the evidence I've found so far is more than could be explained by just that. It feels... different. Chaotic. This practice has to be widespread, which means someone must be talking about it. I've been rooting around too long to go unnoticed, but perhaps you could covertly listen in on some idle banter around the city. If you learn anything useful, report back to me.", ["objectivesText"] = "Listen in on 3 conversations near the Royal Exchange. Progress: People let many things slip when they assume they're unheard. Never assume you're unheard.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 245418, ["x"] = 0.515, ["y"] = 0.642 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 244443, ["x"] = 0.561, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 90835 }, ["questLines"] = { { ["id"] = 5931, ["name"] = "Fear and Fel", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[90819] = { ["id"] = 90819, ["name"] = "Murder Row: Acting the Part", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 90818, 90819, 90821, 90822, 90835, 90837 }, ["description"] = "Based on what we discovered, I believe the fel is coming from Murder Row. Someone there is breaking down Legion relics and infusing the magic into mana wyrms for covert siphoning--and people are buying it up in droves. We need to figure out who that someone is. Take this wyrm core with you into the Row and look for more of them. The promise of coin should get you in front of the right person.", ["objectivesText"] = "Take the Cracked Wyrm Core , then investigate Murder Row to discover the source of the smuggled fel wyrms. Progress: The denizens of Murder Row are tight-lipped, but any information we manage to uncover will be invaluable.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 244407, 244528, 253210, 253211, 253212 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 244443, ["x"] = 0.561, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 244454, ["x"] = 0.545, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.561, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 90818, 90837 }, ["questLines"] = { { ["id"] = 5931, ["name"] = "Fear and Fel", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[90821] = { ["id"] = 90821, ["name"] = "Murder Row: Harbored Secrets", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 90818, 90819, 90821, 90822, 90835, 90837 }, ["description"] = "That manifest is stamped by the Silvermoon Harbor. It looks like Zaen has his smugglers working there to push his fel relic shipments through inspections. If we cut off their supply line at the harbor, we can halt the fel operation until we track down Zaen and end it for good. No sense going after the middlemen until then. Subterfuge got us this far, so let's keep at it. Head to the harbor and tell them you're picking up Zaen's shipment. We'll work from there.", ["objectivesText"] = "Talk to the dockmaster at the Silvermoon Harbor to collect Zaen's fel relic shipment. Progress: Zaen is the mastermind here, or at least he seems to be. We'll need to deal with him to truly end this scheme. Taking out their fel supply line at the harbor will stop the situation from getting any worse while we find him.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 244547 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 244454, ["x"] = 0.545, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 245297, ["x"] = 0.322, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 90819 }, ["questLines"] = { { ["id"] = 5931, ["name"] = "Fear and Fel", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[90822] = { ["id"] = 90822, ["name"] = "Murder Row: One Fel Swoop", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 90818, 90819, 90821, 90822, 90835, 90837 }, ["description"] = "We have all the puzzle pieces. Zaen smuggles fel relics from the Broken Isles by stacking the Silvermoon Harbor with his own smugglers. The relics are processed in Murder Row, then fel magic is infused into mana wyrms for sale and siphoning. Such a convoluted operation might be impressive, if the goals weren't so reckless. Zaen is preying on people's fear. He doesn't care who he helps or hurts as long as he rakes in the gold. Let us end it. We'll find the Illicit Rain in Murder Row and clear it out.", ["objectivesText"] = "Dismantle the fel smuggling operation inside Murder Row. Progress: Something seems to have happened in Murder Row since we left. A crowd is forming. Proceed with caution. I'm with you.", ["rewardGold"] = 1366400, ["rewardXP"] = 23530, ["rewardItems"] = { 251132, 251136, 251142 }, ["rewardChoices"] = { 251132, 251136, 251142 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 50 }, { ["id"] = 3365, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 245297, ["x"] = 0.322, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 244446, ["x"] = 0.565, ["y"] = 0.612 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.322, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 90821 }, ["questLines"] = { { ["id"] = 5931, ["name"] = "Fear and Fel", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[90824] = { ["id"] = 90824, ["name"] = "My Brother's Alive!", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90824, 90826, 90827, 90829, 90830, 90831, 90832, 90833, 90834 }, ["description"] = "En'liahn saved me from the Rift of Aln. He's my older brother. I know it was stupid to go there, but it wasn't my fault! We all thought En'liahn was dead, but I saw him earlier at the wetland. When he saw me, he ran away. < Chua looks sad.> No one here believes me and now I can't go. Will you help me find him again?", ["objectivesText"] = "Find En'liahn at the Ahl'ua Wetland.", ["rewardGold"] = 30900, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3370, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 244163, ["x"] = 0.522, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 244242, ["x"] = 0.43, ["y"] = 0.614 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86890 }, ["questLines"] = { { ["id"] = 5932, ["name"] = "Trials of the Shul'ka", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90826] = { ["id"] = 90826, ["name"] = "The Healing Waters of Ahl'ua", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90824, 90826, 90827, 90829, 90830, 90831, 90832, 90833, 90834 }, ["series"] = { 90827, 90829, 90830, 90831, 90832 }, ["description"] = "I'd hoped Chua hadn't seen me. Better he thinks I died. Instead, I'm self-exiling. I was trapped in the Rift of Aln while saving him. Being in there for so long corrupted my connection to the goddess--if I don't sever it soon, it'll drive me mad, or worse. The Shul'ka who saved me has agreed to mentor me through the process. He told me to come here and gather some things for a ritual to sever the connection. I must collect the nearby healing waters. Will you help me fill this jug?", ["objectivesText"] = "Collect 6 Healing Waters of Ahl'ua . Progress: I appreciate your help, <name>.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 85500, 243196, 246118 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 244242, ["x"] = 0.43, ["y"] = 0.614 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 244242, ["x"] = 0.43, ["y"] = 0.614 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.614 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90824 }, ["questLines"] = { { ["id"] = 5932, ["name"] = "Trials of the Shul'ka", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90827] = { ["id"] = 90827, ["name"] = "Only the Poisonous Parts", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90824, 90826, 90827, 90829, 90830, 90831, 90832, 90833, 90834 }, ["series"] = { 90826, 90829, 90830, 90831, 90832 }, ["description"] = "My Shul'ka mentor instructed me to collect the toxic glands from the creatures here. He said they were crucial to the Ritual of Severing in order to break my connection with the goddess. < En'liahn shakes his head in pain.> I'm not looking forward to whatever this ritual is, but her disjointed song in my head is getting stronger and making it hard to focus.", ["objectivesText"] = "Collect 8 Phytogenic Poison Parts . Progress: Be careful handling that poison. These creatures are some of the deadliest in all of Harandar .", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 243598 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 244242, ["x"] = 0.43, ["y"] = 0.614 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 244242, ["x"] = 0.43, ["y"] = 0.614 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.614 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90824 }, ["questLines"] = { { ["id"] = 5932, ["name"] = "Trials of the Shul'ka", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90829] = { ["id"] = 90829, ["name"] = "Meeting My Mentor", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["series"] = { 90826, 90827, 90830, 90831, 90832 }, ["description"] = "I'm in your debt, . I didn't think I'd get any help. My mentor only provides guidance. He says that is the way of the Shul'ka. Thanks to you, I have everything I need for the ritual. Will you continue on with me? I'm heading for the cliffside overlooking the Rift of Aln to the northeast.", ["rewardGold"] = 30900, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3370, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 244242, ["x"] = 0.43, ["y"] = 0.614, ["mapID"] = 2413 } }, ["ends"] = { { ["npcID"] = 244394, ["x"] = 0.638, ["y"] = 0.546, ["mapID"] = 2413 } }, ["coords"] = { ["x"] = 0.43, ["y"] = 0.614, ["source"] = "quest_giver", ["mapID"] = 2413 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90826, 90827 }, ["questLines"] = { { ["id"] = 5932, ["name"] = "Trials of the Shul'ka", ["orderIndex"] = 3, ["flags"] = 0 } } },
[90830] = { ["id"] = 90830, ["name"] = "The Path Will Reveal Itself", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90824, 90826, 90827, 90829, 90830, 90831, 90832, 90833, 90834 }, ["series"] = { 90826, 90827, 90829, 90831, 90832 }, ["description"] = "The next step is to locate the ritual site. It's different for each potential Shul'ka. Amarakk says that I must open myself to the power of the rift--that some part of myself tied to this place will guide the way. All I can tell you is it hurts. Are you still with me?", ["objectivesText"] = "Travel with En'liahn to discover the ritual site within the Rift of Aln. Progress: I see you made it.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 244394, ["x"] = 0.638, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 244455, ["x"] = 0.628, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90829 }, ["questLines"] = { { ["id"] = 5932, ["name"] = "Trials of the Shul'ka", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90831] = { ["id"] = 90831, ["name"] = "Doing Is Becoming", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90824, 90826, 90827, 90829, 90830, 90831, 90832, 90833, 90834 }, ["series"] = { 90826, 90827, 90829, 90830, 90832 }, ["description"] = "If En'liahn is to succeed as a Shul'ka, he must learn to disrupt the manifestations in the rift. Sometimes that means closing small tears as they open. Most of the time, we simply slay the manifestations where we find them so they do not become so numerous as to threaten the rest of Harandar . It is a never-ending responsibility each of us bears. It is why we are Shul'ka. This, of course, assumes that he survives the ritual, or even survives to find the ritual site.", ["objectivesText"] = "Disrupt the manifestations within the Rift of Aln. Progress: I see you, <name>.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 244419, ["x"] = 0.638, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 244455, ["x"] = 0.628, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90829 }, ["questLines"] = { { ["id"] = 5932, ["name"] = "Trials of the Shul'ka", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90832] = { ["id"] = 90832, ["name"] = "As Her Voice Goes Silent", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90824, 90826, 90827, 90829, 90830, 90831, 90832, 90833, 90834 }, ["series"] = { 90826, 90827, 90829, 90830, 90831 }, ["description"] = "En'liahn is about to drink the mixture of the poison and healing waters to begin the ritual. He will be unconscious and fighting for his life. The manifestations of the rift can sense this, and they are gathering. <name>, you must place the wards and use their power to defend him while he severs his final connection to the goddess before her song drives him to madness.", ["objectivesText"] = "Protect En'liahn while he endures the Ritual of Severing. Progress: Whatever happens next, you've proven you can be trusted.", ["rewardGold"] = 170800, ["rewardXP"] = 6085, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 244455, ["x"] = 0.628, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 244455, ["x"] = 0.628, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90830, 90831 }, ["questLines"] = { { ["id"] = 5932, ["name"] = "Trials of the Shul'ka", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90833] = { ["id"] = 90833, ["name"] = "The Final Rite", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90824, 90826, 90827, 90829, 90830, 90831, 90832, 90833, 90834 }, ["series"] = { 90834 }, ["description"] = "Foolish. En'liahn is still weak from the ritual and not prepared. He has run off to confront Morta'ka the Sundered Echo . This is the final rite of all who would become Shul'ka, but it is usually only attempted after years of preparation. En'liahn will not survive, and in dying will only make Morta'ka more powerful. Will you save him, <name>?", ["objectivesText"] = "Help En'liahn to slay the manifestation known as Morta'ka the Sundered Echo inside the Shadow Cleft.", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3370, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 244455, ["x"] = 0.628, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 244473, ["x"] = 0.615, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90832 }, ["questLines"] = { { ["id"] = 5932, ["name"] = "Trials of the Shul'ka", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90834] = { ["id"] = 90834, ["name"] = "From This Point Forward", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90824, 90826, 90827, 90829, 90830, 90831, 90832, 90833, 90834 }, ["series"] = { 90833 }, ["description"] = "I don't know how to feel about losing my connection with Aln'hara. There's no more pain... I'm not going mad, but there's a hole inside. Does that make sense? Will you rejoin us back up on the cliff?", ["objectivesText"] = "Return to En'liahn and Amarakk on the cliff overlooking the Rift of Aln.", ["rewardGold"] = 312800, ["rewardXP"] = 12170, ["rewardItems"] = { 263020 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3370, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 244473, ["x"] = 0.615, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 244394, ["x"] = 0.638, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90833 }, ["questLines"] = { { ["id"] = 5932, ["name"] = "Trials of the Shul'ka", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90835] = { ["id"] = 90835, ["name"] = "Murder Row: Rumors Abound", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 90818, 90819, 90821, 90822, 90835, 90837 }, ["description"] = "I would advise exploring the city with caution. Not all is what it seems in Silvermoon. The Illidari are performing an investigation which need not be spoken of openly. But you appear formidable... Perhaps you can aid us. My commander, Belath Dawnblade , is heading the investigation. The last I heard, he was surveying the upper terraces of the Bazaar. Seek him out, if you would make use of yourself.", ["objectivesText"] = "Find Belath Dawnblade in the terraces above the Bazaar.", ["rewardGold"] = 31200, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 244493, ["x"] = 0.56, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 244440, ["x"] = 0.515, ["y"] = 0.642 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 86735 }, ["questLines"] = { { ["id"] = 5931, ["name"] = "Fear and Fel", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[90837] = { ["id"] = 90837, ["name"] = "Murder Row: Traces of Fel", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 90818, 90819, 90821, 90822, 90835, 90837 }, ["description"] = "I have been sensing powerful fel magic throughout Silvermoon, but this is the first origin point I could locate. The rest were too faint, or perhaps deliberately hidden. Fortunately, this means we now have a specific area to comb through more closely. We need to gather more evidence. Go around this area and see if you can find more hidden sources of fel. I will grant you a temporary portion of my sight so that even the slightest hint of fel magic will be obvious to you.", ["objectivesText"] = "Discover 5 sources of fel magic near the Royal Exchange. Progress: Were you able to locate anything?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 243236, 243237, 243238, 243239, 243240 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 245418, ["x"] = 0.515, ["y"] = 0.642 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 244443, ["x"] = 0.561, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 90835 }, ["questLines"] = { { ["id"] = 5931, ["name"] = "Fear and Fel", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[90838] = { ["id"] = 90838, ["name"] = "Oaths and Heirlooms", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90838, 90844, 90845, 90847, 90848, 90851, 90852, 90858, 90860, 93396 }, ["description"] = "You, stranger... do you know of the Shadowguard that left K'aresh in ruins? My sister was lost in the conflict, her heart forcibly turned to the Void, but I swore oaths to my family... to cherish them no matter their transgressions. My sister, Veraan, is surely lost, but if I were to recover her necklace, at least then my oaths would be upheld in spirit. I am a simple tinkerer. I've tuned this device to track the Shadowguard, but I cannot face them alone. Would you help me?", ["objectivesText"] = "Meet Kifaan outside of the Ethereum Overcroft.", ["rewardGold"] = 31500, ["rewardXP"] = 1605, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3389, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 244490, ["x"] = 0.506, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 244499, ["x"] = 0.446, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 90571 }, ["nextQuests"] = { 90844, 90845 }, ["questLines"] = { { ["id"] = 6014, ["name"] = "Oaths to Family", ["orderIndex"] = 1, ["flags"] = 1 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[90840] = { ["id"] = 90840, ["name"] = "What's Your Specialty?", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 1519, ["mapID"] = 2022, ["description"] = "The Dragon Isles is a dangerous and uncharted place. We'll need to get you prepared. You're strong enough now that you should choose a combat specialization. This will unlock a new array of abilities for you to face the dangers within the Dragon Isles. Go ahead and choose your combat specialization.", ["rewardXP"] = 505, ["rewardItems"] = { 25474, 175165, 246462 }, ["starts"] = { { ["npcID"] = 244496, ["x"] = 0.812, ["y"] = 0.28, ["mapID"] = 2022 } }, ["ends"] = { { ["npcID"] = 244496, ["x"] = 0.812, ["y"] = 0.28, ["mapID"] = 2022 } }, ["coords"] = { ["x"] = 0.812, ["y"] = 0.28, ["source"] = "quest_giver", ["mapID"] = 2022 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 59985 }, ["questLines"] = { { ["id"] = 5459, ["name"] = "The Dragon Isles", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6025, ["name"] = "Welcome to the Waking Shore", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 49, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5459, ["questLineOrder"] = 2 }, { ["id"] = 322, ["title"] = "Exile's Reach", ["questLineID"] = 6025, ["questLineOrder"] = 0 } } },
[90842] = { ["id"] = 90842, ["name"] = "Home Is Where the Hearth Is", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 1519, ["mapID"] = 2022, ["description"] = "Before you head off, you'll want to get yourself a Hearthstone . This little stone will return you to the inn where you last bound it to. It's not much of an \"inn\", but the explorers have a tent set up. Test out that new mount of yours and ride over to Sil'nori Crestshade. He'll get you sorted out with a Hearthstone .", ["rewardXP"] = 505, ["starts"] = { { ["npcID"] = 244496, ["x"] = 0.812, ["y"] = 0.28, ["mapID"] = 2022 } }, ["ends"] = { { ["npcID"] = 244496, ["x"] = 0.812, ["y"] = 0.28, ["mapID"] = 2022 } }, ["coords"] = { ["x"] = 0.812, ["y"] = 0.28, ["source"] = "quest_giver", ["mapID"] = 2022 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 90840 }, ["questLines"] = { { ["id"] = 5459, ["name"] = "The Dragon Isles", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6025, ["name"] = "Welcome to the Waking Shore", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 50, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5459, ["questLineOrder"] = 2 }, { ["id"] = 322, ["title"] = "Exile's Reach", ["questLineID"] = 6025, ["questLineOrder"] = 0 } } },
[90843] = { ["id"] = 90843, ["name"] = "Aiding the Dragon Isles", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 1519, ["mapID"] = 2022, ["description"] = "It's time for us to part ways. I have pressing business further within the Dragon Isles in a place called the Azure Span. Naleidea Rivergleam of the Dragonscale Expedition could use your help. Safe travels, . I look forward to our next meeting!", ["rewardXP"] = 505, ["starts"] = { { ["npcID"] = 244496, ["x"] = 0.812, ["y"] = 0.28, ["mapID"] = 2022 } }, ["ends"] = { { ["npcID"] = 184841, ["x"] = 0.806, ["y"] = 0.276, ["mapID"] = 2022 } }, ["coords"] = { ["x"] = 0.812, ["y"] = 0.28, ["source"] = "quest_giver", ["mapID"] = 2022 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 90842 }, ["questLines"] = { { ["id"] = 5459, ["name"] = "The Dragon Isles", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 6025, ["name"] = "Welcome to the Waking Shore", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 51, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5459, ["questLineOrder"] = 2 }, { ["id"] = 322, ["title"] = "Exile's Reach", ["questLineID"] = 6025, ["questLineOrder"] = 0 } } },
[90844] = { ["id"] = 90844, ["name"] = "Fits of Lucidity", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90838, 90844, 90845, 90847, 90848, 90851, 90852, 90858, 90860, 93396 }, ["series"] = { 90845, 90847, 90848 }, ["description"] = "While I've been lurking, I've been listening. These Shadowguard appear to have a minor rebellion on their hands. Some of the ethereals are acting erratically. They're being rounded up and questioned. What's going on here? Dispatch some of these Shadowguard and intercept their intel. I'll decode anything you bring back to me.", ["objectivesText"] = "Slay ethereals in the Ethereum Overcroft and collect 8 Interrogated Data . Progress: I thought the Void coursing through these ethereals was all-consuming. And yet, there seem to be some able to resist its infinite darkness.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 244146 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 244499, ["x"] = 0.446, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 244499, ["x"] = 0.446, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 90838 }, ["questLines"] = { { ["id"] = 6014, ["name"] = "Oaths to Family", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[90845] = { ["id"] = 90845, ["name"] = "Distant Memories", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90838, 90844, 90845, 90847, 90848, 90851, 90852, 90858, 90860, 93396 }, ["series"] = { 90844, 90847, 90848 }, ["description"] = "I swore an oath to honor my family... difficult when my sister was converted to the Shadowguard. She may not be here, but tracking the Shadowguard has led me to this place. I'm looking for a necklace that belonged to my sister Veraan. It's odd... I've noticed many K'areshi heirlooms discarded around here. It seems the Shadowguard wish to destroy any reminders of our home world. If you bring some of these trinkets and baubles to me, we can see if there are any I recognize.", ["objectivesText"] = "Collect 8 K'areshi Keepsakes found at the Ethereum Overcroft. Progress: These keepsakes are some of the last remnants of our home world. The memories they contain are powerful. The Shadowguard is right to fear them.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 244775 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 244499, ["x"] = 0.446, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 244499, ["x"] = 0.446, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 90838 }, ["questLines"] = { { ["id"] = 6014, ["name"] = "Oaths to Family", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[90847] = { ["id"] = 90847, ["name"] = "Truth From Power", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90838, 90844, 90845, 90847, 90848, 90851, 90852, 90858, 90860, 93396 }, ["series"] = { 90844, 90845, 90848 }, ["description"] = "Thanks to your intel, we have learned that the rebels are being interrogated by Questioner Xen'daan . It is said that after being questioned, the rebel ethereals are being taken somewhere to be \"dealt with.\" The head questioner is sure to know more. If we can find where they've taken the rebels, there may still be hope for them.", ["objectivesText"] = "Slay Questioner Xen'daan at the Ethereum Overcroft to discover the rebels' whereabouts. Progress: At the risk of getting my hopes up... do you think Veraan could be among them? Could I face her now? After the atrocities she's committed in the name of the Void?", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardItems"] = { 245628 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 244499, ["x"] = 0.446, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 244499, ["x"] = 0.446, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 90844, 90845 }, ["questLines"] = { { ["id"] = 6014, ["name"] = "Oaths to Family", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[90848] = { ["id"] = 90848, ["name"] = "She Started the Fire", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90838, 90844, 90845, 90847, 90848, 90851, 90852, 90858, 90860, 93396 }, ["series"] = { 90844, 90845, 90847 }, ["description"] = "Veraan is sure to be amongst the rebels taken to Shadowguard Point. Her fiery spirit fills me with great pride! I came here expecting to say a farewell of sorts. I did not come here expecting to find my sister. Perhaps it's not too late, <name>!", ["objectivesText"] = "Meet Kifaan at Shadowguard Point.", ["rewardGold"] = 30900, ["rewardXP"] = 1605, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3389, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 244499, ["x"] = 0.446, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 244516, ["x"] = 0.3988, ["y"] = 0.476 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 90847 }, ["questLines"] = { { ["id"] = 6014, ["name"] = "Oaths to Family", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[90849] = { ["id"] = 90849, ["name"] = "Light Show", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16182, ["mapID"] = 2432, ["storyline"] = { 90849 }, ["objectivesText"] = "Luminescent Wards activated", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.362, ["y"] = 0.275, ["mapID"] = 2432 } }, ["ends"] = { { ["x"] = 0.362, ["y"] = 0.275, ["mapID"] = 2432 } }, ["coords"] = { ["mapID"] = 2432, ["x"] = 0.362, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16182 } }, ["questType"] = "standard", ["sourceQuests"] = { 86807 }, ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 10, ["objectID"] = 246280 }, { ["orderIndex"] = 1, ["type"] = 0, ["amount"] = 6, ["objectID"] = 244520, ["text"] = "Luminescent Wards activated" } }, ["db2PoiMapID"] = 2858, ["db2PoiUiMapID"] = 2432 },
[90851] = { ["id"] = 90851, ["name"] = "Eating Their Own", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90838, 90844, 90845, 90847, 90848, 90851, 90852, 90858, 90860, 93396 }, ["description"] = "The Shadowguard seem to have no qualms caging and torturing their own kind. The last thing I want is more violence amongst the people of K'aresh, but better them than us. Disrupt their operation by subduing some of the Shadowguard.", ["objectivesText"] = "Slay 12 Shadowguard Engineers and Infusers at Shadowguard Point.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 244516, ["x"] = 0.3988, ["y"] = 0.476 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 244516, ["x"] = 0.3988, ["y"] = 0.476 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.3988, ["y"] = 0.476 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 90848 }, ["questLines"] = { { ["id"] = 6014, ["name"] = "Oaths to Family", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[90852] = { ["id"] = 90852, ["name"] = "Techno-Magnetic Pulse", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90838, 90844, 90845, 90847, 90848, 90851, 90852, 90858, 90860, 93396 }, ["description"] = "The betrayers are being held in stasis chambers. I've seen these cages before. Their design is efficient but fragile. They will fail with the slightest energy variation. Find crackling energy vessels strewn about and heave them at the stasis chambers. With true aim, you will disable them and free the betrayers.", ["objectivesText"] = "Throw Crackling Energy Vessels at arcane prisons to free the Caged Betrayers .", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 244516, ["x"] = 0.3988, ["y"] = 0.476 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 244516, ["x"] = 0.3988, ["y"] = 0.476 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.3988, ["y"] = 0.476 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 90848 }, ["questLines"] = { { ["id"] = 6014, ["name"] = "Oaths to Family", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[90858] = { ["id"] = 90858, ["name"] = "Repress the Oppressors", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90838, 90844, 90845, 90847, 90848, 90851, 90852, 90858, 90860, 93396 }, ["series"] = { 90860 }, ["description"] = "We were brought here to face the wrath of Soulbinder D'zaar. She commands the Shadowguard here. She leverages the power of the Voidstorm to convert souls to energy that she consumes. She and her loyalists are traitors to our kind! < Veraan grimaces in pain as the Void courses through her.> They must be stopped... their devices dismantled... their will ended... <name>... destroy them all!", ["objectivesText"] = "Disrupt the operation by slaying ethereals, destroying Fragile Energy Piping , and detonating Volatile Energy Reservoirs . Progress: < Veraan trembles with rage.> These kinslayers were willing to sacrifice their own. And in service of what? Xal'atath's will?", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 244522, ["x"] = 0.415333, ["y"] = 0.507333 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 244522, ["x"] = 0.415333, ["y"] = 0.507333 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.415333, ["y"] = 0.507333 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 93396 }, ["questLines"] = { { ["id"] = 6014, ["name"] = "Oaths to Family", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[90860] = { ["id"] = 90860, ["name"] = "Shedding the Yoke", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90838, 90844, 90845, 90847, 90848, 90851, 90852, 90858, 90860, 93396 }, ["series"] = { 90858 }, ["description"] = "Rebels like us are brought to Soulbinder D'zaar . She suffers no betrayers. Our fate was to be sacrificed--our souls converted to energy. D'zaar works the conduit with arcane mastery to absorb these souls! We don't have much time. I can feel the Void pressing from within. If we are to leave this life violently, D'zaar and her conduit are coming with us!", ["objectivesText"] = "Slay Soulbinder D'zaar at Shadowguard Point. Progress: The pressure is building... it's almost time... And besides, do I even deserve to live? What will they say of me, a member of the Shadowguard, when all is said and done? Do you think Kifaan could ever forgive me?", ["rewardGold"] = 676600, ["rewardXP"] = 16055, ["rewardItems"] = { 264407, 264408, 264409, 264410 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3389, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 244522, ["x"] = 0.415333, ["y"] = 0.507333 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 244522, ["x"] = 0.415333, ["y"] = 0.507333 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.415333, ["y"] = 0.507333 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 90858 }, ["questLines"] = { { ["id"] = 6014, ["name"] = "Oaths to Family", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[90861] = { ["id"] = 90861, ["name"] = "Those Left Behind", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 90861, 90862, 90867, 90871, 90876, 92689 }, ["description"] = "In the wake of Xal'atath's destruction, what remains of our forces are gathering at the Darkwell to determine what we can do about the remnants of the Void. We cannot abide the presence of so much dark energy. Some of our greatest casters and most knowledgeable scholars believe they might have a solution, but we could use your aid. Please, join Arator at the Darkwell at your earliest convenience.", ["objectivesText"] = "Seek out Arator at the Darkwell.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 2424, ["npcID"] = 244557, ["x"] = 0.526, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 2393, 2424 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 90871, 90876 }, ["questLines"] = { { ["id"] = 5798, ["name"] = "Dawn of a New Well", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5798, ["questLineOrder"] = 5 } } },
[90862] = { ["id"] = 90862, ["name"] = "In Times of Need", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16215, ["mapID"] = 2424, ["storyline"] = { 90861, 90862, 90867, 90876, 92689 }, ["description"] = "The last of the other elven leaders have returned with powers from their homeland that will help us in cleansing the Darkwell. While the Voidstorm no longer barrages the Darkwell, it still needs healing. Please meet with the other leaders and let them know we are ready for them.", ["objectivesText"] = "Speak with each of the elven leaders.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 }, { ["id"] = 3391, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2424, ["npcID"] = 244557, ["x"] = 0.526, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 2424, ["npcID"] = 244576, ["x"] = 0.525, ["y"] = 0.461 } }, ["coords"] = { ["mapID"] = 2424, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 2424 }, ["zone"] = { 16215 } }, ["questType"] = "standard", ["sourceQuests"] = { 90861 }, ["questLines"] = { { ["id"] = 5798, ["name"] = "Dawn of a New Well", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5798, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 2424 },
[90866] = { ["id"] = 90866, ["name"] = "Universal Language", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90782, 90866, 90872, 90873, 90874, 90875 }, ["description"] = "To go home, water of life. Need. <Tul'amar attempts to discern if you understand what she's talking about with a look. After a pause, she opts to stab her own fingertip with the end of her staff and then displays a bead of her blood to you.> This. Of here. Is of fight. Of fight is Void. Void is power. With power, go home. <She shows her fangs with an exaggerated snarl before pantomiming a claw swipe.> Water of life. Of beast. Much. Yes?", ["objectivesText"] = "Collect blood from the beasts north of the Night Trench. Progress: You. Not die? Good.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 243350 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 241620, ["x"] = 0.396, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 241620, ["x"] = 0.396, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 90782 }, ["questLines"] = { { ["id"] = 5933, ["name"] = "The Nethersent", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[90867] = { ["id"] = 90867, ["name"] = "From Darkness, Light", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16215, ["mapID"] = 2424, ["storyline"] = { 90861, 90862, 90867, 90876, 92689 }, ["description"] = "We will not let the Sunwell be corrupted again. This Darkwell must change, but it must change to something that we are no longer bound to with such dependency. We do not need this well to be the bait for so many other world-corrupting forces. No, today we heal the Darkwell, and make it something new. Let me know when you are ready.", ["objectivesText"] = "Conduct the ritual to cleanse the Darkwell.", ["rewardGold"] = 1024800, ["rewardXP"] = 20540, ["rewardItems"] = { 257143, 265106, 265631 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3365, ["amount"] = 1000 }, { ["id"] = 3391, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2424, ["npcID"] = 244576, ["x"] = 0.525, ["y"] = 0.461 } }, ["ends"] = { { ["mapID"] = 2424, ["npcID"] = 245469, ["x"] = 0.525, ["y"] = 0.459 } }, ["coords"] = { ["mapID"] = 2424, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.461 }, ["mapCandidates"] = { ["npc"] = { 2424 }, ["zone"] = { 16215 } }, ["questType"] = "standard", ["sourceQuests"] = { 90862 }, ["questLines"] = { { ["id"] = 5798, ["name"] = "Dawn of a New Well", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5798, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 2424 },
[90869] = { ["id"] = 90869, ["name"] = "It's All in the Image", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["description"] = "So, the higher-ups in the marketing department say you need a good partner to soften your aesthetic of... you know, \"murder everyone around me for gold.\" We've got two focus group approved goblins over there ready to go, so go take your pick. Sassy will handle the paperwork. Oh, don't give me that look. You only gotta forever-love each other in front of the public. Once the cameras are off, no one cares. It'll be great for your reputation!", ["objectivesText"] = "Speak to Sassy Hardwrench to select a \"marketing partner.\" Progress: C'mon, this ain't rocket surgery. Pick whoever you wanna pose on some magazine covers with.", ["rewardGold"] = 309800, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 34874, ["x"] = 0.591, ["y"] = 0.76775 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 34874, ["x"] = 0.591, ["y"] = 0.76775 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.591, ["y"] = 0.76775 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 5, ["flags"] = 1 } }, ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194 },
[90870] = { ["id"] = 90870, ["name"] = "Gathering the Grub", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 90870 }, ["description"] = "Ah, ye're here! Brewfest is here and we've got a small problem. We can't have a proper feast without the food, but some pesky hozen thought it'd be fun to steal our bags of grub. I'm sure they're just lookin' to fill their own bellies, but it's messin' up our plans! So here's what I need ye to do: hunt down those hozen and take back the bags they've snatched. There's a good chance ye'll find a few bags just sittin' on the ground too. When ye return, just add the recovered bags to that wagon back there.", ["objectivesText"] = "Collect Bags of Brewfest Ingredients and deposit them at the wagon. Progress: The feast won't come together without those ingredients!", ["rewardGold"] = 29200, ["rewardXP"] = 25, ["rewardItems"] = { 37829, 62978, 62979, 62980, 62981, 64641, 243479 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 242172, ["x"] = 0.56, ["y"] = 0.374 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 242172, ["x"] = 0.56, ["y"] = 0.374 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.374 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 }, ["db2QuestSortName"] = "Epic" },
[90871] = { ["id"] = 90871, ["name"] = "The Silversun Compact", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 90861, 90871, 92689 }, ["description"] = "Champion. After much discussion, negotiation, and even some screaming and three duels, the Sunreavers and the Silver Covenant have decided on a course of action to define both of our futures. Given your aid in getting us to this day, we would like you here to act as a witness as we formalize and sign our peace accords. Will you do us the honor of igniting the Flames of Remembrance?", ["objectivesText"] = "Assist in the formalization of The Silversun Compact . Progress: Strange times. Strange times indeed.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 }, { ["id"] = 3391, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 244699, ["x"] = 0.401, ["y"] = 0.895 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 247452, ["x"] = 0.41, ["y"] = 0.888 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.401, ["y"] = 0.895 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 92689 }, ["questLines"] = { { ["id"] = 5798, ["name"] = "Dawn of a New Well", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5798, ["questLineOrder"] = 5 } } },
[90872] = { ["id"] = 90872, ["name"] = "Drenched In It", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90782, 90866, 90872, 90873, 90874, 90875 }, ["description"] = "<Tul'amar looks away from the blood-soaked and mortified Juras, and toward the portal as it flickers to life. She reads it with her powers of the arcane.> Good. Blood is vio... violent? Violent is power. Need more. Now, brothers and sisters. <She gestures to the blood in your possession, and then to her people. Many of them return wary looks your way.> You can. I say. Then, go out. See of me.", ["objectivesText"] = "Mark 8 Offworld Refugees with Predator Blood to empower the portal in Exiles' Hovel. Progress: Done?", ["rewardGold"] = 170800, ["rewardXP"] = 6425, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 241620, ["x"] = 0.396, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 241620, ["x"] = 0.396, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 90866 }, ["questLines"] = { { ["id"] = 5933, ["name"] = "The Nethersent", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[90873] = { ["id"] = 90873, ["name"] = "These Violent Delights", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90782, 90866, 90872, 90873, 90874, 90875 }, ["description"] = "Brothers and sisters. Here. Help. <Tul'amar connects her thumb and index finger on both hands to make a chain. Then, she breaks the link with a sharp gesture.> How? Show. <She then produces a glimmering relic and holds it over her gauntlet. She spends a portion of her arcane energy into it. Its newly activated magic forces the straps holding her glove in place loose.> Use.", ["objectivesText"] = "Use the Relic of Liberation to free 10 Master's Prospects and 3 Unwilling Summons. Progress: <Tul'amar holds still, even as you approach.>", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 244173 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 241620, ["x"] = 0.396, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 241620, ["x"] = 0.396, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 90872 }, ["questLines"] = { { ["id"] = 5933, ["name"] = "The Nethersent", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[90874] = { ["id"] = 90874, ["name"] = "Their Violent Ends", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90782, 90866, 90872, 90873, 90874, 90875 }, ["description"] = "Go home. How? <She offers a dramatic flourish with her fingertips, producing some arcane sparks. Then, she makes an X with her index fingers.> Of me? No. Of they. <Tul'amar gestures to a group of voidwalkers up ahead. She then draws her thumb across her neck.> Kill. And. <She reaches into a pouch on her hip and retrieves a cracked stone of domanaar make. It looks like a spell reagent of some kind.> As this. Need.", ["objectivesText"] = "Collect 8 Abductor's Marks from the voidwalkers of Masters' Perch. Progress: <Tul'amar holds still, even as you approach.>", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 244171 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 241620, ["x"] = 0.396, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 241620, ["x"] = 0.396, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 90872 }, ["questLines"] = { { ["id"] = 5933, ["name"] = "The Nethersent", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[90875] = { ["id"] = 90875, ["name"] = "Across Worlds", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90782, 90866, 90872, 90873, 90874, 90875 }, ["description"] = "Man of Void. Have key. Need. Key to home. <Tul'amar gestures down the way to the northwest. She grimaces back at her injured kin.> Go back, we. Wait. Hope. For you.", ["objectivesText"] = "Kill Snaerius and recover his Lodestar of the Great Dark . Progress: <Tul'amar smiles sadly at her people.>", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardItems"] = { 244435, 264293, 264294 }, ["rewardChoices"] = { 264293, 264294 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3389, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 241620, ["x"] = 0.396, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 241620, ["x"] = 0.396, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 90873, 90874 }, ["questLines"] = { { ["id"] = 5933, ["name"] = "The Nethersent", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[90876] = { ["id"] = 90876, ["name"] = "Reluctant Hand", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 90861, 90862, 90867, 90876, 92689 }, ["description"] = "Champion, I felt it was important to have you here for this moment so that neither I nor my wayward former peer get off topic with his many failings. I also want a witness in case he turns to evil. Would you be so kind as to unpack a few items so that I do not have to touch them?", ["objectivesText"] = "Assist in preparing the Umbral Atrium. Progress: I am not so filled with pride that I cannot admit to some... mild nostalgia for the banter I once enjoyed with my former peer. Magister Umbric was once quite the source of counterpoints and suggestions that went beyond expectations, and helped push our knowledge of magic further and further.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 }, { ["id"] = 3391, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 244701, ["x"] = 0.538667, ["y"] = 0.597333 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 247262, ["x"] = 0.538667, ["y"] = 0.597333 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.538667, ["y"] = 0.597333 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 92689 }, ["questLines"] = { { ["id"] = 5798, ["name"] = "Dawn of a New Well", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5798, ["questLineOrder"] = 5 } } },
[90879] = { ["id"] = 90879, ["name"] = "Brewmaster's Kitchen", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 90879 }, ["description"] = "Now that ye've gathered the materials, we can get to cookin'! We'll need plenty o' food for the whole crowd. We've got a short but sweet menu: Barley Soup, Pretzels , and of course a good ol' brew! Are ye ready to learn the ropes?", ["objectivesText"] = "Follow the steps to cook Brewfest food and a delicious Brew. Progress: Get cookin'!", ["rewardGold"] = 16330, ["rewardXP"] = 25, ["rewardItems"] = { 37829, 244050, 244051, 244052, 244064 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 242172, ["x"] = 0.56, ["y"] = 0.374 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 242172, ["x"] = 0.56, ["y"] = 0.374 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.374 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["sourceQuests"] = { 90870 }, ["db2LabelIDs"] = { 2751 }, ["db2QuestSortName"] = "Epic" },
[90880] = { ["id"] = 90880, ["name"] = "Serving with Style", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 90880 }, ["description"] = "Ye've done well in the kitchen, now it's time to learn how to serve! Brewfest isn't just about food--it's about makin' sure everyone has a good time. Ye'll be takin' orders, deliverin' dishes, and pourin' drinks with a smile. Get out there and show 'em how it's done. Brewfest won't run without good service!", ["objectivesText"] = "Take the customer's order and serve the food to them. Progress: Remember to serve with a smile!", ["rewardGold"] = 29200, ["rewardXP"] = 25, ["rewardItems"] = { 37829 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 242172, ["x"] = 0.56, ["y"] = 0.374 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 242172, ["x"] = 0.56, ["y"] = 0.374 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.374 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["sourceQuests"] = { 90879 }, ["db2LabelIDs"] = { 2751 }, ["db2QuestSortName"] = "Epic" },
