[90885] = { ["id"] = 90885, ["name"] = "My Beautiful Pumpkins", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16432, ["mapID"] = 2451, ["storyline"] = { 90882, 90885 }, ["description"] = "The kobolds and ogres appeared out of nowhere and kicked us out of the farm! I thought this was some Alliance plot until you all showed up. Maybe the Alliance is here to help us after all. You have to help me get my precious pumpkins back. I've spent the entire harvest cultivating them! You lead the way. I'll grab the pumpkins when you find them.", ["objectivesText"] = "Recover 4 Prized Pumpkins . Progress: Return to Thrall with Farmer Bruvk and his pumpkins", ["rewardGold"] = 34100, ["rewardXP"] = 175, ["rewardItems"] = { 153741, 153742, 153796, 153797, 153802, 153803, 153817, 153818, 153862, 153863, 153908, 153909, 153927, 153928, 153948, 153949, 153995, 153996, 154011, 154012, 154114, 154115, 154745, 154746, 194533, 194534 }, ["starts"] = { { ["mapID"] = 2451, ["npcID"] = 244729, ["x"] = 0.565, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2451, ["npcID"] = 244656, ["x"] = 0.564, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 2451, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2451 }, ["zone"] = { 16432 } }, ["questType"] = "standard", ["sourceQuests"] = { 90883 }, ["questLines"] = { { ["id"] = 5934, ["name"] = "Siege of Arathi Highlands", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 6004, ["name"] = "12.0 Testing - RPE - Delete Me - (STM)", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 315, ["title"] = "Arathi Highlands Siege", ["questLineID"] = 5934, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2927, ["db2PoiUiMapID"] = 2451 },
[90886] = { ["id"] = 90886, ["name"] = "Best Laid Plans of Kobolds and Ogres", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16432, ["mapID"] = 2451, ["storyline"] = { 90882, 90883, 90885, 90886, 90887, 90888, 90893, 90895, 90896, 90897, 90898, 90911 }, ["description"] = "The kobolds and ogres here seem to be carrying some sort of plan for their attack. I don't think they're particularly well written, so I'll need several of them to figure out what the ogres are planning.", ["objectivesText"] = "Collect 7 Poorly Written Plans . Progress: Did you recover the plans? They should be on most of the foes within the farm.", ["rewardGold"] = 31500, ["rewardXP"] = 175, ["rewardItems"] = { 153735, 153736, 153785, 153786, 153806, 153807, 153820, 153821, 153845, 153846, 153902, 153903, 153936, 153937, 153952, 153953, 154001, 154002, 154014, 154015, 154039, 154040, 154738, 154741, 194524, 194527, 243573 }, ["starts"] = { { ["mapID"] = 2451, ["npcID"] = 244656, ["x"] = 0.564, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2451, ["npcID"] = 244656, ["x"] = 0.564, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 2451, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2451 }, ["zone"] = { 16432 } }, ["questType"] = "standard", ["sourceQuests"] = { 90883 }, ["questLines"] = { { ["id"] = 5934, ["name"] = "Siege of Arathi Highlands", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 315, ["title"] = "Arathi Highlands Siege", ["questLineID"] = 5934, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2927, ["db2PoiUiMapID"] = 2451 },
[90887] = { ["id"] = 90887, ["name"] = "Farmer's Nemesis", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16432, ["mapID"] = 2451, ["storyline"] = { 90882, 90883, 90885, 90886, 90887, 90888, 90893, 90895, 90896, 90897, 90898, 90911 }, ["description"] = "Farmer Bruvk mentioned an ogre named Runk was leading the group here. These creatures won't leave this place as long as that ogre is commanding them.", ["objectivesText"] = "Slay Runk . Progress: We'll stay here and guard the remaining farmers while you handle Runk .", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 153718, 153733, 153734, 153793, 153799, 153805, 153829, 153837, 153865, 153866, 153867, 153875, 153900, 153901, 153935, 153945, 153951, 153998, 154023, 154026, 154037, 154119, 154739, 154748, 194526, 194535 }, ["starts"] = { { ["mapID"] = 2451, ["npcID"] = 244655, ["x"] = 0.564, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2451, ["npcID"] = 244655, ["x"] = 0.564, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 2451, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2451 }, ["zone"] = { 16432 } }, ["questType"] = "standard", ["sourceQuests"] = { 90883 }, ["questLines"] = { { ["id"] = 5934, ["name"] = "Siege of Arathi Highlands", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 315, ["title"] = "Arathi Highlands Siege", ["questLineID"] = 5934, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2927, ["db2PoiUiMapID"] = 2451 },
