[90893] = { ["id"] = 90893, ["name"] = "Repelling the Siege", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16432, ["mapID"] = 2451, ["storyline"] = { 90882, 90883, 90885, 90886, 90887, 90888, 90893, 90895, 90896, 90897, 90898, 90911 }, ["description"] = "We must do everything possible to stop this siege on Stromgarde. Make your way into the battle and weaken the ogre forces. Stromgarde should be able to rally if they can gain the upper hand.", ["objectivesText"] = "Repel the Ogre Siege outside of Stromgarde keep. Progress: Meet Thrall near Ar'gorok.", ["rewardGold"] = 262100, ["rewardXP"] = 1415, ["rewardItems"] = { 153745, 153746, 153790, 153791, 153811, 153812, 153826, 153827, 153857, 153858, 153912, 153913, 153942, 153943, 153957, 153958, 154007, 154008, 154020, 154021, 154049, 154050, 154740, 154742, 194523, 194525 }, ["starts"] = { { ["mapID"] = 2451, ["npcID"] = 244657, ["x"] = 0.194, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2451, ["npcID"] = 244666, ["x"] = 0.245, ["y"] = 0.371 } }, ["coords"] = { ["mapID"] = 2451, ["source"] = "quest_giver", ["x"] = 0.194, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2451 }, ["zone"] = { 16432 } }, ["questType"] = "standard", ["sourceQuests"] = { 90888 }, ["questLines"] = { { ["id"] = 5934, ["name"] = "Siege of Arathi Highlands", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 315, ["title"] = "Arathi Highlands Siege", ["questLineID"] = 5934, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2927, ["db2PoiUiMapID"] = 2451 },
[90895] = { ["id"] = 90895, ["name"] = "Catapult Bombardment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16432, ["mapID"] = 2451, ["storyline"] = { 90882, 90883, 90885, 90886, 90887, 90888, 90893, 90895, 90896, 90897, 90898, 90911 }, ["description"] = "These catapults are relentless. They must be destroyed. Place these rune stones at their base. It'll unleash arcane magic to turn the catapults to dust. I'll take out a few as well as I make my way across the battlefield.", ["objectivesText"] = "Apply Jaina's Runes to 4 Catapults. Progress: Meet Jaina near Ar'gorok.", ["rewardGold"] = 312800, ["rewardXP"] = 1415, ["rewardItems"] = { 153738, 153739, 153788, 153794, 153800, 153809, 153815, 153823, 153850, 153861, 153905, 153906, 153925, 153939, 153946, 153955, 153993, 154004, 154009, 154017, 154042, 154118, 154736, 154747, 194529, 194536 }, ["starts"] = { { ["mapID"] = 2451, ["npcID"] = 244658, ["x"] = 0.194667, ["y"] = 0.574667 } }, ["ends"] = { { ["mapID"] = 2451, ["npcID"] = 244667, ["x"] = 0.245, ["y"] = 0.371 } }, ["coords"] = { ["mapID"] = 2451, ["source"] = "quest_giver", ["x"] = 0.194667, ["y"] = 0.574667 }, ["mapCandidates"] = { ["npc"] = { 2451 }, ["zone"] = { 16432 } }, ["questType"] = "standard", ["sourceQuests"] = { 90888 }, ["questLines"] = { { ["id"] = 5934, ["name"] = "Siege of Arathi Highlands", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 315, ["title"] = "Arathi Highlands Siege", ["questLineID"] = 5934, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2927, ["db2PoiUiMapID"] = 2451 },
[90896] = { ["id"] = 90896, ["name"] = "One Last Ogre", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16432, ["mapID"] = 2451, ["storyline"] = { 90882, 90883, 90885, 90886, 90887, 90888, 90893, 90895, 90896, 90897, 90898, 90911 }, ["description"] = "The head of the siege is still cowering within the former Horde encampment. He managed to hide from Jaina's spell behind several of his cohorts. You can have the honors to confront of him. Jaina and I will stay here to ensure any remnants of the siege do not return. End this.", ["objectivesText"] = "Slay Ro'grok . Progress: Defeat Ro'grok and end this siege.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 153737, 153744, 153787, 153789, 153808, 153810, 153822, 153825, 153842, 153847, 153855, 153904, 153911, 153938, 153941, 153954, 153956, 154003, 154006, 154016, 154041, 154048, 154735, 154737, 194528, 194530 }, ["starts"] = { { ["mapID"] = 2451, ["npcID"] = 244666, ["x"] = 0.245, ["y"] = 0.371 } }, ["ends"] = { { ["mapID"] = 2451, ["npcID"] = 244666, ["x"] = 0.245, ["y"] = 0.371 } }, ["coords"] = { ["mapID"] = 2451, ["source"] = "quest_giver", ["x"] = 0.245, ["y"] = 0.371 }, ["mapCandidates"] = { ["npc"] = { 2451 }, ["zone"] = { 16432 } }, ["questType"] = "standard", ["sourceQuests"] = { 90888, 90893 }, ["questLines"] = { { ["id"] = 5934, ["name"] = "Siege of Arathi Highlands", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 315, ["title"] = "Arathi Highlands Siege", ["questLineID"] = 5934, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2927, ["db2PoiUiMapID"] = 2451 },
[90897] = { ["id"] = 90897, ["name"] = "Back to Stromgarde", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16432, ["mapID"] = 2451, ["storyline"] = { 90882, 90883, 90885, 90886, 90887, 90888, 90893, 90895, 90896, 90897, 90911 }, ["description"] = "I think we can count ourselves lucky there was no bigger threat here beyond a group of overambitious ogres. The same can't be said of other threats that are looming throughout Azeroth. Come. Let's return to Stromgarde to discuss matters further.", ["objectivesText"] = "Meet Jaina Proudmoore within Stromgarde Keep.", ["rewardGold"] = 29200, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2451, ["npcID"] = 244667, ["x"] = 0.245, ["y"] = 0.371 } }, ["ends"] = { { ["mapID"] = 2451, ["npcID"] = 244714, ["x"] = 0.195, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2451, ["source"] = "quest_giver", ["x"] = 0.245, ["y"] = 0.371 }, ["mapCandidates"] = { ["npc"] = { 2451 }, ["zone"] = { 16432 } }, ["questType"] = "standard", ["sourceQuests"] = { 90896 }, ["questLines"] = { { ["id"] = 5934, ["name"] = "Siege of Arathi Highlands", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 315, ["title"] = "Arathi Highlands Siege", ["questLineID"] = 5934, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2927, ["db2PoiUiMapID"] = 2451 },
[90898] = { ["id"] = 90898, ["name"] = "Back to Hammerfall", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16432, ["mapID"] = 2451, ["storyline"] = { 90882, 90883, 90885, 90886, 90887, 90888, 90893, 90895, 90896, 90898, 90911 }, ["description"] = "We're not always so lucky that a plan such as this is ended so swiftly and without a surprise portal or two. That being said, more dangers lurk throughout Azeroth. I know you can be of help to some. Let us return to Hammerfall to see how they're recovering.", ["objectivesText"] = "Return to Hammerfall.", ["rewardGold"] = 29200, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2451, ["npcID"] = 244666, ["x"] = 0.245, ["y"] = 0.371 } }, ["ends"] = { { ["mapID"] = 2451, ["npcID"] = 244715, ["x"] = 0.692, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 2451, ["source"] = "quest_giver", ["x"] = 0.245, ["y"] = 0.371 }, ["mapCandidates"] = { ["npc"] = { 2451 }, ["zone"] = { 16432 } }, ["questType"] = "standard", ["sourceQuests"] = { 90896 }, ["questLines"] = { { ["id"] = 5934, ["name"] = "Siege of Arathi Highlands", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 315, ["title"] = "Arathi Highlands Siege", ["questLineID"] = 5934, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2927, ["db2PoiUiMapID"] = 2451 },
[90907] = { ["id"] = 90907, ["name"] = "The First to Know", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 86621, 86622, 86623, 86624, 86626, 86632, 86633, 86634, 86635, 86636, 86781, 90493, 90494, 90509, 90907 }, ["description"] = "Notes speaking of fear, of uncertainty--of some mysterious truth? This is not good, $p. By all accounts, it sounds as if a cult has managed to infiltrate Tranquillien. If that journal entry was true, Kasiea was attempting to leave it. We must tell Antenorian. He'll want to secure the town and make sure his people are safe.", ["objectivesText"] = "Inform Lord Antenorian , governor of Tranquillien, of your investigation results. Progress: I hope our fair town is treating you well. If you have any concerns at all, bring them to me.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 244783 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 236087, ["x"] = 0.476, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 245004, ["x"] = 0.472, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86623, 86624 }, ["questLines"] = { { ["id"] = 5720, ["name"] = "Shadowfall", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5720, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 2395 },
[90910] = { ["id"] = 90910, ["name"] = "Overwhelming Darkness", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90910, 91339, 91340, 91341, 91343 }, ["description"] = "A dreadful presence calls from the den just to the southeast of here. Many of the dazed ren'dorei you see in camp were overwhelmed by its raw power on a scouting mission. Let us go together and see if whatever dwells within can be put to use. We cannot afford to spurn power in the fight against Xal'atath. Before that: we have little need of Kalgorg . The Voidstorm has made my voidwalker unruly and disobedient. Assist me in sacrificing it. We will need all of the Void energy we can muster.", ["objectivesText"] = "Sacrifice Kalgorg and then meet Lucia Nightbreaker in the Den of Predaxes. Progress: Disobedient little...", ["rewardGold"] = 85400, ["rewardXP"] = 3210, ["rewardItems"] = { 247713 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 239720, ["x"] = 0.46, ["y"] = 0.774667 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 239720, ["x"] = 0.46, ["y"] = 0.774667 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.774667 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86565 }, ["questLines"] = { { ["id"] = 5962, ["name"] = "The Nightbreaker", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[90911] = { ["id"] = 90911, ["name"] = "Your Next Adventure", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16432, ["mapID"] = 2451, ["storyline"] = { 90882, 90883, 90885, 90886, 90887, 90888, 90893, 90895, 90896, 90897, 90898, 90911 }, ["objectivesText"] = "Choose your next adventure.", ["rewardGold"] = 29200, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2451, ["npcID"] = 244714, ["x"] = 0.195, ["y"] = 0.615 }, { ["mapID"] = 2451, ["npcID"] = 244715, ["x"] = 0.692, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2451, ["npcID"] = 244714, ["x"] = 0.195, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2451, ["source"] = "quest_giver", ["x"] = 0.195, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2451 }, ["zone"] = { 16432 } }, ["questTurnInID"] = 244714, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5934, ["name"] = "Siege of Arathi Highlands", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 315, ["title"] = "Arathi Highlands Siege", ["questLineID"] = 5934, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2927, ["db2PoiUiMapID"] = 2451 },
[90914] = { ["id"] = 90914, ["name"] = "A Born Killer", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90914, 90915, 90916, 90917, 90918, 90919, 90920, 90922, 90923, 90924 }, ["description"] = "Ah, <name>. I have so enjoyed our time together. I hunger for more. I wish you knew more of me than my predilection for the taste of mortal suffering. One of my greatest joys is in crafting Void power into various objects and structures. It is my passion--my art. Here, I would like to show you. First, we will need power. You already know how to get it, of course: kill, kill, kill.", ["objectivesText"] = "Collect 15 Void Essence from monsters around Voidstorm . Progress: What an odd feeling. I feel almost... drawn to you. It must be your mesmerizing presence.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 248086 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235697, ["x"] = 0.512, ["y"] = 0.703 }, { ["mapID"] = 2405, ["npcID"] = 243907, ["x"] = 0.512, ["y"] = 0.684 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 243907, ["x"] = 0.512, ["y"] = 0.684 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.703 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86521 }, ["questLines"] = { { ["id"] = 5936, ["name"] = "Dance with the Devil", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405, ["db2QuestHubAreaPoiID"] = 8502 },
[90915] = { ["id"] = 90915, ["name"] = "Artifice of Aggression", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90914, 90915, 90916, 90917, 90918, 90919, 90920, 90922, 90923, 90924 }, ["description"] = "While we domanaar are best known for leading armies and savoring battles, there is more to us. Many, like myself, enjoy using our mastery over the Void to shape it into the buildings and objects you see around you. How do you think Xal'atath learned to create that great tower of hers? She's a quick study. Come now, and I will show you my work.", ["objectivesText"] = "Craft a blade with Decimus . Progress: How excellent to spend some time together. You mortals are so very interesting... you most of all.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 248281 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 243907, ["x"] = 0.512, ["y"] = 0.684 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 243907, ["x"] = 0.512, ["y"] = 0.684 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.684 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 90914 }, ["questLines"] = { { ["id"] = 5936, ["name"] = "Dance with the Devil", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[90916] = { ["id"] = 90916, ["name"] = "Seek to Destroy", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90914, 90915, 90916, 90917, 90918, 90919, 90920, 90922, 90923, 90924 }, ["description"] = "It's no easy thing, intertwining Light and Void together. The result is unstable, so we must continue to temper it. We shall quench this blade in the blood of our enemies. Some domanaar attempt to reclaim and re-power Nexus-Point Xenas. That won't be good for your people. I'll assume you want to stop it. What is it you mortals say? Two birds, one stone?", ["objectivesText"] = "Meet Decimus at Nexus-Point Xenas.", ["rewardGold"] = 32200, ["rewardXP"] = 1605, ["rewardItems"] = { 185954 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3389, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 243907, ["x"] = 0.512, ["y"] = 0.684 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 244929, ["x"] = 0.612, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.684 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 90915 }, ["questLines"] = { { ["id"] = 5936, ["name"] = "Dance with the Devil", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[90917] = { ["id"] = 90917, ["name"] = "Harvester of Savagery", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90914, 90915, 90916, 90917, 90918, 90919, 90920, 90922, 90923, 90924 }, ["description"] = "The blade hungers! The blood of our enemies will help stabilize and hone our nascent weapon. You'll need to drench the blade inside some corpses. So, you'll need to make corpses. < Decimus 's smile grows broader.> You're good at that, right?", ["objectivesText"] = "Use the Nascent Blade on corpses in Nexus-Point Xenas. Progress: The monsters native to this land are fierce and violent. Their bloodlust drew the Void here, so naturally... we feel quite at home here.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 248593 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 244929, ["x"] = 0.612, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 244929, ["x"] = 0.612, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 90916 }, ["questLines"] = { { ["id"] = 5936, ["name"] = "Dance with the Devil", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[90918] = { ["id"] = 90918, ["name"] = "The Unforgiven", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90914, 90915, 90916, 90917, 90918, 90919, 90920, 90922, 90923, 90924 }, ["description"] = "Since even before our little misadventure, Nexus-Point Xenas has always been the weakest link. The beasts here are stubborn and powerful, always pushing deeper and deeper in. Some domanaar seek to reclaim the Nexus-Point. They are known to me: weaklings, fighting for scraps. Let's ensure they fail.", ["objectivesText"] = "Slay Noxian , Averus , and Tenebre around Nexus-Point Xenas. Progress: Noxian , Averus , and Tenebre ... all lackeys of Xal'atath, just like the majority of my kin. I wonder how long each would wait before attempting their betrayal of her. Shame we'll never get to see their attempts.", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardItems"] = { 251144, 251146, 251148, 251155, 251160, 251173 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3389, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 244929, ["x"] = 0.612, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 244929, ["x"] = 0.612, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 90916 }, ["questLines"] = { { ["id"] = 5936, ["name"] = "Dance with the Devil", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[90919] = { ["id"] = 90919, ["name"] = "The Fiend That Failed", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90914, 90915, 90916, 90917, 90918, 90919, 90920, 90922, 90923, 90924 }, ["description"] = "The blade squirms. It is ready for its next transformation. There is only the leader, Vortensiun , left. He is known to me. Once, we formed a pact together to defeat a rival. When the time came for him to betray me, he did so clumsily. I let him live, so I could savor the taste of his regret. I wonder how well that pain has marinated by now? Let's find out. When the blade is tempered in his essence, it shall grow new power.", ["objectivesText"] = "Slay Vortensiun in Nexus-Point Xenas.", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3389, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 244929, ["x"] = 0.612, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 244948, ["x"] = 0.59, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 90917, 90918 }, ["questLines"] = { { ["id"] = 5936, ["name"] = "Dance with the Devil", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[90920] = { ["id"] = 90920, ["name"] = "Warmth for the Soul", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90914, 90915, 90916, 90917, 90918, 90919, 90920, 90922, 90923, 90924 }, ["description"] = "Enjoying the view? The blade is stronger now, but it is not yet complete. A weapon worthy of you deserves nothing less than perfection. But let us relax for a moment. I understand you mortals enjoy a... casual exchange of conversation to get to know each other better. I am familiar with the concept, but am curious to see it in action. Indulge me?", ["objectivesText"] = "Enjoy a pleasant conversation with Decimus .", ["rewardGold"] = 170800, ["rewardXP"] = 6425, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 244948, ["x"] = 0.59, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 244948, ["x"] = 0.59, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 90919 }, ["questLines"] = { { ["id"] = 5936, ["name"] = "Dance with the Devil", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[90922] = { ["id"] = 90922, ["name"] = "The Fallen Wake", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90914, 90915, 90916, 90917, 90918, 90919, 90920, 90922, 90923, 90924 }, ["description"] = "<The shade flickers. You can barely make out its whisper.> You... left me... to die... <Its arm reaches toward you, then dissipates. Somehow, the presence is a familiar one. You feel that you know this spirit. You see more flickers in the distance. What are these shades?>", ["objectivesText"] = "Dispel spirits in the Gnawing Reach. Progress: Such a strange and terrible place. Fear not--if you wish to converse more to settle your nerves... I am here for you.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 251891, ["mapID"] = 2405, ["x"] = 0.585477, ["y"] = 0.554767 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 252853, ["x"] = 0.472, ["y"] = 0.49 }, { ["npcID"] = 251891, ["mapID"] = 2405, ["x"] = 0.585477, ["y"] = 0.554767 } }, ["coords"] = { ["source"] = "quest_giver", ["mapID"] = 2405, ["x"] = 0.585477, ["y"] = 0.554767 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 90920 }, ["questLines"] = { { ["id"] = 5936, ["name"] = "Dance with the Devil", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[90923] = { ["id"] = 90923, ["name"] = "Shepherd of Fear", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90914, 90915, 90916, 90917, 90918, 90919, 90920, 90922, 90923, 90924 }, ["description"] = "Our journey continues... one final battlefield. There are vicious beasts aplenty here. Their Void shall fuel the blade even more. And the blade's newfound power shall draw their Void into itself by mere proximity! Though, this place is different. You may find things you don't expect. Keep an eye out.", ["objectivesText"] = "Slay monsters and gather Void Essence in the Gnawing Reach. Progress: Don't get distracted, now. This will all be worth it when you have a mighty weapon to hold.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 244948, ["x"] = 0.59, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 252853, ["x"] = 0.472, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 90920 }, ["questLines"] = { { ["id"] = 5936, ["name"] = "Dance with the Devil", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[90924] = { ["id"] = 90924, ["name"] = "The Wicked End", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90914, 90915, 90916, 90917, 90918, 90919, 90920, 90922, 90923, 90924 }, ["description"] = "The time has come. The final step. < Decimus pauses, savoring something.> Let us create the greatest weapon your kind has ever seen.", ["objectivesText"] = "Complete the forging of the blade. Progress: Your patience has been... appreciated.", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardItems"] = { 264425, 264426, 264427, 264428, 264429, 264430, 264431, 264432, 264433 }, ["rewardChoices"] = { 264425, 264426, 264427, 264428, 264429, 264430, 264431, 264432, 264433 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3389, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 252853, ["x"] = 0.472, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 243907, ["x"] = 0.512, ["y"] = 0.684 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 90922, 90923 }, ["questLines"] = { { ["id"] = 5936, ["name"] = "Dance with the Devil", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[90938] = { ["id"] = 90938, ["name"] = "A Skip Through the Void", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 90938 }, ["description"] = "Fleshling, do you know about Untethered Space? I am sure you know someone who has encountered it. Previously we assumed that only beings of energy such as those from K'aresh could Phase Dive. Since the Harbinger's return, she has created a means for solid creatures to become energy using Reshii Wraps . My name is Hashim , and I have some Reshii Wraps in my possession. We are in desperate need of adventurers powerful enough to brave the lucrative depths of Untethered Space.", ["objectivesText"] = "Meet Hashim at Overlook Zo'Shuul.", ["rewardGold"] = 30900, ["rewardItems"] = { 235499, 238037, 238039, 238040, 238041 }, ["rewardChoices"] = { 238037, 238039, 238040, 238041 }, ["starts"] = { { ["x"] = 0.503, ["y"] = 0.363, ["mapID"] = 2371, ["npcID"] = 241588 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 241588, ["x"] = 0.502, ["y"] = 0.364 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.364 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questGiverID"] = 241588, ["questType"] = "standard", ["sourceQuests"] = { 84957 } },
[90943] = { ["id"] = 90943, ["name"] = "Stormarion Assault", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["storyline"] = { 90943 }, ["rewardGold"] = 683200, ["rewardXP"] = 13690, ["rewardItems"] = { 251635, 254677, 268490 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[90957] = { ["id"] = 90957, ["name"] = "Initiation Day", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredRaces"] = { 91 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90957, 90958, 90959, 90960, 90961 }, ["description"] = "<name>, today is when you find your proper place among the haranir. Root Tender Dalnir will guide you. His path is one of tradition and humility, so don't expect excitement. By the end of the day, you will make your mark in the Den of Remembrance. The story you begin now will build on those that came before, like the roots themselves, growing the foundations of Harandar. Dalnir was clearing invasive drifters from the roots. Before you go to him, aid Dalnir by removing some of the pests yourself.", ["objectivesText"] = "Elder Hagar is asking you to kill 6 Invasive drifters from around the roots of Teldrassil, and then meet with Root Tender Dalnir .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 257527, 257528, 257529, 257530 }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 245090, ["x"] = 0.348, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 245102, ["x"] = 0.352, ["y"] = 0.234 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.348, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5996, ["name"] = "Rooted In Traditions", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90958] = { ["id"] = 90958, ["name"] = "Roots Above All", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredRaces"] = { 91 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90957, 90958, 90959, 90960, 90961 }, ["description"] = "Some say the great trees grow, and Harandar will remain even if we do not tend them. Our traditions say, it does not matter. We remain here to protect, tend and serve. We do this with dedication and humility. Keeping the environment around the roots clean and free of pests reflects upon this duty. Return to me once you are done. You will represent our ways well, <name>.", ["objectivesText"] = "Root Tender Dalnir wants you to pull weeds, remove mud skippers and invasive fungi from the area. Progress: Have you performed the tasks that I have asked for?", ["rewardGold"] = 335000, ["rewardXP"] = 1415, ["rewardItems"] = { 246112, 246126, 246129 }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 245102, ["x"] = 0.352, ["y"] = 0.234 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 245102, ["x"] = 0.352, ["y"] = 0.234 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.234 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90957 }, ["questLines"] = { { ["id"] = 5996, ["name"] = "Rooted In Traditions", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90959] = { ["id"] = 90959, ["name"] = "Traditional Duties", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredRaces"] = { 91 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90957, 90958, 90959, 90960, 90961 }, ["description"] = "Dalnir has a point about the ceremony, but we should not focus too narrowly. I still hold the values of our people, but sometimes we must look beyond. Do not worry. You should be focusing on the ceremony. I will search for the outsiders later. I am sure you could join me once the initiation ceremony is done.", ["objectivesText"] = "An inner voice is telling you to search for the outsider in Har'mara. Progress: Hello, <name>. Hagar offered that I will remain as a witness to your ceremony.", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 257558, 257559, 257560, 257561 }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 245879, ["x"] = 0.352, ["y"] = 0.234 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 245881, ["x"] = 0.34, ["y"] = 0.268 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.234 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90958 }, ["questLines"] = { { ["id"] = 5996, ["name"] = "Rooted In Traditions", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90960] = { ["id"] = 90960, ["name"] = "My Story, My Legacy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredRaces"] = { 91 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90957, 90958, 90959, 90960, 90961 }, ["description"] = "<name>, the final part of the ceremony is ahead of you, though you've put it at risk with your digressions. The first mural will show you a vision of your true self, the one that resonates from within you. The second mural will show you a vision of where you are needed. The third mural, tradition tells us, breaks the barrier between us and the Goddess herself. The ceremony will conclude with you painting your story in the Den.", ["objectivesText"] = "Elder Hagar asked you to commune with the three murals, and then paint your own story. Progress: Take your time, <name>. The ceremony is not about how fast you do it, but about what you learn from it.", ["rewardGold"] = 182760, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 245096, ["x"] = 0.34, ["y"] = 0.268 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 245097, ["x"] = 0.318, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.268 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90959 }, ["questLines"] = { { ["id"] = 5996, ["name"] = "Rooted In Traditions", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90961] = { ["id"] = 90961, ["name"] = "Stranger in a New Land", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredRaces"] = { 91 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90957, 90958, 90959, 90960, 90961 }, ["description"] = "<name>, I see you now for who you are. You are dedicated not just to our people, but to the world. The goddess has acknowledged you as well, and I can not recall such an event--not even Orweyna's ceremony was so eventful. This is where your story begins. It is time for you to take the first steps of your journey.", ["objectivesText"] = "With the conclusion of the ceremony, it is now time to start your journey.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 246740, 246795 }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 245097, ["x"] = 0.318, ["y"] = 0.274 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 133362, ["x"] = 0.530667, ["y"] = 0.150667 }, { ["mapID"] = 85, ["npcID"] = 133407, ["x"] = 0.395, ["y"] = 0.794 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.318, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 84, 85, 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90960 }, ["questLines"] = { { ["id"] = 5996, ["name"] = "Rooted In Traditions", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85 },
