[90963] = { ["id"] = 90963, ["name"] = "Caves of the Cleft", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90537, 90540, 90569, 90601, 90602, 90963 }, ["series"] = { 90601 }, ["description"] = "Good work freeing the captured rutaani. With the seeds you recovered, I can try to carry on Ru'gar's work. I did some scouting and gathering while you were keeping the fungarians distracted, and could use your help with another task. Meet me at the cave northeast of here.", ["objectivesText"] = "Meet Ney'leia near the northeastern cave in Fungal Cleft.", ["rewardGold"] = 34100, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 243053, ["x"] = 0.49, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 245166, ["x"] = 0.496, ["y"] = 0.232 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90540, 90569 }, ["questLines"] = { { ["id"] = 5935, ["name"] = "Late Bloomers", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[90965] = { ["id"] = 90965, ["name"] = "How to Train Your Protegee", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["storyline"] = { 90965 }, ["description"] = "Champion! Perhaps you can help me? I've spent months learning bits of each path--the bow of the Farstriders, the Light of the Blood Knights, the arcane teachings of the magisters... but no matter how hard I train, I still can't feel which one is truly right for me. If I could watch you face them--see their true strength in a real fight--I think perhaps then I'd finally understand where I belong. Could you help me?", ["objectivesText"] = "Spar with Trainers in Sunstrider Isle.", ["rewardGold"] = 234000, ["rewardXP"] = 11765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15968 } }, ["questType"] = "standard" },
[90968] = { ["id"] = 90968, ["name"] = "Titanic Rumblings", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15329, ["mapID"] = 2339, ["storyline"] = { 90968, 90969, 90970, 90971, 91009, 91026, 91030, 91031, 91033, 91035 }, ["description"] = "Rumors are abuzz of titan forces being sighted around Khaz Algar. Brann has asked Dagran Thaurissan II for assistance in looking into these rumors.", ["objectivesText"] = "Seek out Dagran Thaurissan II at the Delver's Headquarters in Dornogal.", ["rewardGold"] = 29200, ["rewardXP"] = 1190, ["rewardItems"] = { 242664, 245964, 245965, 245966 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["nextQuests"] = { 90969 }, ["questLines"] = { { ["id"] = 5755, ["name"] = "Overcharged Delves", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[90969] = { ["id"] = 90969, ["name"] = "Titan Consoles", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15329, ["mapID"] = 2339, ["storyline"] = { 90968, 90969, 90970, 90971, 91009, 91026, 91030, 91031, 91033, 91035 }, ["description"] = "Adventurer, the rumors are true. I've seen the titan forces and they are nae friendly. We must try tae discover why they are emergin' now and try and stop 'em from doin' too much damage. Confront and stop these renegade constructs. To help ye, I've procured some Titan Consoles. I was able to set them up in the affected areas. I can use them to communicate with ye in the field. I am thinkin' we can use them to counter these titan forces as well.", ["objectivesText"] = "Seek out one of Dagran's Titan Consoles in an Overcharged Delve.", ["rewardGold"] = 306800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questTurnInID"] = 245191, ["questType"] = "standard", ["sourceQuests"] = { 90968 }, ["questLines"] = { { ["id"] = 5755, ["name"] = "Overcharged Delves", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[90970] = { ["id"] = 90970, ["name"] = "Titan Disc-Count", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16427, ["mapID"] = 2215, ["storyline"] = { 90968, 90969, 90970, 90971, 91009, 91026, 91030, 91031, 91033, 91035 }, ["description"] = "We need tae secure more titan discs. Venture deeper into this area, seek out the Titan Constructs, and defeat them. Ye should find disc shards. This console can reassemble them and access their data. Make sure tae search for any treasure rooms as well. The constructs appear to be assistin' the local denizens. Some of those locals might've secured additional titan discs with their other treasures.", ["objectivesText"] = "Secure Titan Disc Shards and dispatch Titan Constructs within the delve. Progress: Adventurer? Is that you?", ["rewardXP"] = 9515, ["rewardItems"] = { 244465 }, ["starts"] = { { ["npcID"] = 235490 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16427 } }, ["questGiverID"] = 235490, ["questType"] = "standard", ["sourceQuests"] = { 90969 }, ["questLines"] = { { ["id"] = 5755, ["name"] = "Overcharged Delves", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[90971] = { ["id"] = 90971, ["name"] = "Overcharged Console", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15329, ["mapID"] = 2393, ["storyline"] = { 90968, 90969, 90970, 90971, 91009, 91026, 91030, 91031, 91033, 91035 }, ["description"] = "With the shards ye found, we can use the console tae restore the titan discs and use them to access powerful boons. Use the console's disc repair feature to create a titan disc, then use that disc to select a starting node in the overcharge console's interface.", ["objectivesText"] = "Restore a Titan Disc and then spend it to unlock one of the starting nodes in the Overcharged Console Tech Tree. Progress: Did it work?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 244466 }, ["starts"] = { { ["npcID"] = 235490 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15329 } }, ["questGiverID"] = 235490, ["questType"] = "standard", ["sourceQuests"] = { 90970 }, ["questLines"] = { { ["id"] = 5755, ["name"] = "Overcharged Delves", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[90972] = { ["id"] = 90972, ["name"] = "A Common Cause", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86786, 89323, 89324, 89325, 89326, 89327, 90972, 91044, 94933 }, ["description"] = "<name>! I heard you were here on K'aresh . Good. I need help. My apprentice Leona has been researching novel means of harnessing the power of the Void. She's approached a Demon Hunter named Adarus to see if the Illidari's methods could offer any insights. To be honest, I'm not sure I trust Adarus. He's not... studious. Unlike Leona. Leona was just going to observe him as he sought to master the Void. But she's disappeared. Please find her. Talk with Adarus--he knows something.", ["objectivesText"] = "Speak to Adarus. Progress: Have you spoken to Adarus yet, <name>? It's clear that the Illidari's apotheosis has stripped them of their manners.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 247882 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 248153, ["x"] = 0.608, ["y"] = 0.278 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 240842, ["x"] = 0.660667, ["y"] = 0.356667 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.278 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 84967 }, ["questLines"] = { { ["id"] = 5770, ["name"] = "In Search of Darkness", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[90993] = { ["id"] = 90993, ["name"] = "Take the Darkwell!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = true, ["expansion"] = 11, ["storyline"] = { 90993 }, ["series"] = { 90748, 88710 }, ["description"] = "We have our army but what lies behind these walls are the most powerful, most vile, and most empowered foes Xal'atath has in her arsenal. Gather your strongest allies,  and meet us within. It is time to end this and take back our well.", ["objectivesText"] = "March on Quel'Danas.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "raid" },
[90995] = { ["id"] = 90995, ["name"] = "The Future of The Fel Hammer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 90995 }, ["description"] = "Oh wait! Of course, right when I send you off I remember the most important thing! The you-of-this-timeline made a critical choice for the future of all demon hunters. The follower they chose to be their personal champion created two diverging timelines for the fate of the Illidari. You will need to choose which of these diverging timelines to explore. What rings true to you?", ["objectivesText"] = "Choose your personal champion. Progress: Have you made a choice?", ["rewardGold"] = 28300, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.721, ["y"] = 0.417, ["mapID"] = 627, ["npcID"] = 243948 } }, ["ends"] = { { ["x"] = 0.721, ["y"] = 0.417, ["mapID"] = 627, ["npcID"] = 243948 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.721, ["y"] = 0.417 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 243948, ["questTurnInID"] = 243948, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[91000] = { ["id"] = 91000, ["name"] = "A Humble Servant", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 130, ["mapID"] = 14, ["storyline"] = { 86837, 86838, 86839, 86840, 86841, 86842, 86843, 86844, 86845, 86846, 86902, 89193, 89338, 91000, 92136 }, ["description"] = "$p, residents of Hammerfall have been focused on daily life, defense, and survival over the past months. They have not had sufficient time, or frankly numbers, to address all the harms that were done. There is much we can do to help them get back on their feet. I know this is humble work, but it makes a very real difference to the orcs who live here.", ["objectivesText"] = "Aid the people of Hammerfall in their recovery. Progress: There is much to do, <name>.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 251816, 251817, 251818, 251819 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 245186, ["x"] = 0.69, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 245186, ["x"] = 0.69, ["y"] = 0.375 }, { ["mapID"] = 14, ["npcID"] = 247299, ["x"] = 0.685, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.69, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 14 }, ["zone"] = { 45 } }, ["questType"] = "standard", ["sourceQuests"] = { 86845 }, ["questLines"] = { { ["id"] = 5750, ["name"] = "The Path of Light", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5750, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2796, ["db2PoiUiMapID"] = 2372 },
[91001] = { ["id"] = 91001, ["name"] = "Clear de Way", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86683, 86684, 86685, 86686, 86687, 86692, 86693, 91001, 91062 }, ["description"] = "With dey magic and dey line broken, de Twilight's Blade is losin' ground. We must take advantage of dey turned backs. I will lead de charge through de ravine to de Conquerer's Sanctum beyond. Mor'duun is there, keepin' his coward-body safe from our spears and axes. He won't be safe much longer.", ["objectivesText"] = "Regroup with Zul'jarra , Zul'jan, and Lady Liadrin at the foot of Conquerer's Sanctum in Broken Throne. Progress: We must act--now!", ["rewardGold"] = 31200, ["rewardXP"] = 1520, ["rewardItems"] = { 26009, 26023, 26035, 81834, 81835, 81836, 81837, 81838, 112595, 112596, 112597, 112598, 131273 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3354, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 245270, ["x"] = 0.256, ["y"] = 0.776 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 240034, ["x"] = 0.225, ["y"] = 0.774 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.256, ["y"] = 0.776 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86685, 86686, 86687 }, ["questLines"] = { { ["id"] = 5724, ["name"] = "De Amani Never Die", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5724, ["questLineOrder"] = 7 } }, ["db2PoiUiMapID"] = 2437 },
[91009] = { ["id"] = 91009, ["name"] = "Durable Information Storage Container", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15329, ["mapID"] = 2339, ["storyline"] = { 90968, 90969, 90970, 90971, 91009, 91026, 91030, 91031, 91033, 91035 }, ["description"] = "Adventurer, can you hear me? I've discovered a smaller titan device, the Durable Information Storage Container, which can fit on yer belt. I've deduced they'll be able tae play smaller titan discs, granting ye boons ye can use anywhere. Each of these devices need a jump start. If ye kick up enough dust in these delves it should generate a spark that the device will detect and collect. It should be enough tae power it for yer lifetime.", ["objectivesText"] = "Complete a Delve to charge the device. Progress: The overcharging is key.", ["rewardXP"] = 11765, ["rewardItems"] = { 242664, 245964, 245965, 245966 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 90971 }, ["questLines"] = { { ["id"] = 5755, ["name"] = "Overcharged Delves", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[91026] = { ["id"] = 91026, ["name"] = "Gathering an Upgrade", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15329, ["mapID"] = 2339, ["storyline"] = { 90968, 90969, 90970, 90971, 91009, 91026, 91030, 91031, 91033, 91035 }, ["description"] = "Hello? Hello? You're back! Perfect! I was studying the titan console and gathering a bunch of new information from the overcharged areas including the faulty directives that were found. This might be the key to this unexpected behavior, but I'll need more time tae know for sure. Return to the delves and we can check the results of the faulty directives, I can use the information to create an upgrade for yer belt!", ["objectivesText"] = "Complete any Delve. Progress: Were ye successful?", ["rewardXP"] = 11765, ["rewardItems"] = { 244311 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 91009 }, ["questLines"] = { { ["id"] = 5755, ["name"] = "Overcharged Delves", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[91030] = { ["id"] = 91030, ["name"] = "New Titan Directives", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15329, ["mapID"] = 2339, ["storyline"] = { 90968, 90969, 90970, 90971, 91009, 91026, 91030, 91031, 91033, 91035 }, ["description"] = "My calculations need a lot more data. I've got another upgrade card nearly finished, but I'm not sure if it will integrate properly. But if ye go back into the delve spaces and defeat more of the enemies, I can see how they react. Based on their reactions, I can put the final touches on this upgrade for yer belt.", ["objectivesText"] = "Complete any Delve. Progress: I can't wait to see the data!", ["rewardXP"] = 11765, ["rewardItems"] = { 244311 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 91026 }, ["questLines"] = { { ["id"] = 5755, ["name"] = "Overcharged Delves", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[91031] = { ["id"] = 91031, ["name"] = "Pushing it to the Limit", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15329, ["mapID"] = 2339, ["storyline"] = { 90968, 90969, 90970, 90971, 91009, 91026, 91030, 91031, 91033, 91035 }, ["description"] = "I realized after ye left last time that I might have worried ye a wee bit with the whole exploding belt upgrade possibility. I'm sorry. I get a bit excited sometimes. I do think I can get even more power out o' the belt. At least a bit more. Safely of course! In yer data, I've seen that you've encountered many enemies as ye entered many delves. That's the key, return one more time for this last upgrade for yer belt.", ["objectivesText"] = "Complete any Delve. Progress: I cannae wait to see if I was correct!", ["rewardGold"] = 936000, ["rewardXP"] = 11765, ["rewardItems"] = { 244311 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 91030 }, ["questLines"] = { { ["id"] = 5755, ["name"] = "Overcharged Delves", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[91033] = { ["id"] = 91033, ["name"] = "Monitoring 'Construct'ing", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15329, ["mapID"] = 2339, ["storyline"] = { 90968, 90969, 90970, 90971, 91009, 91026, 91030, 91031, 91033, 91035 }, ["description"] = "Welcome back, adventurer. I have a simple request for ye. I need ye tae continue monitorin' these titan constructs. We have seen them moving around Azeroth in different locations, but I've not yet figured out their end goal or what instructions they might have. Perhaps if ye can gather more information, an insight will present itself.", ["objectivesText"] = "Complete an Overcharged Delve.", ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 91031 }, ["questLines"] = { { ["id"] = 5755, ["name"] = "Overcharged Delves", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[91035] = { ["id"] = 91035, ["name"] = "Construct De-Escalation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15329, ["mapID"] = 2339, ["storyline"] = { 90968, 90969, 90970, 90971, 91009, 91026, 91030, 91031, 91033, 91035 }, ["description"] = "Yer previous results showed a reduction in the overcharge present in the constructs. We must see if that was a one-off or if the reduction is escalatin'... Head back into these overcharged areas and test out the charge on the constructs, then report back.", ["objectivesText"] = "Defeat 5 constructs and complete an Overcharged Delve.", ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 245191, ["x"] = 0.48, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 91033 }, ["questLines"] = { { ["id"] = 5755, ["name"] = "Overcharged Delves", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[91038] = { ["id"] = 91038, ["name"] = "Hellhunters Wanted", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 91038 }, ["description"] = "<A scorch-marked missive has been nailed to this wall.> HELL COMES FOR YOU! Now that we have your attention, please be warned that shards of brimstone have entered this world. They are warm to the touch and should not, under any circumstances, be stabbed into your head, the head of anyone else, or any other vital organ of you or anyone near you. Please bring any shards you find IMMEDIATELY to us in Dornogal. And if you see any tiny little minions carrying a bag of treasures, KILL THEM ON SIGHT.", ["objectivesText"] = "Bring the missive to Baranar in Dornogal.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardCurrencies"] = { { ["id"] = 3309, ["amount"] = 13 } }, ["starts"] = { { ["x"] = 0.491, ["y"] = 0.271, ["mapID"] = 2339, ["objectID"] = 547529 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 245378, ["x"] = 0.53, ["y"] = 0.683 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.683 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard" },
[91039] = { ["id"] = 91039, ["name"] = "Faerin's Request", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 84638, 84639, 84640, 84641, 84643, 84645, 84649, 84650, 84651, 84652, 84656, 84657, 84658, 84659, 84704, 84705, 84706, 84707, 84708, 84709, 84710, 84711, 84712, 84713, 84714, 84715, 84716, 84717, 85451, 85529, 87299, 91039 }, ["description"] = "<name>, Geya'rah and Danath have arrived in Dornogal. They both seem upset about rising tensions in the Arathi Highlands. It sounds serious. Can you come to Dornogal? I believe your presence can help the situation. Faerin", ["objectivesText"] = "Speak to Faerin Lothar in Dornogal.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["nextQuests"] = { 84638 }, ["questLines"] = { { ["id"] = 5684, ["name"] = "Rise of the Red Dawn", ["orderIndex"] = 0, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 267, ["title"] = "Rise of the Red Dawn", ["questLineID"] = 5684, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
