[91044] = { ["id"] = 91044, ["name"] = "Hunger of the Void", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 86786, 89323, 89324, 89325, 89326, 89327, 90972, 91044, 94933 }, ["description"] = "I did all I could to prevent this outcome. If you hadn't pushed him through the portal the unrestrained void energy would've collapsed the cave around us. He was strong. In a way, I think that worked against him. Meet me back in Shan'dorah. I need to report to Umbric and let him know what happened here.", ["objectivesText"] = "Reconvene with Magister Umbric and Leona back in Shan'dorah. Progress: I could feel the void energies roiling from here, <class>. What exactly happened?", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 245729, 245730, 245731, 245732 }, ["rewardCurrencies"] = { { ["id"] = 3129, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 240842, ["x"] = 0.660667, ["y"] = 0.356667 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 248153, ["x"] = 0.608, ["y"] = 0.278 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.660667, ["y"] = 0.356667 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 89327 }, ["questLines"] = { { ["id"] = 5770, ["name"] = "In Search of Darkness", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[91052] = { ["id"] = 91052, ["name"] = "Worldsoul: Overcharged Delves", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Something has caused hostile titan constructs to activate and enter various caverns and spaces around Khaz Algar. Venture to these locations and investigate and eliminate the threat they pose.", ["objectivesText"] = "Complete an Overcharged War Within Delve at any difficulty.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[91062] = { ["id"] = 91062, ["name"] = "Broken Bridges", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86683, 86684, 86685, 86686, 86687, 86692, 86693, 91001, 91062 }, ["description"] = "I make one last request of you before you return with Liadrin to Silvermoon, hash'ura. Find Zul'jan. None have seen him since returnin' to Amani'Zar. On de way back here, I confronted him about takin' our soldiers to Broken Throne against my orders. People died dat shouldn't have. I asked him what he don't understand about dat. He didn't argue. He was blank. His body was there, but his mind? Sometimes he seeks peace in de sound of ocean waves. You might find him on de Skybridge.", ["objectivesText"] = "Seek out Zul'jan upon the Skybridge.", ["rewardGold"] = 34100, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3354, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 249653, ["x"] = 0.456, ["y"] = 0.655 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 241308, ["x"] = 0.506, ["y"] = 0.544 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.655 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86693 }, ["questLines"] = { { ["id"] = 5724, ["name"] = "De Amani Never Die", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5724, ["questLineOrder"] = 7 } }, ["db2PoiUiMapID"] = 2437, ["db2QuestHubAreaPoiID"] = 8504 },
[91063] = { ["id"] = 91063, ["name"] = "The Blooming Lattice", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91063, 91065, 91085, 91086, 91088, 91136 }, ["series"] = { 91065 }, ["description"] = "You're that stranger I've been hearing about, aren't you? I'm Su'meera , apprentice painter to Ja'kul. You heard of him? No? Maybe his work hasn't made it to your lands. That makes sense, I guess. Anyhow, I heard you like helping people out. Well, a few important things went missing when Ja'kul was attacked and killed. I want them back. Will you meet me near Blooming Lattice?", ["objectivesText"] = "Meet Su'meera near Blooming Lattice.", ["rewardGold"] = 31500, ["rewardXP"] = 1520, ["rewardItems"] = { 255826, 256424 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3370, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 245637, ["x"] = 0.654, ["y"] = 0.226 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 245639, ["x"] = 0.608, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.226 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86930 }, ["questLines"] = { { ["id"] = 5944, ["name"] = "Peril Among Petals", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91065] = { ["id"] = 91065, ["name"] = "Purloining Petals", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91063, 91065, 91085, 91086, 91088, 91136 }, ["series"] = { 91063 }, ["description"] = "A couple of days ago, a group of rutaani attacked and killed my mentor, Ja'kul. When they did, their stupid birds stole a few things from him. Those petals-for-brains will make off with anything shiny that isn't thorned down. Will you recover Ja'kul's things for me? I'm a painter, not a fighter. I wouldn't last very long in there on my own.", ["objectivesText"] = "Recover stolen objects from Blooming Terrace. Progress: Those birds would steal your head if it wasn't attached to your shoulders. Especially if you were wearing a shiny hat or helm. Right off your shoulders! <She pauses for a moment as if picturing this, then turns slightly green and shudders.>", ["rewardGold"] = 309800, ["rewardXP"] = 12170, ["rewardItems"] = { 245569, 245570, 245883, 245886 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 245639, ["x"] = 0.608, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 245639, ["x"] = 0.608, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 91063 }, ["questLines"] = { { ["id"] = 5944, ["name"] = "Peril Among Petals", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91066] = { ["id"] = 91066, ["name"] = "Brewmaster's Kitchen", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 91066 }, ["description"] = "Good, you've brought the supplies. Now, we begin the feast. We'll need plenty of food to keep up our strength. The menu's simple, but worthy: Barley Stew, Stone-baked Pretzels , and a strong brew to fuel the Horde! Are you prepared to learn?", ["objectivesText"] = "Follow the steps to cook Brewfest food and a delicious Brew. Progress: Start the fire and get to work!", ["rewardGold"] = 31200, ["rewardXP"] = 25, ["rewardItems"] = { 37829, 246040, 246042, 246047, 246049 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 245967, ["x"] = 0.408, ["y"] = 0.175 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 245967, ["x"] = 0.408, ["y"] = 0.175 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.175 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 91067 }, ["db2LabelIDs"] = { 2751 } },
[91067] = { ["id"] = 91067, ["name"] = "Gathering the Grub", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 91067 }, ["description"] = "Ah, you're here. Brewfest has begun-but we've got a problem. Can't have a proper feast without food, and some thieving hozen thought it'd be clever to snatch our grub. Here's what you'll do: track down those hozen and take back what's ours. You might find a few bags just lying around too-grab those. Once you've got the goods, toss them in the wagon behind me.", ["objectivesText"] = "Collect Bags of Brewfest Ingredients and deposit them at the wagon. Progress: The feast won't come together without those ingredients!", ["rewardGold"] = 29200, ["rewardXP"] = 25, ["rewardItems"] = { 37829, 62978, 62979, 62980, 62981, 64641, 246044 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 245967, ["x"] = 0.408, ["y"] = 0.175 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 245967, ["x"] = 0.408, ["y"] = 0.175 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.175 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 } },
[91068] = { ["id"] = 91068, ["name"] = "Serving with Style", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 91068 }, ["description"] = "You've proven your strength at cooking, now it's time to prove it on the floor! Brewfest isn't just about feastin-it's about bringing the revelry to every corner of the camp. You'll be taking orders, hauling plates, and pouring ale like a true warrior of celebration. Now get out there and show them what real service looks like! Brewfest don't run on empty mugs!", ["objectivesText"] = "Take the customer's order and serve the food to them. Progress: Remember to serve with a smile!", ["rewardGold"] = 29200, ["rewardXP"] = 25, ["rewardItems"] = { 37829 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 245967, ["x"] = 0.408, ["y"] = 0.175 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 245967, ["x"] = 0.408, ["y"] = 0.175 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.175 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 91066 }, ["db2LabelIDs"] = { 2751 } },
[91069] = { ["id"] = 91069, ["name"] = "Vengeance for Tolbani", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91069, 91070, 91071, 91556, 94867 }, ["description"] = "Me and Tolbani had loaded de skiff with medicine, steel, and food to bring upriver to de forward camp. It was meant to be a quiet run: no trouble, and no eyes on us. But in de shallows, de murlocs came swarmin' out of de reeds all foam and teeth. Dey hit us hard--too fast to fight back proper. We tipped and lost de cargo. I barely made it to shore. Tolbani didn't. I dragged his dart-riddled body here. De murlocs must pay for what dey have done.", ["objectivesText"] = "Kill 12 murlocs in Atal'Abasi. Progress: Bleed de mindless beasts. Make dem suffer for killin' Tolbani.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 245669, ["x"] = 0.53, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 245669, ["x"] = 0.53, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 94867 }, ["questLines"] = { { ["id"] = 5939, ["name"] = "Vengeance for Tolbani", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91070] = { ["id"] = 91070, ["name"] = "Reclaim the Goods", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91069, 91070, 91071, 91556, 94867 }, ["description"] = "While I was limping back from de river, I spotted a few of de murlocs dragging our food bags through de mud. They weren't working together either--kept snapping at each other, trying to snatch de best pieces for themselves. I saw one of them stash a whole satchel behind a fallen tree. Another buried something under a pile of rocks. Greedy little monsters think they can steal from us and get away with it.", ["objectivesText"] = "Find 6 stolen Food Provisions in Atal'Abasi. Progress: Yes, <class>?", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 929, 245588 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 245669, ["x"] = 0.53, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 245669, ["x"] = 0.53, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 94867 }, ["questLines"] = { { ["id"] = 5939, ["name"] = "Vengeance for Tolbani", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91071] = { ["id"] = 91071, ["name"] = "The Menace of Atal'Abasi", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91069, 91070, 91071, 91556, 94867 }, ["description"] = "Our boat didn't ground on its own. We were fightin' de murlocs, and then suddenly we were in de air. Dats when I saw him--one dat wasn't like de rest. Bigger. Stronger. When he attacked, de other murlocs scattered. He picked up our boat like it weighed nothin' and hurled it on de rocks. I've never seen a murloc do somethin' like that. We're gonna keep losin' people and supplies if dat muscle-bound murloc is watchin' de river.", ["objectivesText"] = "Find and slay Mrruk the Musclefin in Atal'Abasi. Progress: De river's dangerous. We must reclaim it.", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3354, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 245669, ["x"] = 0.53, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 245669, ["x"] = 0.53, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 94867 }, ["questLines"] = { { ["id"] = 5939, ["name"] = "Vengeance for Tolbani", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91084] = { ["id"] = 91084, ["name"] = "Looming Shadows", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2393, ["storyline"] = { 91084, 91087 }, ["description"] = "Though we've triumphed over Ruia and the Lightbloom for now, more remains to be done. The elders will want to convene regarding the Hara'ti 's new place in the world, now that we have stepped out from the shadows of our past. Our reticence and fear will not vanish overnight. But this is an important first step. We will be fine, <name>. Let Orweyna and I deal with the elders. When the time comes, the Hara'ti shall be at your side. For now, though, I'd imagine you have more pressing matters to attend to.", ["objectivesText"] = "Return to Regent Lord Lor'themar Theron in the Sanctum of Light in Silvermoon City.", ["rewardGold"] = 32200, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3370, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 255819, ["x"] = 0.365, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 86898 }, ["nextQuests"] = { 91967, 92061 }, ["questLines"] = { { ["id"] = 5940, ["name"] = "Return to the Scouting Map", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5979, ["name"] = "The Darkening Sky", ["orderIndex"] = 3, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5979, ["questLineOrder"] = 16 } }, ["db2PoiUiMapID"] = 2393 },
[91085] = { ["id"] = 91085, ["name"] = "Petal Bristles", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91063, 91065, 91085, 91086, 91088, 91136 }, ["description"] = "Ja'kul was out hunting petalwings when the rutaani came upon him and killed him. We use their feathers for some of our paintbrushes. They are especially useful in helping the young sprouts learn how to be more precise and delicate. While you're up there, will you bring me back some of their plumes?", ["objectivesText"] = "Collect 8 Petalwing Plumes . Progress: Have you gathered the petalwing plumes I asked for? They're essential for the lessons of the younger haranir.", ["rewardGold"] = 309800, ["rewardXP"] = 12170, ["rewardItems"] = { 245571 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 245639, ["x"] = 0.608, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 245639, ["x"] = 0.608, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 91063 }, ["questLines"] = { { ["id"] = 5944, ["name"] = "Peril Among Petals", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91086] = { ["id"] = 91086, ["name"] = "Nipping the Buds", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91063, 91065, 91085, 91086, 91088, 91136 }, ["description"] = "The rutaani of Blooming Lattice were behind the attack on Ja'kul. They're led by a Prime Bloomwarden who's even more vicious. I hate them and they're all terrible! How about you go prune the overgrowth and make the rest of us safer?", ["objectivesText"] = "Kill rutaani and the Prime Bloomwarden in Blooming Lattice.", ["rewardGold"] = 625600, ["rewardXP"] = 15215, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3370, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 245639, ["x"] = 0.608, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 245639, ["x"] = 0.608, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 91063 }, ["questLines"] = { { ["id"] = 5944, ["name"] = "Peril Among Petals", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91087] = { ["id"] = 91087, ["name"] = "Reports Returned", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91084, 91087 }, ["description"] = "I will go to Silvermoon but... I will return here to advise Zul'jarra. I feel I let my past and my prejudices get in the way of my judgement regarding the Amani. You could say that being a hash'ura is a befitting atonement but... I feel drawn to stay, perhaps to help Zul'jarra in guiding her people back to the loa. I will go to Silvermoon with you to bear the report--and Lor'themar's reaction. If we go now, we may return to... party. <A small smile cracks Liadrin's usually stoic face.>", ["objectivesText"] = "Report to Lor'themar Theron in Silvermoon City.", ["rewardGold"] = 34100, ["rewardXP"] = 1520, ["rewardItems"] = { 256928 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3354, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 241308, ["x"] = 0.506, ["y"] = 0.544 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = { 2393, 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91062 }, ["questLines"] = { { ["id"] = 5940, ["name"] = "Return to the Scouting Map", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5979, ["name"] = "The Darkening Sky", ["orderIndex"] = 2, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5979, ["questLineOrder"] = 16 } }, ["db2PoiUiMapID"] = 2393 },
[91088] = { ["id"] = 91088, ["name"] = "Behind the Falls", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91063, 91065, 91085, 91086, 91088, 91136 }, ["series"] = { 91136 }, ["description"] = "The scroll you brought back was left behind for me by my mentor, Ja'kul. I didn't even have a chance to read it before it was stolen away! Ja'kul left directions in the scroll to a cave that's behind a waterfall in Blooming Lattice. I'm not sure what we'll find there, but I would really appreciate if you came along while I check it out. Will you meet me there?", ["objectivesText"] = "Meet Su'meera in the cave behind the waterfall in Blooming Lattice.", ["rewardGold"] = 34100, ["rewardXP"] = 1520, ["rewardItems"] = { 255826, 256424 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3370, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 245639, ["x"] = 0.608, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 245986, ["x"] = 0.56, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 91065, 91085, 91086 }, ["questLines"] = { { ["id"] = 5944, ["name"] = "Peril Among Petals", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91089] = { ["id"] = 91089, ["name"] = "Defeating Ky'veza", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16539, ["mapID"] = 2339, ["storyline"] = { 91089, 91780, 91781, 91782 }, ["description"] = "So she's here to collect a bounty, eh? Did nae one tell her it's rude to try and kill a Champion of Azeroth? Or a Bronzebeard, for that matter?", ["objectivesText"] = "Increase your item level to challenge Ky'veza in her tier 8 delve on K'aresh.", ["rewardItems"] = { 212265, 212282, 219309, 219314, 219905, 222776, 244470 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 16539 } }, ["questType"] = "standard", ["sourceQuests"] = { 91782 }, ["questLines"] = { { ["id"] = 5973, ["name"] = "Delves - Season 3", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[91090] = { ["id"] = 91090, ["name"] = "Pesky Pests", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16536, ["mapID"] = 2395, ["storyline"] = { 91090, 91137, 91271, 91328 }, ["description"] = "Nearby creatures are suffering an infection of Light, and are being drawn to the Sunbath. Our guests find it disturbing. That is a problem, when one is trying to enjoy a tranquil escape from the world. I confess, having one run into your leg while you are swimming can be unnerving. Please, dissuade the invading sungrubs from joining us, and take to the sky to chase off those persistent butterflies.", ["objectivesText"] = "Kill 10 Sungrubs and fly to chase away 10 Persistent Butterflies . Progress: Are the insects giving you trouble?", ["rewardGold"] = 312800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 245748, ["x"] = 0.488, ["y"] = 0.766 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 245748, ["x"] = 0.488, ["y"] = 0.766 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.766 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91271 }, ["questLines"] = { { ["id"] = 5949, ["name"] = "Sunbath, Take Me Away", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91093] = { ["id"] = 91093, ["name"] = "More Than Just a Phase", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 91093 }, ["description"] = "Untethered Space represents an ongoing danger to our people on K'aresh. It is infested with banished souls, broken technology, and monsters of all kinds. Aid the K'aresh Trust and defeat our foes in Untethered Space. You may use the Phase Conduits to navigate between the remnants of K'aresh while phase diving.", ["objectivesText"] = "Complete activities while phase diving in Untethered Space on K'aresh. Progress: I dream of a day when we K'areshi can roam these lands freely and without fear.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235499, 255676 }, ["rewardCurrencies"] = { { ["id"] = 3129, ["amount"] = 300 }, { ["id"] = 3303, ["amount"] = 7 } }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 238255, ["x"] = 0.485, ["y"] = 0.5755 }, { ["mapID"] = 2371, ["npcID"] = 241624, ["x"] = 0.504, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 241624, ["x"] = 0.504, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.5755 }, ["mapCandidates"] = { ["npc"] = { 2371, 2472 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2472 },
[91095] = { ["id"] = 91095, ["name"] = "Prey: Magister Sunbreaker (Normal)", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["mapID"] = 2437, ["storyline"] = { 91095, 91096, 91097, 91098, 91099, 91100, 91101, 91102, 91103, 91104, 91105, 91106, 91107, 91108, 91109, 91110, 91111, 91112, 91113, 91114, 91115, 91116, 91117, 91118, 91119, 91120, 91121, 91122, 91123, 91124, 91210, 91211, 91212, 91213, 91214, 91215, 91216, 91217, 91218, 91219, 91220, 91221, 91222, 91223, 91224, 91225, 91226, 91227, 91228, 91229, 91230, 91231, 91232, 91233, 91234, 91235, 91236, 91237, 91238, 91239, 91240, 91241, 91242, 91243, 91244, 91245, 91246, 91247, 91248, 91249, 91250, 91251, 91252, 91253, 91254, 91255, 91256, 91257, 91258, 91259, 91260, 91261, 91262, 91263, 91264, 91265, 91266, 91267, 91268, 91269 }, ["description"] = "Once a noble Magister of Silvermoon, sworn to protect Quel'Thalas at any cost, he has broken away from the order and now seeks vengeance on his own terms. I see something of myself in him. Kill it for me.", ["objectivesText"] = "Hunt down Magister Sunbreaker and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", ["rewardXP"] = 17650, ["starts"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["ends"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["coords"] = { ["mapID"] = 2393, ["x"] = 0.568, ["y"] = 0.653 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 245824, ["questTurnInID"] = 245824, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5945, ["name"] = "Prey", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2AdventureMapPoiID"] = 206, ["db2DetailThemeID"] = 76, ["db2LabelIDs"] = { 6036 }, ["db2PoiUiMapID"] = 2437, ["db2WidgetSetID"] = 1896 },
