[91119] = { ["id"] = 91119, ["name"] = "Prey: Lost Theldrin (Normal)", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["mapID"] = 2437, ["storyline"] = { 91095, 91096, 91097, 91098, 91099, 91100, 91101, 91102, 91103, 91104, 91105, 91106, 91107, 91108, 91109, 91110, 91111, 91112, 91113, 91114, 91115, 91116, 91117, 91118, 91119, 91120, 91121, 91122, 91123, 91124, 91210, 91211, 91212, 91213, 91214, 91215, 91216, 91217, 91218, 91219, 91220, 91221, 91222, 91223, 91224, 91225, 91226, 91227, 91228, 91229, 91230, 91231, 91232, 91233, 91234, 91235, 91236, 91237, 91238, 91239, 91240, 91241, 91242, 91243, 91244, 91245, 91246, 91247, 91248, 91249, 91250, 91251, 91252, 91253, 91254, 91255, 91256, 91257, 91258, 91259, 91260, 91261, 91262, 91263, 91264, 91265, 91266, 91267, 91268, 91269 }, ["description"] = "Those of us who succumbed to our base desire for mana were slowly weeded out of civil society, if they survived at all. Theldrin is one such example, only it is a testament to his cunning and will to live that he has made it as long as he has. He accepts no aid, choosing instead to stalk careless students and idle Magisters. His sole obsession is the mana that others possess... See to it that he never harms another elf again.", ["objectivesText"] = "Hunt down Lost Theldrin and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", ["rewardXP"] = 17650, ["starts"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["ends"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["coords"] = { ["mapID"] = 2393, ["x"] = 0.568, ["y"] = 0.653 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 245824, ["questTurnInID"] = 245824, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5945, ["name"] = "Prey", ["orderIndex"] = 24, ["flags"] = 0 } }, ["db2AdventureMapPoiID"] = 233, ["db2DetailThemeID"] = 76, ["db2LabelIDs"] = { 6036 }, ["db2PoiUiMapID"] = 2437, ["db2WidgetSetID"] = 1896 },
[91120] = { ["id"] = 91120, ["name"] = "Prey: Neydra the Starving (Normal)", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["mapID"] = 2437, ["storyline"] = { 91095, 91096, 91097, 91098, 91099, 91100, 91101, 91102, 91103, 91104, 91105, 91106, 91107, 91108, 91109, 91110, 91111, 91112, 91113, 91114, 91115, 91116, 91117, 91118, 91119, 91120, 91121, 91122, 91123, 91124, 91210, 91211, 91212, 91213, 91214, 91215, 91216, 91217, 91218, 91219, 91220, 91221, 91222, 91223, 91224, 91225, 91226, 91227, 91228, 91229, 91230, 91231, 91232, 91233, 91234, 91235, 91236, 91237, 91238, 91239, 91240, 91241, 91242, 91243, 91244, 91245, 91246, 91247, 91248, 91249, 91250, 91251, 91252, 91253, 91254, 91255, 91256, 91257, 91258, 91259, 91260, 91261, 91262, 91263, 91264, 91265, 91266, 91267, 91268, 91269 }, ["description"] = "Poor Neydra... I knew her, in a previous life. She was full of vitality. Full of ambition. Unfortunately, she let that ambition get the best of her. She grew too enamored with the raw power of the arcane. She became resentful of all other things. Of all other people... And now she is a murderous creature who beheads rats and attacks innocents in a desperate attempt to garner enough arcane energy to slake her unquenchable thirst. It's funny, the paths life takes us...", ["objectivesText"] = "Hunt down Neydra the Starving and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", ["rewardXP"] = 17650, ["starts"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["ends"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["coords"] = { ["mapID"] = 2393, ["x"] = 0.568, ["y"] = 0.653 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 245824, ["questTurnInID"] = 245824, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5945, ["name"] = "Prey", ["orderIndex"] = 25, ["flags"] = 0 } }, ["db2AdventureMapPoiID"] = 234, ["db2DetailThemeID"] = 76, ["db2LabelIDs"] = { 6036 }, ["db2PoiUiMapID"] = 2437, ["db2WidgetSetID"] = 1896 },
[91121] = { ["id"] = 91121, ["name"] = "Prey: Thornspeaker Edgath (Normal)", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["mapID"] = 2437, ["storyline"] = { 91095, 91096, 91097, 91098, 91099, 91100, 91101, 91102, 91103, 91104, 91105, 91106, 91107, 91108, 91109, 91110, 91111, 91112, 91113, 91114, 91115, 91116, 91117, 91118, 91119, 91120, 91121, 91122, 91123, 91124, 91210, 91211, 91212, 91213, 91214, 91215, 91216, 91217, 91218, 91219, 91220, 91221, 91222, 91223, 91224, 91225, 91226, 91227, 91228, 91229, 91230, 91231, 91232, 91233, 91234, 91235, 91236, 91237, 91238, 91239, 91240, 91241, 91242, 91243, 91244, 91245, 91246, 91247, 91248, 91249, 91250, 91251, 91252, 91253, 91254, 91255, 91256, 91257, 91258, 91259, 91260, 91261, 91262, 91263, 91264, 91265, 91266, 91267, 91268, 91269 }, ["description"] = "This one presents a prickly problem indeed. Thornspeaker Edgath has made a name for himself by using his druidic powers not to preserve Azeroth, but to twist its strength both against his enemies and innocent bystanders alike. He has no regard for anything that is not a beast or growing in the ground. It is time we clip this thorn.", ["objectivesText"] = "Hunt down Thornspeaker Edgath and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", ["rewardXP"] = 17650, ["starts"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["ends"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["coords"] = { ["mapID"] = 2393, ["x"] = 0.568, ["y"] = 0.653 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 245824, ["questTurnInID"] = 245824, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5945, ["name"] = "Prey", ["orderIndex"] = 26, ["flags"] = 0 } }, ["db2AdventureMapPoiID"] = 235, ["db2DetailThemeID"] = 76, ["db2LabelIDs"] = { 6036 }, ["db2PoiUiMapID"] = 2437, ["db2WidgetSetID"] = 1896 },
[91122] = { ["id"] = 91122, ["name"] = "Prey: Thorn-Witch Liset (Normal)", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["mapID"] = 2437, ["storyline"] = { 91095, 91096, 91097, 91098, 91099, 91100, 91101, 91102, 91103, 91104, 91105, 91106, 91107, 91108, 91109, 91110, 91111, 91112, 91113, 91114, 91115, 91116, 91117, 91118, 91119, 91120, 91121, 91122, 91123, 91124, 91210, 91211, 91212, 91213, 91214, 91215, 91216, 91217, 91218, 91219, 91220, 91221, 91222, 91223, 91224, 91225, 91226, 91227, 91228, 91229, 91230, 91231, 91232, 91233, 91234, 91235, 91236, 91237, 91238, 91239, 91240, 91241, 91242, 91243, 91244, 91245, 91246, 91247, 91248, 91249, 91250, 91251, 91252, 91253, 91254, 91255, 91256, 91257, 91258, 91259, 91260, 91261, 91262, 91263, 91264, 91265, 91266, 91267, 91268, 91269 }, ["description"] = "Thorn-Witch Liset is a curse upon civilization and a blight upon the land itself. She twists the very trees and beasts, communing with the dark, evil things that live on the very edges of the natural realm. I despise the natural realm.", ["objectivesText"] = "Hunt down Thorn-Witch Liset and slay her. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", ["rewardXP"] = 17650, ["starts"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["ends"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["coords"] = { ["mapID"] = 2393, ["x"] = 0.568, ["y"] = 0.653 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 245824, ["questTurnInID"] = 245824, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5945, ["name"] = "Prey", ["orderIndex"] = 27, ["flags"] = 0 } }, ["db2AdventureMapPoiID"] = 236, ["db2DetailThemeID"] = 76, ["db2LabelIDs"] = { 6036 }, ["db2PoiUiMapID"] = 2437, ["db2WidgetSetID"] = 1896 },
[91123] = { ["id"] = 91123, ["name"] = "Prey: Grothoz, the Burning Shadow (Normal)", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["mapID"] = 2437, ["storyline"] = { 91095, 91096, 91097, 91098, 91099, 91100, 91101, 91102, 91103, 91104, 91105, 91106, 91107, 91108, 91109, 91110, 91111, 91112, 91113, 91114, 91115, 91116, 91117, 91118, 91119, 91120, 91121, 91122, 91123, 91124, 91210, 91211, 91212, 91213, 91214, 91215, 91216, 91217, 91218, 91219, 91220, 91221, 91222, 91223, 91224, 91225, 91226, 91227, 91228, 91229, 91230, 91231, 91232, 91233, 91234, 91235, 91236, 91237, 91238, 91239, 91240, 91241, 91242, 91243, 91244, 91245, 91246, 91247, 91248, 91249, 91250, 91251, 91252, 91253, 91254, 91255, 91256, 91257, 91258, 91259, 91260, 91261, 91262, 91263, 91264, 91265, 91266, 91267, 91268, 91269 }, ["description"] = "The Twilight's Blade are an embarrassing band of mediocre cultists and uninspired conspirators. Grothoz is the brains of a particularly stupid cabal that has been active in a nearby region. As his stupidity prevents him from using his whole brain, let us unlock his potential for him...", ["objectivesText"] = "Hunt down Grothoz, the Burning Shadow and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", ["rewardXP"] = 17650, ["starts"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["ends"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["coords"] = { ["mapID"] = 2393, ["x"] = 0.568, ["y"] = 0.653 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 245824, ["questTurnInID"] = 245824, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5945, ["name"] = "Prey", ["orderIndex"] = 28, ["flags"] = 0 } }, ["db2AdventureMapPoiID"] = 237, ["db2DetailThemeID"] = 76, ["db2LabelIDs"] = { 6036 }, ["db2PoiUiMapID"] = 2437, ["db2WidgetSetID"] = 1896 },
[91124] = { ["id"] = 91124, ["name"] = "Prey: Dengzag, the Darkened Blaze (Normal)", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["mapID"] = 2437, ["storyline"] = { 91095, 91096, 91097, 91098, 91099, 91100, 91101, 91102, 91103, 91104, 91105, 91106, 91107, 91108, 91109, 91110, 91111, 91112, 91113, 91114, 91115, 91116, 91117, 91118, 91119, 91120, 91121, 91122, 91123, 91124, 91210, 91211, 91212, 91213, 91214, 91215, 91216, 91217, 91218, 91219, 91220, 91221, 91222, 91223, 91224, 91225, 91226, 91227, 91228, 91229, 91230, 91231, 91232, 91233, 91234, 91235, 91236, 91237, 91238, 91239, 91240, 91241, 91242, 91243, 91244, 91245, 91246, 91247, 91248, 91249, 91250, 91251, 91252, 91253, 91254, 91255, 91256, 91257, 91258, 91259, 91260, 91261, 91262, 91263, 91264, 91265, 91266, 91267, 91268, 91269 }, ["description"] = "Do you know why the Twilight's Blade call Dengzag the \"Darkened Blaze?\" It is because they are stupid, small-minded, and utterly bereft of imagination. What a silly name indeed. I, however, am not small-minded. I have quite the prodigious mind, and it is currently intent on putting an end to Dengzag and whatever his tiny brain is up to. Get to it.", ["objectivesText"] = "Hunt down Dengzag, the Darkened Blaze and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", ["rewardXP"] = 17650, ["starts"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["ends"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["coords"] = { ["mapID"] = 2393, ["x"] = 0.568, ["y"] = 0.653 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 245824, ["questTurnInID"] = 245824, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5945, ["name"] = "Prey", ["orderIndex"] = 29, ["flags"] = 0 } }, ["db2AdventureMapPoiID"] = 238, ["db2DetailThemeID"] = 76, ["db2LabelIDs"] = { 6036 }, ["db2PoiUiMapID"] = 2437, ["db2WidgetSetID"] = 1896 },
[91136] = { ["id"] = 91136, ["name"] = "Memories in Stone", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91063, 91065, 91085, 91086, 91088, 91136 }, ["series"] = { 91088 }, ["description"] = "Ja'kul was killed before he could finish my training, but I would recognize his work anywhere! He must have painted this vision stone for me! The rutaani will catch on pretty soon that we're up here, and I won't be able to defend myself. Will you keep watch while I journey into the memory he left me?", ["objectivesText"] = "Defend Su'meera while she vision walks.", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 260434, 260435, 260436, 260437 }, ["rewardChoices"] = { 260434, 260435, 260436, 260437 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3370, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 245986, ["x"] = 0.56, ["y"] = 0.248 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 245728, ["x"] = 0.556, ["y"] = 0.265 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 91088 }, ["questLines"] = { { ["id"] = 5944, ["name"] = "Peril Among Petals", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91137] = { ["id"] = 91137, ["name"] = "Lost in Light", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16536, ["mapID"] = 2395, ["storyline"] = { 91090, 91137, 91271, 91328 }, ["description"] = "It seems some of our more adventurous guests have not returned from their hike. Val said he saw a rutaani skulking about earlier, but I was certain he was just trying to add some drama to our day. The Lightbloom infiltrated the Sanctum to the north and has been spilling residual issues our way. Our guests are here to escape the troubles of the world... This all could become a bit too real for them. If you'll take care of that situation, I'll make sure Val keeps the guests distracted.", ["objectivesText"] = "Kill Liya Waterbloom and send the hikers home. Progress: Did they make it back?", ["rewardGold"] = 683200, ["rewardXP"] = 14705, ["rewardItems"] = { 263198 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3365, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 245748, ["x"] = 0.488, ["y"] = 0.766 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 245748, ["x"] = 0.488, ["y"] = 0.766 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.766 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91090, 91328 }, ["questLines"] = { { ["id"] = 5949, ["name"] = "Sunbath, Take Me Away", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91138] = { ["id"] = 91138, ["name"] = "I am the Creator and Destroyer", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 91138, 91140 }, ["description"] = "Such a small thing, really. And devoid of any of the power T'uure once nurtured. But a relic of inestimable value nonetheless. Did you know, <class>, that to T'uure, the dark and the light were inseparable aspects of a greater truth? What creates, has the power to destroy in equal measure. Demonstrate this lesson and you will reach a new understanding of yourself, and of the great Naaru whose sacrifice was able to halt the annihilation of an entire planet.", ["objectivesText"] = "Demonstrate your mastery over life and death.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 245743, 250082 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 245915, ["x"] = 0.404, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 245915, ["x"] = 0.404, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 91140 }, ["questLines"] = { { ["id"] = 5942, ["name"] = "The Legacy of T'uure", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2472 },
[91140] = { ["id"] = 91140, ["name"] = "A Piece of the Past", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 91138, 91140 }, ["description"] = "<This crystalline fragment has lost any luster it once had. Now finally extricated from Dimensius's dread form and in the hands of the devout, a brief glimmer revives in its depths. Perhaps someone in Tazavesh will know more.>", ["objectivesText"] = "Show the fragment to Om'en in Tazavesh. Progress: What is this? Ah, I see now. You were right to come to me.", ["rewardGold"] = 232300, ["rewardXP"] = 8825, ["rewardItems"] = { 59693, 59694, 59695, 59696, 59697, 59698, 245743 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 245915, ["x"] = 0.404, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5942, ["name"] = "The Legacy of T'uure", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2472, ["startItems"] = { 245743 } },
[91142] = { ["id"] = 91142, ["name"] = "Tabard for the Trusted", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15781, ["mapID"] = 2472, ["storyline"] = { 91142 }, ["rewardItems"] = { 245968 }, ["starts"] = { { ["npcID"] = 235252, ["x"] = 0.406, ["y"] = 0.292, ["mapID"] = 2472 } }, ["ends"] = { { ["npcID"] = 235252, ["x"] = 0.406, ["y"] = 0.292, ["mapID"] = 2472 } }, ["coords"] = { ["x"] = 0.406, ["y"] = 0.292, ["source"] = "quest_giver", ["mapID"] = 2472 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard" },
[91145] = { ["id"] = 91145, ["name"] = "The Conquered Heroes", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91145, 91146, 91147, 91148, 91149, 92641 }, ["description"] = "A domanaar was harrying our back lines. It was... different than the other void beasts--like it was playing rather than fighting. My partner, Callum, led a squad to hunt it down. They never came back. Callum's an Arathi through and through. He wouldn't fall here--I know it. Commander Lightblood refused to send a search party. He said there's a difference between personal and important. Well, the Vanguard can have their war, but I'm going after Cal. I know the route he took, but I can't search alone.", ["objectivesText"] = "Find Callum Ashvow 's squad.", ["rewardGold"] = 170800, ["rewardXP"] = 6425, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 245878, ["x"] = 0.486, ["y"] = 0.602667 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 246035, ["x"] = 0.538, ["y"] = 0.84 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.486, ["y"] = 0.602667 }, ["mapCandidates"] = { ["npc"] = { 2405, 2444 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86522 }, ["questLines"] = { { ["id"] = 5943, ["name"] = "Shadow Puppets", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405, ["db2QuestHubAreaPoiID"] = 8502 },
[91146] = { ["id"] = 91146, ["name"] = "Flickering Light", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 91145, 91146, 91147, 91148, 91149, 92641 }, ["description"] = "I feel traces of Light here--dim, scattered across the plain, but unmistakable. It's Callum. I know his Light like I know my own. That domanaar is a monster: using others like toys, smashing them together until they break. We'll find them, $p, and then I will turn that void beast to ash. <Anais grips her spear.> One thing at a time. Find the Light, and we find Callum.", ["objectivesText"] = "Find traces of Callum's Light.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 255158, 255159, 255160 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 246035, ["x"] = 0.538, ["y"] = 0.84 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 246035, ["x"] = 0.538, ["y"] = 0.84 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.84 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questTurnInID"] = 246035, ["questType"] = "standard", ["sourceQuests"] = { 91145 }, ["questLines"] = { { ["id"] = 5943, ["name"] = "Shadow Puppets", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[91147] = { ["id"] = 91147, ["name"] = "Cut Her Strings", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 91145, 91146, 91147, 91148, 91149, 92641 }, ["description"] = "Revik, Riandron, Danna... that domanaar made them kill each other. The creatures here are bound with the same shadowgrafts: the same twisted magic. If this is how Imperia controls her victims, we have to find a way to remove it. Restrain the beasts and I'll attempt to break their bonds. If it's forged by the Void, the Light must be able to overcome it.", ["objectivesText"] = "Subdue creatures while Anais removes their Shadowgrafts.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 246035, ["x"] = 0.538, ["y"] = 0.84 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 246035, ["x"] = 0.538, ["y"] = 0.84 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.84 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questTurnInID"] = 246035, ["questType"] = "standard", ["sourceQuests"] = { 91145 }, ["questLines"] = { { ["id"] = 5943, ["name"] = "Shadow Puppets", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[91148] = { ["id"] = 91148, ["name"] = "Strung Along", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 91145, 91146, 91147, 91148, 91149, 92641 }, ["description"] = "When the Light called, it called both of us. Why? So Callum could die on some void-scarred rock? I can't think here. All I can picture is Callum bleeding out. Come, we'll return to camp. With his belongings, I should be able to find him. Then... I don't know. If we can't break the shadowgrafts, we'll subdue him and drag him back to Silvermoon if we must. I'm not losing him.", ["objectivesText"] = "Help Knight Anais find and subdue Callum Ashvow .", ["rewardGold"] = 34100, ["rewardXP"] = 1605, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3389, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 252807, ["mapID"] = 2444, ["x"] = 0.539756, ["y"] = 0.840346 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 253523, ["x"] = 0.44, ["y"] = 0.87 }, { ["npcID"] = 252807, ["mapID"] = 2444, ["x"] = 0.539756, ["y"] = 0.840346 } }, ["coords"] = { ["source"] = "quest_giver", ["mapID"] = 2444, ["x"] = 0.539756, ["y"] = 0.840346 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 91146, 91147 }, ["questLines"] = { { ["id"] = 5943, ["name"] = "Shadow Puppets", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[91149] = { ["id"] = 91149, ["name"] = "Bury Me Not", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 91145, 91146, 91147, 91148, 91149, 92641 }, ["description"] = "I knew we'd never grow old together, but I thought we'd have more time. <Anais coughs, blood pooling beneath her. Flecks of the Void shimmer in the spreading crimson.> Don't worry. I'm not afraid. I promised myself I wouldn't go home without him... wouldn't spend a night in an empty bed. I'm just keeping that promise. Don't let her have him. Take his tinder box. You'll know what to do.", ["objectivesText"] = "Take Callum's Tinder Box and defeat Imperia. Progress: My parents always said falling in love with a human would end in heartbreak. <She doesn't lift her head.> There's never enough time, is there?", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardItems"] = { 256135, 264289, 264290, 264291, 264292 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3389, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 253523, ["x"] = 0.44, ["y"] = 0.87 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 253577, ["x"] = 0.44, ["y"] = 0.87 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.87 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 91148 }, ["questLines"] = { { ["id"] = 5943, ["name"] = "Shadow Puppets", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[91173] = { ["id"] = 91173, ["name"] = "The Flame Burns Eternal", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 91173 }, ["description"] = "These Sureki sure are a persistent bunch! We need to match their persistence with our blades. Can we count on your continued support in the battles ahead?", ["objectivesText"] = "Complete the Nightfall scenario. Progress: Ready yourself soldier, the battle is still to come.", ["rewardItems"] = { 239004 }, ["rewardCurrencies"] = { { ["id"] = 3283, ["amount"] = 100 }, { ["id"] = 3283, ["amount"] = 400 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 234774, ["x"] = 0.282, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard" },
[91197] = { ["id"] = 91197, ["name"] = "Collecting Remains", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 91197 }, ["objectivesText"] = "Collect 50 Void-Tainted Remains . Progress: The domanaar need void-tainted remains to fuel their war effort. Scavenge the area or slay fellow adventurers across Slayer's Rise to obtain this resource.", ["rewardItems"] = { 245937 }, ["rewardCurrencies"] = { { ["id"] = 1792, ["amount"] = 50 }, { ["id"] = 2123, ["amount"] = 50 }, { ["id"] = 3410, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 245976, ["x"] = 0.388, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 245976, ["x"] = 0.388, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 86549 } },
[91206] = { ["id"] = 91206, ["name"] = "Loa Disturbance", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 87254, 87256, 87267, 87268, 87317, 91206, 92531 }, ["description"] = "Now dat we are tryin' to contact all de loa, my mind turns to Kulzi, de loa of medicine--and the madness that surrounds his shrine. His loa speaker, Sij'ta, was a good friend. He healed many war parties of their injuries. But somethin' happened at Kulzi's shrine, and it is full of angry spirits. Dey attack anybody dat tries to get through to dem, and de loa is silent. Perhaps you can finally reach out to de loa and find his speaker!", ["objectivesText"] = "Find Loa Speaker Sij'ta at the Shrine of Kulzi.", ["rewardGold"] = 33800, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3354, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 254665, ["x"] = 0.432, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 237953, ["x"] = 0.404, ["y"] = 0.494 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91062 }, ["questLines"] = { { ["id"] = 5778, ["name"] = "Healing the Spirit", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
