[91250] = { ["id"] = 91250, ["name"] = "Prey: Lost Theldrin (Hard)", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["mapID"] = 2437, ["storyline"] = { 91095, 91096, 91097, 91098, 91099, 91100, 91101, 91102, 91103, 91104, 91105, 91106, 91107, 91108, 91109, 91110, 91111, 91112, 91113, 91114, 91115, 91116, 91117, 91118, 91119, 91120, 91121, 91122, 91123, 91124, 91210, 91211, 91212, 91213, 91214, 91215, 91216, 91217, 91218, 91219, 91220, 91221, 91222, 91223, 91224, 91225, 91226, 91227, 91228, 91229, 91230, 91231, 91232, 91233, 91234, 91235, 91236, 91237, 91238, 91239, 91240, 91241, 91242, 91243, 91244, 91245, 91246, 91247, 91248, 91249, 91250, 91251, 91252, 91253, 91254, 91255, 91256, 91257, 91258, 91259, 91260, 91261, 91262, 91263, 91264, 91265, 91266, 91267, 91268, 91269 }, ["description"] = "Those of us who succumbed to our base desire for mana were slowly weeded out of civil society, if they survived at all. Theldrin is one such example, only it is a testament to his cunning and will to live that he has made it as long as he has. He accepts no aid, choosing instead to stalk careless students and idle Magisters. His sole obsession is the mana that others possess... See to it that he never harms another elf again.", ["objectivesText"] = "Hunt down Lost Theldrin and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", ["rewardXP"] = 20540, ["starts"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["ends"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["coords"] = { ["mapID"] = 2393, ["x"] = 0.568, ["y"] = 0.653 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 245824, ["questTurnInID"] = 245824, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5945, ["name"] = "Prey", ["orderIndex"] = 70, ["flags"] = 0 } }, [