[91269] = { ["id"] = 91269, ["name"] = "Prey: Dengzag, the Darkened Blaze (Nightmare)", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["mapID"] = 2444, ["storyline"] = { 91095, 91096, 91097, 91098, 91099, 91100, 91101, 91102, 91103, 91104, 91105, 91106, 91107, 91108, 91109, 91110, 91111, 91112, 91113, 91114, 91115, 91116, 91117, 91118, 91119, 91120, 91121, 91122, 91123, 91124, 91210, 91211, 91212, 91213, 91214, 91215, 91216, 91217, 91218, 91219, 91220, 91221, 91222, 91223, 91224, 91225, 91226, 91227, 91228, 91229, 91230, 91231, 91232, 91233, 91234, 91235, 91236, 91237, 91238, 91239, 91240, 91241, 91242, 91243, 91244, 91245, 91246, 91247, 91248, 91249, 91250, 91251, 91252, 91253, 91254, 91255, 91256, 91257, 91258, 91259, 91260, 91261, 91262, 91263, 91264, 91265, 91266, 91267, 91268, 91269 }, ["description"] = "Do you know why the Twilight's Blade call Dengzag the \"Darkened Blaze?\" It is because they are stupid, small-minded, and utterly bereft of imagination. What a silly name indeed. I, however, am not small-minded. I have quite the prodigious mind, and it is currently intent on putting an end to Dengzag and whatever his tiny brain is up to. Get to it.", ["objectivesText"] = "Hunt down Dengzag, the Darkened Blaze and slay him. Hunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", ["rewardXP"] = 20540, ["starts"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["ends"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["coords"] = { ["mapID"] = 2393, ["x"] = 0.568, ["y"] = 0.653 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 245824, ["questTurnInID"] = 245824, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5945, ["name"] = "Prey", ["orderIndex"] = 86, ["flags"] = 0 } }, ["db2AdventureMapPoiID"] = 559, ["db2DetailThemeID"] = 76, ["db2LabelIDs"] = { 6036, 6348 }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444, ["db2WidgetSetID"] = 1851 },
[91270] = { ["id"] = 91270, ["name"] = "The Most Important Thing", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90615, 90616, 90617, 90619, 90620, 90621, 90622, 91270, 91450, 92616, 92617, 92618 }, ["description"] = "We will be strong for the Pit! But Boletus right. Another thing needed. Must have great name. Best teams all have good name. Fungus Force. Spore Storm. Cap Clash. And champions, Glow Guard! All good names. We need amazing name. Best name. So will be best team. You help choose?", ["objectivesText"] = "Speak to each of your teammates to choose a name. Progress: Find best name?", ["rewardGold"] = 170800, ["rewardXP"] = 6085, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 251715, ["x"] = 0.718, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 251715, ["x"] = 0.718, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 91450 }, ["questLines"] = { { ["id"] = 5910, ["name"] = "The Grudge Pit", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91271] = { ["id"] = 91271, ["name"] = "A Fish!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16536, ["mapID"] = 2395, ["storyline"] = { 91090, 91137, 91271, 91328 }, ["description"] = "There is a deliciously delectable dish that I am dying to share with my guests. We start with just the right fish, then chop it up, drop it in a blend of citrus and our special savory seasonings, and let it bask in the glorious flavors. In the shake of a tail feather, it becomes a magical delight for the senses! We are the talk of the town, you know. Could you please procure for us the perfect fish?", ["objectivesText"] = "Catch the best fish for the dish. Progress: I have a great feeling about this one!", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 13546, 19969, 19971, 19978, 59653, 59654, 59655, 62972, 62973, 62974, 64640, 67414, 74866, 81402, 87399, 108439, 109578, 130904, 133755, 142054, 144075, 167649, 173032, 199894, 199896, 224752, 225770, 225771, 228362, 228363, 228364, 228365, 228366, 228367, 228370, 228371, 228372, 228373, 246379, 246380, 246381, 246382 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 245745, ["x"] = 0.488, ["y"] = 0.766 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 245745, ["x"] = 0.488, ["y"] = 0.766 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.766 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86745 }, ["questLines"] = { { ["id"] = 5949, ["name"] = "Sunbath, Take Me Away", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91274] = { ["id"] = 91274, ["name"] = "Severing the Void", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16182, ["mapID"] = 2565, ["storyline"] = { 86769, 86770, 86780, 86805, 86806, 86807, 86811, 86834, 86848, 86849, 86850, 86852, 88719, 89012, 89271, 91274, 91281 }, ["description"] = "The High Exarch has formed an impressive defensive line. It will hold the Devouring Host's current numbers. But I can see void pylons behind the lines. Those will call forth more Devouring Host and overwhelm the Vanguard of Light. Their power is too dangerous for us to destroy directly, but if we can re-activate the sentinels that fell in the initial assault, they could destroy the pylons for us.", ["objectivesText"] = "Activate 5 Quel'Danas Sentinels to destroy the Void Pylons. Progress: We need to activate all the sentinels if we want to destroy the void pylons.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2565, ["npcID"] = 236964, ["x"] = 0.4948, ["y"] = 0.2176 } }, ["ends"] = { { ["mapID"] = 2432, ["npcID"] = 236978, ["x"] = 0.454, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 2565, ["source"] = "quest_giver", ["x"] = 0.4948, ["y"] = 0.2176 }, ["mapCandidates"] = { ["npc"] = { 2432, 2565 }, ["zone"] = { 16211 } }, ["questType"] = "standard", ["sourceQuests"] = { 86807 }, ["questLines"] = { { ["id"] = 5811, ["name"] = "The Light's Summons", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 335, ["title"] = "Midnight Expansion Intro Skip", ["questLineID"] = 5811, ["questLineOrder"] = 0 }, { ["id"] = 352, ["title"] = "Midnight", ["questLineID"] = 5811, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2858, ["db2PoiUiMapID"] = 2432 },
[91277] = { ["id"] = 91277, ["name"] = "Prey: Preferential Killing", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 91277 }, ["description"] = "The anguish you've brought me has been... impeccable. As potent and complex as a finely aged wine. Normally, scrying the rough whereabouts of our targets takes me time and power. But using these overflowing stores of anguish, I can find anyone you desire to slaughter. You have done well, my champion. You deserve to reap this bounty. Tell me what you want.", ["objectivesText"] = "Speak to Astalor to select a customized Prey target, zone, and difficulty. Progress: Consider your choices with relish. I know I do.", ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 246231, ["x"] = 0.565333, ["y"] = 0.654667 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 246231, ["x"] = 0.565333, ["y"] = 0.654667 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.565333, ["y"] = 0.654667 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
