[91284] = { ["id"] = 91284, ["name"] = "A Path Not Yet Chosen", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16173, ["mapID"] = 2395, ["storyline"] = { 91284, 91288, 91291, 91292, 91301, 94393 }, ["description"] = "I'm trying to figure out what career path to follow, but I keep second-guessing myself. The Farstriders, the Blood Knights, the Magisters... they all seem so incredible that I can't decide. I was hoping if I spoke to each and earned a recommendation, I might finally understand where I'm meant to be. Would you help me?", ["objectivesText"] = "Collect Recommendations from the Farstrider, Blood Knight, and Magister trainers. Progress: I really hope I find where I belong...", ["rewardGold"] = 170800, ["rewardXP"] = 5885, ["rewardItems"] = { 246166, 246167, 246168 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 245192, ["x"] = 0.425333, ["y"] = 0.145333 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 246557, ["x"] = 0.426, ["y"] = 0.145 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.425333, ["y"] = 0.145333 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 94393 }, ["questLines"] = { { ["id"] = 5937, ["name"] = "How to Train Your Protegee", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91288] = { ["id"] = 91288, ["name"] = "A Test of the Hunt", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16173, ["mapID"] = 2395, ["storyline"] = { 91284, 91288, 91291, 91292, 91301, 94393 }, ["description"] = "So, you want a Farstrider recommendation? We don't hand those out like festival ribbons. If you want to earn it, then you'll need to do what every other recruit does. Bring me lynx pelts, clean and proper. No shortcuts, no excuses. Let's see if you've got the spine for it.", ["objectivesText"] = "Gather 8 Invasive Lynx Pelts in the Sunstrider Isle. Progress: Have you gotten those pelts yet or are you quitting already?", ["rewardGold"] = 328500, ["rewardXP"] = 11765, ["rewardItems"] = { 246153 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 245202, ["x"] = 0.422, ["y"] = 0.132 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 245202, ["x"] = 0.422, ["y"] = 0.132 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.132 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91284 }, ["questLines"] = { { ["id"] = 5937, ["name"] = "How to Train Your Protegee", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91291] = { ["id"] = 91291, ["name"] = "A Test of Blood", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16173, ["mapID"] = 2395, ["storyline"] = { 91284, 91288, 91291, 91292, 91301, 94393 }, ["description"] = "Ah, you seek a Blood Knight's recommendation, do you? In that case, you'll need to prove your worth... against me. Only those with true strength and honor may join our ranks! Prepare yourself. This won't be a simple challenge, but if you can best me, I'll gladly offer my recommendation!", ["objectivesText"] = "Defeat Jesthenis Sunstriker in the Sunstrider Isle. Progress: Well, what do you think?", ["rewardGold"] = 683200, ["rewardXP"] = 14705, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3365, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 245200, ["x"] = 0.428, ["y"] = 0.138 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 245200, ["x"] = 0.428, ["y"] = 0.138 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.138 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91284 }, ["questLines"] = { { ["id"] = 5937, ["name"] = "How to Train Your Protegee", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91292] = { ["id"] = 91292, ["name"] = "A Test of the Arcane", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16173, ["mapID"] = 2395, ["storyline"] = { 91284, 91288, 91291, 91292, 91301, 94393 }, ["description"] = "Ah, you seek a recommendation from a Magister, do you? Very well... but first, you must prove your understanding of the arcane. Go to the nearby crystals we have for training, extract their energy, and channel it into this staff. Show me that you can harness the arcane, and I will see you worthy of my recommendation. Should you fail, don't bother returning. My time is too valuable for such trivial matters.", ["objectivesText"] = "Charge the Arcane Transfer Staff 4 times in Sunstrider Isle. Progress: Well? Is the staff charged, or are you wasting both our lives?", ["rewardGold"] = 170800, ["rewardXP"] = 5885, ["rewardItems"] = { 244539 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 245201, ["x"] = 0.432, ["y"] = 0.146 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 245201, ["x"] = 0.432, ["y"] = 0.146 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.146 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91284 }, ["questLines"] = { { ["id"] = 5937, ["name"] = "How to Train Your Protegee", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91301] = { ["id"] = 91301, ["name"] = "How to Train Your Protege", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16173, ["mapID"] = 2395, ["storyline"] = { 91284, 91288, 91291, 91292, 91301, 94393 }, ["description"] = "I did everything they asked--the trials, the lessons--and they all said I did well... but I still don't know where I truly belong. Each path felt right in its own way, and now my heart feels pulled in three directions. Please... could you help me decide?", ["objectivesText"] = "Turn in the chosen recommendation to Instructor Thalendir in Silvermoon City.", ["rewardGold"] = 170800, ["rewardXP"] = 5885, ["rewardItems"] = { 263349, 263351, 263352, 263353 }, ["rewardChoices"] = { 263349, 263351, 263352, 263353 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3365, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 246557, ["x"] = 0.426, ["y"] = 0.145 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 245285, ["x"] = 0.332, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.145 }, ["mapCandidates"] = { ["npc"] = { 2393, 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91284 }, ["questLines"] = { { ["id"] = 5937, ["name"] = "How to Train Your Protegee", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[91302] = { ["id"] = 91302, ["name"] = "Abundance: Abundant Grove", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["storyline"] = { 87350, 89507, 91302, 91457, 91475, 91930, 91932, 91933, 93890, 93931, 94361 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5810, ["name"] = "Abundance", ["orderIndex"] = 4, ["flags"] = 0 } }, ["activities"] = { ["scenarios"] = { { ["id"] = 3093, ["name"] = "Abundance: Herbalism Cave", ["areaID"] = 0 } } } },
[91314] = { ["id"] = 91314, ["name"] = "Untethered Potential", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 91314, 91454 }, ["description"] = "<class>--I heard you have explored Untethered Space? That place is soaked with pristine void energy. I would like to explore it myself, but the last who have ventured into were consumed by the Void. I need help with my research. There are Phase-Lost creatures in the Voidscar Cavern that I could use to examine their essence. If you could collect that for me, I would be grateful. Go carefully.", ["objectivesText"] = "Collect 5 Phase-Altered essence in Untethered Space. Progress: Were you able to collect the Phase-Altered essence ?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 235499, 246244, 246589 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 246601, ["x"] = 0.598, ["y"] = 0.29 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 246601, ["x"] = 0.598, ["y"] = 0.29 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.29 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 84967 }, ["questLines"] = { { ["id"] = 5953, ["name"] = "Untethered Potential", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[91328] = { ["id"] = 91328, ["name"] = "Secret Ingredients", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16536, ["mapID"] = 2395, ["storyline"] = { 91090, 91137, 91271, 91328 }, ["description"] = "Our gregarious guests have partaken so much from our stores that we are running dangerously low of our special Solaarian sintalia. The rich taste of belanise, with its intoxicating scent, contrasts perfectly with the sharp tartness of the local berries. Carefully prepared then soaked in our special blend of spirits, then served--it's to die for! Just between us, if the berries are not handled just right, the infusion can be quite deadly. Otherwise... delicious, invigorating, purifying, glorious!", ["objectivesText"] = "Collect 6 Belanise Blossoms and 5 Sinara Berries for the Solaarian Sintalia. Progress: Are you gathering carefully?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 246363, 246364 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 245745, ["x"] = 0.488, ["y"] = 0.766 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 245745, ["x"] = 0.488, ["y"] = 0.766 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.766 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91271 }, ["questLines"] = { { ["id"] = 5949, ["name"] = "Sunbath, Take Me Away", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91339] = { ["id"] = 91339, ["name"] = "Smothered in the Crib", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90910, 91339, 91340, 91341, 91343 }, ["description"] = "I summoned my first imp in a dirty, haze-filled lounge beneath Murder Row after a dozen failed attempts. Each time, I reached further for what made so-called greater powers submit to mortals. I finally managed it after wetting my hands with the hot blood of a young rabbit. Bloodthistle never satisfied me again. I have matured my technique since then. Seek the whelps of these beasts. Siphon their energy into my reliquary of darkness . From their sacrifice, we will draw the power to defeat Kalgorg.", ["objectivesText"] = "Drain 9 juvenile wildlife with the Reliquary of Darkness . Progress: Don't fear power, <name>: fear those who wield it.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 246435 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 239720, ["x"] = 0.46, ["y"] = 0.774667 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 239720, ["x"] = 0.46, ["y"] = 0.774667 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.774667 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 90910 }, ["questLines"] = { { ["id"] = 5962, ["name"] = "The Nightbreaker", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2526 },
[91340] = { ["id"] = 91340, ["name"] = "For Violence's Sake", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90910, 91339, 91340, 91341, 91343 }, ["description"] = "Like many warlocks, I bind my demons with terms of a contract. I should have realized the Void and violence of this world could affect the rules I took for granted. Kalgorg used that power to break its bindings and end our arrangement. When we confront Kalgorg, the scent of blood and violence must be upon us. Slay the beasts you find to demonstrate to Kalgorg we are willing to do the same to it. Control over the Void is found and lost within the blink of an eye.", ["objectivesText"] = "Kill wildlife on the surface of the Den of Predaxas.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 239720, ["x"] = 0.46, ["y"] = 0.774667 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 239720, ["x"] = 0.46, ["y"] = 0.774667 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.774667 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 90910 }, ["questLines"] = { { ["id"] = 5962, ["name"] = "The Nightbreaker", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2526 },
[91341] = { ["id"] = 91341, ["name"] = "Unlimited", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90910, 91339, 91340, 91341, 91343 }, ["description"] = "Now, we descend. The Void energy below is unlike any I've felt before, as if gravity itself yields to the Void. Once you enter the cave, its influence will be upon you. Kalgorg has already slain and claimed power from the creatures within. Their violent deaths have left behind some kind of cursed terrain, but we must proceed and claim the power within. Fill the reliquary to the brim. I know not what to expect from my voidwalker. We will need all the power we can manage.", ["objectivesText"] = "Gather Void Power within the Lair of Predaxas. Progress: The trail of carnage it left behind... I'm almost proud.", ["rewardGold"] = 256200, ["rewardXP"] = 9635, ["rewardItems"] = { 211951, 212458, 247854 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 239720, ["x"] = 0.46, ["y"] = 0.774667 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 239720, ["x"] = 0.46, ["y"] = 0.774667 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.774667 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 91339, 91340 }, ["questLines"] = { { ["id"] = 5962, ["name"] = "The Nightbreaker", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2527 },
[91342] = { ["id"] = 91342, ["name"] = "If You Want It Done Right", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91342, 91345, 91347, 91348, 91349, 91350, 91383, 91384, 91385, 91452, 91462, 91463, 94371 }, ["description"] = "With all the problems facing Eversong, the Farstriders have their hands full! I'm a capable arcanist. I've always admired the Farstriders--why not lend my talents to their cause? They do so much work by hand, when a bit of magic would allow them so much more time for adventuring! Alas, my enchanted broom idea has not quite gone as I'd hoped. They're so ornery, they end up attacking the recruits instead of cleaning! Perhaps this is a problem for elbow grease after all.", ["objectivesText"] = "Slay 8 Ornery Sweepers . Progress: Captain Dawnrunner warned me about trying to solve all my problems with magic... Clearly I have much yet to learn.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 246806, ["x"] = 0.574, ["y"] = 0.4 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 258969, ["x"] = 0.566, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.574, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 94371 }, ["questLines"] = { { ["id"] = 5969, ["name"] = "Far Striding", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91343] = { ["id"] = 91343, ["name"] = "Ambition's Reward", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90910, 91339, 91340, 91341, 91343 }, ["description"] = "You have filled the reliquary with power I can draw on. Now, we reap the reward of our preparations. Kalgorg waits just ahead, draining the beast that once made this cave its lair. Weaken Kalgorg, and I will bind it as I first did years ago.", ["objectivesText"] = "Subdue Kalgorg the Unshackled .", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardItems"] = { 264295, 264296, 264297, 264298 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3389, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 239720, ["x"] = 0.46, ["y"] = 0.774667 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 239720, ["x"] = 0.46, ["y"] = 0.774667 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.774667 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 91341 }, ["questLines"] = { { ["id"] = 5962, ["name"] = "The Nightbreaker", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[91345] = { ["id"] = 91345, ["name"] = "To the North Tower", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91342, 91345, 91347, 91348, 91349, 91350, 91383, 91384, 91385, 91452, 91462, 91463, 94371 }, ["description"] = "Ranger Valsarin is a chef at Farstrider Hold. He's decent in a kitchen, but his passion is field cooking. There was a time when you could wander any path in Eversong and find the ingredients for a good meal. A Farstrider's dream! With enough hard work, we can help the forest recover, and it starts with rehabilitating the soil. Meet Valsarin at the North Tower and he can tell you more.", ["objectivesText"] = "Meet Ranger Valsarin at the North Tower.", ["rewardGold"] = 31900, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 246866, ["x"] = 0.566, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 247394, ["x"] = 0.496, ["y"] = 0.482 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91342, 91452 }, ["questLines"] = { { ["id"] = 5969, ["name"] = "Far Striding", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91346] = { ["id"] = 91346, ["name"] = "Supplicants to the Goddess", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91346, 91359, 91360, 91361 }, ["description"] = "We have long tended to the roots with the help of the creatures who live and grow here. Think of it as a symbiotic relationship from which we, the creatures, and the roots all benefit. That said, my partner Riverscale isn't contributing very much lately! Please help me find a way to motivate him again. First, you must cleanse off the essence of the outside. Cleanse yourself in the waters of Har'kuai .", ["objectivesText"] = "Cleanse yourself in the Waters of Har'kuai .", ["rewardGold"] = 34100, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3370, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 246607, ["x"] = 0.654, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 246607, ["x"] = 0.654, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86930 }, ["questLines"] = { { ["id"] = 5952, ["name"] = "The Greenspeaker's Vigil", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91347] = { ["id"] = 91347, ["name"] = "Strider Stampede", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91342, 91345, 91347, 91348, 91349, 91350, 91383, 91384, 91385, 91452, 91462, 91463, 94371 }, ["description"] = "It's hard to believe this used to be the Dead Scar. Up here, close to the city, the land has almost completely recovered. Which is good, because we've got a lot of mouths to feed. Hawkstriders are the perfect helpers for preparing the soil. Their tough claws can easily spread seeds and squash bugs! Meet me down in the Tranquil Repose and I'll saddle one up for you.", ["objectivesText"] = "Mount up the Saddled Hawkstrider and prepare the Tranquil Repose for gardening. Progress: Nothing like planting seeds.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 249491 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 247394, ["x"] = 0.496, ["y"] = 0.482 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 248307, ["x"] = 0.504, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.482 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91345 }, ["questLines"] = { { ["id"] = 5969, ["name"] = "Far Striding", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91348] = { ["id"] = 91348, ["name"] = "See a Mana 'bout a Wyrm", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91342, 91345, 91347, 91348, 91349, 91350, 91383, 91384, 91385, 91452, 91462, 91463, 94371 }, ["description"] = "Mana wyrms may not be as glamorous as lynxes or hawkstriders, but they're crucial to keeping magic flowing through the forest. They congregate on the ley lines to molt, but sometimes they get a little agitated. And we have to help them out! Aggressively! I've set up some ley channels to get things started. Find wyrms that look like they could use a little help, and beat them up until they shed their arcane carapace. Don't worry--all that mana returns to the forest eventually!", ["objectivesText"] = "Aggressively assist 8 Agitated Wyrms with their molting. Progress: Don't worry! They bounce right back.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 249490 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 247395, ["x"] = 0.486, ["y"] = 0.576 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 247395, ["x"] = 0.486, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.486, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91462 }, ["questLines"] = { { ["id"] = 5969, ["name"] = "Far Striding", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91349] = { ["id"] = 91349, ["name"] = "The Dark Part of the Woods", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91342, 91345, 91347, 91348, 91349, 91350, 91383, 91384, 91385, 91452, 91462, 91463, 94371 }, ["description"] = "Much of the forest has recovered, but to the south... Everything that Eversong has faced--the Scourge, the fel, and now the Twilight's Blade--all that magic leaches into the soil. It builds up in the creatures until they're completely overwhelmed... My instruments can detect corruption in these animals. We can cull the ones that are too far gone and save the ones that aren't. It isn't fun... but it's for the good of Eversong!", ["objectivesText"] = "Test 8 creatures for corruption, and deal with the consequences. Progress: It's hard work, but it will bring peace eventually.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 248244, 249492 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 247500, ["x"] = 0.436, ["y"] = 0.752667 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 247500, ["x"] = 0.436, ["y"] = 0.752667 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.752667 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91463 }, ["questLines"] = { { ["id"] = 5969, ["name"] = "Far Striding", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91350] = { ["id"] = 91350, ["name"] = "A Real Assignment", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91342, 91345, 91347, 91348, 91349, 91350, 91383, 91384, 91385, 91452, 91462, 91463, 94371 }, ["description"] = "Captain Dawnrunner was supposed to check on the Enclave and then meet us here. She's as capable a ranger as any! It's a bad sign if she's been detained. Farstrider Enclave is usually where they do wilderness training. With all the trouble however, everyone's been dispatched elsewhere. She could be up there alone, in serious danger! There's no time to lose. I'm going to save my Captain and prove myself as a Farstrider!", ["objectivesText"] = "Find Captain Dawnrunner at Farstrider Enclave.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 247500, ["x"] = 0.436, ["y"] = 0.752667 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 247593, ["x"] = 0.594, ["y"] = 0.688 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.752667 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91349 }, ["questLines"] = { { ["id"] = 5969, ["name"] = "Far Striding", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91359] = { ["id"] = 91359, ["name"] = "Fungal Lashers B Gone", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91346, 91359, 91360, 91361 }, ["description"] = "We are blessed to live in Harandar , but this is also our responsibility. The roots of the World Trees wind through these lands. We tend them, and they thrive. That is why it is so important for Riverscale to be back on duty. We need to keep these grounds clear of these fungal lashers before they leach off the roots. As a plus, Riverscale really loves lasher fronds. Can you find and bring some back for him?", ["objectivesText"] = "Collect 6 Harmonious Fronds in the outskirts of Har'kuai. Progress: It's important that we keep the lashers from sapping important nutrients from the World Tree. ...and I like spoiling my obstinate little boy.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 246886 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 246607, ["x"] = 0.654, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 246607, ["x"] = 0.654, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 91346 }, ["questLines"] = { { ["id"] = 5952, ["name"] = "The Greenspeaker's Vigil", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91360] = { ["id"] = 91360, ["name"] = "Weeding Out the Unwanted", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91346, 91359, 91360, 91361 }, ["description"] = "The roots of the World Trees are infused with both nutrients and the magic of Harandar . As the large vessels that they are, they will draw to them unwanted fauna and flora. Some of them are harmless, but we want to keep the roots clear. Haranir can often be allergic to the green weeds that flourish beside the roots of the World Trees. If you rip them out by the root, you would be saving us a lot of time--and hives!", ["objectivesText"] = "Pull 8 Allergenic Weeds in the outskirts of Har'kuai.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 246607, ["x"] = 0.654, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 246607, ["x"] = 0.654, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 91346 }, ["questLines"] = { { ["id"] = 5952, ["name"] = "The Greenspeaker's Vigil", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91361] = { ["id"] = 91361, ["name"] = "Back on Duty?", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91346, 91359, 91360, 91361 }, ["description"] = "Finally! I knew the little guy could do it. No, that is a bald-faced lie. If this grovecrawler could somehow find a way back into his cocoon, he would already be there. <Cyenna sighs.> His second favorite treat is the potatoad. If that doesn't work, his third favorite treat is the petalwing. That should get him back onto his mite-hunting duties. ...I have the backbone of a wet frond.", ["objectivesText"] = "Help Riverscale gain his confidence by killing 8 Potatoads and Petalwings by the outskirts of Har'kuai.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 260431, 260432 }, ["rewardChoices"] = { 260431, 260432 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3370, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 246607, ["x"] = 0.654, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 246607, ["x"] = 0.654, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 91359, 91360 }, ["questLines"] = { { ["id"] = 5952, ["name"] = "The Greenspeaker's Vigil", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91363] = { ["id"] = 91363, ["name"] = "Harvest of Darkness", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91363, 91380, 91382 }, ["description"] = "You... make yourself useful. As a master of terrible beasts, it is my job to mold these hatchlings into dreaded beasts. I pit them against each other and they grow ever more violent. But the elves here insist that I will yield better results with just a bit of... tender loving care. Let us put this to the test. This runt is Fidoficus. You will show him tenderness and affection, and then we will see how ferocious he becomes. Collect some delicious dietary treats for him and return to me.", ["objectivesText"] = "Collect 10 Void-Infused Morsels and 6 Glaring Glowcaps outside of the Howling Ridge. Progress: These ingredients will make for a highly nutritious and equally delectable meal.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 246372, 246661 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 246727, ["x"] = 0.52, ["y"] = 0.674 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 246727, ["x"] = 0.52, ["y"] = 0.674 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.674 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86509 }, ["questLines"] = { { ["id"] = 6012, ["name"] = "A Domanaar's Best Friend", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405, ["db2QuestHubAreaPoiID"] = 8502 },
[91375] = { ["id"] = 91375, ["name"] = "The Silence at Fungara Village", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91375, 91376, 91377, 91378, 91379, 91381 }, ["description"] = "Fungara Village has been silent for some time now. We've largely been occupied with the Lightbloom and the threat it presents, so we haven't had time to check in on the fungarians to the east. Usually, they are rowdy yet manageable... but it's rare that they go completely silent. I am going to investigate. If you wish to prove yourself an ally, you would do well to join me.", ["objectivesText"] = "Seek Ghikal outside of Fungara Village in Harandar .", ["rewardGold"] = 34100, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3370, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 257002, ["x"] = 0.333, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 246777, ["x"] = 0.44, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.333, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86890 }, ["nextQuests"] = { 91376, 91377 }, ["questLines"] = { { ["id"] = 6036, ["name"] = "The Silence at Fungara Village", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91376] = { ["id"] = 91376, ["name"] = "Little Monsters", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91375, 91376, 91377, 91378, 91379, 91381 }, ["description"] = "When I sent a request for aid from Har'alnor, I did not expect them to send me an outsider. No matter. The denizens of Fungara Village have gone quiet. Normally, I would be thrilled: they're horribly screechy. But the way they are shambling about... it is like they have forgotten that they yet live. < Ghikal shudders.> I tried to get close, but they attacked me on sight. I will need samples of their flesh. Go and bring them to me, so I can see what has happened here.", ["objectivesText"] = "Collect 10 samples of Strange Mycelium from the former denizens of Fungara Village. Progress: I do not know what is going on, but to err on the side of caution... do not let them bite you, hrm? Whatever plagues them may be infectious.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 247243 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 246777, ["x"] = 0.44, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 246777, ["x"] = 0.44, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 91375 }, ["questLines"] = { { ["id"] = 6036, ["name"] = "The Silence at Fungara Village", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91377] = { ["id"] = 91377, ["name"] = "Spawn of the Dead", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91375, 91376, 91377, 91378, 91379, 91381 }, ["description"] = "It is obvious that something terrible has happened in the village. I can see the corpses of their largest specimens strewn across the southern reaches from here, but something is off about them too. Fungarians don't usually just leave the corpses of their kin lying about. And though I am watching from afar, I swear that some of them are... twitching. Investigate. Find out what you can, and report back to me.", ["objectivesText"] = "Investigate 5 Blooming Corpses in Fungara Village.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 246777, ["x"] = 0.44, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 246777, ["x"] = 0.44, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 91375 }, ["questLines"] = { { ["id"] = 6036, ["name"] = "The Silence at Fungara Village", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91378] = { ["id"] = 91378, ["name"] = "You Are Legend", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91375, 91376, 91377, 91378, 91379, 91381 }, ["description"] = "Whatever these things are, they're not fungarians. Not anymore. Har'alnor has enough to worry about with the Lightbloom as it is. It cannot afford to be trapped between its forces and these... things. Do what must be done. Destroy as many of them as you can.", ["objectivesText"] = "Kill 15 Decanimated fungarians in the northern reaches of Fungara Village. Progress: Do not feel regret. These things are not alive anymore. Not in any way that matters.", ["rewardGold"] = 335000, ["rewardXP"] = 12170, ["rewardItems"] = { 17903, 17908, 18149, 20600, 67168, 67185, 67202, 67218, 67225, 67271, 71086, 80749, 80750, 80751, 80752, 80753, 80754, 80755, 80756, 80757, 172121, 172122, 172123, 172125, 172139, 208829, 253343, 255648, 255826, 263265, 263267, 263268, 263269 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 246777, ["x"] = 0.44, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 246777, ["x"] = 0.44, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 91376, 91377 }, ["questLines"] = { { ["id"] = 6036, ["name"] = "The Silence at Fungara Village", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91379] = { ["id"] = 91379, ["name"] = "Decayed Land", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91375, 91376, 91377, 91378, 91379, 91381 }, ["description"] = "As far as I can tell, these fungarians are all already dead. Something is animating their corpses from within, like puppets attached to unseen vines. This fungal matter that's infesting them must be coming from somewhere... and judging from the size of the ones further north, we'll find plenty of it there. Find it, get rid of it, but for Aln'hara's sake don't breathe it in.", ["objectivesText"] = "Destroy 8 growths of Fruiting Mycelium in Fungara Village.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 246777, ["x"] = 0.44, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 246777, ["x"] = 0.44, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 91376, 91377 }, ["questLines"] = { { ["id"] = 6036, ["name"] = "The Silence at Fungara Village", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91380] = { ["id"] = 91380, ["name"] = "Belly of the Beast", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91363, 91380, 91382 }, ["description"] = "I normally raise my beasts on a diet of raw, bloody carcasses and souls ripped asunder by the Void. But we shall try your mortal ways. I hear you... cook? And that makes the treat better? Do this. Then, take him on a walk around the Howling Ridge. Even I know exercise is good for digestion. Only the most ferocious of creatures is worthy of serving me. I hope neither you nor Fido disappoint me.", ["objectivesText"] = "Feed and walk Fidoficus around the Howling Ridge to promote its growth and savagery. Progress: He is still small, but one day, he will grow to be a terrible foe.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 62886, 62887, 62888, 131679 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 246727, ["x"] = 0.52, ["y"] = 0.674 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 246727, ["x"] = 0.52, ["y"] = 0.674 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.674 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 91363 }, ["questLines"] = { { ["id"] = 6012, ["name"] = "A Domanaar's Best Friend", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[91381] = { ["id"] = 91381, ["name"] = "Reticent Evil", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91375, 91376, 91377, 91378, 91379, 91381 }, ["description"] = "I do not understand. We've searched high and low, north and south. Everywhere we go, we find animated corpses and small fruiting fungus, but where is the central body? Where is-- Oh, goddess. Of course. The water, <class>. Check the water.", ["objectivesText"] = "Destroy the Agericus Decanimatus .", ["rewardGold"] = 309800, ["rewardXP"] = 12170, ["rewardItems"] = { 260440, 260444, 260446, 260447 }, ["rewardChoices"] = { 260440, 260444, 260446, 260447 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3370, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 246777, ["x"] = 0.44, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 246777, ["x"] = 0.44, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 91378, 91379 }, ["questLines"] = { { ["id"] = 6036, ["name"] = "The Silence at Fungara Village", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91382] = { ["id"] = 91382, ["name"] = "Mighty and Superior", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91363, 91380, 91382 }, ["description"] = "The beast is fed and exercised. Imagine, mortal... one day his maw will grow to fit you inside it a thousand times over. Now, we will test his potential for true violence. There is a beast that has laid claim to a den south of the Howling Ridge. Fidoficus trusts you now. Go with him and bear witness to his might.", ["objectivesText"] = "Bear witness to Fidoficus 's savagery as it slays Den-Gorger Zitoc . Progress: Fidoficus has grown fearsome, and perhaps you have claim to some of his growth.", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardItems"] = { 260922 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3389, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 246727, ["x"] = 0.52, ["y"] = 0.674 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 246727, ["x"] = 0.52, ["y"] = 0.674 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.674 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 91380 }, ["questLines"] = { { ["id"] = 6012, ["name"] = "A Domanaar's Best Friend", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[91383] = { ["id"] = 91383, ["name"] = "Tidy Up", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91342, 91345, 91347, 91348, 91349, 91350, 91383, 91384, 91385, 91452, 91462, 91463, 94371 }, ["description"] = "Captain Dawnrunner is fine, thank the sun. The only danger was... we didn't keep up on our chores. It's not heroic, it's not romantic, but we can't go on with Farstrider Enclave in this state. The rangers here are overwhelmed. We can all pitch in to help them get it cleaned up again. I can't believe it all comes back to sweeping. That's what being a Farstrider is really about.", ["objectivesText"] = "Clear out 5 Messy Nests and sweep up 5 Dusty Webs.", ["rewardGold"] = 331700, ["rewardXP"] = 11765, ["rewardItems"] = { 167562 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 247596, ["x"] = 0.594, ["y"] = 0.688 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 247593, ["x"] = 0.594, ["y"] = 0.688 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.594, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91350 }, ["questLines"] = { { ["id"] = 5969, ["name"] = "Far Striding", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91384] = { ["id"] = 91384, ["name"] = "Recovery Mission", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91342, 91345, 91347, 91348, 91349, 91350, 91383, 91384, 91385, 91452, 91462, 91463, 94371 }, ["description"] = "We've been deploying Farstriders across the forest to fight the Amani, the Lightbloom, the Void... but for all our heroics, there's no one left to tend to the wildlife! Or maintain the building! Or keep track of supplies! And now our beloved Enclave looks like a hawkstrider pen. I've had enough! I may not be able to help, but I trust you all can gather anything that was taken and get this place looking respectable again.", ["objectivesText"] = "Retrieve 12 Scattered Supplies from around Farstrider Enclave. Progress: If we want to be of any use to the rest of Eversong, first we must pick up after ourselves.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 249272 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 247593, ["x"] = 0.594, ["y"] = 0.688 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 247593, ["x"] = 0.594, ["y"] = 0.688 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.594, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91350 }, ["questLines"] = { { ["id"] = 5969, ["name"] = "Far Striding", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91385] = { ["id"] = 91385, ["name"] = "A Ranger's Spirit", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91342, 91345, 91347, 91348, 91349, 91350, 91383, 91384, 91385, 91452, 91462, 91463, 94371 }, ["description"] = "Taemin has proved himself as capable as any Farstrider today. But I'm afraid he might not see it that way. He came to us with such lofty ideas about the rangers--all those swashbuckling adventure stories, all the romantic old legends. But at the end of the day, being a ranger is mostly... chores. Difficult, boring, important chores. Why don't you go talk to him, and make sure he's not too disappointed?", ["objectivesText"] = "Find Recruit Taemin. Progress: The beauty of the forest? It never gets old.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 263416, 263419, 263427, 263429 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3365, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 247593, ["x"] = 0.594, ["y"] = 0.688 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 249398, ["x"] = 0.594, ["y"] = 0.672 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.594, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91383, 91384 }, ["questLines"] = { { ["id"] = 5969, ["name"] = "Far Striding", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91386] = { ["id"] = 91386, ["name"] = "Mad to Measure", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 91386, 91388, 91389, 92408 }, ["description"] = "These... tourists! These uncultured, ungrateful slobs! This Vanguard of Light has brought a lot of business to Silvermoon, to be certain. But none of them actually appreciate what Thalassian craftsmanship means. They have no respect for the elven arts--they just want shiny, glittery souvenirs! I am no spring runner dancing for their amusement... but I can hardly turn them away, can I? Perhaps an assistant would make this atrocious task easier.", ["objectivesText"] = "Assist Solwin Brightstitch with making clothes for Pushy Paladins. Progress: If only a single soul among these brutes showed any appreciation... alas, it seems even this small ask is too great.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 258127 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 247645, ["x"] = 0.4855, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 247645, ["x"] = 0.4855, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.4855, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 86735 }, ["questLines"] = { { ["id"] = 5989, ["name"] = "Tailor Troubles", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[91388] = { ["id"] = 91388, ["name"] = "Uncommon Threads", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91386, 91388, 91389, 92408 }, ["description"] = "Our patron--Gaari, I suppose--should count himself lucky. These mana wyrms produce the finest silk in Eversong. I know Magisters who would kill to have a robe trimmed in this, and yet here we are, using it for a mending job. Ah well. Once the wyrms have eaten their fill of arcane energy, you can siphon the silk from them onto these bobbins. If they are reluctant to release their silk, you may have to, ah... beat it out of them. But I've been assured it's entirely ethical.", ["objectivesText"] = "Siphon 8 Full Bobbins of Manasilk from weakened wyrms in the North Sanctum. Progress: This is the easy part, of course.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 250919, 251521 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 250888, ["x"] = 0.468, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 250888, ["x"] = 0.468, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 92408 }, ["questLines"] = { { ["id"] = 5989, ["name"] = "Tailor Troubles", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91389] = { ["id"] = 91389, ["name"] = "Clothes Make the Man", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91386, 91388, 91389, 92408 }, ["description"] = "It is not merely the material that makes an arcanoweave cloak so fine, but the weaving process itself. To mend one, particularly one that has built up so much history and latent arcane energy... I am about to embark on a very dangerous bit of tailoring indeed. Finally, a real testament to my skills. I am excited. I hope nothing explodes. Meet me inside when you're prepared.", ["objectivesText"] = "Meet Solwin inside, then fend off any manifestations as he mends the cloak.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 258127 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3365, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 250888, ["x"] = 0.468, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 252179, ["x"] = 0.45, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91388 }, ["questLines"] = { { ["id"] = 5989, ["name"] = "Tailor Troubles", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91390] = { ["id"] = 91390, ["name"] = "Special Assignment: What Remains of a Temple Broken", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91390, 91793, 91796, 91798, 91799, 91800, 91801, 91802, 91803, 91804, 91805, 91806, 91808, 91810, 91811 }, ["objectivesText"] = "Daily quests completed in Broken Throne", ["rewardXP"] = 13690, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15947 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5978, ["name"] = "Zul'Aman - World Quests/Repeatables", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 3, ["objectID"] = 246802, ["text"] = "Daily quests completed in Broken Throne" } }, ["db2PoiUiMapID"] = 2437, ["db2QuestInfoID"] = 286, ["db2QuestInfoName"] = "Capstone World Quest" },
[91391] = { ["id"] = 91391, ["name"] = "Still Scouting", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 46, ["mapID"] = 36, ["storyline"] = { 86822, 86823, 86824, 86825, 86826, 86827, 86828, 86829, 86830, 86831, 86832, 86833, 86903, 91391, 91726, 91787, 91842 }, ["description"] = "When the Alliance originally fought the Horde here, Kurdran served as a scout. He's still an excellent one. He took his gryphon to Blackrock Mountain to see what kind of forces we may be dealing with there. Meet up with him and see what kind of trouble you can cause.", ["objectivesText"] = "Meet Kurdran at Blackrock Mountain.", ["rewardGold"] = 31900, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 36, ["npcID"] = 237224, ["x"] = 0.335, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 36, ["npcID"] = 237268, ["x"] = 0.212, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 36, ["source"] = "quest_giver", ["x"] = 0.335, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 36 }, ["zone"] = { 46 } }, ["questType"] = "standard", ["sourceQuests"] = { 86823, 86824, 86825 }, ["questLines"] = { { ["id"] = 5751, ["name"] = "Regrets of the Past", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5751, ["questLineOrder"] = 12 } }, ["db2PoiUiMapID"] = 36 },
[91398] = { ["id"] = 91398, ["name"] = "Tomes of Terror", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91398, 91399, 91400, 91401, 91402 }, ["description"] = "Knowledge is power, and de ogres been reading. Bring me dey tomes so dey never grow dis powah again.", ["objectivesText"] = "Kill ogres in Atal'Kaldan and collect 4 tomes. Progress: Get me de tomes.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 246436 }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 246877, ["x"] = 0.272, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 246877, ["x"] = 0.272, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91390 }, ["questLines"] = { { ["id"] = 5951, ["name"] = "What Remains of Broken Throne", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91399] = { ["id"] = 91399, ["name"] = "Ashes of the Void", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91398, 91399, 91400, 91401, 91402 }, ["description"] = "De void elementals have one use. De dust dey drop is useful for shadow magic rituals. Collect some for our tribe.", ["objectivesText"] = "Kill void elementals and collect their ashes. Progress: Don't worry, we been doin' dese rituals for centuries.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 246439 }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 246878, ["x"] = 0.226, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 246878, ["x"] = 0.226, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.226, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91390 }, ["questLines"] = { { ["id"] = 5951, ["name"] = "What Remains of Broken Throne", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91400] = { ["id"] = 91400, ["name"] = "Blades of the Fallen", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91398, 91399, 91400, 91401, 91402 }, ["description"] = "After de battle we left a lot of our weapons behind. Please go collect dem so de Twilight's Blade doesn't get dem.", ["objectivesText"] = "Collect 12 Amani weapons from Atal'Kaldan.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 246879, ["x"] = 0.224, ["y"] = 0.796 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 246879, ["x"] = 0.224, ["y"] = 0.796 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.224, ["y"] = 0.796 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91390 }, ["questLines"] = { { ["id"] = 5951, ["name"] = "What Remains of Broken Throne", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91401] = { ["id"] = 91401, ["name"] = "Dead by Dusk", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91398, 91399, 91400, 91401, 91402 }, ["description"] = "De Twilight's Blade cultists have de audacity to try and take back our temple. Kill de peons and bring me their femurs.", ["objectivesText"] = "Collect 20 femurs from Twilight's Blade cultists in Atal'Kaldan. Progress: Why femurs? None of ya business.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 242639, 246440 }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 246880, ["x"] = 0.284, ["y"] = 0.768 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 246880, ["x"] = 0.284, ["y"] = 0.768 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91390 }, ["questLines"] = { { ["id"] = 5951, ["name"] = "What Remains of Broken Throne", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91402] = { ["id"] = 91402, ["name"] = "Ultra Deadly Ultradon", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91398, 91399, 91400, 91401, 91402 }, ["description"] = "I saw some of de void elementals doing a sketchy ritual in de center of the battlefield. It looked like dey were summoning some void creatures. Make sure whatever dey summon is dealt with.", ["objectivesText"] = "Kill the Eminent Ultradon in the center of Atal'Kaldan. Progress: If dey start bringing the void here we're gonna be in a whole heap o' trouble.", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 246881, ["x"] = 0.254, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 246881, ["x"] = 0.254, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.254, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "group", ["sourceQuests"] = { 91390 }, ["questLines"] = { { ["id"] = 5951, ["name"] = "What Remains of Broken Throne", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91403] = { ["id"] = 91403, ["name"] = "Probable Paralytic", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91403, 91404, 91405, 91406, 91407, 91408, 91409, 91410, 91411, 91412, 91630 }, ["description"] = "Halazzi says dat de Vilebranch have made a new venom dat para... parliz--makes its victims not move--so they can drag them off to be sacrificed. He says it's frog venom. I said that doesn't make sense. Frogs are poison, right? Halazzi said frogs are normally poisonous, not venomous. But these have sharp horn bits on them, so maybe they have venom! I didn't know frogs could have venom, did you? Let's find out if these do--then de Witherbark can make an anti-venom!", ["objectivesText"] = "Collect 8 Venomous Horns from Horned Frogs. Progress: Halazzi says venomous is when dey bite or stab you, and poisonous is when you bite or eat dem! Isn't dat interestin'?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 246621 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 250068, ["x"] = 0.322, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 250068, ["x"] = 0.322, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.322, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91407 }, ["questLines"] = { { ["id"] = 5950, ["name"] = "A Venomous History", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91404] = { ["id"] = 91404, ["name"] = "A Most Vile Venom", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91403, 91404, 91405, 91406, 91407, 91408, 91409, 91410, 91411, 91412, 91630 }, ["description"] = "De Vilebranch are cookin' up more bad things. You should go to de source and make dem stop! Halazzi has smelled their venom-mixin' place someplace to de southeast, and he thinks it's more den just frog venom. ...Oh, Halazzi also said to bring back some kind of huge fang. Frogs don't have fangs, though. Well, find it anyway!", ["objectivesText"] = "Kill Venomhexxer Raxxis and find the fang Tobui described. Progress: Did you look for de big fang?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 246681 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 250068, ["x"] = 0.322, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 250068, ["x"] = 0.322, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.322, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91563 }, ["questLines"] = { { ["id"] = 5950, ["name"] = "A Venomous History", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91405] = { ["id"] = 91405, ["name"] = "Validating the Venom", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91403, 91404, 91405, 91406, 91407, 91408, 91409, 91410, 91411, 91412, 91630 }, ["description"] = "This means there are both frog and spider venoms in de mixtures. Halazzi says he senses somebody beseeched Shadra with dat fang. Dey must be a really big spider if their fang is dat big! Halazzi doesn't like that de Vilebranch had it. I can tell. He's unhappy. His ears get all flat like de wings of a kite. So we gotta help out. Take de samples and de fang to de Witherbark Chief. We Witherbark have alchemists dat can brew anti-venoms for both spiders and frogs.", ["objectivesText"] = "Speak to the Witherbark Chief and locate an anti-venom alchemist in the village.", ["rewardGold"] = 241500, ["rewardXP"] = 8825, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 250068, ["x"] = 0.322, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 247014, ["x"] = 0.36, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.322, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91403, 91404 }, ["questLines"] = { { ["id"] = 5950, ["name"] = "A Venomous History", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91406] = { ["id"] = 91406, ["name"] = "Far from the Hinterlands", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91403, 91404, 91405, 91406, 91407, 91408, 91409, 91410, 91411, 91412, 91630 }, ["description"] = "As a Torntusk of de Revantusk tribe, I am cautious of Witherbark because of our history with dem in de Hinterlands. My family moved here because of dem. The Witherbark here in Zul'Aman seem to respect us, but de Witherbark I remember in de Hinterlands killed and backstabbed their allies for power. They worshipped de spider loa, Shadra. When de Hinterlands's Witherbark temple Shadra'Alor fell, de Witherbark must have fled somewhere. Look around for evidence of Hinterlands Witherbark and of Shadra.", ["objectivesText"] = "Investigate the Witherbark from the Hinterlands for signs of Shadra.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 247014, ["x"] = 0.36, ["y"] = 0.248 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 247014, ["x"] = 0.36, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.36, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 92084 }, ["questLines"] = { { ["id"] = 5950, ["name"] = "A Venomous History", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91407] = { ["id"] = 91407, ["name"] = "The Eye of the Loa", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91403, 91404, 91405, 91406, 91407, 91408, 91409, 91410, 91411, 91412, 91630 }, ["description"] = "I lost friends to venoms made from Shadra's spiders in de Hinterlands. I gotta know if Shadra's lurkin' around here, twistin' de minds of these Witherbark. No Revantusk will be safe in Zul'Aman with Shadra-worshippin' Witherbark around! Maybe I seem paranoid, but I have my reasons. And you have Halazzi's ear. You could ask him to reveal to you any hidden spiders, yes? I know those long ears can hear dem skitterin'! There is a shrine behind me. Stand in front of it and see if he'll grant you a boon.", ["objectivesText"] = "Find evidence of Shadra in the Witherbark Bluffs with Halazzi's aid. Progress: Did Halazzi help you? He can hear anything, but he also can see what's hidden in shadow.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 247014, ["x"] = 0.36, ["y"] = 0.248 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 247014, ["x"] = 0.36, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.36, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91406 }, ["questLines"] = { { ["id"] = 5950, ["name"] = "A Venomous History", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91408] = { ["id"] = 91408, ["name"] = "Seeking Shadra", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91403, 91404, 91405, 91406, 91407, 91408, 91409, 91410, 91411, 91412, 91630 }, ["description"] = "We will untangle dis mess about Witherbark and Vilebranch soon enough. De loa Shadra and her schemes must be our first priority. I watched the spiders run in terror from you, and somethin' struck me. De spiders are not just running in panic--they're going somewhere... somewhere dey feel safe, and even I can see dem now. Dey are not hiding anymore. Dey are on de run! Our hunt continues. Let's follow dem.", ["objectivesText"] = "Follow the spiders to find where they lead. Progress: Where dis trail leads, we follow.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 247014, ["x"] = 0.36, ["y"] = 0.248 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 247251, ["x"] = 0.36, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.36, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91405 }, ["questLines"] = { { ["id"] = 5950, ["name"] = "A Venomous History", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91409] = { ["id"] = 91409, ["name"] = "Dreaming of Spiders", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["mapID"] = 2537, ["storyline"] = { 91403, 91404, 91405, 91406, 91407, 91408, 91409, 91410, 91411, 91412, 91630 }, ["description"] = "There are three relics of Shadra. I only had two. I had de fang in de village and de eye hidden here. Dey musta stolen de fang somehow, then came for de eye! We never had de Shell of Shadra--it was lost when we left Shadra'Alor. It's possible de Vilebranch have de shell. De fang and de eye should let us talk to Shadra briefly, even if we lack de last ritual relic to summon her. Come with me. I will show you how.", ["objectivesText"] = "Attempt the ritual with the fang and eye to speak to Shadra. Progress: De two artifacts should be enough to speak to a vision of Shadra.", ["rewardGold"] = 315900, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2537, ["npcID"] = 247254, ["x"] = 0.434, ["y"] = 0.536 } }, ["ends"] = { { ["mapID"] = 2537, ["npcID"] = 247254, ["x"] = 0.434, ["y"] = 0.536 } }, ["coords"] = { ["mapID"] = 2537, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.536 }, ["mapCandidates"] = { ["npc"] = { 2537 }, ["zone"] = {} }, ["questType"] = "standard", ["sourceQuests"] = { 91630 }, ["questLines"] = { { ["id"] = 5950, ["name"] = "A Venomous History", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91410] = { ["id"] = 91410, ["name"] = "Shared Loa", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2537, ["storyline"] = { 91403, 91404, 91405, 91406, 91407, 91408, 91409, 91410, 91411, 91412, 91630 }, ["description"] = "De Witherbark Chief knows many of us came from de Hinterlands with our worship of Shadra'Alor, but believed Shadra was long dead. We should let him know how Halazzi helped us to find and restore Shadra, and of Shadra's presence in de Witherbark crypt. He also must learn of de rapport with de Revantusk. I will stay with Shadra for now. Will you carry de message?", ["objectivesText"] = "Speak to the Witherbark Chief about Shadra.", ["rewardGold"] = 170800, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3354, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2537, ["npcID"] = 247254, ["x"] = 0.434, ["y"] = 0.536 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 244591, ["x"] = 0.385, ["y"] = 0.224 } }, ["coords"] = { ["mapID"] = 2537, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.536 }, ["mapCandidates"] = { ["npc"] = { 2437, 2537 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91412 }, ["questLines"] = { { ["id"] = 5950, ["name"] = "A Venomous History", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91411] = { ["id"] = 91411, ["name"] = "Maisara Caverns: Deep in Maisara", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91403, 91404, 91405, 91406, 91407, 91408, 91409, 91410, 91411, 91412, 91630 }, ["description"] = "Shadra has asked dat we recover de third piece of Mixer Jamanga's ritual, de Shell of Shadra . With it, maybe we can bring her back. She recognized both de Witherbark and Revantusk as her allies. I felt her approval upon all of us. I believe this is de right choice. Halazzi set us on dis path, and we each got our roles to see it through. Gather your allies and go into Maisara Caverns! I would expect one of their leaders to hold de shell. Kill dem and take it back.", ["objectivesText"] = "Recover the Shell of Shadra from within Maisara Caverns. Progress: I think dat Shadra will honor her word.", ["rewardGold"] = 1366400, ["rewardXP"] = 23530, ["rewardItems"] = { 246586 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3354, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 247251, ["x"] = 0.36, ["y"] = 0.248 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 247251, ["x"] = 0.36, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.36, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 91409 }, ["questLines"] = { { ["id"] = 5950, ["name"] = "A Venomous History", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91412] = { ["id"] = 91412, ["name"] = "Return of the Venom Queen", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2537, ["storyline"] = { 91403, 91404, 91405, 91406, 91407, 91408, 91409, 91410, 91411, 91412, 91630 }, ["description"] = "It is time to bring Shadra to her proper place as a loa of de Witherbark and Revantusk. She will be small at first, but one day could be great like Halazzi and Nalorakk! Even a small loa will be a good ally against de Vilebranch venoms. She is de Loa of Spies, and will block their thievery of our people and relics, just as Halazzi hides them in the mists. Hold de Shell of Shadra in de center of de room, and we will call de loa to us!", ["objectivesText"] = "Follow Mixer Jamanga 's ritual to restore Shadra. Progress: This is more than de return of a loa--it is a bridge between tribes.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2537, ["npcID"] = 247254, ["x"] = 0.434, ["y"] = 0.536 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 247251, ["x"] = 0.36, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 2537, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.536 }, ["mapCandidates"] = { ["npc"] = { 2437, 2537 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91411 }, ["questLines"] = { { ["id"] = 5950, ["name"] = "A Venomous History", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
