[91442] = { ["id"] = 91442, ["name"] = "Eco-Dome Al'dani", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 91442 }, ["description"] = "We have received word from Ve'nari that the Wastelanders continue to stand in the way of progress on K'aresh. They threaten the most promising eco-dome. The restoration directive of K'aresh must not be interrupted. Put an end to these inefficiencies.", ["objectivesText"] = "Biergoth wants you to confront Soul-Scribe within Eco-Dome Al'Dani. Progress: Have you put an end to their efforts?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 2815, 2899, 2902, 3056, 237014 }, ["rewardChoices"] = { 2815, 2899, 2902, 3056, 237014 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.483333 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "dungeon" },
