[91452] = { ["id"] = 91452, ["name"] = "Range of Knowledge", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91342, 91345, 91347, 91348, 91349, 91350, 91383, 91384, 91385, 91452, 91462, 91463, 94371 }, ["description"] = "I've always dreamed of being a Farstrider--the adventure! The romance! The beauty of nature! When they put out a call for help, I knew I had to join. Captain Dawnrunner assigned me to the library initially, but with everything going on, we all have to be flexible. I don't mind, but I had hoped to collect all the overdue books before being sent on a real assignment. If you find any, would you bring them to the library for me? And feel free to give them a read! There are some interesting volumes!", ["objectivesText"] = "Retrieve 3 overdue books from around Farstrider Hold and return them to the library. Progress: It really takes everyone to get through times like these.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 254557, 254558, 254559 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 246806, ["x"] = 0.574, ["y"] = 0.4 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 258969, ["x"] = 0.566, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.574, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 94371 }, ["questLines"] = { { ["id"] = 5969, ["name"] = "Far Striding", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91454] = { ["id"] = 91454, ["name"] = "Phase-Lost Adventurer", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 91314, 91454 }, ["description"] = "Covered in slime and saliva, the journal bears a partial entry of a previous Phase Diver. <Day 27 Untethered Space is much more vast than I expected, with monsters stronger than I have seen on K'aresh . There is a nearby cave I will explore tomorrow. It is brimming with Phase-Altered Essence. This could bode useful for better understanding the ecology out here.> Researcher Essarae would be very interested in this.", ["objectivesText"] = "Take the journal to Researcher Essarae in Shan'dorah.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 246589 }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 246601, ["x"] = 0.598, ["y"] = 0.29 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.29 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 84967 }, ["questLines"] = { { ["id"] = 5953, ["name"] = "Untethered Potential", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371, ["startItems"] = { 246589 } },
