[91459] = { ["id"] = 91459, ["name"] = "Manaforge Omega: A Walking Shadow", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16178, ["mapID"] = 2371, ["storyline"] = { 91459 }, ["description"] = "Hero, can you hear me? There's a translocator the Shadowguard uses to send cargo to their reserves that can carry you directly to their post beneath the Manaforge. An ambush they'll never see coming! There is of course, a catch. We do not have clearance to use their supply lines... so we need you to procure some for us. Take down the highest-ranking member of the Shadowguard you can find, return with identification, and we'll forge you a one-way ticket to the front lines.", ["objectivesText"] = "Defeat Nexus-King Salhadaar within Manaforge Omega on Normal difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 245344, ["x"] = 0.42, ["y"] = 0.222 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 245344, ["x"] = 0.42, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "raid" },
[91460] = { ["id"] = 91460, ["name"] = "Manaforge Omega: A Walking Shadow", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16178, ["mapID"] = 2371, ["storyline"] = { 91460 }, ["description"] = "Hero, can you hear me? There's a translocator the Shadowguard uses to send cargo to their reserves that can carry you directly to their post beneath the Manaforge. An ambush they'll never see coming! There is of course, a catch. We do not have clearance to use their supply lines... so we need you to procure some for us. Take down the highest-ranking member of the Shadowguard you can find, return with identification, and we'll forge you a one-way ticket to the front lines.", ["objectivesText"] = "Defeat Nexus-King Salhadaar within Manaforge Omega on Heroic difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 245344, ["x"] = 0.42, ["y"] = 0.222 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 245344, ["x"] = 0.42, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "raid" },
[91461] = { ["id"] = 91461, ["name"] = "Manaforge Omega: A Walking Shadow", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16178, ["mapID"] = 2371, ["storyline"] = { 91461 }, ["description"] = "Hero, can you hear me? There's a translocator the Shadowguard uses to send cargo to their reserves that can carry you directly to their post beneath the Manaforge. An ambush they'll never see coming! There is of course, a catch. We do not have clearance to use their supply lines... so we need you to procure some for us. Take down the highest-ranking member of the Shadowguard you can find, return with identification, and we'll forge you a one-way ticket to the front lines.", ["objectivesText"] = "Defeat Nexus-King Salhadaar within Manaforge Omega on Mythic difficulty.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 245344, ["x"] = 0.42, ["y"] = 0.222 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 245344, ["x"] = 0.42, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "raid" },
[91462] = { ["id"] = 91462, ["name"] = "To the Central Tower", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91342, 91345, 91347, 91348, 91349, 91350, 91383, 91384, 91385, 91452, 91462, 91463, 94371 }, ["description"] = "Ranger Asterae is one of our veterinarians. She usually cares for our lynxes, but the mana wyrm molt is too crucial to the health of the forest to go unmonitored. The wyrms regulate the flow of magic from the ley lines to the rest of the woods. When the ley lines were disrupted, so was their molting season. It's not so dire as it once was, but they still need help from time to time. Meet Asterae at the Central Tower. She can tell you more.", ["objectivesText"] = "Meet Ranger Asterae at the Central Tower.", ["rewardGold"] = 31900, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 246866, ["x"] = 0.566, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 247395, ["x"] = 0.486, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91342, 91452 }, ["questLines"] = { { ["id"] = 5969, ["name"] = "Far Striding", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91463] = { ["id"] = 91463, ["name"] = "To the South Tower", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91342, 91345, 91347, 91348, 91349, 91350, 91383, 91384, 91385, 91452, 91462, 91463, 94371 }, ["description"] = "Despite being new to the Farstriders, Taemin has the hardest assignment. Eversong Woods has mostly recovered, but the further south you go, the more dangerous things get. He's a capable mage, though. And we need his nose for magic. We'll meet you down there once things are wrapped up here. Captain Dawnrunner was going to provide backup. She should be there by now.", ["objectivesText"] = "Meet Arcanist Taemin at the South Tower.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 247395, ["x"] = 0.486, ["y"] = 0.576 }, { ["mapID"] = 2395, ["npcID"] = 248307, ["x"] = 0.504, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 247500, ["x"] = 0.436, ["y"] = 0.752667 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.486, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91347, 91348 }, ["questLines"] = { { ["id"] = 5969, ["name"] = "Far Striding", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
