[91485] = { ["id"] = 91485, ["name"] = "Hacking the Planet", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16178, ["mapID"] = 2371, ["storyline"] = { 91485 }, ["description"] = "Hero... we're in. We have full control of Manaforge Omega 's security. I'll brief you on your next trip back.", ["objectivesText"] = "Report to Zo'ropo at Shadow Point.", ["starts"] = { { ["x"] = 0.42, ["y"] = 0.221, ["mapID"] = 2371, ["npcID"] = 245344 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 245349, ["x"] = 0.42, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questGiverID"] = 245344, ["questType"] = "raid" },
