[91493] = { ["id"] = 91493, ["name"] = "Not What I Ordered", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91493, 91494, 91495, 91504, 91505, 94370 }, ["description"] = "<A bite wound wrecks Hathvelion's forearm.> Snapdragons... cruel creatures made to kill and feed. Their poison moves as you move. The naga bred the perfect pet. I'm here on a tip from Lyssara Duskmourne. Sunsail Anchorage's shipping routes have been sabotaged by the naga, and those routes converge... here. I intercepted a few shipments. Could you help me search them? My team is still out in the field, but they should report back soon.", ["objectivesText"] = "Inspect 5 Intercepted Shipments. Progress: The blood elves could just use magic to trade. But there's something dependable about a sturdy wooden box. <Hathvelion thumps the table beside him and smiles.> Plus, I hear food and drink aren't as tasty after being transported by magic.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 246910, 246911, 246912, 246913, 246914 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 247503, ["x"] = 0.39, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 247503, ["x"] = 0.39, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 94370 }, ["questLines"] = { { ["id"] = 5958, ["name"] = "Daggerspine Landing", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91494] = { ["id"] = 91494, ["name"] = "One Elf's Trash, Another Elf's Treasure", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91493, 91494, 91495, 91504, 91505, 94370 }, ["description"] = "The arcane arts are not my specialty. I'm more versed in tangible magic--herbs, mixtures, distillation, topical applications, extraction, suture, painkilling... Regardless--that wand. To my uneducated eyes, it looks usable. Why don't you test it on the arcana container? Maybe it could help us against the naga. If it's truly broken, no harm done.", ["objectivesText"] = "Test the Discarded Wand on the Container of Unstable Arcana. Then, empower the wand in Daggerspine Landing. Progress: Maybe the wand was too weak for its original owner. Whatever the case, we can try to put it to good use.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 247593 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 250298, ["x"] = 0.39, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 250298, ["x"] = 0.39, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91493 }, ["questLines"] = { { ["id"] = 5958, ["name"] = "Daggerspine Landing", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91495] = { ["id"] = 91495, ["name"] = "Familiar Faces in Peril", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91493, 91494, 91495, 91504, 91505, 94370 }, ["description"] = "Fair winds guide your steps. My wish has come true--Eversong flourishes. But like before, evil threatens all that is good. Two townsfolk are unaccounted for since the naga arrived: Enith--Goldenmist's most curious apothecary, and Varnis--he's a student visiting from the city. It is my charge to find them. My fellow ranger, Vedoran, must still be in the field. I wonder if he's found something important. Will you keep an eye out for him?", ["objectivesText"] = "Find Apothecary Enith, Apprentice Varnis, and Ranger Vedoran in Daggerspine Landing. Progress: The Farstriders are grateful for your assistance.", ["rewardGold"] = 170800, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 250291, ["x"] = 0.39, ["y"] = 0.616 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 250291, ["x"] = 0.39, ["y"] = 0.616 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.616 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91493 }, ["questLines"] = { { ["id"] = 5958, ["name"] = "Daggerspine Landing", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91504] = { ["id"] = 91504, ["name"] = "Arcane Amassing", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91493, 91494, 91495, 91504, 91505, 94370 }, ["description"] = "Well, you heard Numia. She'll have my bow split in two if I don't rest. Ranger Vedoran reported activity at the lighthouse. A swarm of mana wyrms are gathered there, and of course, more naga. If that's where the head of the snake lives, chop it off! My rangers Vedoran and Krann'an will accompany you. And take the wand with you. It proved its worth. Powered up, it should pack a punch against whatever you face.", ["objectivesText"] = "Slay Princess Naz'jena in Daggerspine Point.", ["rewardGold"] = 683200, ["rewardXP"] = 14705, ["rewardItems"] = { 247753, 263334, 263343, 263344, 263345 }, ["rewardChoices"] = { 263334, 263343, 263344, 263345 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3365, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 247503, ["x"] = 0.39, ["y"] = 0.615 }, { ["mapID"] = 2395, ["npcID"] = 250388, ["x"] = 0.39, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 249870, ["x"] = 0.402, ["y"] = 0.612 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91494, 91495, 91505 }, ["questLines"] = { { ["id"] = 5958, ["name"] = "Daggerspine Landing", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91505] = { ["id"] = 91505, ["name"] = "Daggers in My Spine", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91493, 91494, 91495, 91504, 91505, 94370 }, ["description"] = "The naga have a history of abusing arcane magic. I bet my boots this is no different--arcane is their lifeblood and source of power. They are clever to operate now while Eversong is besieged by other threats. Since I became a Farstrider, I have safeguarded Eversong's western coast. My strike team set up watch on Goldenmist's perimeter already. Fortunately, the naga do not seem interested in the town yet, but they are far too close for comfort. Our course of action is simple: clear them out!", ["objectivesText"] = "Slay 12 Daggerspine naga in Daggerspine Landing. Progress: We can't let the naga get any closer to Goldenmist.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 247503, ["x"] = 0.39, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 247503, ["x"] = 0.39, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91493 }, ["questLines"] = { { ["id"] = 5958, ["name"] = "Daggerspine Landing", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91506] = { ["id"] = 91506, ["name"] = "Tale of the First Shul'ka and the Flame", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["starts"] = { { ["x"] = 0.646, ["y"] = 0.386, ["mapID"] = 2413, ["npcID"] = 241836 } }, ["ends"] = { { ["x"] = 0.646, ["y"] = 0.386, ["mapID"] = 2413, ["npcID"] = 241836 } }, ["coords"] = { ["mapID"] = 2413, ["x"] = 0.646, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15355 } }, ["questGiverID"] = 241836, ["questTurnInID"] = 241836, ["questType"] = "standard", ["sourceQuests"] = { 88996 }, ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 19, ["amount"] = 0, ["objectID"] = 38707, ["text"] = "The Echoless Flame located" }, { ["orderIndex"] = 1, ["type"] = 21, ["amount"] = 1, ["objectID"] = 5327, ["text"] = "Attune to the Echoless Flame" }, { ["orderIndex"] = 2, ["type"] = 15, ["amount"] = 1, ["objectID"] = 0, ["text"] = "The Echoless Flame used to slay Rift manifestations" }, { ["orderIndex"] = 3, ["type"] = 21, ["amount"] = 20, ["objectID"] = 5337, ["text"] = "<Rift Manifestations>" }, { ["orderIndex"] = 4, ["type"] = 2, ["amount"] = 3, ["objectID"] = 563492, ["text"] = "Containment Wards placed" }, { ["orderIndex"] = 5, ["type"] = 0, ["amount"] = 1, ["objectID"] = 248433, ["text"] = "Morta'ka contained" } } },
