[91525] = { ["id"] = 91525, ["name"] = "Head Hunting: Loom'ithar", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16178, ["mapID"] = 2371, ["storyline"] = { 91525 }, ["description"] = "Our intelligence describes a colossal beast within the Manaforge, responsible for producing the fabric that gives the Shadowguard their very form. Take it down and we'll hinder their ability to produce reinforcements. Oh, and Ba'choso says to bring some of the silk back with you - he may be able to fashion it into something useful.", ["objectivesText"] = "Defeat Loom'ithar within Manaforge Omega on any difficulty. Progress: Have you procured a sample?", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 245510 }, ["starts"] = { { ["x"] = 0.42, ["y"] = 0.221, ["mapID"] = 2371, ["npcID"] = 245344 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 245348, ["x"] = 0.42, ["y"] = 0.224 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.224 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questGiverID"] = 245344, ["questType"] = "raid" },
[91526] = { ["id"] = 91526, ["name"] = "Head Hunting: Forgeweaver Araz", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16178, ["mapID"] = 2371, ["storyline"] = { 91526 }, ["description"] = "My friend, I hope your assault is going well. It's time for you to dispatch the Forgeweaver; using his mastery of technomancy he oversees both the Manaforge's production pipelines... as well as the ritual to return Dimensius to this plane. His workshop will be further in and heavily guarded, but cutting him down should stop their plans of resurrection for good.", ["objectivesText"] = "Defeat Forgeweaver Araz inside Manaforge Omega on any difficulty. Progress: Does the Forgeweaver yet live?", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 249218 }, ["starts"] = { { ["x"] = 0.42, ["y"] = 0.221, ["mapID"] = 2371, ["npcID"] = 245344 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 245344, ["x"] = 0.42, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questGiverID"] = 245344, ["questType"] = "raid" },
[91527] = { ["id"] = 91527, ["name"] = "Head Hunting: The Soul Hunters", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16178, ["mapID"] = 2371, ["storyline"] = { 91527 }, ["description"] = "Careful in the wastes, my friend. Scouts report that a trio of Demon Hunters are training south of the Manaforge - with one of them exhibiting power like we've never seen. You can avoid their path if you wish, but ignoring them could open you up to being flanked should they decide to engage. I recommend taking them out if you can, as well as providing us some samples of their newfound strength.", ["objectivesText"] = "Defeat The Soul Hunters within Manaforge Omega on any difficulty.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 246492 }, ["starts"] = { { ["x"] = 0.42, ["y"] = 0.221, ["mapID"] = 2371, ["npcID"] = 245344 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 245344, ["x"] = 0.42, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questGiverID"] = 245344, ["questType"] = "raid" },
[91528] = { ["id"] = 91528, ["name"] = "Head Hunting: Horrors of the Forge", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16178, ["mapID"] = 2371, ["storyline"] = { 91528 }, ["description"] = "By now no doubt you've seen some of the Manaforge's Elite coming to Salhadaar's aid. I'm sending you a list of names now - focus on these targets, and you may uncover spoils to aid your assault.", ["objectivesText"] = "Defeat powerful Elite enemies within Manaforge Omega on any difficulty. Progress: Have you eliminated your targets?", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 238028, 238033 }, ["starts"] = { { ["x"] = 0.42, ["y"] = 0.221, ["mapID"] = 2371, ["npcID"] = 245344 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 245344, ["x"] = 0.42, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 16178 } }, ["questGiverID"] = 245344, ["questType"] = "raid" },
[91529] = { ["id"] = 91529, ["name"] = "Head Hunting: Nexus-King Salhadaar", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16178, ["mapID"] = 2371, ["storyline"] = { 91529 }, ["description"] = "The hour of Salhadaar's demise is upon us. While he may posture upon his Voidwing, he grows desperate at the feet of the All-Devouring. The army he commands is not enough for your might - strike him down.", ["objectivesText"] = "Defeat Nexus-King Salhadaar within Manaforge Omega on any difficulty.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 246727 }, ["starts"] = { { ["x"] = 0.42, ["y"] = 0.221, ["mapID"] = 2371, ["npcID"] = 245344 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 245344, ["x"] = 0.42, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questGiverID"] = 245344, ["questType"] = "raid" },
[91530] = { ["id"] = 91530, ["name"] = "Seeing Eye to Eye", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 91530 }, ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 244913 }, ["starts"] = { { ["npcID"] = 245344, ["x"] = 0.42, ["y"] = 0.222, ["mapID"] = 2371 } }, ["ends"] = { { ["npcID"] = 245344, ["x"] = 0.42, ["y"] = 0.222, ["mapID"] = 2371 } }, ["coords"] = { ["x"] = 0.42, ["y"] = 0.222, ["source"] = "quest_giver", ["mapID"] = 2371 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "raid" },
[91533] = { ["id"] = 91533, ["name"] = "What We Leave Behind", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91533, 91535, 91536, 91537, 91541, 91542, 91543, 91544, 91545, 91546, 91963 }, ["description"] = "Lothraxion deserved to pay for his arrogance with his life. Hieron didn't. Without him, I'd be dead. I know that Maella and Darkglen feel the same way. Hieron's journal , the one you recovered for us, ended up with me. I knew Hieron, but Astre knew him better. The two of them had found a closeness I admired. Astre deserves to hold onto it. Last I saw Astre, Hieron was tending to their wounds back at Locus Point. You were there when Hieron passed. They should know of his heroism and sacrifice.", ["objectivesText"] = "Deliver Hieron's journal to Riftblade Astre at Locus Point. Progress: I've recovered some since we last parted ways here, but the whispers continue to plague me. They're insidious, torturing me with what I lack, how I've failed. And-- Wait. Is that...? Where did you get that?", ["rewardGold"] = 34100, ["rewardXP"] = 1605, ["rewardItems"] = { 248207, 248209 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3389, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 249034, ["x"] = 0.536, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 248616, ["x"] = 0.418, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86522 }, ["questLines"] = { { ["id"] = 5961, ["name"] = "To Be Changed", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[91535] = { ["id"] = 91535, ["name"] = "Home Sweet Grave", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91533, 91535, 91536, 91537, 91541, 91542, 91543, 91544, 91545, 91546, 91963 }, ["description"] = "<Astre spends a long time in silence, thumbing through Hieron's journal.> Killed on another world, defending a city that didn't want him. There was so much we planned to do. Now... <Astre trails off, their eyes focusing on the journal's pages.> Oh. The tea recipe that Hieron was telling me about. He was excited for its properties--called it a purgative for the soul. He never had a chance to brew it. I know it seems stupid, <name>. I just want to taste Hieron's tea. The leaves should be nearby.", ["objectivesText"] = "Collect 8 Ghostflower Leaves around the base of Locus Point. Progress: <Astre thumbs through Hieron's journal with a detached expression.>", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 248241 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 248616, ["x"] = 0.418, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 248616, ["x"] = 0.418, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 91533 }, ["questLines"] = { { ["id"] = 5961, ["name"] = "To Be Changed", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[91536] = { ["id"] = 91536, ["name"] = "Like a Weed", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91533, 91535, 91536, 91537, 91541, 91542, 91543, 91544, 91545, 91546, 91963 }, ["description"] = "<Astre looks from Hieron's journal to the worn letter. Their expression flickers with anger.> Blood elves. They were our people until we embraced the Void. In their ignorance, they exiled us. Yet they are happy to ask us to fight their battles for them. They say we threaten the Sunwell. The truth is, they are afraid of us. Let's protect something of actual value. Kill any beasts that threaten those flowers for Hieron's tea. Silvermoon can save itself.", ["objectivesText"] = "Kill wildlife around Locus Point.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 248616, ["x"] = 0.418, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 248616, ["x"] = 0.418, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 91533 }, ["questLines"] = { { ["id"] = 5961, ["name"] = "To Be Changed", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[91537] = { ["id"] = 91537, ["name"] = "Confronting It", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91533, 91535, 91536, 91537, 91541, 91542, 91543, 91544, 91545, 91546, 91963 }, ["description"] = "I've put the kettle on. I trust you to brew it, if you wouldn't mind. It shouldn't take more than a moment before the tea is ready to drink. Let me try it first, just in case it's poisonous. I'm the one that asked to try it.", ["objectivesText"] = "Brew the Ghostflower Tea for Astre. Progress: <Astre holds their forehead.>", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 248616, ["x"] = 0.418, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 248616, ["x"] = 0.418, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 91535, 91536 }, ["questLines"] = { { ["id"] = 5961, ["name"] = "To Be Changed", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[91539] = { ["id"] = 91539, ["name"] = "A Radiant Echo", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 91539 }, ["description"] = "<Within your hand, you hold a small Azerite sphere. Its light is steady and bright, but the sound it emits is plaintive and longing. It tugs at you, ever so slightly.>", ["objectivesText"] = "Bring the Radiant Echo to a Worldsoul Memory, then release it.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 246771 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14771 } }, ["questType"] = "standard", ["startItems"] = { 246772, 254276 } },
[91541] = { ["id"] = 91541, ["name"] = "Unchecked Emotions", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91533, 91535, 91536, 91537, 91541, 91542, 91543, 91544, 91545, 91546, 91963 }, ["description"] = "Ren'dorei learn early to check our emotions. That by controlling ourselves, we can control the Void. Otherwise, our unsuppressed feelings can lead us to ruin. But I felt just now the powers of facing my feelings head-on. Maybe I could have done it on my own... But the tea, and your aid, made it easier. We should share Hieron's recipe with the others. I'll retrieve the kettle you brewed.", ["objectivesText"] = "Meet with Riftblade Astre at the Howling Ridge.", ["rewardGold"] = 30900, ["rewardXP"] = 1605, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3389, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 248616, ["x"] = 0.418, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 248072, ["x"] = 0.52, ["y"] = 0.696 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 91537 }, ["questLines"] = { { ["id"] = 5961, ["name"] = "To Be Changed", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[91542] = { ["id"] = 91542, ["name"] = "The Town Inside Me", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91533, 91535, 91536, 91537, 91541, 91542, 91543, 91544, 91545, 91546, 91963 }, ["description"] = "I can't say that drinking the tea is a pleasant experience. But it helps. I want the others to experience that too. That Hieron left us with a gift like this is so... him. He was always doing little things like that for others. For me. Share the tea with the others, then join me at Obscurion Citadel. I know better than to be alone in a place like that.", ["objectivesText"] = "Serve Ghostflower tea to Umbric, Maella, and Sideras in the Howling Ridge.", ["rewardGold"] = 256200, ["rewardXP"] = 9635, ["rewardItems"] = { 248722 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 248072, ["x"] = 0.52, ["y"] = 0.696 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 249045, ["x"] = 0.624, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.696 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 91541 }, ["questLines"] = { { ["id"] = 5961, ["name"] = "To Be Changed", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[91543] = { ["id"] = 91543, ["name"] = "Retaking Control", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91533, 91535, 91536, 91537, 91541, 91542, 91543, 91544, 91545, 91546, 91963 }, ["description"] = "This world is violent and dangerous, but it has an order to things. After you and the others took down the domanaar that ran this citadel and its arena, the food chain must have fallen to disarray. Harrowers swarm the skies and darken the horizon. I worry they'll seek new hunting grounds closer to our settlements if they aren't dealt with. Point them out for me and I'll use my grappling hook to pull them to the ground. Hieron's survival gear proves its use when we need it, as always.", ["objectivesText"] = "Kill flying Harrowers and Siphoids in Obscurion Citadel. Progress: Have they been dealt with?", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 248724 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 249045, ["x"] = 0.624, ["y"] = 0.824 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 249045, ["x"] = 0.624, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questTurnInID"] = 249045, ["questType"] = "standard", ["sourceQuests"] = { 91542 }, ["questLines"] = { { ["id"] = 5961, ["name"] = "To Be Changed", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[91544] = { ["id"] = 91544, ["name"] = "Familiar Energies", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91533, 91535, 91536, 91537, 91541, 91542, 91543, 91544, 91545, 91546, 91963 }, ["description"] = "I know that Hieron died here, but I feel echoes of someone else--of a great clash, where Void met Void. Hieron must have crossed blades with someone... something else. Something that's still out there.", ["objectivesText"] = "Scry Void Rifts with Riftblade Astre in Obscurion Citadel.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 249045, ["x"] = 0.624, ["y"] = 0.824 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 247668, ["x"] = 0.582, ["y"] = 0.785 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 91542 }, ["questLines"] = { { ["id"] = 5961, ["name"] = "To Be Changed", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[91545] = { ["id"] = 91545, ["name"] = "Stronger Than Before", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91533, 91535, 91536, 91537, 91541, 91542, 91543, 91544, 91545, 91546, 91963 }, ["description"] = "That must be the monster that killed Hieron. It's tearing open a backdoor for the Void's forces to pour into Silvermoon. This damn city. I'm not doing this for them. Signal Umbric. Let's do this. Together.", ["objectivesText"] = "Kill Notatus the Riftscarred .", ["rewardGold"] = 309800, ["rewardXP"] = 12845, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 249130, ["mapID"] = 2405, ["x"] = 0.623606, ["y"] = 0.824542 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 248072, ["x"] = 0.52, ["y"] = 0.696 }, { ["npcID"] = 249130, ["mapID"] = 2405, ["x"] = 0.623606, ["y"] = 0.824542 } }, ["coords"] = { ["source"] = "quest_giver", ["mapID"] = 2405, ["x"] = 0.623606, ["y"] = 0.824542 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 91543, 91544, 91963 }, ["questLines"] = { { ["id"] = 5961, ["name"] = "To Be Changed", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[91546] = { ["id"] = 91546, ["name"] = "To Be Changed", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91533, 91535, 91536, 91537, 91541, 91542, 91543, 91544, 91545, 91546, 91963 }, ["description"] = "There is one unresolved matter... <Astre reaches into their pocket and reveals the worn letter you had unpackaged alongside Hieron's journal. They run their fingers over it with a pensive expression.> Hieron wanted her to have it. She should know what happened to him. This is on me. Silvermoon again... Guess I'll see you when I'm back, <name>.", ["objectivesText"] = "Speak to Umbric about meeting with Astre in Silvermoon City. Progress: At least I'm not visiting my parents.", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardItems"] = { 249724, 264411, 264412 }, ["rewardChoices"] = { 264411, 264412 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3389, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 248072, ["x"] = 0.52, ["y"] = 0.696 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 249459, ["x"] = 0.318, ["y"] = 0.876667 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.696 }, ["mapCandidates"] = { ["npc"] = { 2393, 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 91545 }, ["questLines"] = { { ["id"] = 5961, ["name"] = "To Be Changed", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[91550] = { ["id"] = 91550, ["name"] = "A Game of Silence and Shadow", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91550, 91551, 91552, 91553 }, ["description"] = "You're different! That makes you kinda cool... and kinda really suspicious. We wanna see what you're made of! So here's the game: we hide, and you try to find us. If you do, well... guess we'll have to train more for next time. But if you don't? Then maybe our parents will finally let us go on our first solo hunt! This isn't just a silly game, okay? It's a trial called Silence and Shadow. It's serious. Very, very serious. Are you ready?", ["objectivesText"] = "Find 4 hiding children.", ["rewardGold"] = 170800, ["rewardXP"] = 6085, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 247640, ["x"] = 0.488, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 247658, ["x"] = 0.538, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86930 }, ["questLines"] = { { ["id"] = 5960, ["name"] = "Haranir Never Say Die", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91551] = { ["id"] = 91551, ["name"] = "De-nest-stration", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91550, 91551, 91552, 91553 }, ["description"] = "If mom and dad find out, we are going to be stuck on fish gutting duty for the rest of our lives! The elders keep telling us that fear is only useful if it sharpens the mind. Right now, we need clarity, not panic. We have to get rid of those nests . Maybe if they are gone, we can eventually find the one they took Shao'mal to. And this way, we can finally drive off those stupid birds! We're going to find him. Will you help us?", ["objectivesText"] = "Search 5 Petalwing Nests for Shao'mal in Harandar .", ["rewardGold"] = 170800, ["rewardXP"] = 6085, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 247658, ["x"] = 0.538, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 247736, ["x"] = 0.572, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 91550 }, ["questLines"] = { { ["id"] = 5960, ["name"] = "Haranir Never Say Die", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91552] = { ["id"] = 91552, ["name"] = "Feathered Fury", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91550, 91551, 91552, 91553 }, ["description"] = "This would have never happened if those stupid petalwings weren't here! Scare them off, chase them, whatever it takes--we just can't let them stay here. If they stay, they'll just keep hurting people. We can't let that happen.", ["objectivesText"] = "Defeat 8 Petalwings in Harandar .", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 247658, ["x"] = 0.538, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 247736, ["x"] = 0.572, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 91550 }, ["questLines"] = { { ["id"] = 5960, ["name"] = "Haranir Never Say Die", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91553] = { ["id"] = 91553, ["name"] = "Haranir Never Say Die!", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91550, 91551, 91552, 91553 }, ["description"] = "That's the one! The big one! The one that took him! We didn't stop it before. But this time, we will. We are haranir. And haranir never back down. Haranir never give up. We're bringing him back. And we're ending this. Are you with me?", ["objectivesText"] = "Defeat the Behemoth Petalwing in Harandar .", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 260439 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3370, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 247736, ["x"] = 0.572, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 248574, ["x"] = 0.584, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 91551, 91552 }, ["questLines"] = { { ["id"] = 5960, ["name"] = "Haranir Never Say Die", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91555] = { ["id"] = 91555, ["name"] = "Defenders of the Vale", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91490, 91555, 91582, 91785, 91927, 91937, 91981, 92119, 92184, 92582 }, ["objectivesText"] = "Weary Defenders reinvigorated", ["rewardXP"] = 13690, ["starts"] = { { ["x"] = 0.587, ["y"] = 0.528, ["mapID"] = 2413 } }, ["ends"] = { { ["x"] = 0.587, ["y"] = 0.528, ["mapID"] = 2413 } }, ["coords"] = { ["mapID"] = 2413, ["x"] = 0.587, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15355 } }, ["questType"] = "world", ["questLines"] = { { ["id"] = 5983, ["name"] = "Harandar - World Quests / Repeatables", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 6, ["objectID"] = 247648, ["text"] = "Weary Defenders reinvigorated" } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[91556] = { ["id"] = 91556, ["name"] = "Loa's Flame", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91069, 91070, 91071, 91556, 94867 }, ["description"] = "I will have to take what's left of de supplies back on foot. De boat... it's no good now. De hull's cracked, and de frame's split. Won't carry another soul across de water. But it'll still serve one final purpose. It can be his pyre. We will burn it, de weapons, de armor he wore--everything with him. Vengeance is done. Now we let de fire take him to de loa and to his rest.", ["objectivesText"] = "Prepare the funeral pyre for Tolbani in Atal'Abasi. Progress: Not long now, Tolbani.", ["rewardGold"] = 309800, ["rewardXP"] = 12170, ["rewardItems"] = { 264470, 264587 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3354, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 245669, ["x"] = 0.53, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 245669, ["x"] = 0.53, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91069, 91070, 91071 }, ["questLines"] = { { ["id"] = 5939, ["name"] = "Vengeance for Tolbani", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91557] = { ["id"] = 91557, ["name"] = "Message to the Molt", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91557, 91558, 91559, 91560, 91561, 93801 }, ["series"] = { 91559 }, ["description"] = "Ah, champion! There are so many unique specimens to identify and catalogue here that I can't keep up. Speaking of which, Lady Darkglen took time out of her busy schedule and coordinated an expedition to a particularly dangerous region north of here. I trust in her power, but I've not heard from her or her team in a while and am growing concerned. With any luck, they are simply caught up in their own research. That being said, would you please find Lady Darkglen in the Molt and check in on her?", ["objectivesText"] = "Find Lady Darkglen in the Molt.", ["rewardGold"] = 31500, ["rewardXP"] = 1605, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3389, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 248040, ["x"] = 0.354, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 247664, ["x"] = 0.358, ["y"] = 0.482 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.354, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86565 }, ["nextQuests"] = { 91558, 91559 }, ["questLines"] = { { ["id"] = 6028, ["name"] = "Pathogenic Problem", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[91558] = { ["id"] = 91558, ["name"] = "Pestilent Petals", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91557, 91558, 91559, 91560, 91561, 93801 }, ["description"] = "A strange pathogenic presence has infected my fellow ren'dorei. When we arrived, I was awestruck by the colorful vibrancy of this decay-filled valley and its many blood-stained flowers. I had hoped to gather some for my collection... to study of course, but this pathogen was living in the same pestilent pools these blood petals thrive in. Are they naturally resilient, or do they have purifying qualities we can harness for a cure? Dear <name>, please, cautiously gather blood petals for my research.", ["objectivesText"] = "Collect 10 Mature Blood Petals in the Molt. Progress: Did you collect enough yet?", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 251902 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 247664, ["x"] = 0.358, ["y"] = 0.482 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 247674, ["x"] = 0.346, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.358, ["y"] = 0.482 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 91557 }, ["questLines"] = { { ["id"] = 6028, ["name"] = "Pathogenic Problem", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[91559] = { ["id"] = 91559, ["name"] = "Virulent Vermin", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91557, 91558, 91559, 91560, 91561, 93801 }, ["series"] = { 91557 }, ["description"] = "The pathogen appears to spread unevenly among the Molt's wildlife. When my fellow ren'dorei were infected, they grew confused and unresponsive. The local fauna appear more resistant. I suspect some of the Molt's denizens have a stronger resistance than others. Perhaps by examining these beasts we can extract elements for a curative elixir. Could you gather livers from the creatures nearby?", ["objectivesText"] = "Gather 6 Specialized Livers from creatures within the Molt. Progress: How goes the hunt? Have you gathered what we need?", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 251905 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 247664, ["x"] = 0.358, ["y"] = 0.482 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 247674, ["x"] = 0.346, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.358, ["y"] = 0.482 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 91557 }, ["questLines"] = { { ["id"] = 6028, ["name"] = "Pathogenic Problem", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[91560] = { ["id"] = 91560, ["name"] = "Expunging Explorers", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91557, 91558, 91559, 91560, 91561, 93801 }, ["description"] = "Let us hope we are able to concoct a cure from the reagents you acquired. I have already prepared the base potion, but now we need to carefully mix in the blood petals and livers you procured. With some calculated determination and a bit of luck, we should be able to craft an antidote and administer it to the afflicted ren'dorei scouts nearby. <name>, assist Blocciniux by mixing in the gathered ingredients.", ["objectivesText"] = "Craft an antidote and cure the infected ren'dorei in the Molt. Progress: Were you successful? Did the antidote work?", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 253518 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 247674, ["x"] = 0.346, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 247674, ["x"] = 0.346, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 91559 }, ["questLines"] = { { ["id"] = 6028, ["name"] = "Pathogenic Problem", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[91561] = { ["id"] = 91561, ["name"] = "Bloodborne Pathogen", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91557, 91558, 91559, 91560, 91561, 93801 }, ["description"] = "The bloodborne pathogen has mutated! The ooze-like carriers of this pathogen usually die quickly, but this new variant is stable even without a host. If it escapes from here, it could infect more ren'dorei and spread across Voidstorm , or worse yet, Azeroth. Our entire operation is at risk. We must stop this mutated variant before it spreads!", ["objectivesText"] = "Destroy the Mutated Pathogen in the Molt. Progress: Have you contained the spread of this deadly pathogen?", ["rewardGold"] = 619600, ["rewardXP"] = 16055, ["rewardItems"] = { 264299, 264300, 264301, 264302 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3389, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 247674, ["x"] = 0.346, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 247674, ["x"] = 0.346, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 91560, 93801 }, ["questLines"] = { { ["id"] = 6028, ["name"] = "Pathogenic Problem", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[91563] = { ["id"] = 91563, ["name"] = "Halazzi's Hunt", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91563 }, ["description"] = "All of these spiders... There must be someting dat we are missing. Halazzi knew exactly how to reveal them, though. Go to Halazzi's temple. I have no doubt that there is more to dis. Seek out his loa speaker.", ["objectivesText"] = "Seek out the Loa Speaker in Halazzi's Temple.", ["rewardGold"] = 31200, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3354, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 247014, ["x"] = 0.36, ["y"] = 0.248 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 250068, ["x"] = 0.322, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.36, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91407 } },
[91565] = { ["id"] = 91565, ["name"] = "Voidscar Arena: The Grief Spire", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 91565, 91583, 91597, 91598, 91599, 91600, 91605, 91606, 91694 }, ["description"] = "You, hero! Vidious here wars with his nemesis, Ziadan, who has brought the most cutthroat, volatile members of the Horde here to fight for her. Murderers and traitors! The leaders of the Alliance do not listen to our calls for action and vengeance! We must take matters into our own hands and support Vidious . <Amari looks you up and down and raises an eyebrow.> And if it is not hatred of the Horde that drives you, consider what valuable information you may glean by helping a powerful domanaar.", ["objectivesText"] = "Use the portal to the Grief Spire and report to Vidious .", ["rewardGold"] = 34100, ["rewardXP"] = 1605, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3389, ["amount"] = 10 }, { ["id"] = 3410, ["amount"] = 40 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 257479, ["x"] = 0.408, ["y"] = 0.84 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 247375, ["x"] = 0.74, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.84 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 86509 }, ["questLines"] = { { ["id"] = 5964, ["name"] = "Breaking the Triad", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[91566] = { ["id"] = 91566, ["name"] = "Voidscar Arena: The Hate Spire", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 91566, 91603, 91606, 91694, 94844, 94845, 94848, 94849, 94855 }, ["description"] = "Lok'tar ogar, <class>. This domanaar, Ziadan , wars her old foe, Vidious, who has brought the most bloodthirsty, vengeful members of the Alliance here to Slayer's Rise to fight in his name. Ziadan now gives the Horde a chance to stand up for our honor. Our leaders may not sanction this conflict, but when have we let anyone keep us from fighting the good fight? Even if you have no grievance with the Alliance, Ziadan 's efforts keep Vidious from turning his eye on Azeroth. Report to her for your orders.", ["objectivesText"] = "Use the portal to the Hate Spire and report to Ziadan .", ["rewardGold"] = 34100, ["rewardXP"] = 1605, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3389, ["amount"] = 10 }, { ["id"] = 3410, ["amount"] = 40 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 257478, ["x"] = 0.348, ["y"] = 0.805 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 247374, ["x"] = 0.235, ["y"] = 0.542 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.348, ["y"] = 0.805 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 86509 }, ["questLines"] = { { ["id"] = 5964, ["name"] = "Breaking the Triad", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
