[91583] = { ["id"] = 91583, ["name"] = "Voidscar Arena: The Bastion of Valor", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 91565, 91583, 91597, 91598, 91599, 91600, 91605, 91606, 91694 }, ["description"] = "Ziadan recently added your great foes, the Horde, to her ranks. However, it is not your fellow mortals that I see sieging my home. No, I see monsters of Voidstorm , twisted and empowered, instead. Something is afoot. Has Ziadan added yet another new force to her army? Go and fight these monsters. Bring me any clues you find as to the source of their newfound power.", ["objectivesText"] = "Collect 12 Spiteful Shadowgraft from wild creatures in the Bastion of Valor. Progress: What have you found?", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 247422 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 }, { ["id"] = 3410, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 247375, ["x"] = 0.74, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 256782, ["x"] = 0.508, ["y"] = 0.585 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.74, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 91565 }, ["questLines"] = { { ["id"] = 5964, ["name"] = "Breaking the Triad", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[91585] = { ["id"] = 91585, ["name"] = "Fresh from the Garden", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91585, 91586, 91587, 91588, 91589 }, ["description"] = "Age has caught up with me this morning and I have pulled something. < Yu'relen clutches his back.> Still, our village meal must be prepared. Otherwise, it will mean the loss of much more than just an empty stomach. If you would gather some ingredients for the meal, your aid would not go unappreciated.", ["objectivesText"] = "Collect 6 Frillfish Fillet and 4 Root Drift Jelly in Harandar . Progress: I hope you brought back a good harvest.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 246923, 246924 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 247936, ["x"] = 0.408, ["y"] = 0.232 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 247936, ["x"] = 0.408, ["y"] = 0.232 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.232 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86930 }, ["questLines"] = { { ["id"] = 5966, ["name"] = "Harandar's Kitchen", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91586] = { ["id"] = 91586, ["name"] = "Soil-Based Alternatives", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91585, 91586, 91587, 91588, 91589 }, ["description"] = "This meal is more than tradition--it is a promise. The haranir, rutaani, and fungarians share no love, but in Har'mara they share this table. To honor that pact, each must be fed in their own way. That is what this meal means. For the rutaani, they will need nutrient-rich soil as they draw sustenance through their roots. A few bags of it should do.", ["objectivesText"] = "Collect 6 Nutrient-Rich Soil in Harandar . Progress: I hope you bring news of good soil.", ["rewardGold"] = 170800, ["rewardXP"] = 6085, ["rewardItems"] = { 246926 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 247936, ["x"] = 0.408, ["y"] = 0.232 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 247936, ["x"] = 0.408, ["y"] = 0.232 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.232 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86930 }, ["questLines"] = { { ["id"] = 5966, ["name"] = "Harandar's Kitchen", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91587] = { ["id"] = 91587, ["name"] = "Carcass Cuisine", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91585, 91586, 91587, 91588, 91589 }, ["description"] = "The fungarians are caretakers of decay, transforming death into life's renewal. They require a sporeglider carcass to sustain their vast community. There is one--larger than most--that has taken to warding off the root drifters we need to sustain our village. Its end will feed many, and ease our burden. Balance, in more ways than one.", ["objectivesText"] = "Defeat the Sporeglider Bloomterror in Harandar . Progress: Did you bring the rind?", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 246942 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3370, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 247936, ["x"] = 0.408, ["y"] = 0.232 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 247936, ["x"] = 0.408, ["y"] = 0.232 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.232 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86930 }, ["questLines"] = { { ["id"] = 5966, ["name"] = "Harandar's Kitchen", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91588] = { ["id"] = 91588, ["name"] = "Harandar's Kitchen", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91585, 91586, 91587, 91588, 91589 }, ["description"] = "Now comes the true work: preparing what's been gathered. The vegetables must be washed, the bones removed, and the fish roasted. A shared meal is only worthy if made with care. Only then may the meal carry the weight of peace.", ["objectivesText"] = "Prepare and cook the meal in Harandar . Progress: How is the preparation coming along?", ["rewardGold"] = 309800, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 247936, ["x"] = 0.408, ["y"] = 0.232 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 247936, ["x"] = 0.408, ["y"] = 0.232 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.232 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 91585, 91586, 91587 }, ["questLines"] = { { ["id"] = 5966, ["name"] = "Harandar's Kitchen", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91589] = { ["id"] = 91589, ["name"] = "Root Dash Delivery", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91585, 91586, 91587, 91588, 91589 }, ["description"] = "It's simple fare, but made with care and meaning. Please, take it to the gathering place. I am sure the villagers will show up when the food comes. Despite the simplicity, if it brings quiet among them, it has done its part.", ["objectivesText"] = "Set up the communal meal in Harandar . Progress: Once the meal is set, our job will be done for today.", ["rewardGold"] = 170800, ["rewardXP"] = 6085, ["rewardItems"] = { 264178 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3370, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 247936, ["x"] = 0.408, ["y"] = 0.232 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 248117, ["x"] = 0.366, ["y"] = 0.268 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.232 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 91588 }, ["questLines"] = { { ["id"] = 5966, ["name"] = "Harandar's Kitchen", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
