[91597] = { ["id"] = 91597, ["name"] = "Voidscar Arena: For My Alliance", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 91565, 91583, 91597, 91598, 91599, 91600, 91605, 91606, 91694 }, ["description"] = "My bastion is besieged by Ziadan once more! You Alliance have proven to me you are strong. I am eager to see you in action upon the battlefield. My own forces could use a taste of your courage. Take this Voidclarion and embolden the void underlings that fight for me. Let them know they have your backing. Let them feel the glory of your Alliance!", ["objectivesText"] = "Empower 8 Griefbound forces at the Bastion of Valor in Slayer's Rise.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 260948 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 }, { ["id"] = 3410, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 247375, ["x"] = 0.74, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 256782, ["x"] = 0.508, ["y"] = 0.585 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.74, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 91565 }, ["questLines"] = { { ["id"] = 5964, ["name"] = "Breaking the Triad", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[91598] = { ["id"] = 91598, ["name"] = "Voidscar Arena: Pre-Provoked Violence", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 91565, 91583, 91597, 91598, 91599, 91600, 91605, 91606, 91694 }, ["series"] = { 91599, 91600 }, ["description"] = "So, Ziadan would stoop so low as to use shadowgraft? Can she not adequately stir the bloodlust of her Horde minions? She's lost her touch. I need no such army to overpower her. I have you. Show her how it's done. Decimate her forces before they reach beyond the bounds of Slayer's Rise. They could threaten your precious mission here, after all.", ["objectivesText"] = "Slay Void creatures or players in the Bastion of Might in Slayer's Rise.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 }, { ["id"] = 3410, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 256782, ["x"] = 0.508, ["y"] = 0.585 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 256782, ["x"] = 0.508, ["y"] = 0.585 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.585 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 91583, 91597 }, ["questLines"] = { { ["id"] = 5964, ["name"] = "Breaking the Triad", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[91599] = { ["id"] = 91599, ["name"] = "Voidscar Arena: A Familiar Grudge", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 91565, 91583, 91597, 91598, 91599, 91600, 91605, 91606, 91694 }, ["series"] = { 91598, 91600 }, ["description"] = "It is time to take the fight to Ziadan. She undoubtedly has her own favorite pet--someone from your world who takes this conflict personally. She is particularly fond of the flavors of rage. I prefer aching, heart-wrenching grief, myself, and we shall prove which fuels you mortals with greater strength. Among their forces is a dark warlock that has slain many of your kind. I've tasted their rage in the air. Go. Savor the fight.", ["objectivesText"] = "Slay Manus Deathwake at the Bastion of Might in Slayer's Rise.", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3389, ["amount"] = 100 }, { ["id"] = 3410, ["amount"] = 400 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 256782, ["x"] = 0.508, ["y"] = 0.585 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 256782, ["x"] = 0.508, ["y"] = 0.585 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.585 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 91583, 91597 }, ["questLines"] = { { ["id"] = 5964, ["name"] = "Breaking the Triad", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[91600] = { ["id"] = 91600, ["name"] = "Voidscar Arena: Setting It Aside", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 91565, 91583, 91597, 91598, 91599, 91600, 91605, 91606, 91694 }, ["series"] = { 91598, 91599 }, ["description"] = "I knew shadowgrafting was beneath Ziadan. I would not spend eons locked in conflict with one so uncouth. Therefore, our little game has an uninvited guest. Not you, of course. We love watching you kill for us. To the far north is the Voidscar Arena. The last time another domanaar tried to come between us, they built that citadel. It has laid empty for ages. If another domanaar intends to challenge us, they will have staged their forces there.", ["objectivesText"] = "Meet the domanaar at the Voidscar Arena in Slayer's Rise.", ["rewardGold"] = 31200, ["rewardXP"] = 1605, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3389, ["amount"] = 10 }, { ["id"] = 3410, ["amount"] = 40 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 256782, ["x"] = 0.508, ["y"] = 0.585 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 256815, ["x"] = 0.535333, ["y"] = 0.214667 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.585 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 91598, 91599 }, ["questLines"] = { { ["id"] = 5964, ["name"] = "Breaking the Triad", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
