[91602] = { ["id"] = 91602, ["name"] = "Prey: Apex Predator", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16534, ["mapID"] = 2405, ["storyline"] = { 91207, 91458, 91523, 91590, 91591, 91592, 91594, 91595, 91596, 91601, 91602, 91604 }, ["objectivesText"] = "Defeat enemies to lure out your Prey target Creatures slain Ambush defeated", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16534 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5954, ["name"] = "Prey WQs", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 15, ["amount"] = 1, ["objectID"] = 0, ["text"] = "Defeat enemies to lure out your Prey target" }, { ["orderIndex"] = 1, ["type"] = 21, ["amount"] = 13, ["objectID"] = 5377, ["text"] = "Creatures slain" }, { ["orderIndex"] = 2, ["type"] = 0, ["amount"] = 10, ["objectID"] = 246605, ["text"] = "Ambush defeated" } }, ["db2LabelIDs"] = { 6017 }, ["db2PoiUiMapID"] = 2437, ["db2QuestInfoID"] = 295, ["db2QuestInfoName"] = "Prey World Quest" },
[91603] = { ["id"] = 91603, ["name"] = "Voidscar Arena: Two Against One", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 91566, 91603, 91606, 91694, 94844, 94845, 94848, 94849, 94855 }, ["series"] = { 91605, 91606 }, ["description"] = "You. Alliance weakling. Shadowgraft requires a potent font to power it--likely more than one, given this many creatures. They will be nearby. Destroy the power sources, then meet us on the next ridge. Remember: if this domanaar succeeds, their conquest will not end in Slayer's Rise. They will find a way to your homeworld. They would shadowgraft Azeroth herself. Put an end to this. Meanwhile, I suppose I shall relish in this opportunity to observe Vidious's weaknesses up close.", ["objectivesText"] = "Drain the Shadowgraft Graftnodes atop the Voidscar Arena in Slayer's Rise. Progress: Are they depleted?", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 }, { ["id"] = 3410, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 256813, ["x"] = 0.535, ["y"] = 0.215 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 256901, ["x"] = 0.535, ["y"] = 0.112 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.215 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 91600, 94855 }, ["questLines"] = { { ["id"] = 5964, ["name"] = "Breaking the Triad", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[91604] = { ["id"] = 91604, ["name"] = "Prey: Apex Predator", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16534, ["mapID"] = 2405, ["storyline"] = { 91207, 91458, 91523, 91590, 91591, 91592, 91594, 91595, 91596, 91601, 91602, 91604 }, ["objectivesText"] = "Defeat enemies to lure out your Prey target Creatures slain Ambush defeated", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16534 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5954, ["name"] = "Prey WQs", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 15, ["amount"] = 1, ["objectID"] = 0, ["text"] = "Defeat enemies to lure out your Prey target" }, { ["orderIndex"] = 1, ["type"] = 21, ["amount"] = 13, ["objectID"] = 5377, ["text"] = "Creatures slain" }, { ["orderIndex"] = 2, ["type"] = 0, ["amount"] = 10, ["objectID"] = 246605, ["text"] = "Ambush defeated" } }, ["db2LabelIDs"] = { 6017 }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413, ["db2QuestInfoID"] = 295, ["db2QuestInfoName"] = "Prey World Quest" },
[91605] = { ["id"] = 91605, ["name"] = "Voidscar Arena: The Wrong Side", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 91565, 91583, 91597, 91598, 91599, 91600, 91605, 91606, 91694 }, ["series"] = { 91603, 91606 }, ["description"] = "Indeed, the Voidscar Arena is crawling with Void once again. A domanaar rules here, I have no doubt. They have not yet emerged to parlay. Our mysterious interloper must not be present. That is well. Let's have you put an end to this charade. Destroy their forces. Destroy their resources. And turn their tools against them. Make them feel the disdain I feel for them. Ziadan and I shall investigate this interloper.", ["objectivesText"] = "Slay 12 Spiteful monsters, use 4 Graftshaper Tools, and destroy 6 Shadowgraft Energy Containers near the top of Voidscar Arena in Slayer's Rise.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 }, { ["id"] = 3410, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 256815, ["x"] = 0.535333, ["y"] = 0.214667 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 256885, ["x"] = 0.536, ["y"] = 0.112 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.535333, ["y"] = 0.214667 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 91600, 94855 }, ["questLines"] = { { ["id"] = 5964, ["name"] = "Breaking the Triad", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[91606] = { ["id"] = 91606, ["name"] = "Voidscar Arena: Clearing House", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 91565, 91566, 91583, 91597, 91598, 91599, 91600, 91603, 91605, 91606, 91694, 94844, 94845, 94848, 94849, 94855 }, ["series"] = { 91603, 91605 }, ["description"] = "A waste of a great monstrosity. Imagine its cunning were it not frenzied! It would have made a fine addition to my collection. The shadowgrafting must end. I doubt this domanaar is doing the work himself. There must be a grafter nearby. While Ziadan and I weaken this monster, find and slay the grafter. Then these shadowgrafted monsters will never breach your precious world. If nothing else, that will finally draw out our enemy.", ["objectivesText"] = "Slay Trelus the Grafter at the top of the Voidscar Arena in Slayer's Rise. Progress: Is the grafter dead?", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3389, ["amount"] = 100 }, { ["id"] = 3410, ["amount"] = 400 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 256885, ["x"] = 0.536, ["y"] = 0.112 }, { ["mapID"] = 2444, ["npcID"] = 256901, ["x"] = 0.535, ["y"] = 0.112 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 256885, ["x"] = 0.536, ["y"] = 0.112 }, { ["mapID"] = 2444, ["npcID"] = 256901, ["x"] = 0.535, ["y"] = 0.112 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.112 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 91603, 91605 }, ["questLines"] = { { ["id"] = 5964, ["name"] = "Breaking the Triad", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
