[91614] = { ["id"] = 91614, ["name"] = "Focusing the Energies", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 42049, 42050, 42051, 42053, 42054, 42055, 42056, 42365, 42432, 43403, 91614 }, ["description"] = "In addition to shards of nightmare, we need Blood of Sargeras to reactivate the portal to the Rift of Aln. This rare reagent can be obtained from around the Broken Isles. Rumor has it that emissaries are in search of hardened adventurers, and may offer these in reward.", ["objectivesText"] = "Collect 3 Blood of Sargeras.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["npcID"] = 103832, ["x"] = 0.448, ["y"] = 0.504, ["mapID"] = 747 } }, ["ends"] = { { ["npcID"] = 101195, ["x"] = 0.448, ["y"] = 0.516, ["mapID"] = 747 } }, ["coords"] = { ["x"] = 0.448, ["y"] = 0.504, ["source"] = "quest_giver", ["mapID"] = 747 }, ["mapCandidates"] = { ["npc"] = { 747 }, ["zone"] = { 7846 } }, ["questType"] = "standard", ["sourceQuests"] = { 42046, 42047, 42048 }, ["questLines"] = { { ["id"] = 5885, ["name"] = "The Eternal Dream III", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5885, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
