[91616] = { ["id"] = 91616, ["name"] = "Required Reagents", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42133, 42402, 42405, 42408, 42415, 42654, 42655, 42656, 42657, 42658, 42659, 43182, 44680, 91616 }, ["description"] = "The Sentinels know of a trusted and talented enchanter who specializes in enchantments that affect demons. She provides her services for free to the Sentinels, but she does require specific reagents to perform her enchantments.", ["objectivesText"] = "Collect the required crafting reagents.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 108455, ["x"] = 0.466571, ["y"] = 0.345143 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 108455, ["x"] = 0.466571, ["y"] = 0.345143 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.466571, ["y"] = 0.345143 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["sourceQuests"] = { 42405 }, ["questLines"] = { { ["id"] = 5850, ["name"] = "Watchers in the Wild III", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5850, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[91618] = { ["id"] = 91618, ["name"] = "A Few Things First", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 45770, 46069, 46070, 46071, 46074, 46083, 91618, 94847 }, ["series"] = { 45770, 46069, 46070, 46071, 46074, 46081, 46083, 94847 }, ["description"] = "Lately I've been working with the ore of this land, leystone it's called. I've found its qualities to hold remarkable strength and durability. We'll need a lot of it for this. There is felslate, but that's probably too tainted for what you're looking to do with this barding. You know, I also like to adorn my pieces with something sparkly, like a jewel. I've heard that the elves of Suramar have particularly beautiful ones. Perhaps you could acquire one for this project.", ["objectivesText"] = "Obtain 1 Leystone Ore and a Suramarian Sapphire . Progress: I doubt you'll have a problem getting the leystone, but the sapphire might be a bit harder to acquire.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 123918, 140328, 147768 }, ["starts"] = { { ["x"] = 0.444, ["y"] = 0.288, ["mapID"] = 627, ["npcID"] = 92183 } }, ["ends"] = { { ["x"] = 0.444, ["y"] = 0.288, ["mapID"] = 627, ["npcID"] = 92183 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.444, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92183, ["questTurnInID"] = 92183, ["questType"] = "standard", ["sourceQuests"] = { 46071 }, ["questLines"] = { { ["id"] = 302, ["name"] = "Class Mount: Paladin", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 302, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[91619] = { ["id"] = 91619, ["name"] = "Blood of Sargeras", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 139, ["mapID"] = 23, ["storyline"] = { 43534, 43697, 43698, 43699, 43700, 43701, 43785, 91619 }, ["description"] = "We will require a powerful reagent to bind the magic in our weapons and armor. A rare material that will do just the trick is Blood of Sargeras. We will need a plentiful quantity. Bring me whatever you can muster.", ["objectivesText"] = "Collect Blood of Sargeras.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["ends"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.523, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90250, ["questTurnInID"] = 90250, ["questType"] = "standard", ["sourceQuests"] = { 43492, 43933 }, ["questLines"] = { { ["id"] = 5827, ["name"] = "Path of the Light III", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5827, ["questLineOrder"] = 3 } }, ["db2PoiUiMapID"] = 24 },
[91620] = { ["id"] = 91620, ["name"] = "Noggenfogger's Reasonable Request", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 42684, 42730, 43468, 43829, 43841, 43852, 43958, 44041, 44116, 44117, 44155, 44177, 44178, 44180, 44181, 44183, 91620 }, ["description"] = "Oh, the gall of that little green twerp! Marin Noggenfogger is blackmailing us. He says that if we do not meet his \"very reasonable requisition request\", he is going to close off access to the crucible. Marin's asking for a hefty amount of Aethril. He said something about you recently holding a blade to his throat and that he's simply returning the favor. Of course, if you would rather, I can eliminate him.", ["objectivesText"] = "Collect Aethril.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127837 }, ["starts"] = { { ["x"] = 0.408, ["y"] = 0.753, ["mapID"] = 626, ["npcID"] = 98102 } }, ["ends"] = { { ["x"] = 0.408, ["y"] = 0.753, ["mapID"] = 626, ["npcID"] = 98102 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.408, ["y"] = 0.753 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 98102, ["questTurnInID"] = 98102, ["questType"] = "standard", ["sourceQuests"] = { 44181 }, ["questLines"] = { { ["id"] = 5853, ["name"] = "Saga of the Shadowblade I", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5853, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
