[91624] = { ["id"] = 91624, ["name"] = "Spark of Starlight", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 91624 }, ["description"] = "A vision of starlight permeates your mind. Custodian Khubon might have more information regarding these Fractured Sparks of Starlight.", ["objectivesText"] = "Speak to Custodian Khubon in Dornogal .", ["rewardGold"] = 30900, ["rewardItems"] = { 231757 }, ["starts"] = { { ["npcID"] = 223533 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223533, ["x"] = 0.498, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 223533, ["questType"] = "standard" },
[91627] = { ["id"] = 91627, ["name"] = "Saltheril's Haven", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 91627, 91628, 91629, 91693 }, ["description"] = "<name>, I presume? Very good. Your reputation precedes you. Lord Saltheril sends his most sincere greetings, along with a cordial invitation to join him at his estate south of Silvermoon. A portion of the grounds have been carved out as a decadent haven for those seeking refined company and pleasant conversation. He believes you would bring a... unique perspective. <He looks you over with a hint of polite disdain.> Receiving an invitation is a rare honor. His lordship hopes you will accept.", ["objectivesText"] = "Speak to Lord Saltheril at Saltheril's Haven.", ["rewardGold"] = 31200, ["rewardXP"] = 1470, ["rewardItems"] = { 23500 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 247955, ["x"] = 0.455, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240832, ["x"] = 0.426, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2393, 2395 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5967, ["name"] = "Saltheril's Haven", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395, ["db2QuestInfoID"] = 282, ["db2QuestInfoName"] = "Important Quest" },
[91628] = { ["id"] = 91628, ["name"] = "Honored Guests", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91627, 91628, 91629, 91693 }, ["description"] = "I am pleased you could join us. Today marks the start of a very special occasion. The sin'dorei are no strangers to the war table, but its aristocracy prefers to play more coy. In wartime, the crown sends representatives to curry favor with the nobles. If they are pleased, they might lend gold to the war effort. It is very much like courting a lover, with all the jealous games you might imagine. So let us play the game, shall we? Deliver these invitations while we finish preparations here.", ["objectivesText"] = "Deliver Lord Saltheril 's invitations to the Magisters, Blood Knights, Farstriders, and \"traders\" in Silvermoon. Progress: Your presence is already turning heads. This will be quite the spectacle.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240832, ["x"] = 0.426, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240832, ["x"] = 0.426, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91627 }, ["questLines"] = { { ["id"] = 5967, ["name"] = "Saltheril's Haven", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91629] = { ["id"] = 91629, ["name"] = "High Esteem", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91627, 91628, 91629, 91693 }, ["description"] = "Invitations to my Haven are highly exclusive, especially at a time like this. Extending an offer, even a temporary one, is a great honor. My favor carries quite a bit of weight amongst the aristocracy. If I invite an ally of one of our representatives, it suggests I think highly of them--and if I think highly of them, so too will our noble guests. But is it not terribly fun if I let you choose an invitation instead? Go peruse any enticements they may offer, then make your selection.", ["objectivesText"] = "Visit the vendors at Saltheril's Soiree, then choose an ally of the Magisters, Blood Knights, Farstriders, or Shades of the Row to invite to Saltheril's Soiree this week. Your choice will determine which faction will offer \"Fortify the Runestones\" to your Warband this week. Progress: Pick any invitation you desire.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 238987, 246692, 250772, 258505, 259027, 259074, 259075, 259076, 259079, 259080, 259081, 259083, 259087, 259088, 259089, 259090, 259364, 259367, 259375, 263203, 263212, 263216, 263224, 263225, 264907, 264909, 264996, 264997, 265997 }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240832, ["x"] = 0.426, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240832, ["x"] = 0.426, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91628 }, ["questLines"] = { { ["id"] = 5967, ["name"] = "Saltheril's Haven", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91630] = { ["id"] = 91630, ["name"] = "Stolen Sight", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2537, ["storyline"] = { 91403, 91404, 91405, 91406, 91407, 91408, 91409, 91410, 91411, 91412, 91630 }, ["description"] = "I can explain, I swear it! I concealed my knowledge of Shadra before because so many people assume she is an evil force. Our lady is merciless, but only to her enemies. When de Witherbark left de Hinterlands, we had to leave our temple of Shadra'Alor. I brought two of her relics with me: de eye and de fang. De Vilebranch stole de fang. Dey are near where I hid the Eye of Shadra , collectin' venom from her children! Please kill de Vilebranch trespassing in the crypt. We can't let dem find de eye.", ["objectivesText"] = "Defeat the Vilebranch leading the attack on Shadra's children and recover the Eye of Shadra . Progress: I can understand why dey want de venom, but de artifacts are just for communin' with Shadra. What would dey need with them?", ["rewardGold"] = 322100, ["rewardXP"] = 11765, ["rewardItems"] = { 246744 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2537, ["npcID"] = 247254, ["x"] = 0.434, ["y"] = 0.536 } }, ["ends"] = { { ["mapID"] = 2537, ["npcID"] = 247254, ["x"] = 0.434, ["y"] = 0.536 } }, ["coords"] = { ["mapID"] = 2537, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.536 }, ["mapCandidates"] = { ["npc"] = { 2537 }, ["zone"] = {} }, ["questType"] = "standard", ["sourceQuests"] = { 91408 }, ["questLines"] = { { ["id"] = 5950, ["name"] = "A Venomous History", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
