[91691] = { ["id"] = 91691, ["name"] = "The Vanishing of Iridikron", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14514, ["mapID"] = 2112, ["storyline"] = { 91691, 91695 }, ["description"] = "As you traveled through Zaralek caverns, Chronormu and I confronted Iridikron and the Infinite Dragonflight. While we defeated the Infinite Dragonflight's champion, Chrono-Lord Deios, I fear Iridikron escaped. Allow me to show you what happened, for it gives us a clue of what must be done next.", ["objectivesText"] = "See Nozdormu 's vision of the conflict with Iridikron.", ["rewardGold"] = 29200, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187669, ["x"] = 0.610286, ["y"] = 0.389143 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 187669, ["x"] = 0.610286, ["y"] = 0.389143 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.610286, ["y"] = 0.389143 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 75417 }, ["questLines"] = { { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 71, ["flags"] = 0 }, { ["id"] = 6214, ["name"] = "Welcome to the Waking Shore", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 }, { ["id"] = 346, ["title"] = "The Azure Span", ["questLineID"] = 6214, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[91693] = { ["id"] = 91693, ["name"] = "The Subtle Game", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91627, 91628, 91629, 91693 }, ["description"] = "Appearances are everything. If the court sees that I favor a certain group, they will follow suit. Take these tokens of my favor and hand them out to our honored guests as you see fit. I suspect they may invite you to partake in their plans and share in the profits, if you choose to align yourself with their cause.", ["objectivesText"] = "Hand out 3 tokens of Saltheril's Favor to the factions you wish to aid this week. Progress: Do endeavor not to keep our guests waiting in suspense.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240832, ["x"] = 0.426, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240832, ["x"] = 0.426, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91629 }, ["questLines"] = { { ["id"] = 5967, ["name"] = "Saltheril's Haven", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91694] = { ["id"] = 91694, ["name"] = "Voidscar Arena: Breaking the Triad", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15958, ["mapID"] = 2444, ["storyline"] = { 91565, 91566, 91583, 91597, 91598, 91599, 91600, 91603, 91605, 91606, 91694, 94844, 94845, 94848, 94849, 94855 }, ["description"] = "That glint in your eye! You've already identified me as an enemy and are thinking about how to slay me, yes? Good. I sent my forces to Ziadan and Vidious 's bastions to overthrow them. Then, Xal'atath's bidding pulled me away and I missed all the action. Fortunately, you are here now. You seem like even greater entertainment than watching these two smitten fools refuse to actually end one another. Come, then! I will prepare my arena and we will put on a real show! Slay me, if you can!", ["objectivesText"] = "Enter the Voidscar Arena and defeat Charonus .", ["rewardGold"] = 1366400, ["rewardXP"] = 25690, ["rewardItems"] = { 251221, 251222, 251228, 251234, 251235, 252258 }, ["rewardChoices"] = { 251221, 251222, 251228, 251234, 251235, 252258 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3389, ["amount"] = 250 }, { ["id"] = 3410, ["amount"] = 1000 } }, ["starts"] = { { ["npcID"] = 248015, ["mapID"] = 2444, ["x"] = 0.536037, ["y"] = 0.109783 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 257130, ["x"] = 0.408, ["y"] = 0.838 }, { ["mapID"] = 2444, ["npcID"] = 257132, ["x"] = 0.348, ["y"] = 0.805 }, { ["npcID"] = 248015, ["mapID"] = 2444, ["x"] = 0.536037, ["y"] = 0.109783 } }, ["coords"] = { ["source"] = "quest_giver", ["mapID"] = 2444, ["x"] = 0.536037, ["y"] = 0.109783 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 91606 }, ["questLines"] = { { ["id"] = 5964, ["name"] = "Breaking the Triad", ["orderIndex"] = 15, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[91695] = { ["id"] = 91695, ["name"] = "Tracking Down Incarnates", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14514, ["mapID"] = 2112, ["storyline"] = { 91691, 91695 }, ["description"] = "We must turn our attention to Fyrakk and Vyranoth with Iridikron seemingly vanished from our sight. Merithra and the Green Dragonflight have been pursuing him and have a lead. They've received the aid of Shandris Feathermoon in this task. She awaits you within Valdrakken. Shandris will need your help with what is to come.", ["objectivesText"] = "Find Shandris Feathermoon within Valdrakken.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187669, ["x"] = 0.610286, ["y"] = 0.389143 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 205067, ["x"] = 0.502, ["y"] = 0.533 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.610286, ["y"] = 0.389143 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 91691 }, ["questLines"] = { { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 70, ["flags"] = 0 }, { ["id"] = 6214, ["name"] = "Welcome to the Waking Shore", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 }, { ["id"] = 346, ["title"] = "The Azure Span", ["questLineID"] = 6214, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[91700] = { ["id"] = 91700, ["name"] = "Darkness Unmade", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91700 }, ["description"] = "The Void energies concentrated in this citadel have given rise to numerous aberrant creatures. Wildlife mutated by residual energy and horrors originating from beyond the anomalies, continue to feed and draw upon the energies here. It is most unpleasant! To safeguard my future enterprises, these threats must be neutralized.", ["objectivesText"] = "Eliminate 2 Rare creatures in the Stormarion Citadel and surrounding area. Progress: Have you eliminated the threats?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 246951 }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 244749, ["x"] = 0.264, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 244749, ["x"] = 0.264, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.264, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "group", ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[91726] = { ["id"] = 91726, ["name"] = "Unstoppable Force", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 46, ["mapID"] = 36, ["storyline"] = { 86822, 86823, 86824, 86825, 86826, 86827, 86828, 86829, 86830, 86831, 86832, 86833, 86903, 91391, 91726, 91787, 91842 }, ["description"] = "This statue seems out of place here. Nothing else like it. But this is where Anduin Lothar fell against Orgrim Doomhammer at the Battle of Blackrock Mountain. Many fought on this field. Many didn't make it. Lothar... Let me tell ye what happened all those years ago.", ["objectivesText"] = "Ask Kurdran about the events of that day. Progress: It was such a dark day, <name>. Painful to remember.", ["rewardGold"] = 312800, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 36, ["npcID"] = 248250, ["x"] = 0.368, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 36, ["npcID"] = 248250, ["x"] = 0.368, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 36, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 36 }, ["zone"] = { 46 } }, ["questType"] = "standard", ["sourceQuests"] = { 86829 }, ["questLines"] = { { ["id"] = 5751, ["name"] = "Regrets of the Past", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5751, ["questLineOrder"] = 12 } }, ["db2PoiUiMapID"] = 36 },
[91739] = { ["id"] = 91739, ["name"] = "Endeavor Reward", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["rewardCurrencies"] = { { ["id"] = 3363, ["amount"] = 30 } }, ["questType"] = "standard" },
[91747] = { ["id"] = 91747, ["name"] = "Not Quite Nalorakk", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91747, 91748, 91749, 91750, 91813, 93734 }, ["description"] = "Were you the one we saw enter Nalorakk's temple with Zul'jarra? I thought so! Zul'jarra spoke to him, didn't she? < Furgh growls in an unsettling way from deep in his throat.> That doesn't make sense. The new Voice of Nalorakk says Nalorakk won't speak to anyone but him. He gave some of the tribe trinkets to feel closer to Nalorakk. But the tribe now fights over them. The ursas think it's unfair they don't get any. But the chosen cling to them. We must take them before more blood is spilled.", ["objectivesText"] = "Remove 8 Nalorakk Trinkets from the furbolgs in Spiritpaw Village. Progress: I don't want them. We'll toss them on the fire.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 248300 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 248121, ["x"] = 0.414, ["y"] = 0.8 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 248121, ["x"] = 0.414, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.414, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91813 }, ["questLines"] = { { ["id"] = 5971, ["name"] = "The Voice of Nalorakk", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91748] = { ["id"] = 91748, ["name"] = "Too Much Twilight", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91747, 91748, 91749, 91750, 91813, 93734 }, ["description"] = "This big bear called himself the Voice of Nalorakk and has \"chosen\" some of our tribe as his favorites. He doesn't know, but I saw him put dark, glowing lodestones in the totems around the village to give his chosen power. Dark power radiates from them. The power smells wrong. Not like Nalorakk. Our guardian bears get agitated and upset near them. They can smell it too! We must cleanse the camp. Get rid of those totems!", ["objectivesText"] = "Destroy 4 corrupted totems in Spiritpaw Village.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 248123, ["x"] = 0.412, ["y"] = 0.8 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 248123, ["x"] = 0.412, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91813 }, ["questLines"] = { { ["id"] = 5971, ["name"] = "The Voice of Nalorakk", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91749] = { ["id"] = 91749, ["name"] = "It's Just Not Right", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91747, 91748, 91749, 91750, 91813, 93734 }, ["description"] = "If Chief Groffa is leading the tribe into the dark, he needs to be stopped. The Voice of Nalorakk dazzled Groffa with trinkets. He keeps them locked away so no one else can have them. If that is true, he's corrupted too. Even more than the others! Stop him and get the gifts out of the village.", ["objectivesText"] = "Stop the Chief and recover the false gifts. Progress: What is he hoarding in his camp?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 248659 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 248121, ["x"] = 0.414, ["y"] = 0.8 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 248121, ["x"] = 0.414, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.414, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91747, 91748 }, ["questLines"] = { { ["id"] = 5971, ["name"] = "The Voice of Nalorakk", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91750] = { ["id"] = 91750, ["name"] = "Perils of Trust", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91747, 91748, 91749, 91750, 91813, 93734 }, ["description"] = "That was scary. We nearly lost Furgh! < Fleeg 's fur twitches in fear and worry as he looks Furgh over.> Furgh said he heard the Voice of Nalorakk talking to him after touching the treasures. But it can't be Nalorakk's voice. Nalorakk doesn't need trinkets! Rip out the throat of this evil that dares to say it speaks for Nalorakk!", ["objectivesText"] = "Kill the false Voice of Nalorakk . Progress: < Fleeg howls mournfully.> Kill them for what they did to Furgh!", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 263272, 263273, 263274, 263275 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3354, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 248123, ["x"] = 0.412, ["y"] = 0.8 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 248123, ["x"] = 0.412, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 93734 }, ["questLines"] = { { ["id"] = 5971, ["name"] = "The Voice of Nalorakk", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
