[91787] = { ["id"] = 91787, ["name"] = "The Journey Ends", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 86822, 86823, 86824, 86825, 86826, 86827, 86828, 86829, 86830, 86831, 86832, 86833, 86903, 91391, 91726, 91787, 91842 }, ["description"] = "The Light takes many forms. But I know now what it means to me, and how I want to wield it. I'm not just a weapon like my father, nor can I devote myself purely to service like Dezco. But I can protect people from the evil that threatens them. Right now, that's Xal'atath and her Devouring Host. We should return to Lor'themar and do whatever is needed to defeat the Void. Beyond that, I shall see where protecting others with the Light takes me.", ["objectivesText"] = "Return to Silvermoon.", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3365, ["amount"] = 100 } }, ["starts"] = { { ["npcID"] = 237502, ["mapID"] = 2541, ["x"] = 0.521008, ["y"] = 0.607214 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 }, { ["npcID"] = 237502, ["mapID"] = 2541, ["x"] = 0.521008, ["y"] = 0.607214 } }, ["coords"] = { ["source"] = "quest_giver", ["mapID"] = 2541, ["x"] = 0.521008, ["y"] = 0.607214 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 10473 } }, ["questType"] = "standard", ["sourceQuests"] = { 86903 }, ["questLines"] = { { ["id"] = 5751, ["name"] = "Regrets of the Past", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5751, ["questLineOrder"] = 12 } }, ["db2PoiUiMapID"] = 2393 },
