[91813] = { ["id"] = 91813, ["name"] = "The Spiritpaw", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91747, 91748, 91749, 91750, 91813, 93734 }, ["description"] = "I just chased away some furbolg dat were actin' real strange. Dey were arguin' and then one walked toward Lilaju with his hands in de air. I charged at dem an' scared dem off. Dey are usually hostile and who knows what dey were gonna do? But Lilaju wants to see what dey wanted. Our scouts saw dem follow de river east to de north side of de lake. Track dem down. See what dey want. If it's a trick, then kill dem.", ["objectivesText"] = "Find the Spiritpaw furbolg that wanted to speak to Lilaju.", ["rewardGold"] = 34100, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3354, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 248657, ["x"] = 0.336, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 248121, ["x"] = 0.414, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91958 }, ["questLines"] = { { ["id"] = 5971, ["name"] = "The Voice of Nalorakk", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91821] = { ["id"] = 91821, ["name"] = "Out of Time", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 7502, ["mapID"] = 619, ["storyline"] = { 91821 }, ["description"] = "There you are, <name>. This timeline is collapsing! Presumably you have noticed the great rift tearing through reality above us. We don't have much time remaining before we must retreat from this timeline. To make matters worse, infernals from other timelines are starting to pour in. Send them back from when they came.", ["objectivesText"] = "Slay a Lost Legion Infernal on the Broken Isles.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 31510, 31512, 31516, 31521, 33226, 37208, 37271, 37393, 37402, 37425, 37484, 37543, 38212, 39348, 39402, 39438, 39508, 57438, 57439, 57440, 59711, 59712, 59713, 59714, 59715, 59716, 62860, 62861, 62862, 65344, 65347, 65350, 65353, 72880, 72881, 72882, 72883, 93724, 116394, 118937, 121490, 121492, 121494, 127853, 128949, 131453, 131665, 132954, 133315, 139506, 139770, 143607, 147467 }, ["starts"] = { { ["mapID"] = 619, ["npcID"] = 243853, ["x"] = 0.456, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 619, ["npcID"] = 243853, ["x"] = 0.456, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 619, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 619 }, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[91822] = { ["id"] = 91822, ["name"] = "The Regent's Request", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 91822, 91823, 91824, 91825, 91826, 91827, 91828, 91829, 91830, 91831, 91918 }, ["description"] = "Lor'themar has requested our presence. He wasn't exactly forthcoming with the details, but the location he chose speaks volumes. Silvermoon Harbor. Quiet and out of sight. Not exactly the kind of place one picks for diplomacy or ceremony. No, this feels like something else entirely. Whatever he's planning, it won't be written down in any official record. Come. Let's find out what the Regent Lord has to say.", ["objectivesText"] = "Find out what Lor'themar is planning. Progress: Let's not keep the Regent Lord waiting.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 242381, ["x"] = 0.525, ["y"] = 0.781 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 248750, ["x"] = 0.618, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = { 2393, 2395 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 86636 }, ["questLines"] = { { ["id"] = 5974, ["name"] = "The Crimson Rogue", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91823] = { ["id"] = 91823, ["name"] = "Lines Cut, Tongues Silenced", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91822, 91823, 91824, 91825, 91826, 91827, 91828, 91829, 91830, 91831, 91918 }, ["description"] = "The Twilight's Blade slipped into Tranquillien so easily because they'd stolen knowledge and secrets. About our defenses, our magic, our people. Once inside, they uncovered even more information. Now they pass that intelligence between themselves using enchanted orbs. Quiet whispers drifting through the dark. Every message tightens the noose around Quel'Thalas. Find the orbs. Break them. Every shattered crystal is a whisper silenced.", ["objectivesText"] = "Destroy the Communications Orbs in Zeb'tela Ruins.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 248750, ["x"] = 0.618, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 248750, ["x"] = 0.618, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91822 }, ["questLines"] = { { ["id"] = 5974, ["name"] = "The Crimson Rogue", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91824] = { ["id"] = 91824, ["name"] = "The Thieves' Trail", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91822, 91823, 91824, 91825, 91826, 91827, 91828, 91829, 91830, 91831, 91918 }, ["description"] = "From what I can see, it looks like the Twilight's Blade stole several arcane artifacts used by our Magisters to enhance long-distance communication. If they learn to wield them, they'll cast their reach far beyond what we can contain. They might even be able to hear our communications... and we can't have that. Recover the artifacts. If anyone gets in your way... you know what to do.", ["objectivesText"] = "Recover Quel'dorei Artifacts from the Twilight's Blade in Zeb'tela Ruins. Progress: Those artifacts should never have fallen into the wrong hands.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 248614 }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 248750, ["x"] = 0.618, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 248750, ["x"] = 0.618, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91822 }, ["questLines"] = { { ["id"] = 5974, ["name"] = "The Crimson Rogue", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91825] = { ["id"] = 91825, ["name"] = "Dead Men Keep No Secrets", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91822, 91823, 91824, 91825, 91826, 91827, 91828, 91829, 91830, 91831, 91918 }, ["description"] = "From what I've seen, this group isn't acting without direction. There's someone leading them, a man hiding in one of their structures. If I had to guess, he's the one holding whatever they considered too important to trust to crystal or courier. Documents, plans, names. Find him, silence him, and bring back whatever he was protecting.", ["objectivesText"] = "Retrieve the stolen documents from Gareth the Listener in Zeb'tela Ruins. Progress: You made that look easy.", ["rewardGold"] = 683200, ["rewardXP"] = 14705, ["rewardItems"] = { 248615 }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 248750, ["x"] = 0.618, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 248750, ["x"] = 0.618, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91822 }, ["questLines"] = { { ["id"] = 5974, ["name"] = "The Crimson Rogue", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[91826] = { ["id"] = 91826, ["name"] = "Tripwire Tango", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91822, 91823, 91824, 91825, 91826, 91827, 91828, 91829, 91830, 91831, 91918 }, ["description"] = "This cache isn't locked with magic. It's craftsmanship. I can hear the mechanism ticking inside. Tiny cogwheels, tension springs, and probably a poison vial ready to shatter the moment someone tries to pick the lock. We'll have to do this together. I'll take the pins, you keep the mechanism from snapping. One wrong move and it'll be enough to drop an ogre in mid-charge. Steady now.", ["objectivesText"] = "Disarm the mechanism and retrieve the documents from inside the chest. Progress: Easy does it.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 248720 }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 248750, ["x"] = 0.618, ["y"] = 0.682 }, { ["mapID"] = 2395, ["npcID"] = 248874, ["x"] = 0.618, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 248874, ["x"] = 0.618, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91823, 91824, 91825 }, ["questLines"] = { { ["id"] = 5974, ["name"] = "The Crimson Rogue", ["orderIndex"] = 5, ["flags"] = 0 } } },
[91827] = { ["id"] = 91827, ["name"] = "No Loose Ends", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91822, 91823, 91824, 91825, 91826, 91827, 91828, 91829, 91830, 91831, 91918 }, ["description"] = "You handled yourself well. These documents are too important to pass through couriers or ravens. I'd like you to deliver them personally to Lor'themar. He'll want to see the truth for himself and know who brought it back. Keep them close, and don't let anyone else near them.", ["objectivesText"] = "Return to Lor'themar Theron in Silvermoon City.", ["rewardGold"] = 232300, ["rewardXP"] = 8825, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 248874, ["x"] = 0.618, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 2393, 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 91826 }, ["questLines"] = { { ["id"] = 5974, ["name"] = "The Crimson Rogue", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[91828] = { ["id"] = 91828, ["name"] = "A Favor for the Lion", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2393, ["storyline"] = { 91822, 91823, 91824, 91825, 91826, 91827, 91828, 91829, 91830, 91831, 91918 }, ["description"] = "A letter arrived for me. No seal, no name. Just folded parchment and handwriting I'd recognize anywhere. It didn't say much. He never wastes words. I've known his family a long time. When they reach out, I answer.", ["objectivesText"] = "Read the letter and assist Valeera Sanguinar in Zul'Aman . Progress: Yes?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 242381, ["x"] = 0.525, ["y"] = 0.781 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 248982, ["x"] = 0.404, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = { 2393, 2437 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 86522, 91827 }, ["questLines"] = { { ["id"] = 5974, ["name"] = "The Crimson Rogue", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91829] = { ["id"] = 91829, ["name"] = "One by One", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91822, 91823, 91824, 91825, 91826, 91827, 91828, 91829, 91830, 91831, 91918 }, ["description"] = "Every last cultist is a threat to the people we're trying to save. To Silvermoon itself. Blasted fanatics with blood on their hands and no intention of letting anyone walk out alive. We're already in the camp. Let's make it count. I want them to feel this.", ["objectivesText"] = "Kill cultists of the Twilight's Blade at Speaker's Rest. Progress: Keep the kills quiet if you can.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 12122, 25610, 25611, 25612, 38739, 39038, 39068, 39104, 39807, 39857, 39860, 39868, 43171, 43172, 43173, 43174, 43176, 59650, 59651, 59652, 64533, 64534, 64535, 64536, 64537, 64538, 64539, 64540, 64541, 64542, 67414, 71083, 78960, 78961, 78962, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82513, 91806, 140238, 141951, 155564, 158585, 158587, 158628, 158630, 166846, 166970, 166971, 167556, 168752, 179620, 179623, 179773, 180847, 180901, 180902, 180903, 180904, 180943, 181176, 181177, 181178, 181181, 181182, 181183, 181184, 181187, 181189, 181192, 181193, 181195, 181196, 181198, 181200, 181203, 181204, 181212, 181215, 181218, 181334, 181368, 181377, 181467, 181498, 181506, 181545, 181546, 181547, 181548, 181550, 181569, 181576, 181577, 181589, 181591, 181603, 181612, 181703, 181708, 181842, 181877, 182126, 182338, 182460, 182480, 182486, 182495, 182504, 182513, 182584, 182648, 182736, 182750, 183476, 183482, 183500, 183502, 183744, 183830, 184147, 184150, 184294, 184363, 184587, 184765, 184767, 184768, 184777, 184839, 184843, 246697 }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 248982, ["x"] = 0.404, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 248982, ["x"] = 0.404, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questTurnInID"] = 248982, ["questType"] = "standard", ["sourceQuests"] = { 91828 }, ["questLines"] = { { ["id"] = 5974, ["name"] = "The Crimson Rogue", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91830] = { ["id"] = 91830, ["name"] = "Intercepted", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91822, 91823, 91824, 91825, 91826, 91827, 91828, 91829, 91830, 91831, 91918 }, ["description"] = "The Twilight's Blade hit Tranquillien hard. Slipped in and took all the supplies and information they could ever need, right beneath everyone's nose. Time to return the favor. I've marked a few tents. Command posts, messengers' satchels, a supply ledger tucked under a wine crate. That's where they keep their orders, maps, and routes. Grab everything you can.", ["objectivesText"] = "Collect 6 Cult Orders from the Twilight's Blade camp at Speaker's Rest. Progress: The right scrap of parchment can win a war. Or start one.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 248928 }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 248982, ["x"] = 0.404, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 248982, ["x"] = 0.404, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questTurnInID"] = 248982, ["questType"] = "standard", ["sourceQuests"] = { 91828 }, ["questLines"] = { { ["id"] = 5974, ["name"] = "The Crimson Rogue", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91831] = { ["id"] = 91831, ["name"] = "Keys Are Optional", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91822, 91823, 91824, 91825, 91826, 91827, 91828, 91829, 91830, 91831, 91918 }, ["description"] = "These people joined the Twilight's Blade looking for purpose, power, or place to belong. For a reprieve from the fear and a promise of certainty. Now they see it for what it is--a prison dressed up as faith. And they want out. We go in together. Get them out before the cult realizes what's happening.", ["objectivesText"] = "Find and release 4 groups of Cult Deserters in Speaker's Rest. Progress: Ready yourself. This might get messy.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 248982, ["x"] = 0.404, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 248982, ["x"] = 0.404, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questTurnInID"] = 248982, ["questType"] = "standard", ["sourceQuests"] = { 91828 }, ["questLines"] = { { ["id"] = 5974, ["name"] = "The Crimson Rogue", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91833] = { ["id"] = 91833, ["name"] = "Dirty Deeps", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91833, 91835, 91836, 91838, 91839, 91840 }, ["series"] = { 91835 }, ["description"] = "De Vilebranch are sinkin' deeper into their cursed minds. Dey spit in de face of de loa, and believe dey have mastered death. I could see a certain... someone not likin' dat way of thinkin'. Dey have taken our kin and now dey take our shaman. Meet my scout there and help dem break their plans. Cut de head off de beast and de body will fall.", ["objectivesText"] = "Meet the Witherbark Scout at Maisara Deeps. Provided item:", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["rewardItems"] = { 248814 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3354, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 244591, ["x"] = 0.385, ["y"] = 0.224 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 248838, ["x"] = 0.4165, ["y"] = 0.2945 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.224 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86664 }, ["questLines"] = { { ["id"] = 5975, ["name"] = "Something Vile This Way Comes", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91834] = { ["id"] = 91834, ["name"] = "Guardians Must Go", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["storyline"] = { 91834 }, ["description"] = "Get rid of shield face and meet me in de hut below. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(91834)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(91834))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Kill the Dark Hex Guardian and meet me below. Provided item:", ["rewardItems"] = { 248756 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[91835] = { ["id"] = 91835, ["name"] = "Send Dem Home", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91833, 91835, 91836, 91838, 91839, 91840 }, ["series"] = { 91833 }, ["description"] = "My friend, dis is a mighty gift. Shadra is givin' us a blessin' for de tasks ahead. These Vilebranch really are livin' up to their name. Dey drain de spirit from de Witherbark and create undead to serve dem. We must free de Witherbark from these necrotic bonds. My friend's still in there... I hope. Me and Bin'zin cut our tusks together growin' up. He grew into a strong shaman. Our village needs him, and he is like a brother to me.", ["objectivesText"] = "Free 8 Witherbark Prisoners . Progress: Are the prisoners safe?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 248745, 257444, 259361 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 248838, ["x"] = 0.4165, ["y"] = 0.2945 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 248838, ["x"] = 0.4165, ["y"] = 0.2945 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.4165, ["y"] = 0.2945 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questTurnInID"] = 248838, ["questType"] = "standard", ["sourceQuests"] = { 91833 }, ["questLines"] = { { ["id"] = 5975, ["name"] = "Something Vile This Way Comes", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91836] = { ["id"] = 91836, ["name"] = "Respect de Totem", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91833, 91835, 91836, 91838, 91839, 91840 }, ["description"] = "When dey took Bin'zin, de priestess destroyed his totems and gave de shattered remains to her minions--like some grisly memento. Take de pieces back, one by one if ya have to. Dat disrespect will not stand.", ["objectivesText"] = "Collect 40 Totem Remnants . Progress: How goes de lootin'?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 254430 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 248838, ["x"] = 0.4165, ["y"] = 0.2945 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 248838, ["x"] = 0.4165, ["y"] = 0.2945 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.4165, ["y"] = 0.2945 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questTurnInID"] = 248838, ["questType"] = "standard", ["sourceQuests"] = { 91835 }, ["questLines"] = { { ["id"] = 5975, ["name"] = "Something Vile This Way Comes", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91837] = { ["id"] = 91837, ["name"] = "Bring Back De Bones", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91837 }, ["description"] = "Big thanks for breakin' us free. Some were not so lucky. Bring dey bones back to de Chief, he will know what to do.", ["objectivesText"] = "Collect 8 Bones of de Fallen .", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 248715 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15947 } }, ["questType"] = "standard" },
[91838] = { ["id"] = 91838, ["name"] = "De Vile Diminished", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91833, 91835, 91836, 91838, 91839, 91840 }, ["description"] = "These vile orbs are harvestin' de souls of our people and sendin' dark energy to de Knife Priestess. She's gettin' mighty powerful. Destroy de orbs so her ritual of death is ruined. With de gift of Shadra, ya will not fail.", ["objectivesText"] = "Destroy 5 Vile Orbs . Progress: Did ya find all de orbs?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 248787, ["x"] = 0.463, ["y"] = 0.3925 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 248787, ["x"] = 0.463, ["y"] = 0.3925 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.463, ["y"] = 0.3925 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91836 }, ["questLines"] = { { ["id"] = 5975, ["name"] = "Something Vile This Way Comes", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91839] = { ["id"] = 91839, ["name"] = "Sacrifice Denied", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91833, 91835, 91836, 91838, 91839, 91840 }, ["description"] = "Our shaman is home and Jin'zin's full of joy to see him again. She was always his little wildcat apprentice. Dey will have sad moments--Tan'zin is a mighty loss. Today, ya brought him home. Go enjoy dat for a bit, $p, before ya be on ya way.", ["objectivesText"] = "Check on Bin'zin . Progress: Did ya talk to him?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 264662, 264663, 264664, 264665 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3354, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 248838, ["x"] = 0.4165, ["y"] = 0.2945 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 253326, ["x"] = 0.372, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.4165, ["y"] = 0.2945 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91840 }, ["questLines"] = { { ["id"] = 5975, ["name"] = "Something Vile This Way Comes", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91840] = { ["id"] = 91840, ["name"] = "One Will Not Rise", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91833, 91835, 91836, 91838, 91839, 91840 }, ["description"] = "Now's our best shot! We end de sacrifices here! Stoppin' de dark energy has weakened her hold. Then, you can be de one to bring back her head. Uh, and <name>--no tellin' de chief about me callin' him Big VunVun. He'll be turnin' me into a frog if he hears dat again.", ["objectivesText"] = "Deliver the head of Knife Priestess Hezzia to Vun'zarah in Witherbark Bluffs. Progress: I am pleased you're takin' my words so literally.", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["rewardItems"] = { 250190, 253629, 254778 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3354, ["amount"] = 100 } }, ["starts"] = { { ["npcID"] = 249106, ["mapID"] = 2437, ["x"] = 0.471566, ["y"] = 0.412417 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 244591, ["x"] = 0.385, ["y"] = 0.224 }, { ["npcID"] = 249106, ["mapID"] = 2437, ["x"] = 0.471566, ["y"] = 0.412417 } }, ["coords"] = { ["source"] = "quest_giver", ["mapID"] = 2437, ["x"] = 0.471566, ["y"] = 0.412417 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91838 }, ["questLines"] = { { ["id"] = 5975, ["name"] = "Something Vile This Way Comes", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[91842] = { ["id"] = 91842, ["name"] = "Disarm the Dark Horde", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 46, ["mapID"] = 36, ["storyline"] = { 86822, 86823, 86824, 86825, 86826, 86827, 86828, 86829, 86830, 86831, 86832, 86833, 86903, 91391, 91726, 91787, 91842 }, ["description"] = "The Dark Horde have no love fer their equipment. Look at their weapons! Cracked, rusted, blunt, and bent. Ach! The only way they function is by making more shoddy tools to constantly replace the ones they've broken. If ye see any of their weapon racks, destroy 'em. Let's see how well they fight without their rusty blades. A bare-fisted orc is nothing to sneeze at, but it'll further delay any daft plans they've got.", ["objectivesText"] = "Destroy 8 Dark Horde Weapon Racks .", ["rewardGold"] = 309800, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 36, ["npcID"] = 237268, ["x"] = 0.212, ["y"] = 0.396 } }, ["ends"] = { { ["mapID"] = 36, ["npcID"] = 237268, ["x"] = 0.212, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 36, ["source"] = "quest_giver", ["x"] = 0.212, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 36 }, ["zone"] = { 46 } }, ["questType"] = "standard", ["sourceQuests"] = { 91391 }, ["questLines"] = { { ["id"] = 5751, ["name"] = "Regrets of the Past", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5751, ["questLineOrder"] = 12 } }, ["db2PoiUiMapID"] = 36 },
[91843] = { ["id"] = 91843, ["name"] = "Recap: The Harbinger", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 91843 }, ["description"] = "To understand the story of The War Within, one must first begin with the mysterious entity known as the Harbinger, and how the heroes of Azeroth uncovered the truth...", ["objectivesText"] = "Read along with the Tome of History and learn about the events which sparked The War Within. Progress: Xal'atath was a mysterious foe with ties to the Void. Her presence portended dire things for Azeroth...", ["starts"] = { { ["x"] = 0.464, ["y"] = 0.602, ["mapID"] = 2112, ["npcID"] = 248956 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 248948, ["x"] = 0.545, ["y"] = 0.567 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.567 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questGiverID"] = 248956, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6007, ["name"] = "Catch Up: War Within: Wrapper 1", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6007, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
