[91854] = { ["id"] = 91854, ["name"] = "Deepening Shadows", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 91084, 91087, 91854, 91967 }, ["description"] = "Champion, I could use your assistance. The natives here in Silvermoon are proving to be less hospitable than we had hoped. In their defense, their city is facing down a darkness unlike anything Azeroth has ever faced, so tensions are high. Can you use your unique perspective and help de-escalate some of the hot spots that are emerging around Silvermoon?", ["objectivesText"] = "De-escalate rising tensions in Silvermoon City . Progress: Tensions are high.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 248631, ["x"] = 0.454, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 248631, ["x"] = 0.454, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5979, ["name"] = "The Darkening Sky", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5979, ["questLineOrder"] = 16 } }, ["db2PoiUiMapID"] = 2393 },
[91855] = { ["id"] = 91855, ["name"] = "Worldsoul: K'aresh World Quests", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "I know now that the heroes of Azeroth venture wherever help is needed. K'aresh is a strange, faraway place, but our allies there need us. Go there and help them. See what you can do to bring respite to the ethereals and brokers.", ["objectivesText"] = "Complete World Quests in K'aresh. Progress: Our allies resist valiantly on a dead and shattered world. I admire them.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 244865 }, ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 45, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
