[91865] = { ["id"] = 91865, ["name"] = "Catch Up: Khaz Algar", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["storyline"] = { 91865 }, ["description"] = "The Earthen of Khaz Algar eventually welcomed the outsiders into their land, but all was not well with them. Divisions had grown among their people. To unravel Xal'atath's plot with the Nerubians, the Champions would have to address these issues. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(91865)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(91865))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Consult the Tome of History to learn about the events in Khaz Algar in The War Within.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[91866] = { ["id"] = 91866, ["name"] = "Catch Up: The Ringing Deeps", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["storyline"] = { 91866 }, ["description"] = "The Champions travel with Brinthe of the Earthen and Moira, Dagran and Magni Bronzebeard to the Ringing deeps. There they find not all is well as a mysterious affliction has touched some of the workers. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(91866)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(91866))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Consult the Tome of History to learn about the events in the Ringing Deeps in The War Within.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[91867] = { ["id"] = 91867, ["name"] = "Catch Up: Hallowfall", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 91867 }, ["description"] = "King Anduin Wrynn, Alleria and the Champions travel deeper into Azeroth, arriving at a place known as Hallowfall. It quickly become apparent that this place has also been touched by the machinations of Xal'atath. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(91867)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(91867))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Consult the Tome of History to learn about the events in Hallowfall in The War Within.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14771 } }, ["questType"] = "standard" },
