[91869] = { ["id"] = 91869, ["name"] = "Catch Up: A Light in the Dark", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 91869 }, ["description"] = "The War Within continued on Khaz Algar as the peoples of the land began to unite against Xal'atath and her Dark Heart. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(91869)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(91869))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Consult the Tome of History to learn about the events in The War Within.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14771 } }, ["questType"] = "standard" },
[91871] = { ["id"] = 91871, ["name"] = "Recap: The Dark Heart", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 85, ["storyline"] = { 83126, 83127, 83128, 83129, 84856, 84857, 84862, 84863, 84864, 84865, 84866, 84967, 85037, 85449, 85450, 86495, 86820, 86946, 90517, 91871, 93979 }, ["description"] = "The champions and Alleria were invited to Undermine by Gazlowe as the peoples of Khaz Algar and beyond began to unite against Xal'atath and her Dark Heart.", ["objectivesText"] = "Consult the Tome of History to learn about the events in Undermine and K'aresh in The War Within. Progress: Dimensius was defeated and Azeroth was saved from his threat, yet there was a cost.", ["rewardItems"] = { 254325 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 248948, ["x"] = 0.545, ["y"] = 0.567 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 248948, ["x"] = 0.545, ["y"] = 0.567 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.567 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 91868 }, ["questLines"] = { { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[91872] = { ["id"] = 91872, ["name"] = "The Former Rootwarden", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91872, 91873, 91874, 91875, 91876 }, ["description"] = "$p, I was the Rootwarden of Teldrassil. For years, I watched the roots here below the surface, but I was not aware of what was threatening the tree outside of Harandar . For just as long, I have regretted that failure, but we cannot change the past. I wonder, however, if roots so great may still have life within them. Might there be something which can still be done? I do not know, but I do hope. Will you join me at the Shrine of Ages, to tend the roots?", ["objectivesText"] = "Meet Hagar at the Shrine of Ages.", ["rewardGold"] = 31500, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3370, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 237572, ["x"] = 0.348, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 252495, ["x"] = 0.425, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.348, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86898 }, ["questLines"] = { { ["id"] = 5977, ["name"] = "Cultivating Hope", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91873] = { ["id"] = 91873, ["name"] = "Buffer Zone", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91872, 91873, 91874, 91875, 91876 }, ["description"] = "At this shrine, I have worked to gather roots that seem to still have the possibility of life within them. They are each greatly damaged, some more than others. My hope is some might recover, with enough time and enough care. In that way, I honor the great tree's memory. For that to be possible, though, we have to keep them safe from the hazards of Harandar . Please be sure that nothing nearby threatens them.", ["objectivesText"] = "Protect the shrine from local wildlife.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 252495, ["x"] = 0.425, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 252497, ["x"] = 0.422, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.425, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 91872 }, ["questLines"] = { { ["id"] = 5977, ["name"] = "Cultivating Hope", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91874] = { ["id"] = 91874, ["name"] = "Flare Up", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91872, 91873, 91874, 91875, 91876 }, ["description"] = "$p, I see smoke rising above Har'mara. The roots are on fire--not here, but beneath the remnants of the tree! I have seen this happen many times, but we must always respond with haste. Take to the skies and douse them, immediately!", ["objectivesText"] = "Fly near the flames on the roots of Teldrassil to douse them.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 252496, ["x"] = 0.424, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 248886, ["x"] = 0.425333, ["y"] = 0.335333 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 91875 }, ["questLines"] = { { ["id"] = 5977, ["name"] = "Cultivating Hope", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91875] = { ["id"] = 91875, ["name"] = "Natural Remedy", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91872, 91873, 91874, 91875, 91876 }, ["description"] = "If we ever hope to see new growth, Teldrassil's roots needs a great deal of special attention. The source of this stream is one of the great roots. The water carries ash, which I believe still contains the tree's essence. The stalkers in the stream carry a mixture of that ash and slime from their tendrils--a very potent mixture. Bring me as much of it as you can carry, and I will combine it with reagents I've gathered. Then we'll be ready to apply it to the roots.", ["objectivesText"] = "Gather 8 clumps of Verdant Stalker Sludge . Progress: Do you have the rejuvenating mud I asked for?", ["rewardGold"] = 676600, ["rewardXP"] = 15215, ["rewardItems"] = { 252649 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3370, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 252497, ["x"] = 0.422, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 252496, ["x"] = 0.424, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 91873 }, ["questLines"] = { { ["id"] = 5977, ["name"] = "Cultivating Hope", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91876] = { ["id"] = 91876, ["name"] = "Tending Hope", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91872, 91873, 91874, 91875, 91876 }, ["description"] = "Thank you for tending to those fires, $p. While you were gone, I've used that sludge to make a salve. Help me spread it over Teldrassil's roots. It may take years to see a difference, if we ever do. But though I failed, I made oaths to her, and I can still choose to keep them. I will never stop doing what I can to... help her perhaps grow again. If I do not succeed, the next Rootwarden, or the one who comes after that, may be the one to finish this work. Even so, I shall not stop trying.", ["objectivesText"] = "Apply Hagar 's salve to 12 Withered Roots. Progress: Have you treated the roots?", ["rewardGold"] = 312800, ["rewardXP"] = 12170, ["rewardItems"] = { 260450, 260451 }, ["rewardChoices"] = { 260450, 260451 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3370, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 248886, ["x"] = 0.425333, ["y"] = 0.335333 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 252494, ["x"] = 0.425, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.425333, ["y"] = 0.335333 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 91874 }, ["questLines"] = { { ["id"] = 5977, ["name"] = "Cultivating Hope", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[91884] = { ["id"] = 91884, ["name"] = "The Illusion of Motion", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91884, 91885, 91886, 91887 }, ["series"] = { 91885 }, ["description"] = "You! Have YOU seen them? I've been tasked to investigate some of our scouts that have gone missing. My reconnaissance had come up empty until recently. Now I've been catching glimpses of the missing scouts, but... they appear formed of pure Void energy. Each time I chase the figures, they lead me further and further before disappearing! The others think I'm crazy. You haven't seen anything like that, have you?", ["objectivesText"] = "Investigate the mysterious figures Nefina has seen around Locus Point.", ["rewardGold"] = 31500, ["rewardXP"] = 1605, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3389, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 248881, ["x"] = 0.414, ["y"] = 0.74 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 248880, ["x"] = 0.488, ["y"] = 0.822 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.414, ["y"] = 0.74 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86565 }, ["nextQuests"] = { 91885 }, ["questLines"] = { { ["id"] = 6013, ["name"] = "A Voice Inside", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[91885] = { ["id"] = 91885, ["name"] = "Drain You", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91884, 91885, 91886, 91887 }, ["series"] = { 91884 }, ["description"] = "Do you... see...? They follow... They plead... for help... <The voidwalker strains and shudders as it tries to communicate.> Too weak... too starving... <It feebly hands you a shard of dark matter.> This... will feed me... then together... we find the missing elves...", ["objectivesText"] = "Slay Voidstorm wildlife and use the Void Splinter to feed the Starving Voidwalker .", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 27730, 27733, 27734, 27735, 249433, 264287, 264288 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 248880, ["x"] = 0.488, ["y"] = 0.822 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 256206, ["x"] = 0.4625, ["y"] = 0.862 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.822 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 91884 }, ["questLines"] = { { ["id"] = 6013, ["name"] = "A Voice Inside", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[91886] = { ["id"] = 91886, ["name"] = "Voices of Omens", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91884, 91885, 91886, 91887 }, ["description"] = "The voices of your elven allies rattle inside my head. I know of a way we can find them. There is a way to locate missing things... using old domanaar scanning devices. But they require immense energy to function. Together, we can use these devices to focus the images of your lost friends. Their cries for help will become clearer, and then you can find them. Come. Lend me your strength.", ["objectivesText"] = "Help the Sentient Voidwalker power Domanaar Scrystones to help locate the missing scouts.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 256206, ["x"] = 0.4625, ["y"] = 0.862 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 248894, ["x"] = 0.4468, ["y"] = 0.8556 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.4625, ["y"] = 0.862 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 91885 }, ["questLines"] = { { ["id"] = 6013, ["name"] = "A Voice Inside", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[91887] = { ["id"] = 91887, ["name"] = "Dominion of Deceit", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91884, 91885, 91886, 91887 }, ["description"] = "We were right to be cautious. The threats we've found here in the Voidstorm are corrupting and irredeemable. This voidwalker's meticulous deceptions are unusual... I can't help but wonder why it would go through all the trouble. <She looks up at you from weary, withered eyes.> But I'm too weak to go on. It really did a number on me. You have the upper hand now! It thinks you're walking into its trap. Walk in with weapons drawn and spells ready!", ["objectivesText"] = "Slay the Deceitful Voidwalker .", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardItems"] = { 264415, 264417, 264418, 264419, 264420, 264421, 264422, 264423, 264424 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3389, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 248894, ["x"] = 0.4468, ["y"] = 0.8556 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 248881, ["x"] = 0.414, ["y"] = 0.74 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.4468, ["y"] = 0.8556 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 91886 }, ["questLines"] = { { ["id"] = 6013, ["name"] = "A Voice Inside", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[91918] = { ["id"] = 91918, ["name"] = "Delves: Measure Once, Cut Twice", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 91822, 91823, 91824, 91825, 91826, 91827, 91828, 91829, 91830, 91831, 91918 }, ["description"] = "We've done well to see those deserters to safety, but don't fool yourself into thinking we've freed them all. I've heard whispers of a place they use to break those whose loyalty is in question. The location isn't common knowledge, but I know where to start looking. If we're quick, we might find others before the cult decides they're too great a risk to keep alive. Meet me near the site. Keep your blades sharp and your steps light.", ["objectivesText"] = "Rescue the remaining Twilight's Blade Deserters from the Twilight Crypts delve on any difficulty.", ["rewardGold"] = 1024800, ["rewardXP"] = 20540, ["starts"] = { { ["x"] = 0.404, ["y"] = 0.717, ["mapID"] = 2437, ["npcID"] = 250295 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 242381, ["x"] = 0.525, ["y"] = 0.781 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questGiverID"] = 250295, ["questType"] = "standard", ["sourceQuests"] = { 91829, 91830, 91831 }, ["questLines"] = { { ["id"] = 5974, ["name"] = "The Crimson Rogue", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
