[91928] = { ["id"] = 91928, ["name"] = "What's For Lunch?", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91928 }, ["description"] = "My Shadowtrade Mercenaries will fight for Stormarion Cores , no questions asked, but they do get hungry also! Food is quite scarce here, so we need supplies! Take a mercenary out with you and find some food for them to eat. I'll make it worth your while!", ["objectivesText"] = "Slay Trigores for 3 Trigore Flanks and collect 20 Shadow-Grown Berries that grow in the area. Progress: Is that mercenary well fed?", ["rewardGold"] = 341600, ["rewardXP"] = 20540, ["rewardItems"] = { 246951, 248826 }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 244749, ["x"] = 0.264, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 244749, ["x"] = 0.264, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.264, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
