[91955] = { ["id"] = 91955, ["name"] = "Just Between Us", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["mapID"] = 619, ["storyline"] = { 91955 }, ["description"] = "The artifact we snatched from the timeline earlier was replaced with a simulacrum so none would notice the true artifact's absence. Such a wealth of infinite energy should not be abandoned so readily. You should seek it out and reclaim it. Once you have recovered the simulacrum you can scrap it for an embarassing sum of bronze and infinite power.", ["objectivesText"] = "Retrieve the Curious Simulacrum left in place of your \"borrowed\" artifact weapon by completing your artifact weapon's acquisition storyline as part of your Order Hall campaign.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 246937, 248141 }, ["starts"] = { { ["mapID"] = 619, ["npcID"] = 241142, ["x"] = 0.458, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 619, ["npcID"] = 241142, ["x"] = 0.458, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 619, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 619 }, ["zone"] = {} }, ["questType"] = "standard" },
[91958] = { ["id"] = 91958, ["name"] = "Den of Nalorakk: Unforgiven", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 86681, 86682, 91958 }, ["description"] = "Nalorakk is de Loa of War. His trial must be a battle! There would be no greater death for an Amani than to die in combat against de Loa of War. No greater thrill than fightin' him. Does it not make your blood pump faster and harder in your veins, hash'ura? < Zul'jarra lets out a feral howl and laughs.> Come. Meet me at Nalorakk's Prowl and we will sit at his fire and face our last trial--together.", ["objectivesText"] = "Complete the Den of Nalorakk dungeon. Progress: De final trial is at hand.", ["rewardGold"] = 1366400, ["rewardXP"] = 24340, ["rewardItems"] = { 251144, 251146, 251148, 251155, 251160, 251173 }, ["rewardChoices"] = { 251144, 251146, 251148, 251155, 251160, 251173 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3354, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 240215, ["x"] = 0.322, ["y"] = 0.821333 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 240215, ["x"] = 0.322, ["y"] = 0.821333 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.322, ["y"] = 0.821333 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86681 }, ["questLines"] = { { ["id"] = 5938, ["name"] = "Where War Slumbers", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5938, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 2437 },
[91963] = { ["id"] = 91963, ["name"] = "Running Amok", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91533, 91535, 91536, 91537, 91541, 91542, 91543, 91544, 91545, 91546, 91963 }, ["description"] = "I've heard from the other scouts about that metal--the shadowgraft. The domanaar use it to enforce their control over others. I have to imagine that there's someone holding the reins still. Maybe it's Xal'atath, or maybe someone else. Gather pieces of their shadowgraft and maybe we can make sense of who.", ["objectivesText"] = "Gather Shadowgraft from foes at Obscurion Citadel. Progress: Have you gathered enough for us to study?", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 249387 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 249045, ["x"] = 0.624, ["y"] = 0.824 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 249045, ["x"] = 0.624, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questTurnInID"] = 249045, ["questType"] = "standard", ["sourceQuests"] = { 91542 }, ["questLines"] = { { ["id"] = 5961, ["name"] = "To Be Changed", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[91966] = { ["id"] = 91966, ["name"] = "Saltheril's Soiree", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91966 }, ["objectivesText"] = "Tend to the Soiree's cleaning and entertainment Song chosen", ["rewardGold"] = 683200, ["rewardXP"] = 20540, ["rewardItems"] = { 254677, 268490 }, ["starts"] = { { ["x"] = 0.427, ["y"] = 0.473, ["mapID"] = 2395 } }, ["ends"] = { { ["x"] = 0.427, ["y"] = 0.473, ["mapID"] = 2395 } }, ["coords"] = { ["mapID"] = 2395, ["x"] = 0.427, ["y"] = 0.473 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 89290 }, ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 15, ["amount"] = 1, ["objectID"] = 0, ["text"] = "Tend to the Soiree's cleaning and entertainment" }, { ["orderIndex"] = 1, ["type"] = 0, ["amount"] = 5, ["objectID"] = 249284 }, { ["orderIndex"] = 2, ["type"] = 0, ["amount"] = 1, ["objectID"] = 249510, ["text"] = "Song chosen" }, { ["orderIndex"] = 3, ["type"] = 2, ["amount"] = 5, ["objectID"] = 568038 }, { ["orderIndex"] = 4, ["type"] = 2, ["amount"] = 5, ["objectID"] = 568047 }, { ["orderIndex"] = 5, ["type"] = 2, ["amount"] = 1, ["objectID"] = 568299 }, { ["orderIndex"] = 6, ["type"] = 0, ["amount"] = 5, ["objectID"] = 249396 }, { ["orderIndex"] = 7, ["type"] = 0, ["amount"] = 5, ["objectID"] = 249457 }, { ["orderIndex"] = 8, ["type"] = 0, ["amount"] = 1, ["objectID"] = 250191 } } },
[91967] = { ["id"] = 91967, ["name"] = "You Know This Evil?", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 91084, 91087, 91854, 91967 }, ["description"] = "Champion, we have a bit of a delicate situation. The Vanguard of the Light has just informed me they have taken Magister Umbric into custody. Apparently he was trying to get close to the Sunwell. I do not have to tell you that tensions are high between my city and the Vanguard. We need Umbric to continue his research if we are to have a chance at contending with the Voidstorm. I want you to represent me in negotiating Umbric's release. Whether we like him or not, we need him.", ["objectivesText"] = "Negotiate with the Vanguard of the Light for Magister Umbric 's release. Progress: Umbric is necessary. So is the Vanguard. I have a lot of necessary and unsavory elements to deal with these days, but I will do so if it means my people are safe.", ["rewardGold"] = 319000, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 91084 }, ["questLines"] = { { ["id"] = 5979, ["name"] = "The Darkening Sky", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5979, ["questLineOrder"] = 16 } }, ["db2PoiUiMapID"] = 2393 },
[91968] = { ["id"] = 91968, ["name"] = "Welcome Home", ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 11, ["storyline"] = { 91968, 91969 }, ["series"] = { 91969, 94210 }, ["description"] = "What a mess! Perhaps the previous owners left in a hurry. Best tidy up! The items removed will be sent to the house chest. They can always be placed down again, if cobwebs are your thing.", ["objectivesText"] = "Pick up objects in your house.", ["rewardGold"] = 34100, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["sourceQuests"] = { 94455 }, ["questLines"] = { { ["id"] = 5984, ["name"] = "Decor Tutorials", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6000, ["name"] = "House Purchase Tutorial", ["orderIndex"] = 2, ["flags"] = 0 } } },
[91969] = { ["id"] = 91969, ["name"] = "Time to Decorate", ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 11, ["storyline"] = { 91968, 91969 }, ["series"] = { 91968, 94210 }, ["description"] = "Now that we've got this place tidied up, let's decorate! The community has chipped in with donations to make sure you have plenty of options to work with. Let's have a look!", ["objectivesText"] = "Decorate your home.", ["rewardGold"] = 34100, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["sourceQuests"] = { 91968 }, ["questLines"] = { { ["id"] = 5984, ["name"] = "Decor Tutorials", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6000, ["name"] = "House Purchase Tutorial", ["orderIndex"] = 3, ["flags"] = 0 } } },
[91970] = { ["id"] = 91970, ["name"] = "WANTED: Gelatonius", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91970 }, ["description"] = "Are you ready to test yourself against a true foe? In the center of the Gloom Mire is Gelatonius , a fungal giant of enormous proportions. Kill him, if you think you can. I'm willing to be impressed, and to pay handsomely for this task.", ["objectivesText"] = "Kill Gelatonius in the Gloom Mire.", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 25 }, { ["id"] = 3310, ["amount"] = 37 }, { ["id"] = 3316, ["amount"] = 50 }, { ["id"] = 3370, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 249361, ["x"] = 0.518, ["y"] = 0.742 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 249361, ["x"] = 0.518, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "group", ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[91971] = { ["id"] = 91971, ["name"] = "Hitting the Hammer", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "The Twilight Hammer is dirtying up the ruins of Zeb'tala. Clean up the area and bring back some of their personal tokens. One never knows what curiosities may appeal to those vying for relevancy. Those mindless cultists may stomp around and act tough, but you will make quick work of them.", ["objectivesText"] = "Bring back 6 Twilight Tokens . Progress: Have you found anything useful?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249411 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 40 }, { ["id"] = 3379, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240835, ["x"] = 0.424, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240835, ["x"] = 0.424, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[91972] = { ["id"] = 91972, ["name"] = "Hold the Watch", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "There is still a lot of friction on the border with Zul'Aman, but we must hold the watch on all fronts. Check in with Bloodguard Nelric at the Thalassian Pass. It is rumored to be one of the most uneventful posts. I am certain he would appreciate a reprieve, if only for a few moments. Stay alert, $p!", ["objectivesText"] = "Check in with Bloodguard Nelric at the Thalassian Pass and hold the watch.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 40 }, { ["id"] = 3379, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240835, ["x"] = 0.424, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240835, ["x"] = 0.424, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[91973] = { ["id"] = 91973, ["name"] = "Naga Blades", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "It seems the locals currently find great appeal in naga blades--the brinier the better. On our southwestern shore, you will find the Daggerspine naga. They have these grungy, barnacle-encrusted scimitars that would perfectly fit the bill. Go grab a few of those. They could have value in some of our upcoming discussions.", ["objectivesText"] = "Collect 7 Naga Scimitars . Progress: Were you able to procure some blades?", ["rewardGold"] = 315900, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249499 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 50 }, { ["id"] = 3379, ["amount"] = 60 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240835, ["x"] = 0.424, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240835, ["x"] = 0.424, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[91974] = { ["id"] = 91974, ["name"] = "Sunfire to the Blade", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "I guess there is one benefit to being part of the courtly intrigue: one does hear things. We have this concoction of sunfire infused with the holy energy of the Blood Knights, courtesy of the court alchemists. Take this down to the Sanctum of the Moon and test it on the Twilight intruders. I look forward to hearing the results in detail.", ["objectivesText"] = "Kill 10 Twilight intruders at the Sanctum of the Moon with Holy Sunfire . Progress: How did it go?", ["rewardGold"] = 312800, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249528, 249691 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 40 }, { ["id"] = 3379, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240835, ["x"] = 0.424, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240835, ["x"] = 0.424, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[91975] = { ["id"] = 91975, ["name"] = "That's Our Wood", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "It seems the lure of the lightwood continues to be a problem. We may as well take advantage of the trolls' hard work! Collect what they have harvested. We can make use of it. What we do not use for weapons, we can hand over to the carvers. The nobles will clamor over lightwood decor.", ["objectivesText"] = "Collect 5 Harvested Lightwood . Progress: Did you gather the lightwood?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249407 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 50 }, { ["id"] = 3379, ["amount"] = 60 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240835, ["x"] = 0.424, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240835, ["x"] = 0.424, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[91976] = { ["id"] = 91976, ["name"] = "Lightbloom Dimmed", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "All of this small talk makes my ears twitch. I would be so much more useful doing field work. For now, you get to do the fun part. The creatures within the Lightbloom are getting a bit dense. I need you to get out there and lower the volume. I am sure you'll run into many options while you are out there. Take a whack at a few for me.", ["objectivesText"] = "Kill Lightbloom creatures.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 50 }, { ["id"] = 3379, ["amount"] = 60 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240835, ["x"] = 0.424, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240835, ["x"] = 0.424, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[91977] = { ["id"] = 91977, ["name"] = "Less Lawless", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "The Tideborne are always running just over the legal line. They are an annoyance at best, but will push boundaries when given too much rope. The ones in Sunsail Anchorage made the mistake of ripping off some nobles not too long ago. Maybe go smack them around a bit--remind them to respect their betters.", ["objectivesText"] = "Chastise 8 Tideborne. Progress: Have you taught the Tideborne a lesson?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 40 }, { ["id"] = 3379, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240835, ["x"] = 0.424, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240835, ["x"] = 0.424, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[91978] = { ["id"] = 91978, ["name"] = "Taxing the Tideborne", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "Have you ever noticed, that sometimes there is benefit in letting someone think they are getting away with something? The Tideborne will continue to smuggle in plain sight, feeling clever at the taxes they're avoiding paying to Silvermoon. This does add up, though, over time. When you have a moment, please head down to the harbor and relieve them of some of their back taxes.", ["objectivesText"] = "Collect 50 Tideborne Dubloons . Progress: Is it still stealing when stolen from thieves?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249686 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 40 }, { ["id"] = 3379, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240835, ["x"] = 0.424, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240835, ["x"] = 0.424, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[91979] = { ["id"] = 91979, ["name"] = "Chop It Down", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "We received word there's a creature from Lightbloom Ath'Ran making trouble on the western coast. It has caused a bit of drama. Head over and resolve the issue.", ["objectivesText"] = "Kill the Rampaging Ent near Lightbloom Ath'Ran. Progress: Is the issue resolved?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 242241 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 40 }, { ["id"] = 3379, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240835, ["x"] = 0.424, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240835, ["x"] = 0.424, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[91980] = { ["id"] = 91980, ["name"] = "WANTED: Hellebora's Thorn", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91980 }, ["description"] = "See that huge creature over that way? That's Hellebora. She's set herself up too close to the road and we're concerned she's going to wander out of the mire and become even more of a threat. Deal with her, if you can, and bring me back one of her thorns as proof of your hunt.", ["objectivesText"] = "Kill Hellabora. Progress: Hurry up and put Hellebora down before she wanders out of the mire.", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardItems"] = { 249402 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 25 }, { ["id"] = 3310, ["amount"] = 37 }, { ["id"] = 3316, ["amount"] = 50 }, { ["id"] = 3370, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 249361, ["x"] = 0.518, ["y"] = 0.742 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 249361, ["x"] = 0.518, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "group", ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[91981] = { ["id"] = 91981, ["name"] = "To Poison and to Heal", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91490, 91555, 91582, 91785, 91927, 91937, 91981, 92119, 92184, 92582 }, ["rewardXP"] = 13690, ["rewardItems"] = { 269022, 269023 }, ["starts"] = { { ["x"] = 0.436, ["y"] = 0.546, ["mapID"] = 2413 } }, ["ends"] = { { ["x"] = 0.436, ["y"] = 0.546, ["mapID"] = 2413 } }, ["coords"] = { ["mapID"] = 2413, ["x"] = 0.436, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15355 } }, ["questType"] = "world", ["questLines"] = { { ["id"] = 5983, ["name"] = "Harandar - World Quests / Repeatables", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 1, ["amount"] = 4, ["objectID"] = 269022 }, { ["orderIndex"] = 1, ["type"] = 1, ["amount"] = 6, ["objectID"] = 269023 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[91982] = { ["id"] = 91982, ["name"] = "WANTED: Toadshade's Petals", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91982 }, ["description"] = "The three-headed hydra, Hellabora, has been causing havoc in the lower end of Gloom Mire. Give her a good pruning and bring me back her petals as proof.", ["objectivesText"] = "Collect petals from Toadshade. Progress: Less talking, more pruning. Go get those petals.", ["rewardGold"] = 619600, ["rewardXP"] = 16055, ["rewardItems"] = { 249403 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 25 }, { ["id"] = 3310, ["amount"] = 37 }, { ["id"] = 3316, ["amount"] = 50 }, { ["id"] = 3370, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 249361, ["x"] = 0.518, ["y"] = 0.742 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 249361, ["x"] = 0.518, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "group", ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[91983] = { ["id"] = 91983, ["name"] = "Lovely Plumage", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "The beautiful members of the Silvermoon Court do so love their colorful embellishments. For this, we can stock up while doing a good deed! Head over to Thuron's Livery and pick up some of the brightly colored feathers shed from the hawkstriders in training. Vaelith gets clean up service and we get the lovely plumage.", ["objectivesText"] = "Collect 8 Bright Feathers . Progress: Did you find loads of feathers?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249439 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 40 }, { ["id"] = 3379, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240836, ["x"] = 0.428, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240836, ["x"] = 0.428, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[91984] = { ["id"] = 91984, ["name"] = "Sungrub Silk", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "Oh, $p, have you ever visited the Solaarian Sunbath? If not, it's highly recommended. The sungrubs that wander nearby have a precious silk from which amazing fabric can be made. Solwin Brightstitch is reputed to be masterful in this, with his sartorial magic. The raw materials are often sought out to have him create unique and personalized goods from scratch. Bring us some of that lovely silk. It will provide a soft cushion when faced with harder discussions.", ["objectivesText"] = "Gather 1 Sunsilk . Progress: Oh, did you get all of the silk?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249422 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 50 }, { ["id"] = 3379, ["amount"] = 60 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240836, ["x"] = 0.428, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240836, ["x"] = 0.428, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[91985] = { ["id"] = 91985, ["name"] = "Windrunner Memorabilia", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "The nobles do so love the unusual. Take a look around Windrunner Village. There are sure to be some interesting mementos still tucked away there. I will find an advantageous home for the pieces you bring back.", ["objectivesText"] = "Collect 5 Windrunner Memorabilia. Progress: Did you find anything interesting?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249542 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 50 }, { ["id"] = 3379, ["amount"] = 60 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240836, ["x"] = 0.428, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240836, ["x"] = 0.428, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[91986] = { ["id"] = 91986, ["name"] = "Put a Little Snap in Their Step", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "Those naga are, as ever, being a beachfront nuisance. Do they not understand that is a prime location? We may not be able to reliably drive them off, but a little mischief would not be untoward. I found this tune that drives the snapdragons mad. They will just attack whoever is nearby. Take this and give it a shot!", ["objectivesText"] = "Drive 8 Daggerspine Snapdragons mad with a tune. Progress: Are the naga adequately harassed?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249779 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 40 }, { ["id"] = 3379, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240836, ["x"] = 0.428, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240836, ["x"] = 0.428, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[91987] = { ["id"] = 91987, ["name"] = "Potted Lashers", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "It seems some of the nobles are botany-curious where the Lightbloom is concerned. They seek the exotic to adorn their windowsills and lurk in the dangerous section of their greenhouses. That's where you come in, $p! Go harvest those small and pernicious plants. Their bulbs will be the best for planting.", ["objectivesText"] = "Collect 8 Lightblooming Bulbs . Progress: Any problems with the harvest?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249418 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 40 }, { ["id"] = 3379, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240836, ["x"] = 0.428, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240836, ["x"] = 0.428, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[91988] = { ["id"] = 91988, ["name"] = "Brightwing Conservation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "The conservators at Brightwing Estate have a mischievous young dragonhawk named Cerul that likes to run away whenever their backs are turned. He doesn't go far, but it has become a game for him to get them to chase him. Take this delicious treat with you and use it to lure him back home.", ["objectivesText"] = "Lure Cerul back to his home in Brightwing Estate.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249775 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 40 }, { ["id"] = 3379, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240836, ["x"] = 0.428, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240836, ["x"] = 0.428, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[91989] = { ["id"] = 91989, ["name"] = "Ghostland Peppers", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "The delicate blue ghostland peppers may not look like much, but they have a mean burn. Many nobles won't admit it, but they are quite popular in the noble games of \"Truth or Challenge.\" Please procure a few for me. I like to watch them sweat.", ["objectivesText"] = "Collect 12 Ghostland Peppers . Progress: How goes the harvest?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249497 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 40 }, { ["id"] = 3379, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240836, ["x"] = 0.428, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240836, ["x"] = 0.428, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[91990] = { ["id"] = 91990, ["name"] = "Sunset to Sea", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "Naga have set up camp on the Sunset Strand. The sunset slugs that called it home are distraught and seem unsure what to do. This little tune will remind them of their home. Go inspire them to seek the freedom of the open sea.", ["objectivesText"] = "Send 7 Sunset Slugs back to the sea.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 267040 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 50 }, { ["id"] = 3379, ["amount"] = 60 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240836, ["x"] = 0.428, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240836, ["x"] = 0.428, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[91991] = { ["id"] = 91991, ["name"] = "A Little Errand", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "When conversations get tense, it can be challenging to keep words flowing in a productive way. At times like these, I find a little social lubrication is in order. Swing over to Goldenmist Village and pick up a cask of Vintner's Golden . It's proven to have a euphoric side effect that can be quite helpful.", ["objectivesText"] = "Collect a Cask of Vintner's Golden . Progress: Did you find the cask?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249732 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 40 }, { ["id"] = 3379, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240836, ["x"] = 0.428, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240836, ["x"] = 0.428, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[91992] = { ["id"] = 91992, ["name"] = "Where Has the Wine Gone?", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "I entrusted one of my apprentices with the delivery of several cases of particularly expensive wine. He was to bring them here from my private storage, but he has not yet arrived. I should hate to ask you to retrieve him, but I cannot stress enough how expensive those bottles are. Please see if you can locate him and my delivery. He should have been traveling from the north to arrive here.", ["objectivesText"] = "Locate the Magister's lost apprentice in Eversong Woods and figure out what happened to the wine shipment. Progress: I dearly hope my apprentice has a colorful excuse for his tardiness.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249421 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 40 }, { ["id"] = 3379, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240834, ["x"] = 0.426, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240834, ["x"] = 0.426, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[91993] = { ["id"] = 91993, ["name"] = "Diminutive Demand", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "Keeping preciously small animals as pets is a popular pastime among the nobility. The more unconventional the animal, often obtained through magic, the more of a conversation piece it is. I have enchanted this wand with the appropriate shrinking spell. Use it on some of the colorful toads out near the ponds and bring them back here. The nobles will find them delightful. Naturally, the toads may not take kindly to the enchantment. But I trust you can handle that, should it occur.", ["objectivesText"] = "Using the Wand of Diminutive Proportions , shrink and capture 4 Gloombelly Toads near Stillwhisper Pond. Progress: Fear not. The enchantment is quite permanent.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249437 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 40 }, { ["id"] = 3379, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240834, ["x"] = 0.426, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240834, ["x"] = 0.426, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[91994] = { ["id"] = 91994, ["name"] = "Pyrepetal Purposes", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "Lord Saltheril, that old lynx, has put me in a bit of a bind. He has requested a grand fireworks display to accompany tonight's dinner service, but we are dreadfully low on pyrepetal dust. It is an herb native to Eversong, highly flammable and quite dazzling when set aflame by pyromancy. Could you help us replenish our stores? We mostly harvest it from the woods near Scintilas Falls.", ["objectivesText"] = "Gather 5 Eversong Pyrepetals near Scintilas Falls. Progress: Do be careful to keep the pyrepetals away from open flame.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249444 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 50 }, { ["id"] = 3379, ["amount"] = 60 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240834, ["x"] = 0.426, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240834, ["x"] = 0.426, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[91995] = { ["id"] = 91995, ["name"] = "What Horrible Magic", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "Have you seen the encampments the naga have been constructing along our coast? Dreadful business. Not only do they menace our ships and disrupt our trade routes, but they might pose a real threat to Eversong's inland settlements if allowed to continue operations unchecked. Their arcanists are particularly dangerous. Dispose of them and our guests will be in your debt.", ["objectivesText"] = "Slay 4 Daggerspine Infusers near Daggerspine Point. Progress: I trust this task is within your skill set.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 40 }, { ["id"] = 3379, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240834, ["x"] = 0.426, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240834, ["x"] = 0.426, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[91996] = { ["id"] = 91996, ["name"] = "Fit for a Magister", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "Battle prowess and magical skill are important, of course, but one cannot deny the power of appearances. A well-dressed army instills far more faith than one bedecked in rags. Fortunately, a fine set of robes can be both flattering and functional. The mana silk produced at the North Sanctum can be woven into robes that deepen and intensify our magical reserves. Be a dear and gather some for us, would you? My wardrobe could use a seasonal refreshment.", ["objectivesText"] = "Gather 5 Iridescent Mana Silk and weave it into a Bolt of Mana Silk Cloth at the North Sanctum. Progress: Do be careful around the mana wyrms. I understand they can be aggressive after harvesting.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249445 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 40 }, { ["id"] = 3379, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240834, ["x"] = 0.426, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240834, ["x"] = 0.426, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[91997] = { ["id"] = 91997, ["name"] = "Power Clean", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "The festivities have been wonderfully entertaining, which means the nobles have been leaving a bit of a mess around the estate. Lord Saltheril's servants have been keeping up with the cleaning, but the Magisters could lend a hand. Enchanting a few brooms to sweep the pavilion should be an easy but impressive feat. I was informed that an arcanist was employing the same tactic over at Farstrider Hold. Go retrieve some of his brooms and I will have them re-enchanted here.", ["objectivesText"] = "Forcefully deactivate and collect 5 Inanimate Brooms at Farstrider Hold. Progress: Technically any broom would do, but the magic is easier to weave if the object has already been primed to receive the enchantment.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249452 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 40 }, { ["id"] = 3379, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240834, ["x"] = 0.426, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240834, ["x"] = 0.426, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[91998] = { ["id"] = 91998, ["name"] = "WANTED: Muckmire's Choking Vines", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91998 }, ["description"] = "Deep within the swamp is a creature of mud, leaves, and rage. His vines choke the life out of any who come near, and this dangerous creature cannot be allowed to live. Defeat Muckmire and bring me back his vines as proof of the deed.", ["objectivesText"] = "Collect the choking vines of Muckmire. Progress: Be careful Muckmire doesn't drag you into the mud with him.", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardItems"] = { 249404 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 25 }, { ["id"] = 3310, ["amount"] = 37 }, { ["id"] = 3316, ["amount"] = 50 }, { ["id"] = 3370, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 249361, ["x"] = 0.518, ["y"] = 0.742 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 249361, ["x"] = 0.518, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "group", ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[91999] = { ["id"] = 91999, ["name"] = "A Bit of Bloodthistle", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "You know, I bring Saltheril a lot of \"imported\" wine, but one of the first things I started supplying him with was bloodthistle. It's an herb that only grows around Eversong. It's got a smooth bite to it, sort of like mana. Nice and classy. His parties really go through the stuff. I took a look and I don't think he has enough to last this whole thing. We should get some more. The best stuff grows over by the West Sanctum. Grab as much as you can carry. Trust me--it'll go fast.", ["objectivesText"] = "Gather 5 Fragrant Bloodthistle near the West Sanctum. Progress: Trust me. I know how to keep nobles happy.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249472 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 40 }, { ["id"] = 3379, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240837, ["x"] = 0.428, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240837, ["x"] = 0.428, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[92000] = { ["id"] = 92000, ["name"] = "Bring the Ruckus", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "This place is pretty fun so far, despite all the dry political talk. I know Saltheril is trying to get the nobles to buy up war bonds, but we could really use some more energy in here. If the nobles are all asleep, no one's buying anything. Tell you what. Go invite some of my friends. They hang out under the bridge right outside of Silvermoon's gates. If anyone can bring some energy to the soiree, it's us.", ["objectivesText"] = "Pass along Vyrin's invitation to 6 of his \"trader\" friends near the Path of Dawn.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 40 }, { ["id"] = 3379, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240837, ["x"] = 0.428, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240837, ["x"] = 0.428, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[92001] = { ["id"] = 92001, ["name"] = "One Smuggler to Another", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "The whole point of this deal is showing the nobles what we bring to the table, both for Silvermoon and for them personally. These other groups bring strength, power, and really nice armor. What we bring is resources: getting the sin'dorei what they need, when they need it, with no questions asked. I heard some folks over at Sunsail Anchorage have been trying out the same business, but they're putting gold in the wrong pockets. Swipe their stock and bring it here.", ["objectivesText"] = "Collect 5 Smuggled Goods around Sunsail Anchorage. Progress: I don't mind competitors, but I don't like the deals those smugglers are making.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249517 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 50 }, { ["id"] = 3379, ["amount"] = 60 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240837, ["x"] = 0.428, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240837, ["x"] = 0.428, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[92002] = { ["id"] = 92002, ["name"] = "Dangerous Showpieces", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "You'd be surprised at the money you can make off of weapons. No, not the kind you're meant to use--the kind you stick up on the wall and have conversations about. Usually those weapons are expensive, or dangerous, or otherwise hard to get your hands on. The more rare and exclusive, the better. The weapons those Twilight cultists are carrying around should sell pretty well, especially to buyers with edgier tastes. If you happen to come across any, I'll gladly take them off your hands.", ["objectivesText"] = "Collect 6 pieces of Twilight Weaponry from cultists at the Sanctum of the Moon. Progress: If it has some blood on it, that's actually better.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249528 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 40 }, { ["id"] = 3379, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240837, ["x"] = 0.428, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240837, ["x"] = 0.428, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[92003] = { ["id"] = 92003, ["name"] = "Artisanal Replicas", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "Don't let the austere demeanor fool you. Nobles are just as susceptible to flashy party favors as the rest of us. I had my people bring over a batch of Felo'melorn replicas . They look great on display, and even better--they're enchanted. Swing them around and they leave a trail of fire. I haven't sold an enchanted batch before, so I'd like to do some testing before I hand them out. Saltheril wouldn't be too happy if I burned a guest to a crisp. Wanna take one of the replicas for a test run?", ["objectivesText"] = "Test the fiery capabilities of the Felo'melorn Replica on 5 creatures near Lightbloom Ath'Ran.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249688 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 50 }, { ["id"] = 3379, ["amount"] = 60 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240837, ["x"] = 0.428, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240837, ["x"] = 0.428, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[92004] = { ["id"] = 92004, ["name"] = "Shady Dealings", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "I feel like I just got here and I'm already fresh out of half the poisons I brought. What? Don't look at me like that. Nobles are some of my top customers for poisons. Quieter than magic and cleaner than blades. I need to restock. The frogs way down in the south produce a poisonous slime that I can bottle without much fuss. Bring some of it to me and I'll get you a cut of the earnings.", ["objectivesText"] = "Collect 6 Poisonous Frog Secretions from frogs near the Amani Pass. Progress: Were you able to find any of those frogs?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249687 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 50 }, { ["id"] = 3379, ["amount"] = 60 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240837, ["x"] = 0.428, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240837, ["x"] = 0.428, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[92005] = { ["id"] = 92005, ["name"] = "Throw the Dice", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "We've been making friends with some of the guests by teaching them how to play dice. It's a nice way to draw people out of the crowd and get them in a quieter space where you can talk privately. I wasn't expecting so much interest, to be honest. We're running out of dice sets. I can carve some more, but I'll need materials. Usually teeth or bone are good picks. Actually, the fangs from those naga along the coast would be perfect. Now that's a conversation starter!", ["objectivesText"] = "Collect 12 Naga Fangs from naga near the Sunset Strand. Progress: Any luck finding some of those fangs?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249541 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3310, ["amount"] = 52 }, { ["id"] = 3379, ["amount"] = 40 }, { ["id"] = 3379, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240837, ["x"] = 0.428, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240837, ["x"] = 0.428, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[92006] = { ["id"] = 92006, ["name"] = "We Need a Refill", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "I talked to some of the servants earlier and it sounds like the casks are running low. That's a recipe for disaster at an event like this. Fortunately, I've got a lot of contacts across Eversong who can help us restock. I need to stay here and play politics, but could you head over to Tranquillien and grab a few bottles? I'll give you a list.", ["objectivesText"] = "Purchase a case of Bloodthistle Brandy , Mana Burner , and Sun-Kissed Tranquilla from vendors in Tranquillien. Progress: Trust me. Everything on that list is fantastic.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249555, 249556, 249557 }, ["rewardCurrencies"] = { { ["id"] = 3379, ["amount"] = 40 }, { ["id"] = 3379, ["amount"] = 50 }, { ["id"] = 3396, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240837, ["x"] = 0.428, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240837, ["x"] = 0.428, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[92007] = { ["id"] = 92007, ["name"] = "Begged, Borrowed, or Stolen", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89276, 89277, 89278, 89285, 89289, 89307, 89311, 89314, 90573, 90574, 90575, 90576, 91971, 91972, 91973, 91974, 91975, 91976, 91977, 91978, 91979, 91983, 91984, 91985, 91986, 91987, 91988, 91989, 91990, 91991, 91992, 91993, 91994, 91995, 91996, 91997, 91999, 92000, 92001, 92002, 92003, 92004, 92005, 92006, 92007 }, ["description"] = "The oldest trick in the book is to create a problem on purpose, solve it yourself, and look like the hero. One of the nobles just got word that some prized valuable was stolen from their estate while they were occupied here. It just so happens I might have put one of their servants up to it. Go talk to a man named Seridis over at the livery. He'll hand over the valuable to you, then you'll come back here and pretend you valiantly subdued the thief and retrieved the item. Everyone's happy.", ["objectivesText"] = "Speak to Seridis at Thuron's Livery, then retrieve the stolen item. Progress: Making friends with the servants in noble households opens up a lot of doors. Sometimes literally.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 242241, 249544 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 }, { ["id"] = 3379, ["amount"] = 40 }, { ["id"] = 3379, ["amount"] = 50 }, { ["id"] = 3379, ["amount"] = 60 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240837, ["x"] = 0.428, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240837, ["x"] = 0.428, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5841, ["name"] = "Saltheril's Haven", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5316 }, ["db2PoiUiMapID"] = 2395 },
[92010] = { ["id"] = 92010, ["name"] = "WANTED: Slewstalk's Stalks", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92010 }, ["description"] = "Not far from here, Slewstalk lurks in the shallows. This creature has developed a taste for flesh and bones, and it won't be long until she wanders out of the Mire in search for warmer blooded prey. Take her out and bring me her luminescent stalks . They'll serve as proof and also make a fine centerpiece for an evening table.", ["objectivesText"] = "Collect luminecent stalks from Slewstalk. Progress: Try to take Slewstalk down before she can get those long grippers of hers around you.", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardItems"] = { 249405 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 25 }, { ["id"] = 3310, ["amount"] = 37 }, { ["id"] = 3316, ["amount"] = 50 }, { ["id"] = 3370, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 249361, ["x"] = 0.518, ["y"] = 0.742 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 249361, ["x"] = 0.518, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "group" },
[92012] = { ["id"] = 92012, ["name"] = "WANTED: Gorebarb's Pincers", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92012 }, ["description"] = "Gorebarb is a creature quite unlike most others who make Harandar their home. He's incredibly violent and his kind is not seen here very often. Let's see less of him. Kill him and bring me his pincers as proof of the deed.", ["objectivesText"] = "Collect Gorebarb's Pincers . Progress: Take care that Gorebarb doesn't catch you with those pincers. I imagine his breath isn't pleasant at all.", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardItems"] = { 249406 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 25 }, { ["id"] = 3310, ["amount"] = 37 }, { ["id"] = 3316, ["amount"] = 50 }, { ["id"] = 3370, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 249361, ["x"] = 0.518, ["y"] = 0.742 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 249361, ["x"] = 0.518, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "group", ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[92013] = { ["id"] = 92013, ["name"] = "WANTED: Dionaea's Thorntusks", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92013 }, ["description"] = "Many thornmaws make the mire their home, but none as are vicious as Dionaea. Unlike the others, she kills merely for the joy of it, and her gluttony threatens the delicate balance of the wildlife in this area. Take her out and restore the equilibrium. Bring me back her thorntusks as proof of the deed.", ["objectivesText"] = "Collect Dionaea's thorntusks. Progress: Dionaea hunts for the thrill of it. She seems to be unable to satiate her hunger. Have you handled her yet?", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardItems"] = { 249408 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 25 }, { ["id"] = 3310, ["amount"] = 37 }, { ["id"] = 3316, ["amount"] = 50 }, { ["id"] = 3370, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 249361, ["x"] = 0.518, ["y"] = 0.742 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 249361, ["x"] = 0.518, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "group", ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[92021] = { ["id"] = 92021, ["name"] = "Graveblossom Gardening", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 92021, 92022, 92023, 92024, 92025 }, ["description"] = "My colleague Amalthea has taken ill. She requires a specialized poultice of sorts in order to ease the symptoms. I would forage for the plants myself, but the local fauna have grown so testy as of late! While you are out and about, could you gather some graveblossoms for me? I'd happily make it worth your while.", ["objectivesText"] = "Gather 8 Pristine Graveblossoms for Talandra Dawnsprite at Windrunner Village. Progress: Oh, come now. While we stand here and chat about the weather, my associate continues to suffer under the travails of her malady! Get on with it. It's gloomy, by the way. The weather. As usual.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 249471 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 249337, ["x"] = 0.358667, ["y"] = 0.746 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 249337, ["x"] = 0.358667, ["y"] = 0.746 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.358667, ["y"] = 0.746 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 90494 }, ["questLines"] = { { ["id"] = 6020, ["name"] = "Flowers for Amalthea", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[92022] = { ["id"] = 92022, ["name"] = "A Venomous Vocation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 92021, 92022, 92023, 92024, 92025 }, ["description"] = "My poultice requires venom samples from the local giant bat populations. Please retrieve some of those, as well. Six common vials' worth should do. Don't give me that look. They're bats. There are mad Light-plant-things to the east and a storm of voidwalkers swirling over our heads. Don't you dare give me guff about the dangers of big, fluffy bats. Now shoo. My colleague is depending on your prompt and efficient aid.", ["objectivesText"] = "Collect six vials of Potent Mournbat Venom from mournbats outside of Windrunner Village. Progress: Strictly speaking, a stronger venom would have a more ample effect. But we're living in strenuous times. This Void hooplah has my usual supply lines at Sunsail completely occupied. We'll have to make do with mournbat venom. Now go.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 253869 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 249337, ["x"] = 0.358667, ["y"] = 0.746 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 249337, ["x"] = 0.358667, ["y"] = 0.746 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.358667, ["y"] = 0.746 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 90494 }, ["questLines"] = { { ["id"] = 6020, ["name"] = "Flowers for Amalthea", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[92023] = { ["id"] = 92023, ["name"] = "Suspicious Sundries", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 92021, 92022, 92023, 92024, 92025 }, ["description"] = "Forgive me for my failure to provide specifics, traveler. The mournbat venom and the graveblossoms were only the first of the reagents I require for my associate's medication. Luckily, the final few things I require can all be easily obtained in Goldenmist Village to the north. Be a dear and fetch these last few things for me, won't you? With these, my toil will be nearly complete.", ["objectivesText"] = "Fetch a Vial of Quicksilver , a Flask of Dragon's Blood , and a Bottle of Magister's Reserve from the vendors at Goldenmist Village. Progress: Eugh. Why do I smell grave soil on you?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 254280, 254281, 254282 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 249337, ["x"] = 0.358667, ["y"] = 0.746 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 249426, ["x"] = 0.406, ["y"] = 0.6 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.358667, ["y"] = 0.746 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 92021, 92022 }, ["questLines"] = { { ["id"] = 6020, ["name"] = "Flowers for Amalthea", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[92024] = { ["id"] = 92024, ["name"] = "House Call", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 92021, 92022, 92023, 92024, 92025 }, ["description"] = "That woman, that \"apothecary,\" has snared you in one of her schemes. I'd be careful around her, <class>. Rumors travel like wildfire in Eversong. And while I would never disparage a fellow artisan of Eversong without cause, I have heard enough rumors to know that your apothecary deals in more than simple herbs. Take your wine and your reagents, I suppose. But before you pass them off to your patroness, I'd recommend doing some digging--lest you find yourself wrapped up in something you come to regret.", ["objectivesText"] = "Investigate Talandra's home in Windrunner Village.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 249426, ["x"] = 0.406, ["y"] = 0.6 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 249426, ["x"] = 0.406, ["y"] = 0.6 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.6 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questTurnInID"] = 249426, ["questType"] = "standard", ["sourceQuests"] = { 92023 }, ["questLines"] = { { ["id"] = 6020, ["name"] = "Flowers for Amalthea", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[92025] = { ["id"] = 92025, ["name"] = "Flowers for Amalthea", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 92021, 92022, 92023, 92024, 92025 }, ["description"] = "<The final pages of the tome detail a meeting place. Whatever Talandra Dawnsprite intends to do, she means to do it amidst the ghosts of Windrunner Spire. The time for Talandra's ritual grows nigh.>", ["objectivesText"] = "Confront Talandra Dawnsprite at Windrunner Spire. Progress: <Time is of the essence. Talandra's ritual approaches.>", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 257418 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3365, ["amount"] = 250 } }, ["starts"] = { { ["npcID"] = 253058, ["mapID"] = 2395, ["x"] = 0.374497, ["y"] = 0.720571 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 249337, ["x"] = 0.358667, ["y"] = 0.746 }, { ["npcID"] = 253058, ["mapID"] = 2395, ["x"] = 0.374497, ["y"] = 0.720571 } }, ["coords"] = { ["source"] = "quest_giver", ["mapID"] = 2395, ["x"] = 0.374497, ["y"] = 0.720571 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 92024 }, ["questLines"] = { { ["id"] = 6020, ["name"] = "Flowers for Amalthea", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[92028] = { ["id"] = 92028, ["name"] = "Pardon the Interruption", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16432, ["mapID"] = 2451, ["storyline"] = { 92028, 93382 }, ["description"] = "<name>! Glad to see you. The defenders in the fortress could use your help. One of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on. She needs the help of someone who can properly interrupt the robot's attacks so it can be repaired. Do you have a moment to help?", ["objectivesText"] = "Activate Fightbot 11.2.7, then interrupt its abilities 3 times. Progress: Some help! Hopefully you can find a way to interrupt this bot's abilities.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2451, ["npcID"] = 249423, ["x"] = 0.194667, ["y"] = 0.574667 } }, ["ends"] = { { ["mapID"] = 2451, ["npcID"] = 249456, ["x"] = 0.208, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 2451, ["source"] = "quest_giver", ["x"] = 0.194667, ["y"] = 0.574667 }, ["mapCandidates"] = { ["npc"] = { 2451 }, ["zone"] = { 16432 } }, ["questType"] = "standard", ["sourceQuests"] = { 90885, 90886, 90887 }, ["questLines"] = { { ["id"] = 5985, ["name"] = "Siege of Arathi Highlands - Side Quests", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2927, ["db2PoiUiMapID"] = 2451 },
[92030] = { ["id"] = 92030, ["name"] = "A New Tradition", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredRaces"] = { 26 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15543, ["mapID"] = 2366, ["storyline"] = { 84442, 84444, 84451, 84452, 84453, 84454, 84455, 84456, 84457, 84458, 84459, 84460, 84461, 84462, 84463, 84464, 84465, 84466, 84467, 84468, 92030 }, ["description"] = "Chon was just looking for you. You can find him at his house, serving drinks with Chen. < Lorewalker Cho laughs--a deep, warm rumble.> Go on, $p! I won't be leaving anytime soon, that's for sure.", ["objectivesText"] = "Meet Chon Po in Wu-Song Village.", ["rewardGold"] = 31900, ["rewardXP"] = 850, ["rewardItems"] = { 242520, 258635, 258657 }, ["starts"] = { { ["mapID"] = 2366, ["npcID"] = 229476, ["x"] = 0.524, ["y"] = 0.192 } }, ["ends"] = { { ["mapID"] = 2366, ["npcID"] = 231913, ["x"] = 0.505, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 2366, ["source"] = "quest_giver", ["x"] = 0.524, ["y"] = 0.192 }, ["mapCandidates"] = { ["npc"] = { 2366 }, ["zone"] = { 15543 } }, ["questType"] = "standard", ["sourceQuests"] = { 84467 }, ["questLines"] = { { ["id"] = 5682, ["name"] = "Pandaren Heritage", ["orderIndex"] = 20, ["flags"] = 0 } }, ["db2PoiMapID"] = 2794, ["db2PoiUiMapID"] = 2366 },
[92031] = { ["id"] = 92031, ["name"] = "Meet the Vandals", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16178, ["mapID"] = 2371, ["storyline"] = { 92031 }, ["description"] = "<The Manaforge Vandals at Shadow Point are eager to see the Shadowguard and their allies removed from Manaforge Omega . It's probably a good time to pay them a visit.>", ["objectivesText"] = "Report to Zo'turu at Shadow Point.", ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 245344, ["x"] = 0.42, ["y"] = 0.222 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 245344, ["x"] = 0.42, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard" },
