[92061] = { ["id"] = 92061, ["name"] = "Rising Storm", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 86543, 86549, 86557, 86558, 86559, 86561, 86562, 86565, 89388, 92061 }, ["description"] = "That was an entropic wave. We felt them just before Xal'atath launched her assault on the Sunwell. Champion, you move faster than my best messengers. I need you to check in with the Vanguard commanders and see if their defenses will hold against this latest assault by Xal'atath's Devouring Host.", ["objectivesText"] = "De-escalate rising tensions in Silvermoon City . Progress: Tensions are high.", ["rewardGold"] = 319000, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 91084 }, ["questLines"] = { { ["id"] = 5728, ["name"] = "Into the Abyss", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5728, ["questLineOrder"] = 13 } }, ["db2PoiUiMapID"] = 2393 },
