[92104] = { ["id"] = 92104, ["name"] = "Broomstick Express", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 11, ["storyline"] = { 92104 }, ["description"] = "Hmm. You look like you can ride a broom without crashin' into a chimney. Hallow's End is a busy time for all kinds of deliveries. Got sweets, potions, pumpkins, haunted socks - don't ask - all goin' to the usual oddballs. Take that broom over there, fly fast to make those deliveries, and don't drop nothin'.", ["objectivesText"] = "Deliver the package to the designated location.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
