[92106] = { ["id"] = 92106, ["name"] = "Ignite the Skies: Northern Kalimdor", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["description"] = "Midsummer is the time to reflect and a time to tell stories by the bonfire. One such story is the tale of the sun blossom ritual and how this offering to An'she first came to be. Our journey will take us through Northern Kalimdor, into territories beyond the lands of the shu'halo. If you wish, take to the skies of Kalimdor and ignite the blossoms as I tell the tale. Our story begins in the Western Barrens...", ["rewardGold"] = 341600, ["rewardItems"] = { 23247 }, ["starts"] = { { ["npcID"] = 250811, ["x"] = 0.478, ["y"] = 0.374, ["mapID"] = 85 }, { ["npcID"] = 265658, ["x"] = 0.624, ["y"] = 0.116, ["mapID"] = 10 } }, ["ends"] = { { ["npcID"] = 251986, ["x"] = 0.222, ["y"] = 0.192, ["mapID"] = 10 }, { ["npcID"] = 251986, ["x"] = 0.316, ["y"] = 0.636, ["mapID"] = 71 } }, ["coords"] = { ["x"] = 0.478, ["y"] = 0.374, ["source"] = "quest_giver", ["mapID"] = 71 }, ["mapCandidates"] = { ["npc"] = { 10, 71, 85 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 92435, 92635 } },
