[92155] = { ["id"] = 92155, ["name"] = "Object Exorcism", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 92155, 92156, 92157, 92158, 92159, 92390 }, ["description"] = "I reached out to examine a console that had dark energy moving through it, but something screamed in my face. It was so unexpected. It didn't feel like an alarm, more like something... vicious. Angry. Hungry. It almost felt like it wanted to grab me. Terrifying. And interesting! Take a look around and see what you can learn. Check for visible disturbances.", ["objectivesText"] = "Investigate the research areas in Shadow Rise. Progress: Be cautious as you check this area. We don't know what we're dealing with, yet.", ["rewardGold"] = 309800, ["rewardXP"] = 12845, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 249935, ["x"] = 0.637, ["y"] = 0.652 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 249935, ["x"] = 0.637, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 92390 }, ["questLines"] = { { ["id"] = 5987, ["name"] = "Shadowguard's Shadow", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[92156] = { ["id"] = 92156, ["name"] = "It Follows Me", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 92155, 92156, 92157, 92158, 92159, 92390 }, ["description"] = "You must listen. An evil creature attached itself to me not long ago. It followed me about, angrily hurling objects, playing tricks, and consuming anything it could. Just now, it stopped following me. It likes you now, I think. If you feed it, it should leave you be for a time. Mark the defeated in the Sparring Grounds with this brand. It should consume them, giving us time to talk more.", ["objectivesText"] = "Mark 8 defeated Shadowguard in the Sparring Grounds.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 57363, 57364, 57365, 251278 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 249917, ["x"] = 0.646, ["y"] = 0.642 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 249917, ["x"] = 0.646, ["y"] = 0.642 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.646, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 92155 }, ["questLines"] = { { ["id"] = 5987, ["name"] = "Shadowguard's Shadow", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[92157] = { ["id"] = 92157, ["name"] = "Ritual Activity", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 92155, 92156, 92157, 92158, 92159, 92390 }, ["description"] = "While you were gone, we were busy. My idea is to force the malevolent entity out into the open--out of its hiding places. Havazza gathered up items that have the entity attached to them. I don't trust her, but if she wants to lift heavy things, at least I don't have to. By destroying the scattered things it is possessing, we will flush it out of hiding!", ["objectivesText"] = "Force the entity to appear by destroying the hiding places. Progress: We'll destroy the hiding places, and draw it out.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 249935, ["x"] = 0.637, ["y"] = 0.652 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 249935, ["x"] = 0.637, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 92156 }, ["questLines"] = { { ["id"] = 5987, ["name"] = "Shadowguard's Shadow", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[92158] = { ["id"] = 92158, ["name"] = "Let It In", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 92155, 92156, 92157, 92158, 92159, 92390 }, ["description"] = "The entity is definitely attached to you, <name>. It even imitated you. I bet it mimics the body of its main target, changing depending on what it's eating. Now that I've seen it in action, I'm confident I can make a container to hold it. You trust me, right? Just outside of Shadow Rise, there is a clear area on the upper bluffs of Claw's Edge. I want to get it away from these objects, like that chair. Brand yourself as defeated and wait. It will come. Ambush it when you see an opening. We'll trap it!", ["objectivesText"] = "Feign death on the hill in Claw's Edge and defeat the entity when it comes for you. Progress: You're not that idiotic ethereal, and you have me to help you. You'll be fine.", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardItems"] = { 20723, 25929, 25930, 25931, 25932, 33226, 34068, 37971, 38014, 38057, 38118, 38671, 60911, 60912, 60913, 84105, 87399, 130903, 131575, 139506, 139746, 140422, 156973, 156974, 247911 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3389, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 249935, ["x"] = 0.637, ["y"] = 0.652 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 251277, ["x"] = 0.69, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 92157 }, ["questLines"] = { { ["id"] = 5987, ["name"] = "Shadowguard's Shadow", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[92159] = { ["id"] = 92159, ["name"] = "A Final Destination", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 92155, 92156, 92157, 92158, 92159, 92390 }, ["description"] = "Havazza betrayed us and left you to clean up after her. It could have killed you. She should face the consequences of her actions. I am sure she is back to duels, revelling in her returned strength at your expense. We should start with the Shenzar Refinery area next to the Sparring Grounds. Challenge her to a real duel!", ["objectivesText"] = "Meet with Lanlae near the Shenzar Refinery and defeat Havazza in combat. Progress: She did not give you mercy. Don't give her any either.", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardItems"] = { 264304, 264305, 264306, 264307 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3389, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 251277, ["x"] = 0.69, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 251286, ["x"] = 0.574, ["y"] = 0.474 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.69, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 92158 }, ["questLines"] = { { ["id"] = 5987, ["name"] = "Shadowguard's Shadow", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[92160] = { ["id"] = 92160, ["name"] = "Hatchling Havoc", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 92105, 92120, 92121, 92122, 92138, 92139, 92140, 92141, 92143, 92144, 92145, 92146, 92149, 92150, 92152, 92153, 92160, 92195, 92364 }, ["objectivesText"] = "Unruly hatchling captured", ["rewardXP"] = 13690, ["starts"] = { { ["x"] = 0.568, ["y"] = 0.356, ["mapID"] = 2395 } }, ["ends"] = { { ["x"] = 0.568, ["y"] = 0.356, ["mapID"] = 2395 } }, ["coords"] = { ["mapID"] = 2395, ["x"] = 0.568, ["y"] = 0.356 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15968 } }, ["questType"] = "world", ["questLines"] = { { ["id"] = 5986, ["name"] = "Eversong Woods - World Quests/Repeatables", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 10, ["objectID"] = 251163, ["text"] = "Unruly hatchling captured" } }, ["db2PoiUiMapID"] = 2395, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[92162] = { ["id"] = 92162, ["name"] = "A Refined Potadpalate", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92162 }, ["objectivesText"] = "Mural activated Hunger sated Dinners Devoured Snacks Savored", ["rewardXP"] = 13690, ["rewardItems"] = { 182694 }, ["starts"] = { { ["x"] = 0.362, ["y"] = 0.461, ["mapID"] = 2413 } }, ["ends"] = { { ["x"] = 0.362, ["y"] = 0.461, ["mapID"] = 2413 } }, ["coords"] = { ["mapID"] = 2413, ["x"] = 0.362, ["y"] = 0.461 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15355 } }, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 250018, ["text"] = "Mural activated" }, { ["orderIndex"] = 1, ["type"] = 15, ["amount"] = 1, ["objectID"] = 0, ["text"] = "Hunger sated" }, { ["orderIndex"] = 2, ["type"] = 0, ["amount"] = 20, ["objectID"] = 250684, ["text"] = "Dinners Devoured" }, { ["orderIndex"] = 3, ["type"] = 0, ["amount"] = 20, ["objectID"] = 250742, ["text"] = "Snacks Savored" }, { ["orderIndex"] = 4, ["type"] = 0, ["amount"] = 10, ["objectID"] = 250684 }, { ["orderIndex"] = 5, ["type"] = 0, ["amount"] = 20, ["objectID"] = 250742 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[92163] = { ["id"] = 92163, ["name"] = "The Loa of Murlocs", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 92163, 92164, 92165, 92166, 92167 }, ["description"] = "Have you heard of de commotion comin' from Atal'Abasi? De murlocs there are gettin' riled up about somethin'. It seems like de murlocs have summoned a loa of their own. And dis loa is rallyin' de murlocs to war. I saw it myself! Just today, lookin' down from dis cliff. De biggest murloc you've ever seen! I'm not de only one who've seen it either! But de elders say we have bigger problems. Bah! Dey better not come to me when we get overrun by murlocs!", ["objectivesText"] = "Investigate the Loa of Murlocs at Atal'Abasi.", ["rewardGold"] = 30900, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3354, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 257092, ["x"] = 0.46, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 250196, ["x"] = 0.528, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91958 }, ["nextQuests"] = { 92164, 92165, 92166 }, ["questLines"] = { { ["id"] = 5988, ["name"] = "The Loa of Murlocs", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiUiMapID"] = 2437 },
[92164] = { ["id"] = 92164, ["name"] = "Murloc Madness", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 92163, 92164, 92165, 92166, 92167 }, ["description"] = "These murlocs have come to me, the Loa of Murlocs, to seek my protection against an evil invader. The Deepfin have risen from the abyssal depths of the ocean. They have invaded this land and defiled its grounds! I charge you, champion, to defend this kingdom and drive the Deepfin back into the sea! < King Mrgl-Mrgl lowers his voice to a whisper.> Get rid of the invaders and maybe the natives won't need me to protect them, and I can leave!", ["objectivesText"] = "Slay 15 Deepfin murlocs at Atal'Abasi.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 250196, ["x"] = 0.528, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 250196, ["x"] = 0.528, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 92163 }, ["questLines"] = { { ["id"] = 5988, ["name"] = "The Loa of Murlocs", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[92165] = { ["id"] = 92165, ["name"] = "Fish Are Food, Not Friends", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 92163, 92164, 92165, 92166, 92167 }, ["description"] = "I have heard your mrgls, my people. Your stomachs grgl in hunger! The invaders have cut you off from the food you so desperately need to survive. I will send my champion to gather fish so you may fill your bellies once more! < King Mrgl-Mrgl lowers his voice to a whisper.> Or you can just give me fish if you have some?", ["objectivesText"] = "Collect 30 Murloc-Skewered Lynxfish or give King Mrgl-Mrgl 30 Lynxfish. Progress: My kingdom is ready for a feast! Are you prepared?", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 263202 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 250196, ["x"] = 0.528, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 250196, ["x"] = 0.528, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 92163 }, ["questLines"] = { { ["id"] = 5988, ["name"] = "The Loa of Murlocs", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[92166] = { ["id"] = 92166, ["name"] = "Following Suit", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 92163, 92164, 92165, 92166, 92167 }, ["description"] = "My fellow murlocs! One among you was chosen to be my... my chosen! She is destined for greatness and is my assistant... erm, priestess! Yes, priestess of the loa! Your priestess has gone missing, possibly taken by the treacherous Deepfin. To showcase my great power, I will send my champion to find and return her to you. < King Mrgl-Mrgl lowers his voice to a whisper.> My assistant is missing, and I'm stuck here! Find her and tell her I'm on top of the temple!", ["objectivesText"] = "Track down the priestess of the Loa of Murlocs. Progress: <name>! I command you to return my priestess unharmed.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 250196, ["x"] = 0.528, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 250196, ["x"] = 0.528, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 92163 }, ["questLines"] = { { ["id"] = 5988, ["name"] = "The Loa of Murlocs", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[92167] = { ["id"] = 92167, ["name"] = "There Can Be Only One", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 92163, 92164, 92165, 92166, 92167 }, ["description"] = "I've observed the Deepfin kidnapping native murlocs and raising troll corpses as undead thralls. But they don't push further inland--they take them all back to the sea. I think they're being led by a powerful murloc who remains safely offshore, hiding from view as it accepts its minions' tribute. We can draw it out. If you put on this murloc suit and offer tribute, it might fool the leader into showing itself. If we eliminate the leader, we might be able to save the native murlocs!", ["objectivesText"] = "Don the Spare Murloc Suit and offer tribute at the underwater shrine to draw out and slay the leader of the Deepfin murlocs.", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 5462, 34620, 263446, 264471, 264472, 264473, 264474 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3354, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 250197, ["x"] = 0.528, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 250196, ["x"] = 0.528, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 92164, 92165, 92166 }, ["questLines"] = { { ["id"] = 5988, ["name"] = "The Loa of Murlocs", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[92177] = { ["id"] = 92177, ["name"] = "One Hero's Prey", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 92177, 92178, 92179, 92180, 92181, 92182 }, ["series"] = { 92178 }, ["description"] = "Again, we sin'dorei find our city under assault. And again, it is up to the finer minds among us to come to Silvermoon's aid. Mortal anguish, it seems, is a powerful reflection of the soul. When contained and manipulated, anguish acts as a form of magic that we can wield to protect this great city. I've located a number of anguish-filled targets across Azeroth. Select and hunt one such target, storing their anguish in this crystalline vessel. Then return to me.", ["objectivesText"] = "Hunt a Prey target and return the crystalline vessel to Astalor Bloodsworn .", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["rewardItems"] = { 249433 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 246231, ["x"] = 0.565333, ["y"] = 0.654667 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 246231, ["x"] = 0.565333, ["y"] = 0.654667 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.565333, ["y"] = 0.654667 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 93086 }, ["questLines"] = { { ["id"] = 6041, ["name"] = "Astalor's Temptations", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[92178] = { ["id"] = 92178, ["name"] = "Practical Magic", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 92177, 92178, 92179, 92180, 92181, 92182 }, ["series"] = { 92177 }, ["description"] = "While you've been out pursuing targets, I've been developing various applications for anguish. The power these raw emotions contain is unfathomable. For now, our applications might seem quaint, but given enough time, I'm certain my discoveries will further Silvermoon's aims. Let me show you. Take the crystalline vessel and meet me below.", ["objectivesText"] = "Accompany Astalor into the chambers below and imbue objects with the power of anguish.", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["rewardItems"] = { 264513 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 246231, ["x"] = 0.565333, ["y"] = 0.654667 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 246231, ["x"] = 0.565333, ["y"] = 0.654667 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.565333, ["y"] = 0.654667 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 92177 }, ["questLines"] = { { ["id"] = 6041, ["name"] = "Astalor's Temptations", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[92179] = { ["id"] = 92179, ["name"] = "Dark Mending", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 92177, 92178, 92179, 92180, 92181, 92182 }, ["description"] = "So far, anguish has been invaluable in bolstering our forces. Our weaponry and golems are all the more hardy and potent thanks to this newfound power. I've also been developing ways to shape anguish into robust enchantments that can strengthen us elves. Meet me downstairs. I will show you what I've found.", ["objectivesText"] = "Follow Astalor into his lower chambers and assist in his discoveries.", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 246231, ["x"] = 0.565333, ["y"] = 0.654667 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 246231, ["x"] = 0.565333, ["y"] = 0.654667 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.565333, ["y"] = 0.654667 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 92178 }, ["questLines"] = { { ["id"] = 6041, ["name"] = "Astalor's Temptations", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[92180] = { ["id"] = 92180, ["name"] = "Precious Jewels", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 92177, 92178, 92179, 92180, 92181, 92182 }, ["description"] = "<name>... While you've been away, I've been refining our work. <He produces a jeweled ring in the palm of his hand.> Small trinkets and jewelry that contain crystallized anguish. I've discretely gifted these to a few willing Silvermoon citizens. I wish to observe the effect of a controlled concentration of anguish over time. I've shaped the magic to lend the bearer health and strength. Seek our volunteers out and check up on them.", ["objectivesText"] = "Check in with the elves that have accepted Astalor's trinkets. Progress: My work here will make the world fear Silvermoon's might.", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["rewardItems"] = { 258023 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 246231, ["x"] = 0.565333, ["y"] = 0.654667 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 246231, ["x"] = 0.565333, ["y"] = 0.654667 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.565333, ["y"] = 0.654667 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 92179 }, ["questLines"] = { { ["id"] = 6041, ["name"] = "Astalor's Temptations", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[92181] = { ["id"] = 92181, ["name"] = "Garden Variety Sacrifices", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 92177, 92178, 92179, 92180, 92181, 92182 }, ["description"] = "<name>... I need you to attend to a matter in the city. I've received word from Knight Captain Solara that there's been an incident in the Gardens of Remembrance. She reports elves have begun acting out violently, causing coalesced anguish to manifest and terrorize the residents. You can use the crystalline vessel to reclaim the coalesced anguish and sooth the elves whose minds have crumbled. So much of the magic will weigh heavy upon you, but I'm confident you have the strength.", ["objectivesText"] = "Elves rescued and Coalesced Anguish reclaimed in the Gardens of Remembrance. Progress: In all of my endeavors, there are always some who seek to impede my progress.", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 246231, ["x"] = 0.565333, ["y"] = 0.654667 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 246231, ["x"] = 0.565333, ["y"] = 0.654667 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.565333, ["y"] = 0.654667 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 92180 }, ["questLines"] = { { ["id"] = 6041, ["name"] = "Astalor's Temptations", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[92182] = { ["id"] = 92182, ["name"] = "The Sheep or the Wolf", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 92177, 92178, 92179, 92180, 92181, 92182 }, ["description"] = "I heard word of your heroics in the garden. Silvermoon thanks you for quelling the chaos. And I thank you for recovering so much anguish. The crystalline vessel may be the conduit, but the body must be robust to handle so much power... Like me, you have the strength to withstand the torrent of anguish inside you, at least for a short while. Come, let me relieve you of the burden.", ["objectivesText"] = "Meet with Astalor below his chambers in Silvermoon City.", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 246231, ["x"] = 0.565333, ["y"] = 0.654667 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 246231, ["x"] = 0.565333, ["y"] = 0.654667 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.565333, ["y"] = 0.654667 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 92181 }, ["questLines"] = { { ["id"] = 6041, ["name"] = "Astalor's Temptations", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[92184] = { ["id"] = 92184, ["name"] = "Potadpole Wrangling", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 91490, 91555, 91582, 91785, 91927, 91937, 91981, 92119, 92184, 92582 }, ["objectivesText"] = "Potadpole captured Release the potatoads", ["rewardXP"] = 13690, ["starts"] = { { ["x"] = 0.679, ["y"] = 0.416, ["mapID"] = 2413 } }, ["ends"] = { { ["x"] = 0.679, ["y"] = 0.416, ["mapID"] = 2413 } }, ["coords"] = { ["mapID"] = 2413, ["x"] = 0.679, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15355 } }, ["questType"] = "world", ["questLines"] = { { ["id"] = 5983, ["name"] = "Harandar - World Quests / Repeatables", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 8, ["objectID"] = 250255, ["text"] = "Potadpole captured" }, { ["orderIndex"] = 1, ["type"] = 2, ["amount"] = 1, ["objectID"] = 571007, ["text"] = "Release the potatoads" } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[92185] = { ["id"] = 92185, ["name"] = "The Tale of the Frost Lord", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 3487, ["mapID"] = 110, ["description"] = "Midsummer is the time to reflect on the past and share stories by the fireside. One such tale is the defeat of Frost Lord Ahune! But this is a story you must witness for yourself so you may share it around the bonfire with others!", ["rewardGold"] = 584200, ["rewardXP"] = 250, ["rewardItems"] = { 23247 }, ["starts"] = { { ["npcID"] = 16817, ["x"] = 0.496, ["y"] = 0.72, ["mapID"] = 84 }, { ["npcID"] = 16817, ["x"] = 0.64, ["y"] = 0.258, ["mapID"] = 87 }, { ["npcID"] = 16817, ["x"] = 0.622, ["y"] = 0.486, ["mapID"] = 89 }, { ["npcID"] = 16817, ["x"] = 0.414, ["y"] = 0.252, ["mapID"] = 103 }, { ["npcID"] = 16817, ["x"] = 0.612, ["y"] = 0.322, ["mapID"] = 111 }, { ["npcID"] = 16818, ["x"] = 0.62, ["y"] = 0.322, ["mapID"] = 111 }, { ["npcID"] = 16818, ["x"] = 0.62, ["y"] = 0.668, ["mapID"] = 18 }, { ["npcID"] = 16818, ["x"] = 0.674, ["y"] = 0.08, ["mapID"] = 90 }, { ["npcID"] = 16818, ["x"] = 0.478, ["y"] = 0.384, ["mapID"] = 85 }, { ["npcID"] = 16818, ["x"] = 0.214, ["y"] = 0.278, ["mapID"] = 88 }, { ["npcID"] = 16818, ["x"] = 0.698, ["y"] = 0.426, ["mapID"] = 110 } }, ["ends"] = { { ["npcID"] = 252528, ["x"] = 0.48, ["y"] = 0.718, ["mapID"] = 84 }, { ["npcID"] = 250811, ["x"] = 0.478, ["y"] = 0.374, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.496, ["y"] = 0.72, ["source"] = "quest_giver", ["mapID"] = 110 }, ["mapCandidates"] = { ["npc"] = { 18, 84, 85, 87, 88, 89, 90, 103, 110, 111 }, ["zone"] = { 3487 } }, ["questType"] = "standard" },
[92195] = { ["id"] = 92195, ["name"] = "Come On Down", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 92105, 92120, 92121, 92122, 92138, 92139, 92140, 92141, 92143, 92144, 92145, 92146, 92149, 92150, 92152, 92153, 92160, 92195, 92364 }, ["objectivesText"] = "Ring the dinner bell for Brightwing Butterflies", ["rewardXP"] = 13690, ["starts"] = { { ["x"] = 0.643, ["y"] = 0.322, ["mapID"] = 2395 } }, ["ends"] = { { ["x"] = 0.643, ["y"] = 0.322, ["mapID"] = 2395 } }, ["coords"] = { ["mapID"] = 2395, ["x"] = 0.643, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15968 } }, ["questType"] = "world", ["questLines"] = { { ["id"] = 5986, ["name"] = "Eversong Woods - World Quests/Repeatables", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 15, ["objectID"] = 250350, ["text"] = "Ring the dinner bell for Brightwing Butterflies" } }, ["db2PoiUiMapID"] = 2395, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[92319] = { ["id"] = 92319, ["name"] = "A Favor to Axe", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 3483, ["mapID"] = 100, ["storyline"] = { 92319, 92320, 92321, 92322, 92323, 92324, 92325, 92326, 92327 }, ["description"] = "Kurdran and I spent twenty years in Outland on the other side of the Dark Portal, after we'd pushed the Horde back with Khadgar, Turalyon, and Alleria. There were some good times, but any day I don't wake up in Honor Hold is already a good day. That whole time, Kurdran led our scouts with his gryphon, Sky'ree. And on his way out of Honor Hold, he would fly low and fast, dodging everything the orcs threw at him. I think it'd be hilarious if you could go find him some mementos!", ["objectivesText"] = "Go to Hellfire Peninsula in Outland and retrieve 10 Rusty Battleaxes. Optionally, collect the Scarred Spear from within the Hellfire Ramparts as well. Progress: What is it, <name>? You have something for me?", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 253542, 248131, 250872, 253629, 254283 }, ["starts"] = { { ["npcID"] = 250415, ["x"] = 0.472, ["y"] = 0.586, ["mapID"] = 2541 } }, ["ends"] = { { ["npcID"] = 250399, ["x"] = 0.47, ["y"] = 0.592, ["mapID"] = 2541 } }, ["coords"] = { ["x"] = 0.472, ["y"] = 0.586, ["source"] = "quest_giver", ["mapID"] = 100 }, ["mapCandidates"] = { ["npc"] = { 2541 }, ["zone"] = { 3483 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5982, ["name"] = "The Arcantina", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2195, ["db2PoiUiMapID"] = 2541 },
[92320] = { ["id"] = 92320, ["name"] = "Still Behind Enemy Portals", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 10473, ["mapID"] = 2541, ["description"] = "In our reminiscing of past events, we were reminded of an artifact that we did not recover during our war with the Burning Legion. This item is a vessel of great evil, and should not stay in the clutches of the remaining demonic forces. To reach this item, we must journey to the Broken Shore where Tehd has a portal he has repurposed for our use. Will you join us on this hunt?", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 253178 }, ["starts"] = { { ["npcID"] = 250401, ["x"] = 0.564, ["y"] = 0.778, ["mapID"] = 2541 } }, ["ends"] = { { ["npcID"] = 250401, ["x"] = 0.564, ["y"] = 0.778, ["mapID"] = 2541 } }, ["coords"] = { ["x"] = 0.564, ["y"] = 0.778, ["source"] = "quest_giver", ["zoneID"] = 10473 }, ["mapCandidates"] = { ["npc"] = { 2541 }, ["zone"] = { 16752 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5982, ["name"] = "The Arcantina", ["orderIndex"] = 2, ["flags"] = 0 } } },
[92321] = { ["id"] = 92321, ["name"] = "A Frostbitten Tally", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10473, ["mapID"] = 2541, ["storyline"] = { 92319, 92320, 92321, 92322, 92323, 92324, 92325, 92326, 92327 }, ["description"] = "Tarenar and I heard stories about the invasion of Icecrown Citadel from all the way out in the Plaguelands. But he's got it all wrong! The elf thinks there were more Ebon Blade commanders than Argent Crusade in the Ashen Verdict. He's completely daft. Obviously there were more paladins! Would you go poke around Icecrown Citadel and find me some proof? I'm sick of arguing with him!", ["objectivesText"] = "Find 8 Frostbitten Tabards in Icecrown Citadel. Optionally, acquire the Ebon Banner from Icecrown Citadel as well. Progress: You find anything yet? Just need something to prove to Tarenar that I'm right.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 253598, 250873, 260227 }, ["starts"] = { { ["npcID"] = 250402, ["x"] = 0.392, ["y"] = 0.556, ["mapID"] = 2541 } }, ["ends"] = { { ["npcID"] = 250402, ["x"] = 0.392, ["y"] = 0.556, ["mapID"] = 2541 } }, ["coords"] = { ["x"] = 0.392, ["y"] = 0.556, ["source"] = "quest_giver", ["mapID"] = 2541 }, ["mapCandidates"] = { ["npc"] = { 2541 }, ["zone"] = { 10473 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5982, ["name"] = "The Arcantina", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2195, ["db2PoiUiMapID"] = 2541 },
[92322] = { ["id"] = 92322, ["name"] = "Timear Foresees a Proof of Demise!", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 6622, ["mapID"] = 2541, ["storyline"] = { 92319, 92320, 92321, 92322, 92323, 92324, 92325, 92326, 92327 }, ["description"] = "Hello, . Do you have a moment? There's something important I lost during the assault on the Isle of Thunder: a pocket watch gifted to me by my old friend, Archmage Timear. Yes, that Timear... the one that can foresee the future. He told me this day would come and that you would assist me. The watch was taken by the Council of Elders, specifically by High Priestess Mar'li. If you would go to the island and retrieve it from the Throne of Thunder, and we both know you will, I can get you there.", ["objectivesText"] = "Journey to the Isle of Thunder and enter the Throne of Thunder. Inside, retrieve Lan'dalock's Pocket Watch . Optionally, acquire the Ancient Zandalari Scroll as well. Progress: Was Timear's prognostication correct? Have you retrieved my pocket watch? Or have you simply returned to enjoy my scintillating company?", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 253176, 255685 }, ["starts"] = { { ["npcID"] = 264499, ["x"] = 0.282, ["y"] = 0.198, ["mapID"] = 2541 } }, ["ends"] = { { ["npcID"] = 264499, ["x"] = 0.282, ["y"] = 0.198, ["mapID"] = 2541 } }, ["coords"] = { ["x"] = 0.282, ["y"] = 0.198, ["source"] = "quest_giver", ["zoneID"] = 10473 }, ["mapCandidates"] = { ["npc"] = { 2541 }, ["zone"] = { 6622 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5982, ["name"] = "The Arcantina", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2195, ["db2PoiUiMapID"] = 2541 },
[92323] = { ["id"] = 92323, ["name"] = "Where the Fire Once Burned", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10473, ["mapID"] = 2541, ["storyline"] = { 92319, 92320, 92321, 92322, 92323, 92324, 92325, 92326, 92327 }, ["description"] = "Hard to believe, isn't it? Horde and Alliance, same room, no stabbing. I was reminiscing about my days in the Firelands, gathering luciferns . They had such a distinctive smell... somewhere between smoke and something long dead. It's been a while, and I almost miss it. Grab a few for Zen'tabra and me, will you? She deserves the full experience.", ["objectivesText"] = "Journey to Mount Hyjal and enter the Firelands. Inside, retrieve 8 Luciferns . Optionally, acquire the Evergreen Vine as well. Progress: I hope you found those luciferns --because if not, I get stabby. Very stabby.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 253175, 250876, 263872 }, ["starts"] = { { ["npcID"] = 250405, ["x"] = 0.754, ["y"] = 0.42, ["mapID"] = 2541 } }, ["ends"] = { { ["npcID"] = 250405, ["x"] = 0.754, ["y"] = 0.42, ["mapID"] = 2541 } }, ["coords"] = { ["x"] = 0.754, ["y"] = 0.42, ["source"] = "quest_giver", ["mapID"] = 2541 }, ["mapCandidates"] = { ["npc"] = { 2541 }, ["zone"] = { 10473 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5982, ["name"] = "The Arcantina", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2195, ["db2PoiUiMapID"] = 2541 },
[92324] = { ["id"] = 92324, ["name"] = "Uncrowned's Cold Case", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10473, ["mapID"] = 2541, ["storyline"] = { 92319, 92320, 92321, 92322, 92323, 92324, 92325, 92326, 92327 }, ["description"] = "We are lucky the Uncrowned survived, and its archives, thanks to Taoshi. We've been reading them... Have you heard of the great highborne city Dire Maul? The Uncrowned kept tabs on the dangerous prince, Tortheldrin, but since he died, the case was shelved. These notes say there might be objects of interest in the city ruins, with a notable mention of Nostro's Compendium of Dragon Slaying. That book was retrieved some time ago, but few know that several chapters were missing. Let's reopen the case.", ["objectivesText"] = "Journey to Feralas and collect 8 Lost Pages from Nostro's Compendium. Optionally, acquire the Pylon Fragment from Dire Maul as well. Progress: Surrounded by hearth and friends, it's hard to believe Dalaran is truly gone... <Kelsey looks at Taoshi with deep sincerity.> The Uncrowned wastes no time picking up its affairs. Have you found anything of interest?", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 253177, 18348, 18401, 250877, 255681 }, ["starts"] = { { ["npcID"] = 250408, ["x"] = 0.772, ["y"] = 0.584, ["mapID"] = 2541 } }, ["ends"] = { { ["npcID"] = 250408, ["x"] = 0.772, ["y"] = 0.584, ["mapID"] = 2541 } }, ["coords"] = { ["x"] = 0.772, ["y"] = 0.584, ["source"] = "quest_giver", ["mapID"] = 2541 }, ["mapCandidates"] = { ["npc"] = { 2541 }, ["zone"] = { 10473 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5982, ["name"] = "The Arcantina", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2195, ["db2PoiUiMapID"] = 2541 },
[92325] = { ["id"] = 92325, ["name"] = "Hellscream's Heritage", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 3518, ["mapID"] = 107, ["storyline"] = { 92319, 92320, 92321, 92322, 92323, 92324, 92325, 92326, 92327 }, ["description"] = "My sister Krenna was once a Conqueror in the Horde's armies. Ruthless. Brutal. Some said a tyrant. But she was different when we were young. Scared, but always kind to me. Warm to those she would let in. Did power change her? And if it changed her into a tyrant, did it change Garrosh Hellscream as well? I know who Krenna was. I do not know who Garrosh was. Travel to Nagrand and find out.", ["objectivesText"] = "Go to Nagrand and discover who Garrosh was in his youth. Optionally, acquire the Weathered Tome as well. Progress: I would know who the previous leader of the Warsong really was.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 253544, 25433, 262911 }, ["starts"] = { { ["npcID"] = 250410, ["x"] = 0.69, ["y"] = 0.568, ["mapID"] = 2541 } }, ["ends"] = { { ["npcID"] = 250410, ["x"] = 0.69, ["y"] = 0.568, ["mapID"] = 2541 } }, ["coords"] = { ["x"] = 0.69, ["y"] = 0.568, ["source"] = "quest_giver", ["mapID"] = 107 }, ["mapCandidates"] = { ["npc"] = { 2541 }, ["zone"] = { 3518 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5982, ["name"] = "The Arcantina", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2195, ["db2PoiUiMapID"] = 2541 },
[92326] = { ["id"] = 92326, ["name"] = "The Fragrance of the Dunes", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10473, ["mapID"] = 2541, ["storyline"] = { 92319, 92320, 92321, 92322, 92323, 92324, 92325, 92326, 92327 }, ["description"] = "I miss the smell of the desert. It is the fragrance of freedom in a wild land. I would love to refresh that scent memory. While you're there, grab something from the caravans. This place could use some nomad personality. Maybe hop over to Shatterstone Harbor and get something for the big guy. Maybe an anchor? That would be perfect! Imagine watching him lug that around.", ["objectivesText"] = "Go to Vol'dun and bring back a Pouch of Fragrant Sands. Optionally, acquire the Sandy Tapestry from Vulpera Hideaway and the Heavy Anchor from Shatterstone Harbor as well. Progress: Did you fill the pouch?", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 253179, 253700, 257756, 257757, 257758 }, ["rewardChoices"] = { 253179, 253700 }, ["starts"] = { { ["npcID"] = 250411, ["x"] = 0.4, ["y"] = 0.776, ["mapID"] = 2541 } }, ["ends"] = { { ["npcID"] = 250411, ["x"] = 0.4, ["y"] = 0.776, ["mapID"] = 2541 } }, ["coords"] = { ["x"] = 0.4, ["y"] = 0.776, ["source"] = "quest_giver", ["mapID"] = 2541 }, ["mapCandidates"] = { ["npc"] = { 2541 }, ["zone"] = { 10473 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5982, ["name"] = "The Arcantina", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2195, ["db2PoiUiMapID"] = 2541 },
[92327] = { ["id"] = 92327, ["name"] = "A Generational Moment", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 4706, ["mapID"] = 217, ["storyline"] = { 92319, 92320, 92321, 92322, 92323, 92324, 92325, 92326, 92327 }, ["description"] = "It's always good to see someone with your history continue to speak to us old dogs, $p. Eitrigg and I have been talking about legacy recently. Did you know we both fought with the Valarjar against the Legion? Interesting how long histories can intertwine. But our real legacy is our children. I wonder if you would have time to check in with them both. While you're there, make sure they're keeping their skills sharp.", ["objectivesText"] = "Eitrigg and Darius want you to spar with their children. Optionally, acquire the Clefthoof Hide from Serpent's Coil in the Blasted Lands and the Dried Roses from Pyrewood Village in Silverpine Forest. Progress: Were you able to find Lorna? What of Eitrigg's son Ariok ?", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 211873, 250881, 250882, 253174, 253543 }, ["rewardChoices"] = { 253174, 253543 }, ["starts"] = { { ["npcID"] = 250413, ["x"] = 0.524, ["y"] = 0.56, ["mapID"] = 2541 } }, ["ends"] = { { ["npcID"] = 250413, ["x"] = 0.524, ["y"] = 0.56, ["mapID"] = 2541 } }, ["coords"] = { ["x"] = 0.524, ["y"] = 0.56, ["source"] = "quest_giver", ["mapID"] = 217 }, ["mapCandidates"] = { ["npc"] = { 2541 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5982, ["name"] = "The Arcantina", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2195, ["db2PoiUiMapID"] = 2541 },
[92331] = { ["id"] = 92331, ["name"] = "Turbo-Boost: Trade Must Flow", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "<The Trust is under pressure from the cartels to keep markets open. We seek associates capable of removing certain... obstacles. Cartel So has been authorized to distribute substantial riches if you are successful. Complete the task, and collect a special reward from Fixer So'kir outside of the Dornogal Treasury. Parties shall remain unbound by any implied oaths arising in the course of trade. Uniform Broker Code standard terms apply.>", ["objectivesText"] = "Defeat any four bosses within the Manaforge Omega raid on Normal difficulty or higher, or complete any four Mythic Dungeons.", ["rewardGold"] = 1239200, ["rewardItems"] = { 250741 }, ["starts"] = { { ["x"] = 0.524, ["y"] = 0.46, ["mapID"] = 2339, ["objectID"] = 571402 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 250450, ["x"] = 0.523, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.523, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[92332] = { ["id"] = 92332, ["name"] = "Turbo-Boost: Infinite Growth", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "<The Trust always has more work to be done if we are to ensure continued growth for our trade. Once again, Cartel So has been authorized to distribute substantial riches if you are successful. Complete the task, and collect a special reward from Fixer So'kir outside of the Dornogal Treasury. Parties shall remain unbound by any implied oaths arising in the course of trade. Uniform Broker Code standard terms apply.>", ["objectivesText"] = "Defeat any four bosses within the Manaforge Omega raid on Normal difficulty or higher, or complete any four Mythic Dungeons. Progress: Again, you prove yourself a friend of the cartels! Well done.", ["rewardGold"] = 1239200, ["rewardItems"] = { 250741 }, ["starts"] = { { ["x"] = 0.524, ["y"] = 0.46, ["mapID"] = 2339, ["objectID"] = 571402 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 250450, ["x"] = 0.523, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.523, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
