[92365] = { ["id"] = 92365, ["name"] = "Creating Defenses", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 92365 }, ["description"] = "Deploying defenses is crucial to safeguarding operation of the Singularity Anchor. I need to ensure you fully understand the process. First, collect the Stormarion cores I have in storage. Then, activate the defensive positions, and finally, choose and deploy one defense at each position. When you have completed that I can entrust you with further Stormarion cores to use as you see fit.", ["objectivesText"] = "Follow the steps and deploy two defenses. Progress: Have you deployed the defenses?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 246951, 250807 }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 248114, ["x"] = 0.265333, ["y"] = 0.676667 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 248114, ["x"] = 0.265333, ["y"] = 0.676667 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.265333, ["y"] = 0.676667 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
