[92390] = { ["id"] = 92390, ["name"] = "Risk for Research", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 92155, 92156, 92157, 92158, 92159, 92390 }, ["description"] = "There is some peculiar activity in Shadow Rise to the northeast. Supposedly it is cursed! The Shadowguard usually have a heavy presence there, but I have word that they are abandoning the site. I want to find out the truth of why they'd leave. Would you accompany me?", ["objectivesText"] = "Meet Lanlae Noxa in Shadow Rise to look around the Shadowguard facility.", ["rewardGold"] = 34100, ["rewardXP"] = 1605, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3389, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 250677, ["x"] = 0.398, ["y"] = 0.84 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 249935, ["x"] = 0.637, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.398, ["y"] = 0.84 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 86509 }, ["questLines"] = { { ["id"] = 5987, ["name"] = "Shadowguard's Shadow", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[92396] = { ["id"] = 92396, ["name"] = "Calling in the Cavalry", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 92396, 92397, 92398 }, ["description"] = "The wards on the runestones weaken by the hour. Without fresh arcane-charged crystals, the Lightbloom will gain ground. I know this is not your burden to bear as you have much more to handle, but if you could see these supplies delivered, it would mean more than I can say. Will you lend your strength to this task, for the sake of all who call this place home?", ["objectivesText"] = "Deliver charged crystals to Runestones across Eversong Woods . Progress: What to do...", ["rewardGold"] = 170800, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 250791, ["x"] = 0.5, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 250798, ["x"] = 0.616, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86735 }, ["questLines"] = { { ["id"] = 5993, ["name"] = "Runestone Rumbles", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[92397] = { ["id"] = 92397, ["name"] = "Dawnstar Defense", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16048, ["mapID"] = 2395, ["storyline"] = { 92396, 92397, 92398 }, ["description"] = "The nearby runestone has gone dark, and the Lightbloom is on its way. I can't hold this ground alone. Help me set the weapons, line up the potions, and get our supplies in order. We'll meet that growth with discipline and precision and send it back in pieces.", ["objectivesText"] = "Build up defenses before the impending Lightbloom attack. Progress: Have you finished setting up?", ["rewardGold"] = 170800, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 250798, ["x"] = 0.616, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 250798, ["x"] = 0.616, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 92396 }, ["questLines"] = { { ["id"] = 5993, ["name"] = "Runestone Rumbles", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[92398] = { ["id"] = 92398, ["name"] = "And Then They Came", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16048, ["mapID"] = 2395, ["storyline"] = { 92396, 92397, 92398 }, ["description"] = "Brace yourself--the time is upon us! Hold the line and keep them from reaching the runestone at all costs. I'll focus on restoring its power, but I need you to protect me and everyone here. Are you ready?", ["objectivesText"] = "Defend Dawnstar Spire.", ["rewardGold"] = 683200, ["rewardXP"] = 17650, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3365, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 250798, ["x"] = 0.616, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 250798, ["x"] = 0.616, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 92397 }, ["questLines"] = { { ["id"] = 5993, ["name"] = "Runestone Rumbles", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[92402] = { ["id"] = 92402, ["name"] = "Magical Touch", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16105, ["mapID"] = 2352, ["description"] = "Oh hey, just the person I was looking for! Some of your neighbors are looking to get into enchanting. They aren't quite ready for prime time yet, but I have an idea to get them started. It looks like there's an area in your neighborhood that has slight magical energy. Can you take this locator and find some crystals for them? They only need to be slightly magical. We don't want them to cause an accident!", ["rewardGold"] = 341600, ["rewardXP"] = 3440, ["rewardCurrencies"] = { { ["id"] = 3363, ["amount"] = 1 } }, ["starts"] = { { ["npcID"] = 254536, ["x"] = 0.544, ["y"] = 0.56, ["mapID"] = 2351 }, { ["npcID"] = 254536, ["x"] = 0.52, ["y"] = 0.38, ["mapID"] = 2352 } }, ["ends"] = { { ["npcID"] = 254536, ["x"] = 0.544, ["y"] = 0.56, ["mapID"] = 2351 }, { ["npcID"] = 254536, ["x"] = 0.52, ["y"] = 0.38, ["mapID"] = 2352 } }, ["coords"] = { ["x"] = 0.544, ["y"] = 0.56, ["source"] = "quest_giver", ["mapID"] = 2352 }, ["mapCandidates"] = { ["npc"] = { 2351, 2352 }, ["zone"] = { 16105 } }, ["questType"] = "standard" },
[92405] = { ["id"] = 92405, ["name"] = "Meet Arator", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 84996, 84997, 84998, 85001, 85002, 92405 }, ["series"] = { 84996, 84997 }, ["description"] = "Greetings, champion. I have an urgent message for you from Arator . He asks that you join him and his aunt Vereesa on Oztan Isle, off the coast to the west.", ["objectivesText"] = "Seek out Arator and Vereesa Windrunner on Oztan Isle off the Isle of Dorn coast.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 250839, ["x"] = 0.515, ["y"] = 0.4555 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 231039, ["x"] = 0.285, ["y"] = 0.446 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.4555 }, ["mapCandidates"] = { ["npc"] = { 2248, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5707, ["name"] = "Radiant Visions", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 269, ["title"] = "Visions of a Shadowed Sun", ["questLineID"] = 5707, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[92407] = { ["id"] = 92407, ["name"] = "Hidey-Hole", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 92407 }, ["description"] = "When Xal'atath departed she left behind a large number of anomalies, small pocket dimensions where enemies can hide. As Romuul calls them, \" Hidey-Holes \". The Artificer has rigged up a device that should do the job. We need to close these Hidey-Holes and flush out any enemies lurking inside.", ["objectivesText"] = "Use the Anomaly Inverter to collapse 5 Hidey-Holes . Progress: Have you removed the anomalies?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 246951, 251284 }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 248114, ["x"] = 0.265333, ["y"] = 0.676667 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 248114, ["x"] = 0.265333, ["y"] = 0.676667 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.265333, ["y"] = 0.676667 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[92408] = { ["id"] = 92408, ["name"] = "Material Gains", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 91386, 91388, 91389, 92408 }, ["description"] = "How on Azeroth one of these encroaching paladins managed to come by such an exquisite example of Thalassian tailoring is beyond me. But it would be negligent of me to turn down this opportunity. The materials we need are far more bespoke than I keep in my shop, however. We'll need to source our manasilk directly. Fortunately, it isn't far--just outside the city gates. And at least there we'll be safe from these dabblers.", ["objectivesText"] = "Meet Solwin Brightstitch at the manasilk mill in the North Sanctum.", ["rewardGold"] = 33500, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 247645, ["x"] = 0.4855, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 250888, ["x"] = 0.468, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.4855, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 2393, 2395 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 91386 }, ["questLines"] = { { ["id"] = 5989, ["name"] = "Tailor Troubles", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
