[92417] = { ["id"] = 92417, ["name"] = "Farm to Table", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16105, ["mapID"] = 2352, ["description"] = "Hey, it's ! I'm in a bit of a pickle here. I'm making food for everyone, but underestimated how many people would turn up! I can whip up a quick stew and the local farmers said I could use their produce, but the other dishes are at a vital point, I can't leave them unattended! Could you gather some ripe ingredients, and bring them back?", ["rewardGold"] = 341600, ["rewardXP"] = 3440, ["rewardCurrencies"] = { { ["id"] = 3363, ["amount"] = 1 } }, ["starts"] = { { ["npcID"] = 250970, ["x"] = 0.548, ["y"] = 0.572, ["mapID"] = 2351 }, { ["npcID"] = 250970, ["x"] = 0.53, ["y"] = 0.38, ["mapID"] = 2352 } }, ["ends"] = { { ["npcID"] = 250970, ["x"] = 0.548, ["y"] = 0.572, ["mapID"] = 2351 }, { ["npcID"] = 250970, ["x"] = 0.53, ["y"] = 0.38, ["mapID"] = 2352 } }, ["coords"] = { ["x"] = 0.548, ["y"] = 0.572, ["source"] = "quest_giver", ["mapID"] = 2352 }, ["mapCandidates"] = { ["npc"] = { 2351, 2352 }, ["zone"] = { 16105 } }, ["questType"] = "standard" },
