[92420] = { ["id"] = 92420, ["name"] = "Ignite the Skies: Southern Kalimdor", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["description"] = "Each year, as tribes from southern and central Kalimdor journeyed to Stonetalon to spend the summer season, the rite of the sun blossoms became common practice. Many saw it as a way to give back to An'she, who worked tirelessly during this long season. The rite became especially important towards the end of Midsummer, as the southern tribes journeyed back home. If you're up for another journey, take to the skies once more, my friend, and listen close...", ["rewardGold"] = 315900, ["rewardItems"] = { 23247 }, ["starts"] = { { ["npcID"] = 251986, ["x"] = 0.222, ["y"] = 0.192, ["mapID"] = 10 }, { ["npcID"] = 251986, ["x"] = 0.316, ["y"] = 0.636, ["mapID"] = 71 } }, ["ends"] = { { ["npcID"] = 251986, ["x"] = 0.222, ["y"] = 0.192, ["mapID"] = 10 }, { ["npcID"] = 251986, ["x"] = 0.316, ["y"] = 0.636, ["mapID"] = 71 } }, ["coords"] = { ["x"] = 0.222, ["y"] = 0.192, ["source"] = "quest_giver", ["mapID"] = 71 }, ["mapCandidates"] = { ["npc"] = { 10, 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 92106 } },
[92429] = { ["id"] = 92429, ["name"] = "Alternative Skinning", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16105, ["mapID"] = 2352, ["description"] = "Hey there! I'm working on a new method for making leather, but without harming animals. I just need small samples, fur, saliva, that sort of thing. Nothing invasive. I have this handy device that should help out!", ["rewardGold"] = 341600, ["rewardXP"] = 3440, ["rewardCurrencies"] = { { ["id"] = 3363, ["amount"] = 1 } }, ["starts"] = { { ["npcID"] = 251056, ["x"] = 0.544, ["y"] = 0.576, ["mapID"] = 2351 }, { ["npcID"] = 251056, ["x"] = 0.528, ["y"] = 0.39, ["mapID"] = 2352 } }, ["ends"] = { { ["npcID"] = 251056, ["x"] = 0.544, ["y"] = 0.576, ["mapID"] = 2351 }, { ["npcID"] = 251056, ["x"] = 0.528, ["y"] = 0.39, ["mapID"] = 2352 } }, ["coords"] = { ["x"] = 0.544, ["y"] = 0.576, ["source"] = "quest_giver", ["mapID"] = 2352 }, ["mapCandidates"] = { ["npc"] = { 2351, 2352 }, ["zone"] = { 16105 } }, ["questType"] = "standard" },
[92435] = { ["id"] = 92435, ["name"] = "Ignite the Skies: Orgrimmar", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 1637, ["mapID"] = 85, ["description"] = "Midsummer is a time to reflect on the past and future. As old traditions fade, new traditions are born. One old tradition, practiced long ago, involved the offering of sun blossoms to An'she. As summer winds took them upwards, the blossoms would burn bright blue and orange. But faded traditions need not remain lost. Will you take to the skies to ignite the sun blossoms and help rekindle this old tradition?", ["rewardGold"] = 312800, ["rewardItems"] = { 23247 }, ["starts"] = { { ["npcID"] = 250811, ["x"] = 0.478, ["y"] = 0.374, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 250811, ["x"] = 0.478, ["y"] = 0.374, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.478, ["y"] = 0.374, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[92437] = { ["id"] = 92437, ["name"] = "Decor Treasure Hunt", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16105, ["mapID"] = 2352, ["storyline"] = { 92437 }, ["description"] = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle: Stone laid by lost hands. Bridging the mountain runoff. Look where lilies listen. Good luck!", ["objectivesText"] = "There are many version of the Decor Treasure Hunt quest. To find the one you're looking for, check out the Alliance List or Horde List . Solve the riddle and find the treasure.", ["rewardGold"] = 170800, ["rewardItems"] = { 235523, 235675, 235677, 235994, 236654, 236655, 236666, 236676, 236677, 236678, 239075, 241617, 241618, 241620, 241621, 242951, 243334, 243495, 244169, 244531, 244532, 244533, 244534, 244780, 244782, 245266, 245334, 245336, 245355, 245356, 245372, 245375, 245376, 245384, 245398, 245532, 245533, 245545, 245546, 245547, 245548, 245555, 245556, 245575, 245576, 245578, 245581, 245583, 245649, 245662, 245680, 246036, 246101, 246102, 246103, 246104, 246106, 246107, 246217, 246218, 246224, 246241, 246243, 246245, 246246, 246249, 246250, 246253, 246254, 246255, 246258, 246259, 246260, 246261, 246502, 246587, 246614, 246687, 246742, 246868, 246869, 246880, 246882, 246883, 247221, 248246, 248760, 250920, 251973, 251981, 253181, 253441, 253479, 253490, 253493, 253589, 255650, 257690, 257691, 257692 }, ["starts"] = { { ["mapID"] = 2352, ["npcID"] = 248854, ["x"] = 0.526, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 2352, ["npcID"] = 248854, ["x"] = 0.526, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 2352, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 2352 }, ["zone"] = { 16105 } }, ["questTurnInID"] = 248854, ["questType"] = "standard" },
[92439] = { ["id"] = 92439, ["name"] = "Infinite Research: Combat Studies, Felrunner", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily", "meta" }, ["sharable"] = false, ["expansion"] = 11, ["mapID"] = 619, ["storyline"] = { 92439 }, ["description"] = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma. This will be a study of fighting the Legion with their own power, so focus on using demonic fel energy to slay your foes. And remember, this is for the greater good.", ["objectivesText"] = "Kill 100 enemies while Twisted Crusade is your active artifact ability. Progress: Remember to pace yourself, the journey is just as important as the destination.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 246936, 249400, 254267, 254579, 264675 }, ["starts"] = { { ["x"] = 0.457, ["y"] = 0.685, ["mapID"] = 619, ["npcID"] = 241748 } }, ["ends"] = { { ["mapID"] = 619, ["npcID"] = 241748, ["x"] = 0.456, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 619, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 619 }, ["zone"] = {} }, ["questGiverID"] = 241748, ["questType"] = "standard" },
