[92441] = { ["id"] = 92441, ["name"] = "Infinite Research: Combat Studies, Magerunner", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily", "meta" }, ["sharable"] = false, ["expansion"] = 11, ["mapID"] = 619, ["storyline"] = { 92441 }, ["description"] = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma. This will be a study of your attunement to the arcane, so focus on fighting opponents with powerful magic. And remember, this is for the greater good.", ["objectivesText"] = "Kill 100 enemies while Naran's Everdisc is your active artifact ability.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 246936, 249400, 254267, 254579, 264675 }, ["starts"] = { { ["x"] = 0.457, ["y"] = 0.685, ["mapID"] = 619, ["npcID"] = 241748 } }, ["ends"] = { { ["mapID"] = 619, ["npcID"] = 241748, ["x"] = 0.456, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 619, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 619 }, ["zone"] = {} }, ["questGiverID"] = 241748, ["questType"] = "standard" },
[92442] = { ["id"] = 92442, ["name"] = "Infinite Research: Combat Studies, Lightrunner", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily", "meta" }, ["sharable"] = false, ["expansion"] = 11, ["mapID"] = 619, ["storyline"] = { 92442 }, ["description"] = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma. This will be a study of your attunement to the Light, so focus on wielding holy justice to smite your enemies. And remember, this is for the greater good.", ["objectivesText"] = "Kill 100 enemies while Vindicator's Judgment is your active artifact ability. Progress: Remember to pace yourself, the journey is just as important as the destination.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 246936, 249400, 254267, 254579, 264675 }, ["starts"] = { { ["x"] = 0.457, ["y"] = 0.685, ["mapID"] = 619, ["npcID"] = 241748 } }, ["ends"] = { { ["mapID"] = 619, ["npcID"] = 241748, ["x"] = 0.456, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 619, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 619 }, ["zone"] = {} }, ["questGiverID"] = 241748, ["questType"] = "standard" },
[92443] = { ["id"] = 92443, ["name"] = "Reverse Herb Farming", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16105, ["mapID"] = 2352, ["description"] = "Hey there, I was collecting herbs around your neighborhood, and I kind of zoned out, and lost track of time. It's so pretty here! I think I may have picked too many herbs. I have an enchanted watering can that should help new ones grow back in, if you have the time to help them grow back?", ["rewardGold"] = 341600, ["rewardXP"] = 3440, ["rewardCurrencies"] = { { ["id"] = 3363, ["amount"] = 1 } }, ["starts"] = { { ["npcID"] = 254255, ["x"] = 0.542, ["y"] = 0.56, ["mapID"] = 2351 }, { ["npcID"] = 254255, ["x"] = 0.528, ["y"] = 0.376, ["mapID"] = 2352 } }, ["ends"] = { { ["npcID"] = 254255, ["x"] = 0.542, ["y"] = 0.56, ["mapID"] = 2351 }, { ["npcID"] = 254255, ["x"] = 0.528, ["y"] = 0.376, ["mapID"] = 2352 } }, ["coords"] = { ["x"] = 0.542, ["y"] = 0.56, ["source"] = "quest_giver", ["mapID"] = 2352 }, ["mapCandidates"] = { ["npc"] = { 2351, 2352 }, ["zone"] = { 16105 } }, ["questType"] = "standard" },
[92445] = { ["id"] = 92445, ["name"] = "Smelting for Two", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16105, ["mapID"] = 2352, ["description"] = "People keep coming up to me and asking me about mining, I'm not a miner, I'm a smelter! I'm looking to teach some people about smelting, but I've been struggling with getting a crowd. Could you help me out while I talk you through smelting?", ["rewardGold"] = 341600, ["rewardXP"] = 3440, ["rewardCurrencies"] = { { ["id"] = 3363, ["amount"] = 1 } }, ["starts"] = { { ["npcID"] = 251185, ["x"] = 0.54, ["y"] = 0.57, ["mapID"] = 2351 }, { ["npcID"] = 251185, ["x"] = 0.524, ["y"] = 0.384, ["mapID"] = 2352 } }, ["ends"] = { { ["npcID"] = 251185, ["x"] = 0.54, ["y"] = 0.57, ["mapID"] = 2351 }, { ["npcID"] = 251185, ["x"] = 0.524, ["y"] = 0.384, ["mapID"] = 2352 } }, ["coords"] = { ["x"] = 0.54, ["y"] = 0.57, ["source"] = "quest_giver", ["mapID"] = 2352 }, ["mapCandidates"] = { ["npc"] = { 2351, 2352 }, ["zone"] = { 16105 } }, ["questType"] = "standard" },
[92447] = { ["id"] = 92447, ["name"] = "Abyss Anglers", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["mapID"] = 2437, ["storyline"] = { 92447 }, ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.682, ["y"] = 0.199, ["mapID"] = 2437 } }, ["ends"] = { { ["x"] = 0.682, ["y"] = 0.199, ["mapID"] = 2437 } }, ["coords"] = { ["mapID"] = 2437, ["x"] = 0.682, ["y"] = 0.199 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["activities"] = { ["scenarios"] = { { ["id"] = 3181, ["name"] = "Abyss Anglers", ["areaID"] = 0 } } }, ["db2PoiUiMapID"] = 2437 },
[92448] = { ["id"] = 92448, ["name"] = "Where Dust Dances", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92448 }, ["description"] = "You find a faintly glowing powder in your hands after catching the moth. It is fine, dry, and oddly luminous. It doesn't hum or shift, but it catches the light in a way that feels deliberate. You recall Mothkeeper Wew'tam is known to have a particular interest in the moths that reside in Harandar . Perhaps this dust would be of interest.", ["objectivesText"] = "Speak to Mothkeeper Wew'tam in the Den. Provided item:", ["rewardGold"] = 31900, ["rewardXP"] = 1520, ["rewardItems"] = { 251881 }, ["starts"] = { { ["x"] = 0.529, ["y"] = 0.517, ["mapID"] = 2413 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 251259, ["x"] = 0.492, ["y"] = 0.544 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["startItems"] = { 251881 } },
[92450] = { ["id"] = 92450, ["name"] = "Growing Up is Hard", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 92450, 92451, 92452, 92453 }, ["description"] = "Oh, hi! You're new. I'm Ani . Dis is Jynx. Have you been to de waterfall yet? All de kids dare each other to jump off, but I'm too scared. Do you want to see it?", ["objectivesText"] = "Head to the waterfall with Ani .", ["rewardGold"] = 170800, ["rewardXP"] = 6085, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 251258, ["x"] = 0.456, ["y"] = 0.6455 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 251258, ["x"] = 0.456, ["y"] = 0.6455 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.6455 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86652 }, ["questLines"] = { { ["id"] = 5999, ["name"] = "No Fear", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[92451] = { ["id"] = 92451, ["name"] = "I Think I Can", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 92450, 92451, 92452, 92453 }, ["description"] = "Yeah, it's pretty far down. But if I don't jump, dey'll make fun of me. Maybe if you cheer me on, I can do it?", ["objectivesText"] = "Help Ani conquer her fear. Progress: I don't want dem to make fun of me anymore. I-I can do dis. I think...", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 251258, ["x"] = 0.456, ["y"] = 0.6455 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 251258, ["x"] = 0.456, ["y"] = 0.6455 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.6455 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questTurnInID"] = 251258, ["questType"] = "standard", ["sourceQuests"] = { 92450 }, ["questLines"] = { { ["id"] = 5999, ["name"] = "No Fear", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[92452] = { ["id"] = 92452, ["name"] = "Not According to Plan", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 92450, 92451, 92452, 92453 }, ["description"] = "< Ani's trinket bag sits in the soft mud of the river bank, but her trinkets are nowhere to be found. If you're lucky, you may be able to follow her trail.>", ["objectivesText"] = "Follow the trail of Ani 's belongings.", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 259345, 259348, 259350 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3354, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.487, ["y"] = 0.661, ["mapID"] = 2437, ["objectID"] = 573714 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 251258, ["x"] = 0.456, ["y"] = 0.6455 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.6455 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 92451 }, ["questLines"] = { { ["id"] = 5999, ["name"] = "No Fear", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[92453] = { ["id"] = 92453, ["name"] = "Fearless", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 92450, 92451, 92452, 92453 }, ["description"] = "Those lizards were waitin' at de bottom and dragged me off! Did you find my toys and stuff? I tried droppin' dem so someone could find me. I can't believe dat worked! I think you scared dem off. It should be safe enough for Jynx to help me out of here.", ["objectivesText"] = "Meet Ani back at Amani'Zar Village. Progress: Jumpin' off dat waterfall isn't so scary anymore.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 264587 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3354, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 251258, ["x"] = 0.456, ["y"] = 0.6455 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 251258, ["x"] = 0.456, ["y"] = 0.6455 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.6455 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 92452 }, ["questLines"] = { { ["id"] = 5999, ["name"] = "No Fear", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[92455] = { ["id"] = 92455, ["name"] = "Specter Inspector", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 11, ["storyline"] = { 92455 }, ["description"] = "Every Hallow's End, same thing... spirits crawl outta the dirt like they forgot they're dead. We tried smashin'. We tried burnin'. Didn't work. Now we got these new tools some goblin made that'll take care of those ghosts. Gear up and get goin'! Get enough of em to clear the streats for now, but don't go gettin' lazy. They always seem to find a way back.", ["objectivesText"] = "Catch 5 ghosts.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[92492] = { ["id"] = 92492, ["name"] = "Honorin' de Sacrifice", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 92492, 92493, 92495, 92496, 92497, 92499 }, ["description"] = "It's de hash'ura again. You willin' to help me, or does Zul'jarra got you on a short leash? No? Then I got a job for you. One of my guards, Idago, was killed in de massacre at Revantusk Sedge. I wish to honor him with funeral rites. We Revantusk burn de bodies of our dead. But we don't have Idago's body. So, I'm goin' back to de sedge to retrieve somethin' of his. We'll burn dat instead. My honor guard Pel'na will not go and says it is too dangerous, but you'll keep me safe, won'tcha?", ["objectivesText"] = "Meet Lilaju at Revantusk Sedge.", ["rewardGold"] = 31500, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3354, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 245664, ["x"] = 0.336, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 251669, ["x"] = 0.2425, ["y"] = 0.6415 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91062 }, ["questLines"] = { { ["id"] = 6011, ["name"] = "Reclaiming De Honor", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[92493] = { ["id"] = 92493, ["name"] = "What Remains of Idago", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 92492, 92493, 92495, 92496, 92497, 92499 }, ["description"] = "Idago was my most trusted guard. He was a mentor to me for as long as I remember. I never thought dat he would be taken from me so soon--and then de Twilight's Blade attacked us without warnin'. Idago is de one that saved me from de village. He left his spear and his banner behind. I also left a note he gave me in case he... Bring me those items. With dem, we can honor his strength and his loyalty--and send his spirit on.", ["objectivesText"] = "Find Idago's Warspear , Banner, and Letter in Revantusk Sedge. Progress: Revantusk Sedge is swarmin' with these foul mages. You're doin' de loa's work.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 252134, 252135, 252136 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 251669, ["x"] = 0.2425, ["y"] = 0.6415 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 251669, ["x"] = 0.2425, ["y"] = 0.6415 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.2425, ["y"] = 0.6415 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 92492 }, ["questLines"] = { { ["id"] = 6011, ["name"] = "Reclaiming De Honor", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[92495] = { ["id"] = 92495, ["name"] = "Disruptin' de Blade", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 92492, 92493, 92495, 92496, 92497, 92499 }, ["description"] = "Look at what these cultists did to Revantusk Sedge! Dis was once a place of peace... dis was our home. An' dey are desecrating it. I know we're here to retrieve Idago's things, but I won't be bothered if you take up arms against de Twilight's Blade. Put dem in de ground. Show dem de ferocity of de bear.", ["objectivesText"] = "Slay 7 Twilight's Blade Enforcers, 7 Shadowmages, and 3 Baleful Darkspawn at Revantusk Sedge. Progress: One day, we're gonna march on these invaders an' take our sedge back!", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 251669, ["x"] = 0.2425, ["y"] = 0.6415 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 251669, ["x"] = 0.2425, ["y"] = 0.6415 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.2425, ["y"] = 0.6415 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 92492 }, ["questLines"] = { { ["id"] = 6011, ["name"] = "Reclaiming De Honor", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[92496] = { ["id"] = 92496, ["name"] = "Spears Against de Shadow", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 92492, 92493, 92495, 92496, 92497, 92499 }, ["description"] = "Idago's still alive, <name>! I saw him dragged up into de crypt, bound in magic runes. De cultists say dey are takin' him to some Deathchanter Mish'mosh . Dis cultist must be behind the death and destruction brought to our sedge. For the honor of the people we lost, root this snake out of our home!", ["objectivesText"] = "Slay Deathchanter Mish'mosh in the crypt at Revantusk Sedge. Progress: The world be better without Mish'mosh's evil stainin' it.", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3354, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 251669, ["x"] = 0.2425, ["y"] = 0.6415 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 251669, ["x"] = 0.2425, ["y"] = 0.6415 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.2425, ["y"] = 0.6415 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 92493, 92495 }, ["questLines"] = { { ["id"] = 6011, ["name"] = "Reclaiming De Honor", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[92497] = { ["id"] = 92497, ["name"] = "Simply Magical", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 92492, 92493, 92495, 92496, 92497, 92499 }, ["description"] = "Who... Who are you? Who sent you? Lilaju? De cultists massacred our village. I stayed behind to make sure everyone got out. But de cultists captured me and now dey say dey got somethin' extra special for Idago . I'd rather not find out what. Dis magic holdin' me here is amateur work. De spells to release de bindings are sure to be in de magical tomes de cultists brought here. Find de tomes and rip some pages out. Then we can piece together de right words to release me.", ["objectivesText"] = "Rip the pages from the Tome of Binding and the Tome of Pain and recite their words to free Idago . Progress: Appreciate ya, <name>. For freeing me and for keeping an eye on dis one here.", ["rewardGold"] = 309800, ["rewardXP"] = 12170, ["rewardItems"] = { 260406, 260407 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 251522, ["x"] = 0.262, ["y"] = 0.688667 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 251522, ["x"] = 0.262, ["y"] = 0.688667 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.262, ["y"] = 0.688667 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 92493, 92495 }, ["questLines"] = { { ["id"] = 6011, ["name"] = "Reclaiming De Honor", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[92499] = { ["id"] = 92499, ["name"] = "The Wisest Leaders Follow", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 92492, 92493, 92495, 92496, 92497, 92499 }, ["description"] = "Idago reminded me dat my first obligation is to my tribe. I missed him dearly, but it was not right for me to put my own life--or yours--at risk to find him. Pel'na tried to tell me this. I would not listen. I must be a model for my people. I will allow de bear loa to guide my direction. Sometimes we must sacrifice de things we hold dear. Nalorakk grant me strength and resilience.", ["objectivesText"] = "Return to Lilaju at Torntusk Overlook.", ["rewardGold"] = 30900, ["rewardXP"] = 1520, ["rewardItems"] = { 264468, 264469 }, ["rewardChoices"] = { 264468, 264469 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3354, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 251669, ["x"] = 0.2425, ["y"] = 0.6415 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 245664, ["x"] = 0.336, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.2425, ["y"] = 0.6415 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 92496, 92497 }, ["questLines"] = { { ["id"] = 6011, ["name"] = "Reclaiming De Honor", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[92503] = { ["id"] = 92503, ["name"] = "Ignite the Skies: Northern Eastern Kingdoms", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 47, ["mapID"] = 26, ["description"] = "Have you heard the tale of the wildsages and their summer star? No? Well, you're in for quite the treat! This story will take you on a journey that follows the path the Wildhammer elders once travelled many moons ago. Take to the skies and ignite the blossom lights as I tell the tale. Our journey begins here in the hills of Loch Modan...", ["rewardGold"] = 309800, ["rewardItems"] = { 23247 }, ["starts"] = { { ["npcID"] = 252784, ["x"] = 0.538, ["y"] = 0.692, ["mapID"] = 48 }, { ["npcID"] = 252784, ["x"] = 0.192, ["y"] = 0.482, ["mapID"] = 26 } }, ["ends"] = { { ["npcID"] = 252784, ["x"] = 0.538, ["y"] = 0.692, ["mapID"] = 48 }, { ["npcID"] = 252784, ["x"] = 0.192, ["y"] = 0.482, ["mapID"] = 26 } }, ["coords"] = { ["x"] = 0.538, ["y"] = 0.692, ["source"] = "quest_giver", ["mapID"] = 26 }, ["mapCandidates"] = { ["npc"] = { 26, 48 }, ["zone"] = { 47 } }, ["questType"] = "standard", ["sourceQuests"] = { 92504 } },
[92504] = { ["id"] = 92504, ["name"] = "Ignite the Skies: Southern Eastern Kingdoms", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 47, ["mapID"] = 26, ["description"] = "The fire festival is a time for people to come together and share stories around the fire. One such tale tells of a celebration of Midsummer and the elemental chaos it wrought for the humans of Stormwind. Our story will take us over the skies of the surrounding regions into lands now scarred by flame and ash. Take to the skies and ignite the blossom lights as I tell you the story. It begins in the Burning Steppes...", ["rewardGold"] = 309800, ["rewardItems"] = { 23247 }, ["starts"] = { { ["npcID"] = 252528, ["x"] = 0.48, ["y"] = 0.718, ["mapID"] = 84 }, { ["npcID"] = 266045, ["x"] = 0.744, ["y"] = 0.014, ["mapID"] = 37 } }, ["ends"] = { { ["npcID"] = 252784, ["x"] = 0.538, ["y"] = 0.692, ["mapID"] = 48 }, { ["npcID"] = 252784, ["x"] = 0.192, ["y"] = 0.482, ["mapID"] = 26 } }, ["coords"] = { ["x"] = 0.48, ["y"] = 0.718, ["source"] = "quest_giver", ["mapID"] = 26 }, ["mapCandidates"] = { ["npc"] = { 26, 37, 48, 84 }, ["zone"] = { 47 } }, ["questType"] = "standard", ["sourceQuests"] = { 92634, 92711 } },
[92505] = { ["id"] = 92505, ["name"] = "Truth of the Past", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 92505, 92506, 92507, 92508, 92509, 92510, 92511, 92512 }, ["description"] = "Thanks for freeing me from those ethereal cages in the Ethereum Overcroft. The Void is powerful here in ways we're only beginning to understand, and that danger brings new opportunities. If you remember, my quest to combine the power of the Void with the strength of the Illidari has not changed. Backing Adarus was a mistake, but a necessary one to progress. And now I've found a willing teacher in Allari. I ask for your help again, <name>. Help me find the strength to protect my people.", ["objectivesText"] = "Travel to Argus.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3389, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 252110, ["x"] = 0.532, ["y"] = 0.704 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 256285, ["x"] = 0.528, ["y"] = 0.142 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.704 }, ["mapCandidates"] = { ["npc"] = { 882, 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86543 }, ["questLines"] = { { ["id"] = 6001, ["name"] = "A More Potent Foe", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405, ["db2QuestHubAreaPoiID"] = 8502 },
[92506] = { ["id"] = 92506, ["name"] = "The Soul Price", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 882, ["storyline"] = { 92505, 92506, 92507, 92508, 92509, 92510, 92511, 92512 }, ["description"] = "Argus. Originally the homeworld of the Eredar, now the stronghold for the Burning Legion. Years ago, Illidan used the Seal of Argus to open the way here. And he was met by one of the naaru who delivered a dire message. To understand the Illidari's connection to the Void, you must see what Illidan saw when he arrived. Hostile spirits in the area should provide the necessary power for our needs. Defeat them to release their essence, and with their sacrifice we will peer into the past.", ["objectivesText"] = "Free spirits and collect their energy in Kil'jaeden's Terrace. Progress: The energy from these spirits will serve as a conduit for us to access the past.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3389, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 256285, ["x"] = 0.528, ["y"] = 0.142 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 256285, ["x"] = 0.528, ["y"] = 0.142 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.142 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["sourceQuests"] = { 92505 }, ["questLines"] = { { ["id"] = 6001, ["name"] = "A More Potent Foe", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882 },
[92507] = { ["id"] = 92507, ["name"] = "A More Potent Foe", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 882, ["storyline"] = { 92505, 92506, 92507, 92508, 92509, 92510, 92511, 92512 }, ["description"] = "We have what we need. Prepare yourself to see Illidan's confrontation with the naaru so many years ago.", ["objectivesText"] = "Watch the scene on the platform.", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 256285, ["x"] = 0.528, ["y"] = 0.142 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 252110, ["x"] = 0.532, ["y"] = 0.704 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.142 }, ["mapCandidates"] = { ["npc"] = { 882, 2405 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["sourceQuests"] = { 92506 }, ["questLines"] = { { ["id"] = 6001, ["name"] = "A More Potent Foe", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[92508] = { ["id"] = 92508, ["name"] = "The Mark of Sacrifice", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 92505, 92506, 92507, 92508, 92509, 92510, 92511, 92512 }, ["description"] = "The tattoos that mark our flesh are more than just ink. They're a promise inscribed across our flesh. The promise that we will hold back the dark and the infernal with our very bodies. That our lifeblood is a currency used to purchase Azeroth's future. Surprised? We are not simply rage and defiance manifest, although we are also that. Help Leona collect the vitae of the void creatures at Nexus-Point Antius. We'll use it to inscribe her tattoos, affirming the vow she makes to protect her people.", ["objectivesText"] = "Harvest vitae from the void creatures of Nexus-Point Antius.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3389, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 252109, ["x"] = 0.567, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 252109, ["x"] = 0.567, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.567, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 92507 }, ["questLines"] = { { ["id"] = 6001, ["name"] = "A More Potent Foe", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[92509] = { ["id"] = 92509, ["name"] = "One Cruel Implement", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 92505, 92506, 92507, 92508, 92509, 92510, 92511, 92512 }, ["description"] = "Voidstorm is a world of apex creatures. One in particular, the ultradon, stands above others in its strength and ferocity. But make no mistake, <name>. We demon hunters are the true apex predators wherever we go, because we are willing to go to any length in order to dominate. I see no better creature to harvest an implement in which to inscribe Leona's tattoos. Head to Nexus-Point Antius with Leona. Defeat as many ultradons as it takes to find the perfect implement.", ["objectivesText"] = "Harvest a Talon from the Ultradons at Nexus-Point Antius. Progress: Have you found the talon yet, <name>? Without it, we cannot start Leona's ritual.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 254671 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3389, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 252109, ["x"] = 0.567, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 252109, ["x"] = 0.567, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.567, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 92507 }, ["questLines"] = { { ["id"] = 6001, ["name"] = "A More Potent Foe", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[92510] = { ["id"] = 92510, ["name"] = "Dark Infusion", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 92505, 92506, 92507, 92508, 92509, 92510, 92511, 92512 }, ["description"] = "The branding ritual we're about to perform is adapted from what demon hunters go through on the Fel Hammer. But given Leona's unique nature and the experimental substitution of Void energy for fel, there's considerable risk here. Even more so than usual. Leona will be vulnerable during this process, as will I. We've found a secluded area to perform it, but we'll need your protection once we start.", ["objectivesText"] = "Enact the branding ritual. Progress: What we're doing is risky, <name>. But that's always been the way with the Illidari.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3389, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 252109, ["x"] = 0.567, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235698, ["x"] = 0.522, ["y"] = 0.696 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.567, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 92508, 92509 }, ["questLines"] = { { ["id"] = 6001, ["name"] = "A More Potent Foe", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[92511] = { ["id"] = 92511, ["name"] = "Event Horizon", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 92505, 92506, 92507, 92508, 92509, 92510, 92511, 92512 }, ["description"] = "It may not surprise you to know that the stabilization of portal entry points is something I'm quite familiar with. If Leona lives, and I believe she does, she'll need beacons to help triangulate her exit point. Take these beacons, set them up where I've marked on your map, and return here. If Leona is alive, she should be able to use these beacons to identify and stabilize her exit. If she isn't-- <Umbric pushes the thought away.> Let's focus on the task at hand for now.", ["objectivesText"] = "Place the beacons to help Leona find her way back.", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235698, ["x"] = 0.522, ["y"] = 0.696 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 253948, ["x"] = 0.52, ["y"] = 0.696 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.696 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 92510 }, ["questLines"] = { { ["id"] = 6001, ["name"] = "A More Potent Foe", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[92512] = { ["id"] = 92512, ["name"] = "Devourer", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 92505, 92506, 92507, 92508, 92509, 92510, 92511, 92512 }, ["description"] = "I'm not sure where I was when I stepped through that portal, <name>. Somewhere in between, Void energy surrounding and suffusing me. Without Umbric, I wouldn't have made it back. I feel different now, but I don't think this is over until we confront that domanaar. Will you meet us at the Voidspire?", ["objectivesText"] = "Help Leona confront Ravenor at the Voidspire. Progress: I await with eagerness and a bit of trepidation for Leona.", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["rewardItems"] = { 267004 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3389, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 253948, ["x"] = 0.52, ["y"] = 0.696 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 235698, ["x"] = 0.522, ["y"] = 0.696 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.696 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 92511 }, ["questLines"] = { { ["id"] = 6001, ["name"] = "A More Potent Foe", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[92520] = { ["id"] = 92520, ["name"] = "Wake of the Darkwell", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16215, ["mapID"] = 2393, ["storyline"] = { 88709, 90690, 90724, 92520 }, ["description"] = "The Sunwell--no... the Darkwell is overrun. Void-spawned creatures swarm the regions where our greatest champions of the Light held their ground to the very last. Champion, can you survey Quel'Danas? Find any survivors? If you tag them with these tokens, our mages here will be able to teleport the individuals back. We must try to save as many as we can.", ["objectivesText"] = "Search for Survivors on the Isle of Quel'Danas. Progress: This is a truly dark day.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3365, ["amount"] = 1000 }, { ["id"] = 3391, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 16215 } }, ["questType"] = "standard", ["sourceQuests"] = { 90724 }, ["questLines"] = { { ["id"] = 5793, ["name"] = "The Voidspire", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5793, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 2393 },
[92531] = { ["id"] = 92531, ["name"] = "The Medicine Loa's Shrine", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 87254, 87256, 87267, 87268, 87317, 91206, 92531 }, ["description"] = "Everyone has their own path toward understanding, even Akutu--though he has yet to set foot on it, unfortunately. My shrine was once a place of discovery and understanding for the Amani. Please take word to them that I welcome their return. The ghosts will calm in time.", ["objectivesText"] = "Return to Elder Doru with news of Kulzi 's return.", ["rewardGold"] = 34100, ["rewardXP"] = 1470, ["rewardItems"] = { 256645 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3354, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 237956, ["x"] = 0.388, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 254665, ["x"] = 0.432, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 87317 }, ["questLines"] = { { ["id"] = 5778, ["name"] = "Healing the Spirit", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[92546] = { ["id"] = 92546, ["name"] = "Encroaching Predators", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15458, ["mapID"] = 2405, ["storyline"] = { 92546 }, ["objectivesText"] = "Encroaching Shredclaw slain", ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.361, ["y"] = 0.603, ["mapID"] = 2405 } }, ["ends"] = { { ["x"] = 0.361, ["y"] = 0.603, ["mapID"] = 2405 } }, ["coords"] = { ["mapID"] = 2405, ["x"] = 0.361, ["y"] = 0.603 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15458 } }, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 8, ["objectID"] = 252119, ["text"] = "Encroaching Shredclaw slain" } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[92549] = { ["id"] = 92549, ["name"] = "Void From Above", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 92549 }, ["objectivesText"] = "Void Anomalies Dispersed", ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.646, ["y"] = 0.622, ["mapID"] = 2405 } }, ["ends"] = { { ["x"] = 0.646, ["y"] = 0.622, ["mapID"] = 2405 } }, ["coords"] = { ["mapID"] = 2405, ["x"] = 0.646, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16648 } }, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 20, ["objectID"] = 252160, ["text"] = "Void Anomalies Dispersed" } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[92554] = { ["id"] = 92554, ["name"] = "Addition of Anguish", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 92554 }, ["description"] = "? See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(92554)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(92554))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[92555] = { ["id"] = 92555, ["name"] = "Honor the Flame", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["description"] = "The time of Dawnsummer Festal has long been a cherished season for our people. Even during the years under the cold grasp of the Ghostlands, the people of Tranquillien strived to maintain this ancient celebration and bring a little light to these once-cold lands. Now, warmth yourself by the bonfire and honor the flames of summer!", ["rewardGold"] = 170800, ["rewardXP"] = 100, ["rewardItems"] = { 23247 }, ["starts"] = { { ["npcID"] = 252192, ["x"] = 0.488, ["y"] = 0.638, ["mapID"] = 2395 } }, ["ends"] = { { ["npcID"] = 569165, ["x"] = 0.489, ["y"] = 0.639, ["mapID"] = 2395 } }, ["coords"] = { ["x"] = 0.488, ["y"] = 0.638, ["source"] = "quest_giver", ["mapID"] = 2395 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard" },
[92556] = { ["id"] = 92556, ["name"] = "Honor the Flame", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["description"] = "A joyous Midsummer and Dawnsummer Festal upon you, ! While celebrating around the bonfire, it is important to pause for a moment of reflection. Much has happened here in Silvermoon in recent times and while we cannot dwell upon the darkness of the past, we must look towards the rising Dawn. Take a moment, while you honor the bonfire, and reflect upon its warmth!", ["rewardGold"] = 141800, ["rewardXP"] = 100, ["rewardItems"] = { 23247 }, ["starts"] = { { ["npcID"] = 248989, ["x"] = 0.486, ["y"] = 0.808, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 569162, ["x"] = 0.486, ["y"] = 0.811, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.486, ["y"] = 0.808, ["source"] = "quest_giver", ["mapID"] = 2393 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[92557] = { ["id"] = 92557, ["name"] = "Honor the Flame", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["description"] = "Fetna Alai-nazdo is upon us once again! Although her trample may be dark, her flame burns brightly in all of us! May this turn of the Season burn bright and bring good fortune to you and all who celebrate Fetna Alai-nazdo!", ["rewardGold"] = 170800, ["rewardXP"] = 100, ["rewardItems"] = { 23247 }, ["starts"] = { { ["npcID"] = 248975, ["x"] = 0.544, ["y"] = 0.168, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 569166, ["x"] = 0.543, ["y"] = 0.169, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.544, ["y"] = 0.168, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard" },
[92558] = { ["id"] = 92558, ["name"] = "Honor the Flame", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15458, ["mapID"] = 2405, ["description"] = "I remember the Dawnsummer Festal celebrations back in Eversong and thought 'why not light my own bonfire here in the Howling Ridge?' Thankfully, the local denizens didn't need much convincing. I told them the bonfires were sacrificial wells for vessels of esoteric magic and... well, that's one way to describe midsummer blossoms, right? Will you take a moment and honor the voidflame?", ["rewardGold"] = 154900, ["rewardXP"] = 100, ["rewardItems"] = { 23247 }, ["starts"] = { { ["npcID"] = 252194, ["x"] = 0.536, ["y"] = 0.702, ["mapID"] = 2405 } }, ["ends"] = { { ["npcID"] = 569169, ["x"] = 0.537, ["y"] = 0.701, ["mapID"] = 2405 } }, ["coords"] = { ["x"] = 0.536, ["y"] = 0.702, ["source"] = "quest_giver", ["mapID"] = 2405 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard" },
[92559] = { ["id"] = 92559, ["name"] = "Honor the Flame", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["description"] = "The season of Midsummer may be unfamiliar to us, but telling stories by the glow of our root flames is not. Take a moment to reflect by the bonfire, friend, and listen to those around you. Ponder that which has come before you and that which has yet to unfurl.", ["rewardGold"] = 154900, ["rewardXP"] = 100, ["rewardItems"] = { 23247 }, ["starts"] = { { ["npcID"] = 252196, ["x"] = 0.542, ["y"] = 0.514, ["mapID"] = 2413 } }, ["ends"] = { { ["npcID"] = 569167, ["x"] = 0.543, ["y"] = 0.514, ["mapID"] = 2413 } }, ["coords"] = { ["x"] = 0.542, ["y"] = 0.514, ["source"] = "quest_giver", ["mapID"] = 2413 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard" },
