[92583] = { ["id"] = 92583, ["name"] = "Fungicide", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92583 }, ["objectivesText"] = "Run through the Entryway Fight in the Grudge Pit", ["rewardXP"] = 13690, ["starts"] = { { ["x"] = 0.718, ["y"] = 0.644, ["mapID"] = 2413 } }, ["ends"] = { { ["x"] = 0.718, ["y"] = 0.644, ["mapID"] = 2413 } }, ["coords"] = { ["mapID"] = 2413, ["x"] = 0.718, ["y"] = 0.644 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15355 } }, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 19, ["amount"] = 0, ["objectID"] = 39544, ["text"] = "Run through the Entryway" }, { ["orderIndex"] = 1, ["type"] = 15, ["amount"] = 1, ["objectID"] = 0, ["text"] = "Fight in the Grudge Pit" }, { ["orderIndex"] = 2, ["type"] = 0, ["amount"] = 6, ["objectID"] = 243779 }, { ["orderIndex"] = 3, ["type"] = 0, ["amount"] = 6, ["objectID"] = 248986 }, { ["orderIndex"] = 4, ["type"] = 0, ["amount"] = 6, ["objectID"] = 243776 }, { ["orderIndex"] = 5, ["type"] = 21, ["amount"] = 17, ["objectID"] = 5383 }, { ["orderIndex"] = 6, ["type"] = 0, ["amount"] = 25, ["objectID"] = 243780 }, { ["orderIndex"] = 7, ["type"] = 0, ["amount"] = 6, ["objectID"] = 243778 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[92600] = { ["id"] = 92600, ["name"] = "Cracked Keystone", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["storyline"] = { 92600 }, ["description"] = "Fragmentary images of heroic deeds flash though your mind as you touch the stone, but they fade as fast as they arrive. Perhaps performing a suitably impressive task will stabilize the stone's magic once more?", ["objectivesText"] = "Complete any dungeon on Mythic 2 or higher difficulty.", ["rewardGold"] = 1366400, ["rewardXP"] = 23530, ["rewardItems"] = { 253245 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 253245 } },
[92603] = { ["id"] = 92603, ["name"] = "O Lonely Star", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 92603, 92604, 92605, 92606, 92607 }, ["description"] = "<The void elf writhes in a fitful sleep, tormented by the nearby shade. Perhaps you should try to wake him.>", ["objectivesText"] = "Learn more about the shade tormenting Orin.", ["rewardGold"] = 34100, ["rewardXP"] = 1605, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3389, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 252510, ["x"] = 0.364, ["y"] = 0.603 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 254012, ["x"] = 0.395, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.364, ["y"] = 0.603 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 86509 }, ["questLines"] = { { ["id"] = 6019, ["name"] = "A Gift, Given Freely", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[92604] = { ["id"] = 92604, ["name"] = "Speak in Blood", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 92603, 92604, 92605, 92606, 92607 }, ["description"] = "After my failed creation, I sought wisdom from the Void, and it told me of this place. There was a voice--strange, yet familiar. It promised a tool for shaping Void and shadow--something that would free me from my failure, but the Void gives nothing freely. We must command it, and violence is this land's mother tongue. Slay the beasts here and bring me their ichor. We'll use it to write our demands.", ["objectivesText"] = "Gather 50 Viscous Ichor from creatures in the Fangfall. Progress: Do you have it? The shade won't be silent. It wasn't meant to exist like this.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 256692 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 254012, ["x"] = 0.395, ["y"] = 0.38 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 252510, ["x"] = 0.364, ["y"] = 0.603 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 92603 }, ["questLines"] = { { ["id"] = 6019, ["name"] = "A Gift, Given Freely", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[92605] = { ["id"] = 92605, ["name"] = "Honest as Bone", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 92603, 92604, 92605, 92606, 92607 }, ["description"] = "If ichor is to be the carrier for our message, bone shall be its pigment. This is a place of scavengers, with bones stolen from across this land: old, new, all carrying the echoes of violence that brought their ends. Bring me bone splinters and I will powder them for our ink. Please hurry. This shade is a wrong thing, and I must put it right.", ["objectivesText"] = "Gather 8 Bone Splinters from the Fangfall. Progress: These scavengers must have brought bones from all over Voidstorm .", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 256694 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 254012, ["x"] = 0.395, ["y"] = 0.38 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 252510, ["x"] = 0.364, ["y"] = 0.603 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 92603 }, ["questLines"] = { { ["id"] = 6019, ["name"] = "A Gift, Given Freely", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[92606] = { ["id"] = 92606, ["name"] = "Take Up Your Gift", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 92603, 92604, 92605, 92606, 92607 }, ["description"] = "This place--this wound--is what the voice from the Void told me I'd find. There's something waiting inside... something to put an end to this broken creation. <Orin winces and glares at the shade.> You can't hear it? It howls. Sometimes in rage. Other times it sounds so lonely that it breaks my heart. Ignore it. With the proper runes written in ichor and bone, I believe we can open this rift wider. Then you can seize what lies within.", ["objectivesText"] = "Help Orin open the rift and uncover what lies within. Progress: The voice spoke true. There was something waiting here.", ["rewardGold"] = 170800, ["rewardXP"] = 6425, ["rewardItems"] = { 256549 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 252510, ["x"] = 0.364, ["y"] = 0.603 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 254014, ["x"] = 0.33, ["y"] = 0.364 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.364, ["y"] = 0.603 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 92604, 92605 }, ["questLines"] = { { ["id"] = 6019, ["name"] = "A Gift, Given Freely", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[92607] = { ["id"] = 92607, ["name"] = "And Carve New Shapes", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 92603, 92604, 92605, 92606, 92607 }, ["description"] = "This is what the voice from the Void promised me: the means to divest myself of this shade. You'll have to wield it. Don't worry--it won't harm me. It will separate me from the shade. Then it should simply fade away, no more than an unmoored shadow. Go on. I'm ready.", ["objectivesText"] = "Separate Orin from his shade.", ["rewardGold"] = 625600, ["rewardXP"] = 16055, ["rewardItems"] = { 264308, 264309, 264310, 264311 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3389, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 254014, ["x"] = 0.33, ["y"] = 0.364 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 254105, ["x"] = 0.332, ["y"] = 0.37 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.364 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 92606 }, ["questLines"] = { { ["id"] = 6019, ["name"] = "A Gift, Given Freely", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[92608] = { ["id"] = 92608, ["name"] = "Landscape Photography", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16105, ["mapID"] = 2351, ["storyline"] = { 92608 }, ["description"] = "I'm having just the best time in your lovely village, it's so quaint! I'm feeling inspired. I would like to paint a landscape picture to commemorate the occasion. But you know the area better than I. Could you provide me with some pictures of the landscape I can use for inspiration? You can use my camera. It's top of the line, of course. I'm sure the perfect spots will just beam at you.", ["objectivesText"] = "Take enough photos of your neighborhood to inspire Corlen Hordralin . Progress: This place is such a delight, so laid back and rustic.", ["rewardGold"] = 341600, ["rewardXP"] = 3440, ["rewardItems"] = { 253316 }, ["rewardCurrencies"] = { { ["id"] = 3363, ["amount"] = 3 } }, ["starts"] = { { ["mapID"] = 2351, ["npcID"] = 252717, ["x"] = 0.538, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 2351, ["npcID"] = 252717, ["x"] = 0.538, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2351, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 2351 }, ["zone"] = { 16105 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5616 } },
[92616] = { ["id"] = 92616, ["name"] = "Mushrooming Courage", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90615, 90616, 90617, 90619, 90620, 90621, 90622, 91270, 91450, 92616, 92617, 92618 }, ["description"] = "Brakko sorry that Brakko let $p and TeamName down. Brakko is much scared of sporegliders. Could sneak up at Brakko above cap, where cannot see. Could really hurt cap! Very sorry, $p. Brakko doesn't think Brakko can be tank for team. Unless... $p practice sporegliders with Brakko ?", ["objectivesText"] = "Help Brakko face his fear of sporegliders.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 247245, ["x"] = 0.718, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 247245, ["x"] = 0.718, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questTurnInID"] = 247245, ["questType"] = "standard", ["sourceQuests"] = { 90620 }, ["questLines"] = { { ["id"] = 5910, ["name"] = "The Grudge Pit", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92617] = { ["id"] = 92617, ["name"] = "Mushrooming Resilience", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90615, 90616, 90617, 90619, 90620, 90621, 90622, 91270, 91450, 92616, 92617, 92618 }, ["description"] = "First Tuktuk runs, then Brakko runs. Cannot be the only one still fighting. Ziny will fail by Ziny 's self. Fight is too hard alone, will not be strong enough. Do not want to fail. Cannot let PH_Teamname down! Had choice, fail or run. But run was also fail. Ziny very sorry to $p! Can practice, fight big and scary enemies together?", ["objectivesText"] = "Face 4 scary enemies with Ziny . Progress: Ziny will try to heal <name>.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 251723, ["x"] = 0.718, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 251723, ["x"] = 0.718, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90620 }, ["questLines"] = { { ["id"] = 5910, ["name"] = "The Grudge Pit", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92618] = { ["id"] = 92618, ["name"] = "Mushrooming Confidence", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 90615, 90616, 90617, 90619, 90620, 90621, 90622, 91270, 91450, 92616, 92617, 92618 }, ["description"] = "Tuktuk 's poison is not good enough. Tuktuk had to run, before we lose. Sorry if you lose! Tuktuk did not lose. Tuktuk quit. Quit is safe from lose. Grudge Pit very, rrr... is so intense. Tuktuk cannot handle. Tuktuk will stay out where is safe. Tuktuk will find place to relax. Away from Grudge Pit. Tuktuk cannot lose if stay far away.", ["objectivesText"] = "Help Tuktuk face 3 difficult feelings.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 251715, ["x"] = 0.718, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 247252, ["x"] = 0.676, ["y"] = 0.672 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 90620 }, ["questLines"] = { { ["id"] = 5910, ["name"] = "The Grudge Pit", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92630] = { ["id"] = 92630, ["name"] = "The Pursuit Continues", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 92630, 92631, 92632 }, ["description"] = "I bring word from Magister Umbric ! His apprentice, Leona, has been preoccupied with a desire to learn how the ways of the Illidari. She apparently found another demon hunter willing to train her, should she prove herself worthy. But after what happened the last time she sought such a mentor, Umbric is concerned for her safety. Umbric requests you join Leona for this trial. Make sure she is not getting involved in something she is not prepared to handle.", ["objectivesText"] = "Find Leona and Allari in K'aresh .", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 248153, ["x"] = 0.608, ["y"] = 0.278 }, { ["mapID"] = 2393, ["npcID"] = 257544, ["x"] = 0.535, ["y"] = 0.66 }, { ["mapID"] = 2339, ["npcID"] = 259951, ["x"] = 0.445, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 254266, ["x"] = 0.65, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.278 }, ["mapCandidates"] = { ["npc"] = { 2339, 2371, 2393 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6043, ["name"] = "Rage of the Ren'dorei", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[92631] = { ["id"] = 92631, ["name"] = "Abhorrent Gauntlet", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 92630, 92631, 92632 }, ["description"] = "Leona must demonstrate mastery of her weapons--and of her own enmity--by retrieving undamaged pieces of her kills. I will observe from here. You, <name>, will go with her.", ["objectivesText"] = "Harvest 24 undamaged parts from aberrations in the Tempest Fields. Progress: A demon hunter wields their ire, but is never ruled by it.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 266128 }, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 252617, ["x"] = 0.65, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 252617, ["x"] = 0.65, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.65, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 91044, 92630 }, ["questLines"] = { { ["id"] = 6043, ["name"] = "Rage of the Ren'dorei", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[92632] = { ["id"] = 92632, ["name"] = "Trial of Wrath", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2371, ["storyline"] = { 92630, 92631, 92632 }, ["description"] = "Cutting through scores of lesser foes is a simple task for any demon hunter. It's when we face a large, singular threat that our skills are truly tested. That will be Leona's trial. You will act as her second. Let us see how she vanquishes a particularly dangerous opponent.", ["objectivesText"] = "Kill Vraxik , the Dimensional Wanderer.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["starts"] = { { ["mapID"] = 2371, ["npcID"] = 252617, ["x"] = 0.65, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 254748, ["x"] = 0.608, ["y"] = 0.278 } }, ["coords"] = { ["mapID"] = 2371, ["source"] = "quest_giver", ["x"] = 0.65, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 2371 }, ["zone"] = { 15336 } }, ["questType"] = "standard", ["sourceQuests"] = { 92631 }, ["questLines"] = { { ["id"] = 6043, ["name"] = "Rage of the Ren'dorei", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[92634] = { ["id"] = 92634, ["name"] = "Midsummer's Journey to Loch Modan", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 6170, ["mapID"] = 37, ["description"] = "While Midsummer may be sacred to the tauren, we are not the only people to pay respects to the spirits of fire during the summer months. The Wildhammer, for example, have shared their own customs with us over the years. It seems this time of year has long been important to the dwarves and denizens of the Eastern Kingdoms. Journey to their celebration grounds across the sea in Loch Modan and visit with the Wildhammer. Perhaps they too will tell you a tale...", ["rewardGold"] = 156400, ["rewardItems"] = { 23247 }, ["starts"] = { { ["npcID"] = 251986, ["x"] = 0.222, ["y"] = 0.192, ["mapID"] = 10 }, { ["npcID"] = 251986, ["x"] = 0.316, ["y"] = 0.636, ["mapID"] = 71 } }, ["ends"] = { { ["npcID"] = 266045, ["x"] = 0.744, ["y"] = 0.014, ["mapID"] = 37 } }, ["coords"] = { ["x"] = 0.222, ["y"] = 0.192, ["source"] = "quest_giver", ["mapID"] = 37 }, ["mapCandidates"] = { ["npc"] = { 10, 37, 71 }, ["zone"] = { 6170 } }, ["questType"] = "standard", ["sourceQuests"] = { 92420 }, ["nextQuests"] = { 92504 } },
[92635] = { ["id"] = 92635, ["name"] = "Midsummer's Journey to the Barrens", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 17, ["mapID"] = 10, ["description"] = "Although we have our own traditions during this time, we are not the only ones who pay respects to the spirits of fire during the summer months. If you wish to hear the origins of the tauren traditions, travel to Kalimdor to continue your journey.", ["rewardGold"] = 170800, ["rewardItems"] = { 23247 }, ["starts"] = { { ["npcID"] = 252784, ["x"] = 0.538, ["y"] = 0.692, ["mapID"] = 48 }, { ["npcID"] = 252784, ["x"] = 0.192, ["y"] = 0.482, ["mapID"] = 26 } }, ["ends"] = { { ["npcID"] = 265658, ["x"] = 0.624, ["y"] = 0.116, ["mapID"] = 10 } }, ["coords"] = { ["x"] = 0.538, ["y"] = 0.692, ["source"] = "quest_giver", ["mapID"] = 10 }, ["mapCandidates"] = { ["npc"] = { 10, 26, 48 }, ["zone"] = { 17 } }, ["questType"] = "standard", ["sourceQuests"] = { 92503 }, ["nextQuests"] = { 92106 } },
