[92647] = { ["id"] = 92647, ["name"] = "A Shadowed Journey Through Time", ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 92647 }, ["description"] = "Champion! The curiosities hidden within the Shadowlands are numerous, as are the dangers. I could use some assistance clearing a path, so to speak. There is much wealth to be gained should you choose to seek it.", ["objectivesText"] = "Complete 5 Timewalking dungeons.", ["rewardGold"] = 1353200, ["rewardItems"] = { 232877 }, ["starts"] = { { ["x"] = 0.56, ["y"] = 0.639, ["mapID"] = 1670, ["npcID"] = 252687 } }, ["ends"] = { { ["x"] = 0.56, ["y"] = 0.639, ["mapID"] = 1670, ["npcID"] = 252687 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.56, ["y"] = 0.639 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 252687, ["questTurnInID"] = 252687, ["questType"] = "standard" },
[92650] = { ["id"] = 92650, ["name"] = "The Flickering Anima", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 10565, ["mapID"] = 1670, ["description"] = "The strange anima shimmers with a gentle hum, barely larger than a candle. As your hand draws near it erupts, flooding your mind with a torrent of visions. Triumphs earned through blood, regrets etched in grief, serene stillness all too fleeting, the bitter taste of betrayal. The unbearable cascade threatens to shatter your mind like glass. Then, silence. The visions end leaving an image Oribos seared into your mind.", ["rewardGold"] = 325300, ["rewardXP"] = 200, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 200 }, { ["id"] = 1166, ["amount"] = 500 } }, ["ends"] = { { ["npcID"] = 239840, ["x"] = 0.708, ["y"] = 0.17, ["mapID"] = 1161 }, { ["npcID"] = 239840, ["x"] = 0.46, ["y"] = 0.948, ["mapID"] = 1165 } }, ["mapCandidates"] = { ["npc"] = { 1161, 1165 }, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[92657] = { ["id"] = 92657, ["name"] = "The Brewing Storm", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 92657, 92658, 92659, 92660, 92661, 92662 }, ["description"] = "Our foothold in Stormarion is tenuous at best. We're barely holding the enemy off on one front. We certainly don't have the forces to assault the rest of the citadel. That's where you and I come in. Meet me in Stormarion Citadel when you're ready to get to work.", ["objectivesText"] = "Meet Lysikas in the Stormarion Citadel.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["rewardItems"] = { 246951 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3389, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 254510, ["x"] = 0.36, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 254509, ["x"] = 0.264, ["y"] = 0.684 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.36, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86522 }, ["nextQuests"] = { 92658, 92659 }, ["questLines"] = { { ["id"] = 6022, ["name"] = "Go Low, Go Loud", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[92658] = { ["id"] = 92658, ["name"] = "Tactical Acquisition", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 92657, 92658, 92659, 92660, 92661, 92662 }, ["description"] = "All our forces are focused on this courtyard, but I think we've got another problem. I've scouted between assaults: there's activity in the lower keep. Not to worry you, but there are signs of another singularity. Up for a little reconnaissance? We'll go through the trench. They've got an impressive operation for gathering Void energy. Might as well hit that on the way. After all, our defenses here can't power themselves. If I'm wrong, we can tell Maella we were proactively shoring up supply lines.", ["objectivesText"] = "Steal Void Energy Reserves from the trench near Stormarion Citadel.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 246951, 257727, 257728, 257870 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 254509, ["x"] = 0.264, ["y"] = 0.684 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 252947, ["x"] = 0.356, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.264, ["y"] = 0.684 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 92657 }, ["questLines"] = { { ["id"] = 6022, ["name"] = "Go Low, Go Loud", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[92659] = { ["id"] = 92659, ["name"] = "Resource Denial", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 92657, 92658, 92659, 92660, 92661, 92662 }, ["description"] = "I've got a hunch I need to follow in the lower keep, and that means going through the trench. I hate to miss targets of opportunity, and the Host's energy collecting operation is right there. How do you feel about wrecking their production capacity? The longer it takes them to recover, the easier it'll be to maintain the offensive up here. It's not complicated. If it looks useful to the enemy, smash it. After that, we'll move onto the main objective in the keep itself.", ["objectivesText"] = "Destroy 6 Void Condensers in the trench north of Stormarion Citadel.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 246951 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 254509, ["x"] = 0.264, ["y"] = 0.684 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 252947, ["x"] = 0.356, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.264, ["y"] = 0.684 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 92657 }, ["questLines"] = { { ["id"] = 6022, ["name"] = "Go Low, Go Loud", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[92660] = { ["id"] = 92660, ["name"] = "Null Implements", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 92657, 92658, 92659, 92660, 92661, 92662 }, ["description"] = "Yes, there may be another unstable singularity. No, I didn't tell anyone. We don't have enough forces to divert our attention--that's why I asked you to accompany me. Besides, we've only got the one Singularity Anchor. Don't worry though, I've got a plan. These domanaar are experts on shaping the Void, so they must have some means of controlling singularities. Get in there and grab any tools that look important. We'll find a way to stabilize this singularity ourselves.", ["objectivesText"] = "Collect domanaar tools in the Stormarion Keep. Progress: I'm sure a domanaar's tools will be able to stabilize a singularity.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 246951, 257729, 257730, 257731 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 252947, ["x"] = 0.356, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 252947, ["x"] = 0.356, ["y"] = 0.668 }, { ["mapID"] = 2405, ["npcID"] = 254515, ["x"] = 0.312, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 92658, 92659 }, ["questLines"] = { { ["id"] = 6022, ["name"] = "Go Low, Go Loud", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[92661] = { ["id"] = 92661, ["name"] = "Hammer Meet Anvil", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 92657, 92658, 92659, 92660, 92661, 92662 }, ["description"] = "I don't approve of Lysikas's disregard for duty, but I do trust his instincts. If he says there's something here we need to see, then he's probably right. Even if he's wrong, we shouldn't waste this opportunity. A domanaar weaponsmith and researcher does his work from here. With most of the Stormarion forces attacking our Singularity Anchor, he should be an easy target. Take him out.", ["objectivesText"] = "Slay Telumnus and 8 Stormarion Keep forces.", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["rewardItems"] = { 246951 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 252949, ["x"] = 0.356, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 254513, ["x"] = 0.312, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 92658, 92659 }, ["questLines"] = { { ["id"] = 6022, ["name"] = "Go Low, Go Loud", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[92662] = { ["id"] = 92662, ["name"] = "Core Collapse", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 92657, 92658, 92659, 92660, 92661, 92662 }, ["description"] = "This singularity could reach critical mass at any moment. We've no time to evacuate. It will devour our forces in the upper citadel, maybe even the Ingress. Will you handle the tools? I've no idea how they work, but you've used more artifacts and seen more strange magic than most. Remember, the Void responds to will. Use the tools and command the singularity to stabilize. I trust you'll figure out the rest. The Host will try to stop us. Lay down some defenses, then I'll cover you while you work.", ["objectivesText"] = "Avert the singularity collapse.", ["rewardGold"] = 309800, ["rewardXP"] = 13690, ["rewardItems"] = { 246951, 260590, 264325, 264326, 264327, 264328 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3389, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 254513, ["x"] = 0.312, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 254513, ["x"] = 0.312, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 92660, 92661 }, ["questLines"] = { { ["id"] = 6022, ["name"] = "Go Low, Go Loud", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[92688] = { ["id"] = 92688, ["name"] = "Bronze Simulacrum", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["mapID"] = 619, ["storyline"] = { 92688 }, ["description"] = "< Erus will be delighted to scrap this for you for a heaping sum of bronze .>", ["objectivesText"] = "Give the Bronze Simulacrum to Erus at the Infinite Bazaar near Dalaran. Progress: You have something for Erus ?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 242516, 247808, 248141 }, ["ends"] = { { ["mapID"] = 619, ["npcID"] = 241141, ["x"] = 0.458, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 619, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 619 }, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 247808 } },
[92689] = { ["id"] = 92689, ["name"] = "A Path Forward", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 90861, 90862, 90867, 90871, 90876, 92689 }, ["description"] = "<name>, today will be a day of ceremonies and great magic. Before we begin to cleanse the Darkwell, agreements must be made. We have two events that have requested your presence, both as a mediator and as a witness. What we lay down today will have lasting ramifications, and it is important to all of us that we have you at the center of it all. Meet with Aethas and Rommath for their respective events. Once you are done, return here and we shall continue to the Darkwell together.", ["objectivesText"] = "Assist Aethas Sunstrider and Grand Magister Rommath.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["rewardItems"] = { 210455, 211313 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 88710 }, ["questLines"] = { { ["id"] = 5798, ["name"] = "Dawn of a New Well", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5798, ["questLineOrder"] = 5 } } },
[92692] = { ["id"] = 92692, ["name"] = "Hero's Call: Test!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 92692 }, ["series"] = { 35702, 36576, 36495, 34676, 37183, 49565, 34558 }, ["description"] = "All able-bodied citizens of the Alliance are to report to Foreman Eksos in Talador . The Iron Horde seek to control Talador . The area is perfect to send reinforcements to any other part of Draenor quickly and without resistance. Foreman Eksos is currently establishing an outpost in Talador . Travel there and stop the Iron Horde. Glory to the Alliance!", ["objectivesText"] = "Speak with Foreman Eksos in Talador .", ["rewardGold"] = 16980, ["rewardXP"] = 345, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[92694] = { ["id"] = 92694, ["name"] = "Dusk Among Pigments", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92694, 92695, 92696, 92697 }, ["description"] = "As Zur'ashar, our oath is to safeguard the harmony within the visions and the histories we preserve. Yet Orn'shan 's crude strokes are reckless. Their creative impulses lack refinement, disturbing the balance we are sworn to protect. In a misguided attempt at creativity, they've created uncontrollable chaos and are distorting the very truths they sought to record. Perhaps they will heed the words of an outsider before their reputation collapses entirely.", ["objectivesText"] = "Speak with Orn'shan in Amirdrassil Roots.", ["rewardGold"] = 33100, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3370, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 252871, ["x"] = 0.705, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 252872, ["x"] = 0.732, ["y"] = 0.544 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86930 }, ["questLines"] = { { ["id"] = 6038, ["name"] = "A Palette of Feelings", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92695] = { ["id"] = 92695, ["name"] = "The Stroke of Storms", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92694, 92695, 92696, 92697 }, ["description"] = "I... I don't think I can mend this. The Zur'ashar were right. I am no true paintmaker. I cannot even capture history properly within my own memories... how could I ever hope to honor it in moments that matter? I thought I could create something beautiful... something worthy. I was foolish to try. Can you... can you help me clean this mess? I... I have no hope left to do it myself.", ["objectivesText"] = "Use the visionstone to enter the painting and restore harmony. Progress: I fear I ruined everything. Have you been able to undo the destruction I brought upon this vision?", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 252872, ["x"] = 0.732, ["y"] = 0.544 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 252872, ["x"] = 0.732, ["y"] = 0.544 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.732, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 92694 }, ["questLines"] = { { ["id"] = 6038, ["name"] = "A Palette of Feelings", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92696] = { ["id"] = 92696, ["name"] = "Colors Born Anew", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92694, 92695, 92696, 92697 }, ["description"] = "Outsider... thank you. I'm still shaken... but I can feel a small spark returning. I'd nearly abandoned my work entirely, yet your kindness... it has steadied me. I think I finally see what I'm meant to create: something meaningful that honors the Zur'ashar tradition through my voice, but to begin, I need the raw essence of color itself. Will you help me collect the ingredients I need? I'd be looking for anything I can use to turn into paint.", ["objectivesText"] = "Collect ingredients for Orn'shan from the Shrouded Grove. Progress: Have you collected the ingredients I need?", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 258571 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 252872, ["x"] = 0.732, ["y"] = 0.544 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 252872, ["x"] = 0.732, ["y"] = 0.544 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.732, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 92695 }, ["questLines"] = { { ["id"] = 6038, ["name"] = "A Palette of Feelings", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92697] = { ["id"] = 92697, ["name"] = "Hues of Tomorrow", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92694, 92695, 92696, 92697 }, ["description"] = "I... never expected to feel this again. Your help has given me hope. These ingredients feel right, and maybe even enough. I want you to be the first to paint. Do not fret over perfection. Paint what you feel, and I'll capture its essence into the memory I preserve. I look forward to see what you create.", ["objectivesText"] = "Paint Pictures for Orn'Shan in Amirdrassil Roots. Progress: Have you put paint to stone and watched your creativity flow?", ["rewardGold"] = 170800, ["rewardXP"] = 6085, ["rewardItems"] = { 260523, 260524, 260525, 260526, 260527, 260528, 260529, 260530, 269981 }, ["rewardChoices"] = { 260523, 260524, 260525, 260526, 260527, 260528, 260529, 260530, 269981 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3370, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 252872, ["x"] = 0.732, ["y"] = 0.544 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 252872, ["x"] = 0.732, ["y"] = 0.544 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.732, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 92696 }, ["questLines"] = { { ["id"] = 6038, ["name"] = "A Palette of Feelings", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92711] = { ["id"] = 92711, ["name"] = "Ignite the Skies: Stormwind", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 1519, ["mapID"] = 84, ["description"] = "Welcome to the Midsummer Festival of Fire, friend! Have you come to toss a few torches? Or maybe dance around the maypole? Ah, you must be here to ignite the blossom lights over the skies of Stormwind, aren't you? It is an old tradition, long forgotten but newly rekindled! Well, come on then. Take to the skies and fly!", ["rewardGold"] = 292100, ["rewardItems"] = { 23247 }, ["starts"] = { { ["npcID"] = 252528, ["x"] = 0.48, ["y"] = 0.718, ["mapID"] = 84 } }, ["ends"] = { { ["npcID"] = 252528, ["x"] = 0.48, ["y"] = 0.718, ["mapID"] = 84 } }, ["coords"] = { ["x"] = 0.48, ["y"] = 0.718, ["source"] = "quest_giver", ["mapID"] = 84 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[92713] = { ["id"] = 92713, ["name"] = "Echoes Rekindled", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92713 }, ["description"] = "The relics you restored still hum with the visions you once walked. Their stories yearn to be lived again, and each retelling leaves the world just a little richer than before. Return them to the shrines, let the memories flow, and I shall place in your hands a reward for one who walks the paths of legend.", ["objectivesText"] = "Select a relic to experience once again.", ["rewardItems"] = { 263467 }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard" },
[92715] = { ["id"] = 92715, ["name"] = "By Invitation Only?", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 92715 }, ["series"] = { 92740 }, ["description"] = "Fancy yourself a Brawl'gar contender do you, <class>? They don't let just anyone in there, you know. Certainly not without an invitation. That said... just between you and me, if you know where to look and you've the means they say anyone can have their moment in the spotlight these days.", ["objectivesText"] = "Talk to Alton Philips near the Brawl'gar Arena.", ["rewardGold"] = 31200, ["rewardXP"] = 1470, ["rewardItems"] = { 254690 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 252857, ["x"] = 0.459, ["y"] = 0.606 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 252933, ["x"] = 0.735, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.459, ["y"] = 0.606 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[92716] = { ["id"] = 92716, ["name"] = "The Story of Wey'nan's Ward", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92716, 92719, 92720, 92721, 92722, 92724, 92725 }, ["description"] = "You have walked this path before, <name>, yet the Vale of Secrets stirs anew. The Visionstone awaits, its sacred paintings familiar to your eyes, the handprint at its heart calling for you again. Press your hand upon it once more and let your spirit be known. The trance will take you as before, carrying your soul through visions whose truths still shift with every telling. Return to me with what new wisdom the echoes grant you.", ["objectivesText"] = "Travel to the indicated shrine in Harandar to meditate and experience the history of Wey'nan's Ward. Progress: Tell me, <name>, what new truths did the past reveal this time?", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 263467, 279525 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3370, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6209, ["name"] = "Legends of the Haranir", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2LabelIDs"] = { 4794 }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92719] = { ["id"] = 92719, ["name"] = "The Story of the Cauldron of Echoes", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92716, 92719, 92720, 92721, 92722, 92724, 92725 }, ["description"] = "Once more, the Cauldron of Echoes stirs. When I first walked the path of the Zur'Ashar, my master spoke of its place at our beginning. Even they could not grasp its full meaning. Now, it beckons again. Step into its quiet and draw forth what the ages have hidden. Bring me the truth as it speaks to you this time.", ["objectivesText"] = "Travel to the Glade of Walking Memories in Harandar to learn the history of the Cauldron of Echoes.", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 263467, 279525 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3370, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6209, ["name"] = "Legends of the Haranir", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2LabelIDs"] = { 4794 }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92720] = { ["id"] = 92720, ["name"] = "The Story of Aln'hara's Bloom", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92716, 92719, 92720, 92721, 92722, 92724, 92725 }, ["description"] = "The bloom still waits, its stillness carrying the same quiet call you once followed. Yet the bloom's story deepens with each telling. Walk its path again, let the stillness speak anew, and see what more the goddess chooses to share.", ["objectivesText"] = "Travel to Veilroot Clearing and uncover the truth behind Aln'hara's Bloom.", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 263467, 269703, 279525 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3370, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6209, ["name"] = "Legends of the Haranir", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2LabelIDs"] = { 4794 }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92721] = { ["id"] = 92721, ["name"] = "The Story of the Echoless Flame", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92716, 92719, 92720, 92721, 92722, 92724, 92725 }, ["description"] = "The Echoless Flame rests as you left it, yet the air around it stirs once more. You have walked Obayo's path before, felt the echo of that first Shul'ka's purpose. But the past is a shifting thing, and the Flame's silence may yet hide verses you have not heard. Return to its vigil. Follow Obayo's steps again, and let the vision show you what remains untold.", ["objectivesText"] = "Travel to the Verdant Sepulcher in Harandar to learn the history of the Echoless Flame. Progress: Tell me, <name>, what new light did the flame cast for you this time?", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 263467, 279525 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3370, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6209, ["name"] = "Legends of the Haranir", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2LabelIDs"] = { 4794 }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92722] = { ["id"] = 92722, ["name"] = "The Story of Russula's Outreach", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92716, 92719, 92720, 92721, 92722, 92724, 92725 }, ["description"] = "The spear still waits where you last left it, pale threads of mushroom slowly weaving new patterns into its grain. The culling grounds draw you again. Walk their softened paths, follow what spores still rise, and let the visions show what time has chosen to reveal this season.", ["objectivesText"] = "Travel to the Verdant Sepulcher to learn the history of Russula's Outreach.", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 263467, 279525 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3370, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6209, ["name"] = "Legends of the Haranir", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2LabelIDs"] = { 4794 }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92724] = { ["id"] = 92724, ["name"] = "The Story of the Root of the World", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92716, 92719, 92720, 92721, 92722, 92724, 92725 }, ["description"] = "The Root of the World stands as it did before--ancient, unbowed--yet the soil breathes differently today. Beneath your feet, the pulse of Harandar quickens, as though eager to share another verse of its oldest story. You have seen through Ruilla the Huntress's eyes once before. But the Rootways are never walked the same way twice. Go again, and let the land decide which truths it will show you now.", ["objectivesText"] = "Travel to the Vale of Secrets to learn the history of the Root of the World. Progress: And so the Root yielded another fragment? Tell me, what shade of truth did it whisper this time?", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 263467, 269703, 279525 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3370, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6209, ["name"] = "Legends of the Haranir", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2LabelIDs"] = { 4794 }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92725] = { ["id"] = 92725, ["name"] = "The Story of Sky's Hope", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92716, 92719, 92720, 92721, 92722, 92724, 92725 }, ["description"] = "Sky's Hope rests in its cradle as before, yet the heavens above seem sharper tonight. You have traced Awe'ohna's path once, but the tale shifts with every telling. Walk the path again, and perhaps the sky will tilt just so, revealing a truth you missed before.", ["objectivesText"] = "Travel to the Shrouded Grove in Harandar to learn the history of Sky's Hope.", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 263467, 279525 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3370, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 238170, ["x"] = 0.542, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6209, ["name"] = "Legends of the Haranir", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2LabelIDs"] = { 4794 }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92728] = { ["id"] = 92728, ["name"] = "Dogged Disturbances", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 92728, 92729, 92868, 92869, 92870 }, ["description"] = "That dog! It ran through here and disrupted every lesson on the schedule. Now there are fire elementals everywhere and my students are ill-prepared to handle this mess. How am I supposed to teach in all of this chaos? You look capable--would you clear out some of these rowdy little elementals? The sooner we get this situation under control, the better!", ["objectivesText"] = "Kill 8 Rowdy Elementals in Thalassian University. Progress: Have you gotten those rowdy little sparks under control?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 253015, ["x"] = 0.354667, ["y"] = 0.576667 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 253015, ["x"] = 0.354667, ["y"] = 0.576667 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.354667, ["y"] = 0.576667 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 92729 }, ["questLines"] = { { ["id"] = 6030, ["name"] = "Scootin' Through Silvermoon", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[92729] = { ["id"] = 92729, ["name"] = "Hounded and Hassled", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 92728, 92729, 92868, 92869, 92870 }, ["description"] = "Gilneas and Kul Tiras are both known for their hunting hounds. With the resurgence of elfhounds in Silvermoon, I thought perhaps they could be similarly utilized. They're dogs, after all. How hard could training possibly be? Long story short, that dog made a mess and dashed off. I have to clean this up. Would you please find that creature and bring him back to me before the local canine cafe has my head? I only borrowed him for the day!", ["objectivesText"] = "Speak to Magistrix Zaedana in Thalassian University.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 252500, ["x"] = 0.356, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 253015, ["x"] = 0.354667, ["y"] = 0.576667 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 86735 }, ["questLines"] = { { ["id"] = 6030, ["name"] = "Scootin' Through Silvermoon", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[92731] = { ["id"] = 92731, ["name"] = "Artificing Aggression", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 92731 }, ["objectivesText"] = "Craft a blade with Decimus.", ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.516, ["y"] = 0.702, ["mapID"] = 2405 } }, ["ends"] = { { ["x"] = 0.516, ["y"] = 0.702, ["mapID"] = 2405 } }, ["coords"] = { ["mapID"] = 2405, ["x"] = 0.516, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16648 } }, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 248584, ["text"] = "Speak with Decimus to begin" }, { ["orderIndex"] = 1, ["type"] = 0, ["amount"] = 1, ["objectID"] = 208283, ["text"] = "Blade forged" } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[92732] = { ["id"] = 92732, ["name"] = "Light Disturbance", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92732, 92736, 92737, 92738, 92739 }, ["description"] = "We have had victories against the Lightbloom, but Alndust is rare. Until we can gather more, the Lightbloom continues its spread. Our forces are stretched too thin to watch their every movement. A scout spotted a strange corpse by the road to the east, along with a report of a general disturbance of the light-cursed creatures. I can't look into both at once. Could you find that corpse while I investigate deeper into the Encroaching Bloom?", ["objectivesText"] = "Go to the disturbance Hannan 's scout found.", ["rewardGold"] = 31500, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3370, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 241629, ["x"] = 0.317, ["y"] = 0.631 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 253087, ["x"] = 0.406, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.317, ["y"] = 0.631 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86898 }, ["questLines"] = { { ["id"] = 6032, ["name"] = "Spot Light", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92735] = { ["id"] = 92735, ["name"] = "Breadcrumb", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["storyline"] = { 92735 }, ["description"] = "I need to test some hypothesis but I can't do this alone.", ["objectivesText"] = "Go to the Stormfields.", ["rewardGold"] = 34100, ["rewardXP"] = 690, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[92736] = { ["id"] = 92736, ["name"] = "Light Stroll", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92732, 92736, 92737, 92738, 92739 }, ["description"] = "<These potatoad creatures are seldom seen near the Lightbloom. It is covered in spores and looks like it was trying to escape. You should search for more clues.>", ["objectivesText"] = "Search for clues.", ["rewardGold"] = 170800, ["rewardXP"] = 6085, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 253087, ["x"] = 0.406, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 253105, ["x"] = 0.395, ["y"] = 0.701 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 92732 }, ["questLines"] = { { ["id"] = 6032, ["name"] = "Spot Light", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92737] = { ["id"] = 92737, ["name"] = "Light Carnage", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92732, 92736, 92737, 92738, 92739 }, ["description"] = "The Lightbloom has infected many of these potatoads and spurred them into a frenzy. They spread the spores and reproduce at a dangerous rate. If we don't act, we will be overrun. Will you cull this heard while I search for the source of the corruption?", ["objectivesText"] = "Kill 12 Lightfrenzied Potatoads . Progress: We must protect Harandar 's natural species from this invasive growth.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 253105, ["x"] = 0.395, ["y"] = 0.701 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 253105, ["x"] = 0.395, ["y"] = 0.701 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.701 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 92736 }, ["questLines"] = { { ["id"] = 6032, ["name"] = "Spot Light", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92738] = { ["id"] = 92738, ["name"] = "Potatoad Tots", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92732, 92736, 92737, 92738, 92739 }, ["description"] = "It is too late for the adults, but the young may still be saved. If you can capture them, we can remove the spores before they take root. Gather up the spore covered potadpoles and bring them to me. I will take them to Har'alnor myself to purge this Lightbloom. Do not let their first breaths be their last. Please, <name>: save the babies.", ["objectivesText"] = "Collect 8 Lightspored Potadpoles and bring them to Hannan .", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 253105, ["x"] = 0.395, ["y"] = 0.701 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 253105, ["x"] = 0.395, ["y"] = 0.701 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.701 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 92736 }, ["questLines"] = { { ["id"] = 6032, ["name"] = "Spot Light", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92739] = { ["id"] = 92739, ["name"] = "O.K. Bloomer", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92732, 92736, 92737, 92738, 92739 }, ["description"] = "I have discovered the lair of a cunning creature I call Adzikel . With luck, this name will soon be forgotten. Adzikel sneaks into the potatoad nests to steal their young, and plants the Lightbloom spores to accelerate their growth into the frenzied toads, which spread more spores. For the little ones to have a chance, I must return to Har'alnor, but you have earned the right to slay this beast. Go with honor, and finish the hunt!", ["objectivesText"] = "Kill the creature spreading these spores.", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 260585 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3370, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 253105, ["x"] = 0.395, ["y"] = 0.701 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 241629, ["x"] = 0.317, ["y"] = 0.631 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.701 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 92737, 92738 }, ["questLines"] = { { ["id"] = 6032, ["name"] = "Spot Light", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92740] = { ["id"] = 92740, ["name"] = "Questionable Qualifications", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 92740 }, ["series"] = { 92715 }, ["description"] = "Well <class>, it's your lucky day. I just happen to have an extremely genuine Brawler's Guild Invitation right here in my stockpile. That said I'll need a moment to process the paperwork. That requires my complete concentration without your prying eyes on me. So do please give me a moment.", ["objectivesText"] = "Purchase an extremely genuine Brawler's Guild Invitation from Alton Philips . Progress: Here's your extremely genuine Brawler's Guild Invitation. Please note all sales are final. There will be no refunds, or receipts.", ["rewardItems"] = { 93227, 144363, 166805, 254690 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 252933, ["x"] = 0.735, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 252933, ["x"] = 0.735, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["sourceQuests"] = { 92715 } },
