[92816] = { ["id"] = 92816, ["name"] = "A Letter for Adventure", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["storyline"] = { 92816 }, ["description"] = "<You look down to see a rough looking letter with your name on it. Why not open it up to see what's inside?>", ["objectivesText"] = "Open the Adventuring Letter .", ["rewardGold"] = 27855, ["rewardXP"] = 175, ["rewardItems"] = { 254504 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["sourceQuests"] = { 94379 } },
[92821] = { ["id"] = 92821, ["name"] = "Ignite the Skies: Silvermoon", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["description"] = "The season of Midsummer is celebrated by many cultures across Azeroth. Even now, bonfires across the land are ignited in honor of the spirits of fire. To share our customs with all who dwell under the sun's warmth, I've had crates of sun blossoms brought to Silvermoon. Take to the skies and ignite the blossoms above, !", ["rewardGold"] = 341600, ["rewardItems"] = { 23247 }, ["starts"] = { { ["npcID"] = 266846, ["x"] = 0.484, ["y"] = 0.8, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 266846, ["x"] = 0.484, ["y"] = 0.8, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.484, ["y"] = 0.8, ["source"] = "quest_giver", ["mapID"] = 2393 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[92826] = { ["id"] = 92826, ["name"] = "Lorewalking: The Loa of Kings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["description"] = "Where to begin? There's so much to say! There's a great story from the Zandalari about the connection between troll and loa. Let's start there!", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 242386 }, ["starts"] = { { ["x"] = 0.642, ["y"] = 0.161, ["mapID"] = 84, ["npcID"] = 253727 } }, ["ends"] = { { ["npcID"] = 253727, ["x"] = 0.586, ["y"] = 0.708, ["mapID"] = 2393 } }, ["coords"] = { ["mapID"] = 84, ["x"] = 0.642, ["y"] = 0.161 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questGiverID"] = 253727, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6023, ["name"] = "Lorewalking: Loa", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 320, ["title"] = "Lorewalking: Loa", ["questLineID"] = 6023, ["questLineOrder"] = 0 } } },
[92829] = { ["id"] = 92829, ["name"] = "Lorewalking: Death of the Drakkari Loa", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["description"] = "The Drakkari of Zul'Drak are well known for massacring their loa. The prophets of the Drakkari loa decided to take the full power of the loa by force. The loa were blind-sided by this betrayal. They never dreamed rituals existed that could permanently kill them and steal their essence.", ["rewardGold"] = 1024800, ["rewardXP"] = 2125, ["rewardItems"] = { 242386 }, ["starts"] = { { ["npcID"] = 253727, ["x"] = 0.586, ["y"] = 0.708, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 253727, ["x"] = 0.586, ["y"] = 0.708, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.586, ["y"] = 0.708, ["source"] = "quest_giver", ["mapID"] = 2393 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6023, ["name"] = "Lorewalking: Loa", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 320, ["title"] = "Lorewalking: Loa", ["questLineID"] = 6023, ["questLineOrder"] = 0 } } },
[92831] = { ["id"] = 92831, ["name"] = "Lorewalking: The Blood Loa", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 13309, ["mapID"] = 1565, ["description"] = "Not every loa is a protector and companion to trolls. There are loa that eat their followers, like the blood loa, Hakkar. In trade for sacrifices, Hakkar grants dark blood powers to his followers. But he always takes more than he gives. Hakkar the Soulflayer has absorbed so much blood from his cultists that he's become almost a perpetual threat to the world.", ["rewardGold"] = 867900, ["rewardXP"] = 2125, ["starts"] = { { ["npcID"] = 253727, ["x"] = 0.586, ["y"] = 0.708, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 253727, ["x"] = 0.586, ["y"] = 0.708, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.586, ["y"] = 0.708, ["source"] = "quest_giver", ["mapID"] = 1565 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 13309 } }, ["questTurnInID"] = 253727, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6023, ["name"] = "Lorewalking: Loa", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 320, ["title"] = "Lorewalking: Loa", ["questLineID"] = 6023, ["questLineOrder"] = 0 } } },
[92832] = { ["id"] = 92832, ["name"] = "Lorewalking: The Hash'ey", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["description"] = "The last story I want to share is about the Darkspear trolls... and Mueh'zala. Mueh'zala is a mighty Loa of Death. Highly manipulative, he puts his plans into motion by using others as his pawns. He's used a hash'ey in the past. A hash'ey is a troll imbued with the full power of the loa.", ["rewardGold"] = 876300, ["rewardXP"] = 2125, ["rewardItems"] = { 242386, 275346 }, ["starts"] = { { ["npcID"] = 253727 } }, ["ends"] = { { ["npcID"] = 253727, ["x"] = 0.586, ["y"] = 0.708, ["mapID"] = 2393 } }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questGiverID"] = 253727, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6023, ["name"] = "Lorewalking: Loa", ["orderIndex"] = 21, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 320, ["title"] = "Lorewalking: Loa", ["questLineID"] = 6023, ["questLineOrder"] = 0 } } },
[92836] = { ["id"] = 92836, ["name"] = "Reignite the Skies: Stormwind", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 1519, ["mapID"] = 84, ["description"] = "Welcome to the Midsummer Festival of Fire, friend! Have you come to toss a few torches? Or maybe dance around the maypole? Ah, you must be here to ignite the blossom lights over the skies of Stormwind, aren't you? It is an old tradition, long forgotten but newly rekindled! Well, come on then, take to the skies and fly!", ["rewardGold"] = 312800, ["rewardItems"] = { 23247 }, ["starts"] = { { ["npcID"] = 252528, ["x"] = 0.48, ["y"] = 0.718, ["mapID"] = 84 } }, ["ends"] = { { ["npcID"] = 252528, ["x"] = 0.48, ["y"] = 0.718, ["mapID"] = 84 } }, ["coords"] = { ["x"] = 0.48, ["y"] = 0.718, ["source"] = "quest_giver", ["mapID"] = 84 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[92839] = { ["id"] = 92839, ["name"] = "Reignite the Skies: Orgrimmar", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 440, ["mapID"] = 71, ["description"] = "Midsummer is a time to reflect on the past and future. As old traditions fade, new traditions are born. One old tradition, practiced long ago, involved the offering of sun blossoms to An'she. As summer winds took them upwards, the blossoms would burn bright blue and orange. But faded traditions need not remain lost. Will you take to the skies to ignite the sun blossoms and help rekindle this old tradition?", ["rewardGold"] = 292100, ["rewardItems"] = { 23247 }, ["starts"] = { { ["npcID"] = 250811, ["x"] = 0.478, ["y"] = 0.374, ["mapID"] = 85 }, { ["npcID"] = 251986, ["x"] = 0.222, ["y"] = 0.192, ["mapID"] = 10 }, { ["npcID"] = 251986, ["x"] = 0.316, ["y"] = 0.636, ["mapID"] = 71 } }, ["ends"] = { { ["npcID"] = 250811, ["x"] = 0.478, ["y"] = 0.374, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.478, ["y"] = 0.374, ["source"] = "quest_giver", ["mapID"] = 71 }, ["mapCandidates"] = { ["npc"] = { 10, 71, 85 }, ["zone"] = { 440 } }, ["questType"] = "standard" },
[92845] = { ["id"] = 92845, ["name"] = "By Invitation Only?", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 2257, ["mapID"] = 84, ["storyline"] = { 92845 }, ["series"] = { 92851 }, ["description"] = "Fancy yourself a Brawlpub contender do you, <class>? They don't let just anyone in there, you know. Certainly not without an invitation. That said... just between you and me, if you know where to look and you've the means they say anyone can have their moment in the spotlight these days.", ["objectivesText"] = "Talk to Pick Butterworth near Bizmo's Brawlpub in the Deeprun Tram .", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 254690 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 253181, ["x"] = 0.664667, ["y"] = 0.716667 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 253181, ["x"] = 0.664667, ["y"] = 0.716667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.664667, ["y"] = 0.716667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 15969 } }, ["questTurnInID"] = 253181, ["questType"] = "standard", ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
