[92857] = { ["id"] = 92857, ["name"] = "Ta'readon's Mount Voucher", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 92857 }, ["description"] = "This token bears the seal of Overseer Ta'readon in Oribos . They would be interested in seeing this.", ["objectivesText"] = "Bring Ta'readon's Mount Voucher to Overseer Ta'readon in Oribos .", ["rewardItems"] = { 254694, 257511, 257513, 257514, 257516 }, ["rewardChoices"] = { 257511, 257514, 257516, 257513 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["startItems"] = { 254694 } },
[92864] = { ["id"] = 92864, ["name"] = "Drift Them Away", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92864, 92865, 92866 }, ["description"] = "With the hydras hunted out of the area, the drifter population in the cascades to the west is on the rise. Egg sacks are making the water murky and undrinkable, and the drifters are becoming very territorial. We must ensure that the reintroduction of the hydras will succeed. We need to cull the number of drifters and clear some of their egg sacks. You look like someone capable of doing this task. Will you help me?", ["objectivesText"] = "Slay 8 Cascade Drifters and remove 5 Drifter Egg Sacks from the cascades at Nordrassil Roots.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 253312, ["x"] = 0.695, ["y"] = 0.506 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 253312, ["x"] = 0.695, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86930 }, ["questLines"] = { { ["id"] = 6040, ["name"] = "Predator Reintroduction", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92865] = { ["id"] = 92865, ["name"] = "Feeding the Buds", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92864, 92865, 92866 }, ["description"] = "The orchid hydra's favorite food is the violet chloroceros--especially the buds on the bull's back. With the hydras gone for so long, the violet chloroceros grazed too much of the fauna. Soon, there will only be mud in that once lush and beautiful part of Harandar . I want to introduce my hydras to their primary source of food, and I would appreciate it if you could bring me four of those buds.", ["objectivesText"] = "Collect 4 Chloroceros Buds from the Violet Chloroceros, then feed them to the Hydra Budlings in Har'athir. Progress: The precious budlings will be very happy with their first taste of the chloroceros buds .", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 255577 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 253312, ["x"] = 0.695, ["y"] = 0.506 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 253312, ["x"] = 0.695, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86930 }, ["questLines"] = { { ["id"] = 6040, ["name"] = "Predator Reintroduction", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92866] = { ["id"] = 92866, ["name"] = "Re-Hydra-ted", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92864, 92865, 92866 }, ["description"] = "With the previous tasks done, it is time to reintroduce the budlings to the wilds. I have marked suitable locations to place the budlings. The little hydras will be an easy pick, so expect predators to attack you. I am sad to see them go. However, I know it is for the ecosystem's and their own good.", ["objectivesText"] = "Place the budlings in the marked areas. Progress: How are my budlings doing? Precious babies that they are.", ["rewardGold"] = 309800, ["rewardXP"] = 12170, ["rewardItems"] = { 260705 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3370, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 253312, ["x"] = 0.695, ["y"] = 0.506 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 253312, ["x"] = 0.695, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 92864, 92865 }, ["questLines"] = { { ["id"] = 6040, ["name"] = "Predator Reintroduction", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92868] = { ["id"] = 92868, ["name"] = "He Went Thataway", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 92728, 92729, 92868, 92869, 92870 }, ["series"] = { 92869, 92870 }, ["description"] = "You've been invaluable, <name>. As for that little menace, after he was done wreaking havoc here, I didn't really pay attention to where he went next. I'm sure you'll find him eventually. Let's hope you do before he wrecks half the city, hmm?", ["objectivesText"] = "Speak to Drathen in the Bazaar.", ["rewardGold"] = 31900, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 253015, ["x"] = 0.354667, ["y"] = 0.576667 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 253468, ["x"] = 0.448, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.354667, ["y"] = 0.576667 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 92728 }, ["questLines"] = { { ["id"] = 6030, ["name"] = "Scootin' Through Silvermoon", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[92869] = { ["id"] = 92869, ["name"] = "Fishy Dis-pondencies", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 92728, 92729, 92868, 92869, 92870 }, ["series"] = { 92868, 92870 }, ["description"] = "That dog tore right through the pond and sent half the sunwhiskers flying right out of the water! Quickly, get them back in the pond before they perish!", ["objectivesText"] = "Return 8 Coy Sunwhisker to the pond in the Bazaar. Progress: Hurry! They're terribly delicate creatures!", ["rewardGold"] = 170800, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3365, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 253468, ["x"] = 0.448, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 253468, ["x"] = 0.448, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 92868 }, ["questLines"] = { { ["id"] = 6030, ["name"] = "Scootin' Through Silvermoon", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[92870] = { ["id"] = 92870, ["name"] = "Scoot Along Now", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 92728, 92729, 92868, 92869, 92870 }, ["series"] = { 92868, 92869 }, ["description"] = "That dog! The last I saw he was tearing through the pond. I didn't see where he went, but he has to be nearby! His barks... they haunt me...", ["objectivesText"] = "Catch Lil' Scoots and return him to Ranger Telenus .", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 267456 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3365, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 253468, ["x"] = 0.448, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 252500, ["x"] = 0.356, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 92869 }, ["questLines"] = { { ["id"] = 6030, ["name"] = "Scootin' Through Silvermoon", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[92875] = { ["id"] = 92875, ["name"] = "Understanding the War Within", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 75918, 75919, 75920, 75921, 75922, 75923, 76276, 76280, 76281, 76282, 76283, 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326, 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 76342, 76343, 76344, 76345, 76347, 76348, 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76402, 76403, 76416, 76433, 76434, 76435, 76436, 76437, 76441, 76442, 76443, 76532, 77178, 77200, 77201, 77283, 77329, 77436, 77780, 77781, 77818, 78643, 78646, 78865, 92875 }, ["series"] = { 78643, 78865 }, ["description"] = "I fear your time in Valdrakken must come to an end. Dark forces gather to threaten other parts of Azeroth. We will do what we can to uncover Iridikron's schemes. You must learn more of what has unfolded.", ["objectivesText"] = "Consult the Tome of History within Valdrakken to learn about the War Within saga.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 248956, ["x"] = 0.641, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.583778, ["y"] = 0.357111 }, ["mapCandidates"] = { ["npc"] = { 84, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 78865 }, ["questLines"] = { { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 70, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[92882] = { ["id"] = 92882, ["name"] = "A Hunter's Plight", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92882, 92883, 92884, 92885 }, ["description"] = "I am desperate enough to ask an outsider for help. To join the Ka'dani, the elite hunters of Har'athir, you must complete a ritual under the guidance of an experienced Ka'dani. However, there are none left to guide me, so I cannot take the trial. But I have heard words of your actions. Maybe Akazi , the Ka'dani Elder, would let you stand as my guide. You may not know the ritual, but you know the hunt. Please, let us speak to Elder Akazi . We must try.", ["objectivesText"] = "Ketan wants you to talk to Elder Akazi about the Ka'dani trials. Progress: Ketan tells me that you wish to mentor him. Is this true?", ["rewardGold"] = 34100, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3370, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 253390, ["x"] = 0.694, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 253392, ["x"] = 0.704, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86930 }, ["questLines"] = { { ["id"] = 6039, ["name"] = "Hunter's Rite", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92883] = { ["id"] = 92883, ["name"] = "A Hunter's Duty", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92882, 92883, 92884, 92885 }, ["description"] = "At the start of the trial, the mentor and trainee gather materials to forge a hunting weapon. The weapon is more than an extension of the Ka'dani-- it's part of their being. There is no other weapon like it, as each is unique. You will help Ketan hunt and gather the materials and decorations, as well as a gift for the weaponsmith.", ["objectivesText"] = "Hunt down beasts around Har'athir and collect materials to forge a Ka'dani weapon. Progress: Were you able to get everything? I know some of the required materials can be hard to gather.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 255258, 255259, 255260, 255261 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 253392, ["x"] = 0.704, ["y"] = 0.506 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 253433, ["x"] = 0.7, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.704, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 92882 }, ["questLines"] = { { ["id"] = 6039, ["name"] = "Hunter's Rite", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92884] = { ["id"] = 92884, ["name"] = "A Hunter's Weapon", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92882, 92883, 92884, 92885 }, ["description"] = "Forging the Ka'dani weapon is a crucial moment in the trial. We will have to follow Al'yaat's instructions. Once Al'yaat forges the weapon, you will bring it to Elder Akazi . There will be a short ceremony where he will hand me the weapon. The ceremony concludes with the elder announcing our final task. I shouldn't let the excitement take the better of me, but one thing at a time. We must be patient and calculated as if we were on a hunt.", ["objectivesText"] = "Help Al'yaat forge the Ka'dani weapon, then deliver it to Elder Akazi . Progress: Forging a Ka'dani weapon is not an easy feat. A master craftsman must use the very best materials brought by the mentor and trainee.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 257717 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 253433, ["x"] = 0.7, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 253392, ["x"] = 0.704, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 92883 }, ["questLines"] = { { ["id"] = 6039, ["name"] = "Hunter's Rite", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92885] = { ["id"] = 92885, ["name"] = "A Hunter's Prey", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92882, 92883, 92884, 92885 }, ["description"] = "The last trial stands before you. Together, you have forged a weapon that will fell any beast, but the weapon is nothing without the hunter. Since you are not a Ka'dani, I present you with a difficult hunt. Ketan and you will hunt down and slay a prey known to all Har'athir hunters: the great Radooni . The beast ventured too close to Har'athir and should be a suitable hunt. Return to me once your hunt is complete and Radooni 's sap is on the spear.", ["objectivesText"] = "Hunt down the great Radooni , then return to Elder Akazi .", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 260472, 260473, 260474, 260476, 260477, 260478, 260479, 260481, 260482, 260483 }, ["rewardChoices"] = { 260472, 260473, 260474, 260476, 260477, 260478, 260479, 260481, 260482, 260483 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3370, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 253392, ["x"] = 0.704, ["y"] = 0.506 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 253392, ["x"] = 0.704, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.704, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 92884 }, ["questLines"] = { { ["id"] = 6039, ["name"] = "Hunter's Rite", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
[92890] = { ["id"] = 92890, ["name"] = "A Handful of Voidlight Marl", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 92890 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 500 } }, ["starts"] = { { ["npcID"] = 240407, ["x"] = 0.51, ["y"] = 0.508, ["mapID"] = 2413 } }, ["ends"] = { { ["npcID"] = 240407, ["x"] = 0.51, ["y"] = 0.508, ["mapID"] = 2413 } }, ["coords"] = { ["x"] = 0.51, ["y"] = 0.508, ["source"] = "quest_giver", ["mapID"] = 2413 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard" },
