[92895] = { ["id"] = 92895, ["name"] = "Hagar's Invitation", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15921, ["mapID"] = 2413, ["description"] = "Hagar has a message she believes the elves and trolls of Azeroth must all hear. She has sent a call to leaders from the elven and troll tribes to come to Harandar. I have come here to ask the blood elves to join us, but you should be there as well. You have been with us through so much of this. The Rootways from Silvermoon would be the fastest way.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["starts"] = { { ["npcID"] = 253640, ["x"] = 0.454, ["y"] = 0.7, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 253654, ["x"] = 0.442, ["y"] = 0.532, ["mapID"] = 2413 } }, ["coords"] = { ["x"] = 0.454, ["y"] = 0.7, ["source"] = "quest_giver", ["mapID"] = 2413 }, ["mapCandidates"] = { ["npc"] = { 2393, 2413 }, ["zone"] = { 15921 } }, ["questType"] = "standard", ["sourceQuests"] = { 92897 }, ["questLines"] = { { ["id"] = 6050, ["name"] = "Legacy of the Amani", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6050, ["questLineOrder"] = 0 } } },
[92897] = { ["id"] = 92897, ["name"] = "The Preparations Are Complete", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2393, ["description"] = ", I bear an important message from Hagar. You are invited to a special meeting in Harandar. Please meet me in Silvermoon to discuss it. Orweyna", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["ends"] = { { ["npcID"] = 253640, ["x"] = 0.454, ["y"] = 0.7, ["mapID"] = 2393 } }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["nextQuests"] = { 92895 }, ["questLines"] = { { ["id"] = 6050, ["name"] = "Legacy of the Amani", ["orderIndex"] = 1, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6050, ["questLineOrder"] = 0 } } },
[92899] = { ["id"] = 92899, ["name"] = "History Lesson", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15921, ["mapID"] = 2413, ["description"] = "Hagar requested that we invite to this meeting all of the troll and elven leaders we know. It was not easy to convince them to come. There are some... past grievances between these groups. Hagar hopes to overcome these divisions. As we wait for the others to arrive, feel free to speak to the other delegates. The wait is making them restless, so try not to inflame tensions.", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["rewardItems"] = { 246731 }, ["starts"] = { { ["npcID"] = 253654, ["mapID"] = 2576, ["x"] = 0.439313, ["y"] = 0.532025 }, { ["npcID"] = 253654, ["x"] = 0.442, ["y"] = 0.532, ["mapID"] = 2413 } }, ["ends"] = { { ["npcID"] = 253654, ["mapID"] = 2576, ["x"] = 0.439313, ["y"] = 0.532025 }, { ["npcID"] = 253651, ["x"] = 0.438, ["y"] = 0.512, ["mapID"] = 2413 } }, ["coords"] = { ["x"] = 0.442, ["y"] = 0.532, ["source"] = "quest_giver", ["mapID"] = 2413 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15921 } }, ["questType"] = "standard", ["sourceQuests"] = { 92895 }, ["questLines"] = { { ["id"] = 6050, ["name"] = "Legacy of the Amani", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6050, ["questLineOrder"] = 0 } } },
[92900] = { ["id"] = 92900, ["name"] = "A Favor for Kinduru", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["description"] = "Zul'jarra could not leave Zul'Aman as the Amani still recover. She sent Zul'jan in her stead. She hoped showing trust and giving him dis responsibility would bring him out of her shadow. Make use of his talents. But dis news... I am an old troll. I have a hard time reining Zul'jan in, but he may listen to you. Would you join us? Zul'jarra and I would be grateful if Zul'jan stayed out of trouble.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["starts"] = { { ["npcID"] = 253651, ["mapID"] = 2576, ["x"] = 0.43507, ["y"] = 0.511252 }, { ["npcID"] = 253651, ["x"] = 0.438, ["y"] = 0.512, ["mapID"] = 2413 } }, ["ends"] = { { ["npcID"] = 253651, ["mapID"] = 2576, ["x"] = 0.43507, ["y"] = 0.511252 }, { ["npcID"] = 253673, ["x"] = 0.388, ["y"] = 0.468, ["mapID"] = 2413 } }, ["coords"] = { ["x"] = 0.438, ["y"] = 0.512, ["source"] = "quest_giver", ["mapID"] = 2413 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 92899 }, ["questLines"] = { { ["id"] = 6050, ["name"] = "Legacy of the Amani", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6050, ["questLineOrder"] = 0 } } },
[92901] = { ["id"] = 92901, ["name"] = "Revisionist History", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["description"] = "Not all of the visions in this place were clear to us. Some of them were... strange. One in particular seemed to revolve around an unfamiliar people: a people that we learned are the Amani trolls. The magic used to create the painting, to pull the memories from the past, are tied to the haranir and those close to us. If there was no connection, the Zur'ashar--who create the paintings--could not have recalled troll history. I can show you and Zul'jan, and you can judge for yourselves.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["starts"] = { { ["npcID"] = 253675, ["x"] = 0.386, ["y"] = 0.468, ["mapID"] = 2413 } }, ["ends"] = { { ["npcID"] = 253675, ["mapID"] = 2413, ["x"] = 0.387343, ["y"] = 0.467627 }, { ["npcID"] = 255659, ["x"] = 0.348, ["y"] = 0.44, ["mapID"] = 2413 } }, ["coords"] = { ["x"] = 0.386, ["y"] = 0.468, ["source"] = "quest_giver", ["mapID"] = 2413 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 92900 }, ["questLines"] = { { ["id"] = 6050, ["name"] = "Legacy of the Amani", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6050, ["questLineOrder"] = 0 } } },
[92904] = { ["id"] = 92904, ["name"] = "Return to Zul'Aman", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16194, ["mapID"] = 2536, ["description"] = "I have heard de story since I was a child! De Amani were outnumbered and still dey fought on! Dey claimed victory through sheer will! Orweyna says de visions cannot lie. Uncle thinks details of de battle could have been lost. Dey would question everything it means to be Amani. Zul'jan scowls.> I must find de truth of dis. Uncle says if anyone would know, it would be de loa. De loa have said nothing of dis before, but we must start somewhere. It's time to go home.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["starts"] = { { ["npcID"] = 255660, ["x"] = 0.348, ["y"] = 0.44, ["mapID"] = 2413 } }, ["ends"] = { { ["npcID"] = 255660, ["mapID"] = 2413, ["x"] = 0.348931, ["y"] = 0.440455 }, { ["npcID"] = 253788, ["x"] = 0.164, ["y"] = 0.206, ["mapID"] = 2536 } }, ["coords"] = { ["x"] = 0.348, ["y"] = 0.44, ["source"] = "quest_giver", ["mapID"] = 2536 }, ["mapCandidates"] = { ["npc"] = { 2413, 2536 }, ["zone"] = { 16194 } }, ["questType"] = "standard", ["sourceQuests"] = { 92901 }, ["questLines"] = { { ["id"] = 6050, ["name"] = "Legacy of the Amani", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6050, ["questLineOrder"] = 0 } } },
[92907] = { ["id"] = 92907, ["name"] = "Amani Answers", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16194, ["mapID"] = 2536, ["description"] = "My uncle has already started communin' with de loa to find information on dis Ula'tek. Meanwhile, we gonna dig through his boxes to see what we can find. Zul'jan points to all the boxes scattered around the terrace.> My uncle has de biggest collection of histories among de Amani. I used to read through dem when I was a boy. Look for anything about Ula'tek, snakes, or early Amani history. I'll take these, you search de others.", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["starts"] = { { ["npcID"] = 253788, ["x"] = 0.164, ["y"] = 0.206, ["mapID"] = 2536 } }, ["ends"] = { { ["npcID"] = 256363, ["x"] = 0.17, ["y"] = 0.206, ["mapID"] = 2536 } }, ["coords"] = { ["x"] = 0.164, ["y"] = 0.206, ["source"] = "quest_giver", ["mapID"] = 2536 }, ["mapCandidates"] = { ["npc"] = { 2536 }, ["zone"] = { 16194 } }, ["questType"] = "standard", ["sourceQuests"] = { 92904 }, ["questLines"] = { { ["id"] = 6050, ["name"] = "Legacy of the Amani", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6050, ["questLineOrder"] = 0 } } },
[92916] = { ["id"] = 92916, ["name"] = "A Call for Aid", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16202, ["mapID"] = 2437, ["description"] = ", I call upon you to aid the Amani again as a fellow hash'ura. Another dire threat is upon them. Malacrass has returned. Witherbark Bluffs is under attack by a monstrous enemy the likes of which I have never seen. And with our brush against the Twilight's Blade, the timing could not be worse. Zul'jan deserted us and... we believe he may be at least partially at fault. We will deal with both of them in time. For now, help us before we are overrun.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["starts"] = { { ["npcID"] = 263331, ["x"] = 0.436, ["y"] = 0.682, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 253476, ["x"] = 0.37, ["y"] = 0.232, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.436, ["y"] = 0.682, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 93012, 98218 }, ["questLines"] = { { ["id"] = 6086, ["name"] = "The Missing Amani", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6229, ["name"] = "An Island of Fangs", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6086, ["questLineOrder"] = 0 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6229, ["questLineOrder"] = 1 } } },
[92917] = { ["id"] = 92917, ["name"] = "Saving Those Bound", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16202, ["mapID"] = 2437, ["description"] = "We fell back from the town gates. There were so many wounded and poisoned. Orweyna, Tak'lejo, and I best serve the Amani here. But you should be out there helping Zul'jarra . Malacrass's serpents are capturing Witherbark, coiling around them, and filling them with poison. Free them--and make sure to find Dak'zor . He was on the front line and first to fall.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["starts"] = { { ["npcID"] = 253476, ["x"] = 0.37, ["y"] = 0.232, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 255269, ["x"] = 0.374, ["y"] = 0.238, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.37, ["y"] = 0.232, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 92916 }, ["questLines"] = { { ["id"] = 6086, ["name"] = "The Missing Amani", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6229, ["name"] = "An Island of Fangs", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6086, ["questLineOrder"] = 0 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6229, ["questLineOrder"] = 1 } } },
[92919] = { ["id"] = 92919, ["name"] = "All Bark, All Bite", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16202, ["mapID"] = 2437, ["description"] = "The wounds I have seen... the ferocity. Not only do these serpents slither on the ground and coil around our warriors' bodies, but they cut deep with their poisoned blades and target them with their talons as they dive from the skies. Zul'jarra and her forces cannot win this on their own, but my hands are needed here. Help Zul'jarra by taking them down.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["starts"] = { { ["npcID"] = 253493, ["x"] = 0.37, ["y"] = 0.232, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 255269, ["x"] = 0.374, ["y"] = 0.238, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.37, ["y"] = 0.232, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 92916 }, ["questLines"] = { { ["id"] = 6086, ["name"] = "The Missing Amani", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 6229, ["name"] = "An Island of Fangs", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6086, ["questLineOrder"] = 0 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6229, ["questLineOrder"] = 1 } } },
[92920] = { ["id"] = 92920, ["name"] = "Down With the Skies", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16183, ["mapID"] = 2437, ["description"] = "I will need some time to call upon Akil'zon and open de way. Dat's where you come in. Protect me, my hash'ura. I entrust you with my life. We've taken great leaps before, eh?", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["rewardItems"] = { 278893, 278894, 278895, 278896 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3504, ["amount"] = 100 } }, ["starts"] = { { ["npcID"] = 258992, ["x"] = 0.5, ["y"] = 0.544, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 255327, ["x"] = 0.51, ["y"] = 0.544, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.5, ["y"] = 0.544, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 93263, 93266 }, ["questLines"] = { { ["id"] = 6086, ["name"] = "The Missing Amani", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 6229, ["name"] = "An Island of Fangs", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6086, ["questLineOrder"] = 0 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6229, ["questLineOrder"] = 1 } } },
[92921] = { ["id"] = 92921, ["name"] = "To the Skybridge", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16202, ["mapID"] = 2437, ["description"] = "Zul'jarra 's face is dark with rage as she looks off toward the Skybridge.> Zul'jan... you let dat snake Malacrass taint your mind and heart. For what? Power? De lightwood was one thing. But dis? I don't know what Malacrass has planned for de captives, but we have to take de fight to him and away from our people. Follow de monsters' path back to de Skybridge. I will consult de loa and meet you there. With their help, we will stop this.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["starts"] = { { ["npcID"] = 255282, ["x"] = 0.374, ["y"] = 0.238, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 257078, ["x"] = 0.44, ["y"] = 0.544, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.374, ["y"] = 0.238, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 93265 }, ["questLines"] = { { ["id"] = 6086, ["name"] = "The Missing Amani", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 6229, ["name"] = "An Island of Fangs", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6086, ["questLineOrder"] = 0 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6229, ["questLineOrder"] = 1 } } },
[92924] = { ["id"] = 92924, ["name"] = "What Lies Beyond the Fog", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16380, ["mapID"] = 2512, ["description"] = "With de loa, we are powerful. Without de loa, we are still the Amani. We will get our kin back. Liadrin will join us soon with reinforcements, and my warriors are eager to take vengeance. There can be no delay. For my people's sake and for Zul'jan's.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3504, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 255327, ["x"] = 0.51, ["y"] = 0.544, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 253528, ["x"] = 0.448, ["y"] = 0.278, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.51, ["y"] = 0.544, ["source"] = "quest_giver", ["zoneID"] = 15947 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 92920 }, ["questLines"] = { { ["id"] = 6086, ["name"] = "The Missing Amani", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 6229, ["name"] = "An Island of Fangs", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6086, ["questLineOrder"] = 0 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6229, ["questLineOrder"] = 1 } } },
[92925] = { ["id"] = 92925, ["name"] = "The Glint of History", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "The ruins across this island are ancient, built by the Amani long ago. If we discover how they came to be here, we may learn the truth of Ula'tek. Then we can show Zul'jan what he is really chasing. I have an idea of where to look for that crypt. Let us go together, .", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 253514, ["x"] = 0.574, ["y"] = 0.49, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 253514, ["x"] = 0.574, ["y"] = 0.49, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.574, ["y"] = 0.49, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93454 }, ["questLines"] = { { ["id"] = 6031, ["name"] = "Ghosts of the Past", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6230, ["name"] = "Ghosts of the Past", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6031, ["questLineOrder"] = 2 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6230, ["questLineOrder"] = 2 } } },
[92926] = { ["id"] = 92926, ["name"] = "Prey: Astalor's Initiative", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 92926, 92945, 93043, 93086 }, ["description"] = "Ah, <name>. I am glad to see you here in our city, even if the times are trying. We are once again beset on all sides by uncertain friends and dangerous foes, but I am not unprepared. I have a... guest, housed nearby. They may hold the key to our city's survival. Meet me near the harbor if you have the strength to do what must be done.", ["objectivesText"] = "Meet Astalor Bloodsworn near the harbor in Silvermoon.", ["rewardGold"] = 85400, ["rewardXP"] = 2940, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 246231, ["x"] = 0.565333, ["y"] = 0.654667 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 253513, ["x"] = 0.428, ["y"] = 0.104 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.565333, ["y"] = 0.654667 }, ["mapCandidates"] = { ["npc"] = { 2393, 2395 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 95114 }, ["questLines"] = { { ["id"] = 6035, ["name"] = "Prey", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[92927] = { ["id"] = 92927, ["name"] = "Echoed Steps", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "Sometimes the goddess' visions are not easy to understand at first, but in time she reveals her intentions. I will keep the Children of Ula'tek out of your path as you follow her memories. Trust that she will reveal what we need to learn. Meet me up ahead once you have witnessed her memories of the Amani.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 278905, 278906, 278907, 278908 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 253514, ["x"] = 0.574, ["y"] = 0.49, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 253514, ["x"] = 0.574, ["y"] = 0.49, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.574, ["y"] = 0.49, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 92925 }, ["questLines"] = { { ["id"] = 6031, ["name"] = "Ghosts of the Past", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 6230, ["name"] = "Ghosts of the Past", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6031, ["questLineOrder"] = 2 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6230, ["questLineOrder"] = 2 } } },
[92928] = { ["id"] = 92928, ["name"] = "What Was Buried", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "The visions of Nek'zali led us here. That we found where she took her last breath is no coincidence. There must be something within this crypt that the goddess wishes for us to see. Zul'jarra bid us to find the truth of Ula'tek. Perhaps here we will find the answers we seek. Let us see where the story we were told in the Den of Echoes ends, and where the truth begins.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 253514, ["x"] = 0.574, ["y"] = 0.49, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 255270, ["x"] = 0.446, ["y"] = 0.767, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.574, ["y"] = 0.49, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 92927 }, ["questLines"] = { { ["id"] = 6031, ["name"] = "Ghosts of the Past", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6230, ["name"] = "Ghosts of the Past", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6031, ["questLineOrder"] = 2 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6230, ["questLineOrder"] = 2 } } },
[92929] = { ["id"] = 92929, ["name"] = "Lurking in the Dark", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "Those who built this crypt would not have sealed it without good reason. A great evil from the past must dwell here. We should put to rest any spirits and undead we find. They cannot keep us from the answers we seek.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 278877, 278878, 278879, 278880 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 253514, ["x"] = 0.574, ["y"] = 0.49, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 255270, ["x"] = 0.446, ["y"] = 0.767, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.574, ["y"] = 0.49, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 92927 }, ["questLines"] = { { ["id"] = 6031, ["name"] = "Ghosts of the Past", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 6230, ["name"] = "Ghosts of the Past", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6031, ["questLineOrder"] = 2 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6230, ["questLineOrder"] = 2 } } },
[92930] = { ["id"] = 92930, ["name"] = "Written by the Victors", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "A version of this history is written into the Den of Echoes. The same events, only recorded by Amani hands instead of haranir ones. But something is missing: Nek'zali. How is she part of the story of Ula'tek? And we do not know how Ula'tek came to this world. We must go deeper into the crypt and witness the truth written on its walls.", ["rewardXP"] = 17110, ["rewardItems"] = { 279452 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3504, ["amount"] = 1500 } }, ["starts"] = { { ["npcID"] = 255270, ["x"] = 0.446, ["y"] = 0.767, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 253514, ["x"] = 0.574, ["y"] = 0.49, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.446, ["y"] = 0.767, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 92928, 92929 }, ["questLines"] = { { ["id"] = 6031, ["name"] = "Ghosts of the Past", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 6230, ["name"] = "Ghosts of the Past", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6031, ["questLineOrder"] = 2 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6230, ["questLineOrder"] = 2 } } },
[92931] = { ["id"] = 92931, ["name"] = "Delay the Venom", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "The wound from Zul'jan's blade. It won't heal. Zul'jan must have poisoned her. She's weakening, and I have not been successful in curing her with Light. Blast it! Whatever you found in that crypt can wait. The Amani are trying to find a cure. Ask Raz'taka if he's made any progress. If you need anything else, talk to Tak'lejo. Zul'jarra needs to focus on recovering.", ["rewardGold"] = 256200, ["rewardXP"] = 10270, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 253827, ["x"] = 0.574, ["y"] = 0.49, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 253514, ["x"] = 0.574, ["y"] = 0.49, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.574, ["y"] = 0.49, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 92930 }, ["questLines"] = { { ["id"] = 6089, ["name"] = "Original Sin", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6231, ["name"] = "Original Sin", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6089, ["questLineOrder"] = 3 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6231, ["questLineOrder"] = 3 } } },
[92932] = { ["id"] = 92932, ["name"] = "Clear the Swamp", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "Look in the distance. Restless, evil energy fills the sky. That structure ahead must have the answers we seek. The creatures that stand in our way must be culled. We cannot risk being overcome on such a vital mission.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 278901, 278902, 278903, 278904 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 253514, ["x"] = 0.574, ["y"] = 0.49, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 253514, ["x"] = 0.574, ["y"] = 0.49, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.574, ["y"] = 0.49, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 92931 }, ["questLines"] = { { ["id"] = 6089, ["name"] = "Original Sin", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6231, ["name"] = "Original Sin", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6089, ["questLineOrder"] = 3 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6231, ["questLineOrder"] = 3 } } },
[92933] = { ["id"] = 92933, ["name"] = "Haunted Shore", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "With Zul'jarra down, de Amani are losin' heart with each passin' moment. We gotta do somethin' to show dem that dis isn't over. Those tortollans have been helpin' where they can. Let's repay de favor and help out de captain. Seein' a bunch of their lost crew return to town oughta give dem some hope in dis cursed land.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 279285 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 253829, ["x"] = 0.674, ["y"] = 0.622, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 253829, ["x"] = 0.674, ["y"] = 0.622, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.674, ["y"] = 0.622, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 92931 }, ["questLines"] = { { ["id"] = 6089, ["name"] = "Original Sin", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 6231, ["name"] = "Original Sin", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6089, ["questLineOrder"] = 3 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6231, ["questLineOrder"] = 3 } } },
[92934] = { ["id"] = 92934, ["name"] = "Fuel the Calling", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "As you foretold, red rain falls from de sky. De heavens align. A great beast rouses at de door beneath de world. At last, a weapon for de Amani--one greater than any Zandalari loa. We just need de fuel to summon it. Most of de warband is injured and isolated. Fallen soldiers will welcome de sight of you, expecting you to heal dem. Take your dagger and do what must be done. Only you can save us, Nek'zali.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 254020, ["x"] = 0.692, ["y"] = 0.64, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 254020, ["x"] = 0.692, ["y"] = 0.64, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.692, ["y"] = 0.64, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93064 }, ["questLines"] = { { ["id"] = 6089, ["name"] = "Original Sin", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 6231, ["name"] = "Original Sin", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6089, ["questLineOrder"] = 3 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6231, ["questLineOrder"] = 3 } } },
[92935] = { ["id"] = 92935, ["name"] = "Pushed to the Brink", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "De ocean at our back slithers with tentacles and eyes, but we are safer there than on dis land. We were fools to think we could claim it from Kith'ix. I have stood by your new obsession with rituals and superstitions, Nek'zali. Now, I need you to be de healer you once were. Help my soldiers fight off de aqir. Buy us the time we need for de transport boats to arrive.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 253557, ["x"] = 0.692, ["y"] = 0.642, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 253557, ["x"] = 0.692, ["y"] = 0.642, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.692, ["y"] = 0.642, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93064 }, ["questLines"] = { { ["id"] = 6089, ["name"] = "Original Sin", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 6231, ["name"] = "Original Sin", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6089, ["questLineOrder"] = 3 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6231, ["questLineOrder"] = 3 } } },
[92936] = { ["id"] = 92936, ["name"] = "The Summoning of Ula'tek", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "Where is de rest of our warband?! De lines are breaking! My soldiers will hold dem off as long as dey can. De weak should run. But you and I... if we die, let it be together with weapons in hand, sister.", ["rewardGold"] = 256200, ["rewardXP"] = 10270, ["rewardItems"] = { 278885, 278886, 278887, 278888 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 253557, ["x"] = 0.692, ["y"] = 0.642, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 253829, ["x"] = 0.674, ["y"] = 0.622, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.692, ["y"] = 0.642, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 92934, 92935 }, ["questLines"] = { { ["id"] = 6089, ["name"] = "Original Sin", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 6231, ["name"] = "Original Sin", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6089, ["questLineOrder"] = 3 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6231, ["questLineOrder"] = 3 } } },
[92937] = { ["id"] = 92937, ["name"] = "Awakened Evil", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "Nek'zali, dat priestess... We should bring word of what we've seen back to de hash'ey. Orweyna . Ay! Wait--what's wrong with her?", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["rewardChoices"] = { 279243, 279244, 279245, 279280, 279281, 279282, 279283 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3504, ["amount"] = 1500 } }, ["starts"] = { { ["npcID"] = 253829, ["x"] = 0.674, ["y"] = 0.622, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 253827, ["x"] = 0.574, ["y"] = 0.49, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.674, ["y"] = 0.622, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 92936 }, ["questLines"] = { { ["id"] = 6089, ["name"] = "Original Sin", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 6231, ["name"] = "Original Sin", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6089, ["questLineOrder"] = 3 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6231, ["questLineOrder"] = 3 } } },
[92938] = { ["id"] = 92938, ["name"] = "Site of Terror", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "The air is thick with restless spirits. But there's more--it is the goddess. Where her voice was once quiet, I can feel it is now raised in anguish. Like a scream of terror. I fear for what we may find ahead. I will follow her voice. Come. Together, we uncover her memories of this place.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 253514, ["x"] = 0.574, ["y"] = 0.49, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 253514, ["x"] = 0.574, ["y"] = 0.49, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.574, ["y"] = 0.49, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 92932, 92933 }, ["questLines"] = { { ["id"] = 6089, ["name"] = "Original Sin", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6231, ["name"] = "Original Sin", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6089, ["questLineOrder"] = 3 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6231, ["questLineOrder"] = 3 } } },
[92939] = { ["id"] = 92939, ["name"] = "It's Not Just a Rock!", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 92939, 92944, 92946, 92948 }, ["description"] = "$p, I have something strange, here. While scouting in the Storm Fields, I found this rock a beast was chewing. Look at it! Could these be runes? Writing? But so ancient? Here? What could it mean? Strangely, I think I've been hearing a voice in my head since I found this thing... We must investigate further. Maybe we can find more of this rubble in the bellies of those beasts?", ["objectivesText"] = "Collect 6 Ancient Rubble from monsters in the Storm Fields. Progress: Why are these beasts even eating these rocks?", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 260363 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 253038, ["x"] = 0.386, ["y"] = 0.580333 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 253038, ["x"] = 0.386, ["y"] = 0.580333 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.580333 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86565 }, ["questLines"] = { { ["id"] = 6017, ["name"] = "Secrets in the Dark", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[92944] = { ["id"] = 92944, ["name"] = "Sifting Through Void", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 92939, 92944, 92946, 92948 }, ["description"] = "There's no rubble on the surface. The beasts are burrowing, so they must be finding it in a cavern underground. I've been thinking of how to get there. You've noticed the vortexes that dot the Storm Fields? They twist space, moving things from place to place. Step through one and I can reveal the anomalous residue that surrounds them. Collect the residue and I can make a spell to redirect the portal to where the source of the rubble is!", ["objectivesText"] = "Jump in the Stellar Vortexes in the Storm Fields and collect 10 Anomalous Residue. Progress: I had some suspicion about these runes not being domanaar or ethereal. The specter all but confirms my thoughts. This could be something different. Maybe even a civilization!", ["rewardGold"] = 341600, ["rewardXP"] = 6425, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 253038, ["x"] = 0.386, ["y"] = 0.580333 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 253038, ["x"] = 0.386, ["y"] = 0.580333 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.580333 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 92939 }, ["questLines"] = { { ["id"] = 6017, ["name"] = "Secrets in the Dark", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[92945] = { ["id"] = 92945, ["name"] = "The Power of Anguish", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 92926, 92945, 93043, 93086 }, ["description"] = "These threats we chase are intelligent. Determined. Deadly. Their ingenuity will seek to confound you. Their strength will seek to destroy you. It is from their very will to live--to predate--that we will extract the essence required to fuel the magical defenses of our city. I have had my assistants lay out our friend's toys. You'd do best to familiarize yourself with them.", ["objectivesText"] = "Learn how to hunt your prey. Progress: Speak with Astalor Bloodsworn to continue.", ["rewardGold"] = 85400, ["rewardXP"] = 2940, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 253513, ["x"] = 0.428, ["y"] = 0.104 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 253513, ["x"] = 0.428, ["y"] = 0.104 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.104 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 92926 }, ["questLines"] = { { ["id"] = 6035, ["name"] = "Prey", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395, ["db2QuestInfoID"] = 282, ["db2QuestInfoName"] = "Important Quest" },
[92946] = { ["id"] = 92946, ["name"] = "Buried in the Dark", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 92939, 92944, 92946, 92948 }, ["description"] = "We're at the brink of a monumental discovery! Hurry, there's no time to even call for backup. We must find this strange spirit! With this residue, I can make a spell to adjust the vortex. It'll lead us to the source of this engraved rubble. Based on the specter's guidance, I believe we'll find an entire cave. Be ready, $p.", ["objectivesText"] = "Jump into the northernmost Stellar Vortex in the Storm Fields and investigate the cave beyond. Progress: What more could we learn?", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 253038, ["x"] = 0.386, ["y"] = 0.580333 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 253038, ["x"] = 0.386, ["y"] = 0.580333 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.580333 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 92944 }, ["questLines"] = { { ["id"] = 6017, ["name"] = "Secrets in the Dark", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[92948] = { ["id"] = 92948, ["name"] = "In Over My Head", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 92939, 92944, 92946, 92948 }, ["description"] = "Akintunde created a weapon to end all intelligent life on this world, eons and eons ago? I hardly believe it. But truth or lie, we can't leave this spirit be. He's clearly dangerous. If he truly knows how to create such a weapon, we can't let him contact anyone from Azeroth. We both know a few warmongers who would do anything for that kind of power... I think I can realign the vortex again to take us directly to Akintunde. Ready yourself for a fight, $p.", ["objectivesText"] = "Step into the Northernmost Stellar Vortex in the Stormfields to confront Akitunde the Unstoppable. Progress: I sensed no remorse at all from him. How could that be?", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardItems"] = { 264403, 264404, 264405, 264406 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3389, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 253038, ["x"] = 0.386, ["y"] = 0.580333 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 253038, ["x"] = 0.386, ["y"] = 0.580333 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.580333 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 92946 }, ["questLines"] = { { ["id"] = 6017, ["name"] = "Secrets in the Dark", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[92951] = { ["id"] = 92951, ["name"] = "Digging Deeper", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["description"] = "De mask says we are lookin' for de scrolls of Malacrass. While we are in Maisara, try to find any scrolls de Vilebranch have left around. Maisara is a dangerous place, so don't bother sortin' through dem--just grab 'em and we can check later. Even if dey don't mention Ula'tek, we might find information about their plans or intentions against de Amani.", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["starts"] = { { ["npcID"] = 253806, ["x"] = 0.444, ["y"] = 0.366, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 253806, ["mapID"] = 2437, ["x"] = 0.444558, ["y"] = 0.366446 }, { ["npcID"] = 253804, ["x"] = 0.444, ["y"] = 0.366, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.444, ["y"] = 0.366, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 92952 }, ["questLines"] = { { ["id"] = 6050, ["name"] = "Legacy of the Amani", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6050, ["questLineOrder"] = 0 } } },
[92952] = { ["id"] = 92952, ["name"] = "Mission to Maisara", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["description"] = "De magic helped, but... not enough. I still don't remember my name or past life. Dat knowledge may be lost forever... I do remember more about Ula'tek--or rather, where we might find more information! I was forced into dis form by de Vilebranch trolls. Dey kept dark knowledge secret from de other tribes, includin' knowledge of Ula'tek. If we are to know more, we must go to de Maisara Deeps.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["starts"] = { { ["npcID"] = 253833, ["x"] = 0.39, ["y"] = 0.388, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 253833, ["mapID"] = 2437, ["x"] = 0.389875, ["y"] = 0.389089 }, { ["npcID"] = 253805, ["x"] = 0.444, ["y"] = 0.366, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.39, ["y"] = 0.388, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 92957, 92958 }, ["questLines"] = { { ["id"] = 6050, ["name"] = "Legacy of the Amani", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6050, ["questLineOrder"] = 0 } } },
[92953] = { ["id"] = 92953, ["name"] = "Memories of Malacrass", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["description"] = "While I was a servant of de Vilebranch, I remember discussions about Malacrass's research into Ula'tek. Malacrass recorded his knowledge in scrolls that he kept with him. Now that he's dead, we need to find out what happened to dem. De Vilebranch hex masters won't talk willingly... but if you slay dem, I can use their own necromantic magic against dem to compel dem to speak.", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["starts"] = { { ["npcID"] = 253805, ["x"] = 0.444, ["y"] = 0.366, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 253805, ["mapID"] = 2437, ["x"] = 0.445177, ["y"] = 0.367207 }, { ["npcID"] = 253804, ["x"] = 0.444, ["y"] = 0.366, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.444, ["y"] = 0.366, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 92952 }, ["questLines"] = { { ["id"] = 6050, ["name"] = "Legacy of the Amani", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6050, ["questLineOrder"] = 0 } } },
[92954] = { ["id"] = 92954, ["name"] = "Maisara Caverns: Master of Souls", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16395, ["mapID"] = 2112, ["description"] = "Malacrass's notes are with Vordaza, and she's using them to further her necromantic experiments. I need you to go into de Maisara Caverns to recover them. It will be dangerous, and you will need to gather allies before venturing in. I will stay here and protect my uncle. We need to sort through all de scrolls we gathered and see what else we can find out.", ["rewardGold"] = 1366400, ["rewardXP"] = 23530, ["starts"] = { { ["npcID"] = 253806, ["x"] = 0.444, ["y"] = 0.366, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 253806, ["x"] = 0.444, ["y"] = 0.366, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.444, ["y"] = 0.366, ["source"] = "quest_giver", ["mapID"] = 2112 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 16395 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 92951, 92953 }, ["questLines"] = { { ["id"] = 6050, ["name"] = "Legacy of the Amani", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6050, ["questLineOrder"] = 0 } } },
[92955] = { ["id"] = 92955, ["name"] = "The Tablets of Numazon", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["description"] = "De ancestors did not bow to a loa--dey claimed a weapon! A weapon dat led to our victory. I must know more. You said de tablets at Numazon are de oldest in Zul'Aman. We can continue de search there. Perhaps de ancient Amani left behind clues for us. Uncle says we should bring de mask. A stray memory might be de key to unlocking dis mystery.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["starts"] = { { ["npcID"] = 256363, ["x"] = 0.17, ["y"] = 0.206, ["mapID"] = 2536 } }, ["ends"] = { { ["npcID"] = 256363, ["mapID"] = 2536, ["x"] = 0.168706, ["y"] = 0.20725 }, { ["npcID"] = 253834, ["x"] = 0.39, ["y"] = 0.388, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.17, ["y"] = 0.206, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437, 2536 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 92907 }, ["questLines"] = { { ["id"] = 6050, ["name"] = "Legacy of the Amani", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6050, ["questLineOrder"] = 0 } } },
[92957] = { ["id"] = 92957, ["name"] = "There's the Rub", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["description"] = "If de tablets were made when de Amani first arrived in Zul'Aman, den there must be some clue about Ula'tek here. De tablets are too heavy to carry, so Uncle suggested dat we take rubbings of de inscriptions. I scouted ahead and gathered a few, but I ran into de Vilebranch. I came back here to make sure Uncle was safe. Enter Numazon and collect more of de rubbings while I watch over Uncle. Watch out for de Vilebranch.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["starts"] = { { ["npcID"] = 253834, ["x"] = 0.39, ["y"] = 0.388, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 253834, ["mapID"] = 2437, ["x"] = 0.390006, ["y"] = 0.388386 }, { ["npcID"] = 253832, ["x"] = 0.39, ["y"] = 0.388, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.39, ["y"] = 0.388, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 92955 }, ["questLines"] = { { ["id"] = 6050, ["name"] = "Legacy of the Amani", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6050, ["questLineOrder"] = 0 } } },
[92958] = { ["id"] = 92958, ["name"] = "Brain Drain", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["description"] = "I wish I could be more help but... de gaps in my memory. Due to de damage de mask has sustained, dat magic has leaked out for who knows how long. You repaired de physical parts of de mask, but de magic within is still weak. Zul'jan says Vilebranch trolls occupy this crypt. De magic dat binds me together is like de magic they use. You might be able to help. Retrieve their hex fetishes--I should be able to drain the magic from them.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["starts"] = { { ["npcID"] = 253833, ["x"] = 0.39, ["y"] = 0.388, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 253833, ["x"] = 0.39, ["y"] = 0.388, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.39, ["y"] = 0.388, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 92955 }, ["questLines"] = { { ["id"] = 6050, ["name"] = "Legacy of the Amani", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6050, ["questLineOrder"] = 0 } } },
[92961] = { ["id"] = 92961, ["name"] = "Decor Treasure Hunt", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16105, ["mapID"] = 2352, ["storyline"] = { 92961 }, ["description"] = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle: Sentinel of stone. First to greet each new neighbor. Seek out the deep shade. Good luck!", ["objectivesText"] = "Solve the riddle and find the treasure.", ["rewardGold"] = 170800, ["rewardItems"] = { 235523, 235675, 235677, 235994, 236654, 236655, 236666, 236676, 236677, 236678, 239075, 241617, 241618, 241620, 241621, 242951, 243334, 243495, 244169, 244531, 244532, 244533, 244534, 244780, 244782, 245266, 245334, 245336, 245355, 245356, 245372, 245375, 245376, 245384, 245398, 245532, 245533, 245545, 245546, 245547, 245548, 245555, 245556, 245575, 245576, 245578, 245581, 245583, 245649, 245662, 245680, 246036, 246101, 246102, 246103, 246104, 246106, 246107, 246217, 246218, 246224, 246241, 246243, 246245, 246246, 246249, 246250, 246253, 246254, 246255, 246258, 246259, 246260, 246261, 246502, 246587, 246614, 246687, 246742, 246868, 246869, 246880, 246882, 246883, 247221, 248246, 248760, 250920, 251973, 251981, 253181, 253441, 253479, 253490, 253493, 253589, 255650, 257690, 257691, 257692 }, ["starts"] = { { ["mapID"] = 2352, ["npcID"] = 248854, ["x"] = 0.526, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 2352, ["npcID"] = 248854, ["x"] = 0.526, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 2352, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 2352 }, ["zone"] = { 16105 } }, ["questTurnInID"] = 248854, ["questType"] = "standard" },
