[93009] = { ["id"] = 93009, ["name"] = "Decor Treasure Hunt", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16105, ["mapID"] = 2352, ["storyline"] = { 93009 }, ["description"] = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle: Seek the smallest house. Where pawsteps mark the sand. Now dig where dogs lie. Good luck!", ["objectivesText"] = "Solve the riddle and find the treasure.", ["rewardGold"] = 170800, ["rewardItems"] = { 235523, 235675, 235677, 235994, 236654, 236655, 236666, 236676, 236677, 236678, 239075, 241617, 241618, 241620, 241621, 242951, 243334, 243495, 244169, 244531, 244532, 244533, 244534, 244780, 244782, 245266, 245334, 245336, 245355, 245356, 245372, 245375, 245376, 245384, 245398, 245532, 245533, 245545, 245546, 245547, 245548, 245555, 245556, 245575, 245576, 245578, 245581, 245583, 245649, 245662, 245680, 246036, 246101, 246102, 246103, 246104, 246106, 246107, 246217, 246218, 246224, 246241, 246243, 246245, 246246, 246249, 246250, 246253, 246254, 246255, 246258, 246259, 246260, 246261, 246502, 246587, 246614, 246687, 246742, 246868, 246869, 246880, 246882, 246883, 247221, 248246, 248760, 250920, 251973, 251981, 253181, 253441, 253479, 253490, 253493, 253589, 255650, 257690, 257691, 257692 }, ["starts"] = { { ["mapID"] = 2352, ["npcID"] = 248854, ["x"] = 0.526, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 2352, ["npcID"] = 248854, ["x"] = 0.526, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 2352, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 2352 }, ["zone"] = { 16105 } }, ["questTurnInID"] = 248854, ["questType"] = "standard" },
[93010] = { ["id"] = 93010, ["name"] = "The Serpent Shrine", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16194, ["mapID"] = 2536, ["description"] = "Here! De note says Ula'tek was sealed away by de Amani. To break de seal, one needs a \"key.\" Zul'jan flips through the notes.> De key was hidden within a shrine and protected with ancient magic. But which shrine... Zul'jan looks up.> Didn't de tablets at Numazon mention a shrine bein' \"dedicated to de serpent's victory?\" We know from de visions in Harandar dat Ula'tek was a serpent. Dat must be it! De key is hidden at de serpent shrine in Atal'Aman!", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["starts"] = { { ["npcID"] = 253806, ["x"] = 0.444, ["y"] = 0.366, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 253806, ["mapID"] = 2437, ["x"] = 0.444558, ["y"] = 0.366446 }, { ["npcID"] = 253840, ["x"] = 0.676, ["y"] = 0.472, ["mapID"] = 2536 } }, ["coords"] = { ["x"] = 0.444, ["y"] = 0.366, ["source"] = "quest_giver", ["mapID"] = 2536 }, ["mapCandidates"] = { ["npc"] = { 2437, 2536 }, ["zone"] = { 16194 } }, ["questType"] = "standard", ["sourceQuests"] = { 92954 }, ["questLines"] = { { ["id"] = 6050, ["name"] = "Legacy of the Amani", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6050, ["questLineOrder"] = 0 } } },
[93011] = { ["id"] = 93011, ["name"] = "Legacy of the Amani", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["description"] = "If Malacrass was right, de key to Ula'tek should be right here. Zul'jan 's heavy hammer thumps onto the shrine for emphasis.> It may take me some time to break through de stone to find it. I don't know what kind of protection de ancestors have in place, but you will have to deal with dem while I work. I admit, I did not believe de visions in Harandar. I don't fully trust Malacrass's notes either. But if de key is here, dat would be undeniable proof dat what we are chasing is real.", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["starts"] = { { ["npcID"] = 253840, ["x"] = 0.676, ["y"] = 0.472, ["mapID"] = 2536 } }, ["ends"] = { { ["npcID"] = 253840, ["mapID"] = 2536, ["x"] = 0.677769, ["y"] = 0.472427 }, { ["npcID"] = 259778, ["x"] = 0.444, ["y"] = 0.666, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.676, ["y"] = 0.472, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437, 2536 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 93010 }, ["questLines"] = { { ["id"] = 6050, ["name"] = "Legacy of the Amani", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6050, ["questLineOrder"] = 0 } } },
[93012] = { ["id"] = 93012, ["name"] = "Dead End", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["description"] = "After the meeting in Harandar, I came here to speak with Zul'jarra about the vision you witnessed. Zul'jan had seemed upset when you left and it was not my intent to make him so. But all of that can wait. Now that you're awake, you should go speak to Zul'jarra . She wants to know what happened at Atal'Aman.", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["rewardItems"] = { 268557 }, ["starts"] = { { ["npcID"] = 259778, ["x"] = 0.444, ["y"] = 0.666, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 259778, ["mapID"] = 2437, ["x"] = 0.443501, ["y"] = 0.666536 }, { ["npcID"] = 253848, ["x"] = 0.438, ["y"] = 0.684, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.444, ["y"] = 0.666, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 93011 }, ["questLines"] = { { ["id"] = 6050, ["name"] = "Legacy of the Amani", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6050, ["questLineOrder"] = 0 } } },
[93013] = { ["id"] = 93013, ["name"] = "Special Assignment: Push Back the Light", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 93013 }, ["objectivesText"] = "Ride the Haranir Petalwing Lightbloom rutaani defeated", ["rewardXP"] = 13690, ["starts"] = { { ["x"] = 0.327, ["y"] = 0.774, ["mapID"] = 2413 } }, ["ends"] = { { ["x"] = 0.327, ["y"] = 0.774, ["mapID"] = 2413 } }, ["coords"] = { ["mapID"] = 2413, ["x"] = 0.327, ["y"] = 0.774 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15355 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 241799, ["text"] = "Ride the Haranir Petalwing" }, { ["orderIndex"] = 1, ["type"] = 15, ["amount"] = 1, ["objectID"] = 0, ["text"] = "Lightbloom rutaani defeated" }, { ["orderIndex"] = 2, ["type"] = 0, ["amount"] = 25, ["objectID"] = 240959 }, { ["orderIndex"] = 3, ["type"] = 0, ["amount"] = 15, ["objectID"] = 240957 }, { ["orderIndex"] = 4, ["type"] = 0, ["amount"] = 10, ["objectID"] = 240956 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413, ["db2QuestInfoID"] = 286, ["db2QuestInfoName"] = "Capstone World Quest" },
[93018] = { ["id"] = 93018, ["name"] = "Them That Were Lost", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "My brother is here. And so are de captives. Dey are bein' held in de small shrines ahead. For what, I don't know. But somehow my brother is involved. Gettin' my people free of dis place is of de highest priority. Do whatever is necessary to free dem. Zul'jan can wait until de prisoners are safe.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 253528, ["x"] = 0.448, ["y"] = 0.278, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 253528, ["x"] = 0.448, ["y"] = 0.278, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.448, ["y"] = 0.278, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93019, 95564 }, ["questLines"] = { { ["id"] = 6087, ["name"] = "An Island of Fangs", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 6229, ["name"] = "An Island of Fangs", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6087, ["questLineOrder"] = 1 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6229, ["questLineOrder"] = 1 } } },
[93019] = { ["id"] = 93019, ["name"] = "Situation Normal, All Snaked Up", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "Zul'jarra 's hand tightens on her axe.> We knew de island was cursed, but is dis de curse? Or has what Zul'jan and Malacrass done brought dem here? De answer doesn't matter. We must find and save de ones dey kidnapped--and find my brother. Zul'jarra surveys the island stretching out around her. Her eyes narrow.> I see somethin' ahead. A structure. I'm gonna see if my people are there. You protect de people here. Crush de serpents. Grind dem into de ground. Meet me when you are done.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 278897, 278898, 278899, 278900 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 253528, ["x"] = 0.448, ["y"] = 0.278, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 253528, ["x"] = 0.448, ["y"] = 0.278, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.448, ["y"] = 0.278, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 95804 }, ["questLines"] = { { ["id"] = 6087, ["name"] = "An Island of Fangs", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6229, ["name"] = "An Island of Fangs", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6087, ["questLineOrder"] = 1 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6229, ["questLineOrder"] = 1 } } },
[93022] = { ["id"] = 93022, ["name"] = "Fire, the Only Way to Be Sure", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "De prisoners need to be rescued, yes, but dis place is an abomination. We must cleanse it with de spirit-born fire of Jan'alai. Take dis totem. It will allow you to wield de breath of our loa. Purge their nests. And kill de spiteful broodsisters that laid dem!", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 280377 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 259218, ["x"] = 0.578, ["y"] = 0.472, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 259218, ["x"] = 0.578, ["y"] = 0.472, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.578, ["y"] = 0.472, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93019, 95564 }, ["questLines"] = { { ["id"] = 6087, ["name"] = "An Island of Fangs", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 6229, ["name"] = "An Island of Fangs", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6087, ["questLineOrder"] = 1 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6229, ["questLineOrder"] = 1 } } },
[93023] = { ["id"] = 93023, ["name"] = "Death of Furies", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "Now only these creatures block our way to... Zul'jarra growls softly.> ...to Zul'jan. Dey are protectin' him like he's one of dem. One of their army. Whether he is or not, we gotta take dem down if we're gonna find out.", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["rewardChoices"] = { 279194, 279195, 279196 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3504, ["amount"] = 100 } }, ["starts"] = { { ["npcID"] = 253528, ["x"] = 0.448, ["y"] = 0.278, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 253528, ["x"] = 0.448, ["y"] = 0.278, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.448, ["y"] = 0.278, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93018, 93022 }, ["questLines"] = { { ["id"] = 6087, ["name"] = "An Island of Fangs", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 6229, ["name"] = "An Island of Fangs", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6087, ["questLineOrder"] = 1 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6229, ["questLineOrder"] = 1 } } },
[93024] = { ["id"] = 93024, ["name"] = "Come With Me", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "Stay here, hash'ura. I'm goin' in to talk to him. Maybe I can talk him into leavin' on his own--and tellin' us what Malacrass has planned. I hope to de loa that he will come to his senses.", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3504, ["amount"] = 1500 } }, ["starts"] = { { ["npcID"] = 253528, ["x"] = 0.448, ["y"] = 0.278, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 258860, ["x"] = 0.582, ["y"] = 0.454, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.448, ["y"] = 0.278, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93023 }, ["questLines"] = { { ["id"] = 6087, ["name"] = "An Island of Fangs", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 6229, ["name"] = "An Island of Fangs", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6087, ["questLineOrder"] = 1 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6229, ["questLineOrder"] = 1 } } },
[93043] = { ["id"] = 93043, ["name"] = "When Predator Becomes Prey", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 92926, 92945, 93043, 93086 }, ["description"] = "Such a strong will to survive, even when trapped in a cage. Do not underestimate your prey, $p. They can strike at any time. Our friend here will be more than willing to demonstrate, I am sure...", ["objectivesText"] = "Survive an ambush by your prey. Progress: Speak with Astalor Bloodsworn to continue.", ["rewardGold"] = 85400, ["rewardXP"] = 2940, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 253513, ["x"] = 0.428, ["y"] = 0.104 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 253513, ["x"] = 0.428, ["y"] = 0.104 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.104 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 92945 }, ["questLines"] = { { ["id"] = 6035, ["name"] = "Prey", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
