[93047] = { ["id"] = 93047, ["name"] = "Butchery Basics", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 93047, 93048, 93049, 93050, 93051 }, ["description"] = "We can't keep up with how much these soldiers eat. Lend us just a bit of your time to feed dis army, hm? We need boar. Not just a steak or two, we need de entire boar. Nothin' goes to waste, yah?", ["objectivesText"] = "Collect 10 Boar Carcasses . Progress: De art of Amani huntin' is about discipline. You practice until de skills come as naturally as breathin'. But right now, discipline means doin' what I tell you.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 258890 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 241072, ["x"] = 0.455, ["y"] = 0.694 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 241072, ["x"] = 0.455, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86652 }, ["questLines"] = { { ["id"] = 6044, ["name"] = "Beyond the Walls", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[93048] = { ["id"] = 93048, ["name"] = "Got No Rhythm", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 93047, 93048, 93049, 93050, 93051 }, ["description"] = "Dat boy Kovu stormed out of here without even tryin' a single step. He thinks he's got two left feet, but he isn't even willin' to try. You look like an impressive fighter. He'll respect you for dat. Maybe he just needs de right dance partner to show him de steps. Help him out, hm?", ["objectivesText"] = "Teach Kovu how to dance. Progress: Makin' progress, yah?", ["rewardGold"] = 170800, ["rewardXP"] = 6085, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 254142, ["x"] = 0.468, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 254142, ["x"] = 0.468, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86652 }, ["questLines"] = { { ["id"] = 6044, ["name"] = "Beyond the Walls", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[93049] = { ["id"] = 93049, ["name"] = "Homework Support", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 93047, 93048, 93049, 93050, 93051 }, ["description"] = "<The little girl keeps her voice low, making sure her father doesn't overhear.> My friends are goin' out to play down where de shade lilies grow, but I'm supposed to do a buncha borin' apothecary stuff. Papa wants me to collect some plants to make salves and balms we use for healin'. I asked if it could wait and he said no. What if... you helped me out? Just dis once, pleeease?", ["objectivesText"] = "Collect 15 Pristine Shade Lilies and 8 Dragonhawk Fern Fronds . Progress: Did you get all of dem?", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 258891, 258892 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 254144, ["x"] = 0.465, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 254144, ["x"] = 0.465, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86652 }, ["questLines"] = { { ["id"] = 6044, ["name"] = "Beyond the Walls", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[93050] = { ["id"] = 93050, ["name"] = "Altar History", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 93047, 93048, 93049, 93050, 93051 }, ["description"] = "De altars need to be infused with de power of de loas every so often. I'm not as spry as I used to be and de altars are all spread out. Help an old shaman out, eh? I'll give you my totem to channel de loas' power into de altars. And maybe you can learn a thing or two from de other acolytes and myself in de process.", ["objectivesText"] = "Empower the 4 Loa Altars. Progress: I just need to take a little breather here. Don't go worryin' about me, now. Keep focused on the task at hand, eh?", ["rewardGold"] = 170800, ["rewardXP"] = 6085, ["rewardItems"] = { 267005 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 254146, ["x"] = 0.434, ["y"] = 0.688 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 257797, ["x"] = 0.434, ["y"] = 0.688 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91062 }, ["questLines"] = { { ["id"] = 6044, ["name"] = "Beyond the Walls", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[93051] = { ["id"] = 93051, ["name"] = "The Final Exam", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 93047, 93048, 93049, 93050, 93051 }, ["description"] = "My trainin' is almost complete! My commander says I need to prove myself against a strong fighter before she can recommend me for combat. But I've been strugglin' to find someone willin' to spar with me after... uh, after what happened de last time... You look capable. And intimidatin'. Mind helpin' me out here? And no goin' easy on me, yes? I can take it.", ["objectivesText"] = "Spar Dar'rak for his final exam. Progress: Do not pull even a single punch. De boy must succeed or fail on his own. If he's not ready, you will be doin' him no favors sendin' him into the fray unprepared.", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3354, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 255406, ["x"] = 0.432, ["y"] = 0.67 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 255907, ["x"] = 0.438, ["y"] = 0.646 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.67 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86652 }, ["questLines"] = { { ["id"] = 6044, ["name"] = "Beyond the Walls", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[93053] = { ["id"] = 93053, ["name"] = "Cleaning the Den", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 93053 }, ["objectivesText"] = "Dried Acorn removed", ["rewardXP"] = 13690, ["starts"] = { { ["x"] = 0.478, ["y"] = 0.516, ["mapID"] = 2576 } }, ["ends"] = { { ["x"] = 0.478, ["y"] = 0.516, ["mapID"] = 2576 } }, ["coords"] = { ["mapID"] = 2576, ["x"] = 0.478, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15355 } }, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 3, ["amount"] = 8, ["objectID"] = 253825, ["text"] = "Dried Acorn removed" } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[93055] = { ["id"] = 93055, ["name"] = "Extracurriculars", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 7502, ["mapID"] = 619, ["storyline"] = { 93055 }, ["description"] = "$p, how fares your journey through this timeline? Should you wish to explore history further, Khadgar and Eternus may be able to show you more quests that the champions of Azeroth previously experienced.", ["objectivesText"] = "Speak with Khadgar in Dalaran and Eternus at the Infinite Bazaar. Progress: Back so soon? Perhaps I miscalculated how long you would spend procrastinating.", ["rewardGold"] = 34100, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 619, ["npcID"] = 243853, ["x"] = 0.456, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 619, ["npcID"] = 243853, ["x"] = 0.456, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 619, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 619 }, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[93056] = { ["id"] = 93056, ["name"] = "A Lesson in Alacrity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 7502, ["mapID"] = 619, ["storyline"] = { 93056 }, ["description"] = "You are exceeding expectations, $p. Even still, let us not tarry. I will teach you what I know so that we may expedite your journey. However, all good things come with time. You are not yet ready for my strongest blessings.", ["objectivesText"] = "Reach level 70.", ["rewardGold"] = 29200, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 619, ["npcID"] = 243853, ["x"] = 0.456, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 619, ["npcID"] = 243853, ["x"] = 0.456, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 619, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 619 }, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[93057] = { ["id"] = 93057, ["name"] = "A House For You", ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 11, ["mapID"] = 2351, ["storyline"] = { 91863, 91968, 91969, 93057 }, ["series"] = { 91863, 93647 }, ["description"] = "Greetings, ! Have you ever wanted to own a home? Have a place to call your own? Now you can! Join us in Founder's Point, the new Housing Neighborhood. Get your very own slice of Azeroth!", ["objectivesText"] = "Travel to your capital city's portal room to find a portal to a neighborhood. You can also travel to a housing neighborhood from the housing Dashboard.", ["rewardGold"] = 34100, ["rewardXP"] = 4115, ["rewardItems"] = { 81485, 81486, 81487, 81488, 81489, 81490, 81491, 81492, 81493, 81742, 81743, 81744, 81745, 81746, 81747, 81748, 81749, 81750, 112524, 112525, 112526, 112527, 119001, 230936, 236954 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["nextQuests"] = { 91863 }, ["questLines"] = { { ["id"] = 6000, ["name"] = "House Purchase Tutorial", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2735, ["db2PoiUiMapID"] = 2352 },
[93063] = { ["id"] = 93063, ["name"] = "Broken Spears", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "De spirits, their weapons--I recognize dem! Dey are Amani: heroes and warriors from our murals and stories! Dis was de site of a great battle--one dat earned us de right to call dis land Zul'Aman. We should bring evidence of our history back to the others watchin' Zul'jarra, to remind 'em we got our ancestors watchin' over us. Takin' de raised spirits' weapons may \"raise some spirits\" back at camp, no?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardChoices"] = { 279231, 279232, 279233, 279234, 279235, 279236, 279237, 279238 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 253829, ["x"] = 0.674, ["y"] = 0.622, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 253829, ["x"] = 0.674, ["y"] = 0.622, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.674, ["y"] = 0.622, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 92932, 92933 }, ["questLines"] = { { ["id"] = 6089, ["name"] = "Original Sin", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 6231, ["name"] = "Original Sin", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6089, ["questLineOrder"] = 3 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6231, ["questLineOrder"] = 3 } } },
[93064] = { ["id"] = 93064, ["name"] = "Awe of She", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "It's the priestess again--the one whose remains we found in the crypt. These memories--no. Not memories. They are like nightmares. Something horrible befell the goddess. We must see it directly. Hear her song through all the noise. I fear this vision will be too much for me alone. Join me, both of you, and let us witness the goddess' past terror.", ["rewardGold"] = 85400, ["rewardXP"] = 3420, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 253514, ["x"] = 0.574, ["y"] = 0.49, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 253557, ["x"] = 0.692, ["y"] = 0.642, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.574, ["y"] = 0.49, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 92938, 93063 }, ["questLines"] = { { ["id"] = 6089, ["name"] = "Original Sin", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 6231, ["name"] = "Original Sin", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6089, ["questLineOrder"] = 3 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6231, ["questLineOrder"] = 3 } } },
