[93093] = { ["id"] = 93093, ["name"] = "Gnarldin Trophies", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 93093, 93094, 93095, 93096 }, ["description"] = "I was sent here to prove dat I am ready to be an Amani warrior. All dat want de honor must prove demselves. I chose de gnarldin since dey are close now, and I heard Zul'jarra softened dem up a little. Looks like I wasn't de only one who thought dat and was wrong. But I still need to collect as many trophies from de gnarldin as possible. If I have de bigshot hash'ura helpin' me, there's no way I can lose, no? You get de trophies. I will stay behind to watch our backs.", ["objectivesText"] = "Recover 35 trophies from gnarldin and their allies. Progress: Did you get de trophies? De gnarldin have plenty of dem from all their fightin'.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 256672 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 253997, ["x"] = 0.289, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 253997, ["x"] = 0.289, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.289, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86652 }, ["questLines"] = { { ["id"] = 6042, ["name"] = "Bitter Honor", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[93094] = { ["id"] = 93094, ["name"] = "Scavenged Victory", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 93093, 93094, 93095, 93096 }, ["description"] = "Many warriors have chosen to face de gnarldin since dey came to Zul'Aman , but many have failed. Dey thought now dat de gnarldin are in our territory and weakened, dey would be easier... De gnarldin hunters have collected tablets from de Amani hunters dat fell here. But with you at my side, we can get \"vengeance\" for those dat lost their lives here--no killin' or life riskin' required. We don't have to kill de gnarldin. We just have to get close enough to gather de tablets. What do you say?", ["objectivesText"] = "Recover 6 Hunter's Tablets from fallen Amani. Progress: With those tablets, no one can question our strength!", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 256685 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 253997, ["x"] = 0.289, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 253997, ["x"] = 0.289, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.289, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86652 }, ["questLines"] = { { ["id"] = 6042, ["name"] = "Bitter Honor", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[93095] = { ["id"] = 93095, ["name"] = "Bitter Fury", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 93093, 93094, 93095, 93096 }, ["description"] = "De leader of de gnarldin here is known as Tusk Taker . Take a wild guess why she's named dat. There is a trophy dis one has in a cave. Take it, and she will run out rarin' for a fight. Defeat her for me, and no one can challenge my right to be an Amani warrior.", ["objectivesText"] = "Steal Tusk Taker's Taken Tusk Trophy to lure her out, then defeat her. Progress: Did you kill Tusk Taker yet?", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3354, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 253997, ["x"] = 0.289, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 253997, ["x"] = 0.289, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.289, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 93093, 93094 }, ["questLines"] = { { ["id"] = 6042, ["name"] = "Bitter Honor", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[93096] = { ["id"] = 93096, ["name"] = "Amani Honor", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 93093, 93094, 93095, 93096 }, ["description"] = "Dat is all de trophies we need. I'll take dem to de meetin' point nearby. All we gotta do is wait there for Huntmaster Jinki to show up. Come!", ["objectivesText"] = "Meet Kel'vujo at the meeting point to receive your reward from Huntmaster Jinki .", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 264460, 264461, 264462, 264463, 264464, 264465, 264466, 264467, 269980 }, ["rewardChoices"] = { 264460, 264461, 264462, 264463, 264464, 264465, 264466, 264467, 269980 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3354, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 253997, ["x"] = 0.289, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 253998, ["x"] = 0.442, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.289, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 93095 }, ["questLines"] = { { ["id"] = 6042, ["name"] = "Bitter Honor", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
