[93171] = { ["id"] = 93171, ["name"] = "Calling All Combatants!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93171 }, ["description"] = "<You read a nearby advertisement...> Run, don't walk! The Artisan's Consortium has teamed up with local Silvermoon artisans in Falconwing Square to offer a new selection of heraldries and crafted equipment. These are certified for use in arenas and battlegrounds, guaranteed! Head on down and look for Mirvedon to receive your free sample today. Act now while supplies last! Terms and conditions apply. -Aisha", ["objectivesText"] = "Follow up on the advertisement with Mirvedon at Falconwing Square in Silvermoon City .", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["rewardItems"] = { 256608, 257194 }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 243225, ["x"] = 0.34, ["y"] = 0.812 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.812 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["startItems"] = { 257194 } },
[93178] = { ["id"] = 93178, ["name"] = "A Quiet Walk Interrupted", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 93178, 93179, 93180, 93181, 93182 }, ["description"] = "It is de hash'ura! De favored of our wily loa! Maybe you can help... My father, Oban, is ill and I have been givin' him all my attention. When I turned my back an hour ago, my daughter, Kanza, had run off! I searched de village, but I can't go further and leave my father behind. Please, find where she went? She can be on her own, but she's a sensitive girl, and I don't want her goin' far. Dat fool boy Haz'kel wouldn't come down, but he may have seen her leave. Ask him first.", ["objectivesText"] = "Help Nerunda find Kanza's whereabouts in Zul'Aman . Progress: I'm so worried about Kanza! She shouldn't be on her own.", ["rewardGold"] = 170800, ["rewardXP"] = 6085, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 254716, ["x"] = 0.366, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 254716, ["x"] = 0.366, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86735 }, ["questLines"] = { { ["id"] = 6055, ["name"] = "The Sound of Her Voice", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[93179] = { ["id"] = 93179, ["name"] = "Childlike Devotion", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 93178, 93179, 93180, 93181, 93182 }, ["description"] = "She's goin' to Filo's shrine. She's too old for dat. She's almost thirteen--an adult. Filo is de Loa of Childhood and protects children. Parents pray to Filo for healthy children. It is even said if a child dies, Filo waits with a child in de afterlife until their parents claim dem. Dat is superstition, but dat's why she's goin'. We lost her twin, Janaka. She must think she's with Filo. The way to Filo's shrine is dangerous, and dat loa won't speak to her. Do what you can to bring her home!", ["objectivesText"] = "Find Kanza at the Shrine of Filo. Progress: < Kanza eyes you uncertainly.>", ["rewardGold"] = 170800, ["rewardXP"] = 6085, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 254716, ["x"] = 0.366, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 254719, ["x"] = 0.515, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 93178 }, ["questLines"] = { { ["id"] = 6055, ["name"] = "The Sound of Her Voice", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[93180] = { ["id"] = 93180, ["name"] = "Shrine Preparations", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 93178, 93179, 93180, 93181, 93182 }, ["description"] = "< Kanza makes no sound but briefly meets your gaze. She points off toward the hot spring pools. Maybe she wants you to do something there?>", ["objectivesText"] = "Follow Kanza and help her by killing 4 Stinger Matriarchs , 6 Stinger Hatchlings , and by collecting 20 Thorncaps . Progress: < Kanza shifts her weight from foot to foot, swaying impatiently.>", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 265341 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 254719, ["x"] = 0.515, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 258014, ["x"] = 0.514, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 93179 }, ["questLines"] = { { ["id"] = 6055, ["name"] = "The Sound of Her Voice", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[93181] = { ["id"] = 93181, ["name"] = "Temple and a Teapot", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 93178, 93179, 93180, 93181, 93182 }, ["description"] = "< Kanza is dancing with excitement. She holds her small hand with one finger up. One last thing to do. You must almost be ready for the ritual to summon Filo--if that is indeed what she is asking for your help to do. She fishes in her tunic for something and presents an object to you: the broken handle of a teapot, presumably from the one she dropped on the way here. Perhaps she needs a substitute?>", ["objectivesText"] = "Buy a teapot from a vendor in nearby Camp Stonewash and help Kanza start the ritual. Progress: < Kanza looks nervous and expectant.>", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 265401 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 258014, ["x"] = 0.514, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 258363, ["x"] = 0.522, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 93180 }, ["questLines"] = { { ["id"] = 6055, ["name"] = "The Sound of Her Voice", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[93182] = { ["id"] = 93182, ["name"] = "Healing Homeward", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 93178, 93179, 93180, 93181, 93182 }, ["description"] = "I will go home.", ["objectivesText"] = "Return to Nerunda in Witherbark Bluffs and check if Kanza returned home.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3354, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 258363, ["x"] = 0.522, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 258569, ["x"] = 0.366, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 93181 }, ["questLines"] = { { ["id"] = 6055, ["name"] = "The Sound of Her Voice", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[93199] = { ["id"] = 93199, ["name"] = "Slithering in the Mire", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "De Children of Ula'tek overwhelmed de swamp and its inhabitants. Dey kill anything in their path, just to increase their numbers and expand their holdings. Do what you can to reduce their numbers. Keep dem distracted and occupied. I'll sneak ahead and look for Wa'kani and de other scouts.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 254372, ["x"] = 0.63, ["y"] = 0.444, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 254376, ["x"] = 0.66, ["y"] = 0.39, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.63, ["y"] = 0.444, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93449 }, ["questLines"] = { { ["id"] = 6118, ["name"] = "The Troubles of Mlurkkr Mire", ["orderIndex"] = 1, ["flags"] = 0 } } },
[93200] = { ["id"] = 93200, ["name"] = "A Handful of Voidlight Marl", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 93200 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 500 } }, ["starts"] = { { ["npcID"] = 240838, ["x"] = 0.434, ["y"] = 0.474, ["mapID"] = 2395 } }, ["ends"] = { { ["npcID"] = 240838, ["x"] = 0.434, ["y"] = 0.474, ["mapID"] = 2395 } }, ["coords"] = { ["x"] = 0.434, ["y"] = 0.474, ["source"] = "quest_giver", ["mapID"] = 2395 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard" },
[93229] = { ["id"] = 93229, ["name"] = "Fried Eggs", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "De snakes are focused on two things: killin' and reproducin'. Dey took over dis part of de swamp, leaving nothing livin' in their path and layin' eggs all over de place! Burn any of de eggs you come across. Careful, though. You get too close, dey can burst open, and you don't wanna be anywhere near dem when dat happens.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 254372, ["x"] = 0.63, ["y"] = 0.444, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 254376, ["x"] = 0.66, ["y"] = 0.39, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.63, ["y"] = 0.444, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93449 }, ["questLines"] = { { ["id"] = 6118, ["name"] = "The Troubles of Mlurkkr Mire", ["orderIndex"] = 2, ["flags"] = 0 } } },
[93233] = { ["id"] = 93233, ["name"] = "Savagery Among the Ruins", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "De murlocs entrenched demselves in these old ruins. Dey are usually a tough, but cowardly sort. Dis batch is different. Probably gone mad--don't know why, don't care. Clear de ruins while you search. Don't slay their young, though. Dey don't seem to be affected by whatever got de others.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 254376, ["x"] = 0.66, ["y"] = 0.39, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 254431, ["x"] = 0.688, ["y"] = 0.372, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.66, ["y"] = 0.39, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 94447 }, ["questLines"] = { { ["id"] = 6118, ["name"] = "The Troubles of Mlurkkr Mire", ["orderIndex"] = 5, ["flags"] = 0 } } },
[93239] = { ["id"] = 93239, ["name"] = "Scouts in the Swamp", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "I looked around some more while you were rescuin' Wa'kani. I think de other scouts were taken by de murlocs. We'll have to search further into de ruins. I'll circle 'round and see if I can find anything. You're better than me in a fight, so you can search where I can't. Locate de scouts and meet me near de docks.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 254376, ["x"] = 0.66, ["y"] = 0.39, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 254431, ["x"] = 0.688, ["y"] = 0.372, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.66, ["y"] = 0.39, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 94447 }, ["questLines"] = { { ["id"] = 6118, ["name"] = "The Troubles of Mlurkkr Mire", ["orderIndex"] = 7, ["flags"] = 0 } } },
[93244] = { ["id"] = 93244, ["name"] = "Special Assignment: Agents of the Shield", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15458, ["mapID"] = 2405, ["storyline"] = { 93244 }, ["description"] = "WQ", ["objectivesText"] = "Smash Arathi Supply crates and recover Airship Tools.", ["rewardXP"] = 11765, ["rewardItems"] = { 263510 }, ["starts"] = { { ["x"] = 0.409, ["y"] = 0.863, ["mapID"] = 2405 } }, ["ends"] = { { ["x"] = 0.409, ["y"] = 0.863, ["mapID"] = 2405 } }, ["coords"] = { ["mapID"] = 2405, ["x"] = 0.409, ["y"] = 0.863 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15458 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 1, ["amount"] = 1, ["objectID"] = 263510, ["text"] = "Slay ethereals for an Overflow Diverter" }, { ["orderIndex"] = 1, ["type"] = 0, ["amount"] = 1, ["objectID"] = 256951, ["text"] = "Amalgam's power rerouted" }, { ["orderIndex"] = 2, ["type"] = 0, ["amount"] = 1, ["objectID"] = 256950, ["text"] = "Unbound's power rerouted" }, { ["orderIndex"] = 3, ["type"] = 0, ["amount"] = 1, ["objectID"] = 256949, ["text"] = "Dweller's power rerouted" }, { ["orderIndex"] = 4, ["type"] = 0, ["amount"] = 1, ["objectID"] = 256945, ["text"] = "Surge's power rerouted" } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405, ["db2QuestInfoID"] = 286, ["db2QuestInfoName"] = "Capstone World Quest" },
[93257] = { ["id"] = 93257, ["name"] = "Revantusk at Risk", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 93257, 93258, 93259, 93260, 93261 }, ["description"] = "Fishers of de forest tribes constantly talk to each other about our hauls, and none are more legendary than de river-walking Revantusk and their crabs! But... I've heard they've fallen on hard times. First, de Twilight's Blade ransacked their city. Now, their cages aren't bringing in enough meat for de refugees. De Revantusk have a new head river-walker, Kahanea , who could use an extra set of hands in taking care of dis crab problem. You up to de task, outsider?", ["objectivesText"] = "Find Kahanea in Nalorakk's Prowl.", ["rewardGold"] = 34100, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3354, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 254488, ["x"] = 0.458, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 254491, ["x"] = 0.351333, ["y"] = 0.806667 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86652 }, ["questLines"] = { { ["id"] = 6045, ["name"] = "River-Walkers of the Prowl", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[93258] = { ["id"] = 93258, ["name"] = "Crab Clues", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 93257, 93258, 93259, 93260, 93261 }, ["description"] = "De rumors are true. No matter what we try, we aren't netting as many crabs as before. And de ones we do catch taste wrong, even making some of my people sick! I succeeded my mother's position as head river-walker after losing her to de Twilight's Blade. Dealing with dis famine, my new duties, and my grief... It's so much for me to bear. Dis is de area where we first noticed an issue with our crabs. Can you investigate for me while I make more traps?", ["objectivesText"] = "Investigate the lakeshore for causes of the food shortage. Progress: I must make dis right--for my people. For my mother. I wish she could give us guidance.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 254491, ["x"] = 0.351333, ["y"] = 0.806667 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 254491, ["x"] = 0.351333, ["y"] = 0.806667 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.351333, ["y"] = 0.806667 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 93257 }, ["questLines"] = { { ["id"] = 6045, ["name"] = "River-Walkers of the Prowl", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[93259] = { ["id"] = 93259, ["name"] = "Clobbering Crawlers", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 93257, 93258, 93259, 93260, 93261 }, ["description"] = "While I continue to scout de area for causes of dis famine, please harvest crab meat for our refugees. Their hunger only gets worse as our investigation goes on. Since de traps aren't working, you have to hunt those crabs yourself and get food straight from de source! Make sure you're getting healthy meat, though. I'm worried about some of those crabs being infected with de Void.", ["objectivesText"] = "Harvest 10 pieces of Mouthwatering Crab Meat from the crabs upriver. Progress: My people have been through so much. Everyone deserves a warm home to return to, and a hearty meal to restore their strength and spirit.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 259471 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 254491, ["x"] = 0.351333, ["y"] = 0.806667 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 254491, ["x"] = 0.351333, ["y"] = 0.806667 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.351333, ["y"] = 0.806667 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 93258 }, ["questLines"] = { { ["id"] = 6045, ["name"] = "River-Walkers of the Prowl", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[93260] = { ["id"] = 93260, ["name"] = "Caging Crawlers", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 93257, 93258, 93259, 93260, 93261 }, ["description"] = "Our traps being mucked up with de Void would explain why we've been catching fewer crabs! And why some of de crabs have made our people sick. Please clean our traps upriver! Based on Nak'tek's report, de infected crabs sound dangerous... so be careful approaching those traps. You can find de baskets nestled among de sticks or by bases of waterfalls--dey provide a natural disguise! Crabs are easily tricked dat way.", ["objectivesText"] = "Clean 6 Crab Traps upriver. Progress: Were you able to clean any of de traps? Or find a source of de filth gumming them up?", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 264166 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 254491, ["x"] = 0.351333, ["y"] = 0.806667 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 254491, ["x"] = 0.351333, ["y"] = 0.806667 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.351333, ["y"] = 0.806667 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 93258 }, ["questLines"] = { { ["id"] = 6045, ["name"] = "River-Walkers of the Prowl", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[93261] = { ["id"] = 93261, ["name"] = "A Crab of Unusual Size", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 93257, 93258, 93259, 93260, 93261 }, ["description"] = "I followed de Void pollution trail upriver and spotted a beast before it ran off to its cave: an enormous, void-addled crab. It was shedding those shards dat were polluting de river! As long as dis beast lives, it'll keep spreading pollution and infecting crabs with de Void. It must be stopped! I'd stay and fight, but I must warn everyone at de Overlook. Please, <name>. Slay dat crab and remove de source of its corruption before it can hurt more of my people!", ["objectivesText"] = "Defeat the Mania-Crab and remove the source of its corruption. Progress: I don't know if de Twilight's Blade created dat beast or not, but it needs to GO!", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 260410, 263278, 263279, 263280, 263281 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3354, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 254491, ["x"] = 0.351333, ["y"] = 0.806667 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 254491, ["x"] = 0.351333, ["y"] = 0.806667 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.351333, ["y"] = 0.806667 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 93259, 93260 }, ["questLines"] = { { ["id"] = 6045, ["name"] = "River-Walkers of the Prowl", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[93263] = { ["id"] = 93263, ["name"] = "It Just Had to Be...", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16380, ["mapID"] = 2437, ["description"] = "Malacrass called these creatures the Children of Ula'tek. Then it is so. My vision led Zul'jan to Ula'tek and from Ula'tek to Malacrass. Together, they must seek her. I will do whatever is in my power to help, and make this right for Zul'jarra and her people. Let us kill as many of these monsters as we can. We will fight side by side and uproot this shared foe.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 255758, ["x"] = 0.44, ["y"] = 0.544, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 258992, ["x"] = 0.5, ["y"] = 0.544, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.44, ["y"] = 0.544, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 92921 }, ["questLines"] = { { ["id"] = 6086, ["name"] = "The Missing Amani", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 6229, ["name"] = "An Island of Fangs", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6086, ["questLineOrder"] = 0 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6229, ["questLineOrder"] = 1 } } },
[93265] = { ["id"] = 93265, ["name"] = "Severing the Serpent's Head", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16202, ["mapID"] = 2437, ["description"] = "Zul'jarra is covered in sweat, blood, and venom. Her face is grim in a way you haven't seen before.> I need your help. I ordered soldiers to move to a hut in de north as a lookout and to protect some Witherbark civilians trapped there. But one of de monster brutes caught their scent. Kill it and rescue de civilians before dey end up like Dak'zor! I will stay here and make sure none of these snakes get into de lodge.", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["rewardItems"] = { 278881, 278882, 278883, 278884 }, ["starts"] = { { ["npcID"] = 255269, ["x"] = 0.374, ["y"] = 0.238, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 255282, ["x"] = 0.374, ["y"] = 0.238, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.374, ["y"] = 0.238, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 92917, 92919 }, ["questLines"] = { { ["id"] = 6086, ["name"] = "The Missing Amani", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6229, ["name"] = "An Island of Fangs", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6086, ["questLineOrder"] = 0 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6229, ["questLineOrder"] = 1 } } },
[93266] = { ["id"] = 93266, ["name"] = "Drumming Up the Troops", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16380, ["mapID"] = 2437, ["description"] = "De loa have blessed our battle! Nalorakk and Halazzi are rippin' at their flanks. Akil'zon and Jan'alai are knockin' dem from de skies. We will stay to de ground and push through de center--all of us--and rid Zul'Aman of these pests. Sound de drums again, hash'ura. Call our warriors to de battle in Atal'Aman. Now we are united and dey will heed us!", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 257078, ["x"] = 0.44, ["y"] = 0.544, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 258992, ["x"] = 0.5, ["y"] = 0.544, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.44, ["y"] = 0.544, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 92921 }, ["questLines"] = { { ["id"] = 6086, ["name"] = "The Missing Amani", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 6229, ["name"] = "An Island of Fangs", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6086, ["questLineOrder"] = 0 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6229, ["questLineOrder"] = 1 } } },
