[93382] = { ["id"] = 93382, ["name"] = "Pardon the Interruption", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16432, ["mapID"] = 2451, ["storyline"] = { 92028, 93382 }, ["description"] = "<name>! Glad to see you. The defenders in the fortress could use your help. One of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on. She needs the help of someone who can properly disrupt the robot's attacks so it can be repaired. Do you have a moment to help?", ["objectivesText"] = "Activate Fightbot 11.2.7, then interrupt its abilities with your Felguard or Felhunter 3 times. Progress: Some help! Hopefully you can find a way to interrupt this bot's abilities.", ["rewardGold"] = 29200, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2451, ["npcID"] = 249423, ["x"] = 0.194667, ["y"] = 0.574667 } }, ["ends"] = { { ["mapID"] = 2451, ["npcID"] = 249456, ["x"] = 0.208, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 2451, ["source"] = "quest_giver", ["x"] = 0.194667, ["y"] = 0.574667 }, ["mapCandidates"] = { ["npc"] = { 2451 }, ["zone"] = { 16432 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5985, ["name"] = "Siege of Arathi Highlands - Side Quests", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2927, ["db2PoiUiMapID"] = 2451 },
[93384] = { ["id"] = 93384, ["name"] = "Delver's Call: Collegiate Calamity", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 93372, 93384, 93385, 93386, 93409, 93410, 93416, 93421, 93427, 93428 }, ["description"] = "The arcane tome, clearly agitated by something, bears the mark of Silvermoon's Thalassian University. It could be worth investigating.", ["objectivesText"] = "Complete the Collegiate Calamity delve on any difficulty. Progress: Is something amiss at the university?", ["rewardGold"] = 4099200, ["rewardXP"] = 23530, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.614, ["mapID"] = 2393, ["objectID"] = 612038 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 242398, ["x"] = 0.526, ["y"] = 0.78 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.78 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6051, ["name"] = "Delver's Call - Midnight", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[93385] = { ["id"] = 93385, ["name"] = "Delver's Call: The Darkway", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 93372, 93384, 93385, 93386, 93409, 93410, 93416, 93421, 93427, 93428 }, ["description"] = "Remnants of the Twilights Blade scurry like rats through the Arcway tunnels beneath Suramar. Exterminate the vermin before they spread.", ["objectivesText"] = "Complete The Darkway delve on any difficulty.", ["rewardGold"] = 4099200, ["rewardXP"] = 23530, ["starts"] = { { ["x"] = 0.521, ["y"] = 0.78, ["mapID"] = 2393, ["objectID"] = 612039 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 242399, ["x"] = 0.525, ["y"] = 0.787 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.787 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6051, ["name"] = "Delver's Call - Midnight", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[93386] = { ["id"] = 93386, ["name"] = "Delver's Call: Parhelion Plaza", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 93372, 93384, 93385, 93386, 93409, 93410, 93416, 93421, 93427, 93428 }, ["description"] = "Adventurers! Quel'Danas is once more under attack by the Void, and any who are able to provide assistance should head to the battlements of Parhelion Plaza to help stem the tide.", ["objectivesText"] = "Complete the Parhelion Plaza delve on any difficulty. Progress: The Void is relentless. Be cautious.", ["rewardGold"] = 4099200, ["rewardXP"] = 23530, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.775, ["mapID"] = 2393, ["objectID"] = 612894 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 242398, ["x"] = 0.526, ["y"] = 0.78 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.78 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6051, ["name"] = "Delver's Call - Midnight", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[93387] = { ["id"] = 93387, ["name"] = "Dealing with Pests", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "Every time I leave my hut, I return to a mess and soggy little murloc footprints. I am plannin' a different approach to deal with those pestersome amphibian encroachers, but I need to sort out some ingredients. While I work out my list for those pests--there is a ghost named Jelvik dat keeps after me for somethin'. Tell him to move along.", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 263327, ["x"] = 0.61, ["y"] = 0.326, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 263327, ["x"] = 0.61, ["y"] = 0.326, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.61, ["y"] = 0.326, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 92920 }, ["questLines"] = { { ["id"] = 6276, ["name"] = "Strange Friends in Odd Places", ["orderIndex"] = 0, ["flags"] = 0 } } },
[93388] = { ["id"] = 93388, ["name"] = "Unusual Alchemy", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "My list is ready. I need you to gather de ingredients to keep dem murlocs away for good. First, talk to Maka de Trawler. He and de kelpweaver from Torga's Beak like to catch fish in de inlet. Bring me some fish guts--disgustin' and perfect. Next, head out to Mlurkkr Mire. I need dat dirty ol' pearl dey think is so special. While you're in de Mire, relieve some of dem irritatin' serpent folk of some scales. Mind you, I only want de good ones.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 263327, ["x"] = 0.61, ["y"] = 0.326, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 260226, ["x"] = 0.604, ["y"] = 0.33, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.61, ["y"] = 0.326, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93387 }, ["questLines"] = { { ["id"] = 6276, ["name"] = "Strange Friends in Odd Places", ["orderIndex"] = 1, ["flags"] = 0 } } },
[93389] = { ["id"] = 93389, ["name"] = "Rocksblood", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "I've been here so long dat pieces of my memory are lost to time. I feel an emptiness for something I loved. There will be no rest for me until I know who or what it was. I can only remember one word... Rocksblood. I don't know who or what dat is. Check de murloc ruins to de south. There's someone who can point you in de right direction. Since Ofi is bein' stubborn, I need you to help me remember.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 260710, ["x"] = 0.61, ["y"] = 0.328, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 254605, ["x"] = 0.61, ["y"] = 0.326, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.61, ["y"] = 0.328, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93387 }, ["questLines"] = { { ["id"] = 6276, ["name"] = "Strange Friends in Odd Places", ["orderIndex"] = 2, ["flags"] = 0 } } },
[93390] = { ["id"] = 93390, ["name"] = "Acceptable Apprentice", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "Dis part is gonna be fun. I got de mixture started. It is already unpleasant, but now we will make it really vile. When you feel mentally prepared to be a useful one again, let me know.", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 260226, ["x"] = 0.604, ["y"] = 0.33, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 260226, ["x"] = 0.604, ["y"] = 0.33, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.604, ["y"] = 0.33, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93388, 93389 }, ["questLines"] = { { ["id"] = 6276, ["name"] = "Strange Friends in Odd Places", ["orderIndex"] = 3, ["flags"] = 0 } } },
[93391] = { ["id"] = 93391, ["name"] = "Make it Stinky", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "Best you move our little deterrents out to de strip of land between my home and de maniacs' mire. They may try to stop you, but hold fast. If it works, dey will be running with their tails between their legs. Do murlocs even have tails?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 260226, ["x"] = 0.604, ["y"] = 0.33, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 260226, ["x"] = 0.604, ["y"] = 0.33, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.604, ["y"] = 0.33, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93390 }, ["questLines"] = { { ["id"] = 6276, ["name"] = "Strange Friends in Odd Places", ["orderIndex"] = 4, ["flags"] = 0 } } },
[93392] = { ["id"] = 93392, ["name"] = "Recovering Memories", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "To de northeast, there's a small island. I remember long ago a great roarin' and howlin' dat echoed across de waters. I could hear de anger, but there was also pain. I could not venture to dat place. What if I became lost, my own feelings swallowed by de bigger ones? One day, it became quiet again, but now I feel dis is de final key to de lock on my soul. Go there. Find de last piece.", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3504, ["amount"] = 100 } }, ["starts"] = { { ["npcID"] = 254605, ["x"] = 0.61, ["y"] = 0.326, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 254605, ["x"] = 0.61, ["y"] = 0.326, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.61, ["y"] = 0.326, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93391 }, ["questLines"] = { { ["id"] = 6276, ["name"] = "Strange Friends in Odd Places", ["orderIndex"] = 5, ["flags"] = 0 } } },
[93393] = { ["id"] = 93393, ["name"] = "A Little Kindness", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "You know, my friend, as happy as I am... I keep thinkin' how sad we made dat beast. I do not wish dat feelin' on another livin' soul. He took care of dear Sava for all de years she was lost. Could you help us with one last request? If you could bring him a friend of his own, it will repay our debt. Then we can move on once and for all--me and Sava will be free.", ["rewardXP"] = 13690, ["rewardItems"] = { 268644 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3504, ["amount"] = 250 } }, ["starts"] = { { ["npcID"] = 254605, ["x"] = 0.61, ["y"] = 0.326, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 263327, ["x"] = 0.61, ["y"] = 0.326, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.61, ["y"] = 0.326, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93392 }, ["questLines"] = { { ["id"] = 6276, ["name"] = "Strange Friends in Odd Places", ["orderIndex"] = 6, ["flags"] = 0 } } },
[93396] = { ["id"] = 93396, ["name"] = "Bursting at the Seams", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 90838, 90844, 90845, 90847, 90848, 90851, 90852, 90858, 90860, 93396 }, ["description"] = "Veraan... alive... < Kifaan shakes his head in disbelief.> I've spent countless hours running this moment through my head, but now that it's here, I find myself grasping for words... The Shadowguard attempted to raise Dimensius to power... they've sworn fealty to Xal'atath as she wages war on worlds. Am I supposed to just... pretend none of that happened? Is THAT what my oaths to family require? And what of Veraan? Does she regret her involvement? I should check on her.", ["objectivesText"] = "Help Kifaan check on his sister's well-being.", ["rewardGold"] = 170800, ["rewardXP"] = 6425, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 244516, ["x"] = 0.3988, ["y"] = 0.476 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 244516, ["x"] = 0.3988, ["y"] = 0.476 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.3988, ["y"] = 0.476 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 90851, 90852 }, ["questLines"] = { { ["id"] = 6014, ["name"] = "Oaths to Family", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
