[93417] = { ["id"] = 93417, ["name"] = "The Vaults of Atal'Utek: Altar of Fangs", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16915, ["mapID"] = 2512, ["description"] = "Orweyna told us what she saw... Damn it, Zul'jan ! Does he truly not understand what he's done? Despite what we have accomplished, he sees the bonds Zul'jarra forged with the both of us as weakness and chases this idea of a \"supreme Amani Empire\" still. And in the process, he has gravely wounded his sister. But maybe Zul'jarra is right--maybe he doesn't know. We have to get that dagger. By making him see sense, or by force.", ["rewardGold"] = 1366400, ["rewardXP"] = 27380, ["rewardChoices"] = { 273781, 273785, 273787, 273789, 273791 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3504, ["amount"] = 250 } }, ["starts"] = { { ["npcID"] = 253827, ["x"] = 0.574, ["y"] = 0.49, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 259226, ["x"] = 0.572, ["y"] = 0.486, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.574, ["y"] = 0.49, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16915 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 92937 }, ["questLines"] = { { ["id"] = 6090, ["name"] = "The Battle for Atal'Utek", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6232, ["name"] = "The Battle for Atal'Utek", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6090, ["questLineOrder"] = 4 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6232, ["questLineOrder"] = 4 } } },
[93418] = { ["id"] = 93418, ["name"] = "The Venomous Abyss", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "I saw things in de venom haze. Heard Zul'jan screamin', felt what's eatin' away at him. Heard Malacrass whisperin' in his ear. Ula'tek has haunted de Amani from de beginning. De lengths we went to for power and empire, and de blood it cost... Dat wasn't greatness. Deep down, Zul'jan knows it too. Malacrass stole my grandfather from me. I won't let him take Zul'jan too.", ["rewardGold"] = 20496000, ["rewardXP"] = 27380, ["starts"] = { { ["npcID"] = 259319, ["x"] = 0.572, ["y"] = 0.486, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 259319, ["x"] = 0.572, ["y"] = 0.486, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.572, ["y"] = 0.486, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questTurnInID"] = 259319, ["questType"] = "raid", ["sourceQuests"] = { 93419 }, ["questLines"] = { { ["id"] = 6090, ["name"] = "The Battle for Atal'Utek", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 6232, ["name"] = "The Battle for Atal'Utek", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6090, ["questLineOrder"] = 4 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6232, ["questLineOrder"] = 4 } } },
[93419] = { ["id"] = 93419, ["name"] = "Nature of Her Wounds", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "The Fang is cursed from the summoning of Ula'tek. We can use it to cure Zul'jarra . I just-- We have to act fast. She's fading!", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 259226, ["x"] = 0.572, ["y"] = 0.486, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 259319, ["x"] = 0.572, ["y"] = 0.486, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.572, ["y"] = 0.486, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93417 }, ["questLines"] = { { ["id"] = 6090, ["name"] = "The Battle for Atal'Utek", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6232, ["name"] = "The Battle for Atal'Utek", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6090, ["questLineOrder"] = 4 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6232, ["questLineOrder"] = 4 } } },
[93420] = { ["id"] = 93420, ["name"] = "Lor'themar's Judgement", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["description"] = "We need to tell Lor'themar what happened here. Meet me in Silvermoon. As for Zul'jarra... she needs time. She needs her people, and her people need her. She will survive this. I am sure of it. She must!", ["rewardGold"] = 85400, ["rewardXP"] = 3420, ["starts"] = { { ["x"] = 0.217, ["y"] = 0.649, ["mapID"] = 2512, ["npcID"] = 259417 } }, ["ends"] = { { ["x"] = 0.217, ["y"] = 0.649, ["mapID"] = 2512, ["npcID"] = 259417 } }, ["coords"] = { ["mapID"] = 2512, ["x"] = 0.217, ["y"] = 0.649 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15969 } }, ["questGiverID"] = 259417, ["questTurnInID"] = 259417, ["questType"] = "standard", ["sourceQuests"] = { 93418 }, ["questLines"] = { { ["id"] = 6090, ["name"] = "The Battle for Atal'Utek", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6232, ["name"] = "The Battle for Atal'Utek", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6090, ["questLineOrder"] = 4 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6232, ["questLineOrder"] = 4 } } },
[93421] = { ["id"] = 93421, ["name"] = "Delver's Call: The Grudge Pit", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 93372, 93384, 93385, 93386, 93409, 93410, 93416, 93421, 93427, 93428 }, ["description"] = "<This moldy hanging has been crudely painted over to depict one fungarian hitting another with what looks to be a chair.> See big fight. Best fight! Grudge Pit. Be there!", ["objectivesText"] = "Complete The Grudge Pit delve on any difficulty. Progress: How fighting?", ["rewardGold"] = 4099200, ["rewardXP"] = 23530, ["starts"] = { { ["x"] = 0.712, ["y"] = 0.521, ["mapID"] = 2413, ["objectID"] = 612264 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 243226, ["x"] = 0.718, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6051, ["name"] = "Delver's Call - Midnight", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
