[93427] = { ["id"] = 93427, ["name"] = "Delver's Call: Sunkiller Sanctum", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 93372, 93384, 93385, 93386, 93409, 93410, 93416, 93421, 93427, 93428 }, ["description"] = "<A note is pinned to the slain voidwalker.> Sunkiller Sanctum is a den of Xal'atath's most pathetic sycophants. I encourage any mercenaries, adventurers, or general do-gooders who happen upon this bounty to pay it a visit and dispense the justice you are all so happy to talk on and on about. - Perodius", ["objectivesText"] = "Complete the Sunkiller Sanctum delve on any difficulty. Progress: Ah, a <race>. How delightful.", ["rewardGold"] = 4099200, ["rewardXP"] = 23530, ["starts"] = { { ["x"] = 0.427, ["y"] = 0.708, ["mapID"] = 2405, ["objectID"] = 612354 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 254765, ["x"] = 0.514, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6051, ["name"] = "Delver's Call - Midnight", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[93428] = { ["id"] = 93428, ["name"] = "Delver's Call: Shadowguard Point", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 93372, 93384, 93385, 93386, 93409, 93410, 93416, 93421, 93427, 93428 }, ["description"] = "Witness the fates of those who bend their neck to Xal'atath. I issue a challenge to any creature of Void or flesh. Pursue the nearby ethereals and dispatch anyone who serves the so-called Harbinger. - Perodius", ["objectivesText"] = "Complete the Shadowguard Point delve on any difficulty. Progress: Have you come to me for a reason, <class>?", ["rewardGold"] = 4099200, ["rewardXP"] = 23530, ["starts"] = { { ["x"] = 0.376, ["y"] = 0.519, ["mapID"] = 2405, ["objectID"] = 612364 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 254765, ["x"] = 0.514, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6051, ["name"] = "Delver's Call - Midnight", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[93432] = { ["id"] = 93432, ["name"] = "Swords to Plowshares", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2536, ["storyline"] = { 93432, 93433, 93435, 93436, 93437, 93440 }, ["description"] = "First Mor'duun and the Blade ambush Atal'Aman. Now it's overrun by these \"echoes...\" At least, that's what Doru calls them: echoes. All I see are ghosts of a bloodier time. And like those days, no matter how many we cut through, they never stop swarming in. Get out there and see for yourself. Bring de echoes' remains as well. Doru wants to study what dey are and how dey work.", ["objectivesText"] = "Collect 20 Raider Ash Remains . Progress: It's like a dream you can't wake from.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 33993, 259204 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2536, ["npcID"] = 254783, ["x"] = 0.457, ["y"] = 0.4615 } }, ["ends"] = { { ["mapID"] = 2536, ["npcID"] = 254783, ["x"] = 0.457, ["y"] = 0.4615 } }, ["coords"] = { ["mapID"] = 2536, ["source"] = "quest_giver", ["x"] = 0.457, ["y"] = 0.4615 }, ["mapCandidates"] = { ["npc"] = { 2536 }, ["zone"] = { 16194 } }, ["questType"] = "standard", ["sourceQuests"] = { 93440 }, ["questLines"] = { { ["id"] = 6052, ["name"] = "Bloodstains", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2536 },
[93433] = { ["id"] = 93433, ["name"] = "Shrine, Sealed, Delivered", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2536, ["storyline"] = { 93432, 93433, 93435, 93436, 93437, 93440 }, ["description"] = "Curse de echoes. Curse Zul'jin, and Mor'duun, and dat snake Malacrass too. They only cause more mess for de livin' to clean up. Listen, hash'ura. I need you to deliver supplies to each of de shrines in de city. We've packaged food, water, bandages, and reagents to keep their barriers at full strength. Ask about their status as well. Though safe, they all likely feel boxed in.", ["objectivesText"] = "Deliver supplies to the Elders of the four Loa Shrines: Elder Shimarra, Eagletender Rhyd, Elder Thak, and Elder Vu'lona.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2536, ["npcID"] = 254827, ["x"] = 0.457333, ["y"] = 0.466667 } }, ["ends"] = { { ["mapID"] = 2536, ["npcID"] = 254827, ["x"] = 0.457333, ["y"] = 0.466667 } }, ["coords"] = { ["mapID"] = 2536, ["source"] = "quest_giver", ["x"] = 0.457333, ["y"] = 0.466667 }, ["mapCandidates"] = { ["npc"] = { 2536 }, ["zone"] = { 16194 } }, ["questType"] = "standard", ["sourceQuests"] = { 93440 }, ["questLines"] = { { ["id"] = 6052, ["name"] = "Bloodstains", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2536 },
[93435] = { ["id"] = 93435, ["name"] = "Four Instigators", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2536, ["storyline"] = { 93432, 93433, 93435, 93436, 93437, 93440 }, ["description"] = "De scouts report seein' a few unique faces among de echoes. I felt old angers rising when I heard de names. Dey were not honorable fighters for us to challenge ourselves against, such as yourself. They were vermin--greedy opportunists that drove legions of connivin' adventurers to rob us of our possessions, our treasures, and... our tusks. Slayin' de echoes of these key figures should reduce de number of echoes appearin'. And it will make me grin to know they've fallen.", ["objectivesText"] = "Slay the echoes of Prigmon , Zungam , Budd Nedreck , and Harrison Jones .", ["rewardGold"] = 309800, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2536, ["npcID"] = 254783, ["x"] = 0.457, ["y"] = 0.4615 } }, ["ends"] = { { ["mapID"] = 2536, ["npcID"] = 254783, ["x"] = 0.457, ["y"] = 0.4615 } }, ["coords"] = { ["mapID"] = 2536, ["source"] = "quest_giver", ["x"] = 0.457, ["y"] = 0.4615 }, ["mapCandidates"] = { ["npc"] = { 2536 }, ["zone"] = { 16194 } }, ["questType"] = "standard", ["sourceQuests"] = { 93432, 93433 }, ["questLines"] = { { ["id"] = 6052, ["name"] = "Bloodstains", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2536 },
[93436] = { ["id"] = 93436, ["name"] = "Hex the Innocent, Disrupt the Guilty", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2536, ["storyline"] = { 93432, 93433, 93435, 93436, 93437, 93440 }, ["description"] = "I will study de ashes you acquired, but we can get dis situation under control by means other than de axe. You must disrupt de battlefield, hash'ura. De echoes believe dey're in de midst of a decades-old battle, so we must target de support dey relied on back then. Poison de feasts dey find respite at, hex their disrespectful civilian allies, and sabotage dat chest they seem so keen on lootin'!", ["objectivesText"] = "Poison 3 Raider's Feasts, hex 7 Civilians, and sabotage the Warlord's Chest. Progress: Let us prove dat even echoes of de past can feel woe.", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 259967 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2536, ["npcID"] = 254827, ["x"] = 0.457333, ["y"] = 0.466667 } }, ["ends"] = { { ["mapID"] = 2536, ["npcID"] = 254827, ["x"] = 0.457333, ["y"] = 0.466667 } }, ["coords"] = { ["mapID"] = 2536, ["source"] = "quest_giver", ["x"] = 0.457333, ["y"] = 0.466667 }, ["mapCandidates"] = { ["npc"] = { 2536 }, ["zone"] = { 16194 } }, ["questType"] = "standard", ["sourceQuests"] = { 93432, 93433 }, ["questLines"] = { { ["id"] = 6052, ["name"] = "Bloodstains", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2536 },
[93437] = { ["id"] = 93437, ["name"] = "In Their Own Blood", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2536, ["storyline"] = { 93432, 93433, 93435, 93436, 93437, 93440 }, ["description"] = "After studying de ashes, Doru believes we can only fight with de past using weapons of de past. I cannot ask this of any Amani. Or Witherbark, Revantusk, or Shadowpine. Ya presence with us in these times must be fate... because we could only make this request to an outsider. Ya must inhabit a soul of de profane ones: those that accepted Malacrass's vile bargain and consumed loa power during de era of Zul'jin. Return to de shrine of de profane one ya wish to merge with. Ancestors forgive us...", ["objectivesText"] = "Become one of the four Loa Avatars. Slay Raiding Echoes in Atal'Aman, and defeat the Raid Leader upon the Warlord's Stair.", ["rewardGold"] = 683200, ["rewardXP"] = 15215, ["rewardItems"] = { 264184 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3354, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2536, ["npcID"] = 254783, ["x"] = 0.457, ["y"] = 0.4615 } }, ["ends"] = { { ["mapID"] = 2536, ["npcID"] = 254783, ["x"] = 0.457, ["y"] = 0.4615 } }, ["coords"] = { ["mapID"] = 2536, ["source"] = "quest_giver", ["x"] = 0.457, ["y"] = 0.4615 }, ["mapCandidates"] = { ["npc"] = { 2536 }, ["zone"] = { 16194 } }, ["questType"] = "standard", ["sourceQuests"] = { 93435, 93436 }, ["questLines"] = { { ["id"] = 6052, ["name"] = "Bloodstains", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2536 },
[93438] = { ["id"] = 93438, ["name"] = "Special Assignment: Precision Excision", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 93438 }, ["objectivesText"] = "Ride the War-Wyrm Forces slain in lower courtyard Forces slain in lower courtyard HIDDEN Forces slain in upper courtyard Forces slain in upper courtyard HIDDEN High value targets eliminated Forces slain in Stormarion Watch Forces slain in Stormarion Watch HIDDEN Stormarion Supplies destroyed", ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.358, ["y"] = 0.704, ["mapID"] = 2405 } }, ["ends"] = { { ["x"] = 0.358, ["y"] = 0.704, ["mapID"] = 2405 } }, ["coords"] = { ["mapID"] = 2405, ["x"] = 0.358, ["y"] = 0.704 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16648 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 255628, ["text"] = "Ride the War-Wyrm" }, { ["orderIndex"] = 1, ["type"] = 0, ["amount"] = 10, ["objectID"] = 255730, ["text"] = "Forces slain in lower courtyard" }, { ["orderIndex"] = 2, ["type"] = 0, ["amount"] = 99, ["objectID"] = 255730, ["text"] = "Forces slain in lower courtyard HIDDEN" }, { ["orderIndex"] = 3, ["type"] = 0, ["amount"] = 10, ["objectID"] = 255740, ["text"] = "Forces slain in upper courtyard" }, { ["orderIndex"] = 4, ["type"] = 0, ["amount"] = 99, ["objectID"] = 255740, ["text"] = "Forces slain in upper courtyard HIDDEN" }, { ["orderIndex"] = 5, ["type"] = 0, ["amount"] = 5, ["objectID"] = 255735, ["text"] = "High value targets eliminated" }, { ["orderIndex"] = 6, ["type"] = 0, ["amount"] = 7, ["objectID"] = 255788, ["text"] = "Forces slain in Stormarion Watch" }, { ["orderIndex"] = 7, ["type"] = 0, ["amount"] = 99, ["objectID"] = 255788, ["text"] = "Forces slain in Stormarion Watch HIDDEN" }, { ["orderIndex"] = 8, ["type"] = 0, ["amount"] = 5, ["objectID"] = 255793, ["text"] = "Stormarion Supplies destroyed" } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405, ["db2QuestInfoID"] = 286, ["db2QuestInfoName"] = "Capstone World Quest" },
[93440] = { ["id"] = 93440, ["name"] = "Personal History", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 93432, 93433, 93435, 93436, 93437, 93440 }, ["description"] = "With Mor'duun slain and de Twilight's Blade defeated, my people want to return to Atal'Aman. It should be a moment of great celebration but... somethin' unexpected is barrin' our way. Seek out Torundo and Elder Doru. Dey are supportin' de resettlement. They'll know how best to use your talents. Prepare yourself, hash'ura, and do not hesitate to defend Atal'Aman no matter who you meet there.", ["objectivesText"] = "Speak with Torundo the Grizzled in Atal'Aman.", ["rewardGold"] = 30900, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3354, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 249653, ["x"] = 0.456, ["y"] = 0.655 } }, ["ends"] = { { ["mapID"] = 2536, ["npcID"] = 254783, ["x"] = 0.457, ["y"] = 0.4615 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.655 }, ["mapCandidates"] = { ["npc"] = { 2437, 2536 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91062 }, ["questLines"] = { { ["id"] = 6052, ["name"] = "Bloodstains", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiUiMapID"] = 2536 },
[93449] = { ["id"] = 93449, ["name"] = "Trouble in the Swamp", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "A group of my people went over to Mlurkkr Mire and have not returned. Dey were looking into an incursion of de Children of Ula'tek in de region. There are also troubling reports of de local murlocs actin' more violent than usual, and de priest Wa'kani said she detected a strong dark energy she wanted to check out. Their leader, Zawadi , was due to report back an hour ago. Will you go find dem and lend aid if needed?", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3504, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 257091, ["x"] = 0.574, ["y"] = 0.474, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 254372, ["x"] = 0.63, ["y"] = 0.444, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.574, ["y"] = 0.474, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93024 }, ["questLines"] = { { ["id"] = 6118, ["name"] = "The Troubles of Mlurkkr Mire", ["orderIndex"] = 0, ["flags"] = 0 } } },
[93452] = { ["id"] = 93452, ["name"] = "Retrieved Crumpled Present", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16227, ["storyline"] = { 93452 }, ["description"] = "<It seems the minions of the Greench have fled, leaving behind a small mangled, but still salvageable present. Perhaps one of the Winter Festivities planners would be able to help return it to the original intended recipient.>", ["objectivesText"] = "Talk to Joanna Copperpinch in the Razorwind Shores neighborhood.", ["rewardGold"] = 292100, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16227 } }, ["questType"] = "standard" },
[93453] = { ["id"] = 93453, ["name"] = "A Grave Concern", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93453 }, ["description"] = "Dearly Departed, Having just tasted the bitter sting of mortality, there seems no better time to discuss with you the oft ignored subject of death and memorialization. Of what you leave behind in a real, physical sense. Leave discussion of love and other such frivolities to the philosophers and dandies. I speak of cold, hard stone and the deeds carved upon it. Find me in Silvermoon.", ["objectivesText"] = "Meet with Nelthius Shadestone in Silvermoon. Progress: Have you made your selection?", ["rewardGold"] = 34100, ["rewardXP"] = 1470, ["rewardItems"] = { 262951, 262966 }, ["starts"] = { { ["x"] = 0.527, ["y"] = 0.776, ["mapID"] = 2393, ["npcID"] = 254616 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 254616, ["x"] = 0.526, ["y"] = 0.775 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.775 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questGiverID"] = 254616, ["questType"] = "standard", ["startItems"] = { 258738 } },
[93454] = { ["id"] = 93454, ["name"] = "Words to Hear", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "Malacrass helped my grandfather lead de Amani to ruin. Now he's gonna do de same to my brother. If we could just separate de two of them... But Jan won't listen. He thinks Ula'tek is a weapon dat will bring de return of de Amani Empire. After de vision he saw--and who knows what else Malacrass told him--I can't convince him otherwise. De hash'ey requires counsel, my hash'ura. Gather de others and join me.", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 258859, ["x"] = 0.584, ["y"] = 0.454, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 253514, ["x"] = 0.574, ["y"] = 0.49, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.584, ["y"] = 0.454, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93024 }, ["questLines"] = { { ["id"] = 6031, ["name"] = "Ghosts of the Past", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6230, ["name"] = "Ghosts of the Past", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6031, ["questLineOrder"] = 2 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6230, ["questLineOrder"] = 2 } } },
[93495] = { ["id"] = 93495, ["name"] = "A Soaring Journey Through Time", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 13862, ["mapID"] = 2112, ["description"] = "The sands of time flow back and forth like ocean waves. Journey once more through the timeways, to the time of Dragon Aspects and Primal Incarnates. Bring me tales of victory in an era of great adventure and danger.", ["rewardGold"] = 1353200, ["rewardItems"] = { 232877 }, ["starts"] = { { ["x"] = 0.815, ["y"] = 0.472, ["mapID"] = 2112, ["npcID"] = 255019 } }, ["ends"] = { { ["npcID"] = 255019, ["x"] = 0.814, ["y"] = 0.47, ["mapID"] = 2112 } }, ["coords"] = { ["mapID"] = 2112, ["x"] = 0.815, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questGiverID"] = 255019, ["questType"] = "standard" },
