[93575] = { ["id"] = 93575, ["name"] = "Maisara Caverns: Maisara Hungers", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16395, ["mapID"] = 2437, ["storyline"] = { 93575 }, ["description"] = "I will not leave my people to die to de Vilebranch's dark rituals. We must go after dem. The heart of Maisara Caverns is where de Vilebranch keep their secrets. I expect dis to be a bloody trip. We will have to face de ugliness of the Vilebranch greed, and what it is costin' all of us. We must discover what purpose they have for my stolen kin. If any still be alive. I will be dere to aid you... but bring a fierce party of warriors. We will need it.", ["objectivesText"] = "Complete the Maisara Caverns dungeon. Progress: Gather your warparty. I will see you in Maisara Caverns.", ["rewardGold"] = 1366400, ["rewardXP"] = 24340, ["rewardItems"] = { 251161, 251164, 251166, 251167, 251169, 251170, 251172, 251176, 251177 }, ["rewardChoices"] = { 251161, 251164, 251166, 251167, 251169, 251170, 251172, 251176, 251177 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3354, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 244521, ["x"] = 0.44, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 244521, ["x"] = 0.44, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 16395 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 92084 }, ["questLines"] = { { ["id"] = 6224, ["name"] = "Something Vile This Way Comes", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437, ["db2QuestInfoID"] = 81, ["db2QuestInfoName"] = "Dungeon" },
[93576] = { ["id"] = 93576, ["name"] = "The Search for Wa'kani", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "While you were keepin' de snakes busy, I was lookin' for Wa'kani and de other scouts. De scouts are still missin', but Wa'kani is in dat temple over there. I tried gettin' closer, but it's too heavily guarded. You should have no problem, though. Please rescue my fool sista before de snakes do something foul to her.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 254376, ["x"] = 0.66, ["y"] = 0.39, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 255978, ["x"] = 0.646, ["y"] = 0.378, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.66, ["y"] = 0.39, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93199, 93229 }, ["questLines"] = { { ["id"] = 6118, ["name"] = "The Troubles of Mlurkkr Mire", ["orderIndex"] = 3, ["flags"] = 0 } } },
