[93586] = { ["id"] = 93586, ["name"] = "Conditional - Multiple Objectives, Non Sequenced", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "none", ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14998, ["storyline"] = { 93586 }, ["description"] = "I be sent out here ta prove dat I can be an amani warrior. Dis trial needs me ta collect as many trophies from dese gnarldin as possible. De two of us should work together! I be helpin' you get recognized as an amani warrior, yeah? Just go out dere and get as many trophies from de gnarldin as possible. I be stayin' behind ta watch our backs, eh?", ["objectivesText"] = "Recover 1 trophies from gnarldin and their allies.", ["rewardGold"] = 309800, ["rewardXP"] = 12170, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14998 } }, ["questType"] = "standard" },
[93593] = { ["id"] = 93593, ["name"] = "A Call to Battle", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93593 }, ["description"] = "Ours is a world of constant struggle, wouldn't you agree? Even in between times of peace, there is value in keeping one's battle skills sharpened. I have heard much of your prowess. Let us see what you are capable of.", ["objectivesText"] = "Win 4 Battleground matches. Progress: There is no substitute for constant vigilance, <class>. Al'anna, dalomore.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 137642 }, ["rewardCurrencies"] = { { ["id"] = 1602, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 2393 },
[93595] = { ["id"] = 93595, ["name"] = "A Call to Delves", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93595 }, ["description"] = "Seeking out challenge and treasure can test one's skills, all while uncovering that which will give us even greater power. Were I you, I would delve into places that provide both.", ["objectivesText"] = "Complete 5 Midnight Delves. Progress: Has your delving come to a satisfactory conclusion?", ["rewardItems"] = { 229129, 250116 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 2393 },
[93598] = { ["id"] = 93598, ["name"] = "Emissary of War", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93598 }, ["description"] = "It is only when we push ourselves beyond our limits that we truly grow... or fail and make way for others. Prove yourself by challenging the deadliest of places. Shorel'aran.", ["objectivesText"] = "Complete 4 dungeons on Mythic difficulty. Progress: Will you become the stuff of myths and legends, <class>?", ["rewardGold"] = 70225, ["rewardXP"] = 25, ["rewardItems"] = { 226194, 234731, 247820, 250117 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "dungeon", ["db2PoiUiMapID"] = 2393, ["db2QuestInfoID"] = 81, ["db2QuestInfoName"] = "Dungeon" },
[93599] = { ["id"] = 93599, ["name"] = "The Very Best", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93599 }, ["description"] = "Even the smallest amongst us must play their part. That includes our little friends. If you would strengthen both their prowess and your bond, challenge others. Only the fittest will survive.", ["objectivesText"] = "Defeat 5 players through Find Battle with a team of level 25 pets. Progress: By strengthening those bonds, you and your little companions will be ready for whatever comes.", ["rewardItems"] = { 122457 }, ["rewardChoices"] = { 122457 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 2393 },
[93600] = { ["id"] = 93600, ["name"] = "The Arena Calls", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93600 }, ["description"] = "Old, musty dungeons and battlefields are one thing, but the arena is where the wheat and the chaff are separated. Can you prove yourself, <class>? Show me. Let me hear your name shouted from the stands by those crying for blood.", ["objectivesText"] = "Win 10 Arena Skirmish battles.", ["rewardCurrencies"] = { { ["id"] = 1602, ["amount"] = 110 }, { ["id"] = 1792, ["amount"] = 2000 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questTurnInID"] = 256212, ["questType"] = "standard", ["db2PoiUiMapID"] = 2393 },
[93605] = { ["id"] = 93605, ["name"] = "The World Awaits", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93605 }, ["description"] = "Sinu a'manore, <class>. It is true in the past, I have been less than... egalitarian in my outlook. Yet in these times of trouble, there is much to be done--whether here in Quel'Thalas or elsewhere. Will you face the challenge and prove yourself once more?", ["objectivesText"] = "Complete 10 Midnight World Quests.", ["rewardItems"] = { 2815, 3056, 255881 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 2393 },
[93607] = { ["id"] = 93607, ["name"] = "An Original Path Through Time", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["description"] = "Greetings, . You come to me because you seek answers. I have nothing for you but guidance. Perhaps the answers you seek lie in the past? Return to that time mere years after the conclusion of the Third War. Face its threats once again and see what wisdom you can glean.", ["rewardItems"] = { 250117 }, ["starts"] = { { ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.646, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.646, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.488, ["y"] = 0.646, ["source"] = "quest_giver", ["mapID"] = 2393 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[93608] = { ["id"] = 93608, ["name"] = "A Burning Path Through Time", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93608 }, ["description"] = "On the other side of the Dark Portal lies Outland. I've never been--my history is tied to the Kirin Tor rather than Silvermoon. Yet the elves of Quel'Thalas went through much turmoil during that period of time. Perhaps you could learn a thing or two from that fractured world. Take up the challenge, if you feel worthy of it.", ["objectivesText"] = "Defeat 5 Timewalking raid bosses or dungeons.", ["rewardItems"] = { 250117, 127853, 226193, 226194 }, ["starts"] = { { ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.646, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.646, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.488, ["y"] = 0.646, ["source"] = "quest_giver", ["mapID"] = 2393 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[93611] = { ["id"] = 93611, ["name"] = "A Shattered Path Through Time", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93611 }, ["description"] = "The Cataclysm was terrifying for all of Azeroth. The existential threat of Deathwing echoes down through the ages. Isn't it interesting that no matter how things change, such threats return time and time again, but in different forms? Go back and face those threats again. See if there's something new to learn from the past.", ["objectivesText"] = "Defeat 5 Timewalking raid bosses or dungeons. Progress: I... would not relive those times. Some memories are best left behind.", ["rewardItems"] = { 127853, 226193, 226194, 247821, 250116 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[93612] = { ["id"] = 93612, ["name"] = "A Shrouded Path Through Time", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93612 }, ["description"] = "My memories of Pandaria are... complicated, <class>. Many lessons were learned during that tumultuous period of time--some good, some painful. The world has changed a great deal since then. We've all changed--I hope for the better. Travel back through the mists of time. Relearn what lessons you can.", ["objectivesText"] = "Complete 5 Timewalking dungeons.", ["rewardItems"] = { 226194, 234729, 247820, 247821, 250116 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[93613] = { ["id"] = 93613, ["name"] = "A Savage Path Through Time", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93613 }, ["description"] = "Perhaps you can untangle the depth of knowledge to be found in Draenor--not the shattered remains of Outland, but the Draenor of the Iron Horde. It is, in its own ways, just as harsh if not harsher than Outland ever was. See what wisdom you can find there.", ["objectivesText"] = "Complete 5 Timewalking dungeons.", ["rewardItems"] = { 226194, 234729, 247820, 247821 }, ["starts"] = { { ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.646, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.646, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.488, ["y"] = 0.646, ["source"] = "quest_giver", ["mapID"] = 2393 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[93614] = { ["id"] = 93614, ["name"] = "A Fel Path Through Time", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["description"] = "I have faced many enemies, but the Burning Legion was perhaps the greatest threat our world ever faced. At least... until now. Of course, there are our inner demons to contend with as well. Do you still have what it takes to defeat the Burning Legion?", ["rewardItems"] = { 250116 }, ["starts"] = { { ["x"] = 0.489, ["y"] = 0.646, ["mapID"] = 2393, ["npcID"] = 256212 } }, ["ends"] = { { ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.646, ["mapID"] = 2393 } }, ["coords"] = { ["mapID"] = 2393, ["x"] = 0.489, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questGiverID"] = 256212, ["questType"] = "standard" },
[93627] = { ["id"] = 93627, ["name"] = "A Scarred Path Through Time", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["description"] = "I remember well the battles of the Alliance and Horde that played out in Kul Tiras and Zandalar. Return there, relive the memories. Will you seek glory, or knowledge? Or perhaps both?", ["rewardItems"] = { 250117 }, ["starts"] = { { ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.646, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.646, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.488, ["y"] = 0.646, ["source"] = "quest_giver", ["mapID"] = 2393 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[93628] = { ["id"] = 93628, ["name"] = "A Shadowed Path Through Time", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93628 }, ["description"] = "Would you return to the realm of death and risk your very existence? Rebirth, eternal peace, endless torment? All can be found across the veil. Travel to the Shadowlands once more. If you can defeat its most dangerous places, perhaps you will return to the living wiser and more powerful.", ["objectivesText"] = "Complete 5 Timewalking dungeons.", ["rewardItems"] = { 250117 }, ["starts"] = { { ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.646, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.646, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.488, ["y"] = 0.646, ["source"] = "quest_giver", ["mapID"] = 2393 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[93640] = { ["id"] = 93640, ["name"] = "Fish Finagling", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 93640 }, ["description"] = "I had wanted to bring the tea set home to my wife to surprise her... But that won't make up for me not bringing home any fish for supper. Hm. I'll make a deal with you, . I've been standing here all day trying to catch some fish for my beautiful wife to cook for us. But the crabs keep stealing my catch--and my bait! Run them off so I can catch and keep some fish, and I will give you this teapot. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(93640)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(93640))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15947 } }, ["questType"] = "standard" },
[93641] = { ["id"] = 93641, ["name"] = "Against Overwhelming Odds", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 11, ["storyline"] = { 93641 }, ["description"] = "Friends - I sense some troubles out there. There's foes out there that harbor grudges and are looking for a fight. Join others and show those looking for a battle who is mighty. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(93641)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(93641))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Slay 25 Level 90 Horde anywhere within Midnight.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
