[93651] = { ["id"] = 93651, ["name"] = "The Blinding Vale: Lightbloom Roots", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2393, ["storyline"] = { 93651 }, ["description"] = "We have traced Ruia's flight through the Rootways. As we suspected, he has sought refuge deep within The Blinding Vale, where the Lightbloom first took root within Harandar. With Alndust empowering our command of life, we are able to keep the Lightbloom from spreading uncontrolled. But we will run out of Alndust long before Ruia runs out of patience. Ruia is wise and powerful. But his actions in Eversong prove that his conviction has grown into an uncontrollable fanaticism. He must be stopped.", ["objectivesText"] = "Complete The Blinding Vale dungeon. Progress: Ruia is too powerful to challenge alone. Who knows what manner of overgrown monsters lurk in the heart of the Lightbloom?", ["rewardGold"] = 1366400, ["rewardXP"] = 24340, ["rewardItems"] = { 251183, 251185, 251190, 251194, 251197, 251200 }, ["rewardChoices"] = { 251183, 251185, 251190, 251194, 251197, 251200 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3370, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 255822, ["x"] = 0.365, ["y"] = 0.685 }, { ["mapID"] = 2413, ["npcID"] = 255828, ["x"] = 0.508, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 255828, ["x"] = 0.508, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2393, 2413 }, ["zone"] = { 15355 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 86898 }, ["db2PoiUiMapID"] = 2393, ["db2QuestInfoID"] = 81, ["db2QuestInfoName"] = "Dungeon" },
[93667] = { ["id"] = 93667, ["name"] = "Camp Stonewash", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 90481, 90482, 90483, 90484, 90485, 90486, 90568, 93667 }, ["description"] = "You're not the first strange thing I've seen today. < Scout Zel'kanra shakes her head.> Saw a big, shelled creature along the path to Jan'Alor. Amaxi took a bunch of scouts and went after it. They've been gone a while. Think you could check in on them?", ["objectivesText"] = "Find Amaxi outside Camp Stonewash in Zul'Aman .", ["rewardGold"] = 30900, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3354, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 255852, ["x"] = 0.442, ["y"] = 0.336 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 242388, ["x"] = 0.462, ["y"] = 0.262 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.336 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86657 }, ["nextQuests"] = { 90481 }, ["questLines"] = { { ["id"] = 5905, ["name"] = "Unlikely Friends", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiUiMapID"] = 2437 },
[93668] = { ["id"] = 93668, ["name"] = "An Old Game for a New Age", ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["storyline"] = { 93668 }, ["description"] = "Greetings, . Have you heard of my joint venture with Aethas Sunreaver and Auric Sunchaser? We have been attempting to rekindle interest in an old arcane tournament of stealth versus perception, called Decor Duel. We're currently training new players, so if you'd like to learn the ropes of the game, feel free to meet us in the Decor Duel training area, just west of here. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(93668)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(93668))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Meet up with Aethas Sunreaver, Riftblade Maella, and Auric Sunchaser at the Decor Duel training area.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[93683] = { ["id"] = 93683, ["name"] = "Conditional Objectives - Singular", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16105, ["mapID"] = 2352, ["storyline"] = { 93683 }, ["description"] = "! Glad to see you. The defenders in the fortress could use your help. One of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on. She needs the help of someone who can properly disrupt the robot's attacks so it can be repaired. Do you have a moment to help?", ["objectivesText"] = "Activate Fightbot 11.2.7, then interrupt its abilities with your Felguard or Felhunter 1 times.", ["rewardGold"] = 29200, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16105 } }, ["questType"] = "standard" },
[93687] = { ["id"] = 93687, ["name"] = "Taste True Power", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93687 }, ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["starts"] = { { ["npcID"] = 243229, ["x"] = 0.402, ["y"] = 0.648, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 243229, ["x"] = 0.402, ["y"] = 0.648, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.402, ["y"] = 0.648, ["source"] = "quest_giver", ["mapID"] = 2393 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 2393, ["db2QuestInfoID"] = 282, ["db2QuestInfoName"] = "Important Quest" },
[93690] = { ["id"] = 93690, ["name"] = "Alchemy Services Requested", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93690 }, ["description"] = "Welcome back, <class>. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort. If your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons. Bring back proof of completed orders and I'll see that you're adequately compensated.", ["objectivesText"] = "Fill Alchemy Crafting Orders for the Artisan's Consortium. Progress: Bring back proof of completed orders and I'll see that you're adequately compensated.", ["rewardXP"] = 11765, ["rewardItems"] = { 228773, 245345, 263454 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 243283, ["x"] = 0.45, ["y"] = 0.552 }, { ["mapID"] = 2393, ["npcID"] = 243357, ["x"] = 0.47, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 243283, ["x"] = 0.45, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 93724 }, ["db2DetailThemeID"] = 38 },
[93691] = { ["id"] = 93691, ["name"] = "Blacksmithing Services Requested", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93691 }, ["description"] = "Welcome back, <class>. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort. If your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons. Bring back proof of completed orders and I'll see that you're adequately compensated.", ["objectivesText"] = "Fill Blacksmithing Crafting Orders for the Artisan's Consortium. Progress: Bring back proof of completed orders and I'll see that you're adequately compensate", ["rewardXP"] = 11765, ["rewardItems"] = { 198606, 228774, 245345, 263455 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 241450, ["x"] = 0.437, ["y"] = 0.515 }, { ["mapID"] = 2393, ["npcID"] = 243283, ["x"] = 0.45, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 243283, ["x"] = 0.45, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.437, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 93726 }, ["db2DetailThemeID"] = 33 },
