[93693] = { ["id"] = 93693, ["name"] = "Inscription Services Requested", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93693 }, ["description"] = "Welcome back, <class>. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort. If your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons. Bring back proof of completed orders and I'll see that you're adequately compensated.", ["objectivesText"] = "Fill Inscription Crafting Orders for the Artisan's Consortium. Progress: Bring back proof of completed orders and I'll see that you're adequately compensated.", ["rewardXP"] = 11765, ["rewardItems"] = { 198607, 228776, 245345, 263457 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 243283, ["x"] = 0.45, ["y"] = 0.552 }, { ["mapID"] = 2393, ["npcID"] = 243553, ["x"] = 0.468, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 243283, ["x"] = 0.45, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 93728 }, ["db2DetailThemeID"] = 42 },
[93694] = { ["id"] = 93694, ["name"] = "Jewelcrafting Services Requested", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93694 }, ["description"] = "Welcome back, <class>. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort. If your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons. Bring back proof of completed orders and I'll see that you're adequately compensated.", ["objectivesText"] = "Fill Jewelcrafting Crafting Orders for the Artisan's Consortium. Progress: Bring back proof of completed orders and I'll see that you're adequately compensated.", ["rewardXP"] = 11765, ["rewardItems"] = { 198612, 228777, 245345, 263458 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 243283, ["x"] = 0.45, ["y"] = 0.552 }, { ["mapID"] = 2393, ["npcID"] = 243345, ["x"] = 0.48, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 243283, ["x"] = 0.45, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 93729 }, ["db2DetailThemeID"] = 43 },
[93695] = { ["id"] = 93695, ["name"] = "Leatherworking Services Requested", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93695 }, ["description"] = "Welcome back, <class>. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort. If your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons. Bring back proof of completed orders and I'll see that you're adequately compensated.", ["objectivesText"] = "Fill Leatherworking Crafting Orders for the Artisan's Consortium. Progress: Bring back proof of completed orders and I'll see that you're adequately compensated.", ["rewardXP"] = 11765, ["rewardItems"] = { 198613, 228778, 245345, 263459 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 243283, ["x"] = 0.45, ["y"] = 0.552 }, { ["mapID"] = 2393, ["npcID"] = 243500, ["x"] = 0.432, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 243283, ["x"] = 0.45, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 93731 }, ["db2DetailThemeID"] = 44 },
[93696] = { ["id"] = 93696, ["name"] = "Tailoring Services Requested", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93696 }, ["description"] = "Welcome back, <class>. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort. If your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons. Bring back proof of completed orders and I'll see that you're adequately compensated.", ["objectivesText"] = "Fill Tailoring Crafting Orders for the Artisan's Consortium. Progress: Bring back proof of completed orders and I'll see that you're adequately compensated.", ["rewardXP"] = 11765, ["rewardItems"] = { 198609, 228779, 245345, 263460 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 243283, ["x"] = 0.45, ["y"] = 0.552 }, { ["mapID"] = 2393, ["npcID"] = 243352, ["x"] = 0.482, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 243283, ["x"] = 0.45, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 93730 }, ["db2DetailThemeID"] = 37 },
[93697] = { ["id"] = 93697, ["name"] = "Shimmering Melodies", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93697 }, ["description"] = "Have you heard it? The magic of Eversong. It emanates a subtle melody, if you listen closely enough. The complex interwoven strands of magic move against each other and create a beautiful harmony. The dust distilled from such magic is exceptionally potent. Bring some to me and I will show you its uses.", ["objectivesText"] = "Collect 20 Eversinging Dust and deliver it to Dolothos in Silvermoon. Progress: Have you collected the dust?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 243599, 245345, 263464 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 243349, ["x"] = 0.479, ["y"] = 0.536 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 243349, ["x"] = 0.479, ["y"] = 0.536 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.479, ["y"] = 0.536 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 40, ["db2LabelIDs"] = { 5881, 6079 } },
[93698] = { ["id"] = 93698, ["name"] = "Splintered Radiance", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93698 }, ["description"] = "When captured at just the right moment, the power exuding from an object can be crystallized into splinters of raw magical energy. The result is dazzling, like beams of sunlight splitting as they stream through a window. Bring me some of these shards. My work cannot continue without them.", ["objectivesText"] = "Collect 10 Radiant Shards and deliver it to Dolothos in Silvermoon. Progress: A few shards should be sufficient.", ["rewardGold"] = 319000, ["rewardXP"] = 11765, ["rewardItems"] = { 243602, 245345, 263464 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 243349, ["x"] = 0.479, ["y"] = 0.536 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 243349, ["x"] = 0.479, ["y"] = 0.536 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.479, ["y"] = 0.536 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 40, ["db2LabelIDs"] = { 5881, 6079 } },
[93699] = { ["id"] = 93699, ["name"] = "A Ray of Sunlight", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93699 }, ["description"] = "There is great magic in the dawn. It illuminates and awakens all it falls upon, rousing the land to action. It is potential in its purest form. As enchanters, we can crystallize that potential. Bring a parcel of the dawn to me.", ["objectivesText"] = "Collect 1 Dawn Crystal and deliver it to Dolothos in Silvermoon. Progress: Have you succeeded?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 243605, 245345, 263464, 267653 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 243349, ["x"] = 0.479, ["y"] = 0.536 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 243349, ["x"] = 0.479, ["y"] = 0.536 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.479, ["y"] = 0.536 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 40, ["db2LabelIDs"] = { 5881, 6079 } },
[93700] = { ["id"] = 93700, ["name"] = "Experience Tranquility", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93700 }, ["description"] = "Are you an herbalist? Oh, thank goodness. I've found myself in need of an exorbitant amount of tranquility bloom . The orders from the alchemists keep piling up and I only just finished restocking our argentleaf and-- <Nathera stops to take a deep breath.> Could you please bring me as much tranquility bloom as you can carry? I'd be in your debt.", ["objectivesText"] = "Collect 20 Tranquility Bloom and deliver it to Botanist Nathera in Silvermoon. Progress: Have you found any tranquility bloom ?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 236761, 245345, 263462 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 243355, ["x"] = 0.482, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 243355, ["x"] = 0.482, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 34, ["db2LabelIDs"] = { 5881, 6080 } },
[93701] = { ["id"] = 93701, ["name"] = "Brittle and Brilliant", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["description"] = "Argentleaf is always in high demand whenever war draws near. It practically falls apart when you dry it out, but that powder can be used in a variety of medicines. It calms the nerves, focuses the mind, and can even work as a mild anesthetic in a pinch. If you find any out in the field, please bring it to me.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 263462, 245345 }, ["starts"] = { { ["npcID"] = 243355, ["x"] = 0.482, ["y"] = 0.514, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 243355, ["x"] = 0.482, ["y"] = 0.514, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.482, ["y"] = 0.514, ["source"] = "quest_giver", ["mapID"] = 2393 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[93702] = { ["id"] = 93702, ["name"] = "The Root of Life", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93702 }, ["description"] = "Most tuberous roots have some sort of healing potential, but azeroot is by far the most potent and versatile. Just a small amount, juiced or powdered, can stave off infections, promote healing, and soothe both body and mind. I've even seen it used to keep lumber from rotting! If you could bring me a few bushels, I'll put it to good use.", ["objectivesText"] = "Collect 3 Azeroot and deliver it to Botanist Nathera in Silvermoon. Progress: Were you able to track down any azeroot ?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 236774, 263462, 245345 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 243355, ["x"] = 0.482, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 243355, ["x"] = 0.482, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 34, ["db2LabelIDs"] = { 5881, 6080 } },
[93703] = { ["id"] = 93703, ["name"] = "Sin'dorei Vices", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93703 }, ["description"] = "While most of our harvests supply the scribes and alchemists in the city, we do occasionally receive orders from the public. Lord Saltheril is one of our most prolific customers. He has an estate in western Eversong that he keeps well-supplied with offerings for guests at his soirees. He has requested a large quantity of mana lilies and sanguithorn this week. Could you help us fulfill the order?", ["objectivesText"] = "Collect 5 Mana Lilies and 2 Sanguithorn and deliver it to Botanist Nathera in Silvermoon. Progress: Lord Saltheril's business is always welcome, even if a bit eccentric.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 236770, 236778, 245345, 263462 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 243355, ["x"] = 0.482, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 243355, ["x"] = 0.482, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 34, ["db2LabelIDs"] = { 5881, 6080 } },
[93704] = { ["id"] = 93704, ["name"] = "Traditional Harvests", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93704 }, ["description"] = "Tranquility bloom and argentleaf are the backbone of countless potions, elixirs, inks, and so much more. It never hurts to keep a surplus around. If you find yourself with any extra, we would gladly take it off your hands.", ["objectivesText"] = "Collect 10 Tranquility Blooms and 5 Argentleaf and deliver it to Botanist Nathera in Silvermoon. Progress: We'll take whatever you can offer.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 236761, 236776, 245345, 263462 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 243355, ["x"] = 0.482, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 243355, ["x"] = 0.482, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 34, ["db2LabelIDs"] = { 5881, 6080 } },
[93705] = { ["id"] = 93705, ["name"] = "Copper for Your Thoughts?", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93705 }, ["description"] = "It's easy to overlook in favor of more extravagant materials, but copper is an extremely reliable and versatile material. Weapons, armor, wiring, jewelry, and of course the humble copper coin--it does it all! Naturally, copper is always in high demand across the city and beyond. If you happen across any extra ore, I would gladly take it off your hands.", ["objectivesText"] = "Collect 20 Refulgent Copper Ore and deliver it to Belil in Silvermoon. Progress: You know, I wrote my thesis on the uses of copper. Have you read it?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 237359, 263463, 245345 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 241455, ["x"] = 0.426, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 241455, ["x"] = 0.426, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 45, ["db2LabelIDs"] = { 5881, 6082 } },
[93706] = { ["id"] = 93706, ["name"] = "Aggressive Tin-dencies", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93706 }, ["description"] = "There's been an influx of newly recruited soldiers lately. Marvelous fighters in the making, but a little too enthusiastic. They've already done a number on the stock of training weapons. We usually make training weapons out of tin or other soft metals. They keep the recruits from doing real damage to the training dummies or each other, but they don't last long. We'll need a lot more tin than what we have in stock to keep up. Bring us some more!", ["objectivesText"] = "Collect 10 Umbral Tin Ore and deliver it to Belil in Silvermoon. Progress: Anything you can contribute will be appreciated.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 237362, 245345, 263463 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 241455, ["x"] = 0.426, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 241455, ["x"] = 0.426, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 45, ["db2LabelIDs"] = { 5881, 6082 } },
[93707] = { ["id"] = 93707, ["name"] = "It's Called Silvermoon", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93707 }, ["description"] = "Elegant gold filigree may be a favorite of the sin'dorei, but our city also boasts some of the finest silversmiths in Azeroth. They have been receiving a particularly high number of orders with all of the new visitors passing through. If you come across any high-quality silver, they can put it to good use.", ["objectivesText"] = "Collect 10 Brilliant Silver Ore and deliver it to Belil in Silvermoon. Progress: I have a certain fondness for silver myself, truth be told.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 237364, 263463, 245345 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 241455, ["x"] = 0.426, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 241455, ["x"] = 0.426, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 45, ["db2LabelIDs"] = { 5881, 6082 } },
[93708] = { ["id"] = 93708, ["name"] = "Conductive Metals", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93708 }, ["description"] = "Our arcane constructs might look purely magical, but there's quite a bit of advanced wiring going on beneath the surface. Silvermoon's engineers truly are spell-workers in their own right. They've been ramping up production lately to help fortify our defenses. Naturally, they look to us for supplies. I have most of the materials they ordered, but I'm low on tin and silver. Could you help me fulfill the order?", ["objectivesText"] = "Collect 5 Umbral Tin Ore and 5 Brilliant Silver Ore and deliver it to Belil in Silvermoon. Progress: Tin and silver are both remarkably conductive. I could elaborate, if you have a few hours?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 237362, 237364, 263463, 245345 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 241455, ["x"] = 0.426, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 241455, ["x"] = 0.426, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 45, ["db2LabelIDs"] = { 5881, 6082 } },
[93709] = { ["id"] = 93709, ["name"] = "Stocking the Staples", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93709 }, ["description"] = "One can never have too much copper and thorium on hand. Even with all the new miners we brought on, we still nearly deplete our stocks every week. At this rate, we'll have to start importing--and I do not want the headache that sort of paperwork brings. If you could help us replenish our stock of copper and thorium, I would be in your debt.", ["objectivesText"] = "Collect 10 Refulgent Copper Ore and 2 Dazzling Thorium and deliver it to Belil in Silvermoon. Progress: I suppose I could bring on a few more apprentices, if I have to...", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 237359, 237366, 245345, 263463 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 241455, ["x"] = 0.426, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 241455, ["x"] = 0.426, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 45, ["db2LabelIDs"] = { 5881, 6082 } },
[93710] = { ["id"] = 93710, ["name"] = "Tempered in Darkness", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93710 }, ["description"] = "The beasts of Quel'Thalas produce leather of unparalleled quality, but the Void has been doing something strange to it. Normally, we harden leather by heating it under specific conditions. But the darkness clinging to these hides seems to be tempering the leather on its own. I have no idea how this is possible, but we can make use of it. Bring me as much as you can gather. We have an army to supply.", ["objectivesText"] = "Collect 20 Void-Tempered Leather and deliver it to Tyn in Silvermoon. Progress: We'll find a use for any leather you can bring us.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 238511, 245345, 263461 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 243527, ["x"] = 0.432, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 243527, ["x"] = 0.432, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 36, ["db2LabelIDs"] = { 5881, 6083 } },
[93711] = { ["id"] = 93711, ["name"] = "The Chill of the Void", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93711 }, ["description"] = "When we mobilized troops to Northrend many years ago, we had to outfit our soldiers to withstand the icy chill of the frozen wastes. The secret is lining the inside of the armor with fur and plating it securely to trap warmth inside. We kept detailed records of those techniques. The Void may not be as cold as Northrend, but I'd rather be prepared for the worst. Bring me a supply of fur and plating and I'll see you compensated.", ["objectivesText"] = "Collect 5 Fantastic Fur and 2 Void-Tempered Plating and deliver it to Tyn in Silvermoon. Progress: As an added benefit, the fur prevents quite a bit of chafing.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 238520, 238525, 263461, 245345 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 243527, ["x"] = 0.432, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 243527, ["x"] = 0.432, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 36, ["db2LabelIDs"] = { 5881, 6083 } },
[93712] = { ["id"] = 93712, ["name"] = "Style and Skill", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93712 }, ["description"] = "In battle, appearances are nearly as important as raw skill. If you can intimidate your foe before you've even drawn your sword, you're already that much closer to victory. Our fletchers take this a step further and insist that beautiful feathers make our Farstriders' arrows do more damage. I'm... not certain about that, but I can appreciate the aesthetic. Here's a list of what they need for this week's batch of arrows. Supply whatever you can and I'll handle the rest.", ["objectivesText"] = "Collect 5 Carving Canines and 5 Peerless Plumage and deliver it to Tyn in Silvermoon. Progress: You can ignore the note about whether the feathers should be crimson or scarlet.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 238522, 238523, 263461, 245345 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 243527, ["x"] = 0.432, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 243527, ["x"] = 0.432, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 36, ["db2LabelIDs"] = { 5881, 6083 } },
[93713] = { ["id"] = 93713, ["name"] = "Essential Materials", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93713 }, ["description"] = "The Horde's penchant for teeth and animal pelts has worn off on some sin'dorei. It's not uncommon in recent years to receive bulk orders for both. This is one of those times. If you have any spare hides, or come across any particularly sharp teeth in your hunts, I'd gladly trade you for them.", ["objectivesText"] = "Collect 5 Carving Canines and 2 Void-Tempered Hides and deliver it to Tyn in Silvermoon.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 263461, 245345, 238518, 238523 }, ["starts"] = { { ["npcID"] = 243527, ["x"] = 0.432, ["y"] = 0.556, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 243527, ["x"] = 0.432, ["y"] = 0.556, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.432, ["y"] = 0.556, ["source"] = "quest_giver", ["mapID"] = 2393 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 36, ["db2LabelIDs"] = { 5881, 6083 } },
[93714] = { ["id"] = 93714, ["name"] = "Minor Scales", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93714 }, ["description"] = "A well-made suit of scalemail is a sight to behold. It requires quite a bit of patience and attention to fine detail, but Silvermoon's leatherworkers are masters of the craft. If you happen to hunt any scaled beasts, we could use those materials. A large quantity of smaller sized ones, if you could--they layer more nicely in the armor.", ["objectivesText"] = "Collect 20 Void-Tempered Scales and deliver it to Tyn in Silvermoon. Progress: Scales are a bit harder to come by than regular leather, but the end result is well worth it.", ["rewardGold"] = 315900, ["rewardXP"] = 11765, ["rewardItems"] = { 238513, 245345, 263461 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 243527, ["x"] = 0.432, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 243527, ["x"] = 0.432, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 36, ["db2LabelIDs"] = { 5881, 6083 } },
[93716] = { ["id"] = 93716, ["name"] = "Learning the Cloaks - Part 1", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93716 }, ["series"] = { 93774 }, ["description"] = "In this game of Decor Duel, one side uses illusion to disguise themselves as, and hide amongst, everyday objects in the area. The other side uses pre-approved lists of illusion-piercing abilities to find and then capture those hiding cloaked in disguise. At the end of the round, the teams switch roles, so each side has a chance to hide and seek. Time for you to try! This armchair has been enchanted to cloak you with its disguise. Don its appearance, then change your disguise a few times.", ["objectivesText"] = "Interact with the armchair to become disguised, then use its Disguise ability a few times, then speak with Captain Auric Sunchaser . Progress: Touch this armchair, to don its disguise...", ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 255368, ["x"] = 0.275, ["y"] = 0.765 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 255370, ["x"] = 0.275, ["y"] = 0.765 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.275, ["y"] = 0.765 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 93774 } },
[93717] = { ["id"] = 93717, ["name"] = "Learning the Cloaks - Part 2", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93717 }, ["description"] = "When disguised, you will have the ability to magically teleport yourself to a nearby piece of decor. Pick up the chair's disguise again, and this time try swapping your location a few times. Feel free to change your disguise between swaps if you'd like.", ["objectivesText"] = "Pick up the Chair's disguise to test out its Swap ability, then speak with Aethas Sunreaver . Progress: Use the disguise chair to swap with other decor, then return to me.", ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 255370, ["x"] = 0.275, ["y"] = 0.765 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 255365, ["x"] = 0.275, ["y"] = 0.77 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.275, ["y"] = 0.765 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 93716 } },
[93719] = { ["id"] = 93719, ["name"] = "Nothing Captured, Nothing Gained", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93719 }, ["description"] = "There are three Seeker classes in Decor Duel, but everyone starts off with the Spellbreaker kit. Don't worry, you can earn access to the others. Some fundamentals. You can break the shield of a disguised hider's illusion by using Dispell Magic. Once the hider has been marked as Found, you'll have a brief window to Tag them, taking them out of the match. My statue has been enchanted to outfit you with a Spellbreaker kit. Once outfitted, use Dispell Magic to find and tag decoys hiding around here.", ["objectivesText"] = "Interact with the statue to become outfitted with a Spellbreaker Kit, use the Dispelling Focus to \"Find\" hiders, then \"Tag\" them. Progress: Use my statue, then find and tag hiders with the Spellbreaker's Dispel Magic and Tag.", ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 255365, ["x"] = 0.275, ["y"] = 0.77 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 255365, ["x"] = 0.275, ["y"] = 0.77 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.275, ["y"] = 0.77 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 93717 } },
[93723] = { ["id"] = 93723, ["name"] = "Crafters Needed", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93723 }, ["description"] = "Greetings. Come to lend a hand? The war effort has been taxing on Silvermoon's resources. We need to keep our soldiers armed and supplied, but even our seasoned crafters have been overwhelmed. To keep up with demand, we have struck a deal with the Artisan's Consortium. If you have your own skills to offer, speak to Mar'nah . She can help you view and place crafting orders.", ["objectivesText"] = "Talk to Mar'nah in the Bazaar. Progress: Have you talked to Mar'nah ?", ["rewardGold"] = 34100, ["rewardXP"] = 1470, ["rewardItems"] = { 236761, 236776, 236778, 236963, 237359, 237362, 237364, 238511, 238513, 243599, 243602, 251321, 251322, 251324, 251326, 251327 }, ["rewardChoices"] = { 251321, 251322, 251324, 251326, 251327 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 243283, ["x"] = 0.45, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 243283, ["x"] = 0.45, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[93724] = { ["id"] = 93724, ["name"] = "Crafting Orders: Alchemy", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93724 }, ["description"] = "Ah, you're an alchemist? You should speak with Camberon . He's a skilled alchemist who runs a shop here in Silvermoon. Camberon has a work table at his shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission. Seek him out and see what work is available for you.", ["objectivesText"] = "Find Camberon in the Bazaar and use his Alchemist's Lab Bench . Progress: The work orders never stop piling up. I'd be glad to have some extra help.", ["rewardGold"] = 34100, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 243283, ["x"] = 0.45, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 243357, ["x"] = 0.47, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 93723 } },
[93726] = { ["id"] = 93726, ["name"] = "Crafting Orders: Blacksmithing", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93726 }, ["description"] = "Ah, you're a blacksmith? You should speak with Bemarrin . He's a skilled blacksmith who runs a shop here in Silvermoon. Bemarrin has a work table at his shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission. Seek him out and see what work is available for you.", ["objectivesText"] = "Find Bemarrin in the Bazaar and use his Blacksmith's Table . Progress: The work orders never stop piling up. I'd be glad to have some extra help.", ["rewardGold"] = 34100, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 243283, ["x"] = 0.45, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 241450, ["x"] = 0.437, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 93723 } },
[93727] = { ["id"] = 93727, ["name"] = "Crafting Orders: Engineering", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93727 }, ["description"] = "Ah, you're an engineer? You should speak with Danwe . She's a skilled engineer who runs a shop here in Silvermoon. Danwe has a work table at her shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission. Seek her out and see what work is available for you.", ["objectivesText"] = "Find Danwe in the Bazaar and use her Tinker's Workbench . Progress: The work orders never stop piling up. I'd be glad to have some extra help.", ["rewardGold"] = 34100, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 243283, ["x"] = 0.45, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 241452, ["x"] = 0.435, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 93723 } },
[93728] = { ["id"] = 93728, ["name"] = "Crafting Orders: Inscription", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93728 }, ["description"] = "Ah, you're a scribe? You should speak with Zantasia . She's a skilled scribe who runs a shop here in Silvermoon. Zantasia has a work table at her shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission. Seek her out and see what work is available for you.", ["objectivesText"] = "Find Zantasia in the Bazaar and use her Scribe's Drafting Table . Progress: The work orders never stop piling up. I'd be glad to have some extra help.", ["rewardGold"] = 34100, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 243283, ["x"] = 0.45, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 243553, ["x"] = 0.468, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 93723 } },
[93729] = { ["id"] = 93729, ["name"] = "Crafting Orders: Jewelcrafting", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93729 }, ["description"] = "Ah, you're a jewelcrafter? You should speak with Amin . He's a skilled alchemist who runs a shop here in Silvermoon. Amin has a work table at his shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission. Seek him out and see what work is available for you.", ["objectivesText"] = "Find Amin in the Bazaar and use his Jeweler's Bench . Progress: The work orders never stop piling up. I'd be glad to have some extra help.", ["rewardGold"] = 31200, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 243283, ["x"] = 0.45, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 243345, ["x"] = 0.48, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 93723 } },
[93730] = { ["id"] = 93730, ["name"] = "Crafting Orders: Tailoring", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93730 }, ["description"] = "Ah, you're a tailor? You should speak with Galana . She's a skilled tailor who runs a shop here in Silvermoon. Galana has a work table at her shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission. Seek her out and see what work is available for you.", ["objectivesText"] = "Find Galana in the Bazaar and use her Tailor's Work Table . Progress: The work orders never stop piling up. I'd be glad to have some extra help.", ["rewardGold"] = 34100, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 243283, ["x"] = 0.45, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 243352, ["x"] = 0.482, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 93723 } },
[93731] = { ["id"] = 93731, ["name"] = "Crafting Orders: Leatherworking", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93731 }, ["description"] = "Ah, you're a leatherworker? You should speak with Talmar . He's a skilled leatherworker who runs a shop here in Silvermoon. Talmar has a work table at his shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission. Seek him out and see what work is available for you.", ["objectivesText"] = "Find Talmar in the Bazaar and use his Leatherworker's Tool Bench . Progress: The work orders never stop piling up. I'd be glad to have some extra help.", ["rewardGold"] = 34100, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 243283, ["x"] = 0.45, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 243500, ["x"] = 0.432, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 93723 } },
[93734] = { ["id"] = 93734, ["name"] = "Precious Trinkets", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 91747, 91748, 91749, 91750, 91813, 93734 }, ["description"] = "Finally we get to see what treasures Groffa was hoarding. < Furgh 's eyes go black as he looks at the bag. The drool on his jowls turns to foam and his claws dig into the sides of the bag as his grip on it tightens.> Maybe the loa speaker's gifts aren't so bad. We should not be so hasty. I'll take a look. You watch and keep me safe.", ["objectivesText"] = "Keep Furgh safe and investigate the treasures. Progress: Whatever Groffa had is bad. Right?", ["rewardGold"] = 169100, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 248121, ["x"] = 0.414, ["y"] = 0.8 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 256101, ["x"] = 0.414, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.414, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91749 }, ["questLines"] = { { ["id"] = 5971, ["name"] = "The Voice of Nalorakk", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[93744] = { ["id"] = 93744, ["name"] = "Unity Against the Void", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 11, ["mapID"] = 2393, ["storyline"] = { 93744 }, ["rewardItems"] = { 251039, 253629 }, ["starts"] = { { ["x"] = 0.49, ["y"] = 0.646, ["mapID"] = 2393 } }, ["ends"] = { { ["x"] = 0.49, ["y"] = 0.646, ["mapID"] = 2393 } }, ["coords"] = { ["mapID"] = 2393, ["x"] = 0.49, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiUiMapID"] = 2393, ["db2QuestInfoID"] = 284, ["db2QuestInfoName"] = "Meta Quest" },
[93745] = { ["id"] = 93745, ["name"] = "Har'athir, Village of Memory", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 93745 }, ["description"] = "You have been permitted to range about beneath our Goddess' light. But that doesn't mean we trust you out of hand. If you wish to prove yourself a friend to the haranir, make yourself useful in Har'athir. It is there that we make the paints for our murals and watch over the newest roots to seek the Goddess' light.", ["objectivesText"] = "Meet Rootwarden Ku'paal in Har'athir.", ["rewardGold"] = 30900, ["rewardXP"] = 1520, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 256245, ["x"] = 0.542, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237331, ["x"] = 0.7, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86930 } },
[93751] = { ["id"] = 93751, ["name"] = "Windrunner Spire", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93751 }, ["description"] = "Former home of the Windrunners... now desecrated beyond thought. Since the Scourge invasion, the spire houses our greatest nightmares: banshees, abominations, hateful spirits. There is no redeeming such a place, but perhaps we may help lay the tormented to rest.", ["objectivesText"] = "Complete the Windrunner Spire dungeon on any difficulty.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 251080, 251082, 251084, 251085, 251086, 251089, 251092, 251096, 251098 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 256210, ["x"] = 0.49, ["y"] = 0.646 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256210, ["x"] = 0.49, ["y"] = 0.646 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "dungeon", ["db2LabelIDs"] = { 4887 }, ["db2PoiUiMapID"] = 2393, ["db2QuestInfoID"] = 81, ["db2QuestInfoName"] = "Dungeon" },
[93752] = { ["id"] = 93752, ["name"] = "Murder Row", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93752 }, ["description"] = "I've always disagreed with Lor'themar about the existence of Murder Row. But I guess like any forest, a city should and will have its secrets. Though recently, Lor'themar has expressed concern about rising fel activity in the area. With the majority of Silvermoon's watch on the Voidstorm, many folks are testing boundaries, taking advantage, making a play for power... You have my permission to investigate and crush any such illegal activities.", ["objectivesText"] = "Complete the Murder Row dungeon on any difficulty. Progress: More reports of fel activity come in daily. Silvermoon is at risk, I fear. I hope you're on the case..", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 251132, 251136, 251142 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 256210, ["x"] = 0.49, ["y"] = 0.646 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256210, ["x"] = 0.49, ["y"] = 0.646 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "dungeon", ["db2LabelIDs"] = { 4887 }, ["db2PoiUiMapID"] = 2393, ["db2QuestInfoID"] = 81, ["db2QuestInfoName"] = "Dungeon" },
[93753] = { ["id"] = 93753, ["name"] = "Magisters' Terrace", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93753 }, ["description"] = "Powerful monsters of the void have taken over Magister's Terrace! These halls contain untold amounts of knowledge and arcane power. We cannot lose any of it to our enemy. Clear the voidspawns and their masters. You'll likely have to solve the terrace's defenses as well, which are designed to prevent and shutdown unauthorized access at any cost.", ["objectivesText"] = "Complete the Magisters' Terrace dungeon on any difficulty. Progress: If the Void gains access to Silvermoon's most exclusive repository of magic... Rommath will throw a fit of epic proportions.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 3316, 3354, 3365, 3370, 3389, 251103, 251104, 251108, 251115, 251118, 260312 }, ["rewardChoices"] = { 3316, 3354, 3365, 3370, 3389 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 256210, ["x"] = 0.49, ["y"] = 0.646 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256210, ["x"] = 0.49, ["y"] = 0.646 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "dungeon", ["db2LabelIDs"] = { 4887 }, ["db2PoiUiMapID"] = 2393, ["db2QuestInfoID"] = 81, ["db2QuestInfoName"] = "Dungeon" },
[93754] = { ["id"] = 93754, ["name"] = "Maisara Caverns", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93754 }, ["description"] = "While Lady Liadrin was in Zul'Aman, she took note of one tribe, the Vilebranch, brutalizing the other forest trolls and their loa. They live up to their name by wanton use of necromancy. Enter their caverns and put a stop to their black magic!", ["objectivesText"] = "Complete the Maisara Caverns dungeon on any difficulty. Progress: The Vilebranch usage of magic reeks of undead teachings... and I know that never ends well.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 3316, 3354, 3365, 3370, 3389, 251161, 251164, 251166, 251167, 251169, 251170, 251172, 251176, 251177 }, ["rewardChoices"] = { 3316, 3354, 3365, 3370, 3389 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 256210, ["x"] = 0.49, ["y"] = 0.646 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256210, ["x"] = 0.49, ["y"] = 0.646 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "dungeon", ["db2LabelIDs"] = { 4887 }, ["db2PoiUiMapID"] = 2393, ["db2QuestInfoID"] = 81, ["db2QuestInfoName"] = "Dungeon" },
[93755] = { ["id"] = 93755, ["name"] = "Den of Nalorakk", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93755 }, ["description"] = "A trial of skill and strength... I'd go myself if I wasn't needed in Silvermoon. Good luck, champion. I look forward to hearing about your victory against the Amani Loa of War.", ["objectivesText"] = "Complete the Den of Nalorakk dungeon on any difficulty. Progress: Didn't chicken out, did you? It's okay, your fear is not unfounded. Bears are the kings of nature. They'll mess you up.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 3354, 3365, 3370, 3389, 251144, 251146, 251148, 251155, 251160, 251173, 264479, 264480, 264481 }, ["rewardChoices"] = { 3354, 3365, 3370, 3389 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 256210, ["x"] = 0.49, ["y"] = 0.646 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256210, ["x"] = 0.49, ["y"] = 0.646 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "dungeon", ["db2LabelIDs"] = { 4887 }, ["db2PoiUiMapID"] = 2393, ["db2QuestInfoID"] = 81, ["db2QuestInfoName"] = "Dungeon" },
[93756] = { ["id"] = 93756, ["name"] = "The Blinding Vale", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93756 }, ["description"] = "This place in Harandar is the Lightbloom's epicenter. Orweyna did what she could, which was much, but we must strike at the taproot of all roots for the plant to die. Be on your guard, even if you think yourself experienced with the Lightbloom by now. The vale is different from the rampant, but ultimately wild growth in Eversong. It's a calculated force of nature led by a Rootwarden who seeks to strangle you and everything else it desires.", ["objectivesText"] = "Complete The Blinding Vale dungeon on any difficulty. Progress: Learn what you can from the Lightbloom in Eversong, but beware this may be an entirely different set of problems. The Rootwarden will be expecting intruders such as yourself.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 251183, 251185, 251190, 251194, 251197, 251200 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 256210, ["x"] = 0.49, ["y"] = 0.646 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256210, ["x"] = 0.49, ["y"] = 0.646 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "dungeon", ["db2LabelIDs"] = { 4887 }, ["db2PoiUiMapID"] = 2393, ["db2QuestInfoID"] = 81, ["db2QuestInfoName"] = "Dungeon" },
[93757] = { ["id"] = 93757, ["name"] = "Voidscar Arena", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93757 }, ["description"] = "If I didn't know that the domanaar thirst for battle, and all the pain and strife that comes with it, I'd say this is trap. Either way, I suppose it's an invitation to get yourself killed. If you insist on participating in the Void's fighting games, I can't stop you. Just don't hesitate to kill as many voidspawn as possible while you're there, okay?", ["objectivesText"] = "Complete the Voidscar Arena dungeon on any difficulty. Progress: May your arrows strike true, champion.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 251221, 251222, 251228, 251234, 251235, 252258 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 256210, ["x"] = 0.49, ["y"] = 0.646 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256210, ["x"] = 0.49, ["y"] = 0.646 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "dungeon", ["db2LabelIDs"] = { 4887 }, ["db2PoiUiMapID"] = 2393, ["db2QuestInfoID"] = 81, ["db2QuestInfoName"] = "Dungeon" },
[93758] = { ["id"] = 93758, ["name"] = "Nexus-Point Xenas", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93758 }, ["description"] = "We must continue to keep an eye on this overpowered facility. If breached, disaster will spread beyond the Voidstorm. Unfortunately this magical and mechanical complex is beyond my area of expertise. Prepare yourself, and ensure that the Nexus-Point Xenas remains dormant.", ["objectivesText"] = "Complete the Nexus-Point Xenas dungeon on any difficulty. Progress: If the Nexus-Point is overloaded, it'll be a very quick death for many. Let's not entertain that thought any further. Secure the facility!", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 251093, 251206, 251217, 262606 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 256210, ["x"] = 0.49, ["y"] = 0.646 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256210, ["x"] = 0.49, ["y"] = 0.646 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "dungeon", ["db2LabelIDs"] = { 4887 }, ["db2PoiUiMapID"] = 2393, ["db2QuestInfoID"] = 81, ["db2QuestInfoName"] = "Dungeon" },
[93766] = { ["id"] = 93766, ["name"] = "Midnight: World Quests", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93766 }, ["description"] = "The Void seeks to divide us, to drive a wedge between kin and kingdom alike. We cannot allow it. Everywhere I turn, I hear of those struggling--families displaced, defenders overwhelmed, healers stretched thin. No blade nor spell alone will turn this tide, but the strength of many hearts united can. Go forth and lend your aid where it is needed most.", ["objectivesText"] = "Complete World Quests in Midnight. Progress: With your aid, will can bring all our people closer together.", ["rewardGold"] = 683200, ["rewardXP"] = 20540, ["rewardItems"] = { 254677, 268490 }, ["starts"] = { { ["x"] = 0.49, ["y"] = 0.646, ["mapID"] = 2393 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256203, ["x"] = 0.49, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 6072 } },
[93767] = { ["id"] = 93767, ["name"] = "Midnight: Arcantina", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93767 }, ["description"] = "The Arcantina welcomes all who seek respite. Step inside its lively halls, share a brew, and trade stories with friends old and new. Where the Void brings chill and silence, here you'll find warmth, laughter, and the spark of fellowship.", ["objectivesText"] = "Visit the Arcantina and have a brew with one of the patrons. Progress: We all need a moment away from the battle now and again.", ["rewardGold"] = 683200, ["rewardXP"] = 20540, ["rewardItems"] = { 251039, 253629, 254677, 268490 }, ["starts"] = { { ["x"] = 0.49, ["y"] = 0.646, ["mapID"] = 2393 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256203, ["x"] = 0.49, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 6072 } },
[93769] = { ["id"] = 93769, ["name"] = "Midnight: Housing", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93769 }, ["description"] = "A strong community is built not by walls, but by the hands and hearts of those within it. Lend your voice, your time, and your spirit to the neighborhood. Help your fellows, share in their burdens, and take your place as an active part of the home we build together.", ["objectivesText"] = "Participate in neighborhood Endeavors and collect Community Coupons.", ["rewardGold"] = 683200, ["rewardXP"] = 20540, ["rewardItems"] = { 254677, 268490, 279527, 279575 }, ["starts"] = { { ["x"] = 0.49, ["y"] = 0.646, ["mapID"] = 2393 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256203, ["x"] = 0.49, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 6072 } },
[93771] = { ["id"] = 93771, ["name"] = "Har'kuai, Village of Rain", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 93771 }, ["description"] = "All waters in Harandar are sacred. They feed the roots of the world and Aln'hara's myriad creations in equal measure. Perhaps none are more spectacular than those that fall from the roots of the tree called Nordrassil. To the north, you will find Har'kuai. The rains that fall from the sky there carry a remarkable vitality. If you wish to witness all of Aln'hara's majesties, then a trek to Har'kuai would serve you well.", ["objectivesText"] = "Meet Rootwarden Kamari in Har'kuai.", ["rewardGold"] = 34100, ["rewardXP"] = 1520, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 256313, ["x"] = 0.51, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 256322, ["x"] = 0.652, ["y"] = 0.264 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86930 } },
[93774] = { ["id"] = 93774, ["name"] = "When is a Chair not for Sitting?", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93774 }, ["series"] = { 93716 }, ["description"] = "Aethas Sunreaver, Riftblade Maella , and Auric Sunchaser have recently revitalized an old arcane twist on hide and seek called Decor Duel. They're looking for new participants to help spread the entertainment. You should meet them over in Falconwing Square.", ["objectivesText"] = "Speak with Riftblade Maella in Falconwing Square.", ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 256307, ["x"] = 0.4935, ["y"] = 0.64725 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 255368, ["x"] = 0.275, ["y"] = 0.765 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.4935, ["y"] = 0.64725 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[93775] = { ["id"] = 93775, ["name"] = "Har'mara, Village of Balance", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 93775 }, ["description"] = "Ah! The outsider who saved Har'mara. Word travels fast through Aln'hara's roots. No doubt Elder Hagar was grateful for your aid. She would never admit it, but things have been difficult since the roots above her village burned. The rutaani and fungarians each grow bolder in their eccentricities. And the lingering flare-ups on Teldrassil's roots present a constant threat. If your travels afford another trip to Har'mara, I do not doubt she would benefit from additional help.", ["objectivesText"] = "Return to Hagar in Har'kuai.", ["rewardGold"] = 32800, ["rewardXP"] = 1520, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 256350, ["x"] = 0.508, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237572, ["x"] = 0.348, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86930 } },
[93776] = { ["id"] = 93776, ["name"] = "Har'alnor, Village of Twilight", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 93776 }, ["description"] = "Our efforts in the Blinding Bloom have halted the Lightbloom's encroachment for now. But with Rootwarden Ruia gone, there are scarce few who remain to handle the rest of the village's troubles. I'm going back to Har'alnor to help out where I can. If you have the time and the inclination, your further assistance would be most appreciated.", ["objectivesText"] = "Meet with Hannan in Har'alnor.", ["rewardGold"] = 33500, ["rewardXP"] = 1520, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 241655, ["x"] = 0.318, ["y"] = 0.765 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 241629, ["x"] = 0.317, ["y"] = 0.631 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.318, ["y"] = 0.765 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86877, 86880, 86881 } },
[93782] = { ["id"] = 93782, ["name"] = "Conditional - Multiple Objectives, Sequenced", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "none", ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14998, ["storyline"] = { 93782 }, ["description"] = "I be sent out here ta prove dat I can be an amani warrior. Dis trial needs me ta collect as many trophies from dese gnarldin as possible. De two of us should work together! I be helpin' you get recognized as an amani warrior, yeah? Just go out dere and get as many trophies from de gnarldin as possible. I be stayin' behind ta watch our backs, eh?", ["objectivesText"] = "Recover 1 trophies from gnarldin and their allies.", ["rewardGold"] = 309800, ["rewardXP"] = 12170, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14998 } }, ["questType"] = "standard" },
[93783] = { ["id"] = 93783, ["name"] = "Conditional - Just One Objective", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "none", ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 14998, ["storyline"] = { 93783 }, ["description"] = "I be sent out here ta prove dat I can be an amani warrior. Dis trial needs me ta collect as many trophies from dese gnarldin as possible. De two of us should work together! I be helpin' you get recognized as an amani warrior, yeah? Just go out dere and get as many trophies from de gnarldin as possible. I be stayin' behind ta watch our backs, eh?", ["objectivesText"] = "Recover 1 trophies from gnarldin and their allies.", ["rewardGold"] = 309800, ["rewardXP"] = 12170, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14998 } }, ["questType"] = "standard" },
[93784] = { ["id"] = 93784, ["name"] = "A Gnawing Void of Curiosity", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15329, ["mapID"] = 2393, ["storyline"] = { 93784 }, ["description"] = "<The artifact crumbles in your hand, leaving only a faint but distinctly ancient arcane footprint. Naleidea Rivergleam will want to hear about this.>", ["objectivesText"] = "Report your discovery to Naleidea Rivergleam in Silvermoon City.", ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 2803, ["amount"] = 750 }, { ["id"] = 2803, ["amount"] = 1500 }, { ["id"] = 3316, ["amount"] = 150 }, { ["id"] = 3316, ["amount"] = 300 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 242398, ["x"] = 0.526, ["y"] = 0.78 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.78 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["startItems"] = { 262586 } },
[93792] = { ["id"] = 93792, ["name"] = "Blessings of the Loa", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 93792 }, ["description"] = "My name is Du'gal . And you are hash'ura. Kinduru has ordered me to train you in de ways of loa worship. Take honor in it. Very few gokinye have earned de right as you have. Beside me is de Altar of Blessings. You may use it to worship any of our loa, and you shall receive a sliver of power in thanks. Go ahead now, if ya be so kind.", ["objectivesText"] = "Worship at the Altar of Blessings. Gain a blessing by choosing to combine the power of Akil'zon, Halazzi, Jan'alai, or Nalorakk with that of any lesser loa you've formed a bond with. Progress: De loa are quite generous indeed.", ["rewardGold"] = 30900, ["rewardXP"] = 1520, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 256510, ["x"] = 0.43, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 256510, ["x"] = 0.43, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91062 }, ["db2PoiUiMapID"] = 2437, ["db2QuestHubAreaPoiID"] = 8504, ["db2QuestInfoID"] = 282, ["db2QuestInfoName"] = "Important Quest" },
[93798] = { ["id"] = 93798, ["name"] = "Renowned with Zul'jarra's Forces", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["description"] = "Dis struggle would have been lost ages ago without you on our side. Now, we live to fight another day. Zul'jarra wishes to honor your efforts with a gift. Come speak to me in Tokka's Landing to receive it.", ["rewardItems"] = { 276624 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard" },
[93801] = { ["id"] = 93801, ["name"] = "Calculated Culling", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 91557, 91558, 91559, 91560, 91561, 93801 }, ["description"] = "This pathogen is spreading rapidly among the denizens of the Molt. A swarm of netherwasp hatched shortly after our arrival. The infection spread throughout the region as they fought over territory. If their numbers continue to grow, they could carry the pathogen to the rest of Voidstorm . <name>, can I ask you to reduce the number of infected creatures in the Molt?", ["objectivesText"] = "Cull creatures endemic to the Molt. Progress: This place has such vitality. It's no wonder the pathogen has spread so easily.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 254402, ["x"] = 0.346, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 247674, ["x"] = 0.346, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 91559 }, ["questLines"] = { { ["id"] = 6028, ["name"] = "Pathogenic Problem", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[93810] = { ["id"] = 93810, ["name"] = "Masters' Perch", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 93810 }, ["description"] = "Not every creature of the Void serves Xal'atath's whims. Conquest was our way long before her arrival. To the north, you find Slayer's Rise. It is the vast battleground where three domanaar vie for power. And I hear your ren'dorei allies have set up in Masters' Perch, the main citadel, as well. I am certain great battles await you there. Go forth.", ["objectivesText"] = "Seek void elf allies in Masters' Perch.", ["rewardGold"] = 33500, ["rewardXP"] = 1605, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3389, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 254765, ["x"] = 0.514, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 256557, ["x"] = 0.398, ["y"] = 0.835 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 2405, 2444 }, ["zone"] = { 15458 } }, ["questType"] = "standard" },
[93811] = { ["id"] = 93811, ["name"] = "Renowned with the Silvermoon Court", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 93811 }, ["description"] = "The people of Quel'thalas appreciate your continued support. With threats on all sides, it is good to know we can rely on champions such as yourself to protect us. The Court wishes to reward you for your efforts.", ["objectivesText"] = "Speak with Caeris Fairdawn at Saltheril's Haven.", ["rewardItems"] = { 263433 }, ["starts"] = { { ["x"] = 0.435, ["y"] = 0.474, ["mapID"] = 2395, ["npcID"] = 240838 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240838, ["x"] = 0.434, ["y"] = 0.474 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questGiverID"] = 240838, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2727, ["threshold"] = 7500 } } } },
[93816] = { ["id"] = 93816, ["name"] = "Putting it Together", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93816 }, ["description"] = "You have the basics now. All that's left is to experience the Arcane Propagator for yourself in a match of Decor Duel! What is the Arcane Propagator, you ask? A mystic relic wrought from glamours. It lets players cloak themselves in the guise of enchanted objects. We've partially recreated it with the chair for training, as you've seen, but the real thing is much better. Why not play a match for real right now?", ["objectivesText"] = "Speak with Fieldweaver Amolenne to enter a match of Decor Duel, then speak with Propagandist Naicira . Progress: <name>? No, I do not see your name on any of the game rosters. \\Speak with Gamemaster Fleurian to join a game of Decor Duel.", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 55924, 55925, 55926, 55927, 55928, 55929, 180935, 181377, 181572, 181573, 181581, 181599, 181609, 181610, 181703, 181843, 181866, 182127, 182385, 182470, 182667, 183132, 183480, 183506, 184294, 184362, 184363, 184766, 184767, 184768, 184839 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 255365, ["x"] = 0.275, ["y"] = 0.77 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256697, ["x"] = 0.315, ["y"] = 0.765 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.275, ["y"] = 0.77 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 93719 } },
[93841] = { ["id"] = 93841, ["name"] = "Ghosts of the Ring", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "I was at de Ring of Glory earlier. Have you been? De place is crawlin' with spirits and one of dem gave me quite de fright! Came right up and tried to talk to me! I was too nervous to stick 'round and find out what he wanted. You look brave and strong. Maybe you oughta check it out.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3504, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 258068, ["x"] = 0.584, ["y"] = 0.472, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 256674, ["x"] = 0.66, ["y"] = 0.532, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.584, ["y"] = 0.472, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93024 }, ["nextQuests"] = { 93842, 93843 }, ["questLines"] = { { ["id"] = 6123, ["name"] = "Don't be Afrayed", ["orderIndex"] = 0, ["flags"] = 0 } } },
[93842] = { ["id"] = 93842, ["name"] = "Bloom and Fade", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "My time is runnin' out and I need to see if I can rescue my beloved, Eshaye. She's stuck in de loop, and I want to break her from de cycle before I fade entirely. I used to be able to get through to her with bouquets of sweetsaw blooms . I can't grasp dem anymore, though. Will you gather some for me?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 256674, ["x"] = 0.66, ["y"] = 0.532, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 256874, ["x"] = 0.694, ["y"] = 0.534, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.66, ["y"] = 0.532, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93841 }, ["questLines"] = { { ["id"] = 6123, ["name"] = "Don't be Afrayed", ["orderIndex"] = 1, ["flags"] = 0 } } },
[93843] = { ["id"] = 93843, ["name"] = "Ectoplasmic Extractions", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "Up near de Ring of Glory, there are spirits like myself who are merchants. Dey sell a variety of things to other spirits, but I got Eshaye's attention in de past using a beverage from Mab'jul. De market goods can be purchased with ectoplasm , which can be gathered from de frayed spirits around de Ring. Especially de cultists, who steal it from de others.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 256674, ["x"] = 0.66, ["y"] = 0.532, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 256874, ["x"] = 0.694, ["y"] = 0.534, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.66, ["y"] = 0.532, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93841 }, ["questLines"] = { { ["id"] = 6123, ["name"] = "Don't be Afrayed", ["orderIndex"] = 2, ["flags"] = 0 } } },
[93849] = { ["id"] = 93849, ["name"] = "Ectoplasmic Emporium", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "Eshaye is sure to love these flowers! Now all we need is de spectral brew . Take de ectoplasm to Mab'jul and exchange it for a bottle of spectral brew . It's a vintage made from harvested ectoplasm, and is quite refreshing. It sometimes has de ability to stall fraying.", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 256874, ["x"] = 0.694, ["y"] = 0.534, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 256874, ["x"] = 0.694, ["y"] = 0.534, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.694, ["y"] = 0.534, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93842, 93843 }, ["questLines"] = { { ["id"] = 6123, ["name"] = "Don't be Afrayed", ["orderIndex"] = 3, ["flags"] = 0 } } },
[93850] = { ["id"] = 93850, ["name"] = "Windrunner Spire: Haunting Melodies", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 93850 }, ["description"] = "So much grief... So much pain. It binds us to this place. His melodies once soothed us, but now they are drowned out by the din of violence. Please help us. Follow the sound of the lyre. He will guide you.", ["objectivesText"] = "Quell the restless spirits inside Windrunner Spire. Progress: Please... help us.", ["rewardGold"] = 1366400, ["rewardXP"] = 23530, ["rewardItems"] = { 251080, 251082, 251084, 251085, 251086, 251089, 251092, 251096, 251098 }, ["rewardChoices"] = { 251080, 251082, 251084, 251085, 251086, 251089, 251092, 251096, 251098 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 50 }, { ["id"] = 3365, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 256875, ["x"] = 0.355, ["y"] = 0.79 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 256875, ["x"] = 0.355, ["y"] = 0.79 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.355, ["y"] = 0.79 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 86745 }, ["db2PoiUiMapID"] = 2395, ["db2QuestInfoID"] = 81, ["db2QuestInfoName"] = "Dungeon" },
[93851] = { ["id"] = 93851, ["name"] = "Communing with Ghosts", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "Dat was a long shot, but I still wanted to try. I am out of ideas, . Will you ask around? Some of de others here may have some ideas of how to get through to Eshaye. I am not welcome too close to dem, or I would come with you.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 256874, ["x"] = 0.694, ["y"] = 0.534, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 256874, ["x"] = 0.694, ["y"] = 0.534, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.694, ["y"] = 0.534, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93849 }, ["questLines"] = { { ["id"] = 6123, ["name"] = "Don't be Afrayed", ["orderIndex"] = 4, ["flags"] = 0 } } },
[93852] = { ["id"] = 93852, ["name"] = "Lost Iridescent Flightstone", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 13862, ["mapID"] = 2112, ["description"] = "The flightstone glimmers with the colors of all aspects. Within the glittering light you have visions of noble dragon houses locked in battle against Primal Incarnates. A vicious cacophony of roars as Shadowflame consumes swaths of land. And the soothing sounds of nature as a world tree blooms. The soaring skies of Valdrakken call.", ["rewardGold"] = 315900, ["rewardXP"] = 200, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 200 }, { ["id"] = 1166, ["amount"] = 500 } }, ["ends"] = { { ["npcID"] = 255019, ["x"] = 0.814, ["y"] = 0.47, ["mapID"] = 2112 } }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[93865] = { ["id"] = 93865, ["name"] = "Carve Your Way", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 93865 }, ["description"] = "We permit the presence of your kind for one reason. Your willingness to fight. Show us the skills of mortal duelists. Go, find others of your kind. The pit below is an ideal site for demonstrations of combat prowess.", ["objectivesText"] = "Win a duel against another player or the Masters' Champion. Progress: Go. Show me a bout.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 262967 }, ["rewardCurrencies"] = { { ["id"] = 1792, ["amount"] = 50 }, { ["id"] = 2123, ["amount"] = 50 }, { ["id"] = 3410, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 245571, ["x"] = 0.36, ["y"] = 0.812 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 245571, ["x"] = 0.36, ["y"] = 0.812 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.36, ["y"] = 0.812 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 86549 } },
[93870] = { ["id"] = 93870, ["name"] = "The Ephemeron Masquerade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93870 }, ["description"] = "The deeds of today becomes the tales of dusk! Seekers and Hiders, alike, make their mark through thrilling game play and strategic out maneuvering. The sun shines its light on a new day, shattering the illusions of yesterday, and elongating the shadows of today. Are you ready? Don you disguise, secure your kit, and show your peers no one can hold a candle to you ... literally!", ["objectivesText"] = "Speak with Fieldweaver Amolenne to play Decor Duel. Progress: Your task remains incomplete, <name>.", ["rewardCurrencies"] = { { ["id"] = 3393, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 256697, ["x"] = 0.315, ["y"] = 0.765 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256697, ["x"] = 0.315, ["y"] = 0.765 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.315, ["y"] = 0.765 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 93719, 93914 } },
[93877] = { ["id"] = 93877, ["name"] = "Conditional Objectives - Sequential", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16432, ["mapID"] = 2451, ["storyline"] = { 93877 }, ["description"] = "! Glad to see you. The defenders in the fortress could use your help. One of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on. She needs the help of someone who can properly disrupt the robot's attacks so it can be repaired. Do you have a moment to help?", ["objectivesText"] = "Activate Fightbot 11.2.7, then interrupt its abilities with your Felguard or Felhunter 1 times.", ["rewardGold"] = 29200, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16432 } }, ["questType"] = "standard" },
[93878] = { ["id"] = 93878, ["name"] = "Conditional Objectives - Multiple Steps, No Sequence", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16432, ["mapID"] = 2451, ["storyline"] = { 93878 }, ["description"] = "! Glad to see you. The defenders in the fortress could use your help. One of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on. She needs the help of someone who can properly disrupt the robot's attacks so it can be repaired. Do you have a moment to help?", ["objectivesText"] = "Activate Fightbot 11.2.7, then interrupt its abilities with your Felguard or Felhunter 1 times.", ["rewardGold"] = 29200, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16432 } }, ["questType"] = "standard" },
[93879] = { ["id"] = 93879, ["name"] = "Conditional Objectives - Conditional After Sequence", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 93879 }, ["description"] = "! Glad to see you. The defenders in the fortress could use your help. One of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on. She needs the help of someone who can properly disrupt the robot's attacks so it can be repaired. Do you have a moment to help?", ["objectivesText"] = "Activate Fightbot 11.2.7, then interrupt its abilities with your Felguard or Felhunter 1 times.", ["rewardGold"] = 29200, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[93889] = { ["id"] = 93889, ["name"] = "Midnight: Saltheril's Soiree", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93889 }, ["description"] = "Champion, you would do well to attend Saltheril's Soiree. There, amidst Silvermoon's intricate politics and quiet struggles for influence, our most distinguished military orders each have matters they wish to see addressed. Prove your worth to these factions, and you may find their gratitude and favor richly rewarded.", ["objectivesText"] = "Participate in Saltheril's Soiree and earn favor with one of the Silvermoon factions.", ["rewardGold"] = 683200, ["rewardXP"] = 20540, ["rewardItems"] = { 254677, 268490, 279527, 279575 }, ["starts"] = { { ["x"] = 0.49, ["y"] = 0.646, ["mapID"] = 2393 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256203, ["x"] = 0.49, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 6072 } },
[93890] = { ["id"] = 93890, ["name"] = "Midnight: Abundance", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 87350, 89507, 91302, 91457, 91475, 91930, 91932, 91933, 93890, 93931, 94361 }, ["description"] = "The trolls of Zul'Aman draw their strength from the loa: ancient spirits that grant power to those who honor them. These boons can be wondrous or perilous, depending on the loa's nature and the devotion of its followers. There are whispers of a Loa of Abundance dwelling within Zul'Aman, its blessings said to bring prosperity to those deemed worthy. Seek it out, learn what drives it, and see if its favor would serve our cause.", ["objectivesText"] = "Participate in Zul'Aman's Abundance Harvest and gain Loa's favor.", ["rewardGold"] = 683200, ["rewardXP"] = 17650, ["rewardItems"] = { 254677 }, ["starts"] = { { ["x"] = 0.49, ["y"] = 0.646, ["mapID"] = 2393 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256203, ["x"] = 0.49, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5810, ["name"] = "Abundance", ["orderIndex"] = 20, ["flags"] = 0 } }, ["db2LabelIDs"] = { 6072 }, ["db2PoiUiMapID"] = 2393 },
[93892] = { ["id"] = 93892, ["name"] = "Midnight: Stormarion Assault", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93892 }, ["description"] = "The fight against Xal'atath tests our resolve, but it will not break us. Void anomalies twist the halls of Stormarion Citadel, but they will find no weakness here. The Void Elves stand as our allies. Prove to our enemies that our strength when united is beyond the reach of even the Void. Go, <name>--aid them, and see the Citadel cleansed of corruption.", ["objectivesText"] = "Participate in the Stormarion Assault event.", ["rewardGold"] = 683200, ["rewardXP"] = 20540, ["rewardItems"] = { 251635, 254677, 268490 }, ["starts"] = { { ["x"] = 0.49, ["y"] = 0.646, ["mapID"] = 2393 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256203, ["x"] = 0.49, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 6072 } },
[93899] = { ["id"] = 93899, ["name"] = "Slayer's Rise", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16423, ["mapID"] = 2444, ["storyline"] = { 93899 }, ["description"] = "We've received reports of escalated troubles between some domanaar. Go investigate the battle in Slayer's Rise , then report to Deminos Darktrance in Masters' Perch.", ["objectivesText"] = "Complete the Slayer's Rise battleground.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 1792, ["amount"] = 250 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 245976, ["x"] = 0.388, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "pvp" },
[93904] = { ["id"] = 93904, ["name"] = "Defying Gravity", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 93904 }, ["description"] = "Now, we descend. The Void energy below is unlike any I've felt before, as if gravity itself yields to the Void. Once you enter the cave, its influence will be upon you. Kalgorg has already slain and claimed power from the creatures within. Their violent deaths have left behind some kind of cursed terrain. But we must proceed and claim the power within. Fill the reliquary to the brim. I know not what to expect from my voidwalker. We will need all the power we can manage.", ["objectivesText"] = "Gather Void energy within the Lair of Predaxas.", ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.48, ["y"] = 0.784, ["mapID"] = 2405 } }, ["ends"] = { { ["x"] = 0.48, ["y"] = 0.784, ["mapID"] = 2405 } }, ["coords"] = { ["mapID"] = 2405, ["x"] = 0.48, ["y"] = 0.784 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16648 } }, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 15, ["amount"] = 1, ["objectID"] = 0, ["text"] = "Void Power Collected" }, { ["orderIndex"] = 1, ["type"] = 0, ["amount"] = 7, ["objectID"] = 247110 }, { ["orderIndex"] = 2, ["type"] = 0, ["amount"] = 10, ["objectID"] = 246687 }, { ["orderIndex"] = 3, ["type"] = 0, ["amount"] = 10, ["objectID"] = 247094 }, { ["orderIndex"] = 4, ["type"] = 0, ["amount"] = 1, ["objectID"] = 245756, ["text"] = "Activate the Gravity Anomaly to travel up" } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2527, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[93905] = { ["id"] = 93905, ["name"] = "Ongoing Stoppage", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15458, ["mapID"] = 2405, ["storyline"] = { 93905 }, ["description"] = "The Shadowguard may once have defied Xal'atath, but they're part of her army now. Whatever they're doing with the energies gathered here must be stopped. Put down their soldiers, harvesters, and machines. I'll do the same, and meet you deeper within.", ["objectivesText"] = "Slay Shadowguard and disrupt the Manaforge at the Ethereum Refinery.", ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.374, ["y"] = 0.751, ["mapID"] = 2405 } }, ["ends"] = { { ["x"] = 0.374, ["y"] = 0.751, ["mapID"] = 2405 } }, ["coords"] = { ["mapID"] = 2405, ["x"] = 0.374, ["y"] = 0.751 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15458 } }, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 15, ["amount"] = 1, ["objectID"] = 0, ["text"] = "Manaforge Disrupted" }, { ["orderIndex"] = 1, ["type"] = 2, ["amount"] = 10, ["objectID"] = 509568, ["text"] = "Manaturret Destroyed" }, { ["orderIndex"] = 2, ["type"] = 0, ["amount"] = 34, ["objectID"] = 236857 }, { ["orderIndex"] = 3, ["type"] = 0, ["amount"] = 25, ["objectID"] = 238581 }, { ["orderIndex"] = 4, ["type"] = 0, ["amount"] = 25, ["objectID"] = 236860 }, { ["orderIndex"] = 5, ["type"] = 0, ["amount"] = 34, ["objectID"] = 237886 }, { ["orderIndex"] = 6, ["type"] = 0, ["amount"] = 34, ["objectID"] = 236859 }, { ["orderIndex"] = 7, ["type"] = 2, ["amount"] = 13, ["objectID"] = 527969 }, { ["orderIndex"] = 8, ["type"] = 2, ["amount"] = 13, ["objectID"] = 528315 }, { ["orderIndex"] = 9, ["type"] = 2, ["amount"] = 10, ["objectID"] = 528316 }, { ["orderIndex"] = 10, ["type"] = 0, ["amount"] = 17, ["objectID"] = 235710 }, { ["orderIndex"] = 11, ["type"] = 0, ["amount"] = 13, ["objectID"] = 241040 }, { ["orderIndex"] = 12, ["type"] = 0, ["amount"] = 100000, ["objectID"] = 239465 }, { ["orderIndex"] = 13, ["type"] = 0, ["amount"] = 1, ["objectID"] = 235710 }, { ["orderIndex"] = 14, ["type"] = 0, ["amount"] = 2, ["objectID"] = 235710 }, { ["orderIndex"] = 15, ["type"] = 0, ["amount"] = 3, ["objectID"] = 235710 }, { ["orderIndex"] = 16, ["type"] = 0, ["amount"] = 4, ["objectID"] = 235710 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[93906] = { ["id"] = 93906, ["name"] = "Untethering the Two", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "It never occurred to me to attack Eshaye . I been wasting time tryin' to get her to talk to me, without knowin' how to talk to her. Will you do dis for me? Challenge Eshaye and beat her. Could dis wake her up? I feel hope stirrin'.", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["rewardItems"] = { 280136 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3504, ["amount"] = 250 } }, ["starts"] = { { ["npcID"] = 256874, ["x"] = 0.694, ["y"] = 0.534, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 258840, ["x"] = 0.694, ["y"] = 0.534, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.694, ["y"] = 0.534, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93851 }, ["questLines"] = { { ["id"] = 6123, ["name"] = "Don't be Afrayed", ["orderIndex"] = 5, ["flags"] = 0 } } },
[93907] = { ["id"] = 93907, ["name"] = "Edification of the Worthy", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93907 }, ["description"] = "When you acquire a new Seeker kit, it always starts off relatively lean. But you'll earn Illusionary Coins as you play, and may trade them in with Gamemaster Fleurian for expanded abilities, and even additional kits! Take these. Add them to what you earned and demonstrate your shopping prowess.", ["objectivesText"] = "Use Illusionary Coins with the vendor, Gamemaster Fleurian, to purchase something. Progress: Those coins were a one-time gift, <name>. If you have mislaid them, or have suffered the misfortune of thievery, then I suppose you will have to enter the games to collect more.", ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 256697, ["x"] = 0.315, ["y"] = 0.765 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256697, ["x"] = 0.315, ["y"] = 0.765 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.315, ["y"] = 0.765 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 93816 } },
[93909] = { ["id"] = 93909, ["name"] = "Midnight: Delves", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93909 }, ["description"] = "Many have ventured into the delves' depths, but few have returned with more than dust and bruises. Valeera Sanguinar has taken a keen interest in these ventures. She leaves no stone unturned and has a remarkable talent for getting in to places others cannot. Seek her out, and see what fortune or danger awaits beneath the surface.", ["objectivesText"] = "Complete 3 Delves in Midnight. Progress: Stay sharp, <name>.", ["rewardGold"] = 683200, ["rewardXP"] = 20540, ["rewardItems"] = { 254677, 268490 }, ["starts"] = { { ["x"] = 0.49, ["y"] = 0.646, ["mapID"] = 2393 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256203, ["x"] = 0.49, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 6072 } },
