[93930] = { ["id"] = 93930, ["name"] = "Courting Success", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 93930, 93931, 93932, 93933 }, ["description"] = "You seek an audience with Saltheril? And you're wearing... that? Excuse me for a moment while I laugh into my handkerchief. <Caeris laughs lightly behind his handkerchief.> Now, let me be professional. You are cordially invited to attend Saltheril's soiree. Don't embarrass yourself, <name>. The best of Silvermoon are watching.", ["objectivesText"] = "Participate in Saltheril's Soiree and empower Eversong's runestones.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 266429, 266430, 266431, 266432 }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 240838, ["x"] = 0.434, ["y"] = 0.474 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240838, ["x"] = 0.434, ["y"] = 0.474 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6115, ["name"] = "Renown of Midnight", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2395 },
[93931] = { ["id"] = 93931, ["name"] = "An Abundance of Wealth", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 87350, 89507, 91302, 91457, 91475, 91930, 91932, 91933, 93890, 93931, 94361 }, ["description"] = "De Loa of Abundance may not be one of de four great ones, but his worshippers are certainly de most devout. Seek him out yaself. You can find him in northern Zul'Aman", ["objectivesText"] = "Harvest wealth for the Loa of Abundance. Progress: Did you find de loa, hash'ura?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 265739, 265740 }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 240279, ["x"] = 0.458, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 240279, ["x"] = 0.458, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5810, ["name"] = "Abundance", ["orderIndex"] = 21, ["flags"] = 0 }, { ["id"] = 6115, ["name"] = "Renown of Midnight", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
