[93933] = { ["id"] = 93933, ["name"] = "Guarded Treasures", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15458, ["mapID"] = 2405, ["storyline"] = { 93930, 93931, 93932, 93933 }, ["description"] = "Our sojourn to this world has brought the ren'dorei an even deeper understanding of the Void than before. The domanaar with whom we share a common enemy are almost strangely generous with their knowledge. I believe they want us to become as fearsome as they are. There is a Singularity Anchor in Stormarion Citadel. I have learned how to draw upon some of its power to craft you a powerful item. But first, we must ensure it does not fall into the hands of our enemies.", ["objectivesText"] = "Defend the Singularity Anchor in Stormarion Citadel. Progress: Have you defended the anchor from the encroaching void forces?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 264507 }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 248328, ["x"] = 0.525, ["y"] = 0.728 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 248328, ["x"] = 0.525, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6115, ["name"] = "Renown of Midnight", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
