[93942] = { ["id"] = 93942, ["name"] = "Spark of Radiance", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93942 }, ["description"] = "A vision of radiance permeates your mind. Eldara Dawnrunner might have more information regarding these Sparks of Radiance.", ["objectivesText"] = "Speak to Eldara Dawnrunner in Silvermoon.", ["rewardGold"] = 33500, ["starts"] = { { ["x"] = 0.402, ["y"] = 0.648, ["mapID"] = 2393 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 243229, ["x"] = 0.402, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
