[93954] = { ["id"] = 93954, ["name"] = "Prestidigimotion", ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["storyline"] = { 93954 }, ["description"] = "Don your chosen disguise, take to the field, and traverse with cunning. Cover as much ground as you dare before capture claims you. To reach the goal unseen is ideal. Though, you may be Found thrice, so long as you are never Tagged. Move as illusion would move: with nimble grace, with stealthful flair, with reckless finesse. The path is open. Become what you are not. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(93954)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(93954))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Move \"1,000 steps\" as a Hider without getting Tagged.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[93955] = { ["id"] = 93955, ["name"] = "Feastform", ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["storyline"] = { 93955 }, ["description"] = "Don your edible disguise, then take to the field and sustain your illusion You are the offering. Not seeker. Not hunter. The summoned feast. Move as the banquet would move! Let your presence tempt, confuse, or deceive. You must complete three full minutes of uninterrupted embodiment. The path is open. Become what you are not. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(93955)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(93955))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Play with a Food Disguise for Three Unbroken Minutes.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[93956] = { ["id"] = 93956, ["name"] = "Wroughtform", ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["storyline"] = { 93956 }, ["description"] = "Don your crafted disguise, then take to the field and sustain your illusion You are the object. Not seeker. Not hunter. The conjured form. Move as relic, ornament, or artifact would move! Let your presence mislead, blend, or vanish. You must complete three full minutes of uninterrupted embodiment. The path is open. Become what you are not. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(93956)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(93956))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Play with a Non-Food Disguise for Three Unbroken Minutes.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[93965] = { ["id"] = 93965, ["name"] = "Pet Wranglin'", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93965, 94012 }, ["description"] = "Seems like you've got the spurs for this ride. Just takes a little gettin' used to is all. Critters of all kind are crawling around Eversong and beyond. Cute, cuddly, creepy--whatever strikes your fancy. You look tough enough to nab your own. Why don't ya give it a try?", ["objectivesText"] = "Capture a Wild Pet in any Midnight zone.", ["rewardGold"] = 256200, ["rewardXP"] = 8825, ["rewardItems"] = { 263871 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 257039, ["x"] = 0.418, ["y"] = 0.762 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 257039, ["x"] = 0.418, ["y"] = 0.762 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.762 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 94012 }, ["questLines"] = { { ["id"] = 6120, ["name"] = "Pet Wranglin'", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[93969] = { ["id"] = 93969, ["name"] = "Call Shot", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93969 }, ["description"] = "Critters of all kind are crawling around Eversong and beyond. Cute, cuddly, creepy--whatever strikes your fancy. Ya might be used to havin' varmints bash heads until one was weak enough to nab. Got a new way to try. All you need is a crate. You've got one, yeah? Just throw the crate from the start. It's mighty effective, I tell ya. You look tough enough to nab your own. Why don't ya give it a try?", ["objectivesText"] = "Capture a Wild Pet in any Midnight zone.", ["rewardGold"] = 232300, ["rewardXP"] = 8825, ["rewardItems"] = { 263871 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[93970] = { ["id"] = 93970, ["name"] = "Researching the Storm", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 93970 }, ["description"] = "The urgent nature of our mission to these lands should not preclude us from embarking on new and meaningful research. Long have my people studied the void, and any opportunity to break new ground must be seized. Our scouts have been finding peculiar void manifestations throughout Voidstorm . If my hypothesis is correct, I believe we can use our host's facilities to further refine and understand these samples.", ["objectivesText"] = "Help Anomander unlock the Research Console in Howling Ridge. Progress: Please do not drop the sample.", ["rewardGold"] = 170800, ["rewardXP"] = 6425, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 248328, ["x"] = 0.525, ["y"] = 0.728 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 248328, ["x"] = 0.525, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 86509 } },
[93979] = { ["id"] = 93979, ["name"] = "Lingering Memories", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2472, ["storyline"] = { 83126, 83127, 83128, 83129, 84856, 84857, 84862, 84863, 84864, 84865, 84866, 84967, 85037, 85449, 85450, 86495, 86820, 86946, 90517, 91871, 93979 }, ["series"] = { 84855, 85032, 85961 }, ["description"] = "Dimensius threatens us once more. There is no one who knows his methods better than his former Harbinger, Xal'atath . I would not say we can trust her, but we can work with her. She fears the All-Devouring's wrath after her betrayal. We can't afford to turn away any potential ally. Think how many we will save from the Void Lord's hunger. Get your bearings in this city the four of us saved together. I will convince Alleria.", ["objectivesText"] = "Meet Alleria and Locus-Walker at the docks.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2472, ["npcID"] = 231128, ["x"] = 0.376, ["y"] = 0.745333 } }, ["ends"] = { { ["mapID"] = 2472, ["npcID"] = 230700, ["x"] = 0.342, ["y"] = 0.108 } }, ["coords"] = { ["mapID"] = 2472, ["source"] = "quest_giver", ["x"] = 0.376, ["y"] = 0.745333 }, ["mapCandidates"] = { ["npc"] = { 2472 }, ["zone"] = { 15781 } }, ["questType"] = "standard", ["sourceQuests"] = { 84967 }, ["questLines"] = { { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2472 },
[93997] = { ["id"] = 93997, ["name"] = "Void Post Control", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 93997 }, ["description"] = "Vidious is moving to claim Slayer's Rise, sending his proxies to occupy the Void Posts. I shall not be outmaneuvered. Seize full control of each of the Void Posts and eliminate any of Vidious's forces that try to stop you.", ["objectivesText"] = "Enter War Mode and seize full control of each of the Void Posts in Slayer's Rise. Progress: Have you seized control of each of the Void Posts?", ["rewardGold"] = 1024800, ["rewardXP"] = 20540, ["rewardCurrencies"] = { { ["id"] = 1792, ["amount"] = 150 }, { ["id"] = 2123, ["amount"] = 50 }, { ["id"] = 3410, ["amount"] = 300 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 257132, ["x"] = 0.348, ["y"] = 0.805 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 257132, ["x"] = 0.348, ["y"] = 0.805 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.348, ["y"] = 0.805 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard" },
[93999] = { ["id"] = 93999, ["name"] = "Void Post Control", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 93999 }, ["description"] = "Ziadan vies for control of Slayer's Rise, sending her proxies out to seize the Void Posts. Show her two can play at this game. Strike quickly: seize control of the Void Posts, slaying any who stand in your way.", ["objectivesText"] = "Enter War Mode and seize full control of each of the Void Posts in Slayer's Rise.", ["rewardGold"] = 1024800, ["rewardXP"] = 20540, ["rewardCurrencies"] = { { ["id"] = 1792, ["amount"] = 150 }, { ["id"] = 2123, ["amount"] = 50 }, { ["id"] = 3410, ["amount"] = 300 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 257130, ["x"] = 0.408, ["y"] = 0.838 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 257130, ["x"] = 0.408, ["y"] = 0.838 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.838 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard" },
[94005] = { ["id"] = 94005, ["name"] = "Stellar Stash", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16648 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 257215, ["text"] = "pulled once" }, { ["orderIndex"] = 1, ["type"] = 0, ["amount"] = 1, ["objectID"] = 257216, ["text"] = "pulled twice" }, { ["orderIndex"] = 2, ["type"] = 0, ["amount"] = 1, ["objectID"] = 257217, ["text"] = "pulled thrice" } } },
[94010] = { ["id"] = 94010, ["name"] = "Gnome Alone", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["storyline"] = { 94010 }, ["description"] = "<Judging by the detritus on the bottle and the timing of events, the gnome that set this message adrift would have long-since passed if not rescued. But, since this bottle made it to shore, perhaps this gnome traveler did as well.>", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[94012] = { ["id"] = 94012, ["name"] = "Lost Lil' Strider", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 93965, 94012 }, ["description"] = "Howdy, pardner. Folks at this here pet store asked for my help straighten' out this place. But while I was distracted, a hawkstrider chick I've been rearin' slipped out the front door. Prettiest purple plumes you ever did see. Would you do me the kindness of finding her and bringing her back for me? I take her for a stroll in the garden every so often. I'll betcha that's where you'll find her.", ["objectivesText"] = "Capture Tiff in the Gardens of Remembrance in Silvermoon City . Progress: Ya find her?", ["rewardGold"] = 170800, ["rewardXP"] = 5885, ["rewardItems"] = { 264165 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 257039, ["x"] = 0.418, ["y"] = 0.762 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 257039, ["x"] = 0.418, ["y"] = 0.762 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.762 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6120, ["name"] = "Pet Wranglin'", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[94031] = { ["id"] = 94031, ["name"] = "Bones of My Soul", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "Do you have time to break a curse, ? I'm what remains of a loa speaker of Gral. I kept de prisoners in line on Gral's Belly. But we crashed, I died, and de prisoners escaped. My powers didn't work on de livin' anymore. But they did work on de captain, who'd died with me. Terrified of his anger at my failure, I set up a ritual to trap him in de ship using my own bones. My soul has leeched into de bones after all this time, and now I can't move them. Would you bring my bones to me?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 257298, ["x"] = 0.59, ["y"] = 0.68, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 257298, ["x"] = 0.59, ["y"] = 0.68, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.59, ["y"] = 0.68, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 92920 }, ["questLines"] = { { ["id"] = 6114, ["name"] = "Bone Deep", ["orderIndex"] = 0, ["flags"] = 0 } } },
[94035] = { ["id"] = 94035, ["name"] = "Meat for the Bones", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "To move my soul out o' de bones and into me, I need to do a ritual. Gral is de loa of many things, but mostly de sea. He's a shark. And he likes meat! Get meat from de sea creatures around here. It will be easier to perform de ritual with somethin' red and oozing to ground me.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 257298, ["x"] = 0.59, ["y"] = 0.68, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 257298, ["x"] = 0.59, ["y"] = 0.68, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.59, ["y"] = 0.68, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 92920 }, ["questLines"] = { { ["id"] = 6114, ["name"] = "Bone Deep", ["orderIndex"] = 1, ["flags"] = 0 } } },
[94036] = { ["id"] = 94036, ["name"] = "One Final Prisoner", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "I cannot pretend I am any better than de captain. We both enjoyed lording our power over de prisoners. When he'd lash out, I did not stop him. But in our time trapped here together, I've reflected. De minute I wasn't useful to him, he got angry. And now I want this to end. I cannot enable him any more. Would you put him to rest?", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3504, ["amount"] = 100 } }, ["starts"] = { { ["npcID"] = 257298, ["x"] = 0.59, ["y"] = 0.68, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 257298, ["x"] = 0.59, ["y"] = 0.68, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.59, ["y"] = 0.68, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 92920 }, ["questLines"] = { { ["id"] = 6114, ["name"] = "Bone Deep", ["orderIndex"] = 2, ["flags"] = 0 } } },
[94040] = { ["id"] = 94040, ["name"] = "Meat and Bone and Soul", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "We have everything we need for de ritual. Meet me at de Tooth o' Sargoth. You'll help me get my soul back in one piece, then this curse will finally be over. May Gral judge me on de other side for my failures here.", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["rewardChoices"] = { 278909, 278910, 278911, 278912 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3504, ["amount"] = 250 } }, ["starts"] = { { ["npcID"] = 257298, ["x"] = 0.59, ["y"] = 0.68, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 257306, ["x"] = 0.684, ["y"] = 0.826, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.59, ["y"] = 0.68, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 94031, 94035, 94036 }, ["questLines"] = { { ["id"] = 6114, ["name"] = "Bone Deep", ["orderIndex"] = 3, ["flags"] = 0 } } },
[94052] = { ["id"] = 94052, ["name"] = "The Domanaar's Plan", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 94052 }, ["description"] = "If I am to defeat Ziadan, I need information. Maps, strategy scrolls, battle reports, anything that gives me an edge! Scour the Hate Spire and nearby grounds. Search every chest and cut down guards to find the information I need.", ["objectivesText"] = "Enter War Mode and collect 6 Ziadan's Battleplans from chests or slain guards. Progress: Have you obtained the battle plans?", ["rewardGold"] = 1024800, ["rewardXP"] = 20540, ["rewardItems"] = { 264191 }, ["rewardCurrencies"] = { { ["id"] = 1792, ["amount"] = 150 }, { ["id"] = 2123, ["amount"] = 50 }, { ["id"] = 3410, ["amount"] = 300 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 257130, ["x"] = 0.408, ["y"] = 0.838 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 257130, ["x"] = 0.408, ["y"] = 0.838 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.838 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard" },
[94055] = { ["id"] = 94055, ["name"] = "The Domanaar's Plan", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 94055 }, ["description"] = "To counter Vidious' foul plans, I need information. Maps, strategy scrolls, battle reports, anything that turns the battle in my favor! Scour the Grief Spire and nearby grounds. Search every chest and cut down guards to find the information I need.", ["objectivesText"] = "Enter War Mode and collect 6 Vidious' Battleplans from chests or slain guards. Progress: Have you obtained the battle plans?", ["rewardGold"] = 1024800, ["rewardXP"] = 20540, ["rewardItems"] = { 264192 }, ["rewardCurrencies"] = { { ["id"] = 1792, ["amount"] = 150 }, { ["id"] = 2123, ["amount"] = 50 }, { ["id"] = 3410, ["amount"] = 300 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 257132, ["x"] = 0.348, ["y"] = 0.805 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 257132, ["x"] = 0.348, ["y"] = 0.805 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.348, ["y"] = 0.805 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard" },
[94056] = { ["id"] = 94056, ["name"] = "A Golden Pull", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 94056 }, ["description"] = "A unique and valuable gift has been sent to me, hidden in the supply crates that drop upon Slayer's Rise. Should Ziadan obtain this gift instead, her insufferable gloating would never cease! Enter War Mode, and seize control of a supply crate. Then recover the gift for me!", ["objectivesText"] = "Enter War Mode and collect the Golden Vidious Card from a War Supply Crate in Slayer's Rise. Progress: Have you obtained my gift?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 264188 }, ["rewardCurrencies"] = { { ["id"] = 1792, ["amount"] = 150 }, { ["id"] = 2123, ["amount"] = 50 }, { ["id"] = 3410, ["amount"] = 300 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 257130, ["x"] = 0.408, ["y"] = 0.838 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 257130, ["x"] = 0.408, ["y"] = 0.838 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.838 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard" },
[94057] = { ["id"] = 94057, ["name"] = "A Golden Pull", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 94057 }, ["description"] = "A unique and valuable gift has been sent to me, hidden in the supply crates that drop upon Slayer's Rise. Should Vidious obtain this gift instead, his taunts would be incessant. Enter War Mode, and seize control of a supply crate. Then recover the gift for me!", ["objectivesText"] = "Enter War Mode and collect the Golden Ziadan Card from a War Supply Crate in Slayer's Rise. Progress: Have you obtained my gift?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 264189 }, ["rewardCurrencies"] = { { ["id"] = 1792, ["amount"] = 150 }, { ["id"] = 2123, ["amount"] = 50 }, { ["id"] = 3410, ["amount"] = 300 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 257132, ["x"] = 0.348, ["y"] = 0.805 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 257132, ["x"] = 0.348, ["y"] = 0.805 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.348, ["y"] = 0.805 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard" },
[94210] = { ["id"] = 94210, ["name"] = "Feathering the Nest", ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15524, ["mapID"] = 2352, ["storyline"] = { 94210 }, ["series"] = { 91968, 91969 }, ["description"] = "A house isn't quite a home without the perfect furnishings. It looked like there were some vendors in town. Perhaps it would be worth checking what they have in stock.", ["objectivesText"] = "Learn where to obtain Decor. Progress: Have you met all the local vendors? They have some great furnishings available.", ["rewardGold"] = 34100, ["rewardItems"] = { 244778 }, ["starts"] = { { ["mapID"] = 2352, ["npcID"] = 233063, ["x"] = 0.53, ["y"] = 0.4 }, { ["mapID"] = 2351, ["npcID"] = 233708, ["x"] = 0.552, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2352, ["npcID"] = 233063, ["x"] = 0.53, ["y"] = 0.4 }, { ["mapID"] = 2351, ["npcID"] = 233708, ["x"] = 0.552, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2352, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 2351, 2352 }, ["zone"] = { 15524 } }, ["questType"] = "standard", ["sourceQuests"] = { 91969 }, ["db2PoiMapID"] = 2735, ["db2PoiUiMapID"] = 2352, ["db2QuestInfoID"] = 282, ["db2QuestInfoName"] = "Important Quest" },
[94361] = { ["id"] = 94361, ["name"] = "The Abundant Life", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 87350, 89507, 91302, 91457, 91475, 91930, 91932, 91933, 93890, 93931, 94361 }, ["description"] = "You are ready, acolyte! Ready to spread your wings or what have you? I have projected my presence into today's most active and tumultuous lands, rummaging about their natures and environs for areas ripe with abundance. With a little provocation from me, these forgotten corners are blooming bright with glorious harvestables! Seek me out! A crypt of phantasms in Eversong! A grove of verdant flora in Harandar! Even a quarry of living rock in Voidstorm! And, of course, right here too!", ["objectivesText"] = "Complete each Abundance event once. They are located in Eversong, Zul'Aman, Harandar, and Voidstorm. Progress: Temperance, acolyte. There is still more abundance to be collected yet.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 253629 }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 242704, ["x"] = 0.316, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 248658, ["x"] = 0.66, ["y"] = 0.615 }, { ["mapID"] = 2405, ["npcID"] = 257632, ["x"] = 0.388, ["y"] = 0.532 }, { ["mapID"] = 2395, ["npcID"] = 257633, ["x"] = 0.568, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.316, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 2395, 2405, 2413, 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 91933 }, ["questLines"] = { { ["id"] = 5810, ["name"] = "Abundance", ["orderIndex"] = 18, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[94363] = { ["id"] = 94363, ["name"] = "The Gloves Are Off", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 2257, ["mapID"] = 500, ["storyline"] = { 94363 }, ["description"] = "If you've found yourself an invite you'll be wanting to put it to good use, no? Use your Blood-Soaked Invitation first then talk to a Bouncer in the Brawlpub and get to brawling!", ["objectivesText"] = "Talk to a Bouncer in Bizmo's Brawlpub in the Deeprun Tram after using your Blood-Soaked Invitation.", ["rewardGold"] = 34100, ["rewardXP"] = 1470, ["starts"] = { { ["x"] = 0.537, ["y"] = 0.616, ["mapID"] = 499, ["npcID"] = 253170 } }, ["ends"] = { { ["x"] = 0.537, ["y"] = 0.616, ["mapID"] = 499, ["npcID"] = 253170 } }, ["coords"] = { ["mapID"] = 499, ["x"] = 0.537, ["y"] = 0.616 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2257 } }, ["questGiverID"] = 253170, ["questTurnInID"] = 253170, ["questType"] = "standard", ["sourceQuests"] = { 92851 } },
[94370] = { ["id"] = 94370, ["name"] = "Slithering Closer", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91493, 91494, 91495, 91504, 91505, 94370 }, ["description"] = "Do you bring tidings from Numia? She was supposed to be here and help me assess these fair flowers. She must be occupied. The naga have encroached on my town and hers... they have kept to the beach so far, but that could change quickly. Will you check on my friend?", ["objectivesText"] = "Find Numia Golden in Goldenmist Village.", ["rewardGold"] = 31500, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 257393, ["x"] = 0.372, ["y"] = 0.738 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 250298, ["x"] = 0.39, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.372, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 90494 }, ["nextQuests"] = { 91493 }, ["questLines"] = { { ["id"] = 5958, ["name"] = "Daggerspine Landing", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiUiMapID"] = 2395 },
[94371] = { ["id"] = 94371, ["name"] = "A Ranger's Dream", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 91342, 91345, 91347, 91348, 91349, 91350, 91383, 91384, 91385, 91452, 91462, 91463, 94371 }, ["description"] = "Apprentices! Who can keep them tied down? Taemin was a particularly talented arcanist, but his head was always in the clouds. Or in the woods, really. Instead of studying, he buried his nose in storybooks! The legends of Eversong! The Rangers of old! Heroes of the Sin'dorei! He couldn't get enough, the dreaming fool! And now... no, he's not dead. Did I imply that? He's just run off to join the Farstriders. Check in on him, won't you? See if he's come to his senses?", ["objectivesText"] = "Check in on Arcanist Taemin at Farstrider Hold.", ["rewardGold"] = 31900, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 257384, ["x"] = 0.452, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 246806, ["x"] = 0.574, ["y"] = 0.4 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86735 }, ["nextQuests"] = { 91342, 91452 }, ["questLines"] = { { ["id"] = 5969, ["name"] = "Far Striding", ["orderIndex"] = 12, ["flags"] = 1 } }, ["db2PoiUiMapID"] = 2395 },
[94372] = { ["id"] = 94372, ["name"] = "The Gloves Are Off", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 6298, ["mapID"] = 85, ["storyline"] = { 94372 }, ["description"] = "If you've found yourself an invite you'll be wanting to put it to good use, no? Use your Blood-Soaked Invitation first then talk to a Grunt in the Brawl'gar Arena and get to brawling!", ["objectivesText"] = "Talk to a Grunt in the Brawl'gar Arena in Orgrimmar after using your Blood-Soaked Invitation.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 252933, ["x"] = 0.735, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 252933, ["x"] = 0.735, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questTurnInID"] = 252933, ["questType"] = "standard", ["sourceQuests"] = { 92740 } },
[94379] = { ["id"] = 94379, ["name"] = "This Old Hearth", ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15524, ["mapID"] = 2352, ["storyline"] = { 94379 }, ["description"] = "It looks like your house is ready for an upgrade. This doesn't normally happen so fast, but you've really made an impression around here. Head on over to our general contractor for next steps.", ["objectivesText"] = "Level up your house. Progress: Did you get your house upgraded?", ["rewardGold"] = 34100, ["starts"] = { { ["mapID"] = 2352, ["npcID"] = 233063, ["x"] = 0.53, ["y"] = 0.4 }, { ["mapID"] = 2351, ["npcID"] = 233708, ["x"] = 0.552, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2352, ["npcID"] = 233063, ["x"] = 0.53, ["y"] = 0.4 }, { ["mapID"] = 2351, ["npcID"] = 233708, ["x"] = 0.552, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2352, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 2351, 2352 }, ["zone"] = { 15524 } }, ["questType"] = "standard", ["sourceQuests"] = { 94210 }, ["questLines"] = { { ["id"] = 6117, ["name"] = "House Purchase Tutorial - Just Last", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2735, ["db2PoiUiMapID"] = 2352, ["db2QuestInfoID"] = 282, ["db2QuestInfoName"] = "Important Quest" },
[94380] = { ["id"] = 94380, ["name"] = "Ranger Captain's Summons", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 94380, 94381, 94382, 94383, 96080 }, ["description"] = "Pardon the intrusion, <name>! I'm delivering a summons from Ranger Captain Lilatha . She's requested your presence at her staging grounds overlooking the Bazaar near the north gate of Silvermoon. Our lands are once again under threat and we'll need all the support we can get. Report to her when you can!", ["objectivesText"] = "Report to Ranger Captain Lilatha in Silvermoon City .", ["rewardGold"] = 31200, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 257459, ["x"] = 0.493, ["y"] = 0.655 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 257411, ["x"] = 0.48, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.493, ["y"] = 0.655 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["nextQuests"] = { 96080 }, ["questLines"] = { { ["id"] = 6270, ["name"] = "Void Assaults", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiUiMapID"] = 2393 },
[94381] = { ["id"] = 94381, ["name"] = "Outfitting and Allies", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 94380, 94381, 94382, 94383, 96080 }, ["description"] = "Halduron Brightwing has made sure that our task force is well equipped to handle any threat. I want you to check in with our quartermaster, Maren Silverwing . She will help you get outfitted. I also want you to talk with our \"liaison.\" She is the troll with the guards. You may already know we are not alone in being targeted. Brightwing has reminded us that these enemies do not respect borders, so threats to Zul'Aman require our attention just as much as Eversong. We must deal with the troll.", ["objectivesText"] = "Speak with Maren Silverwing and Kul'amara the Fierce . Progress: When you have time continue to talk with others in our task force. We are prepared to support all of your efforts!", ["rewardGold"] = 170800, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 257411, ["x"] = 0.48, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 257411, ["x"] = 0.48, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 96080 }, ["questLines"] = { { ["id"] = 6270, ["name"] = "Void Assaults", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[94382] = { ["id"] = 94382, ["name"] = "Ritual Problems", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 94380, 94381, 94382, 94383, 96080 }, ["description"] = "To get right to it, I have laid out some lessons and some scout objectives for us as we approach the various dangers we might see in these ritual sites. I have also marked on your map the location of one of these rituals. Take care, as the magics we have seen woven at these sites can overwhelm even the most stalwart warrior.", ["objectivesText"] = "Investigate the Ritual Site Reports and then disrupt a Ritual Site in Eversong Woods or Zul'Aman. Progress: Were you successful?", ["rewardGold"] = 683200, ["rewardCurrencies"] = { { ["id"] = 3429, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 257416, ["x"] = 0.478, ["y"] = 0.496 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 257416, ["x"] = 0.478, ["y"] = 0.496 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 94383 }, ["questLines"] = { { ["id"] = 6270, ["name"] = "Void Assaults", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[94383] = { ["id"] = 94383, ["name"] = "Ritual Interest", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 94380, 94381, 94382, 94383, 96080 }, ["description"] = "I am here at the behest of the great Zul'jarra! May she lead her people to greatness. We face dire threats. Your Captain General is focused on the martial stakes, but the terrible magics unleashed recently pose an even greater danger. Our scouts have discovered rituals that risk ruin for us all. Your Ranger Captain has recruited the Lady Darkglen , who appears to be a knowledgeable and capable ritual expert. Seek her out in the tent nearby to find out how best to approach these ritual sites.", ["objectivesText"] = "Check in with Lady Darkglen .", ["rewardGold"] = 34100, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 257415, ["x"] = 0.48, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 257416, ["x"] = 0.478, ["y"] = 0.496 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 96080 }, ["questLines"] = { { ["id"] = 6270, ["name"] = "Void Assaults", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
[94385] = { ["id"] = 94385, ["name"] = "Void Assaults: Eversong Woods", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 94385 }, ["description"] = "We are seeing a Void Assault in Eversong. We need you to head out immediately to counter these threats. I will mark the strikes on your map as our scouts identify them and direct your efforts from here.", ["objectivesText"] = "Disrupt the Void Strikes around Eversong Woods.", ["rewardXP"] = 14705, ["rewardItems"] = { 264914, 272125 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 257411, ["x"] = 0.48, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 257411, ["x"] = 0.48, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 94381 }, ["db2LabelIDs"] = { 6472 }, ["db2PoiUiMapID"] = 2393 },
[94386] = { ["id"] = 94386, ["name"] = "Void Assaults: Zul'Aman", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 94386 }, ["description"] = "My scouts report a Void Assault in Zul'Aman. We need your help to counter these threats. I will direct you, and my scouts will continue to mark new activities on your map.", ["objectivesText"] = "Disrupt the Void Strikes around Zul'Aman. Progress: We will triumph over these foes!", ["rewardXP"] = 14705, ["rewardItems"] = { 264914, 272125 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 257415, ["x"] = 0.48, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 257415, ["x"] = 0.48, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 94381 }, ["db2LabelIDs"] = { 6472 }, ["db2PoiUiMapID"] = 2393 },
[94388] = { ["id"] = 94388, ["name"] = "Second Time's a Choice", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 88977, 88978, 88979, 90544, 94388 }, ["description"] = "A little lesson. Trying to fool me twice is a grave error. My dim-witted pupil has yet to return from their rendezvous with their acquaintance. Normally I would not bat an eye, but he has a journal of mine. I want that journal back. Would you be a dear and remind him?", ["objectivesText"] = "Remind Magister Meledor in the West Sanctum.", ["rewardGold"] = 32200, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2395, ["npcID"] = 257426, ["x"] = 0.445, ["y"] = 0.454 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 240403, ["x"] = 0.41, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 2395, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.454 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86735 }, ["nextQuests"] = { 88977, 88978 }, ["questLines"] = { { ["id"] = 5804, ["name"] = "Theft Tracking", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiUiMapID"] = 2395 },
