[94393] = { ["id"] = 94393, ["name"] = "Career Counseling", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 91284, 91288, 91291, 91292, 91301, 94393 }, ["description"] = "How good are you at teaching, <name>? One of my pupils, Kyltus, has been having particular trouble with deciding what path along the road of life he wants to pursue. Perhaps a talk with you will aid his tumultuous heart?", ["objectivesText"] = "Check in on Kyltus Bloodburn in the Sunstrider Isle.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 245285, ["x"] = 0.332, ["y"] = 0.742 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 245192, ["x"] = 0.425333, ["y"] = 0.145333 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 2393, 2395 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 86735 }, ["nextQuests"] = { 91284 }, ["questLines"] = { { ["id"] = 5937, ["name"] = "How to Train Your Protegee", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiUiMapID"] = 2395 },
[94396] = { ["id"] = 94396, ["name"] = "Down a Peg", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16173, ["mapID"] = 2393, ["storyline"] = { 86997, 86998, 87002, 94396 }, ["description"] = "There seems to be a problem student at the academy. I have heard reports that a student, Tytalor Goldenblade , is stirring up trouble in Sunstrider Isle. I'd go myself but I have my hands full running practice here already. Could you go check on him and... educate him of his misgivings?", ["objectivesText"] = "Check in on Tytalor Goldenblade in the Sunstrider Isle.", ["rewardGold"] = 31900, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3365, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 245285, ["x"] = 0.332, ["y"] = 0.742 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 237873, ["x"] = 0.394, ["y"] = 0.174 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 2393, 2395 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 86735 }, ["nextQuests"] = { 86997 }, ["questLines"] = { { ["id"] = 5781, ["name"] = "Aspiring Academic", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiUiMapID"] = 2395 },
[94402] = { ["id"] = 94402, ["name"] = "Old War Grudge", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 94402 }, ["description"] = "Ziadan has allied with some of the most die-hard Horde champions. The kind who despise peace and fight on whenever and wherever possible. Show them that Vidious also commands mighty champions!", ["objectivesText"] = "Enter War Mode, slay Gar'chak Skullcleave and bring me his Head. Progress: Have you slain the enemy?", ["rewardGold"] = 1024800, ["rewardXP"] = 20540, ["rewardItems"] = { 264363 }, ["rewardCurrencies"] = { { ["id"] = 1792, ["amount"] = 150 }, { ["id"] = 2123, ["amount"] = 50 }, { ["id"] = 3410, ["amount"] = 300 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 257479, ["x"] = 0.408, ["y"] = 0.84 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 257479, ["x"] = 0.408, ["y"] = 0.84 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.84 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "group" },
