[94408] = { ["id"] = 94408, ["name"] = "Contract of Service", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 94408 }, ["description"] = "It is not honor or glory that drives your kind to war...it is gold. You and your enemies are always paid for the blood you spill upon the battlefield. Every enemy you slay in Slayer's Rise carries a contract from Ziadan. Bring me those contracts, and I will pay you what their loyalty once cost her.", ["objectivesText"] = "Collect 10 Contracts of Service off slain players in War Mode. Progress: Are you here to deliver their contracts?", ["rewardGold"] = 1024800, ["rewardXP"] = 20540, ["rewardItems"] = { 264380 }, ["rewardCurrencies"] = { { ["id"] = 1792, ["amount"] = 150 }, { ["id"] = 2123, ["amount"] = 50 }, { ["id"] = 3410, ["amount"] = 300 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 257501, ["x"] = 0.408, ["y"] = 0.838 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 257501, ["x"] = 0.408, ["y"] = 0.838 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.838 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard" },
