[94417] = { ["id"] = 94417, ["name"] = "Crests of the Dawn", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 94417, 94418, 94430, 94432 }, ["description"] = "Using what I've learned from Silvermoon's artisans, Cuzolth and I can infuse your gear with additional power! Powerful equipment requires Dawncrests to upgrade it to its full potential. These crests are rewarded through many different activities. Dawncrests have five tiers, and more dangerous tasks reward you with higher-tier crests. Adventurer Dawncrests are the lowest tier, but still quite powerful! Bring me thirty Adventurer Dawncrests and we can help you upgrade your gear further.", ["objectivesText"] = "Acquire 30 Adventurer Dawncrests by defeating unique creatures, completing world activities, or by looting caches. Speak to Cuzolth to upgrade an Adventurer track item using those crests, then return to Vaskarn in Silvermoon. Progress: If you're having a hard time finding Adventurer Dawncrests, you can search for hidden treasures around Eversong, Zul'Aman, Harandar, and Voidstorm. There's no shortage of those treasures!", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 239676, ["x"] = 0.485, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 239676, ["x"] = 0.485, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 94430 }, ["questLines"] = { { ["id"] = 6119, ["name"] = "Item Upgrade Tutorial", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393, ["db2QuestInfoID"] = 282, ["db2QuestInfoName"] = "Important Quest" },
[94418] = { ["id"] = 94418, ["name"] = "Crest Transmutation", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 94417, 94418, 94430, 94432 }, ["description"] = "Did you know that crests can be transmuted into different tiers? If you find yourself with crests that are too powerful for the gear you've acquired, I can help you transmute those crests into lower tiers that you can use. And once all of your gear is sufficiently powerful, I'll be able to transmute your spare lower crests into higher ones! Let's practice the transmutation process. Here's a few Veteran Dawncrests. Speak to me and I can transform them into Adventurer Dawncrests for you.", ["objectivesText"] = "Bring 10 Veteran Dawncrests to Vaskarn in Silvermoon, then trade them for a Bundle of Adventurer Dawncrests. Progress: If you lose those Veteran Dawncrests, you can find more from powerful creatures around Eversong, Zul'Aman, Harandar, and Voidstorm. I've heard there's quite a variety of them!", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 236953 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 239676, ["x"] = 0.485, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 239676, ["x"] = 0.485, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 94432 }, ["questLines"] = { { ["id"] = 6119, ["name"] = "Item Upgrade Tutorial", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393, ["db2QuestInfoID"] = 282, ["db2QuestInfoName"] = "Important Quest" },
[94423] = { ["id"] = 94423, ["name"] = "Sanctum Secure", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 94423 }, ["description"] = "Our control here is only the beginning. Xal'atath has left other pockets of anomalies across the land. The defenses we've devised here can be used to secure those areas as well. Travel to Sunkiller Sanctum and construct five additional defenses to solidify our hold on that location. I will supply the Stormarion Core necessary to activate those defenses.", ["objectivesText"] = "Deploy 3 defenses at Sunkiller Sanctum.", ["rewardGold"] = 309800, ["rewardXP"] = 13690, ["rewardItems"] = { 246951 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16648 } }, ["questType"] = "standard" },
[94425] = { ["id"] = 94425, ["name"] = "Bleed the Spire", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["flags"] = { "elite" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15458, ["mapID"] = 2405, ["storyline"] = { 94425 }, ["objectivesText"] = "Speak to Scout Adaephus Elite Voidspire forces slain Summoning Pylons shattered Front Pylons Completed Rear Pylons Completed Right Pylon Left Pylon", ["rewardXP"] = 14705, ["starts"] = { { ["x"] = 0.488, ["y"] = 0.598, ["mapID"] = 2405 } }, ["ends"] = { { ["x"] = 0.488, ["y"] = 0.598, ["mapID"] = 2405 } }, ["coords"] = { ["mapID"] = 2405, ["x"] = 0.488, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15458 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 257704, ["text"] = "Speak to Scout Adaephus" }, { ["orderIndex"] = 1, ["type"] = 21, ["amount"] = 8, ["objectID"] = 5996, ["text"] = "Elite Voidspire forces slain" }, { ["orderIndex"] = 2, ["type"] = 2, ["amount"] = 8, ["objectID"] = 618960, ["text"] = "Summoning Pylons shattered" }, { ["orderIndex"] = 3, ["type"] = 0, ["amount"] = 5, ["objectID"] = 258664, ["text"] = "Front Pylons Completed" }, { ["orderIndex"] = 4, ["type"] = 0, ["amount"] = 5, ["objectID"] = 257814, ["text"] = "Rear Pylons Completed" }, { ["orderIndex"] = 5, ["type"] = 0, ["amount"] = 1, ["objectID"] = 258662, ["text"] = "Right Pylon" }, { ["orderIndex"] = 6, ["type"] = 0, ["amount"] = 1, ["objectID"] = 258663, ["text"] = "Left Pylon" } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405, ["db2QuestInfoID"] = 111, ["db2QuestInfoName"] = "Elite World Quest" },
[94430] = { ["id"] = 94430, ["name"] = "Adventuring Gear", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 94417, 94418, 94430, 94432 }, ["description"] = "<name>, you're just in time! I was exchanging research notes with the artisans here in Silvermoon all day. Did you know they can infuse weapons and armor with the power of the dawn itself? Fascinating! I've been itching to put some of these new techniques to the test. Bring me a piece of Adventurer equipment and I'll let you know what we need to make it more powerful. There should be plenty of people in Silvermoon and beyond willing to reward you with some Adventurer equipment in exchange for your aid.", ["objectivesText"] = "Obtain a piece of Adventurer track gear, then return to Vaskarn in Silvermoon.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 239676, ["x"] = 0.485, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 239676, ["x"] = 0.485, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6119, ["name"] = "Item Upgrade Tutorial", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393, ["db2QuestInfoID"] = 282, ["db2QuestInfoName"] = "Important Quest" },
[94432] = { ["id"] = 94432, ["name"] = "Veteran Equipment", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 94417, 94418, 94430, 94432 }, ["description"] = "We have only just begun to scratch the surface of how powerful your gear can become! However, every piece of equipment has a limit to how much it can be upgraded. The more powerful an item is at its baseline, the more powerful it will become as we upgrade it. An item's upgrade track determines which crests we must use to upgrade it. Bring me a piece of Veteran equipment this time along with ten Veteran Dawncrests. Just like before, Cuzolth will help you upgrade the item using those crests.", ["objectivesText"] = "Obtain a piece of Veteran track gear and 10 Veteran Dawncrests. Speak to Cuzolth to upgrade a Veteran track item using those crests, then return to Vaskarn in Silvermoon. Progress: If you're having trouble finding a piece of Veteran equipment, try completing a Heroic dungeon or a challenging weekly activity in Eversong, Zul'Aman, Harandar, or Voidstorm. You can find more powerful gear this way!", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 239676, ["x"] = 0.485, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 239676, ["x"] = 0.485, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 94417 }, ["questLines"] = { { ["id"] = 6119, ["name"] = "Item Upgrade Tutorial", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393, ["db2QuestInfoID"] = 282, ["db2QuestInfoName"] = "Important Quest" },
[94444] = { ["id"] = 94444, ["name"] = "Choose a Path", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredRaces"] = { 91 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 94444 }, ["description"] = "Hi. I'm Ambassador Blackguard . I am honored to welcome you to Orgrimmar, <race>. <He smiles unconvincingly.> As a lifetime of adventure unfolds before you, be assured that... uh... You know what? I've been saying this same greeting all day. Enough's enough. Talk to Chromie on top of the hourglass, then talk to your emissary. Run along.", ["objectivesText"] = "Talk to Chromie in Orgrimmar. Progress: Greetings, <name>. Has Orgrimmar been to your liking so far?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 50375, 50376, 50377, 50378, 52569 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 133407, ["x"] = 0.395, ["y"] = 0.794 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 257671, ["x"] = 0.4, ["y"] = 0.794 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.794 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["sourceQuests"] = { 90961 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85 },
[94445] = { ["id"] = 94445, ["name"] = "Choose a Path", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 94445 }, ["description"] = "Welcome to Stormwind, <race>. I invite you to explore our fair city. Say, you look like someone who appreciates the great outdoors! Elwynn is lovely this time of year. Ah, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things! After that, an emissary of yours is waiting to welcome you to the city. Sounds like a busy day for you! Have a pleasant stay, <name>!", ["objectivesText"] = "Talk to Chromie in Stormwind City.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 50375, 50376, 50377, 50378, 52569 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 133362, ["x"] = 0.530667, ["y"] = 0.150667 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 249187, ["x"] = 0.538, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.530667, ["y"] = 0.150667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 90961 }, ["db2PoiUiMapID"] = 84 },
[94446] = { ["id"] = 94446, ["name"] = "A Nightmarish Task", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 94446 }, ["description"] = "Excellent work so far, $p. But there is always more to be done. Go out and hunt the most powerful targets available to us with all the fury our magic has to offer.", ["objectivesText"] = "Complete Nightmare Hunts in Prey.", ["rewardItems"] = { 253342, 275910 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 500 }, { ["id"] = 3345, ["amount"] = 20 }, { ["id"] = 3346, ["amount"] = 20 }, { ["id"] = 3392, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 246231, ["x"] = 0.565333, ["y"] = 0.654667 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 246231, ["x"] = 0.565333, ["y"] = 0.654667 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.565333, ["y"] = 0.654667 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 92182 } },
[94447] = { ["id"] = 94447, ["name"] = "Ophidia the Broodmother", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "Zawadi safe, eh? Good. No harm should come to her. We need to deal with these oversized worms. Just over there, by de beach, is one of their broodmothers. Vile creature! Responsible for all de eggs you see 'round here. Kill her. Their invasion will stall, giving my people more time to organize a strike. I need to tend my wounds. I will hide and wait for you.", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3504, ["amount"] = 100 } }, ["starts"] = { { ["npcID"] = 255978, ["x"] = 0.646, ["y"] = 0.378, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 254376, ["x"] = 0.66, ["y"] = 0.39, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.646, ["y"] = 0.378, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93576 }, ["questLines"] = { { ["id"] = 6118, ["name"] = "The Troubles of Mlurkkr Mire", ["orderIndex"] = 4, ["flags"] = 0 } } },
