[94623] = { ["id"] = 94623, ["name"] = "Building the Voidforge", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 94623 }, ["description"] = "I have been considering how I may offer you greater strength, my friend. I've come up with something, but I need your help building a proper Voidforge. What? Oh, fear not, all my ulterior motives are still aligned with your cause. For now. To begin, I need one Elementary Voidcore. You will be able to find shards from the more powerful foes you habitually encounter. Inflict your usual violence, return the shards, and I can weave them back into a true Voidcore to serve as the forge's foundation.", ["objectivesText"] = "Deliver Elemental Voidcore Shards from Midnight Season 1 raid bosses, Bountiful Delves, and Mythic+ dungeons to begin constructing the Voidforge. Progress: Back already, <name>? Pick up any fresh scars?", ["rewardGold"] = 1366400, ["rewardXP"] = 27380, ["rewardItems"] = { 265695 }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 235697, ["x"] = 0.512, ["y"] = 0.703 }, { ["mapID"] = 2405, ["npcID"] = 243907, ["x"] = 0.512, ["y"] = 0.684 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 243907, ["x"] = 0.512, ["y"] = 0.684 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.703 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405, ["db2QuestInfoID"] = 282, ["db2QuestInfoName"] = "Important Quest" },
[94625] = { ["id"] = 94625, ["name"] = "An Elementary Voidcore", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 94625 }, ["description"] = "The work continues. Find enough shards and we can fuse them back into an Elemental Voidcore. I have acquired sufficient reagents to transmute $30474w cores in total thus far. The nascent Voidforge will require $30506W before it is fully formed, and you have generously contributed $3409cur so far. Go out and indulge in a bit more violence, will you?", ["objectivesText"] = "Collect Elementary Voidcore Shards from Midnight Season 1 raid bosses, Bountiful Delves, and Mythic+ dungeons. Progress: You certainly weren't in any rush with this one, <name>. I suppose the gates of time can't be rushed, can they?", ["rewardGold"] = 1366400, ["rewardXP"] = 27380, ["rewardItems"] = { 265695 }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 243907, ["x"] = 0.512, ["y"] = 0.684 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 243907, ["x"] = 0.512, ["y"] = 0.684 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.684 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 94623 }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405, ["db2QuestInfoID"] = 282, ["db2QuestInfoName"] = "Important Quest" },
