[94677] = { ["id"] = 94677, ["name"] = "The Missing Rootwarden", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["storyline"] = { 86836, 86851, 86855, 86856, 86857, 86858, 86859, 86860, 86861, 86862, 86864, 86865, 86866, 86867, 86874, 86877, 86880, 86881, 86882, 86890, 94677 }, ["description"] = "Something keeps troubling me about this, $p. Where is the Rootwarden? Ruia has a solemn duty to watch over the World Tree and the land around it. He should be here, with his people in need. So where could he be when they are in crisis? What is he thinking? I am sure that we can find clues to where he has gone if we search his town. Perhaps we can learn more about his state of mind along the way.", ["objectivesText"] = "Find 3 Ruia's Musings in Har'alnor. Progress: The Rootwarden should be here. We must find out what would be so pressing that would take him away from his responsibilities.", ["rewardGold"] = 170800, ["rewardXP"] = 6085, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3370, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2413, ["npcID"] = 237325, ["x"] = 0.314, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 2413, ["npcID"] = 237356, ["x"] = 0.319333, ["y"] = 0.715333 } }, ["coords"] = { ["mapID"] = 2413, ["source"] = "quest_giver", ["x"] = 0.314, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["sourceQuests"] = { 86865 }, ["questLines"] = { { ["id"] = 5726, ["name"] = "Call of the Goddess", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5726, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2694, ["db2PoiUiMapID"] = 2413 },
