[94790] = { ["id"] = 94790, ["name"] = "Research Console: Exploring the Void", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 94790 }, ["description"] = "No rest for the researchers, as they say. As much as I would love to go traipsing around this blasted voidscape, I need to remain at this post. But you! You can be our eyes and ears in the abyss. Go and explore the Voidstorm , maybe we can find some additional samples to feed into the console.", ["objectivesText"] = "Complete 3 World Quests for Void Researcher Anomander in Howling Ridge. Progress: Back so soon?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3400, ["amount"] = 1 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 248328, ["x"] = 0.525, ["y"] = 0.728 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 248328, ["x"] = 0.525, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 93970 }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
