[94835] = { ["id"] = 94835, ["name"] = "Early Morning Training", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 94835 }, ["description"] = "Interested in enrolling in a training program? Some of the strongest warriors have emerged from hard work and dedication. With some practice, <name>, you surely can join their ranks. Begin today!", ["objectivesText"] = "Win Battlegrounds in Training Grounds or against players. Progress: You have yet to finish your training for the week.", ["rewardItems"] = { 267076 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "pvp" },
