[94844] = { ["id"] = 94844, ["name"] = "Voidscar Arena: For My Horde", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 91566, 91603, 91606, 91694, 94844, 94845, 94848, 94849, 94855 }, ["description"] = "We must repel this attack. Your Horde is strong. You do not give in to the hypocritical claims of the Alliance. You do not let them besmirch your honor. I want my forces to learn from you. Go, take this Voidclarion. Use it to inspire my void minions. Let them see the power of the Horde.", ["objectivesText"] = "Empower 8 Hatebound forces at the Bastion of Might in Slayer's Rise.", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 260948, 266183 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 }, { ["id"] = 3410, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 247374, ["x"] = 0.235, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 256796, ["x"] = 0.505, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.235, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 91566 }, ["questLines"] = { { ["id"] = 5964, ["name"] = "Breaking the Triad", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[94845] = { ["id"] = 94845, ["name"] = "Voidscar Arena: The Bastion of Might", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 91566, 91603, 91606, 91694, 94844, 94845, 94848, 94849, 94855 }, ["description"] = "Vidious presses an attack. I do not see this Alliance he recruited, but monsters. Illogical. Vidious would not recruit another force until we had our fun with the recent additions. Fight these monsters. Find out what they are. Bring me evidence. Perhaps you need a cause to fight for beyond amusement? If Vidious tires of me, he will turn his conquest to Azeroth next. You'll want to stop that, right? Then aid me.", ["objectivesText"] = "Collect 12 Spiteful Shadowgraft from wild creatures in the Bastion of Might. Progress: What trickery have you found?", ["rewardGold"] = 341600, ["rewardXP"] = 12845, ["rewardItems"] = { 247422 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 }, { ["id"] = 3410, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 247374, ["x"] = 0.235, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 256796, ["x"] = 0.505, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.235, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 91566 }, ["questLines"] = { { ["id"] = 5964, ["name"] = "Breaking the Triad", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[94847] = { ["id"] = 94847, ["name"] = "Preparations Underway", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 139, ["mapID"] = 23, ["storyline"] = { 45770, 46069, 46070, 46071, 46074, 46083, 91618, 94847 }, ["series"] = { 45770, 46069, 46070, 46071, 46074, 46081, 46083, 91618 }, ["description"] = "As you may or may not recall, I once helped young paladins obtain their first armored mount. It was a tedious task that involved months of obtaining materials and sending them all over Azeroth. Thankfully, times have changed and we now have most of those materials at hand. That being said, I wish to help you obtain a new mount, something worthy of your title as Highlord. In order for us to begin, I only require that you obtain a barding for us. Something strong, thick, and heavy.", ["objectivesText"] = "Obtain a Stonehide Leather Barding from a leatherworker. You may also obtain it from the auction house if you're not a leatherworker or don't know a leatherworker.", ["rewardGold"] = 19570, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["ends"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.523, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90250, ["questTurnInID"] = 90250, ["questType"] = "standard", ["sourceQuests"] = { 46069 }, ["questLines"] = { { ["id"] = 302, ["name"] = "Class Mount: Paladin", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 302, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 24 },
[94848] = { ["id"] = 94848, ["name"] = "Voidscar Arena: Pre-Provoked Violence", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 91566, 91603, 91606, 91694, 94844, 94845, 94848, 94849, 94855 }, ["series"] = { 94849, 94855 }, ["description"] = "Vidious, using shadowgraft? Unbelievable. He is better than this. How dare he disappoint me. I need no shadowgraft to convince mighty <class>s like you to fight for me. Show him the error of his ways before he disappoints me further and abandons this conflict in favor of helping Xal'atath conquer Azeroth. Take the fight to him. Siege his bastion. And if you do not wish to stain your hands with Alliance blood, there are many void minions awaiting your prowess.", ["objectivesText"] = "Slay Void creatures or players in the Bastion of Valor in Slayer's Rise. Progress: Do you possess what it takes to survive in these lands, <race>?", ["rewardGold"] = 309800, ["rewardXP"] = 12845, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3389, ["amount"] = 50 }, { ["id"] = 3410, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 256796, ["x"] = 0.505, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 256796, ["x"] = 0.505, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 94844, 94845 }, ["questLines"] = { { ["id"] = 5964, ["name"] = "Breaking the Triad", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[94849] = { ["id"] = 94849, ["name"] = "Voidscar Arena: A Familiar Grudge", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 91566, 91603, 91606, 91694, 94844, 94845, 94848, 94849, 94855 }, ["series"] = { 94848, 94855 }, ["description"] = "Vidious will have a favorite, much like I do: a mortal from your world filled with grief turned to violence. They do not have the support of your leaders, but they will always have support from us domanaar. Find this favorite. I hear of a warlock that has slain many Horde. I feel their grief wafting in the air. They are so lost in it, they would give up the war to save Azeroth for a chance to kill your people. Go. Savor the fight.", ["objectivesText"] = "Slay Emrin Sparkpox at the Bastion of Valor in Slayer's Rise.", ["rewardGold"] = 683200, ["rewardXP"] = 16055, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3389, ["amount"] = 100 }, { ["id"] = 3410, ["amount"] = 400 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 256796, ["x"] = 0.505, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 256796, ["x"] = 0.505, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 94844, 94845 }, ["questLines"] = { { ["id"] = 5964, ["name"] = "Breaking the Triad", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
[94850] = { ["id"] = 94850, ["name"] = "If You Build It", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 46237, 46238, 46239, 46240, 46241, 46242, 46243, 94850 }, ["description"] = "If we wish to achieve a sustained connection to Xoroth, we'll need a particularly resilient portal. Unfortunately, we can't just summon this one up from the ground. I will need you to gather the requisite materials. Once we have them, I will have the mo'arg begin construction at once. Here's the list of what you'll need.", ["objectivesText"] = "Collect 5 Felslate, 3 Chaotic Spinel and an Unbending Potion. These can be gathered and crafted using profession skills or purchased on the Auction House.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 29784, 29785, 29786, 30398, 33226, 63227, 63228, 63229, 144328, 156937, 157009, 157010, 158611, 158612, 158613, 158614, 160189, 160190, 160191, 160192, 167649, 178061, 183830 }, ["starts"] = { { ["npcID"] = 119166, ["x"] = 0.354, ["y"] = 0.382, ["mapID"] = 717 } }, ["ends"] = { { ["npcID"] = 119166, ["x"] = 0.354, ["y"] = 0.382, ["mapID"] = 717 } }, ["coords"] = { ["x"] = 0.354, ["y"] = 0.382, ["source"] = "quest_giver", ["mapID"] = 717 }, ["mapCandidates"] = { ["npc"] = { 717 }, ["zone"] = { 7875 } }, ["questType"] = "standard", ["sourceQuests"] = { 46237 }, ["questLines"] = { { ["id"] = 315, ["name"] = "Class Mount: Warlock", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 315, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[94855] = { ["id"] = 94855, ["name"] = "Voidscar Arena: Setting It Aside", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2444, ["storyline"] = { 91566, 91603, 91606, 91694, 94844, 94845, 94848, 94849, 94855 }, ["series"] = { 94848, 94849 }, ["description"] = "So, we have another enemy? One who would get in between me and Vidious? < Ziadan tightens her fist around her weapon.> Unacceptable. The Voidscar Arena to the north is the most strategic position outside of our bastions. An interloping domanaar will have staged their forces there, I guarantee it. I can set aside my quarrel with Vidious long enough to deal with this shared threat. Fortunately for you, he hasn't brought his Alliance forces with him.", ["objectivesText"] = "Meet the domanaar at the Voidscar Arena in Slayer's Rise.", ["rewardGold"] = 30900, ["rewardXP"] = 1605, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3389, ["amount"] = 10 }, { ["id"] = 3410, ["amount"] = 40 } }, ["starts"] = { { ["mapID"] = 2444, ["npcID"] = 256796, ["x"] = 0.505, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 2444, ["npcID"] = 256813, ["x"] = 0.535, ["y"] = 0.215 } }, ["coords"] = { ["mapID"] = 2444, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 2444 }, ["zone"] = { 15958 } }, ["questType"] = "standard", ["sourceQuests"] = { 94848, 94849 }, ["questLines"] = { { ["id"] = 5964, ["name"] = "Breaking the Triad", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2444 },
