[94867] = { ["id"] = 94867, ["name"] = "Lost in Atal'Abasi", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["description"] = "Tolbani and Jehnira have been missin' for some time. Last I heard, dey were scoutin' Atal'Abasi for supplies. That area is covered in murlocs. Too many of 'em is dangerous even for an Amani. Find dem and make sure dey alright!", ["rewardGold"] = 33500, ["rewardXP"] = 1520, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 5 }, { ["id"] = 3354, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 258950, ["x"] = 0.45, ["y"] = 0.682, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 258950, ["mapID"] = 2437, ["x"] = 0.45054, ["y"] = 0.682458 }, { ["npcID"] = 245669, ["x"] = 0.53, ["y"] = 0.628, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.45, ["y"] = 0.682, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 86652 }, ["nextQuests"] = { 91069, 91070, 91071 }, ["questLines"] = { { ["id"] = 5939, ["name"] = "Vengeance for Tolbani", ["orderIndex"] = 0, ["flags"] = 1 } } },
[94868] = { ["id"] = 94868, ["name"] = "It Takes Two", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["description"] = "Jan'alai is a hen! And dat means eggs! De eggs of de loa are volatile! Dey must be hatched carefully. My family carried dis honor for generations, but de tradition died when my older brothers followed de false promises of Zul'jin. Sadly, I am de only brother left, and we need two hatchers for de ritual! Find my niece, Shaja , down by de shore. She is too young to know de ritual, but de loa's favor flows through her veins as it did my brothers'. It is time for her to know this honor.", ["rewardGold"] = 170800, ["rewardXP"] = 6085, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 245512, ["x"] = 0.55, ["y"] = 0.182, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 264710, ["x"] = 0.55, ["y"] = 0.184, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.55, ["y"] = 0.182, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6128, ["name"] = "A Fiery Blast from the Past", ["orderIndex"] = 0, ["flags"] = 0 } } },
[94869] = { ["id"] = 94869, ["name"] = "Hungry Hungry Hatchlings", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 94868, 94869, 94870, 94882, 94883 }, ["description"] = "We will soon be blessed with eggs! Jan'alai has told me so. And once dem eggs hatch, we'll have many hungry mouths to feed! Dey will crave somethin' soft, delicate, and pungent. Ya best scurry down to de shore and find somethin' to tempt de hatchlings with or dey may take a nibble out of you!", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardItems"] = { 12206 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 245512, ["x"] = 0.55, ["y"] = 0.182, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 621773, ["x"] = 0.551, ["y"] = 0.183, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.55, ["y"] = 0.182, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6128, ["name"] = "A Fiery Blast from the Past", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2437 },
[94870] = { ["id"] = 94870, ["name"] = "Eggstra Protection Never Hurts", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["description"] = "De eggs are nearly ready! Ya may know somethin' about dis, eh? Jan'alai tells me so. What ya lack in blood, ya make up for in spirit. Help me teach Shaja! Ya spirit alone is not enough for dis ritual. De eggs are imbued with de power of de loa herself and will burst with fiery energy! We can protect ya from dis, but first we need feathers. Loa feathers! Collect dem from around de temple... unless ya dare ask de loa herself!", ["rewardGold"] = 341600, ["rewardXP"] = 12170, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 245512, ["x"] = 0.55, ["y"] = 0.182, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 245512, ["x"] = 0.55, ["y"] = 0.182, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.55, ["y"] = 0.182, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 94868, 94869 }, ["questLines"] = { { ["id"] = 6128, ["name"] = "A Fiery Blast from the Past", ["orderIndex"] = 3, ["flags"] = 0 } } },
[94871] = { ["id"] = 94871, ["name"] = "Eversong", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["storyline"] = { 89193, 89388, 89402, 94871, 94957 }, ["description"] = "Magistrix Landra Dawnstrider has sent a request for aid in dealing with the local Lightbloom. While typically harmless, it has recently begun to grow at an incredible rate. Meet up with Arator in Fairbreeze Village to investigate the threat and provide what assistance you can.", ["objectivesText"] = "Journey to Fairbreeze Village.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 232875, 264914 }, ["starts"] = { { ["npcID"] = 240523, ["mapID"] = 2393, ["x"] = 0.455998, ["y"] = 0.703362 } }, ["ends"] = { { ["mapID"] = 2395, ["npcID"] = 236739, ["x"] = 0.466, ["y"] = 0.456 }, { ["npcID"] = 240523, ["mapID"] = 2393, ["x"] = 0.455998, ["y"] = 0.703362 } }, ["coords"] = { ["source"] = "quest_giver", ["mapID"] = 2393, ["x"] = 0.455998, ["y"] = 0.703362 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 86735 }, ["questLines"] = { { ["id"] = 5719, ["name"] = "Whispers in the Twilight", ["orderIndex"] = 13, ["flags"] = 1 }, { ["id"] = 6131, ["name"] = "Midnight Scouting Map", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5719, ["questLineOrder"] = 1 } }, ["db2AdventureMapPoiID"] = 195, ["db2PoiUiMapID"] = 2395 },
[94882] = { ["id"] = 94882, ["name"] = "Perfect Timing", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["description"] = "All is ready! I will now guide ya both through de hatchin' ceremony! Talk to Shaja and she will use de feathers to protect ya from dem powerful loa energies.", ["rewardGold"] = 170800, ["rewardXP"] = 6085, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3354, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 245512, ["x"] = 0.55, ["y"] = 0.182, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 245512, ["x"] = 0.55, ["y"] = 0.182, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.55, ["y"] = 0.182, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 94870 }, ["questLines"] = { { ["id"] = 6128, ["name"] = "A Fiery Blast from the Past", ["orderIndex"] = 4, ["flags"] = 0 } } },
[94883] = { ["id"] = 94883, ["name"] = "Like Dragonhawks to a Flame", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["description"] = "I know my uncle can seem... off at times. His talk of de loa always felt like childhood stories to me. But ever since Jan'alai returned, I feel her energy too! She flickers, she smolders, she burns red hot. She also brings warmth, light, and life! But what I feel from her right now is distress--dat of a mother hen counting her chicks but comin' up short. Let's check on de hatchlings. We can cover more ground if we split up.", ["rewardGold"] = 670000, ["rewardXP"] = 15215, ["rewardItems"] = { 271185 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3354, ["amount"] = 250 } }, ["starts"] = { { ["npcID"] = 264710, ["x"] = 0.55, ["y"] = 0.184, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 264710, ["x"] = 0.55, ["y"] = 0.184, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.55, ["y"] = 0.184, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 94882 }, ["questLines"] = { { ["id"] = 6128, ["name"] = "A Fiery Blast from the Past", ["orderIndex"] = 2, ["flags"] = 0 } } },
[94909] = { ["id"] = 94909, ["name"] = "Blessings of Pestilence", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 94909 }, ["description"] = "<This idol proves the depth of your bond with pestilence. Speak with Du'gal at the Altar of Blessings in Amani'Zar to begin worshipping Mot'amra.>", ["objectivesText"] = "Speak with Du'gal at the Altar of Blessings in Amani'Zar.", ["rewardGold"] = 31200, ["rewardXP"] = 1520, ["rewardItems"] = { 266438 }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 256510, ["x"] = 0.43, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["db2QuestHubAreaPoiID"] = 8504, ["startItems"] = { 266438 } },
[94910] = { ["id"] = 94910, ["name"] = "Blessings of Growth", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 94910 }, ["description"] = "<This idol proves the depth of your bond with growth. Speak with Du'gal at the Altar of Blessings in Amani'Zar to begin worshipping Oe.>", ["objectivesText"] = "Speak with Du'gal at the Altar of Blessings in Amani'Zar.", ["rewardGold"] = 31200, ["rewardXP"] = 1520, ["rewardItems"] = { 266440 }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 256510, ["x"] = 0.43, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["db2QuestHubAreaPoiID"] = 8504, ["startItems"] = { 266440 } },
[94920] = { ["id"] = 94920, ["name"] = "Hal'hadar Battery Core", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15458, ["mapID"] = 2393, ["storyline"] = { 94920 }, ["description"] = "<The Hal'hadar battery core has been damaged, exposing its inner workings. Amidst the thin energy wires and familiar metalwork seen in K'areshi technology, you spot gleaming yellow crystals fitted into a golden frame. Small runic letters on the metal are inscribed under it. Perhaps one of the ethereals in the Howling Ridge in the Voidstorm could help identify this.>", ["objectivesText"] = "Learn more about the Hal'hadar and their technology. Progress: I may not have fought these ethereals like Baraat has, but I am quite familiar with their technology. I decoded many of their encrypted schematics taken from the field. Their use of technomancy and arcanic formula is quite advanced.", ["rewardGold"] = 170800, ["rewardXP"] = 5885, ["rewardItems"] = { 266448 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 400 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 259688, ["x"] = 0.52, ["y"] = 0.341 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.341 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["startItems"] = { 266448 } },
[94932] = { ["id"] = 94932, ["name"] = "Bindings of the Windlord", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 94932 }, ["series"] = { 43558, 43560, 43796, 44093, 44094, 44095, 44096, 44097 }, ["description"] = "With Thunderaan risen again as the lord of Skywall, there may indeed be an arrangement you can make in exchange for those wretched implements. But one binding is of no use on its own. Return to me with both bindings, and with powerful enough ore to bind them, and I will arrange your audience with Thunderaan the Windlord.", ["objectivesText"] = "Retrieve both Bindings of the Windlord and 10 Infernal Brimstone. Progress: Yes, <race>?", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 139466, 139468 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92218, ["x"] = 0.408, ["y"] = 0.808 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92218, ["x"] = 0.408, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.808 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39652 } },
[94933] = { ["id"] = 94933, ["name"] = "Lessons in the Void", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15336, ["mapID"] = 2393, ["storyline"] = { 86786, 89323, 89324, 89325, 89326, 89327, 90972, 91044, 94933 }, ["description"] = "Ah, you're there! Our esteemed Magister Umbric has tasked me with wrangling an able-bodied champion to assist him. An apprentice of his, Leona Darkstrider, is investigating the techniques and methods of the illidari. It appears her inquiries may have put her in a bit of trouble. The Magister can fill you in. He's in K'aresh now, and he's allowed me to open the way for you if you require transportation.", ["objectivesText"] = "Meet up with Umbric in Shand'orah in K'aresh .", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 257544, ["x"] = 0.535, ["y"] = 0.66 }, { ["mapID"] = 84, ["npcID"] = 259942, ["x"] = 0.505, ["y"] = 0.165 }, { ["mapID"] = 2339, ["npcID"] = 259951, ["x"] = 0.445, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 2371, ["npcID"] = 248153, ["x"] = 0.608, ["y"] = 0.278 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 84, 2339, 2371, 2393 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 84967 }, ["questLines"] = { { ["id"] = 5770, ["name"] = "In Search of Darkness", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiMapID"] = 2738, ["db2PoiUiMapID"] = 2371 },
[94936] = { ["id"] = 94936, ["name"] = "A Bond of Brothers", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "My brother Tekkan and I were part of a team. Our friend Kariz died fighting de snakes. Kariz's younger brother, Jabat, was consumed by vengeance. He is young and hot-headed, blind to his actions. He took off to kill de snakes. He is in great danger. The Right Spear doesn't want to send a rescue, and I won't let their mother cry twice. We are going to get Jabat. We need to plan an escape route for when we find Jabat. Tekkan can handle snake burrows with his explosives, but we need a muscle. You in?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 258717, ["x"] = 0.564, ["y"] = 0.43, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 259075, ["x"] = 0.532, ["y"] = 0.35, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.564, ["y"] = 0.43, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93024 }, ["questLines"] = { { ["id"] = 6329, ["name"] = "A Bond of Brothers", ["orderIndex"] = 0, ["flags"] = 0 } } },
[94937] = { ["id"] = 94937, ["name"] = "Too Quiet on the Northern Front", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "I only have one small explosive left. Even if Aol'ggin is right about my methods, we can't go back now. I... Tekkan chokes on his words, then clears his throat.> We can do dis. You lure de snakes out and deal with dem so I can safely blow up de burrow. De escape route will be cleared after dat.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 259295, ["x"] = 0.532, ["y"] = 0.35, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 259298, ["x"] = 0.534, ["y"] = 0.334, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.532, ["y"] = 0.35, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 94936 }, ["questLines"] = { { ["id"] = 6329, ["name"] = "A Bond of Brothers", ["orderIndex"] = 1, ["flags"] = 0 } } },
[94941] = { ["id"] = 94941, ["name"] = "Saving Recruit Jabat", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "That large snake was the one who killed Kariz. And now I see Jabat is wounded and in danger. Tekkan is not responsive. I don't know what is wrong with him. There is no time to waste and I don't want to ask what else can go wrong. Dis is bad luck. Check on Jabat or take out de large snake right away. Whatever you decide to do first, dat large snake must die.", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["rewardItems"] = { 278889, 278890, 278891, 278892 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3504, ["amount"] = 250 } }, ["starts"] = { { ["npcID"] = 259297, ["x"] = 0.534, ["y"] = 0.334, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 259076, ["x"] = 0.564, ["y"] = 0.432, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.534, ["y"] = 0.334, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 94937 }, ["questLines"] = { { ["id"] = 6329, ["name"] = "A Bond of Brothers", ["orderIndex"] = 2, ["flags"] = 0 } } },
[94954] = { ["id"] = 94954, ["name"] = "Darkspear Dash", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 14, ["mapID"] = 1, ["description"] = "Today, celebrate da Darkspear footrunners. Long ago, our footrunners ran 'round all da troll empire deliverin' important messages. Dey carried their messages through battle an' storm an' were famous for dey courage. Today we be celebratin' not dey courage in war, but da courage of some of da messages dey carried--messages of peace an' hope for a better world. Help us send a message of hope by joinin' our symbolic run ta Silvermoon. Ya be ready? Well go, mon!", ["rewardGold"] = 683200, ["rewardItems"] = { 267323 }, ["starts"] = { { ["npcID"] = 259191, ["x"] = 0.468, ["y"] = 0.476, ["mapID"] = 463 } }, ["ends"] = { { ["npcID"] = 259397, ["x"] = 0.624, ["y"] = 0.382, ["mapID"] = 110 }, { ["npcID"] = 259397, ["x"] = 0.446, ["y"] = 0.786, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.468, ["y"] = 0.476, ["source"] = "quest_giver", ["mapID"] = 1 }, ["mapCandidates"] = { ["npc"] = { 110, 463, 2393 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 95009 } },
[94957] = { ["id"] = 94957, ["name"] = "War of Light and Shadow", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16215, ["mapID"] = 2424, ["storyline"] = { 88696, 88697, 88698, 88699, 88700, 88701, 88702, 88703, 88704, 88705, 88706, 90777, 91417, 91426, 94957 }, ["description"] = "The Vanguard has begun to rally its forces to confront the Devouring Host. Report to Lady Liadrin at the Sunwell to join the offensive.", ["objectivesText"] = "Speak to Liadrin at the Sunwell. Progress: The Devouring Host tried to break us. Soon, they will face the combined might of the Vanguard.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["starts"] = { { ["x"] = 0.455, ["y"] = 0.704, ["mapID"] = 2393, ["npcID"] = 240523 } }, ["ends"] = { { ["mapID"] = 2424, ["npcID"] = 247414, ["x"] = 0.53, ["y"] = 0.585 } }, ["coords"] = { ["mapID"] = 2424, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.585 }, ["mapCandidates"] = { ["npc"] = { 2424 }, ["zone"] = { 16215 } }, ["questGiverID"] = 240523, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5792, ["name"] = "Foothold", ["orderIndex"] = 14, ["flags"] = 1 }, { ["id"] = 6131, ["name"] = "Midnight Scouting Map", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 284, ["title"] = "The War of Light and Shadow", ["questLineID"] = 5792, ["questLineOrder"] = 0 } }, ["db2AdventureMapPoiID"] = 566, ["db2PoiUiMapID"] = 2424 },
