[94993] = { ["id"] = 94993, ["name"] = "Adventuring in Midnight", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 86733, 86734, 86736, 86737, 86738, 86739, 86740, 86741, 86742, 86743, 86744, 86745, 94871, 94993, 95008 }, ["description"] = "The Void encroaches on Azeroth from all sides. Visit the Scouting Map in the Sanctum of Light and choose where you will make your stand.", ["objectivesText"] = "Review the Scouting Map and choose where to begin the Midnight campaign.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["x"] = 0.457, ["y"] = 0.677, ["mapID"] = 2393 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 235386, ["x"] = 0.452, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5719, ["name"] = "Whispers in the Twilight", ["orderIndex"] = 14, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5719, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 2393 },
