[95008] = { ["id"] = 95008, ["name"] = "Adventuring in Midnight", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 86733, 86734, 86735, 86736, 86737, 86738, 86739, 86740, 86741, 86742, 86743, 86744, 86745, 94871, 94993, 95008 }, ["description"] = "It's rare that we get to choose our paths in life, but you seem like someone who's seen it all before. < Soridormi winks.> Don't dally, this war won't win itself. Go to the Sanctum of Light. Choose where you'll make your first stand.", ["objectivesText"] = "Review the Scouting Map and choose where to begin the Midnight campaign.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 250352 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 259153, ["x"] = 0.556, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 259153, ["x"] = 0.556, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questTurnInID"] = 259153, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5719, ["name"] = "Whispers in the Twilight", ["orderIndex"] = 15, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5719, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 2393 },
[95009] = { ["id"] = 95009, ["name"] = "Doing the Dash", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 6453, ["mapID"] = 463, ["description"] = "Have you heard about the race today? Thousands of trolls are gathering to run to Silvermoon City for a celebration! Kalaya could tell you more. They're setting up at the Echo Isles now!", ["rewardGold"] = 30900, ["starts"] = { { ["x"] = 0.46, ["y"] = 0.55, ["mapID"] = 2339, ["npcID"] = 220307 } }, ["ends"] = { { ["npcID"] = 259191, ["x"] = 0.468, ["y"] = 0.476, ["mapID"] = 463 } }, ["coords"] = { ["mapID"] = 2339, ["x"] = 0.46, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 463 }, ["zone"] = { 6453 } }, ["questGiverID"] = 220307, ["questType"] = "standard", ["nextQuests"] = { 94954 } },
[95021] = { ["id"] = 95021, ["name"] = "Prey: Janoa the Fang (Nightmare)", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["mapID"] = 2395, ["description"] = "This creature has established a reputation for particularly vicious ambushes. Envenomed fangs flashing in the dark, followed by frenzied thrashing and then... stillness. See if you cannot give it a taste of its own venom.", ["rewardXP"] = 20540, ["starts"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["ends"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["coords"] = { ["mapID"] = 2393, ["x"] = 0.568, ["y"] = 0.653 }, ["questGiverID"] = 245824, ["questTurnInID"] = 245824, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5945, ["name"] = "Prey", ["orderIndex"] = 90, ["flags"] = 0 } } },
[95022] = { ["id"] = 95022, ["name"] = "Prey: Kursak the Coiled (Nightmare)", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["mapID"] = 2395, ["description"] = "Do not let this serpentine monstrosity get close, $p, lest you have the life squeezed out of you. My servants recently found one of its unfortunate victims. Like a fistful of mashed grapes... Apologies, I lost myself for a moment there.", ["rewardXP"] = 20540, ["starts"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["ends"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["coords"] = { ["mapID"] = 2393, ["x"] = 0.568, ["y"] = 0.653 }, ["questGiverID"] = 245824, ["questTurnInID"] = 245824, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5945, ["name"] = "Prey", ["orderIndex"] = 91, ["flags"] = 0 } } },
[95023] = { ["id"] = 95023, ["name"] = "Prey: Batani the Scaled (Nightmare)", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["mapID"] = 2395, ["description"] = "I have heard that this creature has scales so thick and sharp you could use them to filet a fish. Do not let its diminutive stature fool you, $p, it was bred for one purpose. To kill. Fortunately, not being killed is something you've grown quite proficient in.", ["rewardXP"] = 20540, ["starts"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["ends"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["coords"] = { ["mapID"] = 2393, ["x"] = 0.568, ["y"] = 0.653 }, ["questGiverID"] = 245824, ["questTurnInID"] = 245824, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5945, ["name"] = "Prey", ["orderIndex"] = 92, ["flags"] = 0 } } },
[95024] = { ["id"] = 95024, ["name"] = "Prey: Kadani the Claw (Nightmare)", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["mapID"] = 2395, ["description"] = "The claw! A miracle of the natural world. An appendage located at the cutting edge of murderous millennia. This creature is all claw and cunning, and you would do best to not fall prey to its violent nature.", ["rewardXP"] = 20540, ["starts"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["ends"] = { { ["x"] = 0.568, ["y"] = 0.653, ["mapID"] = 2393, ["npcID"] = 245824 } }, ["coords"] = { ["mapID"] = 2393, ["x"] = 0.568, ["y"] = 0.653 }, ["questGiverID"] = 245824, ["questTurnInID"] = 245824, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5945, ["name"] = "Prey", ["orderIndex"] = 93, ["flags"] = 0 } } },
[95069] = { ["id"] = 95069, ["name"] = "Torn Twilight Missive", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 95069 }, ["description"] = "<The Twilight Missive reads: \"Our search presses on yet we remain as divided as ever. If we don't unite, then we truly deserved to be abandoned by her! Of our surviving Speakers, two refuse my missives. Lazaar rallies survivors in the ruins of Deatholme, while Ger'lock amasses a host at the Broken Throne. The others have yet to declare for them, which buys us time to continue our search. We may yet salvage our broken cause.\" The Ranger Captain will want to see this.>", ["objectivesText"] = "Take the Twilight Missive to Silvermoon.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 268807 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 400 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 255368, ["x"] = 0.275, ["y"] = 0.765 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.275, ["y"] = 0.765 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["startItems"] = { 268807 } },
[95070] = { ["id"] = 95070, ["name"] = "Permafrosted Keystone", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15458, ["mapID"] = 2393, ["storyline"] = { 95070 }, ["description"] = "<Several void-touched runes flicker across the keystone's surface before dissipating one by one. As the last rune fades, so does the faint hum of power within, leaving nothing but a painfully cold sphere of dark green metal.> Although it doesn't resemble other domanaar artifacts, there was no mistaking the cold, dark magic. Perhaps Decimus in the Howling Ridge can provide you with more information.>", ["objectivesText"] = "Show the Keystone to someone familiar with Domanaar relics.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 268808 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 400 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 262823, ["x"] = 0.508, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["startItems"] = { 268808 } },
[95071] = { ["id"] = 95071, ["name"] = "Enchanted Naga Scroll", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 95071 }, ["description"] = "<The enchanted scroll shimmers with an arcane glint, the text vaguely resembling the elven language. You presume it is written in the language of the naga, though the arcane-laced ink appears to move the letters around the scroll. Perhaps a Magister in Silvermoon can help you translate it.>", ["objectivesText"] = "Take the Enchanted Naga Missive to someone in Silvermoon City . Progress: Yes, <name>?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 268809 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 400 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["startItems"] = { 268809 } },
[95114] = { ["id"] = 95114, ["name"] = "Prey: A Crimson Summons", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 95114 }, ["description"] = "Ah, $p. I have been looking for you. My... contacts have told me much regarding your continued attempts to defend our beloved city. But there is another way. Come, join me in Murder Row and we can get to work.", ["objectivesText"] = "Meet with Astalor Bloodsworn in Murder Row.", ["rewardGold"] = 85400, ["rewardXP"] = 3420, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 259865, ["x"] = 0.475, ["y"] = 0.71 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 246231, ["x"] = 0.565333, ["y"] = 0.654667 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.71 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["nextQuests"] = { 92926 } },
[95175] = { ["id"] = 95175, ["name"] = "Anchoring the Defense", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 95175 }, ["description"] = "We need your help to activate the Singularity Anchor. With proper defenses we can counter enemy assaults long enough to activate the device. If the Anchor is destroyed our efforts will be halted. Do what you can to help us.", ["objectivesText"] = "Complete the Stormarion Assault event. Progress: Have you helped us activate the Singularity Anchor?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3389, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 248114, ["x"] = 0.265333, ["y"] = 0.676667 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 248114, ["x"] = 0.265333, ["y"] = 0.676667 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.265333, ["y"] = 0.676667 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 92365 }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[95215] = { ["id"] = 95215, ["name"] = "A New Direction", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 39691, 40661, 44463, 44471, 44473, 95215 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40760, 40976, 40982, 40983, 41002, 43926, 44120, 44281, 44463, 44471, 44473, 44543, 44663 }, ["description"] = "<Your hand burns with felfire as a scroll materializes within your grasp. The seal bears the mark of the Illidari.> <name>, as leader of the Illidari in Lord Illidan's absence, you must choose your second-in-command. Kayn or Altruis. You can only choose one. The chosen shall become your personal champion, and their ideology will color our decisions for the Illidari going forward. No matter who is chosen, our mission remains unchanged. -Kor'vas Bloodthorn", ["objectivesText"] = "Choose between Kayn and Altruis.", ["rewardGold"] = 20220, ["rewardXP"] = 145, ["rewardItems"] = { 138970, 141650, 268551 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 97296, ["x"] = 0.725, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 259, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
