[95245] = { ["id"] = 95245, ["name"] = "Midnight: World Tour", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 95245 }, ["description"] = "The immediate danger has passed, but there is still much to be done. Go out and work with our allies to secure what ground we have made against the darkness. Whether it is in Azeroth or beyond, there is still much to be done.", ["objectivesText"] = "Complete faction features in Midnight zones.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 232875 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[95259] = { ["id"] = 95259, ["name"] = "Midnight (81-89) E", ["level"] = 81, ["requiredLevel"] = 81, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["storyline"] = { 95259 }, ["rewardXP"] = 17850, ["rewardItems"] = { 135539 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[95268] = { ["id"] = 95268, ["name"] = "New Tools, New Heights", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 95268 }, ["description"] = "There is another sort of Void power I know you will be interested in. An Ascendant Voidcore is difficult to come by, and even more difficult to work. With the Voidforge completed, I can now weave a magnificent Nilhammer capable of such things. Of course, I will need you to help with the materials. It will take time. Take this chunk of Hungering Oblivium . It can devour moments of extreme violence to be catalyzed to new heights of power, but I don't think you'll have any trouble managing that, will you?", ["objectivesText"] = "Catalyze the Hungering Oblivium with violence by defeating Midnight Season 1 raid bosses or completing Mythic+ dungeons and Bountiful Delves. Progress: Have you fed your pet rock yet, <name>? I would not suggest leaving Oblivium on your person for extended periods of time...", ["rewardGold"] = 1366400, ["rewardXP"] = 27380, ["rewardItems"] = { 269668 }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 243907, ["x"] = 0.512, ["y"] = 0.684 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 243907, ["x"] = 0.512, ["y"] = 0.684 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.684 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 94675 }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405, ["db2QuestInfoID"] = 282, ["db2QuestInfoName"] = "Important Quest" },
[95269] = { ["id"] = 95269, ["name"] = "Feeding the Nilhammer", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 95269 }, ["description"] = "Our nascent Nilhammer coalesces! But I will need to weave the Void energies from more Hungering Oblivium into it before it can fully take form. Luckily I have prepared another piece for you to catalyze. Extreme violence, remember?", ["objectivesText"] = "Catalyze the Hungering Oblivium with violence by defeating Midnight Season 1 raid bosses or completing Mythic+ dungeons and Bountiful Delves.", ["rewardGold"] = 1366400, ["rewardXP"] = 27380, ["rewardItems"] = { 269668 }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 243907, ["x"] = 0.512, ["y"] = 0.684 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 243907, ["x"] = 0.512, ["y"] = 0.684 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.684 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 95268 }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405, ["db2QuestInfoID"] = 282, ["db2QuestInfoName"] = "Important Quest" },
[95271] = { ["id"] = 95271, ["name"] = "The Ascendant Nilhammer", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15458, ["mapID"] = 2405, ["storyline"] = { 95271 }, ["rewardGold"] = 1366400, ["rewardXP"] = 27380, ["rewardItems"] = { 268650 }, ["starts"] = { { ["npcID"] = 243907, ["x"] = 0.512, ["y"] = 0.684, ["mapID"] = 2405 } }, ["ends"] = { { ["npcID"] = 243907, ["x"] = 0.512, ["y"] = 0.684, ["mapID"] = 2405 } }, ["coords"] = { ["x"] = 0.512, ["y"] = 0.684, ["source"] = "quest_giver", ["mapID"] = 2405 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405, ["db2QuestInfoID"] = 282, ["db2QuestInfoName"] = "Important Quest" },
[95276] = { ["id"] = 95276, ["name"] = "The Last Push", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 86509, 86510, 86511, 86512, 86513, 86514, 86515, 86516, 86517, 86518, 86519, 86520, 86521, 86522, 90571, 95276 }, ["description"] = "Our forces are starting to move out to take the fight to Xal'atath. I've received word there are many areas that you've visited that could still use some aid. We must focus our attention on the counter offensive. Can you help those that are in need?", ["objectivesText"] = "Reach level 90. Quests in Silvermoon City , Eversong Woods, Zul'aman, Harandar, and Voidstorm will now scale to your level. World Quests are now unlocked. Progress: There's plenty out there that can be done.", ["rewardGold"] = 85400, ["rewardXP"] = 3210, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5730, ["name"] = "Dawn of Reckoning", ["orderIndex"] = 15, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 270, ["title"] = "Midnight", ["questLineID"] = 5730, ["questLineOrder"] = 15 } }, ["db2PoiUiMapID"] = 2393 },
[95279] = { ["id"] = 95279, ["name"] = "Nebulous Voidcores: Gold", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 95279 }, ["objectivesText"] = "Progress: Back for more Nebulous Voidcores ? I have them prepared, but I do expect you to share the burden of my expenses. And then some. Why shouldn't your delightful affinity for violence pay dividends, after all? Even in the Voidstorm we can find uses for the gold. It has the most interesting properties when subjected to a touch of Void energy under the right conditions!", ["rewardCurrencies"] = { { ["id"] = 3418, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 243907, ["x"] = 0.512, ["y"] = 0.684 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 243907, ["x"] = 0.512, ["y"] = 0.684 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.684 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 95373 }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[95290] = { ["id"] = 95290, ["name"] = "Nebulous Voidcores: Voidlight Marl", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 95290 }, ["objectivesText"] = "Progress: Back for more Nebulous Voidcores ? I have them prepared, but I do expect you to share the burden of my expenses. And then some. Why shouldn't your delightful affinity for violence pay dividends, after all? Voidlight Marl is a fascinating substance! I am always happy to have more to experiment with. It is usually difficult to come by such Light-touched reagents in the Voidstorm .", ["rewardCurrencies"] = { { ["id"] = 3418, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 243907, ["x"] = 0.512, ["y"] = 0.684 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 243907, ["x"] = 0.512, ["y"] = 0.684 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.684 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 95373 }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[95304] = { ["id"] = 95304, ["name"] = "Nebulous Voidcores: Veteran Dawncrest", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 95304 }, ["objectivesText"] = "Progress: Back for more Nebulous Voidcores ? I have them prepared, but I do expect you to share the burden of my expenses. And then some. Why shouldn't your delightful affinity for violence pay dividends, after all? Those crests you use to empower equipment could be put to great use in my workshop. I can always use new materials to experiment with.", ["rewardCurrencies"] = { { ["id"] = 3418, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 243907, ["x"] = 0.512, ["y"] = 0.684 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 243907, ["x"] = 0.512, ["y"] = 0.684 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.684 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 95373 }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
[95324] = { ["id"] = 95324, ["name"] = "The War Beyond the Roots", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2393, ["storyline"] = { 95324 }, ["description"] = "Your actions in Harandar caused quite an uproar. The elders are up in arms. The rootwardens are worried. It's really quite exhausting. But there is good news as well. Orweyna has heard rumblings from every corner of the roots. She tells me of haranir who wish to see the world as she does--who feel compelled to seek the goddess beyond the boughs of Harandar. I will handle things in Harandar. Go to your leaders. Tell them that the haranir are ready to join the fight.", ["objectivesText"] = "Bring word to Lor'themar in the Sanctum of Light.", ["rewardItems"] = { 246736 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 255819, ["x"] = 0.365, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 235787, ["x"] = 0.454, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 86898 }, ["db2PoiUiMapID"] = 2393, ["db2QuestInfoID"] = 282, ["db2QuestInfoName"] = "Important Quest" },
[95336] = { ["id"] = 95336, ["name"] = "Frenzied Fossicking", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16105, ["mapID"] = 2352, ["description"] = "Ya be down for helping me out with a little spot of bother? Shajanji be over in the mountains collecting some local rocks. If you could go help her out, I'd be mighty grateful ta ya. Just bring them back ta me. I be keeping them safe for her. I--She needs a lot of them. She be an avid collector.", ["rewardGold"] = 341600, ["rewardXP"] = 3440, ["rewardCurrencies"] = { { ["id"] = 3363, ["amount"] = 1 } }, ["starts"] = { { ["npcID"] = 263442, ["x"] = 0.542, ["y"] = 0.566, ["mapID"] = 2351 }, { ["npcID"] = 263442, ["x"] = 0.528, ["y"] = 0.384, ["mapID"] = 2352 } }, ["ends"] = { { ["npcID"] = 263442, ["x"] = 0.542, ["y"] = 0.566, ["mapID"] = 2351 }, { ["npcID"] = 263442, ["x"] = 0.528, ["y"] = 0.384, ["mapID"] = 2352 } }, ["coords"] = { ["x"] = 0.542, ["y"] = 0.566, ["source"] = "quest_giver", ["mapID"] = 2352 }, ["mapCandidates"] = { ["npc"] = { 2351, 2352 }, ["zone"] = { 16105 } }, ["questType"] = "standard" },
