[95373] = { ["id"] = 95373, ["name"] = "A Nebulous Endeavour", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16648, ["mapID"] = 2405, ["storyline"] = { 95373 }, ["description"] = "With the Voidforge completed, I can now weave Nebulous Voidcores for you out of the power it accumulates. Of course, I'll need you to cover certain expenses. You'll have to engage in a bit more delightful bloodshed to transmute them into weapons and armor. The most dangerous foes will require two. Each Nebulous Voidcore will capture a bit of your... victims' particular essence in order to become the sort of shiny knicknack I know you can't resist chasing after.", ["objectivesText"] = "Transmute a Nebulous Voidcore into equipment after defeating a Midnight Season 1 raid boss, completing a Mythic+ dungeon, or opening a Delve's Bountiful Coffer. Progress: Back already, <name>? Were you able to transmute the Nebulous Voidcore?", ["rewardGold"] = 1366400, ["rewardXP"] = 27380, ["rewardItems"] = { 251785, 259915 }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 243907, ["x"] = 0.512, ["y"] = 0.684 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 243907, ["x"] = 0.512, ["y"] = 0.684 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.684 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 94675 }, ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405, ["db2QuestInfoID"] = 282, ["db2QuestInfoName"] = "Important Quest" },
