[95438] = { ["id"] = 95438, ["name"] = "Lost Animals", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 95438 }, ["description"] = "<name>, I am so glad to see you. A good friend of mine has sent a letter informing me she lost track of some of her tiny pets throughout the neighborhood! She's asking for assistance from anyone who can help! Help find her lost animals right away!", ["objectivesText"] = "Find 10 Lost Animals in the neighborhood and bring them to Kara Meldansen . Progress: Oh please do hurry! I'm sure they are off having the most grand adventures but I worry so!", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 3316, 259085, 269010, 274069, 274070, 274071 }, ["rewardChoices"] = { 3316, 259085, 274069, 274070, 274071, 280732, 280734, 280737 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 500 }, { ["id"] = 3363, ["amount"] = 25 } }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 260957, ["x"] = 0.495, ["y"] = 0.659 } }, ["ends"] = { { ["mapID"] = 2351, ["npcID"] = 261034, ["x"] = 0.558, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.495, ["y"] = 0.659 }, ["mapCandidates"] = { ["npc"] = { 2351, 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 6666 }, ["db2PoiUiMapID"] = 2393 },
