[95440] = { ["id"] = 95440, ["name"] = "Housewarming", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 95440 }, ["description"] = "Kirin Tor scholars have argued for centuries over the semantics of a \"gathering\". How many people are required? For how long must they remain? Who is bringing the beverages? Debates have raged into the night. Papers written. Research grants awarded. Consensus yet eludes the scholars, but they still meet often to deliberate. They take turns bringing beverages.", ["objectivesText"] = "Gather with at least four other players inside a player home while the homeowner is present.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 260957, ["x"] = 0.495, ["y"] = 0.659 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 260957, ["x"] = 0.495, ["y"] = 0.659 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.495, ["y"] = 0.659 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questTurnInID"] = 260957, ["questType"] = "group", ["activities"] = { ["groupFinder"] = { { ["id"] = 1972, ["name"] = "Housewarming", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 11, ["maxPlayers"] = 40 } } }, ["db2LabelIDs"] = { 6666 }, ["db2PoiUiMapID"] = 2393, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[95468] = { ["id"] = 95468, ["name"] = "Hope in the Darkest Corners", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly", "meta" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 95468 }, ["description"] = "I can't imagine what will happen to Quel'Thalas if the Sunwell falls to the forces of the Void. We need you out on the battlefield, <name>. Bring hope and heroism to the people across these lands.", ["objectivesText"] = "Complete various activities in Midnight zones. Progress: You must fight, <name>.", ["rewardGold"] = 676600, ["rewardXP"] = 14705, ["rewardItems"] = { 265995 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 256210, ["x"] = 0.49, ["y"] = 0.646 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 256210, ["x"] = 0.49, ["y"] = 0.646 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6223, ["name"] = "Hope in The Darkest Corners", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 2393 },
