[95520] = { ["id"] = 95520, ["name"] = "Purging the Vaults", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["mapID"] = 2509, ["description"] = "De fiends of dis temple would see us all dead. We are all dat stands between them and de mainland, you understand? We hold dem here. Not one scale, not one bony finger, none of them will leave dis temple while we breathe. Get out there and cut them down.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 273000, 274374, 279382 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 125 }, { ["id"] = 3316, ["amount"] = 150 }, { ["id"] = 3448, ["amount"] = 1500 }, { ["id"] = 3448, ["amount"] = 1875 } }, ["starts"] = { { ["npcID"] = 262798, ["x"] = 0.472, ["y"] = 0.608, ["zoneID"] = 16535 }, { ["npcID"] = 267635, ["x"] = 0.586, ["y"] = 0.458, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 262798, ["x"] = 0.472, ["y"] = 0.608, ["zoneID"] = 16535 } }, ["coords"] = { ["x"] = 0.472, ["y"] = 0.608, ["source"] = "quest_giver", ["zoneID"] = 16535 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard" },
[95521] = { ["id"] = 95521, ["name"] = "The Med'jai Medallion", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["mapID"] = 2509, ["description"] = "Me'si , will know where this came from.>", ["rewardGold"] = 85400, ["rewardXP"] = 3420, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3448, ["amount"] = 50 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 641565, ["x"] = 0.48, ["y"] = 0.519, ["zoneID"] = 16535 } }, ["ends"] = { { ["npcID"] = 261659, ["x"] = 0.488, ["y"] = 0.64, ["zoneID"] = 16535 } }, ["coords"] = { ["x"] = 0.48, ["y"] = 0.519, ["source"] = "quest_giver", ["zoneID"] = 16535 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16535 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6227, ["name"] = "The Honored Med'jai", ["orderIndex"] = 0, ["flags"] = 0 } } },
[95522] = { ["id"] = 95522, ["name"] = "Guardians of Death, Guardians in Stone", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["mapID"] = 2509, ["description"] = "In de legends passed down, dey speak of a group of heroic guardians whose sacrifice protect us to dis day. These honored few, known as de Med'jai, adorned their belts with gems like these--de better to draw their enemies in and defeat dem. We were told dey went on a great expedition to fight de evil abroad, but it seems de greatest of de evils was within--below our feet. Please,  search for dis gem's true home. If our ancestor spirits watch over us, perhaps we will find their resting place.", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3448, ["amount"] = 50 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 261659, ["x"] = 0.488, ["y"] = 0.64, ["zoneID"] = 16535 } }, ["ends"] = { { ["npcID"] = 261659, ["x"] = 0.488, ["y"] = 0.64, ["zoneID"] = 16535 } }, ["coords"] = { ["x"] = 0.488, ["y"] = 0.64, ["source"] = "quest_giver", ["zoneID"] = 16535 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16535 } }, ["questTurnInID"] = 261659, ["questType"] = "group", ["sourceQuests"] = { 95521 }, ["questLines"] = { { ["id"] = 6227, ["name"] = "The Honored Med'jai", ["orderIndex"] = 1, ["flags"] = 0 } } },
[95523] = { ["id"] = 95523, ["name"] = "Worthy of the Past", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["mapID"] = 2509, ["description"] = "De Soulcoilers must pay, . De Soulcoilers believed their actions saved de Amani. Instead, our people and our future was plundered. We did not realize until it was too late. End them. Shatter their very souls so that even de great Mueh'zala cannot put dem back together.", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3448, ["amount"] = 100 }, { ["id"] = 3504, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.384, ["y"] = 0.344, ["mapID"] = 2509, ["npcID"] = 261895 } }, ["ends"] = { { ["npcID"] = 262281, ["x"] = 0.44, ["y"] = 0.56, ["zoneID"] = 16535 } }, ["coords"] = { ["mapID"] = 2509, ["x"] = 0.384, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16535 } }, ["questGiverID"] = 261895, ["questType"] = "group", ["sourceQuests"] = { 95522 }, ["questLines"] = { { ["id"] = 6227, ["name"] = "The Honored Med'jai", ["orderIndex"] = 2, ["flags"] = 0 } } },
[95524] = { ["id"] = 95524, ["name"] = "The Unremembered", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["mapID"] = 2509, ["description"] = "I am not de only Med'jai tasked with keeping sentinel over de priests. There were three of us, entombed in stone that matched how we looked in life. I must know if dey are still there. Can you help me find them? My body is bound in dis stone, but my spirit is not. Bring my gem to those places, if you can find dem. If we cannot wake dem, we will at least honor dem.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3448, ["amount"] = 50 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["x"] = 0.384, ["y"] = 0.344, ["mapID"] = 2509, ["npcID"] = 261895 } }, ["ends"] = { { ["npcID"] = 262281, ["x"] = 0.44, ["y"] = 0.56, ["zoneID"] = 16535 } }, ["coords"] = { ["mapID"] = 2509, ["x"] = 0.384, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16535 } }, ["questGiverID"] = 261895, ["questType"] = "group", ["sourceQuests"] = { 95522 }, ["questLines"] = { { ["id"] = 6227, ["name"] = "The Honored Med'jai", ["orderIndex"] = 3, ["flags"] = 0 } } },
[95525] = { ["id"] = 95525, ["name"] = "A Worthy Vigil", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["mapID"] = 2509, ["description"] = "De temple has changed since I began my watch, . When you first woke me, all I saw was corruption and impure spirits. De consequence of our weakness. Now, I see dat we have not failed. De battlefield has changed, as dey always do. Please take my gem and bring it back to de others like you. Perhaps my spirit can become a force for good on dis new battlefield, in a new way.", ["rewardGold"] = 85400, ["rewardXP"] = 3420, ["rewardChoices"] = { 280277, 280278 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3448, ["amount"] = 250 }, { ["id"] = 3504, ["amount"] = 250 } }, ["starts"] = { { ["npcID"] = 263557, ["x"] = 0.392, ["y"] = 0.482, ["zoneID"] = 16535 } }, ["ends"] = { { ["npcID"] = 261659, ["x"] = 0.488, ["y"] = 0.64, ["zoneID"] = 16535 } }, ["coords"] = { ["x"] = 0.392, ["y"] = 0.482, ["source"] = "quest_giver", ["zoneID"] = 16535 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16535 } }, ["questType"] = "standard", ["sourceQuests"] = { 95954 }, ["questLines"] = { { ["id"] = 6227, ["name"] = "The Honored Med'jai", ["orderIndex"] = 5, ["flags"] = 0 } } },
