[95547] = { ["id"] = 95547, ["name"] = "Ritual Site Challenge Report: Tendrils", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 95547 }, ["description"] = "<The information in the scrolls speaks of a mysterious vine attracted to the high levels of magic at Ritual Sites. This is the type of information Lady Darkglen needs to be told to better prepare for countering future Ritual Sites.>", ["objectivesText"] = "Return your report to Lady Darkglen in Silvermoon City . Progress: What do you have there?", ["rewardGold"] = 341600, ["rewardItems"] = { 269817 }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 257416, ["x"] = 0.478, ["y"] = 0.496 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["startItems"] = { 269817 } },
[95548] = { ["id"] = 95548, ["name"] = "Tainted Sample", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 95548 }, ["description"] = "<This sample is tainted and reeks of unknown scents. Perhaps Lady Darkglen would be interested in studying it further.>", ["objectivesText"] = "Return the tainted sample to Lady Darkglen .", ["rewardGold"] = 341600, ["rewardItems"] = { 270562 }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 257416, ["x"] = 0.478, ["y"] = 0.496 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2VignetteID"] = 7593, ["db2VignetteName"] = "Bone Pile", ["startItems"] = { 270562 } },
[95549] = { ["id"] = 95549, ["name"] = "Raising Magical Alarms", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 95549 }, ["description"] = "I have a request. These Ritual Sites invoke some interesting magic. I would like you to obtain some sample readings. You don't need to concern yourself with the details. Just visit the area I will mark on your map and press the button. You may end up garnering some extra attention when you do so.", ["objectivesText"] = "Use Lady Darkglen's device in a Ritual Site. Progress: That is the look of success.", ["rewardGold"] = 341600, ["rewardItems"] = { 271094 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 257416, ["x"] = 0.478, ["y"] = 0.496 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 257416, ["x"] = 0.478, ["y"] = 0.496 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 2393 },
[95550] = { ["id"] = 95550, ["name"] = "Thin Their Ranks", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 95550 }, ["description"] = "I don't like it. We have far too many scouts returning wounded from these so-called ritual sites. Thin out the ranks of these cultists.", ["objectivesText"] = "Defeat enemies in a Ritual Site. Progress: Is the job done?", ["rewardGold"] = 341600, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 257411, ["x"] = 0.48, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 257411, ["x"] = 0.48, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 2393 },
[95551] = { ["id"] = 95551, ["name"] = "Misappropriated Treasures", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 95551 }, ["description"] = "<It seems the cultists have added theft to their repertoire. You should reclaim the stolen treasures from the Ritual Site and return them to Rae'ana .>", ["objectivesText"] = "Return the stolen treasures to Rae'ana . Progress: Oh? What do you have there?", ["rewardGold"] = 341600, ["rewardItems"] = { 124640, 271427, 271428, 271429, 271430 }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 255495, ["x"] = 0.478, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["startItems"] = { 271353, 271427, 271428, 271429, 271430 } },
[95552] = { ["id"] = 95552, ["name"] = "Dark Obelisk Investigation", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 95552 }, ["description"] = "<race>, we have reports that the leaders of the Ritual Sites are using dark obelisks to bolster their forces with malevolent boons. I need you to investigate the objects they are using to gain these boons.", ["objectivesText"] = "Investigate the sources of the malevolent boons in a Ritual Site. Progress: What do you have to report?", ["rewardGold"] = 341600, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 257416, ["x"] = 0.478, ["y"] = 0.496 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 257416, ["x"] = 0.478, ["y"] = 0.496 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 2393 },
[95553] = { ["id"] = 95553, ["name"] = "Manifested Density", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 95553 }, ["description"] = "I'm hearing strange murmurings from my scouts. Some are claiming that strange manifestations are appearing and cursing intruders. Could I ask you to investigate and see if there is any truth to these rumors?", ["objectivesText"] = "Complete a Ritual Site.", ["rewardGold"] = 341600, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 257411, ["x"] = 0.48, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 257411, ["x"] = 0.48, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 2393 },
