[95673] = { ["id"] = 95673, ["name"] = "Suspicious Scare-gull", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16105, ["mapID"] = 2352, ["description"] = "Hey there, could ya help a poor troll down on their luck? I'm looking for some feathers from ya neighborhood. If ya give the birds around here a good scare, they'll take off and drop some, just bring them back here.", ["rewardGold"] = 341600, ["rewardXP"] = 3440, ["rewardCurrencies"] = { { ["id"] = 3363, ["amount"] = 1 } }, ["starts"] = { { ["npcID"] = 262234, ["x"] = 0.542, ["y"] = 0.572, ["mapID"] = 2351 }, { ["npcID"] = 262234, ["x"] = 0.524, ["y"] = 0.386, ["mapID"] = 2352 } }, ["ends"] = { { ["npcID"] = 262234, ["x"] = 0.542, ["y"] = 0.572, ["mapID"] = 2351 }, { ["npcID"] = 262234, ["x"] = 0.524, ["y"] = 0.386, ["mapID"] = 2352 } }, ["coords"] = { ["x"] = 0.542, ["y"] = 0.572, ["source"] = "quest_giver", ["mapID"] = 2352 }, ["mapCandidates"] = { ["npc"] = { 2351, 2352 }, ["zone"] = { 16105 } }, ["questType"] = "standard" },
[95768] = { ["id"] = 95768, ["name"] = "My Stuff's Better Than Your Stuff", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16105, ["mapID"] = 2352, ["description"] = "Hey there, . I set up shop to trade some of our neighborhood goods with our new friends here, and I've been selling like hotcakes! I could use a break though, would you mind watching the shop for me? If any customers come by, just offer them what you think is best.", ["rewardGold"] = 341600, ["rewardXP"] = 3440, ["rewardCurrencies"] = { { ["id"] = 3363, ["amount"] = 1 } }, ["starts"] = { { ["npcID"] = 262240, ["x"] = 0.544, ["y"] = 0.56, ["mapID"] = 2351 }, { ["npcID"] = 262669, ["x"] = 0.528, ["y"] = 0.376, ["mapID"] = 2352 } }, ["ends"] = { { ["npcID"] = 262240, ["x"] = 0.544, ["y"] = 0.56, ["mapID"] = 2351 }, { ["npcID"] = 262669, ["x"] = 0.528, ["y"] = 0.376, ["mapID"] = 2352 } }, ["coords"] = { ["x"] = 0.544, ["y"] = 0.56, ["source"] = "quest_giver", ["mapID"] = 2352 }, ["mapCandidates"] = { ["npc"] = { 2351, 2352 }, ["zone"] = { 16105 } }, ["questType"] = "standard" },
[95779] = { ["id"] = 95779, ["name"] = "Moments in a Mug", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 10473, ["mapID"] = 2541, ["description"] = "A man who knows his way around a drink deserves the finest brew. I have just the thing in mind for my friend, Flynn. The ingredients I need are within my family's brewery in the Valley of Four Winds. I would fetch them myself, but a brewmaster must also know when to sit, breathe, and appreciate what is within the mug. Would you go to Stormstout Brewery and bring those ingredients to me, friend?", ["rewardItems"] = { 278694 }, ["starts"] = { { ["npcID"] = 259343, ["x"] = 0.442, ["y"] = 0.638, ["mapID"] = 2541 } }, ["ends"] = { { ["npcID"] = 259343, ["x"] = 0.442, ["y"] = 0.638, ["mapID"] = 2541 } }, ["coords"] = { ["x"] = 0.442, ["y"] = 0.638, ["source"] = "quest_giver", ["mapID"] = 2541 }, ["mapCandidates"] = { ["npc"] = { 2541 }, ["zone"] = { 10473 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5982, ["name"] = "The Arcantina", ["orderIndex"] = 9, ["flags"] = 0 } } },
[95780] = { ["id"] = 95780, ["name"] = "Hope for the Orphans", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 3703, ["mapID"] = 111, ["description"] = "Garona and I both don't talk about our childhoods much. There's not a lot worth saying. The children in that orphanage in Shattrath--they're living what we lived. I'm not asking you to fix that. I'm asking you to show up and remind them the world holds something worth fighting for. For me, revenge was worth fighting for. But maybe they can have a brighter future. Go play games with them. Try to show them what a person worth looking up to actually is.", ["rewardItems"] = { 278038 }, ["starts"] = { { ["npcID"] = 259335, ["x"] = 0.556, ["y"] = 0.646, ["mapID"] = 2541 } }, ["ends"] = { { ["npcID"] = 259335, ["x"] = 0.556, ["y"] = 0.646, ["mapID"] = 2541 } }, ["coords"] = { ["x"] = 0.556, ["y"] = 0.646, ["source"] = "quest_giver", ["mapID"] = 111 }, ["mapCandidates"] = { ["npc"] = { 2541 }, ["zone"] = { 3703 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5982, ["name"] = "The Arcantina", ["orderIndex"] = 10, ["flags"] = 0 } } },
