[95804] = { ["id"] = 95804, ["name"] = "The Children of Ula'tek", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "Are these tortollans lost? How long have dey been here? We have a settlement of dem near de Shrine of Filo, but dis is a place dey should not be. A day not long ago, I would have chased dem off. But we've been havin' good luck with outsiders. Zul'jarra 's face. It's the first you've seen since before Malacrass's return.> We should talk to dem. Maybe dey know how dis started.", ["rewardGold"] = 85400, ["rewardXP"] = 3420, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 253528, ["x"] = 0.448, ["y"] = 0.278, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 253528, ["x"] = 0.448, ["y"] = 0.278, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.448, ["y"] = 0.278, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 92924 }, ["questLines"] = { { ["id"] = 6087, ["name"] = "An Island of Fangs", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6229, ["name"] = "An Island of Fangs", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 332, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6087, ["questLineOrder"] = 1 }, { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6229, ["questLineOrder"] = 1 } } },
