[95842] = { ["id"] = 95842, ["name"] = "Midnight: Void Assaults", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 95842 }, ["description"] = "Both Void forces and old enemies press us in this turbulent time. We must stay vigilant and let no faction gain a foothold. You must put a stop to these Void assaults! Stay alert, our scouts report some factions may be using the smaller strikes to prepare for a major incursion. If so, I know you will help with the defense.", ["objectivesText"] = "Complete Void Strikes and Void Incursions in Midnight.", ["rewardGold"] = 683200, ["rewardXP"] = 20540, ["rewardItems"] = { 254677 }, ["starts"] = { { ["x"] = 0.49, ["y"] = 0.646, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 256203, ["x"] = 0.49, ["y"] = 0.646, ["mapID"] = 2393 } }, ["coords"] = { ["mapID"] = 2393, ["x"] = 0.49, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 6072 } },
