[96223] = { ["id"] = 96223, ["name"] = "The Magisters' Call", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["description"] = "The Magisters request your presence at Thalassian University. Please proceed to the upper levels overlooking the harbor. This concerns a private matter of minor urgency.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["starts"] = { { ["npcID"] = 265903, ["x"] = 0.478, ["y"] = 0.516, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 264063, ["x"] = 0.388, ["y"] = 0.486, ["mapID"] = 2393 }, { ["npcID"] = 264064, ["x"] = 0.388, ["y"] = 0.486, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.478, ["y"] = 0.516, ["source"] = "quest_giver", ["mapID"] = 2393 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6275, ["name"] = "The Sunstrider Omnium", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 381, ["title"] = "The Sunstrider Omnium", ["questLineID"] = 6275, ["questLineOrder"] = 0 } } },
[96224] = { ["id"] = 96224, ["name"] = "The Magisters' Conundrum", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 17067, ["mapID"] = 2649, ["description"] = "Magisters' Terrace is home to many mysterious artifacts. Among them is a relic once central to our pursuit of magical knowledge. A few years ago, the relic fell into a state of dormancy. After the Dawnwell reignited, this artifact began to stir. Upon returning it to the Lycaneum for study, the relic unleashed chaos upon the library. I believe your unique expertise may be helpful in quelling this chaos.", ["rewardGold"] = 34100, ["rewardXP"] = 1470, ["starts"] = { { ["npcID"] = 264063, ["x"] = 0.388, ["y"] = 0.486, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 264066, ["x"] = 0.636, ["y"] = 0.166, ["zoneID"] = 17067 } }, ["coords"] = { ["x"] = 0.388, ["y"] = 0.486, ["source"] = "quest_giver", ["zoneID"] = 15969 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 17067 } }, ["questType"] = "standard", ["sourceQuests"] = { 96223 }, ["questLines"] = { { ["id"] = 6275, ["name"] = "The Sunstrider Omnium", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 381, ["title"] = "The Sunstrider Omnium", ["questLineID"] = 6275, ["questLineOrder"] = 0 } } },
[96225] = { ["id"] = 96225, ["name"] = "The Magisters' Conundrum", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 17067, ["mapID"] = 2649, ["description"] = "For the last few decades, a dormant artifact laid beneath the halls of Magisters' Terrace. Once serving as a beacon of knowledge to the Magisters, the artifact abruptly fell silent some decades ago. After the Dawnwell's rebirth, the artifact reawakened. When we returned it to the Lycaneum for study, it unleashed chaos upon the library. Your assistance, and discretion, would be most appreciated.", ["rewardGold"] = 34100, ["rewardXP"] = 1470, ["starts"] = { { ["npcID"] = 264064, ["x"] = 0.388, ["y"] = 0.486, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 264065, ["x"] = 0.624, ["y"] = 0.154, ["zoneID"] = 17067 } }, ["coords"] = { ["x"] = 0.388, ["y"] = 0.486, ["source"] = "quest_giver", ["zoneID"] = 15969 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 17067 } }, ["questType"] = "standard", ["sourceQuests"] = { 96223 }, ["questLines"] = { { ["id"] = 6275, ["name"] = "The Sunstrider Omnium", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 381, ["title"] = "The Sunstrider Omnium", ["questLineID"] = 6275, ["questLineOrder"] = 0 } } },
[96226] = { ["id"] = 96226, ["name"] = "Omnium Anomalies", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16215, ["mapID"] = 2424, ["description"] = "Shortly after the Omnium awoke, it began manifesting arcane anomalies around the Lycaneum. We believe these anomalies to be malfunctioning security protocols--the hostile projections they conjure can be quite lethal. If we do not dispatch them quickly, they will continue to manifest. As you deal with them, keep an eye out for anything peculiar that can help us understand the Omnium's current state.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 150 } }, ["starts"] = { { ["npcID"] = 264065, ["x"] = 0.624, ["y"] = 0.154, ["zoneID"] = 17067 } }, ["ends"] = { { ["npcID"] = 264065, ["x"] = 0.624, ["y"] = 0.154, ["zoneID"] = 17067 } }, ["coords"] = { ["x"] = 0.624, ["y"] = 0.154, ["source"] = "quest_giver", ["mapID"] = 2424 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16215 } }, ["questType"] = "standard", ["sourceQuests"] = { 96224, 96225 }, ["questLines"] = { { ["id"] = 6275, ["name"] = "The Sunstrider Omnium", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 381, ["title"] = "The Sunstrider Omnium", ["questLineID"] = 6275, ["questLineOrder"] = 0 } } },
[96227] = { ["id"] = 96227, ["name"] = "Lycaneum Chaos", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 17067, ["mapID"] = 2649, ["description"] = "When the Omnium began to stir in its vault, we thought to move it here for observation. Evidently, this was a bad idea. The arcane magics seeping out are causing chaos. Folios casting all sorts of incomplete spells, arcane sparks running amok--even the candle flames have sprung to life! But we cannot simply destroy them, as the magics here are too volatile. I have procured a ward-lance from the arsenal of the spellbreakers. It will dispel the volatile magic. Here, take it. And do be careful.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 150 } }, ["starts"] = { { ["npcID"] = 264066, ["x"] = 0.636, ["y"] = 0.166, ["zoneID"] = 17067 } }, ["ends"] = { { ["npcID"] = 264066, ["x"] = 0.636, ["y"] = 0.166, ["zoneID"] = 17067 } }, ["coords"] = { ["x"] = 0.636, ["y"] = 0.166, ["source"] = "quest_giver", ["zoneID"] = 17067 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 17067 } }, ["questType"] = "standard", ["sourceQuests"] = { 96224, 96225 }, ["questLines"] = { { ["id"] = 6275, ["name"] = "The Sunstrider Omnium", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 381, ["title"] = "The Sunstrider Omnium", ["questLineID"] = 6275, ["questLineOrder"] = 0 } } },
[96228] = { ["id"] = 96228, ["name"] = "The Shadowed Spire", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["description"] = "Time and time again, Dar'Khan continues to haunt us in some form. To think the Omnium also fell prey to his madness... If he really severed the Void Magicule from the Omnium, then I have no doubt he would have hidden it well. I have a suspicion I know where to start looking. Meet me at Dawnstar Spire in Eversong Woods.", ["rewardGold"] = 256200, ["rewardXP"] = 8825, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 } }, ["starts"] = { { ["npcID"] = 264065, ["x"] = 0.624, ["y"] = 0.154, ["zoneID"] = 17067 } }, ["ends"] = { { ["npcID"] = 264067, ["x"] = 0.626, ["y"] = 0.63, ["mapID"] = 2395 } }, ["coords"] = { ["x"] = 0.624, ["y"] = 0.154, ["source"] = "quest_giver", ["mapID"] = 2395 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 96226, 96227 }, ["questLines"] = { { ["id"] = 6275, ["name"] = "The Sunstrider Omnium", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 381, ["title"] = "The Sunstrider Omnium", ["questLineID"] = 6275, ["questLineOrder"] = 0 } } },
[96229] = { ["id"] = 96229, ["name"] = "The Void Reveals", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["description"] = "After reclaiming Silvermoon, the Magisters torched Dar'Khan's personal study and dwellings within the city walls. I had thought I had found everything I needed the first time I searched this place, but now... It seems that Dar'Khan left some secrets. This portal will take us to them. I do not know what we will find on the other side. Be on your guard.", ["rewardGold"] = 683200, ["rewardXP"] = 14705, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 400 } }, ["starts"] = { { ["npcID"] = 264067, ["x"] = 0.626, ["y"] = 0.63, ["mapID"] = 2395 } }, ["ends"] = { { ["npcID"] = 269814, ["x"] = 0.624, ["y"] = 0.626, ["mapID"] = 2395 } }, ["coords"] = { ["x"] = 0.626, ["y"] = 0.63, ["source"] = "quest_giver", ["mapID"] = 2395 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["sourceQuests"] = { 96228 }, ["questLines"] = { { ["id"] = 6275, ["name"] = "The Sunstrider Omnium", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 381, ["title"] = "The Sunstrider Omnium", ["questLineID"] = 6275, ["questLineOrder"] = 0 } } },
[96230] = { ["id"] = 96230, ["name"] = "Unraveling the Wards", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16215, ["mapID"] = 2424, ["description"] = "The Magicules, the orbs you see on the relic, were never meant to be severed from the Omnium. By tearing one out, Dar'Khan likely sent the artifact into a frenzied state before it shut down. Even if the Void Magicule is restored, the Omnium will need recalibrating. We will need Belo'vir's key-cipher, now my key-cipher, to do this. I will meet you at my study and we can recover it.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 150 } }, ["starts"] = { { ["npcID"] = 264066, ["x"] = 0.636, ["y"] = 0.166, ["zoneID"] = 17067 } }, ["ends"] = { { ["npcID"] = 264945, ["x"] = 0.588, ["y"] = 0.574, ["mapID"] = 2424 } }, ["coords"] = { ["x"] = 0.636, ["y"] = 0.166, ["source"] = "quest_giver", ["mapID"] = 2424 }, ["mapCandidates"] = { ["npc"] = { 2424 }, ["zone"] = { 16215 } }, ["questType"] = "standard", ["sourceQuests"] = { 96226, 96227 }, ["questLines"] = { { ["id"] = 6275, ["name"] = "The Sunstrider Omnium", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 381, ["title"] = "The Sunstrider Omnium", ["questLineID"] = 6275, ["questLineOrder"] = 0 } } },
[96231] = { ["id"] = 96231, ["name"] = "The Grand Magister's Key-Cipher", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16215, ["mapID"] = 2424, ["description"] = "After Belo'vir's death, I contemplated opening this vault. I talked myself out of it. A key for a shattered lock serves no purpose. And yet, even as Kael'thas tried to open it with his key, I couldn't help but wonder... It doesn't matter, . I am nearly done with the master ward on the upper floor. Meet me there. No doubt, Belo'vir took extra steps to safeguard his vault.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["starts"] = { { ["npcID"] = 264945, ["x"] = 0.588, ["y"] = 0.574, ["mapID"] = 2424 } }, ["ends"] = { { ["npcID"] = 264944, ["x"] = 0.59, ["y"] = 0.592, ["mapID"] = 2424 } }, ["coords"] = { ["x"] = 0.588, ["y"] = 0.574, ["source"] = "quest_giver", ["mapID"] = 2424 }, ["mapCandidates"] = { ["npc"] = { 2424 }, ["zone"] = { 16215 } }, ["questType"] = "standard", ["sourceQuests"] = { 96230 }, ["questLines"] = { { ["id"] = 6275, ["name"] = "The Sunstrider Omnium", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 381, ["title"] = "The Sunstrider Omnium", ["questLineID"] = 6275, ["questLineOrder"] = 0 } } },
[96232] = { ["id"] = 96232, ["name"] = "Return to the Omnium", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 17067, ["mapID"] = 2424, ["description"] = "Well, now that we've recovered the piece Dar'Khan stole, we are one step closer to restoring the Omnium. Hopefully your endeavor with Rommath was a little less troublesome? When you're ready, return to the Magisters' Terrace. I will clean up anything left behind here and join you shortly.", ["rewardGold"] = 85400, ["rewardXP"] = 2940, ["starts"] = { { ["npcID"] = 269814, ["x"] = 0.624, ["y"] = 0.626, ["mapID"] = 2395 } }, ["ends"] = { { ["npcID"] = 264066, ["x"] = 0.636, ["y"] = 0.166, ["zoneID"] = 17067 } }, ["coords"] = { ["x"] = 0.624, ["y"] = 0.626, ["source"] = "quest_giver", ["zoneID"] = 15968 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 17067 } }, ["questType"] = "standard", ["sourceQuests"] = { 96229, 96231 }, ["questLines"] = { { ["id"] = 6275, ["name"] = "The Sunstrider Omnium", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 381, ["title"] = "The Sunstrider Omnium", ["questLineID"] = 6275, ["questLineOrder"] = 0 } } },
[96233] = { ["id"] = 96233, ["name"] = "The Omnium Reawakens", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 17067, ["mapID"] = 2424, ["description"] = "For years, as Silvermoon and its people changed, this relic sat in a vault beneath the Terrace, unresponsive and dormant. We may never truly understand why the relic fell silent when it did or why it refused the prince's call, but perhaps in time, we might. Let us hope the missing Magicule and the key-cipher will be enough to restore it. Are you ready, ?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 250 } }, ["starts"] = { { ["npcID"] = 264066, ["x"] = 0.636, ["y"] = 0.166, ["zoneID"] = 17067 } }, ["ends"] = { { ["npcID"] = 264069, ["x"] = 0.604, ["y"] = 0.112, ["zoneID"] = 17067 } }, ["coords"] = { ["x"] = 0.636, ["y"] = 0.166, ["source"] = "quest_giver", ["zoneID"] = 17067 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 17067 } }, ["questType"] = "standard", ["sourceQuests"] = { 96226, 96227 }, ["questLines"] = { { ["id"] = 6275, ["name"] = "The Sunstrider Omnium", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 381, ["title"] = "The Sunstrider Omnium", ["questLineID"] = 6275, ["questLineOrder"] = 0 } } },
[96238] = { ["id"] = 96238, ["name"] = "Return to the Omnium", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 17067, ["mapID"] = 2424, ["description"] = "With Belo'vir's key-cipher recovered and Umbric in possession of the Void Magicule, we should return to the Lycaneum. Hopefully we have all that we need to recalibrate the Sunstrider Omnium. I will meet you back in the Magisters' Terrace when I am done here.", ["rewardGold"] = 85400, ["rewardXP"] = 2940, ["starts"] = { { ["npcID"] = 264944, ["x"] = 0.59, ["y"] = 0.592, ["mapID"] = 2424 } }, ["ends"] = { { ["npcID"] = 264066, ["x"] = 0.636, ["y"] = 0.166, ["zoneID"] = 17067 } }, ["coords"] = { ["x"] = 0.59, ["y"] = 0.592, ["source"] = "quest_giver", ["zoneID"] = 16215 }, ["mapCandidates"] = { ["npc"] = { 2424 }, ["zone"] = { 17067 } }, ["questType"] = "standard", ["sourceQuests"] = { 96229, 96231 }, ["questLines"] = { { ["id"] = 6275, ["name"] = "The Sunstrider Omnium", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 381, ["title"] = "The Sunstrider Omnium", ["questLineID"] = 6275, ["questLineOrder"] = 0 } } },
[96242] = { ["id"] = 96242, ["name"] = "An Easy Path to Trickery", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 96242 }, ["description"] = "You can always speak to me to enter a game of Decor Duel, but did you know there's an easier way? If there's a GROUP you wan to FIND, we have \"magic\" to help!", ["objectivesText"] = "Use Group Finder to get into a Decor Duel game. <Group Finder -> Player vs. Player -> Decor Duel> Progress: You're on the easy path to Trickery? Good luck! <use Group Finder to play a PvP Decor Duel match.> <If you abandon her quest, or complete it, you may re-enter Decor Duel through Amolene again>", ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 257125, ["x"] = 0.315, ["y"] = 0.765 } }, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 257125, ["x"] = 0.315, ["y"] = 0.765 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.315, ["y"] = 0.765 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 93907 } },
[96245] = { ["id"] = 96245, ["name"] = "You've Seen it All Before", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 96245 }, ["description"] = "<A fine parchment materializes in a shower of bronze dust. It is an invitation from Soridormi to visit her at the Wayfarer's Rest in Silvermoon City .>", ["objectivesText"] = "Visit Soridormi at the Wayfarer's Rest in Silvermoon City .", ["rewardGold"] = 34100, ["ends"] = { { ["mapID"] = 2393, ["npcID"] = 259153, ["x"] = 0.556, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[96267] = { ["id"] = 96267, ["name"] = "Ancestral Gems", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["mapID"] = 2509, ["description"] = "When de Children of Ula'tek seized dis temple, many of my ancestors died defendin' it. Sacred relics were seized by de snakes! Even now, dey twist those items into foul magic! Among these items were some gems of great power. Search de vaults, ritual chambers, and every deep corner of de temple and recover any gems you find.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3448, ["amount"] = 350 } }, ["starts"] = { { ["npcID"] = 264611, ["x"] = 0.504, ["y"] = 0.638, ["zoneID"] = 16535 } }, ["ends"] = { { ["npcID"] = 264611, ["x"] = 0.504, ["y"] = 0.638, ["zoneID"] = 16535 } }, ["coords"] = { ["x"] = 0.504, ["y"] = 0.638, ["source"] = "quest_giver", ["zoneID"] = 16535 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16535 } }, ["questType"] = "group" },
[96268] = { ["id"] = 96268, ["name"] = "Marsh Mana Spores", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16943, ["mapID"] = 2600, ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.631, ["y"] = 0.55, ["mapID"] = 2600 } }, ["ends"] = { { ["x"] = 0.631, ["y"] = 0.55, ["mapID"] = 2600 } }, ["coords"] = { ["mapID"] = 2600, ["x"] = 0.631, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16943 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 264323, ["text"] = "Jump on a Bouncy Mushroom" }, { ["orderIndex"] = 1, ["type"] = 1, ["amount"] = 5, ["objectID"] = 276276, ["text"] = "Mana Spores gathered" } } },
[96271] = { ["id"] = 96271, ["name"] = "Cursed Existence", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["mapID"] = 2509, ["description"] = "When de poison spread through dis temple, many of our ancestors fell trying to defend dis place. Now Nek'zali has ensnared their spirits to serve her in restoring Ula'tek. Put de cursed spirits to rest so dey may pass beyond dis place.", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["starts"] = { { ["x"] = 0.506, ["y"] = 0.638, ["mapID"] = 2509, ["npcID"] = 264611 } }, ["ends"] = { { ["x"] = 0.506, ["y"] = 0.638, ["mapID"] = 2509, ["npcID"] = 264611 } }, ["coords"] = { ["mapID"] = 2509, ["x"] = 0.506, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16535 } }, ["questGiverID"] = 264611, ["questTurnInID"] = 264611, ["questType"] = "group", ["sourceQuests"] = { 96275 } },
[96273] = { ["id"] = 96273, ["name"] = "A Balance Paid in Blood", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["mapID"] = 2509, ["description"] = "De Children of Ula'tek have upset de balance of de spirit world. Many spirits are angry and demand justice before dey can move on. De snakes' blood will restore de balance! Slay de Children of Ula'tek and all dat aid dem here in de temple.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["starts"] = { { ["npcID"] = 264611, ["x"] = 0.504, ["y"] = 0.638, ["zoneID"] = 16535 } }, ["ends"] = { { ["npcID"] = 264611, ["x"] = 0.504, ["y"] = 0.638, ["zoneID"] = 16535 } }, ["coords"] = { ["x"] = 0.504, ["y"] = 0.638, ["source"] = "quest_giver", ["zoneID"] = 16535 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16535 } }, ["questType"] = "group", ["sourceQuests"] = { 96276 } },
[96275] = { ["id"] = 96275, ["name"] = "Wading In", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["mapID"] = 2509, ["description"] = "Too many spirits here have succumbed to de dark charms of Nek'zali, but there's still hope to save others. Place spirit guardians throughout de lakes of venom so dey may offer sanctuary to spirits nearby. De venom lakes are deadly, so go prepared!", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["starts"] = { { ["npcID"] = 264611, ["x"] = 0.504, ["y"] = 0.638, ["zoneID"] = 16535 } }, ["ends"] = { { ["npcID"] = 264611, ["x"] = 0.504, ["y"] = 0.638, ["zoneID"] = 16535 } }, ["coords"] = { ["x"] = 0.504, ["y"] = 0.638, ["source"] = "quest_giver", ["zoneID"] = 16535 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16535 } }, ["questTurnInID"] = 264611, ["questType"] = "group", ["sourceQuests"] = { 96273 } },
[96276] = { ["id"] = 96276, ["name"] = "Dark Charms", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["mapID"] = 2509, ["description"] = "De Children of Ula'tek play cruel games on de spirits here. Dey use dark charms to keep dem trapped and tormented. De charms are hidden throughout de temple. Find and burn them, so de spirits here can find peace.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3448, ["amount"] = 350 } }, ["starts"] = { { ["npcID"] = 264611, ["x"] = 0.504, ["y"] = 0.638, ["zoneID"] = 16535 } }, ["ends"] = { { ["npcID"] = 264611, ["x"] = 0.504, ["y"] = 0.638, ["zoneID"] = 16535 } }, ["coords"] = { ["x"] = 0.504, ["y"] = 0.638, ["source"] = "quest_giver", ["zoneID"] = 16535 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16535 } }, ["questType"] = "group", ["sourceQuests"] = { 96267 } },
[96293] = { ["id"] = 96293, ["name"] = "Mush-Vroom!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 17103, ["mapID"] = 2600, ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.342, ["y"] = 0.459, ["mapID"] = 2600 } }, ["ends"] = { { ["x"] = 0.342, ["y"] = 0.459, ["mapID"] = 2600 } }, ["coords"] = { ["mapID"] = 2600, ["x"] = 0.342, ["y"] = 0.459 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 17103 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 6, ["objectID"] = 264835, ["text"] = "Batteries thrown at volatile mushrooms" }, { ["orderIndex"] = 1, ["type"] = 0, ["amount"] = 10, ["objectID"] = 265115 } } },
