[96305] = { ["id"] = 96305, ["name"] = "The Innocent Essence", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["mapID"] = 2509, ["description"] = "When de defenders fell, cursed to their fate, so too did de great eagle Tok'jara who flew with dem. Such innocence did not deserve dis curse. Even now, de spirit struggles to break free, forming a twisting geyser as it rises from the venomous pools. Help it be free, claim its essence from the poison, and end its suffering.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["starts"] = { { ["x"] = 0.506, ["y"] = 0.638, ["mapID"] = 2509, ["npcID"] = 264611 } }, ["ends"] = { { ["x"] = 0.506, ["y"] = 0.638, ["mapID"] = 2509, ["npcID"] = 264611 } }, ["coords"] = { ["mapID"] = 2509, ["x"] = 0.506, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16535 } }, ["questGiverID"] = 264611, ["questTurnInID"] = 264611, ["questType"] = "group", ["sourceQuests"] = { 96271 } },
