[96310] = { ["id"] = 96310, ["name"] = "Disrupting the Order", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16900, ["mapID"] = 2599, ["description"] = "Great work defeating their forces. Every step we take will keep Azeroth safe. But usurpers are still trying to seize control. Baraat has already spotted high ranking domanaar looking at the remaining resources. We need to defeat the Umbrawardens and any of their forces along the way.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 25 } }, ["starts"] = { { ["npcID"] = 263482, ["x"] = 0.596, ["y"] = 0.218, ["zoneID"] = 16900 } }, ["ends"] = { { ["npcID"] = 265166, ["x"] = 0.668, ["y"] = 0.425, ["zoneID"] = 16900 } }, ["coords"] = { ["x"] = 0.596, ["y"] = 0.218, ["source"] = "quest_giver", ["zoneID"] = 16900 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16900 } }, ["questType"] = "standard", ["sourceQuests"] = { 96053 }, ["questLines"] = { { ["id"] = 6272, ["name"] = "Umbral Blitz", ["orderIndex"] = 0, ["flags"] = 0 } } },
