[96338] = { ["id"] = 96338, ["name"] = "Port of Entry", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16900, ["mapID"] = 2619, ["description"] = ", take a look at that platform above. What do you think they use that for? The void creatures steal wildlife from Azeroth and move them here to be broken, then added to their forces. That platform must be where creatures are first brought in. Let's force our way through any defenses up there and destroy that portal!", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 25 } }, ["starts"] = { { ["npcID"] = 265166, ["x"] = 0.668, ["y"] = 0.425, ["zoneID"] = 16900 } }, ["ends"] = { { ["npcID"] = 265166, ["x"] = 0.668, ["y"] = 0.425, ["zoneID"] = 16900 } }, ["coords"] = { ["x"] = 0.668, ["y"] = 0.425, ["source"] = "quest_giver", ["zoneID"] = 16900 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16900 } }, ["questType"] = "standard", ["sourceQuests"] = { 96310 }, ["questLines"] = { { ["id"] = 6272, ["name"] = "Umbral Blitz", ["orderIndex"] = 1, ["flags"] = 0 } } },
[96361] = { ["id"] = 96361, ["name"] = "Cursed Existence", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["mapID"] = 2509, ["description"] = "When de poison spread through dis temple, many of our ancestors fell trying to defend dis place. Now Nek'zali has ensnared their spirits to serve her in restoring Ula'tek. Put de cursed spirits to rest so dey may pass beyond dis place.", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16535 } }, ["questType"] = "group" },
[96382] = { ["id"] = 96382, ["name"] = "A New Approach", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16900, ["mapID"] = 2618, ["description"] = "For this threat, you'll need to think more like the domanaar. Luckily, I can do just that. What we need is a puppet. Someone we can give the reins who has no aspirations for your precious Azeroth. Those new domanaar you saw will need evaluation. Take this veil. You'll be able to blend in and observe them. I understand your urge to strike, but be patient. The time will come to eliminate all in your path, as your kind seems to enjoy. See if you can find a proper candidate.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 20 } }, ["starts"] = { { ["npcID"] = 264879, ["x"] = 0.598, ["y"] = 0.218, ["zoneID"] = 16900 } }, ["ends"] = { { ["npcID"] = 264879, ["x"] = 0.598, ["y"] = 0.218, ["zoneID"] = 16900 } }, ["coords"] = { ["x"] = 0.598, ["y"] = 0.218, ["source"] = "quest_giver", ["zoneID"] = 16900 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16900 } }, ["questTurnInID"] = 264879, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6291, ["name"] = "Considering an Alternative", ["orderIndex"] = 0, ["flags"] = 0 } } },
[96388] = { ["id"] = 96388, ["name"] = "Joining the Abyss Anglers", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["storyline"] = { 96388 }, ["description"] = "Ya ever heard of de Abyss Anglers? Forest tribes have been hunting de land as well as de waters for generations. Don't be shy, hash'ura. Grab a suit and go for a dive!", ["objectivesText"] = "Talk to Depthdiver Jeju to join an Abyss Anglers dive. Catch any 3 fish with your harpoon, recover 1 Sunken Artifact, and use the Surface! ability to return safely. Progress: De suit fit okay?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3373, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2437, ["npcID"] = 240195, ["x"] = 0.681, ["y"] = 0.198 } }, ["ends"] = { { ["mapID"] = 2437, ["npcID"] = 240195, ["x"] = 0.681, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 2437, ["source"] = "quest_giver", ["x"] = 0.681, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 2437, ["db2QuestInfoID"] = 282, ["db2QuestInfoName"] = "Important Quest" },
[96389] = { ["id"] = 96389, ["name"] = "A Place to Negotiate", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16900, ["mapID"] = 2599, ["description"] = "While you were attuning the gem to the Void, I managed to acquire one of Impotus's projection devices. We're going to use it to lure him to us, then prevent him from escaping with the gem. Not here, though. Let us find somewhere more discrete.", ["rewardGold"] = 170800, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 5 } }, ["starts"] = { { ["x"] = 0.637, ["y"] = 0.652, ["mapID"] = 2618, ["npcID"] = 265334 } }, ["ends"] = { { ["npcID"] = 267877, ["x"] = 0.589, ["y"] = 0.695, ["zoneID"] = 16900 } }, ["coords"] = { ["mapID"] = 2618, ["x"] = 0.637, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16900 } }, ["questGiverID"] = 265334, ["questType"] = "standard", ["sourceQuests"] = { 96475 }, ["questLines"] = { { ["id"] = 6291, ["name"] = "Considering an Alternative", ["orderIndex"] = 2, ["flags"] = 0 } } },
[96410] = { ["id"] = 96410, ["name"] = "Seeking Knowledge Week 1 of 5: The Omnium Folio", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 17067, ["mapID"] = 2649, ["description"] = "Those who sought to learn from the Omnium had to contribute to it. While most Magisters studied within the Terrace, a select few were appointed as \"Seekers of Wisdom.\" Seekers would search for new and foreign magic to contribute to the Omnium's vast index for study. Given your... adventurous experience, I think you'd make an excellent seeker. If you're interested, the Grand Magister will explain more.", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["starts"] = { { ["npcID"] = 264069, ["x"] = 0.604, ["y"] = 0.112, ["zoneID"] = 17067 } }, ["ends"] = { { ["npcID"] = 264070, ["x"] = 0.602, ["y"] = 0.116, ["zoneID"] = 17067 } }, ["coords"] = { ["x"] = 0.604, ["y"] = 0.112, ["source"] = "quest_giver", ["zoneID"] = 17067 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 17067 } }, ["questType"] = "standard", ["sourceQuests"] = { 96233 }, ["questLines"] = { { ["id"] = 6307, ["name"] = "The Empowered Folio", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 380, ["title"] = "The Empowered Folio", ["questLineID"] = 6307, ["questLineOrder"] = 0 } } },
[96439] = { ["id"] = 96439, ["name"] = "Gone Dark", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "These infernal nests are where de Children of Ula'tek spawn from. We must work to clear dem out if we are to have any hope of stemming de endless tide of snakes. I have been sending groups of my most fearless scouts to gather information on dem. All have returned... except for one. Go, track down Ulantu and Naj'kula in de Blistering Terrace. Find out why dey gone dark.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["starts"] = { { ["npcID"] = 265173, ["x"] = 0.578, ["y"] = 0.466, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 265173, ["x"] = 0.578, ["y"] = 0.466, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.578, ["y"] = 0.466, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questTurnInID"] = 265173, ["questType"] = "standard", ["sourceQuests"] = { 93024 }, ["nextQuests"] = { 96450 }, ["questLines"] = { { ["id"] = 6274, ["name"] = "The Monster's Mother", ["orderIndex"] = 0, ["flags"] = 1 } } },
[96440] = { ["id"] = 96440, ["name"] = "Victory Within Hindsight", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16900, ["mapID"] = 2599, ["description"] = "Great work, ! I can already picture the walls of the Acropolis crumbling. In fact, why don't we head there now and press our advantage? The Light can shine through the tiniest of cracks. I'll scout ahead and meet you on the way there.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 25 } }, ["starts"] = { { ["npcID"] = 265166, ["x"] = 0.668, ["y"] = 0.425, ["zoneID"] = 16900 } }, ["ends"] = { { ["npcID"] = 263482, ["x"] = 0.596, ["y"] = 0.218, ["zoneID"] = 16900 } }, ["coords"] = { ["x"] = 0.668, ["y"] = 0.425, ["source"] = "quest_giver", ["zoneID"] = 16900 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16900 } }, ["questType"] = "standard", ["sourceQuests"] = { 96338 }, ["questLines"] = { { ["id"] = 6272, ["name"] = "Umbral Blitz", ["orderIndex"] = 2, ["flags"] = 0 } } },
[96441] = { ["id"] = 96441, ["name"] = "Seeking Knowledge Week 2 of 5: Ritualized Arcana", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 17067, ["mapID"] = 2649, ["description"] = "The nature of the Dawnwell has sparked a question among the minds of Magisters' Terrace: If magic can corrupt and suffuse other magics, how will the Dawnwell affect the ley lines branching out from it? With inquiry, comes experiment. The Ritual Sites in Quel'Thalas use the ley lines to fuel their magic. Disrupt these sites and retrieve samples of the arcana you find.", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["rewardItems"] = { 274576 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 300 } }, ["starts"] = { { ["npcID"] = 264069, ["x"] = 0.604, ["y"] = 0.112, ["zoneID"] = 17067 } }, ["ends"] = { { ["npcID"] = 264070, ["x"] = 0.602, ["y"] = 0.116, ["zoneID"] = 17067 } }, ["coords"] = { ["x"] = 0.604, ["y"] = 0.112, ["source"] = "quest_giver", ["zoneID"] = 17067 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 17067 } }, ["questType"] = "standard", ["sourceQuests"] = { 96410, 96831 }, ["questLines"] = { { ["id"] = 6307, ["name"] = "The Empowered Folio", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 380, ["title"] = "The Empowered Folio", ["questLineID"] = 6307, ["questLineOrder"] = 0 } } },
[96442] = { ["id"] = 96442, ["name"] = "Seeking Knowledge Week 3 of 5: Ley Line Assaults", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 17067, ["mapID"] = 2424, ["description"] = "Unfortunately, most of the measurable samples were expunged by the Ritual Site's excessive energy. If we are to accurately measure the various magics seeping into the ley lines, we'll need samples from a broader, less concentrated source. I am told the Farstriders continue to route the void strikes across Quel'Thalas. Bring me coalesced ley energy from any of the assaulting forces.", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["rewardItems"] = { 274577 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 300 } }, ["starts"] = { { ["npcID"] = 264070, ["x"] = 0.602, ["y"] = 0.116, ["zoneID"] = 17067 } }, ["ends"] = { { ["npcID"] = 264069, ["x"] = 0.604, ["y"] = 0.112, ["zoneID"] = 17067 } }, ["coords"] = { ["x"] = 0.602, ["y"] = 0.116, ["source"] = "quest_giver", ["zoneID"] = 17067 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 17067 } }, ["questType"] = "standard", ["sourceQuests"] = { 96441, 96831 }, ["questLines"] = { { ["id"] = 6307, ["name"] = "The Empowered Folio", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 380, ["title"] = "The Empowered Folio", ["questLineID"] = 6307, ["questLineOrder"] = 0 } } },
[96443] = { ["id"] = 96443, ["name"] = "Seeking Knowledge Week 4 of 5: Magical Primessence", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 17067, ["mapID"] = 2424, ["description"] = "Thanks to your efforts, we've isolated the effects of trace amounts of foreign magic coalescing with the ley lines. Our next phase is to compare these results against a pure sample of magic coalescing with the same energy. Your task is to track down a primessence of magic--be it arcane, Void, Light, or other--and acquire it from its deadly source. Good luck, .", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["rewardItems"] = { 274580, 274581, 274582, 274583, 274584, 274585 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 300 } }, ["starts"] = { { ["npcID"] = 264070, ["x"] = 0.602, ["y"] = 0.116, ["zoneID"] = 17067 } }, ["ends"] = { { ["npcID"] = 264069, ["x"] = 0.604, ["y"] = 0.112, ["zoneID"] = 17067 } }, ["coords"] = { ["x"] = 0.602, ["y"] = 0.116, ["source"] = "quest_giver", ["zoneID"] = 17067 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 17067 } }, ["questType"] = "standard", ["sourceQuests"] = { 96442, 96831 }, ["questLines"] = { { ["id"] = 6307, ["name"] = "The Empowered Folio", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 380, ["title"] = "The Empowered Folio", ["questLineID"] = 6307, ["questLineOrder"] = 0 } } },
[96444] = { ["id"] = 96444, ["name"] = "Seeking Knowledge Week 5 of 5: Off-World Magic", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 17067, ["mapID"] = 2424, ["description"] = "Although it made an excellent catalyst, the primessence you retrieved revealed a factor we did not account for. The alien nature of the Void and ethereal magic used in their assaults proved incompatible with the experiment. We need a sample of their magic if we are to make any progress--not from the assaults here in Quel'Thalas, but from the source of their attacks. I am told these enemies strike from off-world staging grounds. Good luck, .", ["rewardGold"] = 1366400, ["rewardXP"] = 17110, ["rewardItems"] = { 274620, 274640 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 500 } }, ["starts"] = { { ["npcID"] = 264069, ["x"] = 0.604, ["y"] = 0.112, ["zoneID"] = 17067 } }, ["ends"] = { { ["npcID"] = 264070, ["x"] = 0.602, ["y"] = 0.116, ["zoneID"] = 17067 } }, ["coords"] = { ["x"] = 0.604, ["y"] = 0.112, ["source"] = "quest_giver", ["zoneID"] = 17067 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 17067 } }, ["questType"] = "standard", ["sourceQuests"] = { 96443, 96831 }, ["questLines"] = { { ["id"] = 6307, ["name"] = "The Empowered Folio", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 380, ["title"] = "The Empowered Folio", ["questLineID"] = 6307, ["questLineOrder"] = 0 } } },
[96446] = { ["id"] = 96446, ["name"] = "Spark of Tides", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["description"] = "A vision of tides permeates your mind. Eldara Dawnrunner might have more information regarding these Sparks of Tides.", ["rewardGold"] = 32200, ["starts"] = { { ["x"] = 0.402, ["y"] = 0.648, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 243229, ["x"] = 0.402, ["y"] = 0.648, ["mapID"] = 2393 } }, ["coords"] = { ["mapID"] = 2393, ["x"] = 0.402, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[96450] = { ["id"] = 96450, ["name"] = "Sideways", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2640, ["description"] = "Naj'kula and I were here to observe how the Children of Ula'tek reproduce. We discovered dis lich, Lokago. Malacrass had him experimentin' on kidnapped Amani. I stole his records to try and figure out why, but de lich discovered us. I was injured. I dropped everythin'. Naj'kula was right behind me... We gotta recover de notes--and find Naj'kula!", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["x"] = 0.807, ["y"] = 0.461, ["mapID"] = 2640, ["npcID"] = 265194 } }, ["ends"] = { { ["x"] = 0.807, ["y"] = 0.461, ["mapID"] = 2640, ["npcID"] = 265194 } }, ["coords"] = { ["mapID"] = 2640, ["x"] = 0.807, ["y"] = 0.461 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questGiverID"] = 265194, ["questTurnInID"] = 265194, ["questType"] = "standard", ["sourceQuests"] = { 96439 }, ["questLines"] = { { ["id"] = 6274, ["name"] = "The Monster's Mother", ["orderIndex"] = 1, ["flags"] = 0 } } },
[96451] = { ["id"] = 96451, ["name"] = "A Child of Ula'tek", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2640, ["description"] = "I don't like dis. We should have found her by now. Ulantu 's face is sweaty and pale. She rubs her wound absentmindedly.> De lich must have dragged her back to where he was doin' his experiments. And if his notes are to be believed... We need to find Naj'kula quickly--or she may not be who she was.", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 20 }, { ["id"] = 3504, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.207, ["y"] = 0.357, ["mapID"] = 2640, ["npcID"] = 265229 } }, ["ends"] = { { ["x"] = 0.207, ["y"] = 0.357, ["mapID"] = 2640, ["npcID"] = 265229 } }, ["coords"] = { ["mapID"] = 2640, ["x"] = 0.207, ["y"] = 0.357 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questGiverID"] = 265229, ["questTurnInID"] = 265229, ["questType"] = "standard", ["sourceQuests"] = { 96450 }, ["questLines"] = { { ["id"] = 6274, ["name"] = "The Monster's Mother", ["orderIndex"] = 2, ["flags"] = 0 } } },
[96457] = { ["id"] = 96457, ["name"] = "Nothing Must Remain", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2640, ["description"] = "You saw what he did to Naj'kula. And who knows how many others. Ulantu is sweating and pale, gripping her stomach.> Too many lives were sacrificed in de name of these awful... whatever Kuku became. If only we could have killed de damned lich! But we can destroy his lab.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["x"] = 0.405, ["y"] = 0.722, ["mapID"] = 2640, ["npcID"] = 265278 } }, ["ends"] = { { ["x"] = 0.405, ["y"] = 0.722, ["mapID"] = 2640, ["npcID"] = 265278 } }, ["coords"] = { ["mapID"] = 2640, ["x"] = 0.405, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questGiverID"] = 265278, ["questTurnInID"] = 265278, ["questType"] = "standard", ["sourceQuests"] = { 96451 }, ["questLines"] = { { ["id"] = 6274, ["name"] = "The Monster's Mother", ["orderIndex"] = 4, ["flags"] = 0 } } },
[96458] = { ["id"] = 96458, ["name"] = "Last Promise", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "Lokago cut me with de same venom that twisted Naj'kula. I feel it burnin' me just the same. I intend to die an Amani. But my work is unfinished. Please get these notes to Kul'amara. Tell her she can find me at Naj'kula's side.", ["rewardGold"] = 85400, ["rewardXP"] = 3420, ["rewardItems"] = { 271609 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3504, ["amount"] = 250 } }, ["starts"] = { { ["x"] = 0.405, ["y"] = 0.722, ["mapID"] = 2640, ["npcID"] = 265278 } }, ["ends"] = { { ["npcID"] = 265173, ["x"] = 0.578, ["y"] = 0.466, ["zoneID"] = 16365 } }, ["coords"] = { ["mapID"] = 2640, ["x"] = 0.405, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questGiverID"] = 265278, ["questType"] = "standard", ["sourceQuests"] = { 96457 }, ["questLines"] = { { ["id"] = 6274, ["name"] = "The Monster's Mother", ["orderIndex"] = 3, ["flags"] = 0 } } },
[96466] = { ["id"] = 96466, ["name"] = "Prey: Anguish Island", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2512, ["description"] = "Something is driving these creatures into our realm. I have sent one of my most capable servants to this \"Isle of Fangs\". Go and see what you can make of this den of snakes. In any other endeavor I would accompany you, of course--but I shall remain here. This island sounds like a most dreadful place. Do have fun, though.", ["rewardGold"] = 85400, ["rewardXP"] = 3420, ["starts"] = { { ["npcID"] = 246231, ["x"] = 0.566, ["y"] = 0.654, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 265267, ["x"] = 0.582, ["y"] = 0.486, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.566, ["y"] = 0.654, ["source"] = "quest_giver", ["zoneID"] = 15969 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 96004 }, ["questLines"] = { { ["id"] = 6296, ["name"] = "Prey: Isle of Fangs", ["orderIndex"] = 1, ["flags"] = 0 } } },
[96467] = { ["id"] = 96467, ["name"] = "Thirst for Knowledge", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "Two brothers came with us to dis cursed place... Zei'ka and Jun'ka. Zei'ka , he got de fire in him. Soon as we landed, he ran off, chasing whispers like dey were calling his name. But, Jun'ka, he ain't a fool. He went after his brother, tryin' to keep him from getting himself killed. I don't like dis. Dis island, it'll swallow us whole if we ain't careful. Go check on dem, eh?", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["starts"] = { { ["npcID"] = 265173, ["x"] = 0.578, ["y"] = 0.466, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 265329, ["x"] = 0.75, ["y"] = 0.626, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.578, ["y"] = 0.466, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 93024 }, ["nextQuests"] = { 96469 }, ["questLines"] = { { ["id"] = 6277, ["name"] = "Ancient Anthropology", ["orderIndex"] = 0, ["flags"] = 1 } } },
[96469] = { ["id"] = 96469, ["name"] = "The Crypt of the Disgraced", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "Jun'ka's my brother, but he frets too much to let me chase after my life's dream. Ever since I was a child, I wanted to learn more of our history. While much of it is told by de talespinners back home, they always skipped one thing: Atal'Utek. De more I dug, de more mysterious it became, and de more I became engrossed. Now, de scouts tell me that this crypt is filled with tablets inside. Tablets that could have de history of our people. I need to see those tablets, even if it kills me. You in?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 265329, ["x"] = 0.75, ["y"] = 0.626, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 265329, ["x"] = 0.75, ["y"] = 0.626, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.75, ["y"] = 0.626, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questTurnInID"] = 265329, ["questType"] = "standard", ["sourceQuests"] = { 96467 }, ["questLines"] = { { ["id"] = 6277, ["name"] = "Ancient Anthropology", ["orderIndex"] = 1, ["flags"] = 0 } } },
[96471] = { ["id"] = 96471, ["name"] = "Crumble and Tumble", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "Blast it all! I dragged y'all into dis muck just 'cause my brother's worried about my hide! You're gettin' outta here quick! I lead, you follow, and don't lag behind, or you're squashed!", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["rewardItems"] = { 280105 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3504, ["amount"] = 250 } }, ["starts"] = { { ["x"] = 0.611, ["y"] = 0.597, ["mapID"] = 2644, ["npcID"] = 265330 } }, ["ends"] = { { ["npcID"] = 267032, ["x"] = 0.748, ["y"] = 0.624, ["zoneID"] = 16365 } }, ["coords"] = { ["mapID"] = 2644, ["x"] = 0.611, ["y"] = 0.597 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questGiverID"] = 265330, ["questType"] = "standard", ["sourceQuests"] = { 96469 }, ["questLines"] = { { ["id"] = 6277, ["name"] = "Ancient Anthropology", ["orderIndex"] = 2, ["flags"] = 0 } } },
[96472] = { ["id"] = 96472, ["name"] = "The Nexus-Captain", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16943, ["mapID"] = 2600, ["description"] = "The Hal'hadar may not know we are here yet, but they still hold the advantage. Nexus-Captain Leth'ir and his associate, Mertei, are just over this ridge and surrounded by a small army. If you can rally enough allies and catch their leaders off guard, we will deal a devastating blow before they know what hit them. Proceed with caution,  and make sure you are not alone.", ["rewardGold"] = 2732800, ["rewardXP"] = 23530, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 75 } }, ["starts"] = { { ["npcID"] = 264028, ["x"] = 0.708, ["y"] = 0.622, ["zoneID"] = 16943 } }, ["ends"] = { { ["npcID"] = 264024, ["x"] = 0.484, ["y"] = 0.82, ["zoneID"] = 16943 } }, ["coords"] = { ["x"] = 0.708, ["y"] = 0.622, ["source"] = "quest_giver", ["zoneID"] = 16943 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16943 } }, ["questType"] = "group", ["sourceQuests"] = { 96054 } },
[96473] = { ["id"] = 96473, ["name"] = "Imperator Pertinax", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16900, ["description"] = "Like all domanaar, Imperator Pertinax sees himself only as a predator and never the prey. Unfortunately, our prey is well-guarded in his Void Acropolis. If you manage to gather enough allies and catch the imperator off guard, we'll deal a crushing blow to our enemies. Move swiftly and cautiously,  and ensure you have backup before engaging Pertinax.", ["rewardGold"] = 2732800, ["rewardXP"] = 23530, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 75 } }, ["starts"] = { { ["npcID"] = 263987, ["x"] = 0.416, ["y"] = 0.846, ["zoneID"] = 16900 } }, ["ends"] = { { ["npcID"] = 264879, ["x"] = 0.598, ["y"] = 0.218, ["zoneID"] = 16900 } }, ["coords"] = { ["x"] = 0.416, ["y"] = 0.846, ["source"] = "quest_giver", ["zoneID"] = 16900 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16900 } }, ["questType"] = "group", ["sourceQuests"] = { 96053 } },
[96474] = { ["id"] = 96474, ["name"] = "Prey: Something for Astalor", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "$p! Ah, we haven't met. Not formally. I've overheard some of your discussions with Magister Astalor while I was, er, scrubbing the floors. You seem like quite the competent operator! That makes two of us. Usually. I'm a bit... preoccupied at the moment, what with the local wildlife and all. Maybe you can poke around for us?", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["starts"] = { { ["npcID"] = 265267, ["x"] = 0.582, ["y"] = 0.486, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 265267, ["x"] = 0.582, ["y"] = 0.486, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.582, ["y"] = 0.486, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 96466 }, ["questLines"] = { { ["id"] = 6296, ["name"] = "Prey: Isle of Fangs", ["orderIndex"] = 2, ["flags"] = 0 } } },
[96492] = { ["id"] = 96492, ["name"] = "Special Assignment: Demand and Supply", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["rewardXP"] = 13690, ["starts"] = { { ["x"] = 0.579, ["y"] = 0.49, ["mapID"] = 2512 } }, ["ends"] = { { ["x"] = 0.579, ["y"] = 0.49, ["mapID"] = 2512 } }, ["coords"] = { ["mapID"] = 2512, ["x"] = 0.579, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6228, ["name"] = "The Coiled Isle - World Quests/Repeatables", ["orderIndex"] = 40, ["flags"] = 0 } } },
[96496] = { ["id"] = 96496, ["name"] = "The Road Not Taken Twice", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16900, ["mapID"] = 2599, ["description"] = "During our surveys of this iced desert, our scouts identified two areas worth keeping an eye on, but with a major problem: they're only accessible through single points of entry. Before I'm comfortable sending out more forces, we need to secure their exits. We've been working on teleportation crystals for faster local travel that leverage the domanaar's existing portal network, and we're close to a solution. You just need to field test them. Set up these prototype rift slippers and report back.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["starts"] = { { ["npcID"] = 263482, ["x"] = 0.596, ["y"] = 0.218, ["zoneID"] = 16900 } }, ["ends"] = { { ["npcID"] = 263482, ["x"] = 0.596, ["y"] = 0.218, ["zoneID"] = 16900 } }, ["coords"] = { ["x"] = 0.596, ["y"] = 0.218, ["source"] = "quest_giver", ["zoneID"] = 16900 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16900 } }, ["questType"] = "standard", ["sourceQuests"] = { 96053 } },
[96497] = { ["id"] = 96497, ["name"] = "Spatial Reasoning", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16900, ["mapID"] = 2599, ["description"] = "The domanaar are more entrenched here than we thought and these storms refuse to relent even for a moment. We've finally figured out how to hijack their portal network for short range traversal thanks to your efforts setting up the rift slippers. Now we just need help setting up our portal bridges . Here are four strategic locations, including this outpost, for you to set up the portal bridges . Once active, you'll be able to more swiftly respond to threats as they arise. Time to get to work.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["starts"] = { { ["npcID"] = 263482, ["x"] = 0.596, ["y"] = 0.218, ["zoneID"] = 16900 } }, ["ends"] = { { ["npcID"] = 263482, ["x"] = 0.596, ["y"] = 0.218, ["zoneID"] = 16900 } }, ["coords"] = { ["x"] = 0.596, ["y"] = 0.218, ["source"] = "quest_giver", ["zoneID"] = 16900 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16900 } }, ["questType"] = "standard" },
[96498] = { ["id"] = 96498, ["name"] = "Grovewarden's Kris", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["rewardItems"] = { 257155 }, ["starts"] = { { ["npcID"] = 251259, ["x"] = 0.492, ["y"] = 0.544, ["mapID"] = 2413 } }, ["ends"] = { { ["npcID"] = 251259, ["x"] = 0.492, ["y"] = 0.544, ["mapID"] = 2413 } }, ["coords"] = { ["x"] = 0.492, ["y"] = 0.544, ["source"] = "quest_giver", ["mapID"] = 2413 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard" },
