[96523] = { ["id"] = 96523, ["name"] = "Living Legend", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["description"] = "These soldiers--dey are too young to remember the time before de loa gave us their help. So de loa can't come here. So? Let me tell a legend dat takes place before the loa helped our kind. Maybe you heard of it? Or maybe you want to see it for yourself...", ["rewardGold"] = 85400, ["rewardXP"] = 3420, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 265476, ["x"] = 0.594, ["y"] = 0.508, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 265660, ["x"] = 0.454, ["y"] = 0.482, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.594, ["y"] = 0.508, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 92920 }, ["questLines"] = { { ["id"] = 6302, ["name"] = "Living Legend", ["orderIndex"] = 0, ["flags"] = 0 } } },
[96525] = { ["id"] = 96525, ["name"] = "Prey: Out of Our Depth", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["description"] = "This is more than I'm prepared to deal with. I'll open a portal back to the Sanctum. I'm going to wait for these blasted little snakelings to grow tired of me before following you through. Do put in a good word for me, please.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["starts"] = { { ["npcID"] = 265267, ["x"] = 0.582, ["y"] = 0.486, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 246231, ["x"] = 0.566, ["y"] = 0.654, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.582, ["y"] = 0.486, ["source"] = "quest_giver", ["mapID"] = 2393 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 96474 }, ["questLines"] = { { ["id"] = 6296, ["name"] = "Prey: Isle of Fangs", ["orderIndex"] = 5, ["flags"] = 0 } } },
[96528] = { ["id"] = 96528, ["name"] = "Prey: Anguish from Beyond", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "$p! I tried to sneak away from those snakes, but one of them slithered up my pant leg and I blacked out for a bit. When I awoke, I was here... I wonder if there's anything in here that would interest Magister Astalor. Wait... what's that? That glowing... It looks like your crystal is interacting with something in this tomb!", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 274422 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 35 } }, ["starts"] = { { ["npcID"] = 265529, ["x"] = 0.57, ["y"] = 0.332, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 265529, ["x"] = 0.57, ["y"] = 0.332, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.57, ["y"] = 0.332, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 96532 } },
[96532] = { ["id"] = 96532, ["name"] = "Prey: Attending the Attendant", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "My methods might come across as cruel and unusual to some, but I do take to heart the well being of those who serve under me. Most of the time. Attendant Ethrandil has served our cause admirably. Please let him know he can return to me. These floors have grown noticeably dirtier as of late...", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["starts"] = { { ["npcID"] = 246231, ["x"] = 0.566, ["y"] = 0.654, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 265529, ["x"] = 0.57, ["y"] = 0.332, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.566, ["y"] = 0.654, ["source"] = "quest_giver", ["zoneID"] = 15969 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 96525 }, ["questLines"] = { { ["id"] = 6296, ["name"] = "Prey: Isle of Fangs", ["orderIndex"] = 4, ["flags"] = 0 } } },
[96534] = { ["id"] = 96534, ["name"] = "Preparing for Threats", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16943, ["description"] = "My brother has always been the creative one, his hands busy on some intricate side project or some device he's working on. His enthusiasm will benefit this operation greatly, especially when it comes to thwarting the threats we face on this world. See what he's been working on and give one of his new experiments a trial run. I'm sure he'll be thrilled at the opportunity to contribute.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 274772 }, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 5 } }, ["starts"] = { { ["npcID"] = 265558, ["x"] = 0.478, ["y"] = 0.814, ["zoneID"] = 16943 } }, ["ends"] = { { ["npcID"] = 265558, ["x"] = 0.478, ["y"] = 0.814, ["zoneID"] = 16943 } }, ["coords"] = { ["x"] = 0.478, ["y"] = 0.814, ["source"] = "quest_giver", ["zoneID"] = 16943 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16943 } }, ["questType"] = "standard", ["sourceQuests"] = { 96054 } },
[96539] = { ["id"] = 96539, ["name"] = "Last Resort", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["description"] = "Long, long ago, there was a village that suffered from a great drought. De crops wouldn't grow, and the land dried up. De whole village was starving! The villagers came to one troll--Jeytha--to ask her a favor. In dis story, you are Jeytha--now go see what those hungry villagers want!", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 265660, ["x"] = 0.454, ["y"] = 0.482, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 265661, ["x"] = 0.444, ["y"] = 0.48, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.454, ["y"] = 0.482, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 96523 }, ["questLines"] = { { ["id"] = 6302, ["name"] = "Living Legend", ["orderIndex"] = 1, ["flags"] = 0 } } },
[96540] = { ["id"] = 96540, ["name"] = "Strong Hands", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["description"] = "Jeytha came across a fox in de path, beset by lynx. And she was kind, and unafraid, and strong--so she decided to help that fox out. Now go tell those lynx to get outta here!", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 265661, ["x"] = 0.444, ["y"] = 0.48, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 265662, ["x"] = 0.436, ["y"] = 0.478, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.444, ["y"] = 0.48, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 96539 }, ["questLines"] = { { ["id"] = 6302, ["name"] = "Living Legend", ["orderIndex"] = 2, ["flags"] = 0 } } },
[96541] = { ["id"] = 96541, ["name"] = "Strong Mind", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["description"] = "That sly old fox wasn't just any fox! He spoke, and he ran, and he waited for Jeytha to meet him. Now what did he want with Jeytha? You should talk to him and find out!", ["rewardGold"] = 85400, ["rewardXP"] = 3420, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 265662, ["x"] = 0.436, ["y"] = 0.478, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 265660, ["x"] = 0.454, ["y"] = 0.482, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.436, ["y"] = 0.478, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 96540 }, ["questLines"] = { { ["id"] = 6302, ["name"] = "Living Legend", ["orderIndex"] = 3, ["flags"] = 0 } } },
[96543] = { ["id"] = 96543, ["name"] = "Root of Survival", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["description"] = "Now dat she was back where she started, Jeytha knew she couldn't make that journey. But what of de starving villagers? How would they survive? Jeytha had a few ideas... if the villagers would listen to her. Go see what she has to say!", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 265660, ["x"] = 0.454, ["y"] = 0.482, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 269367, ["x"] = 0.454, ["y"] = 0.484, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.454, ["y"] = 0.482, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 96541 }, ["questLines"] = { { ["id"] = 6302, ["name"] = "Living Legend", ["orderIndex"] = 4, ["flags"] = 0 } } },
[96544] = { ["id"] = 96544, ["name"] = "Bravely Burning", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["description"] = "Years passed, and she didn't use dat third boon. One year, a flight of angry dragonhawks set their eyes--and flames--on de village. Her son was trapped, their home on fire! \"I could use my boon,\" thought Jeytha, \"But why use my boon, when I can use my strength?\" Go show those dragonhawks your strength, and save dat boy!", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 265660, ["x"] = 0.454, ["y"] = 0.482, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 265666, ["x"] = 0.456, ["y"] = 0.49, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.454, ["y"] = 0.482, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 96543 }, ["questLines"] = { { ["id"] = 6302, ["name"] = "Living Legend", ["orderIndex"] = 5, ["flags"] = 0 } } },
[96545] = { ["id"] = 96545, ["name"] = "Strong Voice", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["description"] = "The years passed, and still Jeytha did not use dat third boon. One year, a group of raiders arrived at de village, looking to steal everything dey had. \"I could use dat third boon,\" Jeytha thought, \"But why use dat boon when I can use my voice?\" Go talk those raiders down--and if dey don't listen, use your strength and change their minds!", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3504, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 265666, ["x"] = 0.456, ["y"] = 0.49, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 265668, ["x"] = 0.452, ["y"] = 0.486, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.456, ["y"] = 0.49, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["sourceQuests"] = { 96544 }, ["questLines"] = { { ["id"] = 6302, ["name"] = "Living Legend", ["orderIndex"] = 6, ["flags"] = 0 } } },
[96546] = { ["id"] = 96546, ["name"] = "Strong Heart", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "The years passed, and Jeytha felt her time coming. She'd lived a long life, full of struggles but still happy. But as Jeytha reached the end of her days, dat sly old fox appeared. \"Wait!\" he said. \"You can't go yet!\" Now what does that fox want? Go talk to him and find out!", ["rewardGold"] = 683200, ["rewardXP"] = 17110, ["rewardItems"] = { 280201 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 25 }, { ["id"] = 3504, ["amount"] = 250 } }, ["starts"] = { { ["npcID"] = 265668, ["x"] = 0.452, ["y"] = 0.486, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 265476, ["x"] = 0.594, ["y"] = 0.508, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.452, ["y"] = 0.486, ["source"] = "quest_giver", ["zoneID"] = 15947 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 96545 }, ["questLines"] = { { ["id"] = 6302, ["name"] = "Living Legend", ["orderIndex"] = 7, ["flags"] = 0 } } },
[96557] = { ["id"] = 96557, ["name"] = "Flying Debris", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16943, ["mapID"] = 2600, ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.549, ["y"] = 0.336, ["mapID"] = 2600 } }, ["ends"] = { { ["x"] = 0.549, ["y"] = 0.336, ["mapID"] = 2600 } }, ["coords"] = { ["mapID"] = 2600, ["x"] = 0.549, ["y"] = 0.336 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16943 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 12, ["objectID"] = 265649, ["text"] = "Remote Detonators planted" }, { ["orderIndex"] = 1, ["type"] = 0, ["amount"] = 1, ["objectID"] = 265650, ["text"] = "Remote Detonators triggered" } } },
[96567] = { ["id"] = 96567, ["name"] = "Data Decryption Disaster", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16943, ["mapID"] = 2600, ["description"] = "To understand the Hal'hadar's intentions with this world, we will need to secure information. Knowing how they operate, they've restricted their data consoles with security measures in place. This decrypter will automatically navigate their security. If you choose, you can engage the manual option to hasten the protocol. Just remember to ignore any security warnings. My device can and will bypass it.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 25 } }, ["starts"] = { { ["npcID"] = 266034, ["x"] = 0.478, ["y"] = 0.82, ["zoneID"] = 16943 } }, ["ends"] = { { ["npcID"] = 266034, ["x"] = 0.478, ["y"] = 0.82, ["zoneID"] = 16943 } }, ["coords"] = { ["x"] = 0.478, ["y"] = 0.82, ["source"] = "quest_giver", ["zoneID"] = 16943 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16943 } }, ["questType"] = "standard", ["sourceQuests"] = { 97072 }, ["questLines"] = { { ["id"] = 6300, ["name"] = "The Hal'hadar Files", ["orderIndex"] = 0, ["flags"] = 0 } } },
[96568] = { ["id"] = 96568, ["name"] = "Hal'hadon't You Dare!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16943, ["mapID"] = 2600, ["description"] = "Y'mera's plan to intercept their data consoles will no doubt trigger heightened security protocols. Normally, no-contact reconnaissance would be advised in this situation, but I think sowing chaos will be more beneficial. The Hal'hadar won't be aware of their stolen data if their entire manaforge is under attack. Dispatch any Hal'hadar agents you find.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 25 } }, ["starts"] = { { ["npcID"] = 265950, ["x"] = 0.476, ["y"] = 0.82, ["zoneID"] = 16943 } }, ["ends"] = { { ["npcID"] = 265950, ["x"] = 0.476, ["y"] = 0.82, ["zoneID"] = 16943 } }, ["coords"] = { ["x"] = 0.476, ["y"] = 0.82, ["source"] = "quest_giver", ["zoneID"] = 16943 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16943 } }, ["questType"] = "standard", ["sourceQuests"] = { 97072 }, ["questLines"] = { { ["id"] = 6300, ["name"] = "The Hal'hadar Files", ["orderIndex"] = 1, ["flags"] = 0 } } },
[96569] = { ["id"] = 96569, ["name"] = "Conductive Crystals", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16943, ["mapID"] = 2600, ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 25 } }, ["starts"] = { { ["npcID"] = 654497, ["x"] = 0.705, ["y"] = 0.487, ["zoneID"] = 16943 } }, ["ends"] = { { ["npcID"] = 265559, ["x"] = 0.478, ["y"] = 0.812, ["zoneID"] = 16943 } }, ["coords"] = { ["x"] = 0.705, ["y"] = 0.487, ["source"] = "quest_giver", ["zoneID"] = 16943 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16943 } }, ["questType"] = "standard", ["sourceQuests"] = { 97072 }, ["questLines"] = { { ["id"] = 6300, ["name"] = "The Hal'hadar Files", ["orderIndex"] = 2, ["flags"] = 0 } } },
[96570] = { ["id"] = 96570, ["name"] = "Technological Transference", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16943, ["mapID"] = 2600, ["description"] = "The Hal'hadar are notorious for looting and stealing technology from any world they descend upon. Thanks to the intel you helped retrieve, we know they are using the manaforge east of us to experiment on whatever salvage they found. Take this translocator with you and mark anything that doesn't resemble ethereal technology. I will transport it back here for further study.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 25 } }, ["starts"] = { { ["npcID"] = 266034, ["x"] = 0.478, ["y"] = 0.82, ["zoneID"] = 16943 } }, ["ends"] = { { ["npcID"] = 266034, ["x"] = 0.478, ["y"] = 0.82, ["zoneID"] = 16943 } }, ["coords"] = { ["x"] = 0.478, ["y"] = 0.82, ["source"] = "quest_giver", ["zoneID"] = 16943 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16943 } }, ["questType"] = "standard", ["sourceQuests"] = { 96567, 96568, 96569 }, ["questLines"] = { { ["id"] = 6300, ["name"] = "The Hal'hadar Files", ["orderIndex"] = 3, ["flags"] = 0 } } },
[96571] = { ["id"] = 96571, ["name"] = "The Node Knows", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16943, ["mapID"] = 2600, ["description"] = "The manaforge to the east serves as both a research site and military compound, making it a valuable target. Much of their research, including holoprint schematics, lays around the forge. The Hal'hadar stationed here also carry nodes containing experimental and logistical data. Take advantage of this accessible intel and bring back what you can find.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 25 } }, ["starts"] = { { ["npcID"] = 265950, ["x"] = 0.476, ["y"] = 0.82, ["zoneID"] = 16943 } }, ["ends"] = { { ["npcID"] = 265950, ["x"] = 0.476, ["y"] = 0.82, ["zoneID"] = 16943 } }, ["coords"] = { ["x"] = 0.476, ["y"] = 0.82, ["source"] = "quest_giver", ["zoneID"] = 16943 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16943 } }, ["questType"] = "standard", ["sourceQuests"] = { 96567, 96568, 96569 }, ["questLines"] = { { ["id"] = 6300, ["name"] = "The Hal'hadar Files", ["orderIndex"] = 4, ["flags"] = 0 } } },
[96572] = { ["id"] = 96572, ["name"] = "Malfunctioning Nullframe", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16943, ["mapID"] = 2600, ["rewardGold"] = 683200, ["rewardXP"] = 14705, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 50 } }, ["starts"] = { { ["x"] = 0.742, ["y"] = 0.735, ["mapID"] = 2600 } }, ["ends"] = { { ["npcID"] = 266034, ["x"] = 0.478, ["y"] = 0.82, ["zoneID"] = 16943 } }, ["coords"] = { ["mapID"] = 2600, ["x"] = 0.742, ["y"] = 0.735 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16943 } }, ["questType"] = "standard", ["sourceQuests"] = { 96567, 96568, 96569 }, ["questLines"] = { { ["id"] = 6300, ["name"] = "The Hal'hadar Files", ["orderIndex"] = 5, ["flags"] = 0 } } },
[96573] = { ["id"] = 96573, ["name"] = "Soul Lattice Revealed", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16943, ["mapID"] = 2600, ["description"] = "It took some work, but we've cracked their ciphers. The Hal'hadar seek to power their Nullframes using draenei vigilant technology. The \"Soul Lattice\" is a heart for the Nullframe using a vigilant's core. With it, they can bind their unwrapped energy into the core and wear the frame like armor. The Hal'hadar must not succeed in finishing this prototype. Y'mera is planning the next move. Speak with her.", ["rewardGold"] = 85400, ["rewardXP"] = 2940, ["starts"] = { { ["npcID"] = 265558, ["x"] = 0.478, ["y"] = 0.814, ["zoneID"] = 16943 } }, ["ends"] = { { ["npcID"] = 265950, ["x"] = 0.476, ["y"] = 0.82, ["zoneID"] = 16943 } }, ["coords"] = { ["x"] = 0.478, ["y"] = 0.814, ["source"] = "quest_giver", ["zoneID"] = 16943 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16943 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6300, ["name"] = "The Hal'hadar Files", ["orderIndex"] = 6, ["flags"] = 0 } } },
[96574] = { ["id"] = 96574, ["name"] = "Cryptside Rendezvous", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 17103, ["mapID"] = 2600, ["description"] = "The tomb is called Vilaldoun. It means \"island of the restful.\" Its entrance lies on the northern coast. We know the Hal'hadar have established an extraction site outside the crypt, harvesting the local flora there to fuel their research. As you approach, you will be met with heavy resistance. Cut a path through their ranks while we establish a footing inside and meet us within.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 25 } }, ["starts"] = { { ["npcID"] = 265950, ["x"] = 0.476, ["y"] = 0.82, ["zoneID"] = 16943 } }, ["ends"] = { { ["npcID"] = 266829, ["x"] = 0.754, ["y"] = 0.442, ["zoneID"] = 17103 } }, ["coords"] = { ["x"] = 0.476, ["y"] = 0.82, ["source"] = "quest_giver", ["zoneID"] = 16943 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 17103 } }, ["questType"] = "standard", ["sourceQuests"] = { 96573 }, ["questLines"] = { { ["id"] = 6300, ["name"] = "The Hal'hadar Files", ["orderIndex"] = 7, ["flags"] = 0 } } },
[96575] = { ["id"] = 96575, ["name"] = "Cages of the Soul", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 17103, ["mapID"] = 2646, ["description"] = "Without the tomb's defenses, the souls of the dead were easy targets for the Hal'hadar. The ethereals intend to use the spirits to fuel the Soul Lattices for the Nullframe. We must not let that happen. Take my scepter and use it to repair the defense wards and shatter the energy cages binding the dead. Once you've finished, regroup with Tala'saan in the lower chambers.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 25 } }, ["starts"] = { { ["npcID"] = 266541, ["x"] = 0.754, ["y"] = 0.442, ["zoneID"] = 17103 } }, ["ends"] = { { ["npcID"] = 266540, ["x"] = 0.362, ["y"] = 0.728, ["zoneID"] = 17103 } }, ["coords"] = { ["x"] = 0.754, ["y"] = 0.442, ["source"] = "quest_giver", ["zoneID"] = 17103 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 17103 } }, ["questType"] = "standard", ["sourceQuests"] = { 96574 }, ["questLines"] = { { ["id"] = 6300, ["name"] = "The Hal'hadar Files", ["orderIndex"] = 8, ["flags"] = 0 } } },
[96576] = { ["id"] = 96576, ["name"] = "Mementos of the Dead", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16943, ["mapID"] = 2646, ["description"] = "Defiling tombs... harnessing innocent souls as fuel... The Hal'hadar are no better than demons. If left unchecked, the ethereals will pilfer every grave and altar down here. I may bear the title of \"Souleater,\" but it doesn't mean I can't honor the dead in this forgotten place. Recover the tributes the ethereals have stolen. Bring them to Tala'saan in the lower chamber.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 25 } }, ["starts"] = { { ["npcID"] = 266829, ["x"] = 0.754, ["y"] = 0.442, ["zoneID"] = 17103 } }, ["ends"] = { { ["npcID"] = 266540, ["x"] = 0.362, ["y"] = 0.728, ["zoneID"] = 17103 } }, ["coords"] = { ["x"] = 0.754, ["y"] = 0.442, ["source"] = "quest_giver", ["zoneID"] = 17103 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16943 } }, ["questType"] = "standard", ["sourceQuests"] = { 96574 }, ["questLines"] = { { ["id"] = 6300, ["name"] = "The Hal'hadar Files", ["orderIndex"] = 9, ["flags"] = 0 } } },
[96577] = { ["id"] = 96577, ["name"] = "The Soul Architect", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 17103, ["mapID"] = 2600, ["description"] = "The architect leading their operation has found a single vigilant with an intact construct core. The other vigilants in this chamber appear to be depleted. If she succeeds in creating the Soul Lattice, the Hal'hadar will possess the means to turn our warframes into new armored bodies for their soldiers. We must stop her now and recover the Soul Lattice prototype.", ["rewardGold"] = 683200, ["rewardXP"] = 14705, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 75 } }, ["starts"] = { { ["npcID"] = 266540, ["x"] = 0.362, ["y"] = 0.728, ["zoneID"] = 17103 } }, ["ends"] = { { ["npcID"] = 266540, ["x"] = 0.362, ["y"] = 0.728, ["zoneID"] = 17103 } }, ["coords"] = { ["x"] = 0.362, ["y"] = 0.728, ["source"] = "quest_giver", ["zoneID"] = 17103 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 17103 } }, ["questType"] = "standard", ["sourceQuests"] = { 96575, 96576 }, ["questLines"] = { { ["id"] = 6300, ["name"] = "The Hal'hadar Files", ["orderIndex"] = 10, ["flags"] = 0 } } },
[96578] = { ["id"] = 96578, ["name"] = "Cryptic Departure", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16943, ["mapID"] = 2600, ["description"] = "Although she escaped, we have denied the architect her prototype... for now. This Soul Lattice is fractured, but the core within still hums with a faint energy. Perhaps this vigilant's soul yet remains... If we hurry, perhaps Veraan and her brother can help stabilize the damage to preserve it. I will regroup with Y'mera and Allari and meet you back at camp.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 266540, ["x"] = 0.362, ["y"] = 0.728, ["zoneID"] = 17103 } }, ["ends"] = { { ["npcID"] = 265558, ["x"] = 0.478, ["y"] = 0.814, ["zoneID"] = 16943 } }, ["coords"] = { ["x"] = 0.362, ["y"] = 0.728, ["source"] = "quest_giver", ["zoneID"] = 17103 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16943 } }, ["questType"] = "standard", ["sourceQuests"] = { 96577 }, ["questLines"] = { { ["id"] = 6300, ["name"] = "The Hal'hadar Files", ["orderIndex"] = 11, ["flags"] = 0 } } },
