[96633] = { ["id"] = 96633, ["name"] = "Equipment Seminar", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["description"] = "Welcome back, ! I've continued my collaboration with the artisans here in Silvermoon. Their techniques have only grown more refined. Infusing equipment with the essence of the dawn is no longer just theory, it's becoming an art form. I'm eager to resume our work together. Bring me another piece of Adventurer equipment, and we'll see how these improved methods hold up in practice. Plenty of people are always in need of a capable hand. Help them, and they'll reward you accordingly.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["starts"] = { { ["npcID"] = 239676, ["x"] = 0.486, ["y"] = 0.618, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 239676, ["x"] = 0.486, ["y"] = 0.618, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.486, ["y"] = 0.618, ["source"] = "quest_giver", ["mapID"] = 2393 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[96635] = { ["id"] = 96635, ["name"] = "Upgrade Practicum", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["description"] = "Cuzolth and I have pushed our craft further than ever, allowing us to imbue your gear with greater power. To unlock its full potential, we'll need Mistcrests. They're drawn from trials of all kinds--greater dangers yield stronger crests, though even Adventurer Mistcrests carry a spark of that power. Bring me fifty Adventurer Mistcrests, . Let's see what your equipment is truly capable of.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["starts"] = { { ["npcID"] = 239676, ["x"] = 0.486, ["y"] = 0.618, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 239676, ["x"] = 0.486, ["y"] = 0.618, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.486, ["y"] = 0.618, ["source"] = "quest_giver", ["mapID"] = 2393 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 96633 } },
[96637] = { ["id"] = 96637, ["name"] = "Veteran Symposium", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["description"] = "There is a lot more power where that came from! Upgrades scale with strength. Higher quality items can reach higher heights of power. For this step, I'll need Veteran equipment along with some Veteran Mistcrests. Once you bring them, Cuzolth and I can continue making the enhancements.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["starts"] = { { ["npcID"] = 239676, ["x"] = 0.486, ["y"] = 0.618, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 239676, ["x"] = 0.486, ["y"] = 0.618, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.486, ["y"] = 0.618, ["source"] = "quest_giver", ["mapID"] = 2393 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 96635 } },
[96640] = { ["id"] = 96640, ["name"] = "Bounty of the Cursed", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["mapID"] = 2509, ["description"] = "Dis temple holds many secrets, $p. Ancient power, just waitin' for someone to take it. De Soulcoilers might be dead, but their power remains. Find their caches and bring me whatever you find.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 50 }, { ["id"] = 3448, ["amount"] = 200 }, { ["id"] = 3448, ["amount"] = 250 }, { ["id"] = 3448, ["amount"] = 350 } }, ["starts"] = { { ["npcID"] = 262880, ["x"] = 0.51, ["y"] = 0.626, ["zoneID"] = 16535 } }, ["ends"] = { { ["npcID"] = 262880, ["x"] = 0.51, ["y"] = 0.626, ["zoneID"] = 16535 } }, ["coords"] = { ["x"] = 0.51, ["y"] = 0.626, ["source"] = "quest_giver", ["zoneID"] = 16535 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16535 } }, ["questType"] = "group" },
[96641] = { ["id"] = 96641, ["name"] = "Relentless Strikes", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["mapID"] = 2509, ["description"] = "Some say de forces of Ula'tek are endless--dat we can never kill them all. But I like a challenge. How 'bout you? Strike de enemy hard, and we'll see how endless dey are.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 100 }, { ["id"] = 3316, ["amount"] = 50 }, { ["id"] = 3448, ["amount"] = 200 }, { ["id"] = 3448, ["amount"] = 250 } }, ["starts"] = { { ["npcID"] = 272109, ["x"] = 0.478, ["y"] = 0.65, ["zoneID"] = 16535 } }, ["ends"] = { { ["npcID"] = 262798, ["x"] = 0.472, ["y"] = 0.608, ["zoneID"] = 16535 } }, ["coords"] = { ["x"] = 0.478, ["y"] = 0.65, ["source"] = "quest_giver", ["zoneID"] = 16535 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16535 } }, ["questType"] = "group" },
[96642] = { ["id"] = 96642, ["name"] = "Decisive Incursions", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["mapID"] = 2509, ["description"] = "De strikes are de first step. We cannot let de enemy recover. First we batter them, soften 'em up. Then, we hit dem hard and fast with everything we've got. We don't have de forces for a longer battle. When de time comes for de incursion, you'd best be ready. Gather your allies. De enemy is mighty.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 50 }, { ["id"] = 3448, ["amount"] = 200 }, { ["id"] = 3448, ["amount"] = 250 }, { ["id"] = 3448, ["amount"] = 350 } }, ["starts"] = { { ["npcID"] = 272109, ["x"] = 0.478, ["y"] = 0.65, ["zoneID"] = 16535 } }, ["ends"] = { { ["npcID"] = 262798, ["x"] = 0.472, ["y"] = 0.608, ["zoneID"] = 16535 } }, ["coords"] = { ["x"] = 0.478, ["y"] = 0.65, ["source"] = "quest_giver", ["zoneID"] = 16535 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16535 } }, ["questType"] = "group" },
[96643] = { ["id"] = 96643, ["name"] = "From Whence it Came", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["mapID"] = 2509, ["description"] = "Can you feel it? Old things lurk in de temple, just waitin' to rise once again. Dey are drawn by the sounds of battle, eager to visit their violence upon you. Find one of these ancient foes and ensure it does not rise again.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 50 }, { ["id"] = 3448, ["amount"] = 200 }, { ["id"] = 3448, ["amount"] = 250 }, { ["id"] = 3448, ["amount"] = 350 } }, ["starts"] = { { ["npcID"] = 262880, ["x"] = 0.51, ["y"] = 0.626, ["zoneID"] = 16535 } }, ["ends"] = { { ["npcID"] = 262880, ["x"] = 0.51, ["y"] = 0.626, ["zoneID"] = 16535 } }, ["coords"] = { ["x"] = 0.51, ["y"] = 0.626, ["source"] = "quest_giver", ["zoneID"] = 16535 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16535 } }, ["questType"] = "group", ["sourceQuests"] = { 98388 } },
[96644] = { ["id"] = 96644, ["name"] = "Essence of Malice", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["mapID"] = 2509, ["description"] = "I'm in need of venom, pure and potent. De venom dat wells up through de ground is too diluted--fouled with other things. You need to find a font of de profane stuff. Search de depths of de vaults. Dat's where de true venom will be found.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 100 }, { ["id"] = 3316, ["amount"] = 50 }, { ["id"] = 3448, ["amount"] = 200 }, { ["id"] = 3448, ["amount"] = 250 } }, ["starts"] = { { ["npcID"] = 262880, ["x"] = 0.51, ["y"] = 0.626, ["zoneID"] = 16535 } }, ["ends"] = { { ["npcID"] = 262880, ["x"] = 0.51, ["y"] = 0.626, ["zoneID"] = 16535 } }, ["coords"] = { ["x"] = 0.51, ["y"] = 0.626, ["source"] = "quest_giver", ["zoneID"] = 16535 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16535 } }, ["questType"] = "group", ["sourceQuests"] = { 98388 } },
