[96703] = { ["id"] = 96703, ["name"] = "Veterans of the Great Dark", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["description"] = "When the Hal'hadar attacked, we quickly learned about their history with the Army of the Light. Commander Tala'saan has been providing us information on these ethereals. His soldiers stand ready to join our cause. I've requested their expertise in establishing a forward camp for our mission. Aid them in their preparations and inform the commander we mobilize soon.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 263479, ["x"] = 0.476, ["y"] = 0.51, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 263479, ["x"] = 0.476, ["y"] = 0.51, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.476, ["y"] = 0.51, ["source"] = "quest_giver", ["mapID"] = 2393 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 96048 }, ["questLines"] = { { ["id"] = 6282, ["name"] = "Assault and Strike Back", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 6309, ["name"] = "Assault and Strike Back: Val", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 6310, ["name"] = "Assault and Strike Back: Naigtal", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 359, ["title"] = "Welcome to Naigtal", ["questLineID"] = 6282, ["questLineOrder"] = 0 }, { ["id"] = 357, ["title"] = "Welcome to Val", ["questLineID"] = 6309, ["questLineOrder"] = 0 }, { ["id"] = 358, ["title"] = "Welcome to Naigtal", ["questLineID"] = 6310, ["questLineOrder"] = 0 } } },
[96708] = { ["id"] = 96708, ["name"] = "To the Voidstorm and Beyond!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15458, ["mapID"] = 2405, ["description"] = "It may not seem like many, but the allies we've secured will have to be enough. It's time we move out. Our forces are gathering at the Howling Ridge. The energies of the Voidstorm will allow us to open the way to these worlds. I will meet you there. There is something here I still require for our mission.", ["rewardGold"] = 34100, ["rewardXP"] = 1470, ["starts"] = { { ["npcID"] = 263479, ["x"] = 0.476, ["y"] = 0.51, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 263480, ["x"] = 0.516, ["y"] = 0.71, ["mapID"] = 2405 } }, ["coords"] = { ["x"] = 0.476, ["y"] = 0.51, ["source"] = "quest_giver", ["mapID"] = 2405 }, ["mapCandidates"] = { ["npc"] = { 2393, 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 96049, 96703 }, ["questLines"] = { { ["id"] = 6282, ["name"] = "Assault and Strike Back", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6309, ["name"] = "Assault and Strike Back: Val", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6310, ["name"] = "Assault and Strike Back: Naigtal", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 359, ["title"] = "Welcome to Naigtal", ["questLineID"] = 6282, ["questLineOrder"] = 0 }, { ["id"] = 357, ["title"] = "Welcome to Val", ["questLineID"] = 6309, ["questLineOrder"] = 0 }, { ["id"] = 358, ["title"] = "Welcome to Naigtal", ["questLineID"] = 6310, ["questLineOrder"] = 0 } } },
[96713] = { ["id"] = 96713, ["name"] = "Showdown on Val", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16900, ["description"] = "Our enemy's hold on Val may be strong, but it is not unbreakable. For every monstrosity we cut down, we deny them another soldier to use against our world. Venture out into the frozen landscape and lay waste to their strongholds. Show them no mercy, .", ["rewardXP"] = 17110, ["rewardItems"] = { 275690 }, ["starts"] = { { ["npcID"] = 263479, ["x"] = 0.476, ["y"] = 0.51, ["mapID"] = 2393 }, { ["npcID"] = 263482, ["x"] = 0.596, ["y"] = 0.218, ["zoneID"] = 16900 } }, ["ends"] = { { ["npcID"] = 263482, ["x"] = 0.596, ["y"] = 0.218, ["zoneID"] = 16900 } }, ["coords"] = { ["x"] = 0.476, ["y"] = 0.51, ["source"] = "quest_giver", ["zoneID"] = 15969 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 16900 } }, ["questType"] = "standard", ["sourceQuests"] = { 96051 } },
