[96716] = { ["id"] = 96716, ["name"] = "Showdown on Val", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16900, ["description"] = "Our enemy's hold on Val may be strong, but it is not unbreakable. For every monstrosity we cut down, we deny them another soldier to use against our world. Venture out into the frozen landscape and lay waste to their strongholds. Show them no mercy, .", ["rewardXP"] = 14705, ["rewardItems"] = { 272125 }, ["starts"] = { { ["npcID"] = 263479, ["x"] = 0.476, ["y"] = 0.51, ["mapID"] = 2393 }, { ["npcID"] = 263482, ["x"] = 0.596, ["y"] = 0.218, ["zoneID"] = 16900 } }, ["ends"] = { { ["npcID"] = 263482, ["x"] = 0.596, ["y"] = 0.218, ["zoneID"] = 16900 } }, ["coords"] = { ["x"] = 0.476, ["y"] = 0.51, ["source"] = "quest_giver", ["zoneID"] = 15969 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 16900 } }, ["questType"] = "standard" },
[96717] = { ["id"] = 96717, ["name"] = "Showdown on Naigtal", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16943, ["description"] = "Now this is quite a strange world, isn't it? The Hal'hadar must have found something of note. The stench of forges indicates they are plundering the riches and resources this remote rock has to offer. If you can disrupt the operations here, you can buy your precious world a moment of respite. Do what you do best, my little monster.", ["rewardXP"] = 17110, ["rewardItems"] = { 275690 }, ["starts"] = { { ["npcID"] = 263531, ["x"] = 0.476, ["y"] = 0.51, ["mapID"] = 2393 }, { ["npcID"] = 265303, ["x"] = 0.484, ["y"] = 0.82, ["zoneID"] = 16943 } }, ["ends"] = { { ["npcID"] = 265303, ["x"] = 0.484, ["y"] = 0.82, ["zoneID"] = 16943 } }, ["coords"] = { ["x"] = 0.476, ["y"] = 0.51, ["source"] = "quest_giver", ["zoneID"] = 15969 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 16943 } }, ["questType"] = "standard", ["sourceQuests"] = { 96052 } },
