[96995] = { ["id"] = 96995, ["name"] = "Turn Back the Surge", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["description"] = "De temple can no longer contain Ula'tek's wrath. De boldest of her brood are spilling out all over de isle! They'll destroy us all if we don't stem de tide of venom. Fight dem wherever dey dare to show their ugly heads. Do not let dem get a foothold.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 274476, 275911 }, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 100 }, { ["id"] = 3504, ["amount"] = 1000 } }, ["starts"] = { { ["npcID"] = 267635, ["x"] = 0.586, ["y"] = 0.458, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 267635, ["x"] = 0.586, ["y"] = 0.458, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.586, ["y"] = 0.458, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard" },
[97016] = { ["id"] = 97016, ["name"] = "Mixing Mysteries", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["description"] = "You think you've got some potent ingredients for my stew, eh? We'll see what de spirits think. Show me what you've brought and I'll throw it in de cauldron. De spirits will eat their fill, and if dey like it, you might get a reward. Or a punishment, if dey hate it. So choose wisely!", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 277985 }, ["starts"] = { { ["npcID"] = 254599, ["x"] = 0.574, ["y"] = 0.486, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 267451, ["x"] = 0.574, ["y"] = 0.486, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.574, ["y"] = 0.486, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 97026 } },
