[97031] = { ["id"] = 97031, ["name"] = "Vilaldoun Valediction", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16943, ["mapID"] = 2646, ["rewardGold"] = 312800, ["rewardXP"] = 11765, ["starts"] = { { ["npcID"] = 658789, ["x"] = 0.541, ["y"] = 0.263, ["zoneID"] = 17103 } }, ["ends"] = { { ["npcID"] = 266034, ["x"] = 0.478, ["y"] = 0.82, ["zoneID"] = 16943 } }, ["coords"] = { ["x"] = 0.541, ["y"] = 0.263, ["source"] = "quest_giver", ["zoneID"] = 17103 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16943 } }, ["questType"] = "standard", ["sourceQuests"] = { 96574 } },
[97034] = { ["id"] = 97034, ["name"] = "Vanquish the Warmonger", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16900, ["mapID"] = 2599, ["description"] = "Poor Impotus doesn't seem to believe we can seize control from his nefarious kin. He's tragically unimaginative. We'll just need to show him an example of our combined strength. Slay that brute of a newcomer, Ignedus. I think his armor would look nice on our new savior. Ignedus seems to be quite careful in showing his face, but clearly quick to anger. Get in there and make some noise, as you're so comfortable doing. I expect him to respond in kind.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 30 } }, ["starts"] = { { ["npcID"] = 264879, ["x"] = 0.598, ["y"] = 0.218, ["zoneID"] = 16900 } }, ["ends"] = { { ["npcID"] = 264941, ["x"] = 0.62, ["y"] = 0.216, ["zoneID"] = 16900 } }, ["coords"] = { ["x"] = 0.598, ["y"] = 0.218, ["source"] = "quest_giver", ["zoneID"] = 16900 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16900 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6297, ["name"] = "A Dance with Domanaar", ["orderIndex"] = 0, ["flags"] = 0 } } },
[97035] = { ["id"] = 97035, ["name"] = "Depose the Deranged", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16900, ["mapID"] = 2599, ["description"] = "Defeating Ignedus is impressive, I suppose, but it does not mean you're any closer to taking Val. Periculus won't let you meddle with his playthings. He is an... eccentric one, to say the least, and dreadfully fascinated by you flesh-beings. You'll likely find him in the darkest hole this world has to offer, carving open the livestock that Pertinax gathered. He likes to toy with his prey, so I would advise caution.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 30 } }, ["starts"] = { { ["npcID"] = 264941, ["x"] = 0.62, ["y"] = 0.216, ["zoneID"] = 16900 }, { ["npcID"] = 267578, ["x"] = 0.62, ["y"] = 0.216, ["zoneID"] = 16900 } }, ["ends"] = { { ["npcID"] = 267578, ["x"] = 0.62, ["y"] = 0.216, ["zoneID"] = 16900 } }, ["coords"] = { ["x"] = 0.62, ["y"] = 0.216, ["source"] = "quest_giver", ["zoneID"] = 16900 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16900 } }, ["questType"] = "standard", ["sourceQuests"] = { 97034 }, ["questLines"] = { { ["id"] = 6297, ["name"] = "A Dance with Domanaar", ["orderIndex"] = 1, ["flags"] = 0 } } },
[97036] = { ["id"] = 97036, ["name"] = "Umbral Title Bout", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16900, ["mapID"] = 2599, ["description"] = "Well then, it seems our goals are more aligned than before. You've impressed me. With Ignedus and Periculus dealt with, all that remains is my former associate. You will find Gladius Reginax atop that high platform, observing her quarry. She already knows you're coming, so don't aim to surprise her. There's only one way up there for you anyway: through that portal in the Glacial Reservoir. I will play my part and join you. A symbol of our... collaboration.", ["rewardGold"] = 683200, ["rewardXP"] = 14705, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 75 } }, ["starts"] = { { ["npcID"] = 267578, ["x"] = 0.62, ["y"] = 0.216, ["zoneID"] = 16900 } }, ["ends"] = { { ["npcID"] = 264879, ["x"] = 0.598, ["y"] = 0.218, ["zoneID"] = 16900 } }, ["coords"] = { ["x"] = 0.62, ["y"] = 0.216, ["source"] = "quest_giver", ["zoneID"] = 16900 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16900 } }, ["questType"] = "standard", ["sourceQuests"] = { 97035 }, ["questLines"] = { { ["id"] = 6297, ["name"] = "A Dance with Domanaar", ["orderIndex"] = 2, ["flags"] = 0 } } },
[97037] = { ["id"] = 97037, ["name"] = "Stargrim Revelations", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15458, ["mapID"] = 2405, ["description"] = "We have a problem, . The hologem you found revealed much about our people's time on this world and who the vigilants were in life. Who they were is not the problem, but rather the possessions they carried within their chassis. Possessions now in the hands of the Soul Architect who, as far as my scouts can tell, has left Naigtal. Archmage Y'mera will explain in greater detail.", ["rewardGold"] = 256200, ["rewardXP"] = 8825, ["starts"] = { { ["npcID"] = 265950, ["x"] = 0.476, ["y"] = 0.82, ["zoneID"] = 16943 } }, ["ends"] = { { ["npcID"] = 245240, ["x"] = 0.508, ["y"] = 0.686, ["mapID"] = 2405 } }, ["coords"] = { ["x"] = 0.476, ["y"] = 0.82, ["source"] = "quest_giver", ["mapID"] = 2405 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["sourceQuests"] = { 96578 } },
[97071] = { ["id"] = 97071, ["name"] = "A Frigid Welcome to Val", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16900, ["mapID"] = 2599, ["description"] = "Even with the element of surprise, we are at a disadvantage without allies. Storming Pertinax's stronghold alone would be a death sentence. Take this beacon Tala'saan gave us and return to our entry point. I will meet you there and deliver my report to Maella. Let us hope we have some sort of shelter awaiting us.", ["rewardGold"] = 256200, ["rewardXP"] = 8825, ["rewardItems"] = { 276371 }, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 5 } }, ["starts"] = { { ["npcID"] = 263987, ["x"] = 0.416, ["y"] = 0.846, ["zoneID"] = 16900 } }, ["ends"] = { { ["npcID"] = 263482, ["x"] = 0.596, ["y"] = 0.218, ["zoneID"] = 16900 } }, ["coords"] = { ["x"] = 0.416, ["y"] = 0.846, ["source"] = "quest_giver", ["zoneID"] = 16900 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16900 } }, ["questType"] = "standard", ["sourceQuests"] = { 96053 }, ["questLines"] = { { ["id"] = 6309, ["name"] = "Assault and Strike Back: Val", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 6282, ["name"] = "Assault and Strike Back", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 357, ["title"] = "Welcome to Val", ["questLineID"] = 6309, ["questLineOrder"] = 0 }, { ["id"] = 359, ["title"] = "Welcome to Naigtal", ["questLineID"] = 6282, ["questLineOrder"] = 0 } } },
[97072] = { ["id"] = 97072, ["name"] = "A Swampy Welcome to Naigtal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16943, ["mapID"] = 2600, ["description"] = "The Nexus-Captain is just over that hill, unaware of our arrival. Attacking now would catch his army off guard... and likely result in our demise. No matter what, we will need allies if we are to succeed. Use this beacon to return to our invasion point. By now, Y'mera has likely brought in the rest of our forces to support us. Speak with Maella when you arrive.", ["rewardGold"] = 256200, ["rewardXP"] = 8825, ["rewardItems"] = { 276371 }, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 5 } }, ["starts"] = { { ["npcID"] = 264028, ["x"] = 0.708, ["y"] = 0.622, ["zoneID"] = 16943 } }, ["ends"] = { { ["npcID"] = 264024, ["x"] = 0.484, ["y"] = 0.82, ["zoneID"] = 16943 } }, ["coords"] = { ["x"] = 0.708, ["y"] = 0.622, ["source"] = "quest_giver", ["zoneID"] = 16943 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16943 } }, ["questType"] = "standard", ["sourceQuests"] = { 96054 }, ["questLines"] = { { ["id"] = 6310, ["name"] = "Assault and Strike Back: Naigtal", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 6282, ["name"] = "Assault and Strike Back", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 358, ["title"] = "Welcome to Naigtal", ["questLineID"] = 6310, ["questLineOrder"] = 0 }, { ["id"] = 359, ["title"] = "Welcome to Naigtal", ["questLineID"] = 6282, ["questLineOrder"] = 0 } } },
