[97077] = { ["id"] = 97077, ["name"] = "A Shot at the Dark", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16900, ["mapID"] = 2599, ["description"] = "Now that our trap is attuned, we just need to lure our prey out into the open. I have strategically... dismantled... certain parts of the projection device I obtained. Impotus should have difficulty seeing and hearing you clearly. Claim to be one of his allies and demand a meeting at once. We will hope his curiosity gets the better of him. And then...", ["rewardGold"] = 683200, ["rewardXP"] = 14705, ["rewardCurrencies"] = { { ["id"] = 3405, ["amount"] = 35 } }, ["starts"] = { { ["npcID"] = 267877, ["x"] = 0.589, ["y"] = 0.695, ["zoneID"] = 16900 } }, ["ends"] = { { ["npcID"] = 264879, ["x"] = 0.598, ["y"] = 0.218, ["zoneID"] = 16900 } }, ["coords"] = { ["x"] = 0.589, ["y"] = 0.695, ["source"] = "quest_giver", ["zoneID"] = 16900 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16900 } }, ["questType"] = "standard", ["sourceQuests"] = { 96389 }, ["questLines"] = { { ["id"] = 6291, ["name"] = "Considering an Alternative", ["orderIndex"] = 3, ["flags"] = 0 } } },
[97080] = { ["id"] = 97080, ["name"] = "More Disruptions: Val", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16900, ["description"] = "We must not let up the pressure. Even now they are rebuilding from our attacks. Venture out again and show them no mercy!", ["rewardXP"] = 14705, ["rewardItems"] = { 276387 }, ["starts"] = { { ["x"] = 0.595, ["y"] = 0.22, ["mapID"] = 2599, ["npcID"] = 263482 } }, ["ends"] = { { ["npcID"] = 263482, ["x"] = 0.596, ["y"] = 0.218, ["zoneID"] = 16900 } }, ["coords"] = { ["mapID"] = 2599, ["x"] = 0.595, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16900 } }, ["questGiverID"] = 263482, ["questType"] = "standard", ["sourceQuests"] = { 96713 } },
