[97084] = { ["id"] = 97084, ["name"] = "More Disruption: Naigtal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16943, ["description"] = "The stench of their forges still lingers. This means they are rebuilding. You must keep at it if you hope to disrupt their operations enough to end their threat. Now you can go. Wreak havoc.", ["rewardXP"] = 14705, ["rewardItems"] = { 276387 }, ["starts"] = { { ["x"] = 0.482, ["y"] = 0.812, ["mapID"] = 2600, ["npcID"] = 265303 } }, ["ends"] = { { ["npcID"] = 264024, ["x"] = 0.484, ["y"] = 0.82, ["zoneID"] = 16943 } }, ["coords"] = { ["mapID"] = 2600, ["x"] = 0.482, ["y"] = 0.812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16943 } }, ["questGiverID"] = 265303, ["questType"] = "standard", ["sourceQuests"] = { 96717 } },
[97085] = { ["id"] = 97085, ["name"] = "Dangerous Enemies: Naigtal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16943, ["description"] = "I hear your scouts talk of dangerous creatures and foes they have faced. It makes me wonder if you could defeat them? Why don't you go and try? It will certainly help your efforts here. I hope to see you return mostly intact.", ["rewardXP"] = 14705, ["rewardItems"] = { 275690, 276389 }, ["starts"] = { { ["x"] = 0.482, ["y"] = 0.812, ["mapID"] = 2600, ["npcID"] = 265303 } }, ["ends"] = { { ["npcID"] = 264024, ["x"] = 0.484, ["y"] = 0.82, ["zoneID"] = 16943 } }, ["coords"] = { ["mapID"] = 2600, ["x"] = 0.482, ["y"] = 0.812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16943 } }, ["questGiverID"] = 265303, ["questType"] = "standard", ["sourceQuests"] = { 96717 } },
