[97141] = { ["id"] = 97141, ["name"] = "Spoils of the Vaults", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["description"] = "It takes de whole of our strength to keep de forces of Ula'tek from overwhelming de isle. Dat battle is waged inside the Vault of Ula'tek, against the endless tide of her children. Kill one, and two more will slither out of de venom. Venture in,  and lend your power to our weary fighters. Who knows? You may even find something valuable in dat ancient, cursed place.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 276531, 276532, 276533, 276534 }, ["starts"] = { { ["npcID"] = 268228, ["x"] = 0.588, ["y"] = 0.46, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 268228, ["x"] = 0.588, ["y"] = 0.46, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.588, ["y"] = 0.46, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard" },
[97215] = { ["id"] = 97215, ["name"] = "A Secondary Strike", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15458, ["mapID"] = 2405, ["description"] = "We have struck a major blow against our enemies. Still, they continue their assaults. Decimus and my riftwardens have targeted another world from which they launch these attacks. The bulk of our forces have temporarily withdrawn to the Voidstorm so that we may begin our assault on this second world. Our strike team awaits us at the Howling Ridge.", ["rewardGold"] = 34100, ["rewardXP"] = 1470, ["starts"] = { { ["npcID"] = 263479, ["x"] = 0.476, ["y"] = 0.51, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 263480, ["x"] = 0.516, ["y"] = 0.71, ["mapID"] = 2405 } }, ["coords"] = { ["x"] = 0.476, ["y"] = 0.51, ["source"] = "quest_giver", ["mapID"] = 2405 }, ["mapCandidates"] = { ["npc"] = { 2393, 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard" },
[97256] = { ["id"] = 97256, ["name"] = "Knocking Off the Top (Heroic)", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16943, ["mapID"] = 2599, ["description"] = "Even the most ruthless of creatures falter when they see their greatest champions crumble to ash. Remind our enemies here just how quickly their leaders fall! Let them know just how unrelenting and vicious you monsters of Azeroth really are! Bring me the Void Commander's Emblems and I will reward you accordingly.", ["rewardGold"] = 1024800, ["rewardChoices"] = { 276787, 276788, 276789, 276790, 276791, 276792, 276793, 276794, 276799 }, ["starts"] = { { ["npcID"] = 264879, ["x"] = 0.598, ["y"] = 0.218, ["zoneID"] = 16900 }, { ["npcID"] = 265303, ["x"] = 0.484, ["y"] = 0.82, ["zoneID"] = 16943 } }, ["ends"] = { { ["npcID"] = 264879, ["x"] = 0.598, ["y"] = 0.218, ["zoneID"] = 16900 }, { ["npcID"] = 265303, ["x"] = 0.484, ["y"] = 0.82, ["zoneID"] = 16943 } }, ["coords"] = { ["x"] = 0.598, ["y"] = 0.218, ["source"] = "quest_giver", ["zoneID"] = 16900 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16943 } }, ["questType"] = "standard", ["sourceQuests"] = { 96052 } },
[97321] = { ["id"] = 97321, ["name"] = "Slithering Spoils", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["description"] = "I've got good news and bad news. Bad is that all those curios we dug up together? Melted. Good news? I've found some very interesting new poisons to work with. But let me explain what happened...", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 25 } }, ["starts"] = { { ["npcID"] = 242381, ["x"] = 0.524, ["y"] = 0.78, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 242381, ["x"] = 0.524, ["y"] = 0.78, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.524, ["y"] = 0.78, ["source"] = "quest_giver", ["mapID"] = 2393 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 97454 } },
[97382] = { ["id"] = 97382, ["name"] = "Counter-Curse Bounty", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["description"] = "Every part of dis isle is cursed, . When de curse of Ula'tek coalesces into a fight, dat is when it is most important to strike back. We need all de help we can get keeping it at bay. You look strong... but you'll need better equipment if you want to stay alive. Defeat the leader of one of dese surges, and then we can discuss a reward.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 276641, 276642, 276643, 276644 }, ["starts"] = { { ["npcID"] = 268228, ["x"] = 0.588, ["y"] = 0.46, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 268228, ["x"] = 0.588, ["y"] = 0.46, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.588, ["y"] = 0.46, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard" },
[97383] = { ["id"] = 97383, ["name"] = "Spirit Corrosion", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["description"] = "Our scouts found dis relic in one of da crypts. Maybe Er'inye knows what to do with it?", ["starts"] = { { ["npcID"] = 268228, ["x"] = 0.588, ["y"] = 0.46, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 262880, ["x"] = 0.51, ["y"] = 0.626, ["zoneID"] = 16535 } }, ["coords"] = { ["x"] = 0.588, ["y"] = 0.46, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16535 } }, ["questType"] = "standard" },
[97454] = { ["id"] = 97454, ["name"] = "Seasonal Refresher: Midnight", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["description"] = "Since the opening of the Coiling Isles, things have started to get interesting again in delves. See if our dear hosts have anything they can spare for those of us actually risking our necks and check the Delver's Guide for any updates. A quick refresher never hurt anyone.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 25 } }, ["starts"] = { { ["npcID"] = 242381, ["x"] = 0.524, ["y"] = 0.78, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 242381, ["x"] = 0.524, ["y"] = 0.78, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.524, ["y"] = 0.78, ["source"] = "quest_giver", ["mapID"] = 2393 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
