[97482] = { ["id"] = 97482, ["name"] = "Fangs for the Memories", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["description"] = "That snake monstrosity was vicious, with venom potent enough to burn through stone. We'll want to make sure we get our hands on the best gear we can before we think about taking it on. I've got some ideas about turning that venom to our own ends, though, so we can hit the ground running.", ["rewardGold"] = 4099200, ["rewardXP"] = 27380, ["rewardItems"] = { 275988 }, ["rewardCurrencies"] = { { ["id"] = 3310, ["amount"] = 25 } }, ["starts"] = { { ["npcID"] = 242381, ["x"] = 0.524, ["y"] = 0.78, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 242381, ["x"] = 0.524, ["y"] = 0.78, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.524, ["y"] = 0.78, ["source"] = "quest_giver", ["mapID"] = 2393 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 97321 } },
[97557] = { ["id"] = 97557, ["name"] = "Tailing the Tlhapi", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["description"] = "Toxic Tlhapi . Nasty little fish. Everything's wrong about them, from their big, buggy eyes to their sweet, succulent meat... Not to mention the toxicity. The seas would be much better without them fouling things up.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3540, ["amount"] = 150 } }, ["starts"] = { { ["npcID"] = 268394, ["x"] = 0.516, ["y"] = 0.502, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 268394, ["x"] = 0.516, ["y"] = 0.502, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.516, ["y"] = 0.502, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard" },
[97562] = { ["id"] = 97562, ["name"] = "Culling the Killifish", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["description"] = "Spotted Killifish . Grotesque little creatures. The little demons swarm like insects, washing up on shores in such horrific numbers that it would take several meals to devour them all. You can do your part by collecting some for me, ridding the waters of their foul presence.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3540, ["amount"] = 150 } }, ["starts"] = { { ["npcID"] = 268394, ["x"] = 0.516, ["y"] = 0.502, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 268394, ["x"] = 0.516, ["y"] = 0.502, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.516, ["y"] = 0.502, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard" },
[97571] = { ["id"] = 97571, ["name"] = "Dogging the Darters", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["description"] = "Dirty Darters . Ghoulish little buggers. The way they flit about the water is so unnerving, so disquieting, one can't help but imagine them darting right down one's gullet... You can do your part by collecting some for me, ridding the waters of their foul presence.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 10 }, { ["id"] = 3540, ["amount"] = 150 } }, ["starts"] = { { ["npcID"] = 268394, ["x"] = 0.516, ["y"] = 0.502, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 268394, ["x"] = 0.516, ["y"] = 0.502, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.516, ["y"] = 0.502, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard" },
[97616] = { ["id"] = 97616, ["name"] = "Corrosive Gifts: Corrosive Power", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["rewardXP"] = 11765, ["rewardItems"] = { 273000 }, ["ends"] = { { ["npcID"] = 262880, ["x"] = 0.51, ["y"] = 0.626, ["zoneID"] = 16535 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16535 } }, ["questType"] = "standard" },
[97621] = { ["id"] = 97621, ["name"] = "The Singularity Anchor", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15458, ["mapID"] = 2405, ["description"] = "Our sojourn to this world has brought the ren'dorei an even deeper understanding of the Void than before. The domanaar with whom we share a common enemy are almost strangely generous with their knowledge. I believe they want us to become as fearsome as they are. There is a Singularity Anchor in Stormarion Citadel. I have learned how to draw upon some of its power to craft you a powerful item. But first, we must ensure it does not fall into the hands of our enemies.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 264507 }, ["starts"] = { { ["npcID"] = 248328, ["x"] = 0.526, ["y"] = 0.728, ["mapID"] = 2405 } }, ["ends"] = { { ["npcID"] = 248328, ["x"] = 0.526, ["y"] = 0.728, ["mapID"] = 2405 } }, ["coords"] = { ["x"] = 0.526, ["y"] = 0.728, ["source"] = "quest_giver", ["mapID"] = 2405 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6115, ["name"] = "Renown of Midnight", ["orderIndex"] = 4, ["flags"] = 0 } } },
[97622] = { ["id"] = 97622, ["name"] = "A Soiree to Remember", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15968, ["mapID"] = 2395, ["description"] = "You seek an audience with Saltheril? And you're wearing... that? Excuse me for a moment while I laugh into my handkerchief. Now, let me be professional. You are cordially invited to attend Saltheril's soiree. Don't embarrass yourself, . The best of Silvermoon are watching.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 266429, 266430, 266431, 266432 }, ["starts"] = { { ["npcID"] = 240838, ["x"] = 0.434, ["y"] = 0.474, ["mapID"] = 2395 } }, ["ends"] = { { ["npcID"] = 240838, ["x"] = 0.434, ["y"] = 0.474, ["mapID"] = 2395 } }, ["coords"] = { ["x"] = 0.434, ["y"] = 0.474, ["source"] = "quest_giver", ["mapID"] = 2395 }, ["mapCandidates"] = { ["npc"] = { 2395 }, ["zone"] = { 15968 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6115, ["name"] = "Renown of Midnight", ["orderIndex"] = 5, ["flags"] = 0 } } },
[97624] = { ["id"] = 97624, ["name"] = "Seeking Legends", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15355, ["mapID"] = 2413, ["description"] = "Harandar hides wisdom in every annal of its history, . You would do well to seek out its legends for yourself. I suspect you may learn something of this world and our places in it.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 263265, 263267, 263268, 263269 }, ["starts"] = { { ["npcID"] = 240407, ["x"] = 0.51, ["y"] = 0.508, ["mapID"] = 2413 } }, ["ends"] = { { ["npcID"] = 240407, ["x"] = 0.51, ["y"] = 0.508, ["mapID"] = 2413 } }, ["coords"] = { ["x"] = 0.51, ["y"] = 0.508, ["source"] = "quest_giver", ["mapID"] = 2413 }, ["mapCandidates"] = { ["npc"] = { 2413 }, ["zone"] = { 15355 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6115, ["name"] = "Renown of Midnight", ["orderIndex"] = 6, ["flags"] = 0 } } },
[97625] = { ["id"] = 97625, ["name"] = "Glorious Abundance", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["description"] = "De Loa of Abundance may not be one of de four great ones, but his worshippers are certainly de most devout. Seek him out yaself. You can find him in northern Zul'Aman near Halazzi's Temple, but I also hear he's established harvest sites in Eversong Woods, Harandar, and even de land of Void through de gargantuan skymouth. If nothing else, de rewards he grants are glorious--to de worthy, at least.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardChoices"] = { 265739, 265740 }, ["starts"] = { { ["npcID"] = 240279, ["x"] = 0.458, ["y"] = 0.658, ["mapID"] = 2437 } }, ["ends"] = { { ["npcID"] = 240279, ["x"] = 0.458, ["y"] = 0.658, ["mapID"] = 2437 } }, ["coords"] = { ["x"] = 0.458, ["y"] = 0.658, ["source"] = "quest_giver", ["mapID"] = 2437 }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6115, ["name"] = "Renown of Midnight", ["orderIndex"] = 7, ["flags"] = 0 } } },
[97640] = { ["id"] = 97640, ["name"] = "Vaults of Atal'Utek: One Coin Too Many", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["mapID"] = 2509, ["description"] = "You don't look so good, . You found something out dere, huh? De vaults are full of treasure, most of it cursed. I don't trust her, but dat spirit-witch you saw knows all de secrets of dis horrid place. If anyone can help, it's her.", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["rewardCurrencies"] = { { ["id"] = 3448, ["amount"] = 1000 } }, ["starts"] = { { ["npcID"] = 262798, ["x"] = 0.472, ["y"] = 0.608, ["zoneID"] = 16535 } }, ["ends"] = { { ["npcID"] = 262880, ["x"] = 0.51, ["y"] = 0.626, ["zoneID"] = 16535 } }, ["coords"] = { ["x"] = 0.472, ["y"] = 0.608, ["source"] = "quest_giver", ["zoneID"] = 16535 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16535 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6352, ["name"] = "The Vaults of Atal'UTek", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6232, ["name"] = "The Battle for Atal'Utek", ["orderIndex"] = 5, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6232, ["questLineOrder"] = 4 } } },
