[97670] = { ["id"] = 97670, ["name"] = "A Handful of Voidlight Marl", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 500 } }, ["starts"] = { { ["npcID"] = 268228, ["x"] = 0.588, ["y"] = 0.46, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 268228, ["x"] = 0.588, ["y"] = 0.46, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.588, ["y"] = 0.46, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard" },
[97910] = { ["id"] = 97910, ["name"] = "Cracked Keystone", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["description"] = "Fragmentary images of heroic deeds flash through your mind as you touch the stone, but they fade as fast as they arrive. Perhaps performing a suitably impressive task will stabilize the stone's magic once more?", ["rewardGold"] = 1366400, ["rewardXP"] = 23530, ["rewardCurrencies"] = { { ["id"] = 3440, ["amount"] = 20 }, { ["id"] = 3441, ["amount"] = 20 } }, ["questType"] = "standard" },
[97945] = { ["id"] = 97945, ["name"] = "In the Catalyst's Shadow", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["description"] = "Ah, ! Good. Now that you've helped me amass such a wealth of resources, it's time for me to pursue other... interests. What? You expected a more dramatic betrayal? Never! Don't worry, $p, while I may be occupied elsewhere, I'll never tire of watching your adventures. Adventures still bolstered by my gifts, of course. Many have shown interest, but I've only found one void elf... amusingly strange enough to mentor. Orin Straylight is the name. You'll find him by the Catalyst in Silvermoon.", ["rewardGold"] = 1366400, ["rewardXP"] = 27380, ["starts"] = { { ["npcID"] = 243907, ["x"] = 0.512, ["y"] = 0.684, ["mapID"] = 2405 } }, ["ends"] = { { ["npcID"] = 269987, ["x"] = 0.4, ["y"] = 0.646, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.512, ["y"] = 0.684, ["source"] = "quest_giver", ["mapID"] = 2393 }, ["mapCandidates"] = { ["npc"] = { 2393, 2405 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[97978] = { ["id"] = 97978, ["name"] = "Prismatic Potential", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["description"] = "Greetings, . Our mutual friend explained everything to us. Don't worry, my shade and I took to Decimus' voidweaving like fish to water. We had an idea. The Catalyst's transformative energies are immense and span the breadth of known elemental forces. If I can learn to isolate the void from that spectrum of power, I could use it to weave Nebulous Voidcores just as Decimus did with the Voidforge. We are no domanaar, though. We need practice.", ["rewardGold"] = 1366400, ["rewardXP"] = 27380, ["starts"] = { { ["npcID"] = 269987, ["x"] = 0.4, ["y"] = 0.646, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 269987, ["x"] = 0.4, ["y"] = 0.646, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.4, ["y"] = 0.646, ["source"] = "quest_giver", ["mapID"] = 2393 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["sourceQuests"] = { 97945 } },
[98172] = { ["id"] = 98172, ["name"] = "Trailing Xal'atath", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["description"] = "We must not lose sight of our true goal here in Silvermoon, : to bring Xal'atath to justice. We all saw her void armies at the Sunwell. They were rushing downward, INTO the well, a thousand a minute. And now: silence. Listen for their whispers, . With any luck, we'll pick up on their trail again, and then we'll find Xal'atath... and perhaps even those that pursued her.", ["rewardGold"] = 683200, ["rewardXP"] = 20540, ["rewardItems"] = { 279527, 279576 }, ["starts"] = { { ["npcID"] = 270645, ["x"] = 0.49, ["y"] = 0.646, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 270645, ["x"] = 0.49, ["y"] = 0.646, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.49, ["y"] = 0.646, ["source"] = "quest_giver", ["mapID"] = 2393 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[98204] = { ["id"] = 98204, ["name"] = "Cursed Keepsake", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["rewardGold"] = 341600, ["rewardItems"] = { 244347, 245991, 245993, 252042, 253396, 253703, 255652, 255712, 256361, 256684, 258540, 263876, 267205, 267355, 267435, 268943, 272129, 272142, 278696, 278701 }, ["starts"] = { { ["x"] = 0.537, ["y"] = 0.574, ["mapID"] = 2351, ["npcID"] = 262726 } }, ["ends"] = { { ["x"] = 0.537, ["y"] = 0.574, ["mapID"] = 2351, ["npcID"] = 262726 } }, ["coords"] = { ["mapID"] = 2351, ["x"] = 0.537, ["y"] = 0.574 }, ["questGiverID"] = 262726, ["questTurnInID"] = 262726, ["questType"] = "standard" },
[98218] = { ["id"] = 98218, ["name"] = "Return to Amani'Zar", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15947, ["mapID"] = 2437, ["description"] = ", Your aid is requested in Amani'Zar Village. Please meet me there. --Liadrin", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["ends"] = { { ["npcID"] = 263331, ["x"] = 0.436, ["y"] = 0.682, ["mapID"] = 2437 } }, ["mapCandidates"] = { ["npc"] = { 2437 }, ["zone"] = { 15947 } }, ["questType"] = "standard", ["nextQuests"] = { 92916 }, ["questLines"] = { { ["id"] = 6229, ["name"] = "An Island of Fangs", ["orderIndex"] = 0, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6229, ["questLineOrder"] = 1 } } },
[98232] = { ["id"] = 98232, ["name"] = "Midnight: Vaults of Atal'Utek", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["description"] = "Zul'jarra's forces stand watch at the gates of the Vaults of Atal'Utek, holding the line against those wicked serpents. The fate of the entire Eastern Kingdoms rests on their blades. We would do well to provide them with reinforcements. The Children of Ula'tek are fierce, but they are no match for a seasoned like you. Traverse the temple and thin their ranks, however you can.", ["rewardGold"] = 683200, ["rewardXP"] = 13690, ["rewardItems"] = { 274476, 279527, 279575 }, ["starts"] = { { ["x"] = 0.49, ["y"] = 0.646, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 256203, ["x"] = 0.49, ["y"] = 0.646, ["mapID"] = 2393 } }, ["coords"] = { ["mapID"] = 2393, ["x"] = 0.49, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[98234] = { ["id"] = 98234, ["name"] = "Week 1 of 3: Gladiator's Distinction", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15969, ["mapID"] = 2393, ["description"] = "Interested in training against some of our fighters? Step into the ring and show us your mettle. Make sure you equip these medallions, and defeat at least two teams of enemies.", ["starts"] = { { ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.646, ["mapID"] = 2393 } }, ["ends"] = { { ["npcID"] = 256212, ["x"] = 0.488, ["y"] = 0.646, ["mapID"] = 2393 } }, ["coords"] = { ["x"] = 0.488, ["y"] = 0.646, ["source"] = "quest_giver", ["mapID"] = 2393 }, ["mapCandidates"] = { ["npc"] = { 2393 }, ["zone"] = { 15969 } }, ["questType"] = "pvp" },
[98343] = { ["id"] = 98343, ["name"] = "Venom Fishing: My Second-Best", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["mapID"] = 2512, ["series"] = { 96110 }, ["description"] = "Before I send ye out hunting, ye should acquaint yerself with what remains of my crew. Most perished in the wreck, of course. Others fell into the swamp. Some traitorous gits... well, we'll get to them in a moment, won't we? But me loyal second mate is holding down the fort, just down river of me Landing. She'll set you up right.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["starts"] = { { ["npcID"] = 258755, ["x"] = 0.572, ["y"] = 0.486, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 257598, ["x"] = 0.516, ["y"] = 0.498, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.572, ["y"] = 0.486, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 96110 }, ["questLines"] = { { ["id"] = 6271, ["name"] = "Tokka's Crew", ["orderIndex"] = 1, ["flags"] = 0 } } },
[98388] = { ["id"] = 98388, ["name"] = "Into the Vaults of Atal'Utek", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["mapID"] = 2509, ["description"] = "Past dis bulwark, there's nothin but snakes, spirits, and venomous death. I've lost three lieutenants dis week. Strong ones. Brave ones. Maybe stronger and braver than you. Warleader Abdumati looks you over with a weary eye.> If you want to fling yaself into de abyss, be my guest. Bring back my scouts, if you can find dem amongst de bones. But watch your step. Dat venom will swallow you whole.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["starts"] = { { ["npcID"] = 262798, ["x"] = 0.472, ["y"] = 0.608, ["zoneID"] = 16535 }, { ["npcID"] = 271885, ["x"] = 0.54, ["y"] = 0.396, ["zoneID"] = 16535 } }, ["ends"] = { { ["npcID"] = 262798, ["x"] = 0.472, ["y"] = 0.608, ["zoneID"] = 16535 } }, ["coords"] = { ["x"] = 0.472, ["y"] = 0.608, ["source"] = "quest_giver", ["zoneID"] = 16535 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16535 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 6352, ["name"] = "The Vaults of Atal'UTek", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6232, ["name"] = "The Battle for Atal'Utek", ["orderIndex"] = 4, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6232, ["questLineOrder"] = 4 } } },
[98406] = { ["id"] = 98406, ["name"] = "A Curated Gift", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 15524, ["mapID"] = 2351, ["description"] = "I have watched the effort and care you take with the other mortals of your neighborhood, here in Razorwind Shores. This ceaseless labor on their behalf is the sort of behavior that I encourage. There's no profit to be had for you, but that isn't a driving concern for the best of your kind. In recognition of your efforts and status, I offer you a gift. This small device contains a piece of decor for you to place in your home. I will have another for you next week.", ["rewardItems"] = { 277975 }, ["starts"] = { { ["x"] = 0.537, ["y"] = 0.574, ["mapID"] = 2351, ["npcID"] = 248854 } }, ["ends"] = { { ["npcID"] = 248854, ["x"] = 0.526, ["y"] = 0.374, ["mapID"] = 2352 }, { ["npcID"] = 253596, ["x"] = 0.536, ["y"] = 0.574, ["mapID"] = 2351 } }, ["coords"] = { ["mapID"] = 2351, ["x"] = 0.537, ["y"] = 0.574 }, ["mapCandidates"] = { ["npc"] = { 2351, 2352 }, ["zone"] = { 15524 } }, ["questGiverID"] = 248854, ["questType"] = "standard" },
[98414] = { ["id"] = 98414, ["name"] = "A Request from the Captain", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["series"] = { 96111 }, ["description"] = "Oh, uh. The Captain has requested you join him at Tokka's Landing as soon as you can. Second Mate Sluggs quivers in her shell.> He had a mean look about him. Tread lightly.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["starts"] = { { ["npcID"] = 257598, ["x"] = 0.516, ["y"] = 0.498, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 258755, ["x"] = 0.572, ["y"] = 0.486, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.516, ["y"] = 0.498, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard", ["sourceQuests"] = { 98343 } },
[98415] = { ["id"] = 98415, ["name"] = "A Favor to the Captain", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["series"] = { 96112 }, ["description"] = "Oh! While you were out fishing, Captain Tokka asked to see you again. I think he's beginning to trust you. Second Mate Sluggs grimaces.> The Captain's trust d-does tend to come with caveats.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["starts"] = { { ["npcID"] = 257598, ["x"] = 0.516, ["y"] = 0.498, ["zoneID"] = 16365 } }, ["ends"] = { { ["npcID"] = 258755, ["x"] = 0.572, ["y"] = 0.486, ["zoneID"] = 16365 } }, ["coords"] = { ["x"] = 0.516, ["y"] = 0.498, ["source"] = "quest_giver", ["zoneID"] = 16365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard" },
[98416] = { ["id"] = 98416, ["name"] = "A Plea from the Captain", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16365, ["series"] = { 96113 }, ["description"] = "Ohh, the Captain's really in a foul mood this time. I think you'd better go see what he wants. You're the only one who can soothe his storms, these days.", ["rewardGold"] = 34100, ["rewardXP"] = 1370, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16365 } }, ["questType"] = "standard" },
[98419] = { ["id"] = 98419, ["name"] = "Shoulder to Shoulder", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["mapID"] = 2509, ["description"] = "De Vaults are a dangerous place. Lotta brave, headstrong fighters think dey can face de Children of Ula'tek alone. If dey're lucky, we manage to recover de bodies before dey get eaten. I like you, $p. It'd be a shame to see a serpent feed you to its young. So be smart. Find people to watch your back, then carve your way through de temple together.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 50 }, { ["id"] = 3448, ["amount"] = 200 }, { ["id"] = 3448, ["amount"] = 250 }, { ["id"] = 3448, ["amount"] = 350 } }, ["starts"] = { { ["npcID"] = 262798, ["x"] = 0.472, ["y"] = 0.608, ["zoneID"] = 16535 } }, ["ends"] = { { ["npcID"] = 262798, ["x"] = 0.472, ["y"] = 0.608, ["zoneID"] = 16535 } }, ["coords"] = { ["x"] = 0.472, ["y"] = 0.608, ["source"] = "quest_giver", ["zoneID"] = 16535 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16535 } }, ["questType"] = "group", ["sourceQuests"] = { 98388 } },
[98420] = { ["id"] = 98420, ["name"] = "What's Out There?", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["mapID"] = 2509, ["description"] = "Knowledge is de most important weapon in war. These Vaults are ancient and vast--our scouts cannot see everything. What lurks in de depths of these corrupted halls? Dat's precisely what I need to know. Get out there and tell me what you see, but it's dangerous to go alone. You best bring some comrades if you want to make it back.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardCurrencies"] = { { ["id"] = 3316, ["amount"] = 50 }, { ["id"] = 3448, ["amount"] = 200 }, { ["id"] = 3448, ["amount"] = 250 }, { ["id"] = 3448, ["amount"] = 350 } }, ["starts"] = { { ["npcID"] = 262798, ["x"] = 0.472, ["y"] = 0.608, ["zoneID"] = 16535 } }, ["ends"] = { { ["npcID"] = 262798, ["x"] = 0.472, ["y"] = 0.608, ["zoneID"] = 16535 } }, ["coords"] = { ["x"] = 0.472, ["y"] = 0.608, ["source"] = "quest_giver", ["zoneID"] = 16535 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16535 } }, ["questType"] = "group", ["sourceQuests"] = { 98388 } },
[98428] = { ["id"] = 98428, ["name"] = "Vaults of Atal'Utek: The Altar of Corrosion", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["mapID"] = 2509, ["description"] = "De Altar of Corrosion . Who can say when dis accursed piece of stone rose out of de venom? I have studied it for lifetimes and have only just tasted its power. Er'inye licks her spectral lips.> Say de word, and I will convert de corrosion you carry to something more useful. Den, you may commune with de Altar and accept its many gifts.", ["rewardGold"] = 170800, ["rewardXP"] = 6850, ["starts"] = { { ["npcID"] = 262880, ["x"] = 0.51, ["y"] = 0.626, ["zoneID"] = 16535 } }, ["ends"] = { { ["npcID"] = 262880, ["x"] = 0.51, ["y"] = 0.626, ["zoneID"] = 16535 } }, ["coords"] = { ["x"] = 0.51, ["y"] = 0.626, ["source"] = "quest_giver", ["zoneID"] = 16535 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16535 } }, ["questType"] = "standard", ["sourceQuests"] = { 97640 }, ["questLines"] = { { ["id"] = 6352, ["name"] = "The Vaults of Atal'UTek", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 6232, ["name"] = "The Battle for Atal'Utek", ["orderIndex"] = 7, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6232, ["questLineOrder"] = 4 } } },
[98515] = { ["id"] = 98515, ["name"] = "Vaults of Atal'Utek: A Toxic Tour", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 11, ["zoneID"] = 16535, ["mapID"] = 2509, ["description"] = "Dis temple is where all de Children of Ula'tek first crawl out of de ooze. Dis is where we hold de line. De threat comes in waves. Sometimes short strikes. Sometimes an incursion dat overwhelms de whole temple. Sometimes a huge monstrosity rising out of de venom. Whatever dey send, send it back cryin' to its big evil mama! And in de meantime, do what you can to keep our patrols safe.", ["rewardGold"] = 341600, ["rewardXP"] = 13690, ["rewardItems"] = { 273000, 274374, 279382 }, ["rewardCurrencies"] = { { ["id"] = 3448, ["amount"] = 1500 }, { ["id"] = 3448, ["amount"] = 1875 }, { ["id"] = 3504, ["amount"] = 500 } }, ["starts"] = { { ["npcID"] = 262798, ["x"] = 0.472, ["y"] = 0.608, ["zoneID"] = 16535 } }, ["ends"] = { { ["npcID"] = 262798, ["x"] = 0.472, ["y"] = 0.608, ["zoneID"] = 16535 } }, ["coords"] = { ["x"] = 0.472, ["y"] = 0.608, ["source"] = "quest_giver", ["zoneID"] = 16535 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16535 } }, ["questType"] = "standard", ["sourceQuests"] = { 98388 }, ["questLines"] = { { ["id"] = 6232, ["name"] = "The Battle for Atal'Utek", ["orderIndex"] = 6, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 324, ["title"] = "The Curse of Ula'tek", ["questLineID"] = 6232, ["questLineOrder"] = 4 } } },
})
